# ---------------------------------------------------------------------------
# NeatMemory-owned shared lexical/storage mechanics (7.4.78.141)
# ---------------------------------------------------------------------------
# These are intentionally small deterministic primitives used by multiple
# source-owning subsystems.  Keeping one implementation avoids repeated regex
# compilation and duplicate compressed-object reads while preserving each
# subsystem's existing public/private wrapper names and authority boundaries.
_NM_UNICODE_WORD_TOKEN_RE = re.compile(r"[^\W_]+(?:['’][^\W_]+)*", flags=re.UNICODE)

def _nm_unicode_word_tokens(text: object):
    for match in _NM_UNICODE_WORD_TOKEN_RE.finditer(str(text or "")):
        raw = match.group(0)
        norm = unicodedata.normalize("NFKC", raw).replace("’", "'").casefold()
        if norm:
            yield norm, raw, match.start(), match.end()

def _nm_read_zlib_payload(path: Path) -> tuple[bytes, str]:
    raw = zlib.decompress(Path(path).read_bytes())
    return raw, hashlib.sha256(raw).hexdigest()

