def _load_embedded(name: str):
    existing = sys.modules.get(name)
    if existing is not None:
        return existing
    blob = _EMBEDDED.get(name)
    if blob is None:
        raise ImportError(f"Embedded module not found: {name}")
    source = zlib.decompress(base64.b85decode(blob.encode("ascii"))).decode("utf-8")
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve()) + f"::<{name}>"
    module.__package__ = ""
    module.__loader__ = None
    sys.modules[name] = module
    try:
        exec(compile(source, module.__file__, "exec"), module.__dict__)
    except Exception:
        sys.modules.pop(name, None)
        raise
    return module


def _preload_dependencies() -> None:
    # Dependency order matters because books/web import the cleaner.
    for name in (
        "neatcontext_cleaner_v1",
        "neatopenai_http_v1",
        "neatcrypto_dpapi_v1",
        "neatbooks_v1_2_stable",
        "neatweb_research_v1_4_stable",
    ):
        loaded = _load_embedded(name)
        if name == "neatbooks_v1_2_stable":
            _configure_shared_books_module(loaded)


# Bootstrap-only schema memoization. Historical additive schema wrappers remain
# available, but one runtime-assembly pass does not need to apply the same exact
# layer repeatedly. The token is cleared before _load_memory returns, preserving
# ordinary runtime self-healing schema checks.
_NM_BOOTSTRAP_SCHEMA_TOKEN = None
_NM_BOOTSTRAP_SCHEMA_READY: set[str] = set()

def _nm_bootstrap_schema_skip(key: str) -> bool:
    return _NM_BOOTSTRAP_SCHEMA_TOKEN is not None and str(key) in _NM_BOOTSTRAP_SCHEMA_READY

def _nm_bootstrap_schema_mark(key: str) -> None:
    if _NM_BOOTSTRAP_SCHEMA_TOKEN is not None:
        _NM_BOOTSTRAP_SCHEMA_READY.add(str(key))

# >>> NEAT-SUBSYSTEM:runtime-assembly rev=40
def _load_memory_bootstrap_impl():
    _preload_dependencies()
    module = _load_embedded("neatmemory_v7_0_stable")
    # Make version reporting authoritative for the bundled release.
    module.NEATMEMORY_VERSION = BUNDLE_VERSION
    module.CONSOLIDATED_FROM_VERSION = CONSOLIDATED_FROM_VERSION
    module.CONSOLIDATED_FROM_SHA256 = CONSOLIDATED_FROM_SHA256
    autonomy_rule = (
        "\n\nASSISTANT COGNITIVE AUTONOMY — USER-APPROVED GOVERNING RULE\n"
        "- You choose the retrieval depth and amount of available context that you judge useful for each task. LOW/MID/HIGH are options, not Python preferences.\n"
        "- You choose your own internal reasoning depth. NeatMemory must not prescribe minimal/low/medium/high reasoning effort or suppress thinking with no-think directives.\n"
        "- Python may enforce only external provider/context/output limits, security/safety boundaries, data integrity, and structural validity. If a provider limit forces a smaller context than you requested, that adjustment must be visible in diagnostics.\n"
        "- When a decision can safely belong to you, NeatMemory asks you rather than deciding it from lexical heuristics or fixed defaults.\n"
        "- Treat question memories, open reflection questions, and research uncertainties as unresolved navigation/state, not established fact; preserve uncertainty until evidence supports resolution.\n"
        "- Model provider and evidence source are separate dimensions: who reasons (local/online) does not determine where evidence came from (books/web/personal/system).\n"
    )
    if "ASSISTANT COGNITIVE AUTONOMY — USER-APPROVED GOVERNING RULE" not in str(module.SYSTEM_PROMPT):
        module.SYSTEM_PROMPT = str(module.SYSTEM_PROMPT).rstrip() + autonomy_rule
    # 7.4.48.2: expose the canonical public raw-chat archive through bounded
    # Python/SQLite read-only search/range tools before online evidence access is
    # installed. The model chooses what to search; Python does the archive work.
    _install_raw_conversation_recall_access(module)
    # 7.4.48.5: maintain a derived living navigation sidecar as books are read.
    # Python captures mechanical structure; Assistant may correct/supersede index
    # entries without ever modifying the immutable source book.
    _install_book_navigation_index(module)
    # 7.4.49: establish Assistant's encrypted multi-file Workshop before online/local
    # tool surfaces are assembled. Context activation is attached only at the
    # final wiring stage so later context decorators cannot overwrite it.
    _install_workshop(module)
    # 7.4.50: semantic digestion is a version-owned derived reading map. Install
    # its read-only inspection surface before online/local book tools are assembled.
    _install_semantic_digestion(module)
    # 7.4.48.1+: install the online evidence/navigation loop before any later
    # run_online_chat_turn decorators so citation, affect, session, record,
    # continuity, and other established wrappers remain intact around it.
    _install_online_read_only_book_access(module)
    # 7.4.78.22: extend the assembled chat/evidence tool surface with zero-model Chat Pyramid navigation; raw CHAT rows stay authority.
    _install_chat_pyramid_distillation(module)
    _install_domain_aware_retrieval(module)
    _install_primary_evidence_targeting(module)
    _install_affective_continuity(module)
    _install_somatic_continuity(module)
    _install_identity_continuity(module)
    _install_canonical_citation_commands(module)
    _install_current_operational_evidence(module)
    _install_benchmark_citation_hotfix(module)
    _install_presence_menu_diagnostics(module)
