def _rcr_int(value, default, minimum, maximum):
    try:
        parsed = int(value)
    except Exception:
        parsed = int(default)
    return max(int(minimum), min(int(maximum), parsed))


def _rcr_terms(query: str) -> list[str]:
    terms: list[str] = []
    for token in re.findall(r"[A-Za-z0-9_'-]{2,}", str(query or "").casefold()):
        token = token.strip("_'-")
        if not token or token in terms:
            continue
        terms.append(token)
        if len(terms) >= 16:
            break
    return terms


def _rcr_fts_query(query: str) -> str:
    terms = _rcr_terms(query)
    return " OR ".join('"' + term.replace('"', '""') + '"' for term in terms)


def _rcr_date_value(value: object, field: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
        raise ValueError(f"{field} must use YYYY-MM-DD")
    try:
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError(f"{field} is not a valid calendar date") from exc
    return text


def _rcr_date_filters(*, date: object = "", date_from: object = "", date_to: object = "") -> dict:
    exact = _rcr_date_value(date, "date")
    start = _rcr_date_value(date_from, "date_from")
    end = _rcr_date_value(date_to, "date_to")
    if exact and (start or end):
        raise ValueError("Use either date or date_from/date_to, not both")
    if exact:
        start = end = exact
    if start and end and start > end:
        raise ValueError("date_from cannot be later than date_to")
    return {"date": exact, "date_from": start, "date_to": end}


def _rcr_date_sql(alias: str, filters: dict) -> tuple[list[str], list[str]]:
    clauses: list[str] = []
    params: list[str] = []
    start = str(filters.get("date_from") or "")
    end = str(filters.get("date_to") or "")
    if start:
        clauses.append(f"SUBSTR({alias}.timestamp,1,10)>=?")
        params.append(start)
    if end:
        clauses.append(f"SUBSTR({alias}.timestamp,1,10)<=?")
        params.append(end)
    return clauses, params


def _rcr_ensure_index(module) -> dict:
    """Create/sync a derived FTS index over plaintext-era chat only; encrypted chat never regains plaintext FTS."""
    secure_probe = globals().get("_nc_secure_chat_exists")
    if callable(secure_probe):
        try:
            if secure_probe(module):
                return {"ok": True, "fts5": False, "indexed_through_row": 0, "new_rows": 0, "method": "encrypted_sql_fallback", "persistent_plaintext_fts": False}
        except Exception:
            pass
    with module.db_connect() as db:
        db.execute(f"""CREATE TABLE IF NOT EXISTS {_RAW_CHAT_FTS_META_TABLE}(
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )""")
        existed = db.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
            (_RAW_CHAT_FTS_TABLE,),
        ).fetchone() is not None
        fts = True
        try:
            db.execute(f"""CREATE VIRTUAL TABLE IF NOT EXISTS {_RAW_CHAT_FTS_TABLE} USING fts5(
                row_id UNINDEXED,
                timestamp UNINDEXED,
                role UNINDEXED,
                content
            )""")
        except sqlite3.OperationalError:
            fts = False
        if not fts:
            return {"ok": True, "fts5": False, "indexed_through_row": 0, "new_rows": 0, "method": "sql_fallback"}
        if not existed:
            db.execute(f"DELETE FROM {_RAW_CHAT_FTS_META_TABLE} WHERE key='last_indexed_message_id'")
        row = db.execute(
            f"SELECT value FROM {_RAW_CHAT_FTS_META_TABLE} WHERE key='last_indexed_message_id'"
        ).fetchone()
        try:
            last = int(row["value"] if row is not None else 0)
        except Exception:
            last = 0
        rows = db.execute(
            """SELECT message_id,timestamp,role,content FROM chat_messages
               WHERE message_id>? ORDER BY message_id""",
            (last,),
        ).fetchall()
        added = 0
        max_seen = last
        for item in rows:
            mid = int(item["message_id"])
            max_seen = max(max_seen, mid)
            if str(item["role"] or "") not in {"user", "assistant"}:
                continue
            # Private rows are excluded even if an older runtime happened to store one.
            private = db.execute("SELECT is_private FROM chat_messages WHERE message_id=?", (mid,)).fetchone()
            if private is not None and int(private["is_private"] or 0):
                continue
            db.execute(
                f"INSERT INTO {_RAW_CHAT_FTS_TABLE}(row_id,timestamp,role,content) VALUES(?,?,?,?)",
                (mid, str(item["timestamp"] or ""), str(item["role"] or ""), str(item["content"] or "")),
            )
            added += 1
        if rows:
            db.execute(
                f"""INSERT INTO {_RAW_CHAT_FTS_META_TABLE}(key,value) VALUES('last_indexed_message_id',?)
                    ON CONFLICT(key) DO UPDATE SET value=excluded.value""",
                (str(max_seen),),
            )
        return {"ok": True, "fts5": True, "indexed_through_row": max_seen, "new_rows": added, "method": "fts5"}


def _rcr_search(module, query: str = "", limit: int = 12, *, date: str = "", date_from: str = "", date_to: str = "") -> dict:
    query = " ".join(str(query or "").split())
    limit = _rcr_int(limit, 12, 1, _RAW_CHAT_SEARCH_MAX_RESULTS)
    try:
        filters = _rcr_date_filters(date=date, date_from=date_from, date_to=date_to)
    except ValueError as exc:
        return {"ok": False, "error": str(exc), "read_only": True, "model_calls": 0}
    has_date = bool(filters.get("date_from") or filters.get("date_to"))
    if not query and not has_date:
        return {"ok": False, "error": "query or date filter is required", "read_only": True, "model_calls": 0}

    # Date-only recall does not need FTS at all: Python/SQLite filters the canonical
    # chat_messages timestamp already stored with every public raw-chat row.
    index = {"ok": True, "fts5": None, "method": "not_needed_for_date_only"}
    results: list[dict] = []
    method = "date_sql" if not query else "sql_fallback"
    if query:
        index = _rcr_ensure_index(module)
        method = "fts5" if index.get("fts5") else "sql_fallback"

    with module.db_connect() as db:
        date_clauses, date_params = _rcr_date_sql("m", filters)
        date_where = (" AND " + " AND ".join(date_clauses)) if date_clauses else ""

        if not query:
            rows = db.execute(
                f"""SELECT m.message_id,m.timestamp,m.role,m.provider,m.model,m.content,m.content_sha256
                    FROM chat_messages m
                    WHERE m.is_private=0 AND m.role IN ('user','assistant'){date_where}
                    ORDER BY m.message_id DESC LIMIT ?""",
                (*date_params, limit),
            ).fetchall()
            for row in rows:
                content = str(row["content"] or "")
                timestamp = str(row["timestamp"] or "")
                results.append({
                    "row_id": int(row["message_id"]),
                    "source_id": f"CHAT-{int(row['message_id'])}",
                    "timestamp": timestamp,
                    "recorded_date": timestamp[:10],
                    "role": str(row["role"] or ""),
                    "provider": str(row["provider"] or ""),
                    "model": str(row["model"] or ""),
                    "excerpt": content[:_RAW_CHAT_SEARCH_EXCERPT_CHARS],
                    "excerpt_complete": len(content) <= _RAW_CHAT_SEARCH_EXCERPT_CHARS,
                    "content_sha256": str(row["content_sha256"] or ""),
                    "rank": 0.0,
                })
        elif index.get("fts5"):
            fts_query = _rcr_fts_query(query)
            if fts_query:
                try:
                    rows = db.execute(
                        f"""SELECT CAST(f.row_id AS INTEGER) AS message_id,m.timestamp,m.role,m.provider,m.model,
                                   m.content,m.content_sha256,bm25({_RAW_CHAT_FTS_TABLE}) AS rank
                            FROM {_RAW_CHAT_FTS_TABLE} f
                            JOIN chat_messages m ON m.message_id=CAST(f.row_id AS INTEGER)
                            WHERE {_RAW_CHAT_FTS_TABLE} MATCH ?
                              AND m.is_private=0 AND m.role IN ('user','assistant'){date_where}
                            ORDER BY rank,m.message_id DESC LIMIT ?""",
                        (fts_query, *date_params, limit),
                    ).fetchall()
                except sqlite3.OperationalError:
                    rows = []
                    method = "sql_fallback"
                for row in rows:
                    content = str(row["content"] or "")
                    timestamp = str(row["timestamp"] or "")
                    results.append({
                        "row_id": int(row["message_id"]),
                        "source_id": f"CHAT-{int(row['message_id'])}",
                        "timestamp": timestamp,
                        "recorded_date": timestamp[:10],
                        "role": str(row["role"] or ""),
                        "provider": str(row["provider"] or ""),
                        "model": str(row["model"] or ""),
                        "excerpt": content[:_RAW_CHAT_SEARCH_EXCERPT_CHARS],
                        "excerpt_complete": len(content) <= _RAW_CHAT_SEARCH_EXCERPT_CHARS,
                        "content_sha256": str(row["content_sha256"] or ""),
                        "rank": float(row["rank"] or 0.0),
                    })

        if query and not results and method == "sql_fallback":
            terms = _rcr_terms(query)
            if not terms:
                terms = [query.casefold()]
            content_clauses = " OR ".join("LOWER(m.content) LIKE ?" for _ in terms)
            params = [f"%{term}%" for term in terms]
            rows = db.execute(
                f"""SELECT m.message_id,m.timestamp,m.role,m.provider,m.model,m.content,m.content_sha256
                    FROM chat_messages m
                    WHERE m.is_private=0 AND m.role IN ('user','assistant') AND ({content_clauses}){date_where}
                    ORDER BY m.message_id DESC LIMIT ?""",
                (*params, *date_params, max(limit * 8, limit)),
            ).fetchall()
            scored = []
            for row in rows:
                content = str(row["content"] or "")
                folded = content.casefold()
                score = sum(1 for term in terms if term in folded)
                scored.append((score, int(row["message_id"]), row))
            scored.sort(key=lambda item: (-item[0], -item[1]))
            for score, mid, row in scored[:limit]:
                content = str(row["content"] or "")
                timestamp = str(row["timestamp"] or "")
                results.append({
                    "row_id": mid,
                    "source_id": f"CHAT-{mid}",
                    "timestamp": timestamp,
                    "recorded_date": timestamp[:10],
                    "role": str(row["role"] or ""),
                    "provider": str(row["provider"] or ""),
                    "model": str(row["model"] or ""),
                    "excerpt": content[:_RAW_CHAT_SEARCH_EXCERPT_CHARS],
                    "excerpt_complete": len(content) <= _RAW_CHAT_SEARCH_EXCERPT_CHARS,
                    "content_sha256": str(row["content_sha256"] or ""),
                    "rank": score,
                })
    return {
        "ok": True,
        "query": query,
        "date_filter": filters,
        "count": len(results),
        "results": results,
        "search_method": method,
        "index": index,
        "read_only": True,
        "model_calls": 0,
        "note": "Search is performed locally by Python/SQLite. Dates match the YYYY-MM-DD prefix already stored in each raw-chat timestamp. Use read_raw_chat_around or read_raw_chat only for rows you actually want to reopen.",
    }


def _rcr_pack_rows(rows) -> dict:
    """Pack canonical CHAT rows without ever splitting one dialogue row.

    7.4.64.5 moves size control *before* execution into the shared online tool-loop
    backpressure frame. A stored user/assistant message is atomic evidence: if a
    requested row window cannot fit, Assistant must request fewer rows rather than
    receive a silently clipped message. Post-execution admission remains the final
    guard for unusual encodings/metadata.
    """
    output: list[dict] = []
    used = 0
    for row in rows:
        content = str(row["content"] or "")
        output.append({
            "row_id": int(row["message_id"]),
            "source_id": f"CHAT-{int(row['message_id'])}",
            "timestamp": str(row["timestamp"] or ""),
            "role": str(row["role"] or ""),
            "provider": str(row["provider"] or ""),
            "model": str(row["model"] or ""),
            "content": content,
            "content_complete": True,
            "content_chars": len(content),
            "content_sha256": str(row["content_sha256"] or ""),
        })
        used += len(content)
    return {"rows": output, "count": len(output), "characters": used, "clipped": False, "row_atomic": True}


def _rcr_preflight_shape(module, name: str, arguments: dict | None = None) -> dict:
    """Estimate raw-chat result size mechanically without reopening message text.

    For exact/around reads SQLite supplies only row counts and LENGTH(content). This
    lets the common 7.4.64.3 backpressure frame make a precise row-window fit
    decision before Python builds the result. Search is bounded by its fixed excerpt
    size. No relevance, meaning, or evidence authority is inferred here.
    """
    tool = str(name or "")
    args = dict(arguments or {}) if isinstance(arguments, dict) else {}
    if tool == "search_raw_chat":
        limit = _rcr_int(args.get("limit", 12), 12, 1, _RAW_CHAT_SEARCH_MAX_RESULTS)
        chars = limit * _RAW_CHAT_SEARCH_EXCERPT_CHARS
        return {
            "tool": tool, "rows": limit, "content_chars_upper_bound": chars,
            "estimated_tokens": 500 + ((chars + 2) // 3) + 160 * limit,
            "method": "bounded_search_excerpt_shape", "row_atomic": True,
        }
    if tool not in {"read_raw_chat", "read_raw_chat_around"}:
        return {"tool": tool, "rows": 0, "content_chars": 0, "estimated_tokens": 0, "method": "not_raw_chat_read", "row_atomic": True}
    try:
        with module.db_connect() as db:
            if tool == "read_raw_chat":
                start_row = _rcr_int(args.get("start_row", 1), 1, 1, 2_147_483_647)
                count = _rcr_int(args.get("count", 30), 30, 1, _RAW_CHAT_READ_MAX_ROWS)
                row = db.execute(
                    """SELECT COUNT(*) AS n, COALESCE(SUM(LENGTH(content)),0) AS chars
                       FROM (SELECT content FROM chat_messages
                             WHERE message_id>=? AND is_private=0 AND role IN ('user','assistant')
                             ORDER BY message_id LIMIT ?)""",
                    (start_row, count),
                ).fetchone()
            else:
                row_id = _rcr_int(args.get("row_id", 1), 1, 1, 2_147_483_647)
                before = _rcr_int(args.get("before", 15), 15, 0, 50)
                after = _rcr_int(args.get("after", 15), 15, 0, 50)
                left = db.execute(
                    """SELECT COUNT(*) AS n, COALESCE(SUM(LENGTH(content)),0) AS chars
                       FROM (SELECT content FROM chat_messages
                             WHERE message_id<=? AND is_private=0 AND role IN ('user','assistant')
                             ORDER BY message_id DESC LIMIT ?)""",
                    (row_id, before + 1),
                ).fetchone()
                right = db.execute(
                    """SELECT COUNT(*) AS n, COALESCE(SUM(LENGTH(content)),0) AS chars
                       FROM (SELECT content FROM chat_messages
                             WHERE message_id>? AND is_private=0 AND role IN ('user','assistant')
                             ORDER BY message_id LIMIT ?)""",
                    (row_id, after),
                ).fetchone()
                n_left = int(left["n"] if left is not None else 0)
                n_right = int(right["n"] if right is not None else 0)
                chars_left = int(left["chars"] if left is not None else 0)
                chars_right = int(right["chars"] if right is not None else 0)
                n = n_left + n_right
                chars = chars_left + chars_right
                return {
                    "tool": tool, "rows": n, "content_chars": chars,
                    "estimated_tokens": 500 + ((chars + 2) // 3) + 160 * n,
                    "method": "sqlite_length_only", "row_atomic": True,
                }
        n = int(row["n"] if row is not None else 0)
        chars = int(row["chars"] if row is not None else 0)
        return {
            "tool": tool, "rows": n, "content_chars": chars,
            "estimated_tokens": 500 + ((chars + 2) // 3) + 160 * n,
            "method": "sqlite_length_only", "row_atomic": True,
        }
    except Exception as exc:
        # Failure to inspect row lengths must never grant a smaller floor. The common
        # caller falls back to an argument-derived conservative bound.
        return {"tool": tool, "rows": None, "content_chars": None, "estimated_tokens": 0, "method": "shape_unavailable", "error": f"{type(exc).__name__}: {exc}", "row_atomic": True}


def _rcr_read(module, start_row: int, count: int = 30) -> dict:
    start_row = _rcr_int(start_row, 1, 1, 2_147_483_647)
    count = _rcr_int(count, 30, 1, _RAW_CHAT_READ_MAX_ROWS)
    with module.db_connect() as db:
        rows = db.execute(
            """SELECT message_id,timestamp,role,provider,model,content,content_sha256
               FROM chat_messages
               WHERE message_id>=? AND is_private=0 AND role IN ('user','assistant')
               ORDER BY message_id LIMIT ?""",
            (start_row, count),
        ).fetchall()
    packed = _rcr_pack_rows(rows)
    return {"ok": True, "requested": {"start_row": start_row, "count": count}, **packed, "read_only": True, "model_calls": 0}


def _rcr_read_around(module, row_id: int, before: int = 15, after: int = 15) -> dict:
    row_id = _rcr_int(row_id, 1, 1, 2_147_483_647)
    before = _rcr_int(before, 15, 0, 50)
    after = _rcr_int(after, 15, 0, 50)
    with module.db_connect() as db:
        left = db.execute(
            """SELECT message_id,timestamp,role,provider,model,content,content_sha256
               FROM chat_messages
               WHERE message_id<=? AND is_private=0 AND role IN ('user','assistant')
               ORDER BY message_id DESC LIMIT ?""",
            (row_id, before + 1),
        ).fetchall()
        right = db.execute(
            """SELECT message_id,timestamp,role,provider,model,content,content_sha256
               FROM chat_messages
               WHERE message_id>? AND is_private=0 AND role IN ('user','assistant')
               ORDER BY message_id LIMIT ?""",
            (row_id, after),
        ).fetchall()
    combined = list(reversed(left)) + list(right)
    packed = _rcr_pack_rows(combined)
    return {"ok": True, "center_row": row_id, "requested": {"before": before, "after": after}, **packed, "read_only": True, "model_calls": 0}


def _rcr_execute_tool(module, name: str, arguments: object) -> dict:
    tool = str(name or "").strip()
    args = dict(arguments or {}) if isinstance(arguments, dict) else {}
    try:
        if tool == "search_raw_chat":
            return _rcr_search(
                module,
                str(args.get("query") or ""),
                _rcr_int(args.get("limit", 12), 12, 1, 30),
                date=str(args.get("date") or ""),
                date_from=str(args.get("date_from") or ""),
                date_to=str(args.get("date_to") or ""),
            )
        if tool == "read_raw_chat":
            return _rcr_read(module, args.get("start_row", 1), args.get("count", 30))
        if tool == "read_raw_chat_around":
            return _rcr_read_around(module, args.get("row_id", 1), args.get("before", 15), args.get("after", 15))
        return {"ok": False, "error": f"Raw-chat read-only tool is not allowed: {tool}", "read_only": True, "model_calls": 0}
    except Exception as exc:
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}", "read_only": True, "model_calls": 0}


def _rcr_apply_recent_default(module) -> dict:
    """One-time .227 migration: historical defaults 400/100 -> 60; explicit user choices are preserved."""
    module.DEFAULT_CHAT_LOAD = _RAW_CHAT_DEFAULT_RECENT_ROWS
    changed = False
    current = None
    try:
        current = str(module.get_setting("recent_chat_messages", "") or "").strip()
        applied = str(module.get_setting(_RAW_CHAT_MIGRATION_SETTING, "0") or "0") == "1"
        if not applied:
            if current in {"", "400", "100"}:
                module.set_setting("recent_chat_messages", str(_RAW_CHAT_DEFAULT_RECENT_ROWS))
                current = str(_RAW_CHAT_DEFAULT_RECENT_ROWS)
                changed = True
            module.set_setting(_RAW_CHAT_MIGRATION_SETTING, "1")
    except Exception:
        pass
    return {"default_recent_rows": _RAW_CHAT_DEFAULT_RECENT_ROWS, "configured_recent_rows": current, "migration_changed_setting": changed}


def _install_raw_conversation_recall_access(module) -> None:
    if getattr(module, "_RAW_CONVERSATION_RECALL_ACCESS_INSTALLED", False):
        return
    recent = _rcr_apply_recent_default(module)
    module.search_raw_chat = lambda query="", limit=12, date="", date_from="", date_to="": _rcr_search(module, query, limit, date=date, date_from=date_from, date_to=date_to)
    module.read_raw_chat = lambda start_row, count=30: _rcr_read(module, start_row, count)
    module.read_raw_chat_around = lambda row_id, before=15, after=15: _rcr_read_around(module, row_id, before, after)
    module.get_raw_chat_recall_status = lambda: {"version": _RAW_CHAT_RECALL_VERSION, "recent": recent, "index": _rcr_ensure_index(module), "read_only": True, "model_calls": 0}
    module.raw_conversation_recall_access_self_test = lambda: raw_conversation_recall_access_self_test(module)
    module.raw_chat_tool_loop_budget_self_test = lambda: raw_chat_tool_loop_budget_self_test(module)

    schemas = [
        {"type":"function","function":{"name":"search_raw_chat","description":"Search the full public raw chat archive locally with Python/SQLite using optional keywords and/or recorded YYYY-MM-DD date filters; returns bounded matching row excerpts.","parameters":{"type":"object","properties":{"query":{"type":"string"},"date":{"type":"string"},"date_from":{"type":"string"},"date_to":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":30}},"required":[],"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_raw_chat","description":"Read chronological public raw chat rows from a stable CHAT/message row ID.","parameters":{"type":"object","properties":{"start_row":{"type":"integer","minimum":1},"count":{"type":"integer","minimum":1,"maximum":100}},"required":["start_row"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_raw_chat_around","description":"Read public raw chat rows surrounding one stable CHAT/message row ID.","parameters":{"type":"object","properties":{"row_id":{"type":"integer","minimum":1},"before":{"type":"integer","minimum":0,"maximum":50},"after":{"type":"integer","minimum":0,"maximum":50}},"required":["row_id"],"additionalProperties":False}}},
    ]
    if hasattr(module, "TOOL_SCHEMAS"):
        existing = {str((schema.get("function") or {}).get("name") or "") for schema in module.TOOL_SCHEMAS if isinstance(schema, dict)}
        module.TOOL_SCHEMAS.extend(schema for schema in schemas if (schema.get("function") or {}).get("name") not in existing)
    if hasattr(module, "_READ_ONLY_TEXT_TOOL_ALLOWLIST"):
        module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"search_raw_chat", "read_raw_chat", "read_raw_chat_around"})
    if hasattr(module, "execute_tool"):
        old_execute = module.execute_tool
        def execute_tool_with_raw_chat(name, arguments, seen, *, allow_sticky, sticky_state):
            if name in {"search_raw_chat", "read_raw_chat", "read_raw_chat_around"}:
                return _rcr_execute_tool(module, name, arguments)
            return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
        module.execute_tool = execute_tool_with_raw_chat
    module.RAW_CHAT_RECALL_VERSION = _RAW_CHAT_RECALL_VERSION
    module.RAW_CHAT_DEFAULT_RECENT_ROWS = _RAW_CHAT_DEFAULT_RECENT_ROWS
    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["raw-chat-recall"] = {
            "label": "Python-indexed full raw-chat keyword/date search + exact row/around read access",
            "groups": ("quick", "critical", "all"),
            "runner": "memory.raw_conversation_recall_access_self_test",
        }
    module._RAW_CONVERSATION_RECALL_ACCESS_INSTALLED = True


def raw_conversation_recall_access_self_test(module=None) -> dict:
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    test_db.execute("""CREATE TABLE chat_messages(
        message_id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,role TEXT,provider TEXT,model TEXT,content TEXT,
        is_private INTEGER DEFAULT 0,content_sha256 TEXT
    )""")
    settings = {"recent_chat_messages": "400"}
    class FakeModule:
        DEFAULT_CHAT_LOAD = 400
        def db_connect(self): return test_db
        def get_setting(self, key, default=""): return settings.get(key, default)
        def set_setting(self, key, value): settings[key] = str(value)
    fake = FakeModule()
    try:
        for index in range(1, 151):
            if index == 3:
                content = "We fixed the Windows Vast SSH tunnelling command and port forwarding." 
            elif index == 149:
                content = "Recent conversation about Shakespeare and local book chunks."
            else:
                content = f"ordinary public conversation row {index}"
            test_db.execute(
                "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,0,?)",
                (("2026-08-07" if index == 3 else "2026-08-12") + f"T12:{index%60:02d}:00+00:00", "user" if index % 2 else "assistant", "online", "test", content, hashlib.sha256(content.encode()).hexdigest()),
            )
        private = "secretprivatetoken should never be searchable"
        test_db.execute(
            "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,1,?)",
            ("2026-08-12T13:00:00+00:00", "user", "local", "test", private, hashlib.sha256(private.encode()).hexdigest()),
        )
        test_db.commit()
        recent = _rcr_apply_recent_default(fake)
        first = _rcr_search(fake, "Windows Vast tunnelling port forwarding", 8)
        exact_date = _rcr_search(fake, "", 8, date="2026-08-07")
        date_keyword = _rcr_search(fake, "Windows Vast tunnelling", 8, date_from="2026-08-07", date_to="2026-08-07")
        wrong_date = _rcr_search(fake, "Windows Vast tunnelling", 8, date="2026-08-12")
        invalid_date = _rcr_search(fake, "", 8, date="2026-02-30")
        around = _rcr_read_around(fake, 3, before=2, after=2)
        exact = _rcr_read(fake, 149, 2)
        long_content = "ROW-ATOMIC-" + ("z" * 60000)
        long_cur = test_db.execute(
            "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,0,?)",
            ("2026-08-12T13:00:30+00:00", "user", "online", "test", long_content, hashlib.sha256(long_content.encode()).hexdigest()),
        )
        test_db.commit()
        long_read = _rcr_read(fake, int(long_cur.lastrowid), 1)
        private_search = _rcr_search(fake, "secretprivatetoken", 8)
        new_content = "A later raw chat row mentions DPAPI portable backup recovery."
        cur = test_db.execute(
            "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,0,?)",
            ("2026-08-12T13:01:00+00:00", "assistant", "online", "test", new_content, hashlib.sha256(new_content.encode()).hexdigest()),
        )
        test_db.commit()
        incremental = _rcr_search(fake, "DPAPI portable backup recovery", 8)
        old_hit_ids = {int(row.get("row_id") or 0) for row in first.get("results") or []}
        around_ids = [int(row.get("row_id") or 0) for row in around.get("rows") or []]
        exact_ids = [int(row.get("row_id") or 0) for row in exact.get("rows") or []]
        incremental_ids = {int(row.get("row_id") or 0) for row in incremental.get("results") or []}
        checks = {
            "recent_default_migrates_historical_default_to_60_once": settings.get("recent_chat_messages") == "60" and recent.get("migration_changed_setting") is True,
            "python_search_finds_old_row_outside_recent_100": 3 in old_hit_ids,
            "exact_recorded_date_search_finds_row": {int(row.get("row_id") or 0) for row in exact_date.get("results") or []} == {3},
            "keyword_plus_date_range_filters_in_python": 3 in {int(row.get("row_id") or 0) for row in date_keyword.get("results") or []} and wrong_date.get("count") == 0,
            "invalid_calendar_date_rejected": invalid_date.get("ok") is False,
            "date_search_is_zero_model": exact_date.get("model_calls") == 0 and date_keyword.get("model_calls") == 0,
            "search_returns_bounded_excerpts_not_full_archive": first.get("count", 0) <= 8 and all("excerpt" in row for row in first.get("results") or []),
            "read_around_reopens_chronological_rows": around_ids == sorted(around_ids) and 3 in around_ids,
            "exact_range_uses_stable_row_ids": exact_ids[:2] == [149, 150],
            "raw_chat_rows_are_atomic_not_character_clipped": long_read.get("row_atomic") is True and long_read.get("clipped") is False and long_read.get("count") == 1 and (long_read.get("rows") or [{}])[0].get("content") == long_content and (long_read.get("rows") or [{}])[0].get("content_complete") is True,
            "private_rows_excluded": private_search.get("count") == 0,
            "index_syncs_new_rows_incrementally": int(cur.lastrowid) in incremental_ids,
            "all_archive_operations_are_zero_model": first.get("model_calls") == 0 and around.get("model_calls") == 0 and exact.get("model_calls") == 0,
        }
        return {"ok": all(bool(v) for v in checks.values()), "checks": checks, "version": _RAW_CHAT_RECALL_VERSION, "search_method": first.get("search_method"), "live_database_modified": False}
    finally:
        test_db.close()


def online_tool_loop_budget_self_test(module=None) -> dict:
    events=[]
    class FakeModule:
        CHAT_OUTPUT_RESERVE_TOKENS=16384
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":16384,"model_context_limit_tokens":128000,"safety_margin_tokens":12800}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":16384}
        @staticmethod
        def _adaptive_estimate_tokens(text): return max(1,(len(str(text))+3)//4) if text else 0
        @staticmethod
        def append_diagnostic_log(event_type,summary,**kwargs): events.append({"event_type":event_type,**kwargs}); return {"ok":True}
    fake=FakeModule()
    working=[{"role":"user","content":"small"}]
    huge={"ok":True,"items":[{"text":"x"*30000} for _ in range(40)],"book_id":"BK-TEST"}
    wire,diag=_ora_tool_result_admission(fake,name="book_structural_reconciliation",arguments={"book_id":"BK-TEST"},result=huge,instructions="i"*4000,working=working,tools=[{"type":"function","name":"probe","parameters":{"type":"object","properties":{}}}])
    env=json.loads(wire)
    small={"ok":True,"items":[{"canonical_label":"BOOK I","status":"reconciled"}],"book_id":"BK-TEST"}
    wire2,diag2=_ora_tool_result_admission(fake,name="book_structural_reconciliation",arguments={"book_id":"BK-TEST","canonical_orders":[1]},result=small,instructions="i"*4000,working=working,tools=[])

    # Reproduce the Constellation incident mechanically: ordinary tool-result room
    # is zero because the 12k safety headroom is protected, while a small part of
    # that headroom still exists for a mutation acknowledgement.
    mutation_tools=[{"type":"function","name":"write_constellation_edge","parameters":{"type":"object","properties":{}}}]
    class TightFakeModule(FakeModule):
        # A deliberately small synthetic context makes the boundary deterministic:
        # ordinary result room is zero after protecting the 12k headroom, while
        # hundreds of hard-limit tokens still remain for the mutation receipt.
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":20000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
    tight_fake=TightFakeModule()
    near_full=[{"role":"user","content":"y"*4000}]
    probe_wire,near_diag=_ora_tool_result_admission(
        tight_fake,name="write_constellation_edge",arguments={"from_ref":"A","to_ref":"B"},
        result={"ok":True,"edge_id":"CE-PROBE","ref":"constellation:CE-PROBE"},
        instructions="i"*4000,working=near_full,tools=mutation_tools,
    )
    mutation_result={
        "ok":True,"edge_id":"CE-TEST","ref":"constellation:CE-TEST","root_edge_id":"CE-TEST",
        "revision":1,"status":"active","from_ref":"A","to_ref":"B",
        "relation_type":"counterpoint","epistemic_status":"inferred",
        "large_ack_detail":"m"*12000,
    }
    wire3,diag3=_ora_tool_result_admission(
        tight_fake,name="write_constellation_edge",arguments={"from_ref":"A","to_ref":"B"},result=mutation_result,
        instructions="i"*4000,working=near_full,tools=mutation_tools,
    )
    receipt=json.loads(wire3)

    # 7.4.64.3: once ordinary room is tiny, a read is blocked before execution;
    # mutation calls remain eligible because their acknowledgement reserve is separate.
    execute_search, search_block, search_pre = _ora_tool_preflight_backpressure(
        tight_fake, name="search_books", arguments={"query":"loyalty","limit":8},
        instructions="i"*4000, working=near_full, tools=[{"type":"function","name":"search_books","parameters":{"type":"object","properties":{}}}],
    )
    execute_mutation, mutation_block, mutation_pre = _ora_tool_preflight_backpressure(
        tight_fake, name="write_constellation_edge", arguments={"from_ref":"A","to_ref":"B"},
        instructions="i"*4000, working=near_full, tools=mutation_tools,
    )
    # Simulate a parallel batch after one read already hit the admission guard.
    execute_parallel, parallel_block, parallel_pre = _ora_tool_preflight_backpressure(
        fake, name="book_semantic_map", arguments={"book_id":"BK-TEST"},
        instructions="i"*4000, working=working, tools=[{"type":"function","name":"book_semantic_map","parameters":{"type":"object","properties":{}}}],
        prior_budget_block=True,
    )
    # Construct the real small-but-nonzero regime: enough room for a compact signal,
    # not enough for a typical multi-chunk read. The tool must be stopped pre-execution.
    class MidFakeModule(FakeModule):
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":30000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
    mid_fake=MidFakeModule()
    chunk_tools=[{"type":"function","name":"read_book_chunks","parameters":{"type":"object","properties":{}}}]
    mid_working=None; mid_snapshot=None
    for chars in range(1000, 50000, 500):
        candidate=[{"role":"user","content":"z"*chars}]
        snap=_ora_tool_budget_snapshot(mid_fake,instructions="i"*4000,working=candidate,tools=chunk_tools,mutation_tool=False)
        allowed=int(snap.get("allowed_result_tokens") or 0)
        if 1000 <= allowed < int(_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS["read_book_chunks"]):
            mid_working=candidate; mid_snapshot=snap; break
    execute_chunk, chunk_block, chunk_pre = _ora_tool_preflight_backpressure(
        mid_fake, name="read_book_chunks", arguments={"book_id":"BK-TEST","start":80,"count":4},
        instructions="i"*4000, working=mid_working or working, tools=chunk_tools,
    )
    search_env=json.loads(search_block or "{}")
    parallel_env=json.loads(parallel_block or "{}")
    chunk_env=json.loads(chunk_block or "{}")

    # 7.4.78.8: reproduce the real Sherlock failure shape. A broad 20-chunk read
    # must be refused before source text is built, then a one-entity search and a
    # one-chunk exact read must remain available in later provider rounds.
    narrow_calls=[]
    class NarrowBooks:
        @staticmethod
        def search_books(query, limit=8, book_id=None):
            narrow_calls.append(("search_books", str(query), int(limit), book_id))
            return {"ok":True,"query":query,"results":[{"book_id":book_id or "BK-SHERLOCK","chunk_id":"BK-SHERLOCK-C000011","ordinal":11,"excerpt":"Irene Adler retained the photograph."}]}
        @staticmethod
        def read_book_chunks(book_id, start=1, count=1):
            narrow_calls.append(("read_book_chunks", str(book_id), int(start), int(count)))
            text="A SCANDAL IN BOHEMIA\nIrene Adler left a letter and departed before Holmes recovered the original photograph."
            return {"ok":True,"book":{"book_id":book_id,"title":"The Adventures of Sherlock Holmes"},"chunks":[{"book_id":book_id,"chunk_id":f"{book_id}-C{int(start):06d}","ordinal":int(start),"text":text,"text_sha256":hashlib.sha256(text.encode()).hexdigest()}]}
    class NarrowCleaner:
        @staticmethod
        def clean_payload(value, string_limit=30000): return value
    class NarrowModule(FakeModule):
        neatbooks=NarrowBooks()
        context_cleaner=NarrowCleaner()
    class NarrowItem:
        def __init__(self,name,call_id,arguments):
            self.type="function_call"; self.name=name; self.call_id=call_id; self.arguments=json.dumps(arguments)
    class NarrowResponse:
        def __init__(self,output=None,text=""):
            self.output=list(output or []); self.output_text=text; self.usage=None
    class NarrowResponses:
        def __init__(self): self.requests=[]; self.index=0
        def create(self,**kwargs):
            self.requests.append(dict(kwargs))
            sequence=[
                NarrowResponse([NarrowItem("read_book_chunks","broad",{"book_id":"BK-SHERLOCK","start":1,"count":20})]),
                # 7.4.78.34: the broad read was mechanically blocked. Before a
                # second source-navigation round, Assistant explicitly chooses to stay
                # full-context for the targeted recovery sequence.
                NarrowResponse([NarrowItem("stay_full_context","gate",{"reason":"The broad read was blocked by mechanical backpressure; keep full context for one targeted search and exact retry.","expected_remaining_navigation_rounds":2})]),
                NarrowResponse([NarrowItem("search_books","search",{"book_id":"BK-SHERLOCK","query":"Irene Adler","limit":2})]),
                NarrowResponse([NarrowItem("read_book_chunks","exact",{"book_id":"BK-SHERLOCK","start":11,"count":1})]),
                NarrowResponse([],"grounded after targeted recovery"),
            ]
            response=sequence[min(self.index,len(sequence)-1)]; self.index+=1; return response
    narrow_backend=type("NarrowBackend",(),{})()
    narrow_backend.model_id="fake-online"
    narrow_backend.client=type("NarrowClient",(),{})()
    narrow_backend.client.responses=NarrowResponses()
    narrow_fake=NarrowModule()
    narrow_answer=_ora_run_responses_book_loop(
        narrow_fake,narrow_backend,"test instructions",
        [{"role":"user","content":"Compare several Sherlock Holmes stories with exact evidence."}],output_kwargs={},
    )
    narrow_request_wire=json.dumps(narrow_backend.client.responses.requests,ensure_ascii=False,default=lambda obj:getattr(obj,"__dict__",str(obj)))
    wide_floor=_ora_tool_execution_floor_tokens("read_book_chunks",{"book_id":"BK-SHERLOCK","start":1,"count":20},module=narrow_fake)
    single_floor=_ora_tool_execution_floor_tokens("read_book_chunks",{"book_id":"BK-SHERLOCK","start":11,"count":1},module=narrow_fake)
    broad_execute,broad_block,broad_pre=_ora_tool_preflight_backpressure(
        narrow_fake,name="read_book_chunks",arguments={"book_id":"BK-SHERLOCK","start":1,"count":20},
        instructions="test instructions",working=[{"role":"user","content":"compare"}],tools=chunk_tools,
    )
    broad_env=json.loads(broad_block or "{}")
    checks={
        "oversized_result_withheld_without_truncation":env.get("result_too_large_for_tool_loop") is True and env.get("silent_truncation") is False and diag.get("admitted") is False,
        "oversized_raw_payload_not_leaked":len(wire)<10000 and "x"*1000 not in wire,
        "small_narrow_result_admitted":diag2.get("admitted") is True and "BOOK I" in wire2,
        "zero_ordinary_budget_case_constructed":int((near_diag or {}).get("allowed_result_tokens", -1))==0 and int((near_diag or {}).get("mutation_allowed_tokens") or 0)>=256,
        "mutation_receipt_uses_reserved_headroom":receipt.get("mutation_receipt") is True and receipt.get("committed") is True and receipt.get("edge_id")=="CE-TEST" and diag3.get("admitted") is True,
        "mutation_receipt_prevents_duplicate_ambiguity":receipt.get("do_not_repeat_automatically") is True and "m"*1000 not in wire3,
        "read_guard_unchanged":env.get("next_action","").startswith("Issue a narrower tool call") and env.get("read_only") is True,
        "budget_block_logged":any(e.get("event_type")=="tool.result_budget_blocked" for e in events),
        "mutation_receipt_logged":any(e.get("event_type") in {"tool.mutation_result_admitted","tool.mutation_receipt_admitted"} for e in events),
        "tiny_budget_read_blocked_before_execution":execute_search is False and search_env.get("tool_executed") is False and search_env.get("tool_loop_backpressure") is True,
        "tiny_budget_requests_tool_phase_close":search_pre.get("close_tool_phase") is True and search_env.get("evidence_returned") is False,
        "mutation_preflight_not_blocked":execute_mutation is True and mutation_block=="" and mutation_pre.get("mutation_tool") is True,
        "parallel_batch_avalanche_prevented":execute_parallel is False and parallel_pre.get("reason")=="previous_read_in_parallel_batch_hit_budget_guard" and parallel_env.get("evidence_returned") is False,
        "small_nonzero_chunk_budget_case_constructed":mid_snapshot is not None and 1000 <= int(mid_snapshot.get("allowed_result_tokens") or 0) < int(_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS["read_book_chunks"]),
        "small_nonzero_chunk_read_blocked_pre_execution":execute_chunk is False and chunk_env.get("tool_executed") is False and chunk_pre.get("reason")=="remaining_room_below_conservative_execution_floor",
        "book_read_floor_scales_with_requested_range":wide_floor>single_floor and wide_floor>=50000 and single_floor<=5000,
        "broad_book_read_blocked_before_source_execution":broad_execute is False and broad_pre.get("reason")=="remaining_room_below_conservative_execution_floor",
        "broad_book_block_returns_mechanical_narrowing_plan":broad_env.get("mechanical_narrowing_plan",{}).get("retry_batch_limit")==1 and broad_env.get("mechanical_narrowing_plan",{}).get("semantic_selection_performed_by_python") is False,
        "tool_loop_recovers_with_targeted_search_then_single_chunk":narrow_answer=="grounded after targeted recovery" and [call[0] for call in narrow_calls]==["search_books","read_book_chunks"] and narrow_calls[-1][-1]==1,
        "blocked_broad_read_text_never_executed_or_admitted":"broad" in narrow_request_wire and not any(call[0]=="read_book_chunks" and call[-1]==20 for call in narrow_calls),
        "multi_story_guidance_requires_per_item_targeting":"one exact story title or distinctive character" in _ONLINE_BOOK_NARROWING_GUIDANCE,
        "uncited_model_knowledge_cannot_be_labelled_textual_fact":"Prior/model knowledge must be labelled provisional at its first use" in _ONLINE_BOOK_GROUNDING_GUIDANCE,
        "preflight_budget_block_logged":any(e.get("event_type")=="tool.preflight_budget_blocked" for e in events),
        "zero_provider_calls":True,
    }
    return {"ok":all(checks.values()),"checks":checks,"version":_ONLINE_BOOK_ACCESS_VERSION,"model_calls":0,"web_calls":0}


def research_tool_loop_budget_self_test(module=None) -> dict:
    """Zero-network regression for 7.4.64.4 research-side budget backpressure."""
    events=[]
    class FakeModule:
        CHAT_OUTPUT_RESERVE_TOKENS=4096
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":30000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
        @staticmethod
        def _adaptive_estimate_tokens(text): return max(1,(len(str(text))+3)//4) if text else 0
        @staticmethod
        def append_diagnostic_log(event_type,summary,**kwargs): events.append({"event_type":event_type,**kwargs}); return {"ok":True}
    fake=FakeModule()
    research_tools=[
        {"type":"function","name":"search_web_archive","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"read_web_archive_page","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"read_web_archive_around","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"search_web_evidence_units","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"read_web_evidence_unit","parameters":{"type":"object","properties":{}}},
    ]

    # Build the same constrained regime seen in normal use: enough room for a
    # materially narrower research read, but not for a default/broad page read.
    working=None; snapshot=None
    narrow_floor=_ora_tool_execution_floor_tokens("read_web_archive_page",{"characters":1200})
    broad_floor=_ora_tool_execution_floor_tokens("read_web_archive_page",{"characters":12000})
    for chars in range(1000, 60000, 250):
        candidate=[{"role":"user","content":"r"*chars}]
        snap=_ora_tool_budget_snapshot(fake,instructions="i"*4000,working=candidate,tools=research_tools,mutation_tool=False)
        allowed=int(snap.get("allowed_result_tokens") or 0)
        if narrow_floor <= allowed < broad_floor:
            working=candidate; snapshot=snap; break

    execute_broad,broad_block,broad_pre=_ora_tool_preflight_backpressure(
        fake,name="read_web_archive_page",arguments={"reference":"WEB-TEST","start":0,"characters":12000},
        instructions="i"*4000,working=working or [{"role":"user","content":"small"}],tools=research_tools,
    )
    execute_narrow,narrow_block,narrow_pre=_ora_tool_preflight_backpressure(
        fake,name="read_web_archive_page",arguments={"reference":"WEB-TEST","start":0,"characters":1200},
        instructions="i"*4000,working=working or [{"role":"user","content":"small"}],tools=research_tools,
    )

    # A broad archive search can mechanically imply more result text than the
    # fixed per-result cap; it must be refused before local execution.
    broad_search_floor=_ora_tool_execution_floor_tokens("search_web_archive",{"query":"alpha","limit":30,"excerpt_chars":3000})
    execute_search,search_block,search_pre=_ora_tool_preflight_backpressure(
        fake,name="search_web_archive",arguments={"query":"alpha","limit":30,"excerpt_chars":3000},
        instructions="i"*4000,working=[{"role":"user","content":"small"}],tools=research_tools,
    )

    # Once one read in a parallel batch hits budget backpressure, a second
    # research read must be deferred just like a second book read.
    execute_parallel,parallel_block,parallel_pre=_ora_tool_preflight_backpressure(
        fake,name="read_web_archive_around",arguments={"reference":"WEB-TEST","query":"beta","before":1000,"after":3000},
        instructions="i"*4000,working=[{"role":"user","content":"small"}],tools=research_tools,prior_budget_block=True,
    )

    # Explicit zero-room case closes research reads without pretending evidence.
    class TightFakeModule(FakeModule):
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":20000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
    tight=TightFakeModule()
    execute_zero,zero_block,zero_pre=_ora_tool_preflight_backpressure(
        tight,name="read_web_evidence_unit",arguments={"unit_id":"WEU-TEST"},
        instructions="i"*4000,working=[{"role":"user","content":"y"*4000}],tools=research_tools,
    )

    broad_env=json.loads(broad_block or "{}")
    parallel_env=json.loads(parallel_block or "{}")
    zero_env=json.loads(zero_block or "{}")
    # Behavioral verification-lane contract. Older tests searched implementation
    # source text for a local variable name, which became stale after later wrappers
    # were added even though the common admission contract still closed the phase.
    import contextlib as _contextlib, io as _io
    with _contextlib.redirect_stdout(_io.StringIO()):
        receipt_wire,receipt_admission=_ora_tool_result_admission(
            tight,name="get_request_envelope_receipts",arguments={"limit":1},
            result={"ok":True,"receipts":[{"envelope_id":"ENV-SELFTEST"}]},
            instructions="i"*4000,working=[{"role":"user","content":"z"*40000}],tools=research_tools,
        )
    checks={
        "research_uses_common_backpressure_frame": callable(globals().get("_ora_tool_preflight_backpressure")) and callable(globals().get("_ora_tool_result_admission")),
        "request_receipt_reserved_lane_single_only": _ora_request_receipt_verification_lane("get_request_envelope_receipts", {"limit":1}) is True and _ora_request_receipt_verification_lane("get_request_envelope_receipts", {"limit":2}) is False,
        "request_receipt_reserved_admission_closes_tool_phase": receipt_admission.get("request_receipt_reserved_admitted") is True and receipt_admission.get("close_tool_phase_after_result") is True,
        "request_receipt_reserved_result_is_full_and_untruncated": receipt_admission.get("admitted") is True and receipt_admission.get("full_result_admitted") is True and receipt_admission.get("silent_truncation") is False and bool(receipt_wire),
        "research_budget_case_constructed": snapshot is not None and narrow_floor <= int((snapshot or {}).get("allowed_result_tokens") or 0) < broad_floor,
        "research_floor_scales_with_requested_range": broad_floor > narrow_floor >= int(_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS["read_web_archive_page"]),
        "broad_page_read_blocked_before_execution": execute_broad is False and broad_env.get("tool_executed") is False and broad_pre.get("reason")=="remaining_room_below_conservative_execution_floor",
        "materially_narrower_page_read_remains_available": execute_narrow is True and narrow_block=="" and narrow_pre.get("reason")=="sufficient_preflight_room",
        "oversized_archive_search_blocked_pre_execution": execute_search is False and broad_search_floor > int(_ONLINE_TOOL_RESULT_MAX_TOKENS) and search_pre.get("reason")=="remaining_room_below_conservative_execution_floor",
        "research_parallel_batch_avalanche_prevented": execute_parallel is False and parallel_pre.get("reason")=="previous_read_in_parallel_batch_hit_budget_guard" and parallel_env.get("evidence_returned") is False,
        "zero_room_research_read_closes_tool_phase": execute_zero is False and zero_pre.get("close_tool_phase") is True and zero_env.get("evidence_returned") is False,
        "blocked_research_claims_no_evidence": broad_env.get("evidence_returned") is False and broad_env.get("silent_truncation") is False and zero_env.get("evidence_returned") is False,
        "preflight_blocks_logged": any(e.get("event_type")=="tool.preflight_budget_blocked" for e in events),
        "zero_model_calls": True,
        "zero_web_calls": True,
    }
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":"7.4.64.4-research-backpressure","model_calls":0,"web_calls":0}


def raw_chat_tool_loop_budget_self_test(module=None) -> dict:
    """Zero-network regression for 7.4.64.5 row-atomic raw-chat backpressure."""
    events=[]
    test_db=sqlite3.connect(":memory:")
    test_db.row_factory=sqlite3.Row
    test_db.execute("""CREATE TABLE chat_messages(
        message_id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,role TEXT,provider TEXT,model TEXT,content TEXT,
        is_private INTEGER DEFAULT 0,content_sha256 TEXT
    )""")
    rows=[
        ("user", "u-small-1 " + "a"*900),
        ("assistant", "a-small-1 " + "b"*1100),
        ("user", "u-broad " + "c"*9000),
        ("assistant", "a-broad " + "d"*9000),
        ("user", "u-small-2 " + "e"*700),
        ("assistant", "a-small-2 " + "f"*800),
    ]
    for idx,(role,content) in enumerate(rows,1):
        test_db.execute(
            "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,0,?)",
            (f"2026-08-15T12:00:{idx:02d}+00:00",role,"online","test",content,hashlib.sha256(content.encode()).hexdigest()),
        )
    test_db.commit()
    class FakeModule:
        CHAT_OUTPUT_RESERVE_TOKENS=4096
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":30000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
        def db_connect(self): return test_db
        @staticmethod
        def _adaptive_estimate_tokens(text): return max(1,(len(str(text))+3)//4) if text else 0
        @staticmethod
        def append_diagnostic_log(event_type,summary,**kwargs): events.append({"event_type":event_type,**kwargs}); return {"ok":True}
    fake=FakeModule()
    tools=[
        {"type":"function","name":"search_raw_chat","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"read_raw_chat","parameters":{"type":"object","properties":{}}},
        {"type":"function","name":"read_raw_chat_around","parameters":{"type":"object","properties":{}}},
    ]
    narrow_args={"start_row":1,"count":2}
    broad_args={"start_row":1,"count":4}
    narrow_shape=_rcr_preflight_shape(fake,"read_raw_chat",narrow_args)
    broad_shape=_rcr_preflight_shape(fake,"read_raw_chat",broad_args)
    narrow_floor=_ora_tool_execution_floor_tokens("read_raw_chat",narrow_args,module=fake)
    broad_floor=_ora_tool_execution_floor_tokens("read_raw_chat",broad_args,module=fake)
    working=None; snapshot=None
    for chars in range(1000,60000,250):
        candidate=[{"role":"user","content":"r"*chars}]
        snap=_ora_tool_budget_snapshot(fake,instructions="i"*4000,working=candidate,tools=tools,mutation_tool=False)
        allowed=int(snap.get("allowed_result_tokens") or 0)
        if narrow_floor <= allowed < broad_floor:
            working=candidate; snapshot=snap; break
    execute_broad,broad_block,broad_pre=_ora_tool_preflight_backpressure(
        fake,name="read_raw_chat",arguments=broad_args,instructions="i"*4000,
        working=working or [{"role":"user","content":"small"}],tools=tools,
    )
    execute_narrow,narrow_block,narrow_pre=_ora_tool_preflight_backpressure(
        fake,name="read_raw_chat",arguments=narrow_args,instructions="i"*4000,
        working=working or [{"role":"user","content":"small"}],tools=tools,
    )
    narrow_result=_rcr_read(fake,1,2)
    around_shape=_rcr_preflight_shape(fake,"read_raw_chat_around",{"row_id":3,"before":1,"after":1})
    search_floor_small=_ora_tool_execution_floor_tokens("search_raw_chat",{"query":"x","limit":2},module=fake)
    search_floor_large=_ora_tool_execution_floor_tokens("search_raw_chat",{"query":"x","limit":30},module=fake)
    execute_parallel,parallel_block,parallel_pre=_ora_tool_preflight_backpressure(
        fake,name="read_raw_chat_around",arguments={"row_id":3,"before":15,"after":15},
        instructions="i"*4000,working=[{"role":"user","content":"small"}],tools=tools,prior_budget_block=True,
    )
    class TightFakeModule(FakeModule):
        _ADAPTIVE_LAST_DECISION={"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":20000,"safety_margin_tokens":4096}
        _ONLINE_PROVIDER_PREFLIGHT_LAST={"max_output_tokens":4096}
    tight=TightFakeModule()
    execute_zero,zero_block,zero_pre=_ora_tool_preflight_backpressure(
        tight,name="read_raw_chat",arguments={"start_row":1,"count":2},instructions="i"*4000,
        working=[{"role":"user","content":"y"*4000}],tools=tools,
    )
    broad_env=json.loads(broad_block or "{}")
    parallel_env=json.loads(parallel_block or "{}")
    zero_env=json.loads(zero_block or "{}")
    checks={
        "raw_chat_uses_common_backpressure_frame": callable(globals().get("_ora_tool_preflight_backpressure")) and callable(globals().get("_ora_tool_result_admission")),
        "raw_chat_row_shape_uses_sqlite_lengths": narrow_shape.get("method")=="sqlite_length_only" and broad_shape.get("method")=="sqlite_length_only" and int(broad_shape.get("content_chars") or 0)>int(narrow_shape.get("content_chars") or 0),
        "two_row_exchange_cheaper_than_broad_window": narrow_floor < broad_floor,
        "raw_chat_budget_case_constructed": snapshot is not None and narrow_floor <= int((snapshot or {}).get("allowed_result_tokens") or 0) < broad_floor,
        "broad_row_window_blocked_before_execution": execute_broad is False and broad_env.get("tool_executed") is False and broad_pre.get("reason")=="remaining_room_below_conservative_execution_floor",
        "two_row_exchange_remains_available": execute_narrow is True and narrow_block=="" and narrow_pre.get("reason")=="sufficient_preflight_room",
        "rows_are_atomic_after_read": narrow_result.get("row_atomic") is True and narrow_result.get("clipped") is False and narrow_result.get("count")==2 and all(r.get("content_complete") is True for r in narrow_result.get("rows") or []),
        "around_window_is_row_mechanical": around_shape.get("rows")==3 and around_shape.get("row_atomic") is True,
        "raw_chat_search_floor_scales_with_result_rows": search_floor_large > search_floor_small,
        "raw_chat_parallel_batch_avalanche_prevented": execute_parallel is False and parallel_pre.get("reason")=="previous_read_in_parallel_batch_hit_budget_guard" and parallel_env.get("evidence_returned") is False,
        "zero_room_raw_chat_closes_tool_phase": execute_zero is False and zero_pre.get("close_tool_phase") is True and zero_env.get("evidence_returned") is False,
        "blocked_raw_chat_claims_no_evidence": broad_env.get("evidence_returned") is False and broad_env.get("silent_truncation") is False and zero_env.get("evidence_returned") is False,
        "preflight_blocks_logged": any(e.get("event_type")=="tool.preflight_budget_blocked" for e in events),
        "zero_model_calls": True,
        "zero_web_calls": True,
    }
    test_db.close()
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":"7.4.64.5-raw-chat-row-backpressure","model_calls":0,"web_calls":0}


