    def episodic_blackbox_self_test() -> dict:
        bb_ensure_schema()
        secret = "blackbox self-test secret phrase 7f92"
        event = bb_begin_event("self_test", secret, provider="python", model=BUNDLE_VERSION,
                               history=[{"role": "user", "content": secret}], parameters={"temperature": 0.0})
