def _install_blackbox_digest(digest_module, memory_module) -> None:
    if getattr(digest_module, "_BLACKBOX_DIGEST_INSTALLED", False):
        return
    begin = getattr(memory_module, "_blackbox_begin_event", None)
    add_frame = getattr(memory_module, "_blackbox_add_frame", None)
    add_outcome = getattr(memory_module, "_blackbox_add_outcome", None)
    finalize = getattr(memory_module, "_blackbox_finalize_event", None)
    if not all(callable(item) for item in (begin, add_frame, add_outcome, finalize)):
        return

    def backend_meta(backend) -> tuple[str, str]:
        return str(getattr(backend, "provider", "digest")), str(getattr(backend, "model_id", "unknown"))

    def install_model_wrapper(function_name: str, event_type: str, input_builder, prompt_builder=None) -> None:
        original = getattr(digest_module, function_name, None)
        if not callable(original):
            return
        def wrapped(*args, **kwargs):
            backend = args[0] if args else kwargs.get("backend")
            provider, model = backend_meta(backend)
            event_input = input_builder(args, kwargs)
            event = begin(event_type, event_input, provider=provider, model=model,
                          parameters={"digest_function": function_name})
            try:
                if callable(prompt_builder):
                    prompt_value = prompt_builder(args, kwargs)
                    add_frame(event, "digest_model_prompt", prompt_value)
                result = original(*args, **kwargs)
                add_frame(event, "digest_model_output", result)
                add_outcome(event["event_id"], "digest_model_call_complete", success=True, source="python")
                return result
            except Exception as exc:
                finalize(event, error=exc)
                raise
        setattr(digest_module, function_name, wrapped)

    install_model_wrapper(
        "call_digest_model", "digest_model_call",
        lambda args, kwargs: args[1] if len(args) > 1 else kwargs.get("section"),
        lambda args, kwargs: digest_module.build_prompt(args[1] if len(args) > 1 else kwargs.get("section")),
    )
    install_model_wrapper(
        "call_reflection_model", "reflection_model_call",
        lambda args, kwargs: args[1] if len(args) > 1 else kwargs.get("window"),
        lambda args, kwargs: digest_module.build_reflection_prompt(args[1] if len(args) > 1 else kwargs.get("window")),
    )
    install_model_wrapper(
        "_call_report_digest_model", "research_report_digest_model_call",
        lambda args, kwargs: {
            "report": args[1] if len(args) > 1 else kwargs.get("report"),
            "source_registry": args[2] if len(args) > 2 else kwargs.get("registry"),
        },
        lambda args, kwargs: digest_module._compact_report_for_model(
            args[1] if len(args) > 1 else kwargs.get("report"),
            args[2] if len(args) > 2 else kwargs.get("registry"),
        ),
    )
    install_model_wrapper(
        "_call_book_digest_model", "book_digest_model_call",
        lambda args, kwargs: {
            "book": args[1] if len(args) > 1 else kwargs.get("book"),
            "scope": args[2] if len(args) > 2 else kwargs.get("scope"),
            "batch": args[3] if len(args) > 3 else kwargs.get("batch"),
            "batch_number": args[4] if len(args) > 4 else kwargs.get("batch_number"),
            "total_batches": args[5] if len(args) > 5 else kwargs.get("total_batches"),
        },
    )

    def install_write_wrapper(function_name: str, event_type: str) -> None:
        original = getattr(digest_module, function_name, None)
        if not callable(original):
            return
        def wrapped(*args, **kwargs):
            backend = kwargs.get("backend")
            provider, model = backend_meta(backend)
            safe_kwargs = {key: value for key, value in kwargs.items() if key != "backend"}
            event = begin(event_type, {"args": list(args), "kwargs": safe_kwargs},
                          provider=provider if backend is not None else "python",
                          model=model if backend is not None else BUNDLE_VERSION,
                          parameters={"digest_function": function_name, "database_write": True})
            try:
                result = original(*args, **kwargs)
                add_frame(event, "digest_write_result", result)
                add_outcome(event["event_id"], "digest_memory_write_complete", success=True, source="python")
                return result
            except Exception as exc:
                finalize(event, error=exc)
                raise
        setattr(digest_module, function_name, wrapped)

    install_write_wrapper("insert_batch", "digest_memory_write")
    install_write_wrapper("_insert_book_digest_batch", "book_digest_memory_write")

    original_help = getattr(digest_module, "print_help", None)
    def help_with_blackbox(*args, **kwargs):
        result = original_help(*args, **kwargs) if callable(original_help) else None
        print("\nEncrypted episodic black box:")
        print("  /blackbox status | /blackbox events [count] | /blackbox show <BBE-ID>")
        print("  /blackbox search <query> | /blackbox verify [BBE-ID] | /blackbox replay <BBE-ID>")
        return result
    digest_module.print_help = help_with_blackbox

    original_main = digest_module.main
    def main_with_blackbox_commands():
        original_input = builtins.input
        def intercepted_input(prompt=""):
            while True:
                raw = original_input(prompt)
                clean = str(raw).strip()
                lower = clean.casefold()
                if not lower.startswith("/blackbox"):
                    return raw
                try:
                    if lower in {"/blackbox", "/blackbox help"}:
                        print("/blackbox status | events [count] | show <id> | search <query> | verify [id] | replay <id>")
                    elif lower == "/blackbox status":
                        print(json.dumps(memory_module.get_blackbox_status(), ensure_ascii=False, indent=2))
                    elif lower.startswith("/blackbox events"):
                        parts = clean.split()
                        count = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 20
                        print(json.dumps(memory_module.list_blackbox_events(count), ensure_ascii=False, indent=2))
                    elif lower.startswith("/blackbox show "):
                        print(json.dumps(memory_module.get_blackbox_event(clean.split(maxsplit=2)[2].strip()), ensure_ascii=False, indent=2, default=str))
                    elif lower.startswith("/blackbox search "):
                        print(json.dumps(memory_module.search_blackbox_events(clean.split(maxsplit=2)[2].strip()), ensure_ascii=False, indent=2))
                    elif lower == "/blackbox verify":
                        print(json.dumps(memory_module.verify_blackbox(), ensure_ascii=False, indent=2))
                    elif lower.startswith("/blackbox verify "):
                        print(json.dumps(memory_module.verify_blackbox(clean.split(maxsplit=2)[2].strip()), ensure_ascii=False, indent=2))
                    elif lower.startswith("/blackbox replay "):
                        print(json.dumps(memory_module.replay_blackbox_event(clean.split(maxsplit=2)[2].strip()), ensure_ascii=False, indent=2, default=str))
                    else:
                        print("Unknown black-box command. Use /blackbox help.")
                except Exception as exc:
                    print(f"Black-box error: {type(exc).__name__}: {exc}")
        builtins.input = intercepted_input
        try:
            return original_main()
        finally:
            builtins.input = original_input
    digest_module.main = main_with_blackbox_commands
    digest_module.BLACKBOX_VERSION = getattr(memory_module, "BLACKBOX_VERSION", _BLACKBOX_VERSION)
    digest_module._BLACKBOX_DIGEST_INSTALLED = True



