_DIAGNOSTIC_LOGBOOK_VERSION = "1.3-forensic-receipt-completeness-identifier-fidelity"
_DIAGNOSTIC_LOGBOOK_DB_FILE = "diagnostic_logbook.sqlite"
_DIAGNOSTIC_LOGBOOK_KEY_FILE = "diagnostic_logbook.local.key"
_DIAGNOSTIC_LOGBOOK_MAGIC = b"NMDL1"
_DIAGNOSTIC_LOGBOOK_ENTROPY = b"NeatMemory.DiagnosticLogbook.v1"
_DIAGNOSTIC_LOGBOOK_MAX_ENTRIES = 2000
_DIAGNOSTIC_LOGBOOK_MAX_READ = 500
_DIAGNOSTIC_LOGBOOK_MAX_SEARCH_SCAN = _DIAGNOSTIC_LOGBOOK_MAX_ENTRIES
_FORENSIC_TURN_RECEIPT_VERSION = "1.1-complete-mechanical-turn-forensics"
_FORENSIC_TURN_RECEIPT_MAX_EVENTS = 512
_FORENSIC_TURN_RECEIPT_MAX_TOOL_CALLS = 128
_DIAGNOSTIC_LOGBOOK_MAX_MESSAGE = 12000
_DIAGNOSTIC_LOGBOOK_TOOL_NAMES = {
    "read_diagnostic_logs", "search_diagnostic_logs", "get_diagnostic_log", "diagnostic_logbook_status",
}


def _dl_redact(value, *, depth: int = 0):
    """Bound diagnostic payloads and redact credential-shaped material before encryption."""
    if depth > 10:
        return "[depth-limit]"
    secret_keys = {
        "api_key", "apikey", "authorization", "password", "passphrase", "secret",
        "access_token", "refresh_token", "client_secret", "private_key",
    }
    if isinstance(value, dict):
        output = {}
        for key, item in list(value.items())[:200]:
            name = str(key)[:160]
            if name.casefold() in secret_keys:
                output[name] = "[REDACTED]"
            else:
                output[name] = _dl_redact(item, depth=depth + 1)
        return output
    if isinstance(value, (list, tuple, set)):
        return [_dl_redact(item, depth=depth + 1) for item in list(value)[:200]]
    if isinstance(value, bytes):
        return f"[bytes:{len(value)} sha256={hashlib.sha256(value).hexdigest()}]"
    if isinstance(value, str):
        text = value[:_DIAGNOSTIC_LOGBOOK_MAX_MESSAGE]
        # Never persist common bearer/API-key shapes even inside encrypted diagnostics.
        text = re.sub(r"(?i)\\bBearer\\s+[A-Za-z0-9._~+/-]{8,}", "Bearer [REDACTED]", text)
        text = re.sub(r"\\bsk-[A-Za-z0-9_-]{12,}\\b", "sk-[REDACTED]", text)
        return text
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return str(value)[:_DIAGNOSTIC_LOGBOOK_MAX_MESSAGE]


def _dl_adaptive_snapshot(module) -> dict:
    decision = dict(getattr(module, "_ADAPTIVE_LAST_DECISION", {}) or {})
    selected = str(decision.get("selected") or "")
    level = dict((decision.get("levels") or {}).get(selected) or {})
    usage = dict(decision.get("actual_provider_usage") or {})
    routing = dict(decision.get("domain_routing") or {})
    return {
        "selected": selected or None,
        "estimated_complete_prompt_tokens": level.get("estimated_complete_prompt_tokens"),
        "safe_input_limit_tokens": decision.get("safe_input_limit_tokens"),
        "model_context_limit_tokens": decision.get("model_context_limit_tokens"),
        "provider_input_tokens": usage.get("provider_input_tokens"),
        "context_priority": decision.get("context_priority"),
        "selected_domains": routing.get("selected_domains"),
    }


def _install_encrypted_diagnostic_logbook(module) -> None:
    if getattr(module, "_ENCRYPTED_DIAGNOSTIC_LOGBOOK_INSTALLED", False):
        return

    crypto_module = sys.modules.get("neatcrypto_dpapi_v1")
    legacy_append = getattr(module, "append_system_log", None)
    legacy_read = getattr(module, "read_system_log", None)

    def dl_db_path() -> Path:
        return module.safe_memory_path(_DIAGNOSTIC_LOGBOOK_DB_FILE)

    def dl_key_path() -> Path:
        return module.safe_memory_path(_DIAGNOSTIC_LOGBOOK_KEY_FILE)

    def dl_connect() -> sqlite3.Connection:
        path = dl_db_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        db = sqlite3.connect(path, timeout=60.0)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=FULL")
        db.execute("PRAGMA busy_timeout=60000")
        return db

    def dl_ensure_schema() -> None:
        with dl_connect() as db:
            db.executescript("""
            CREATE TABLE IF NOT EXISTS diagnostic_logbook_meta (
                singleton INTEGER PRIMARY KEY CHECK(singleton=1),
                feature_version TEXT NOT NULL,
                max_entries INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS diagnostic_logbook_entries (
                sequence INTEGER PRIMARY KEY,
                log_id TEXT NOT NULL UNIQUE,
                content_sha256 TEXT NOT NULL,
                cipher_sha256 TEXT NOT NULL,
                encryption_mode TEXT NOT NULL,
                encrypted_blob BLOB NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_diagnostic_log_sequence
                ON diagnostic_logbook_entries(sequence DESC);
            CREATE TRIGGER IF NOT EXISTS diagnostic_logbook_no_update
            BEFORE UPDATE ON diagnostic_logbook_entries
            BEGIN SELECT RAISE(ABORT, 'diagnostic log entries are immutable'); END;
            """)
            db.execute(
                "INSERT INTO diagnostic_logbook_meta(singleton,feature_version,max_entries) VALUES(1,?,?) "
                "ON CONFLICT(singleton) DO UPDATE SET feature_version=excluded.feature_version,max_entries=excluded.max_entries",
                (_DIAGNOSTIC_LOGBOOK_VERSION, _DIAGNOSTIC_LOGBOOK_MAX_ENTRIES),
            )

    def dl_local_key() -> bytes:
        path = dl_key_path()
        if path.exists():
            key = path.read_bytes()
            if len(key) != 32:
                raise RuntimeError("Invalid diagnostic-logbook local key length.")
            return key
        key = os.urandom(32)
        temp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
        temp.write_bytes(key)
        try:
            os.chmod(temp, 0o600)
        except OSError:
            pass
        os.replace(temp, path)
        return key

    def dl_encrypt(raw: bytes) -> tuple[str, bytes]:
        compressed = zlib.compress(raw, 9)
        if os.name == "nt" and crypto_module is not None:
            protected = crypto_module.protect_bytes(compressed, entropy=_DIAGNOSTIC_LOGBOOK_ENTROPY)
            return "windows-dpapi-current-user", _DIAGNOSTIC_LOGBOOK_MAGIC + b"D" + protected
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except Exception as exc:
            raise RuntimeError(
                "Encrypted diagnostic logging requires Windows DPAPI or the cryptography package; plaintext fallback is forbidden."
            ) from exc
        nonce = os.urandom(12)
        encrypted = AESGCM(dl_local_key()).encrypt(nonce, compressed, _DIAGNOSTIC_LOGBOOK_ENTROPY)
        return "aes-256-gcm-local-key", _DIAGNOSTIC_LOGBOOK_MAGIC + b"A" + nonce + encrypted

    def dl_decrypt(blob: bytes) -> bytes:
        payload = bytes(blob)
        if not payload.startswith(_DIAGNOSTIC_LOGBOOK_MAGIC) or len(payload) < len(_DIAGNOSTIC_LOGBOOK_MAGIC) + 1:
            raise RuntimeError("Unrecognized encrypted diagnostic-log object.")
        mode = payload[len(_DIAGNOSTIC_LOGBOOK_MAGIC):len(_DIAGNOSTIC_LOGBOOK_MAGIC) + 1]
        body = payload[len(_DIAGNOSTIC_LOGBOOK_MAGIC) + 1:]
        if mode == b"D":
            if crypto_module is None:
                raise RuntimeError("Windows DPAPI helper is unavailable for diagnostic-log decryption.")
            compressed = crypto_module.unprotect_bytes(body, entropy=_DIAGNOSTIC_LOGBOOK_ENTROPY)
        elif mode == b"A":
            if len(body) < 13:
                raise RuntimeError("Truncated AES-GCM diagnostic-log object.")
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            nonce, encrypted = body[:12], body[12:]
            compressed = AESGCM(dl_local_key()).decrypt(nonce, encrypted, _DIAGNOSTIC_LOGBOOK_ENTROPY)
        else:
            raise RuntimeError("Unknown diagnostic-log encryption mode.")
        return zlib.decompress(compressed)

    def dl_max_entries() -> int:
        override = getattr(module, "_DIAGNOSTIC_LOGBOOK_MAX_OVERRIDE", None)
        if override is not None:
            return max(2, min(_DIAGNOSTIC_LOGBOOK_MAX_ENTRIES, int(override)))
        return _DIAGNOSTIC_LOGBOOK_MAX_ENTRIES

    def dl_decode_row(row) -> dict:
        raw = dl_decrypt(row["encrypted_blob"])
        digest = hashlib.sha256(raw).hexdigest()
        if digest != str(row["content_sha256"]):
            raise RuntimeError(f"Diagnostic log integrity mismatch: {row['log_id']}")
        event = json.loads(raw.decode("utf-8"))
        if not isinstance(event, dict):
            raise RuntimeError("Diagnostic log payload is not an object.")
        event["integrity_verified"] = True
        event["encryption_mode"] = str(row["encryption_mode"])
        return event

    _forensic_provenance_id_re = re.compile(r"(?<![A-Za-z0-9])(?:NB|BK|KI|KP|KSB|KSR|KSO|KDV)-(?=[A-Za-z0-9-]*\d)[A-Za-z0-9][A-Za-z0-9-]{5,72}")

    def _publish_forensic_operational_ids(entries) -> None:
        verified=[]; ids=[]
        for entry in list(entries or []):
            if not isinstance(entry,dict) or entry.get("integrity_verified") is not True or str(entry.get("event_type") or "").casefold()!="forensics.turn_receipt":
                continue
            verified.append(str(entry.get("diagnostic_log_id") or ""))
            text=json.dumps(entry.get("details") or {},ensure_ascii=False,sort_keys=True,default=str)
            for match in _forensic_provenance_id_re.finditer(text):
                value=match.group(0)
                if value not in ids: ids.append(value)
                if len(ids)>=512: break
        if verified:
            current=list(getattr(module,"_FORENSIC_VISIBLE_IDENTIFIER_ALLOWLIST",[]) or [])
            merged=[]
            for value in current+ids:
                if value and value not in merged: merged.append(value)
                if len(merged)>=512: break
            module._FORENSIC_VISIBLE_IDENTIFIER_ALLOWLIST=merged
            module._FORENSIC_VISIBLE_IDENTIFIER_SOURCE={"diagnostic_log_ids":verified[:24],"authority":"OPERATIONAL_IDENTITY_ONLY","creates_evidence_authority":False,"creates_claim_binding":False}

    def append_diagnostic_log(event_type: str, summary: str, *, details=None, severity: str = "info",
                              provider: str | None = None, model: str | None = None,
                              source: str = "python", subsystem: str | None = None,
                              related_refs=None) -> dict:
        event = re.sub(r"[^a-z0-9_.-]+", "_", str(event_type or "event").strip().casefold()).strip("_") or "event"
        level = str(severity or "info").strip().casefold()
        if level not in {"debug", "info", "warning", "error", "critical"}:
            level = "info"
        message = " ".join(str(summary or "").split())[:_DIAGNOSTIC_LOGBOOK_MAX_MESSAGE]
        if not message:
            message = event
        inferred_subsystem = str(subsystem or "").strip().casefold()
        if not inferred_subsystem:
            inferred_subsystem = re.split(r"[._-]", event, maxsplit=1)[0] or "system"
        now_utc = datetime.now(timezone.utc)
        now_local = datetime.now().astimezone()
        safe_details = _dl_redact(details if details is not None else {})
        active_turn_id = str(getattr(module, "_FORENSIC_ACTIVE_TURN_ID", "") or "")
        if active_turn_id and isinstance(safe_details, dict) and not safe_details.get("turn_id"):
            safe_details["turn_id"] = active_turn_id
        safe_refs = _dl_redact(list(related_refs or [])[:100])
        try:
            dl_ensure_schema()
            with dl_connect() as db:
                db.execute("BEGIN IMMEDIATE")
                row = db.execute("SELECT sequence FROM diagnostic_logbook_entries ORDER BY sequence DESC LIMIT 1").fetchone()
                sequence = int(row["sequence"] + 1) if row else 1
                log_id = f"LOG-{sequence:012d}"
                payload = {
                    "log_id": sequence,
                    "diagnostic_log_id": log_id,
                    "sequence": sequence,
                    "timestamp": now_local.isoformat(timespec="milliseconds"),
                    "timestamp_utc": now_utc.isoformat(timespec="milliseconds"),
                    "session_id": str(getattr(module, "SESSION_ID", "") or ""),
                    "process_id": os.getpid(),
                    "thread_id": threading.get_ident(),
                    "subsystem": inferred_subsystem[:120],
                    "event_type": event,
                    "severity": level,
                    "summary": message,
                    "details": safe_details,
                    "provider": None if provider is None else str(provider)[:120],
                    "model": None if model is None else str(model)[:240],
                    "source": str(source or "python")[:120],
                    "related_refs": safe_refs,
                    "bundle_version": str(getattr(module, "NEATMEMORY_VERSION", BUNDLE_VERSION)),
                }
                raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
                encryption_mode, encrypted_blob = dl_encrypt(raw)
                db.execute(
                    "INSERT INTO diagnostic_logbook_entries(sequence,log_id,content_sha256,cipher_sha256,encryption_mode,encrypted_blob) VALUES(?,?,?,?,?,?)",
                    (sequence, log_id, hashlib.sha256(raw).hexdigest(), hashlib.sha256(encrypted_blob).hexdigest(), encryption_mode, encrypted_blob),
                )
                cutoff = sequence - dl_max_entries()
                pruned = 0
                if cutoff > 0:
                    cur = db.execute("DELETE FROM diagnostic_logbook_entries WHERE sequence<=?", (cutoff,))
                    pruned = int(cur.rowcount if cur.rowcount is not None and cur.rowcount >= 0 else 0)
            accumulator = getattr(module, "_FORENSIC_TURN_ACCUMULATOR", None)
            if isinstance(accumulator, dict) and event != "forensics.turn_receipt":
                accumulator["events_seen"] = int(accumulator.get("events_seen") or 0) + 1
                events = accumulator.setdefault("events", [])
                if len(events) < _FORENSIC_TURN_RECEIPT_MAX_EVENTS:
                    events.append({
                        "sequence": sequence, "diagnostic_log_id": log_id, "timestamp_utc": payload["timestamp_utc"],
                        "event_type": event, "subsystem": payload["subsystem"], "severity": level,
                        "summary": message, "details": safe_details, "provider": payload["provider"], "model": payload["model"],
                    })
                else:
                    accumulator["events_truncated"] = True
            return {
                "ok": True, "log_id": sequence, "diagnostic_log_id": log_id,
                "timestamp": payload["timestamp"], "event_type": event, "summary": message,
                "encrypted_at_rest": True, "encryption_mode": encryption_mode,
                "rotating": True, "max_entries": dl_max_entries(), "pruned": pruned,
            }
        except Exception as exc:
            # Diagnostics must never downgrade to plaintext and must not crash the primary operation.
            return {
                "ok": False, "event_type": event, "error": f"{type(exc).__name__}: {exc}",
                "encrypted_at_rest": True, "plaintext_fallback": False,
            }

    def read_diagnostic_logs(limit: int = 20, *, severity: str | None = None,
                             subsystem: str | None = None, event_type: str | None = None) -> dict:
        amount = max(1, min(_DIAGNOSTIC_LOGBOOK_MAX_READ, int(limit)))
        try:
            dl_ensure_schema()
            with dl_connect() as db:
                rows = db.execute("SELECT * FROM diagnostic_logbook_entries ORDER BY sequence DESC").fetchall()
            entries = []
            errors = []
            for row in rows:
                try:
                    event = dl_decode_row(row)
                except Exception as exc:
                    errors.append({"log_id": str(row["log_id"]), "error": f"{type(exc).__name__}: {exc}"})
                    continue
                if severity and str(event.get("severity") or "").casefold() != str(severity).casefold():
                    continue
                if subsystem and str(event.get("subsystem") or "").casefold() != str(subsystem).casefold():
                    continue
                if event_type and str(event.get("event_type") or "").casefold() != str(event_type).casefold():
                    continue
                entries.append(event)
                if len(entries) >= amount:
                    break
            entries.reverse()
            _publish_forensic_operational_ids(entries)
            return {
                "ok": not errors, "encrypted_at_rest": True, "plaintext_fallback": False,
                "rotating": True, "max_entries": dl_max_entries(), "count": len(entries),
                "entries": entries, "read_errors": errors[:20],
                "model_calls": 0, "web_calls": 0,
                "reader_model_calls": 0, "reader_web_calls": 0,
                "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity",
                "llm_access": "read-only", "writer": "python",
            }
        except Exception as exc:
            return {"ok": False, "error": f"{type(exc).__name__}: {exc}", "entries": [], "encrypted_at_rest": True, "model_calls": 0, "web_calls": 0, "reader_model_calls": 0, "reader_web_calls": 0, "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity"}

    def search_diagnostic_logs(query: str = "", limit: int = 50, *, severity: str | None = None,
                               subsystem: str | None = None, event_type: str | None = None,
                               turn_id: str | None = None, min_sequence: int | None = None,
                               max_sequence: int | None = None) -> dict:
        clean = str(query or "").strip().casefold()
        terms = [term for term in re.findall(r"[\w.-]+", clean) if term]
        amount = max(1, min(200, int(limit)))
        try:
            dl_ensure_schema()
            with dl_connect() as db:
                rows = db.execute("SELECT * FROM diagnostic_logbook_entries ORDER BY sequence DESC LIMIT ?", (_DIAGNOSTIC_LOGBOOK_MAX_SEARCH_SCAN,)).fetchall()
            matches=[]; errors=[]; scanned=0
            for row in rows:
                sequence=int(row["sequence"]); scanned += 1
                if min_sequence is not None and sequence < int(min_sequence): continue
                if max_sequence is not None and sequence > int(max_sequence): continue
                try:
                    event=dl_decode_row(row)
                except Exception as exc:
                    errors.append({"log_id":str(row["log_id"]),"error":f"{type(exc).__name__}: {exc}"}); continue
                if severity and str(event.get("severity") or "").casefold()!=str(severity).casefold(): continue
                if subsystem and str(event.get("subsystem") or "").casefold()!=str(subsystem).casefold(): continue
                if event_type and str(event.get("event_type") or "").casefold()!=str(event_type).casefold(): continue
                if turn_id and str((event.get("details") or {}).get("turn_id") or "").casefold()!=str(turn_id).casefold(): continue
                haystack=json.dumps(event,ensure_ascii=False,sort_keys=True,default=str).casefold()
                if terms and not all(term in haystack for term in terms): continue
                matches.append(event)
                if len(matches)>=amount: break
            matches.reverse()
            _publish_forensic_operational_ids(matches)
            return {
                "ok": not errors, "query":str(query or ""), "count":len(matches), "entries":matches,
                "scanned_retained_entries":scanned, "search_scan_ceiling":_DIAGNOSTIC_LOGBOOK_MAX_SEARCH_SCAN,
                "retention_ceiling":dl_max_entries(), "full_retained_window_search":True, "read_errors":errors[:20],
                "encrypted_at_rest":True,"model_calls":0,"web_calls":0,"reader_model_calls":0,"reader_web_calls":0,
                "counter_scope":"this diagnostic-log search operation only; not aggregate runtime/chat activity",
            }
        except Exception as exc:
            return {"ok":False,"error":f"{type(exc).__name__}: {exc}","query":str(query or ""),"entries":[],"count":0,"model_calls":0,"web_calls":0}

    def get_diagnostic_log(log_id) -> dict:
        text = str(log_id or "").strip().upper()
        match = re.search(r"(\d+)$", text)
        if not match:
            return {"ok": False, "error": "Expected LOG-<sequence> or numeric log sequence.", "model_calls": 0, "web_calls": 0, "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity"}
        sequence = int(match.group(1))
        try:
            dl_ensure_schema()
            with dl_connect() as db:
                row = db.execute("SELECT * FROM diagnostic_logbook_entries WHERE sequence=?", (sequence,)).fetchone()
            if row is None:
                return {"ok": False, "error": "Diagnostic log entry is not retained (unknown or rotated out).", "sequence": sequence, "model_calls": 0, "web_calls": 0, "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity"}
            entry=dl_decode_row(row)
            _publish_forensic_operational_ids([entry])
            return {"ok": True, "entry": entry, "encrypted_at_rest": True, "model_calls": 0, "web_calls": 0, "reader_model_calls": 0, "reader_web_calls": 0, "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity"}
        except Exception as exc:
            return {"ok": False, "error": f"{type(exc).__name__}: {exc}", "sequence": sequence, "model_calls": 0, "web_calls": 0, "counter_scope": "this diagnostic-log read operation only; not aggregate runtime/chat activity"}

    def diagnostic_logbook_status() -> dict:
        try:
            dl_ensure_schema()
            with dl_connect() as db:
                count = int(db.execute("SELECT COUNT(*) FROM diagnostic_logbook_entries").fetchone()[0])
                bounds = db.execute("SELECT MIN(sequence),MAX(sequence) FROM diagnostic_logbook_entries").fetchone()
                modes = [str(row[0]) for row in db.execute("SELECT DISTINCT encryption_mode FROM diagnostic_logbook_entries ORDER BY encryption_mode").fetchall()]
            return {
                "ok": True, "version": _DIAGNOSTIC_LOGBOOK_VERSION,
                "path": str(dl_db_path()), "encrypted_at_rest": True,
                "windows_live_encryption": "DPAPI current-user" if os.name == "nt" else "not-current-platform",
                "fallback_encryption": "AES-256-GCM local key (non-Windows/test only)",
                "plaintext_fallback": False, "rotating": True, "max_entries": dl_max_entries(),
                "retained_entries": count,
                "oldest_sequence": None if not bounds or bounds[0] is None else int(bounds[0]),
                "newest_sequence": None if not bounds or bounds[1] is None else int(bounds[1]),
                "encryption_modes_present": modes,
                "llm_access": "read-only", "writer": "python", "model_calls": 0, "web_calls": 0,
                "reader_model_calls": 0, "reader_web_calls": 0,
                "counter_scope": "this diagnostic-log status/read operation only; not aggregate runtime/chat activity",
                "legacy_note": "Pre-7.4.51 plaintext system-log artifacts, if present, are historical legacy only; 7.4.51+ does not append new events to them.",
            }
        except Exception as exc:
            return {"ok": False, "error": f"{type(exc).__name__}: {exc}", "encrypted_at_rest": True, "plaintext_fallback": False}

    # Compatibility surface: existing /log commands and SYSTEM-context logbook now
    # read/write the encrypted rotating store instead of the old plaintext table/file.
    def append_system_log(event_type: str, summary: str, *, details=None, severity: str = "info",
                          provider: str | None = None, model: str | None = None, source: str = "python") -> dict:
        return append_diagnostic_log(
            event_type, summary, details=details, severity=severity,
            provider=provider, model=model, source=source,
        )

    def read_system_log(limit: int = 20, query: str | None = None, event_type: str | None = None) -> dict:
        if query and str(query).strip():
            return search_diagnostic_logs(str(query), limit=max(1, min(_DIAGNOSTIC_LOGBOOK_MAX_READ, int(limit))))
        return read_diagnostic_logs(limit, event_type=event_type)

    module.append_diagnostic_log = append_diagnostic_log
    module.read_diagnostic_logs = read_diagnostic_logs
    module.search_diagnostic_logs = search_diagnostic_logs
    module.get_diagnostic_log = get_diagnostic_log
    module.diagnostic_logbook_status = diagnostic_logbook_status
    module.append_system_log = append_system_log
    module.read_system_log = read_system_log
    module.LOGBOOK_FILE = _DIAGNOSTIC_LOGBOOK_DB_FILE
    module.DIAGNOSTIC_LOGBOOK_VERSION = _DIAGNOSTIC_LOGBOOK_VERSION
    module.DIAGNOSTIC_LOGBOOK_MAX_ENTRIES = _DIAGNOSTIC_LOGBOOK_MAX_ENTRIES
    module._FORENSIC_VISIBLE_IDENTIFIER_ALLOWLIST=[]
    module._FORENSIC_VISIBLE_IDENTIFIER_SOURCE={}
    module._DIAGNOSTIC_LOGBOOK_LEGACY_APPEND = legacy_append
    module._DIAGNOSTIC_LOGBOOK_LEGACY_READ = legacy_read

    # Read-only tools for Assistant. The write function is deliberately never exposed.
    schemas = getattr(module, "TOOL_SCHEMAS", None)
    if isinstance(schemas, list):
        existing = set()
        for schema in schemas:
            fn = schema.get("function") if isinstance(schema, dict) else None
            if isinstance(fn, dict) and fn.get("name"):
                existing.add(str(fn.get("name")))
        additions = [
            {"type":"function","function":{"name":"read_diagnostic_logs","description":"Read the most recent encrypted rotating NeatMemory diagnostic-log entries. Python decrypts locally; read-only. Any model_calls/web_calls fields describe only this log-reading operation, never aggregate chat/provider activity.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":500},"severity":{"type":["string","null"]},"subsystem":{"type":["string","null"]},"event_type":{"type":["string","null"]}},"additionalProperties":False}}},
            {"type":"function","function":{"name":"search_diagnostic_logs","description":"Search across the full retained encrypted Diagnostic Logbook window (up to 2,000 events) while returning at most 200 bounded matches. Exact event_type/turn_id/sequence filters are mechanical and read-only. A single event_type=forensics.turn_receipt, limit=1 lookup has a small reserved forensic verification lane.","parameters":{"type":"object","properties":{"query":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":200},"severity":{"type":["string","null"]},"subsystem":{"type":["string","null"]},"event_type":{"type":["string","null"]},"turn_id":{"type":["string","null"]},"min_sequence":{"type":["integer","null"]},"max_sequence":{"type":["integer","null"]}},"additionalProperties":False}}},
            {"type":"function","function":{"name":"get_diagnostic_log","description":"Open one retained encrypted diagnostic event by LOG-ID or numeric sequence. Read-only.","parameters":{"type":"object","properties":{"log_id":{"type":["string","integer"]}},"required":["log_id"],"additionalProperties":False}}},
            {"type":"function","function":{"name":"diagnostic_logbook_status","description":"Inspect encrypted Diagnostic Logbook health, retention count, rotation limit and encryption mode. Read-only.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        ]
        schemas.extend(schema for schema in additions if schema["function"]["name"] not in existing)

    if isinstance(getattr(module, "_READ_ONLY_TEXT_TOOL_ALLOWLIST", None), set):
        module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update(_DIAGNOSTIC_LOGBOOK_TOOL_NAMES)

    old_execute = module.execute_tool
    def execute_with_diagnostic_logbook(name, arguments, *args, **kwargs):
        tool = str(name or "")
        args_dict = dict(arguments or {}) if isinstance(arguments, dict) else {}
        if tool == "read_diagnostic_logs":
            return read_diagnostic_logs(**args_dict)
        if tool == "search_diagnostic_logs":
            return search_diagnostic_logs(**args_dict)
        if tool == "get_diagnostic_log":
            return get_diagnostic_log(**args_dict)
        if tool == "diagnostic_logbook_status":
            return diagnostic_logbook_status()
        if tool == "read_system_log":
            return read_system_log(**args_dict)
        if tool not in _DIAGNOSTIC_LOGBOOK_TOOL_NAMES:
            append_diagnostic_log("tool.call", f"Local tool call: {tool}", details={"tool": tool, "arguments": args_dict}, subsystem="tools")
        started = time.perf_counter()
        try:
            result = old_execute(name, arguments, *args, **kwargs)
        except Exception as exc:
            if tool not in _DIAGNOSTIC_LOGBOOK_TOOL_NAMES:
                append_diagnostic_log(
                    "tool.error", f"Local tool failed: {tool}", severity="error", subsystem="tools",
                    details={"tool": tool, "duration_ms": round((time.perf_counter()-started)*1000, 3), "error_type": type(exc).__name__, "error": str(exc), "traceback": traceback.format_exc()[-12000:]},
                )
            raise
        if tool not in _DIAGNOSTIC_LOGBOOK_TOOL_NAMES:
            append_diagnostic_log(
                "tool.complete", f"Local tool completed: {tool}", subsystem="tools",
                details={"tool": tool, "duration_ms": round((time.perf_counter()-started)*1000, 3), "ok": (result.get("ok") if isinstance(result, dict) else None)},
            )
        return result
    module.execute_tool = execute_with_diagnostic_logbook

    module.encrypted_diagnostic_logbook_self_test = lambda: encrypted_diagnostic_logbook_self_test(module)
    module._ENCRYPTED_DIAGNOSTIC_LOGBOOK_INSTALLED = True
    append_diagnostic_log(
        "diagnostics.logbook_started", "Encrypted rotating Diagnostic Logbook active.",
        subsystem="diagnostics", details={"max_entries": dl_max_entries(), "path": str(dl_db_path()), "plaintext_fallback": False},
    )


def _attach_diagnostic_logbook_turn_hooks(module) -> None:
    if getattr(module, "_DIAGNOSTIC_LOGBOOK_TURN_HOOKS_ATTACHED", False):
        return
    logger = getattr(module, "append_diagnostic_log", None)
    if not callable(logger):
        return

    def _receipt_projection_snapshot():
        active=dict(getattr(module,"_CONTEXT_PROJECTION_LAST_TURN",{}) or {})
        exact_reads=dict(active.get("exact_source_reads") or {})
        base=dict(active.get("coverage_base") or {})
        renderer=globals().get("_cpt_render_coverage")
        rendered=renderer(base,exact_reads) if base and callable(renderer) else {"domains":{},"lines":list(active.get("coverage_statement") or []),"high_contract":None}
        return {
            "used":bool(active.get("used")),"inspection_initialized":bool(active.get("inspection_initialized")),
            "tiers":dict(active.get("tiers") or {}),"book_ids":list(active.get("book_ids") or []),
            "query":str(active.get("query") or ""),"projection_estimate_tokens":active.get("projection_estimate_tokens"),
            "capacity":dict(active.get("capacity") or {}),"coverage_base":base,
            "coverage_domains":dict(rendered.get("domains") or {}),"coverage_statement":list(rendered.get("lines") or active.get("coverage_statement") or []),
            "high_contract":rendered.get("high_contract"),"mechanical_expansion_facts":list(active.get("mechanical_expansion_facts") or []),
            "exact_source_reads":exact_reads,"exact_open_transitions":list(active.get("exact_open_transitions") or []),
        }

    def _build_receipt(turn_id: str, status: str, query_sha256: str, duration_ms: float, error=None) -> dict:
        acc=dict(getattr(module,"_FORENSIC_TURN_ACCUMULATOR",{}) or {})
        events=list(acc.get("events") or [])
        providers={}
        calls={}; results={}; decisions=[]; capsule_completions=[]; exact_open_transitions=[]
        tool_calls_seen=0
        for ev in events:
            et=str(ev.get("event_type") or ""); d=dict(ev.get("details") or {})
            if et.startswith("provider.request_"):
                pid=str(d.get("provider_call_id") or "")
                if pid:
                    row=providers.setdefault(pid,{"provider_call_id":pid,"events":[]})
                    row["events"].append({"event_type":et,"attempt":d.get("attempt"),"response_id":d.get("response_id"),"request_envelope_id":d.get("request_envelope_id"),"request_envelope_evidence_ref":d.get("request_envelope_evidence_ref"),"duration_ms":d.get("duration_ms"),"preflight":d.get("preflight") if et=="provider.request_start" else None})
            elif et=="tool.call":
                tool_calls_seen += 1
                cid=str(d.get("call_id") or "")
                if cid and len(calls)<_FORENSIC_TURN_RECEIPT_MAX_TOOL_CALLS:
                    calls[cid]={"call_id":cid,"tool":d.get("tool"),"arguments":d.get("arguments") if isinstance(d.get("arguments"),dict) else {},"round":d.get("round"),"provider_call_id":d.get("provider_call_id"),"batch_id":d.get("batch_id"),"capsule":bool(d.get("capsule") or d.get("web_capsule"))}
            elif et=="forensics.tool_result":
                cid=str(d.get("call_id") or "")
                if cid: results[cid]=dict(d.get("result_summary") or {})
