def _dl_selftest_precise_aware_timestamp(value) -> bool:
    """Accept precise ISO-8601 timestamps in any real UTC offset, including negative offsets.

    This validates the existing Diagnostic Logbook timestamp contract without
    assuming the local timezone is UTC or east of UTC. It is self-test logic
    only; production timestamp generation remains unchanged.
    """
    text = str(value or "").strip()
    if "T" not in text:
        return False
    normalized = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        parsed = datetime.fromisoformat(normalized)
    except (TypeError, ValueError):
        return False
    # The logbook promises millisecond precision and an explicit timezone.
    time_part = text.split("T", 1)[1]
    return (
        parsed.tzinfo is not None
        and parsed.utcoffset() is not None
        and "." in time_part
    )


