def _install_learning_ledger(module) -> None:
    if getattr(module, "_LEARNING_LEDGER_INSTALLED", False):
        return

    put_object = getattr(module, "_blackbox_put_object", None)
    get_object = getattr(module, "_blackbox_get_object", None)
