# NeatMemory 7.4.29.1 — Reliable Metric Design Commit
# ---------------------------------------------------------------------------
# A general, append-only metric layer for Assistant-authored/user-authored variables
# and safe deterministic equations.  It deliberately reuses the already proven
# perception AST evaluator rather than introducing eval/exec or another code path.
_CUSTOM_METRICS_VERSION = "1.0-typed-scoped-append-only-safe-equations"
_CUSTOM_METRIC_DESIGN_MARKER = "[NEATMEMORY_CUSTOM_METRIC_DESIGN]"
_CUSTOM_METRIC_MAX_VARIABLES = 512
_CUSTOM_METRIC_MAX_EQUATIONS = 256
_CUSTOM_METRIC_MAX_CONTEXT_VARIABLES = 32
_CUSTOM_METRIC_MAX_CONTEXT_EQUATIONS = 20
_CUSTOM_METRIC_MAX_CONTEXT_CHARS = 9000
_CUSTOM_METRIC_MAX_DESCRIPTION = 1200
_CUSTOM_METRIC_MAX_REASON = 1200
_CUSTOM_METRIC_MAX_SOURCE_REFS = 24
_CUSTOM_METRIC_MAX_HISTORY = 500
_CUSTOM_METRIC_FORMULA_TYPES = {"float", "integer", "count", "percentage", "duration", "boolean"}
_CUSTOM_METRIC_TYPES = _CUSTOM_METRIC_FORMULA_TYPES | {"text", "date", "datetime", "enum"}
_CUSTOM_METRIC_VALUE_KINDS = {"user_supplied", "observed", "calculated", "inferred"}
_CUSTOM_METRIC_CONTEXT_MODES = {"always", "auto", "off"}
_CUSTOM_METRIC_SEMANTIC_ROLES = {"operational", "descriptive", "interpretive"}
_CUSTOM_METRIC_RESERVED_ROOTS = {"emotion", "somatic", "session", "memory", "context", "time", "derived"}


def _cm_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _cm_canonical(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _cm_sha(value: object) -> str:
    return hashlib.sha256(_cm_canonical(value).encode("utf-8")).hexdigest()


def _cm_clean(value: object, limit: int) -> str:
    return str(value or "").replace("\x00", "").strip()[:limit]


def _cm_source_refs(values: object) -> list[str]:
    raw = values if isinstance(values, list) else ([values] if values else [])
    output: list[str] = []
    for item in raw:
        text = _cm_clean(item, 240)
        if text and text not in output:
            output.append(text)
        if len(output) >= _CUSTOM_METRIC_MAX_SOURCE_REFS:
            break
    return output


def _cm_identifier(value: object, *, label: str = "name") -> str:
    text = str(value or "").strip().casefold()
    text = re.sub(r"[^a-z0-9_]+", "_", text).strip("_")
    if not text or not re.fullmatch(r"[a-z_][a-z0-9_]{0,63}", text):
        raise ValueError(f"Invalid custom metric {label}: {value!r}")
    if text in _PERCEPTION_SAFE_FUNCTIONS or text in {"true", "false"}:
        raise ValueError(f"Reserved custom metric {label}: {text}")
    return text


def _cm_normalize_ref(value: object) -> str:
    raw = _cm_clean(value, 240)
    if not raw:
        raise ValueError("Variable reference is required.")
    parts = raw.split(".")
    if len(parts) < 2 or len(parts) > 6:
        raise ValueError("Variable references must use 2-6 dot-separated segments, e.g. project.assistant.progress.")
    clean = [_cm_identifier(part, label="reference segment") for part in parts]
    if clean[0] in _CUSTOM_METRIC_RESERVED_ROOTS:
        raise ValueError(f"Custom variables cannot use reserved system root {clean[0]!r}.")
    return ".".join(clean)


def _cm_scope_name(ref: str) -> tuple[str, str]:
    normalized = _cm_normalize_ref(ref)
    scope, name = normalized.rsplit(".", 1)
    return scope, name


def _cm_normalize_scope(value: object) -> str:
    raw = _cm_clean(value, 200)
    if not raw:
        raise ValueError("Metric scope is required.")
    # Validate by appending a temporary legal variable name.
    probe = _cm_normalize_ref(raw + ".probe")
    return probe.rsplit(".", 1)[0]


def _cm_variable_id(ref: str) -> str:
    return "VAR-" + hashlib.sha256(_cm_normalize_ref(ref).encode("utf-8")).hexdigest()[:20].upper()


def _cm_equation_ref(scope: str, name: str) -> str:
    return f"{_cm_normalize_scope(scope)}.{_cm_identifier(name, label='equation name')}"


def _cm_equation_id(scope: str, name: str) -> str:
    ref = _cm_equation_ref(scope, name)
    return "EQ-" + hashlib.sha256(ref.encode("utf-8")).hexdigest()[:20].upper()


def _cm_parse_json(text: object, fallback: object) -> object:
    try:
        return json.loads(str(text or ""))
    except Exception:
        return fallback


def _cm_ensure_schema(module) -> None:
    with module.db_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS custom_metric_variables (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            variable_id TEXT NOT NULL,
            version INTEGER NOT NULL,
            ref TEXT NOT NULL,
            scope TEXT NOT NULL,
            name TEXT NOT NULL,
            value_type TEXT NOT NULL,
            unit TEXT,
            min_value REAL,
            max_value REAL,
            enum_json TEXT NOT NULL,
            description TEXT NOT NULL,
            value_kind TEXT NOT NULL,
            context_mode TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            provenance_json TEXT NOT NULL,
            definition_sha256 TEXT NOT NULL,
            UNIQUE(variable_id, version)
        );
        CREATE INDEX IF NOT EXISTS idx_custom_metric_variables_ref
            ON custom_metric_variables(ref, version DESC);
        CREATE INDEX IF NOT EXISTS idx_custom_metric_variables_status
            ON custom_metric_variables(status, row_id DESC);

        CREATE TABLE IF NOT EXISTS custom_metric_value_events (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT NOT NULL UNIQUE,
            variable_id TEXT NOT NULL,
            variable_ref TEXT NOT NULL,
            definition_version INTEGER NOT NULL,
            recorded_at TEXT NOT NULL,
            value_json TEXT NOT NULL,
            value_kind TEXT NOT NULL,
            confidence REAL NOT NULL,
            actor TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            reason_text TEXT,
            source_refs_json TEXT NOT NULL,
            equation_id TEXT,
            equation_version INTEGER,
            input_snapshot_json TEXT,
            input_snapshot_sha256 TEXT,
            provenance_json TEXT NOT NULL,
            event_sha256 TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_custom_metric_values_variable
            ON custom_metric_value_events(variable_id, row_id DESC);
        CREATE INDEX IF NOT EXISTS idx_custom_metric_values_recorded
            ON custom_metric_value_events(recorded_at DESC, row_id DESC);

        CREATE TABLE IF NOT EXISTS custom_metric_equations (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equation_id TEXT NOT NULL,
            version INTEGER NOT NULL,
            equation_ref TEXT NOT NULL,
            scope TEXT NOT NULL,
            name TEXT NOT NULL,
            output_variable_id TEXT NOT NULL,
            output_ref TEXT NOT NULL,
            formula TEXT NOT NULL,
            purpose TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            provenance_json TEXT NOT NULL,
            validation_json TEXT NOT NULL,
            equation_sha256 TEXT NOT NULL,
            UNIQUE(equation_id, version)
        );
        CREATE INDEX IF NOT EXISTS idx_custom_metric_equations_ref
            ON custom_metric_equations(equation_ref, version DESC);
        CREATE INDEX IF NOT EXISTS idx_custom_metric_equations_output
            ON custom_metric_equations(output_variable_id, version DESC);

        CREATE TRIGGER IF NOT EXISTS custom_metric_variables_no_update
        BEFORE UPDATE ON custom_metric_variables BEGIN
            SELECT RAISE(ABORT, 'custom metric variable history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_variables_no_delete
        BEFORE DELETE ON custom_metric_variables BEGIN
            SELECT RAISE(ABORT, 'custom metric variable history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_values_no_update
        BEFORE UPDATE ON custom_metric_value_events BEGIN
            SELECT RAISE(ABORT, 'custom metric value history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_values_no_delete
        BEFORE DELETE ON custom_metric_value_events BEGIN
            SELECT RAISE(ABORT, 'custom metric value history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_equations_no_update
        BEFORE UPDATE ON custom_metric_equations BEGIN
            SELECT RAISE(ABORT, 'custom metric equation history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_equations_no_delete
        BEFORE DELETE ON custom_metric_equations BEGIN
            SELECT RAISE(ABORT, 'custom metric equation history is append-only');
        END;
        """)


def _cm_decode_variable_row(row: object) -> dict | None:
    if not row:
        return None
    data = dict(row)
    data["enum_values"] = _cm_parse_json(data.pop("enum_json", "[]"), [])
    data["provenance"] = _cm_parse_json(data.pop("provenance_json", "{}"), {})
    return data


def _cm_decode_equation_row(row: object) -> dict | None:
    if not row:
        return None
    data = dict(row)
    data["provenance"] = _cm_parse_json(data.pop("provenance_json", "{}"), {})
    data["validation"] = _cm_parse_json(data.pop("validation_json", "{}"), {})
    data["semantic_role"] = str((data.get("provenance") or {}).get("semantic_role") or (data.get("validation") or {}).get("semantic_role") or "legacy_unspecified")
    data["authoritative_writeback"] = False
    return data


def _cm_decode_value_row(row: object) -> dict | None:
    if not row:
        return None
    data = dict(row)
    data["value"] = _cm_parse_json(data.pop("value_json", "null"), None)
    data["source_refs"] = _cm_parse_json(data.pop("source_refs_json", "[]"), [])
    data["input_snapshot"] = _cm_parse_json(data.pop("input_snapshot_json", "null"), None)
    data["provenance"] = _cm_parse_json(data.pop("provenance_json", "{}"), {})
    return data


def _cm_latest_variable_defs(module, *, include_retired: bool = False) -> list[dict]:
    _cm_ensure_schema(module)
    with module.db_connect() as db:
        rows = db.execute("""
            SELECT v.* FROM custom_metric_variables v
            JOIN (
                SELECT variable_id, MAX(version) AS max_version
                FROM custom_metric_variables GROUP BY variable_id
            ) latest ON latest.variable_id=v.variable_id AND latest.max_version=v.version
            ORDER BY v.ref
        """).fetchall()
    out = [_cm_decode_variable_row(row) for row in rows]
    return [row for row in out if row and (include_retired or row.get("status") == "active")]


def _cm_latest_equations(module, *, include_retired: bool = False) -> list[dict]:
    _cm_ensure_schema(module)
    with module.db_connect() as db:
        rows = db.execute("""
            SELECT e.* FROM custom_metric_equations e
            JOIN (
                SELECT equation_id, MAX(version) AS max_version
                FROM custom_metric_equations GROUP BY equation_id
            ) latest ON latest.equation_id=e.equation_id AND latest.max_version=e.version
            ORDER BY e.equation_ref
        """).fetchall()
    out = [_cm_decode_equation_row(row) for row in rows]
    return [row for row in out if row and (include_retired or row.get("status") == "active")]


def _cm_latest_value_events(module) -> dict[str, dict]:
    _cm_ensure_schema(module)
    with module.db_connect() as db:
        rows = db.execute("""
            SELECT e.* FROM custom_metric_value_events e
            JOIN (
                SELECT variable_id, MAX(row_id) AS max_row
                FROM custom_metric_value_events GROUP BY variable_id
            ) latest ON latest.variable_id=e.variable_id AND latest.max_row=e.row_id
        """).fetchall()
    output: dict[str, dict] = {}
    for row in rows:
        decoded = _cm_decode_value_row(row)
        if decoded:
            output[str(decoded["variable_id"])] = decoded
    return output


def _cm_get_variable(module, reference: str, *, include_retired: bool = True) -> dict | None:
    ref = str(reference or "").strip()
    rows = _cm_latest_variable_defs(module, include_retired=include_retired)
    folded = ref.casefold()
    for row in rows:
        if str(row.get("variable_id", "")).casefold() == folded or str(row.get("ref", "")).casefold() == folded:
            return row
    try:
        normalized = _cm_normalize_ref(ref)
    except Exception:
        return None
    return next((row for row in rows if row.get("ref") == normalized), None)


def _cm_get_equation(module, reference: str, *, include_retired: bool = True) -> dict | None:
    ref = str(reference or "").strip().casefold()
    rows = _cm_latest_equations(module, include_retired=include_retired)
    exact = [row for row in rows if str(row.get("equation_id", "")).casefold() == ref or str(row.get("equation_ref", "")).casefold() == ref or str(row.get("output_ref", "")).casefold() == ref]
    if exact:
        return exact[0] if len(exact) == 1 else None
    names = [row for row in rows if str(row.get("name", "")).casefold() == ref]
    return names[0] if len(names) == 1 else None


def _cm_normalize_type(value: object) -> str:
    aliases = {"int": "integer", "bool": "boolean", "percent": "percentage", "%": "percentage", "str": "text"}
    text = aliases.get(str(value or "float").strip().casefold(), str(value or "float").strip().casefold())
    if text not in _CUSTOM_METRIC_TYPES:
        raise ValueError(f"Unsupported variable type: {text}. Allowed: {', '.join(sorted(_CUSTOM_METRIC_TYPES))}")
    return text


def _cm_validate_value(definition: dict, raw_value: object) -> object:
    kind = str(definition.get("value_type") or "float")
    min_value = definition.get("min_value")
    max_value = definition.get("max_value")
    if kind == "boolean":
        if isinstance(raw_value, bool):
            value = raw_value
        elif isinstance(raw_value, (int, float)) and raw_value in {0, 1}:
            value = bool(raw_value)
        else:
            text = str(raw_value or "").strip().casefold()
            if text in {"true", "yes", "on", "1"}: value = True
            elif text in {"false", "no", "off", "0"}: value = False
            else: raise ValueError(f"Expected boolean for {definition.get('ref')}.")
        return value
    if kind in {"float", "integer", "count", "percentage", "duration"}:
        try:
            number = float(raw_value)
        except Exception as exc:
            raise ValueError(f"Expected numeric value for {definition.get('ref')}.") from exc
        if not math.isfinite(number):
            raise ValueError("Metric values must be finite.")
        if kind in {"integer", "count"}:
            if abs(number - round(number)) > 1e-9:
                raise ValueError(f"Expected an integer value for {definition.get('ref')}.")
            value: object = int(round(number))
        else:
            value = float(number)
        if kind == "count" and float(value) < 0:
            raise ValueError("Count values cannot be negative.")
        if kind == "percentage" and min_value is None and max_value is None and not (0 <= float(value) <= 100):
            raise ValueError("Percentage values default to the 0..100 range.")
        if kind == "duration" and min_value is None and float(value) < 0:
            raise ValueError("Duration values cannot be negative.")
        if min_value is not None and float(value) < float(min_value):
            raise ValueError(f"Value is below minimum {min_value}.")
        if max_value is not None and float(value) > float(max_value):
            raise ValueError(f"Value is above maximum {max_value}.")
        return value
    if kind == "date":
        text = str(raw_value or "").strip()
        try:
            return datetime.strptime(text, "%Y-%m-%d").date().isoformat()
        except Exception as exc:
            raise ValueError("Date variables require YYYY-MM-DD.") from exc
    if kind == "datetime":
        text = str(raw_value or "").strip()
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except Exception as exc:
            raise ValueError("Datetime variables require ISO-8601 text.") from exc
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc).replace(microsecond=0).isoformat()
    if kind == "enum":
        text = _cm_clean(raw_value, 500)
        allowed = [str(x) for x in definition.get("enum_values") or []]
        if text not in allowed:
            raise ValueError(f"Enum value must be one of: {', '.join(allowed[:20])}")
        return text
    if kind == "text":
        return _cm_clean(raw_value, 4000)
    raise ValueError(f"Unsupported metric type: {kind}")


def _cm_define_variable(module, *, ref: str, value_type: str = "float", unit: str | None = None,
                        min_value: float | None = None, max_value: float | None = None,
                        enum_values: list | None = None, description: str = "",
                        value_kind: str = "user_supplied", context_mode: str = "auto",
                        actor: str = "user", provider: str = "console", model: str = "runtime",
                        reason: str = "variable_definition", source_refs: object = None,
                        status: str = "active") -> dict:
    _cm_ensure_schema(module)
    normalized = _cm_normalize_ref(ref)
    scope, name = _cm_scope_name(normalized)
    value_type = _cm_normalize_type(value_type)
    value_kind = str(value_kind or "user_supplied").strip().casefold()
    if value_kind not in _CUSTOM_METRIC_VALUE_KINDS:
        raise ValueError(f"Unsupported value_kind: {value_kind}")
    context_mode = str(context_mode or "auto").strip().casefold()
    if context_mode not in _CUSTOM_METRIC_CONTEXT_MODES:
        raise ValueError("context_mode must be always, auto, or off.")
    status = str(status or "active").strip().casefold()
    if status not in {"active", "retired"}:
        raise ValueError("Variable status must be active or retired.")
    enum_clean = []
    if value_type == "enum":
        for item in enum_values or []:
            text = _cm_clean(item, 500)
            if text and text not in enum_clean:
                enum_clean.append(text)
        if not enum_clean:
            raise ValueError("Enum variables require enum_values.")
        if len(enum_clean) > 64:
            raise ValueError("Enum variables support at most 64 values.")
    elif enum_values:
        raise ValueError("enum_values are only valid for enum variables.")
    if min_value is not None: min_value = float(min_value)
    if max_value is not None: max_value = float(max_value)
    if min_value is not None and max_value is not None and min_value > max_value:
        raise ValueError("Variable minimum exceeds maximum.")
    if value_type == "percentage" and min_value is None and max_value is None:
        min_value, max_value = 0.0, 100.0
    if value_type in {"count", "duration"} and min_value is None:
        min_value = 0.0
    if value_type == "percentage" and not unit:
        unit = "%"
    if value_type == "count" and not unit:
        unit = "count"
    unit = _cm_clean(unit, 48) or None
    description = _cm_clean(description, _CUSTOM_METRIC_MAX_DESCRIPTION) or f"Custom variable {normalized}."
    variable_id = _cm_variable_id(normalized)
    source_list = _cm_source_refs(source_refs)
    provenance = {
        "actor": _cm_clean(actor, 120) or "unknown",
        "provider": _cm_clean(provider, 120) or "unknown",
        "model": _cm_clean(model, 200) or "unknown",
        "reason": _cm_clean(reason, _CUSTOM_METRIC_MAX_REASON) or "variable_definition",
        "source_refs": source_list,
        "publisher_credibility_inferred": False,
    }
    definition = {
        "ref": normalized, "scope": scope, "name": name, "value_type": value_type,
        "unit": unit, "min_value": min_value, "max_value": max_value,
        "enum_values": enum_clean, "description": description, "value_kind": value_kind,
        "context_mode": context_mode, "status": status,
    }
    digest = _cm_sha(definition)
    with module.db_connect() as db:
        previous = db.execute("SELECT * FROM custom_metric_variables WHERE variable_id=? ORDER BY version DESC LIMIT 1", (variable_id,)).fetchone()
        if previous:
            decoded = _cm_decode_variable_row(previous)
            previous_digest = str(decoded.get("definition_sha256") or "")
            if previous_digest == digest:
                return {"ok": True, "created": False, "idempotent": True, "variable": decoded}
            version = int(decoded.get("version") or 0) + 1
        else:
            count = int(db.execute("SELECT COUNT(DISTINCT variable_id) FROM custom_metric_variables").fetchone()[0])
            if count >= _CUSTOM_METRIC_MAX_VARIABLES:
                raise ValueError("Custom metric variable limit reached.")
            version = 1
        created_at = _cm_now()
        db.execute("""
            INSERT INTO custom_metric_variables(
                variable_id,version,ref,scope,name,value_type,unit,min_value,max_value,enum_json,
                description,value_kind,context_mode,status,created_at,created_by,provider,model,
                provenance_json,definition_sha256
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (variable_id, version, normalized, scope, name, value_type, unit, min_value, max_value,
              _cm_canonical(enum_clean), description, value_kind, context_mode, status, created_at,
              _cm_clean(actor,120) or "unknown", _cm_clean(provider,120), _cm_clean(model,200),
              _cm_canonical(provenance), digest))
        row = db.execute("SELECT * FROM custom_metric_variables WHERE variable_id=? AND version=?", (variable_id, version)).fetchone()
    return {"ok": True, "created": True, "variable": _cm_decode_variable_row(row)}


def _cm_append_value_event(module, definition: dict, value: object, *, value_kind: str,
                           confidence: float, actor: str, provider: str, model: str,
                           reason: str, source_refs: object = None,
                           equation_id: str | None = None, equation_version: int | None = None,
                           input_snapshot: object = None) -> dict:
    validated = _cm_validate_value(definition, value)
    confidence = max(0.0, min(1.0, float(confidence)))
    source_list = _cm_source_refs(source_refs)
    recorded_at = _cm_now()
    input_sha = _cm_sha(input_snapshot) if input_snapshot is not None else None
    provenance = {
        "actor": _cm_clean(actor,120) or "unknown", "provider": _cm_clean(provider,120) or "unknown",
        "model": _cm_clean(model,200) or "unknown", "reason": _cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),
        "source_refs": source_list, "equation_id": equation_id, "equation_version": equation_version,
        "deterministic_calculation": bool(equation_id), "publisher_credibility_inferred": False,
    }
    body = {
        "variable_id": definition["variable_id"], "definition_version": int(definition["version"]),
        "recorded_at": recorded_at, "value": validated, "value_kind": value_kind,
        "confidence": round(confidence,6), "actor": actor, "provider": provider, "model": model,
        "reason": _cm_clean(reason,_CUSTOM_METRIC_MAX_REASON), "source_refs": source_list,
        "equation_id": equation_id, "equation_version": equation_version, "input_snapshot_sha256": input_sha,
    }
    event_sha = _cm_sha(body)
    event_id = "MVE-" + hashlib.sha256((event_sha + uuid.uuid4().hex).encode("utf-8")).hexdigest()[:20].upper()
    with module.db_connect() as db:
        db.execute("""
            INSERT INTO custom_metric_value_events(
                event_id,variable_id,variable_ref,definition_version,recorded_at,value_json,value_kind,
                confidence,actor,provider,model,reason_text,source_refs_json,equation_id,equation_version,
                input_snapshot_json,input_snapshot_sha256,provenance_json,event_sha256
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (event_id, definition["variable_id"], definition["ref"], int(definition["version"]), recorded_at,
              _cm_canonical(validated), value_kind, confidence, _cm_clean(actor,120) or "unknown",
              _cm_clean(provider,120), _cm_clean(model,200), _cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),
              _cm_canonical(source_list), equation_id, equation_version,
              _cm_canonical(input_snapshot) if input_snapshot is not None else None, input_sha,
              _cm_canonical(provenance), event_sha))
        row = db.execute("SELECT * FROM custom_metric_value_events WHERE event_id=?", (event_id,)).fetchone()
    return _cm_decode_value_row(row)


def _cm_system_inputs(module) -> dict[str, dict]:
    output: dict[str, dict] = {}
    collector = globals().get("_perception_collect_metrics")
    if not callable(collector):
        return output
    try:
        metrics, _sources = collector(module, query="")
    except Exception:
        return output
    for ref, item in (metrics or {}).items():
        value = item.get("value") if isinstance(item, dict) else None
        if isinstance(value, bool) or (isinstance(value, (int, float)) and math.isfinite(float(value))):
            output[str(ref)] = {
                "ref": str(ref), "value": value, "value_type": "boolean" if isinstance(value,bool) else "float",
                "unit": item.get("unit"), "description": item.get("description"), "category": item.get("category"),
                "source_id": item.get("source_id"), "confidence": float(item.get("confidence", 1.0) or 1.0),
                "origin": "python_system_metric",
            }
    return output


def _cm_current_custom_inputs(module) -> tuple[dict[str, dict], dict[str, dict], dict[str, dict]]:
    definitions = {row["ref"]: row for row in _cm_latest_variable_defs(module)}
    events_by_id = _cm_latest_value_events(module)
    entries: dict[str, dict] = {}
    for ref, definition in definitions.items():
        event = events_by_id.get(definition["variable_id"])
        if not event:
            continue
        try:
            value = _cm_validate_value(definition, event.get("value"))
        except Exception:
            continue
        entries[ref] = {
            "ref": ref, "value": value, "value_type": definition.get("value_type"), "unit": definition.get("unit"),
            "description": definition.get("description"), "source_id": event.get("event_id"),
            "confidence": float(event.get("confidence",1.0) or 1.0), "origin": "custom_variable",
            "variable_id": definition["variable_id"], "event_id": event["event_id"],
            "definition_version": definition["version"], "source_refs": list(event.get("source_refs") or []),
            "recorded_at": event.get("recorded_at"), "value_kind": event.get("value_kind"),
        }
    return definitions, entries, events_by_id


def _cm_input_catalog(module, *, include_values: bool = True, query: str = "", include_system: bool = True) -> dict:
    definitions, custom, _events = _cm_current_custom_inputs(module)
    system = _cm_system_inputs(module) if include_system else {}
    rows = []
    for ref, definition in sorted(definitions.items()):
        current = custom.get(ref)
        row = {
            "ref": ref, "origin": "custom_variable", "value_type": definition.get("value_type"),
            "unit": definition.get("unit"), "description": definition.get("description"),
            "value_kind": definition.get("value_kind"), "context_mode": definition.get("context_mode"),
        }
        if include_values and current: row["value"] = current.get("value")
        rows.append(row)
    for ref, item in sorted(system.items()):
        row = {k:item.get(k) for k in ("ref","origin","value_type","unit","description","category","source_id")}
        if include_values: row["value"] = item.get("value")
        rows.append(row)
    needle = str(query or "").strip().casefold()
    if needle:
        rows = [row for row in rows if needle in str(row.get("ref","")).casefold() or needle in str(row.get("description","")).casefold()]
    return {"ok": True, "version": _CUSTOM_METRICS_VERSION, "count": len(rows), "inputs": rows[:240], "truncated": len(rows) > 240}


def _cm_formula_parse(expression: str, allowed_refs: set[str], *, local_scope: str) -> dict:
    expression = _cm_clean(expression, _PERCEPTION_MAX_FORMULA_CHARS)
    if not expression:
        raise ValueError("Equation formula cannot be empty.")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"Invalid equation syntax: {exc.msg}") from exc
    nodes = list(ast.walk(tree))
    if len(nodes) > _PERCEPTION_MAX_AST_NODES:
        raise ValueError("Equation is too complex.")
    if _perception_ast_depth(tree) > _PERCEPTION_MAX_AST_DEPTH:
        raise ValueError("Equation nesting is too deep.")
    allowed_roots = {ref.split(".",1)[0] for ref in allowed_refs if "." in ref}
    local_aliases = {ref.rsplit(".",1)[1]: ref for ref in allowed_refs if ref.startswith(local_scope + ".") and ref.count(".") == local_scope.count(".") + 1}
    used_refs: set[str] = set()
    used_aliases: dict[str,str] = {}
    for node in nodes:
        if isinstance(node, ast.Expression | ast.Load | ast.operator | ast.unaryop | ast.boolop | ast.cmpop):
            continue
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool): continue
            if not isinstance(node.value, (int,float)) or not math.isfinite(float(node.value)):
                raise ValueError("Only finite numeric and boolean constants are allowed in equations.")
            continue
        if isinstance(node, ast.BinOp):
            if not isinstance(node.op, _PERCEPTION_ALLOWED_BINOPS): raise ValueError("Unsupported equation binary operator.")
            continue
        if isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, _PERCEPTION_ALLOWED_UNARYOPS): raise ValueError("Unsupported equation unary operator.")
            continue
        if isinstance(node, ast.BoolOp):
            if not isinstance(node.op, (ast.And,ast.Or)): raise ValueError("Unsupported equation boolean operator.")
            continue
        if isinstance(node, ast.Compare):
            if not all(isinstance(op, _PERCEPTION_ALLOWED_CMPOPS) for op in node.ops): raise ValueError("Unsupported equation comparison operator.")
            continue
        if isinstance(node, ast.IfExp): continue
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in _PERCEPTION_SAFE_FUNCTIONS:
                raise ValueError("Only approved mathematical functions are allowed in equations.")
            if node.keywords: raise ValueError("Keyword arguments are not allowed in equations.")
            continue
        if isinstance(node, ast.Attribute):
            path = _perception_attribute_path(node)
            if path in allowed_refs:
                used_refs.add(path); continue
            if path and any(ref.startswith(path + ".") for ref in allowed_refs):
                continue
            raise ValueError(f"Unknown variable reference in equation: {path}")
        if isinstance(node, ast.Name):
            if node.id in _PERCEPTION_SAFE_FUNCTIONS or node.id in {"True","False"}: continue
            if node.id in local_aliases:
                used_refs.add(local_aliases[node.id]); used_aliases[node.id]=local_aliases[node.id]; continue
            if node.id in allowed_roots: continue
            raise ValueError(f"Unknown variable name in equation: {node.id}")
        raise ValueError(f"Unsupported equation element: {type(node).__name__}")
    return {"tree": tree, "input_refs": sorted(used_refs), "local_aliases": used_aliases, "ast_nodes": len(nodes)}


def _cm_formula_eval(parsed: dict, values: dict[str, object]) -> object:
    aliases = {alias: values[ref] for alias, ref in (parsed.get("local_aliases") or {}).items() if ref in values}
    return _perception_eval_ast(parsed["tree"], values, aliases)


def _cm_graph_order(equations: list[dict]) -> tuple[list[str], dict[str,str]]:
    output_to_equation: dict[str,str] = {}
    equation_map = {row["equation_id"]: row for row in equations}
    for row in equations:
        output = str(row.get("output_ref") or "")
        if output in output_to_equation and output_to_equation[output] != row["equation_id"]:
            raise ValueError(f"More than one active equation targets {output}.")
        output_to_equation[output] = row["equation_id"]
    dependencies: dict[str,set[str]] = {}
    for row in equations:
        refs = set((row.get("validation") or {}).get("input_refs") or [])
        dependencies[row["equation_id"]] = {output_to_equation[ref] for ref in refs if ref in output_to_equation}
    remaining = {key:set(value) for key,value in dependencies.items()}
    ordered: list[str] = []
    while remaining:
        ready = sorted(key for key,deps in remaining.items() if not deps)
        if not ready:
            refs = [equation_map[key].get("equation_ref") for key in sorted(remaining)]
            raise ValueError("Equation dependency cycle: " + ", ".join(str(x) for x in refs))
        for key in ready:
            ordered.append(key); remaining.pop(key)
        for deps in remaining.values(): deps.difference_update(ready)
    return ordered, output_to_equation


def _cm_define_equation(module, *, name: str, output_ref: str, formula: str, purpose: str,
                        scope: str | None = None, output_type: str = "float", output_unit: str | None = None,
                        output_min: float | None = None, output_max: float | None = None,
                        context_mode: str = "auto", semantic_role: str = "interpretive",
                        actor: str = "Assistant", provider: str = "runtime",
                        model: str = "runtime", reason: str = "equation_definition", source_refs: object = None,
                        include_system: bool = True) -> dict:
    _cm_ensure_schema(module)
    normalized_output = _cm_normalize_ref(output_ref)
    output_scope, _output_name = _cm_scope_name(normalized_output)
    scope = _cm_normalize_scope(scope or output_scope)
    name = _cm_identifier(name, label="equation name")
    equation_ref = _cm_equation_ref(scope,name)
    equation_id = _cm_equation_id(scope,name)
    output_def = _cm_get_variable(module, normalized_output, include_retired=True)
    created_output = None
    output_missing = output_def is None
    if output_missing:
        virtual_type = _cm_normalize_type(output_type)
        if virtual_type not in _CUSTOM_METRIC_FORMULA_TYPES:
            raise ValueError("Equation outputs must use numeric or boolean variable types.")
        output_def = {
            "variable_id": _cm_variable_id(normalized_output), "version": 1, "ref": normalized_output,
            "scope": output_scope, "name": normalized_output.rsplit(".",1)[1], "value_type": virtual_type,
            "unit": output_unit, "min_value": output_min, "max_value": output_max, "enum_values": [],
            "description": f"Calculated output of {equation_ref}.", "value_kind": "calculated",
            "context_mode": context_mode, "status": "active",
        }
    elif output_def.get("status") != "active":
        raise ValueError(f"Equation output variable is retired: {normalized_output}")
    if output_def.get("value_type") not in _CUSTOM_METRIC_FORMULA_TYPES:
        raise ValueError("Equation outputs must use numeric or boolean variable types.")
    if output_def.get("value_kind") != "calculated":
        raise ValueError("Equation output variables must have value_kind=calculated.")

    custom_defs = {row["ref"]:row for row in _cm_latest_variable_defs(module)}
    if output_missing:
        custom_defs[normalized_output] = output_def
    system_inputs = _cm_system_inputs(module) if include_system else {}
    allowed_refs = set(custom_defs) | set(system_inputs)
    parsed = _cm_formula_parse(formula, allowed_refs, local_scope=scope)
    if not parsed["input_refs"]:
        raise ValueError("An equation must reference at least one variable or system metric.")
    for ref in parsed["input_refs"]:
        if ref in custom_defs and custom_defs[ref].get("value_type") not in _CUSTOM_METRIC_FORMULA_TYPES:
            raise ValueError(f"Equation input {ref} is not numeric/boolean.")
    purpose = _cm_clean(purpose, _CUSTOM_METRIC_MAX_DESCRIPTION)
    if not purpose:
        raise ValueError("Equation purpose is required so the metric remains interpretable.")
    semantic_role = str(semantic_role or "interpretive").strip().casefold()
    if semantic_role not in _CUSTOM_METRIC_SEMANTIC_ROLES:
        raise ValueError("semantic_role must be operational, descriptive, or interpretive.")
    formula = _cm_clean(formula, _PERCEPTION_MAX_FORMULA_CHARS)
    source_list = _cm_source_refs(source_refs)
    # If every input already has a current value, validate a real preview before
    # persisting anything. Equations with not-yet-populated inputs remain valid
    # structurally and will calculate once those inputs arrive.
    _defs_now, _custom_now, _events_now = _cm_current_custom_inputs(module)
    _preview_values = {ref:item.get("value") for ref,item in _custom_now.items()}
    _preview_values.update({ref:item.get("value") for ref,item in system_inputs.items()})
    preview_status = "missing_inputs"
    preview_value = None
    if all(ref in _preview_values for ref in parsed["input_refs"]):
        preview_value = _cm_validate_value(output_def, _cm_formula_eval(parsed, _preview_values))
        preview_status = "validated"
    validation = {
        "ok": True, "validated_at": _cm_now(), "input_refs": parsed["input_refs"],
        "local_aliases": parsed["local_aliases"], "ast_nodes": parsed["ast_nodes"],
        "output_ref": normalized_output, "preview_status": preview_status, "preview_value": preview_value,
        "safe_functions": sorted(_PERCEPTION_SAFE_FUNCTIONS),
        "arbitrary_code_execution": False, "semantic_role": semantic_role,
        "authoritative_writeback": False,
    }
    active_equations = _cm_latest_equations(module)
    candidate = {
        "equation_id": equation_id, "equation_ref": equation_ref, "scope": scope, "name": name,
        "output_variable_id": output_def["variable_id"], "output_ref": normalized_output,
        "formula": formula, "purpose": purpose, "status": "active", "validation": validation,
    }
    graph_rows = [row for row in active_equations if row["equation_id"] != equation_id] + [candidate]
    _cm_graph_order(graph_rows)
    # Persist an automatically-created calculated output only after formula and
    # whole-graph validation succeed, so rejected equations do not leave debris.
    if output_missing:
        created_output = _cm_define_variable(
            module, ref=normalized_output, value_type=output_def["value_type"], unit=output_unit,
            min_value=output_min, max_value=output_max, description=f"Calculated output of {equation_ref}.",
            value_kind="calculated", context_mode=context_mode, actor=actor, provider=provider, model=model,
            reason="equation_output_variable", source_refs=source_refs,
        )
        output_def = created_output["variable"]
    provenance = {
        "actor": _cm_clean(actor,120) or "unknown", "provider": _cm_clean(provider,120) or "unknown",
        "model": _cm_clean(model,200) or "unknown", "reason": _cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),
        "source_refs": source_list, "python_validated": True, "arbitrary_code_execution": False,
        "publisher_credibility_inferred": False, "semantic_role": semantic_role,
        "authoritative_writeback": False,
    }
    content = {
        "equation_ref":equation_ref,"output_ref":normalized_output,"formula":formula,"purpose":purpose,"status":"active",
        "input_refs":validation["input_refs"],"local_aliases":validation["local_aliases"],"ast_nodes":validation["ast_nodes"],
        "arbitrary_code_execution":False,"semantic_role":semantic_role,"authoritative_writeback":False,
    }
    digest = _cm_sha(content)
    with module.db_connect() as db:
        previous = db.execute("SELECT * FROM custom_metric_equations WHERE equation_id=? ORDER BY version DESC LIMIT 1", (equation_id,)).fetchone()
        if previous:
            previous_decoded = _cm_decode_equation_row(previous)
            if str(previous_decoded.get("equation_sha256") or "") == digest:
                return {"ok":True,"created":False,"idempotent":True,"equation":previous_decoded,"output_variable_created":bool(created_output)}
            version = int(previous_decoded.get("version") or 0) + 1
        else:
            count = int(db.execute("SELECT COUNT(DISTINCT equation_id) FROM custom_metric_equations").fetchone()[0])
            if count >= _CUSTOM_METRIC_MAX_EQUATIONS:
                raise ValueError("Custom metric equation limit reached.")
            version = 1
        db.execute("""
            INSERT INTO custom_metric_equations(
                equation_id,version,equation_ref,scope,name,output_variable_id,output_ref,formula,purpose,status,
                created_at,created_by,provider,model,provenance_json,validation_json,equation_sha256
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (equation_id,version,equation_ref,scope,name,output_def["variable_id"],normalized_output,formula,purpose,"active",
              _cm_now(),_cm_clean(actor,120) or "unknown",_cm_clean(provider,120),_cm_clean(model,200),
              _cm_canonical(provenance),_cm_canonical(validation),digest))
        row = db.execute("SELECT * FROM custom_metric_equations WHERE equation_id=? AND version=?", (equation_id,version)).fetchone()
    equation = _cm_decode_equation_row(row)
    recalculation = _cm_recalculate(module, include_system=include_system)
    return {"ok":True,"created":True,"equation":equation,"output_variable_created":bool(created_output),"recalculation":recalculation}


def _cm_version_equation_semantic_role(module, reference: str, semantic_role: str, *, actor: str="Assistant", provider: str="runtime", model: str="runtime", reason: str="semantic_role_only_version") -> dict:
    current = _cm_get_equation(module, reference, include_retired=False)
    if not current:
        raise KeyError(f"Unknown active equation/output: {reference}")
    role = str(semantic_role or "").strip().casefold()
    if role not in _CUSTOM_METRIC_SEMANTIC_ROLES:
        raise ValueError("semantic_role must be operational, descriptive, or interpretive.")
    current_role = str(current.get("semantic_role") or (current.get("validation") or {}).get("semantic_role") or "legacy_unspecified")
    if current_role == role:
        return {"ok":True,"created":False,"idempotent":True,"equation":current,"semantic_role":role,"role_only":True}
    output = _cm_get_variable(module, current.get("output_ref"), include_retired=False)
    if not output:
        raise KeyError(f"Equation output variable is unavailable: {current.get('output_ref')}")
    result = _cm_define_equation(
        module, name=current.get("name"), output_ref=current.get("output_ref"), formula=current.get("formula"),
        purpose=current.get("purpose"), scope=current.get("scope"), output_type=output.get("value_type") or "float",
        output_unit=output.get("unit"), output_min=output.get("min_value"), output_max=output.get("max_value"),
        context_mode=output.get("context_mode") or "auto", semantic_role=role, actor=actor, provider=provider, model=model,
        reason=reason, source_refs=(current.get("provenance") or {}).get("source_refs") or [], include_system=True,
    )
    updated = dict(result.get("equation") or {})
    invariant_fields = ("equation_id","equation_ref","scope","name","output_ref","formula","purpose")
    changed = [field for field in invariant_fields if current.get(field) != updated.get(field)]
    if changed:
        raise RuntimeError("Semantic-role-only version changed protected equation fields: " + ", ".join(changed))
    result.update({"role_only":True,"previous_semantic_role":current_role,"semantic_role":role,"protected_fields_unchanged":True})
    return result


def _cm_retire_equation(module, reference: str, *, actor: str, provider: str, model: str, reason: str) -> dict:
    current = _cm_get_equation(module, reference, include_retired=True)
    if not current:
        raise KeyError(f"Unknown equation: {reference}")
    if current.get("status") == "retired": return {"ok":True,"changed":False,"equation":current}
    content = {"equation_ref":current["equation_ref"],"output_ref":current["output_ref"],"formula":current["formula"],"purpose":current["purpose"],"status":"retired","validation":current["validation"]}
    version = int(current["version"]) + 1
    provenance = dict(current.get("provenance") or {})
    provenance.update({"actor":actor,"provider":provider,"model":model,"reason":_cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),"retired":True})
    with module.db_connect() as db:
        db.execute("""INSERT INTO custom_metric_equations(
            equation_id,version,equation_ref,scope,name,output_variable_id,output_ref,formula,purpose,status,
            created_at,created_by,provider,model,provenance_json,validation_json,equation_sha256
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (current["equation_id"],version,current["equation_ref"],current["scope"],current["name"],current["output_variable_id"],current["output_ref"],current["formula"],current["purpose"],"retired",
         _cm_now(),_cm_clean(actor,120),_cm_clean(provider,120),_cm_clean(model,200),_cm_canonical(provenance),_cm_canonical(current["validation"]),_cm_sha(content)))
        row=db.execute("SELECT * FROM custom_metric_equations WHERE equation_id=? AND version=?",(current["equation_id"],version)).fetchone()
    return {"ok":True,"changed":True,"equation":_cm_decode_equation_row(row)}


def _cm_retire_variable(module, reference: str, *, actor: str, provider: str, model: str, reason: str) -> dict:
    current = _cm_get_variable(module, reference, include_retired=True)
    if not current: raise KeyError(f"Unknown variable: {reference}")
    if current.get("status") == "retired": return {"ok":True,"changed":False,"variable":current}
    active_equations = _cm_latest_equations(module)
    blockers=[]
    for eq in active_equations:
        refs=set((eq.get("validation") or {}).get("input_refs") or []) | {eq.get("output_ref")}
        if current["ref"] in refs: blockers.append(eq["equation_ref"])
    if blockers:
        raise ValueError("Retire dependent equations first: " + ", ".join(blockers[:12]))
    return _cm_define_variable(module, ref=current["ref"], value_type=current["value_type"], unit=current.get("unit"),
        min_value=current.get("min_value"), max_value=current.get("max_value"), enum_values=current.get("enum_values"),
        description=current.get("description"), value_kind=current.get("value_kind"), context_mode=current.get("context_mode"),
        actor=actor,provider=provider,model=model,reason=reason,source_refs=(current.get("provenance") or {}).get("source_refs"),status="retired")


def _cm_recalculate(module, *, changed_refs: set[str] | None = None, include_system: bool = True) -> dict:
    _cm_ensure_schema(module)
    definitions, custom_inputs, events_by_id = _cm_current_custom_inputs(module)
    system_inputs = _cm_system_inputs(module) if include_system else {}
    equations = _cm_latest_equations(module)
    if not equations:
        return {"ok":True,"version":_CUSTOM_METRICS_VERSION,"equations":0,"calculated":0,"unchanged":0,"errors":[],"changed_refs":sorted(changed_refs or [])}
    order, _output_map = _cm_graph_order(equations)
    equation_map={row["equation_id"]:row for row in equations}
    values={ref:item["value"] for ref,item in custom_inputs.items()}
    values.update({ref:item["value"] for ref,item in system_inputs.items()})
    current_by_ref={ref:events_by_id.get(defn["variable_id"]) for ref,defn in definitions.items()}
    calculated=0; unchanged=0; errors=[]; outputs=[]
    for equation_id in order:
        eq=equation_map[equation_id]
        try:
            allowed_refs=set(definitions) | set(system_inputs)
            parsed=_cm_formula_parse(eq["formula"],allowed_refs,local_scope=eq["scope"])
            missing=[ref for ref in parsed["input_refs"] if ref not in values]
            if missing: raise ValueError("Missing current input value(s): " + ", ".join(missing[:12]))
            raw_result=_cm_formula_eval(parsed,values)
            output_def=definitions.get(eq["output_ref"])
            if not output_def or output_def.get("status")!="active": raise ValueError(f"Output variable unavailable: {eq['output_ref']}")
            result=_cm_validate_value(output_def,raw_result)
            snapshot=[]; source_refs=[]; confidences=[]
            for ref in parsed["input_refs"]:
                if ref in custom_inputs:
                    item=custom_inputs[ref]; event=current_by_ref.get(ref)
                    snapshot.append({"ref":ref,"origin":"custom_variable","value":values[ref],"event_id":item.get("event_id"),"recorded_at":item.get("recorded_at")})
                    source_refs.extend(item.get("source_refs") or [])
                    confidences.append(float(item.get("confidence",1.0) or 1.0))
                else:
                    item=system_inputs[ref]
                    snapshot.append({"ref":ref,"origin":"python_system_metric","value":values[ref],"source_id":item.get("source_id")})
                    if item.get("source_id"): source_refs.append(str(item.get("source_id")))
                    confidences.append(float(item.get("confidence",1.0) or 1.0))
            snapshot={"equation_id":eq["equation_id"],"equation_version":eq["version"],"formula":eq["formula"],"inputs":snapshot}
            input_sha=_cm_sha(snapshot)
            latest=current_by_ref.get(eq["output_ref"])
            same=bool(latest and latest.get("equation_id")==eq["equation_id"] and int(latest.get("equation_version") or 0)==int(eq["version"]) and latest.get("input_snapshot_sha256")==input_sha and latest.get("value")==result)
            if same:
                event=latest; unchanged+=1
            else:
                event=_cm_append_value_event(module,output_def,result,value_kind="calculated",confidence=min(confidences or [1.0]),actor="Python",provider="python",model=BUNDLE_VERSION,
                    reason=f"equation:{eq['equation_ref']}",source_refs=source_refs,equation_id=eq["equation_id"],equation_version=int(eq["version"]),input_snapshot=snapshot)
                calculated+=1
            values[eq["output_ref"]]=result
            current_by_ref[eq["output_ref"]]=event
            custom_inputs[eq["output_ref"]]={"ref":eq["output_ref"],"value":result,"confidence":float(event.get("confidence",1.0) or 1.0),"event_id":event.get("event_id"),"recorded_at":event.get("recorded_at"),"source_refs":event.get("source_refs") or [],"origin":"custom_variable"}
            outputs.append({"equation_ref":eq["equation_ref"],"output_ref":eq["output_ref"],"value":result,"event_id":event.get("event_id"),"new_event":not same})
        except Exception as exc:
            errors.append({"equation_id":eq.get("equation_id"),"equation_ref":eq.get("equation_ref"),"output_ref":eq.get("output_ref"),"error":f"{type(exc).__name__}: {exc}"})
    return {"ok":not errors,"version":_CUSTOM_METRICS_VERSION,"equations":len(equations),"calculated":calculated,"unchanged":unchanged,"errors":errors,"outputs":outputs,"changed_refs":sorted(changed_refs or [])}


def _cm_set_value(module, reference: str, value: object, *, confidence: float = 1.0,
                  actor: str = "user", provider: str = "console", model: str = "runtime",
                  reason: str = "value_update", source_refs: object = None,
                  value_kind: str | None = None, recalculate: bool = True, include_system: bool = True) -> dict:
    definition=_cm_get_variable(module,reference,include_retired=False)
    if not definition: raise KeyError(f"Unknown active custom variable: {reference}")
    kind=str(value_kind or definition.get("value_kind") or "user_supplied").strip().casefold()
    if kind not in _CUSTOM_METRIC_VALUE_KINDS: raise ValueError(f"Unsupported value_kind: {kind}")
    if definition.get("value_kind")=="calculated" or kind=="calculated":
        raise ValueError("Calculated variables are written only by Python from a validated equation.")
    event=_cm_append_value_event(module,definition,value,value_kind=kind,confidence=confidence,actor=actor,provider=provider,model=model,reason=reason,source_refs=source_refs)
    recalculation=_cm_recalculate(module,changed_refs={definition["ref"]},include_system=include_system) if recalculate else None
    return {"ok":True,"event":event,"recalculation":recalculation}


def _cm_history(module, reference: str, limit: int = 50) -> dict:
    definition=_cm_get_variable(module,reference,include_retired=True)
    if not definition: raise KeyError(f"Unknown variable: {reference}")
    limit=max(1,min(_CUSTOM_METRIC_MAX_HISTORY,int(limit)))
    with module.db_connect() as db:
        rows=db.execute("SELECT * FROM custom_metric_value_events WHERE variable_id=? ORDER BY row_id DESC LIMIT ?",(definition["variable_id"],limit)).fetchall()
    return {"ok":True,"variable":definition,"count":len(rows),"events":[_cm_decode_value_row(row) for row in rows]}


def _cm_state(module, *, recalculate: bool = True, include_system: bool = True, include_retired: bool = False) -> dict:
    recalculation=_cm_recalculate(module,include_system=include_system) if recalculate else None
    definitions=_cm_latest_variable_defs(module,include_retired=include_retired)
    events=_cm_latest_value_events(module)
    equations=_cm_latest_equations(module,include_retired=include_retired)
    active_equations={eq["output_variable_id"]:eq for eq in equations if eq.get("status")=="active"}
    errors_by_output={x.get("output_ref"):x.get("error") for x in (recalculation or {}).get("errors",[]) if x.get("output_ref")}
    variables=[]
    for definition in definitions:
        event=events.get(definition["variable_id"])
        row={k:definition.get(k) for k in ("variable_id","version","ref","scope","name","value_type","unit","min_value","max_value","enum_values","description","value_kind","context_mode","status")}
        row["current"] = None
        if event:
            row["current"]={k:event.get(k) for k in ("event_id","recorded_at","value","value_kind","confidence","actor","provider","model","reason_text","source_refs","equation_id","equation_version","input_snapshot_sha256")}
        eq=active_equations.get(definition["variable_id"])
        row["derived_by"]={"equation_id":eq["equation_id"],"equation_ref":eq["equation_ref"],"version":eq["version"]} if eq else None
        row["status_detail"]="recalculation_error" if definition.get("ref") in errors_by_output else ("no_value" if not event else "current")
        if definition.get("ref") in errors_by_output: row["recalculation_error"]=errors_by_output[definition["ref"]]
        variables.append(row)
    return {"ok":bool((recalculation or {"ok":True}).get("ok",True)),"version":_CUSTOM_METRICS_VERSION,"variable_count":len(variables),"equation_count":len(equations),"variables":variables,"equations":equations,"recalculation":recalculation,"arbitrary_code_execution":False}


def _cm_context_packet(module, *, query: str = "", force_recalculate: bool = True) -> dict:
    state=_cm_state(module,recalculate=force_recalculate,include_system=True)
    candidates=[]
    for row in state["variables"]:
        if row.get("status")!="active" or row.get("context_mode")=="off" or not row.get("current"):
            continue
        rank=0 if row.get("context_mode")=="always" else 1
        candidates.append((rank,str((row.get("current") or {}).get("recorded_at") or ""),row))
    # Stable two-pass sort: newest within each context mode, then always before auto.
    candidates.sort(key=lambda item:(item[1],item[2]["ref"]), reverse=True)
    candidates.sort(key=lambda item:item[0])
    selected=[item[2] for item in candidates[:_CUSTOM_METRIC_MAX_CONTEXT_VARIABLES]]
    selected_refs={row["ref"] for row in selected}
    variables=[]
    for row in selected:
        current=row["current"]
        variables.append({
            "ref":row["ref"],"value":current.get("value"),"type":row.get("value_type"),"unit":row.get("unit"),
            "value_kind":current.get("value_kind"),"confidence":current.get("confidence"),"recorded_at":current.get("recorded_at"),
            "context_mode":row.get("context_mode"),"status":row.get("status_detail"),"derived_by":row.get("derived_by"),
        })
    equations=[]
    for eq in state["equations"]:
        if eq.get("status")!="active": continue
        if eq.get("output_ref") in selected_refs or len(equations)<4:
            equations.append({"equation_id":eq["equation_id"],"version":eq["version"],"equation_ref":eq["equation_ref"],"output_ref":eq["output_ref"],"formula":eq["formula"],"purpose":eq["purpose"],"semantic_role":eq.get("semantic_role","legacy_unspecified"),"authoritative_writeback":False,"input_refs":(eq.get("validation") or {}).get("input_refs") or []})
        if len(equations)>=_CUSTOM_METRIC_MAX_CONTEXT_EQUATIONS: break
    return {"version":_CUSTOM_METRICS_VERSION,"computed_at":_cm_now(),"variables":variables,"equations":equations,"recalculation":{"ok":(state.get("recalculation") or {}).get("ok",True),"calculated":(state.get("recalculation") or {}).get("calculated",0),"errors":(state.get("recalculation") or {}).get("errors",[])[:4]},"variable_count_total":state["variable_count"],"equation_count_total":state["equation_count"],"context_truncated":len(candidates)>len(selected),"freshness":"recalculated_before_injection" if force_recalculate else "caller_controlled"}


def _cm_prompt_context(module, query: str) -> str:
    try:
        packet=_cm_context_packet(module,query=query,force_recalculate=True)
    except Exception as exc:
        packet={"version":_CUSTOM_METRICS_VERSION,"variables":[],"equations":[],"error":f"{type(exc).__name__}: {exc}"}
    compact=_cm_canonical(packet)
    if len(compact)>_CUSTOM_METRIC_MAX_CONTEXT_CHARS:
        compact=compact[:_CUSTOM_METRIC_MAX_CONTEXT_CHARS] + "..."
    text=(
        "CUSTOM VARIABLES & EQUATIONS — PYTHON-VALIDATED PERSONAL METRICS\n"
        "These are typed, scoped, append-only variables and deterministic derived values. Calculated values are interpretations of their recorded inputs/formula, not independent source truth. Preserve value_kind, confidence, units, and provenance distinctions. Python evaluates formulas with a restricted AST; no eval/exec/import/filesystem/network code is allowed.\n\n"
        + compact + "\n\n"
        "You may intentionally request custom_metric_updates inside the existing hidden <affective_update> JSON when a reusable metric or equation would genuinely help continuity. Do not convert every number or casual equation in conversation into persistent system state. Supported actions are define_variable, set_value, define_equation, set_equation_semantic_role, recalculate, retire_variable, retire_equation. Python validates every type, range, dependency, and formula and preserves append-only history."
    )
    if _CUSTOM_METRIC_DESIGN_MARKER in str(query or ""):
        catalog=_cm_input_catalog(module,include_values=True,query="",include_system=True)
        design={
            "available_inputs":catalog.get("inputs",[])[:160],
            "safe_functions":sorted(_PERCEPTION_SAFE_FUNCTIONS),
            "variable_types":sorted(_CUSTOM_METRIC_TYPES),
            "value_kinds":sorted(_CUSTOM_METRIC_VALUE_KINDS),
            "context_modes":sorted(_CUSTOM_METRIC_CONTEXT_MODES),
            "semantic_roles":sorted(_CUSTOM_METRIC_SEMANTIC_ROLES),
            "existing_equations":[{"equation_ref":eq.get("equation_ref"),"output_ref":eq.get("output_ref"),"formula":eq.get("formula"),"purpose":eq.get("purpose"),"semantic_role":eq.get("semantic_role","legacy_unspecified"),"input_refs":(eq.get("validation") or {}).get("input_refs") or [],"version":eq.get("version")} for eq in _cm_latest_equations(module,include_retired=False)[:80]],
            "update_examples":{
                "define_variable":{"action":"define_variable","ref":"project.assistant.completed_tasks","value_type":"count","unit":"count","description":"Completed project tasks.","value_kind":"user_supplied","context_mode":"auto"},
                "set_value":{"action":"set_value","ref":"project.assistant.completed_tasks","value":23,"confidence":1.0,"reason":"User supplied the current task count."},
                "define_equation":{"action":"define_equation","name":"project_progress","output_ref":"project.assistant.progress","output_type":"percentage","formula":"100 * safe_div(completed_tasks, planned_tasks, 0)","purpose":"Track completion percentage from completed and planned tasks.","context_mode":"always","semantic_role":"operational"},
                "set_equation_semantic_role":{"action":"set_equation_semantic_role","ref":"continuity.note_load","semantic_role":"descriptive","reason":"Assistant chose how this existing metric should be interpreted; Python inherits all protected equation fields."},
            },
            "design_rule":"Create only metrics that are reusable and meaningful. Prefer a small coherent set over many weak variables. Label each equation operational, descriptive, or interpretive. Derived values may read Python-owned state but never write back into authoritative emotion, somatic, continuity, session, memory, or context state.",
        }
        extra="\n\nCUSTOM METRIC DESIGN WORKSPACE\n"+json.dumps(design,ensure_ascii=False,indent=2)
        if len(extra)>18000: extra=extra[:18000]+"\n[design catalog truncated]"
        text+=extra
    return text


def _cm_design_prompt(purpose: str) -> str:
    purpose=_cm_clean(purpose,1600) or "Design useful variables and equations you would actually want to revisit."
    contract = {
        "visible_response": "An explanation in Assistant's own voice of what was selected and why; choose whatever length and structure feels appropriate.",
        "custom_metric_updates": [
            {
                "action": "define_equation",
                "name": "example_metric",
                "output_ref": "example.metric",
                "output_type": "float",
                "formula": "safe_div(example.input_a, example.input_b, 0)",
                "purpose": "Example only; use real available inputs instead.",
                "context_mode": "auto",
            }
        ],
    }
    return (
        f"{_CUSTOM_METRIC_DESIGN_MARKER}\n"
        f"Purpose requested by Steeve: {purpose}\n"
        "This is an APPLY command, not an advisory brainstorming request. Inspect the Python-provided custom metric workspace and choose only a small coherent useful subset. "
        "Do not duplicate Python-owned inputs. If you select a NEW derived metric, provide its exact safe formula and scoped output_ref. "
        "If you only want to change the semantic role of an EXISTING equation, use set_equation_semantic_role with its equation/output ref; Python inherits and protects the exact formula, inputs, output_ref, purpose, and behavior. "
        "Set values only when supported by current conversation/evidence. It is valid to choose nothing if nothing is genuinely useful.\n\n"
        "Return EXACTLY one JSON object and no Markdown. The object must contain visible_response and custom_metric_updates. "
        "Every metric you say you selected in visible_response MUST have the corresponding define_variable/set_value/define_equation operation in custom_metric_updates. "
        "Do not rely on the hidden affective_update block for this explicit command; Python will commit this JSON transaction itself.\n"
        f"Required shape example:\n{json.dumps(contract, ensure_ascii=False, indent=2)}"
    )


def _cm_parse_design_payload(text: object) -> dict:
    raw=str(text or "").strip()
    if not raw:
        raise ValueError("Assistant returned an empty metric-design response.")
    # Tolerate a single Markdown JSON fence even though the contract forbids it.
    if raw.startswith("```"):
        lines=raw.splitlines()
        if lines and lines[0].strip().casefold() in {"```","```json"}:
            lines=lines[1:]
        if lines and lines[-1].strip()=="```":
            lines=lines[:-1]
        raw="\n".join(lines).strip()
    try:
        payload=json.loads(raw)
    except Exception as exc:
        # Last-resort bounded extraction of one JSON object; never infer operations from prose.
        start=raw.find("{"); end=raw.rfind("}")
        if start<0 or end<=start:
            raise ValueError("Metric design was not returned as the required JSON transaction.") from exc
        try:
            payload=json.loads(raw[start:end+1])
        except Exception as inner:
            raise ValueError("Metric design JSON could not be parsed; no metric changes were committed.") from inner
    if not isinstance(payload,dict):
        raise ValueError("Metric design payload must be one JSON object.")
    visible=_cm_clean(payload.get("visible_response"),6000)
    updates=payload.get("custom_metric_updates")
    if not isinstance(updates,list):
        raise ValueError("Metric design payload requires custom_metric_updates as a list.")
    if len(updates)>12:
        raise ValueError("Metric design proposed more than 12 operations; choose a smaller coherent subset.")
    if not visible:
        visible="I did not add a separate explanation for this metric design."
    return {"visible_response":visible,"custom_metric_updates":updates}


def _cm_commit_design_answer(module, answer: object, *, provider: str, model: str) -> str:
    try:
        payload=_cm_parse_design_payload(answer)
    except Exception as exc:
        module._CUSTOM_METRIC_LAST_DESIGN={
            "ok":False,"committed":False,"error":f"{type(exc).__name__}: {exc}","processed_at":_cm_now(),
        }
        return (
            str(answer or "").strip()
            + "\n\n[metrics commit: 0 applied — structured design transaction missing/invalid; no metric state changed]"
        ).strip()
    result=_cm_apply_updates(module,payload["custom_metric_updates"],provider=provider,model=model)
    rows=list(result.get("results") or [])
    applied=sum(1 for row in rows if row.get("ok"))
    rejected=[row for row in rows if not row.get("ok")]
    # Recalculate once after the transaction so dependent outputs become immediately visible.
    recalc=None
    if applied:
        try:
            recalc=_cm_recalculate(module,include_system=True)
        except Exception as exc:
            recalc={"ok":False,"error":f"{type(exc).__name__}: {exc}"}
    outcome={
        "ok":not rejected and bool(result.get("changed") or not rows),
        "committed":bool(applied),
        "operations":len(rows),
        "applied":applied,
        "rejected":len(rejected),
        "rejections":[{"action":row.get("action"),"error":row.get("error")} for row in rejected[:6]],
        "recalculation":recalc,
        "processed_at":_cm_now(),
    }
    module._CUSTOM_METRIC_LAST_DESIGN=outcome
    summary=f"[metrics commit: {applied} applied"
    if rejected:
        summary+=f", {len(rejected)} rejected"
    if not rows:
        summary+=", deliberate no-change design"
    summary+="]"
    if rejected:
        details="; ".join(f"{row.get('action')}: {row.get('error')}" for row in rejected[:3])
        summary+=f" {details}"
    return (payload["visible_response"].strip()+"\n\n"+summary).strip()


def _cm_apply_updates(module, updates: object, *, provider: str, model: str) -> dict:
    if not isinstance(updates,list): return {"changed":False,"results":[]}
    results=[]
    for item in updates[:12]:
        if not isinstance(item,dict): continue
        action=str(item.get("action") or "").strip().casefold()
        try:
            if action in {"define_variable","create_variable","update_variable"}:
                result=_cm_define_variable(module,ref=item.get("ref"),value_type=item.get("value_type","float"),unit=item.get("unit"),min_value=item.get("min_value"),max_value=item.get("max_value"),enum_values=item.get("enum_values"),description=item.get("description",""),value_kind=item.get("value_kind","inferred"),context_mode=item.get("context_mode","auto"),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_variable_definition"),source_refs=item.get("source_refs"))
            elif action in {"set_value","observe","update_value"}:
                result=_cm_set_value(module,str(item.get("ref") or ""),item.get("value"),confidence=float(item.get("confidence",1.0) or 1.0),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_metric_update"),source_refs=item.get("source_refs"),value_kind=item.get("value_kind"),recalculate=True,include_system=True)
            elif action in {"define_equation","create_equation","update_equation"}:
                result=_cm_define_equation(module,name=item.get("name") or "derived_metric",output_ref=item.get("output_ref"),formula=item.get("formula"),purpose=item.get("purpose") or item.get("description") or "Assistant-authored derived metric.",scope=item.get("scope"),output_type=item.get("output_type","float"),output_unit=item.get("output_unit") or item.get("unit"),output_min=item.get("output_min"),output_max=item.get("output_max"),context_mode=item.get("context_mode","auto"),semantic_role=item.get("semantic_role","interpretive"),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_equation_definition"),source_refs=item.get("source_refs"),include_system=True)
            elif action in {"set_equation_semantic_role","version_equation_semantic_role","set_semantic_role"}:
                result=_cm_version_equation_semantic_role(module,str(item.get("ref") or item.get("equation_ref") or item.get("output_ref") or item.get("name") or ""),item.get("semantic_role"),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_semantic_role_choice"))
            elif action in {"recalculate","recalc"}:
                result=_cm_recalculate(module,include_system=True)
            elif action=="retire_variable":
                result=_cm_retire_variable(module,str(item.get("ref") or item.get("variable_id") or ""),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_variable_retirement"))
            elif action=="retire_equation":
                result=_cm_retire_equation(module,str(item.get("equation_ref") or item.get("equation_id") or item.get("name") or ""),actor="Assistant",provider=provider,model=model,reason=item.get("reason","assistant_equation_retirement"))
            else:
                raise ValueError(f"Unknown custom metric action: {action or '<empty>'}")
            results.append({"action":action,"ok":True,"result":result})
        except Exception as exc:
            results.append({"action":action,"ok":False,"error":f"{type(exc).__name__}: {exc}"})
            try: module.append_system_log("custom_metric_update_rejected",{"action":action,"error":results[-1]["error"]},provider=provider,model=model)
            except Exception: pass
    outcome={"changed":any(x.get("ok") for x in results),"results":results,"processed_at":_cm_now()}
    module._CUSTOM_METRIC_LAST_UPDATE=outcome
    return outcome


def _cm_command_help() -> str:
    return (
        "/metrics — typed variables and safe equations\n\n"
        "  /metrics status | /metrics variables | /metrics equations\n"
        "  /metrics inputs [query] | /metrics show <VAR/EQ/ref> | /metrics history <variable> [limit]\n"
        "  /metrics recalc\n"
        "  /metrics discover [query] | /metrics discover values [query] | /metrics discover design <purpose>\n"
        "  /metrics role <equation|output_ref> <operational|descriptive|interpretive>\n"
        "  /metrics design <purpose>\n"
        "      Assistant designs a coherent set and Python validates/commits the structured transaction in the same turn.\n"
        "  /metrics define <scope.name> <type> [unit=...] [kind=...] [context=always|auto|off] [min=...] [max=...] :: description\n"
        "  /metrics set <scope.name> <value> :: reason\n"
        "  /metrics equation <name> -> <output.scope.name> = <safe formula> :: purpose\n"
        "  /metrics retire variable <ref> | /metrics retire equation <EQ/ref>\n\n"
        "Equations may use same-scope short names (completed_tasks) or full refs (project.assistant.completed_tasks), plus numeric/boolean Python system metrics such as emotion.CURIOSITY.current. No arbitrary Python is executed."
    )


def _cm_handle_command(module, text: str) -> bool:
    command=str(text or "").strip(); lower=command.casefold()
    if not (lower=="/metrics" or lower.startswith("/metrics ")): return False
    import shlex
    try:
        if lower in {"/metrics","/metrics status"}:
            print(json.dumps(_cm_state(module,recalculate=True,include_system=True),ensure_ascii=False,indent=2)); return True
        if lower in {"/metrics help","/metrics commands"}:
            print(_cm_command_help()); return True
        if lower=="/metrics variables":
            print(json.dumps({"ok":True,"variables":_cm_state(module,recalculate=True,include_system=True)["variables"]},ensure_ascii=False,indent=2)); return True
        if lower=="/metrics equations":
            print(json.dumps({"ok":True,"equations":_cm_latest_equations(module,include_retired=True)},ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics inputs"):
            query=command[len("/metrics inputs"):].strip(); print(json.dumps(_cm_input_catalog(module,include_values=True,query=query),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics show "):
            ref=command[len("/metrics show "):].strip(); variable=_cm_get_variable(module,ref,include_retired=True)
            if variable: result={"kind":"variable","variable":variable,"history":_cm_history(module,ref,limit=12)["events"]}
            else:
                equation=_cm_get_equation(module,ref,include_retired=True)
                if not equation: raise KeyError(f"Unknown metric/equation: {ref}")
                result={"kind":"equation","equation":equation}
            print(json.dumps(result,ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics history "):
            parts=shlex.split(command[len("/metrics history "):].strip());
            if not parts: raise ValueError("Use /metrics history <variable> [limit].")
            limit=int(parts[1]) if len(parts)>1 else 50
            print(json.dumps(_cm_history(module,parts[0],limit),ensure_ascii=False,indent=2)); return True
        if lower=="/metrics recalc":
            print(json.dumps(_cm_recalculate(module,include_system=True),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics role "):
            parts=shlex.split(command[len("/metrics role "):].strip())
            if len(parts)!=2: raise ValueError("Use /metrics role <equation|output_ref> <operational|descriptive|interpretive>.")
            print(json.dumps(_cm_version_equation_semantic_role(module,parts[0],parts[1],actor="user",provider="console",model=BUNDLE_VERSION,reason="console_semantic_role_choice"),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics define "):
            body=command[len("/metrics define "):].strip(); head,sep,desc=body.partition("::"); parts=shlex.split(head.strip())
            if len(parts)<2: raise ValueError("Use /metrics define <scope.name> <type> [options] :: description")
            ref,value_type=parts[:2]; options={}
            for token in parts[2:]:
                if "=" not in token: raise ValueError(f"Unknown define option: {token}")
                key,val=token.split("=",1); options[key.casefold()]=val
            result=_cm_define_variable(module,ref=ref,value_type=value_type,unit=options.get("unit"),min_value=float(options["min"]) if "min" in options else None,max_value=float(options["max"]) if "max" in options else None,description=desc.strip(),value_kind=options.get("kind","user_supplied"),context_mode=options.get("context","auto"),actor="user",provider="console",model=BUNDLE_VERSION,reason="console_variable_definition")
            print(json.dumps(result,ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics set "):
            body=command[len("/metrics set "):].strip(); head,sep,reason=body.partition("::"); parts=shlex.split(head.strip())
            if len(parts)<2: raise ValueError("Use /metrics set <scope.name> <value> :: reason")
            ref=parts[0]; definition=_cm_get_variable(module,ref,include_retired=False)
            if not definition: raise KeyError(f"Unknown active variable: {ref}")
            raw=" ".join(parts[1:]); result=_cm_set_value(module,ref,raw,confidence=1.0,actor="user",provider="console",model=BUNDLE_VERSION,reason=reason.strip() or "console_value_update",source_refs=[])
            print(json.dumps(result,ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics equation "):
            body=command[len("/metrics equation "):].strip(); head,sep,purpose=body.partition("::")
            match=re.fullmatch(r"\s*([A-Za-z_][A-Za-z0-9_-]*)\s*->\s*([A-Za-z0-9_.]+)\s*=\s*(.+?)\s*",head)
            if not match: raise ValueError("Use /metrics equation <name> -> <output.ref> = <formula> :: purpose")
            name,output_ref,formula=match.groups(); result=_cm_define_equation(module,name=name,output_ref=output_ref,formula=formula,purpose=purpose.strip() or f"Derived metric {name}.",actor="user",provider="console",model=BUNDLE_VERSION,reason="console_equation_definition")
            print(json.dumps(result,ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics retire variable "):
            ref=command[len("/metrics retire variable "):].strip(); print(json.dumps(_cm_retire_variable(module,ref,actor="user",provider="console",model=BUNDLE_VERSION,reason="console_retire"),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics retire equation "):
            ref=command[len("/metrics retire equation "):].strip(); print(json.dumps(_cm_retire_equation(module,ref,actor="user",provider="console",model=BUNDLE_VERSION,reason="console_retire"),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/metrics design"):
            # The input wrapper converts this to a model design request before this handler.
            print("Use /metrics design <purpose> from normal chat so Assistant can design the metrics."); return True
        print(_cm_command_help()); return True
    except Exception as exc:
        print(f"Custom metric error: {type(exc).__name__}: {exc}"); return True


def typed_variables_equations_self_test(module=None) -> dict:
    import inspect
    if module is None: module=_load_memory()
    original_db_connect=module.db_connect
    opened=[]
    checks={}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-custom-metrics-") as folder:
            db_path=Path(folder)/"metrics.sqlite"
            def tracked_connect():
                db=sqlite3.connect(db_path); db.row_factory=sqlite3.Row; opened.append(db); return db
            module.db_connect=tracked_connect
            _cm_ensure_schema(module)
            a=_cm_define_variable(module,ref="project.assistant.completed_tasks",value_type="count",unit="count",description="Completed tasks",value_kind="user_supplied",context_mode="always",actor="SelfTest",provider="python",model="self-test")
            b=_cm_define_variable(module,ref="project.assistant.planned_tasks",value_type="count",unit="count",description="Planned tasks",value_kind="user_supplied",context_mode="always",actor="SelfTest",provider="python",model="self-test")
            _cm_set_value(module,a["variable"]["ref"],23,actor="SelfTest",provider="python",model="self-test",reason="seed",recalculate=False,include_system=False)
            _cm_set_value(module,b["variable"]["ref"],40,actor="SelfTest",provider="python",model="self-test",reason="seed",recalculate=False,include_system=False)
            eq=_cm_define_equation(module,name="project_progress",output_ref="project.assistant.progress",output_type="percentage",output_unit="%",formula="100 * safe_div(completed_tasks, planned_tasks, 0)",purpose="Completion percentage",context_mode="always",actor="SelfTest",provider="python",model="self-test",include_system=False)
            state=_cm_state(module,recalculate=True,include_system=False)
            progress=next(row for row in state["variables"] if row["ref"]=="project.assistant.progress")
            checks["typed_variables_saved"]=a["variable"]["value_type"]=="count" and b["variable"]["unit"]=="count"
            checks["same_scope_alias_equation"]=abs(float(progress["current"]["value"])-57.5)<1e-9
            checks["calculated_value_is_python_owned"]=progress["current"]["value_kind"]=="calculated" and progress["current"]["actor"]=="Python"
            checks["equation_has_input_provenance"]=bool(progress["current"].get("input_snapshot_sha256")) and len((progress["current"] and _cm_history(module,"project.assistant.progress",5)["events"][0].get("input_snapshot",{}).get("inputs",[])) or [])==2
            history_before=_cm_history(module,"project.assistant.completed_tasks",20)["count"]
            _cm_set_value(module,"project.assistant.completed_tasks",24,actor="SelfTest",provider="python",model="self-test",reason="advance",include_system=False)
            state2=_cm_state(module,recalculate=True,include_system=False)
            progress2=next(row for row in state2["variables"] if row["ref"]=="project.assistant.progress")
            checks["dependency_recalculation"]=abs(float(progress2["current"]["value"])-60.0)<1e-9
            checks["append_only_value_history"]=_cm_history(module,"project.assistant.completed_tasks",20)["count"]==history_before+1
            malicious=False
            try: _cm_define_equation(module,name="unsafe",output_ref="project.assistant.unsafe",formula="__import__('os').system('echo nope')",purpose="unsafe",actor="SelfTest",provider="python",model="self-test",include_system=False)
            except Exception: malicious=True
            checks["arbitrary_python_rejected"]=malicious
            checks["rejected_equation_leaves_no_output_debris"]=_cm_get_variable(module,"project.assistant.unsafe",include_retired=True) is None
            same_eq=_cm_define_equation(module,name="project_progress",output_ref="project.assistant.progress",formula="100 * safe_div(completed_tasks, planned_tasks, 0)",purpose="Completion percentage",actor="SelfTest",provider="python",model="self-test",include_system=False)
            checks["identical_equation_is_idempotent"]=same_eq.get("idempotent") is True and int(same_eq.get("equation",{}).get("version",0))==1
            role_before=_cm_get_equation(module,"project.assistant.progress",include_retired=False)
            role_update=_cm_version_equation_semantic_role(module,"project.assistant.progress","descriptive",actor="SelfTest",provider="python",model="self-test",reason="role-only regression")
            role_after=_cm_get_equation(module,"project.assistant.progress",include_retired=False)
            checks["semantic_role_only_version_by_output_ref"]=bool(role_update.get("role_only") and role_update.get("protected_fields_unchanged") and role_after and role_after.get("semantic_role")=="descriptive" and int(role_after.get("version",0))==int(role_before.get("version",0))+1)
            checks["semantic_role_only_preserves_equation_definition"]=all(role_before.get(k)==role_after.get(k) for k in ("equation_id","equation_ref","scope","name","output_ref","formula","purpose"))
            role_idempotent=_cm_version_equation_semantic_role(module,"project.assistant.progress","descriptive",actor="SelfTest",provider="python",model="self-test")
            checks["semantic_role_only_idempotent"]=role_idempotent.get("idempotent") is True and int((role_idempotent.get("equation") or {}).get("version",0))==int(role_after.get("version",0))
            _cm_define_variable(module,ref="calc.a",value_type="float",description="A",value_kind="calculated",actor="SelfTest",provider="python",model="self-test")
            _cm_define_variable(module,ref="calc.b",value_type="float",description="B",value_kind="calculated",actor="SelfTest",provider="python",model="self-test")
            _cm_define_equation(module,name="a_from_b",output_ref="calc.a",formula="b + 1",purpose="A from B",actor="SelfTest",provider="python",model="self-test",include_system=False)
            cycle=False
            try: _cm_define_equation(module,name="b_from_a",output_ref="calc.b",formula="a + 1",purpose="B from A",actor="SelfTest",provider="python",model="self-test",include_system=False)
            except Exception: cycle=True
            checks["dependency_cycle_rejected"]=cycle
            off=_cm_define_variable(module,ref="private.hidden_metric",value_type="float",description="hidden",value_kind="user_supplied",context_mode="off",actor="SelfTest",provider="python",model="self-test")
            _cm_set_value(module,off["variable"]["ref"],7,actor="SelfTest",provider="python",model="self-test",reason="hidden",recalculate=False,include_system=False)
            packet=_cm_context_packet(module,force_recalculate=False)
            checks["context_mode_off_respected"]=all(row.get("ref")!="private.hidden_metric" for row in packet.get("variables") or [])
            direct_calculated=False
            try: _cm_set_value(module,"project.assistant.progress",99,actor="SelfTest",provider="python",model="self-test",include_system=False)
            except Exception: direct_calculated=True
            checks["calculated_output_cannot_be_manually_written"]=direct_calculated
            update_result=_cm_apply_updates(module,[{"action":"define_variable","ref":"personal.focus_score","value_type":"float","description":"Assistant-selected focus score","value_kind":"inferred","context_mode":"auto"},{"action":"set_value","ref":"personal.focus_score","value":0.72,"confidence":0.7,"reason":"self-test inference"}],provider="self-test",model="python")
            checks["assistant_update_protocol_works"]=update_result.get("changed") is True and _cm_get_variable(module,"personal.focus_score") is not None
            design_answer=json.dumps({
                "visible_response":"I selected one additional derived ratio for the test.",
                "custom_metric_updates":[{
                    "action":"define_equation",
                    "name":"project_ratio_transaction",
                    "output_ref":"project.assistant.ratio_transaction",
                    "output_type":"float",
                    "formula":"safe_div(completed_tasks, planned_tasks, 0)",
                    "purpose":"Verify that an explicit metrics design response is committed transactionally.",
                    "context_mode":"auto",
                }],
            })
            design_visible=_cm_commit_design_answer(module,design_answer,provider="self-test",model="python")
            design_eq=_cm_get_equation(module,"project.assistant.project_ratio_transaction",include_retired=False)
            design_state=_cm_state(module,recalculate=True,include_system=False)
            design_var=next((row for row in design_state["variables"] if row.get("ref")=="project.assistant.ratio_transaction"),None)
            checks["metrics_design_transaction_commits"]=bool(design_eq and design_var and design_var.get("current") and abs(float(design_var["current"]["value"])-0.6)<1e-9)
            checks["metrics_design_transaction_visible_ack"]="metrics commit: 1 applied" in design_visible
            before_defs=len(_cm_latest_variable_defs(module,include_retired=True))
            invalid_design=_cm_commit_design_answer(module,"I selected a metric but forgot the JSON.",provider="self-test",model="python")
            after_defs=len(_cm_latest_variable_defs(module,include_retired=True))
            checks["invalid_design_never_infers_from_prose"]=before_defs==after_defs and "0 applied" in invalid_design
            append_only=False
            db=tracked_connect()
            try:
                db.execute("UPDATE custom_metric_variables SET description='tampered'"); db.commit()
            except sqlite3.DatabaseError:
                db.rollback(); append_only=True
            checks["definition_history_append_only"]=append_only
            checks["safe_evaluator_reused"]={"eval","exec","compile","__import__"}.isdisjoint(set(_cm_formula_eval.__code__.co_names)) and "_perception_eval_ast" in set(_cm_formula_eval.__code__.co_names)
            checks["equation_versioned"]=int(eq["equation"]["version"])==1 and str(eq["equation"]["equation_id"]).startswith("EQ-")
            groups=_adaptive_tool_query_groups("show my variables metrics and equations",("personal",))
            selected,_report=_adaptive_tool_select(list(module.TOOL_SCHEMAS),"show my variables metrics and equations",("personal",))
            selected_names=[_adaptive_tool_name(item) for item in selected]
            checks["adaptive_tool_catalog_understands_metrics"]="metrics" in groups and any("custom_metric" in name for name in selected_names)
            help_key,help_text=_unified_help_topic("/help metrics")
            checks["unified_help_exposes_metrics"]=help_key=="/metrics" and "/metrics design" in str(help_text or "")
            _affective_chain_source="\n".join(inspect.getsource(fn) for fn in (globals().get("_process_affective_output_749"),globals().get("_process_affective_output_7410"),process_affective_output) if callable(fn))
            checks["affective_update_hook_exposed"]=callable(getattr(module,"apply_custom_metric_updates",None)) and "custom_metric_updates" in _affective_chain_source
            # Close every SQLite handle before Windows TemporaryDirectory cleanup.
            for db in reversed(opened):
                try: db.close()
                except Exception: pass
            opened.clear()
    finally:
        for db in reversed(opened):
            try: db.close()
            except Exception: pass
        module.db_connect=original_db_connect
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_CUSTOM_METRICS_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


def _install_typed_variables_equations(module) -> None:
    if getattr(module,"_TYPED_VARIABLES_EQUATIONS_INSTALLED",False): return
    module.CUSTOM_METRICS_VERSION=_CUSTOM_METRICS_VERSION
    module.get_custom_metric_state=lambda recalculate=True:_cm_state(module,recalculate=recalculate,include_system=True)
    module.list_custom_metric_variables=lambda include_retired=False:_cm_latest_variable_defs(module,include_retired=include_retired)
    module.list_custom_metric_equations=lambda include_retired=False:_cm_latest_equations(module,include_retired=include_retired)
    module.get_custom_metric_history=lambda reference,limit=50:_cm_history(module,reference,limit)
    module.get_custom_metric_inputs=lambda query="",include_values=True:_cm_input_catalog(module,include_values=include_values,query=query,include_system=True)
    module.recalculate_custom_metrics=lambda:_cm_recalculate(module,include_system=True)
    module.apply_custom_metric_updates=lambda updates,provider="unknown",model="unknown":_cm_apply_updates(module,updates,provider=provider,model=model)
    module.typed_variables_equations_self_test=lambda:typed_variables_equations_self_test(module)

    old_build=module.build_runtime_context
    def build_runtime_context_with_custom_metrics(query,*args,**kwargs):
        original=old_build(query,*args,**kwargs)
        return _cm_prompt_context(module,str(query or "")) + "\n\n" + original
    module.build_runtime_context=build_runtime_context_with_custom_metrics

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_custom_metric_state","description":"Read Assistant's current typed custom variables, safe equations, derived values, units, confidence and recalculation status.","parameters":{"type":"object","properties":{"recalculate":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"list_custom_metric_variables","description":"List versioned typed custom variable definitions.","parameters":{"type":"object","properties":{"include_retired":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"list_custom_metric_equations","description":"List Assistant-authored safe deterministic equations and their input/output dependencies.","parameters":{"type":"object","properties":{"include_retired":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_custom_metric_history","description":"Read append-only value history for one custom variable.","parameters":{"type":"object","properties":{"reference":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":500}},"required":["reference"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_custom_metric_inputs","description":"Inspect numeric/boolean custom and Python-authoritative system metrics that may be used as safe equation inputs.","parameters":{"type":"object","properties":{"query":{"type":"string"},"include_values":{"type":"boolean"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_custom_metric_state","list_custom_metric_variables","list_custom_metric_equations","get_custom_metric_history","get_custom_metric_inputs"})
    old_execute=module.execute_tool
    def execute_tool_with_custom_metrics(name,arguments,seen,*args,**kwargs):
        if name=="get_custom_metric_state": return module.get_custom_metric_state(**arguments)
        if name=="list_custom_metric_variables": return module.list_custom_metric_variables(**arguments)
        if name=="list_custom_metric_equations": return module.list_custom_metric_equations(**arguments)
        if name=="get_custom_metric_history": return module.get_custom_metric_history(**arguments)
        if name=="get_custom_metric_inputs": return module.get_custom_metric_inputs(**arguments)
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_tool_with_custom_metrics

    # Explicit /metrics design is a transaction. The normal hidden affective-update
    # path remains available for opportunistic metric proposals during ordinary chat,
    # but this command must not silently degrade into prose-only advice.
    old_metric_local=module.run_local_turn
    def run_local_with_metric_design(backend,messages,query=None,*,allow_sticky=True):
        if query is None:
            return old_metric_local(backend,messages,allow_sticky=allow_sticky)
        answer=old_metric_local(backend,messages,query,allow_sticky=allow_sticky)
        if _CUSTOM_METRIC_DESIGN_MARKER in str(query or ""):
            return _cm_commit_design_answer(module,answer,provider="local",model=getattr(backend,"model_id","local"))
        return answer
    module.run_local_turn=run_local_with_metric_design

    old_metric_online=module.run_online_chat_turn
    def run_online_with_metric_design(backend,messages,query):
        answer=old_metric_online(backend,messages,query)
        if _CUSTOM_METRIC_DESIGN_MARKER in str(query or ""):
            return _cm_commit_design_answer(module,answer,provider="online",model=getattr(backend,"model_id","online"))
        return answer
    module.run_online_chat_turn=run_online_with_metric_design

    old_doctor=getattr(module,"doctor_report",None)
    if callable(old_doctor):
        def doctor_with_custom_metrics():
            report=old_doctor()
            try:
                state=_cm_state(module,recalculate=False,include_system=False)
                report["custom_metrics"]={"version":_CUSTOM_METRICS_VERSION,"variables":state["variable_count"],"equations":state["equation_count"],"safe_equations":True,"arbitrary_code_execution":False}
            except Exception as exc:
                report["custom_metrics"]={"version":_CUSTOM_METRICS_VERSION,"error":f"{type(exc).__name__}: {exc}"}
            return report
        module.doctor_report=doctor_with_custom_metrics

    old_main=module.main
    def main_with_custom_metric_commands():
        previous_input=builtins.input
        def custom_metric_input(prompt=""):
            while True:
                value=previous_input(prompt)
                compact=" ".join(str(value or "").strip().split())
                lower=compact.casefold()
                if lower=="/metrics design" or lower.startswith("/metrics design "):
                    purpose=compact[len("/metrics design"):].strip()
                    return _cm_design_prompt(purpose)
                if _cm_handle_command(module,value): continue
                return value
        builtins.input=custom_metric_input
        try: return old_main()
        finally: builtins.input=previous_input
    module.main=main_with_custom_metric_commands
    module.RELEASE_NAME=RELEASE_NAME
    module._TYPED_VARIABLES_EQUATIONS_INSTALLED=True



# ---------------------------------------------------------------------------
# NeatMemory 7.4.33 — Assistant-Controlled Derived Signal Discovery
# ---------------------------------------------------------------------------
_DERIVED_SIGNAL_DISCOVERY_VERSION = "1.0-assistant-controlled-authoritative-signal-discovery"
_DERIVED_SIGNAL_DESIGN_MARKER = "[NEATMEMORY_DERIVED_SIGNAL_DISCOVERY_DESIGN]"
_DERIVED_SIGNAL_MAX_RESULTS = 180
_DERIVED_SIGNAL_MAX_DESIGN_EQUATIONS = 6


def _ds_words(value: object) -> set[str]:
    return {word for word in re.findall(r"[a-z0-9_]{2,}", str(value or "").casefold()) if word not in {"the","and","for","with","from","that","this","into","current"}}


def _ds_category(ref: str, item: dict) -> str:
    category=str(item.get("category") or "").strip().casefold().replace("-","_").replace(" ","_")
    if category:
        return category[:80]
    root=str(ref or "other").split(".",1)[0].strip().casefold()
    return root or "other"


def _ds_usage_map(module) -> dict[str,list[str]]:
    used: dict[str,list[str]]={}
    for eq in _cm_latest_equations(module,include_retired=False):
        if eq.get("status")!="active":
            continue
        for ref in (eq.get("validation") or {}).get("input_refs") or []:
            used.setdefault(str(ref),[]).append(str(eq.get("equation_ref") or ""))
    return {key:sorted({x for x in values if x}) for key,values in used.items()}


def _ds_catalog(module, *, query: str="", category: str="", include_values: bool=False, limit: int=_DERIVED_SIGNAL_MAX_RESULTS) -> dict:
    system=_cm_system_inputs(module)
    usage=_ds_usage_map(module)
    query_terms=_ds_words(query)
    category_filter=str(category or "").strip().casefold().replace("-","_").replace(" ","_")
    rows=[]
    for ref,item in system.items():
        cat=_ds_category(ref,item)
        if category_filter and cat!=category_filter:
            continue
        description=str(item.get("description") or "")
        hay_terms=_ds_words(f"{ref} {cat} {description}")
        overlap=len(query_terms & hay_terms)
        prefix_bonus=1 if query_terms and any(str(ref).casefold().startswith(term+".") or cat==term for term in query_terms) else 0
        phrase_bonus=1 if str(query or "").strip() and str(query or "").strip().casefold() in f"{ref} {description}".casefold() else 0
        score=(3*overlap)+(2*prefix_bonus)+phrase_bonus
        row={
            "ref":str(ref),
            "category":cat,
            "value_type":item.get("value_type"),
            "unit":item.get("unit"),
            "description":item.get("description"),
            "source_id":item.get("source_id"),
            "confidence":float(item.get("confidence",1.0) or 1.0),
            "authority":"python_authoritative_read_only",
            "origin":"python_system_metric",
            "equation_input_allowed":True,
            "authoritative_writeback":False,
            "used_by_equations":usage.get(str(ref),[]),
            "relevance_score":score,
        }
        if include_values:
            row["current_value"]=item.get("value")
        rows.append(row)
    if query_terms:
        relevant=[row for row in rows if int(row.get("relevance_score") or 0)>0]
        if relevant:
            rows=relevant
    rows.sort(key=lambda row:(-int(row.get("relevance_score") or 0),str(row.get("category") or ""),str(row.get("ref") or "")))
    total=len(rows); limit=max(1,min(_DERIVED_SIGNAL_MAX_RESULTS,int(limit or _DERIVED_SIGNAL_MAX_RESULTS))); rows=rows[:limit]
    grouped: dict[str,int]={}
    for row in rows:
        grouped[str(row.get("category") or "other")]=grouped.get(str(row.get("category") or "other"),0)+1
    return {
        "ok":True,
        "version":_DERIVED_SIGNAL_DISCOVERY_VERSION,
        "query":str(query or ""),
        "category_filter":category_filter or None,
        "include_values":bool(include_values),
        "count":len(rows),
        "matched_before_limit":total,
        "truncated":total>len(rows),
        "categories":dict(sorted(grouped.items())),
        "signals":rows,
        "meaning":"These are Python-authoritative read-only numeric/boolean signals available as equation inputs. Discovery never changes their source state.",
        "authoritative_writeback":False,
    }


def _ds_workspace(module, purpose: str) -> dict:
    catalog=_ds_catalog(module,query=purpose,include_values=True,limit=_DERIVED_SIGNAL_MAX_RESULTS)
    # A broad request should still expose a balanced category-spanning catalog.
    if not catalog.get("signals") or len(_ds_words(purpose))<3:
        catalog=_ds_catalog(module,query="",include_values=True,limit=_DERIVED_SIGNAL_MAX_RESULTS)
    variables=[]
    for row in _cm_latest_variable_defs(module,include_retired=False)[:120]:
        variables.append({k:row.get(k) for k in ("ref","value_type","unit","description","value_kind","context_mode","status")})
    equations=[]
    for eq in _cm_latest_equations(module,include_retired=False)[:100]:
        equations.append({
            "equation_ref":eq.get("equation_ref"),"output_ref":eq.get("output_ref"),"formula":eq.get("formula"),
            "purpose":eq.get("purpose"),"semantic_role":eq.get("semantic_role","legacy_unspecified"),
            "input_refs":(eq.get("validation") or {}).get("input_refs") or [],"version":eq.get("version"),
        })
    return {
        "version":_DERIVED_SIGNAL_DISCOVERY_VERSION,
        "purpose":purpose,
        "authoritative_signal_catalog":catalog,
        "existing_custom_variables":variables,
        "existing_equations":equations,
        "safe_functions":sorted(_PERCEPTION_SAFE_FUNCTIONS),
        "semantic_roles":sorted(_CUSTOM_METRIC_SEMANTIC_ROLES),
        "context_modes":sorted(_CUSTOM_METRIC_CONTEXT_MODES),
        "rules":[
            "Prefer no new equation over a weak or redundant metric.",
            "Every new discovery equation must directly reference at least one Python-authoritative signal from the supplied catalog.",
            "Do not duplicate an existing equation/output with a new name.",
            "Choose operational, descriptive, or interpretive explicitly for every new equation.",
            "Derived outputs must use a non-reserved custom namespace and can never write back into authoritative emotion, somatic, session, memory, context, time, or derived roots.",
            "Current signal values are snapshots for reasoning/preview only; formulas must reference signal IDs, not copy snapshot values as constants.",
        ],
    }


def _ds_design_prompt(purpose: str) -> str:
    purpose=_cm_clean(purpose,1800) or "Review the authoritative signals available to you and create only genuinely useful derived variables/equations."
    contract={
        "visible_response":"An explanation in Assistant's own voice of what you chose and why, or why you chose no change; choose whatever length and structure feels appropriate.",
        "custom_metric_updates":[{
            "action":"define_equation",
            "name":"example_signal",
            "output_ref":"self.example_signal",
            "output_type":"float",
            "formula":"safe_div(continuity.example_count, continuity.example_total, 0)",
            "purpose":"Example shape only; use real supplied authoritative signal refs.",
            "context_mode":"auto",
            "semantic_role":"descriptive",
        }],
    }
    return (
        f"{_DERIVED_SIGNAL_DESIGN_MARKER}\n"
        f"Purpose requested by Steeve: {purpose}\n"
        "This is an APPLY command for derived-signal discovery. Python will provide a read-only catalog of authoritative numeric/boolean signals. "
        "Choose at most a small coherent set of NEW derived equations that are genuinely useful to you. Every new equation must directly depend on at least one supplied Python-authoritative signal. "
        "Do not create manual/user-supplied variables in this flow, do not copy current snapshot values into formulas, and do not duplicate an existing equation. "
        "For every equation, explicitly choose semantic_role operational, descriptive, or interpretive. It is valid and preferred to make no change when nothing meaningful is available.\n\n"
        "Return EXACTLY one JSON object and no Markdown. The object must contain visible_response and custom_metric_updates. "
        f"Use only define_equation operations here, at most {_DERIVED_SIGNAL_MAX_DESIGN_EQUATIONS}. Python performs a full preflight before applying anything; if one proposed operation fails discovery rules, none are committed.\n"
        f"Required shape example:\n{json.dumps(contract,ensure_ascii=False,indent=2)}"
    )


def _ds_preflight(module, updates: list[dict]) -> list[dict]:
    if len(updates)>_DERIVED_SIGNAL_MAX_DESIGN_EQUATIONS:
        raise ValueError(f"Derived-signal discovery supports at most {_DERIVED_SIGNAL_MAX_DESIGN_EQUATIONS} new equations per design.")
    system=_cm_system_inputs(module); system_refs=set(system)
    all_defs=_cm_latest_variable_defs(module,include_retired=True)
    custom_defs={row["ref"]:row for row in all_defs if row.get("status")=="active"}
    active_equations=[eq for eq in _cm_latest_equations(module,include_retired=False) if eq.get("status")=="active"]
    active_outputs={str(eq.get("output_ref")):eq for eq in active_equations}
    active_equation_refs={str(eq.get("equation_ref")):eq for eq in active_equations}
    existing_equation_ids={str(eq.get("equation_id")) for eq in active_equations}
    _defs_now, custom_now, _events_now=_cm_current_custom_inputs(module)
    preview_values={ref:item.get("value") for ref,item in custom_now.items()}; preview_values.update({ref:item.get("value") for ref,item in system.items()})
    prepared=[]; seen_outputs=set(); seen_equation_refs=set(); candidate_rows=[]; missing_outputs=0
    for raw in updates:
        if not isinstance(raw,dict):
            raise ValueError("Every derived-signal update must be an object.")
        action=str(raw.get("action") or "").strip().casefold()
        if action not in {"define_equation","create_equation","update_equation"}:
            raise ValueError("Derived-signal discovery accepts only define_equation operations.")
        output_ref=_cm_normalize_ref(raw.get("output_ref"))
        if output_ref in seen_outputs:
            raise ValueError(f"Duplicate proposed output_ref: {output_ref}")
        seen_outputs.add(output_ref)
        if output_ref in active_outputs:
            raise ValueError(f"An active equation already produces {output_ref}; use the normal metric/versioning tools instead of duplicating it.")
        scope=_cm_normalize_scope(raw.get("scope") or output_ref.rsplit(".",1)[0])
        name=_cm_identifier(raw.get("name") or "derived_metric",label="equation name")
        equation_ref=_cm_equation_ref(scope,name); equation_id=_cm_equation_id(scope,name)
        if equation_ref in seen_equation_refs:
            raise ValueError(f"Duplicate proposed equation_ref: {equation_ref}")
        seen_equation_refs.add(equation_ref)
        if equation_ref in active_equation_refs or equation_id in existing_equation_ids:
            raise ValueError(f"Discovery creates new equations only; {equation_ref} already exists. Use the normal versioning tools instead.")
        role=str(raw.get("semantic_role") or "").strip().casefold()
        if role not in _CUSTOM_METRIC_SEMANTIC_ROLES:
            raise ValueError(f"New discovery equation {output_ref} requires explicit semantic_role: operational, descriptive, or interpretive.")
        purpose=_cm_clean(raw.get("purpose") or raw.get("description"),_CUSTOM_METRIC_MAX_DESCRIPTION)
        if not purpose:
            raise ValueError(f"New discovery equation {output_ref} requires a purpose.")
        context_mode=str(raw.get("context_mode") or "auto").strip().casefold()
        if context_mode not in _CUSTOM_METRIC_CONTEXT_MODES:
            raise ValueError(f"context_mode for {output_ref} must be always, auto, or off.")
        output_type=_cm_normalize_type(raw.get("output_type","float"))
        if output_type not in _CUSTOM_METRIC_FORMULA_TYPES:
            raise ValueError(f"Equation output {output_ref} must use a numeric or boolean type.")
        output_unit=_cm_clean(raw.get("output_unit") or raw.get("unit"),48) or None
        output_min=float(raw["output_min"]) if raw.get("output_min") is not None else None
        output_max=float(raw["output_max"]) if raw.get("output_max") is not None else None
        if output_min is not None and output_max is not None and output_min>output_max:
            raise ValueError(f"Output minimum exceeds maximum for {output_ref}.")
        if output_type=="percentage" and output_min is None and output_max is None:
            output_min,output_max=0.0,100.0
        if output_type in {"count","duration"} and output_min is None:
            output_min=0.0
        if output_type=="percentage" and not output_unit: output_unit="%"
        if output_type=="count" and not output_unit: output_unit="count"
        existing_output=_cm_get_variable(module,output_ref,include_retired=True)
        if existing_output:
            if existing_output.get("status")!="active":
                raise ValueError(f"Equation output variable is retired: {output_ref}")
            if existing_output.get("value_kind")!="calculated":
                raise ValueError(f"Existing output {output_ref} is not a calculated variable.")
            if existing_output.get("value_type") not in _CUSTOM_METRIC_FORMULA_TYPES:
                raise ValueError(f"Existing output {output_ref} is not numeric/boolean.")
            output_def=existing_output
        else:
            missing_outputs+=1
            output_def={"ref":output_ref,"value_type":output_type,"unit":output_unit,"min_value":output_min,"max_value":output_max,"enum_values":[],"value_kind":"calculated","context_mode":context_mode,"status":"active"}
        # Permit existing custom numeric/boolean inputs, but require at least one direct
        # Python-authoritative input so this workflow stays anchored in discovered truth.
        virtual_defs=dict(custom_defs); virtual_defs[output_ref]=output_def
        parsed=_cm_formula_parse(str(raw.get("formula") or ""),set(virtual_defs)|system_refs,local_scope=scope)
        direct_authoritative=sorted(ref for ref in parsed.get("input_refs") or [] if ref in system_refs)
        if not direct_authoritative:
            raise ValueError(f"Discovery equation {output_ref} must directly reference at least one Python-authoritative signal.")
        for ref in parsed.get("input_refs") or []:
            if ref in custom_defs and custom_defs[ref].get("value_type") not in _CUSTOM_METRIC_FORMULA_TYPES:
                raise ValueError(f"Equation input {ref} is not numeric/boolean.")
        # Match the normal equation path's real-value preview before any write.
        if all(ref in preview_values for ref in parsed.get("input_refs") or []):
            _cm_validate_value(output_def,_cm_formula_eval(parsed,preview_values))
        candidate_rows.append({
            "equation_id":equation_id,"equation_ref":equation_ref,"scope":scope,"name":name,
            "output_ref":output_ref,"status":"active","validation":{"input_refs":parsed.get("input_refs") or []},
        })
        item=dict(raw); item.update({
            "action":"define_equation","name":name,"output_ref":output_ref,"scope":scope,"semantic_role":role,
            "purpose":purpose,"context_mode":context_mode,"output_type":output_type,"output_unit":output_unit,
            "output_min":output_min,"output_max":output_max,
        })
        item["reason"]=item.get("reason") or "assistant_authoritative_signal_discovery"
        item["discovery_authoritative_inputs"]=direct_authoritative
        prepared.append(item)
    # Validate global limits and dependency graph before the first persistent write.
    current_var_ids={row.get("variable_id") for row in all_defs}
    if len(current_var_ids)+missing_outputs>_CUSTOM_METRIC_MAX_VARIABLES:
        raise ValueError("Custom metric variable limit would be exceeded by this discovery design.")
    current_eq_ids={eq.get("equation_id") for eq in _cm_latest_equations(module,include_retired=True)}
    if len(current_eq_ids)+len(candidate_rows)>_CUSTOM_METRIC_MAX_EQUATIONS:
        raise ValueError("Custom metric equation limit would be exceeded by this discovery design.")
    _cm_graph_order(active_equations+candidate_rows)
    return prepared


def _ds_commit_design_answer(module, answer: object, *, provider: str, model: str) -> str:
    try:
        payload=_cm_parse_design_payload(answer)
        updates=_ds_preflight(module,list(payload.get("custom_metric_updates") or []))
    except Exception as exc:
        module._DERIVED_SIGNAL_LAST_DESIGN={"ok":False,"committed":False,"error":f"{type(exc).__name__}: {exc}","processed_at":_cm_now()}
        return (str(answer or "").strip()+f"\n\n[derived signal commit: 0 applied — preflight rejected; no metric state changed] {type(exc).__name__}: {exc}").strip()
    if not updates:
        module._DERIVED_SIGNAL_LAST_DESIGN={"ok":True,"committed":False,"operations":0,"applied":0,"processed_at":_cm_now()}
        return (payload["visible_response"].strip()+"\n\n[derived signal commit: 0 applied, deliberate no-change design]").strip()
    result=_cm_apply_updates(module,updates,provider=provider,model=model)
    rows=list(result.get("results") or [])
    applied=sum(1 for row in rows if row.get("ok")); rejected=[row for row in rows if not row.get("ok")]
    recalc=None
    if applied:
        try: recalc=_cm_recalculate(module,include_system=True)
        except Exception as exc: recalc={"ok":False,"error":f"{type(exc).__name__}: {exc}"}
    module._DERIVED_SIGNAL_LAST_DESIGN={
        "ok":not rejected,"committed":bool(applied),"operations":len(rows),"applied":applied,"rejected":len(rejected),
        "recalculation":recalc,"processed_at":_cm_now(),
    }
    summary=f"[derived signal commit: {applied} applied"
    if rejected: summary+=f", {len(rejected)} rejected"
    summary+="]"
    if rejected:
        summary+=" "+"; ".join(f"{row.get('action')}: {row.get('error')}" for row in rejected[:3])
    return (payload["visible_response"].strip()+"\n\n"+summary).strip()


def _ds_contract_text(module, purpose: str) -> str:
    workspace=_ds_workspace(module,purpose)
    raw=json.dumps(workspace,ensure_ascii=False,indent=2)
    if len(raw)>24000:
        raw=raw[:24000]+"\n[derived-signal workspace truncated]"
    return "\n\nDERIVED SIGNAL DISCOVERY WORKSPACE — READ-ONLY AUTHORITATIVE INPUTS\n"+raw


def _ds_handle_command(module, text: str) -> bool:
    command=str(text or "").strip(); lower=command.casefold()
    if not lower.startswith("/metrics discover"):
        return False
    try:
        body=command[len("/metrics discover"):].strip()
        body_lower=body.casefold()
        if body_lower=="design" or body_lower.startswith("design "):
            print("Use /metrics discover design <purpose> from normal chat so Assistant can review authoritative signals and apply a bounded design."); return True
        include_values=False
        if body_lower=="values" or body_lower.startswith("values "):
            include_values=True; body=body[len("values"):].strip()
        category=""
        if body.casefold().startswith("category "):
            rest=body[len("category "):].strip(); parts=rest.split(None,1); category=parts[0] if parts else ""; body=parts[1] if len(parts)>1 else ""
        print(json.dumps(_ds_catalog(module,query=body,category=category,include_values=include_values),ensure_ascii=False,indent=2)); return True
    except Exception as exc:
        print(f"Derived signal discovery error: {type(exc).__name__}: {exc}"); return True


def derived_signal_discovery_self_test(module=None) -> dict:
    if module is None: module=_load_memory()
    original_db_connect=module.db_connect; original_collector=globals().get("_perception_collect_metrics"); opened=[]; checks={}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-derived-signal-discovery-") as folder:
            db_path=Path(folder)/"signals.sqlite"
            def tracked_connect():
                db=sqlite3.connect(db_path); db.row_factory=sqlite3.Row; opened.append(db); return db
            def fake_collect(_module, query=""):
                return ({
                    "continuity.active_high_note_count":{"value":2,"unit":"count","description":"Active high-priority continuity notes.","category":"continuity","source_id":"SCS-test","confidence":1.0},
                    "continuity.active_mid_note_count":{"value":3,"unit":"count","description":"Active medium-priority continuity notes.","category":"continuity","source_id":"SCS-test","confidence":1.0},
                    "emotion.CURIOSITY.current":{"value":0.6,"unit":None,"description":"Current canonical curiosity strength.","category":"emotion","source_id":"EMO-test","confidence":1.0},
                },[])
            module.db_connect=tracked_connect; globals()["_perception_collect_metrics"]=fake_collect; _cm_ensure_schema(module)
            catalog=_ds_catalog(module,query="continuity notes",include_values=False)
            checks["authoritative_signals_are_read_only"]=catalog.get("count")==2 and all(row.get("authority")=="python_authoritative_read_only" and row.get("authoritative_writeback") is False for row in catalog.get("signals") or [])
            checks["discovery_hides_values_by_default"]=all("current_value" not in row for row in catalog.get("signals") or [])
            with_values=_ds_catalog(module,query="curiosity",include_values=True)
            checks["values_are_explicit_opt_in_snapshots"]=len(with_values.get("signals") or [])==1 and abs(float(with_values["signals"][0].get("current_value"))-0.6)<1e-9
            answer=json.dumps({"visible_response":"I want one descriptive continuity load signal.","custom_metric_updates":[{
                "action":"define_equation","name":"continuity_load_discovered","output_ref":"self.continuity_load_discovered","output_type":"count",
                "formula":"continuity.active_high_note_count + continuity.active_mid_note_count","purpose":"Summarize active high and medium continuity-note load.",
                "context_mode":"auto","semantic_role":"descriptive"}]})
            visible=_ds_commit_design_answer(module,answer,provider="self-test",model="python")
            eq=_cm_get_equation(module,"self.continuity_load_discovered",include_retired=False); state=_cm_state(module,recalculate=True,include_system=True)
            var=next((row for row in state.get("variables") or [] if row.get("ref")=="self.continuity_load_discovered"),None)
            checks["bounded_design_commits_safe_equation"]="derived signal commit: 1 applied" in visible and eq is not None and var is not None and abs(float((var.get("current") or {}).get("value"))-5.0)<1e-9
            checks["semantic_role_required_and_persisted"]=(eq or {}).get("semantic_role")=="descriptive"
            checks["authoritative_dependency_recorded"]=set(((eq or {}).get("validation") or {}).get("input_refs") or [])=={"continuity.active_high_note_count","continuity.active_mid_note_count"}
            before=len(_cm_latest_equations(module,include_retired=True))
            bad=json.dumps({"visible_response":"bad","custom_metric_updates":[{"action":"define_variable","ref":"self.bad","value_type":"float"}]})
            bad_visible=_ds_commit_design_answer(module,bad,provider="self-test",model="python")
            checks["non_equation_actions_rejected_before_commit"]=len(_cm_latest_equations(module,include_retired=True))==before and "0 applied" in bad_visible
            atomic_bad=json.dumps({"visible_response":"bad batch","custom_metric_updates":[
                {"action":"define_equation","name":"would_be_valid","output_ref":"self.would_be_valid","formula":"continuity.active_high_note_count + 1","purpose":"First proposal should not leak through a failed batch.","semantic_role":"descriptive"},
                {"action":"define_equation","name":"invalid_mode","output_ref":"self.invalid_mode","formula":"continuity.active_mid_note_count + 1","purpose":"Invalid context mode should fail preflight.","semantic_role":"descriptive","context_mode":"sometimes"}
            ]})
            atomic_visible=_ds_commit_design_answer(module,atomic_bad,provider="self-test",model="python")
            checks["full_batch_preflight_prevents_partial_commit"]=_cm_get_equation(module,"self.would_be_valid",include_retired=True) is None and _cm_get_equation(module,"self.invalid_mode",include_retired=True) is None and "0 applied" in atomic_visible
            no_auth=json.dumps({"visible_response":"bad","custom_metric_updates":[{"action":"define_equation","name":"copy","output_ref":"self.copy","formula":"continuity_load_discovered * 2","purpose":"No direct authority","semantic_role":"descriptive"}]})
            no_auth_visible=_ds_commit_design_answer(module,no_auth,provider="self-test",model="python")
            checks["direct_authoritative_input_required"]=_cm_get_equation(module,"self.copy",include_retired=True) is None and "0 applied" in no_auth_visible
            duplicate=json.dumps({"visible_response":"bad","custom_metric_updates":[{"action":"define_equation","name":"duplicate","output_ref":"self.continuity_load_discovered","formula":"continuity.active_high_note_count","purpose":"Duplicate","semantic_role":"descriptive"}]})
            duplicate_visible=_ds_commit_design_answer(module,duplicate,provider="self-test",model="python")
            checks["existing_output_duplication_rejected"]="0 applied" in duplicate_visible and int((_cm_get_equation(module,"self.continuity_load_discovered") or {}).get("version",0))==1
            nochange=_ds_commit_design_answer(module,json.dumps({"visible_response":"Nothing else is useful.","custom_metric_updates":[]}),provider="self-test",model="python")
            checks["deliberate_no_change_supported"]="deliberate no-change design" in nochange
            checks["discovery_never_adds_authoritative_writeback"]=(eq or {}).get("authoritative_writeback") is False
            groups=_adaptive_tool_query_groups("discover authoritative signals for a useful derived equation",("system","personal"))
            selected,_=_adaptive_tool_select(list(module.TOOL_SCHEMAS),"discover authoritative signals for a useful derived equation",("system","personal")); names=[_adaptive_tool_name(item) for item in selected]
            checks["adaptive_catalog_exposes_signal_discovery"]="metrics" in groups and "discover_authoritative_signals" in names
            for db in reversed(opened):
                try: db.close()
                except Exception: pass
            opened.clear()
    finally:
        for db in reversed(opened):
            try: db.close()
            except Exception: pass
        module.db_connect=original_db_connect
        if original_collector is None: globals().pop("_perception_collect_metrics",None)
        else: globals()["_perception_collect_metrics"]=original_collector
    return {"ok":all(bool(value) for value in checks.values()),"checks":checks,"version":_DERIVED_SIGNAL_DISCOVERY_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


def _install_derived_signal_discovery(module) -> None:
    if getattr(module,"_DERIVED_SIGNAL_DISCOVERY_INSTALLED",False): return
    module.DERIVED_SIGNAL_DISCOVERY_VERSION=_DERIVED_SIGNAL_DISCOVERY_VERSION
    module.discover_authoritative_signals=lambda query="",category="",include_values=False,limit=_DERIVED_SIGNAL_MAX_RESULTS:_ds_catalog(module,query=query,category=category,include_values=include_values,limit=limit)
    module.derived_signal_discovery_self_test=lambda:derived_signal_discovery_self_test(module)
    module.TOOL_SCHEMAS.append({"type":"function","function":{
        "name":"discover_authoritative_signals",
        "description":"Inspect grouped Python-authoritative read-only numeric/boolean signals that Assistant may reference in safe derived equations. Values are hidden unless explicitly requested.",
        "parameters":{"type":"object","properties":{"query":{"type":"string"},"category":{"type":"string"},"include_values":{"type":"boolean"},"limit":{"type":"integer","minimum":1,"maximum":180}},"additionalProperties":False},
    }})
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("discover_authoritative_signals")
    old_execute=module.execute_tool
    def execute_with_discovery(name,arguments,seen,*args,**kwargs):
        if name=="discover_authoritative_signals": return module.discover_authoritative_signals(**arguments)
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_with_discovery

    old_build=module.build_runtime_context
    def build_with_discovery(query,*args,**kwargs):
        result=old_build(query,*args,**kwargs)
        if _DERIVED_SIGNAL_DESIGN_MARKER in str(query or ""):
            purpose=str(query or "").split("Purpose requested by Steeve:",1)[-1].split("\n",1)[0].strip()
            result+=_ds_contract_text(module,purpose)
        return result
    module.build_runtime_context=build_with_discovery

    old_local=module.run_local_turn
    def run_local_with_discovery(backend,messages,query=None,*,allow_sticky=True):
        if query is None: return old_local(backend,messages,allow_sticky=allow_sticky)
        answer=old_local(backend,messages,query,allow_sticky=allow_sticky)
        if _DERIVED_SIGNAL_DESIGN_MARKER in str(query or ""):
            return _ds_commit_design_answer(module,answer,provider="local",model=getattr(backend,"model_id","local"))
        return answer
    module.run_local_turn=run_local_with_discovery
    old_online=module.run_online_chat_turn
    def run_online_with_discovery(backend,messages,query):
        answer=old_online(backend,messages,query)
        if _DERIVED_SIGNAL_DESIGN_MARKER in str(query or ""):
            return _ds_commit_design_answer(module,answer,provider="online",model=getattr(backend,"model_id","online"))
        return answer
    module.run_online_chat_turn=run_online_with_discovery

    old_main=module.main
    def main_with_discovery_commands():
        previous=builtins.input
        def discovery_input(prompt=""):
            while True:
                value=previous(prompt); compact=" ".join(str(value or "").strip().split()); lower=compact.casefold()
                if lower=="/metrics discover design" or lower.startswith("/metrics discover design "):
                    purpose=compact[len("/metrics discover design"):].strip(); return _ds_design_prompt(purpose)
                if _ds_handle_command(module,value): continue
                return value
        builtins.input=discovery_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_discovery_commands

    old_help=module.print_help
    def help_with_discovery(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /metrics discover [query] | /metrics discover values [query] | /metrics discover design [purpose]")
    module.print_help=help_with_discovery
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["derived-signal-discovery"]={"label":"Assistant-controlled read-only authoritative signal discovery and bounded all-preflight derived-equation design","groups":("quick","critical","all"),"runner":"memory.derived_signal_discovery_self_test"}
    module.RELEASE_NAME=RELEASE_NAME; module._DERIVED_SIGNAL_DISCOVERY_INSTALLED=True


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:provider-startup rev=2
# Provider-agnostic / lazy local startup (7.4.25.10.13.7.1)
# ---------------------------------------------------------------------------
# Startup must not require LM Studio (or any OpenAI-compatible local endpoint)
# to be reachable.  This layer deliberately does NOT auto-fallback from a
# private/local endpoint to Vast or online.  It only defers the connection
# until a local model operation is actually requested, or until the user
# explicitly switches endpoint with /endpoint or --endpoint.
_PROVIDER_AGNOSTIC_STARTUP_VERSION = "1.0-lazy-local-backend-no-implicit-fallback"
_DEFERRED_LOCAL_MODEL_ID = "<local-model-deferred-until-use>"
_LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS = 14_400


def _local_backend_is_deferred(backend) -> bool:
    return bool(backend is not None and str(getattr(backend, "model_id", "") or "") == _DEFERRED_LOCAL_MODEL_ID)


def _make_deferred_local_backend(module, error: BaseException | None = None):
    # Constructing the OpenAI client does not perform network I/O.  The endpoint
    # remains the explicitly selected local profile; no remote fallback occurs.
    client = module.OpenAI(
        base_url=module.LOCAL_BASE_URL,
        api_key=module.LOCAL_API_KEY,
        timeout=module.LOCAL_REQUEST_TIMEOUT_SECONDS,
    )
    backend = module.LocalBackend(client=client, model_id=_DEFERRED_LOCAL_MODEL_ID, provider="local")
    module._LOCAL_STARTUP_BACKEND_STATE = {
        "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION,
        "startup_allowed": True,
        "connected": False,
        "deferred": True,
        "profile": str(getattr(module, "LOCAL_ENDPOINT_PROFILE", "local") or "local"),
        "url": str(getattr(module, "LOCAL_BASE_URL", "") or ""),
        "model": None,
        "last_error": (f"{type(error).__name__}: {error}" if error is not None else None),
        "implicit_fallback": False,
    }
    return backend


def _make_startup_tolerant_builder(module, strict_builder):
    state = {"startup_probe_pending": True}

    def build_local_backend_startup_tolerant():
        # The first call is the historical unconditional startup probe.  Let it
        # succeed normally when the endpoint is up, but convert only connection
        # failure into a deferred backend so NeatMemory itself can still start.
        if state["startup_probe_pending"]:
            state["startup_probe_pending"] = False
            try:
                backend = strict_builder()
            except Exception as exc:
                return _make_deferred_local_backend(module, exc)
            module._LOCAL_STARTUP_BACKEND_STATE = {
                "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION,
                "startup_allowed": True,
                "connected": True,
                "deferred": False,
                "profile": str(getattr(module, "LOCAL_ENDPOINT_PROFILE", "local") or "local"),
                "url": str(getattr(module, "LOCAL_BASE_URL", "") or ""),
                "model": str(getattr(backend, "model_id", "") or "") or None,
                "last_error": None,
                "implicit_fallback": False,
            }
            return backend
        # Every explicit later build (/endpoint switch, reflection backend,
        # digest backend, etc.) remains strict and therefore cannot pretend an
        # unreachable endpoint is healthy.  A successful explicit build also
        # refreshes the read-only startup/backend diagnostic state.
        backend = strict_builder()
        module._LOCAL_STARTUP_BACKEND_STATE = {
            "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION,
            "startup_allowed": True,
            "connected": True,
            "deferred": False,
            "profile": str(getattr(module, "LOCAL_ENDPOINT_PROFILE", "local") or "local"),
            "url": str(getattr(module, "LOCAL_BASE_URL", "") or ""),
            "model": str(getattr(backend, "model_id", "") or "") or None,
            "last_error": None,
            "implicit_fallback": False,
        }
        return backend

    return build_local_backend_startup_tolerant, state


def _resolve_deferred_local_backend(module, backend, strict_builder):
    if not _local_backend_is_deferred(backend):
        return backend
    resolved = strict_builder()  # strict: errors are reported by the caller
    # LocalBackend is mutable; updating in place also updates the backend object
    # retained by the historical interactive main loop.
    backend.client = resolved.client
    backend.model_id = resolved.model_id
    backend.provider = getattr(resolved, "provider", "local")
    module._LOCAL_STARTUP_BACKEND_STATE = {
        "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION,
        "startup_allowed": True,
        "connected": True,
        "deferred": False,
        "profile": str(getattr(module, "LOCAL_ENDPOINT_PROFILE", "local") or "local"),
        "url": str(getattr(module, "LOCAL_BASE_URL", "") or ""),
        "model": str(getattr(resolved, "model_id", "") or "") or None,
        "last_error": None,
        "implicit_fallback": False,
    }
    return backend


def provider_agnostic_startup_self_test(module) -> dict:
    calls = {"count": 0}

    def unavailable_builder():
        calls["count"] += 1
        raise ConnectionError("synthetic endpoint unavailable")

    tolerant, state = _make_startup_tolerant_builder(module, unavailable_builder)
    first = tolerant()
    checks = {
        "first_unavailable_probe_does_not_raise": _local_backend_is_deferred(first),
        "first_probe_attempted_once": calls["count"] == 1,
        "startup_probe_consumed": state.get("startup_probe_pending") is False,
        "no_implicit_fallback": (getattr(module, "_LOCAL_STARTUP_BACKEND_STATE", {}) or {}).get("implicit_fallback") is False,
        "local_timeout_default_is_four_hours": int(getattr(module, "LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS", 0) or 0) == 14_400,
        "local_timeout_respects_environment_override": int(getattr(module, "LOCAL_REQUEST_TIMEOUT_SECONDS", 0) or 0) == max(60, int(module.env_int("LOCAL_REQUEST_TIMEOUT_SECONDS", _LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS))),
    }
    try:
        tolerant()
        checks["later_explicit_build_is_strict"] = False
    except ConnectionError:
        checks["later_explicit_build_is_strict"] = calls["count"] == 2

    resolved_calls = {"count": 0}

    def available_builder():
        resolved_calls["count"] += 1
        return module.LocalBackend(client=object(), model_id="MODEL-READY", provider="local")

    deferred = module.LocalBackend(client=object(), model_id=_DEFERRED_LOCAL_MODEL_ID, provider="local")
    resolved = _resolve_deferred_local_backend(module, deferred, available_builder)
    checks.update({
        "deferred_resolves_on_local_use": resolved is deferred and resolved.model_id == "MODEL-READY",
        "resolution_is_in_place": resolved_calls["count"] == 1,
        "status_marks_connected": (getattr(module, "_LOCAL_STARTUP_BACKEND_STATE", {}) or {}).get("connected") is True,
    })
    return {"ok": all(bool(v) for v in checks.values()), "checks": checks, "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION}


def _install_provider_agnostic_startup(module) -> None:
    if getattr(module, "_PROVIDER_AGNOSTIC_STARTUP_INSTALLED", False):
        return

    # .223: large local models may legitimately generate for well over one hour.
    # Keep the existing environment override, but make four hours the assembled
    # default instead of the historical one-hour core default.
    module.LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS = int(_LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS)
    module.LOCAL_REQUEST_TIMEOUT_SECONDS = max(
        60,
        int(module.env_int("LOCAL_REQUEST_TIMEOUT_SECONDS", _LOCAL_REQUEST_TIMEOUT_DEFAULT_SECONDS)),
    )

    # The historical embedded core defines endpoint normalization helpers but
    # did not import urllib.parse names into its own module namespace.  Export
    # the wrapper's already-imported helpers so /endpoint vast/custom remains
    # usable after a deferred startup.
    module.urlsplit = urlsplit
    module.urlunsplit = urlunsplit

    strict_build = module.build_local_backend
    tolerant_build, startup_state = _make_startup_tolerant_builder(module, strict_build)
    module._STRICT_BUILD_LOCAL_BACKEND = strict_build
    module._LOCAL_STARTUP_PROBE_STATE = startup_state
    module.build_local_backend = tolerant_build
    module.resolve_local_backend_if_needed = lambda backend: _resolve_deferred_local_backend(module, backend, strict_build)
    module.local_startup_backend_status = lambda: dict(getattr(module, "_LOCAL_STARTUP_BACKEND_STATE", {}) or {
        "version": _PROVIDER_AGNOSTIC_STARTUP_VERSION,
        "startup_allowed": True,
        "connected": None,
        "deferred": None,
        "implicit_fallback": False,
    })
    module.provider_agnostic_startup_self_test = lambda: provider_agnostic_startup_self_test(module)

    # Normal local chat and /ask local: transparently resolve the deferred model
    # at the moment it is actually needed.  If still unreachable, the existing
    # per-turn exception handler reports the error without terminating memory.
    old_run_local_turn = module.run_local_turn
    def run_local_turn_lazy(backend, *args, **kwargs):
        backend = _resolve_deferred_local_backend(module, backend, strict_build)
        return old_run_local_turn(backend, *args, **kwargs)
    module.run_local_turn = run_local_turn_lazy

    # The historical main loop passes its startup backend into these operations.
    # Resolve that same object in place only when the selected provider is local.
    for function_name in ("run_benchmark_pilot738", "run_benchmark_retrieval_levels"):
        original = getattr(module, function_name, None)
        if not callable(original):
            continue
        def make_wrapper(fn):
            def wrapped(local_backend, active_provider, *args, **kwargs):
                if str(active_provider or "").casefold() == "local":
                    local_backend = _resolve_deferred_local_backend(module, local_backend, strict_build)
                return fn(local_backend, active_provider, *args, **kwargs)
            return wrapped
        setattr(module, function_name, make_wrapper(original))

    original_test_suite = getattr(module, "run_memory_retrieval_test_suite", None)
    if callable(original_test_suite):
        def retrieval_test_lazy(provider, local_backend, online_backend, *args, **kwargs):
            if str(provider or "").casefold() == "local":
                local_backend = _resolve_deferred_local_backend(module, local_backend, strict_build)
            return original_test_suite(provider, local_backend, online_backend, *args, **kwargs)
        module.run_memory_retrieval_test_suite = retrieval_test_lazy

    # Local research receives the main-loop backend directly.  Resolve only a
    # deferred backend; online research is untouched.
    for function_name in ("run_research_loop", "run_autonomous_research_loop"):
        original = getattr(module, function_name, None)
        if not callable(original):
            continue
        def make_research_wrapper(fn):
            def wrapped(backend, *args, **kwargs):
                backend = _resolve_deferred_local_backend(module, backend, strict_build)
                return fn(backend, *args, **kwargs)
            return wrapped
        setattr(module, function_name, make_research_wrapper(original))

    # Add a compact read-only diagnostic without changing the existing endpoint
    # command contract.
    old_endpoint_status = module.local_endpoint_status
    def endpoint_status_with_startup_state():
        out = dict(old_endpoint_status())
        out["startup_backend"] = module.local_startup_backend_status()
        return out
    module.local_endpoint_status = endpoint_status_with_startup_state

    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["provider-agnostic-startup"] = {
            "label": "NeatMemory starts with local endpoint offline; local backend resolves lazily without implicit fallback",
            "groups": ("quick", "critical", "all"),
            "runner": "memory.provider_agnostic_startup_self_test",
        }
    module.PROVIDER_AGNOSTIC_STARTUP_VERSION = _PROVIDER_AGNOSTIC_STARTUP_VERSION
    module._PROVIDER_AGNOSTIC_STARTUP_INSTALLED = True


