# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:provider-status-reporting rev=1
# NeatMemory 7.4.78.12 — truthful active/configured/unverified provider display
# ---------------------------------------------------------------------------
_PROVIDER_STATUS_REPORTING_VERSION = "1.0-active-provider-configured-local-tristate-verification"


def _psr_yes_no_unknown(value, unknown_note: str = "not verified in this process") -> str:
    if value is True:
        return "yes"
    if value is False:
        return "no"
    return f"unknown ({unknown_note})"


def _psr_runtime_status(module, *, backend, active_provider: str, online_backend=None) -> dict:
    provider = str(active_provider or "local").strip().casefold()
    if provider not in {"local", "online"}:
        provider = "local"
    startup = dict(getattr(module, "_LOCAL_STARTUP_BACKEND_STATE", {}) or {})
    configured_local = str(getattr(module, "LOCAL_MODEL_ENV", "") or "").strip()
    backend_model = str(getattr(backend, "model_id", "") or "").strip()
    deferred_id = str(globals().get("_DEFERRED_LOCAL_MODEL_ID") or "<local-model-deferred-until-use>")
    if not configured_local and backend_model and backend_model != deferred_id:
        configured_local = backend_model
    if not configured_local:
        configured_local = "automatic /v1/models discovery"

    if provider == "online":
        active_model = str(getattr(online_backend, "model_id", "") or getattr(module, "ONLINE_MODEL_ENV", "") or "").strip()
        active_initialized = online_backend is not None
    else:
        active_model = backend_model if backend_model and backend_model != deferred_id else configured_local
        active_initialized = backend_model != deferred_id

    configured_shortcut = bool(str(getattr(module, "LOCAL_MODEL_ENV", "") or "").strip())
    deferred = bool(startup.get("deferred")) or backend_model == deferred_id
    last_error = str(startup.get("last_error") or "").strip() or None
    if deferred and last_error:
        endpoint_reachable = False
        model_loaded = False
        verification_basis = "startup endpoint/model probe failed"
    elif configured_shortcut:
        # select_local_model returns LOCAL_MODEL_ENV without contacting /v1/models.
        # A configured identifier is not mechanical evidence that the endpoint or
        # model is currently reachable/loaded.
        endpoint_reachable = None
        model_loaded = None
        verification_basis = "configured model identifier; /v1/models was not required and no load claim is made"
    elif startup.get("connected") is True and startup.get("model"):
        endpoint_reachable = True
        model_loaded = True
        verification_basis = "successful /v1/models discovery during this process"
    elif startup.get("connected") is False:
        endpoint_reachable = False
        model_loaded = False
        verification_basis = "last recorded local startup probe failed"
    else:
        endpoint_reachable = None
        model_loaded = None
        verification_basis = "local endpoint has not been mechanically verified in this process"

    return {
        "version": str(getattr(module, "NEATMEMORY_VERSION", BUNDLE_VERSION)),
        "schema": str(getattr(module, "SCHEMA_VERSION", "")),
        "database": str(module.database_path()),
        "active_provider": provider,
        "active_model": active_model or "unconfigured",
        "active_backend_initialized": bool(active_initialized),
        "configured_local_model": configured_local,
        "local_endpoint_profile": str(getattr(module, "LOCAL_ENDPOINT_PROFILE", "local") or "local"),
        "local_endpoint_url": str(getattr(module, "LOCAL_BASE_URL", "") or ""),
        "local_endpoint_reachable": endpoint_reachable,
        "local_model_loaded": model_loaded,
        "local_verification_basis": verification_basis,
        "local_last_error": last_error,
        "read_only": True,
        "network_probe_performed_by_command": False,
    }


def _psr_runtime_status_text(module, *, backend, active_provider: str, online_backend=None) -> str:
    status = _psr_runtime_status(module, backend=backend, active_provider=active_provider, online_backend=online_backend)
    lines = [
        f"NeatMemory: {status['version']}",
        f"Schema: {status['schema']}",
        f"Database: {status['database']}",
        f"Active provider: {status['active_provider']}",
        f"Active model: {status['active_model']}",
        f"Active backend initialized: {'yes' if status['active_backend_initialized'] else 'no'}",
        f"Configured local model: {status['configured_local_model']}",
        f"Local endpoint: {status['local_endpoint_profile']} ({status['local_endpoint_url']})",
        f"Local endpoint reachable: {_psr_yes_no_unknown(status['local_endpoint_reachable'])}",
        f"Local model loaded: {_psr_yes_no_unknown(status['local_model_loaded'])}",
        f"Local verification: {status['local_verification_basis']}",
    ]
    if status.get("local_last_error"):
        lines.append(f"Last local error: {status['local_last_error']}")
    return "\n".join(lines)


def provider_status_reporting_self_test(module=None) -> dict:
    if module is None:
        module = _load_memory()
    class FakeModule:
        NEATMEMORY_VERSION = "TEST"
        SCHEMA_VERSION = "2.3"
        LOCAL_MODEL_ENV = "configured-local-model"
        ONLINE_MODEL_ENV = "configured-online-model"
        LOCAL_ENDPOINT_PROFILE = "lmstudio"
        LOCAL_BASE_URL = "http://127.0.0.1:1234/v1"
        _LOCAL_STARTUP_BACKEND_STATE = {"connected": True, "deferred": False, "model": "configured-local-model", "last_error": None}
        @staticmethod
        def database_path():
            return Path("test.db")
    local_backend = type("Backend", (), {"model_id": "configured-local-model"})()
    online_backend = type("Backend", (), {"model_id": "online-live-model"})()
    online = _psr_runtime_status(FakeModule, backend=local_backend, active_provider="online", online_backend=online_backend)
    online_text = _psr_runtime_status_text(FakeModule, backend=local_backend, active_provider="online", online_backend=online_backend)
    FakeModule.LOCAL_MODEL_ENV = ""
    FakeModule._LOCAL_STARTUP_BACKEND_STATE = {"connected": True, "deferred": False, "model": "discovered-local-model", "last_error": None}
    discovered_backend = type("Backend", (), {"model_id": "discovered-local-model"})()
