# >>> NEAT-SUBSYSTEM:strict-local-chat-protocol rev=1
# NeatMemory 7.4.78.46 — provider-boundary role normalization for strict local chat templates
# ---------------------------------------------------------------------------
_STRICT_LOCAL_CHAT_PROTOCOL_VERSION = "1.0-provider-boundary-role-alternation"
_STRICT_LOCAL_OBSERVATION_TOOLS = frozenset()


class _StrictLocalProtocolError(RuntimeError):
    pass


def _slcp_message_dict(message):
    if isinstance(message, dict):
        return dict(message)
    dump=getattr(message,"model_dump",None)
    if callable(dump):
        try: return dict(dump(exclude_none=True))
        except TypeError: return dict(dump())
    raise _StrictLocalProtocolError(f"Unsupported local chat message type: {type(message).__name__}")


def _slcp_content_text(message: dict) -> str:
    value=message.get("content")
    if value is None: return ""
    if isinstance(value,str): return value
    # Structured multimodal content is not rewritten. JSON gives a stable exact envelope if merge is needed.
    try: return json.dumps(value,ensure_ascii=False,separators=(",",":"))
    except Exception: return str(value)


def _slcp_has_tool_calls(message: dict) -> bool:
    calls=message.get("tool_calls")
    return bool(calls)


def _slcp_merge_same_role(left: dict, right: dict, role: str) -> dict:
    # Only ordinary same-role messages are merged. Tool-call assistant messages are never merged.
    if role=="assistant" and (_slcp_has_tool_calls(left) or _slcp_has_tool_calls(right)):
        raise _StrictLocalProtocolError("Cannot merge adjacent assistant messages when either carries tool_calls.")
    merged=dict(left)
    ltext=_slcp_content_text(left)
    rtext=_slcp_content_text(right)
    separator="\n\n[CONTINUED USER MESSAGE]\n" if role=="user" else "\n\n[CONTINUED ASSISTANT MESSAGE]\n"
    merged["content"]=(ltext+separator+rtext) if ltext and rtext else (ltext or rtext)
    # Preserve only fields that do not conflict. Same-role public history is normally content-only.
    for key,value in right.items():
        if key in {"role","content"}: continue
        if key not in merged: merged[key]=value
        elif merged[key]!=value:
            raise _StrictLocalProtocolError(f"Cannot safely merge adjacent {role} messages with conflicting field {key!r}.")
    return merged


def _slcp_validate_messages(messages: list[dict]) -> tuple[bool,str|None]:
    if not messages: return False,"empty message list"
    idx=0
    if messages[0].get("role") in {"system","developer"}:
        idx=1
    if idx>=len(messages): return True,None
    body=messages[idx:]
    if body and body[0].get("role")!="user":
        return False,f"first conversational role is {body[0].get('role')!r}, expected 'user'"
    last_dialogue=None
    in_tool_block=False
    for pos,msg in enumerate(body,start=idx):
        role=str(msg.get("role") or "")
        if role in {"system","developer"}:
            return False,f"late {role} message at index {pos}"
        if role=="tool":
            if not in_tool_block:
                return False,f"orphan tool result at index {pos}"
            continue
        if role=="user":
            if in_tool_block:
                return False,f"user message at index {pos} interrupts an unfinished tool-result block"
            if last_dialogue=="user":
                return False,f"adjacent user messages at index {pos}"
            last_dialogue="user"
            continue
        if role=="assistant":
            if in_tool_block:
                # Assistant consumes the preceding tool result(s); this is the tool-call exception.
                in_tool_block=False
                last_dialogue="assistant"
            else:
                if last_dialogue=="assistant":
                    return False,f"adjacent assistant messages at index {pos}"
                last_dialogue="assistant"
            if _slcp_has_tool_calls(msg):
                in_tool_block=True
            continue
        return False,f"unsupported role {role!r} at index {pos}"
    return True,None


def _slcp_normalize_messages(messages) -> tuple[list[dict],dict]:
    original=[_slcp_message_dict(m) for m in list(messages or [])]
    input_roles=[str(m.get("role") or "") for m in original]
    if not original:
        raise _StrictLocalProtocolError("Local chat request has no messages.")

    system_parts=[]
    system_base=None
    body=[]
    moved_system=0
    for i,msg in enumerate(original):
        role=str(msg.get("role") or "")
        if role in {"system","developer"}:
            if system_base is None:
                system_base=dict(msg); system_base["role"]="system"
            else:
                moved_system+=1
            text=_slcp_content_text(msg)
            if text: system_parts.append(text)
        else:
            body.append(dict(msg))
    if system_base is not None:
        system_base["content"]="\n\n[ADDITIONAL SYSTEM CONTEXT]\n".join(system_parts)

    # A token-tail trim can begin on an assistant turn whose user half was clipped.
    # Drop that orphan prefix rather than inventing a synthetic user or promoting assistant text to system authority.
    dropped_orphan_prefix=0
    while body and str(body[0].get("role") or "")!="user":
        dropped_orphan_prefix+=1
        body.pop(0)
    if not body:
        raise _StrictLocalProtocolError("Strict local normalization found no retained user turn after removing orphan prefix messages.")

    out_body=[]
    merged_same_role=0
    for msg in body:
        role=str(msg.get("role") or "")
        if role in {"user","assistant"} and out_body and str(out_body[-1].get("role") or "")==role:
            # Do not merge across tool semantics; those must remain exact API records.
            if role=="assistant" and (_slcp_has_tool_calls(out_body[-1]) or _slcp_has_tool_calls(msg)):
                out_body.append(msg)
            else:
                out_body[-1]=_slcp_merge_same_role(out_body[-1],msg,role)
                merged_same_role+=1
        else:
            out_body.append(msg)

    normalized=([system_base] if system_base is not None else [])+out_body
    valid,error=_slcp_validate_messages(normalized)
    if not valid:
        raise _StrictLocalProtocolError(f"Unable to safely normalize local chat roles: {error}; roles={[m.get('role') for m in normalized]}")
    output_roles=[str(m.get("role") or "") for m in normalized]
    report={
        "version":_STRICT_LOCAL_CHAT_PROTOCOL_VERSION,
        "changed":normalized!=original,
        "input_roles":input_roles,
        "output_roles":output_roles,
        "moved_or_merged_system_messages":moved_system,
        "dropped_orphan_prefix_messages":dropped_orphan_prefix,
        "merged_same_role_messages":merged_same_role,
        "tool_messages_preserved":sum(1 for m in normalized if m.get("role")=="tool"),
        "tool_call_messages_preserved":sum(1 for m in normalized if m.get("role")=="assistant" and _slcp_has_tool_calls(m)),
        "valid":True,
        "semantic_content_rewritten":False,
        "authority_rule":"Provider protocol normalization only: exact message content is preserved except same-role concatenation; orphan assistant/tool prefixes created by tail trimming are omitted rather than reclassified.",
    }
    return normalized,report


class _SLCPCompletionsProxy:
    def __init__(self,module,inner): self._module=module; self._inner=inner
    def __getattr__(self,name): return getattr(self._inner,name)
    def create(self,*args,**kwargs):
        if "messages" in kwargs:
            controller = globals().get("_mcp_control_local_messages")
            controlled = controller(self._module, kwargs.get("messages") or []) if callable(controller) else (kwargs.get("messages") or [])
            normalized,report=_slcp_normalize_messages(controlled)
            kwargs=dict(kwargs); kwargs["messages"]=normalized
            self._module._STRICT_LOCAL_CHAT_PROTOCOL_LAST=report
            if report.get("changed"):
                print(
                    "[local protocol] strict roles normalized"
                    f" | orphan-prefix -{int(report.get('dropped_orphan_prefix_messages') or 0)}"
                    f" | same-role merges {int(report.get('merged_same_role_messages') or 0)}"
                    f" | late-system merges {int(report.get('moved_or_merged_system_messages') or 0)}",
                    flush=True,
                )
            logger=getattr(self._module,"append_diagnostic_log",None)
            if callable(logger):
                try: logger("provider.local_protocol_normalized","Local chat role grammar checked before provider call.",subsystem="provider",provider="local",details=report)
                except Exception: pass
        return self._inner.create(*args,**kwargs)


class _SLCPChatProxy:
    def __init__(self,module,inner):
        self._inner=inner
        self.completions=_SLCPCompletionsProxy(module,inner.completions)
    def __getattr__(self,name): return getattr(self._inner,name)


class _SLCPClientProxy:
    _STRICT_LOCAL_CHAT_PROTOCOL_PROXY=True
    def __init__(self,module,inner):
        self._module=module; self._inner=inner; self.chat=_SLCPChatProxy(module,inner.chat)
    def __getattr__(self,name): return getattr(self._inner,name)
    def with_options(self,*args,**kwargs):
        fn=getattr(self._inner,"with_options",None)
        if not callable(fn): raise AttributeError("with_options")
        return _SLCPClientProxy(self._module,fn(*args,**kwargs))


def _slcp_wrap_backend(module,backend):
    if backend is None: return backend
    client=getattr(backend,"client",None)
    if client is None: return backend
    if not getattr(client,"_STRICT_LOCAL_CHAT_PROTOCOL_PROXY",False):
        backend.client=_SLCPClientProxy(module,client)
    return backend


def strict_local_chat_protocol_self_test(module=None) -> dict:
    class FakeCompletions:
        def __init__(self): self.calls=[]
        def create(self,*args,**kwargs):
            self.calls.append(dict(kwargs))
            ok,err=_slcp_validate_messages(kwargs.get("messages") or [])
            if not ok: raise AssertionError(err)
            return {"ok":True}
    class FakeChat:
        def __init__(self): self.completions=FakeCompletions()
    class FakeClient:
        def __init__(self): self.chat=FakeChat(); self.models=object()
    fake_module=module if module is not None else type("M",(),{})()
    setattr(fake_module,"_STRICT_LOCAL_CHAT_PROTOCOL_LAST",{})
    # Tail-trim shape that triggered Ministral: assistant orphan before current user.
    m1=[{"role":"system","content":"S"},{"role":"assistant","content":"old A"},{"role":"user","content":"current U"}]
    n1,r1=_slcp_normalize_messages(m1)
    # Same-role public history is merged, not semantically reclassified.
    m2=[{"role":"system","content":"S"},{"role":"user","content":"u1"},{"role":"user","content":"u2"},{"role":"assistant","content":"a1"},{"role":"assistant","content":"a2"},{"role":"user","content":"u3"}]
    n2,r2=_slcp_normalize_messages(m2)
    # Tool-call/result exception remains byte-for-byte structurally present.
    tc={"role":"assistant","content":None,"tool_calls":[{"id":"call-1","type":"function","function":{"name":"x","arguments":"{}"}}]}
    tr={"role":"tool","tool_call_id":"call-1","content":"{\"ok\":true}"}
    m3=[{"role":"system","content":"S"},{"role":"user","content":"u"},tc,tr,{"role":"assistant","content":"done"},{"role":"user","content":"next"}]
    n3,r3=_slcp_normalize_messages(m3)
    # Late extra system/developer context is consolidated into the single initial system role.
    m4=[{"role":"system","content":"S1"},{"role":"developer","content":"S2"},{"role":"user","content":"u"}]
    n4,r4=_slcp_normalize_messages(m4)
    inner=FakeClient(); proxy=_SLCPClientProxy(fake_module,inner)
    proxy.chat.completions.create(model="fake",messages=m1)
    sent=inner.chat.completions.calls[-1]["messages"]
    checks={
        "orphan_assistant_prefix_removed": [x.get("role") for x in n1]==["system","user"] and r1.get("dropped_orphan_prefix_messages")==1,
        "same_role_messages_merged": [x.get("role") for x in n2]==["system","user","assistant","user"] and r2.get("merged_same_role_messages")==2,
        "merged_content_preserves_both_user_messages": "u1" in n2[1].get("content","") and "u2" in n2[1].get("content",""),
        "tool_call_id_preserved": any(x.get("tool_call_id")=="call-1" for x in n3),
        "tool_call_message_preserved": any(x.get("role")=="assistant" and x.get("tool_calls") for x in n3),
        "tool_sequence_valid": _slcp_validate_messages(n3)[0] is True,
        "single_initial_system_after_consolidation": [x.get("role") for x in n4]==["system","user"] and "S1" in n4[0].get("content","") and "S2" in n4[0].get("content",""),
        "proxy_normalizes_before_delegate": [x.get("role") for x in sent]==["system","user"],
        "normalizer_has_zero_model_calls": True,
        "normalizer_has_zero_web_calls": True,
    }
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_STRICT_LOCAL_CHAT_PROTOCOL_VERSION,"model_calls":0,"web_calls":0,"persistent_writes":False,"sample_reports":{"orphan":r1,"merge":r2,"tool":r3,"system":r4}}


def _install_strict_local_chat_protocol(module) -> None:
    if getattr(module,"_STRICT_LOCAL_CHAT_PROTOCOL_INSTALLED",False): return
    module._STRICT_LOCAL_CHAT_PROTOCOL_LAST={"version":_STRICT_LOCAL_CHAT_PROTOCOL_VERSION,"status":"not-yet-used"}

    old_build=getattr(module,"build_local_backend",None)
    if callable(old_build):
        def build_local_backend_strict_protocol(*args,**kwargs):
            return _slcp_wrap_backend(module,old_build(*args,**kwargs))
        module.build_local_backend=build_local_backend_strict_protocol

    # A deferred startup backend may be resolved through a closure that predates this installer.
    # Resolve first, then decorate the in-place client before entering the historical local turn.
    old_run=getattr(module,"run_local_turn",None)
    if callable(old_run):
        def run_local_turn_strict_protocol(backend,*args,**kwargs):
            resolver=getattr(module,"resolve_local_backend_if_needed",None)
            if callable(resolver): backend=resolver(backend)
            backend=_slcp_wrap_backend(module,backend)
            return old_run(backend,*args,**kwargs)
        module.run_local_turn=run_local_turn_strict_protocol

    module.normalize_local_chat_messages=lambda messages:_slcp_normalize_messages(messages)
    module.get_strict_local_chat_protocol_status=lambda:dict(getattr(module,"_STRICT_LOCAL_CHAT_PROTOCOL_LAST",{}) or {})
    module.strict_local_chat_protocol_self_test=lambda:strict_local_chat_protocol_self_test(module)
    module.STRICT_LOCAL_CHAT_PROTOCOL_VERSION=_STRICT_LOCAL_CHAT_PROTOCOL_VERSION
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["strict-local-chat-protocol"]={
            "label":"Local chat provider boundary normalizes strict user/assistant alternation while preserving tool-call/result blocks",
            "groups":("quick","critical","all"),
            "runner":"memory.strict_local_chat_protocol_self_test",
        }
    module._STRICT_LOCAL_CHAT_PROTOCOL_INSTALLED=True


