def _self_test_json_safe(value):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, dict):
        return {str(key): _self_test_json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_self_test_json_safe(item) for item in value]
    return repr(value)


def _self_test_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _ensure_openai_self_test_stub() -> None:
    # Compatibility name retained for old self-test callers. The provider client is
    # now an embedded NeatMemory-owned module, so no external-package stub is needed.
    _load_embedded("neatopenai_http_v1")


def _load_self_test_environment() -> dict:
    _ensure_openai_self_test_stub()
    memory = _load_memory()
    digest = _load_digest()
    return {
        "memory": memory,
        "digest": digest,
        "books": sys.modules["neatbooks_v1_2_stable"],
        "web": sys.modules["neatweb_research_v1_4_stable"],
        "cleaner": sys.modules["neatcontext_cleaner_v1"],
        "crypto": sys.modules["neatcrypto_dpapi_v1"],
    }


