def _run_builtin_subsystem_test(name: str, environment: dict) -> dict:
    memory = environment["memory"]
    if name == "registry":
        names = tuple(_SELF_TEST_SPECS)
        checks = {
            "expected_registry_exact": names == _SELF_TEST_EXPECTED,
            "unique_names": len(names) == len(set(names)),
            "all_have_labels": all(bool(spec.get("label")) for spec in _SELF_TEST_SPECS.values()),
            "all_have_runners": all(bool(spec.get("runner")) for spec in _SELF_TEST_SPECS.values()),
            "all_in_all_group": all("all" in tuple(spec.get("groups") or ()) for spec in _SELF_TEST_SPECS.values()),
            "framework_version": bool(_SELF_TEST_FRAMEWORK_VERSION),
        }
        return {"ok": all(checks.values()), "checks": checks}
    if name == "bundle":
        checks = _self_test_required_surface(environment)
        return {"ok": all(checks.values()), "checks": checks}
    if name == "database":
        memory.initialize_database()
        report = memory.integrity_report()
        integrity_clean = not any((
            report.get("hash_mismatches"),
            report.get("source_hash_mismatches"),
            report.get("dangling_links"),
            report.get("dangling_topic_memberships"),
        ))
        with memory.db_connect() as db:
            sqlite_integrity = str(db.execute("PRAGMA integrity_check").fetchone()[0]).casefold() == "ok"
        checks = {
            "database_exists": bool(memory.database_path().exists()),
            "sqlite_integrity": sqlite_integrity,
            "semantic_integrity_clean": integrity_clean,
            "schema_version_present": bool(getattr(memory, "SCHEMA_VERSION", "")),
            "temp_memory_dir": str(memory.MEMORY_DIR) == str(Path(os.environ["NEAT_MEMORY_DIR"]).resolve()),
        }
        return {"ok": all(checks.values()), "checks": checks, "integrity": report}
    if name == "context-cleaner":
        cleaner = environment["cleaner"]
        fn = next((getattr(cleaner, candidate, None) for candidate in ("clean_text", "clean_plain_text", "clean_model_text") if callable(getattr(cleaner, candidate, None))), None)
        sample = "Alpha\x00\r\nBeta   \n\n\nGamma"
        cleaned = fn(sample) if fn else None
        checks = {
            "callable": callable(fn),
            "returns_text": isinstance(cleaned, str),
            "nul_removed": "\x00" not in str(cleaned),
            "content_preserved": all(word in str(cleaned) for word in ("Alpha", "Beta", "Gamma")),
        }
        return {"ok": all(checks.values()), "checks": checks, "output": cleaned}
    if name == "books":
        books = environment["books"]
        books.initialize()
        status = books.status()
        checks = {
            "database_exists": bool(books.db_path().exists()),
            "status_mapping": isinstance(status, dict),
            "books_directory_exists": books.BOOK_DIR.exists(),
            "pending_alias_is_books": books.PENDING_DIR.resolve() == books.BOOK_DIR.resolve(),
            "archive_alias_is_books": books.ARCHIVE_DIR.resolve() == books.BOOK_DIR.resolve(),
            "legacy_pending_not_created": not Path(getattr(books,"LEGACY_PENDING_DIR",books.MEMORY_DIR/"book_pending")).exists(),
            "legacy_archive_not_created": not Path(getattr(books,"LEGACY_ARCHIVE_DIR",books.MEMORY_DIR/"book_archive")).exists(),
            "single_storage_mode_reported": status.get("storage_mode") == "single_books_directory",
        }
        return {"ok": all(checks.values()), "checks": checks, "status": status}
    if name == "web":
        web = environment["web"]
        checks = {
            "research_loop": callable(getattr(web, "run_research_loop", None)),
            "autonomous_loop": callable(getattr(web, "run_autonomous_research_loop", None)),
            "search": callable(getattr(web, "web_search", None)),
            "read": callable(getattr(web, "web_read", None)),
        }
        return {"ok": all(checks.values()), "checks": checks, "network_called": False}
    if name == "digest":
        digest = environment["digest"]
        checks = {
            "main": callable(getattr(digest, "main", None)),
            "module_loaded": digest.__name__ == "neatdigest_v2_0_stable",
            "uses_bundled_memory_runtime": getattr(digest, "nm", None) is memory,
            "memory_dir_is_temporary": str(memory.MEMORY_DIR) == str(Path(os.environ["NEAT_MEMORY_DIR"]).resolve()),
        }
        return {"ok": all(checks.values()), "checks": checks}
    raise KeyError(name)


def _invoke_registered_subsystem_test(name: str) -> dict:
    if name not in _SELF_TEST_SPECS:
        raise KeyError(f"Unknown self-test subsystem: {name}")
    environment = _load_self_test_environment()
    runner = str(_SELF_TEST_SPECS[name]["runner"])
    if runner in {"registry", "bundle", "database", "context-cleaner", "books", "web", "digest"}:
        result = _run_builtin_subsystem_test(runner, environment)
    else:
        prefix, attribute = runner.split(".", 1)
        target = environment[prefix]
        fn = getattr(target, attribute)
        result = fn()
    if not isinstance(result, dict):
        result = {"ok": bool(result), "result": result}
    result.setdefault("ok", False)
    return _self_test_json_safe(result)


def _self_test_worker(name: str, output_path: Path | None = None) -> int:
    started = time.perf_counter()
    payload: dict = {
        "framework_version": _SELF_TEST_FRAMEWORK_VERSION,
        "bundle_version": BUNDLE_VERSION,
        "subsystem": name,
        "label": (_SELF_TEST_SPECS.get(name) or {}).get("label", name),
        "started_at": _self_test_now(),
        "isolated": True,
        "memory_dir": os.getenv("NEAT_MEMORY_DIR", ""),
    }
    original_tempdir_factory = tempfile.TemporaryDirectory
    original_tempdir_root = tempfile.tempdir
    nested_temp_root = os.getenv("NEAT_SELF_TEST_TMPDIR", "").strip()
    if nested_temp_root:
        Path(nested_temp_root).mkdir(parents=True, exist_ok=True)
        tempfile.tempdir = nested_temp_root

    def _self_test_nested_tempdir(*args, **kwargs):
        # Old subsystem tests often create a second temp SQLite tree. On Windows,
        # a still-referenced SQLite/WAL handle can make that nested context's eager
        # cleanup raise PermissionError even though the worker is about to exit.
        # Keep the behavioral result, tolerate only cleanup here, and let the parent
        # delete the entire isolated worker tree after process exit releases handles.
        try:
            kwargs.setdefault("ignore_cleanup_errors", True)
            return original_tempdir_factory(*args, **kwargs)
        except TypeError:
            kwargs.pop("ignore_cleanup_errors", None)
            return original_tempdir_factory(*args, **kwargs)

    tempfile.TemporaryDirectory = _self_test_nested_tempdir
    try:
        result = _invoke_registered_subsystem_test(name)
        payload["result"] = result
        payload["ok"] = bool(result.get("ok"))
        payload["status"] = "PASS" if payload["ok"] else "FAIL"
    except BaseException as exc:
        payload.update({
            "ok": False,
            "status": "ERROR",
            "error": f"{type(exc).__name__}: {exc}",
            "traceback": traceback.format_exc(),
        })
    finally:
        tempfile.TemporaryDirectory = original_tempdir_factory
        tempfile.tempdir = original_tempdir_root
    payload["duration_seconds"] = round(time.perf_counter() - started, 6)
    payload["finished_at"] = _self_test_now()
    if output_path is not None:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(json.dumps(_self_test_json_safe(payload), ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    else:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    return 0 if payload.get("ok") else 1


def _self_test_resolve_selection(selection: str | None) -> list[str]:
    raw = str(selection or "all").strip().casefold().replace("_", "-")
    raw = _SELF_TEST_ALIASES.get(raw, raw)
    if raw == "list":
        return []
    if raw in _SELF_TEST_NAMED_SUITES:
        missing = [name for name in _SELF_TEST_NAMED_SUITES[raw] if name not in _SELF_TEST_SPECS]
        if missing:
            raise ValueError(f"Named self-test suite {raw!r} references unknown subsystems: {', '.join(missing)}")
        return list(_SELF_TEST_NAMED_SUITES[raw])
    if raw in {"all", "quick", "critical"}:
        return [name for name, spec in _SELF_TEST_SPECS.items() if raw in tuple(spec.get("groups") or ())]
    requested = [part.strip().casefold().replace("_", "-") for part in re.split(r"[,;+]", raw) if part.strip()]
    names: list[str] = []
    for item in requested:
        item = _SELF_TEST_ALIASES.get(item, item)
        if item not in _SELF_TEST_SPECS:
            raise ValueError(f"Unknown self-test subsystem: {item}")
        if item not in names:
            names.append(item)
    return names


def _self_test_list_text() -> str:
    lines = ["Available isolated subsystem self-tests:"]
    for name, spec in _SELF_TEST_SPECS.items():
        groups = ", ".join(spec.get("groups") or ())
        lines.append(f"  {name:<22} {spec['label']} [{groups}]")
    lines.extend([
        "",
        "Named suites: checkpoint, developer, developer-integrity, developer-structure, smoke, core, portability, quick (legacy), critical (legacy), all",
        "Examples:",
        f"  python {Path(__file__).name} --self-test smoke",
        f"  python {Path(__file__).name} --self-test core",
        f"  python {Path(__file__).name} --self-test citations",
        f"  python {Path(__file__).name} --self-test critical",
        "  /test subsystem perception",
        "  /test subsystem all",
    ])
    return "\n".join(lines)


def _self_test_receipt_path(selection: str) -> Path:
    root = Path(os.getenv("NEAT_MEMORY_DIR", "./neat_memory")).resolve() / "self_test_receipts"
    root.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    safe = re.sub(r"[^a-z0-9_-]+", "-", selection.casefold()).strip("-") or "all"
    if len(safe) > 80:
        digest = hashlib.sha256(selection.encode("utf-8", "replace")).hexdigest()[:12]
        safe = safe[:64].rstrip("-_") + "-" + digest
    return root / f"self-test-{stamp}-{safe}.json"


def _run_isolated_self_tests(selection: str | None = "all", *, save_receipt: bool = True, echo: bool = True) -> dict:
    global _SELF_TEST_LAST_RECEIPT
    normalized = str(selection or "all").strip().casefold() or "all"
    if _SELF_TEST_ALIASES.get(normalized, normalized) == "list":
        if echo:
            print(_self_test_list_text())
        receipt = {"ok": True, "selection": "list", "subsystems": list(_SELF_TEST_SPECS)}
        _SELF_TEST_LAST_RECEIPT = receipt
        return receipt
    names = _self_test_resolve_selection(normalized)
    started_at = _self_test_now()
    started_clock = time.perf_counter()
    cases: list[dict] = []
    if echo:
        print(f"NeatMemory all-in-one bundle: {BUNDLE_VERSION}")
        print(f"Isolated subsystem self-tests: {normalized} ({len(names)} subsystem{'s' if len(names) != 1 else ''})")
    for index, name in enumerate(names, start=1):
        spec = _SELF_TEST_SPECS[name]
        with tempfile.TemporaryDirectory(prefix=f"neatmemory-test-{name}-") as folder:
            root = Path(folder)
            output = root / "worker-result.json"
            env = os.environ.copy()
            nested_tmp = (root / "nested_tmp").resolve()
            nested_tmp.mkdir(parents=True, exist_ok=True)
            env.update({
                "NEAT_MEMORY_DIR": str((root / "neat_memory").resolve()),
                "NEAT_SELF_TEST_TMPDIR": str(nested_tmp),
                "TMP": str(nested_tmp),
                "TEMP": str(nested_tmp),
                "TMPDIR": str(nested_tmp),
                "NEAT_TEST_MODE": "1",
                "PYTHONUTF8": "1",
            })
            command = [sys.executable, str(Path(__file__).resolve()), "--self-test-worker", name, "--self-test-worker-output", str(output)]
            case_started = time.perf_counter()
            try:
                case_timeout = max(10, int(os.getenv("NEAT_SELF_TEST_CASE_TIMEOUT_SECONDS", "120") or 120))
            except Exception:
                case_timeout = 120
            timed_out = False
            try:
                completed = subprocess.run(command, cwd=root, env=env, capture_output=True, text=True, timeout=case_timeout)
            except subprocess.TimeoutExpired as exc:
                timed_out = True
                completed = types.SimpleNamespace(
                    returncode=124,
                    stdout=(exc.stdout.decode("utf-8", "replace") if isinstance(exc.stdout, (bytes, bytearray)) else str(exc.stdout or "")),
                    stderr=(exc.stderr.decode("utf-8", "replace") if isinstance(exc.stderr, (bytes, bytearray)) else str(exc.stderr or "")),
                )
            duration = round(time.perf_counter() - case_started, 6)
            if output.exists():
                try:
                    case = json.loads(output.read_text(encoding="utf-8"))
                except Exception as exc:
                    case = {"ok": False, "status": "ERROR", "error": f"Invalid worker receipt: {exc}"}
            elif timed_out:
                case = {"ok": False, "status": "TIMEOUT", "error": f"Subsystem exceeded {case_timeout}s watchdog."}
            else:
                case = {"ok": False, "status": "ERROR", "error": "Worker produced no receipt."}
            case.update({
                "subsystem": name,
                "label": spec["label"],
                "worker_exit_code": completed.returncode,
                "worker_stdout": str(completed.stdout or "")[-12000:],
                "worker_stderr": str(completed.stderr or "")[-12000:],
                "duration_seconds": duration,
                "timeout_seconds": case_timeout,
                "timed_out": timed_out,
                "temporary_directory_cleaned": True,
                "live_state_modified": False,
            })
            case["ok"] = bool(case.get("ok")) and completed.returncode == 0 and not timed_out
            case["status"] = "PASS" if case["ok"] else ("TIMEOUT" if timed_out else str(case.get("status") or "FAIL"))
            cases.append(case)
        if echo:
            current = cases[-1]
            mark = "PASS" if current["ok"] else current["status"]
            print(f"[{mark}] {name}: {spec['label']} ({current['duration_seconds']:.3f}s)")
            if not current.get("ok"):
                if current.get("error"):
                    print(f"  -> {current.get('error')}")
                failed_checks = [
                    str(key) for key, value in ((current.get("result") or {}).get("checks") or {}).items()
                    if value is False
                ]
                if failed_checks:
                    print("  -> failed checks: " + ", ".join(failed_checks))
                stderr_tail = str(current.get("worker_stderr") or "").strip().splitlines()[-1:]
                if stderr_tail and not current.get("error"):
                    print("  -> worker stderr: " + stderr_tail[0][:600])
    failures = [case for case in cases if not case.get("ok")]
    receipt = {
        "receipt_version": "1.0-isolated-subsystem-tests",
        "framework_version": _SELF_TEST_FRAMEWORK_VERSION,
        "bundle_version": BUNDLE_VERSION,
        "selection": normalized,
        "started_at": started_at,
        "finished_at": _self_test_now(),
        "duration_seconds": round(time.perf_counter() - started_clock, 6),
        "ok": not failures,
        "summary": {
            "total": len(cases),
            "passed": len(cases) - len(failures),
            "failed": len(failures),
            "isolated_child_processes": len(cases),
            "live_state_modified": False,
        },
        "cases": cases,
    }
    # 7.4.50.7: the correction-precedence fixture itself remains disposable,
    # but its successful sanitized proof is promoted by the parent process into
    # Assistant's persistent records + encrypted Black Box. No fake test memory is
    # copied into canonical memory. Workers never promote their own evidence.
    promoter = globals().get("_promote_correction_precedence_receipt")
    if callable(promoter):
        try:
            promotion = promoter(receipt)
        except Exception as exc:
            promotion = {"ok": False, "required": True, "promoted": False, "error": f"{type(exc).__name__}: {exc}"}
        receipt["durable_evidence_promotion"] = promotion
        if promotion.get("required"):
            receipt["summary"]["live_canonical_memory_modified"] = False
            receipt["summary"]["live_evidence_archive_modified"] = bool(promotion.get("promoted"))
            if not promotion.get("ok"):
                receipt["ok"] = False
                receipt["summary"]["durable_promotion_failed"] = True
    if save_receipt:
        path = _self_test_receipt_path(normalized)
        path.write_text(json.dumps(_self_test_json_safe(receipt), ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        receipt["receipt_path"] = str(path)
    _SELF_TEST_LAST_RECEIPT = receipt
    if echo:
        summary = receipt["summary"]
        print(f"Self-test summary: {summary['passed']} passed, {summary['failed']} failed, {receipt['duration_seconds']:.3f}s")
        if receipt.get("receipt_path"):
            print(f"Receipt: {receipt['receipt_path']}")
        print("Self-test passed. No local companion modules are required." if receipt["ok"] else "Self-test failed. See the receipt for exact subsystem details.")
    return receipt


def _self_test(selection: str | None = "all") -> int:
    try:
        return 0 if _run_isolated_self_tests(selection, save_receipt=True, echo=True).get("ok") else 1
    except Exception as exc:
        print(f"Self-test error: {type(exc).__name__}: {exc}")
        return 1


def _print_self_test_failures(receipt: dict | None) -> None:
    if not receipt:
        print("No subsystem self-test has run in this process yet.")
        return
    failures = [case for case in receipt.get("cases", []) if not case.get("ok")]
    if not failures:
        print("The last subsystem self-test receipt has no failures.")
        return
    print(json.dumps({"selection": receipt.get("selection"), "failures": failures}, ensure_ascii=False, indent=2))


def _install_subsystem_test_commands(module) -> None:
    if getattr(module, "_ISOLATED_SUBSYSTEM_TEST_COMMANDS_INSTALLED", False):
        return
    original_help = module.print_help
    original_main = module.main

    def enhanced_help(advanced: bool = False):
        original_help(advanced=advanced)
        if advanced:
            print(
                "Isolated subsystem tests:\n"
                "  /test subsystem list\n"
                "  /test subsystem <name|quick|critical|all>\n"
                "  /test status\n"
                "  /test failures\n"
                "Tests run in fresh child processes with temporary databases and identity folders.\n"
            )
        else:
            print("  /test subsystem quick          isolated health check; /help advanced for details")

    def command_aware_main():
        original_input = builtins.input
        def intercepted_input(prompt: str = ""):
            while True:
                raw = original_input(prompt)
                compact = " ".join(str(raw or "").strip().split())
                lower = compact.casefold()
                if lower.startswith("/test subsystem"):
                    selection = compact[len("/test subsystem"):].strip() or "list"
                    try:
                        _run_isolated_self_tests(selection, save_receipt=True, echo=True)
                    except Exception as exc:
                        print(f"Subsystem self-test error: {type(exc).__name__}: {exc}")
                    continue
                if lower == "/test status":
                    if _SELF_TEST_LAST_RECEIPT:
                        print(json.dumps({
                            "bundle_version": _SELF_TEST_LAST_RECEIPT.get("bundle_version"),
                            "selection": _SELF_TEST_LAST_RECEIPT.get("selection"),
                            "ok": _SELF_TEST_LAST_RECEIPT.get("ok"),
                            "summary": _SELF_TEST_LAST_RECEIPT.get("summary"),
                            "receipt_path": _SELF_TEST_LAST_RECEIPT.get("receipt_path"),
                        }, ensure_ascii=False, indent=2))
                    else:
                        print("No subsystem self-test has run in this process yet.")
                    continue
                if lower == "/test failures":
                    _print_self_test_failures(_SELF_TEST_LAST_RECEIPT)
                    continue
                return raw
        builtins.input = intercepted_input
        try:
            return original_main()
        finally:
            builtins.input = original_input

    module.print_help = enhanced_help
    module.main = command_aware_main
    module.run_isolated_subsystem_tests = _run_isolated_self_tests
    module.list_isolated_subsystem_tests = lambda: list(_SELF_TEST_SPECS)
    module.ISOLATED_SELF_TEST_FRAMEWORK_VERSION = _SELF_TEST_FRAMEWORK_VERSION
    module._ISOLATED_SUBSYSTEM_TEST_COMMANDS_INSTALLED = True


