# NeatMemory 7.4.78.25 — zero-model performance + diagnostic-fidelity benchmark
# ---------------------------------------------------------------------------
_ACTION_SNAKE_BENCHMARK_VERSION = "1.0-isolated-performance-diagnostic-fidelity"
_ACTION_SNAKE_BENCHMARK_DEFAULT_ITERATIONS = 20
_ACTION_SNAKE_BENCHMARK_MAX_ITERATIONS = 100


def _asb_percentile(values, percentile: float):
    seq = sorted(float(x) for x in values if x is not None)
    if not seq:
        return None
    if len(seq) == 1:
        return round(seq[0], 3)
    pos = (len(seq) - 1) * max(0.0, min(1.0, float(percentile)))
    lo = int(pos); hi = min(len(seq) - 1, lo + 1); frac = pos - lo
    return round(seq[lo] * (1.0 - frac) + seq[hi] * frac, 3)


def _asb_latency_summary(values) -> dict:
    seq = [float(x) for x in values]
    if not seq:
        return {"samples":0,"min_ms":None,"median_ms":None,"p95_ms":None,"max_ms":None}
    return {
        "samples":len(seq),
        "min_ms":round(min(seq),3),
        "median_ms":_asb_percentile(seq,0.5),
        "p95_ms":_asb_percentile(seq,0.95),
        "max_ms":round(max(seq),3),
    }


def _asb_json_bytes(value) -> int:
    return len(json.dumps(value, ensure_ascii=False, separators=(",",":"), default=str).encode("utf-8"))


def _asb_time_call(fn, *args, **kwargs):
    started=time.perf_counter(); value=fn(*args,**kwargs); elapsed=(time.perf_counter()-started)*1000.0
    return value, elapsed


def _asb_reader_has_explicit_snapshot(value: dict) -> bool:
    keys={str(k).casefold() for k in (value or {}).keys()}
    return bool(keys.intersection({"snapshot_action_number","snapshot_action_id","snapshot_action_ref","snapshot_at","window_at_snapshot"}))


def _asb_measure(module, *, iterations: int = _ACTION_SNAKE_BENCHMARK_DEFAULT_ITERATIONS) -> dict:
    iterations=max(1,min(_ACTION_SNAKE_BENCHMARK_MAX_ITERATIONS,int(iterations)))
    append=getattr(module,"_append_action_snake",None)
    reader=getattr(module,"read_action_snake",None)
    searcher=getattr(module,"search_action_snake",None)
    getter=getattr(module,"get_action_snake",None)
    status_fn=getattr(module,"action_snake_status",None)
    if not all(callable(x) for x in (append,reader,searcher,getter,status_fn)):
        return {"ok":False,"error":"Action Snake runtime readers/writer are unavailable.","model_calls":0,"web_calls":0,"live_action_snake_modified":False}
    original_safe=module.safe_memory_path
    original_override=getattr(module,"_ACTION_SNAKE_MAX_OVERRIDE",None)
    marker="ASB-PLAINTEXT-FIDELITY-MARKER-78425"
    result={}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-action-snake-benchmark-") as folder:
            root=Path(folder)
            module.safe_memory_path=lambda name: root/str(name)
            module._ACTION_SNAKE_MAX_OVERRIDE=200
            append_lat=[]
            # Fill one beyond production capacity. Rich but bounded payloads exercise encryption and
            # projection without making the benchmark artificially huge.
            for index in range(1,202):
                payload={
                    "query":f"benchmark fixture {index}",
                    "rows_requested":(index%23)+1,
                    "provider_input_tokens":40000+(index%17)*100,
                    "fixture_blob":"x"*(256+(index%5)*128),
                }
                _,elapsed=_asb_time_call(
                    append,kind="benchmark_fixture",name="capacity_fill",status="complete",
                    summary=f"encrypted capacity fixture {index}",arguments=payload,
                    details={"duration_ms":index/10.0,"attempt":1},
                    result={"ok":True,"read_only":True,"source_ref":f"CHAT-{1000+index}"},source="action_snake_benchmark",
                )
                append_lat.append(elapsed)
            fifo_status=status_fn()
            evicted=getter(1); retained_oldest=getter(2); newest_201=getter(201)

            # Known troubleshooting path. The previous-action chain must preserve exact ordering/status.
            p1=append(kind="benchmark_path",name="search_chat_pyramid",status="complete",summary=f"{marker} locate candidate",
                      arguments={"query":"portable backup"},details={"candidate_count":4,"selected_rank":1},
                      result={"ok":True,"thread_id":"CPT-ASB1","source_range":"CHAT-736..755","read_only":True},source="action_snake_benchmark")
            p2=append(kind="benchmark_path",name="read_raw_chat",status="blocked",summary=f"{marker} broad read blocked",
                      arguments={"start_message_id":736,"end_message_id":755,"rows_requested":20},
                      details={"backpressure":True,"remaining_tokens":4472,"required_floor_tokens":7549},
                      result={"ok":False,"blocked":True,"reason":"tool_result_budget"},source="action_snake_benchmark",parent_action_id=p1.get("action_id"))
            p3=append(kind="benchmark_path",name="read_raw_chat",status="complete",summary=f"{marker} narrower retry completed",
                      arguments={"start_message_id":736,"end_message_id":743,"rows_requested":8},
                      details={"backpressure":False,"retry_of":p2.get("action_ref")},
                      result={"ok":True,"rows_loaded":8,"source_ref":"CHAT-736","read_only":True},source="action_snake_benchmark",parent_action_id=p2.get("action_id"))
            p4=append(kind="benchmark_path",name="evidence_check",status="verified",summary=f"{marker} evidence verified",
                      arguments={"source_range":"CHAT-736..743"},details={"verification":"exact_raw_chat"},
                      result={"ok":True,"verified":True,"source_refs":["CHAT-736","CHAT-743"],"read_only":True},source="action_snake_benchmark",parent_action_id=p3.get("action_id"))
            path_ids=[p1.get("action_id"),p2.get("action_id"),p3.get("action_id"),p4.get("action_id")]
            path_records=[]
            for aid in path_ids:
                item=getter(aid); path_records.append(dict(item.get("action") or {}))
            reconstructed=[{"action_ref":x.get("action_ref"),"name":x.get("name"),"status":x.get("status"),"previous_action_ref":x.get("previous_action_ref"),"parent_action_ref":x.get("parent_action_ref")} for x in path_records]
            expected_status=["complete","blocked","complete","verified"]
            expected_names=["search_chat_pyramid","read_raw_chat","read_raw_chat","evidence_check"]
            path_order_ok=[x.get("action_id") for x in path_records]==path_ids
            previous_chain_ok=all(path_records[i].get("previous_action_id")==path_ids[i-1] for i in range(1,len(path_ids)))
            parent_chain_ok=all(path_records[i].get("parent_action_id")==path_ids[i-1] for i in range(1,len(path_ids)))
            state_distinction_ok=[x.get("status") for x in path_records]==expected_status and [x.get("name") for x in path_records]==expected_names
            source_refs_ok="CHAT-736" in (path_records[2].get("source_refs") or []) and "CHAT-743" in (path_records[3].get("source_refs") or [])
            arguments_ok=(path_records[1].get("arguments") or {}).get("rows_requested")==20 and (path_records[2].get("arguments") or {}).get("rows_requested")==8

            # Snapshot-consistency experiment: capture an ordinary read, append three newer actions,
            # then verify the captured object remains a truthful immutable description of that moment.
            snapshot_read=reader(5,include_payloads=False)
            snapshot_newest=((snapshot_read.get("actions") or [{}])[0]).get("action_id")
            explicit_snapshot_metadata=_asb_reader_has_explicit_snapshot(snapshot_read)
            for index in range(3):
                append(kind="benchmark_snapshot",name="snapshot_advance",status="complete",summary=f"advance after snapshot {index}",
                       details={"snapshot_base":snapshot_newest,"advance_index":index},result={"ok":True,"read_only":True},source="action_snake_benchmark")
            after_status=status_fn()
            snapshot_stable=((snapshot_read.get("actions") or [{}])[0]).get("action_id")==snapshot_newest and int(after_status.get("newest_action_id") or 0)==int(snapshot_newest or 0)+3

            # Performance reads/search/exact lookup. Readers do not append to the snake.
            latency={"read_last_5_ms":[],"read_last_20_ms":[],"read_last_50_ms":[],"read_last_200_ms":[],"exact_lookup_ms":[],"keyword_search_ms":[]}
            compact20=full20=None; compact200=full200=None; exact_sample=None; search_sample=None
            for _ in range(iterations):
                v,t=_asb_time_call(reader,5,include_payloads=False); latency["read_last_5_ms"].append(t)
                v,t=_asb_time_call(reader,20,include_payloads=False); latency["read_last_20_ms"].append(t); compact20=v
                v,t=_asb_time_call(reader,50,include_payloads=False); latency["read_last_50_ms"].append(t)
                v,t=_asb_time_call(reader,200,include_payloads=False); latency["read_last_200_ms"].append(t); compact200=v
                v,t=_asb_time_call(getter,p4.get("action_id")); latency["exact_lookup_ms"].append(t); exact_sample=v
                v,t=_asb_time_call(searcher,marker,20,include_payloads=False); latency["keyword_search_ms"].append(t); search_sample=v
            full20=reader(20,include_payloads=True); full200=reader(200,include_payloads=True)

            # Encrypted store sizing / plaintext scan. WAL/SHM may exist depending on platform.
            store_files=[]; encrypted_store_bytes=0; supporting_bytes=0; raw_all=b""
            for candidate in sorted(root.glob("action_snake.sqlite*")):
                if candidate.is_file():
                    data=candidate.read_bytes(); raw_all+=data; encrypted_store_bytes+=len(data); store_files.append({"name":candidate.name,"bytes":len(data)})
            key_file=root/str(globals().get("_ACTION_SNAKE_KEY_FILE") or "action_snake.local.key")
            if key_file.exists(): supporting_bytes+=key_file.stat().st_size
            avg_cipher=None; slot_count=None
            db_path=root/str(globals().get("_ACTION_SNAKE_DB_FILE") or "action_snake.sqlite")
            if db_path.exists():
                db=sqlite3.connect(db_path)
                try:
                    row=db.execute("SELECT COUNT(*), AVG(length(encrypted_blob)) FROM action_snake_slots").fetchone()
                    slot_count=int(row[0] or 0); avg_cipher=round(float(row[1] or 0.0),3)
                finally: db.close()
            final_status=status_fn()
            plaintext_absent=marker.encode("utf-8") not in raw_all and b"portable backup" not in raw_all and str(p4.get("action_ref") or "").encode("utf-8") not in raw_all
            fifo_ok=(fifo_status.get("retained_actions")==200 and fifo_status.get("oldest_action_id")==2 and fifo_status.get("newest_action_id")==201 and fifo_status.get("next_action_id")==202 and evicted.get("ok") is False and retained_oldest.get("ok") is True and newest_201.get("ok") is True)
            monotonic_after_path=(path_ids==[202,203,204,205] and final_status.get("newest_action_id")==208 and final_status.get("next_action_id")==209)
            search_ok=bool(search_sample and search_sample.get("ok") and search_sample.get("count")>=4)
            exact_ok=bool(exact_sample and exact_sample.get("ok") and (exact_sample.get("action") or {}).get("action_id")==p4.get("action_id"))
            read_nonpolluting=final_status.get("next_action_id")==209
            checks={
                "isolated_capacity_200":fifo_status.get("capacity")==200,
                "fifo_201_evicts_oldest":fifo_ok,
                "monotonic_ids_survive_eviction":monotonic_after_path,
                "known_path_order_reconstructed":path_order_ok,
                "previous_action_chain_reconstructed":previous_chain_ok,
                "parent_action_chain_reconstructed":parent_chain_ok,
                "attempt_block_complete_verified_distinct":state_distinction_ok,
                "arguments_preserved":arguments_ok,
                "source_refs_preserved":source_refs_ok,
                "exact_lookup_finds_expected_action":exact_ok,
                "encrypted_keyword_search_finds_path":search_ok,
                "snapshot_object_stable_while_window_advances":snapshot_stable,
                "reader_inspection_does_not_consume_actions":read_nonpolluting,
                "encrypted_files_do_not_expose_fixture_plaintext":plaintext_absent,
                "encrypted_at_rest_reported":final_status.get("encrypted_at_rest") is True and final_status.get("plaintext_fallback") is False,
                "slot_count_bounded_200":slot_count==200,
                "zero_model_zero_web":True,
                "live_action_snake_untouched":True,
            }
            warnings=[]
            if not explicit_snapshot_metadata:
                warnings.append("Ordinary Action Snake reader output does not yet expose an explicit snapshot action number/window; snapshot consistency itself passed in the isolated benchmark. This is a usability/observability refinement, not storage corruption.")
            result={
                "ok":all(bool(v) for v in checks.values()),
                "operation":"action_snake_light_benchmark_measure",
                "version":_ACTION_SNAKE_BENCHMARK_VERSION,
                "checks":checks,
                "warnings":warnings,
                "diagnostic_fidelity":{
                    "path_action_ids":path_ids,
                    "reconstructed_path":reconstructed,
                    "expected_statuses":expected_status,
                    "snapshot_action_number":snapshot_newest,
                    "current_action_number_after_snapshot_advances":after_status.get("newest_action_id"),
                    "snapshot_consistency_pass":snapshot_stable,
                    "ordinary_reader_explicit_snapshot_boundary":explicit_snapshot_metadata,
                },
                "performance":{
                    "iterations":iterations,
                    "append_201":_asb_latency_summary(append_lat),
                    **{name.replace("_ms",""):_asb_latency_summary(values) for name,values in latency.items()},
                    "compact_json_bytes":{"last_20":_asb_json_bytes(compact20),"last_200":_asb_json_bytes(compact200)},
                    "full_json_bytes":{"last_20":_asb_json_bytes(full20),"last_200":_asb_json_bytes(full200)},
                    "full_to_compact_ratio":{"last_20":round(_asb_json_bytes(full20)/max(1,_asb_json_bytes(compact20)),3),"last_200":round(_asb_json_bytes(full200)/max(1,_asb_json_bytes(compact200)),3)},
                    "performance_threshold_policy":"Report hardware-relative timings; no arbitrary latency threshold changes PASS/FAIL.",
                },
                "storage":{
                    "capacity":200,
                    "retained_actions":final_status.get("retained_actions"),
                    "encrypted_store_bytes":encrypted_store_bytes,
                    "supporting_key_bytes_nonwindows_test":supporting_bytes,
                    "average_encrypted_blob_bytes":avg_cipher,
                    "files":store_files,
                    "encryption_modes_present":final_status.get("encryption_modes_present"),
                    "plaintext_fixture_scan_pass":plaintext_absent,
                },
                "authority":{
                    "live_action_snake_modified":False,
                    "temporary_store_destroyed_after_measurement":True,
                    "semantic_memory_modified":False,
                    "model_calls":0,"web_calls":0,
                },
                "model_calls":0,"web_calls":0,"live_action_snake_modified":False,
            }
            return result
    finally:
        module.safe_memory_path=original_safe
        if original_override is None:
            try: delattr(module,"_ACTION_SNAKE_MAX_OVERRIDE")
            except Exception: pass
        else:
            module._ACTION_SNAKE_MAX_OVERRIDE=original_override


def _asb_receipt_path(module, run_id: str) -> Path:
    root=Path(getattr(module,"MEMORY_DIR",Path.cwd()/"neat_memory"))/"benchmarks"/"receipts"
    root.mkdir(parents=True,exist_ok=True)
    return root/f"action-snake-{run_id}.json"


def _asb_atomic_write(module, path: Path, payload: dict) -> None:
    writer=getattr(module,"_benchmark_atomic_write_json",None)
    if callable(writer):
        writer(path,payload); return
    temp=path.with_suffix(path.suffix+".tmp")
    temp.write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    os.replace(temp,path)


def _asb_run(module, *, iterations: int = _ACTION_SNAKE_BENCHMARK_DEFAULT_ITERATIONS) -> dict:
    started=time.perf_counter(); measured=_asb_measure(module,iterations=iterations)
    run_id=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")+"-"+uuid.uuid4().hex[:8]
    receipt={
        "benchmark":{"name":"action-snake","version":_ACTION_SNAKE_BENCHMARK_VERSION,"run_id":run_id,"finished_at":datetime.now(timezone.utc).isoformat(timespec="seconds"),"runtime_version":str(getattr(module,"NEATMEMORY_VERSION",BUNDLE_VERSION)),"kind":"zero-model-isolated-encrypted-performance-and-diagnostic-fidelity"},
        "summary":{"planned_cases":3,"completed_cases":3 if measured.get("ok") else 2,"failed_cases":0 if measured.get("ok") else 1,"model_calls":0,"web_calls":0,"iterations":max(1,min(_ACTION_SNAKE_BENCHMARK_MAX_ITERATIONS,int(iterations))),"duration_ms":round((time.perf_counter()-started)*1000.0,3),"diagnostic_fidelity_pass":all(bool(v) for k,v in (measured.get("checks") or {}).items() if k not in {"zero_model_zero_web","live_action_snake_untouched"}),"live_action_snake_modified":False},
        "diagnostic_fidelity":measured.get("diagnostic_fidelity"),
        "performance":measured.get("performance"),
        "storage":measured.get("storage"),
        "checks":measured.get("checks"),
        "warnings":measured.get("warnings") or [],
        "authority":{"benchmark_store":"temporary isolated encrypted Action Snake only","live_action_snake":"not read or written by benchmark measurement","performance_claim":"timings are hardware-relative observations, not semantic correctness thresholds","model_calls":0,"web_calls":0},
        "receipt_validation":{"status":"PASS" if measured.get("ok") else "FAIL","errors":[] if measured.get("ok") else [measured.get("error") or "One or more diagnostic-fidelity checks failed."]},
    }
    path=_asb_receipt_path(module,run_id); _asb_atomic_write(module,path,receipt)
    return {"ok":receipt["receipt_validation"]["status"]=="PASS","path":str(path),"receipt":receipt}


def _asb_parse_command(raw: str) -> dict:
    clean=" ".join(str(raw or "").strip().split())
    match=re.search(r"--iterations\s+(\d+)",clean,re.IGNORECASE)
    value=int(match.group(1)) if match else _ACTION_SNAKE_BENCHMARK_DEFAULT_ITERATIONS
    return {"iterations":max(1,min(_ACTION_SNAKE_BENCHMARK_MAX_ITERATIONS,value))}


def action_snake_benchmark_self_test(module=None) -> dict:
    if module is None: module=_load_memory()
    measured=_asb_measure(module,iterations=2)
    catalog=_uv_benchmark_catalog(module) if callable(globals().get("_uv_benchmark_catalog")) else {}
    checks=dict(measured.get("checks") or {})
    checks.update({
        "command_parser_default":_asb_parse_command("/benchmark action-snake")=={"iterations":20},
        "command_parser_clamps":_asb_parse_command("/benchmark action-snake --iterations 999")=={"iterations":100},
        "catalog_registered":bool((catalog.get("action-snake") or {}).get("runner_available")),
        "benchmark_measurement_passed":measured.get("ok") is True,
        "benchmark_is_zero_model":measured.get("model_calls")==0 and measured.get("web_calls")==0,
        "benchmark_does_not_touch_live_ring":measured.get("live_action_snake_modified") is False,
    })
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"sample":{"diagnostic_fidelity":measured.get("diagnostic_fidelity"),"performance":measured.get("performance"),"storage":measured.get("storage"),"warnings":measured.get("warnings")},"version":_ACTION_SNAKE_BENCHMARK_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


def _install_action_snake_benchmark(module) -> None:
    if getattr(module,"_ACTION_SNAKE_BENCHMARK_INSTALLED",False): return
    module.ACTION_SNAKE_BENCHMARK_VERSION=_ACTION_SNAKE_BENCHMARK_VERSION
    module.run_action_snake_benchmark=lambda **kwargs:_asb_run(module,**kwargs)
    module.action_snake_benchmark_self_test=lambda:action_snake_benchmark_self_test(module)
    old_catalog=globals().get("_uv_benchmark_catalog")
    if callable(old_catalog) and not globals().get("_ASB_CATALOG_WRAPPED"):
        def asb_catalog(mod):
            out=dict(old_catalog(mod)); out["action-snake"]={
                "command":"/benchmark action-snake [--iterations N]","kind":"zero_model_isolated_encrypted_performance_and_diagnostic_fidelity","model_calls":0,"provider":"none","purpose":"measure encrypted 200-entry Action Snake performance, FIFO/monotonic correctness, plaintext-at-rest protection, compact/full read cost, and reconstructability of a known failure/retry/evidence path without touching the live ring","runner_available":callable(getattr(mod,"run_action_snake_benchmark",None)),
            }; return out
        globals()["_uv_benchmark_catalog"]=asb_catalog; globals()["_ASB_CATALOG_WRAPPED"]=True
    old_main=module.main
    def main_with_asb():
        previous=builtins.input
        def asb_input(prompt=""):
            while True:
                value=previous(prompt); clean=" ".join(str(value or "").strip().split()); low=clean.casefold()
                if low.startswith("/benchmark action-snake") or low.startswith("/benchmark snake"):
                    result=_asb_run(module,**_asb_parse_command(clean)); receipt=result.get("receipt") or {}
                    print(json.dumps({"ok":result.get("ok"),"path":result.get("path"),"benchmark":receipt.get("benchmark"),"summary":receipt.get("summary"),"diagnostic_fidelity":receipt.get("diagnostic_fidelity"),"performance":receipt.get("performance"),"storage":receipt.get("storage"),"warnings":receipt.get("warnings"),"receipt_validation":receipt.get("receipt_validation")},ensure_ascii=False,indent=2)); continue
                return value
        builtins.input=asb_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_asb
    old_help=module.print_help
    def help_with_asb(*args,**kwargs):
        result=old_help(*args,**kwargs); print("  /benchmark action-snake [--iterations N]   zero-model isolated encrypted performance + diagnostic-fidelity audit"); return result
    module.print_help=help_with_asb
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["action-snake-benchmark"]={"label":"Zero-model isolated Action Snake performance, FIFO/encryption and synthetic diagnostic-path reconstructability benchmark","groups":("quick","critical","all"),"runner":"memory.action_snake_benchmark_self_test"}
    module._ACTION_SNAKE_BENCHMARK_INSTALLED=True

