def _bni_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _bni_db_path(module) -> Path:
    return Path(module.safe_memory_path(_BOOK_NAV_DB_FILE))


def _bni_connect(module):
    path = _bni_db_path(module)
    path.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(path, timeout=30.0)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA journal_mode=WAL")
    db.execute("PRAGMA foreign_keys=ON")
    db.executescript("""
        CREATE TABLE IF NOT EXISTS book_navigation_books(
            book_id TEXT PRIMARY KEY,
            title TEXT,
            authors_json TEXT NOT NULL DEFAULT '[]',
            total_source_chunks INTEGER,
            contents_ordinal INTEGER,
            first_seen_at TEXT NOT NULL,
            last_seen_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS book_navigation_observations(
            book_id TEXT NOT NULL,
            chunk_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            open_count INTEGER NOT NULL DEFAULT 1,
            first_opened_at TEXT NOT NULL,
            last_opened_at TEXT NOT NULL,
            last_trigger TEXT,
            last_query TEXT,
            PRIMARY KEY(book_id,chunk_id)
        );
        CREATE INDEX IF NOT EXISTS idx_book_navigation_observations_ordinal
            ON book_navigation_observations(book_id,ordinal);
        CREATE TABLE IF NOT EXISTS book_navigation_entries(
            entry_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL,
            entry_type TEXT NOT NULL,
            label TEXT NOT NULL,
            normalized_label TEXT NOT NULL,
            start_ordinal INTEGER NOT NULL,
            end_ordinal INTEGER,
            line_start INTEGER,
            line_end INTEGER,
            source_chunk_id TEXT,
            source_text_sha256 TEXT,
            origin TEXT NOT NULL,
            status TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            supersedes_entry_id TEXT,
            reason TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_book_navigation_entries_lookup
            ON book_navigation_entries(book_id,active,start_ordinal,entry_type,normalized_label);
        CREATE TABLE IF NOT EXISTS book_navigation_events(
            event_id TEXT PRIMARY KEY,
            entry_id TEXT,
            related_entry_id TEXT,
            event_type TEXT NOT NULL,
            actor TEXT NOT NULL,
            before_json TEXT,
            after_json TEXT,
            reason TEXT,
            created_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_book_navigation_events_entry
            ON book_navigation_events(entry_id,created_at);
    """)
    return db


def _bni_norm(text: object) -> str:
    return " ".join(str(text or "").strip().casefold().split())


def _bni_entry_id(book_id: str, entry_type: str, label: str, ordinal: int, line_start: int | None,
                  source_chunk_id: str, origin: str = "python_auto") -> str:
    payload = "|".join([str(book_id), str(entry_type), _bni_norm(label), str(int(ordinal)),
                        str(line_start or 0), str(source_chunk_id or ""), str(origin)])
    return "BNI-" + hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20]


def _bni_structural_candidates(text: str) -> list[dict]:
    """Mechanical structure only. Ambiguous uppercase lines remain candidates, not semantic truth."""
    output = []
    seen = set()
    act_re = re.compile(r"^ACT\s+([IVXLCDM]+|\d+)\b[\s.:\-]*(.*)$", re.IGNORECASE)
    scene_re = re.compile(r"^SCENE\s+([IVXLCDM]+|\d+)\b[\s.:\-]*(.*)$", re.IGNORECASE)
    chapter_re = re.compile(r"^CHAPTER\s+([IVXLCDM]+|\d+)\b[\s.:\-]*(.*)$", re.IGNORECASE)
    work_re = re.compile(r"^(?:THE\s+)?(?:TRAGEDY|COMEDY|HISTORY|LIFE)\s+OF\s+.+$", re.IGNORECASE)
    for line_no, raw_line in enumerate(str(text or "").splitlines(), 1):
        line = " ".join(str(raw_line).strip().split())
        if not line or len(line) > 180:
            continue
        folded = line.casefold().rstrip(" .:-")
        entry_type = None
        if folded in {"contents", "table of contents"}:
            entry_type = "contents"
        elif folded == "index":
            entry_type = "index"
        elif act_re.match(line):
            entry_type = "act"
        elif scene_re.match(line):
            entry_type = "scene"
        elif chapter_re.match(line):
            entry_type = "chapter"
        elif work_re.match(line):
            entry_type = "work"
        else:
            letters = [ch for ch in line if ch.isalpha()]
            # Preserve obvious source headings without claiming what they mean.
            if len(letters) >= 4 and line.upper() == line and not line.isdigit():
                entry_type = "heading_candidate"
        if entry_type:
            key = (entry_type, _bni_norm(line), line_no)
            if key not in seen:
                seen.add(key)
                output.append({"entry_type": entry_type, "label": line, "line_start": line_no})
    return output


def _bni_upsert_book(db, book: dict, book_id: str) -> None:
    now = _bni_now()
    title = str((book or {}).get("title") or "").strip()
    authors = (book or {}).get("authors") or []
    try:
        total = int((book or {}).get("total_chunks") or 0) or None
    except Exception:
        total = None
    db.execute("""INSERT INTO book_navigation_books(book_id,title,authors_json,total_source_chunks,first_seen_at,last_seen_at)
        VALUES(?,?,?,?,?,?) ON CONFLICT(book_id) DO UPDATE SET
        title=CASE WHEN excluded.title<>'' THEN excluded.title ELSE book_navigation_books.title END,
        authors_json=CASE WHEN excluded.authors_json<>'[]' THEN excluded.authors_json ELSE book_navigation_books.authors_json END,
        total_source_chunks=COALESCE(excluded.total_source_chunks,book_navigation_books.total_source_chunks),
        last_seen_at=excluded.last_seen_at""",
        (book_id,title,json.dumps(authors,ensure_ascii=False),total,now,now))


def _bni_record_auto_entry(db, *, book_id: str, chunk: dict, candidate: dict) -> str:
    ordinal = int(chunk.get("ordinal") or 0)
    chunk_id = str(chunk.get("chunk_id") or "")
    label = str(candidate.get("label") or "").strip()
    entry_type = str(candidate.get("entry_type") or "heading_candidate")
    line_start = int(candidate.get("line_start") or 0) or None
    entry_id = _bni_entry_id(book_id, entry_type, label, ordinal, line_start, chunk_id)
    now = _bni_now()
    source_hash = str(chunk.get("text_sha256") or "")
    db.execute("""INSERT OR IGNORE INTO book_navigation_entries(
        entry_id,book_id,entry_type,label,normalized_label,start_ordinal,end_ordinal,line_start,line_end,
        source_chunk_id,source_text_sha256,origin,status,active,supersedes_entry_id,reason,created_at,updated_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (entry_id,book_id,entry_type,label,_bni_norm(label),ordinal,None,line_start,None,
         chunk_id,source_hash,"python_auto","AUTO",1,None,"Mechanically extracted from exact source text.",now,now))
    db.execute("UPDATE book_navigation_entries SET updated_at=? WHERE entry_id=?",(now,entry_id))
    if entry_type == "contents":
        db.execute("""UPDATE book_navigation_books SET contents_ordinal=CASE
            WHEN contents_ordinal IS NULL OR ? < contents_ordinal THEN ? ELSE contents_ordinal END
            WHERE book_id=?""",(ordinal,ordinal,book_id))
    return entry_id


def _bni_observe_read_result(module, result: object, *, trigger: str = "read_book_chunks", query: str = "") -> dict:
    """Record only what Python can observe mechanically from chunks Assistant already chose to open."""
    if not isinstance(result, dict) or result.get("ok") is False:
        return {"ok": False, "observed": 0, "entries_added": 0}
    if not callable(getattr(module, "safe_memory_path", None)):
        return {"ok": False, "observed": 0, "entries_added": 0, "reason": "navigation_storage_unavailable"}
    book = dict(result.get("book") or {})
    chunks = [dict(c) for c in (result.get("chunks") or []) if isinstance(c, dict)]
    bid = str(book.get("book_id") or (chunks[0].get("book_id") if chunks else "") or "").strip()
    if not bid:
        return {"ok": False, "observed": 0, "entries_added": 0}
    now = _bni_now()
    added = 0
    with _bni_connect(module) as db:
        _bni_upsert_book(db, book, bid)
        before = int(db.execute("SELECT COUNT(*) FROM book_navigation_entries WHERE book_id=?",(bid,)).fetchone()[0])
        for chunk in chunks:
            cid = str(chunk.get("chunk_id") or "").strip()
            try: ordinal = int(chunk.get("ordinal") or 0)
            except Exception: ordinal = 0
            if not cid or ordinal <= 0:
                continue
            db.execute("""INSERT INTO book_navigation_observations(
                book_id,chunk_id,ordinal,open_count,first_opened_at,last_opened_at,last_trigger,last_query)
                VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(book_id,chunk_id) DO UPDATE SET
                ordinal=excluded.ordinal,open_count=book_navigation_observations.open_count+1,
                last_opened_at=excluded.last_opened_at,last_trigger=excluded.last_trigger,last_query=excluded.last_query""",
                (bid,cid,ordinal,1,now,now,str(trigger or "")[:80],str(query or "")[:500]))
            exact_text = str(chunk.get("original_text") or chunk.get("text") or "")
            for candidate in _bni_structural_candidates(exact_text):
                _bni_record_auto_entry(db, book_id=bid, chunk=chunk, candidate=candidate)
        after = int(db.execute("SELECT COUNT(*) FROM book_navigation_entries WHERE book_id=?",(bid,)).fetchone()[0])
        added = max(0, after-before)
    return {"ok": True, "book_id": bid, "observed": len(chunks), "entries_added": added, "model_calls": 0}


def _bni_ranges(ordinals: list[int]) -> list[dict]:
    vals = sorted({int(x) for x in ordinals if int(x) > 0})
    if not vals:
        return []
    out=[]; start=prev=vals[0]
    for value in vals[1:]:
        if value == prev + 1:
            prev = value; continue
        out.append({"start":start,"end":prev,"count":prev-start+1})
        start=prev=value
    out.append({"start":start,"end":prev,"count":prev-start+1})
    return out


def _bni_get_index(module, book_id: str, *, query: str = "", limit: int = 100,
                   include_superseded: bool = False) -> dict:
    bid = str(book_id or "").strip()
    if not bid:
        return {"ok": False, "error": "book_id is required.", "read_only": True, "model_calls": 0}
    try: limit = max(1,min(200,int(limit)))
    except Exception: limit = 100
    with _bni_connect(module) as db:
        book_row = db.execute("SELECT * FROM book_navigation_books WHERE book_id=?",(bid,)).fetchone()
        where=["book_id=?"]; params=[bid]
        if not include_superseded:
            where.append("active=1")
        q=_bni_norm(query)
        if q:
            where.append("(normalized_label LIKE ? OR lower(entry_type) LIKE ? OR lower(COALESCE(reason,'')) LIKE ?)")
            like=f"%{q}%"; params.extend([like,like,like])
        params.append(limit)
        rows=db.execute("SELECT * FROM book_navigation_entries WHERE "+" AND ".join(where)+" ORDER BY start_ordinal,line_start,created_at LIMIT ?",tuple(params)).fetchall()
        obs=db.execute("SELECT ordinal,open_count,last_opened_at,last_trigger FROM book_navigation_observations WHERE book_id=? ORDER BY ordinal",(bid,)).fetchall()
        entries=[dict(r) for r in rows]
        for item in entries:
            item["active"] = bool(item.get("active"))
        return {
            "ok": True,
            "book_id": bid,
            "book": dict(book_row) if book_row else {"book_id":bid},
            "query": str(query or ""),
            "entries": entries,
            "entry_count": len(entries),
            "observed_source_chunks": len(obs),
            "observed_ranges": _bni_ranges([int(r["ordinal"]) for r in obs]),
            "navigation_note": "AUTO entries are Python-extracted structural observations. Assistant corrections may supersede them; the original book remains authoritative and immutable.",
            "read_only": True,
            "model_calls": 0,
        }


def _bni_source_chunk(module, book_id: str, ordinal: int) -> dict | None:
    books = getattr(module,"neatbooks",None)
    if books is None or int(ordinal) <= 0:
        return None
    raw=books.read_book_chunks(book_id=str(book_id),start=int(ordinal),count=1)
    if not isinstance(raw,dict) or raw.get("ok") is False:
        return None
    _bni_observe_read_result(module,raw,trigger="index_correction_evidence")
    for chunk in raw.get("chunks") or []:
        try: found=int(chunk.get("ordinal") or 0)
        except Exception: found=0
        if found == int(ordinal):
            return dict(chunk)
    return None


def _bni_clean_type(value: object, default: str) -> str:
    candidate=_bni_norm(value).replace(" ","_")
    return candidate if candidate in _BOOK_NAV_ENTRY_TYPES else default


def _bni_clean_status(value: object, default: str) -> str:
    candidate=str(value or "").strip().upper()
    return candidate if candidate in _BOOK_NAV_STATUSES and candidate != "SUPERSEDED" else default


def _bni_correct_index(module, *, book_id: str, entry_id: str = "", label: str = "",
                       entry_type: str = "", start_ordinal: int | None = None,
                       end_ordinal: int | None = None, start_line: int | None = None,
                       status: str = "", reason: str = "") -> dict:
    """Assistant-authorized semantic correction of derived navigation only; source book is never modified."""
    bid=str(book_id or "").strip(); old_id=str(entry_id or "").strip()
    if not bid:
        return {"ok":False,"error":"book_id is required.","source_book_modified":False}
    reason=" ".join(str(reason or "").split())[:1200]
    with _bni_connect(module) as db:
        old=db.execute("SELECT * FROM book_navigation_entries WHERE entry_id=? AND book_id=?",(old_id,bid)).fetchone() if old_id else None
        if old_id and old is None:
            return {"ok":False,"error":"Index entry not found for this book.","source_book_modified":False}
        oldd=dict(old) if old else {}
        final_label=" ".join(str(label or oldd.get("label") or "").split())
        if not final_label:
            return {"ok":False,"error":"label is required when creating a new index entry.","source_book_modified":False}
        final_type=_bni_clean_type(entry_type, str(oldd.get("entry_type") or "note"))
        raw_start=start_ordinal if start_ordinal is not None else oldd.get("start_ordinal")
        try: final_start=int(raw_start)
        except Exception: final_start=0
        if final_start <= 0:
            return {"ok":False,"error":"A positive start_ordinal is required.","source_book_modified":False}
        raw_end=end_ordinal if end_ordinal is not None else oldd.get("end_ordinal")
        final_end=None
        if raw_end not in (None,""):
            try: final_end=int(raw_end)
            except Exception: return {"ok":False,"error":"end_ordinal must be an integer.","source_book_modified":False}
            if final_end < final_start:
                return {"ok":False,"error":"end_ordinal cannot be before start_ordinal.","source_book_modified":False}
        evidence=_bni_source_chunk(module,bid,final_start)
        if evidence is None:
            return {"ok":False,"error":f"Cannot verify source chunk ordinal {final_start} in {bid}.","source_book_modified":False}
        if final_end is not None and final_end != final_start and _bni_source_chunk(module,bid,final_end) is None:
            return {"ok":False,"error":f"Cannot verify end source chunk ordinal {final_end} in {bid}.","source_book_modified":False}
        try: final_line=int(start_line) if start_line is not None else (int(oldd.get("line_start")) if oldd.get("line_start") is not None else None)
        except Exception: final_line=None
        final_status=_bni_clean_status(status, "CORRECTED" if old else "VERIFIED")
        now=_bni_now()
        new_id="BNI-ASSISTANT-"+uuid.uuid4().hex[:16]
        new_row={
            "entry_id":new_id,"book_id":bid,"entry_type":final_type,"label":final_label,
            "normalized_label":_bni_norm(final_label),"start_ordinal":final_start,"end_ordinal":final_end,
            "line_start":final_line,"line_end":None,"source_chunk_id":str(evidence.get("chunk_id") or ""),
            "source_text_sha256":str(evidence.get("text_sha256") or ""),"origin":"assistant_correction",
            "status":final_status,"active":1,"supersedes_entry_id":old_id or None,
            "reason":reason or ("Assistant corrected derived navigation." if old else "Assistant added a verified navigation landmark."),
            "created_at":now,"updated_at":now,
        }
        if old:
            db.execute("UPDATE book_navigation_entries SET active=0,status='SUPERSEDED',updated_at=? WHERE entry_id=?",(now,old_id))
        cols=list(new_row)
        db.execute("INSERT INTO book_navigation_entries("+",".join(cols)+") VALUES("+",".join("?" for _ in cols)+")",tuple(new_row[c] for c in cols))
        event_id="BNIE-"+uuid.uuid4().hex[:16]
        db.execute("INSERT INTO book_navigation_events(event_id,entry_id,related_entry_id,event_type,actor,before_json,after_json,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?)",
                   (event_id,new_id,old_id or None,"CORRECT" if old else "ADD_VERIFIED","Assistant",
                    json.dumps(oldd,ensure_ascii=False,default=str) if old else None,
                    json.dumps(new_row,ensure_ascii=False,default=str),new_row["reason"],now))
    return {
        "ok":True,"book_id":bid,"entry":new_row,"superseded_entry_id":old_id or None,
        "actor":"Assistant","history_preserved":bool(old_id),"source_book_modified":False,
        "book_index_modified":True,"model_calls":0,
    }


def _bni_execute_tool(module, name: str, arguments: object) -> dict:
    args=dict(arguments or {}) if isinstance(arguments,dict) else {}
    if name == "book_index":
        return _bni_get_index(module,str(args.get("book_id") or ""),query=str(args.get("query") or ""),
                              limit=args.get("limit",100),include_superseded=bool(args.get("include_superseded",False)))
    if name == "correct_book_index":
        return _bni_correct_index(module,book_id=str(args.get("book_id") or ""),entry_id=str(args.get("entry_id") or ""),
                                  label=str(args.get("label") or ""),entry_type=str(args.get("entry_type") or ""),
                                  start_ordinal=args.get("start_ordinal"),end_ordinal=args.get("end_ordinal"),
                                  start_line=args.get("start_line"),status=str(args.get("status") or ""),reason=str(args.get("reason") or ""))
    return {"ok":False,"error":f"Book-navigation tool not allowed: {name}"}


def _install_book_navigation_index(module) -> None:
    if getattr(module,"_BOOK_NAVIGATION_INDEX_INSTALLED",False):
        return
    # Initialize lazily but early enough to surface storage errors now.
    with _bni_connect(module):
        pass
    module.book_index=lambda book_id,query="",limit=100,include_superseded=False: _bni_get_index(module,book_id,query=query,limit=limit,include_superseded=include_superseded)
    module.correct_book_index=lambda **kwargs: _bni_correct_index(module,**kwargs)
    module.observe_book_read_for_index=lambda result,trigger="manual",query="": _bni_observe_read_result(module,result,trigger=trigger,query=query)
    module.book_navigation_index_self_test=lambda: book_navigation_index_self_test(module)
    schemas=[
        {"type":"function","function":{"name":"book_index","description":"Read the living derived navigation index for one book. Shows Python-observed structural landmarks, Assistant corrections, and source-chunk coverage without changing the book.","parameters":{"type":"object","properties":{"book_id":{"type":"string"},"query":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":200},"include_superseded":{"type":"boolean"}},"required":["book_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"correct_book_index","description":"Correct or add one derived book-navigation landmark as Assistant. Python verifies the referenced source chunk, preserves any superseded entry/history, and never modifies the original book.","parameters":{"type":"object","properties":{"book_id":{"type":"string"},"entry_id":{"type":"string"},"label":{"type":"string"},"entry_type":{"type":"string"},"start_ordinal":{"type":"integer","minimum":1},"end_ordinal":{"type":["integer","null"],"minimum":1},"start_line":{"type":["integer","null"],"minimum":1},"status":{"type":"string"},"reason":{"type":"string"}},"required":["book_id"],"additionalProperties":False}}},
    ]
    existing={str((x.get("function") or {}).get("name") or "") for x in getattr(module,"TOOL_SCHEMAS",[]) if isinstance(x,dict)}
    module.TOOL_SCHEMAS.extend(x for x in schemas if (x.get("function") or {}).get("name") not in existing)
    if hasattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST"):
        module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("book_index")
    if hasattr(module,"execute_tool"):
        old_execute=module.execute_tool
        def execute_tool_with_book_index(name,arguments,seen,*,allow_sticky,sticky_state):
            if name in {"book_index","correct_book_index"}:
                return _bni_execute_tool(module,name,arguments)
            return old_execute(name,arguments,seen,allow_sticky=allow_sticky,sticky_state=sticky_state)
        module.execute_tool=execute_tool_with_book_index
    module.BOOK_NAVIGATION_INDEX_VERSION=_BOOK_NAV_INDEX_VERSION
    module._BOOK_NAVIGATION_INDEX_INSTALLED=True


def book_navigation_index_self_test(module=None) -> dict:
    with tempfile.TemporaryDirectory(prefix="neat-book-index-test-") as td:
        root=Path(td); calls=[]
        class FakeBooks:
            @staticmethod
            def read_book_chunks(book_id,start=1,count=1):
                calls.append((str(book_id),int(start),int(count)))
                data={
                    123:"THE TRAGEDY OF MACBETH\nDramatis Personae",
                    124:"ACT I\nSCENE I\nThunder and Lightning. Enter three Witches.",
                }
                chunks=[]
                for ordinal in range(int(start),int(start)+int(count)):
                    if ordinal in data:
                        text=data[ordinal]
                        chunks.append({"chunk_id":f"{book_id}-C{ordinal:06d}","ordinal":ordinal,"original_text":text,"text":text,"text_sha256":hashlib.sha256(text.encode()).hexdigest()})
                return {"ok":True,"book":{"book_id":book_id,"title":"The Complete Works of William Shakespeare","authors":["William Shakespeare"],"total_chunks":1240},"chunks":chunks}
        class FakeModule:
            neatbooks=FakeBooks()
            TOOL_SCHEMAS=[]
            _READ_ONLY_TEXT_TOOL_ALLOWLIST=set()
            @staticmethod
            def safe_memory_path(name): return root/Path(str(name)).name
        fake=FakeModule()
        first=fake.neatbooks.read_book_chunks("BK-SHAKESPEARE",123,2)
        observed=_bni_observe_read_result(fake,first,trigger="read_book_chunks")
        idx=_bni_get_index(fake,"BK-SHAKESPEARE",query="Macbeth")
        auto=next((x for x in idx.get("entries",[]) if x.get("entry_type")=="work"),None)
        correction=_bni_correct_index(fake,book_id="BK-SHAKESPEARE",entry_id=str((auto or {}).get("entry_id") or ""),label="Macbeth",entry_type="work",start_ordinal=123,status="VERIFIED",reason="Verified work heading from the exact source chunk.") if auto else {"ok":False}
        final=_bni_get_index(fake,"BK-SHAKESPEARE",query="Macbeth",include_superseded=True)
        active=[x for x in final.get("entries",[]) if x.get("active")]
        superseded=[x for x in final.get("entries",[]) if not x.get("active") and x.get("status")=="SUPERSEDED"]
        with _bni_connect(fake) as db:
            events=int(db.execute("SELECT COUNT(*) FROM book_navigation_events WHERE actor='Assistant'").fetchone()[0])
            meta=db.execute("SELECT total_source_chunks FROM book_navigation_books WHERE book_id='BK-SHAKESPEARE'").fetchone()
        checks={
            "python_observes_source_chunks": observed.get("observed")==2,
            "python_extracts_work_without_model": auto is not None and auto.get("origin")=="python_auto" and auto.get("status")=="AUTO",
            "python_extracts_act_and_scene": any(x.get("entry_type")=="act" for x in _bni_get_index(fake,"BK-SHAKESPEARE").get("entries",[])) and any(x.get("entry_type")=="scene" for x in _bni_get_index(fake,"BK-SHAKESPEARE").get("entries",[])),
            "book_metadata_keeps_source_total": bool(meta and int(meta[0])==1240),
            "assistant_can_correct": correction.get("ok") is True and correction.get("actor")=="Assistant",
            "old_entry_preserved_as_superseded": bool(superseded),
            "corrected_entry_is_active": any(x.get("origin")=="assistant_correction" and x.get("label")=="Macbeth" for x in active),
            "correction_history_is_append_only": events==1,
            "source_book_not_modified": correction.get("source_book_modified") is False,
            "correction_source_was_verified": any(c[1]==123 for c in calls),
            "zero_model_bookkeeping": observed.get("model_calls")==0 and correction.get("model_calls")==0,
        }
        return {"ok":all(checks.values()),"checks":checks,"version":_BOOK_NAV_INDEX_VERSION,"live_database_modified":False}


# >>> NEAT-SUBSYSTEM:digest-entity-index rev=1
# Digest Entity & Keyword Index / source-grounded co-occurrence retrieval (7.4.23)
# ---------------------------------------------------------------------------
_DIGEST_ENTITY_INDEX_VERSION = "1.1-precise-evidence-subpassage-cooccurrence"
_DIGEST_ENTITY_ORIGINS = {"explicit", "inferred", "alias"}
_DIGEST_ENTITY_SCOPES = {"passage", "digest", "document"}
_DIGEST_ENTITY_DEFAULT_MIN_CONFIDENCE = 0.60
_DIGEST_ENTITY_MAX_TERMS_PER_PASSAGE = 128
_DIGEST_ENTITY_MAX_SUMMARY_CHARS = 2400
_DIGEST_ENTITY_MAX_ORIGINAL_CHARS = 24000
_DIGEST_ENTITY_EVIDENCE_TARGET_CHARS = 850
_DIGEST_ENTITY_EVIDENCE_MIN_CHARS = 260
_DIGEST_ENTITY_EVIDENCE_MAX_CHARS = 1250
_DIGEST_ENTITY_MAX_SUPPORT_PASSAGES = 2
_DIGEST_ENTITY_QUERY_STOPWORDS = {
    "a","an","and","are","as","at","be","been","being","both","but","by","can","could","did","do","does",
    "for","from","had","has","have","he","her","hers","him","his","i","if","in","into","is","it","its",
    "me","my","of","on","or","our","ours","she","so","that","the","their","theirs","them","they","this",
    "those","to","was","we","were","what","when","where","which","who","why","will","with","would","you","your",
    "about","find","get","give","show","tell","search","look","looking","happen","happened","happens","mentioned",
    "mention","talk","talked","talking","original","passage","passages","summary","summaries","resumer","résumé","resume",
}
_DIGEST_ENTITY_LEXICAL_STOPWORDS = _DIGEST_ENTITY_QUERY_STOPWORDS | {
    "after","again","against","all","also","am","any","because","before","between","during","each","few","further",
    "here","how","more","most","no","nor","not","now","off","once","only","other","out","over","same","some",
    "such","than","then","there","these","through","too","under","until","up","very","while","yes","yet","user",
    "assistant","assistant","message","messages","line","lines","context","evidence","memory","memories","source","sources",
}
_DIGEST_ENTITY_NON_NAMES = {
    "The","This","That","These","Those","And","But","Or","If","When","Where","Why","How","Then","After","Before",
    "User","Assistant","You","Assistant","System","Source","Section","Memory","Book","Chapter","Page","Line","Lines","Today",
    "Yesterday","Tomorrow","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday",
}


def _dei_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _dei_clean(value: object, limit: int = 500) -> str:
    return " ".join(str(value or "").replace("\x00", " ").split()).strip()[:limit]


def _dei_norm(value: object) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).casefold().replace("’", "'")
    text = re.sub(r"[^\wÀ-ÖØ-öø-ÿ'-]+", " ", text, flags=re.UNICODE)
    text = re.sub(r"\s+", " ", text).strip(" -'")
    if text.endswith("'s") and len(text) > 4:
        text = text[:-2]
    return text


def _dei_singular(value: str) -> str:
    value = _dei_norm(value)
    if len(value) > 5 and value.endswith("ies"):
        return value[:-3] + "y"
    if len(value) > 4 and value.endswith("s") and not value.endswith(("ss", "us", "is")):
        return value[:-1]
    return value


def _dei_query_terms(query: str) -> list[str]:
    raw = str(query or "").strip()
    if not raw:
        return []
    pieces: list[str] = []
    for quoted, bare in re.findall(r'"([^"\\]*(?:\\.[^"\\]*)*)"|([^\s]+)', raw):
        value = quoted or bare
        value = _dei_norm(value)
        if not value:
            continue
        if " " in value:
            pieces.append(value)
            continue
        if value in _DIGEST_ENTITY_QUERY_STOPWORDS or len(value) < 2:
            continue
        pieces.append(value)
    seen: set[str] = set()
    return [item for item in pieces if not (item in seen or seen.add(item))][:12]


def _dei_name_phrases(text: str) -> list[str]:
    # Conservative proper-name candidates. Structural EPUB/play labels are removed
    # before alias generation so phrases such as "Enter Romeo" or "Juliet Author"
    # cannot become misleading canonical entities.
    pattern = re.compile(
        r"(?<![\w'’-])([A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ0-9'’-]{1,}"
        r"(?:\s+[A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ0-9'’-]{1,}){0,2})(?![\w'’-])"
    )
    structural = {
        "author","authors","title","chapter","contents","content","scene","act","page","pages",
        "image","images","illustration","illustrations","editor","edited","translator","translated",
        "project","gutenberg","ebook","epub","copyright","license","credits","credit","proofreader",
        "transcriber","transcribed","produced","producer","html","xml","toc",
    }
    stage_prefixes = {"enter","enters","exit","exits","exeunt","reenter","re-enter","aside"}
    out: list[str] = []
    seen: set[str] = set()
    for match in pattern.finditer(str(text or "")):
        value = _dei_clean(match.group(1), 100)
        if not value:
            continue
        parts = value.split()
        while parts and _dei_norm(parts[0]) in stage_prefixes:
            parts.pop(0)
        value = " ".join(parts).strip()
        norm = _dei_norm(value)
        if not value or not norm:
            continue
        norm_parts = norm.split()
        if any(part in structural for part in norm_parts):
            continue
        if value in _DIGEST_ENTITY_NON_NAMES or value.casefold() in {x.casefold() for x in _DIGEST_ENTITY_NON_NAMES}:
            continue
        if norm not in seen:
            seen.add(norm)
            out.append(value)
    return out[:48]


def _dei_lexical_terms(text: str) -> list[str]:
    values: list[str] = []
    seen: set[str] = set()
    for token in re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿ0-9][A-Za-zÀ-ÖØ-öø-ÿ0-9'’-]*", str(text or "")):
        norm = _dei_norm(token)
        if not norm or len(norm) < 3 or norm in _DIGEST_ENTITY_LEXICAL_STOPWORDS or norm.isdigit():
            continue
        if norm not in seen:
            seen.add(norm)
            values.append(norm)
        if len(values) >= _DIGEST_ENTITY_MAX_TERMS_PER_PASSAGE:
            break
    return values


def _dei_entity_type(display: str, *, lexical: bool = False) -> str:
    low = _dei_norm(display)
    if lexical:
        if low in {"father","mother","brother","sister","parent","parents","friend","wife","husband","daughter","son"}:
            return "relationship"
        return "keyword"
    if any(word in low.split() for word in ("father","mother","brother","sister","wife","husband","daughter","son")):
        return "relationship"
    if any(word in low.split() for word in ("project","system","protocol","runtime","memory","tool","tools")):
        return "project_or_system"
    if any(word in low.split() for word in ("company","corporation","corp","inc","university","foundation","organization")):
        return "organization"
    parts = [p for p in re.split(r"\s+", display.strip()) if p]
    if len(parts) == 1 and parts[0][:1].isupper():
        return "person_or_character"
    return "named_entity"


def _dei_contains_norm(source_norm: str, candidate_norm: str) -> bool:
    source_norm = _dei_norm(source_norm)
    candidate_norm = _dei_norm(candidate_norm)
    return bool(candidate_norm and f" {candidate_norm} " in f" {source_norm} ")


def _dei_aliases(display: str) -> list[str]:
    aliases: list[str] = []
    raw = _dei_clean(display, 120)
    norm = _dei_norm(raw)
    if not raw or not norm:
        return []
    structural = {"enter","enters","exit","exits","exeunt","reenter","re-enter","author","title","chapter","scene","act","contents","image","illustration"}
    if any(part in structural for part in norm.split()):
        return []
    for value in (raw, norm):
        if value and value not in aliases:
            aliases.append(value)
    if norm.endswith("'s"):
        base = norm[:-2]
        if base and base not in aliases:
            aliases.append(base)
    parts = [p for p in norm.split() if len(p) >= 3 and p not in _DIGEST_ENTITY_QUERY_STOPWORDS]
    # Split-person aliases are useful for "Friar Lawrence" / "Prince Escalus",
    # but only after structural labels were filtered above.
    if 1 < len(parts) <= 3:
        for part in parts:
            if part not in aliases:
                aliases.append(part)
    return aliases[:8]


def _dei_passage_id(locator: dict, source_text_sha256: str) -> str:
    canonical = json.dumps({"locator": locator, "source_sha256": source_text_sha256}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "DP-" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:20].upper()


def _dei_group_id(source_kind: str, source_name: str, start: object, end: object, discriminator: str = "") -> str:
    raw = f"{source_kind}|{source_name}|{start}|{end}|{discriminator}"
    return "DG-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:18].upper()


def _dei_ensure_schema(module) -> None:
    with module.db_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS digest_passage_index(
            passage_id TEXT PRIMARY KEY,
            digest_group_id TEXT NOT NULL,
            source_kind TEXT NOT NULL,
            source_name TEXT NOT NULL,
            source_start INTEGER,
            source_end INTEGER,
            source_locator_json TEXT NOT NULL,
            source_text_sha256 TEXT NOT NULL,
            summary_text TEXT NOT NULL,
            summary_sha256 TEXT NOT NULL,
            memory_ids_json TEXT NOT NULL,
            digest_version TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            metadata_json TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_digest_passage_source
            ON digest_passage_index(source_name,source_start,source_end);
        CREATE INDEX IF NOT EXISTS idx_digest_passage_group
            ON digest_passage_index(digest_group_id);
        CREATE TABLE IF NOT EXISTS digest_entity_terms(
            passage_id TEXT NOT NULL,
            term_norm TEXT NOT NULL,
            canonical_norm TEXT NOT NULL,
            display_text TEXT NOT NULL,
            entity_type TEXT NOT NULL,
            origin TEXT NOT NULL,
            confidence REAL NOT NULL,
            is_alias INTEGER NOT NULL DEFAULT 0,
            evidence_locator_json TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            PRIMARY KEY(passage_id,term_norm,canonical_norm,origin),
            FOREIGN KEY(passage_id) REFERENCES digest_passage_index(passage_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_digest_entity_term
            ON digest_entity_terms(term_norm,confidence,origin);
        CREATE INDEX IF NOT EXISTS idx_digest_entity_canonical
            ON digest_entity_terms(canonical_norm,confidence);
        CREATE TABLE IF NOT EXISTS digest_entity_index_events(
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            event_type TEXT NOT NULL,
            passage_id TEXT,
            payload_json TEXT NOT NULL,
            event_sha256 TEXT NOT NULL
        );
        """)


def _dei_event(module, event_type: str, payload: dict, passage_id: str | None = None) -> None:
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    with module.db_connect() as db:
        db.execute(
            "INSERT INTO digest_entity_index_events(created_at,event_type,passage_id,payload_json,event_sha256) VALUES(?,?,?,?,?)",
            (_dei_now(), str(event_type), passage_id, canonical, hashlib.sha256(canonical.encode("utf-8")).hexdigest()),
        )


def _dei_build_terms(source_text: str, inferred_candidates: list[dict] | None = None) -> list[dict]:
    source_norm = _dei_norm(source_text)
    merged: dict[tuple[str, str], dict] = {}
    ordinal = 0

    def add(display: str, canonical: str, entity_type: str, origin: str, confidence: float, *, is_alias: bool = False) -> None:
        nonlocal ordinal
        term = _dei_norm(display)
        canonical_norm = _dei_norm(canonical)
        if not term or not canonical_norm:
            return
        if term in _DIGEST_ENTITY_LEXICAL_STOPWORDS and entity_type == "keyword":
            return
        key = (term, canonical_norm)
        candidate = {
            "term_norm": term, "canonical_norm": canonical_norm, "display_text": _dei_clean(display, 120),
            "entity_type": entity_type, "origin": origin, "confidence": max(0.0, min(1.0, float(confidence))),
            "is_alias": bool(is_alias), "ordinal": ordinal,
        }
        ordinal += 1
        prior = merged.get(key)
        if (prior is None or (prior["origin"] != "explicit" and origin == "explicit")
                or candidate["confidence"] > prior["confidence"]
                or (candidate["confidence"] == prior["confidence"] and prior.get("entity_type") == "keyword" and entity_type != "keyword")):
            merged[key] = candidate

    # Every useful lexical item comes from the original passage and therefore has
    # explicit provenance. This is what makes object/concept AND queries reliable.
    for token in _dei_lexical_terms(source_text):
        add(token, token, _dei_entity_type(token, lexical=True), "explicit", 1.0)

    # Preserve original named surfaces in addition to the lower-case lexical keys.
    for name in _dei_name_phrases(source_text):
        add(name, name, _dei_entity_type(name), "explicit", 1.0)
        for alias in _dei_aliases(name):
            if _dei_norm(alias) != _dei_norm(name):
                add(alias, name, _dei_entity_type(name), "explicit", 1.0, is_alias=True)

    # Digest claims/subjects can resolve a pronoun or implicit participant to a
    # canonical name. Those terms aid retrieval but never become explicit evidence.
    for item in inferred_candidates or []:
        display = _dei_clean(item.get("text"), 120)
        if not display:
            continue
        norm = _dei_norm(display)
        if not norm:
            continue
        confidence = max(0.0, min(0.95, float(item.get("confidence", 0.72))))
        entity_type = str(item.get("entity_type") or _dei_entity_type(display))
        explicit = _dei_contains_norm(source_norm, norm)
        origin = "explicit" if explicit else "inferred"
        if explicit:
            confidence = 1.0
        add(display, display, entity_type, origin, confidence)
        for alias in _dei_aliases(display):
            alias_norm = _dei_norm(alias)
            if alias_norm and alias_norm != norm:
                alias_explicit = _dei_contains_norm(source_norm, alias_norm)
                add(alias, display, entity_type, "explicit" if alias_explicit else origin,
                    1.0 if alias_explicit else confidence, is_alias=True)

    rows = list(merged.values())
    rows.sort(key=lambda row: (0 if row["origin"] == "explicit" else 1, -row["confidence"], row["ordinal"], row["term_norm"]))
    return rows[:_DIGEST_ENTITY_MAX_TERMS_PER_PASSAGE]


def _dei_store_passages(module, passages: list[dict], *, event_type: str = "index") -> dict:
    _dei_ensure_schema(module)
    inserted = 0
    updated = 0
    term_count = 0
    with module.db_connect() as db:
        db.execute("PRAGMA foreign_keys=ON")
        db.execute("BEGIN IMMEDIATE")
        try:
            for item in passages:
                locator = dict(item.get("locator") or {})
                source_text = str(item.get("source_text") or "")
                if not locator or not source_text.strip():
                    continue
                source_sha = hashlib.sha256(source_text.encode("utf-8")).hexdigest()
                passage_id = _dei_passage_id(locator, source_sha)
                summary = _dei_clean(item.get("summary") or "[No durable digest summary for this evidence passage.]", _DIGEST_ENTITY_MAX_SUMMARY_CHARS)
                summary_sha = hashlib.sha256(summary.encode("utf-8")).hexdigest()
                existing = db.execute("SELECT summary_text,memory_ids_json FROM digest_passage_index WHERE passage_id=?", (passage_id,)).fetchone()
                memory_ids = sorted({str(x) for x in (item.get("memory_ids") or []) if str(x).strip()})
                if existing:
                    old_summary = str(existing["summary_text"] or "")
                    old_ids = []
                    try: old_ids = json.loads(existing["memory_ids_json"] or "[]")
                    except Exception: old_ids = []
                    combined_summary = old_summary
                    if summary and summary not in old_summary:
                        combined_summary = _dei_clean((old_summary + " " + summary).strip(), _DIGEST_ENTITY_MAX_SUMMARY_CHARS)
                    summary = combined_summary
                    summary_sha = hashlib.sha256(summary.encode("utf-8")).hexdigest()
                    memory_ids = sorted(set(memory_ids) | {str(x) for x in old_ids})
                    updated += 1
                else:
                    inserted += 1
                metadata = dict(item.get("metadata") or {})
                now = _dei_now()
                db.execute("""
                    INSERT INTO digest_passage_index(
                        passage_id,digest_group_id,source_kind,source_name,source_start,source_end,
                        source_locator_json,source_text_sha256,summary_text,summary_sha256,memory_ids_json,
                        digest_version,provider,model,created_at,updated_at,metadata_json
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(passage_id) DO UPDATE SET
                        digest_group_id=excluded.digest_group_id,summary_text=excluded.summary_text,
                        summary_sha256=excluded.summary_sha256,memory_ids_json=excluded.memory_ids_json,
                        digest_version=excluded.digest_version,provider=excluded.provider,model=excluded.model,
                        updated_at=excluded.updated_at,metadata_json=excluded.metadata_json
                """, (
                    passage_id, str(item.get("digest_group_id") or ""), str(item.get("source_kind") or "unknown"),
                    str(item.get("source_name") or "unknown"), item.get("source_start"), item.get("source_end"),
                    json.dumps(locator, ensure_ascii=False, sort_keys=True, separators=(",", ":")), source_sha,
                    summary, summary_sha, json.dumps(memory_ids, ensure_ascii=False), str(item.get("digest_version") or _DIGEST_ENTITY_INDEX_VERSION),
                    str(item.get("provider") or ""), str(item.get("model") or ""), now, now,
                    json.dumps(metadata, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
                ))
                db.execute("DELETE FROM digest_entity_terms WHERE passage_id=?", (passage_id,))
                terms = _dei_build_terms(source_text, list(item.get("inferred_candidates") or []))
                for ordinal, term in enumerate(terms):
                    db.execute("""
                        INSERT OR REPLACE INTO digest_entity_terms(
                            passage_id,term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,evidence_locator_json,ordinal
                        ) VALUES(?,?,?,?,?,?,?,?,?,?)
                    """, (
                        passage_id, term["term_norm"], term["canonical_norm"], term["display_text"], term["entity_type"],
                        term["origin"], term["confidence"], 1 if term["is_alias"] else 0,
                        json.dumps(locator, ensure_ascii=False, sort_keys=True, separators=(",", ":")), ordinal,
                    ))
                term_count += len(terms)
            db.commit()
        except Exception:
            db.rollback()
            raise
    payload = {"passages_inserted": inserted, "passages_updated": updated, "terms_indexed": term_count, "event_type": event_type}
    try: _dei_event(module, event_type, payload)
    except Exception: pass
    return payload


def _dei_trim_span(text: str, start: int, end: int) -> tuple[int, int, str]:
    start = max(0, int(start)); end = min(len(text), max(start, int(end)))
    while start < end and text[start].isspace():
        start += 1
    while end > start and text[end - 1].isspace():
        end -= 1
    return start, end, text[start:end]


def _dei_split_evidence_passages(text: str, *, target: int = _DIGEST_ENTITY_EVIDENCE_TARGET_CHARS,
                                  minimum: int = _DIGEST_ENTITY_EVIDENCE_MIN_CHARS,
                                  maximum: int = _DIGEST_ENTITY_EVIDENCE_MAX_CHARS) -> list[dict]:
    """Split a digest/book chunk into exact contiguous source spans without changing the source text."""
    raw = str(text or "")
    if not raw.strip():
        return []
    target = max(320, int(target)); minimum = max(80, min(int(minimum), target)); maximum = max(target, int(maximum))
    # Atomic spans follow source line boundaries. Long lines are split near sentence/word boundaries.
    atoms: list[tuple[int, int]] = []
    offset = 0
    for line in raw.splitlines(keepends=True) or [raw]:
        line_start = offset; line_end = offset + len(line); offset = line_end
        if len(line) <= maximum:
            atoms.append((line_start, line_end)); continue
        cursor = line_start
        while cursor < line_end:
            hard = min(line_end, cursor + maximum)
            if hard < line_end:
                window = raw[cursor:hard]
                candidates = [m.end() for m in re.finditer(r"[.!?;:]\s+|\s+", window)]
                cut = cursor + (candidates[-1] if candidates and candidates[-1] >= minimum else len(window))
            else:
                cut = line_end
            if cut <= cursor: cut = min(line_end, cursor + maximum)
            atoms.append((cursor, cut)); cursor = cut
    if not atoms:
        atoms = [(0, len(raw))]
    passages: list[dict] = []
    cur_start = atoms[0][0]; cur_end = atoms[0][1]
    for a_start, a_end in atoms[1:]:
        proposed = a_end - cur_start
        current = cur_end - cur_start
        if proposed > maximum or (current >= target and current >= minimum):
            s,e,piece = _dei_trim_span(raw, cur_start, cur_end)
            if piece:
                passages.append({"char_start":s,"char_end":e,"text":piece})
            cur_start,cur_end = a_start,a_end
        else:
            cur_end = a_end
    s,e,piece = _dei_trim_span(raw, cur_start, cur_end)
    if piece:
        passages.append({"char_start":s,"char_end":e,"text":piece})
    # Merge a tiny final fragment into its predecessor when safe.
    if len(passages) > 1 and len(passages[-1]["text"]) < minimum:
        prev,last = passages[-2],passages[-1]
        if last["char_end"] - prev["char_start"] <= maximum:
            s,e,piece = _dei_trim_span(raw, prev["char_start"], last["char_end"])
            passages[-2:] = [{"char_start":s,"char_end":e,"text":piece}]
    for i,item in enumerate(passages,1): item["passage_ordinal"] = i
    return passages


def _dei_support_terms(text: str) -> set[str]:
    return {_dei_singular(x) for x in _dei_lexical_terms(text) if _dei_singular(x)}


def _dei_select_support_passages(passages: list[dict], claim_text: str, inferred: list[dict] | None = None,
                                  max_hits: int = _DIGEST_ENTITY_MAX_SUPPORT_PASSAGES) -> list[int]:
    """Select only passages with deterministic lexical support for a digest claim."""
    if not passages:
        return []
    claim_terms = _dei_support_terms(claim_text)
    candidate_norms = {_dei_norm(x.get("text")) for x in (inferred or []) if _dei_norm(x.get("text"))}
    scored: list[tuple[float,int,int]] = []
    for idx,p in enumerate(passages):
        p_terms = _dei_support_terms(p.get("text", ""))
        overlap = claim_terms & p_terms
        # Named candidates explicitly present in a span strongly identify support,
        # while other lexical overlap lets implicit/pronoun passages still win.
        explicit_names = sum(1 for n in candidate_norms if _dei_contains_norm(_dei_norm(p.get("text","")), n))
        score = (3.0 * explicit_names) + float(len(overlap))
        if claim_terms:
            score += len(overlap) / max(1.0, len(claim_terms) ** 0.5)
        scored.append((score, len(overlap), idx))
    scored.sort(key=lambda x: (-x[0], -x[1], x[2]))
    positive = [idx for score,overlap,idx in scored if score > 0 and overlap > 0]
    return positive[:max(1, min(int(max_hits), len(positive)))]


def _dei_book_chunk_record(book_id: str, chunk_id: str) -> dict:
    books_module = sys.modules.get("neatbooks_v1_2_stable")
    if books_module is None:
        books_module = _load_embedded("neatbooks_v1_2_stable")
    with books_module.connect() as db:
        row = db.execute("SELECT * FROM book_chunks WHERE book_id=? AND chunk_id=?", (str(book_id), str(chunk_id))).fetchone()
    if row is None:
        return {"text":"", "ordinal":0}
    data = dict(row)
    return {"text":str(data.get("text") or ""), "ordinal":int(data.get("ordinal") or 0)}


def _dei_locator_text(module, locator: dict) -> dict:
    kind = str(locator.get("kind") or "")
    text = ""
    error = None
    try:
        if kind == "sqlite_chat":
            start, end = int(locator["start"]), int(locator["end"])
            with module.db_connect() as db:
                rows = db.execute(
                    "SELECT message_id,timestamp,role,provider,model,content FROM chat_messages WHERE message_id BETWEEN ? AND ? ORDER BY message_id",
                    (start, end),
                ).fetchall()
            text = "\n".join(str(r["content"]) for r in rows)
        elif kind == "text_file":
            start, end = int(locator["start"]), int(locator["end"])
            path = module.safe_memory_path(str(locator["source_name"]))
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
            text = "\n".join(lines[max(0,start-1):max(0,end)])
        elif kind in {"book_chunk", "book_span"}:
            record = _dei_book_chunk_record(str(locator["book_id"]), str(locator["chunk_id"]))
            full = str(record.get("text") or "")
            if kind == "book_span":
                start = max(0, int(locator.get("char_start") or 0)); end = min(len(full), int(locator.get("char_end") or len(full)))
                text = full[start:end]
            else:
                text = full
        else:
            error = f"Unsupported source locator kind: {kind or '[missing]'}"
    except Exception as exc:
        error = f"{type(exc).__name__}: {exc}"
    return {"text": text[:_DIGEST_ENTITY_MAX_ORIGINAL_CHARS], "complete": len(text) <= _DIGEST_ENTITY_MAX_ORIGINAL_CHARS, "error": error}


def _dei_status(module) -> dict:
    _dei_ensure_schema(module)
    with module.db_connect() as db:
        p = db.execute("SELECT COUNT(*) n,COUNT(DISTINCT source_name) docs,COUNT(DISTINCT digest_group_id) groups FROM digest_passage_index").fetchone()
        t = db.execute("SELECT COUNT(*) n,SUM(CASE WHEN origin='explicit' THEN 1 ELSE 0 END) explicit_n,SUM(CASE WHEN origin='inferred' THEN 1 ELSE 0 END) inferred_n FROM digest_entity_terms").fetchone()
        latest = db.execute("SELECT created_at,event_type,payload_json,event_sha256 FROM digest_entity_index_events ORDER BY event_id DESC LIMIT 1").fetchone()
    return {
        "ok": True, "version": _DIGEST_ENTITY_INDEX_VERSION,
        "passages": int(p["n"] or 0), "digest_groups": int(p["groups"] or 0), "documents": int(p["docs"] or 0),
        "terms": int(t["n"] or 0), "explicit_terms": int(t["explicit_n"] or 0), "inferred_terms": int(t["inferred_n"] or 0),
        "default_scope": "passage", "default_semantics": "AND/co-occurrence in the same exact evidence passage",
        "inferred_is_authoritative": False,
        "evidence_passage_mode": "precise_subpassage",
        "evidence_target_chars": _DIGEST_ENTITY_EVIDENCE_TARGET_CHARS,
        "evidence_max_chars": _DIGEST_ENTITY_EVIDENCE_MAX_CHARS,
        "latest_event": dict(latest) if latest else None,
    }


def _dei_search(module, query: str, scope: str = "passage", include_inferred: bool = True,
                min_confidence: float = _DIGEST_ENTITY_DEFAULT_MIN_CONFIDENCE, limit: int = 20) -> dict:
    _dei_ensure_schema(module)
    scope = str(scope or "passage").casefold()
    if scope not in _DIGEST_ENTITY_SCOPES:
        raise ValueError(f"scope must be one of {sorted(_DIGEST_ENTITY_SCOPES)}")
    terms = _dei_query_terms(query)
    if not terms:
        return {"ok": True, "query": query, "query_terms": [], "scope": scope, "count": 0, "results": [], "note": "No meaningful query terms remained after normalization."}
    min_confidence = max(0.0, min(1.0, float(min_confidence)))
    limit = max(1, min(100, int(limit)))
    placeholders = ",".join("?" for _ in terms)
    origin_sql = "" if include_inferred else " AND t.origin='explicit'"
    with module.db_connect() as db:
        rows = db.execute(f"""
            SELECT t.*,p.digest_group_id,p.source_kind,p.source_name,p.source_start,p.source_end,
                   p.source_locator_json,p.source_text_sha256,p.summary_text,p.memory_ids_json,p.digest_version,p.provider,p.model,p.created_at
            FROM digest_entity_terms t JOIN digest_passage_index p ON p.passage_id=t.passage_id
            WHERE t.term_norm IN ({placeholders}) AND t.confidence>=? {origin_sql}
            ORDER BY p.created_at DESC,t.confidence DESC
        """, [*terms, min_confidence]).fetchall()
    passage_hits: dict[str, dict] = {}
    for row in rows:
        pid = str(row["passage_id"])
        hit = passage_hits.setdefault(pid, {"row": dict(row), "matched": set(), "matches": []})
        term_norm = str(row["term_norm"])
        if term_norm in terms:
            hit["matched"].add(term_norm)
            hit["matches"].append({
                "query_term": term_norm, "canonical": row["canonical_norm"], "display": row["display_text"],
                "entity_type": row["entity_type"], "origin": row["origin"], "confidence": float(row["confidence"]),
                "is_alias": bool(row["is_alias"]),
            })

    required = set(terms)
    groups: dict[str, dict] = {}
    if scope == "passage":
        for pid, hit in passage_hits.items():
            if hit["matched"] >= required:
                groups[pid] = {"matched": set(hit["matched"]), "passages": [hit]}
    else:
        for pid, hit in passage_hits.items():
            row = hit["row"]
            key = str(row["digest_group_id"] if scope == "digest" else row["source_name"])
            group = groups.setdefault(key, {"matched": set(), "passages": []})
            group["matched"].update(hit["matched"])
            group["passages"].append(hit)
        groups = {key: value for key, value in groups.items() if value["matched"] >= required}

    results: list[dict] = []
    for key, group in groups.items():
        passages_out = []
        explicit_matches = 0
        min_match_conf = 1.0
        for hit in group["passages"]:
            row = hit["row"]
            for match in hit["matches"]:
                explicit_matches += 1 if match["origin"] == "explicit" else 0
                min_match_conf = min(min_match_conf, match["confidence"])
            try: locator = json.loads(row["source_locator_json"])
            except Exception: locator = {}
            try: mids = json.loads(row["memory_ids_json"] or "[]")
            except Exception: mids = []
            passages_out.append({
                "passage_id": row["passage_id"], "summary": row["summary_text"], "source_kind": row["source_kind"],
                "source_name": row["source_name"], "source_start": row["source_start"], "source_end": row["source_end"],
                "source_locator": locator, "source_text_sha256": row["source_text_sha256"], "memory_ids": mids,
                "matches": hit["matches"],
            })
        results.append({
            "scope_key": key, "scope": scope, "matched_terms": sorted(group["matched"]), "all_terms_matched": True,
            "explicit_match_rows": explicit_matches, "minimum_match_confidence": round(min_match_conf, 4),
            "passages": passages_out,
        })
    results.sort(key=lambda r: (-r["explicit_match_rows"], -r["minimum_match_confidence"], str(r["scope_key"])))
    return {
        "ok": True, "query": query, "query_terms": terms, "operator": "AND", "scope": scope,
        "include_inferred": bool(include_inferred), "min_confidence": min_confidence,
        "count": min(len(results), limit), "results": results[:limit],
        "evidence_rule": "Summaries navigate; source locators and source hashes identify the original evidence. Inferred terms aid retrieval but are not authoritative evidence.",
    }


def _dei_get_passage(module, passage_id: str, include_original: bool = False) -> dict:
    _dei_ensure_schema(module)
    ref = str(passage_id or "").strip().upper()
    with module.db_connect() as db:
        rows = db.execute("SELECT * FROM digest_passage_index WHERE upper(passage_id) LIKE ? ORDER BY passage_id LIMIT 3", (ref + "%",)).fetchall()
        if len(rows) != 1:
            return {"ok": False, "error": "Passage ID must resolve to exactly one digest passage.", "matches": [r["passage_id"] for r in rows]}
        row = dict(rows[0])
        terms = [dict(r) for r in db.execute("SELECT term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,ordinal FROM digest_entity_terms WHERE passage_id=? ORDER BY ordinal", (row["passage_id"],)).fetchall()]
    try: locator = json.loads(row["source_locator_json"])
    except Exception: locator = {}
    try: mids = json.loads(row["memory_ids_json"] or "[]")
    except Exception: mids = []
    output = {
        "ok": True, "passage_id": row["passage_id"], "digest_group_id": row["digest_group_id"],
        "summary": row["summary_text"], "source_kind": row["source_kind"], "source_name": row["source_name"],
        "source_start": row["source_start"], "source_end": row["source_end"], "source_locator": locator,
        "source_text_sha256": row["source_text_sha256"], "memory_ids": mids, "digest_version": row["digest_version"],
        "provider": row["provider"], "model": row["model"], "terms": terms,
        "summary_is_authoritative_evidence": False,
    }
    if include_original:
        source = _dei_locator_text(module, locator)
        actual_sha = hashlib.sha256(str(source.get("text") or "").encode("utf-8")).hexdigest() if source.get("text") else None
        output["original"] = source
        output["source_verification"] = {
            "expected_sha256": row["source_text_sha256"], "actual_sha256": actual_sha,
            "verified": bool(actual_sha and actual_sha == row["source_text_sha256"] and source.get("complete")),
            "note": "A truncated source view cannot be hash-verified." if source.get("text") and not source.get("complete") else None,
        }
    return output


def _dei_inferred_from_claim(claim: str, subjects: list[str] | None, confidence: float = 0.72) -> list[dict]:
    out: list[dict] = []
    for subject in subjects or []:
        value = _dei_clean(subject, 120)
        if value:
            out.append({"text": value, "confidence": min(0.95, confidence), "entity_type": _dei_entity_type(value)})
    for name in _dei_name_phrases(claim):
        out.append({"text": name, "confidence": min(0.95, confidence), "entity_type": _dei_entity_type(name)})
    seen: set[str] = set()
    return [row for row in out if not (_dei_norm(row["text"]) in seen or seen.add(_dei_norm(row["text"])))]


def _dei_index_section_from_batch(module, digest_module, section: dict, batch: dict, report: dict, backend) -> dict:
    source_kind = str(section.get("kind") or "unknown")
    source_name = str(section.get("source_name") or "unknown")
    group_id = _dei_group_id(source_kind, source_name, section.get("start"), section.get("end"))
    grouped: dict[tuple[int,int], dict] = {}
    for raw in (batch.get("memories") or []) if isinstance(batch, dict) else []:
        if not isinstance(raw, dict):
            continue
        claim = _dei_clean(raw.get("claim"), 800)
        details = _dei_clean(raw.get("details"), 1200)
        confidence = 0.72 if str(raw.get("interpretation") or "paraphrase").casefold() in {"inference","hypothesis"} else 0.88
        inferred = _dei_inferred_from_claim(f"{claim} {details}", raw.get("subjects") or [], confidence)
        for evidence in raw.get("evidence") or []:
            if not isinstance(evidence, list) or len(evidence) != 2:
                continue
            start, end = int(evidence[0]), int(evidence[1])
            if start < int(section.get("start") or start) or end > int(section.get("end") or end) or end < start:
                continue
            key = (start, end)
            item = grouped.setdefault(key, {"summaries": [], "inferred": []})
            if claim and claim not in item["summaries"]:
                item["summaries"].append(claim)
            item["inferred"].extend(inferred)
    passages: list[dict] = []
    report_ids = list(report.get("ids") or []) if isinstance(report, dict) else []
    for (start, end), item in grouped.items():
        source_text = digest_module.source_excerpt(section, start, end)
        if not source_text.strip():
            continue
        locator = {"kind": source_kind, "source_name": source_name, "start": start, "end": end}
        passages.append({
            "digest_group_id": group_id, "source_kind": source_kind, "source_name": source_name,
            "source_start": start, "source_end": end, "locator": locator, "source_text": source_text,
            "summary": " ".join(item["summaries"]), "memory_ids": report_ids,
            "inferred_candidates": item["inferred"], "digest_version": getattr(digest_module, "NEATDIGEST_VERSION", "unknown"),
            "provider": getattr(backend, "provider", ""), "model": getattr(backend, "model_id", ""),
            "metadata": {"index_source": "digest_batch_evidence", "section_start": section.get("start"), "section_end": section.get("end")},
        })
    return _dei_store_passages(module, passages, event_type="digest_section_indexed") if passages else {"passages_inserted": 0, "passages_updated": 0, "terms_indexed": 0}


def _dei_index_book_batch(module, digest_module, *, backend, run_id: str, book: dict, batch: list[dict], proposals: list[dict], registry: dict, result: dict) -> dict:
    group_id = _dei_group_id("book_batch", str(book.get("book_id") or "book"), batch[0].get("ordinal") if batch else 0, batch[-1].get("ordinal") if batch else 0, run_id)
    by_chunk: dict[str, dict] = {}
    for row in batch:
        cid = str(row.get("chunk_id") or "")
        text = str(row.get("text") or "")
        by_chunk[cid] = {"row": row, "passages": _dei_split_evidence_passages(text), "claims": []}
    for proposal in proposals or []:
        if not isinstance(proposal, dict):
            continue
        claim = _dei_clean(proposal.get("claim"), 800)
        details = _dei_clean(proposal.get("details"), 1200)
        claim_text = _dei_clean(f"{claim} {details}", 2000)
        conf = 0.72 if str(proposal.get("interpretation") or "paraphrase").casefold() in {"inference","hypothesis"} else 0.88
        inferred = _dei_inferred_from_claim(claim_text, proposal.get("subjects") if isinstance(proposal.get("subjects"), list) else [], conf)
        try:
            resolved = digest_module._resolve_book_refs(proposal.get("source_refs") or proposal.get("sources"), registry)
        except Exception:
            resolved = []
        for src in resolved:
            cid = str(src.get("chunk_id") or "")
            item = by_chunk.get(cid)
            if not item:
                continue
            selected = _dei_select_support_passages(item["passages"], claim_text, inferred)
            for idx in selected:
                item["claims"].append({"passage_index": idx, "claim": claim, "inferred": inferred})
    all_mids = list(result.get("inserted") or []) if isinstance(result, dict) else []
    fallback_summary = _dei_clean(result.get("neatblock", {}).get("summary") if isinstance(result.get("neatblock"), dict) else "", 1600)
    passages: list[dict] = []
    for cid, item in by_chunk.items():
        row = item["row"]
        ordinal = int(row.get("ordinal") or 0)
        support: dict[int, dict] = {}
        for claim_row in item["claims"]:
            bucket = support.setdefault(int(claim_row["passage_index"]), {"summaries": [], "inferred": []})
            if claim_row["claim"] and claim_row["claim"] not in bucket["summaries"]:
                bucket["summaries"].append(claim_row["claim"])
            bucket["inferred"].extend(claim_row["inferred"])
        for idx,span in enumerate(item["passages"]):
            bucket = support.get(idx, {"summaries": [], "inferred": []})
            locator = {
                "kind": "book_span", "book_id": str(book.get("book_id") or ""), "chunk_id": cid,
                "ordinal": ordinal, "passage_ordinal": int(span.get("passage_ordinal") or idx + 1),
                "char_start": int(span["char_start"]), "char_end": int(span["char_end"]),
                "source_name": str(book.get("title") or book.get("book_id") or "book"),
            }
            passages.append({
                "digest_group_id": group_id, "source_kind": "book_span", "source_name": f"book:{book.get('book_id')}",
                "source_start": ordinal, "source_end": ordinal,
                "locator": locator, "source_text": span["text"],
                "summary": " ".join(bucket["summaries"]) or fallback_summary,
                "memory_ids": all_mids, "inferred_candidates": bucket["inferred"],
                "digest_version": getattr(digest_module, "NEATDIGEST_VERSION", "unknown"), "provider": getattr(backend, "provider", ""), "model": getattr(backend, "model_id", ""),
                "metadata": {"index_source": "book_digest_subpassage", "run_id": run_id, "book_id": str(book.get("book_id") or ""), "chunk_id": cid, "chunk_ordinal": ordinal, "passage_ordinal": int(span.get("passage_ordinal") or idx + 1), "char_start": int(span["char_start"]), "char_end": int(span["char_end"])},
            })
    return _dei_store_passages(module, passages, event_type="book_digest_subpassages_indexed") if passages else {"passages_inserted": 0, "passages_updated": 0, "terms_indexed": 0}


def _dei_backfill(module, *, clear: bool = False, limit: int = 0) -> dict:
    _dei_ensure_schema(module)
    if clear:
        with module.db_connect() as db:
            db.execute("DELETE FROM digest_entity_terms")
            db.execute("DELETE FROM digest_passage_index")
    with module.db_connect() as db:
        sql = "SELECT id,summary,data,confidence,interpretation,payload_json FROM memories ORDER BY created_at"
        if limit and int(limit) > 0:
            sql += f" LIMIT {max(1,min(100000,int(limit)))}"
        rows = db.execute(sql).fetchall()
    passages: list[dict] = []
    scanned = 0; unavailable = 0
    for row in rows:
        scanned += 1
        try: payload = json.loads(row["payload_json"] or "{}")
        except Exception: payload = {}
        claim = _dei_clean(row["summary"], 800)
        details = _dei_clean(row["data"], 1200)
        subjects = payload.get("subjects") if isinstance(payload.get("subjects"), list) else []
        confidence = float(row["confidence"] or 0.72)
        inferred = _dei_inferred_from_claim(f"{claim} {details}", subjects, min(0.92, confidence))
        sources = payload.get("sources") if isinstance(payload.get("sources"), list) else []
        if not sources:
            with module.db_connect() as db:
                sources = [dict(x) for x in db.execute("SELECT file,line_start,line_end FROM memory_sources WHERE memory_id=? ORDER BY ordinal", (row["id"],)).fetchall()]
        for source in sources:
            locator: dict
            if source.get("chunk_id") and (source.get("book_id") or payload.get("book_id")):
                book_id = str(source.get("book_id") or payload.get("book_id")); chunk_id = str(source.get("chunk_id"))
                record = _dei_book_chunk_record(book_id, chunk_id)
                text = str(record.get("text") or "")
                if not text.strip():
                    unavailable += 1; continue
                ordinal = int(source.get("ordinal") or record.get("ordinal") or source.get("line_start") or 0)
                source_name = f"book:{book_id}"
                split = _dei_split_evidence_passages(text)
                selected = _dei_select_support_passages(split, f"{claim} {details}", inferred)
                selected_set = set(selected)
                for idx,span in enumerate(split):
                    locator = {"kind":"book_span","book_id":book_id,"chunk_id":chunk_id,"ordinal":ordinal,"passage_ordinal":int(span.get("passage_ordinal") or idx+1),"char_start":int(span["char_start"]),"char_end":int(span["char_end"]),"source_name":str(source.get("title") or payload.get("book_title") or payload.get("book_id") or "book")}
                    passages.append({
                        "digest_group_id": _dei_group_id("backfill-book", source_name, ordinal, ordinal, chunk_id), "source_kind": "book_span", "source_name": source_name,
                        "source_start": ordinal, "source_end": ordinal, "locator": locator, "source_text": span["text"],
                        "summary": claim if idx in selected_set else "", "memory_ids": [str(row["id"])], "inferred_candidates": inferred if idx in selected_set else [],
                        "digest_version": "backfill-precise-evidence-passages", "provider": "python", "model": "none",
                        "metadata": {"index_source":"memory_backfill_book_subpassage","memory_id":str(row["id"]),"interpretation":str(row["interpretation"] or ""),"chunk_id":chunk_id,"chunk_ordinal":ordinal,"passage_ordinal":int(span.get("passage_ordinal") or idx+1),"char_start":int(span["char_start"]),"char_end":int(span["char_end"])},
                    })
                continue
            else:
                file_name = str(source.get("file") or "")
                start = int(source.get("line_start") or 0); end = int(source.get("line_end") or start)
                source_kind = "sqlite_chat" if file_name == "sqlite:chat_messages" else "text_file"
                source_name = file_name
                locator = {"kind":source_kind,"source_name":source_name,"start":start,"end":end}
            original = _dei_locator_text(module, locator)
            text = str(original.get("text") or "")
            if not text.strip() or original.get("error"):
                unavailable += 1; continue
            passages.append({
                "digest_group_id": _dei_group_id("backfill", source_name, start, end), "source_kind": source_kind, "source_name": source_name,
                "source_start": start, "source_end": end, "locator": locator, "source_text": text,
                "summary": claim, "memory_ids": [str(row["id"])], "inferred_candidates": inferred,
                "digest_version": "backfill-from-existing-memory", "provider": "python", "model": "none",
                "metadata": {"index_source":"memory_backfill","memory_id":str(row["id"]),"interpretation":str(row["interpretation"] or "")},
            })
    result = _dei_store_passages(module, passages, event_type="backfill") if passages else {"passages_inserted":0,"passages_updated":0,"terms_indexed":0}
    result.update({"ok": True, "memories_scanned": scanned, "source_passages_available": len(passages), "source_passages_unavailable": unavailable, "clear_first": bool(clear)})
    return result


def _install_digest_entity_index_digest(digest_module, memory_module) -> None:
    if getattr(digest_module, "_DIGEST_ENTITY_INDEX_BRIDGE_INSTALLED", False):
        return
    _dei_ensure_schema(memory_module)
    original_call = digest_module.call_digest_model
    def call_with_entity_capture(backend, section):
        batch = original_call(backend, section)
        digest_module._DEI_LAST_BATCH = {"key": (section.get("kind"), section.get("source_name"), section.get("start"), section.get("end")), "batch": batch}
        return batch
    digest_module.call_digest_model = call_with_entity_capture

    original_process = digest_module.process_section
    def process_with_entity_index(backend, section, *, checkpoint_name):
        digest_module._DEI_LAST_BATCH = None
        report = original_process(backend, section, checkpoint_name=checkpoint_name)
        capture = getattr(digest_module, "_DEI_LAST_BATCH", None)
        expected = (section.get("kind"), section.get("source_name"), section.get("start"), section.get("end"))
        if isinstance(capture, dict) and capture.get("key") == expected:
            index_report = _dei_index_section_from_batch(memory_module, digest_module, section, capture.get("batch") or {}, report, backend)
            if isinstance(report, dict): report["entity_index"] = index_report
        return report
    digest_module.process_section = process_with_entity_index

    original_book_insert = digest_module._insert_book_digest_batch
    def book_insert_with_entity_index(**kwargs):
        result = original_book_insert(**kwargs)
        if isinstance(result, dict) and result.get("shared_knowledge"):
            return result
        try:
            index_report = _dei_index_book_batch(memory_module, digest_module, result=result, **kwargs)
            if isinstance(result, dict): result["entity_index"] = index_report
        except Exception as exc:
            if isinstance(result, dict): result["entity_index"] = {"ok": False, "error": f"{type(exc).__name__}: {exc}"}
            try: _dei_event(memory_module, "book_digest_index_error", {"error": f"{type(exc).__name__}: {exc}", "run_id": kwargs.get("run_id")})
            except Exception: pass
        return result
    digest_module._insert_book_digest_batch = book_insert_with_entity_index

    original_audit = digest_module.deep_audit
    def audit_with_entity_index():
        report = original_audit()
        if isinstance(report, dict):
            report["digest_entity_index"] = _dei_status(memory_module)
        return report
    digest_module.deep_audit = audit_with_entity_index
    digest_module.DIGEST_ENTITY_INDEX_VERSION = _DIGEST_ENTITY_INDEX_VERSION
    digest_module._DIGEST_ENTITY_INDEX_BRIDGE_INSTALLED = True


def digest_entity_index_self_test(module) -> dict:
    original_db_connect = module.db_connect
    original_safe = module.safe_memory_path
    checks: dict[str, bool] = {}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-digest-entity-index-") as folder:
            root = Path(folder); db_path = root / "test.db"
            def test_connect():
                conn = sqlite3.connect(db_path)
                conn.row_factory = sqlite3.Row
                return conn
            module.db_connect = test_connect
            module.safe_memory_path = lambda name: root / str(name)
            _dei_ensure_schema(module)
            (root / "story.txt").write_text(
                "The sword rested beside the old gate.\nShe reached for the sword before dawn.\nElara spoke to the guard.\nThe shield remained in storage.\n",
                encoding="utf-8",
            )
            p1_text = "The sword rested beside the old gate.\nShe reached for the sword before dawn."
            p2_text = "Elara spoke to the guard."
            p3_text = "The shield remained in storage."
            base = {
                "source_kind":"text_file","source_name":"story.txt","digest_version":"test","provider":"python","model":"none","memory_ids":[],
            }
            stored = _dei_store_passages(module, [
                {**base,"digest_group_id":"DG-ONE","source_start":1,"source_end":2,"locator":{"kind":"text_file","source_name":"story.txt","start":1,"end":2},"source_text":p1_text,"summary":"Elara reaches for the sword.","inferred_candidates":[{"text":"Elara","confidence":0.91,"entity_type":"person_or_character"}]},
                {**base,"digest_group_id":"DG-TWO","source_start":3,"source_end":3,"locator":{"kind":"text_file","source_name":"story.txt","start":3,"end":3},"source_text":p2_text,"summary":"Elara speaks to the guard.","inferred_candidates":[]},
                {**base,"digest_group_id":"DG-TWO","source_start":4,"source_end":4,"locator":{"kind":"text_file","source_name":"story.txt","start":4,"end":4},"source_text":p3_text,"summary":"A shield remains stored.","inferred_candidates":[]},
            ], event_type="self_test")
            strict = _dei_search(module, "Elara Sword", "passage", True, 0.6, 20)
            explicit_only = _dei_search(module, "Elara Sword", "passage", False, 0.6, 20)
            explicit_name = _dei_search(module, "Elara", "passage", False, 0.6, 20)
            separated = _dei_search(module, "Elara Shield", "passage", True, 0.6, 20)
            digest_scope = _dei_search(module, "Elara Shield", "digest", True, 0.6, 20)
            pid = strict["results"][0]["passages"][0]["passage_id"] if strict.get("results") else ""
            detail = _dei_get_passage(module, pid, include_original=True) if pid else {}
            explicit_pid = next((p["passage_id"] for r in explicit_name.get("results", []) for p in r.get("passages", []) if p.get("source_start") == 3), "")
            explicit_detail = _dei_get_passage(module, explicit_pid, include_original=False) if explicit_pid else {}
            # Existing-memory backfill is model-free and lets an upgraded database
            # populate the index without re-digesting its source material.
            with module.db_connect() as db:
                db.execute("CREATE TABLE memories(id TEXT PRIMARY KEY,summary TEXT,data TEXT,confidence REAL,interpretation TEXT,payload_json TEXT,created_at TEXT)")
                payload = {"subjects":["Elara"],"sources":[{"file":"story.txt","line_start":1,"line_end":2}]}
                db.execute("INSERT INTO memories VALUES(?,?,?,?,?,?,?)", ("NB-OLD","Elara reaches for the sword.","",0.88,"paraphrase",json.dumps(payload),_dei_now()))
            backfill = _dei_backfill(module, clear=False)
            status = _dei_status(module)
            terms = detail.get("terms") or []
            explicit_terms = explicit_detail.get("terms") or []
            checks = {
                "stored_three_passages": stored.get("passages_inserted") == 3,
                "strict_and_matches_inferred_elara_plus_explicit_sword": strict.get("count") == 1,
                "strict_same_passage_rejects_separated_terms": separated.get("count") == 0,
                "digest_scope_can_match_terms_across_same_digest_group": digest_scope.get("count") == 1,
                "explicit_only_does_not_promote_inferred_name": explicit_only.get("count") == 0,
                "inferred_entity_is_labeled": any(r.get("canonical_norm") == "elara" and r.get("origin") == "inferred" for r in terms),
                "explicit_object_is_labeled": any(r.get("term_norm") == "sword" and r.get("origin") == "explicit" for r in terms),
                "explicit_name_typed_as_person_or_character": any(r.get("term_norm") == "elara" and r.get("origin") == "explicit" and r.get("entity_type") == "person_or_character" for r in explicit_terms),
                "original_source_round_trip_verified": bool((detail.get("source_verification") or {}).get("verified")),
                "summary_not_authoritative": detail.get("summary_is_authoritative_evidence") is False,
                "backfill_scans_existing_memory": backfill.get("memories_scanned") == 1 and backfill.get("source_passages_available") == 1,
                "backfill_does_not_duplicate_same_source_passage": status.get("passages") == 3,
                "status_counts_passages": status.get("passages") == 3,
                "default_scope_is_passage": status.get("default_scope") == "passage",
                "query_operator_is_and": strict.get("operator") == "AND",
            }
            precision = digest_entity_precision_self_test(module)
            checks["precise_subpassage_regression_suite"] = bool(precision.get("ok"))
            return {"ok": all(checks.values()), "checks": checks, "sample_search": strict, "status": status, "precision": precision}
    finally:
        module.db_connect = original_db_connect
        module.safe_memory_path = original_safe


def digest_entity_precision_self_test(module) -> dict:
    checks: dict[str, bool] = {}
    # One synthetic chunk intentionally mentions JULIET far away from a later
    # pronoun+dagger passage. Whole-chunk classification would call Juliet explicit;
    # precise subpassages must keep the later reference inferred.
    filler = "The household waited in silence while the night deepened. " * 9
    chunk = "JULIET. I must go now.\n" + filler + "\nShe drew the dagger and held it close before the watch arrived.\n"
    spans = _dei_split_evidence_passages(chunk, target=420, minimum=120, maximum=560)
    inferred = [{"text":"Juliet","confidence":0.91,"entity_type":"person_or_character"}]
    chosen = _dei_select_support_passages(spans, "Juliet draws the dagger before the watch arrives", inferred, max_hits=2)
    dagger_idx = next((i for i,p in enumerate(spans) if "dagger" in p["text"].casefold()), -1)
    terms = _dei_build_terms(spans[dagger_idx]["text"], inferred) if dagger_idx >= 0 else []
    checks["chunk_split_into_multiple_exact_passages"] = len(spans) >= 2
    checks["support_selector_reaches_dagger_passage"] = dagger_idx in chosen
    checks["juliet_absent_from_dagger_evidence_span"] = dagger_idx >= 0 and "juliet" not in _dei_norm(spans[dagger_idx]["text"])
    checks["juliet_stays_inferred_at_span_level"] = any(x.get("term_norm") == "juliet" and x.get("origin") == "inferred" for x in terms)
    checks["dagger_is_explicit_at_span_level"] = any(x.get("term_norm") == "dagger" and x.get("origin") == "explicit" for x in terms)
    names = _dei_name_phrases("Enter Romeo. JULIET AUTHOR William Shakespeare. Friar Lawrence speaks.")
    checks["stage_direction_not_canonical_name"] = all(_dei_norm(x) != "enter romeo" for x in names) and any(_dei_norm(x) == "romeo" for x in names)
    checks["epub_author_artifact_filtered"] = all("author" not in _dei_norm(x).split() for x in names)
    checks["legitimate_multiword_name_preserved"] = any(_dei_norm(x) == "friar lawrence" for x in names)
    # Verify exact span slicing independently of the real book database.
    sample = spans[dagger_idx] if dagger_idx >= 0 else spans[-1]
    checks["span_offsets_round_trip"] = chunk[sample["char_start"]:sample["char_end"]] == sample["text"]
    return {"ok": all(checks.values()), "checks": checks, "sample_span_count": len(spans), "chosen_support_indices": chosen}


def _install_digest_entity_index(module) -> None:
    if getattr(module, "_DIGEST_ENTITY_INDEX_INSTALLED", False):
        return
    _dei_ensure_schema(module)
    module.get_digest_entity_index_status = lambda: _dei_status(module)
    module.search_digest_index = lambda query, scope="passage", include_inferred=True, min_confidence=_DIGEST_ENTITY_DEFAULT_MIN_CONFIDENCE, limit=20: _dei_search(module, query, scope, include_inferred, min_confidence, limit)
    module.get_digest_passage = lambda passage_id, include_original=False: _dei_get_passage(module, passage_id, include_original)
    module.rebuild_digest_entity_index = lambda clear=False, limit=0: _dei_backfill(module, clear=bool(clear), limit=int(limit or 0))
    module.digest_entity_index_self_test = lambda: digest_entity_index_self_test(module)
    module.digest_entity_precision_self_test = lambda: digest_entity_precision_self_test(module)
    module.DIGEST_ENTITY_INDEX_VERSION = _DIGEST_ENTITY_INDEX_VERSION

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_digest_entity_index_status","description":"Read status of the source-grounded Digest Entity & Keyword Index. Summaries are navigation only; original source locators remain authoritative evidence.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"search_digest_index","description":"Search digested original evidence by entity/keyword co-occurrence. Multiple query terms use strict AND semantics within the same exact evidence passage by default; e.g. 'Elara Sword' returns summaries only where both terms are supported in the same passage. Inferred entities are uncertainty-labeled and never become authoritative evidence.","parameters":{"type":"object","properties":{"query":{"type":"string"},"scope":{"type":"string","enum":["passage","digest","document"]},"include_inferred":{"type":"boolean"},"min_confidence":{"type":"number","minimum":0,"maximum":1},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["query"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_digest_passage","description":"Read one digest passage summary, indexed explicit/inferred entities, exact source locator and hashes; optionally retrieve and verify the original source text. The summary is not authoritative evidence.","parameters":{"type":"object","properties":{"passage_id":{"type":"string"},"include_original":{"type":"boolean"}},"required":["passage_id"],"additionalProperties":False}}},
    ])
    if isinstance(getattr(module, "_READ_ONLY_TEXT_TOOL_ALLOWLIST", None), set):
        module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_digest_entity_index_status","search_digest_index","get_digest_passage"})
    old_execute = module.execute_tool
    def execute_with_digest_entity_index(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_digest_entity_index_status": return module.get_digest_entity_index_status()
        if name == "search_digest_index": return module.search_digest_index(**arguments)
        if name == "get_digest_passage": return module.get_digest_passage(**arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_with_digest_entity_index

    # Keep entity/co-occurrence navigation visible in the small LM Studio catalog:
    # search_memories + search_digest_index + get_memory_by_id are the primary
    # general-memory trio; deeper graph tools remain available by expansion.
    memory_group = list(_ADAPTIVE_TOOL_GROUPS.get("memory", ()))
    for name in ("search_digest_index", "get_digest_passage", "get_digest_entity_index_status"):
        if name in memory_group: memory_group.remove(name)
    desired = ["search_memories", "search_digest_index", "get_memory_by_id"]
    remainder = [n for n in memory_group if n not in desired]
    _ADAPTIVE_TOOL_GROUPS["memory"] = tuple(desired + remainder + ["get_digest_passage", "get_digest_entity_index_status"])

    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict) and "digest-entity-index" not in specs:
        specs["digest-entity-index"] = {
            "label": "Source-grounded digest entity/keyword index and strict passage co-occurrence",
            "groups": ("quick", "critical", "all"),
            "runner": "memory.digest_entity_index_self_test",
        }
    module._DIGEST_ENTITY_INDEX_INSTALLED = True


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:shared-knowledge rev=11
# Shared Knowledge Store + versioned redigest (7.4.23.2)
# ---------------------------------------------------------------------------
# External books/research are entity-neutral knowledge. Personal NeatMemory keeps
# identity, experience, continuity, preferences, relationships and local overlays;
# this store keeps reusable source-grounded knowledge that can be mounted by many
# entities through NEATMEMORY_SHARED_KNOWLEDGE_DIR.

_SHARED_KNOWLEDGE_VERSION = "1.0-entity-neutral-versioned-knowledge"
_DEEP_REDIGEST_ENABLED = True
_DEEP_REDIGEST_VERSION = "2.3-deterministic-metadata-repair-resumable"
_DEEP_REDIGEST_DISABLED_REASON = ""
# One chunk per deep call, with enough room for reasoning plus strict JSON.
_DEEP_PREVIOUS_ITEMS_LIMIT = 16
_DEEP_MAX_IMPLICIT_PER_MEMORY = 6
_DEEP_MAX_MEMORIES_PER_CHUNK = 14
_DEEP_TEST_CHUNKS_MAX = 5
_DEEP_ONLINE_OUTPUT_CAP_DEFAULT = 16000
_SHARED_KNOWLEDGE_DB = "shared_knowledge.sqlite"
_SHARED_KNOWLEDGE_DIR_ENV = "NEATMEMORY_SHARED_KNOWLEDGE_DIR"
_SHARED_KNOWLEDGE_CONTRIBUTION = {
    "coding": "ChatGPT",
    "direction": "Steeve Martin Dumont-Roy",
    "description": "ChatGPT coding / implementation assistance; Steeve Martin Dumont-Roy direction, architecture, testing, and design decisions.",
}
_GPT_MODEL_ALIASES = {
    "luna": os.getenv("NEATMEMORY_GPT_LUNA_MODEL", "gpt-5.6-luna").strip() or "gpt-5.6-luna",
    "terra": os.getenv("NEATMEMORY_GPT_TERRA_MODEL", "gpt-5.6-terra").strip() or "gpt-5.6-terra",
    "sol": os.getenv("NEATMEMORY_GPT_SOL_MODEL", "gpt-5.6-sol").strip() or "gpt-5.6-sol",
}
_SHARED_KNOWLEDGE_EXTERNAL_ORIGINS = {"book_digest", "research_digest", "learn"}


def _sk_personal_root() -> Path:
    return Path(os.getenv("NEAT_MEMORY_DIR", "./neat_memory")).resolve()


def _sk_root_path() -> Path:
    configured = os.getenv(_SHARED_KNOWLEDGE_DIR_ENV, "").strip()
    if configured:
        return Path(configured).expanduser().resolve()
    personal = _sk_personal_root()
    return (personal.parent / "shared_knowledge").resolve()


def _sk_backup_sqlite(source: Path, destination: Path) -> bool:
    if not source.exists() or destination.exists():
        return False
    destination.parent.mkdir(parents=True, exist_ok=True)
    src = sqlite3.connect(source)
    dst = sqlite3.connect(destination)
    try:
        src.backup(dst)
        dst.commit()
    finally:
        dst.close(); src.close()
    return True


def _sk_copy_tree_once(source: Path, destination: Path) -> int:
    if not source.exists() or destination.exists():
        return 0
    import shutil
    shutil.copytree(source, destination)
    return sum(1 for p in destination.rglob("*") if p.is_file())


def _sk_sync_legacy_book_storage(books_module) -> dict:
    """Migrate legacy books/book_pending/book_archive files into the single books/ directory.

    Legacy folders are read only when they already exist. They are never created,
    and normal scan/import operations use books/ exclusively after configuration.
    """
    canonical = Path(getattr(books_module, "BOOK_DIR", _sk_root_path() / "books")).resolve()
    canonical.mkdir(parents=True, exist_ok=True)
    personal = _sk_personal_root().resolve()
    shared = _sk_root_path().resolve()
    source_dirs: list[Path] = []
    seen_dirs: set[str] = set()
    for base in (personal, shared):
        for dirname in ("books", "book_pending", "book_archive"):
            candidate = (base / dirname).resolve()
            key = str(candidate)
            if key in seen_dirs or candidate == canonical:
                continue
            seen_dirs.add(key); source_dirs.append(candidate)
    result = {
        "ok": True, "books_directory": str(canonical), "legacy_sources": [str(p) for p in source_dirs],
        "copied": 0, "already_present": 0, "errors": [],
    }
    supported = {str(x).casefold() for x in (getattr(books_module, "SUPPORTED_BOOK_SUFFIXES", set()) or set())}
    if not supported:
        supported = {".txt", ".md", ".html", ".htm", ".epub", ".pdf", ".log", ".json", ".jsonl", ".csv"}
    canonical_hashes: dict[str, Path] = {}
    for existing in canonical.iterdir():
        if not existing.is_file() or existing.suffix.casefold() not in supported:
            continue
        try: canonical_hashes[hashlib.sha256(existing.read_bytes()).hexdigest()] = existing
        except OSError: continue
    for legacy_dir in source_dirs:
        if not legacy_dir.exists() or not legacy_dir.is_dir():
            continue
        for source in sorted(legacy_dir.iterdir(), key=lambda item: item.name.casefold()):
            if not source.is_file() or source.suffix.casefold() not in supported:
                continue
            try:
                digest = hashlib.sha256(source.read_bytes()).hexdigest()
                if digest in canonical_hashes:
                    result["already_present"] += 1; continue
                target = canonical / source.name
                if target.exists():
                    stem, suffix = target.stem, target.suffix; counter = 2
                    while target.exists():
                        target = canonical / f"{stem}_{counter}{suffix}"; counter += 1
                shutil.copy2(source, target)
                canonical_hashes[digest] = target
                result["copied"] += 1
            except Exception as exc:
                result["ok"] = False
                result["errors"].append({"file": str(source), "error": f"{type(exc).__name__}: {exc}"})
    return result


def _configure_shared_books_module(books_module) -> None:
    """Mount NeatBooks under shared knowledge with one physical books/ directory.

    Existing books/book_pending/book_archive files are copied into books/ once per
    startup by content hash. Legacy folders are never created or used as the active
    queue/archive location. READY/DIGESTING/COMPLETE remain logical SQL states.
    """
    root = _sk_root_path()
    root.mkdir(parents=True, exist_ok=True)
    legacy = Path(getattr(books_module, "MEMORY_DIR", _sk_personal_root())).resolve()
    db_name = str(getattr(books_module, "DB_FILE", "neatbooks.db"))
    shared_db = root / db_name
    legacy_db = legacy / db_name
    _sk_backup_sqlite(legacy_db, shared_db) if legacy != root else False

    books_module.MEMORY_DIR = root
    books_module.BOOK_DIR = root / "books"
    books_module.PENDING_DIR = books_module.BOOK_DIR
    books_module.ARCHIVE_DIR = books_module.BOOK_DIR
    books_module.LEGACY_PENDING_DIR = root / "book_pending"
    books_module.LEGACY_ARCHIVE_DIR = root / "book_archive"
    books_module.BOOK_DIR.mkdir(parents=True, exist_ok=True)
    books_module._NEAT_LAST_LEGACY_BOOK_STORAGE_SYNC = _sk_sync_legacy_book_storage(books_module)

    # Rebind copied DB rows to the canonical books/ file with the same content hash.
    # This also handles older rows whose local_file pointed at book_pending/archive.
    if shared_db.exists():
        try:
            supported = {str(x).casefold() for x in (getattr(books_module, "SUPPORTED_BOOK_SUFFIXES", set()) or set())}
            by_hash: dict[str, Path] = {}
            for path in books_module.BOOK_DIR.iterdir():
                if path.is_file() and (not supported or path.suffix.casefold() in supported):
                    try: by_hash[hashlib.sha256(path.read_bytes()).hexdigest()] = path
                    except OSError: pass
            db = sqlite3.connect(shared_db); db.row_factory = sqlite3.Row
            rows = db.execute("SELECT book_id,local_file,content_sha256 FROM books WHERE local_file IS NOT NULL AND local_file<>''").fetchall()
            for row in rows:
                current = Path(str(row["local_file"] or ""))
                try:
                    if current.exists() and current.resolve().parent == books_module.BOOK_DIR.resolve():
                        continue
                except Exception:
                    pass
                target = by_hash.get(str(row["content_sha256"] or "").strip())
                if target is None:
                    candidate = books_module.BOOK_DIR / current.name
                    if candidate.exists(): target = candidate
                if target is not None:
                    db.execute("UPDATE books SET local_file=? WHERE book_id=?", (str(target), row["book_id"]))
            db.commit(); db.close()
        except Exception:
            pass

    # Upgrade filename-derived EPUB catalog labels to the real package metadata.
    # Explicit/custom titles are preserved by NeatBooks.refresh_epub_metadata().
    try:
        refresher = getattr(books_module, "refresh_epub_metadata", None)
        if callable(refresher):
            books_module._NEAT_LAST_EPUB_METADATA_REFRESH = refresher()
    except Exception as exc:
        books_module._NEAT_LAST_EPUB_METADATA_REFRESH = {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


def _shared_knowledge_root_for_archive(module) -> Path:
    root = _sk_root_path()
    root.mkdir(parents=True, exist_ok=True)
    legacy_root = Path(getattr(module, "MEMORY_DIR", _sk_personal_root())).resolve()
    legacy_db = legacy_root / _RESEARCH_ARCHIVE_DB_FILE
    shared_db = root / _RESEARCH_ARCHIVE_DB_FILE
    try:
        _sk_backup_sqlite(legacy_db, shared_db)
        _sk_copy_tree_once(legacy_root / _RESEARCH_ARCHIVE_ROOT, root / _RESEARCH_ARCHIVE_ROOT)
    except Exception:
        pass
    return root


def _sk_db_path(module=None) -> Path:
    root = _sk_root_path()
    root.mkdir(parents=True, exist_ok=True)
    return root / _SHARED_KNOWLEDGE_DB


_SK_SESSION_LOCAL = threading.local()


def _sk_profile_sqlite_bucket() -> dict | None:
    holder=globals().get("_KP_PROFILE_LOCAL")
    profile=getattr(holder,"current",None) if holder is not None else None
    if not isinstance(profile,dict):
        return None
    return profile.setdefault("shared_sqlite",{})


def _sk_active_session() -> dict | None:
    session=getattr(_SK_SESSION_LOCAL,"current",None)
    return session if isinstance(session,dict) and session.get("db") is not None else None


def _sk_connect(module=None) -> sqlite3.Connection:
    # 7.4.67.1: a bounded Pyramid invocation can reuse one Shared-Knowledge
    # connection on its current thread. Outside that session behavior remains
    # the legacy open/configure/return path.
    metrics=_sk_profile_sqlite_bucket()
    if isinstance(metrics,dict):
        metrics["connection_requests"]=int(metrics.get("connection_requests") or 0)+1
    session=_sk_active_session()
    if session is not None:
        if isinstance(metrics,dict):
            metrics["session_reuses"]=int(metrics.get("session_reuses") or 0)+1
        return session["db"]
    t0=time.perf_counter()
    path=_sk_db_path(module)
    t1=time.perf_counter()
    db=sqlite3.connect(path, timeout=30)
    t2=time.perf_counter()
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA foreign_keys=ON")
    t3=time.perf_counter()
    db.execute("PRAGMA journal_mode=WAL")
    t4=time.perf_counter()
    db.execute("PRAGMA synchronous=NORMAL")
    t5=time.perf_counter()
    if isinstance(metrics,dict):
        metrics["connect_calls"]=int(metrics.get("connect_calls") or 0)+1
        metrics["physical_connect_calls"]=int(metrics.get("physical_connect_calls") or 0)+1
        metrics["path_setup_ms"]=round(float(metrics.get("path_setup_ms") or 0.0)+(t1-t0)*1000.0,3)
        metrics["connect_open_ms"]=round(float(metrics.get("connect_open_ms") or 0.0)+(t2-t1)*1000.0,3)
        metrics["pragma_foreign_keys_ms"]=round(float(metrics.get("pragma_foreign_keys_ms") or 0.0)+(t3-t2)*1000.0,3)
        metrics["pragma_wal_ms"]=round(float(metrics.get("pragma_wal_ms") or 0.0)+(t4-t3)*1000.0,3)
        metrics["pragma_synchronous_ms"]=round(float(metrics.get("pragma_synchronous_ms") or 0.0)+(t5-t4)*1000.0,3)
        elapsed=(t5-t0)*1000.0
        metrics["setup_total_ms"]=round(float(metrics.get("setup_total_ms") or 0.0)+elapsed,3)
        metrics["max_single_setup_ms"]=round(max(float(metrics.get("max_single_setup_ms") or 0.0),elapsed),3)
        metrics["connect_calls_semantics"]="physical sqlite opens; connection_requests counts helper requests"
    return db


def _sk_session_begin(module=None) -> dict:
    existing=_sk_active_session()
    if existing is not None:
        existing["depth"]=int(existing.get("depth") or 1)+1
        return {"owner":False,"session":existing}
    started=time.perf_counter()
    db=_sk_connect(module)
    session={"db":db,"depth":1,"started_perf":started,"semantic_schema_ready":None}
    _SK_SESSION_LOCAL.current=session
    metrics=_sk_profile_sqlite_bucket()
    if isinstance(metrics,dict):
        metrics["session_active"]=True
        metrics["session_owner_thread"]=threading.get_ident()
    return {"owner":True,"session":session}


def _sk_session_end(token: dict | None) -> None:
    if not isinstance(token,dict):
        return
    session=token.get("session") if isinstance(token.get("session"),dict) else None
    if session is None:
        return
    if not bool(token.get("owner")):
        session["depth"]=max(1,int(session.get("depth") or 1)-1)
        return
    db=session.get("db")
    metrics=_sk_profile_sqlite_bucket()
    t0=time.perf_counter()
    try:
        if db is not None:
            db.commit()
    finally:
        commit_ms=(time.perf_counter()-t0)*1000.0
    t1=time.perf_counter()
    try:
        if db is not None:
            db.close()
    finally:
        close_ms=(time.perf_counter()-t1)*1000.0
        if getattr(_SK_SESSION_LOCAL,"current",None) is session:
            _SK_SESSION_LOCAL.current=None
    if isinstance(metrics,dict):
        metrics["session_commit_ms"]=round(float(metrics.get("session_commit_ms") or 0.0)+commit_ms,3)
        metrics["session_close_ms"]=round(float(metrics.get("session_close_ms") or 0.0)+close_ms,3)
        metrics["session_wall_ms"]=round((time.perf_counter()-float(session.get("started_perf") or time.perf_counter()))*1000.0,3)
        metrics["semantic_schema_ready_at_close"]=bool(session.get("semantic_schema_ready"))


def _sk_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _sk_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _sk_hash(value: object) -> str:
    raw = value if isinstance(value, bytes) else str(value).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _sk_id(prefix: str, payload: object, length: int = 20) -> str:
    return f"{prefix}-" + _sk_hash(_sk_json(payload))[:length].upper()


def _sk_ensure_schema(module=None) -> None:
    if _nm_bootstrap_schema_skip("shared-knowledge-base-v1"):
        return
    with _sk_connect(module) as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS shared_knowledge_meta(
            key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS knowledge_sources(
            source_id TEXT PRIMARY KEY,
            source_kind TEXT NOT NULL,
            source_key TEXT NOT NULL,
            title TEXT NOT NULL,
            source_sha256 TEXT NOT NULL,
            source_locator_json TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            retired INTEGER NOT NULL DEFAULT 0,
            current_version_id TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(source_kind, source_key)
        );
        CREATE TABLE IF NOT EXISTS knowledge_source_relations(
            from_source_id TEXT NOT NULL,
            relation TEXT NOT NULL,
            to_source_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY(from_source_id,relation,to_source_id)
        );
        CREATE TABLE IF NOT EXISTS knowledge_versions(
            version_id TEXT PRIMARY KEY,
            source_id TEXT NOT NULL,
            version_number INTEGER NOT NULL,
            status TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 0,
            archive INTEGER NOT NULL DEFAULT 0,
            previous_version_id TEXT,
            supersedes_version_id TEXT,
            scope TEXT NOT NULL,
            digest_mode TEXT NOT NULL,
            provider TEXT NOT NULL,
            model_alias TEXT,
            model_id TEXT NOT NULL,
            source_sha256 TEXT NOT NULL,
            run_id TEXT NOT NULL,
            contribution_json TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            notes_json TEXT NOT NULL DEFAULT '{}',
            UNIQUE(source_id,version_number),
            FOREIGN KEY(source_id) REFERENCES knowledge_sources(source_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_versions_source ON knowledge_versions(source_id,version_number DESC);
        CREATE INDEX IF NOT EXISTS idx_knowledge_versions_active ON knowledge_versions(source_id,active,archive,status);
        CREATE TABLE IF NOT EXISTS knowledge_items(
            item_id TEXT PRIMARY KEY,
            version_id TEXT NOT NULL,
            kind TEXT NOT NULL,
            claim TEXT NOT NULL,
            details TEXT NOT NULL,
            interpretation TEXT NOT NULL,
            domain TEXT NOT NULL,
            importance REAL NOT NULL,
            confidence REAL NOT NULL,
            content_sha256 TEXT NOT NULL,
            created_at TEXT NOT NULL,
            metadata_json TEXT NOT NULL DEFAULT '{}',
            FOREIGN KEY(version_id) REFERENCES knowledge_versions(version_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_items_version ON knowledge_items(version_id);
        CREATE INDEX IF NOT EXISTS idx_knowledge_items_hash ON knowledge_items(content_sha256);
        CREATE TABLE IF NOT EXISTS knowledge_item_sources(
            item_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            source_ref TEXT NOT NULL,
            locator_json TEXT NOT NULL,
            evidence_sha256 TEXT NOT NULL,
            excerpt_sha256 TEXT NOT NULL,
            excerpt TEXT NOT NULL,
            PRIMARY KEY(item_id,ordinal),
            FOREIGN KEY(item_id) REFERENCES knowledge_items(item_id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS knowledge_version_chunks(
            version_id TEXT NOT NULL,
            chunk_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            text_sha256 TEXT NOT NULL,
            status TEXT NOT NULL,
            completed_at TEXT,
            PRIMARY KEY(version_id,chunk_id,text_sha256),
            FOREIGN KEY(version_id) REFERENCES knowledge_versions(version_id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS knowledge_passages(
            passage_id TEXT PRIMARY KEY,
            version_id TEXT NOT NULL,
            source_id TEXT NOT NULL,
            source_ref TEXT NOT NULL,
            source_kind TEXT NOT NULL,
            chunk_id TEXT,
            chunk_ordinal INTEGER,
            passage_ordinal INTEGER NOT NULL,
            char_start INTEGER NOT NULL,
            char_end INTEGER NOT NULL,
            source_text_sha256 TEXT NOT NULL,
            summary_text TEXT NOT NULL,
            metadata_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            FOREIGN KEY(version_id) REFERENCES knowledge_versions(version_id) ON DELETE CASCADE,
            FOREIGN KEY(source_id) REFERENCES knowledge_sources(source_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_passage_version ON knowledge_passages(version_id,chunk_ordinal,passage_ordinal);
        CREATE TABLE IF NOT EXISTS knowledge_terms(
            passage_id TEXT NOT NULL,
            term_norm TEXT NOT NULL,
            canonical_norm TEXT NOT NULL,
            display_text TEXT NOT NULL,
            entity_type TEXT NOT NULL,
            origin TEXT NOT NULL,
            confidence REAL NOT NULL,
            is_alias INTEGER NOT NULL DEFAULT 0,
            ordinal INTEGER NOT NULL,
            PRIMARY KEY(passage_id,term_norm,canonical_norm,origin),
            FOREIGN KEY(passage_id) REFERENCES knowledge_passages(passage_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_term ON knowledge_terms(term_norm,confidence,origin);
        CREATE INDEX IF NOT EXISTS idx_knowledge_canonical ON knowledge_terms(canonical_norm,confidence,origin);
        CREATE TABLE IF NOT EXISTS knowledge_runs(
            run_id TEXT PRIMARY KEY,
            source_id TEXT NOT NULL,
            version_id TEXT NOT NULL,
            operation TEXT NOT NULL,
            digest_mode TEXT NOT NULL,
            provider TEXT NOT NULL,
            model_alias TEXT,
            model_id TEXT NOT NULL,
            status TEXT NOT NULL,
            total_chunks INTEGER NOT NULL DEFAULT 0,
            processed_chunks INTEGER NOT NULL DEFAULT 0,
            model_calls INTEGER NOT NULL DEFAULT 0,
            items_created INTEGER NOT NULL DEFAULT 0,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            error TEXT,
            stats_json TEXT NOT NULL DEFAULT '{}'
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_runs_source ON knowledge_runs(source_id,started_at DESC);
        CREATE TABLE IF NOT EXISTS knowledge_events(
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            event_type TEXT NOT NULL,
            source_id TEXT,
            version_id TEXT,
            payload_json TEXT NOT NULL,
            payload_sha256 TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS knowledge_purge_tokens(
            token TEXT PRIMARY KEY,
            source_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            preview_sha256 TEXT NOT NULL
        );
        """)
        now = _sk_now()
        db.execute("INSERT INTO shared_knowledge_meta(key,value,updated_at) VALUES('schema_version',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at", (_SHARED_KNOWLEDGE_VERSION, now))
        db.execute("INSERT INTO shared_knowledge_meta(key,value,updated_at) VALUES('contribution',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at", (_sk_json(_SHARED_KNOWLEDGE_CONTRIBUTION), now))
    _nm_bootstrap_schema_mark("shared-knowledge-base-v1")


def _sk_event(event_type: str, payload: dict, *, source_id: str | None = None, version_id: str | None = None) -> None:
    _sk_ensure_schema()
    canonical = _sk_json(payload)
    with _sk_connect() as db:
        db.execute("INSERT INTO knowledge_events(created_at,event_type,source_id,version_id,payload_json,payload_sha256) VALUES(?,?,?,?,?,?)", (_sk_now(), event_type, source_id, version_id, canonical, _sk_hash(canonical)))


def _sk_model_alias(module) -> str:
    try:
        value = str(module.get_setting("gpt_model_alias", "luna") or "luna").casefold()
    except Exception:
        value = "luna"
    return value if value in _GPT_MODEL_ALIASES else "luna"


def _sk_set_model_alias(module, alias: str) -> dict:
    value = str(alias or "").strip().casefold()
    if value not in _GPT_MODEL_ALIASES:
        raise ValueError("GPT alias must be luna, terra, or sol.")
    try:
        module.set_setting("gpt_model_alias", value)
    except Exception:
        pass
    return {"ok": True, "default_alias": value, "model_id": _GPT_MODEL_ALIASES[value], "aliases": dict(_GPT_MODEL_ALIASES)}


def _sk_gpt_status(module) -> dict:
    alias = _sk_model_alias(module)
    return {"ok": True, "default_alias": alias, "model_id": _GPT_MODEL_ALIASES[alias], "aliases": dict(_GPT_MODEL_ALIASES), "override_examples": ["/redigest BK-... --deep --gpt luna", "/redigest BK-... --deep --lmstudio", "/redigest BK-... --deep --gpt luna --test-chunks 2"]}


def _sk_source_hash_for_book(book: dict, rows: list[dict]) -> str:
    # Source-file bytes establish physical identity, but the digest evidence stream
    # also depends on extraction order. Prefer the canonical extracted-text hash
    # when the importer recorded one (EPUB spine-aware imports in 7.4.51.5+).
    metadata = book.get("metadata_json") if isinstance(book, dict) else None
    if isinstance(metadata, str):
        try: metadata = json.loads(metadata or "{}")
        except Exception: metadata = {}
    if isinstance(metadata, dict):
        source_meta = metadata.get("source_metadata") if isinstance(metadata.get("source_metadata"), dict) else {}
        canonical = str(metadata.get("canonical_text_sha256") or source_meta.get("canonical_text_sha256") or "").strip().casefold()
        if re.fullmatch(r"[0-9a-f]{64}", canonical):
            return canonical
    value = str(book.get("content_sha256") or "").strip()
    if value:
        return value
    return _sk_hash("|".join(str(r.get("text_sha256") or "") for r in rows))

def _sk_source_id(source_kind: str, source_key: str) -> str:
    prefix = "KSB" if source_kind == "book" else "KSR" if source_kind == "research" else "KSO"
    return _sk_id(prefix, {"kind": source_kind, "key": source_key}, 18)


def _sk_upsert_source(source_kind: str, source_key: str, title: str, source_sha256: str, locator: dict) -> dict:
    _sk_ensure_schema()
    sid = _sk_source_id(source_kind, source_key)
    now = _sk_now()
    with _sk_connect() as db:
        row = db.execute("SELECT * FROM knowledge_sources WHERE source_kind=? AND source_key=?", (source_kind, source_key)).fetchone()
        if row:
            sid = str(row["source_id"])
            db.execute("UPDATE knowledge_sources SET title=?,source_sha256=?,source_locator_json=?,updated_at=? WHERE source_id=?", (title, source_sha256, _sk_json(locator), now, sid))
        else:
            db.execute("INSERT INTO knowledge_sources(source_id,source_kind,source_key,title,source_sha256,source_locator_json,active,retired,created_at,updated_at) VALUES(?,?,?,?,?,?,1,0,?,?)", (sid, source_kind, source_key, title, source_sha256, _sk_json(locator), now, now))
    return {"source_id": sid, "source_kind": source_kind, "source_key": source_key, "title": title, "source_sha256": source_sha256}


def _sk_current_version(source_id: str) -> dict | None:
    _sk_ensure_schema()
    with _sk_connect() as db:
        row = db.execute("SELECT v.* FROM knowledge_versions v JOIN knowledge_sources s ON s.current_version_id=v.version_id WHERE s.source_id=? AND v.active=1 AND v.archive=0 AND v.status='completed'", (source_id,)).fetchone()
    return dict(row) if row else None


def _sk_begin_version(*, source: dict, scope: str, digest_mode: str, provider: str, model_alias: str | None, model_id: str, operation: str, total_chunks: int) -> dict:
    _sk_ensure_schema()
    now = _sk_now()
    run_id = f"KR-{time.strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:8]}"
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            previous = db.execute("SELECT * FROM knowledge_versions WHERE source_id=? AND active=1 AND archive=0 AND status='completed' ORDER BY version_number DESC LIMIT 1", (source["source_id"],)).fetchone()
            next_number = int(db.execute("SELECT COALESCE(MAX(version_number),0)+1 FROM knowledge_versions WHERE source_id=?", (source["source_id"],)).fetchone()[0])
            version_id = _sk_id("KDV", {"source": source["source_id"], "version": next_number, "run": run_id}, 20)
            previous_id = str(previous["version_id"]) if previous else None
            db.execute("""INSERT INTO knowledge_versions(version_id,source_id,version_number,status,active,archive,previous_version_id,supersedes_version_id,scope,digest_mode,provider,model_alias,model_id,source_sha256,run_id,contribution_json,started_at,notes_json) VALUES(?,?,?,'processing',0,0,?,?,?,?,?,?,?,?,?,?,?,?)""", (version_id, source["source_id"], next_number, previous_id, previous_id, scope, digest_mode, provider, model_alias, model_id, source["source_sha256"], run_id, _sk_json(_SHARED_KNOWLEDGE_CONTRIBUTION), now, _sk_json({"operation": operation})))
            db.execute("INSERT INTO knowledge_runs(run_id,source_id,version_id,operation,digest_mode,provider,model_alias,model_id,status,total_chunks,started_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)", (run_id, source["source_id"], version_id, operation, digest_mode, provider, model_alias, model_id, "processing", int(total_chunks), now))
            db.commit()
        except Exception:
            db.rollback(); raise
    _sk_event("knowledge_version_started", {"run_id": run_id, "operation": operation, "mode": digest_mode, "provider": provider, "model_alias": model_alias, "model_id": model_id, "previous_version_id": previous_id}, source_id=source["source_id"], version_id=version_id)
    return {"version_id": version_id, "version_number": next_number, "previous_version_id": previous_id, "run_id": run_id}


def _sk_fail_version(version_id: str, run_id: str, error: BaseException | str, *, processed: int = 0, model_calls: int = 0, items: int = 0) -> None:
    message = str(error) if isinstance(error, str) else f"{type(error).__name__}: {error}"
    now = _sk_now()
    with _sk_connect() as db:
        db.execute("UPDATE knowledge_versions SET status='failed',active=0,archive=1,completed_at=?,notes_json=? WHERE version_id=?", (now, _sk_json({"failure": message}), version_id))
        db.execute("UPDATE knowledge_runs SET status='failed',processed_chunks=?,model_calls=?,items_created=?,completed_at=?,error=? WHERE run_id=?", (processed, model_calls, items, now, message, run_id))
    _sk_event("knowledge_version_failed", {"run_id": run_id, "error": message, "processed": processed, "model_calls": model_calls, "items": items}, version_id=version_id)


def _sk_finalize_version(source_id: str, version_id: str, run_id: str, *, processed: int, model_calls: int, items: int, stats: dict | None = None) -> dict:
    now = _sk_now()
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            current = db.execute("SELECT version_id FROM knowledge_versions WHERE source_id=? AND active=1 AND archive=0 AND status='completed' AND version_id<>?", (source_id, version_id)).fetchall()
            archived_ids = [str(r["version_id"]) for r in current]
            db.execute("UPDATE knowledge_versions SET active=0,archive=1,status='archived' WHERE source_id=? AND active=1 AND version_id<>?", (source_id, version_id))
            db.execute("UPDATE knowledge_versions SET status='completed',active=1,archive=0,completed_at=? WHERE version_id=?", (now, version_id))
            db.execute("UPDATE knowledge_sources SET active=1,retired=0,current_version_id=?,updated_at=? WHERE source_id=?", (version_id, now, source_id))
            db.execute("UPDATE knowledge_runs SET status='completed',processed_chunks=?,model_calls=?,items_created=?,completed_at=?,error=NULL,stats_json=? WHERE run_id=?", (processed, model_calls, items, now, _sk_json(stats or {}), run_id))
            db.commit()
        except Exception:
            db.rollback(); raise
    _sk_event("knowledge_version_activated", {"run_id": run_id, "archived_previous_versions": archived_ids, "active": True, "archive": False, "processed": processed, "model_calls": model_calls, "items": items}, source_id=source_id, version_id=version_id)
    return {"active": True, "archive": False, "archived_previous_versions": archived_ids}


def _sk_resolve_source(reference: str) -> dict | None:
    ref = str(reference or "").strip()
    with _sk_connect() as db:
        row = db.execute("SELECT * FROM knowledge_sources WHERE source_id=? OR source_key=?", (ref, ref)).fetchone()
        if not row and ref.isdigit():
            # Book list-number resolution is handled by the book subsystem, not here.
            return None
        if not row:
            row = db.execute("SELECT * FROM knowledge_sources WHERE lower(title)=lower(?)", (ref,)).fetchone()
    return dict(row) if row else None


def _sk_active_items_for_chunk(source_id: str, chunk_id: str) -> list[dict]:
    with _sk_connect() as db:
        rows = db.execute("""SELECT i.item_id,i.claim,i.details,i.interpretation,i.domain,i.confidence FROM knowledge_items i JOIN knowledge_versions v ON v.version_id=i.version_id JOIN knowledge_item_sources s ON s.item_id=i.item_id WHERE v.source_id=? AND v.active=1 AND v.archive=0 AND v.status='completed' AND json_extract(s.locator_json,'$.chunk_id')=? ORDER BY i.item_id""", (source_id, chunk_id)).fetchall()
    return [dict(r) for r in rows]


def _sk_entities_from_proposal(proposal: dict, confidence: float) -> list[dict]:
    claim = f"{proposal.get('claim') or ''} {proposal.get('details') or ''}"
    subjects = proposal.get("subjects") if isinstance(proposal.get("subjects"), list) else []
    inferred = _dei_inferred_from_claim(claim, subjects, confidence)
    for raw in proposal.get("entities") or []:
        if isinstance(raw, str):
            item = {"text": raw, "confidence": confidence, "entity_type": _dei_entity_type(raw)}
        elif isinstance(raw, dict):
            name = str(raw.get("name") or raw.get("text") or "").strip()
            if not name: continue
            try: conf = float(raw.get("confidence", confidence))
            except Exception: conf = confidence
            item = {"text": name, "confidence": max(0.05, min(0.95, conf)), "entity_type": str(raw.get("type") or raw.get("entity_type") or _dei_entity_type(name)), "reason": str(raw.get("reason") or "")[:500]}
        else:
            continue
        inferred.append(item)
    # Deep redigest may add non-authoritative concepts that are not literal words.
    # They are indexed as inferred concept terms only and never become source evidence.
    for raw in (proposal.get("implicit_keywords") or [])[:_DEEP_MAX_IMPLICIT_PER_MEMORY]:
        if isinstance(raw, str):
            name=raw; conf=0.72; reason="deep inferred concept"
        elif isinstance(raw, dict):
            name=str(raw.get("term") or raw.get("name") or "").strip()
            try: conf=float(raw.get("confidence",0.72))
            except Exception: conf=0.72
            reason=str(raw.get("reason") or "deep inferred concept")[:500]
        else:
            continue
        if name:
            inferred.append({"text":name,"confidence":max(0.05,min(0.95,conf)),"entity_type":"concept","reason":reason})
    out=[]; seen=set()
    for item in inferred:
        key=_dei_norm(item.get("text"))
        if key and key not in seen:
            seen.add(key); out.append(item)
    return out[:64]


def _sk_store_item(db, *, version_id: str, proposal: dict, resolved_sources: list[dict], source_kind: str, metadata: dict | None = None) -> str | None:
    claim = " ".join(str(proposal.get("claim") or "").split()).strip()
    if len(claim) < 8 or not resolved_sources:
        return None
    kind = str(proposal.get("kind") or "fact").strip().casefold()
    if kind not in {"fact","question","artifact","decision","preference","experience"}: kind = "fact"
    interpretation = str(proposal.get("interpretation") or "paraphrase").strip().casefold()
    if interpretation not in {"direct","paraphrase","inference","hypothesis"}: interpretation = "paraphrase"
    details = str(proposal.get("details") or "").strip()
    domain = re.sub(r"[^a-z0-9_-]+", "-", str(proposal.get("domain") or "general").casefold()).strip("-") or "general"
    try: importance = max(0.0, min(1.0, float(proposal.get("importance", 0.65))))
    except Exception: importance = 0.65
    try: confidence = max(0.05, min(1.0, float(proposal.get("confidence", 0.86 if interpretation != "inference" else 0.72))))
    except Exception: confidence = 0.82
    content_sha = _sk_hash(_sk_json({"kind":kind,"claim":claim,"details":details,"interpretation":interpretation,"domain":domain,"sources":[str(x.get("ref") or x.get("source_ref") or "") for x in resolved_sources]}))
    item_id = _sk_id("KI", {"version": version_id, "sha": content_sha}, 20)
    exists = db.execute("SELECT item_id FROM knowledge_items WHERE item_id=?", (item_id,)).fetchone()
    if exists: return str(exists["item_id"])
    db.execute("INSERT INTO knowledge_items(item_id,version_id,kind,claim,details,interpretation,domain,importance,confidence,content_sha256,created_at,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)", (item_id,version_id,kind,claim,details,interpretation,domain,importance,confidence,content_sha,_sk_now(),_sk_json(metadata or {})))
    for ordinal, src in enumerate(resolved_sources):
        ref = str(src.get("ref") or src.get("source_ref") or src.get("file") or "source")
        excerpt = str(src.get("excerpt") or src.get("content") or src.get("text") or "")
        locator = {k:v for k,v in src.items() if k not in {"excerpt","content","text"}}
        evidence_sha = str(src.get("text_sha256") or src.get("archive_text_sha256") or _sk_hash(excerpt))
        db.execute("INSERT INTO knowledge_item_sources(item_id,ordinal,source_ref,locator_json,evidence_sha256,excerpt_sha256,excerpt) VALUES(?,?,?,?,?,?,?)", (item_id,ordinal,ref,_sk_json(locator),evidence_sha,_sk_hash(excerpt),excerpt))
    return item_id


def _sk_store_book_passages(*, version_id: str, source_id: str, book: dict, batch: list[dict], proposals: list[dict], registry: dict, item_ids: list[str]) -> dict:
    by_chunk = {str(row.get("chunk_id") or ""): {"row":row, "spans":_dei_split_evidence_passages(str(row.get("text") or "")), "support":{}} for row in batch}
    for proposal in proposals:
        if not isinstance(proposal, dict): continue
        claim = _dei_clean(proposal.get("claim"), 900); details = _dei_clean(proposal.get("details"), 1400)
        claim_text = _dei_clean(f"{claim} {details}", 2200)
        inferred = _sk_entities_from_proposal(proposal, 0.72 if str(proposal.get("interpretation") or "").casefold()=="inference" else 0.88)
        try: resolved = sys.modules["neatdigest_v2_0_stable"]._resolve_book_refs(proposal.get("source_refs") or proposal.get("sources"), registry)
        except Exception: resolved = []
        for src in resolved:
            cid=str(src.get("chunk_id") or ""); info=by_chunk.get(cid)
            if not info: continue
            for idx in _dei_select_support_passages(info["spans"], claim_text, inferred):
                bucket=info["support"].setdefault(idx,{"summaries":[],"inferred":[]})
                if claim and claim not in bucket["summaries"]: bucket["summaries"].append(claim)
                bucket["inferred"].extend(inferred)
    passage_count=term_count=0
    with _sk_connect() as db:
        for cid, info in by_chunk.items():
            row=info["row"]; ordinal=int(row.get("ordinal") or 0)
            for idx, span in enumerate(info["spans"]):
                bucket=info["support"].get(idx,{"summaries":[],"inferred":[]})
                locator={"kind":"book_span","book_id":str(book.get("book_id") or ""),"chunk_id":cid,"ordinal":ordinal,"passage_ordinal":int(span.get("passage_ordinal") or idx+1),"char_start":int(span["char_start"]),"char_end":int(span["char_end"]),"source_name":str(book.get("title") or book.get("book_id") or "book")}
                source_sha=_sk_hash(span["text"])
                passage_id=_sk_id("KP", {"version":version_id,"locator":locator,"sha":source_sha},20)
                summary=" ".join(bucket["summaries"])[:4000]
                db.execute("INSERT OR REPLACE INTO knowledge_passages(passage_id,version_id,source_id,source_ref,source_kind,chunk_id,chunk_ordinal,passage_ordinal,char_start,char_end,source_text_sha256,summary_text,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (passage_id,version_id,source_id,f"book:{book.get('book_id')}:{cid}","book",cid,ordinal,int(span.get("passage_ordinal") or idx+1),int(span["char_start"]),int(span["char_end"]),source_sha,summary,_sk_json({"locator":locator,"item_ids":item_ids}),_sk_now()))
                db.execute("DELETE FROM knowledge_terms WHERE passage_id=?", (passage_id,))
                terms=_dei_build_terms(span["text"], bucket["inferred"])
                for t in terms:
                    db.execute("INSERT OR REPLACE INTO knowledge_terms(passage_id,term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,ordinal) VALUES(?,?,?,?,?,?,?,?,?)", (passage_id,t["term_norm"],t["canonical_norm"],t["display_text"],t["entity_type"],t["origin"],float(t["confidence"]),1 if t.get("is_alias") else 0,int(t["ordinal"])))
                passage_count += 1; term_count += len(terms)
    return {"passages": passage_count, "terms": term_count}


def _sk_store_book_batch(digest_module, *, version_id: str, source_id: str, backend, book: dict, batch: list[dict], proposals: list[dict], registry: dict) -> dict:
    inserted=[]; rejected=0
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            for proposal in proposals:
                if not isinstance(proposal,dict): rejected+=1; continue
                try: resolved=digest_module._resolve_book_refs(proposal.get("source_refs") or proposal.get("sources"),registry)
                except Exception: resolved=[]
                item_id=_sk_store_item(db,version_id=version_id,proposal=proposal,resolved_sources=resolved,source_kind="book",metadata={"book_id":str(book.get("book_id") or "")})
                if item_id: inserted.append(item_id)
                else: rejected+=1
            for row in batch:
                db.execute("INSERT OR REPLACE INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)", (version_id,str(row.get("chunk_id") or ""),int(row.get("ordinal") or 0),str(row.get("text_sha256") or _sk_hash(row.get("text") or "")),"completed",_sk_now()))
            db.commit()
        except Exception:
            db.rollback(); raise
    index=_sk_store_book_passages(version_id=version_id,source_id=source_id,book=book,batch=batch,proposals=proposals,registry=registry,item_ids=inserted)
    return {"shared_knowledge":True,"inserted":inserted,"knowledge_ids":inserted,"rejected":rejected,"duplicates":0,"entity_index":index,"neatblock":{}}


def _sk_book_schema(deep: bool = False) -> dict:
    memory_props={"kind":{"type":"string","enum":["fact","question","artifact"]},"claim":{"type":"string"},"details":{"type":"string"},"source_refs":{"type":"array","items":{"type":"string"}},"interpretation":{"type":"string","enum":["direct","paraphrase","inference"]},"domain":{"type":"string"},"importance":{"type":"number"},"confidence":{"type":"number"}}
    required=["kind","claim","details","source_refs","interpretation","domain","importance","confidence"]
    if deep:
        memory_props["entities"]={"type":"array","items":{"type":"object","properties":{"name":{"type":"string"},"type":{"type":"string"},"origin":{"type":"string","enum":["explicit","inferred"]},"confidence":{"type":"number"},"reason":{"type":"string"}},"required":["name","type","origin","confidence","reason"],"additionalProperties":False}}
        memory_props["implicit_keywords"]={"type":"array","items":{"type":"object","properties":{"term":{"type":"string"},"confidence":{"type":"number"},"reason":{"type":"string"}},"required":["term","confidence","reason"],"additionalProperties":False}}
        required.extend(["entities","implicit_keywords"])
    return {"type":"object","properties":{"block_title":{"type":"string"},"block_summary":{"type":"string"},"themes":{"type":"array","items":{"type":"string"}},"entities":{"type":"array","items":{"type":"string"}},"memories":{"type":"array","items":{"type":"object","properties":memory_props,"required":required,"additionalProperties":False}},"batch_complete":{"type":"boolean"}},"required":["block_title","block_summary","themes","entities","memories","batch_complete"],"additionalProperties":False}


def _sk_online_refusal_text(response) -> str:
    """Return a structured-output refusal message without assuming a specific SDK object shape."""
    for item in list(getattr(response,"output",None) or []):
        if str(getattr(item,"type","") or "") != "message":
            continue
        for part in list(getattr(item,"content",None) or []):
            if str(getattr(part,"type","") or "") == "refusal":
                value=getattr(part,"refusal",None) or getattr(part,"text",None) or "model refusal"
                return str(value)[:1200]
    return ""


def _sk_parse_online_structured_response(digest_module, response, *, schema_name: str) -> dict:
    status=str(getattr(response,"status","") or "")
    if status=="incomplete":
        detail=getattr(response,"incomplete_details",None)
        reason=getattr(detail,"reason",None) if detail is not None else None
        usage=getattr(response,"usage",None)
        output_tokens=getattr(usage,"output_tokens",None) if usage is not None else None
        output_details=getattr(usage,"output_tokens_details",None) if usage is not None else None
        reasoning_tokens=getattr(output_details,"reasoning_tokens",None) if output_details is not None else None
        cap=getattr(response,"max_output_tokens",None)
        diag=[]
        if cap is not None: diag.append(f"cap={cap}")
        if output_tokens is not None: diag.append(f"output_tokens={output_tokens}")
        if reasoning_tokens is not None: diag.append(f"reasoning_tokens={reasoning_tokens}")
        suffix=("; "+", ".join(diag)) if diag else ""
        raise RuntimeError(f"Structured output was incomplete ({reason or 'unknown reason'}); no JSON was accepted{suffix}. No automatic paid retry was made.")
    refusal=_sk_online_refusal_text(response)
    if refusal:
        raise RuntimeError(f"Structured output was refused: {refusal}")
    raw=str(getattr(response,"output_text","") or "").strip()
    if not raw:
        raise RuntimeError("Structured output response contained no output_text.")
    try:
        parsed=digest_module.parse_json_object(raw)
    except (json.JSONDecodeError,ValueError) as exc:
        # With strict Structured Outputs this should be exceptional (for example,
        # a proxy/SDK that silently ignored text.format). Do not spend a second
        # model call trying to repair malformed JSON automatically.
        line=getattr(exc,"lineno",None); col=getattr(exc,"colno",None); pos=getattr(exc,"pos",None)
        where=f" line={line} col={col} pos={pos}" if line is not None else ""
        raise RuntimeError(f"Strict structured output returned malformed JSON for {schema_name}:{where} {exc}") from exc
    if not isinstance(parsed,dict):
        raise RuntimeError(f"Strict structured output root for {schema_name} was not an object.")
    return parsed


def _sk_validate_openai_strict_schema(schema: dict, *, schema_name: str="schema") -> dict:
    """Fail locally if a Structured Outputs schema violates OpenAI strict-object rules.

    In strict mode every object property must be listed in ``required`` and
    ``additionalProperties`` must be false.  Validation happens before the API
    request so an invalid schema cannot consume a remote request.
    """
    if not isinstance(schema, dict):
        raise ValueError(f"Structured schema {schema_name!r} must be a JSON object.")
    problems=[]

    def walk(node, path):
        if not isinstance(node, dict):
            return
        props=node.get("properties")
        node_type=node.get("type")
        if isinstance(props, dict) or node_type == "object":
            props=props if isinstance(props, dict) else {}
            required=node.get("required")
            required_list=list(required) if isinstance(required, list) else []
            prop_keys=list(props.keys())
            missing=[key for key in prop_keys if key not in required_list]
            unknown=[key for key in required_list if key not in props]
            if missing:
                problems.append(f"{path}: required is missing {missing}")
            if unknown:
                problems.append(f"{path}: required contains unknown keys {unknown}")
            if node.get("additionalProperties") is not False:
                problems.append(f"{path}: additionalProperties must be false")
            for key, child in props.items():
                walk(child, f"{path}.properties.{key}")
        items=node.get("items")
        if isinstance(items, dict):
            walk(items, f"{path}.items")
        elif isinstance(items, list):
            for idx, child in enumerate(items):
                walk(child, f"{path}.items[{idx}]")
        for combiner in ("anyOf","oneOf","allOf"):
            values=node.get(combiner)
            if isinstance(values, list):
                for idx, child in enumerate(values):
                    walk(child, f"{path}.{combiner}[{idx}]")
        defs=node.get("$defs")
        if isinstance(defs, dict):
            for key, child in defs.items():
                walk(child, f"{path}.$defs.{key}")

    walk(schema, "$schema")
    if problems:
        raise ValueError(
            f"Structured Outputs schema {schema_name!r} is not strict-compatible: "
            + "; ".join(problems[:12])
        )
    return schema


def _sk_call_json(digest_module, backend, *, system: str, user: str, max_tokens: int, schema: dict, schema_name: str, deep: bool) -> dict:
    autonomy = (
        "COGNITIVE AUTONOMY: Choose your own internal reasoning depth for this task. "
        "NeatMemory does not prescribe minimal/low/medium/high effort. Use as much or as little reasoning as you judge useful, "
        "while returning only the requested visible structured output."
    )
    system = str(system).rstrip() + "\n\n" + autonomy
    if getattr(backend,"provider","") == "local":
        return digest_module._call_local_json_http(backend,system=system,user=user,max_tokens=max_tokens,json_schema=schema,schema_name=schema_name)
    safe_name=re.sub(r"[^A-Za-z0-9_-]+","_",str(schema_name or "neatmemory_deep"))[:64] or "neatmemory_deep"
    _sk_validate_openai_strict_schema(schema, schema_name=safe_name)
    kwargs={
        "model":backend.model_id,
        "input":[{"role":"system","content":system},{"role":"user","content":user}],
        "max_output_tokens":max_tokens,
        "store":False,
        "text":{"format":{"type":"json_schema","name":safe_name,"strict":True,"schema":schema}},
    }
    response=digest_module.call_with_retry(lambda: backend.client.responses.create(**kwargs))
    return _sk_parse_online_structured_response(digest_module,response,schema_name=safe_name)


def _sk_deep_output_cap(digest_module, backend=None, *, max_memories: int|None=None) -> int:
    """Budget hidden reasoning plus visible structured output without forcing spend."""
    max_memories=max(1,int(max_memories or _DEEP_MAX_MEMORIES_PER_CHUNK))
    configured=int(getattr(digest_module,"BOOK_DIGEST_MAX_OUTPUT_TOKENS",12000) or 12000)
    if getattr(backend,"provider","")=="local":
        return max(6000,min(16000,configured))
    raw=os.getenv("NEATMEMORY_DEEP_MAX_OUTPUT_TOKENS","").strip()
    if raw:
        try:return max(8000,min(32000,int(raw)))
        except Exception:pass
    dynamic=6500 + max_memories*650
    return max(_DEEP_ONLINE_OUTPUT_CAP_DEFAULT,min(24000,dynamic))


def _sk_validation_terms(value: str) -> set[str]:
    value=unicodedata.normalize("NFKC",str(value or "")).casefold()
    return set(re.findall(r"[^\W_]+(?:['’\-][^\W_]+)*",value,flags=re.UNICODE))


def _sk_deep_validate_payload(draft: dict, registry: dict, source_text: str, *, max_memories: int) -> dict:
    """Deterministic gate before a second model call or permanent storage."""
    issues=[]; warnings=[]
    if not isinstance(draft,dict):
        return {"ok":False,"issues":["payload is not an object"],"warnings":[],"memory_count":0}
    if draft.get("batch_complete") is not True:
        issues.append("batch_complete is not true")
    memories=draft.get("memories")
    if not isinstance(memories,list):
        return {"ok":False,"issues":issues+["memories is not an array"],"warnings":warnings,"memory_count":0}
    if len(memories)>max_memories:
        issues.append(f"too many memories: {len(memories)} > {max_memories}")
    valid_refs=set(str(k) for k in registry)
    source_fold=unicodedata.normalize("NFKC",str(source_text or "")).casefold()
    source_terms=_sk_validation_terms(source_text)
    seen_claims=set()
    for idx,proposal in enumerate(memories[:max_memories+8],1):
        prefix=f"memory[{idx}]"
        if not isinstance(proposal,dict):
            issues.append(f"{prefix} is not an object"); continue
        claim=" ".join(str(proposal.get("claim") or "").split())
        if len(claim)<8: issues.append(f"{prefix} claim is missing/too short")
        claim_key=unicodedata.normalize("NFKC",claim).casefold()
        if claim_key in seen_claims: warnings.append(f"{prefix} duplicates an earlier claim")
        elif claim_key: seen_claims.add(claim_key)
        refs=proposal.get("source_refs")
        if not isinstance(refs,list) or not refs:
            issues.append(f"{prefix} has no source_refs")
        else:
            invalid=[str(r) for r in refs if str(r) not in valid_refs]
            if invalid: issues.append(f"{prefix} has invalid source_refs: {invalid[:3]}")
        for field in ("importance","confidence"):
            try: number=float(proposal.get(field))
            except Exception: issues.append(f"{prefix} {field} is not numeric"); continue
            if not 0.0<=number<=1.0: issues.append(f"{prefix} {field} is outside 0..1")
        entities=proposal.get("entities")
        if not isinstance(entities,list):
            issues.append(f"{prefix} entities is not an array"); entities=[]
        for eidx,entity in enumerate(entities,1):
            if not isinstance(entity,dict): issues.append(f"{prefix}.entity[{eidx}] is not an object"); continue
            name=" ".join(str(entity.get("name") or "").split())
            origin=str(entity.get("origin") or "").casefold()
            reason=str(entity.get("reason") or "").strip()
            try: confidence=float(entity.get("confidence"))
            except Exception: confidence=-1
            if not name: issues.append(f"{prefix}.entity[{eidx}] missing name")
            if origin not in {"explicit","inferred"}: issues.append(f"{prefix}.entity[{eidx}] invalid origin")
            if not 0.0<=confidence<=1.0: issues.append(f"{prefix}.entity[{eidx}] invalid confidence")
            if origin=="explicit" and name and unicodedata.normalize("NFKC",name).casefold() not in source_fold:
                issues.append(f"{prefix}.entity[{eidx}] marked explicit but not literal in source: {name[:80]}")
            if origin=="inferred" and not reason:
                issues.append(f"{prefix}.entity[{eidx}] inferred without reason")
        implicit=proposal.get("implicit_keywords")
        if not isinstance(implicit,list):
            issues.append(f"{prefix} implicit_keywords is not an array"); implicit=[]
        if len(implicit)>_DEEP_MAX_IMPLICIT_PER_MEMORY:
            warnings.append(f"{prefix} has {len(implicit)} implicit keywords; only first {_DEEP_MAX_IMPLICIT_PER_MEMORY} are indexed")
        for kidx,item in enumerate(implicit,1):
            if not isinstance(item,dict): issues.append(f"{prefix}.implicit[{kidx}] is not an object"); continue
            term=" ".join(str(item.get("term") or "").split())
            reason=str(item.get("reason") or "").strip()
            try: confidence=float(item.get("confidence"))
            except Exception: confidence=-1
            if not term: issues.append(f"{prefix}.implicit[{kidx}] missing term")
            if not 0.0<=confidence<=1.0: issues.append(f"{prefix}.implicit[{kidx}] invalid confidence")
            if not reason: issues.append(f"{prefix}.implicit[{kidx}] missing reason")
            if term and unicodedata.normalize("NFKC",term).casefold() in source_fold:
                warnings.append(f"{prefix}.implicit[{kidx}] is literal in source; implicit expansion is unnecessary")
        if str(proposal.get("interpretation") or "").casefold()=="direct" and claim:
            cterms={t for t in _sk_validation_terms(claim) if len(t)>2}
            if cterms and not (cterms & source_terms):
                issues.append(f"{prefix} direct claim has no lexical grounding in source")
    return {"ok":not issues,"issues":issues[:40],"warnings":warnings[:40],"memory_count":len(memories)}


def _sk_deep_entity_acronym(name: str) -> str:
    words=re.findall(r"[^\W_]+", unicodedata.normalize("NFKC",str(name or "")), flags=re.UNICODE)
    if len(words)<2: return ""
    acronym="".join(word[0] for word in words if word).casefold()
    return acronym if 2<=len(acronym)<=12 else ""


def _sk_deep_safe_metadata_repair(payload: dict, source_text: str) -> tuple[dict,list[dict]]:
    """Repair only non-authoritative entity metadata when the evidence permits it.

    This never edits claims, details, source refs, interpretation, importance, or
    confidence of a knowledge item.  If an explicit entity label is not a literal
    source span, Python may (a) downgrade it to inferred when the source contains
    a defensible lexical/acronym anchor, or (b) remove an extraneous entity that
    is absent from both the claim/details and the source.  Anything else remains
    unresolved for the model verifier / fail-closed path.
    """
    if not isinstance(payload,dict): return payload,[]
    memories=payload.get("memories")
    if not isinstance(memories,list): return payload,[]
    source_raw=unicodedata.normalize("NFKC",str(source_text or ""))
    source_fold=source_raw.casefold()
    source_terms={t for t in _sk_validation_terms(source_raw) if len(t)>2}
    repairs=[]
    for midx,proposal in enumerate(memories,1):
        if not isinstance(proposal,dict): continue
        entities=proposal.get("entities")
        if not isinstance(entities,list): continue
        context=unicodedata.normalize("NFKC",f"{proposal.get('claim') or ''} {proposal.get('details') or ''}").casefold()
        kept=[]
        for eidx,entity in enumerate(entities,1):
            if not isinstance(entity,dict):
                kept.append(entity); continue
            name=" ".join(str(entity.get("name") or "").split())
            origin=str(entity.get("origin") or "").casefold()
            name_fold=unicodedata.normalize("NFKC",name).casefold()
            if origin!="explicit" or not name or name_fold in source_fold:
                kept.append(entity); continue
            acronym=_sk_deep_entity_acronym(name)
            acronym_present=bool(acronym and re.search(rf"(?<![\w]){re.escape(acronym)}(?![\w])",source_fold,re.UNICODE))
            name_terms={t for t in _sk_validation_terms(name) if len(t)>2}
            grounded=sorted(name_terms & source_terms)
            coverage=(len(grounded)/len(name_terms)) if name_terms else 0.0
            in_context=bool(name_fold and name_fold in context)
            # Strong deterministic anchor: the source literally contains the
            # acronym for the expanded entity name (e.g. IRS -> Internal Revenue Service).
            if acronym_present:
                try: conf=float(entity.get("confidence",0.75))
                except Exception: conf=0.75
                entity=dict(entity); entity["origin"]="inferred"; entity["confidence"]=min(max(conf,0.0),0.84)
                entity["reason"]=f"Python evidence repair: full label is not a literal source span; resolved from source acronym {acronym.upper()}."
                kept.append(entity); repairs.append({"memory":midx,"entity":eidx,"name":name,"action":"explicit_to_inferred","anchor":f"acronym:{acronym.upper()}"}); continue
            # A normalized label may add a generic qualifier while retaining
            # substantial literal grounding (e.g. 'Montague family' from 'Montague').
            if in_context and grounded and coverage>=0.5:
                try: conf=float(entity.get("confidence",0.72))
                except Exception: conf=0.72
                entity=dict(entity); entity["origin"]="inferred"; entity["confidence"]=min(max(conf,0.0),0.78)
                entity["reason"]="Python evidence repair: normalized entity label is not literal; retained as inferred from source terms: "+", ".join(grounded[:4])+"."
                kept.append(entity); repairs.append({"memory":midx,"entity":eidx,"name":name,"action":"explicit_to_inferred","anchor":"terms:"+",".join(grounded[:4])}); continue
            # If the label appears in the proposed claim/details but is not a
            # literal target-chunk span, it can only survive as contextual/inferred
            # metadata.  This closes the failure mode where a neighbor/prior-digest
            # identity (for example, Paris) was repeatedly mislabeled explicit.
            if in_context:
                try: conf=float(entity.get("confidence",0.68))
                except Exception: conf=0.68
                entity=dict(entity); entity["origin"]="inferred"; entity["confidence"]=min(max(conf,0.0),0.70)
                entity["reason"]="Python evidence repair: entity label is not literal in the target chunk; retained only as contextual inference from the proposed claim/details."
                kept.append(entity); repairs.append({"memory":midx,"entity":eidx,"name":name,"action":"explicit_to_inferred","anchor":"claim-context-only"}); continue
            # Partial lexical grounding in the target is still insufficient for an
            # explicit label.  Retain it only as a lower-confidence inference.
            if grounded:
                try: conf=float(entity.get("confidence",0.66))
                except Exception: conf=0.66
                entity=dict(entity); entity["origin"]="inferred"; entity["confidence"]=min(max(conf,0.0),0.68)
                entity["reason"]="Python evidence repair: full entity label is not literal in the target chunk; retained as inferred from partial target terms: "+", ".join(grounded[:4])+"."
                kept.append(entity); repairs.append({"memory":midx,"entity":eidx,"name":name,"action":"explicit_to_inferred","anchor":"partial-terms:"+",".join(grounded[:4])}); continue
            # If the model emitted an entity only as surplus metadata and neither
            # the claim/details nor source supports the full label, dropping that
            # metadata cannot change the knowledge claim itself.
            repairs.append({"memory":midx,"entity":eidx,"name":name,"action":"remove_extraneous_entity","anchor":"none"}); continue
        proposal["entities"]=kept
    return payload,repairs


def _sk_deep_book_model(digest_module, backend, book: dict, row: dict, previous_items: list[dict], chunk_index: int, total_chunks: int) -> tuple[dict,dict,int,dict]:
    registry=digest_module._book_source_registry(book,[row])
    ref,src=next(iter(registry.items()))
    source_text=str(src.get("excerpt") or "")
    previous_items=list(previous_items or [])[:_DEEP_PREVIOUS_ITEMS_LIMIT]
    packet={"book":{"book_id":book.get("book_id"),"title":book.get("title"),"authors":book.get("authors") or []},"chunk":{"number":chunk_index,"total":total_chunks,"ref":ref,"ordinal":row.get("ordinal"),"chapter":row.get("chapter"),"content":src.get("excerpt")},"previous_active_digest_items":previous_items}
    schema=_sk_book_schema(deep=True)
    max_memories=min(_DEEP_MAX_MEMORIES_PER_CHUNK,int(getattr(digest_module,'BOOK_DIGEST_MAX_MEMORIES',24))+8)
    output_cap=_sk_deep_output_cap(digest_module,backend,max_memories=max_memories)
    system=f"""You are NeatMemory's deep archival book curator. Work source-first on exactly one book chunk. The original chunk is authoritative; the previous digest is guidance only and may be wrong. Extract the most durable atomic knowledge, relationships, chronology, named entities, objects, unresolved references and important details without trying to exhaust every sentence. Every memory must cite the exact supplied source ref. Explicit entities must literally occur in the chunk. Inferred entities may resolve pronouns or local context but require confidence and a concrete reason. Add only high-value implicit_keywords for concepts not literally stated but strongly supported; they are navigation aids, never evidence. Avoid trivial synonyms and keep at most {_DEEP_MAX_IMPLICIT_PER_MEMORY} implicit concepts per memory. Keep claims concise, details focused, reasons short, and do not repeat the same fact in multiple memories. Return JSON only and set batch_complete=true. Create at most {max_memories} memories."""
    draft=_sk_call_json(digest_module,backend,system=system,user=json.dumps(packet,ensure_ascii=False),max_tokens=output_cap,schema=schema,schema_name="neatmemory_deep_book_extract_v4",deep=True)
    audit=_sk_deep_validate_payload(draft,registry,source_text,max_memories=max_memories)
    calls=1
    if audit["ok"]:
        return draft,registry,calls,{"python_gate":"pass","second_model_pass":False,"python_repairs":[],"issues":[],"warnings":audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset"}

    repaired,repairs=_sk_deep_safe_metadata_repair(draft,source_text)
    repaired_audit=_sk_deep_validate_payload(repaired,registry,source_text,max_memories=max_memories)
    if repairs and repaired_audit["ok"]:
        return repaired,registry,calls,{"python_gate":"metadata_repair","second_model_pass":False,"python_repairs":repairs,"initial_issues":audit["issues"],"issues":[],"warnings":repaired_audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset"}

    verify_packet={"source":packet["chunk"],"previous_active_digest_items":previous_items,"draft":repaired,"python_validation_issues":repaired_audit["issues"],"python_metadata_repairs":repairs}
    verify_system="""You are a conditional verification pass for a permanent source-grounded knowledge archive. Python found concrete validation problems in the draft. Re-read the exact original source and correct those problems. Remove unsupported claims, fix invalid source refs, correct explicit/inferred entity labels, preserve uncertainty, and recover important omissions only when directly supported. The original source outranks both the old digest and draft. Keep implicit keywords non-authoritative and strongly supported. Return the final schema only with batch_complete=true."""
    final=_sk_call_json(digest_module,backend,system=verify_system,user=json.dumps(verify_packet,ensure_ascii=False),max_tokens=output_cap,schema=schema,schema_name="neatmemory_deep_book_verify_v4",deep=True)
    calls+=1
    final_audit=_sk_deep_validate_payload(final,registry,source_text,max_memories=max_memories)
    post_repairs=[]
    if not final_audit["ok"]:
        final,post_repairs=_sk_deep_safe_metadata_repair(final,source_text)
        final_audit=_sk_deep_validate_payload(final,registry,source_text,max_memories=max_memories)
    if not final_audit["ok"]:
        raise RuntimeError("Deep conditional verifier still failed deterministic validation: "+"; ".join(final_audit["issues"][:8]))
    return final,registry,calls,{"python_gate":"conditional_verify"+("+metadata_repair" if post_repairs else ""),"second_model_pass":True,"python_repairs":repairs+post_repairs,"initial_issues":audit["issues"],"issues":[],"warnings":final_audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset","verify_reasoning_control":"assistant-selected; API effort unset"}


def _sk_find_resumable_deep(source_id: str, *, source_sha256: str, scope: str, provider: str, model_alias: str|None, model_id: str, operation: str) -> dict|None:
    with _sk_connect() as db:
        row=db.execute("""SELECT v.*,r.processed_chunks,r.model_calls,r.items_created,r.status AS run_status
                          FROM knowledge_versions v JOIN knowledge_runs r ON r.run_id=v.run_id
                          WHERE v.source_id=? AND v.source_sha256=? AND v.scope=? AND v.digest_mode='deep'
                            AND v.provider=? AND COALESCE(v.model_alias,'')=COALESCE(?, '') AND v.model_id=?
                            AND v.status IN ('processing','paused') AND v.archive=0 AND r.operation=?
                          ORDER BY v.version_number DESC LIMIT 1""",
                       (source_id,source_sha256,scope,provider,model_alias,model_id,operation)).fetchone()
    return dict(row) if row else None


def _sk_supersede_resumable_deep_versions(source_id: str, *, source_sha256: str, provider: str, model_alias: str|None, model_id: str, operation: str, reason: str="--force full redigest") -> list[str]:
    """Non-destructively retire incomplete deep checkpoints before a forced restart.

    Completed active knowledge is untouched.  Only processing/paused deep versions
    for the same source/provider/model/operation are marked superseded+archived so
    a later normal /redigest --deep cannot accidentally resume stale checkpoints.
    """
    now=_sk_now(); changed=[]
    with _sk_connect() as db:
        rows=db.execute("""SELECT v.version_id,v.run_id,v.notes_json
                           FROM knowledge_versions v JOIN knowledge_runs r ON r.run_id=v.run_id
                           WHERE v.source_id=? AND v.source_sha256=? AND v.digest_mode='deep'
                             AND v.provider=? AND COALESCE(v.model_alias,'')=COALESCE(?, '') AND v.model_id=?
                             AND v.status IN ('processing','paused') AND v.archive=0 AND r.operation=?
                           ORDER BY v.version_number""",
                        (source_id,source_sha256,provider,model_alias,model_id,operation)).fetchall()
        for row in rows:
            try: notes=json.loads(row["notes_json"] or "{}")
            except Exception: notes={}
            notes.update({"superseded":True,"superseded_reason":reason,"superseded_at":now,"resumable":False,"deep_version":_DEEP_REDIGEST_VERSION})
            db.execute("UPDATE knowledge_versions SET status='superseded',active=0,archive=1,notes_json=? WHERE version_id=?",(_sk_json(notes),row["version_id"]))
            db.execute("UPDATE knowledge_runs SET status='superseded',completed_at=COALESCE(completed_at,?),error=COALESCE(error,?) WHERE run_id=?",(now,reason,row["run_id"]))
            changed.append(str(row["version_id"]))
    for version_id in changed:
        _sk_event("deep_redigest_superseded_by_force",{"reason":reason,"resumable":False},version_id=version_id)
    return changed


def _sk_pause_version(version_id: str, run_id: str, reason: str, *, processed: int, model_calls: int, items: int) -> None:
    now=_sk_now(); reason=str(reason or "paused")[:2000]
    with _sk_connect() as db:
        db.execute("UPDATE knowledge_versions SET status='paused',active=0,archive=0,notes_json=? WHERE version_id=?",(_sk_json({"paused":reason,"resumable":True,"deep_version":_DEEP_REDIGEST_VERSION}),version_id))
        db.execute("UPDATE knowledge_runs SET status='paused',processed_chunks=?,model_calls=?,items_created=?,error=? WHERE run_id=?",(processed,model_calls,items,reason,run_id))
    _sk_event("deep_redigest_paused",{"run_id":run_id,"reason":reason,"processed":processed,"model_calls":model_calls,"items":items,"resume":True},version_id=version_id)


def _sk_resume_version(version_id: str, run_id: str) -> None:
    with _sk_connect() as db:
        db.execute("UPDATE knowledge_versions SET status='processing',active=0,archive=0 WHERE version_id=?",(version_id,))
        db.execute("UPDATE knowledge_runs SET status='processing',error=NULL,completed_at=NULL WHERE run_id=?",(run_id,))
    _sk_event("deep_redigest_resumed",{"run_id":run_id,"deep_version":_DEEP_REDIGEST_VERSION},version_id=version_id)


def _sk_deep_test_book(digest_module, memory_module, backend, book_ref: str, *, count: int=2, model_alias: str|None=None) -> dict:
    book,selected,scope,_force=digest_module._load_book_scope(book_ref,[])
    count=max(1,min(_DEEP_TEST_CHUNKS_MAX,int(count)))
    selected=list(selected)[:count]
    source_id=_sk_source_id("book",str(book["book_id"]))
    results=[]; model_calls=0
    for index,row in enumerate(selected,1):
        try: previous=_sk_active_items_for_chunk(source_id,str(row.get("chunk_id") or ""))
        except Exception: previous=[]
        result,_registry,calls,audit=_sk_deep_book_model(digest_module,backend,book,row,previous,index,len(selected))
        model_calls+=calls
        memories=result.get("memories") or []
        results.append({"chunk_id":row.get("chunk_id"),"ordinal":row.get("ordinal"),"model_calls":calls,"audit":audit,"memory_count":len(memories),"sample_claims":[str(m.get("claim") or "")[:300] for m in memories[:5] if isinstance(m,dict)]})
    return {"ok":True,"test_only":True,"stored":False,"active_digest_changed":False,"book_id":book.get("book_id"),"title":book.get("title"),"provider":"lmstudio" if getattr(backend,"provider","")=="local" else "gpt","model_alias":model_alias,"model":backend.model_id,"deep_version":_DEEP_REDIGEST_VERSION,"tested_chunks":len(selected),"model_calls":model_calls,"chunks":results}


def _sk_backend(digest_module, memory_module, *, use_lmstudio: bool=False, gpt_alias: str|None=None):
    if use_lmstudio:
        return digest_module.build_local_backend(), "lmstudio", None
    alias=(gpt_alias or _sk_model_alias(memory_module)).casefold()
    if alias not in _GPT_MODEL_ALIASES: raise ValueError("GPT alias must be luna, terra, or sol.")
    if not str(getattr(digest_module,"OPENAI_API_KEY","") or os.getenv("OPENAI_API_KEY","")).strip():
        raise RuntimeError("OPENAI_API_KEY is required for GPT redigestion.")
    client=digest_module.OpenAI(api_key=str(getattr(digest_module,"OPENAI_API_KEY","") or os.getenv("OPENAI_API_KEY","")).strip())
    backend=digest_module.OnlineBackend(client=client,model_id=_GPT_MODEL_ALIASES[alias])
    return backend,"gpt",alias



def _sk_normal_resume_candidates(source_id: str, *, source_sha256: str, scope: str, provider: str, model_alias: str | None, model_id: str, operation: str, selected: list[dict]) -> list[dict]:
    """Return exact-compatible incomplete normal-digest versions ranked by durable work.

    This is intentionally stricter than a generic retry: source hash, scope,
    provider/model, operation, selected chunk set, and total chunk count must all
    match.  Multiple compatible interrupted versions can exist after an old
    Ctrl+C/restart bug; ranking prefers the checkpoint that preserves the most
    already-paid-for exact work, not merely the newest version number.
    """
    selected_pairs={(str(r.get("chunk_id") or ""),str(r.get("text_sha256") or _sk_hash(r.get("text") or ""))) for r in (selected or [])}
    if not selected_pairs:
        return []
    alias=str(model_alias or "") if str(provider)!="lmstudio" else ""
    with _sk_connect() as db:
        rows=db.execute("""SELECT v.*,r.processed_chunks,r.total_chunks,r.model_calls,r.items_created,r.status AS run_status,r.error AS run_error
                           FROM knowledge_versions v JOIN knowledge_runs r ON r.run_id=v.run_id
                           WHERE v.source_id=? AND v.source_sha256=? AND v.scope=? AND v.digest_mode='normal'
                             AND v.provider=? AND COALESCE(v.model_alias,'')=? AND v.model_id=? AND r.operation=?
                             AND v.active=0 AND v.status IN ('processing','paused','failed')
                           ORDER BY v.version_number DESC""",
                        (source_id,source_sha256,scope,provider,alias,model_id,str(operation or "").casefold())).fetchall()
        table_names={str(x[0]) for x in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('knowledge_semantic_units','knowledge_structural_resumes')").fetchall()}
        out=[]
        for raw in rows:
            item=dict(raw)
            if int(item.get("total_chunks") or 0)!=len(selected_pairs):
                continue
            completed_rows=db.execute("SELECT chunk_id,text_sha256 FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(item["version_id"],)).fetchall()
            completed={(str(x["chunk_id"]),str(x["text_sha256"])) for x in completed_rows}
            if not completed.issubset(selected_pairs):
                continue
            item["completed_knowledge_chunks"]=len(completed)
            item["semantic_units"]=int(db.execute("SELECT COUNT(*) FROM knowledge_semantic_units WHERE version_id=?",(item["version_id"],)).fetchone()[0]) if "knowledge_semantic_units" in table_names else 0
            item["structural_resumes"]=int(db.execute("SELECT COUNT(*) FROM knowledge_structural_resumes WHERE version_id=?",(item["version_id"],)).fetchone()[0]) if "knowledge_structural_resumes" in table_names else 0
            item["resume_score"]=[item["completed_knowledge_chunks"],item["semantic_units"],item["structural_resumes"],int(item.get("version_number") or 0)]
            out.append(item)
    out.sort(key=lambda x: tuple(int(v) for v in x.get("resume_score") or [0,0,0,0]),reverse=True)
    return out


def _sk_choose_resumable_normal(source_id: str, *, source_sha256: str, scope: str, provider: str, model_alias: str | None, model_id: str, operation: str, selected: list[dict]) -> tuple[dict | None,list[dict]]:
    candidates=_sk_normal_resume_candidates(source_id,source_sha256=source_sha256,scope=scope,provider=provider,model_alias=model_alias,model_id=model_id,operation=operation,selected=selected)
    return (dict(candidates[0]) if candidates else None), candidates


def _sk_supersede_competing_normal_checkpoints(chosen_version_id: str, candidates: list[dict]) -> list[str]:
    changed=[]; now=_sk_now()
    for item in candidates or []:
        vid=str(item.get("version_id") or "")
        if not vid or vid==str(chosen_version_id):
            continue
        run_id=str(item.get("run_id") or "")
        reason=f"Compatible interrupted checkpoint superseded by more complete resume checkpoint {chosen_version_id}; retained for history."
        with _sk_connect() as db:
            row=db.execute("SELECT notes_json FROM knowledge_versions WHERE version_id=?",(vid,)).fetchone()
            try: notes=json.loads(str(row["notes_json"] or "{}")) if row else {}
            except Exception: notes={}
            notes.update({"superseded":True,"superseded_reason":reason,"superseded_at":now,"resumable":False,"resume_winner":str(chosen_version_id)})
            db.execute("UPDATE knowledge_versions SET status='superseded',active=0,archive=1,notes_json=? WHERE version_id=?",(_sk_json(notes),vid))
            if run_id:
                db.execute("UPDATE knowledge_runs SET status='superseded',completed_at=COALESCE(completed_at,?),error=COALESCE(error,?) WHERE run_id=?",(now,reason,run_id))
        _sk_event("normal_digest_checkpoint_superseded",{"resume_winner":str(chosen_version_id),"reason":reason},version_id=vid)
        changed.append(vid)
    return changed


def _sk_pause_normal_version(version_id: str, run_id: str, reason: BaseException | str, *, processed: int, model_calls: int, items: int) -> None:
    message=str(reason) if isinstance(reason,str) else f"{type(reason).__name__}: {reason}"
    now=_sk_now()
    with _sk_connect() as db:
        row=db.execute("SELECT notes_json FROM knowledge_versions WHERE version_id=?",(version_id,)).fetchone()
        try: notes=json.loads(str(row["notes_json"] or "{}")) if row else {}
        except Exception: notes={}
        notes.update({"paused":message[:2000],"paused_at":now,"resumable":True,"resume_mode":"normal-digest-durable","digest_resume_version":"1.0"})
        db.execute("UPDATE knowledge_versions SET status='paused',active=0,archive=0,completed_at=NULL,notes_json=? WHERE version_id=?",(_sk_json(notes),version_id))
        db.execute("UPDATE knowledge_runs SET status='paused',processed_chunks=?,model_calls=?,items_created=?,completed_at=NULL,error=? WHERE run_id=?",(int(processed),int(model_calls),int(items),message[:4000],run_id))
    _sk_event("normal_digest_paused",{"run_id":run_id,"reason":message[:2000],"processed":int(processed),"model_calls":int(model_calls),"items":int(items),"resumable":True},version_id=version_id)


def _sk_digest_book(digest_module, memory_module, backend, book_ref: str, scope_tokens: list[str]|None=None, *, operation: str="digest", deep: bool=False, model_alias: str|None=None, force_full: bool=False) -> dict:
    # --force on /redigest intentionally means a FULL fresh pass. Normal digest
    # retries without --force may resume exact compatible durable checkpoints.
    load_tokens=[] if force_full else list(scope_tokens or [])
    book, selected, scope, force=digest_module._load_book_scope(book_ref,load_tokens)
    if force_full:
        scope="full book"; force=True
    book_id=str(book["book_id"]); source_hash=_sk_source_hash_for_book(book,selected)
    source=_sk_upsert_source("book",book_id,str(book.get("title") or book_id),source_hash,{"kind":"neatbooks","book_id":book_id,"shared_root":str(_sk_root_path())})
    current=_sk_current_version(source["source_id"])
    if operation=="digest" and current and str(current.get("source_sha256"))==source_hash and not force:
        return {"ok":True,"already_digested":True,"shared_knowledge":True,"book_id":book_id,"source_id":source["source_id"],"active_version_id":current["version_id"],"message":"Active shared-knowledge digest already exists. Use /redigest for a new version or --force for a normal replacement pass."}
    mode="deep" if deep else "normal"
    provider="lmstudio" if getattr(backend,"provider","")=="local" else "gpt"
    alias=model_alias if provider=="gpt" else None
    resumed=False; superseded_incomplete_versions=[]; resume_candidates=[]
    if deep and force_full:
        superseded_incomplete_versions=_sk_supersede_resumable_deep_versions(
            source["source_id"],source_sha256=source_hash,provider=provider,model_alias=alias,
            model_id=str(backend.model_id),operation=operation,reason="--force requested a fresh full deep redigest from chunk 1")
        existing=None
    elif deep:
        existing=_sk_find_resumable_deep(source["source_id"],source_sha256=source_hash,scope=scope,provider=provider,model_alias=alias,model_id=str(backend.model_id),operation=operation)
    elif not force:
        existing,resume_candidates=_sk_choose_resumable_normal(source["source_id"],source_sha256=source_hash,scope=scope,provider=provider,model_alias=alias,model_id=str(backend.model_id),operation=operation,selected=selected)
    else:
        existing=None
    if existing:
        started={"version_id":existing["version_id"],"version_number":int(existing["version_number"]),"previous_version_id":existing.get("previous_version_id"),"run_id":existing["run_id"]}
        resumed=True
        _sk_resume_version(started["version_id"],started["run_id"])
        if not deep:
            superseded_incomplete_versions.extend(_sk_supersede_competing_normal_checkpoints(started["version_id"],resume_candidates))
    else:
        started=_sk_begin_version(source=source,scope=scope,digest_mode=mode,provider=provider,model_alias=alias,model_id=str(backend.model_id),operation=operation,total_chunks=len(selected))
    version_id=started["version_id"]; run_id=started["run_id"]
    with _sk_connect() as db:
        completed_rows=db.execute("SELECT chunk_id,text_sha256 FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(version_id,)).fetchall()
        completed={(str(r["chunk_id"]),str(r["text_sha256"])) for r in completed_rows}
        runrow=db.execute("SELECT model_calls FROM knowledge_runs WHERE run_id=?",(run_id,)).fetchone()
        model_calls=int(runrow["model_calls"] or 0) if runrow else 0
        items_created=int(db.execute("SELECT COUNT(*) FROM knowledge_items WHERE version_id=?",(version_id,)).fetchone()[0])
        index_passages=int(db.execute("SELECT COUNT(*) FROM knowledge_passages WHERE version_id=?",(version_id,)).fetchone()[0])
        index_terms=int(db.execute("SELECT COUNT(*) FROM knowledge_terms t JOIN knowledge_passages p ON p.passage_id=t.passage_id WHERE p.version_id=?",(version_id,)).fetchone()[0])
    selected_pairs={(str(r.get("chunk_id") or ""),str(r.get("text_sha256") or _sk_hash(r.get("text") or ""))) for r in selected}
    processed=sum(1 for pair in selected_pairs if pair in completed)
    reused_initial=processed
    conditional_verifications=0
    if resumed:
        sem_count=int(existing.get("semantic_units") or 0) if isinstance(existing,dict) else 0
        struct_count=int(existing.get("structural_resumes") or 0) if isinstance(existing,dict) else 0
        print(f"  [resume] durable checkpoint {version_id}: knowledge {processed}/{len(selected)} complete; semantic units {sem_count}; structural resumes {struct_count}")
        if superseded_incomplete_versions:
            print(f"  [resume] preserved {len(superseded_incomplete_versions)} weaker compatible interrupted checkpoint(s) as superseded history")
    try:
        batches=[[row] for row in selected] if deep else digest_module._book_batches(selected)
        skipped_batches=0
        for index,batch in enumerate(batches,1):
            pending=[]
            for row in batch:
                pair=(str(row.get("chunk_id") or ""),str(row.get("text_sha256") or _sk_hash(row.get("text") or "")))
                if pair not in completed:
                    pending.append(row)
            if not pending:
                skipped_batches+=1
                continue
            batch=pending
            first=int(batch[0].get("ordinal") or 0); last=int(batch[-1].get("ordinal") or 0)
            print(f"  {'deep ' if deep else ''}knowledge batch {index}/{len(batches)}: chunks {first}-{last}")
            audit=None
            if deep:
                row=batch[0]; previous=_sk_active_items_for_chunk(source["source_id"],str(row.get("chunk_id") or ""))
                result,registry,calls,audit=_sk_deep_book_model(digest_module,backend,book,row,previous,index,len(batches))
                if audit.get("second_model_pass"): conditional_verifications+=1
                print(f"    python gate: {audit.get('python_gate')} | model calls this chunk: {calls}")
            else:
                result,registry=digest_module._SHARED_ORIGINAL_BOOK_CALL(backend,book,scope,batch,index,len(batches)); calls=1
            proposals=result.get("memories") or []
            stored=_sk_store_book_batch(digest_module,version_id=version_id,source_id=source["source_id"],backend=backend,book=book,batch=batch,proposals=proposals,registry=registry)
            for row in batch:
                completed.add((str(row.get("chunk_id") or ""),str(row.get("text_sha256") or _sk_hash(row.get("text") or ""))))
            processed=sum(1 for pair in selected_pairs if pair in completed)
            model_calls += calls
            items_created += len(stored.get("inserted") or [])
            index_passages += int((stored.get("entity_index") or {}).get("passages",0)); index_terms += int((stored.get("entity_index") or {}).get("terms",0))
            with _sk_connect() as db:
                db.execute("UPDATE knowledge_runs SET processed_chunks=?,model_calls=?,items_created=?,stats_json=? WHERE run_id=?",(processed,model_calls,items_created,_sk_json({"conditional_verifications":conditional_verifications,"deep_version":_DEEP_REDIGEST_VERSION,"forced_full_redigest":bool(force_full),"durable_resume":True,"reused_completed_chunks":reused_initial}),run_id))
        if skipped_batches and resumed:
            print(f"  [resume] skipped {skipped_batches} fully completed knowledge batch(es); no model calls repeated for them")
        with _sk_connect() as db:
            done=int(db.execute("SELECT COUNT(*) FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(version_id,)).fetchone()[0])
            items_created=int(db.execute("SELECT COUNT(*) FROM knowledge_items WHERE version_id=?",(version_id,)).fetchone()[0])
            index_passages=int(db.execute("SELECT COUNT(*) FROM knowledge_passages WHERE version_id=?",(version_id,)).fetchone()[0])
            index_terms=int(db.execute("SELECT COUNT(*) FROM knowledge_terms t JOIN knowledge_passages p ON p.passage_id=t.passage_id WHERE p.version_id=?",(version_id,)).fetchone()[0])
        if done < len(selected):
            reason="digest run incomplete; rerun the same command without --force to continue from durable checkpoints"
            if deep: _sk_pause_version(version_id,run_id,reason,processed=done,model_calls=model_calls,items=items_created)
            else: _sk_pause_normal_version(version_id,run_id,reason,processed=done,model_calls=model_calls,items=items_created)
            return {"ok":False,"paused":True,"resumable":True,"version_id":version_id,"run_id":run_id,"processed_chunks":done,"total_chunks":len(selected),"active_digest_changed":False,"previous_active_version_id":started.get("previous_version_id"),"resume_command":f"/{'redigest' if operation=='redigest' else 'digest'} {book_id}"}
        print(f"  [finalize] knowledge evidence complete {done}/{len(selected)}; entering semantic-map finalization (completed knowledge will not be repeated)")
        activation=_sk_finalize_version(source["source_id"],version_id,run_id,processed=len(selected),model_calls=model_calls,items=items_created,stats={"passages":index_passages,"terms":index_terms,"conditional_verifications":conditional_verifications,"deep_version":_DEEP_REDIGEST_VERSION if deep else None,"resumed":resumed,"durable_resume":True,"reused_completed_chunks":reused_initial,"forced_full_redigest":bool(force_full),"superseded_incomplete_versions":superseded_incomplete_versions})
        print("  [done] digest version activated; derived navigation finalization complete")
        archive=None
        if scope=="full book":
            try: archive=digest_module.books.archive_book_file(book_id)
            except Exception as exc: archive={"ok":False,"error":f"{type(exc).__name__}: {exc}"}
        return {"ok":True,"shared_knowledge":True,"operation":operation,"mode":mode,"deep_version":_DEEP_REDIGEST_VERSION if deep else None,"resumed":resumed,"durable_resume":True,"reused_completed_chunks":reused_initial,"forced_full_redigest":bool(force_full),"superseded_incomplete_versions":superseded_incomplete_versions,"run_id":run_id,"source_id":source["source_id"],"book_id":book_id,"title":book.get("title"),"version_id":version_id,"version_number":started["version_number"],"previous_version_id":started["previous_version_id"],"active":True,"archive":False,"provider":provider,"model_alias":alias,"model":backend.model_id,"processed_chunks":len(selected),"model_calls":model_calls,"conditional_verifications":conditional_verifications,"knowledge_items_created":items_created,"evidence_passages":index_passages,"indexed_terms":index_terms,"archived_previous_versions":activation["archived_previous_versions"],"book_file_archive":archive}
    except KeyboardInterrupt:
        with _sk_connect() as db:
            processed=int(db.execute("SELECT COUNT(*) FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(version_id,)).fetchone()[0])
            items_created=int(db.execute("SELECT COUNT(*) FROM knowledge_items WHERE version_id=?",(version_id,)).fetchone()[0])
        if deep: _sk_pause_version(version_id,run_id,"user cancelled with Ctrl+C",processed=processed,model_calls=model_calls,items=items_created)
        else: _sk_pause_normal_version(version_id,run_id,"user cancelled with Ctrl+C",processed=processed,model_calls=model_calls,items=items_created)
        print(f"  [paused] durable digest checkpoint saved at knowledge {processed}/{len(selected)}; rerun the same command WITHOUT --force to resume")
        return {"ok":False,"cancelled":True,"paused":True,"resumable":True,"version_id":version_id,"run_id":run_id,"processed_chunks":processed,"total_chunks":len(selected),"model_calls":model_calls,"active_digest_changed":False,"previous_active_version_id":started.get("previous_version_id"),"resume_command":f"/{'redigest' if operation=='redigest' else 'digest'} {book_id}"}
    except Exception as exc:
        with _sk_connect() as db:
            processed=int(db.execute("SELECT COUNT(*) FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(version_id,)).fetchone()[0])
            items_created=int(db.execute("SELECT COUNT(*) FROM knowledge_items WHERE version_id=?",(version_id,)).fetchone()[0])
        if deep:
            _sk_pause_version(version_id,run_id,exc,processed=processed,model_calls=model_calls,items=items_created)
            recovery=("rerun WITHOUT --force to resume this new checkpoint, or keep --force to intentionally restart again from chunk 1" if force_full else "rerun the same provider/model command to continue")
            raise RuntimeError(f"Deep shared-knowledge {operation} paused after {processed}/{len(selected)} chunks; {recovery}. The previous active digest remains active. {exc}") from exc
        _sk_pause_normal_version(version_id,run_id,exc,processed=processed,model_calls=model_calls,items=items_created)
        raise RuntimeError(f"Shared-knowledge {operation} paused after {processed}/{len(selected)} chunks. Completed knowledge and semantic checkpoints are durable; rerun the same command WITHOUT --force to resume. The previous active digest remains active. {exc}") from exc

def _sk_report_source_rows(digest_module, report: dict, registry: dict, proposals: list[dict]) -> tuple[list[str],int]:
    return [],0


def _sk_store_research_proposals(*, version_id: str, source_id: str, proposals: list[dict], resolver, registry: dict, run_id: str) -> dict:
    inserted=[]; rejected=0; source_claims={}
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            for proposal in proposals:
                if not isinstance(proposal,dict): rejected+=1; continue
                resolved_out=resolver(proposal.get("source_refs") or proposal.get("sources"),registry)
                resolved=resolved_out[0] if isinstance(resolved_out,tuple) else resolved_out
                item_id=_sk_store_item(db,version_id=version_id,proposal=proposal,resolved_sources=resolved or [],source_kind="research",metadata={"research_run_id":run_id})
                if not item_id: rejected+=1; continue
                inserted.append(item_id)
                for src in resolved or []:
                    key=str(src.get("ref") or src.get("file") or "source")
                    bucket=source_claims.setdefault(key,{"src":src,"claims":[]})
                    bucket["claims"].append(proposal)
            db.commit()
        except Exception:
            db.rollback(); raise
    passages=terms=0
    with _sk_connect() as db:
        for source_ref,bucket in source_claims.items():
            src=bucket["src"]; text=str(src.get("excerpt") or src.get("text") or src.get("content") or "")
            if not text.strip(): continue
            spans=_dei_split_evidence_passages(text)
            support={}
            for proposal in bucket["claims"]:
                claim=_dei_clean(f"{proposal.get('claim') or ''} {proposal.get('details') or ''}",1800)
                inferred=_sk_entities_from_proposal(proposal,0.82)
                for idx in _dei_select_support_passages(spans,claim,inferred):
                    b=support.setdefault(idx,{"summaries":[],"inferred":[]})
                    if proposal.get("claim") not in b["summaries"]: b["summaries"].append(str(proposal.get("claim") or ""))
                    b["inferred"].extend(inferred)
            for idx,span in enumerate(spans):
                b=support.get(idx,{"summaries":[],"inferred":[]})
                locator={"kind":"research_span","source_ref":source_ref,"snapshot_id":src.get("snapshot_id"),"page_id":src.get("page_id"),"char_start":int(span["char_start"]),"char_end":int(span["char_end"])}
                pid=_sk_id("KP",{"version":version_id,"locator":locator,"sha":_sk_hash(span["text"])},20)
                db.execute("INSERT OR REPLACE INTO knowledge_passages(passage_id,version_id,source_id,source_ref,source_kind,chunk_id,chunk_ordinal,passage_ordinal,char_start,char_end,source_text_sha256,summary_text,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(pid,version_id,source_id,source_ref,"research",None,None,idx+1,int(span["char_start"]),int(span["char_end"]),_sk_hash(span["text"])," ".join(b["summaries"])[:4000],_sk_json({"locator":locator,"run_id":run_id}),_sk_now()))
                db.execute("DELETE FROM knowledge_terms WHERE passage_id=?",(pid,))
                built=_dei_build_terms(span["text"],b["inferred"])
                for t in built:
                    db.execute("INSERT OR REPLACE INTO knowledge_terms(passage_id,term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,ordinal) VALUES(?,?,?,?,?,?,?,?,?)",(pid,t["term_norm"],t["canonical_norm"],t["display_text"],t["entity_type"],t["origin"],float(t["confidence"]),1 if t.get("is_alias") else 0,int(t["ordinal"])))
                passages+=1; terms+=len(built)
    return {"inserted":inserted,"rejected":rejected,"passages":passages,"terms":terms}


def _sk_digest_research_report(digest_module, memory_module, backend, run_id: str) -> dict:
    source_path=digest_module._find_report_path(run_id,include_archive=False)
    report=digest_module._load_report(source_path); run_id=str(report["run_id"]); report_hash=str(report["_report_sha256"])
    registry=digest_module._report_source_registry(report)
    if not registry: raise ValueError("Research report contains no readable sources.")
    source=_sk_upsert_source("research",run_id,str(report.get("topic") or run_id),report_hash,{"kind":"research_report","run_id":run_id,"report":str(source_path)})
    current=_sk_current_version(source["source_id"])
    if current and str(current.get("source_sha256"))==report_hash:
        return {"ok":True,"already_digested":True,"shared_knowledge":True,"run_id":run_id,"source_id":source["source_id"],"active_version_id":current["version_id"]}
    alias=_sk_model_alias(memory_module) if getattr(backend,"provider","")=="online" else None
    started=_sk_begin_version(source=source,scope="research report",digest_mode="normal",provider="lmstudio" if getattr(backend,"provider","")=="local" else "gpt",model_alias=alias,model_id=str(backend.model_id),operation="digest_research",total_chunks=len(registry))
    try:
        batch=digest_module._call_report_digest_model(backend,report,registry); proposals=batch.get("memories") or []
        stored=_sk_store_research_proposals(version_id=started["version_id"],source_id=source["source_id"],proposals=proposals,resolver=digest_module._resolve_report_refs,registry=registry,run_id=run_id)
        activation=_sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=len(registry),model_calls=1,items=len(stored["inserted"]),stats={"passages":stored["passages"],"terms":stored["terms"]})
        archive_path=digest_module._report_dir(digest_module.RESEARCH_ARCHIVE_DIR)/source_path.name
        try:
            if archive_path.exists(): source_path.unlink(missing_ok=True)
            else: source_path.replace(archive_path)
        except Exception: archive_path=source_path
        return {"ok":True,"shared_knowledge":True,"run_id":run_id,"source_id":source["source_id"],"version_id":started["version_id"],"active":True,"archive":False,"knowledge_items_created":len(stored["inserted"]),"knowledge_ids":stored["inserted"],"evidence_passages":stored["passages"],"indexed_terms":stored["terms"],"archived_previous_versions":activation["archived_previous_versions"],"report_archive":str(archive_path)}
    except Exception as exc:
        _sk_fail_version(started["version_id"],started["run_id"],exc)
        raise


def _sk_persist_learned_memories(memory_module, report: dict, report_path=None) -> dict:
    proposals=report.get("memory_proposals") or []
    registry=memory_module._research_source_registry(report)
    run_id=str(report.get("run_id") or "learn")
    source_hash=_sk_hash(_sk_json({"run_id":run_id,"topic":report.get("topic"),"sources":sorted(registry)}))
    source=_sk_upsert_source("research",run_id,str(report.get("topic") or run_id),source_hash,{"kind":"research_run","run_id":run_id,"report_path":str(report_path or "")})
    current=_sk_current_version(source["source_id"])
    if current and str(current.get("source_sha256"))==source_hash:
        return {"ok":True,"shared_knowledge":True,"already_persisted":True,"knowledge_ids":[],"memory_ids":[],"inserted":0,"knowledge_created":0,"created":0,"knowledge_database_modified":False,"database_modified":False,"source_id":source["source_id"],"version_id":current["version_id"]}
    started=_sk_begin_version(source=source,scope="research learning run",digest_mode="research",provider="research-loop",model_alias=None,model_id=str(report.get("model") or "research-loop"),operation="learn_persist",total_chunks=len(registry))
    def resolver(raw, reg): return memory_module._resolve_learn_source_refs({"source_refs":raw},reg)
    try:
        stored=_sk_store_research_proposals(version_id=started["version_id"],source_id=source["source_id"],proposals=proposals,resolver=resolver,registry=registry,run_id=run_id)
        _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=len(registry),model_calls=0,items=len(stored["inserted"]),stats={"passages":stored["passages"],"terms":stored["terms"]})
        return {"ok":True,"shared_knowledge":True,"knowledge_ids":stored["inserted"],"memory_ids":[],"inserted":len(stored["inserted"]),"knowledge_created":len(stored["inserted"]),"created":0,"skipped_duplicates":[],"duplicates_skipped":0,"rejected":stored["rejected"],"source_id":source["source_id"],"version_id":started["version_id"],"knowledge_database_modified":bool(stored["inserted"]),"database_modified":False}
    except Exception as exc:
        _sk_fail_version(started["version_id"],started["run_id"],exc); raise


def _sk_status(module=None) -> dict:
    _sk_ensure_schema(module)
    with _sk_connect(module) as db:
        counts={
            "sources":int(db.execute("SELECT COUNT(*) FROM knowledge_sources").fetchone()[0]),
            "active_sources":int(db.execute("SELECT COUNT(*) FROM knowledge_sources WHERE active=1 AND retired=0").fetchone()[0]),
            "versions":int(db.execute("SELECT COUNT(*) FROM knowledge_versions").fetchone()[0]),
            "active_versions":int(db.execute("SELECT COUNT(*) FROM knowledge_versions WHERE active=1 AND archive=0 AND status='completed'").fetchone()[0]),
            "archived_versions":int(db.execute("SELECT COUNT(*) FROM knowledge_versions WHERE archive=1").fetchone()[0]),
            "items":int(db.execute("SELECT COUNT(*) FROM knowledge_items").fetchone()[0]),
            "passages":int(db.execute("SELECT COUNT(*) FROM knowledge_passages").fetchone()[0]),
            "terms":int(db.execute("SELECT COUNT(*) FROM knowledge_terms").fetchone()[0]),
            "explicit_terms":int(db.execute("SELECT COUNT(*) FROM knowledge_terms WHERE origin='explicit'").fetchone()[0]),
            "inferred_terms":int(db.execute("SELECT COUNT(*) FROM knowledge_terms WHERE origin='inferred'").fetchone()[0]),
        }
    return {"ok":True,"version":_SHARED_KNOWLEDGE_VERSION,"root":str(_sk_root_path()),"database":str(_sk_db_path()),"entity_neutral":True,"personal_memory_writes_from_books_research":False,"default_scope":"passage","default_semantics":"AND/co-occurrence in the same exact active shared evidence passage","inferred_is_authoritative":False,"deep_redigest_enabled":_DEEP_REDIGEST_ENABLED,"deep_redigest_version":_DEEP_REDIGEST_VERSION,"deep_default_provider":"lmstudio","deep_second_pass":"conditional-only","deep_resume":"per-chunk","contribution":dict(_SHARED_KNOWLEDGE_CONTRIBUTION),**counts}


def _sk_search_passages(query: str, scope: str="passage", include_inferred: bool=True, min_confidence: float=0.6, limit: int=20) -> dict:
    terms=_dei_query_terms(query); scope=str(scope or "passage").casefold()
    if scope not in {"passage","digest","document"}: scope="passage"
    if not terms: return {"ok":True,"query":query,"query_terms":[],"operator":"AND","scope":scope,"count":0,"results":[]}
    with _sk_connect() as db:
        placeholders=",".join("?" for _ in terms)
        origin_clause="" if include_inferred else " AND t.origin='explicit'"
        rows=db.execute(f"""SELECT t.*,p.version_id,p.source_id,p.source_ref,p.source_kind,p.chunk_id,p.chunk_ordinal,p.passage_ordinal,p.char_start,p.char_end,p.source_text_sha256,p.summary_text,p.metadata_json,v.version_number,v.model_id,v.model_alias,v.provider,s.title FROM knowledge_terms t JOIN knowledge_passages p ON p.passage_id=t.passage_id JOIN knowledge_versions v ON v.version_id=p.version_id JOIN knowledge_sources s ON s.source_id=p.source_id WHERE s.active=1 AND s.retired=0 AND v.active=1 AND v.archive=0 AND v.status='completed' AND t.confidence>=? {origin_clause} AND (t.term_norm IN ({placeholders}) OR t.canonical_norm IN ({placeholders}))""", [float(min_confidence),*terms,*terms]).fetchall()
    groups={}
    for r in rows:
        d=dict(r); matched=[q for q in terms if q in {str(d["term_norm"]),str(d["canonical_norm"])}]
        group_key=str(d["passage_id"] if scope=="passage" else d["version_id"] if scope=="digest" else d["source_id"])
        g=groups.setdefault(group_key,{"matched":set(),"passages":{}}); g["matched"].update(matched)
        p=g["passages"].setdefault(str(d["passage_id"]),{"passage_id":str(d["passage_id"]),"summary":str(d["summary_text"] or ""),"source_kind":str(d["source_kind"]),"source_name":str(d["title"]),"source_start":d["chunk_ordinal"],"source_end":d["chunk_ordinal"],"source_locator":{"source_id":str(d["source_id"]),"version_id":str(d["version_id"]),"source_ref":str(d["source_ref"]),"chunk_id":d["chunk_id"],"chunk_ordinal":d["chunk_ordinal"],"passage_ordinal":d["passage_ordinal"],"char_start":d["char_start"],"char_end":d["char_end"]},"source_text_sha256":str(d["source_text_sha256"]),"matches":[]})
        p["matches"].append({"query_term":matched[0] if matched else str(d["term_norm"]),"canonical":str(d["canonical_norm"]),"display":str(d["display_text"]),"entity_type":str(d["entity_type"]),"origin":str(d["origin"]),"confidence":float(d["confidence"]),"is_alias":bool(d["is_alias"])})
    results=[]
    for key,g in groups.items():
        if not all(t in g["matched"] for t in terms): continue
        passages=list(g["passages"].values())
        results.append({"scope_key":key,"scope":scope,"matched_terms":sorted(g["matched"]),"all_terms_matched":True,"explicit_match_rows":sum(1 for p in passages for m in p["matches"] if m["origin"]=="explicit"),"minimum_match_confidence":min((m["confidence"] for p in passages for m in p["matches"]),default=1.0),"passages":passages})
    results.sort(key=lambda x:(-x["minimum_match_confidence"],x["scope_key"]))
    return {"ok":True,"query":query,"query_terms":terms,"operator":"AND","scope":scope,"include_inferred":bool(include_inferred),"min_confidence":float(min_confidence),"count":len(results[:max(1,min(100,int(limit)))]),"results":results[:max(1,min(100,int(limit)))],"evidence_rule":"Shared summaries navigate; exact retained source locators/hashes remain authoritative. Inferred terms aid retrieval but are not authoritative evidence."}


def _sk_get_passage(passage_id: str, include_original: bool=False) -> dict:
    with _sk_connect() as db:
        row=db.execute("""SELECT p.*,v.active,v.archive,v.status,v.model_id,v.model_alias,v.provider,s.title,s.source_key FROM knowledge_passages p JOIN knowledge_versions v ON v.version_id=p.version_id JOIN knowledge_sources s ON s.source_id=p.source_id WHERE p.passage_id=?""",(passage_id,)).fetchone()
        if not row: return {"ok":False,"error":f"Shared knowledge passage not found: {passage_id}"}
        terms=[dict(x) for x in db.execute("SELECT term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias FROM knowledge_terms WHERE passage_id=? ORDER BY ordinal",(passage_id,)).fetchall()]
    result={"ok":True,"passage":dict(row),"terms":terms,"authoritative_summary":False}
    if include_original and row["source_kind"]=="book" and row["chunk_id"]:
        try:
            record=_dei_book_chunk_record(str(row["source_key"]),str(row["chunk_id"])); text=str(record.get("text") or "")
            start=int(row["char_start"] or 0); end=int(row["char_end"] or 0); original=text[start:end]
            result["original"]={"text":original,"sha256":_sk_hash(original),"matches_index_sha256":_sk_hash(original)==str(row["source_text_sha256"])}
        except Exception as exc: result["original"]={"error":f"{type(exc).__name__}: {exc}"}
    return result


def _sk_search_items(query: str, limit: int=20) -> dict:
    terms=_dei_query_terms(query); like_terms=[f"%{t}%" for t in terms]
    with _sk_connect() as db:
        rows=db.execute("""SELECT i.*,v.version_number,v.provider,v.model_alias,v.model_id,s.source_id,s.source_kind,s.source_key,s.title FROM knowledge_items i JOIN knowledge_versions v ON v.version_id=i.version_id JOIN knowledge_sources s ON s.source_id=v.source_id WHERE s.active=1 AND s.retired=0 AND v.active=1 AND v.archive=0 AND v.status='completed' ORDER BY i.importance DESC,i.confidence DESC LIMIT 1000""").fetchall()
    scored=[]
    for row in rows:
        d=dict(row); hay=f"{d['claim']} {d['details']} {d['domain']}".casefold(); matched=sum(1 for t in terms if t in hay)
        if terms and not matched: continue
        score=matched*2+float(d["importance"])+float(d["confidence"])
        scored.append((score,d))
    scored.sort(key=lambda x:x[0],reverse=True)
    return {"ok":True,"query":query,"count":len(scored[:max(1,min(100,int(limit)))]),"results":[{**d,"score":round(score,4)} for score,d in scored[:max(1,min(100,int(limit)))]]}


def _sk_get_item(item_id: str) -> dict:
    with _sk_connect() as db:
        row=db.execute("""SELECT i.*,v.version_number,v.status version_status,v.active version_active,v.archive version_archive,v.provider,v.model_alias,v.model_id,s.source_id,s.source_kind,s.source_key,s.title FROM knowledge_items i JOIN knowledge_versions v ON v.version_id=i.version_id JOIN knowledge_sources s ON s.source_id=v.source_id WHERE i.item_id=?""",(str(item_id),)).fetchone()
        if not row: return {"ok":False,"error":f"Shared knowledge item not found: {item_id}"}
        sources=[dict(x) for x in db.execute("SELECT ordinal,source_ref,locator_json,evidence_sha256,excerpt_sha256,excerpt FROM knowledge_item_sources WHERE item_id=? ORDER BY ordinal",(str(item_id),)).fetchall()]
    for source in sources:
        try: source["locator"]=json.loads(source.pop("locator_json") or "{}")
        except Exception: source["locator"]={}
    return {"ok":True,"item":dict(row),"sources":sources}


def _sk_read_provenance_ref(reference: str, include_original: bool = True) -> dict:
    """Open exactly one canonical KP/KI object without broad pyramid traversal.

    This is an identifier lookup, not semantic retrieval.  Python neither chooses a
    related object nor falls back to a prefix/nearest match.  KP reads reuse the
    existing retained-source reconstruction and hash comparison; KI reads expose the
    item's stored source witnesses unchanged.
    """
    requested = str(reference or "").strip()
    canonical = requested.upper()
    common = {
        "requested_ref": requested,
        "canonical_ref": canonical,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
        "semantic_selection_performed": False,
        "whole_pyramid_loaded": False,
    }
    if not canonical:
        return {"ok": False, "error": "reference is required.", "supported_prefixes": ["KP-", "KI-"], **common}
    if canonical.startswith("KP-"):
        result = _sk_get_passage(canonical, include_original=bool(include_original))
        if not result.get("ok"):
            return {**result, **common, "reference_kind": "shared_evidence_passage"}
        passage = dict(result.get("passage") or {})
        original = dict(result.get("original") or {})
        source_key = str(passage.get("source_key") or "")
        chunk_id = str(passage.get("chunk_id") or "")
        return {
            "ok": True,
            **common,
            "reference_kind": "shared_evidence_passage",
            "passage": passage,
            "terms": list(result.get("terms") or []),
            "original": original,
            "binding": {
                "passage_id": str(passage.get("passage_id") or canonical),
                "source_id": str(passage.get("source_id") or ""),
                "version_id": str(passage.get("version_id") or ""),
                "book_id": source_key if source_key.startswith("BK-") else None,
                "chunk_id": chunk_id or None,
                "chunk_ordinal": passage.get("chunk_ordinal"),
                "passage_ordinal": passage.get("passage_ordinal"),
                "char_start": passage.get("char_start"),
                "char_end": passage.get("char_end"),
                "stored_source_text_sha256": str(passage.get("source_text_sha256") or ""),
                "reconstructed_source_text_sha256": str(original.get("sha256") or "") or None,
                "reconstructed_hash_matches_stored": original.get("matches_index_sha256"),
            },
            "authority": "The reconstructed retained source span is authoritative when present and hash-matched; summary_text is derived navigation, not source fact.",
        }
    if canonical.startswith("KI-"):
        result = _sk_get_item(canonical)
        if not result.get("ok"):
            return {**result, **common, "reference_kind": "shared_knowledge_item"}
        item = dict(result.get("item") or {})
        sources = list(result.get("sources") or [])
        return {
            "ok": True,
            **common,
            "reference_kind": "shared_knowledge_item",
            "item": item,
            "sources": sources,
            "binding": {
                "item_id": str(item.get("item_id") or canonical),
                "source_id": str(item.get("source_id") or ""),
                "version_id": str(item.get("version_id") or ""),
                "book_id": str(item.get("source_key") or "") if str(item.get("source_key") or "").startswith("BK-") else None,
                "source_witness_count": len(sources),
                "source_refs": _citation_unique(source.get("source_ref") for source in sources),
                "chunk_ids": _citation_unique((source.get("locator") or {}).get("chunk_id") for source in sources),
            },
            "authority": "The KI claim is derived interpretation/navigation. Its retained source witnesses remain the evidentiary authority.",
        }
    return {
        "ok": False,
        "error": "Unsupported shared provenance reference. Use one exact KP- or KI- identifier.",
        "supported_prefixes": ["KP-", "KI-"],
        **common,
    }



# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:shared-chat-bridge rev=1
# Shared knowledge -> normal chat bridge (7.4.25.6)
# ---------------------------------------------------------------------------
_SHARED_CHAT_BRIDGE_VERSION = "1.2-deduplicated-continuation-packet"
_SHARED_CHAT_BRIDGE_LIMITS = {
    "low": {"items": 3, "passages": 3, "max_chars": 9000, "source_excerpt_chars": 1100, "source_continuation_chars": 450},
    "mid": {"items": 5, "passages": 5, "max_chars": 17000, "source_excerpt_chars": 1500, "source_continuation_chars": 650},
    "high": {"items": 8, "passages": 8, "max_chars": 28000, "source_excerpt_chars": 1900, "source_continuation_chars": 800},
}
_SHARED_CHAT_BRIDGE_WEAK_TERMS = {
    "answer", "asked", "asking", "book", "books", "question", "questions", "message", "messages",
    "say", "says", "said", "send", "sends", "sent", "tell", "tells", "told", "information",
}


def _sk_chat_bridge_config(level: str) -> dict:
    return dict(_SHARED_CHAT_BRIDGE_LIMITS.get(str(level or "mid").casefold(), _SHARED_CHAT_BRIDGE_LIMITS["mid"]))


def _sk_chat_bridge_term_stats(query: str) -> list[dict]:
    terms = _dei_query_terms(query)
    if not terms:
        return []
    output = []
    with _sk_connect() as db:
        for ordinal, term in enumerate(terms):
            row = db.execute(
                """SELECT COUNT(DISTINCT t.passage_id) AS passage_count,
                          SUM(CASE WHEN t.origin='explicit' THEN 1 ELSE 0 END) AS explicit_rows,
                          SUM(CASE WHEN t.origin='inferred' THEN 1 ELSE 0 END) AS inferred_rows
                   FROM knowledge_terms t
                   JOIN knowledge_passages p ON p.passage_id=t.passage_id
                   JOIN knowledge_versions v ON v.version_id=p.version_id
                   JOIN knowledge_sources s ON s.source_id=p.source_id
                   WHERE s.active=1 AND s.retired=0 AND v.active=1 AND v.archive=0 AND v.status='completed'
                     AND (t.term_norm=? OR t.canonical_norm=?)""",
                (term, term),
            ).fetchone()
            count = int((row["passage_count"] if row else 0) or 0)
            output.append({
                "term": term,
                "query_ordinal": ordinal,
                "passage_count": count,
                "explicit_rows": int((row["explicit_rows"] if row else 0) or 0),
                "inferred_rows": int((row["inferred_rows"] if row else 0) or 0),
                "weak": term in _SHARED_CHAT_BRIDGE_WEAK_TERMS,
            })
    return output


def _sk_chat_bridge_evidence(query: str, *, limit: int) -> dict:
    stats = _sk_chat_bridge_term_stats(query)
    viable = [row for row in stats if row["passage_count"] > 0]
    strong = [row for row in viable if not row["weak"]]
    pool = strong or viable
    # Rarer indexed terms are more discriminative; query order breaks ties deterministically.
    ranked = sorted(pool, key=lambda row: (int(row["passage_count"]), int(row["query_ordinal"])))[:5]
    terms = [row["term"] for row in ranked]
    attempts = []
    merged: dict[str, dict] = {}
    # Prefer 3-term exact co-occurrence, then pairs, then a single indexed anchor.
    import itertools
    sizes = []
    if len(terms) >= 3: sizes.append(3)
    if len(terms) >= 2: sizes.append(2)
    if len(terms) >= 1: sizes.append(1)
    for size in sizes:
        combos = list(itertools.combinations(terms, size))[:10]
        for combo in combos:
            q = " ".join(combo)
            result = _sk_search_passages(q, "passage", True, 0.6, max(limit * 2, 6))
            attempts.append({"terms": list(combo), "count": int(result.get("count", 0) or 0)})
            for row in result.get("results") or []:
                for passage in row.get("passages") or []:
                    pid = str(passage.get("passage_id") or "")
                    if not pid:
                        continue
                    score = (
                        size * 100.0
                        + float(row.get("explicit_match_rows", 0) or 0) * 5.0
                        + float(row.get("minimum_match_confidence", 0.0) or 0.0) * 10.0
                    )
                    current = merged.get(pid)
                    if current is None or score > current["score"]:
                        merged[pid] = {"score": score, "combo": list(combo), "result": row, "passage": passage}
        if len(merged) >= max(2, limit):
            break
    selected = sorted(merged.values(), key=lambda row: (-row["score"], str(row["passage"].get("passage_id") or "")))[:limit]
    return {
        "term_stats": stats,
        "selected_anchor_terms": terms,
        "attempts": attempts,
        "results": selected,
    }


def _sk_chat_bridge_item_candidates(query: str, *, limit: int) -> list[dict]:
    primary = _sk_search_items(query, max(limit * 4, 12)).get("results") or []
    # A second pass using only terms that actually exist in active evidence avoids
    # generic question words diluting item ranking without asking a model to rewrite the query.
    stats = _sk_chat_bridge_term_stats(query)
    indexed = [row["term"] for row in stats if row["passage_count"] > 0 and not row["weak"]]
    secondary = _sk_search_items(" ".join(indexed[:6]), max(limit * 4, 12)).get("results") if indexed else []
    by_id: dict[str, dict] = {}
    for row in [*primary, *(secondary or [])]:
        iid = str(row.get("item_id") or "")
        if not iid:
            continue
        previous = by_id.get(iid)
        if previous is None or float(row.get("score", 0) or 0) > float(previous.get("score", 0) or 0):
            by_id[iid] = row
    return sorted(
        by_id.values(),
        key=lambda row: (-float(row.get("score", 0) or 0), -float(row.get("confidence", 0) or 0), -float(row.get("importance", 0) or 0), str(row.get("item_id") or "")),
    )[:limit]


def _sk_focus_retained_excerpt(excerpt: str, query: str, limit: int, continuation: int = 0) -> dict:
    """Return an exact contiguous source window biased toward the user's query.

    The stored retained excerpt remains authoritative and unchanged.  ``limit`` is
    the normal focused-window budget.  ``continuation`` is optional *recovered*
    packet budget (for example from deduplicating identical retained excerpts) and
    is spent only forward from the chosen exact window.  This helps preserve an
    answer that immediately follows the queried event without inventing semantic
    synonyms or rewriting source text.
    """
    raw = str(excerpt or "")
    cap = max(200, int(limit or 0))
    continuation_cap = max(0, int(continuation or 0))
    if not raw:
        return {"text": "", "start": 0, "end": 0, "base_end": 0, "continuation_chars": 0, "truncated": False, "matched_terms": []}
    terms = [t for t in _dei_query_terms(query) if t and t not in _SHARED_CHAT_BRIDGE_WEAK_TERMS]
    folded = raw.casefold()
    if len(raw) <= cap:
        matched = [t for t in terms if t.casefold() in folded]
        return {"text": raw, "start": 0, "end": len(raw), "base_end": len(raw), "continuation_chars": 0, "truncated": False, "matched_terms": matched}

    candidates = {0, max(0, len(raw) - cap)}
    for term in terms:
        needle = term.casefold()
        start_at = 0
        seen = 0
        while needle and seen < 8:
            pos = folded.find(needle, start_at)
            if pos < 0:
                break
            candidates.add(max(0, min(len(raw) - cap, pos - cap // 3)))
            start_at = pos + max(1, len(needle))
            seen += 1

    best = None
    for start in sorted(candidates):
        base_end = min(len(raw), start + cap)
        window_folded = folded[start:base_end]
        matched = [t for t in terms if t.casefold() in window_folded]
        occurrences = sum(min(3, window_folded.count(t.casefold())) for t in matched)
        # Distinct query concepts dominate; occurrence count only breaks ties.
        score = len(matched) * 100 + occurrences
        candidate = (score, -start, start, base_end, matched)
        if best is None or candidate > best:
            best = candidate
    _, _, start, base_end, _ = best
    end = min(len(raw), base_end + continuation_cap) if base_end < len(raw) else base_end
    final_folded = folded[start:end]
    matched = [t for t in terms if t.casefold() in final_folded]
    return {
        "text": raw[start:end],
        "start": int(start),
        "end": int(end),
        "base_end": int(base_end),
        "continuation_chars": int(max(0, end - base_end)),
        "truncated": bool(start > 0 or end < len(raw)),
        "matched_terms": matched,
    }


def _sk_group_source_records(records: list[dict]) -> list[dict]:
    """Deduplicate byte-identical retained excerpts while preserving KI handles.

    Multiple knowledge items often point to the same authoritative chunk excerpt.
    Repeating that text consumes bounded chat context without adding evidence.  The
    grouped record keeps every KI/handle visible while packing the exact source once.
    """
    groups: dict[tuple[str, str], dict] = {}
    order: list[tuple[str, str]] = []
    for record in records or []:
        excerpt = str(record.get("excerpt") or "")
        excerpt_hash = str(record.get("excerpt_sha256") or _sk_hash(excerpt))
        source_ref = str(record.get("source_ref") or "")
        key = (source_ref, excerpt_hash)
        if key not in groups:
            groups[key] = {
                "source_ref": source_ref,
                "excerpt": excerpt,
                "excerpt_sha256": excerpt_hash,
                "handles": [],
                "item_ids": [],
            }
            order.append(key)
        group = groups[key]
        handle = str(record.get("handle") or "")
        item_id = str(record.get("item_id") or "")
        if handle and handle not in group["handles"]:
            group["handles"].append(handle)
        if item_id and item_id not in group["item_ids"]:
            group["item_ids"].append(item_id)
    return [groups[key] for key in order]


def _sk_chat_bridge_context(module, query: str, *, level: str = "mid") -> tuple[str, dict]:
    cfg = _sk_chat_bridge_config(level)
    trace = {
        "version": _SHARED_CHAT_BRIDGE_VERSION,
        "enabled": True,
        "ok": True,
        "level": str(level or "mid").casefold(),
        "query": str(query or ""),
        "model_calls": 0,
        "authority": "retained original source text > exact source locator/hash > digest knowledge item/summary",
        "item_ids": [],
        "passage_ids": [],
        "citation_entries": [],
        "exact_original_passages": 0,
        "direct_source_excerpts": 0,
        "source_excerpt_windows": [],
        "errors": [],
    }
    try:
        status = _sk_status(module)
    except Exception as exc:
        trace.update({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return "[shared knowledge store unavailable]", trace
    if int(status.get("active_sources", 0) or 0) <= 0:
        trace.update({"ok": True, "reason": "no active shared knowledge sources"})
        return "[no active shared knowledge sources]", trace

    # 7.4.25.10.6+: the historical shortlist is lexical and can crowd out a
    # semantically relevant paraphrased KI before its validated KPL can be
    # traversed.  Add a zero-model KPL-backed candidate pass and reserve one
    # shortlist slot when a linked KI has meaningful overlap with the question.
    baseline_items = _sk_chat_bridge_item_candidates(query, limit=int(cfg["items"]))
    linked_item_provider = globals().get("_elk_bridge_item_candidates")
    linked_item_rows = linked_item_provider(query, limit=max(2, int(cfg["items"]))) if callable(linked_item_provider) else []
    by_item = {str(row.get("item_id") or ""): row for row in baseline_items if str(row.get("item_id") or "")}
    for row in linked_item_rows:
        iid = str(row.get("item_id") or "")
        if not iid:
            continue
        previous = by_item.get(iid)
        if previous is None or float(row.get("bridge_candidate_score", row.get("score", 0.0)) or 0.0) > float(previous.get("bridge_candidate_score", previous.get("score", 0.0)) or 0.0):
            by_item[iid] = row
    items = sorted(
        by_item.values(),
        key=lambda row: (-float(row.get("bridge_candidate_score", row.get("score", 0.0)) or 0.0),
                         -float(row.get("confidence", 0.0) or 0.0),
                         -float(row.get("importance", 0.0) or 0.0),
                         str(row.get("item_id") or "")),
    )[:int(cfg["items"])]
    # Guarantee one strong KPL-backed candidate is not lost solely to the legacy
    # shortlist size.  This is navigation only; the linked KP remains authority.
    if linked_item_rows and not any(bool(row.get("kpl_bridge_candidate")) for row in items):
        strongest = linked_item_rows[0]
        if int(cfg["items"]) > 0:
            if len(items) >= int(cfg["items"]):
                items[-1] = strongest
            else:
                items.append(strongest)
    # De-duplicate after the reserved-slot substitution.
    dedup = {}
    for row in items:
        iid = str(row.get("item_id") or "")
        if iid and iid not in dedup:
            dedup[iid] = row
    items = list(dedup.values())[:int(cfg["items"])]

    evidence = _sk_chat_bridge_evidence(query, limit=int(cfg["passages"]))
    # 7.4.25.10.5+: once a KI is selected as navigation, follow only validated
    # append-only KI<->KP witness links back to exact primary evidence.  This does
    # not make the KPL authoritative; it lets the authoritative KP participate in
    # the same bounded passage packet even when the user's wording is a paraphrase.
    linked_provider = globals().get("_elk_bridge_linked_passages")
    linked_rows = linked_provider(items, limit=int(cfg["passages"])) if callable(linked_provider) else []
    reserved_linked_passage_ids = []
    if linked_rows:
        merged = {}
        for selected in [*(evidence.get("results") or []), *linked_rows]:
            passage = selected.get("passage") or {}
            pid = str(passage.get("passage_id") or "")
            if not pid:
                continue
            current = merged.get(pid)
            if current is None or float(selected.get("score", 0.0) or 0.0) > float(current.get("score", 0.0) or 0.0):
                merged[pid] = selected
        passage_cap = max(1, int(cfg["passages"]))
        ordered = sorted(merged.values(), key=lambda row: (-float(row.get("score",0.0) or 0.0), str((row.get("passage") or {}).get("passage_id") or "")))
        selected_rows = ordered[:passage_cap]
        # 7.4.25.10.7: exact 3-term lexical hits score 300+ while validated
        # KPL navigation was intentionally lower (~240) so it could not dominate.
        # That allowed every linked authoritative KP to be evicted from a full
        # five-passage packet. Reserve at most one passage slot instead of
        # inflating KPL scores: bounded diversity, not authority inversion.
        linked_ids = {str((row.get("passage") or {}).get("passage_id") or "") for row in linked_rows}
        selected_ids = {str((row.get("passage") or {}).get("passage_id") or "") for row in selected_rows}
        if linked_ids and not (linked_ids & selected_ids):
            strongest_linked = sorted(
                linked_rows,
                key=lambda row: (-float(row.get("link_confidence",0.0) or 0.0),
                                 -float(row.get("score",0.0) or 0.0),
                                 str((row.get("passage") or {}).get("passage_id") or "")),
            )[0]
            reserve_pid = str((strongest_linked.get("passage") or {}).get("passage_id") or "")
            if reserve_pid:
                if len(selected_rows) >= passage_cap:
                    selected_rows[-1] = strongest_linked
                else:
                    selected_rows.append(strongest_linked)
                dedup_rows = {}
                for row in selected_rows:
                    pid = str((row.get("passage") or {}).get("passage_id") or "")
                    if pid and pid not in dedup_rows:
                        dedup_rows[pid] = row
                selected_rows = list(dedup_rows.values())[:passage_cap]
                reserved_linked_passage_ids.append(reserve_pid)
        # 7.4.25.10.8: reservation must survive not only passage selection but also
        # final character-budget truncation.  Serialize a reserved linked primary
        # passage first among PRIMARY passages.  This changes packet order only;
        # ranking, membership, authority, and the one-slot reservation bound stay
        # unchanged.
        if reserved_linked_passage_ids:
            reserved_set = set(reserved_linked_passage_ids)
            selected_rows = sorted(
                selected_rows,
                key=lambda row: (
                    0 if str((row.get("passage") or {}).get("passage_id") or "") in reserved_set else 1,
                    -float(row.get("score", 0.0) or 0.0),
                    str((row.get("passage") or {}).get("passage_id") or ""),
                ),
            )
        evidence["results"] = selected_rows
    trace["query_term_stats"] = evidence["term_stats"]
    trace["evidence_anchor_terms"] = evidence["selected_anchor_terms"]
    trace["evidence_attempts"] = evidence["attempts"][:12]
    trace["item_ids"] = [str(row.get("item_id") or "") for row in items]
    trace["evidence_linked_item_ids"] = [str(row.get("item_id") or "") for row in linked_item_rows if str(row.get("item_id") or "")]
    trace["evidence_linked_passage_ids"] = [str((row.get("passage") or {}).get("passage_id") or "") for row in linked_rows if str((row.get("passage") or {}).get("passage_id") or "")]
    trace["evidence_link_reserved_passage_ids"] = list(reserved_linked_passage_ids)

    lines = [
        "SHARED KNOWLEDGE CHAT BRIDGE — ACTIVE BOOK/RESEARCH KNOWLEDGE, READ-ONLY",
        f"Bridge version: {_SHARED_CHAT_BRIDGE_VERSION} | retrieval level: {trace['level']} | model calls for retrieval: 0",
        "AUTHORITY: retained original source text is authoritative. Digest claims and summaries are navigation/interpretation aids and must not overrule exact source evidence.",
        "STATE: only active, non-archived, completed shared-knowledge versions are eligible. Personal identity/memory is not read by this bridge.",
        f"User query: {str(query or '').strip()}",
    ]

    item_source_records = []
    if items:
        lines.append("\nACTIVE SHARED KNOWLEDGE ITEMS — NAVIGATION, NOT PRIMARY EVIDENCE")
        # Emit every selected KI's compact navigation/provenance first.  Long source
        # excerpts are packed afterward so an early item's text cannot starve a later
        # selected item from the bounded context packet.
        for index, item in enumerate(items, 1):
            iid = str(item.get("item_id") or "")
            cite_handle = f"K{index}"
            item_citation = {
                "handle": cite_handle, "kind": "knowledge_item", "role": "SUPPORTING",
                "contribution": (str(item.get("claim") or "").strip() or "active shared knowledge item")[:300],
                "knowledge_ids": [iid] if iid else [], "passage_ids": [],
                "source_ids": _citation_unique([item.get("source_id")]),
                "versions": _citation_unique([item.get("version_id")]),
                "book_ids": _citation_unique([item.get("source_key")]) if str(item.get("source_key") or "").startswith("BK-") else [],
                "chunk_ids": [],
            }
            lines.append(
                f"[{index}] {iid} | cite=[[CITE:{cite_handle}]] | title={item.get('title')} | source={item.get('source_id')} | version={item.get('version_id')} v{item.get('version_number')} | "
                f"provider={item.get('provider')}/{item.get('model_alias') or item.get('model_id')} | interpretation={item.get('interpretation')} | confidence={item.get('confidence')} | score={item.get('score')}"
            )
            lines.append(f"Claim: {str(item.get('claim') or '').strip()}")
            details = " ".join(str(item.get("details") or "").split())
            if details:
                lines.append("Details: " + details[:700])
            try:
                full = _sk_get_item(iid)
                sources = full.get("sources") or []
                if sources:
                    src = sources[0]
                    locator = src.get("locator") or {}
                    excerpt = str(src.get("excerpt") or "")
                    chunk_value = locator.get("chunk_id") or locator.get("snapshot_id")
                    if chunk_value:
                        item_citation["chunk_ids"] = _citation_unique([chunk_value])
                    trace["direct_source_excerpts"] += 1 if excerpt else 0
                    lines.append(
                        "Direct source: "
                        f"ref={src.get('source_ref')} | chunk={locator.get('chunk_id') or locator.get('snapshot_id') or '[n/a]'} | "
                        f"ordinal={locator.get('ordinal') or locator.get('chunk_ordinal') or '[n/a]'} | evidence_sha256={src.get('evidence_sha256')} | excerpt_sha256={src.get('excerpt_sha256')}"
                    )
                    if excerpt:
                        item_source_records.append({
                            "index": index, "handle": cite_handle, "item_id": iid,
                            "excerpt": excerpt, "excerpt_sha256": src.get("excerpt_sha256"),
                            "source_ref": src.get("source_ref"),
                        })
            except Exception as exc:
                trace["errors"].append(f"item {iid}: {type(exc).__name__}: {exc}")
            trace["citation_entries"].append(item_citation)

        if item_source_records:
            lines.append("\nDIRECT RETAINED SOURCE WINDOWS — EXACT SUPPORTING TEXT")
            grouped_sources = _sk_group_source_records(item_source_records)
            duplicate_count = max(0, len(item_source_records) - len(grouped_sources))
            recovered_chars = duplicate_count * int(cfg["source_excerpt_chars"])
            continuation_each = 0
            if grouped_sources and recovered_chars > 0:
                continuation_each = min(
                    int(cfg.get("source_continuation_chars", 0) or 0),
                    recovered_chars // len(grouped_sources),
                )
            trace["source_excerpt_packing"] = {
                "selected_item_source_records": len(item_source_records),
                "unique_source_windows": len(grouped_sources),
                "deduplicated_windows": duplicate_count,
                "recovered_chars": int(recovered_chars),
                "continuation_chars_per_unique_window": int(continuation_each),
            }
            for record in grouped_sources:
                focused = _sk_focus_retained_excerpt(
                    record["excerpt"], query, int(cfg["source_excerpt_chars"]), int(continuation_each)
                )
                window_text = str(focused.get("text") or "")
                window_sha = _sk_hash(window_text) if window_text else None
                handles = list(record.get("handles") or [])
                item_ids = list(record.get("item_ids") or [])
                trace["source_excerpt_windows"].append({
                    "handle": handles[0] if handles else None,
                    "handles": handles,
                    "item_id": item_ids[0] if item_ids else None,
                    "item_ids": item_ids,
                    "start": int(focused.get("start", 0) or 0),
                    "base_end": int(focused.get("base_end", focused.get("end", 0)) or 0),
                    "end": int(focused.get("end", 0) or 0),
                    "continuation_chars": int(focused.get("continuation_chars", 0) or 0),
                    "matched_terms": list(focused.get("matched_terms") or []),
                    "window_sha256": window_sha,
                    "stored_excerpt_sha256": record.get("excerpt_sha256"),
                    "source_ref": record.get("source_ref"),
                })
                handle_label = ",".join(handles) if handles else "K?"
                item_label = ",".join(item_ids) if item_ids else "[n/a]"
                lines.append(
                    f"[{handle_label} source window] items={item_label} | source_ref={record.get('source_ref')} | "
                    f"excerpt_chars={focused.get('start')}..{focused.get('end')} | base_end={focused.get('base_end')} | "
                    f"continuation={focused.get('continuation_chars')} | window_sha256={window_sha} | stored_excerpt_sha256={record.get('excerpt_sha256')}"
                )
                if len(handles) > 1:
                    lines.append(f"Deduplicated exact source: one retained excerpt supports handles {handle_label}; canonical KI IDs remain separate above.")
                if window_text:
                    lines.append("Exact retained source window:")
                    lines.append(_rbi_exact_evidence_block(
                        kind="source_window", handle=handle_label, source_ref=str(record.get("source_ref") or ""),
                        sha256=str(window_sha or ""), text=window_text,
                    ))
                    if focused.get("truncated"):
                        lines.append("[exact contiguous window selected from a longer retained source excerpt; canonical stored excerpt remains unchanged]")

    if evidence["results"]:
        lines.append("\nPRECISE EVIDENCE PASSAGES — PRIMARY SOURCE TARGETS")
        for index, selected in enumerate(evidence["results"], 1):
            passage = selected["passage"]
            pid = str(passage.get("passage_id") or "")
            cite_handle = f"P{index}"
            trace["passage_ids"].append(pid)
            locator = passage.get("source_locator") or {}
            trace["citation_entries"].append({
                "handle": cite_handle, "kind": "evidence_passage", "role": "PRIMARY",
                "contribution": ("exact retained source passage: " + " ".join(str(passage.get("summary") or "").split()))[:300],
                "knowledge_ids": [], "passage_ids": [pid] if pid else [],
                "source_ids": _citation_unique([locator.get("source_id")]),
                "versions": _citation_unique([locator.get("version_id")]),
                "book_ids": _citation_unique([locator.get("book_id")]) if str(locator.get("book_id") or "").startswith("BK-") else [],
                "chunk_ids": _citation_unique([locator.get("chunk_id")]),
            })
            lines.append(
                f"[P{index}] {pid} | cite=[[CITE:{cite_handle}]] | matched={','.join(selected['combo'])} | title={passage.get('source_name')} | "
                f"source_id={locator.get('source_id')} | version={locator.get('version_id')} | source_ref={locator.get('source_ref')}"
            )
            lines.append(
                f"Locator: chunk={locator.get('chunk_id') or '[n/a]'} | chunk_ordinal={locator.get('chunk_ordinal')} | passage_ordinal={locator.get('passage_ordinal')} | "
                f"chars={locator.get('char_start')}..{locator.get('char_end')} | page=unavailable/not-stable-for-EPUB | source_text_sha256={passage.get('source_text_sha256')}"
            )
            summary = " ".join(str(passage.get("summary") or "").split())
            if summary:
                lines.append("Digest navigation summary (non-authoritative): " + summary[:900])
            try:
                full = _sk_get_passage(pid, include_original=True)
                original = full.get("original") or {}
                exact = str(original.get("text") or "")
                verified = bool(original.get("matches_index_sha256"))
                if exact:
                    if verified:
                        trace["exact_original_passages"] += 1
                    lines.append(f"Original retained source span (hash_verified={verified}):")
                    lines.append(_rbi_exact_evidence_block(
                        kind="primary_passage", handle=cite_handle, source_ref=str(locator.get("source_ref") or ""),
                        sha256=str(passage.get("source_text_sha256") or ""), text=exact,
                    ))
                elif original.get("error"):
                    lines.append("Original span resolution error: " + str(original.get("error"))[:500])
            except Exception as exc:
                trace["errors"].append(f"passage {pid}: {type(exc).__name__}: {exc}")
    else:
        lines.append("\nPRECISE EVIDENCE PASSAGES — none selected for this query. Do not infer that the knowledge is absent; report insufficient retrieved evidence if the navigation items do not directly support the answer.")

    # 7.4.38.2: source bytes are authoritative and must survive packet assembly
    # byte-for-byte.  Do NOT collapse blank lines across the shared-evidence packet.
    # Exact evidence regions are explicitly marked and the context router/compiler
    # treat those regions as atomic evidence units instead.
    raw = "\n".join(lines).strip()
    trace["planned_context_chars"] = len(raw)
    max_chars = int(cfg["max_chars"])
    if len(raw) > max_chars:
        raw = raw[:max_chars] + "\n[shared knowledge chat bridge truncated to retrieval-level context budget]"
        trace["truncated"] = True
    else:
        trace["truncated"] = False

    # 7.4.38.1: citation availability is a property of the final packet, not of
    # pre-truncation selection.  Keep the full selection trace for diagnostics,
    # but expose only handles that actually survive into model-visible context.
    visible_handles = _citation_unique(
        str(match).upper()
        for match in re.findall(r"\[\[CITE:([KP]\d+)\]\]", raw, flags=re.IGNORECASE)
    )
    trace["visible_citation_handles"] = visible_handles
    visible_set = set(visible_handles)
    trace["visible_item_ids"] = [
        str(iid) for entry in trace.get("citation_entries") or []
        if str(entry.get("handle") or "").upper() in visible_set
        for iid in (entry.get("knowledge_ids") or []) if str(iid)
    ]
    trace["visible_passage_ids"] = [
        str(pid) for entry in trace.get("citation_entries") or []
        if str(entry.get("handle") or "").upper() in visible_set
        for pid in (entry.get("passage_ids") or []) if str(pid)
    ]
    for window in trace.get("source_excerpt_windows") or []:
        handles = [str(x).upper() for x in (window.get("handles") or []) if str(x)]
        label = ",".join(handles) if handles else str(window.get("handle") or "").upper()
        window["packet_header_visible"] = bool(label and f"[{label} source window]" in raw)

    trace["context_chars"] = len(raw)
    trace["ok"] = True
    return raw, trace


def _sk_chat_bridge_preview(module, query: str, level: str = "mid") -> dict:
    context, trace = _sk_chat_bridge_context(module, query, level=level)
    return {"ok": bool(trace.get("ok")), "trace": trace, "context": context}


def shared_knowledge_chat_bridge_self_test(module) -> dict:
    original = os.getenv(_SHARED_KNOWLEDGE_DIR_ENV)
    checks = {}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-shared-chat-bridge-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV] = folder
            _sk_ensure_schema(module)
            source = _sk_upsert_source("research", "TEST-ROMEO", "Romeo Test Source", "a" * 64, {"kind": "test"})
            started = _sk_begin_version(source=source, scope="test", digest_mode="deep", provider="python", model_alias=None, model_id="test", operation="test", total_chunks=1)
            exact = "Balthasar tells Romeo that Juliet is dead and Romeo resolves to return to Verona."
            proposal = {"kind":"fact","claim":"Balthasar tells Romeo that Juliet is dead.","details":"He brings Romeo the report of Juliet's apparent death.","interpretation":"direct","domain":"plot","importance":1.0,"confidence":1.0}
            with _sk_connect() as db:
                iid = _sk_store_item(db, version_id=started["version_id"], proposal=proposal, resolved_sources=[{"ref":"test:romeo:1","excerpt":exact,"snapshot_id":"S1","text_sha256":_sk_hash(exact)}], source_kind="research")
                pid = _sk_id("KP", {"test":"bridge"}, 20)
                db.execute("INSERT INTO knowledge_passages(passage_id,version_id,source_id,source_ref,source_kind,chunk_id,chunk_ordinal,passage_ordinal,char_start,char_end,source_text_sha256,summary_text,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                           (pid, started["version_id"], source["source_id"], "test:romeo:1", "research", None, 1, 1, 0, len(exact), _sk_hash(exact), proposal["claim"], _sk_json({"test":True}), _sk_now()))
                for ordinal, term in enumerate(_dei_build_terms(exact, [{"text":"Balthasar","confidence":0.95,"entity_type":"person_or_character","reason":"test"}])):
                    db.execute("INSERT OR REPLACE INTO knowledge_terms(passage_id,term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,ordinal) VALUES(?,?,?,?,?,?,?,?,?)",
                               (pid, term["term_norm"], term["canonical_norm"], term["display_text"], term["entity_type"], term["origin"], float(term["confidence"]), 1 if term.get("is_alias") else 0, int(term["ordinal"])))
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)", (started["version_id"], "C1", 1, _sk_hash(exact), "completed", _sk_now()))
            _sk_finalize_version(source["source_id"], started["version_id"], started["run_id"], processed=1, model_calls=0, items=1)
            context, trace = _sk_chat_bridge_context(module, "Who sends Romeo the message about Juliet's death?", level="mid")
            late_excerpt = ("Prefatory filler. " * 180) + "Prince Escalus banishes Romeo from Verona for killing Tybalt."
            focused_late = _sk_focus_retained_excerpt(late_excerpt, "What punishment does Prince Escalus give Romeo for killing Tybalt?", 500)
            continuation_excerpt = (
                "Prince Escalus hears that Romeo killed Tybalt. " + ("testimony " * 34) +
                "PRINCE. And for that offence immediately we do exile him hence."
            )
            focused_continuation = _sk_focus_retained_excerpt(
                continuation_excerpt, "What punishment does Prince Escalus give Romeo for killing Tybalt?", 260, 500
            )
            grouped_test = _sk_group_source_records([
                {"handle":"K1","item_id":"KI-1","source_ref":"book:test:C1","excerpt":"same","excerpt_sha256":"abc"},
                {"handle":"K2","item_id":"KI-2","source_ref":"book:test:C1","excerpt":"same","excerpt_sha256":"abc"},
                {"handle":"K3","item_id":"KI-3","source_ref":"book:test:C2","excerpt":"other","excerpt_sha256":"def"},
            ])
            checks = {
                "bridge_returns_context": bool(context.strip()),
                "zero_model_calls": int(trace.get("model_calls", -1)) == 0,
                "active_item_selected": iid in (trace.get("item_ids") or []),
                "passage_selected": pid in (trace.get("passage_ids") or []),
                "contains_answer_navigation": "Balthasar" in context and "Romeo" in context and "Juliet" in context,
                "contains_version_provenance": started["version_id"] in context,
                "contains_source_hash": _sk_hash(exact) in context,
                "citation_handles_exposed": "cite=[[CITE:K1]]" in context and "cite=[[CITE:P1]]" in context,
                "citation_entries_traced": any(row.get("handle") == "K1" for row in trace.get("citation_entries") or []) and any(row.get("handle") == "P1" for row in trace.get("citation_entries") or []),
                "visible_citation_handles_traced": "K1" in (trace.get("visible_citation_handles") or []) and "P1" in (trace.get("visible_citation_handles") or []),
                "source_window_source_ref_traced": all(str(row.get("source_ref") or "") for row in (trace.get("source_excerpt_windows") or [])),
                "shared_only": "Personal identity/memory is not read by this bridge" in context,
                "query_focused_window_keeps_late_evidence": "Prince Escalus banishes Romeo" in str(focused_late.get("text") or ""),
                "query_focused_window_is_not_blind_prefix": int(focused_late.get("start", 0) or 0) > 0,
                "forward_continuation_preserves_following_verdict": "exile him hence" in str(focused_continuation.get("text") or "").casefold(),
                "forward_continuation_is_exact_source": str(focused_continuation.get("text") or "") in continuation_excerpt,
                "duplicate_source_records_grouped": len(grouped_test) == 2 and grouped_test[0].get("handles") == ["K1","K2"],
                "source_window_trace_present": isinstance(trace.get("source_excerpt_windows"), list),
            }
            return {"ok": all(checks.values()), "checks": checks, "trace": trace, "version": _SHARED_CHAT_BRIDGE_VERSION}
    finally:
        if original is None:
            os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV, None)
        else:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV] = original


def _install_shared_knowledge_chat_bridge(module) -> None:
    if getattr(module, "_SHARED_KNOWLEDGE_CHAT_BRIDGE_INSTALLED", False):
        return
    module.SHARED_KNOWLEDGE_CHAT_BRIDGE_VERSION = _SHARED_CHAT_BRIDGE_VERSION
    module.get_shared_knowledge_chat_context = lambda query, level="mid": _sk_chat_bridge_preview(module, query, level)
    module.shared_knowledge_chat_bridge_self_test = lambda: shared_knowledge_chat_bridge_self_test(module)
    # Keep the command diagnostic-only. Normal chat mounting happens inside the
    # domain-aware context builder before context-group routing/token selection.
    old_main = module.main
    def main_with_shared_chat_bridge():
        previous_input = builtins.input
        def intercepted(prompt=""):
            while True:
                raw = previous_input(prompt)
                clean = str(raw or "").strip()
                low = clean.casefold()
                if low.startswith("/knowledge chat-context "):
                    query = clean[len("/knowledge chat-context "):].strip()
                    print(json.dumps(_sk_chat_bridge_preview(module, query, "mid"), ensure_ascii=False, indent=2))
                    continue
                return raw
        builtins.input = intercepted
        try:
            return old_main()
        finally:
            builtins.input = previous_input
    module.main = main_with_shared_chat_bridge
    old_help = module.print_help
    def help_with_shared_chat_bridge(advanced=False, *args, **kwargs):
        result = old_help(advanced=advanced, *args, **kwargs)
        print("  /knowledge chat-context <query>      preview the source-grounded shared context normal chat will receive")
        return result
    module.print_help = help_with_shared_chat_bridge
    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["shared-knowledge-chat-bridge"] = {"label":"Active shared book/research evidence mounted into normal chat", "groups":("quick","critical","all"), "runner":"memory.shared_knowledge_chat_bridge_self_test"}
    module._SHARED_KNOWLEDGE_CHAT_BRIDGE_INSTALLED = True


