def _ska_fold(value: object) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).casefold()
    text = text.replace("’", "'").replace("‘", "'").replace("–", "-").replace("—", "-")
    return " ".join(text.split())


def _ska_group_hits(text: str, groups: list[list[str]] | tuple) -> tuple[bool, list[dict]]:
    folded = _ska_fold(text)
    details = []
    all_ok = True
    for group in groups or []:
        alternatives = [str(x) for x in group if str(x).strip()]
        matched = [term for term in alternatives if _ska_fold(term) in folded]
        ok = bool(matched)
        all_ok = all_ok and ok
        details.append({"alternatives": alternatives, "matched": matched, "ok": ok})
    return all_ok, details


def _ska_collect_selected_passages(module, passage_ids: list[str]) -> list[dict]:
    rows = []
    for passage_id in passage_ids:
        try:
            payload = module.get_shared_evidence_passage(str(passage_id), include_original=True)
        except Exception as exc:
            rows.append({"passage_id": str(passage_id), "ok": False, "error": f"{type(exc).__name__}: {exc}", "text": ""})
            continue
        passage = dict(payload.get("passage") or {})
        original = dict(payload.get("original") or {})
        summary = str(passage.get("summary_text") or "")
        exact = str(original.get("text") or "")
        combined = (summary + "\n" + exact).strip()
        rows.append({
            "passage_id": str(passage_id),
            "ok": bool(payload.get("ok")),
            "source_id": passage.get("source_id"),
            "version_id": passage.get("version_id"),
            "chunk_id": passage.get("chunk_id"),
            "source_ref": passage.get("source_ref"),
            "hash_verified": bool(original.get("matches_index_sha256")) if exact else None,
            "has_original": bool(exact),
            "text": combined,
        })
    return rows


def _ska_grade_evidence(case: dict, passage_rows: list[dict]) -> dict:
    """Legacy 7.4.25.8 metric: exact lexical groups in one KP unless case says bundle.

    This metric is intentionally preserved for longitudinal comparison. It is no
    longer treated as the overall shared-packet evidence score in 7.4.25.8.1.
    """
    groups = list(case.get("evidence_groups") or [])
    mode = str(case.get("evidence_mode") or "single").casefold()
    if mode == "bundle":
        combined = "\n".join(str(row.get("text") or "") for row in passage_rows if row.get("ok"))
        ok, detail = _ska_group_hits(combined, groups)
        supporting_ids = [row.get("passage_id") for row in passage_rows if row.get("ok")]
        return {"ok": ok, "mode": mode, "groups": detail, "supporting_passage_ids": supporting_ids}
    evaluations = []
    for row in passage_rows:
        ok, detail = _ska_group_hits(str(row.get("text") or ""), groups)
        evaluations.append({"passage_id": row.get("passage_id"), "ok": ok, "groups": detail})
    winners = [row for row in evaluations if row.get("ok")]
    return {
        "ok": bool(winners), "mode": "single", "groups": (winners[0].get("groups") if winners else []),
        "supporting_passage_ids": [row.get("passage_id") for row in winners],
        "per_passage": evaluations,
    }


def _ska_grade_bundle(groups: list[list[str]] | tuple, rows: list[dict], *, id_key: str, mode: str) -> dict:
    """Grade expected evidence across all selected canonical records."""
    eligible = [row for row in rows if row.get("ok")]
    combined = "\n".join(str(row.get("text") or "") for row in eligible)
    ok, detail = _ska_group_hits(combined, groups)
    return {
        "ok": ok,
        "mode": mode,
        "groups": detail,
        "supporting_ids": [row.get(id_key) for row in eligible if row.get(id_key)],
        "record_count": len(eligible),
    }


def _ska_collect_selected_items(module, item_ids: list[str]) -> list[dict]:
    """Collect the KI navigation text and direct retained source excerpts selected by the bridge."""
    rows = []
    for item_id in item_ids:
        try:
            payload = module.get_shared_knowledge_item(str(item_id))
        except Exception as exc:
            rows.append({"item_id": str(item_id), "ok": False, "error": f"{type(exc).__name__}: {exc}", "text": ""})
            continue
        item = dict(payload.get("item") or {})
        sources = [dict(x) for x in (payload.get("sources") or [])]
        pieces = [str(item.get("claim") or ""), str(item.get("details") or "")]
        direct_source_count = 0
        for source in sources:
            excerpt = str(source.get("excerpt") or "")
            if excerpt:
                direct_source_count += 1
                pieces.append(excerpt)
        rows.append({
            "item_id": str(item_id),
            "ok": bool(payload.get("ok")),
            "source_id": item.get("source_id"),
            "version_id": item.get("version_id"),
            "interpretation": item.get("interpretation"),
            "confidence": item.get("confidence"),
            "direct_source_count": direct_source_count,
            "source_refs": [s.get("source_ref") for s in sources if s.get("source_ref")],
            "text": "\n".join(piece for piece in pieces if piece).strip(),
        })
    return rows


def _ska_packet_evidence_text(context: str) -> str:
    """Return only the evidence-bearing portion actually supplied to Assistant.

    The bridge header and echoed user query are excluded so the benchmark cannot
    satisfy an expected lexical group merely because the question itself contains it.
    """
    raw = str(context or "")
    marker = "ACTIVE SHARED KNOWLEDGE ITEMS — NAVIGATION, NOT PRIMARY EVIDENCE"
    if marker in raw:
        return raw.split(marker, 1)[1]
    lines = []
    for line in raw.splitlines():
        if line.startswith("User query:"):
            continue
        if line.startswith("SHARED KNOWLEDGE CHAT BRIDGE") or line.startswith("Bridge version:"):
            continue
        if line.startswith("AUTHORITY:") or line.startswith("STATE:"):
            continue
        lines.append(line)
    return "\n".join(lines)


def _ska_grade_packet(case: dict, context: str) -> dict:
    text = _ska_packet_evidence_text(context)
    ok, detail = _ska_group_hits(text, list(case.get("evidence_groups") or []))
    return {
        "ok": ok,
        "mode": "actual_context_packet_bundle",
        "groups": detail,
        "context_evidence_chars": len(text),
    }


def _ska_router_grade(module, question: str) -> dict:
    try:
        plan = module._domain_python_minimum(question)
    except Exception as exc:
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}", "selected_domains": []}
    mandatory = [str(x).casefold() for x in (plan.get("mandatory_domains") or [])]
    suggested = [str(x).casefold() for x in (plan.get("suggested_domains") or [])]
    selected = list(dict.fromkeys([*mandatory, *suggested]))
    return {"ok": "books" in selected, "mandatory_domains": mandatory, "suggested_domains": suggested, "selected_domains": selected, "reason": plan.get("reason")}


def _ska_answer_prompt(question: str, context: str) -> tuple[str, str]:
    system = (
        "You are the assistant performing a source-grounded shared-knowledge accuracy benchmark. "
        "Answer only from the supplied retained evidence. If the evidence is insufficient, say so rather than using outside knowledge. "
        "Use the supplied [[CITE:P#]] citation handles for direct source-backed claims whenever possible; K# may be used for supporting digest navigation. "
        "Do not manually type or reconstruct KI-, KP-, KSB-, KSR-, KSO-, KDV-, or BK- identifiers. Keep the answer concise."
    )
    user = f"QUESTION\n{question}\n\nRETRIEVED SHARED KNOWLEDGE\n{context}"
    return system, user


def _ska_make_backend(module, *, provider: str, gpt_alias: str | None = None):
    normalized = str(provider or "local").casefold()
    if normalized == "local":
        return module.build_local_backend(), "local", None
    if normalized != "online":
        raise ValueError("Benchmark provider must be local or online.")
    alias = str(gpt_alias or _sk_model_alias(module) or "luna").casefold()
    if alias not in _GPT_MODEL_ALIASES:
        raise ValueError("GPT alias must be luna, terra, or sol.")
    base = module.build_online_backend()
    model_id = _GPT_MODEL_ALIASES[alias]
    try:
        base.model_id = model_id
        base.provider = "online"
        backend = base
    except Exception:
        backend = module.LocalBackend(client=base.client, model_id=model_id, provider="online")
    return backend, "online", alias


def _ska_receipt_path(module, run_id: str) -> Path:
    root = Path(module.MEMORY_DIR) / "benchmarks" / "receipts"
    root.mkdir(parents=True, exist_ok=True)
    return root / f"shared-knowledge-accuracy-{run_id}.json"


def _ska_atomic_write(module, path: Path, payload: dict) -> None:
    writer = getattr(module, "_benchmark_atomic_write_json", None)
    if callable(writer):
        writer(path, payload)
        return
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(temp, path)


def _ska_select_cases(*, suite: str = "full", limit: int = 0) -> list[dict]:
    selected = [dict(case) for case in _SHARED_ACCURACY_CASES]
    if str(suite or "full").casefold() == "quick":
        selected = [case for case in selected if case.get("id") in _SHARED_ACCURACY_QUICK_IDS]
    if int(limit or 0) > 0:
        selected = selected[: max(1, min(len(selected), int(limit)))]
    return selected


def _ska_run_benchmark(module, *, answers: bool = False, suite: str = "full", level: str = _SHARED_ACCURACY_DEFAULT_LEVEL,
                       limit: int = 0, provider: str = "local", gpt_alias: str | None = None, print_progress: bool = True) -> dict:
    level = str(level or _SHARED_ACCURACY_DEFAULT_LEVEL).casefold()
    if level not in {"low", "mid", "high"}:
        raise ValueError("--level must be low, mid, or high.")
    cases = _ska_select_cases(suite=suite, limit=limit)
    if not cases:
        raise ValueError("No benchmark cases selected.")
    started_at = _sk_now()
    run_id = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:8]
    backend = None
    resolved_provider = "python"
    resolved_alias = None
    model_id = None
    if answers:
        backend, resolved_provider, resolved_alias = _ska_make_backend(module, provider=provider, gpt_alias=gpt_alias)
        model_id = str(getattr(backend, "model_id", "") or "")
    results = []
    total_model_calls = 0
    input_tokens = 0
    output_tokens = 0
    if print_progress:
        mode_text = "answers" if answers else "retrieval-only"
        provider_text = f"{resolved_provider}/{resolved_alias or model_id or 'python'}" if answers else "python/0-model-calls"
        print(f"[shared accuracy] {len(cases)} cases | {mode_text} | level={level} | {provider_text} | packet-aware-v1.1", flush=True)
    for ordinal, case in enumerate(cases, 1):
        t0 = time.perf_counter()
        row = {
            "ordinal": ordinal, "case_id": case["id"], "category": case["category"], "question": case["question"],
            "status": "completed", "quality_pass": False, "legacy_quality_pass": False, "error": None,
        }
        try:
            route = _ska_router_grade(module, case["question"])
            bridge = module.get_shared_knowledge_chat_context(case["question"], level)
            trace = dict(bridge.get("trace") or {})
            context = str(bridge.get("context") or "")
            passage_ids = [str(x) for x in (trace.get("passage_ids") or []) if str(x)]
            item_ids = [str(x) for x in (trace.get("item_ids") or []) if str(x)]
            passage_rows = _ska_collect_selected_passages(module, passage_ids)
            item_rows = _ska_collect_selected_items(module, item_ids)

            # Preserve the old 7.4.25.8 number verbatim as a longitudinal metric.
            legacy_single = _ska_grade_evidence(case, passage_rows)
            kp_bundle = _ska_grade_bundle(case.get("evidence_groups") or [], passage_rows, id_key="passage_id", mode="selected_kp_bundle")
            ki_source = _ska_grade_bundle(case.get("evidence_groups") or [], item_rows, id_key="item_id", mode="selected_ki_direct_source_bundle")
            packet = _ska_grade_packet(case, context)

            bridge_ok = bool(bridge.get("ok") and trace.get("ok"))
            zero_model_retrieval = int(trace.get("model_calls", -1) or 0) == 0
            packet_retrieval_ok = bool(bridge_ok and (passage_ids or item_ids) and zero_model_retrieval and packet.get("ok"))
            legacy_retrieval_ok = bool(bridge_ok and passage_ids and zero_model_retrieval and legacy_single.get("ok"))
            row.update({
                "routing": route,
                "retrieval": {
                    # Backward-facing ok now means actual packet evidence coverage; old score is retained below.
                    "ok": packet_retrieval_ok,
                    "bridge_ok": bridge_ok,
                    "level": level,
                    "model_calls": int(trace.get("model_calls", 0) or 0),
                    "selected_item_ids": item_ids,
                    "selected_passage_ids": passage_ids,
                    "exact_original_passages": int(trace.get("exact_original_passages", 0) or 0),
                    "direct_source_excerpts": int(trace.get("direct_source_excerpts", 0) or 0),
                    "context_chars": int(trace.get("context_chars", 0) or 0),
                    "truncated": bool(trace.get("truncated")),
                    "evidence_anchor_terms": list(trace.get("evidence_anchor_terms") or []),
                    "legacy_single_kp_exact": {"ok": legacy_retrieval_ok, "grade": legacy_single},
                    "kp_bundle": kp_bundle,
                    "ki_direct_source_bundle": ki_source,
                    "packet_evidence": packet,
                    # Compatibility alias: old readers can still inspect retrieval.evidence.
                    "evidence": packet,
                    "passages": [{k:v for k,v in p.items() if k != "text"} for p in passage_rows],
                    "items": [{k:v for k,v in i.items() if k != "text"} for i in item_rows],
                },
            })
            answer_ok = True
            citation_ok = True
            primary_cited = None
            if answers:
                system_prompt, user_prompt = _ska_answer_prompt(case["question"], context)
                call = module._benchmark_provider_call(backend, resolved_provider, system_prompt, user_prompt)
                total_model_calls += 1
                input_tokens += int(call.get("provider_input_tokens", 0) or 0)
                output_tokens += int(call.get("provider_output_tokens", 0) or 0)
                raw_answer = str(call.get("answer") or "")
                plan = {"query": case["question"], "level": level, "query_kind": case["category"], "selected_evidence": [], "shared_knowledge_chat_bridge": trace}
                catalog = module._citation_catalog_from_plan(plan)
                visible_answer, citation_validation = module._citation_process_answer(raw_answer, catalog)
                answer_ok, answer_groups = _ska_group_hits(visible_answer, case.get("answer_groups") or [])
                citation_status = str(citation_validation.get("status") or "")
                citation_ok = citation_status in {"PASS", "PASS_CORRECTED"} and bool(re.search(r"\b(?:KP|KI)-[A-Za-z0-9]+\b", visible_answer))
                primary_cited = bool(re.search(r"\bKP-[A-Za-z0-9]+\b", visible_answer))
                row["answer"] = {
                    "ok": answer_ok,
                    "expected_groups": answer_groups,
                    "raw": raw_answer,
                    "visible": visible_answer,
                    "provider": resolved_provider,
                    "model_alias": resolved_alias,
                    "model": model_id,
                    "provider_input_tokens": int(call.get("provider_input_tokens", 0) or 0),
                    "provider_output_tokens": int(call.get("provider_output_tokens", 0) or 0),
                    "request_id": call.get("request_id"),
                }
                row["citation"] = {
                    "ok": citation_ok,
                    "status": citation_status,
                    "primary_passage_cited": primary_cited,
                    "validation": citation_validation,
                    "catalog_handles": [x.get("handle") for x in (catalog.get("entries") or [])],
                    "catalog_canonical_ids": list(catalog.get("canonical_ids") or []),
                }
            row["quality_pass"] = bool(route.get("ok") and packet_retrieval_ok and answer_ok and citation_ok)
            row["legacy_quality_pass"] = bool(route.get("ok") and legacy_retrieval_ok and answer_ok and citation_ok)
        except Exception as exc:
            row["status"] = "error"
            row["quality_pass"] = False
            row["legacy_quality_pass"] = False
            row["error"] = {"type": type(exc).__name__, "message": str(exc)}
        row["elapsed_seconds"] = round(time.perf_counter() - t0, 3)
        results.append(row)
        if print_progress:
            route_flag = "PASS" if (row.get("routing") or {}).get("ok") else "FAIL"
            retrieval = row.get("retrieval") or {}
            legacy_flag = "PASS" if ((retrieval.get("legacy_single_kp_exact") or {}).get("ok")) else "FAIL"
            kp_bundle_flag = "PASS" if ((retrieval.get("kp_bundle") or {}).get("ok")) else "FAIL"
            ki_flag = "PASS" if ((retrieval.get("ki_direct_source_bundle") or {}).get("ok")) else "FAIL"
            packet_flag = "PASS" if ((retrieval.get("packet_evidence") or {}).get("ok")) else "FAIL"
            answer_flag = "n/a" if not answers else ("PASS" if (row.get("answer") or {}).get("ok") else "FAIL")
            cite_flag = "n/a" if not answers else ("PASS" if (row.get("citation") or {}).get("ok") else "FAIL")
            print(
                f"[{ordinal:02d}/{len(cases):02d}] {case['id']} | route {route_flag} | "
                f"KP-single {legacy_flag} | KP-bundle {kp_bundle_flag} | KI/source {ki_flag} | packet {packet_flag} | "
                f"answer {answer_flag} | cite {cite_flag}", flush=True,
            )
    finished_at = _sk_now()
    completed = sum(1 for row in results if row.get("status") == "completed")
    quality_passes = sum(1 for row in results if row.get("quality_pass"))
    legacy_quality_passes = sum(1 for row in results if row.get("legacy_quality_pass"))
    route_passes = sum(1 for row in results if (row.get("routing") or {}).get("ok"))
    packet_passes = sum(1 for row in results if ((row.get("retrieval") or {}).get("packet_evidence") or {}).get("ok"))
    legacy_single_passes = sum(1 for row in results if ((row.get("retrieval") or {}).get("legacy_single_kp_exact") or {}).get("ok"))
    kp_bundle_passes = sum(1 for row in results if ((row.get("retrieval") or {}).get("kp_bundle") or {}).get("ok"))
    ki_source_passes = sum(1 for row in results if ((row.get("retrieval") or {}).get("ki_direct_source_bundle") or {}).get("ok"))
    answer_passes = sum(1 for row in results if answers and (row.get("answer") or {}).get("ok"))
    citation_passes = sum(1 for row in results if answers and (row.get("citation") or {}).get("ok"))
    primary_citations = sum(1 for row in results if answers and (row.get("citation") or {}).get("primary_passage_cited"))
    execution_errors = [row["case_id"] for row in results if row.get("status") != "completed"]
    summary = {
        "planned_cases": len(cases), "completed_cases": completed, "failed_cases": len(cases) - quality_passes,
        "quality_passes": quality_passes, "quality_accuracy_percent": round(100.0 * quality_passes / len(cases), 1),
        "legacy_quality_passes": legacy_quality_passes, "legacy_quality_accuracy_percent": round(100.0 * legacy_quality_passes / len(cases), 1),
        "routing_passes": route_passes, "routing_percent": round(100.0 * route_passes / len(cases), 1),
        # evidence_* now means the actual bounded packet Assistant received.
        "evidence_passes": packet_passes, "evidence_percent": round(100.0 * packet_passes / len(cases), 1),
        "packet_evidence_passes": packet_passes, "packet_evidence_percent": round(100.0 * packet_passes / len(cases), 1),
        "legacy_single_kp_exact_passes": legacy_single_passes,
        "legacy_single_kp_exact_percent": round(100.0 * legacy_single_passes / len(cases), 1),
        "kp_bundle_passes": kp_bundle_passes, "kp_bundle_percent": round(100.0 * kp_bundle_passes / len(cases), 1),
        "ki_direct_source_passes": ki_source_passes, "ki_direct_source_percent": round(100.0 * ki_source_passes / len(cases), 1),
        "answer_passes": answer_passes if answers else None,
        "answer_accuracy_percent": round(100.0 * answer_passes / len(cases), 1) if answers else None,
        "citation_passes": citation_passes if answers else None,
        "citation_coverage_percent": round(100.0 * citation_passes / len(cases), 1) if answers else None,
        "primary_passage_citations": primary_citations if answers else None,
        "primary_passage_citation_percent": round(100.0 * primary_citations / len(cases), 1) if answers else None,
        "model_calls": total_model_calls,
        "provider_input_tokens": input_tokens if answers else 0,
        "provider_output_tokens": output_tokens if answers else 0,
    }
    receipt = {
        "benchmark": {
            "name": _SHARED_ACCURACY_BENCHMARK_NAME, "version": _SHARED_ACCURACY_BENCHMARK_VERSION,
            "run_id": run_id, "suite": str(suite or "full").casefold(), "mode": "answers" if answers else "retrieval_only",
            "retrieval_level": level, "started_at": started_at, "finished_at": finished_at,
        },
        "environment": {
            "neatmemory_version": getattr(module, "NEATMEMORY_VERSION", BUNDLE_VERSION),
            "retrieval_engine": getattr(module, "SHARED_KNOWLEDGE_CHAT_BRIDGE_VERSION", _SHARED_CHAT_BRIDGE_VERSION),
            "citation_engine": getattr(module, "CITATION_ENGINE_VERSION", None),
            "provider": resolved_provider if answers else "python",
            "model_alias": resolved_alias,
            "model": model_id,
            "retrieval_model_calls_per_case": 0,
        },
        "metric_definitions": {
            "legacy_single_kp_exact": "7.4.25.8 lexical metric: all expected evidence groups must occur in one selected KP passage unless the case was already bundle-mode.",
            "kp_bundle": "Expected evidence groups may be distributed across all selected canonical KP passages.",
            "ki_direct_source_bundle": "Expected evidence groups may be distributed across selected KI claims/details and their retained direct source excerpts.",
            "packet_evidence": "Expected evidence groups must occur somewhere in the actual bounded shared-knowledge context supplied to Assistant; the echoed user query/header are excluded from scoring.",
            "quality": "Routing + packet_evidence + answer/citation requirements when answer mode is enabled.",
        },
        "summary": summary,
        "cases": results,
        "receipt_validation": {
            "status": "PASS" if not execution_errors and completed == len(cases) else "FAIL",
            "errors": (["case execution errors: " + ", ".join(execution_errors)] if execution_errors else []),
            "validator": "neatmemory_shared_knowledge_accuracy_receipt_v1_1_packet_aware",
            "note": "Receipt PASS means the benchmark executed completely. The legacy single-KP metric is preserved separately; overall evidence/quality use the actual bounded packet supplied to Assistant.",
        },
    }
    path = _ska_receipt_path(module, run_id)
    _ska_atomic_write(module, path, receipt)
    if print_progress:
        print(
            f"[shared accuracy] packet quality {quality_passes}/{len(cases)} ({summary['quality_accuracy_percent']}%) | "
            f"routing {route_passes}/{len(cases)} | packet {packet_passes}/{len(cases)} | "
            f"KP-single(old) {legacy_single_passes}/{len(cases)} | KP-bundle {kp_bundle_passes}/{len(cases)} | "
            f"KI/source {ki_source_passes}/{len(cases)}" +
            (f" | answers {answer_passes}/{len(cases)} | citations {citation_passes}/{len(cases)}" if answers else "") +
            f" | model calls {total_model_calls}", flush=True,
        )
        print(f"[shared accuracy] receipt: {path}", flush=True)
    return {"ok": not execution_errors and completed == len(cases), "path": str(path), "receipt": receipt}


def _ska_parse_command(module, raw: str) -> dict | None:
    clean = " ".join(str(raw or "").strip().split())
    parts = clean.split()
    if len(parts) < 2 or parts[0].casefold() != "/benchmark" or parts[1].casefold() not in {"shared-knowledge", "shared", "knowledge-accuracy"}:
        return None
    suite = "quick" if "--quick" in [p.casefold() for p in parts] else "full"
    answers = "--answers" in [p.casefold() for p in parts]
    level = _SHARED_ACCURACY_DEFAULT_LEVEL
    limit = 0
    provider = "local"
    alias = None
    lowered = [p.casefold() for p in parts]
    if "--level" in lowered:
        idx = lowered.index("--level")
        if idx + 1 >= len(parts): raise ValueError("--level requires low, mid, or high.")
        level = lowered[idx + 1]
    if "--limit" in lowered:
        idx = lowered.index("--limit")
        if idx + 1 >= len(parts): raise ValueError("--limit requires a positive integer.")
        limit = int(parts[idx + 1])
        if limit < 1: raise ValueError("--limit must be at least 1.")
    if "--gpt" in lowered:
        idx = lowered.index("--gpt")
        if idx + 1 >= len(parts): raise ValueError("--gpt requires luna, terra, or sol.")
        alias = lowered[idx + 1]
        provider = "online"
        answers = True
    if "--lmstudio" in lowered:
        if "--gpt" in lowered: raise ValueError("Choose either --lmstudio or --gpt <alias>, not both.")
        provider = "local"
        answers = True
    return {"answers": answers, "suite": suite, "level": level, "limit": limit, "provider": provider, "gpt_alias": alias}


def shared_knowledge_accuracy_benchmark_self_test(module) -> dict:
    original = os.getenv(_SHARED_KNOWLEDGE_DIR_ENV)
    checks = {}
    try:
        checks["benchmark_has_20_plus_cases"] = len(_SHARED_ACCURACY_CASES) >= 20
        checks["quick_suite_bounded"] = 5 <= len(_ska_select_cases(suite="quick")) < len(_SHARED_ACCURACY_CASES)
        checks["grader_accepts_alternatives"] = _ska_group_hits("The quarantine was caused by plague searchers sealing the house.", [["plague","pestilence"],["searchers"],["house"]])[0]
        checks["command_default_is_zero_model"] = _ska_parse_command(module, "/benchmark shared-knowledge").get("answers") is False
        checks["gpt_requires_explicit_flag"] = _ska_parse_command(module, "/benchmark shared-knowledge --gpt luna").get("provider") == "online"
        # The new packet grader must not count words that appear only in the echoed question.
        leak_context = "User query: secretword\nACTIVE SHARED KNOWLEDGE ITEMS — NAVIGATION, NOT PRIMARY EVIDENCE\nNo matching evidence here."
        checks["packet_query_echo_excluded"] = not _ska_grade_packet({"evidence_groups":[["secretword"]]}, leak_context).get("ok")
        # Multi-record coverage must be allowed even when no single record contains all groups.
        split_rows = [
            {"ok": True, "passage_id": "KP-A", "text": "Friar Lawrence speaks of rancour."},
            {"ok": True, "passage_id": "KP-B", "text": "The marriage may turn it to pure love."},
        ]
        split_case = {"evidence_groups":[["rancour"],["pure love"]], "evidence_mode":"single"}
        checks["legacy_single_can_fail_split_evidence"] = not _ska_grade_evidence(split_case, split_rows).get("ok")
        checks["kp_bundle_accepts_split_evidence"] = _ska_grade_bundle(split_case["evidence_groups"], split_rows, id_key="passage_id", mode="test").get("ok")
        with tempfile.TemporaryDirectory(prefix="neat-shared-accuracy-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV] = folder
            _sk_ensure_schema(module)
            source = _sk_upsert_source("research", "TEST-RJ-BENCH", "Romeo and Juliet benchmark synthetic", "c" * 64, {"kind":"test"})
            started = _sk_begin_version(source=source, scope="test", digest_mode="deep", provider="python", model_alias=None, model_id="test", operation="test", total_chunks=1)
            exact = "Balthasar tells Romeo that Juliet is dead and buried."
            proposal = {"kind":"fact","claim":"Balthasar brings Romeo the news of Juliet's apparent death.","details":"Balthasar reports that Juliet is dead and buried.","interpretation":"direct","domain":"literature","importance":1.0,"confidence":1.0}
            with _sk_connect() as db:
                iid = _sk_store_item(db, version_id=started["version_id"], proposal=proposal, resolved_sources=[{"ref":"test:rj:1","excerpt":exact,"snapshot_id":"S1","text_sha256":_sk_hash(exact)}], source_kind="research")
                pid = _sk_id("KP", {"test":"shared-accuracy"}, 20)
                db.execute("INSERT INTO knowledge_passages(passage_id,version_id,source_id,source_ref,source_kind,chunk_id,chunk_ordinal,passage_ordinal,char_start,char_end,source_text_sha256,summary_text,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                           (pid, started["version_id"], source["source_id"], "test:rj:1", "research", None, 1, 1, 0, len(exact), _sk_hash(exact), exact, _sk_json({"test":True}), _sk_now()))
                for term in _dei_build_terms(exact, [{"text":"Balthasar","confidence":1.0,"entity_type":"person_or_character","reason":"test"}]):
                    db.execute("INSERT OR REPLACE INTO knowledge_terms(passage_id,term_norm,canonical_norm,display_text,entity_type,origin,confidence,is_alias,ordinal) VALUES(?,?,?,?,?,?,?,?,?)",
                               (pid, term["term_norm"], term["canonical_norm"], term["display_text"], term["entity_type"], term["origin"], float(term["confidence"]), 1 if term.get("is_alias") else 0, int(term["ordinal"])))
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)", (started["version_id"], "C1", 1, _sk_hash(exact), "completed", _sk_now()))
            _sk_finalize_version(source["source_id"], started["version_id"], started["run_id"], processed=1, model_calls=0, items=1)
            run = _ska_run_benchmark(module, answers=False, suite="full", level="mid", limit=1, print_progress=False)
            receipt = run.get("receipt") or {}
            first = (receipt.get("cases") or [{}])[0]
            retrieval = first.get("retrieval") or {}
            summary = receipt.get("summary") or {}
            checks["synthetic_retrieval_benchmark_executes"] = bool(run.get("ok"))
            checks["synthetic_route_books"] = bool((first.get("routing") or {}).get("ok"))
            checks["synthetic_packet_evidence_passes"] = bool((retrieval.get("packet_evidence") or {}).get("ok"))
            checks["synthetic_kp_bundle_passes"] = bool((retrieval.get("kp_bundle") or {}).get("ok"))
            checks["synthetic_ki_source_passes"] = bool((retrieval.get("ki_direct_source_bundle") or {}).get("ok"))
            checks["synthetic_ids_recorded"] = iid in (retrieval.get("selected_item_ids") or []) and pid in (retrieval.get("selected_passage_ids") or [])
            checks["synthetic_zero_model_calls"] = int(summary.get("model_calls", -1)) == 0
            checks["packet_metric_is_summary_evidence"] = summary.get("evidence_passes") == summary.get("packet_evidence_passes")
            checks["legacy_metric_retained"] = "legacy_single_kp_exact_percent" in summary
            checks["receipt_execution_valid"] = str((receipt.get("receipt_validation") or {}).get("status")) == "PASS"
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV, None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV] = original
    return {"ok": all(bool(v) for v in checks.values()), "checks": checks, "case_count": len(_SHARED_ACCURACY_CASES), "version": _SHARED_ACCURACY_BENCHMARK_VERSION}


def _install_shared_knowledge_accuracy_benchmark(module) -> None:
    if getattr(module, "_SHARED_KNOWLEDGE_ACCURACY_BENCHMARK_INSTALLED", False):
        return
    module.SHARED_KNOWLEDGE_ACCURACY_BENCHMARK_VERSION = _SHARED_ACCURACY_BENCHMARK_VERSION
    module.SHARED_KNOWLEDGE_ACCURACY_BENCHMARK_CASES = tuple(dict(x) for x in _SHARED_ACCURACY_CASES)
    module.run_shared_knowledge_accuracy_benchmark = lambda **kwargs: _ska_run_benchmark(module, **kwargs)
    module.shared_knowledge_accuracy_benchmark_self_test = lambda: shared_knowledge_accuracy_benchmark_self_test(module)
    old_help = module.print_help
    def help_with_shared_accuracy(advanced=False, *args, **kwargs):
        result = old_help(advanced=advanced, *args, **kwargs)
        print("  /benchmark shared-knowledge [--quick] [--level mid] [--limit N]   0-model-call packet-aware routing/evidence benchmark")
        print("  /benchmark shared-knowledge --answers [--online|--lmstudio|--gpt luna]     add answer/citation accuracy; LM Studio default")
        return result
    module.print_help = help_with_shared_accuracy
    module._SHARED_KNOWLEDGE_ACCURACY_BENCHMARK_INSTALLED = True


# ---------------------------------------------------------------------------
# NeatMemory 7.4.25.10.11 — Deep Digestion Quality Benchmark
# ---------------------------------------------------------------------------
# This benchmark deliberately bypasses natural-question retrieval. It audits the
# currently active canonical Deep digest itself: did a KI capture the expected
# concept, and does that KI carry its own retained source excerpt supporting the
# fact? Provenance integrity is measured separately. Duplicate and low-grounding
# signals are diagnostics, not automatic proof of hallucination.

_DEEP_DIGESTION_QUALITY_VERSION = "1.0-anchored-ki-source-provenance"
_DEEP_DIGESTION_QUALITY_NAME = "deep_digestion_quality"
_DEEP_DIGESTION_QUICK_IDS = frozenset(_SHARED_ACCURACY_QUICK_IDS)
_DQ_STOPWORDS = frozenset({
    "the","and","that","this","with","from","have","has","had","for","are","was","were","will","would","could","should",
    "into","onto","than","then","there","their","they","them","you","your","our","his","her","its","but","not","all",
    "any","can","may","might","also","more","most","some","such","only","same","when","where","what","which","who","whom",
    "why","how","about","over","under","after","before","between","through","during","because","while","a","an","of","to","in",
    "on","at","by","as","is","it","be","or","if","so","we","i","me","my","he","she","do","did","does","done"
})


def _dq_content_terms(value: object) -> set[str]:
    return {t for t in _sk_validation_terms(str(value or "")) if len(t) > 2 and t not in _DQ_STOPWORDS}


def _dq_source_candidates() -> list[dict]:
    with _sk_connect() as db:
        rows=db.execute("""SELECT * FROM knowledge_sources
                           WHERE source_kind='book' AND active=1 AND retired=0 AND current_version_id IS NOT NULL
                           ORDER BY updated_at DESC, source_id""").fetchall()
    return [dict(r) for r in rows]


def _dq_resolve_source(reference: str | None = None) -> tuple[dict,str]:
    if str(reference or "").strip():
        source=_sk_resolve_source(str(reference).strip())
        if not source: raise ValueError(f"Knowledge source not found: {reference}")
        if str(source.get("source_kind") or "").casefold() != "book":
            raise ValueError("Deep digestion quality benchmark currently targets active book digests.")
        if not source.get("current_version_id"):
            raise ValueError("Selected source has no active completed knowledge version.")
        return dict(source),"explicit"
    candidates=_dq_source_candidates()
    if not candidates: raise ValueError("No active book digest is available. Use /benchmark digestion <BK-ID> after a Deep digest exists.")
    if len(candidates)==1: return candidates[0],"single_active_book"
    # The built-in truth anchors are Romeo-and-Juliet-specific. If several books
    # are active, select only when one source is uniquely identifiable from its
    # canonical KI content; never guess on a tie.
    anchors=("romeo","juliet","tybalt","mercutio","capulet","rosaline","balthasar")
    scored=[]
    with _sk_connect() as db:
        for src in candidates:
            vid=str(src.get("current_version_id") or "")
            rows=db.execute("SELECT claim,details FROM knowledge_items WHERE version_id=?",(vid,)).fetchall()
            folded=_ska_fold("\n".join(f"{r['claim']} {r['details']}" for r in rows))
            score=sum(1 for term in anchors if term in folded)
            scored.append((score,src))
    scored.sort(key=lambda x:(-x[0],str(x[1].get("source_id") or "")))
    if scored and scored[0][0] >= 4 and (len(scored)==1 or scored[0][0] > scored[1][0]):
        return scored[0][1],"benchmark_anchor_match"
    raise ValueError("Multiple active book digests exist and the Romeo and Juliet benchmark source is ambiguous. Use /benchmark digestion <BK-ID>.")


def _dq_load_items(source: dict) -> list[dict]:
    version_id=str(source.get("current_version_id") or "")
    with _sk_connect() as db:
        item_rows=[dict(r) for r in db.execute("SELECT * FROM knowledge_items WHERE version_id=? ORDER BY item_id",(version_id,)).fetchall()]
        src_rows=[dict(r) for r in db.execute("""SELECT s.* FROM knowledge_item_sources s
                                                  JOIN knowledge_items i ON i.item_id=s.item_id
                                                  WHERE i.version_id=? ORDER BY s.item_id,s.ordinal""",(version_id,)).fetchall()]
    by_item={}
    for row in src_rows: by_item.setdefault(str(row.get("item_id") or ""),[]).append(row)
    out=[]
    for item in item_rows:
        iid=str(item.get("item_id") or "")
        sources=by_item.get(iid,[])
        item_text="\n".join(x for x in (str(item.get("claim") or ""),str(item.get("details") or "")) if x).strip()
        source_text="\n".join(str(s.get("excerpt") or "") for s in sources if str(s.get("excerpt") or "")).strip()
        hash_mismatches=[]; missing_refs=[]
        for s in sources:
            if not str(s.get("source_ref") or "").strip(): missing_refs.append(int(s.get("ordinal") or 0))
            excerpt=str(s.get("excerpt") or "")
            stored=str(s.get("excerpt_sha256") or "")
            if not stored or stored != _sk_hash(excerpt): hash_mismatches.append(int(s.get("ordinal") or 0))
        claim_terms=_dq_content_terms(item.get("claim"))
        source_terms=_dq_content_terms(source_text)
        grounding_ratio=(len(claim_terms & source_terms)/len(claim_terms)) if claim_terms else 1.0
        out.append({
            **item,"sources":sources,"item_text":item_text,"source_text":source_text,
            "source_count":len(sources),"hash_mismatches":hash_mismatches,"missing_source_refs":missing_refs,
            "claim_grounding_ratio":round(grounding_ratio,4),
            "provenance_ok":bool(sources) and not hash_mismatches and not missing_refs,
        })
    return out


def _dq_any_group_hit(text: str, groups: list[list[str]] | tuple) -> bool:
    folded=_ska_fold(text)
    for group in groups or []:
        for term in group:
            if _ska_fold(term) in folded: return True
    return False


def _dq_grade_case(case: dict, items: list[dict]) -> dict:
    answer_groups=list(case.get("answer_groups") or [])
    evidence_groups=list(case.get("evidence_groups") or [])
    mode=str(case.get("evidence_mode") or "single").casefold()
    per=[]
    for item in items:
        concept_ok,concept_groups=_ska_group_hits(item.get("item_text") or "",answer_groups)
        evidence_ok,evidence_detail=_ska_group_hits(item.get("source_text") or "",evidence_groups)
        per.append({"item_id":item.get("item_id"),"concept_ok":concept_ok,"evidence_ok":evidence_ok,
                    "grounded_ok":bool(concept_ok and evidence_ok and item.get("provenance_ok")),
                    "provenance_ok":bool(item.get("provenance_ok")),"concept_groups":concept_groups,"evidence_groups":evidence_detail})
    if mode=="bundle":
        relevant=[item for item in items if _dq_any_group_hit(item.get("item_text") or "",answer_groups)]
        combined_items="\n".join(str(item.get("item_text") or "") for item in relevant)
        combined_sources="\n".join(str(item.get("source_text") or "") for item in relevant)
        concept_ok,concept_groups=_ska_group_hits(combined_items,answer_groups)
        evidence_ok,evidence_detail=_ska_group_hits(combined_sources,evidence_groups)
        provenance_ok=bool(relevant) and all(bool(item.get("provenance_ok")) for item in relevant)
        supporting=[str(item.get("item_id")) for item in relevant]
        grounded_ok=bool(concept_ok and evidence_ok and provenance_ok)
    else:
        concept_winners=[row for row in per if row.get("concept_ok")]
        grounded_winners=[row for row in per if row.get("grounded_ok")]
        concept_ok=bool(concept_winners)
        grounded_ok=bool(grounded_winners)
        evidence_ok=any(bool(row.get("evidence_ok")) for row in concept_winners)
        provenance_ok=bool(grounded_winners) or (bool(concept_winners) and all(bool(row.get("provenance_ok")) for row in concept_winners))
        supporting=[str(row.get("item_id")) for row in (grounded_winners or concept_winners)]
        concept_groups=(concept_winners[0].get("concept_groups") if concept_winners else [])
        evidence_detail=(grounded_winners[0].get("evidence_groups") if grounded_winners else (concept_winners[0].get("evidence_groups") if concept_winners else []))
    return {"ok":bool(grounded_ok),"mode":mode,"concept_ok":bool(concept_ok),"evidence_ok":bool(evidence_ok),
            "provenance_ok":bool(provenance_ok),"grounded_ok":bool(grounded_ok),"supporting_item_ids":supporting,
            "concept_groups":concept_groups,"evidence_groups":evidence_detail}


def _dq_duplicate_diagnostics(items: list[dict]) -> dict:
    exact={}
    for item in items:
        key=_ska_fold(item.get("claim") or "")
        if key: exact.setdefault(key,[]).append(str(item.get("item_id") or ""))
    exact_groups=[ids for ids in exact.values() if len(ids)>1]
    near=[]
    token_rows=[]
    for item in items:
        terms=_dq_content_terms(item.get("claim") or "")
        if len(terms)>=5: token_rows.append((str(item.get("item_id") or ""),terms))
    for i in range(len(token_rows)):
        ia,a=token_rows[i]
        for j in range(i+1,len(token_rows)):
            ib,b=token_rows[j]
            union=a|b
            score=(len(a&b)/len(union)) if union else 0.0
            if score>=0.84: near.append({"item_ids":[ia,ib],"jaccard":round(score,4)})
    near.sort(key=lambda r:(-float(r["jaccard"]),r["item_ids"]))
    return {"exact_duplicate_groups":exact_groups[:30],"near_duplicate_pairs":near[:30],"near_duplicate_pair_count":len(near)}


def _dq_global_diagnostics(items: list[dict]) -> dict:
    duplicates=_dq_duplicate_diagnostics(items)
    orphan=[str(i.get("item_id")) for i in items if int(i.get("source_count") or 0)==0]
    mismatched=[str(i.get("item_id")) for i in items if i.get("hash_mismatches")]
    missing_refs=[str(i.get("item_id")) for i in items if i.get("missing_source_refs")]
    low_direct=[{"item_id":str(i.get("item_id")),"ratio":i.get("claim_grounding_ratio")}
                for i in items if str(i.get("interpretation") or "").casefold()=="direct" and float(i.get("claim_grounding_ratio") or 0.0)<0.25 and not (callable(globals().get("_cb_is_chunk_boundary_artifact")) and _cb_is_chunk_boundary_artifact(i))]
    very_short=[str(i.get("item_id")) for i in items if len(_dq_content_terms(i.get("claim") or ""))<4]
    return {"item_count":len(items),"orphan_item_ids":orphan,"excerpt_hash_mismatch_item_ids":mismatched,
            "missing_source_ref_item_ids":missing_refs,"low_grounding_direct_items":low_direct[:30],
            "very_short_claim_item_ids":very_short[:30],**duplicates}


def _dq_select_cases(*, suite: str="full", limit: int=0) -> list[dict]:
    selected=[dict(case) for case in _SHARED_ACCURACY_CASES]
    if str(suite or "full").casefold()=="quick": selected=[case for case in selected if case.get("id") in _DEEP_DIGESTION_QUICK_IDS]
    if int(limit or 0)>0: selected=selected[:max(1,min(len(selected),int(limit)))]
    return selected


def _dq_receipt_path(module, run_id: str) -> Path:
    root=Path(module.MEMORY_DIR)/"benchmarks"/"receipts"; root.mkdir(parents=True,exist_ok=True)
    return root/f"deep-digestion-quality-{run_id}.json"


def _dq_run_benchmark(module, *, reference: str|None=None, suite: str="full", limit: int=0, print_progress: bool=True) -> dict:
    started=_sk_now(); run_id=datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")+"-"+uuid.uuid4().hex[:8]
    source,selection=_dq_resolve_source(reference)
    version_id=str(source.get("current_version_id") or "")
    with _sk_connect() as db:
        version_row=db.execute("SELECT * FROM knowledge_versions WHERE version_id=?",(version_id,)).fetchone()
    if not version_row: raise ValueError("Active knowledge version row is missing.")
    version=dict(version_row)
    cases=_dq_select_cases(suite=suite,limit=limit)
    items=_dq_load_items(source)
    diagnostics=_dq_global_diagnostics(items)
    rows=[]
    if print_progress:
        print(f"[digestion quality] {len(cases)} anchors | active digest | source={source.get('source_key')} | version={version_id} | 0 model calls",flush=True)
    for idx,case in enumerate(cases,1):
        grade=_dq_grade_case(case,items)
        row={"id":case.get("id"),"category":case.get("category"),"question":case.get("question"),"grade":grade}
        rows.append(row)
        if print_progress:
            print(f"[{idx:02d}/{len(cases):02d}] {case.get('id')} | KI {'PASS' if grade['concept_ok'] else 'FAIL'} | KI/source {'PASS' if grade['grounded_ok'] else 'FAIL'} | provenance {'PASS' if grade['provenance_ok'] else 'FAIL'}",flush=True)
    quality=sum(1 for r in rows if (r.get("grade") or {}).get("ok"))
    concepts=sum(1 for r in rows if (r.get("grade") or {}).get("concept_ok"))
    grounded=sum(1 for r in rows if (r.get("grade") or {}).get("grounded_ok"))
    provenance_cases=sum(1 for r in rows if (r.get("grade") or {}).get("provenance_ok"))
    total=len(rows)
    global_provenance_ok=(not diagnostics["orphan_item_ids"] and not diagnostics["excerpt_hash_mismatch_item_ids"] and not diagnostics["missing_source_ref_item_ids"])
    summary={
        "planned_cases":total,"completed_cases":total,"quality_passes":quality,"quality_percent":round(100.0*quality/total,1) if total else 0.0,
        "concept_coverage_passes":concepts,"concept_coverage_percent":round(100.0*concepts/total,1) if total else 0.0,
        "grounded_ki_source_passes":grounded,"grounded_ki_source_percent":round(100.0*grounded/total,1) if total else 0.0,
        "case_provenance_passes":provenance_cases,"case_provenance_percent":round(100.0*provenance_cases/total,1) if total else 0.0,
        "global_provenance_integrity":global_provenance_ok,"knowledge_items":diagnostics["item_count"],
        "orphan_items":len(diagnostics["orphan_item_ids"]),"excerpt_hash_mismatches":len(diagnostics["excerpt_hash_mismatch_item_ids"]),
        "missing_source_refs":len(diagnostics["missing_source_ref_item_ids"]),"exact_duplicate_groups":len(diagnostics["exact_duplicate_groups"]),
        "near_duplicate_pairs":int(diagnostics["near_duplicate_pair_count"]),"low_grounding_direct_items":len(diagnostics["low_grounding_direct_items"]),
        "very_short_claim_items":len(diagnostics["very_short_claim_item_ids"]),"model_calls":0,
    }
    receipt={
        "benchmark":{"name":_DEEP_DIGESTION_QUALITY_NAME,"version":_DEEP_DIGESTION_QUALITY_VERSION,"run_id":run_id,"suite":str(suite or "full").casefold(),
                     "started_at":started,"finished_at":_sk_now(),"mode":"active_digest_zero_retrieval_zero_model","source_selection":selection},
        "source":{"source_id":source.get("source_id"),"source_key":source.get("source_key"),"title":source.get("title"),"version_id":version_id,
                  "version_number":version.get("version_number"),"digest_mode":version.get("digest_mode"),"provider":version.get("provider"),
                  "model_alias":version.get("model_alias"),"model_id":version.get("model_id")},
        "summary":summary,"cases":rows,"diagnostics":diagnostics,
        "authority":{"KI":"canonical digest interpretation/navigation","KI_source_excerpt":"retained direct source attached to the KI","benchmark":"measurement only; no retrieval and no digest mutation"},
        "receipt_validation":{"status":"PASS","errors":[],"validator":"neatmemory_deep_digestion_quality_receipt_v1",
                              "note":"Receipt PASS means the audit executed completely. Quality percentages measure the active digest; they are not forced to pass."},
    }
    path=_dq_receipt_path(module,run_id); _ska_atomic_write(module,path,receipt)
    if print_progress:
        print(f"[digestion quality] quality {quality}/{total} ({summary['quality_percent']}%) | KI concepts {concepts}/{total} | KI/source {grounded}/{total} | case provenance {provenance_cases}/{total} | global provenance {'PASS' if global_provenance_ok else 'FAIL'} | duplicates exact={summary['exact_duplicate_groups']} near={summary['near_duplicate_pairs']} | grounding-risk={summary['low_grounding_direct_items']} | model calls 0",flush=True)
        print(f"[digestion quality] receipt: {path}",flush=True)
    return {"ok":True,"path":str(path),"receipt":receipt}


def _dq_parse_command(raw: str) -> dict|None:
    clean=" ".join(str(raw or "").strip().split()); parts=clean.split(); lowered=[p.casefold() for p in parts]
    if len(parts)<2 or parts[0].casefold()!="/benchmark" or parts[1].casefold() not in {"digestion","deep-digestion","digestion-quality"}: return None
    suite="quick" if "--quick" in lowered else "full"; limit=0; reference=None
    if "--limit" in lowered:
        idx=lowered.index("--limit")
        if idx+1>=len(parts): raise ValueError("--limit requires a positive integer.")
        limit=int(parts[idx+1])
        if limit<1: raise ValueError("--limit must be at least 1.")
    if "--source" in lowered:
        idx=lowered.index("--source")
        if idx+1>=len(parts): raise ValueError("--source requires a BK-/KSB- reference.")
        reference=parts[idx+1]
    elif len(parts)>=3 and not parts[2].startswith("--"):
        reference=parts[2]
    if "--gpt" in lowered or "--lmstudio" in lowered or "--answers" in lowered:
        raise ValueError("Digestion quality audits the already-stored active digest with zero model calls; provider flags are not used.")
    return {"reference":reference,"suite":suite,"limit":limit}


def deep_digestion_quality_benchmark_self_test(module) -> dict:
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV); checks={}
    try:
        checks["parser_zero_model_surface"]=_dq_parse_command("/benchmark digestion BK-TEST --quick --limit 1")=={"reference":"BK-TEST","suite":"quick","limit":1}
        synthetic_item={"item_id":"KI-X","claim":"Balthasar brings Romeo news of Juliet's death.","details":"He reports that Juliet is dead and buried.","interpretation":"direct",
                        "item_text":"Balthasar brings Romeo news of Juliet's death. He reports that Juliet is dead and buried.",
                        "source_text":"Balthasar tells Romeo that Juliet is dead and buried.","source_count":1,"hash_mismatches":[],"missing_source_refs":[],"provenance_ok":True}
        first=dict(_SHARED_ACCURACY_CASES[0]); grade=_dq_grade_case(first,[synthetic_item])
        checks["grader_requires_ki_and_owned_source"]=bool(grade.get("concept_ok") and grade.get("grounded_ok") and grade.get("provenance_ok"))
        ungrounded=dict(synthetic_item); ungrounded["source_text"]="A completely unrelated retained excerpt."
        checks["ki_without_support_does_not_pass_grounded"]=not _dq_grade_case(first,[ungrounded]).get("grounded_ok")
        duplicate_items=[{"item_id":"KI-A","claim":"Romeo learns the news from Balthasar."},{"item_id":"KI-B","claim":"Romeo learns the news from Balthasar."}]
        checks["duplicate_diagnostics_report_exact"]=len(_dq_duplicate_diagnostics(duplicate_items).get("exact_duplicate_groups") or [])==1
        with tempfile.TemporaryDirectory(prefix="neat-digestion-quality-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder; _sk_ensure_schema(module)
            source=_sk_upsert_source("book","BK-TEST-DQ","Synthetic Romeo and Juliet digestion benchmark","d"*64,{"kind":"test"})
            started=_sk_begin_version(source=source,scope="test",digest_mode="deep",provider="python",model_alias=None,model_id="test",operation="test",total_chunks=1)
            exact="Balthasar tells Romeo that Juliet is dead and buried."
            proposal={"kind":"fact","claim":"Balthasar brings Romeo the news of Juliet's apparent death.","details":"Balthasar reports that Juliet is dead and buried.","interpretation":"direct","domain":"literature","importance":1.0,"confidence":1.0}
            with _sk_connect() as db:
                iid=_sk_store_item(db,version_id=started["version_id"],proposal=proposal,resolved_sources=[{"ref":"book:BK-TEST-DQ:C1","excerpt":exact,"chunk_id":"C1","text_sha256":_sk_hash(exact)}],source_kind="book")
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)",(started["version_id"],"C1",1,_sk_hash(exact),"completed",_sk_now()))
            _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=1,model_calls=0,items=1)
            run=_dq_run_benchmark(module,reference="BK-TEST-DQ",suite="full",limit=1,print_progress=False)
            receipt=run.get("receipt") or {}; summary=receipt.get("summary") or {}; first_row=(receipt.get("cases") or [{}])[0]
            checks["synthetic_benchmark_executes"]=bool(run.get("ok"))
            checks["synthetic_first_anchor_passes"]=bool((first_row.get("grade") or {}).get("grounded_ok"))
            checks["synthetic_global_provenance_passes"]=summary.get("global_provenance_integrity") is True
            checks["synthetic_zero_model_calls"]=int(summary.get("model_calls",-1))==0
            checks["synthetic_item_id_recorded"]=iid in ((first_row.get("grade") or {}).get("supporting_item_ids") or [])
            checks["receipt_execution_valid"]=str((receipt.get("receipt_validation") or {}).get("status"))=="PASS"
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_DEEP_DIGESTION_QUALITY_VERSION,"case_count":len(_SHARED_ACCURACY_CASES)}


def _install_deep_digestion_quality_benchmark(module) -> None:
    if getattr(module,"_DEEP_DIGESTION_QUALITY_BENCHMARK_INSTALLED",False): return
    module.DEEP_DIGESTION_QUALITY_BENCHMARK_VERSION=_DEEP_DIGESTION_QUALITY_VERSION
    module.run_deep_digestion_quality_benchmark=lambda **kwargs:_dq_run_benchmark(module,**kwargs)
    module.deep_digestion_quality_benchmark_self_test=lambda:deep_digestion_quality_benchmark_self_test(module)
    old_help=module.print_help
    def help_with_digestion_quality(advanced=False,*args,**kwargs):
        result=old_help(advanced=advanced,*args,**kwargs)
        print("  /benchmark digestion [BK-/KSB-ID] [--quick] [--limit N]   0-model-call audit of active Deep KI coverage, KI-owned source grounding, provenance, and duplicate pressure")
        return result
    module.print_help=help_with_digestion_quality
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["deep-digestion-quality"]={"label":"Zero-model-call active Deep digest coverage, KI-owned source grounding, provenance, duplication, and grounding-risk benchmark","groups":("quick","critical","all"),"runner":"memory.deep_digestion_quality_benchmark_self_test"}
    module._DEEP_DIGESTION_QUALITY_BENCHMARK_INSTALLED=True


# ---------------------------------------------------------------------------
# NeatMemory 7.4.25.10.11.1 — Grounding Risk Audit
# ---------------------------------------------------------------------------
# Diagnostic only. A low lexical-overlap "direct" KI is not automatically wrong:
# it may be a valid paraphrase with a conservative labeling mismatch. This audit
# exposes the exact KI/source pair so a human can distinguish label mismatch,
# harmless benchmark false-positive, and genuinely weak support without mutating
# canonical knowledge or invoking a model.

_GROUNDING_RISK_AUDIT_VERSION = "1.0-direct-claim-source-review"
_GROUNDING_RISK_THRESHOLD = 0.25
_GROUNDING_RISK_DEFAULT_LIMIT = 30
_GROUNDING_RISK_DEFAULT_EXCERPT_CHARS = 900


def _gra_priority(ratio: float) -> str:
    value=float(ratio or 0.0)
    if value < 0.10: return "high-review"
    if value < 0.18: return "medium-review"
    return "low-review"


def _gra_excerpt(value: object, max_chars: int) -> str:
    text=str(value or "")
    cap=max(200,min(4000,int(max_chars or _GROUNDING_RISK_DEFAULT_EXCERPT_CHARS)))
    if len(text)<=cap: return text
    return text[:cap].rstrip()+"\n[excerpt preview truncated; canonical retained excerpt is unchanged]"


def _gra_row(item: dict, *, excerpt_chars: int) -> dict:
    claim=str(item.get("claim") or "")
    details=str(item.get("details") or "")
    source_text=str(item.get("source_text") or "")
    claim_terms=_dq_content_terms(claim)
    details_terms=_dq_content_terms(details)
    source_terms=_dq_content_terms(source_text)
    overlap=sorted(claim_terms & source_terms)
    missing=sorted(claim_terms - source_terms)
    details_overlap=sorted(details_terms & source_terms)
    claim_ratio=(len(overlap)/len(claim_terms)) if claim_terms else 1.0
    details_ratio=(len(details_overlap)/len(details_terms)) if details_terms else 1.0
    sources=[]
    for src in item.get("sources") or []:
        sources.append({
            "ordinal":int(src.get("ordinal") or 0),
            "source_ref":str(src.get("source_ref") or ""),
            "locator_json":str(src.get("locator_json") or ""),
            "evidence_sha256":str(src.get("evidence_sha256") or ""),
            "excerpt_sha256":str(src.get("excerpt_sha256") or ""),
            "hash_verified":bool(str(src.get("excerpt_sha256") or "") and str(src.get("excerpt_sha256") or "")==_sk_hash(str(src.get("excerpt") or ""))),
            "excerpt_preview":_gra_excerpt(src.get("excerpt"),excerpt_chars),
        })
    return {
        "item_id":str(item.get("item_id") or ""),
        "version_id":str(item.get("version_id") or ""),
        "kind":str(item.get("kind") or ""),
        "interpretation":str(item.get("interpretation") or ""),
        "domain":str(item.get("domain") or ""),
        "importance":float(item.get("importance") or 0.0),
        "confidence":float(item.get("confidence") or 0.0),
        "claim":claim,
        "details":details,
        "claim_grounding_ratio":round(claim_ratio,4),
        "details_grounding_ratio":round(details_ratio,4),
        "claim_overlap_terms":overlap,
        "claim_nonliteral_terms":missing,
        "details_overlap_terms":details_overlap,
        "review_priority":_gra_priority(claim_ratio),
        "review_reason":f"interpretation=direct but claim/source lexical overlap {claim_ratio:.3f} is below {_GROUNDING_RISK_THRESHOLD:.2f}; diagnostic only — inspect semantic support and whether the KI should have been labeled paraphrase",
        "provenance_ok":bool(item.get("provenance_ok")),
        "source_count":int(item.get("source_count") or 0),
        "sources":sources,
        "authority":"retained source excerpt/hash is authoritative; this risk flag is diagnostic and non-authoritative",
        "mutation_performed":False,
    }


def _gra_receipt_path(module, run_id: str) -> Path:
    root=Path(module.MEMORY_DIR)/"benchmarks"/"receipts"; root.mkdir(parents=True,exist_ok=True)
    return root/f"grounding-risk-audit-{run_id}.json"


def _gra_run_audit(module, *, reference: str|None=None, limit: int=_GROUNDING_RISK_DEFAULT_LIMIT,
                   excerpt_chars: int=_GROUNDING_RISK_DEFAULT_EXCERPT_CHARS, print_progress: bool=True) -> dict:
    started=_sk_now(); run_id=datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")+"-"+uuid.uuid4().hex[:8]
    source,selection=_dq_resolve_source(reference)
    items=_dq_load_items(source)
    flagged=[i for i in items if str(i.get("interpretation") or "").casefold()=="direct" and float(i.get("claim_grounding_ratio") or 0.0)<_GROUNDING_RISK_THRESHOLD and not (callable(globals().get("_cb_is_chunk_boundary_artifact")) and _cb_is_chunk_boundary_artifact(i))]
    flagged.sort(key=lambda i:(float(i.get("claim_grounding_ratio") or 0.0),-float(i.get("importance") or 0.0),str(i.get("item_id") or "")))
    total_flagged=len(flagged)
    selected=flagged[:max(1,min(total_flagged,int(limit or _GROUNDING_RISK_DEFAULT_LIMIT)))] if flagged else []
    rows=[_gra_row(i,excerpt_chars=excerpt_chars) for i in selected]
    priorities={"high-review":0,"medium-review":0,"low-review":0}
    for row in rows: priorities[row["review_priority"]]=priorities.get(row["review_priority"],0)+1
    summary={
        "knowledge_items":len(items),
        "flagged_total":total_flagged,
        "returned_items":len(rows),
        "threshold":_GROUNDING_RISK_THRESHOLD,
        "high_review":sum(1 for i in flagged if _gra_priority(float(i.get("claim_grounding_ratio") or 0.0))=="high-review"),
        "medium_review":sum(1 for i in flagged if _gra_priority(float(i.get("claim_grounding_ratio") or 0.0))=="medium-review"),
        "low_review":sum(1 for i in flagged if _gra_priority(float(i.get("claim_grounding_ratio") or 0.0))=="low-review"),
        "provenance_failures":sum(1 for i in flagged if not i.get("provenance_ok")),
        "model_calls":0,"retrieval_calls":0,"database_mutations":0,
    }
    receipt={
        "audit":{"name":"grounding_risk_audit","version":_GROUNDING_RISK_AUDIT_VERSION,"run_id":run_id,"started_at":started,"finished_at":_sk_now(),"mode":"active_digest_read_only_zero_model_zero_retrieval","source_selection":selection},
        "source":{"source_id":source.get("source_id"),"source_key":source.get("source_key"),"title":source.get("title"),"version_id":source.get("current_version_id")},
        "summary":summary,"items":rows,
        "rule":"Flag only canonical KIs labeled direct whose claim/source lexical overlap is below 0.25. A flag is a review signal, not proof of hallucination or wrong knowledge.",
        "authority":"Exact retained KI source excerpts and hashes remain authoritative. The audit never relabels, rewrites, archives, or creates knowledge.",
        "receipt_validation":{"status":"PASS","errors":[],"validator":"neatmemory_grounding_risk_audit_receipt_v1","note":"Receipt PASS means the read-only audit executed completely; individual flags require inspection."},
    }
    path=_gra_receipt_path(module,run_id); _ska_atomic_write(module,path,receipt)
    if print_progress:
        print(f"[grounding risk] {total_flagged} flagged / {len(items)} KIs | threshold < {_GROUNDING_RISK_THRESHOLD:.2f} | returned {len(rows)} | 0 model calls | read-only",flush=True)
        for idx,row in enumerate(rows,1):
            print(f"[{idx:02d}/{len(rows):02d}] {row['item_id']} | {row['review_priority']} | ratio={row['claim_grounding_ratio']:.4f} | provenance {'PASS' if row['provenance_ok'] else 'FAIL'} | {row['interpretation']} | {row['claim'][:180]}",flush=True)
        print(f"[grounding risk] receipt: {path}",flush=True)
    return {"ok":True,"path":str(path),"receipt":receipt}


def _gra_parse_command(raw: str) -> dict|None:
    clean=" ".join(str(raw or "").strip().split()); parts=clean.split(); lowered=[p.casefold() for p in parts]
    if len(parts)<2 or parts[0].casefold()!="/knowledge" or parts[1].casefold() not in {"grounding-risk","grounding-audit","risk-audit"}: return None
    reference=None; limit=_GROUNDING_RISK_DEFAULT_LIMIT; excerpt_chars=_GROUNDING_RISK_DEFAULT_EXCERPT_CHARS
    if len(parts)>=3 and not parts[2].startswith("--"): reference=parts[2]
    if "--limit" in lowered:
        idx=lowered.index("--limit")
        if idx+1>=len(parts): raise ValueError("--limit requires a positive integer.")
        limit=max(1,int(parts[idx+1]))
    if "--excerpt-chars" in lowered:
        idx=lowered.index("--excerpt-chars")
        if idx+1>=len(parts): raise ValueError("--excerpt-chars requires an integer from 200 to 4000.")
        excerpt_chars=max(200,min(4000,int(parts[idx+1])))
    if "--gpt" in lowered or "--lmstudio" in lowered:
        raise ValueError("Grounding risk audit is deterministic and read-only; provider flags are not used.")
    return {"reference":reference,"limit":limit,"excerpt_chars":excerpt_chars}


def grounding_risk_audit_self_test(module) -> dict:
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV); checks={}
    try:
        parsed=_gra_parse_command("/knowledge grounding-risk BK-TEST --limit 7 --excerpt-chars 500")
        checks["parser_surface"]=parsed=={"reference":"BK-TEST","limit":7,"excerpt_chars":500}
        low={"item_id":"KI-RISK","version_id":"KDV-X","kind":"fact","claim":"The monarch exiles the young lover from the city.","details":"The ruler sends him away.","interpretation":"direct","domain":"test","importance":0.8,"confidence":0.9,
             "source_text":"Prince Escalus says Romeo is banished from Verona.","sources":[{"ordinal":1,"source_ref":"book:BK-X:C1","locator_json":"{}","evidence_sha256":"x","excerpt_sha256":_sk_hash("Prince Escalus says Romeo is banished from Verona."),"excerpt":"Prince Escalus says Romeo is banished from Verona."}],"source_count":1,"provenance_ok":True,"claim_grounding_ratio":0.0}
        row=_gra_row(low,excerpt_chars=500)
        checks["row_keeps_canonical_id"]=row.get("item_id")=="KI-RISK"
        checks["row_exposes_exact_source_ref"]=((row.get("sources") or [{}])[0].get("source_ref")=="book:BK-X:C1")
        checks["row_hash_verified"]=bool((row.get("sources") or [{}])[0].get("hash_verified"))
        checks["flag_is_diagnostic_only"]=row.get("mutation_performed") is False and "diagnostic" in str(row.get("review_reason") or "")
        paraphrase=dict(low); paraphrase["interpretation"]="paraphrase"
        checks["paraphrase_not_in_direct_filter"]=not (str(paraphrase.get("interpretation") or "").casefold()=="direct" and float(paraphrase.get("claim_grounding_ratio") or 0.0)<_GROUNDING_RISK_THRESHOLD)
        with tempfile.TemporaryDirectory(prefix="neat-grounding-risk-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder; _sk_ensure_schema(module)
            source=_sk_upsert_source("book","BK-TEST-GRA","Synthetic grounding risk audit", "e"*64,{"kind":"test"})
            started=_sk_begin_version(source=source,scope="test",digest_mode="deep",provider="python",model_alias=None,model_id="test",operation="test",total_chunks=1)
            exact="Prince Escalus says Romeo is banished from Verona."
            proposal={"kind":"fact","claim":"The monarch exiles the young lover from the city.","details":"A ruler sends the lover away.","interpretation":"direct","domain":"test","importance":0.8,"confidence":0.9}
            with _sk_connect() as db:
                iid=_sk_store_item(db,version_id=started["version_id"],proposal=proposal,resolved_sources=[{"ref":"book:BK-TEST-GRA:C1","excerpt":exact,"chunk_id":"C1","text_sha256":_sk_hash(exact)}],source_kind="book")
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)",(started["version_id"],"C1",1,_sk_hash(exact),"completed",_sk_now()))
            _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=1,model_calls=0,items=1)
            run=_gra_run_audit(module,reference="BK-TEST-GRA",limit=10,excerpt_chars=500,print_progress=False)
            receipt=run.get("receipt") or {}; rows=receipt.get("items") or []; summary=receipt.get("summary") or {}
            checks["synthetic_audit_executes"]=bool(run.get("ok"))
            checks["synthetic_low_overlap_direct_flagged"]=len(rows)==1 and rows[0].get("item_id")==iid
            checks["synthetic_zero_model_retrieval_mutation"]=all(int(summary.get(k,-1))==0 for k in ("model_calls","retrieval_calls","database_mutations"))
            checks["synthetic_receipt_valid"]=str((receipt.get("receipt_validation") or {}).get("status"))=="PASS"
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_GROUNDING_RISK_AUDIT_VERSION}


def _install_grounding_risk_audit(module) -> None:
    if getattr(module,"_GROUNDING_RISK_AUDIT_INSTALLED",False): return
    module.GROUNDING_RISK_AUDIT_VERSION=_GROUNDING_RISK_AUDIT_VERSION
    module.run_grounding_risk_audit=lambda **kwargs:_gra_run_audit(module,**kwargs)
    module.grounding_risk_audit_self_test=lambda:grounding_risk_audit_self_test(module)
    old_help=module.print_help
    def help_with_grounding_risk(advanced=False,*args,**kwargs):
        result=old_help(advanced=advanced,*args,**kwargs)
        print("  /knowledge grounding-risk [BK-/KSB-ID] [--limit N] [--excerpt-chars N]   read-only zero-model review of low-overlap direct KIs")
        return result
    module.print_help=help_with_grounding_risk
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["grounding-risk-audit"]={"label":"Read-only zero-model-call inspection of low-overlap direct KIs with exact retained-source provenance and diagnostic-only review metadata","groups":("quick","critical","all"),"runner":"memory.grounding_risk_audit_self_test"}
    module._GROUNDING_RISK_AUDIT_INSTALLED=True

# ---------------------------------------------------------------------------
# NeatMemory 7.4.25.10.11.2 — Chunk-Boundary Canonical Visibility
# ---------------------------------------------------------------------------
_CHUNK_BOUNDARY_VISIBILITY_VERSION = "1.0-preserve-but-hide-artificial-source-boundaries"
_CB_BOUNDARY_DOMAINS = {"textual-state", "textual-continuity", "unresolved-reference"}
_CB_SCOPE_MARKERS = ("chunk", "excerpt", "extract", "supplied text", "supplied passage", "within this excerpt", "within this chunk")
_CB_STATE_MARKERS = ("unfinished", "incomplete", "unresolved", "ends before", "ends immediately", "breaks off", "supplied text ends", "extract ends", "excerpt ends")


def _cb_is_chunk_boundary_artifact(item: dict) -> bool:
    """True only for process observations about an artificial ingestion boundary.

    This deliberately does *not* classify every unresolved question.  It requires
    both a boundary-oriented domain/phrase and explicit truncation/incompletion
    language.  The KI row and exact provenance stay preserved; this predicate only
    controls normal canonical visibility.
    """
    if not isinstance(item, dict):
        return False
    domain = str(item.get("domain") or "").casefold().strip()
    text = " ".join((str(item.get("claim") or ""), str(item.get("details") or ""))).casefold()
    has_scope = domain in _CB_BOUNDARY_DOMAINS or any(marker in text for marker in _CB_SCOPE_MARKERS)
    has_state = any(marker in text for marker in _CB_STATE_MARKERS)
    # Stronger guard for unresolved-reference: it must explicitly name the local
    # excerpt/chunk boundary rather than merely being an unresolved story question.
    if domain == "unresolved-reference" and not any(marker in text for marker in _CB_SCOPE_MARKERS):
        return False
    return bool(has_scope and has_state)


def _cb_filter_rows(rows: list[dict]) -> tuple[list[dict], list[str]]:
    kept=[]; suppressed=[]
    for row in rows or []:
        d=dict(row)
        if _cb_is_chunk_boundary_artifact(d):
            suppressed.append(str(d.get("item_id") or ""))
        else:
            kept.append(row)
    return kept,[x for x in suppressed if x]


def _cb_resolve_source(reference: str|None=None) -> tuple[dict, str]:
    if reference:
        source=_sk_resolve_source(str(reference))
        if not source: raise ValueError(f"Knowledge source not found: {reference}")
        return source,"explicit"
    with _sk_connect() as db:
        rows=[dict(r) for r in db.execute("SELECT * FROM knowledge_sources WHERE active=1 AND retired=0 AND current_version_id IS NOT NULL ORDER BY updated_at DESC,source_id").fetchall()]
    if not rows: raise ValueError("No active shared-knowledge source is available.")
    if len(rows)>1: raise ValueError("Multiple active shared-knowledge sources exist; provide BK-/KSB-ID explicitly.")
    return rows[0],"single_active"


def _cb_active_items(source: dict) -> list[dict]:
    sid=str(source.get("source_id") or "")
    vid=str(source.get("current_version_id") or "")
    with _sk_connect() as db:
        rows=[dict(r) for r in db.execute("SELECT i.* FROM knowledge_items i JOIN knowledge_versions v ON v.version_id=i.version_id WHERE v.source_id=? AND i.version_id=? AND v.active=1 AND v.archive=0 AND v.status='completed' ORDER BY i.importance DESC,i.item_id",(sid,vid)).fetchall()]
    return rows


def _cb_run_audit(module, *, reference: str|None=None, limit: int=100) -> dict:
    source,selection=_cb_resolve_source(reference)
    items=_cb_active_items(source)
    flagged=[i for i in items if _cb_is_chunk_boundary_artifact(i)]
    flagged.sort(key=lambda x:(-float(x.get("importance") or 0.0),str(x.get("item_id") or "")))
    rows=[]
    for item in flagged[:max(1,min(500,int(limit or 100)))]:
        iid=str(item.get("item_id") or "")
        with _sk_connect() as db:
            sources=[dict(r) for r in db.execute("SELECT ordinal,source_ref,locator_json,evidence_sha256,excerpt_sha256 FROM knowledge_item_sources WHERE item_id=? ORDER BY ordinal",(iid,)).fetchall()]
        rows.append({
            "item_id":iid,"kind":item.get("kind"),"domain":item.get("domain"),"interpretation":item.get("interpretation"),
            "importance":item.get("importance"),"confidence":item.get("confidence"),"claim":item.get("claim"),"details":item.get("details"),
            "canonical_visibility":"suppressed_chunk_boundary","history_preserved":True,"direct_id_lookup_available":True,
            "sources":sources,"reason":"Artificial chunk/excerpt truncation observation; preserved for provenance/audit but excluded from normal canonical shared-knowledge retrieval."
        })
    return {"ok":True,"version":_CHUNK_BOUNDARY_VISIBILITY_VERSION,"source_selection":selection,
            "source":{"source_id":source.get("source_id"),"source_key":source.get("source_key"),"title":source.get("title"),"version_id":source.get("current_version_id")},
            "knowledge_items":len(items),"suppressed_count":len(flagged),"returned_items":len(rows),"items":rows,
            "model_calls":0,"database_mutations":0,"authority":"Exact retained source/KP evidence remains authoritative; suppression affects canonical KI navigation only."}


def _cb_parse_command(raw: str) -> dict:
    parts=" ".join(str(raw or "").strip().split()).split(); lowered=[p.casefold() for p in parts]
    reference=None; limit=100
    if len(parts)>=3 and not parts[2].startswith("--"): reference=parts[2]
    if "--limit" in lowered:
        idx=lowered.index("--limit");
        if idx+1>=len(parts): raise ValueError("--limit requires a positive integer.")
        limit=int(parts[idx+1]);
        if limit<1: raise ValueError("--limit must be at least 1.")
    return {"reference":reference,"limit":limit}


def chunk_boundary_visibility_self_test(module) -> dict:
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV); checks={}; details={}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-chunk-boundary-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder
            _sk_ensure_schema()
            source=_sk_upsert_source("research","TEST-CB","Chunk Boundary Test",_sk_hash("source"),{"kind":"test"})
            started=_sk_begin_version(source=source,scope="full book",digest_mode="deep",provider="python",model_alias=None,model_id="test",operation="test",total_chunks=2)
            vid=str(started["version_id"])
            exact1="Mira asks a question at the edge of a source chunk."
            exact2="The next source chunk continues with durable facts about Soren."
            with _sk_connect() as db:
                boundary=_sk_store_item(db,version_id=vid,proposal={"kind":"question","claim":"The extract ends before Mira completes her question.","details":"The supplied chunk is incomplete and the thought remains unresolved within this excerpt.","interpretation":"direct","domain":"textual-state","importance":0.8,"confidence":0.99},resolved_sources=[{"ref":"test:C1","excerpt":exact1,"snapshot_id":"C1","text_sha256":_sk_hash(exact1)}],source_kind="research")
                durable=_sk_store_item(db,version_id=vid,proposal={"kind":"fact","claim":"Soren carries the blue key.","details":"This is a durable story fact.","interpretation":"direct","domain":"plot","importance":0.9,"confidence":0.99},resolved_sources=[{"ref":"test:C2","excerpt":exact2,"snapshot_id":"C2","text_sha256":_sk_hash(exact2)}],source_kind="research")
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)",(vid,"C1",1,_sk_hash(exact1),"completed",_sk_now()))
                db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)",(vid,"C2",2,_sk_hash(exact2),"completed",_sk_now()))
            _sk_finalize_version(source["source_id"],vid,started["run_id"],processed=2,model_calls=0,items=2)
            checks["boundary_predicate_narrow"]=_cb_is_chunk_boundary_artifact({"domain":"textual-state","claim":"The extract ends before the thought is complete.","details":""}) and not _cb_is_chunk_boundary_artifact({"domain":"question","claim":"Who committed the crime remains unresolved?","details":""})
            legacy=_sk_search_items("extract ends",20)
            checks["legacy_search_suppresses_boundary"]=boundary not in [str(x.get("item_id") or "") for x in legacy.get("results") or []]
            public=_elk_search_items("extract ends",20) if callable(globals().get("_elk_search_items")) else legacy
            checks["evidence_linked_search_suppresses_boundary"]=boundary not in [str(x.get("item_id") or "") for x in public.get("results") or []]
            checks["durable_item_remains_searchable"]=durable in [str(x.get("item_id") or "") for x in _sk_search_items("soren blue key",20).get("results") or []]
            checks["direct_id_lookup_preserves_history"]=_sk_get_item(boundary).get("ok") is True
            audit=_cb_run_audit(module,reference="TEST-CB",limit=10)
            checks["audit_reports_preserved_boundary"]=audit.get("suppressed_count")==1 and (audit.get("items") or [{}])[0].get("item_id")==boundary
            checks["zero_model_zero_mutation"]=int(audit.get("model_calls",-1))==0 and int(audit.get("database_mutations",-1))==0
            details={"boundary_item_id":boundary,"durable_item_id":durable,"audit":audit}
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"details":details,"version":_CHUNK_BOUNDARY_VISIBILITY_VERSION}


def _install_chunk_boundary_canonical_visibility(module) -> None:
    if getattr(module,"_CHUNK_BOUNDARY_VISIBILITY_INSTALLED",False): return
    global _sk_search_items, _elk_search_items, _srf_relation_candidates
    previous_search=_sk_search_items
    def filtered_search(query: str, limit: int=20) -> dict:
        result=previous_search(query,max(20,int(limit or 20)*3)); kept,suppressed=_cb_filter_rows(result.get("results") or [])
        cap=max(1,min(100,int(limit or 20))); kept=kept[:cap]
        return {**result,"count":len(kept),"results":kept,"chunk_boundary_suppressed_item_ids":suppressed,"canonical_visibility_policy":_CHUNK_BOUNDARY_VISIBILITY_VERSION}
    _sk_search_items=filtered_search
    if callable(globals().get("_elk_search_items")):
        previous_elk=_elk_search_items
        def filtered_elk(query: str, limit: int=20) -> dict:
            result=previous_elk(query,max(20,int(limit or 20)*3)); kept,suppressed=_cb_filter_rows(result.get("results") or [])
            cap=max(1,min(100,int(limit or 20))); kept=kept[:cap]
            return {**result,"count":len(kept),"results":kept,"chunk_boundary_suppressed_item_ids":suppressed,"canonical_visibility_policy":_CHUNK_BOUNDARY_VISIBILITY_VERSION}
        _elk_search_items=filtered_elk
        module.search_shared_knowledge=lambda query,limit=20:_elk_search_items(query,limit)
    if callable(globals().get("_srf_relation_candidates")):
        previous_srf=_srf_relation_candidates
        def filtered_srf(query: str, limit: int=5) -> list[dict]:
            rows=previous_srf(query,limit=max(5,int(limit or 5)*3)); kept,_=_cb_filter_rows(rows); return kept[:max(1,int(limit or 5))]
        _srf_relation_candidates=filtered_srf
    module.run_chunk_boundary_audit=lambda **kwargs:_cb_run_audit(module,**kwargs)
    module.chunk_boundary_visibility_self_test=lambda:chunk_boundary_visibility_self_test(module)
    old_help=module.print_help
    def help_with_chunk_boundary(advanced=False,*args,**kwargs):
        result=old_help(advanced=advanced,*args,**kwargs)
        print("  /knowledge chunk-boundary [BK-/KSB-ID] [--limit N]   show preserved artificial chunk/excerpt boundary KIs hidden from normal canonical retrieval")
        return result
    module.print_help=help_with_chunk_boundary
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["chunk-boundary-visibility"]={"label":"Artificial chunk/excerpt boundary observations remain preserved by ID/provenance but are excluded from normal canonical shared-knowledge retrieval","groups":("quick","critical","all"),"runner":"memory.chunk_boundary_visibility_self_test"}
    module._CHUNK_BOUNDARY_VISIBILITY_INSTALLED=True


# ---------------------------------------------------------------------------
# Interpretation label audit (7.4.25.10.11.3)
# ---------------------------------------------------------------------------
_INTERPRETATION_LABEL_AUDIT_VERSION = "1.0-direct-vs-paraphrase-candidate-review"
_INTERPRETATION_LABEL_DETAILS_SUPPORT_THRESHOLD = 0.40
_INTERPRETATION_LABEL_DEFAULT_LIMIT = 50
_INTERPRETATION_LABEL_DEFAULT_EXCERPT_CHARS = 1200


def _ila_classify(item: dict) -> tuple[str,str]:
    """Classify label fit without mutating canonical knowledge.

    The classifier is intentionally conservative.  A low-overlap ``direct``
    claim is only called a *paraphrase candidate* when its own details retain
    substantial literal support in the same authoritative source excerpt and
    provenance is intact.  That is evidence of semantic compression, not an
    automatic relabel decision.  Anything weaker remains manual review.
    """
    if callable(globals().get("_cb_is_chunk_boundary_artifact")) and _cb_is_chunk_boundary_artifact(item):
        return "chunk_boundary_excluded", "Artificial source-boundary observation; handled by chunk-boundary visibility policy rather than interpretation relabeling."
    interpretation=str(item.get("interpretation") or "").casefold()
    claim_ratio=float(item.get("claim_grounding_ratio") or 0.0)
    if item.get("details_grounding_ratio") is None:
        details_terms=_dq_content_terms(item.get("details"))
        source_terms=_dq_content_terms(item.get("source_text"))
        details_ratio=(len(details_terms & source_terms)/len(details_terms)) if details_terms else 1.0
    else:
        details_ratio=float(item.get("details_grounding_ratio") or 0.0)
    if interpretation!="direct":
        return "not_direct", "Current interpretation is not direct; no direct-vs-paraphrase label review is needed."
    if claim_ratio>=_GROUNDING_RISK_THRESHOLD:
        return "direct_label_supported", f"Claim/source lexical overlap {claim_ratio:.3f} is at or above the direct-label audit threshold {_GROUNDING_RISK_THRESHOLD:.2f}."
    if bool(item.get("provenance_ok")) and int(item.get("source_count") or 0)>0 and details_ratio>=_INTERPRETATION_LABEL_DETAILS_SUPPORT_THRESHOLD:
        return "paraphrase_candidate", f"Claim wording is semantically compressed (claim/source overlap {claim_ratio:.3f}) while KI details remain strongly source-grounded ({details_ratio:.3f}); review whether interpretation should be paraphrase."
    return "weak_grounding_review", f"Both direct-claim overlap ({claim_ratio:.3f}) and/or detailed retained-source support ({details_ratio:.3f}) are too weak for deterministic paraphrase-label confidence; manual semantic review required."


def _ila_row(item: dict, *, excerpt_chars: int) -> dict:
    base=_gra_row(item,excerpt_chars=excerpt_chars)
    classification,reason=_ila_classify(item)
    recommended="paraphrase" if classification=="paraphrase_candidate" else None
    return {
        **base,
        "label_classification":classification,
        "recommended_interpretation":recommended,
        "classification_reason":reason,
        "details_support_threshold":_INTERPRETATION_LABEL_DETAILS_SUPPORT_THRESHOLD,
        "automatic_relabel":False,
        "mutation_performed":False,
        "authority":"retained source excerpt/hash remains authoritative; interpretation-label classification is diagnostic only and never rewrites the KI",
    }


def _ila_receipt_path(module, run_id: str) -> Path:
    root=Path(module.MEMORY_DIR)/"benchmarks"/"receipts"; root.mkdir(parents=True,exist_ok=True)
    return root/f"interpretation-label-audit-{run_id}.json"


def _ila_run_audit(module, *, reference: str|None=None, limit: int=_INTERPRETATION_LABEL_DEFAULT_LIMIT,
                   excerpt_chars: int=_INTERPRETATION_LABEL_DEFAULT_EXCERPT_CHARS, print_progress: bool=True) -> dict:
    started=_sk_now(); run_id=datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")+"-"+uuid.uuid4().hex[:8]
    source,selection=_dq_resolve_source(reference)
    items=_dq_load_items(source)
    boundary=[i for i in items if callable(globals().get("_cb_is_chunk_boundary_artifact")) and _cb_is_chunk_boundary_artifact(i)]
    targets=[]
    for item in items:
        if item in boundary: continue
        if str(item.get("interpretation") or "").casefold()!="direct": continue
        if float(item.get("claim_grounding_ratio") or 0.0)>=_GROUNDING_RISK_THRESHOLD: continue
        targets.append(item)
    targets.sort(key=lambda i:(float(i.get("claim_grounding_ratio") or 0.0),-float(i.get("details_grounding_ratio") or 0.0),str(i.get("item_id") or "")))
    classifications=[(_ila_classify(i)[0],i) for i in targets]
    cap=max(1,min(100,int(limit or _INTERPRETATION_LABEL_DEFAULT_LIMIT)))
    selected=targets[:cap]
    rows=[_ila_row(i,excerpt_chars=excerpt_chars) for i in selected]
    summary={
        "knowledge_items":len(items),
        "low_overlap_direct_items":len(targets),
        "returned_items":len(rows),
        "chunk_boundary_excluded":len(boundary),
        "paraphrase_candidates":sum(1 for c,_ in classifications if c=="paraphrase_candidate"),
        "weak_grounding_review":sum(1 for c,_ in classifications if c=="weak_grounding_review"),
        "provenance_failures":sum(1 for i in targets if not i.get("provenance_ok")),
        "claim_overlap_threshold":_GROUNDING_RISK_THRESHOLD,
        "details_support_threshold":_INTERPRETATION_LABEL_DETAILS_SUPPORT_THRESHOLD,
        "model_calls":0,"retrieval_calls":0,"database_mutations":0,"automatic_relabels":0,
    }
    receipt={
        "audit":{"name":"interpretation_label_audit","version":_INTERPRETATION_LABEL_AUDIT_VERSION,"run_id":run_id,"started_at":started,"finished_at":_sk_now(),"mode":"active_digest_read_only_zero_model_zero_retrieval","source_selection":selection},
        "source":{"source_id":source.get("source_id"),"source_key":source.get("source_key"),"title":source.get("title"),"version_id":source.get("current_version_id")},
        "summary":summary,"items":rows,
        "rule":"Among non-boundary KIs currently labeled direct with claim/source overlap below 0.25, mark paraphrase_candidate only when provenance is intact and KI details retain at least 0.40 lexical support in the KI-owned source excerpt; otherwise keep weak_grounding_review. Classification is diagnostic, not an automatic relabel.",
        "authority":"Exact retained KI source excerpts and hashes remain authoritative. This audit performs no relabeling, rewriting, archiving, creation, retrieval, or model call.",
        "receipt_validation":{"status":"PASS","errors":[],"validator":"neatmemory_interpretation_label_audit_receipt_v1","note":"Receipt PASS means the read-only audit executed completely; paraphrase_candidate is a label-review recommendation, not a source-truth verdict."},
    }
    path=_ila_receipt_path(module,run_id); _ska_atomic_write(module,path,receipt)
    if print_progress:
        print(f"[interpretation label] {len(targets)} low-overlap direct / {len(items)} KIs | paraphrase-candidate={summary['paraphrase_candidates']} | weak-review={summary['weak_grounding_review']} | boundary-excluded={summary['chunk_boundary_excluded']} | 0 model calls | read-only",flush=True)
        for idx,row in enumerate(rows,1):
            print(f"[{idx:02d}/{len(rows):02d}] {row['item_id']} | {row['label_classification']} | claim={row['claim_grounding_ratio']:.4f} details={row['details_grounding_ratio']:.4f} | provenance {'PASS' if row['provenance_ok'] else 'FAIL'} | {row['claim'][:170]}",flush=True)
        print(f"[interpretation label] receipt: {path}",flush=True)
    return {"ok":True,"path":str(path),"receipt":receipt}


def _ila_parse_command(raw: str) -> dict|None:
    clean=" ".join(str(raw or "").strip().split()); parts=clean.split(); lowered=[p.casefold() for p in parts]
    if len(parts)<2 or parts[0].casefold()!="/knowledge" or parts[1].casefold() not in {"interpretation-audit","interpretation-label","label-audit","direct-paraphrase-audit"}: return None
    reference=None; limit=_INTERPRETATION_LABEL_DEFAULT_LIMIT; excerpt_chars=_INTERPRETATION_LABEL_DEFAULT_EXCERPT_CHARS
    if len(parts)>=3 and not parts[2].startswith("--"): reference=parts[2]
    if "--limit" in lowered:
        idx=lowered.index("--limit")
        if idx+1>=len(parts): raise ValueError("--limit requires a positive integer.")
        limit=max(1,int(parts[idx+1]))
    if "--excerpt-chars" in lowered:
        idx=lowered.index("--excerpt-chars")
        if idx+1>=len(parts): raise ValueError("--excerpt-chars requires an integer from 200 to 4000.")
        excerpt_chars=max(200,min(4000,int(parts[idx+1])))
    if "--gpt" in lowered or "--lmstudio" in lowered:
        raise ValueError("Interpretation label audit is deterministic and read-only; provider flags are not used.")
    return {"reference":reference,"limit":limit,"excerpt_chars":excerpt_chars}


def interpretation_label_audit_self_test(module) -> dict:
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV); checks={}
    try:
        checks["parser_surface"]=_ila_parse_command("/knowledge interpretation-audit BK-TEST --limit 7 --excerpt-chars 500")=={"reference":"BK-TEST","limit":7,"excerpt_chars":500}
        candidate={"item_id":"KI-P","interpretation":"direct","claim_grounding_ratio":0.10,"details_grounding_ratio":0.60,"provenance_ok":True,"source_count":1,"claim":"A semantically compressed claim.","details":"Mira carries the blue key.","sources":[]}
        weak={**candidate,"item_id":"KI-W","details_grounding_ratio":0.10}
        checks["classifier_paraphrase_candidate"]=_ila_classify(candidate)[0]=="paraphrase_candidate"
        checks["classifier_weak_review"]=_ila_classify(weak)[0]=="weak_grounding_review"
        with tempfile.TemporaryDirectory(prefix="neat-interpretation-label-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder; _sk_ensure_schema(module)
            source=_sk_upsert_source("book","BK-TEST-ILA","Synthetic interpretation label audit","f"*64,{"kind":"test"})
            started=_sk_begin_version(source=source,scope="test",digest_mode="deep",provider="python",model_alias=None,model_id="test",operation="test",total_chunks=3)
            c1="Prince Escalus says Romeo is banished from Verona."
            c2="Soren carries the blue key."
            c3="Mira begins to ask Nola a question."
            with _sk_connect() as db:
                p=_sk_store_item(db,version_id=started["version_id"],proposal={"kind":"fact","claim":"The monarch exiles the young lover from the city.","details":"Prince Escalus says Romeo is banished from Verona.","interpretation":"direct","domain":"test","importance":0.8,"confidence":0.99},resolved_sources=[{"ref":"book:BK-TEST-ILA:C1","excerpt":c1,"chunk_id":"C1","text_sha256":_sk_hash(c1)}],source_kind="book")
                w=_sk_store_item(db,version_id=started["version_id"],proposal={"kind":"fact","claim":"The political decision transforms social identity.","details":"A consequence follows.","interpretation":"direct","domain":"test","importance":0.7,"confidence":0.9},resolved_sources=[{"ref":"book:BK-TEST-ILA:C2","excerpt":c2,"chunk_id":"C2","text_sha256":_sk_hash(c2)}],source_kind="book")
                b=_sk_store_item(db,version_id=started["version_id"],proposal={"kind":"question","claim":"The excerpt ends before Mira completes her question.","details":"The supplied chunk is incomplete and the thought remains unresolved within this excerpt.","interpretation":"direct","domain":"textual-state","importance":0.7,"confidence":0.99},resolved_sources=[{"ref":"book:BK-TEST-ILA:C3","excerpt":c3,"chunk_id":"C3","text_sha256":_sk_hash(c3)}],source_kind="book")
                for n,txt in (("C1",c1),("C2",c2),("C3",c3)):
                    db.execute("INSERT INTO knowledge_version_chunks(version_id,chunk_id,ordinal,text_sha256,status,completed_at) VALUES(?,?,?,?,?,?)",(started["version_id"],n,int(n[1:]),_sk_hash(txt),"completed",_sk_now()))
            _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=3,model_calls=0,items=3)
            result=_ila_run_audit(module,reference="BK-TEST-ILA",limit=10,excerpt_chars=500,print_progress=False)
            receipt=result.get("receipt") or {}; summary=receipt.get("summary") or {}; rows=receipt.get("items") or []
            byid={r.get("item_id"):r for r in rows}
            checks["synthetic_executes"]=bool(result.get("ok"))
            checks["candidate_detected"]=byid.get(p,{}).get("label_classification")=="paraphrase_candidate"
            checks["weak_detected"]=byid.get(w,{}).get("label_classification")=="weak_grounding_review"
            checks["boundary_excluded"]=b not in byid and int(summary.get("chunk_boundary_excluded") or 0)==1
            checks["no_mutation_model_retrieval"]=int(summary.get("model_calls",-1))==0 and int(summary.get("retrieval_calls",-1))==0 and int(summary.get("database_mutations",-1))==0 and int(summary.get("automatic_relabels",-1))==0
            checks["receipt_valid"]=(receipt.get("receipt_validation") or {}).get("status")=="PASS"
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_INTERPRETATION_LABEL_AUDIT_VERSION}


def _install_interpretation_label_audit(module) -> None:
    if getattr(module,"_INTERPRETATION_LABEL_AUDIT_INSTALLED",False): return
    module.INTERPRETATION_LABEL_AUDIT_VERSION=_INTERPRETATION_LABEL_AUDIT_VERSION
    module.run_interpretation_label_audit=lambda **kwargs:_ila_run_audit(module,**kwargs)
    module.interpretation_label_audit_self_test=lambda:interpretation_label_audit_self_test(module)
    old_help=module.print_help
    def help_with_interpretation_label(advanced=False,*args,**kwargs):
        result=old_help(advanced=advanced,*args,**kwargs)
        print("  /knowledge interpretation-audit [BK-/KSB-ID] [--limit N] [--excerpt-chars N]   read-only direct-vs-paraphrase label-fit audit for low-overlap KIs")
        return result
    module.print_help=help_with_interpretation_label
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["interpretation-label-audit"]={"label":"Read-only zero-model audit of low-overlap direct KIs into paraphrase-label candidates versus weak-grounding review cases","groups":("quick","critical","all"),"runner":"memory.interpretation_label_audit_self_test"}
    module._INTERPRETATION_LABEL_AUDIT_INSTALLED=True


def _sk_history(reference: str) -> dict:
    source=_sk_resolve_source(reference)
    if not source: return {"ok":False,"error":f"Knowledge source not found: {reference}"}
    with _sk_connect() as db:
        versions=[dict(r) for r in db.execute("SELECT version_id,version_number,status,active,archive,previous_version_id,supersedes_version_id,scope,digest_mode,provider,model_alias,model_id,run_id,started_at,completed_at FROM knowledge_versions WHERE source_id=? ORDER BY version_number DESC",(source["source_id"],)).fetchall()]
    return {"ok":True,"source":source,"versions":versions}


def _sk_retire(reference: str) -> dict:
    source=_sk_resolve_source(reference)
    if not source: return {"ok":False,"error":f"Knowledge source not found: {reference}"}
    with _sk_connect() as db: db.execute("UPDATE knowledge_sources SET active=0,retired=1,updated_at=? WHERE source_id=?",(_sk_now(),source["source_id"]))
    _sk_event("knowledge_source_retired",{"reference":reference},source_id=source["source_id"])
    return {"ok":True,"source_id":source["source_id"],"active":False,"retired":True,"history_preserved":True}


def _sk_restore(reference: str) -> dict:
    source=_sk_resolve_source(reference)
    if not source: return {"ok":False,"error":f"Knowledge source not found: {reference}"}
    with _sk_connect() as db: db.execute("UPDATE knowledge_sources SET active=1,retired=0,updated_at=? WHERE source_id=?",(_sk_now(),source["source_id"]))
    _sk_event("knowledge_source_restored",{"reference":reference},source_id=source["source_id"])
    return {"ok":True,"source_id":source["source_id"],"active":True,"retired":False}


def _sk_replace(old_ref: str, new_ref: str) -> dict:
    old=_sk_resolve_source(old_ref); new=_sk_resolve_source(new_ref)
    if not old or not new: return {"ok":False,"error":"Both old and new knowledge sources must exist."}
    with _sk_connect() as db:
        db.execute("UPDATE knowledge_sources SET active=0,retired=1,updated_at=? WHERE source_id=?",(_sk_now(),old["source_id"]))
        db.execute("INSERT OR IGNORE INTO knowledge_source_relations(from_source_id,relation,to_source_id,created_at) VALUES(?,?,?,?)",(old["source_id"],"superseded_by",new["source_id"],_sk_now()))
        db.execute("INSERT OR IGNORE INTO knowledge_source_relations(from_source_id,relation,to_source_id,created_at) VALUES(?,?,?,?)",(new["source_id"],"supersedes",old["source_id"],_sk_now()))
    return {"ok":True,"old_source_id":old["source_id"],"new_source_id":new["source_id"],"old_active":False,"relation":"superseded_by"}


def _sk_purge_preview(reference: str) -> dict:
    source=_sk_resolve_source(reference)
    if not source: return {"ok":False,"error":f"Knowledge source not found: {reference}"}
    with _sk_connect() as db:
        sid=source["source_id"]
        counts={"versions":int(db.execute("SELECT COUNT(*) FROM knowledge_versions WHERE source_id=?",(sid,)).fetchone()[0]),"items":int(db.execute("SELECT COUNT(*) FROM knowledge_items i JOIN knowledge_versions v ON v.version_id=i.version_id WHERE v.source_id=?",(sid,)).fetchone()[0]),"passages":int(db.execute("SELECT COUNT(*) FROM knowledge_passages WHERE source_id=?",(sid,)).fetchone()[0]),"terms":int(db.execute("SELECT COUNT(*) FROM knowledge_terms t JOIN knowledge_passages p ON p.passage_id=t.passage_id WHERE p.source_id=?",(sid,)).fetchone()[0])}
        preview={"source_id":sid,"source_key":source["source_key"],"title":source["title"],**counts,"warning":"PURGE permanently deletes the shared knowledge package/index/history for this source. The original NeatBooks/source file is not deleted by this command."}
        token="PURGE-"+uuid.uuid4().hex[:12].upper(); expires=(datetime.now(timezone.utc)+timedelta(minutes=10)).isoformat(timespec="seconds")
        sha=_sk_hash(_sk_json(preview)); db.execute("DELETE FROM knowledge_purge_tokens WHERE source_id=?",(sid,)); db.execute("INSERT INTO knowledge_purge_tokens(token,source_id,created_at,expires_at,preview_sha256) VALUES(?,?,?,?,?)",(token,sid,_sk_now(),expires,sha))
    return {"ok":True,"preview":preview,"confirmation_token":token,"expires_at":expires,"confirm_command":f"/knowledge purge {sid} --confirm {token}"}


def _sk_purge_confirm(reference: str, token: str) -> dict:
    source=_sk_resolve_source(reference)
    if not source: return {"ok":False,"error":f"Knowledge source not found: {reference}"}
    with _sk_connect() as db:
        row=db.execute("SELECT * FROM knowledge_purge_tokens WHERE token=? AND source_id=?",(token,source["source_id"])).fetchone()
        if not row: return {"ok":False,"error":"Valid purge confirmation token not found."}
        if datetime.fromisoformat(str(row["expires_at"])) < datetime.now(timezone.utc): return {"ok":False,"error":"Purge confirmation token expired."}
        db.execute("DELETE FROM knowledge_source_relations WHERE from_source_id=? OR to_source_id=?",(source["source_id"],source["source_id"]))
        db.execute("DELETE FROM knowledge_events WHERE source_id=?",(source["source_id"],))
        db.execute("DELETE FROM knowledge_runs WHERE source_id=?",(source["source_id"],))
        db.execute("DELETE FROM knowledge_sources WHERE source_id=?",(source["source_id"],))
        db.execute("DELETE FROM knowledge_purge_tokens WHERE source_id=?",(source["source_id"],))
    return {"ok":True,"purged":True,"source_id":source["source_id"],"note":"Shared digest/index/history removed. Original book/research source files were not deleted."}


def _sk_book_progress(digest_module, book_id: str) -> dict:
    try:
        book_id=digest_module.books.resolve_book_reference(str(book_id))
        with digest_module.books.connect() as bdb:
            rows=bdb.execute("SELECT chunk_id,text_sha256 FROM book_chunks WHERE book_id=?",(book_id,)).fetchall()
        total=len(rows); current={(str(r["chunk_id"]),str(r["text_sha256"])) for r in rows}
        source=_sk_resolve_source(book_id)
        completed=set()
        if source and source.get("current_version_id"):
            with _sk_connect() as db:
                completed={(str(r["chunk_id"]),str(r["text_sha256"])) for r in db.execute("SELECT chunk_id,text_sha256 FROM knowledge_version_chunks WHERE version_id=? AND status='completed'",(source["current_version_id"],)).fetchall()}
        done=len(current & completed)
        return {"completed_chunks":done,"total_chunks":total,"pending_chunks":max(0,total-done),"percent":round((done/total*100.0) if total else 0.0,1),"complete":bool(total) and done==total}
    except Exception:
        return {"completed_chunks":0,"total_chunks":0,"pending_chunks":0,"percent":0.0,"complete":False}


def _sk_migrate_legacy(module, archive_personal: bool=False) -> dict:
    """Copy old external derived memories into the shared store. No deletion.

    archive_personal=True marks only book/research/learn-derived legacy rows archived
    after they have been copied; personal identity/experience memories are untouched.
    """
    _sk_ensure_schema(module)
    with module.db_connect() as db:
        rows=db.execute("SELECT id,summary,data,confidence,interpretation,payload_json FROM memories ORDER BY created_at").fetchall()
    grouped={}; skipped=0
    for row in rows:
        try: payload=json.loads(row["payload_json"] or "{}")
        except Exception: skipped+=1; continue
        origin=str(payload.get("origin") or "")
        if origin not in _SHARED_KNOWLEDGE_EXTERNAL_ORIGINS: continue
        if origin=="book_digest": key=("book",str(payload.get("book_id") or ""),str(payload.get("book_title") or payload.get("book_id") or "book"))
        else: key=("research",str(payload.get("research_run_id") or payload.get("learn_run_id") or "legacy-research"),str(payload.get("research_run_id") or payload.get("learn_run_id") or "research"))
        grouped.setdefault(key,[]).append((row,payload))
    migrated_items=0; migrated_sources=0; archived=0
    for (kind,key,title),items in grouped.items():
        if not key: continue
        source_hash=_sk_hash(key); source=_sk_upsert_source(kind,key,title,source_hash,{"kind":"legacy_migration","source_key":key})
        current=_sk_current_version(source["source_id"])
        if current: continue
        started=_sk_begin_version(source=source,scope="legacy migrated digest",digest_mode="migration",provider="python",model_alias=None,model_id=BUNDLE_VERSION,operation="legacy_migration",total_chunks=0)
        with _sk_connect() as kdb:
            for row,payload in items:
                sources=payload.get("sources") if isinstance(payload.get("sources"),list) else []
                proposal={"kind":payload.get("kind") or payload.get("type") or "fact","claim":row["summary"],"details":row["data"],"interpretation":row["interpretation"],"domain":payload.get("domain") or "general","confidence":row["confidence"],"importance":0.65}
                iid=_sk_store_item(kdb,version_id=started["version_id"],proposal=proposal,resolved_sources=sources or [{"ref":"legacy:"+str(row["id"]),"excerpt":str(row["summary"])}],source_kind=kind,metadata={"legacy_memory_id":str(row["id"])})
                if iid: migrated_items+=1
        _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=0,model_calls=0,items=len(items),stats={"legacy":True}); migrated_sources+=1
        if archive_personal:
            ids=[str(r[0]["id"]) for r in items]; placeholders=",".join("?" for _ in ids)
            with module.db_connect() as db:
                db.execute(f"UPDATE memories SET state='archived',temporal_status='historical',modified_at=? WHERE id IN ({placeholders})",[_sk_now(),*ids]); archived+=len(ids)
    return {"ok":True,"migrated_sources":migrated_sources,"migrated_items":migrated_items,"archived_personal_legacy_rows":archived,"archive_personal":bool(archive_personal),"skipped":skipped}


def _sk_shared_tools_install(module) -> None:
    schemas=[
        {"type":"function","function":{"name":"search_shared_knowledge","description":"Search active entity-neutral book/research knowledge. Shared knowledge is source-grounded and separate from personal identity memory.","parameters":{"type":"object","properties":{"query":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["query"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"search_shared_evidence","description":"Strict AND/co-occurrence search over active shared evidence passages, including uncertainty-labeled inferred entities.","parameters":{"type":"object","properties":{"query":{"type":"string"},"scope":{"type":"string","enum":["passage","digest","document"]},"include_inferred":{"type":"boolean"},"min_confidence":{"type":"number","minimum":0,"maximum":1},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["query"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_shared_evidence_passage","description":"Read one shared knowledge evidence passage and optionally verify the original retained book span.","parameters":{"type":"object","properties":{"passage_id":{"type":"string"},"include_original":{"type":"boolean"}},"required":["passage_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_shared_knowledge_item","description":"Read one versioned shared knowledge item with its exact source evidence and model/version provenance.","parameters":{"type":"object","properties":{"item_id":{"type":"string"}},"required":["item_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_shared_provenance","description":"Open exactly one canonical KP- evidence passage or KI- knowledge item by its full identifier. Returns stored binding fields and, for book KP objects, the exact retained source span plus mechanical hash comparison. Read-only, zero-model, and does not enumerate the whole Knowledge Pyramid.","parameters":{"type":"object","properties":{"reference":{"type":"string"},"include_original":{"type":"boolean"}},"required":["reference"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_shared_knowledge_status","description":"Read shared book/research knowledge-store status and active/archive counts.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
    ]
    existing={_adaptive_tool_name(x) for x in module.TOOL_SCHEMAS}
    module.TOOL_SCHEMAS.extend([x for x in schemas if _adaptive_tool_name(x) not in existing])
    if isinstance(getattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST",None),set): module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"search_shared_knowledge","search_shared_evidence","get_shared_evidence_passage","get_shared_knowledge_item","read_shared_provenance","get_shared_knowledge_status"})
    old_execute=module.execute_tool
    def execute_shared(name,arguments,seen,*,allow_sticky,sticky_state):
        if name=="search_shared_knowledge": return _sk_search_items(**arguments)
        if name=="search_shared_evidence": return _sk_search_passages(**arguments)
        if name=="get_shared_evidence_passage": return _sk_get_passage(**arguments)
        if name=="get_shared_knowledge_item": return _sk_get_item(**arguments)
        if name=="read_shared_provenance": return _sk_read_provenance_ref(**arguments)
        if name=="get_shared_knowledge_status": return _sk_status(module)
        return old_execute(name,arguments,seen,allow_sticky=allow_sticky,sticky_state=sticky_state)
    module.execute_tool=execute_shared
    books_group=list(_ADAPTIVE_TOOL_GROUPS.get("books",()));
    for n in ("search_shared_knowledge","search_shared_evidence","get_shared_evidence_passage","read_shared_provenance"):
        if n not in books_group: books_group.insert(0,n)
    _ADAPTIVE_TOOL_GROUPS["books"]=tuple(books_group)
    research_group=list(_ADAPTIVE_TOOL_GROUPS.get("research",()));
    for n in ("search_shared_knowledge","search_shared_evidence","get_shared_knowledge_status"):
        if n not in research_group: research_group.insert(0,n)
    _ADAPTIVE_TOOL_GROUPS["research"]=tuple(research_group)

    # The online Responses surface is assembled before shared knowledge. Add one
    # compact exact-ID reader here and wrap the online dispatcher at call time.
    online_schema={
        "type":"function","name":"read_shared_provenance",
        "description":"Open exactly one canonical KP- evidence passage or KI- knowledge item by its full identifier. Returns the persisted binding and bounded retained source evidence without loading a whole book pyramid. Read-only, local, zero-model.",
        "parameters":{"type":"object","properties":{"reference":{"type":"string"},"include_original":{"type":"boolean"}},"required":["reference"],"additionalProperties":False},
        "strict":False,
    }
    online_tools=globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS")
    if isinstance(online_tools,list) and not any(str(x.get("name") or "")=="read_shared_provenance" for x in online_tools if isinstance(x,dict)):
        online_tools.append(online_schema)
    previous_online=globals().get("_ora_execute_evidence_tool")
    if callable(previous_online) and not globals().get("_SHARED_PROVENANCE_ONLINE_WRAPPED"):
        def execute_online_shared_provenance(mod,name,arguments):
            if str(name or "")=="read_shared_provenance":
                args=dict(arguments or {}) if isinstance(arguments,dict) else {}
                return _ora_clean_result(mod,_sk_read_provenance_ref(str(args.get("reference") or ""),bool(args.get("include_original",True))))
            return previous_online(mod,name,arguments)
        globals()["_ora_execute_evidence_tool"]=execute_online_shared_provenance
        globals()["_SHARED_PROVENANCE_ONLINE_WRAPPED"]=True


def _sk_dispatch_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    if lower=="/gpt" or lower=="/gpt status": print(json.dumps(_sk_gpt_status(module),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/gpt "):
        print(json.dumps(_sk_set_model_alias(module,clean.split(maxsplit=1)[1]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge chunk-boundary") or lower.startswith("/knowledge boundary-artifacts"):
        options=_cb_parse_command(clean)
        runner=getattr(module,"run_chunk_boundary_audit",None)
        if callable(runner):
            result=runner(**options); print(json.dumps(result,ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge interpretation-audit") or lower.startswith("/knowledge interpretation-label") or lower.startswith("/knowledge label-audit") or lower.startswith("/knowledge direct-paraphrase-audit"):
        options=_ila_parse_command(clean)
        runner=getattr(module,"run_interpretation_label_audit",None)
        if callable(runner):
            result=runner(**options); receipt=result.get("receipt") or {}
            compact={"ok":result.get("ok"),"path":result.get("path"),"audit":receipt.get("audit"),"source":receipt.get("source"),"summary":receipt.get("summary"),"items":receipt.get("items"),"rule":receipt.get("rule"),"authority":receipt.get("authority"),"receipt_validation":receipt.get("receipt_validation")}
            print(json.dumps(compact,ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge grounding-risk") or lower.startswith("/knowledge grounding-audit") or lower.startswith("/knowledge risk-audit"):
        options=_gra_parse_command(clean)
        runner=getattr(module,"run_grounding_risk_audit",None)
        if callable(runner):
            result=runner(**options); receipt=result.get("receipt") or {}
            compact={"ok":result.get("ok"),"path":result.get("path"),"audit":receipt.get("audit"),"source":receipt.get("source"),"summary":receipt.get("summary"),"items":receipt.get("items"),"rule":receipt.get("rule"),"authority":receipt.get("authority"),"receipt_validation":receipt.get("receipt_validation")}
            print(json.dumps(compact,ensure_ascii=False,indent=2)); return True
    if lower.startswith("/benchmark digestion") or lower.startswith("/benchmark deep-digestion") or lower.startswith("/benchmark digestion-quality"):
        options=_dq_parse_command(clean)
        runner=getattr(module,"run_deep_digestion_quality_benchmark",None)
        if callable(runner):
            result=runner(**options); receipt=result.get("receipt") or {}
            compact={"ok":result.get("ok"),"path":result.get("path"),"benchmark":receipt.get("benchmark"),"source":receipt.get("source"),"summary":receipt.get("summary"),"receipt_validation":receipt.get("receipt_validation")}
            print(json.dumps(compact,ensure_ascii=False,indent=2)); return True
    if lower.startswith("/benchmark shared-knowledge") or lower.startswith("/benchmark shared ") or lower.startswith("/benchmark knowledge-accuracy") or lower in {"/benchmark shared", "/benchmark knowledge-accuracy"}:
        parser = globals().get("_ska_parse_command")
        runner = getattr(module, "run_shared_knowledge_accuracy_benchmark", None)
        if callable(parser) and callable(runner):
            options = parser(module, clean)
            result = runner(**options)
            receipt = result.get("receipt") or {}
            compact = {"ok": result.get("ok"), "path": result.get("path"), "benchmark": receipt.get("benchmark"), "summary": receipt.get("summary"), "receipt_validation": receipt.get("receipt_validation")}
            print(json.dumps(compact, ensure_ascii=False, indent=2)); return True
    if lower=="/knowledge" or lower=="/knowledge status": print(json.dumps(_sk_status(module),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge search "): print(json.dumps(_sk_search_items(clean[len("/knowledge search "):],30),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge show "): print(json.dumps(_sk_get_item(clean[len("/knowledge show "):]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge evidence "): print(json.dumps(_sk_search_passages(clean[len("/knowledge evidence "):],"passage",True,0.6,30),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge history "): print(json.dumps(_sk_history(clean[len("/knowledge history "):]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge retire "): print(json.dumps(_sk_retire(clean[len("/knowledge retire "):]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge restore "): print(json.dumps(_sk_restore(clean[len("/knowledge restore "):]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge replace "):
        parts=clean.split();
        if len(parts)<4: raise ValueError("Use /knowledge replace <old> <new>.")
        print(json.dumps(_sk_replace(parts[2],parts[3]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge purge "):
        parts=clean.split(); ref=parts[2] if len(parts)>2 else ""
        if "--confirm" in parts:
            idx=parts.index("--confirm"); token=parts[idx+1] if idx+1<len(parts) else ""; result=_sk_purge_confirm(ref,token)
        else: result=_sk_purge_preview(ref)
        print(json.dumps(result,ensure_ascii=False,indent=2)); return True
    if lower.startswith("/knowledge migrate"):
        archive_personal="--archive-personal" in lower
        print(json.dumps(_sk_migrate_legacy(module,archive_personal=archive_personal),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/redigest history "): print(json.dumps(_sk_history(clean[len("/redigest history "):]),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/redigest "):
        tokens=clean.split(); lowered=[x.casefold() for x in tokens]
        # Provider-prefix compatibility: mirror normal /digest local|online book ...
        # while preserving the established /redigest <BK-ID> [flags] form.
        provider_prefix=None
        if len(tokens)>=4 and lowered[1] in {"online","local","lmstudio"} and lowered[2]=="book":
            provider_prefix=lowered[1]
            tokens=[tokens[0],tokens[3],*tokens[4:]]; lowered=[x.casefold() for x in tokens]
        elif len(tokens)>=3 and lowered[1]=="book":
            tokens=[tokens[0],tokens[2],*tokens[3:]]; lowered=[x.casefold() for x in tokens]
        # Historical help advertised --online; make it authoritative rather than ignored.
        online_flag="--online" in lowered
        if online_flag:
            tokens=[x for x in tokens if x.casefold()!="--online"]; lowered=[x.casefold() for x in tokens]
        ref=tokens[1]; deep="--deep" in lowered; force_full="--force" in lowered
        explicit_gpt="--gpt" in lowered
        if provider_prefix in {"local","lmstudio"} and (explicit_gpt or online_flag):
            raise ValueError("Choose either local/LM Studio or online/GPT for /redigest, not both.")
        if provider_prefix=="online" and "--lmstudio" in lowered:
            raise ValueError("Choose either online/GPT or LM Studio for /redigest, not both.")
        use_lm=("--lmstudio" in lowered) or provider_prefix in {"local","lmstudio"}
        gpt_alias=None
        if explicit_gpt:
            idx=lowered.index("--gpt")
            if idx+1>=len(tokens): raise ValueError("--gpt requires luna, terra, or sol.")
            gpt_alias=tokens[idx+1].casefold(); use_lm=False
        elif provider_prefix=="online" or online_flag:
            gpt_alias=_sk_model_alias(module); use_lm=False
        elif provider_prefix not in {"local","lmstudio"} and "--lmstudio" not in lowered:
            use_lm=True
        if "--lmstudio" in lowered and explicit_gpt: raise ValueError("Choose either --lmstudio or --gpt <alias>, not both.")
        test_chunks=0
        if "--test-chunks" in lowered:
            if force_full: raise ValueError("--force requests a full redigest and cannot be combined with --test-chunks.")
            if not deep: raise ValueError("--test-chunks requires --deep.")
            idx=lowered.index("--test-chunks")
            if idx+1>=len(tokens): raise ValueError("--test-chunks requires a number (1-5).")
            test_chunks=max(1,min(_DEEP_TEST_CHUNKS_MAX,int(tokens[idx+1])))
        digest=_load_digest_for_memory(module); backend,provider,alias=_sk_backend(digest,module,use_lmstudio=use_lm,gpt_alias=gpt_alias)
        if test_chunks:
            result=_sk_deep_test_book(digest,module,backend,ref,count=test_chunks,model_alias=alias)
        else:
            result=_sk_digest_book(digest,module,backend,ref,[],operation="redigest",deep=deep,model_alias=alias,force_full=force_full)
        print(json.dumps(result,ensure_ascii=False,indent=2)); return True
    return False


def redigest_provider_syntax_self_test(module=None) -> dict:
    """Deterministic parser contract: /redigest provider prefixes mirror /digest."""
    # Exercise the normalization conditions without constructing any model/backend.
    alias=_sk_model_alias(module) if module is not None else "luna"
    def normalize(command: str) -> dict:
        tokens=" ".join(command.strip().split()).split(); lowered=[x.casefold() for x in tokens]; provider_prefix=None
        if len(tokens)>=4 and lowered[1] in {"online","local","lmstudio"} and lowered[2]=="book":
            provider_prefix=lowered[1]; tokens=[tokens[0],tokens[3],*tokens[4:]]; lowered=[x.casefold() for x in tokens]
        elif len(tokens)>=3 and lowered[1]=="book":
            tokens=[tokens[0],tokens[2],*tokens[3:]]; lowered=[x.casefold() for x in tokens]
        online_flag="--online" in lowered
        if online_flag:
            tokens=[x for x in tokens if x.casefold()!="--online"]; lowered=[x.casefold() for x in tokens]
        explicit_gpt="--gpt" in lowered
        use_lm=("--lmstudio" in lowered) or provider_prefix in {"local","lmstudio"}
        chosen_alias=None
        if explicit_gpt:
            idx=lowered.index("--gpt"); chosen_alias=tokens[idx+1].casefold(); use_lm=False
        elif provider_prefix=="online" or online_flag:
            chosen_alias=alias; use_lm=False
        elif provider_prefix not in {"local","lmstudio"} and "--lmstudio" not in lowered:
            use_lm=True
        return {"ref":tokens[1],"use_lm":use_lm,"alias":chosen_alias}
    bk="BK-d020f7dfe8fbd902"
    a=normalize(f"/redigest online book {bk}")
    b=normalize(f"/redigest local book {bk}")
    c=normalize(f"/redigest {bk} --online")
    d=normalize(f"/redigest {bk} --gpt terra")
    e=normalize(f"/redigest {bk}")
    checks={
        "online_prefix_preserves_bk":a["ref"]==bk,
        "online_prefix_uses_gpt":a["use_lm"] is False and bool(a["alias"]),
        "local_prefix_preserves_bk":b["ref"]==bk,
        "local_prefix_uses_lmstudio":b["use_lm"] is True,
        "online_flag_uses_gpt":c["use_lm"] is False and bool(c["alias"]),
        "explicit_gpt_alias_preserved":d["alias"]=="terra" and d["use_lm"] is False,
        "legacy_default_remains_local":e["use_lm"] is True,
    }
    return {"ok":all(checks.values()),"checks":checks,"version":"1.0-redigest-provider-prefix-compatibility","model_calls":0,"network_calls":0}


def epub_spine_order_self_test(module=None) -> dict:
    """Isolated regression for legacy NeatBooks EPUB import order/provenance."""
    import zipfile
    module = module or _load_memory()
    books = getattr(module, "neatbooks", None) or sys.modules.get("neatbooks_v1_2_stable")
    if books is None:
        return {"ok": False, "checks": {"neatbooks_available": False}}
    attrs = ("MEMORY_DIR","DB_FILE","BOOK_DIR","PENDING_DIR","ARCHIVE_DIR","LEGACY_PENDING_DIR","LEGACY_ARCHIVE_DIR")
    saved = {name:getattr(books,name,None) for name in attrs}
    saved_init = set(getattr(books,"_INITIALIZED_DB_KEYS",set()))
    checks = {}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-epub-spine-") as folder:
            root=Path(folder)
            books.MEMORY_DIR=root; books.DB_FILE="neatbooks-test.sqlite"; books.BOOK_DIR=root/"books"
            books.PENDING_DIR=books.BOOK_DIR; books.ARCHIVE_DIR=books.BOOK_DIR
            books.LEGACY_PENDING_DIR=root/"book_pending"; books.LEGACY_ARCHIVE_DIR=root/"book_archive"
            books._INITIALIZED_DB_KEYS.clear()
            epub=root/"pg999-images-3.epub"
            container='<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>'
            opf='<?xml version="1.0"?><package xmlns="http://www.idpf.org/2007/opf" version="3.0"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>The Spine Test Book</dc:title><dc:creator>Ada Tester</dc:creator></metadata><manifest><item id="first" href="z-first.xhtml" media-type="application/xhtml+xml"/><item id="second" href="a-second.xhtml" media-type="application/xhtml+xml"/><item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/><item id="extra" href="m-extra.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="first"/><itemref idref="second"/></spine></package>'
            first='<html><body><h1>First Story</h1><p>PG_HEADER_SHOULD_DISAPPEAR</p><p>*** START OF THE PROJECT GUTENBERG EBOOK THE SPINE TEST BOOK ***</p><p>FIRST_CONTENT '+('alpha '*900)+'</p></body></html>'
            second='<html><body><h1>Second Story</h1><p>SECOND_CONTENT '+('beta '*900)+'</p><p>*** END OF THE PROJECT GUTENBERG EBOOK THE SPINE TEST BOOK ***</p><p>LICENSE_SHOULD_DISAPPEAR '+('license '*120)+'</p><p>REPEATED_CONTENTS_SHOULD_DISAPPEAR</p></body></html>'
            with zipfile.ZipFile(epub,"w") as zf:
                zf.writestr("META-INF/container.xml",container); zf.writestr("OPS/content.opf",opf)
                # ZIP lexical order is deliberately opposite the spine.
                zf.writestr("OPS/a-second.xhtml",second); zf.writestr("OPS/z-first.xhtml",first)
                zf.writestr("OPS/nav.xhtml","<html><body>NAV_SHOULD_NOT_APPEAR</body></html>")
                zf.writestr("OPS/m-extra.xhtml","<html><body>EXTRA_SHOULD_NOT_APPEAR</body></html>")
            result=books.import_book(str(epub)); bid=str(result.get("book_id") or "")
            checks["import_ok"]=bool(result.get("ok") and bid)
            file_digest=hashlib.sha256(epub.read_bytes()).hexdigest()
            legacy_bid=books._book_id("local:"+file_digest)
            corrected_bid=books._book_id("local:epub-opf-spine-gutenberg-clean-v2:"+file_digest)
            checks["corrected_ingestion_uses_distinct_book_id"]=bid==corrected_bid and bid!=legacy_bid
            checks["metadata_title_and_author"]=result.get("title")=="The Spine Test Book" and "Ada Tester" in (result.get("authors") or [])
            checks["spine_extraction_version"]=result.get("extraction_version")=="opf-spine-gutenberg-clean-v2"
            with books.connect() as db:
                rows=db.execute("SELECT ordinal,chapter,original_text FROM book_chunks WHERE book_id=? ORDER BY ordinal",(bid,)).fetchall()
                meta_row=db.execute("SELECT metadata_json FROM books WHERE book_id=?",(bid,)).fetchone()
            text="\n".join(str(r["original_text"] or "") for r in rows)
            checks["spine_beats_zip_filename_order"]=text.find("FIRST_CONTENT")>=0 and text.find("FIRST_CONTENT")<text.find("SECOND_CONTENT")
            checks["non_spine_html_excluded"]="NAV_SHOULD_NOT_APPEAR" not in text and "EXTRA_SHOULD_NOT_APPEAR" not in text
            checks["gutenberg_wrapper_removed"]=("PG_HEADER_SHOULD_DISAPPEAR" not in text and "LICENSE_SHOULD_DISAPPEAR" not in text and "REPEATED_CONTENTS_SHOULD_DISAPPEAR" not in text and "START OF THE PROJECT GUTENBERG" not in text and "END OF THE PROJECT GUTENBERG" not in text)
            checks["file_boundary_markers_not_in_canonical_text"]="[OPS/" not in text and "[OEBPS/" not in text
            checks["section_labels_reach_chunks"]=any(str(r["chapter"] or "") in {"First Story","Second Story"} for r in rows)
            try: metadata=json.loads(meta_row["metadata_json"] or "{}") if meta_row else {}
            except Exception: metadata={}
            cleanup_meta=((metadata.get("source_metadata") or {}).get("gutenberg_wrapper_cleanup") if isinstance(metadata.get("source_metadata"),dict) else {}) or {}
            checks["canonical_hash_and_section_provenance_recorded"]=bool(re.fullmatch(r"[0-9a-f]{64}",str(metadata.get("canonical_text_sha256") or "")) and len(metadata.get("source_sections") or [])==2)
            checks["gutenberg_cleanup_provenance_recorded"]=bool(cleanup_meta.get("applied") and int(cleanup_meta.get("removed_prefix_chars") or 0)>0 and int(cleanup_meta.get("removed_suffix_chars") or 0)>0 and re.fullmatch(r"[0-9a-f]{64}",str(cleanup_meta.get("source_text_sha256_before_cleanup") or "")))
            listed=books.list_books(limit=10)
            item=next((x for x in listed if str(x.get("book_id"))==bid),{})
            checks["library_exposes_spine_order_state"]=item.get("epub_reading_order")=="spine"
    finally:
        for name,value in saved.items():
            if value is not None: setattr(books,name,value)
        books._INITIALIZED_DB_KEYS.clear(); books._INITIALIZED_DB_KEYS.update(saved_init)
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":"1.1-opf-spine-gutenberg-clean-regression","model_calls":0,"web_calls":0,"live_database_modified":False}


def shared_knowledge_self_test(module) -> dict:
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV)
    original_memory=os.getenv("NEAT_MEMORY_DIR")
    checks={}
    try:
        with tempfile.TemporaryDirectory(prefix="neat-shared-knowledge-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder
            _sk_ensure_schema(module)
            source=_sk_upsert_source("book","BK-TEST","Test Book","a"*64,{"kind":"test"})
            v1=_sk_begin_version(source=source,scope="full book",digest_mode="normal",provider="python",model_alias="luna",model_id="test-luna",operation="digest",total_chunks=1)
            with _sk_connect() as db:
                iid=_sk_store_item(db,version_id=v1["version_id"],proposal={"kind":"fact","claim":"Juliet carries a dagger in the test passage.","details":"","interpretation":"paraphrase","domain":"literature","importance":0.7,"confidence":0.9},resolved_sources=[{"ref":"book:BK-TEST:C1","chunk_id":"C1","excerpt":"She carries the dagger."}],source_kind="book")
                db.execute("INSERT INTO knowledge_version_chunks VALUES(?,?,?,?,?,?)",(v1["version_id"],"C1",1,"b"*64,"completed",_sk_now()))
            _sk_finalize_version(source["source_id"],v1["version_id"],v1["run_id"],processed=1,model_calls=1,items=1)
            v2=_sk_begin_version(source=source,scope="full book",digest_mode="deep",provider="gpt",model_alias="luna",model_id="test-luna",operation="redigest",total_chunks=1)
            _sk_fail_version(v2["version_id"],v2["run_id"],"synthetic failure")
            current=_sk_current_version(source["source_id"])
            checks["failed_redigest_keeps_old_active"]=bool(current and current["version_id"]==v1["version_id"])
            v3=_sk_begin_version(source=source,scope="full book",digest_mode="deep",provider="gpt",model_alias="luna",model_id="test-luna",operation="redigest",total_chunks=1)
            _sk_finalize_version(source["source_id"],v3["version_id"],v3["run_id"],processed=1,model_calls=1,items=0)
            with _sk_connect() as db:
                old=db.execute("SELECT active,archive,status FROM knowledge_versions WHERE version_id=?",(v1["version_id"],)).fetchone(); new=db.execute("SELECT active,archive,status FROM knowledge_versions WHERE version_id=?",(v3["version_id"],)).fetchone()
            checks["successful_redigest_archives_old"]=old and int(old["active"])==0 and int(old["archive"])==1
            checks["new_version_active"]=new and int(new["active"])==1 and int(new["archive"])==0 and str(new["status"])=="completed"
            checks["contribution_recorded"]=_SHARED_KNOWLEDGE_CONTRIBUTION["direction"]=="Steeve Martin Dumont-Roy"
            checks["gpt_aliases"]=set(_GPT_MODEL_ALIASES)=={"luna","terra","sol"}
            retired=_sk_retire("BK-TEST"); checks["retire_non_destructive"]=retired.get("retired") is True and _sk_history("BK-TEST").get("ok") is True
            restored=_sk_restore("BK-TEST"); checks["restore"] = restored.get("active") is True
            preview=_sk_purge_preview("BK-TEST"); checks["purge_requires_token"]=bool(preview.get("confirmation_token"))
            status=_sk_status(module); checks["separate_database"]=Path(status["database"]).name==_SHARED_KNOWLEDGE_DB and status["entity_neutral"] is True

            # Regression: legacy physical folders migrate into one canonical books/
            # directory without becoming active storage locations again.
            personal_root=Path(folder)/"personal-memory"
            canonical_books=Path(folder)/"books"
            os.environ["NEAT_MEMORY_DIR"]=str(personal_root)
            legacy_pending=personal_root/"book_pending"; legacy_pending.mkdir(parents=True,exist_ok=True)
            legacy_archive=personal_root/"book_archive"; legacy_archive.mkdir(parents=True,exist_ok=True)
            canonical_books.mkdir(parents=True,exist_ok=True)
            (legacy_pending/"new-book.txt").write_text("A newly dropped book.",encoding="utf-8")
            (legacy_archive/"old-book.txt").write_text("A completed legacy book.",encoding="utf-8")
            class _SyncBooks:
                BOOK_DIR=canonical_books
                SUPPORTED_BOOK_SUFFIXES={".txt"}
            sync_first=_sk_sync_legacy_book_storage(_SyncBooks)
            sync_second=_sk_sync_legacy_book_storage(_SyncBooks)
            checks["legacy_book_folders_merge_into_books_once"]=(sync_first.get("copied")==2 and sync_second.get("copied")==0 and sync_second.get("already_present")==2 and (canonical_books/"new-book.txt").exists() and (canonical_books/"old-book.txt").exists())
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original
        if original_memory is None: os.environ.pop("NEAT_MEMORY_DIR",None)
        else: os.environ["NEAT_MEMORY_DIR"]=original_memory
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks}


def _install_shared_knowledge(module) -> None:
    if getattr(module,"_SHARED_KNOWLEDGE_INSTALLED",False): return
    _sk_ensure_schema(module)
    module.get_shared_knowledge_status=lambda:_sk_status(module)
    module.search_shared_knowledge=lambda query,limit=20:_sk_search_items(query,limit)
    module.get_shared_knowledge_item=lambda item_id:_sk_get_item(item_id)
    module.read_shared_provenance=lambda reference,include_original=True:_sk_read_provenance_ref(reference,include_original)
    module.search_shared_evidence=lambda query,scope="passage",include_inferred=True,min_confidence=0.6,limit=20:_sk_search_passages(query,scope,include_inferred,min_confidence,limit)
    module.get_shared_evidence_passage=lambda passage_id,include_original=False:_sk_get_passage(passage_id,include_original)
    module.shared_knowledge_self_test=lambda:shared_knowledge_self_test(module)
    module.epub_spine_order_self_test=lambda:epub_spine_order_self_test(module)
    # Redirect the familiar entity-index API to the entity-neutral store. The old
    # personal DB index remains untouched as legacy derived data but is no longer
    # authoritative for books/research in 7.4.23.2.
    module.get_digest_entity_index_status=lambda:_sk_status(module)
    module.search_digest_index=lambda query,scope="passage",include_inferred=True,min_confidence=0.6,limit=20:_sk_search_passages(query,scope,include_inferred,min_confidence,limit)
    module.get_digest_passage=lambda passage_id,include_original=False:_sk_get_passage(passage_id,include_original)
    module.rebuild_digest_entity_index=lambda clear=False,limit=0:{"ok":True,"shared_knowledge":True,"message":"Shared evidence indexes are version-owned and rebuilt by digest/redigest. Use /knowledge migrate for legacy personal-derived book/research rows.","status":_sk_status(module)}
    # Research learning proposals now become shared knowledge instead of personal
    # memories. The previous writer remains reachable only through archived source.
    module._SHARED_ORIGINAL_PERSIST_LEARNED=getattr(module,"persist_learned_memories",None)
    module.persist_learned_memories=lambda report,report_path=None:_sk_persist_learned_memories(module,report,report_path)
    _sk_shared_tools_install(module)
    old_main=module.main
    def main_with_shared_knowledge():
        previous_input=builtins.input
        def intercepted(prompt=""):
            while True:
                raw=previous_input(prompt)
                try:
                    if _sk_dispatch_command(module,raw): continue
                except Exception as exc:
                    print(f"Shared knowledge command error: {type(exc).__name__}: {exc}"); continue
                return raw
        builtins.input=intercepted
        try: return old_main()
        finally: builtins.input=previous_input
    module.main=main_with_shared_knowledge
    original_help=module.print_help
    def shared_help(advanced=False,*args,**kwargs):
        result=original_help(advanced=advanced,*args,**kwargs)
        print("  /gpt status|luna|terra|sol         choose the default GPT API alias (Luna default)")
        print("  /redigest online book BK-...       normal versioned redigest with configured GPT alias")
        print("  /redigest local book BK-...        normal versioned redigest with LM Studio")
        print("  /redigest BK-... --deep [--online|--lmstudio|--gpt luna]   optimized resumable deep redigest; local default")
        print("  /redigest BK-... --deep --force --gpt luna   discard stale deep checkpoints and restart a FULL redigest from chunk 1")
        print("  /redigest BK-...                    normal versioned redigest; LM Studio default unless --gpt <alias>")
        print("  /redigest BK-... --deep --gpt luna --test-chunks 2   safe no-store deep test")
        print("  /knowledge status|search|show|evidence|history|retire|restore|replace|purge|migrate")
        return result
    module.print_help=shared_help
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs.setdefault("shared-knowledge",{"label":"Entity-neutral shared books/research knowledge and safe versioned redigest","groups":("quick","critical","all"),"runner":"memory.shared_knowledge_self_test"})
        specs["redigest-provider-syntax"]={"label":"/redigest accepts /digest-style online/local book provider prefixes plus legacy flags without losing the BK-ID","groups":("quick","critical","all"),"runner":"memory.redigest_provider_syntax_self_test"}
        specs["epub-spine-order"]={"label":"NeatBooks imports EPUB literary text in OPF spine order, excludes non-spine HTML, uses a distinct corrected BK identity, and keeps source-member provenance outside canonical prose","groups":("quick","critical","all"),"runner":"memory.epub_spine_order_self_test"}
    module.redigest_provider_syntax_self_test=lambda:redigest_provider_syntax_self_test(module)
    module.SHARED_KNOWLEDGE_VERSION=_SHARED_KNOWLEDGE_VERSION
    module.DEEP_REDIGEST_ENABLED=_DEEP_REDIGEST_ENABLED
    module.DEEP_REDIGEST_VERSION=_DEEP_REDIGEST_VERSION
    module.SHARED_KNOWLEDGE_ROOT=str(_sk_root_path())
    module.RELEASE_CONTRIBUTION=dict(_SHARED_KNOWLEDGE_CONTRIBUTION)
    module._SHARED_KNOWLEDGE_INSTALLED=True


def _install_shared_knowledge_digest(digest_module, memory_module) -> None:
    if getattr(digest_module,"_SHARED_KNOWLEDGE_DIGEST_INSTALLED",False): return
    digest_module._SHARED_ORIGINAL_BOOK_CALL=digest_module._call_book_digest_model
    digest_module._SHARED_ORIGINAL_BOOK_INSERT=digest_module._insert_book_digest_batch
    digest_module._SHARED_ORIGINAL_DIGEST_BOOK=digest_module.digest_book
    digest_module._SHARED_ORIGINAL_DIGEST_RESEARCH_REPORT=digest_module.digest_research_report
    # Normal online digest commands obey /gpt <alias>.
    original_local_builder=digest_module.build_local_backend
    def build_online_selected():
        backend,_,_=_sk_backend(digest_module,memory_module,use_lmstudio=False,gpt_alias=None); return backend
    digest_module.build_backend=build_online_selected
    digest_module.build_provider_backend=lambda provider: original_local_builder() if digest_module.normalize_provider(provider)=="local" else build_online_selected()
    digest_module.digest_book=lambda backend,book_id,scope_tokens=None:_sk_digest_book(digest_module,memory_module,backend,book_id,scope_tokens or [],operation="digest",deep=False,model_alias=_sk_model_alias(memory_module) if getattr(backend,"provider","")=="online" else None)
    digest_module.digest_research_report=lambda backend,run_id:_sk_digest_research_report(digest_module,memory_module,backend,run_id)
    # Keep the old insert callable for compatibility but redirect any direct call to
    # the shared staging version only when a version context is explicit.
    def direct_shared_insert(**kwargs):
        ctx=getattr(digest_module,"_SHARED_ACTIVE_VERSION_CONTEXT",None)
        if not isinstance(ctx,dict):
            raise RuntimeError("Direct book digest insertion into personal NeatMemory is disabled in 7.4.23.2; use digest_book/redigest shared workflow.")
        return _sk_store_book_batch(digest_module,version_id=ctx["version_id"],source_id=ctx["source_id"],**kwargs)
    digest_module._insert_book_digest_batch=direct_shared_insert
    # Library progress reads the active shared version instead of personal digest tables.
    digest_module._current_book_progress=lambda book_id:_sk_book_progress(digest_module,book_id)
    digest_module.SHARED_KNOWLEDGE_VERSION=_SHARED_KNOWLEDGE_VERSION
    digest_module._SHARED_KNOWLEDGE_DIGEST_INSTALLED=True


# ---------------------------------------------------------------------------
# NeatMemory 7.4.78.89 — Retired Mesh compatibility + neutral shared-KI adoption
# ---------------------------------------------------------------------------
# The old Layered Evidence Mesh implementation and its disabled wrapper were
# retained for A/B experiments long after normal retrieval stopped using them.
# They are now physically removed. This small facade exists solely to fail closed
# for historical callers; it creates no Mesh schemas/files and contributes no
# retrieval context beyond an explicit retired status.
#
# /knowledge remember is deliberately preserved outside the retired concept: it
# copies one shared KI into canonical personal memory with exact shared provenance.
# The active lexical-personal-retrieval layer, installed immediately after this
# compatibility facade, refreshes the canonical word-set index for any new memory.

_MESH_RETIRED_VERSION = "retired-7.4.78.89"
_MESH_RETIRED_STATUS = "retired"
_MESH_RETIRED_REASON = (
    "NeatMesh experimental routing/index implementations were removed in 7.4.78.89. "
    "Canonical SQL, keyword/entity, exact-source, Pyramid, Constellation, and current retrieval paths remain active."
)


def _mesh_retired_status(command: str = "") -> dict:
    return {
        "ok": True,
        "feature": "mesh",
        "status": _MESH_RETIRED_STATUS,
        "enabled": False,
        "experimental": False,
        "retired": True,
        "command": str(command or "").strip() or None,
        "participates_in_retrieval": False,
        "automatic_meshing": False,
        "model_calls": 0,
        "canonical_memory_affected": False,
        "canonical_memory_authority": "unchanged",
        "reason": _MESH_RETIRED_REASON,
        "replacement": "canonical SQL + lexical keyword/entity + exact-source/Pyramid/Constellation retrieval",
    }


def _adopt_shared_knowledge_to_personal_memory(module, item_id: str) -> dict:
    """Adopt one shared KI as canonical personal memory without any Mesh dependency."""
    detail = _sk_get_item(str(item_id or "").strip())
    if not detail.get("ok"):
        return detail
    item = detail["item"]
    now = getattr(module, "utc_now", lambda: datetime.now(timezone.utc).isoformat())()
    claim = " ".join(str(item.get("claim") or "").split()).strip()
    if not claim:
        return {"ok": False, "error": "Shared knowledge item has no claim to adopt."}
    source = {
        "ref": f"shared:{item['item_id']}",
        "shared_knowledge_id": item["item_id"],
        "shared_version_id": item["version_id"],
        "shared_source_id": item["source_id"],
        "source_kind": item.get("source_kind"),
        "source_key": item.get("source_key"),
        "evidence": detail.get("sources") or [],
    }
    payload = {
        "type": "knowledge", "kind": "fact", "domain": str(item.get("domain") or "general"),
        "interpretation": "paraphrase", "summary": claim, "data": str(item.get("details") or ""),
        "sources": [source], "source_type": "shared_knowledge", "origin": "adopted_shared_knowledge",
        "adopted_from": item["item_id"], "shared_version_id": item["version_id"],
        "shared_source_id": item["source_id"], "adopted_at": now,
        "upstream_status": "active" if int(item.get("version_active") or 0) else str(item.get("version_status") or "inactive"),
    }
    digest_fn = getattr(module, "memory_content_sha256", None)
    digest = digest_fn(payload) if callable(digest_fn) else hashlib.sha256(
        json.dumps(payload, sort_keys=True, default=str).encode()
    ).hexdigest()
    with module.db_connect() as db:
        duplicate = db.execute("SELECT id FROM memories WHERE content_sha256=? LIMIT 1", (digest,)).fetchone()
        if duplicate:
            return {
                "ok": True, "adopted": False, "duplicate": True,
                "memory_id": str(duplicate["id"]), "shared_knowledge_id": item["item_id"],
                "mesh_dependency": False,
            }
        memory_id = f"NB-{datetime.now(timezone.utc).strftime('%Y%m%d')}-{digest[:10]}"
        base = memory_id; suffix = 1
        while db.execute("SELECT 1 FROM memories WHERE id=?", (memory_id,)).fetchone():
            suffix += 1; memory_id = f"{base}-{suffix}"
        encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), default=str)
        db.execute(
            """INSERT INTO memories(id,tier,state,type,kind,domain,interpretation,summary,data,version,base_importance,current_importance,confidence,activation,created_at,modified_at,observed_at,valid_from,temporal_status,project_status,last_confirmed_at,content_sha256,payload_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (memory_id, "short", "validated", "knowledge", "fact", payload["domain"], "paraphrase", claim,
             payload["data"], 1, 0.62, 0.62, max(0.5, min(1.0, float(item.get("confidence") or 0.8))),
             0.0, now, now, now, now, "active", "none", now, digest, encoded),
        )
        try:
            db.execute(
                "INSERT INTO memory_sources(memory_id,ordinal,file,line_start,line_end,speaker,conversation,weight) VALUES(?,?,?,?,?,?,?,?)",
                (memory_id, 0, f"shared:{item['item_id']}", 1, 1, "shared knowledge", str(item["version_id"]), 1.0),
            )
        except sqlite3.Error:
            pass
        try:
            db.execute(
                "INSERT INTO memory_history(memory_id,changed_at,action,previous_payload_json,new_payload_json,reason) VALUES(?,?,?,?,?,?)",
                (memory_id, now, "adopt_shared_knowledge", None, encoded,
                 f"Deliberately adopted from {item['item_id']} without mutating shared knowledge."),
            )
        except sqlite3.Error:
            pass
    return {
        "ok": True, "adopted": True, "memory_id": memory_id,
        "shared_knowledge_id": item["item_id"], "shared_version_id": item["version_id"],
        "shared_source_unchanged": True, "mesh_dependency": False,
        "lexical_index_refresh": "performed by active lexical-personal-retrieval wrapper",
    }


def retired_mesh_cleanup_self_test(module=None) -> dict:
    module = module or _load_memory()
    import inspect as _mesh_inspect
    status = _mesh_retired_status("self-test")
    checks = {
        "mesh_is_retired": status.get("retired") is True and status.get("enabled") is False,
        "mesh_not_in_retrieval": status.get("participates_in_retrieval") is False,
        "mesh_does_not_auto_ingest": status.get("automatic_meshing") is False,
        "no_mesh11_implementation_globals": not any(str(k).startswith("_MESH11_") for k in globals()),
        "no_mesh24_implementation_globals": not any(str(k).startswith("_MESH24_") for k in globals()),
        "adoption_function_has_no_mesh_calls": "_mesh" not in _mesh_inspect.getsource(_adopt_shared_knowledge_to_personal_memory).casefold(),
        "programmatic_rebuild_fails_closed": bool(getattr(module, "rebuild_personal_mesh")().get("retired")),
        "historical_search_returns_no_results": getattr(module, "search_layered_mesh")("anything").get("results") == [],
    }
    return {"ok": all(bool(v) for v in checks.values()), "checks": checks, "version": _MESH_RETIRED_VERSION}


def _install_retired_mesh_compatibility(module) -> None:
    if getattr(module, "_RETIRED_MESH_COMPATIBILITY_INSTALLED", False):
        return

    def retired_operation(*args, **kwargs):
        return _mesh_retired_status("programmatic-call")

    # A later legacy context composer still asks for this attribute. Keep a tiny
    # empty-navigation response rather than carrying a Mesh implementation.
    module.MESH_RESULT_LIMIT = int(getattr(module, "MESH_RESULT_LIMIT", 12) or 12)
    module.mesh_entries_for_query = lambda query, limit=None: "[NeatMesh retired; canonical retrieval active]"
    module.get_mesh_experimental_status = lambda: _mesh_retired_status("status")
    module.get_layered_mesh_status = lambda: _mesh_retired_status("status")
    module.search_layered_mesh = lambda query, limit=20: {**_mesh_retired_status(f"search:{query}"), "results": []}
    module.get_hierarchical_mesh_status = lambda: _mesh_retired_status("hierarchical-status")
    module.search_mesh_groups = lambda query="", limit=8, nodes_per_group=5: []
    module.get_mesh_group = lambda reference, depth=2, member_limit=30: None
    module.search_mesh_nodes = lambda query="", limit=30: []
    module.hierarchical_mesh_context = lambda query="": "[NeatMesh retired]"
    module.hierarchical_mesh_integrity = lambda: _mesh_retired_status("integrity")
    module.get_mesh_vocabulary_status = lambda: _mesh_retired_status("vocabulary-status")
    module.list_mesh_vocabulary_terms = lambda query="", limit=100: []
    module.search_controlled_mesh = lambda query, limit=30: {**_mesh_retired_status(f"legacy-search:{query}"), "results": []}
    module.list_mesh_vocab_candidates = lambda status="pending", limit=100: []
    module.get_mesh_rebuild_status = lambda: _mesh_retired_status("rebuild-status")
    module.get_mesh_rebuild_history = lambda limit=20: []

    for name in (
        "rebuild_personal_mesh", "rebuild_folder_mesh", "rebuild_general_mesh", "rebuild_mesh_master",
        "rebuild_all_layered_meshes", "initialize_hierarchical_mesh", "sync_hierarchical_mesh",
        "create_mesh_group", "add_mesh_group_member", "link_mesh_groups",
        "add_mesh_vocabulary_term", "add_mesh_vocabulary_alias", "add_mesh_vocabulary_relation",
        "approve_mesh_term_candidate", "reject_mesh_term_candidate", "rebuild_mesh_from_current_memory",
    ):
        setattr(module, name, retired_operation)

    module.adopt_shared_knowledge = lambda item_id: _adopt_shared_knowledge_to_personal_memory(module, item_id)

    def retired_test():
        return {"ok": True, "skipped": True, "retired": True, "enabled": False, "reason": _MESH_RETIRED_REASON}
    module.hierarchical_mesh_self_test = retired_test
    module.controlled_vocabulary_mesh_self_test = retired_test
    module.mesh_candidate_persistence_self_test = retired_test
    module.layered_evidence_mesh_self_test = retired_test
    module.retired_mesh_cleanup_self_test = lambda: retired_mesh_cleanup_self_test(module)

    old_main = module.main
    def main_with_retired_mesh_compatibility():
        previous_input = builtins.input
        def intercepted(prompt=""):
            while True:
                raw = previous_input(prompt)
                normalized = " ".join(str(raw or "").strip().split())
                lower = normalized.casefold()
                if lower.startswith("/mesh") or lower.startswith("/digest mesh"):
                    print(json.dumps(_mesh_retired_status(normalized), ensure_ascii=False, indent=2))
                    continue
                if lower.startswith("/knowledge remember "):
                    item_id = normalized[len("/knowledge remember "):].strip()
                    print(json.dumps(module.adopt_shared_knowledge(item_id), ensure_ascii=False, indent=2))
                    continue
                return raw
        builtins.input = intercepted
        try:
            return old_main()
        finally:
            builtins.input = previous_input
    module.main = main_with_retired_mesh_compatibility

    old_help = module.print_help
    def help_with_retired_mesh(advanced=False, *args, **kwargs):
        result = old_help(advanced=advanced, *args, **kwargs)
        print("  /knowledge remember <KI-ID>          adopt shared knowledge into canonical personal memory")
        if advanced:
            print("  /mesh status                         RETIRED — compatibility status only")
        return result
    module.print_help = help_with_retired_mesh

    module.MESH_ENABLED = False
    module.MESH_EXPERIMENTAL = False
    module.MESH_RETIRED = True
    module.MESH_STATUS = _MESH_RETIRED_STATUS
    module.MESH_PARTICIPATES_IN_RETRIEVAL = False
    module.MESH_AUTOMATIC_INGESTION = False
    module.MESH_EXPERIMENTAL_REASON = _MESH_RETIRED_REASON
    module.LAYERED_EVIDENCE_MESH_VERSION = _MESH_RETIRED_VERSION
    module.LAYERED_EVIDENCE_MESH_RESUME_COMMAND = None
    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["retired-mesh-cleanup"] = {
            "label": "NeatMesh implementations removed; historical surface fails closed; shared-KI adoption remains canonical and Mesh-independent",
            "groups": ("quick", "critical", "all"),
            "runner": "memory.retired_mesh_cleanup_self_test",
        }
    module._RETIRED_MESH_COMPATIBILITY_INSTALLED = True


# Historical startup name retained as a compatibility alias only. It no longer
# installs or contains an experimental Mesh implementation.
def _install_experimental_mesh_disabled(module) -> None:
    _install_retired_mesh_compatibility(module)


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:memorize-book rev=3
# Memorize Book raw authority (7.4.25.10.12)
# ---------------------------------------------------------------------------
# Architecture rule:
#   Python remembers exactly what the extracted book says.
#   Semantic/LLM digestion later remembers what it means.
# This layer is intentionally model-free, immutable after import, and separate
# from the replaceable summarized/shared-knowledge layer.

_MEMORIZE_BOOK_VERSION = "1.1-python-raw-authority-spine-gutenberg-clean"
_MEMORIZE_BOOK_DB = "memorize_books.db"
_MEMORIZE_BOOK_SCHEMA_VERSION = "1"
_MEMORIZE_BOOK_EXTRACTION_VERSION = "epub-spine-gutenberg-clean-v2"
_MEMORIZE_BOOK_CHUNKING_VERSION = "exact-nonoverlap-v1"
_MEMORIZE_BOOK_WORD_INDEX_VERSION = "unicode-word-postings-v1"
_MEMORIZE_BOOK_DEFAULT_CHARS = 12000
_MEMORIZE_BOOK_MIN_CHARS = 2000
_MEMORIZE_BOOK_MAX_CHARS = 50000
_MEMORIZE_BOOK_CONTEXT_CHARS = 1600


def _mb_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _mb_db_path() -> Path:
    root = _sk_root_path()
    root.mkdir(parents=True, exist_ok=True)
    return root / _MEMORIZE_BOOK_DB


def _mb_connect() -> sqlite3.Connection:
    db = sqlite3.connect(_mb_db_path(), timeout=30)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA foreign_keys=ON")
    db.execute("PRAGMA journal_mode=WAL")
    db.execute("PRAGMA synchronous=NORMAL")
    return db


def _mb_ensure_schema() -> None:
    with _mb_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS memorize_book_meta(
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS memorize_books(
            book_id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            authors_json TEXT NOT NULL DEFAULT '[]',
            source_format TEXT NOT NULL,
            source_filename TEXT NOT NULL,
            source_file_sha256 TEXT NOT NULL,
            canonical_text_sha256 TEXT NOT NULL UNIQUE,
            canonical_characters INTEGER NOT NULL,
            total_words INTEGER NOT NULL,
            total_unique_words INTEGER NOT NULL,
            total_sections INTEGER NOT NULL,
            total_chunks INTEGER NOT NULL,
            first_chunk_id TEXT,
            last_chunk_id TEXT,
            extraction_version TEXT NOT NULL,
            chunking_version TEXT NOT NULL,
            chunk_chars INTEGER NOT NULL,
            word_index_version TEXT NOT NULL,
            chunk_set_sha256 TEXT NOT NULL,
            immutable INTEGER NOT NULL DEFAULT 1,
            status TEXT NOT NULL DEFAULT 'memorized',
            created_at TEXT NOT NULL,
            metadata_json TEXT NOT NULL DEFAULT '{}'
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_books_title ON memorize_books(title);
        CREATE INDEX IF NOT EXISTS idx_memorize_books_source_hash ON memorize_books(source_file_sha256);

        CREATE TABLE IF NOT EXISTS memorize_book_imports(
            import_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL REFERENCES memorize_books(book_id) ON DELETE CASCADE,
            source_path TEXT NOT NULL,
            source_file_sha256 TEXT NOT NULL,
            source_file_size INTEGER NOT NULL,
            result TEXT NOT NULL,
            imported_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_imports_book ON memorize_book_imports(book_id, imported_at);

        CREATE TABLE IF NOT EXISTS memorize_book_sections(
            section_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL REFERENCES memorize_books(book_id) ON DELETE CASCADE,
            ordinal INTEGER NOT NULL,
            source_member TEXT,
            label TEXT,
            char_start INTEGER NOT NULL,
            char_end INTEGER NOT NULL,
            text_sha256 TEXT NOT NULL,
            UNIQUE(book_id, ordinal)
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_sections_book ON memorize_book_sections(book_id, ordinal);

        CREATE TABLE IF NOT EXISTS memorize_book_chunks(
            chunk_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL REFERENCES memorize_books(book_id) ON DELETE CASCADE,
            ordinal INTEGER NOT NULL,
            char_start INTEGER NOT NULL,
            char_end INTEGER NOT NULL,
            text TEXT NOT NULL,
            text_sha256 TEXT NOT NULL,
            word_count INTEGER NOT NULL,
            previous_chunk_id TEXT,
            next_chunk_id TEXT,
            first_section_ordinal INTEGER,
            last_section_ordinal INTEGER,
            canonical_target INTEGER NOT NULL DEFAULT 1,
            context_overlap INTEGER NOT NULL DEFAULT 0,
            UNIQUE(book_id, ordinal)
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_chunks_book ON memorize_book_chunks(book_id, ordinal);
        CREATE INDEX IF NOT EXISTS idx_memorize_chunks_hash ON memorize_book_chunks(book_id, text_sha256);

        CREATE TABLE IF NOT EXISTS memorize_book_word_lexicon(
            book_id TEXT NOT NULL REFERENCES memorize_books(book_id) ON DELETE CASCADE,
            word_norm TEXT NOT NULL,
            display_form TEXT NOT NULL,
            total_count INTEGER NOT NULL,
            chunk_count INTEGER NOT NULL,
            first_chunk_id TEXT NOT NULL,
            last_chunk_id TEXT NOT NULL,
            PRIMARY KEY(book_id, word_norm)
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_word_global ON memorize_book_word_lexicon(word_norm, total_count DESC);

        CREATE TABLE IF NOT EXISTS memorize_book_word_postings(
            book_id TEXT NOT NULL REFERENCES memorize_books(book_id) ON DELETE CASCADE,
            word_norm TEXT NOT NULL,
            chunk_id TEXT NOT NULL REFERENCES memorize_book_chunks(chunk_id) ON DELETE CASCADE,
            occurrence_count INTEGER NOT NULL,
            positions_json TEXT NOT NULL,
            PRIMARY KEY(book_id, word_norm, chunk_id)
        );
        CREATE INDEX IF NOT EXISTS idx_memorize_postings_word ON memorize_book_word_postings(book_id, word_norm, chunk_id);
        CREATE INDEX IF NOT EXISTS idx_memorize_postings_chunk ON memorize_book_word_postings(book_id, chunk_id);
        """)
        fts = True
        try:
            db.execute("""CREATE VIRTUAL TABLE IF NOT EXISTS memorize_book_fts USING fts5(
                book_id UNINDEXED, chunk_id UNINDEXED, ordinal UNINDEXED, text,
                tokenize='unicode61 remove_diacritics 2'
            )""")
        except sqlite3.OperationalError:
            fts = False
        now = _mb_now()
        for key, value in (
            ("schema_version", _MEMORIZE_BOOK_SCHEMA_VERSION),
            ("layer_version", _MEMORIZE_BOOK_VERSION),
            ("fts5_available", "1" if fts else "0"),
        ):
            db.execute(
                "INSERT INTO memorize_book_meta(key,value,updated_at) VALUES(?,?,?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",
                (key, value, now),
            )
        db.commit()


def _mb_sha(value: object) -> str:
    raw = value if isinstance(value, bytes) else str(value).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _mb_normalize_text(text: str) -> str:
    value = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
    value = "\n".join(line.rstrip(" \t") for line in value.split("\n"))
    value = re.sub(r"\n{4,}", "\n\n\n", value)
    return value.strip()


def _mb_xml_local(tag: str) -> str:
    return str(tag or "").rsplit("}", 1)[-1].casefold()


def _mb_epub_extract(path: Path, books_module) -> dict:
    import posixpath
    import zipfile
    import xml.etree.ElementTree as ET
    from urllib.parse import unquote

    with zipfile.ZipFile(path) as zf:
        names = set(zf.namelist())
        opf_path = ""
        try:
            container_xml = ET.fromstring(zf.read("META-INF/container.xml"))
            for node in container_xml.iter():
                if _mb_xml_local(node.tag) == "rootfile":
                    candidate = str(node.attrib.get("full-path") or "").strip()
                    if candidate:
                        opf_path = candidate
                        break
        except Exception:
            opf_path = ""

        title = path.stem
        authors: list[str] = []
        ordered_members: list[str] = []
        ordered_member_set: set[str] = set()
        package_meta: dict = {}

        if opf_path and opf_path in names:
            try:
                package = ET.fromstring(zf.read(opf_path))
                manifest: dict[str, dict] = {}
                spine_ids: list[str] = []
                for node in package.iter():
                    local = _mb_xml_local(node.tag)
                    if local == "item":
                        item_id = str(node.attrib.get("id") or "").strip()
                        href = str(node.attrib.get("href") or "").strip()
                        if item_id and href:
                            manifest[item_id] = {
                                "href": href,
                                "media_type": str(node.attrib.get("media-type") or "").casefold(),
                                "properties": str(node.attrib.get("properties") or "").casefold(),
                            }
                    elif local == "itemref":
                        itemref = str(node.attrib.get("idref") or "").strip()
                        linear = str(node.attrib.get("linear") or "yes").casefold()
                        if itemref and linear != "no":
                            spine_ids.append(itemref)
                    elif local == "title" and (not title or title == path.stem):
                        if node.text and node.text.strip():
                            title = node.text.strip()
                    elif local == "creator":
                        if node.text and node.text.strip():
                            authors.append(node.text.strip())

                base = posixpath.dirname(opf_path)
                for item_id in spine_ids:
                    item = manifest.get(item_id) or {}
                    href = unquote(str(item.get("href") or "").split("#", 1)[0].split("?", 1)[0])
                    media = str(item.get("media_type") or "")
                    if not href:
                        continue
                    member = posixpath.normpath(posixpath.join(base, href)) if base else posixpath.normpath(href)
                    suffix = Path(member).suffix.casefold()
                    if member in names and ("html" in media or suffix in {".xhtml", ".html", ".htm"}):
                        if member not in ordered_member_set:
                            ordered_member_set.add(member)
                            ordered_members.append(member)
                package_meta = {"opf_path": opf_path, "spine_items": len(ordered_members)}
            except Exception as exc:
                package_meta = {"opf_path": opf_path, "opf_error": f"{type(exc).__name__}: {exc}"}

        # Standards-compliant spine is authority. Fallback exists for damaged/simple EPUBs.
        if not ordered_members:
            ordered_members = [
                name for name in sorted(names)
                if Path(name).suffix.casefold() in {".xhtml", ".html", ".htm"}
                and not name.casefold().endswith(("nav.xhtml", "toc.xhtml"))
            ]
            package_meta["fallback_member_order"] = True

        sections: list[dict] = []
        for member in ordered_members:
            try:
                raw = zf.read(member).decode("utf-8", errors="replace")
            except Exception:
                continue
            try:
                text = books_module.html_to_text(raw)
            except Exception:
                # The embedded NeatBooks parser is preferred; this fallback is intentionally simple.
                text = re.sub(r"<[^>]+>", " ", raw)
            text = _mb_normalize_text(text)
            if not text:
                continue
            heading = ""
            m = re.search(r"<(?:h1|h2|title)[^>]*>(.*?)</(?:h1|h2|title)>", raw, flags=re.I | re.S)
            if m:
                heading = _mb_normalize_text(re.sub(r"<[^>]+>", " ", m.group(1)))[:300]
            sections.append({"source_member": member, "label": heading or Path(member).stem, "text": text})

        if not sections:
            raise ValueError("EPUB contains no readable spine text.")

        parts: list[str] = []
        cursor = 0
        section_rows: list[dict] = []
        for ordinal, section in enumerate(sections, 1):
            if parts:
                parts.append("\n\n")
                cursor += 2
            start = cursor
            text = section["text"]
            parts.append(text)
            cursor += len(text)
            section_rows.append({
                "ordinal": ordinal,
                "source_member": section.get("source_member"),
                "label": section.get("label"),
                "char_start": start,
                "char_end": cursor,
                "text_sha256": _mb_sha(text),
            })
        canonical = "".join(parts)
        cleanup_fn = getattr(books_module, "clean_gutenberg_wrapper", None)
        if callable(cleanup_fn):
            cleaned = cleanup_fn(canonical, section_rows)
            canonical = str(cleaned.get("text") or canonical)
            section_rows = list(cleaned.get("sections") or section_rows)
            package_meta["gutenberg_wrapper_cleanup"] = dict(cleaned.get("metadata") or {})
        package_meta["extraction_version"] = ("epub-spine-gutenberg-clean-v2" if (package_meta.get("gutenberg_wrapper_cleanup") or {}).get("applied") else "epub-spine-v1")
        return {
            "text": canonical,
            "sections": section_rows,
            "title": _mb_normalize_text(title) or path.stem,
            "authors": list(dict.fromkeys(a for a in authors if a)),
            "metadata": package_meta,
        }


def _mb_extract_source(path: Path, books_module) -> dict:
    suffix = path.suffix.casefold()
    if suffix == ".epub":
        result = _mb_epub_extract(path, books_module)
        result["source_format"] = "epub"
        return result
    if suffix in {".html", ".htm"}:
        raw = path.read_text(encoding="utf-8", errors="replace")
        text = _mb_normalize_text(books_module.html_to_text(raw))
        return {
            "text": text,
            "sections": [{"ordinal": 1, "source_member": path.name, "label": path.stem, "char_start": 0, "char_end": len(text), "text_sha256": _mb_sha(text)}],
            "title": path.stem,
            "authors": [],
            "metadata": {},
            "source_format": suffix.lstrip("."),
        }
    if suffix in {".txt", ".md", ".log", ".json", ".jsonl", ".csv"}:
        text = _mb_normalize_text(path.read_text(encoding="utf-8", errors="replace"))
        return {
            "text": text,
            "sections": [{"ordinal": 1, "source_member": path.name, "label": path.stem, "char_start": 0, "char_end": len(text), "text_sha256": _mb_sha(text)}],
            "title": path.stem,
            "authors": [],
            "metadata": {},
            "source_format": suffix.lstrip("."),
        }
    if suffix == ".pdf":
        text, pages = books_module.extract_local(path)
        text = _mb_normalize_text(text)
        sections = []
        if pages:
            # Legacy extractor page offsets are advisory after text normalization.
            sections.append({"ordinal": 1, "source_member": path.name, "label": path.stem, "char_start": 0, "char_end": len(text), "text_sha256": _mb_sha(text)})
        else:
            sections.append({"ordinal": 1, "source_member": path.name, "label": path.stem, "char_start": 0, "char_end": len(text), "text_sha256": _mb_sha(text)})
        return {"text": text, "sections": sections, "title": path.stem, "authors": [], "metadata": {"source_pages": len(pages)}, "source_format": "pdf"}
    raise ValueError("memorize_book supports epub, txt, md, html, pdf, log, json/jsonl, and csv.")


def _mb_chunk_text(text: str, chunk_chars: int = _MEMORIZE_BOOK_DEFAULT_CHARS) -> list[dict]:
    size = max(_MEMORIZE_BOOK_MIN_CHARS, min(_MEMORIZE_BOOK_MAX_CHARS, int(chunk_chars)))
    value = str(text or "")
    if not value:
        return []
    out: list[dict] = []
    start = 0
    n = len(value)
    while start < n:
        target = min(n, start + size)
        end = target
        if target < n:
            floor = min(target, start + max(1, int(size * 0.55)))
            candidates: list[int] = []
            # Exact boundaries only; no characters are dropped or duplicated.
            for marker in ("\n\n", "\n", ". ", "! ", "? ", "; ", ", ", " "):
                pos = value.rfind(marker, floor, target)
                if pos >= floor:
                    candidates.append(pos + len(marker))
            if candidates:
                end = max(candidates)
        if end <= start:
            end = min(n, start + size)
        piece = value[start:end]
        if not piece:
            break
        out.append({"ordinal": len(out) + 1, "char_start": start, "char_end": end, "text": piece, "text_sha256": _mb_sha(piece)})
        start = end
    return out


def _mb_word_tokens(text: str):
    yield from _nm_unicode_word_tokens(text)


def _mb_sections_for_span(sections: list[dict], start: int, end: int) -> tuple[int | None, int | None]:
    hits = [int(s["ordinal"]) for s in sections if int(s["char_end"]) > start and int(s["char_start"]) < end]
    return (min(hits), max(hits)) if hits else (None, None)


def _mb_import_book(path_value: str, *, title: str | None = None, authors: list[str] | None = None,
                    chunk_chars: int = _MEMORIZE_BOOK_DEFAULT_CHARS) -> dict:
    _mb_ensure_schema()
    books_module = sys.modules.get("neatbooks_v1_2_stable") or _load_embedded("neatbooks_v1_2_stable")
    path = Path(str(path_value or "")).expanduser().resolve()
    if not path.exists() or not path.is_file():
        raise FileNotFoundError(str(path_value))
    extracted = _mb_extract_source(path, books_module)
    canonical = _mb_normalize_text(extracted.get("text") or "")
    if not canonical:
        raise ValueError("No readable text was extracted.")
    canonical_hash = _mb_sha(canonical)
    book_id = "BK-" + canonical_hash[:16]
    source_bytes = path.read_bytes()
    source_hash = _mb_sha(source_bytes)
    chunks = _mb_chunk_text(canonical, chunk_chars)
    if not chunks:
        raise ValueError("No canonical chunks were created.")
    sections = list(extracted.get("sections") or [])
    if not sections:
        sections = [{"ordinal": 1, "source_member": path.name, "label": path.stem, "char_start": 0, "char_end": len(canonical), "text_sha256": canonical_hash}]
    effective_title = _mb_normalize_text(title or extracted.get("title") or path.stem) or path.stem
    effective_authors = list(dict.fromkeys(str(a).strip() for a in (authors if authors is not None else extracted.get("authors") or []) if str(a).strip()))
    chunk_hash_payload = [{"o": c["ordinal"], "s": c["char_start"], "e": c["char_end"], "h": c["text_sha256"]} for c in chunks]
    chunk_set_sha = _mb_sha(json.dumps(chunk_hash_payload, sort_keys=True, separators=(",", ":")))
    first_chunk_id = f"{book_id}-C000001"
    last_chunk_id = f"{book_id}-C{len(chunks):06d}"
    now = _mb_now()

    with _mb_connect() as db:
        existing = db.execute("SELECT * FROM memorize_books WHERE book_id=?", (book_id,)).fetchone()
        if existing:
            if str(existing["canonical_text_sha256"]) != canonical_hash:
                raise RuntimeError("Canonical book ID collision detected.")
            import_id = "MBI-" + _mb_sha(f"{book_id}|{source_hash}|{path}|{now}|{time.time_ns()}|{uuid.uuid4().hex}")[:20].upper()
            db.execute(
                "INSERT INTO memorize_book_imports(import_id,book_id,source_path,source_file_sha256,source_file_size,result,imported_at) VALUES(?,?,?,?,?,?,?)",
                (import_id, book_id, str(path), source_hash, len(source_bytes), "already_memorized", now),
            )
            db.commit()
            return {
                "ok": True, "book_id": book_id, "title": existing["title"], "already_memorized": True,
                "immutable": bool(existing["immutable"]), "chunks": int(existing["total_chunks"]),
                "words": int(existing["total_words"]), "unique_words": int(existing["total_unique_words"]),
                "canonical_text_sha256": canonical_hash, "source_file_sha256": source_hash,
                "database": str(_mb_db_path()), "model_calls": 0,
            }

        db.execute("BEGIN IMMEDIATE")
        # Book row is inserted first so all exact source children are FK-bound to it.
        db.execute("""INSERT INTO memorize_books(
            book_id,title,authors_json,source_format,source_filename,source_file_sha256,canonical_text_sha256,
            canonical_characters,total_words,total_unique_words,total_sections,total_chunks,first_chunk_id,last_chunk_id,
            extraction_version,chunking_version,chunk_chars,word_index_version,chunk_set_sha256,immutable,status,created_at,metadata_json
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (book_id,effective_title,json.dumps(effective_authors,ensure_ascii=False),str(extracted.get("source_format") or path.suffix.lstrip(".")),path.name,
         source_hash,canonical_hash,len(canonical),0,0,len(sections),len(chunks),first_chunk_id,last_chunk_id,
         str((extracted.get("metadata") or {}).get("extraction_version") or _MEMORIZE_BOOK_EXTRACTION_VERSION),_MEMORIZE_BOOK_CHUNKING_VERSION,int(max(_MEMORIZE_BOOK_MIN_CHARS,min(_MEMORIZE_BOOK_MAX_CHARS,int(chunk_chars)))),
         _MEMORIZE_BOOK_WORD_INDEX_VERSION,chunk_set_sha,1,"memorized",now,json.dumps(extracted.get("metadata") or {},ensure_ascii=False,sort_keys=True)))

        for section in sections:
            ordinal = int(section.get("ordinal") or 1)
            section_id = f"{book_id}-S{ordinal:06d}"
            db.execute("""INSERT INTO memorize_book_sections(section_id,book_id,ordinal,source_member,label,char_start,char_end,text_sha256)
                VALUES(?,?,?,?,?,?,?,?)""",
                (section_id,book_id,ordinal,section.get("source_member"),section.get("label"),int(section.get("char_start") or 0),int(section.get("char_end") or 0),str(section.get("text_sha256") or "")))

        total_words = 0
        try:
            db.execute("DELETE FROM memorize_book_fts WHERE book_id=?", (book_id,))
        except sqlite3.OperationalError:
            pass
        lexicon_acc: dict[str, dict] = {}
        for chunk in chunks:
            ordinal = int(chunk["ordinal"])
            chunk_id = f"{book_id}-C{ordinal:06d}"
            prev_id = f"{book_id}-C{ordinal-1:06d}" if ordinal > 1 else None
            next_id = f"{book_id}-C{ordinal+1:06d}" if ordinal < len(chunks) else None
            first_sec, last_sec = _mb_sections_for_span(sections, int(chunk["char_start"]), int(chunk["char_end"]))
            positions: dict[str, list[int]] = {}
            display: dict[str, str] = {}
            word_count = 0
            for norm, raw, local_start, _ in _mb_word_tokens(chunk["text"]):
                word_count += 1
                positions.setdefault(norm, []).append(int(chunk["char_start"]) + int(local_start))
                display.setdefault(norm, raw)
            total_words += word_count
            db.execute("""INSERT INTO memorize_book_chunks(
                chunk_id,book_id,ordinal,char_start,char_end,text,text_sha256,word_count,previous_chunk_id,next_chunk_id,
                first_section_ordinal,last_section_ordinal,canonical_target,context_overlap
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,0)""",
            (chunk_id,book_id,ordinal,int(chunk["char_start"]),int(chunk["char_end"]),chunk["text"],chunk["text_sha256"],word_count,
             prev_id,next_id,first_sec,last_sec))
            for norm, pos_list in positions.items():
                db.execute("""INSERT INTO memorize_book_word_postings(book_id,word_norm,chunk_id,occurrence_count,positions_json)
                    VALUES(?,?,?,?,?)""", (book_id,norm,chunk_id,len(pos_list),json.dumps(pos_list,separators=(",",":"))))
                entry = lexicon_acc.get(norm)
                if entry is None:
                    lexicon_acc[norm] = {"display": display[norm], "count": len(pos_list), "chunks": 1, "first": chunk_id, "last": chunk_id}
                else:
                    entry["count"] += len(pos_list); entry["chunks"] += 1; entry["last"] = chunk_id
            try:
                db.execute("INSERT INTO memorize_book_fts(book_id,chunk_id,ordinal,text) VALUES(?,?,?,?)", (book_id,chunk_id,ordinal,chunk["text"]))
            except sqlite3.OperationalError:
                pass

        for norm, entry in lexicon_acc.items():
            db.execute("""INSERT INTO memorize_book_word_lexicon(book_id,word_norm,display_form,total_count,chunk_count,first_chunk_id,last_chunk_id)
                VALUES(?,?,?,?,?,?,?)""", (book_id,norm,entry["display"],entry["count"],entry["chunks"],entry["first"],entry["last"]))
        db.execute("UPDATE memorize_books SET total_words=?,total_unique_words=? WHERE book_id=?", (total_words,len(lexicon_acc),book_id))
        import_id = "MBI-" + _mb_sha(f"{book_id}|{source_hash}|{path}|{now}|{time.time_ns()}|{uuid.uuid4().hex}")[:20].upper()
        db.execute("""INSERT INTO memorize_book_imports(import_id,book_id,source_path,source_file_sha256,source_file_size,result,imported_at)
            VALUES(?,?,?,?,?,?,?)""", (import_id,book_id,str(path),source_hash,len(source_bytes),"memorized",now))
        db.commit()

    return {
        "ok": True, "book_id": book_id, "title": effective_title, "authors": effective_authors,
        "already_memorized": False, "immutable": True, "sections": len(sections), "chunks": len(chunks),
        "characters": len(canonical), "words": total_words, "unique_words": len(lexicon_acc),
        "canonical_text_sha256": canonical_hash, "source_file_sha256": source_hash,
        "chunk_set_sha256": chunk_set_sha, "chunking": _MEMORIZE_BOOK_CHUNKING_VERSION,
        "word_index": _MEMORIZE_BOOK_WORD_INDEX_VERSION, "database": str(_mb_db_path()), "model_calls": 0,
    }


def _mb_list_books(limit: int = 50) -> dict:
    _mb_ensure_schema(); limit=max(1,min(500,int(limit)))
    with _mb_connect() as db:
        rows=db.execute("""SELECT book_id,title,authors_json,source_format,source_filename,canonical_text_sha256,canonical_characters,
            total_words,total_unique_words,total_sections,total_chunks,immutable,status,created_at FROM memorize_books ORDER BY created_at DESC LIMIT ?""",(limit,)).fetchall()
    items=[]
    for r in rows:
        d=dict(r); d["authors"]=json.loads(d.pop("authors_json") or "[]"); d["immutable"]=bool(d["immutable"]); items.append(d)
    return {"ok":True,"library":"memorize_book","count":len(items),"books":items,"model_calls":0}


def _mb_status(book_id: str) -> dict:
    _mb_ensure_schema()
    with _mb_connect() as db:
        row=db.execute("SELECT * FROM memorize_books WHERE book_id=?",(str(book_id),)).fetchone()
        if not row: return {"ok":False,"error":"Memorized book not found.","book_id":book_id}
        imports=db.execute("SELECT import_id,source_path,result,imported_at FROM memorize_book_imports WHERE book_id=? ORDER BY imported_at DESC LIMIT 5",(book_id,)).fetchall()
    d=dict(row); d["authors"]=json.loads(d.pop("authors_json") or "[]"); d["metadata"]=json.loads(d.pop("metadata_json") or "{}"); d["immutable"]=bool(d["immutable"])
    return {"ok":True,"library":"memorize_book","book":d,"recent_imports":[dict(x) for x in imports],"semantic_summary":"separate_replaceable_layer_not_run_here","model_calls":0}


def _mb_read(book_id: str, start: int = 1, count: int = 1) -> dict:
    _mb_ensure_schema(); start=max(1,int(start)); count=max(1,min(20,int(count)))
    with _mb_connect() as db:
        book=db.execute("SELECT book_id,title,total_chunks,canonical_text_sha256 FROM memorize_books WHERE book_id=?",(book_id,)).fetchone()
        if not book: return {"ok":False,"error":"Memorized book not found.","book_id":book_id}
        rows=db.execute("""SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256,word_count,previous_chunk_id,next_chunk_id,
            first_section_ordinal,last_section_ordinal,canonical_target,context_overlap
            FROM memorize_book_chunks WHERE book_id=? AND ordinal>=? ORDER BY ordinal LIMIT ?""",(book_id,start,count)).fetchall()
    return {"ok":True,"book":dict(book),"chunks":[dict(r) for r in rows],"text_authority":"exact extracted canonical chunk text","model_calls":0}


def _mb_word_lookup(book_id: str, word: str, limit: int = 100) -> dict:
    _mb_ensure_schema()
    tokens=list(_mb_word_tokens(str(word or "")))
    if len(tokens)!=1:
        return {"ok":False,"error":"word lookup requires exactly one word"}
    norm=tokens[0][0]; limit=max(1,min(500,int(limit)))
    with _mb_connect() as db:
        lex=db.execute("SELECT * FROM memorize_book_word_lexicon WHERE book_id=? AND word_norm=?",(book_id,norm)).fetchone()
        rows=db.execute("""SELECT p.chunk_id,p.occurrence_count,p.positions_json,c.ordinal,c.char_start,c.char_end
            FROM memorize_book_word_postings p JOIN memorize_book_chunks c ON c.chunk_id=p.chunk_id
            WHERE p.book_id=? AND p.word_norm=? ORDER BY c.ordinal LIMIT ?""",(book_id,norm,limit)).fetchall()
    postings=[]
    for r in rows:
        d=dict(r); d["positions"]=json.loads(d.pop("positions_json") or "[]"); postings.append(d)
    return {"ok":True,"book_id":book_id,"query_word":word,"normalized_word":norm,"found":bool(lex),"lexicon":dict(lex) if lex else None,"postings":postings,"position_space":"canonical extracted text character offsets","model_calls":0}


def _mb_search(query: str, *, book_id: str | None = None, limit: int = 10) -> dict:
    _mb_ensure_schema(); query=str(query or "").strip(); limit=max(1,min(50,int(limit)))
    if not query: return {"ok":False,"error":"search query is empty"}
    rows=[]; used="fts5"
    terms=[t[0] for t in _mb_word_tokens(query)]
    fts_query=" AND ".join('"'+t.replace('"','""')+'"' for t in terms)
    with _mb_connect() as db:
        try:
            sql="""SELECT f.book_id,f.chunk_id,CAST(f.ordinal AS INTEGER) ordinal,c.char_start,c.char_end,c.text,c.text_sha256,
                bm25(memorize_book_fts) rank FROM memorize_book_fts f JOIN memorize_book_chunks c ON c.chunk_id=f.chunk_id
                WHERE memorize_book_fts MATCH ?"""
            params=[fts_query or query]
            if book_id: sql+=" AND f.book_id=?"; params.append(book_id)
            sql+=" ORDER BY rank LIMIT ?"; params.append(limit)
            rows=db.execute(sql,tuple(params)).fetchall()
        except sqlite3.OperationalError:
            used="like"
            sql="SELECT book_id,chunk_id,ordinal,char_start,char_end,text,text_sha256,0.0 rank FROM memorize_book_chunks WHERE text LIKE ?"
            params=[f"%{query}%"]
            if book_id: sql+=" AND book_id=?"; params.append(book_id)
            sql+=" ORDER BY ordinal LIMIT ?"; params.append(limit)
            rows=db.execute(sql,tuple(params)).fetchall()
    results=[]
    qcf=query.casefold()
    for r in rows:
        d=dict(r); text=str(d.pop("text") or "")
        pos=text.casefold().find(qcf)
        if pos<0 and terms:
            pos=text.casefold().find(terms[0])
        pos=max(0,pos)
        left=max(0,pos-220); right=min(len(text),pos+max(220,len(query)+220))
        d["excerpt"]=("…" if left else "")+text[left:right]+("…" if right<len(text) else "")
        results.append(d)
    return {"ok":True,"query":query,"book_id":book_id,"search_backend":used,"count":len(results),"results":results,"model_calls":0}


def _mb_summary_packet(book_id: str, ordinal: int, context_chars: int = _MEMORIZE_BOOK_CONTEXT_CHARS) -> dict:
    _mb_ensure_schema(); ordinal=max(1,int(ordinal)); context_chars=max(0,min(10000,int(context_chars)))
    with _mb_connect() as db:
        target=db.execute("SELECT * FROM memorize_book_chunks WHERE book_id=? AND ordinal=?",(book_id,ordinal)).fetchone()
        if not target: return {"ok":False,"error":"Target chunk not found.","book_id":book_id,"ordinal":ordinal}
        prev=db.execute("SELECT chunk_id,ordinal,text FROM memorize_book_chunks WHERE book_id=? AND ordinal=?",(book_id,ordinal-1)).fetchone() if ordinal>1 else None
        nxt=db.execute("SELECT chunk_id,ordinal,text FROM memorize_book_chunks WHERE book_id=? AND ordinal=?",(book_id,ordinal+1)).fetchone()
    before=str(prev["text"] if prev else "")[-context_chars:] if context_chars else ""
    after=str(nxt["text"] if nxt else "")[:context_chars] if context_chars else ""
    return {
        "ok":True,"book_id":book_id,"target_chunk_id":target["chunk_id"],"target_ordinal":ordinal,
        "context_before":{"chunk_id":prev["chunk_id"] if prev else None,"text":before,"context_only":True},
        "target":{"chunk_id":target["chunk_id"],"char_start":target["char_start"],"char_end":target["char_end"],"text":target["text"],"text_sha256":target["text_sha256"],"canonical_target":True},
        "context_after":{"chunk_id":nxt["chunk_id"] if nxt else None,"text":after,"context_only":True},
        "rule":"Only target text is canonical for this future summary step; neighboring text is context only and must not create chunk-boundary facts.",
        "model_calls":0,
    }


def _mb_verify(book_id: str) -> dict:
    _mb_ensure_schema()
    with _mb_connect() as db:
        book=db.execute("SELECT * FROM memorize_books WHERE book_id=?",(book_id,)).fetchone()
        if not book: return {"ok":False,"error":"Memorized book not found.","book_id":book_id}
        chunks=db.execute("SELECT * FROM memorize_book_chunks WHERE book_id=? ORDER BY ordinal",(book_id,)).fetchall()
        lex_counts=db.execute("SELECT COALESCE(SUM(total_count),0),COUNT(*) FROM memorize_book_word_lexicon WHERE book_id=?",(book_id,)).fetchone()
        posting_counts=db.execute("SELECT COALESCE(SUM(occurrence_count),0) FROM memorize_book_word_postings WHERE book_id=?",(book_id,)).fetchone()[0]
    errors=[]; reconstructed=[]; expected_start=0; hashes=[]
    for idx,row in enumerate(chunks,1):
        text=str(row["text"] or ""); reconstructed.append(text)
        if int(row["ordinal"])!=idx: errors.append(f"ordinal mismatch at {row['chunk_id']}")
        if int(row["char_start"])!=expected_start: errors.append(f"non-contiguous char_start at {row['chunk_id']}")
        if int(row["char_end"])-int(row["char_start"])!=len(text): errors.append(f"span length mismatch at {row['chunk_id']}")
        if _mb_sha(text)!=str(row["text_sha256"]): errors.append(f"chunk hash mismatch at {row['chunk_id']}")
        expected_start=int(row["char_end"]); hashes.append({"o":idx,"s":int(row["char_start"]),"e":int(row["char_end"]),"h":str(row["text_sha256"])})
    canonical="".join(reconstructed)
    if _mb_sha(canonical)!=str(book["canonical_text_sha256"]): errors.append("canonical text hash mismatch")
    if len(canonical)!=int(book["canonical_characters"]): errors.append("canonical character count mismatch")
    if len(chunks)!=int(book["total_chunks"]): errors.append("chunk count mismatch")
    if int(lex_counts[0])!=int(book["total_words"]): errors.append("lexicon word count mismatch")
    if int(posting_counts)!=int(book["total_words"]): errors.append("posting word count mismatch")
    if int(lex_counts[1])!=int(book["total_unique_words"]): errors.append("unique word count mismatch")
    computed_chunk_set=_mb_sha(json.dumps(hashes,sort_keys=True,separators=(",",":")))
    if computed_chunk_set!=str(book["chunk_set_sha256"]): errors.append("chunk set hash mismatch")
    return {
        "ok":not errors,"status":"PASS" if not errors else "FAIL","book_id":book_id,"errors":errors,
        "canonical_text_sha256":book["canonical_text_sha256"],"chunks":len(chunks),"words":int(lex_counts[0]),
        "unique_words":int(lex_counts[1]),"postings_word_count":int(posting_counts),"immutable":bool(book["immutable"]),
        "authority":"memorize_book exact extracted chunks + hashes + deterministic Python word index","model_calls":0,
    }


def _mb_adopt_legacy(legacy_book_id: str) -> dict:
    books_module=sys.modules.get("neatbooks_v1_2_stable") or _load_embedded("neatbooks_v1_2_stable")
    books_module.initialize()
    with books_module.connect() as db:
        row=db.execute("SELECT book_id,title,authors_json,local_file FROM books WHERE book_id=?",(legacy_book_id,)).fetchone()
    if not row: return {"ok":False,"error":"Legacy NeatBooks book not found.","legacy_book_id":legacy_book_id}
    local_file=str(row["local_file"] or "")
    if not local_file or not Path(local_file).exists():
        return {"ok":False,"error":"Legacy book has no accessible original local_file; re-import the EPUB/text path directly.","legacy_book_id":legacy_book_id,"local_file":local_file}
    result=_mb_import_book(local_file,title=row["title"],authors=json.loads(row["authors_json"] or "[]"))
    result["legacy_book_id"]=legacy_book_id
    result["adopted_from_neatbooks"]=True
    return result


def _mb_command(module, command: str) -> dict | None:
    import shlex
    raw=str(command or "").strip()
    low=raw.casefold()
    prefixes=("/memorize-book","/memorize_book","/memorizebook")
    prefix=next((p for p in prefixes if low==p or low.startswith(p+" ")),None)
    if not prefix: return None
    rest=raw[len(prefix):].strip()
    if not rest or rest.casefold() in {"help","?"}:
        return {"ok":True,"usage":[
            "/memorize-book import <epub-or-text-path>",
            "/memorize-book adopt <legacy-BK-ID>",
            "/memorize-book list [limit]",
            "/memorize-book status <BK-ID>",
            "/memorize-book verify <BK-ID>",
            "/memorize-book word <BK-ID> <word>",
            "/memorize-book search <BK-ID> <query>",
            "/memorize-book read <BK-ID> [start] [count]",
            "/memorize-book packet <BK-ID> <ordinal> [context-chars]",
        ],"architecture":"Python raw authority first; replaceable semantic summary later.","model_calls":0}
    parts=shlex.split(rest,posix=False)
    if not parts: return {"ok":False,"error":"missing memorize-book command"}
    action=parts[0].casefold()
    if action=="import":
        if len(parts)<2: return {"ok":False,"error":"usage: /memorize-book import <path>"}
        path=" ".join(parts[1:]).strip().strip('"')
        return _mb_import_book(path)
    if action=="adopt":
        if len(parts)!=2: return {"ok":False,"error":"usage: /memorize-book adopt <legacy-BK-ID>"}
        return _mb_adopt_legacy(parts[1])
    if action=="list": return _mb_list_books(int(parts[1]) if len(parts)>1 and parts[1].isdigit() else 50)
    if action=="status" and len(parts)>=2: return _mb_status(parts[1])
    if action=="verify" and len(parts)>=2: return _mb_verify(parts[1])
    if action=="word" and len(parts)>=3: return _mb_word_lookup(parts[1],parts[2])
    if action=="search" and len(parts)>=3: return _mb_search(" ".join(parts[2:]),book_id=parts[1])
    if action=="read" and len(parts)>=2:
        start=int(parts[2]) if len(parts)>2 and parts[2].isdigit() else 1; count=int(parts[3]) if len(parts)>3 and parts[3].isdigit() else 1
        return _mb_read(parts[1],start,count)
    if action in {"packet","summary-packet","summarize-packet"} and len(parts)>=3:
        context=int(parts[3]) if len(parts)>3 and parts[3].isdigit() else _MEMORIZE_BOOK_CONTEXT_CHARS
        return _mb_summary_packet(parts[1],int(parts[2]),context)
    return {"ok":False,"error":"Unknown memorize-book command. Use /memorize-book help."}


def memorize_book_self_test(module=None) -> dict:
    import tempfile
    import zipfile
    original=os.environ.get(_SHARED_KNOWLEDGE_DIR_ENV)
    checks={}
    try:
        with tempfile.TemporaryDirectory(prefix="neatmemory-memorize-book-") as folder:
            root=Path(folder); shared=root/"shared"; shared.mkdir(parents=True,exist_ok=True)
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=str(shared)
            epub=root/"spine-order.epub"
            container_xml='''<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container" version="1.0"><rootfiles><rootfile full-path="OPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>'''
            opf='''<?xml version="1.0"?><package xmlns="http://www.idpf.org/2007/opf" version="3.0"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>Spine Test</dc:title><dc:creator>Ada Tester</dc:creator></metadata><manifest><item id="one" href="z-first.xhtml" media-type="application/xhtml+xml"/><item id="two" href="a-second.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="one"/><itemref idref="two"/></spine></package>'''
            first="<html><body><h1>First</h1><p>Rancour turns toward pure love. Alpha beta gamma. " + ("First passage continues. "*8) + "</p></body></html>"
            second="<html><body><h1>Second</h1><p>Rosaline appears twice: Rosaline. Delta epsilon zeta. " + ("Second passage continues. "*8) + "</p></body></html>"
            with zipfile.ZipFile(epub,"w") as zf:
                zf.writestr("META-INF/container.xml",container_xml); zf.writestr("OPS/content.opf",opf)
                # Deliberately lexical order conflicts with spine order.
                zf.writestr("OPS/a-second.xhtml",second); zf.writestr("OPS/z-first.xhtml",first)
            result=_mb_import_book(str(epub),chunk_chars=2000)
            bid=result.get("book_id")
            checks["import_ok"]=bool(result.get("ok") and bid)
            checks["immutable"]=result.get("immutable") is True
            checks["zero_model_calls"]=result.get("model_calls")==0
            with _mb_connect() as db:
                secs=db.execute("SELECT ordinal,source_member FROM memorize_book_sections WHERE book_id=? ORDER BY ordinal",(bid,)).fetchall()
                chunks=db.execute("SELECT ordinal,text,char_start,char_end FROM memorize_book_chunks WHERE book_id=? ORDER BY ordinal",(bid,)).fetchall()
            checks["epub_spine_order"]=len(secs)==2 and str(secs[0]["source_member"]).endswith("z-first.xhtml") and str(secs[1]["source_member"]).endswith("a-second.xhtml")
            reconstructed="".join(str(r["text"]) for r in chunks)
            checks["canonical_order_text"]=reconstructed.find("Rancour") < reconstructed.find("Rosaline")
            checks["nonoverlap_contiguous"]=all(int(chunks[i]["char_end"])==int(chunks[i+1]["char_start"]) for i in range(len(chunks)-1))
            checks["exact_reconstruction_hash"]=_mb_sha(reconstructed)==result.get("canonical_text_sha256")
            word=_mb_word_lookup(bid,"Rosaline")
            checks["word_index_every_occurrence"]=word.get("found") and int((word.get("lexicon") or {}).get("total_count",0))==2
            checks["word_positions_present"]=sum(len(p.get("positions") or []) for p in word.get("postings") or [])==2
            verification=_mb_verify(bid)
            checks["verify_pass"]=verification.get("status")=="PASS"
            duplicate=_mb_import_book(str(epub),chunk_chars=4000)
            checks["immutable_duplicate_no_rechunk"]=duplicate.get("already_memorized") is True and duplicate.get("book_id")==bid
            # Independent chunker property: canonical spans contain no overlap and reconstruct exactly.
            synthetic=("A paragraph with words.\n\n"*300).strip()
            split=_mb_chunk_text(synthetic,2000)
            checks["chunker_multiple_chunks"]=len(split)>1
            checks["chunker_exact_reconstruct"]="".join(c["text"] for c in split)==synthetic
            checks["chunker_no_overlap"]=all(split[i]["char_end"]==split[i+1]["char_start"] for i in range(len(split)-1))
            packet=_mb_summary_packet(bid,1,80)
            checks["summary_packet_target_separated"]=packet.get("ok") and packet.get("target",{}).get("canonical_target") is True and packet.get("context_after",{}).get("context_only") is True
            checks["dedicated_db"]=_mb_db_path().name==_MEMORIZE_BOOK_DB and _mb_db_path().exists()
            return {"ok":all(checks.values()),"checks":checks,"version":_MEMORIZE_BOOK_VERSION,"book_id":bid,"verification":verification}
    finally:
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original


def _install_memorize_book_layer(module) -> None:
    if getattr(module,"_MEMORIZE_BOOK_LAYER_INSTALLED",False): return
    _mb_ensure_schema()
    module.MEMORIZE_BOOK_VERSION=_MEMORIZE_BOOK_VERSION
    module.memorize_book_import=lambda path,**kwargs:_mb_import_book(path,**kwargs)
    module.memorize_book_list=lambda limit=50:_mb_list_books(limit)
    module.memorize_book_status=lambda book_id:_mb_status(book_id)
    module.memorize_book_verify=lambda book_id:_mb_verify(book_id)
    module.memorize_book_word=lambda book_id,word,limit=100:_mb_word_lookup(book_id,word,limit)
    module.memorize_book_search=lambda query,book_id=None,limit=10:_mb_search(query,book_id=book_id,limit=limit)
    module.memorize_book_read=lambda book_id,start=1,count=1:_mb_read(book_id,start,count)
    module.memorize_book_summary_packet=lambda book_id,ordinal,context_chars=_MEMORIZE_BOOK_CONTEXT_CHARS:_mb_summary_packet(book_id,ordinal,context_chars)
    module.memorize_book_adopt=lambda legacy_book_id:_mb_adopt_legacy(legacy_book_id)
    module.memorize_book_self_test=lambda:memorize_book_self_test(module)
    old_main=module.main
    def main_with_memorize_book():
        previous_input=builtins.input
        def intercepted(prompt=""):
            while True:
                raw=previous_input(prompt)
                command=str(raw or "").strip()
                if command.casefold().startswith(("/memorize-book","/memorize_book","/memorizebook")):
                    try: print(json.dumps(_mb_command(module,command),ensure_ascii=False,indent=2))
                    except Exception as exc: print(json.dumps({"ok":False,"error":f"{type(exc).__name__}: {exc}"},ensure_ascii=False,indent=2))
                    continue
                return raw
        builtins.input=intercepted
        try: return old_main()
        finally: builtins.input=previous_input
    module.main=main_with_memorize_book
    old_help=module.print_help
    def help_with_memorize_book(advanced=False,*args,**kwargs):
        result=old_help(advanced=advanced,*args,**kwargs)
        print("  /memorize-book ...              deterministic raw book authority: import/list/search/word/read/verify/packet")
        return result
    module.print_help=help_with_memorize_book
    module._MEMORIZE_BOOK_LAYER_INSTALLED=True



