_CHUNK_MEMORY_ENVELOPE_VERSION = "1.2-compact-complete-chunk-memory-envelope"


def _cme_json_load(raw, default):
    try:
        value = json.loads(raw or "")
        return value
    except Exception:
        return default


def _cme_original_chunk(book_id: str, chunk_id: str, *, original_text: str | None = None,
                        original_ref: str | None = None) -> dict:
    """Resolve the exact canonical chunk without semantic reconstruction."""
    bid = str(book_id or "").strip(); cid = str(chunk_id or "").strip()
    if original_text is not None:
        text = str(original_text)
        return {
            "available": True,
            "authority": "supplied_current_chunk",
            "book_id": bid,
            "chunk_id": cid,
            "ref": str(original_ref or (f"book:{bid}:{cid}" if bid and cid else "chunk")),
            "text": text,
            "text_sha256": hashlib.sha256(text.encode("utf-8")).hexdigest(),
            "exact": True,
        }
    # Prefer memorize_book: immutable exact authority introduced in 10.12.
    try:
        _mb_ensure_schema()
        with _mb_connect() as db:
            row = db.execute(
                "SELECT book_id,chunk_id,ordinal,char_start,char_end,text,text_sha256 FROM memorize_book_chunks WHERE book_id=? AND chunk_id=?",
                (bid, cid),
            ).fetchone()
        if row:
            d = dict(row)
            return {
                "available": True,
                "authority": "memorize_book",
                "book_id": bid,
                "chunk_id": cid,
                "ordinal": d.get("ordinal"),
                "char_start": d.get("char_start"),
                "char_end": d.get("char_end"),
                "ref": str(original_ref or f"memorize-book:{bid}:{cid}"),
                "text": str(d.get("text") or ""),
                "text_sha256": str(d.get("text_sha256") or ""),
                "exact": True,
            }
    except Exception:
        pass
    # Compatibility authority for legacy NeatBooks chunks.
    try:
        books = sys.modules.get("neatbooks_v1_2_stable")
        if books is None:
            _preload_dependencies(); books = sys.modules.get("neatbooks_v1_2_stable")
        if books is not None and hasattr(books, "connect"):
            with books.connect() as db:
                row = db.execute(
                    "SELECT book_id,chunk_id,ordinal,char_start,char_end,text,text_sha256,original_text,original_text_hash FROM book_chunks WHERE book_id=? AND chunk_id=?",
                    (bid, cid),
                ).fetchone()
            if row:
                d = dict(row); text = str(d.get("original_text") if d.get("original_text") is not None else d.get("text") or "")
                return {
                    "available": True,
                    "authority": "neatbooks_exact_chunk",
                    "book_id": bid,
                    "chunk_id": cid,
                    "ordinal": d.get("ordinal"),
                    "char_start": d.get("char_start"),
                    "char_end": d.get("char_end"),
                    "ref": str(original_ref or f"book:{bid}:{cid}"),
                    "text": text,
                    "text_sha256": str(d.get("original_text_hash") or d.get("text_sha256") or hashlib.sha256(text.encode()).hexdigest()),
                    "exact": True,
                }
    except Exception:
        pass
    return {
        "available": False,
        "authority": "unresolved",
        "book_id": bid,
        "chunk_id": cid,
        "ref": str(original_ref or (f"book:{bid}:{cid}" if bid and cid else "chunk")),
        "text": "",
        "text_sha256": "",
        "exact": False,
    }



def _cme_neighbor_context(book_id: str, chunk_id: str) -> dict:
    """Return the exact previous/next book chunks as context-only continuity.

    Neighbor chunks are never target evidence for this pass. They are supplied in
    full so the model can resolve transitions, pronouns, motives, and scene flow,
    but every created memory/KI must remain grounded in the target original_chunk.
    """
    bid=str(book_id or "").strip(); cid=str(chunk_id or "").strip()
    out={
        "version":"1.0-full-adjacent-chunks-target-only",
        "context_before":None,
        "context_after":None,
        "rule":"Read the full previous and next chunks only for continuity. Summarize/analyze/create memories only for original_chunk (the target). Never create or cite a memory from context-only neighbor text during this pass; process that neighbor as its own target later.",
        "target_only":True,
    }
    # Prefer immutable memorize_book authority when the target lives there.
    try:
        _mb_ensure_schema()
        with _mb_connect() as db:
            target=db.execute("SELECT ordinal FROM memorize_book_chunks WHERE book_id=? AND chunk_id=?",(bid,cid)).fetchone()
            if target:
                ordv=int(target["ordinal"])
                prev=db.execute("SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256 FROM memorize_book_chunks WHERE book_id=? AND ordinal=?",(bid,ordv-1)).fetchone() if ordv>1 else None
                nxt=db.execute("SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256 FROM memorize_book_chunks WHERE book_id=? AND ordinal=?",(bid,ordv+1)).fetchone()
                def pack(row):
                    if not row: return None
                    d=dict(row)
                    return {"ref":f"memorize-book:{bid}:{d['chunk_id']}","book_id":bid,"chunk_id":d["chunk_id"],"ordinal":d["ordinal"],"char_start":d["char_start"],"char_end":d["char_end"],"text":str(d.get("text") or ""),"text_sha256":str(d.get("text_sha256") or ""),"exact":True,"context_only":True,"may_create_memories":False}
                out["context_before"]=pack(prev); out["context_after"]=pack(nxt); out["authority"]="memorize_book"
                return out
    except Exception:
        pass
    # Compatibility path for legacy NeatBooks chunks.
    try:
        books=sys.modules.get("neatbooks_v1_2_stable")
        if books is None:
            _preload_dependencies(); books=sys.modules.get("neatbooks_v1_2_stable")
        if books is not None and hasattr(books,"connect"):
            db=books.connect()
            try:
                target=db.execute("SELECT ordinal FROM book_chunks WHERE book_id=? AND chunk_id=?",(bid,cid)).fetchone()
                if target:
                    ordv=int(target["ordinal"])
                    prev=db.execute("SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256,original_text,original_text_hash FROM book_chunks WHERE book_id=? AND ordinal=?",(bid,ordv-1)).fetchone() if ordv>1 else None
                    nxt=db.execute("SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256,original_text,original_text_hash FROM book_chunks WHERE book_id=? AND ordinal=?",(bid,ordv+1)).fetchone()
                else:
                    prev=nxt=None
            finally:
                db.close()
            def pack_legacy(row):
                if not row: return None
                d=dict(row); text=str(d.get("original_text") if d.get("original_text") is not None else d.get("text") or "")
                return {"ref":f"book:{bid}:{d['chunk_id']}","book_id":bid,"chunk_id":d["chunk_id"],"ordinal":d["ordinal"],"char_start":d.get("char_start"),"char_end":d.get("char_end"),"text":text,"text_sha256":str(d.get("original_text_hash") or d.get("text_sha256") or hashlib.sha256(text.encode("utf-8")).hexdigest()),"exact":True,"context_only":True,"may_create_memories":False}
            out["context_before"]=pack_legacy(prev); out["context_after"]=pack_legacy(nxt); out["authority"]="neatbooks_exact_chunks"
    except Exception:
        pass
    return out


# ---------------------------------------------------------------------------
# Canonical Source Equivalence Bridge (7.4.25.10.13.8.3.1)
# ---------------------------------------------------------------------------
_CANONICAL_SOURCE_EQUIVALENCE_VERSION = "1.0-file-sha256-exact-word-sequence"
_CSE_SHINGLE_WORDS = 20


def _cse_tokens(text: str) -> list[str]:
    """Deterministic lexical sequence used only for exact source equivalence.

    This is deliberately not semantic matching: Unicode-normalized words must
    occur in the same order. Source-file SHA-256 equality is required before
    any legacy chunk is considered.
    """
    return [norm for norm, _raw, _start, _end in _nm_unicode_word_tokens(text)]


def _cse_windows(tokens: list[str], width: int) -> set[tuple[str, ...]]:
    if not tokens:
        return set()
    width = max(1, min(int(width), len(tokens)))
    if len(tokens) <= width:
        return {tuple(tokens)}
    return {tuple(tokens[i:i + width]) for i in range(0, len(tokens) - width + 1)}


def _cse_text_match(target_text: str, legacy_text: str) -> dict:
    """Measure exact ordered lexical overlap between two source chunks."""
    target_tokens = _cse_tokens(target_text)
    legacy_tokens = _cse_tokens(legacy_text)
    if not target_tokens or not legacy_tokens:
        return {"matched": False, "basis": "no-text", "shared_windows": 0,
                "target_window_coverage": 0.0, "legacy_window_coverage": 0.0,
                "window_words": 0}
    width = min(_CSE_SHINGLE_WORDS, len(target_tokens), len(legacy_tokens))
    # Tiny chunks still require an exact contiguous lexical sequence, just with
    # a smaller window because twenty words do not exist.
    if width < 4:
        a = " ".join(target_tokens); b = " ".join(legacy_tokens)
        matched = bool(a and b and (a in b or b in a))
        return {"matched": matched, "basis": "exact-short-token-sequence" if matched else "no-exact-sequence",
                "shared_windows": 1 if matched else 0,
                "target_window_coverage": 1.0 if matched else 0.0,
                "legacy_window_coverage": 1.0 if matched else 0.0,
                "window_words": width}
    target_windows = _cse_windows(target_tokens, width)
    legacy_windows = _cse_windows(legacy_tokens, width)
    shared = target_windows.intersection(legacy_windows)
    shared_n = len(shared)
    target_cov = shared_n / max(1, len(target_windows))
    legacy_cov = shared_n / max(1, len(legacy_windows))
    return {
        "matched": shared_n > 0,
        "basis": "exact-ordered-word-sequence" if shared_n > 0 else "no-exact-sequence",
        "shared_windows": shared_n,
        "target_window_coverage": round(target_cov, 6),
        "legacy_window_coverage": round(legacy_cov, 6),
        "window_words": width,
    }


def _cse_source_equivalence(module, book_id: str, chunk_id: str, original_chunk: dict | None = None) -> dict:
    """Resolve equivalent old/new chunks for the exact same physical source file.

    The bridge is bidirectional:
      memorize_book canonical chunk -> legacy NeatBooks chunk(s)
      legacy NeatBooks chunk         -> memorize_book canonical chunk(s)

    Book identity is exact source-file SHA-256. Chunk identity is exact ordered
    lexical overlap. Nothing is rewritten or persisted.
    """
    bid = str(book_id or "").strip(); cid = str(chunk_id or "").strip()
    original = original_chunk or _cme_original_chunk(bid, cid)
    result = {
        "schema": _CANONICAL_SOURCE_EQUIVALENCE_VERSION,
        "read_only": True,
        "provenance_rewritten": False,
        "target_book_id": bid,
        "target_chunk_id": cid,
        "target_authority": None,
        "source_file_sha256": None,
        "equivalent_books": [],
        "equivalent_chunks": [],
        "match_policy": {
            "book": "exact source-file SHA-256 equality",
            "chunk": f"at least one exact ordered {_CSE_SHINGLE_WORDS}-word window (or the complete shorter exact token sequence)",
            "semantic_matching": False,
            "bidirectional": True,
        },
    }
    if not bid or not cid or not original.get("available"):
        return result

    books = getattr(module, "neatbooks", None) or sys.modules.get("neatbooks_v1_2_stable")
    if books is None:
        try:
            _preload_dependencies()
            books = sys.modules.get("neatbooks_v1_2_stable")
        except Exception:
            books = None

    # Determine which authority owns the requested chunk and obtain the exact
    # physical source-file hash from that authority's immutable metadata.
    source_hash = ""
    modern_target = None
    try:
        _mb_ensure_schema()
        with _mb_connect() as db:
            modern_target = db.execute(
                "SELECT book_id,title,source_file_sha256,canonical_text_sha256 FROM memorize_books WHERE book_id=?",
                (bid,),
            ).fetchone()
    except Exception:
        modern_target = None

    legacy_target = None
    if modern_target:
        source_hash = str(modern_target["source_file_sha256"] or "").strip()
        result["target_authority"] = "memorize_book"
    elif books is not None and hasattr(books, "connect"):
        try:
            if hasattr(books, "initialize"):
                books.initialize()
            with books.connect() as db:
                legacy_target = db.execute(
                    "SELECT book_id,title,content_sha256,local_file,total_chunks FROM books WHERE book_id=?",
                    (bid,),
                ).fetchone()
            if legacy_target:
                source_hash = str(legacy_target["content_sha256"] or "").strip()
                result["target_authority"] = "neatbooks_legacy"
        except Exception:
            legacy_target = None

    result["source_file_sha256"] = source_hash or None
    if not source_hash:
        return result

    target_text = str(original.get("text") or "")
    try:
        if modern_target:
            # Canonical -> legacy: exact physical source hash identifies the old
            # NeatBooks book; exact word sequence identifies overlapping chunks.
            if books is None or not hasattr(books, "connect"):
                return result
            with books.connect() as db:
                candidates = db.execute(
                    "SELECT book_id,title,content_sha256,local_file,total_chunks FROM books WHERE content_sha256=? ORDER BY book_id",
                    (source_hash,),
                ).fetchall()
                for book in candidates:
                    candidate_bid = str(book["book_id"] or "")
                    if not candidate_bid or candidate_bid == bid:
                        continue
                    result["equivalent_books"].append({
                        "book_id": candidate_bid,
                        "authority": "neatbooks_legacy",
                        "title": str(book["title"] or ""),
                        "match_basis": "source_file_sha256",
                        "source_file_sha256": source_hash,
                        "total_chunks": int(book["total_chunks"] or 0),
                    })
                    rows = db.execute(
                        """SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256,
                                  original_text,original_text_hash
                           FROM book_chunks WHERE book_id=? ORDER BY ordinal""",
                        (candidate_bid,),
                    ).fetchall()
                    for row in rows:
                        d = dict(row)
                        candidate_text = str(d.get("original_text") if d.get("original_text") is not None else d.get("text") or "")
                        match = _cse_text_match(target_text, candidate_text)
                        if not match.get("matched"):
                            continue
                        candidate_cid = str(d.get("chunk_id") or "")
                        result["equivalent_chunks"].append({
                            "book_id": candidate_bid,
                            "chunk_id": candidate_cid,
                            "authority": "neatbooks_legacy",
                            "ordinal": int(d.get("ordinal") or 0),
                            "char_start": d.get("char_start"),
                            "char_end": d.get("char_end"),
                            "text_sha256": str(d.get("original_text_hash") or d.get("text_sha256") or ""),
                            "match_basis": match.get("basis"),
                            "shared_windows": int(match.get("shared_windows") or 0),
                            "window_words": int(match.get("window_words") or 0),
                            "target_window_coverage": float(match.get("target_window_coverage") or 0.0),
                            "equivalent_window_coverage": float(match.get("legacy_window_coverage") or 0.0),
                            "provenance_ref": f"book:{candidate_bid}:{candidate_cid}",
                        })
        else:
            # Legacy -> canonical: used by current NeatDigest book operations.
            # This lets digestion see memories already written against the new
            # memorize_book authority too.
            with _mb_connect() as db:
                candidates = db.execute(
                    "SELECT book_id,title,source_file_sha256,total_chunks FROM memorize_books WHERE source_file_sha256=? ORDER BY book_id",
                    (source_hash,),
                ).fetchall()
                for book in candidates:
                    candidate_bid = str(book["book_id"] or "")
                    if not candidate_bid or candidate_bid == bid:
                        continue
                    result["equivalent_books"].append({
                        "book_id": candidate_bid,
                        "authority": "memorize_book",
                        "title": str(book["title"] or ""),
                        "match_basis": "source_file_sha256",
                        "source_file_sha256": source_hash,
                        "total_chunks": int(book["total_chunks"] or 0),
                    })
                    rows = db.execute(
                        "SELECT chunk_id,ordinal,char_start,char_end,text,text_sha256 FROM memorize_book_chunks WHERE book_id=? ORDER BY ordinal",
                        (candidate_bid,),
                    ).fetchall()
                    for row in rows:
                        d = dict(row); candidate_text = str(d.get("text") or "")
                        match = _cse_text_match(target_text, candidate_text)
                        if not match.get("matched"):
                            continue
                        candidate_cid = str(d.get("chunk_id") or "")
                        result["equivalent_chunks"].append({
                            "book_id": candidate_bid,
                            "chunk_id": candidate_cid,
                            "authority": "memorize_book",
                            "ordinal": int(d.get("ordinal") or 0),
                            "char_start": d.get("char_start"),
                            "char_end": d.get("char_end"),
                            "text_sha256": str(d.get("text_sha256") or ""),
                            "match_basis": match.get("basis"),
                            "shared_windows": int(match.get("shared_windows") or 0),
                            "window_words": int(match.get("window_words") or 0),
                            "target_window_coverage": float(match.get("target_window_coverage") or 0.0),
                            "equivalent_window_coverage": float(match.get("legacy_window_coverage") or 0.0),
                            "provenance_ref": f"memorize-book:{candidate_bid}:{candidate_cid}",
                        })
    except Exception as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
        return result

    result["equivalent_chunks"].sort(
        key=lambda x: (str(x.get("book_id") or ""), int(x.get("ordinal") or 0), str(x.get("chunk_id") or ""))
    )
    return result


def _cse_source_pairs(book_id: str, chunk_id: str, equivalence: dict) -> list[dict]:
    pairs = [{"book_id": str(book_id or ""), "chunk_id": str(chunk_id or ""),
              "relationship": "canonical", "match_basis": "direct-canonical-link"}]
    seen = {(str(book_id or ""), str(chunk_id or ""))}
    for item in equivalence.get("equivalent_chunks") or []:
        key = (str(item.get("book_id") or ""), str(item.get("chunk_id") or ""))
        if not all(key) or key in seen:
            continue
        seen.add(key)
        pairs.append({
            "book_id": key[0], "chunk_id": key[1],
            "relationship": "equivalent_source",
            "match_basis": item.get("match_basis"),
            "shared_windows": item.get("shared_windows"),
            "window_words": item.get("window_words"),
            "target_window_coverage": item.get("target_window_coverage"),
            "legacy_window_coverage": item.get("legacy_window_coverage"),
            "provenance_ref": item.get("provenance_ref"),
        })
    return pairs


def _cse_collect_personal_memories(module, source_pairs: list[dict]) -> list[dict]:
    merged: dict[str, dict] = {}
    for pair in source_pairs:
        items = _cme_personal_memories(module, pair.get("book_id"), pair.get("chunk_id"))
        for item in items:
            mid = str(item.get("memory_id") or "")
            if not mid:
                continue
            if mid not in merged:
                merged[mid] = dict(item)
                merged[mid]["source_equivalence_matches"] = []
            if pair.get("relationship") != "canonical":
                marker = {k: pair.get(k) for k in (
                    "book_id","chunk_id","relationship","match_basis","shared_windows","window_words",
                    "target_window_coverage","equivalent_window_coverage","provenance_ref","authority"
                )}
                if marker not in merged[mid]["source_equivalence_matches"]:
                    merged[mid]["source_equivalence_matches"].append(marker)
    return sorted(merged.values(), key=lambda x: (str(x.get("created_at") or ""), str(x.get("memory_id") or "")))


def _cse_collect_shared_items(source_pairs: list[dict]) -> list[dict]:
    merged: dict[str, dict] = {}
    for pair in source_pairs:
        items = _cme_shared_items(pair.get("book_id"), pair.get("chunk_id"))
        for item in items:
            iid = str(item.get("item_id") or "")
            if not iid:
                continue
            if iid not in merged:
                merged[iid] = dict(item)
                merged[iid]["sources"] = list(item.get("sources") or [])
                merged[iid]["source_equivalence_matches"] = []
            else:
                existing_sources = {
                    (str(x.get("source_ref") or ""), int(x.get("ordinal") or 0))
                    for x in merged[iid].get("sources") or []
                }
                for source in item.get("sources") or []:
                    key = (str(source.get("source_ref") or ""), int(source.get("ordinal") or 0))
                    if key not in existing_sources:
                        merged[iid]["sources"].append(dict(source)); existing_sources.add(key)
            if pair.get("relationship") != "canonical":
                marker = {k: pair.get(k) for k in (
                    "book_id","chunk_id","relationship","match_basis","shared_windows","window_words",
                    "target_window_coverage","equivalent_window_coverage","provenance_ref","authority"
                )}
                if marker not in merged[iid]["source_equivalence_matches"]:
                    merged[iid]["source_equivalence_matches"].append(marker)
    result = list(merged.values())
    result.sort(key=lambda x: (int(x.get("version_number") or 0), str(x.get("item_id") or "")))
    return result


def _cme_personal_memories(module, book_id: str, chunk_id: str) -> list[dict]:
    """Return every canonical personal memory linked to one chunk, in every state."""
    bid = str(book_id or "").strip(); cid = str(chunk_id or "").strip()
    if not bid or not cid:
        return []
    try:
        module.initialize_database()
    except Exception:
        pass
    rows = []
    with module.db_connect() as db:
        try:
            rows = db.execute(
                """SELECT DISTINCT m.* FROM memories m
                   JOIN memory_source_links l ON l.memory_id=m.id
                   WHERE l.book_id=? AND l.chunk_id=?
                   ORDER BY m.created_at,m.id""",
                (bid, cid),
            ).fetchall()
        except Exception:
            return []
        output = []
        for row in rows:
            d = dict(row); mid = str(d.get("id") or "")
            links = []
            try:
                links = [dict(x) for x in db.execute(
                    "SELECT ordinal,source_type,source_id,book_id,chunk_id,neatblock_id,source_hash FROM memory_source_links WHERE memory_id=? ORDER BY ordinal",
                    (mid,),
                ).fetchall()]
            except Exception:
                pass
            latest_archive = None
            try:
                evt = db.execute(
                    "SELECT event_id,action,actor,reason,confidence,evidence_refs_json,previous_state,previous_temporal_status,new_state,new_temporal_status,created_at FROM reflection_archive_events WHERE memory_id=? AND action='archive' ORDER BY created_at DESC LIMIT 1",
                    (mid,),
                ).fetchone()
                if evt:
                    latest_archive = dict(evt)
                    latest_archive["evidence_refs"] = _cme_json_load(latest_archive.pop("evidence_refs_json", "[]"), [])
            except Exception:
                pass
            if latest_archive is None and str(d.get("state") or "").casefold() == "archived":
                try:
                    hist = db.execute(
                        "SELECT action,reason,changed_at FROM memory_history WHERE memory_id=? ORDER BY history_id DESC LIMIT 20",
                        (mid,),
                    ).fetchall()
                    h = next((dict(x) for x in hist if "archiv" in str(x["action"] or "").casefold() or "supersed" in str(x["action"] or "").casefold()), None)
                    if h:
                        latest_archive = {"event_id": None, "action": h.get("action"), "actor": "legacy/history", "reason": h.get("reason"), "created_at": h.get("changed_at"), "evidence_refs": []}
                except Exception:
                    pass
            superseded_by = []
            try:
                superseded_by = [str(x["id"]) for x in db.execute("SELECT id FROM memories WHERE supersedes_id=? ORDER BY created_at,id", (mid,)).fetchall()]
            except Exception:
                pass
            output.append({
                "ref": f"memory:{mid}",
                "memory_id": mid,
                "type": d.get("type"),
                "kind": d.get("kind"),
                "domain": d.get("domain"),
                "interpretation": d.get("interpretation"),
                "state": d.get("state"),
                "temporal_status": d.get("temporal_status"),
                "summary": str(d.get("summary") or ""),
                "data": str(d.get("data") or ""),
                "confidence": d.get("confidence"),
                "importance": d.get("current_importance"),
                "created_at": d.get("created_at"),
                "modified_at": d.get("modified_at"),
                "supersedes_id": d.get("supersedes_id"),
                "superseded_by_ids": superseded_by,
                "parent_version_id": d.get("parent_version_id"),
                "archive_event": latest_archive,
                "archive_reason": (latest_archive or {}).get("reason") if latest_archive else None,
                "source_links": links,
                "immutable_content": True,
            })
    return output


def _cme_shared_items(book_id: str, chunk_id: str) -> list[dict]:
    """Return all shared-KI history linked to the chunk, including archived versions."""
    bid = str(book_id or "").strip(); cid = str(chunk_id or "").strip()
    if not bid or not cid:
        return []
    try:
        _sk_ensure_schema()
    except Exception:
        return []
    out = {}; source_ids = []
    with _sk_connect() as db:
        try:
            srcs = db.execute("SELECT source_id,source_key,source_locator_json,title FROM knowledge_sources WHERE source_kind='book'").fetchall()
            for s in srcs:
                loc = _cme_json_load(s["source_locator_json"], {})
                if str(s["source_key"] or "") == bid or str(loc.get("book_id") or "") == bid:
                    source_ids.append(str(s["source_id"]))
            for sid in source_ids:
                rows = db.execute(
                    """SELECT i.item_id,i.kind,i.claim,i.details,i.interpretation,i.domain,i.importance,i.confidence,i.created_at,
                              v.version_id,v.version_number,v.status AS version_status,v.active AS version_active,v.archive AS version_archive,
                              r.operation,v.digest_mode,v.provider,v.model_id,v.completed_at,
                              ks.ordinal AS source_ordinal,ks.source_ref,ks.locator_json,ks.evidence_sha256,ks.excerpt_sha256,ks.excerpt
                       FROM knowledge_items i
                       JOIN knowledge_versions v ON v.version_id=i.version_id
                       LEFT JOIN knowledge_runs r ON r.run_id=v.run_id
                       JOIN knowledge_item_sources ks ON ks.item_id=i.item_id
                       WHERE v.source_id=? ORDER BY v.version_number,i.item_id,ks.ordinal""",
                    (sid,),
                ).fetchall()
                for row in rows:
                    d = dict(row); loc = _cme_json_load(d.get("locator_json"), {})
                    if str(loc.get("chunk_id") or "") != cid and not str(d.get("source_ref") or "").endswith(":" + cid):
                        continue
                    iid = str(d.get("item_id") or "")
                    entry = out.setdefault(iid, {
                        "ref": f"knowledge:{iid}", "item_id": iid,
                        "kind": d.get("kind"), "claim": str(d.get("claim") or ""), "details": str(d.get("details") or ""),
                        "interpretation": d.get("interpretation"), "domain": d.get("domain"),
                        "importance": d.get("importance"), "confidence": d.get("confidence"), "created_at": d.get("created_at"),
                        "version_id": d.get("version_id"), "version_number": d.get("version_number"),
                        "version_status": d.get("version_status"), "version_active": bool(d.get("version_active")),
                        "version_archive": bool(d.get("version_archive")), "operation": d.get("operation"),
                        "digest_mode": d.get("digest_mode"), "provider": d.get("provider"), "model": d.get("model_id"),
                        "completed_at": d.get("completed_at"), "sources": [], "immutable_content": True,
                    })
                    entry["sources"].append({
                        "ordinal": d.get("source_ordinal"), "source_ref": d.get("source_ref"), "locator": loc,
                        "evidence_sha256": d.get("evidence_sha256"), "excerpt_sha256": d.get("excerpt_sha256"),
                        "excerpt": str(d.get("excerpt") or ""),
                    })
        except Exception:
            return []
    result = list(out.values())
    result.sort(key=lambda x: (int(x.get("version_number") or 0), str(x.get("item_id") or "")))
    for item in result:
        if item.get("version_archive") or str(item.get("version_status") or "").casefold() == "archived":
            item["history_status"] = "archived_version"
            item["archive_reason"] = "Previous shared-knowledge digest version retained after a newer version became active."
        elif item.get("version_active"):
            item["history_status"] = "active_version"
        else:
            item["history_status"] = str(item.get("version_status") or "historical")
    return result


def _cme_candidate_refs(candidate: dict) -> set[str]:
    """Return source/evidence refs for both reflection and digestion candidates."""
    if not isinstance(candidate, dict):
        return set()
    values=[]
    for key in ("evidence_refs", "source_refs", "sources"):
        raw=candidate.get(key)
        if not isinstance(raw,list):
            continue
        for item in raw:
            if isinstance(item,dict):
                ref=str(item.get("ref") or item.get("source_ref") or "").strip()
            else:
                ref=str(item or "").strip()
            if ref:
                values.append(ref)
    return set(values)


def _chunk_memory_envelope(module, book_id: str, chunk_id: str, *, original_text: str | None = None,
                           original_ref: str | None = None, same_run_candidates: list[dict] | None = None,
                           surface: str = "reflection") -> dict:
    """Complete local interpretation history for exactly one source chunk.

    There is deliberately no memory-count cap. If this eventually exceeds a
    provider context window the operation must fail/resize explicitly rather
    than silently hide chunk-linked memories.
    """
    original = _cme_original_chunk(book_id, chunk_id, original_text=original_text, original_ref=original_ref)
    source_equivalence = _cse_source_equivalence(module, book_id, chunk_id, original)
    source_pairs = _cse_source_pairs(book_id, chunk_id, source_equivalence)
    personal = _cse_collect_personal_memories(module, source_pairs)
    shared = _cse_collect_shared_items(source_pairs)
    local_refs = {str(original.get("ref") or "")}
    local_refs.update(str(x.get("ref") or "") for x in personal)
    local_refs.update(str(s.get("source_ref") or "") for item in shared for s in (item.get("sources") or []))
    # Same-run digest candidates may cite either the current canonical ref or an
    # exact legacy-equivalent chunk ref.  Source equivalence is deterministic,
    # so all such provenance refs are valid anti-duplication match keys.
    for pair in source_pairs:
        pref=str(pair.get("provenance_ref") or "").strip()
        if pref:
            local_refs.add(pref)
        pbid=str(pair.get("book_id") or "").strip(); pcid=str(pair.get("chunk_id") or "").strip()
        if pbid and pcid:
            local_refs.add(f"book:{pbid}:{pcid}")
            local_refs.add(f"memorize-book:{pbid}:{pcid}")
    same_run = []
    for item in same_run_candidates or []:
        if not isinstance(item, dict):
            continue
        refs = _cme_candidate_refs(item)
        if refs and refs.intersection(local_refs):
            same_run.append(dict(item))
    archived_personal = sum(1 for x in personal if str(x.get("state") or "").casefold()=="archived" or str(x.get("temporal_status") or "").casefold() in {"archived","historical","retired"})
    archived_shared = sum(1 for x in shared if x.get("history_status")=="archived_version")
    surface = str(surface or "reflection").casefold()
    return {
        "schema": _CHUNK_MEMORY_ENVELOPE_VERSION,
        "complete": bool(original.get("available")),
        "book_id": str(book_id or ""), "chunk_id": str(chunk_id or ""), "surface": surface,
        "original_chunk": original,
        "neighbor_context": _cme_neighbor_context(book_id, chunk_id),
        "source_equivalence": source_equivalence,
        "source_pairs": source_pairs,
        "personal_memories": personal,
        "shared_knowledge_items": shared,
        "same_run_candidates": same_run,
        "counts": {
            "personal_memories": len(personal), "personal_archived": archived_personal,
            "shared_knowledge_items": len(shared), "shared_archived_versions": archived_shared,
            "same_run_candidates": len(same_run),
            "equivalent_books": len(source_equivalence.get("equivalent_books") or []),
            "equivalent_chunks": len(source_equivalence.get("equivalent_chunks") or []),
            "equivalent_legacy_books": sum(1 for x in source_equivalence.get("equivalent_books") or [] if x.get("authority")=="neatbooks_legacy"),
            "equivalent_legacy_chunks": sum(1 for x in source_equivalence.get("equivalent_chunks") or [] if x.get("authority")=="neatbooks_legacy"),
            "equivalent_personal_memories": sum(1 for x in personal if x.get("source_equivalence_matches")),
            "equivalent_shared_knowledge_items": sum(1 for x in shared if x.get("source_equivalence_matches")),
        },
        "memory_evolution_rules": {
            "read_original_chunk_before_writing": True,
            "all_chunk_linked_memories_visible": True,
            "include_archived_and_disputed": True,
            "include_same_run_candidates": True,
            "may_edit_existing_memory": False,
            "may_delete_existing_memory": False,
            "may_create_new_memory": True,
            "may_archive_personal_memory": True,
            "archive_is_reversible_retention": True,
            "archived_memories_remain_visible_here": True,
            "correction_rule": "Never rewrite an existing memory. If a materially wrong/obsolete personal memory should leave active continuity, archive it with evidence and create a new candidate that supersedes it; preserve the old ID/content/provenance.",
            "duplicate_rule": "Do not create a semantic duplicate merely because wording differs. Check active, disputed, archived, shared-version history, and same-run candidates first.",
            "shared_knowledge_rule": "Shared KI content is immutable. Digestion creates a new version; replacement archives the prior version as history instead of editing individual KIs.",
            "source_equivalence_rule": "Legacy memories/KIs may be loaded when exact source-file SHA-256 identity and exact ordered textual overlap connect their old chunk to this canonical chunk. This does not rewrite old provenance and does not make old claims evidence. The exact current original_chunk remains authoritative; use equivalent-source history to detect duplicates, corrections, conflicts, and prior rejected interpretations.",
        },
        "execution_surface": {
            "archive_personal_memory_now": surface == "reflection",
            "create_candidate_personal_memory_now": surface == "reflection",
            "create_shared_knowledge_item_now": surface == "digestion",
            "shared_version_replacement_archives_prior_version": surface == "digestion",
        },
    }



# ---------------------------------------------------------------------------
# Compact Complete Chunk Envelope (7.4.25.10.13.8.4)
# ---------------------------------------------------------------------------
_COMPACT_CHUNK_ENVELOPE_VERSION = "1.0-complete-semantics-compact-transport"


def _cme_nonempty_distinct(*values) -> list[str]:
    out=[]; seen=set()
    for value in values:
        raw=str(value or "")
        norm=" ".join(raw.split()).strip()
        if not norm or norm in seen:
            continue
        seen.add(norm); out.append(raw)
    return out


def _cme_compact_source_refs(links) -> list[str]:
    refs=[]
    for link in links or []:
        if not isinstance(link,dict):
            continue
        bid=str(link.get("book_id") or "").strip(); cid=str(link.get("chunk_id") or "").strip()
        if bid and cid:
            ref=f"book:{bid}:{cid}"
        else:
            st=str(link.get("source_type") or "").strip(); sid=str(link.get("source_id") or "").strip()
            ref=f"{st}:{sid}" if st and sid else ""
        if ref and ref not in refs:
            refs.append(ref)
    return refs


def _cme_compact_personal_for_model(item: dict) -> dict:
    values=_cme_nonempty_distinct(item.get("summary"),item.get("data"),item.get("interpretation"))
    out={
        "memory_id":item.get("memory_id"),
        "ref":item.get("ref"),
        "type":item.get("type"),
        "kind":item.get("kind"),
        "domain":item.get("domain"),
        "state":item.get("state"),
        "temporal_status":item.get("temporal_status"),
        "summary":values[0] if values else "",
        "additional_content":values[1:] if len(values)>1 else [],
        "confidence":item.get("confidence"),
        "archive_reason":item.get("archive_reason"),
        "supersedes_id":item.get("supersedes_id"),
        "superseded_by_ids":item.get("superseded_by_ids") or [],
        "source_refs":_cme_compact_source_refs(item.get("source_links") or []),
        "via_source_equivalence":bool(item.get("source_equivalence_matches")),
        "immutable":True,
    }
    return {k:v for k,v in out.items() if v not in (None,"",[],{})}


def _cme_compact_shared_for_model(item: dict) -> dict:
    values=_cme_nonempty_distinct(item.get("claim"),item.get("details"),item.get("interpretation"))
    source_refs=[]
    for src in item.get("sources") or []:
        ref=str(src.get("source_ref") or "").strip() if isinstance(src,dict) else ""
        if ref and ref not in source_refs:
            source_refs.append(ref)
    out={
        "item_id":item.get("item_id"),
        "ref":item.get("ref"),
        "kind":item.get("kind"),
        "domain":item.get("domain"),
        "claim":values[0] if values else "",
        "additional_content":values[1:] if len(values)>1 else [],
        "confidence":item.get("confidence"),
        "version_id":item.get("version_id"),
        "version_number":item.get("version_number"),
        "history_status":item.get("history_status"),
        "archive_reason":item.get("archive_reason"),
        "source_refs":source_refs,
        "via_source_equivalence":bool(item.get("source_equivalence_matches")),
        "immutable":True,
    }
    return {k:v for k,v in out.items() if v not in (None,"",[],{})}


def _cme_compact_candidate_for_model(item: dict) -> dict:
    refs=sorted(_cme_candidate_refs(item))
    out={
        "memory_id":item.get("memory_id") or item.get("candidate_id"),
        "memory_type":item.get("memory_type") or item.get("type") or "shared_knowledge_candidate",
        "kind":item.get("kind"),
        "claim":item.get("claim") or item.get("summary") or item.get("data"),
        "details":item.get("details"),
        "confidence":item.get("confidence"),
        "evidence_refs":refs,
        "same_run":True,
    }
    return {k:v for k,v in out.items() if v not in (None,"",[],{})}


def _cme_model_envelope(env: dict) -> dict:
    """Complete semantic history, compact transport form for model context.

    No linked memory/KI is omitted. Bulky source excerpts, locator objects,
    hashes, provider metadata, and repeated source-equivalence diagnostics are
    removed because the exact original chunk is already present once.
    """
    original=dict(env.get("original_chunk") or {})
    original_model={k:original.get(k) for k in (
        "available","authority","book_id","chunk_id","ordinal","char_start","char_end","ref","text","text_sha256","exact"
    ) if original.get(k) is not None}
    personal=[_cme_compact_personal_for_model(x) for x in env.get("personal_memories") or [] if isinstance(x,dict)]
    shared=[_cme_compact_shared_for_model(x) for x in env.get("shared_knowledge_items") or [] if isinstance(x,dict)]
    same_run=[_cme_compact_candidate_for_model(x) for x in env.get("same_run_candidates") or [] if isinstance(x,dict)]
    equivalence=env.get("source_equivalence") or {}
    eq_summary={
        "schema":equivalence.get("schema"),
        "read_only":equivalence.get("read_only"),
        "provenance_rewritten":equivalence.get("provenance_rewritten"),
        "target_authority":equivalence.get("target_authority"),
        "source_file_sha256":equivalence.get("source_file_sha256"),
        "equivalent_book_refs":[f"{x.get('authority')}:{x.get('book_id')}" for x in equivalence.get("equivalent_books") or [] if x.get("book_id")],
        "equivalent_chunk_refs":[str(x.get("provenance_ref") or f"book:{x.get('book_id')}:{x.get('chunk_id')}") for x in equivalence.get("equivalent_chunks") or [] if x.get("chunk_id")],
        "semantic_matching":False,
    }
    rules=env.get("memory_evolution_rules") or {}
    compact_rules={k:rules.get(k) for k in (
        "read_original_chunk_before_writing","all_chunk_linked_memories_visible","include_archived_and_disputed",
        "include_same_run_candidates","may_edit_existing_memory","may_delete_existing_memory","may_create_new_memory",
        "may_archive_personal_memory","archive_is_reversible_retention","duplicate_rule","correction_rule","shared_knowledge_rule"
    ) if k in rules}
    out={
        "schema":_COMPACT_CHUNK_ENVELOPE_VERSION,
        "complete":env.get("complete"),
        "book_id":env.get("book_id"),
        "chunk_id":env.get("chunk_id"),
        "surface":env.get("surface"),
        "original_chunk":original_model,
        "neighbor_context":dict(env.get("neighbor_context") or {}),
        "personal_memories":personal,
        "shared_knowledge_items":shared,
        "same_run_candidates":same_run,
        "counts":dict(env.get("counts") or {}),
        "source_equivalence":eq_summary,
        "memory_evolution_rules":compact_rules,
        "execution_surface":dict(env.get("execution_surface") or {}),
        "transport_guarantees":{
            "all_personal_memory_ids_preserved":len(personal)==len(env.get("personal_memories") or []),
            "all_shared_ki_ids_preserved":len(shared)==len(env.get("shared_knowledge_items") or []),
            "all_same_run_candidates_preserved":len(same_run)==len(env.get("same_run_candidates") or []),
            "original_chunk_text_preserved_exactly":original_model.get("text")==original.get("text"),
            "source_excerpts_repeated":False,
            "neighbor_chunks_full_context_only":True,
            "neighbor_chunks_may_ground_output":False,
        },
    }
    return out


def _cme_json_size(value) -> int:
    return len(json.dumps(value,ensure_ascii=False,separators=(",",":")))


def _cme_estimated_tokens(value) -> int:
    # Conservative transport estimate for diagnostics only; provider tokenizer
    # remains authoritative. Four UTF-8-ish text characters per token is a
    # useful rough upper-level planning estimate for this English-heavy data.
    return max(1,(_cme_json_size(value)+3)//4)


def _cme_chunk_memory_ids(envelopes: list[dict]) -> tuple[set[str],set[str]]:
    active=set(); archived=set()
    for env in envelopes or []:
        for item in env.get("personal_memories") or []:
            mid=str(item.get("memory_id") or "").strip()
            if not mid:
                continue
            is_archived=(str(item.get("state") or "").casefold()=="archived" or str(item.get("temporal_status") or "").casefold() in {"archived","historical","retired"})
            (archived if is_archived else active).add(mid)
    return active,archived


def _cme_reflection_item_from_personal(item: dict) -> dict:
    return {
        "ref": item.get("ref"), "memory_id": item.get("memory_id"), "type": item.get("type"), "kind": item.get("kind"),
        "domain": item.get("domain"), "interpretation": item.get("interpretation"), "summary": item.get("summary"),
        "data": item.get("data"), "confidence": item.get("confidence"), "importance": item.get("importance"),
        "state": item.get("state"), "temporal_status": item.get("temporal_status"), "archive_reason": item.get("archive_reason"),
        "supersedes_id": item.get("supersedes_id"), "superseded_by_ids": item.get("superseded_by_ids") or [],
        "archived": bool(str(item.get("state") or "").casefold()=="archived" or str(item.get("temporal_status") or "").casefold() in {"archived","historical","retired"}),
    }


def _cme_enrich_reflection_chunk_context(module, book_passages: list[dict], memory_evidence: list[dict],
                                          archived_memory_evidence: list[dict], same_run_candidates: list[dict]) -> tuple[list[dict],list[dict],list[dict]]:
    envelopes=[]; seen_chunks=set(); active_ids={str(x.get("memory_id") or x.get("id") or "") for x in memory_evidence}; archived_ids={str(x.get("memory_id") or x.get("id") or "") for x in archived_memory_evidence}
    for passage in book_passages or []:
        if not isinstance(passage, dict): continue
        bid=str(passage.get("book_id") or "").strip(); cid=str(passage.get("chunk_id") or "").strip()
        if not bid or not cid or (bid,cid) in seen_chunks: continue
        seen_chunks.add((bid,cid))
        env=_chunk_memory_envelope(module,bid,cid,original_ref=str(passage.get("ref") or "") or None,same_run_candidates=same_run_candidates,surface="reflection")
        envelopes.append(env)
        for raw in env.get("personal_memories") or []:
            item=_cme_reflection_item_from_personal(raw); mid=str(item.get("memory_id") or "")
            if not mid: continue
            if item.get("archived"):
                if mid not in archived_ids:
                    archived_ids.add(mid); archived_memory_evidence.append(item)
            else:
                if mid not in active_ids:
                    active_ids.add(mid); memory_evidence.append(item)
    return memory_evidence, archived_memory_evidence, envelopes


def _cme_normal_book_call(digest_module, memory_module, backend, book: dict, scope: str, batch: list[dict], batch_number: int, total_batches: int):
    registry=digest_module._book_source_registry(book,batch)
    sources=[]; envelopes=[]
    same_run_candidates=list(getattr(digest_module,"_CME_DIGEST_SAME_RUN_CANDIDATES",[]) or [])
    for row in batch:
        cid=str(row.get("chunk_id") or ""); ref=f"book:{book.get('book_id')}:{cid}"
        src=registry.get(ref) or {}
        sources.append({"ref":ref,"chunk":src.get("ordinal"),"chapter":src.get("chapter"),"pages":[src.get("page_start"),src.get("page_end")],"content":src.get("excerpt")})
        envelopes.append(_chunk_memory_envelope(memory_module,str(book.get("book_id") or ""),cid,original_text=str(row.get("text") or ""),original_ref=ref,same_run_candidates=same_run_candidates,surface="digestion"))
    model_envelopes=[_cme_model_envelope(e) for e in envelopes]
    model_sources=[{k:x.get(k) for k in ("ref","chunk","chapter","pages") if x.get(k) is not None} for x in sources]
    packet={
        "book":{"book_id":book.get("book_id"),"title":book.get("title"),"authors":book.get("authors") or [],"publication_year":book.get("publication_year"),"source_type":book.get("source_type"),"access_status":book.get("access_status")},
        "scope":scope,"batch":{"number":batch_number,"total":total_batches},"sources":model_sources,"chunk_memory_envelopes":model_envelopes,
        "context_transport":{"version":_COMPACT_CHUNK_ENVELOPE_VERSION,"all_chunk_linked_memories_preserved":True,"source_text_present_once_in_original_chunk":True,"full_envelope_estimated_tokens":sum(_cme_estimated_tokens(e) for e in envelopes),"compact_envelope_estimated_tokens":sum(_cme_estimated_tokens(e) for e in model_envelopes)},
    }
    max_memories=int(getattr(digest_module,"BOOK_DIGEST_MAX_MEMORIES",24))
    system=f"""You are NeatDigest's chunk-memory-aware book curator. Return one JSON object only.
For every supplied source chunk, first read its chunk_memory_envelope. The exact original_chunk is the target authority. neighbor_context supplies the FULL previous and next chunks only for continuity; never summarize, extract, create a memory from, or cite context-only neighbors during this target pass. Every personal memory and shared KI already linked to that chunk is supplied in the envelope, including archived/disputed/history versions and same-run candidates when present. The envelope can also include legacy-source history deterministically connected by exact source-file SHA-256 plus exact ordered textual overlap; that history keeps its old provenance and is anti-duplication/correction context, not replacement evidence. Treat old memory content as immutable history: never rewrite or silently correct it. Do not recreate a semantic duplicate with different wording. Archived memories are intentionally visible so rejected/superseded ideas are not accidentally recreated. If the source supports a materially different correction, create a new memory; do not edit the old one. Shared KI replacement is versioned/archival, never in-place editing.
Create zero to {max_memories} durable atomic shared-knowledge memories for this bounded batch. Every new memory must cite one or more exact source_refs from sources. Do not invent content outside the exact chunks. Do not create personal memories about the user. Attribute opinions/fiction/historical perspectives rather than converting them to universal fact. Prefer stable definitions, concepts, methods, important arguments, useful questions, and artifacts. Use kind fact, question, or artifact only. Paraphrase rather than copying long passages. Return batch_complete=true."""
    result=_sk_call_json(digest_module,backend,system=system,user=json.dumps(packet,ensure_ascii=False),max_tokens=int(getattr(digest_module,"BOOK_DIGEST_MAX_OUTPUT_TOKENS",12000)),schema=_sk_book_schema(deep=False),schema_name="neatmemory_chunk_memory_book_digest_v1",deep=False)
    return result,registry


# Preserve the 10.11 deep validator/gate while replacing the bounded model packet.
def _sk_deep_book_model(digest_module, backend, book: dict, row: dict, previous_items: list[dict], chunk_index: int, total_chunks: int) -> tuple[dict,dict,int,dict]:
    registry=digest_module._book_source_registry(book,[row]); ref,src=next(iter(registry.items())); source_text=str(row.get("text") if row.get("text") is not None else src.get("excerpt") or "")
    memory_module=sys.modules.get("neatmemory_v7_0_stable")
    same_run_candidates=list(getattr(digest_module,"_CME_DIGEST_SAME_RUN_CANDIDATES",[]) or [])
    envelope=_chunk_memory_envelope(memory_module,str(book.get("book_id") or ""),str(row.get("chunk_id") or ""),original_text=source_text,original_ref=ref,same_run_candidates=same_run_candidates,surface="digestion") if memory_module is not None else {"original_chunk":{"ref":ref,"text":source_text,"exact":True},"personal_memories":[],"shared_knowledge_items":list(previous_items or []),"same_run_candidates":same_run_candidates,"memory_evolution_rules":{"may_edit_existing_memory":False,"may_create_new_memory":True},"counts":{"personal_memories":0,"shared_knowledge_items":len(previous_items or []),"same_run_candidates":len(same_run_candidates)}}
    model_envelope=_cme_model_envelope(envelope)
    packet={"book":{"book_id":book.get("book_id"),"title":book.get("title"),"authors":book.get("authors") or []},"chunk":{"number":chunk_index,"total":total_chunks,"ref":ref,"ordinal":row.get("ordinal"),"chapter":row.get("chapter")},"chunk_memory_envelope":model_envelope,"previous_active_digest_item_ids":[str(x.get("item_id") or x.get("memory_id") or "") for x in previous_items or [] if isinstance(x,dict) and (x.get("item_id") or x.get("memory_id"))],"context_transport":{"version":_COMPACT_CHUNK_ENVELOPE_VERSION,"source_text_present_once_in_original_chunk":True,"full_envelope_estimated_tokens":_cme_estimated_tokens(envelope),"compact_envelope_estimated_tokens":_cme_estimated_tokens(model_envelope)}}
    schema=_sk_book_schema(deep=True); max_memories=min(_DEEP_MAX_MEMORIES_PER_CHUNK,int(getattr(digest_module,'BOOK_DIGEST_MAX_MEMORIES',24))+8); output_cap=_sk_deep_output_cap(digest_module,backend,max_memories=max_memories)
    system=f"""You are NeatMemory's deep archival chunk curator. Work source-first on exactly one book chunk. Before proposing anything, inspect the complete chunk_memory_envelope: exact original chunk, FULL previous/next chunks in neighbor_context as context-only continuity, every personal memory linked to the target in every state, every shared-KI version linked to it including archived versions, same-run candidates when present, and any deterministic source_equivalence history from legacy chunks of the exact same source file. The original chunk is the ONLY target evidence for outputs in this pass; neighbor_context may clarify continuity but must never be summarized/cited or used to create a memory until that neighbor becomes the target. All prior memories are immutable interpretation history and may be wrong. Never rewrite an old memory and never recreate a semantic duplicate merely by rephrasing it. Archived memories remain visible specifically to prevent accidental recreation. If a materially corrected/new interpretation is needed, create a new memory rather than editing the old one. Extract only durable atomic knowledge, relationships, chronology, named entities, objects, unresolved references and important details. Every memory must cite the exact supplied source ref. Explicit entities must literally occur in the chunk. Inferred entities require confidence and a concrete reason. Add only high-value implicit_keywords strongly supported by the chunk; they are navigation aids, never evidence. Keep at most {_DEEP_MAX_IMPLICIT_PER_MEMORY} implicit concepts per memory. Return JSON only, batch_complete=true, at most {max_memories} memories."""
    draft=_sk_call_json(digest_module,backend,system=system,user=json.dumps(packet,ensure_ascii=False),max_tokens=output_cap,schema=schema,schema_name="neatmemory_deep_chunk_memory_extract_v1",deep=True)
    audit=_sk_deep_validate_payload(draft,registry,source_text,max_memories=max_memories); calls=1
    if audit["ok"]:
        return draft,registry,calls,{"python_gate":"pass","second_model_pass":False,"python_repairs":[],"issues":[],"warnings":audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset","chunk_memory_envelope_counts":envelope.get("counts",{})}
    repaired,repairs=_sk_deep_safe_metadata_repair(draft,source_text); repaired_audit=_sk_deep_validate_payload(repaired,registry,source_text,max_memories=max_memories)
    if repairs and repaired_audit["ok"]:
        return repaired,registry,calls,{"python_gate":"metadata_repair","second_model_pass":False,"python_repairs":repairs,"initial_issues":audit["issues"],"issues":[],"warnings":repaired_audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset","chunk_memory_envelope_counts":envelope.get("counts",{})}
    verify_packet={"source":packet["chunk"],"chunk_memory_envelope":model_envelope,"draft":repaired,"python_validation_issues":repaired_audit["issues"],"python_metadata_repairs":repairs}
    verify_system="""You are a conditional verification pass for a permanent source-grounded archive. Re-read the exact target original chunk, its full previous/next context-only neighbors, and its complete chunk-memory envelope. Neighbor chunks are continuity only and must not ground, be summarized by, or be cited by any output in this pass. Correct concrete validation problems without rewriting any existing memory. Remove unsupported or duplicate claims, fix invalid source refs, preserve uncertainty, and create only materially new/corrected memories. Archived/history memories remain visible and must not be recreated just by paraphrasing. The original source outranks both old memories and the draft. Return the final schema only with batch_complete=true."""
    final=_sk_call_json(digest_module,backend,system=verify_system,user=json.dumps(verify_packet,ensure_ascii=False),max_tokens=output_cap,schema=schema,schema_name="neatmemory_deep_chunk_memory_verify_v1",deep=True); calls+=1
    final_audit=_sk_deep_validate_payload(final,registry,source_text,max_memories=max_memories); post_repairs=[]
    if not final_audit["ok"]:
        final,post_repairs=_sk_deep_safe_metadata_repair(final,source_text); final_audit=_sk_deep_validate_payload(final,registry,source_text,max_memories=max_memories)
    if not final_audit["ok"]:
        raise RuntimeError("Deep conditional verifier still failed deterministic validation: "+"; ".join(final_audit["issues"][:8]))
    return final,registry,calls,{"python_gate":"conditional_verify"+("+metadata_repair" if post_repairs else ""),"second_model_pass":True,"python_repairs":repairs+post_repairs,"initial_issues":audit["issues"],"issues":[],"warnings":final_audit["warnings"],"output_cap":output_cap,"max_memories":max_memories,"reasoning_control":"assistant-selected; API effort unset","verify_reasoning_control":"assistant-selected; API effort unset","chunk_memory_envelope_counts":envelope.get("counts",{})}


