# Extend the existing shared-knowledge console without changing legacy commands.
_SD_BASE_SK_DISPATCH = _sk_dispatch_command

def _sk_dispatch_command(module, raw: str) -> bool:
    """Extend knowledge-map commands while preserving legacy /redigest --force dispatch unchanged."""
    clean=" ".join(str(raw or "").strip().split()); low=clean.casefold()
    if low.startswith("/knowledge structure ") or low.startswith("/knowledge semantic "):
        parts=clean.split()
        if len(parts)<3:
            raise ValueError("Use /knowledge structure <BK-ID> [version-id].")
        version_id=parts[3] if len(parts)>3 else ""
        print(json.dumps(_sd_book_map(parts[2],version_id=version_id,limit=1000),ensure_ascii=False,indent=2)); return True
    return _SD_BASE_SK_DISPATCH(module,raw)


