_SEMANTIC_HYPERROAD_NAVIGATION_VERSION = "1.1-concise-route-card-direct-original-exit"
_SHN_ROUTE_HINT_CHARS = 160
_SHN_VIEWS = {"route", "detail"}


def _shn_compact_hint(value: object, limit: int = _SHN_ROUTE_HINT_CHARS) -> str:
    """Return a scan-sized derived orientation whose final visible length never exceeds the cap."""
    clean = " ".join(str(value or "").strip().split())
    cap = max(80, min(400, int(limit or _SHN_ROUTE_HINT_CHARS)))
    if len(clean) <= cap:
        return clean
    ellipsis = "…"
    body_cap = max(1, cap - len(ellipsis))
    cut = clean[:body_cap + 1]
    boundary = cut.rfind(" ")
    if boundary >= body_cap // 2:
        cut = cut[:boundary]
    else:
        cut = cut[:body_cap]
    cut = cut.rstrip(" ,;:-") or clean[:body_cap]
    return (cut + ellipsis)[:cap]


def _shn_int_or_none(value: object) -> int | None:
    try:
        return int(value)
    except Exception:
        return None


def _shn_original_source_exit(book_id: str, source_range: dict) -> dict:
    """Build one-hop immutable-source and neighbor reads from stored coordinates."""
    span = dict(source_range or {})
    start = list(span.get("start") or [])
    end = list(span.get("end") or [])
    start_chunk = start[0] if len(start) > 0 else None
    start_ordinal = _shn_int_or_none(start[1] if len(start) > 1 else None)
    start_char = _shn_int_or_none(start[2] if len(start) > 2 else None)
    end_chunk = end[0] if len(end) > 0 else None
    end_ordinal = _shn_int_or_none(end[1] if len(end) > 1 else None)
    end_char = _shn_int_or_none(end[2] if len(end) > 2 else None)
    if start_ordinal is None:
        return {
            "available": False,
            "reason": "The derived node has no original chunk ordinal.",
            "verification_required_before_claim": True,
        }
    first_read = {"book_id": str(book_id or ""), "start": start_ordinal, "count": 1}
    neighbors = []
    if start_ordinal > 1:
        neighbors.append({
            "relation": "previous_chunk",
            "tool": "read_book_chunks",
            "arguments": {"book_id": str(book_id or ""), "start": start_ordinal - 1, "count": 1},
        })
    if end_ordinal is not None:
        neighbors.append({
            "relation": "next_chunk",
            "tool": "read_book_chunks",
            "arguments": {"book_id": str(book_id or ""), "start": end_ordinal + 1, "count": 1},
        })
    span_count = max(1, (end_ordinal - start_ordinal + 1) if end_ordinal is not None else 1)
    return {
        "available": True,
        "tool": "read_book_chunks",
        "arguments": first_read,
        "exact_derived_span": {
            "start_chunk_id": start_chunk,
            "start_ordinal": start_ordinal,
            "start_char": start_char,
            "end_chunk_id": end_chunk,
            "end_ordinal": end_ordinal,
            "end_char": end_char,
            "derived_span_sha256": span.get("source_sha256"),
            "chunk_count": span_count,
        },
        "neighbor_reads": neighbors,
        "continuation": "Read one original chunk at a time when the derived span crosses multiple chunks.",
        "verification_required_before_claim": True,
    }


def _shn_route_node(node: dict, book_id: str) -> dict:
    source_range = dict(node.get("source_range") or {})
    hint = _shn_compact_hint(node.get("resume_excerpt"))
    route = {
        "node_type": node.get("node_type"),
        "node_id": node.get("node_id"),
        "node_ref": node.get("node_ref"),
        "sequence_no": node.get("sequence_no"),
        "kind": node.get("kind"),
        "title": node.get("title"),
        "route_card": {
            "derived_hint": hint,
            "derived_hint_characters": len(hint),
            "stored_resume_characters": int(node.get("resume_characters") or 0),
            "role": "derived_navigation_signpost_not_original_evidence",
            "verification_required_before_claim": True,
            "scope": {
                "coverage_status": node.get("coverage_status") or "semantic_unit_span",
                "source_span_is_exact": True,
                "semantic_claim_verification": "not_assessed_by_python",
            },
        },
        "matched_fields": list(node.get("matched_fields") or []),
        "source_range": source_range,
        "original_source_exit": _shn_original_source_exit(book_id, source_range),
        "derived_detail_exit": dict(node.get("exact_read") or {}),
        "linked_record_count": int(node.get("linked_record_count") or 0),
    }
    for key in ("structure", "coverage_status", "coverage"):
        if key in node:
            route[key] = node.get(key)
    return route


def _shn_project_page(result: dict, view: str) -> dict:
    output = dict(result or {})
    if not output.get("ok"):
        return output
    chosen = str(view or "route").casefold().strip()
    if chosen not in _SHN_VIEWS:
        return {
            "ok": False,
            "error": "view must be route or detail.",
            "read_only": True,
            "model_calls": 0,
            "web_calls": 0,
        }
    book_id = str(output.get("book_id") or "")
    if chosen == "route":
        output["nodes"] = [_shn_route_node(dict(node), book_id) for node in output.get("nodes") or []]
    else:
        detailed = []
        for original in output.get("nodes") or []:
            node = dict(original)
            node["original_source_exit"] = _shn_original_source_exit(book_id, dict(node.get("source_range") or {}))
            node["derived_content_role"] = "derived_navigation_detail_not_original_evidence"
            node["verification_required_before_claim"] = True
            detailed.append(node)
        output["nodes"] = detailed
    output.update({
        "version": _SEMANTIC_HYPERROAD_NAVIGATION_VERSION,
        "view": chosen,
        "route_card_default": True,
        "detailed_resume_included": chosen == "detail",
        "stored_summaries_modified": False,
        "redigest_required": False,
        "one_hop_original_source_exit": True,
        "authority": "Derived summaries select where to look; exact original book chunks determine what may be claimed.",
    })
    return output


_SHN_BASE_SEARCH_BOOK_MAP = _smn_search_book_map


def _smn_search_book_map(book_id: str, *, version_id: str = "", query: str = "",
                         include: str = "all", offset: int = 0, limit: int = _SMN_DEFAULT_LIMIT,
                         view: str = "route") -> dict:
    chosen = str(view or "route").casefold().strip()
    if chosen not in _SHN_VIEWS:
        return {"ok": False, "error": "view must be route or detail.", "read_only": True, "model_calls": 0, "web_calls": 0}
    base = _SHN_BASE_SEARCH_BOOK_MAP(
        book_id, version_id=version_id, query=query, include=include, offset=offset, limit=limit,
    )
    return _shn_project_page(base, chosen)


def semantic_hyperroad_navigation_self_test(module=None) -> dict:
    module = module or _load_memory()
    inherited = semantic_map_navigation_self_test(module)
    sample = {
        "ok": True,
        "book_id": "BK-HYPERROAD-TEST",
        "nodes": [{
            "node_type": "semantic_unit", "node_id": "SDU-HYPERROAD-1", "node_ref": "semantic:SDU-HYPERROAD-1",
            "sequence_no": 1, "kind": "method", "title": "Class size paradox",
            "resume_excerpt": "A detailed derived explanation. " * 40, "resume_characters": 1200,
            "matched_fields": ["title"], "linked_record_count": 1,
            "source_range": {"start": ["BK-HYPERROAD-TEST-C000007", 7, 110], "end": ["BK-HYPERROAD-TEST-C000008", 8, 240], "source_sha256": "abc"},
            "exact_read": {"tool": "read_book_semantic_unit", "arguments": {"unit_id": "SDU-HYPERROAD-1"}},
        }],
        "model_calls": 0, "web_calls": 0,
    }
    route = _shn_project_page(sample, "route")
    first = dict((route.get("nodes") or [{}])[0])
    route_card = dict(first.get("route_card") or {})
    source_exit = dict(first.get("original_source_exit") or {})
    detail = _shn_project_page(sample, "detail")
    detailed_node = dict((detail.get("nodes") or [{}])[0])
    invariance = dict(getattr(module, "_SEMANTIC_HYPERROAD_SPEECH_INVARIANCE", {}) or {})
    online_schema = next((item for item in globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS", []) if isinstance(item, dict) and str(item.get("name") or "") == "book_semantic_map"), {})
    local_schema = next((item for item in getattr(module, "TOOL_SCHEMAS", []) if str((item.get("function") or {}).get("name") or "") == "book_semantic_map"), {})
    online_view = (((online_schema.get("parameters") or {}).get("properties") or {}).get("view") or {}).get("enum")
    local_view = (((((local_schema.get("function") or {}).get("parameters") or {}).get("properties") or {}).get("view") or {}).get("enum"))
    checks = {
        "prior_semantic_navigation_contract_still_passes": bool(inherited.get("ok")),
        "route_projection_is_available": route.get("view") == "route",
        "route_card_is_scan_sized": bool(route_card) and len(str(route_card.get("derived_hint") or "")) <= _SHN_ROUTE_HINT_CHARS,
        "route_omits_miniature_essay": "resume_excerpt" not in first,
        "derived_hint_is_not_source_authority": route_card.get("role") == "derived_navigation_signpost_not_original_evidence" and route_card.get("verification_required_before_claim") is True,
        "direct_original_exit_is_one_hop": source_exit.get("available") is True and source_exit.get("tool") == "read_book_chunks" and int((source_exit.get("arguments") or {}).get("count") or 0) == 1,
        "neighbor_coordinates_are_exposed": isinstance(source_exit.get("neighbor_reads"), list),
        "detailed_resume_requires_explicit_view": detail.get("view") == "detail" and "resume_excerpt" in detailed_node,
        "stored_summaries_are_unchanged": detail.get("stored_summaries_modified") is False and detail.get("redigest_required") is False,
        "online_and_local_tools_expose_route_detail_choice": online_view == ["route", "detail"] and local_view == ["route", "detail"],
        "installer_did_not_modify_speech_surfaces": bool(invariance) and all(bool(value) for value in invariance.values()),
        "zero_model_zero_web": detail.get("model_calls") == 0 and detail.get("web_calls") == 0,
    }
    return {
        "ok": all(bool(value) for value in checks.values()),
        "checks": checks,
        "details": {"route_node": first, "explicit_detail_projection": detail},
        "version": _SEMANTIC_HYPERROAD_NAVIGATION_VERSION,
        "model_calls": 0,
        "web_calls": 0,
        "live_database_modified": False,
    }


def _install_semantic_hyperroad_navigation(module) -> None:
    if getattr(module, "_SEMANTIC_HYPERROAD_NAVIGATION_INSTALLED", False):
        return
    system_before = hashlib.sha256(str(getattr(module, "SYSTEM_PROMPT", "")).encode("utf-8")).hexdigest()
