    context_before = id(getattr(module, "build_runtime_context", None))

    schema = {
        "type": "function",
        "name": "book_semantic_map",
        "description": "Search or page one book's derived semantic map. Defaults to lightweight route cards: short visibly-derived signposts, exact source ranges/hashes, and direct read_book_chunks exits with neighboring-chunk coordinates. Use view=detail only when the longer derived resume is actually needed. Derived text chooses where to look; original chunks determine what may be claimed.",
        "parameters": {
            "type": "object",
            "properties": {
                "book_id": {"type": "string"}, "version_id": {"type": "string"}, "query": {"type": "string"},
                "include": {"type": "string", "enum": ["all", "semantic_units", "structural_resumes"]},
                "offset": {"type": "integer", "minimum": 0}, "limit": {"type": "integer", "minimum": 1, "maximum": 50},
                "view": {"type": "string", "enum": ["route", "detail"]},
            },
            "required": ["book_id"],
            "additionalProperties": False,
        },
        "strict": False,
    }

    def replace_schema(array, replacement):
        if not isinstance(array, list):
            return
        for index, item in enumerate(array):
            if isinstance(item, dict) and str(item.get("name") or "") == "book_semantic_map":
                array[index] = replacement
                return

    for array_name in ("_ONLINE_BOOK_RESPONSE_TOOLS", "_ONLINE_EVIDENCE_RESPONSE_TOOLS"):
        replace_schema(globals().get(array_name), schema)

    if isinstance(getattr(module, "TOOL_SCHEMAS", None), list):
        local_schema = {"type": "function", "function": {key: value for key, value in schema.items() if key not in {"type", "strict"}}}
        for index, item in enumerate(module.TOOL_SCHEMAS):
            if str((item.get("function") or {}).get("name") or "") == "book_semantic_map":
                module.TOOL_SCHEMAS[index] = local_schema
                break

    old_evidence = globals().get("_ora_execute_evidence_tool")
    if callable(old_evidence):
        def execute_hyperroad(mod, name, arguments):
            args = dict(arguments or {}) if isinstance(arguments, dict) else {}
            if str(name or "") == "book_semantic_map":
                return _ora_clean_result(mod, _smn_search_book_map(
                    str(args.get("book_id") or ""), version_id=str(args.get("version_id") or ""),
                    query=str(args.get("query") or ""), include=str(args.get("include") or "all"),
                    offset=int(args.get("offset") or 0), limit=int(args.get("limit") or _SMN_DEFAULT_LIMIT),
                    view=str(args.get("view") or "route"),
                ))
            return old_evidence(mod, name, arguments)
        globals()["_ora_execute_evidence_tool"] = execute_hyperroad

    old_execute = getattr(module, "execute_tool", None)
    if callable(old_execute):
        def execute_local_hyperroad(name, arguments, seen, *args, **kwargs):
            tool_args = dict(arguments or {}) if isinstance(arguments, dict) else {}
            if name == "book_semantic_map":
                return _smn_search_book_map(
                    str(tool_args.get("book_id") or ""), version_id=str(tool_args.get("version_id") or ""),
                    query=str(tool_args.get("query") or ""), include=str(tool_args.get("include") or "all"),
                    offset=int(tool_args.get("offset") or 0), limit=int(tool_args.get("limit") or _SMN_DEFAULT_LIMIT),
                    view=str(tool_args.get("view") or "route"),
                )
            return old_execute(name, arguments, seen, *args, **kwargs)
        module.execute_tool = execute_local_hyperroad

    module.search_book_semantic_map = lambda book_id, version_id="", query="", include="all", offset=0, limit=_SMN_DEFAULT_LIMIT, view="route": _smn_search_book_map(
        book_id, version_id=version_id, query=query, include=include, offset=offset, limit=limit, view=view,
    )
    module.semantic_hyperroad_navigation_self_test = lambda: semantic_hyperroad_navigation_self_test(module)
    module.SEMANTIC_HYPERROAD_NAVIGATION_VERSION = _SEMANTIC_HYPERROAD_NAVIGATION_VERSION
    module._SEMANTIC_HYPERROAD_SPEECH_INVARIANCE = {
        "system_prompt_sha256_unchanged": system_before == hashlib.sha256(str(getattr(module, "SYSTEM_PROMPT", "")).encode("utf-8")).hexdigest(),
        "run_online_chat_turn_callable_unchanged": chat_before == id(getattr(module, "run_online_chat_turn", None)),
        "runtime_context_builder_unchanged": context_before == id(getattr(module, "build_runtime_context", None)),
    }
    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["semantic-hyperroad-navigation"] = {
            "label": "Lightweight derived route cards, explicit detail descent, and direct original/neighbor source exits",
            "groups": ("quick", "critical", "all"),
            "runner": "memory.semantic_hyperroad_navigation_self_test",
        }
    suites = globals().get("_SELF_TEST_NAMED_SUITES")
    if isinstance(suites, dict):
        checkpoint = list(suites.get("checkpoint") or ())
        if "semantic-hyperroad-navigation" not in checkpoint:
            checkpoint.append("semantic-hyperroad-navigation")
        suites["checkpoint"] = tuple(checkpoint)
    module._SEMANTIC_HYPERROAD_NAVIGATION_INSTALLED = True


