# New snapshots automatically receive a deterministic source-word baseline.
_RKW_BASE_RESEARCH_STORE_PAGE=_research_store_page
def _research_store_page(module, web_module, requested_url: str, raw: bytes, charset: str, final_url: str, *, content_type: str="text/html") -> dict:
    out=dict(_RKW_BASE_RESEARCH_STORE_PAGE(module,web_module,requested_url,raw,charset,final_url,content_type=content_type))
    sid=str(out.get("snapshot_id") or "")
