# Keyword route is searched first, then the established full-text archive route.
_RKW_BASE_AWR_SEARCH_ARCHIVE=_awr_search_archive
def _awr_search_archive(module, query: str, limit: int=8, excerpt_chars: int=1400) -> dict:
    clean=" ".join(str(query or "").split()).strip(); limit=_awr_int(limit,8,1,30)
    keyword_hits=_rkw_search(module,"snapshot",clean,limit=max(limit,12)) if clean else []
    results=[]; seen=set()
    for hit in keyword_hits:
        sid=str(hit.get("target_id") or ""); full=_research_read_full_text(module,sid)
        if not full.get("ok"): continue
        text=str(full.get("text") or ""); pos,matched=_awr_find_position(text,clean); chars=_awr_int(excerpt_chars,1400,400,_ARCHIVED_WEB_RECALL_MAX_EXCERPT_CHARS)
        start=max(0,pos-chars//3); end=min(len(text),start+chars)
        if end-start<chars and start>0: start=max(0,end-chars)
        head=_rkw_head(module,"snapshot",sid) or {}
        results.append({**_awr_snapshot_public(dict(full.get("snapshot") or {})),"match_start":int(pos),"matched_term":matched,"excerpt_start":int(start),"excerpt_end":int(end),"excerpt":text[start:end],"has_more_before":start>0,"has_more_after":end<len(text),"keyword_match_count":int(hit.get("match_count") or 0),"matched_keywords":str(hit.get("matched_keywords") or "").split(),"navigation_keywords":list(head.get("keywords") or []),"research_keyword_revision_id":head.get("current_revision_id"),"route":"research_keywords"})
        seen.add(sid)
        if len(results)>=limit: break
    base=_RKW_BASE_AWR_SEARCH_ARCHIVE(module,clean,limit=max(limit,12),excerpt_chars=excerpt_chars)
    for row in list(base.get("results") or []):
        sid=str((row or {}).get("snapshot_id") or "")
        if not sid or sid in seen: continue
        # Lazily seed exact-source keywords for a snapshot already found by FTS.
        try: _rkw_ensure_snapshot(module,sid)
        except Exception: pass
        item=dict(row); head=_rkw_head(module,"snapshot",sid) or {}; item["navigation_keywords"]=list(head.get("keywords") or []); item["research_keyword_revision_id"]=head.get("current_revision_id"); item["route"]="archive_full_text"
        results.append(item); seen.add(sid)
