_RKW_BASE_AWR_SEARCH_UNITS=_awr_search_units
def _awr_search_units(module, query: str="", limit: int=12) -> dict:
    clean=" ".join(str(query or "").split()).strip(); limit=_awr_int(limit,12,1,50)
    # Evidence units live in immutable research reports rather than a dedicated
    # source table, so baseline keyword rows are lazily materialized once from
