            uid=str(unit.get("unit_id") or "")
            if uid in wanted and uid not in by_id:
                by_id[uid]={"run_id":run_id,"unit_id":uid,"source_ref":unit.get("source_ref"),"unit_title":unit.get("unit_title"),"unit_kind":unit.get("unit_kind"),"resume":unit.get("resume"),"url":unit.get("url"),"snapshot_id":unit.get("snapshot_id"),"start":unit.get("start"),"end":unit.get("end"),"use_for_analysis":unit.get("use_for_analysis"),"report_file":path.name}
