# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:book-search-precision rev=1
# NeatMemory 7.4.78.12 — explicit exact/all-terms/relaxed book search contract
# ---------------------------------------------------------------------------
_BOOK_SEARCH_PRECISION_VERSION = "1.0-explicit-match-mode-no-silent-relaxation"
_BSP_MATCH_MODES = {"exact_phrase", "all_terms", "relaxed"}
_BSP_EXCERPT_CHARS = 1000


def _bsp_clean_query(query: object) -> str:
    clean = " ".join(str(query or "").strip().split())
    if len(clean) >= 2 and clean[0] == clean[-1] and clean[0] in {'"', "'"}:
        clean = " ".join(clean[1:-1].strip().split())
    return clean


def _bsp_terms(query: object) -> list[str]:
    folded = unicodedata.normalize("NFKC", _bsp_clean_query(query)).casefold()
    terms = []
    for term in re.findall(r"[^\W_]+", folded, flags=re.UNICODE):
        if term and term not in terms:
            terms.append(term)
    return terms[:32]


def _bsp_exact_pattern(query: object):
    clean = _bsp_clean_query(query)
    pieces = [piece for piece in re.split(r"\s+", clean) if piece]
    if not pieces:
        return None
    body = r"\s+".join(re.escape(piece) for piece in pieces)
    prefix = r"(?<!\w)" if pieces[0][0].isalnum() else ""
    suffix = r"(?!\w)" if pieces[-1][-1].isalnum() else ""
    return re.compile(prefix + body + suffix, re.IGNORECASE | re.UNICODE)


def _bsp_term_match(text: str, term: str):
    return re.search(r"(?<!\w)" + re.escape(term) + r"(?!\w)", text, re.IGNORECASE | re.UNICODE)


def _bsp_match(text: object, query: object) -> dict:
    raw = str(text or "")
    terms = _bsp_terms(query)
    pattern = _bsp_exact_pattern(query)
    exact = pattern.search(raw) if pattern is not None else None
    term_hits = []
    for term in terms:
        hit = _bsp_term_match(raw, term)
        if hit is not None:
            term_hits.append((term, hit.start(), hit.end()))
    all_terms = bool(terms) and len(term_hits) == len(terms)
    if exact is not None:
        start, end = exact.start(), exact.end()
    elif term_hits:
        start = min(hit[1] for hit in term_hits)
        end = max(hit[2] for hit in term_hits)
    else:
        start = end = 0
    return {
        "exact_phrase_matched": exact is not None,
        "all_terms_matched": all_terms,
        "matched_terms": [hit[0] for hit in term_hits],
        "match_char_start_in_chunk": start if (exact is not None or term_hits) else None,
        "match_char_end_in_chunk": end if (exact is not None or term_hits) else None,
        "match_span_characters": max(0, end - start) if (exact is not None or term_hits) else None,
    }


def _bsp_excerpt(text: str, start: int | None, end: int | None, limit: int = _BSP_EXCERPT_CHARS) -> str:
    raw = str(text or "")
    cap = max(300, min(1800, int(limit or _BSP_EXCERPT_CHARS)))
    center = int(start or 0)
    left = max(0, center - cap // 3)
    right = min(len(raw), left + cap)
    left = max(0, right - cap)
    return ("…" if left else "") + raw[left:right] + ("…" if right < len(raw) else "")


def _bsp_source_rows(module, book_id: str | None = None) -> list[dict]:
    books = getattr(module, "neatbooks", None)
    if books is None or not callable(getattr(books, "connect", None)):
        raise RuntimeError("NeatBooks canonical database connection is unavailable.")
    sql = """SELECT c.chunk_id,c.book_id,b.title,b.authors_json authors,c.chapter,c.ordinal,
                    c.page_start,c.page_end,c.char_start,c.char_end,c.text_sha256,
                    COALESCE(NULLIF(c.original_text,''),c.text,'') source_text
               FROM book_chunks c JOIN books b ON b.book_id=c.book_id"""
    params = []
    if book_id:
        sql += " WHERE c.book_id=?"
        params.append(str(book_id))
    sql += " ORDER BY c.book_id,c.ordinal,c.chunk_id"
    with books.connect() as db:
        rows = [dict(row) for row in db.execute(sql, tuple(params)).fetchall()]
    return rows


def _bsp_result_row(row: dict, query: str, match: dict, mode: str) -> dict:
    source_text = str(row.get("source_text") or "")
    digest = str(row.get("text_sha256") or "") or hashlib.sha256(source_text.encode("utf-8")).hexdigest()
    output = {key: row.get(key) for key in (
        "book_id", "chunk_id", "title", "authors", "chapter", "ordinal",
        "page_start", "page_end", "char_start", "char_end",
    )}
    output.update({
        "text_sha256": digest,
        "requested_match_mode": mode,
        "exact_phrase_matched": bool(match.get("exact_phrase_matched")),
        "all_terms_matched": bool(match.get("all_terms_matched")),
        "matched_terms": list(match.get("matched_terms") or []),
        "match_char_start_in_chunk": match.get("match_char_start_in_chunk"),
        "match_char_end_in_chunk": match.get("match_char_end_in_chunk"),
        "match_span_characters": match.get("match_span_characters"),
        "excerpt": _bsp_excerpt(source_text, match.get("match_char_start_in_chunk"), match.get("match_char_end_in_chunk")),
    })
    return output


def _bsp_primary_search(module, query: str, mode: str, limit: int, book_id: str | None) -> dict:
    rows = _bsp_source_rows(module, book_id)
    matches = []
    for row in rows:
        matched = _bsp_match(row.get("source_text"), query)
        admitted = matched["exact_phrase_matched"] if mode == "exact_phrase" else matched["all_terms_matched"]
        if not admitted:
            continue
        item = _bsp_result_row(row, query, matched, mode)
        rank = (
            0 if item["exact_phrase_matched"] else 1,
            int(item.get("match_span_characters") or 10**9),
            str(item.get("book_id") or ""),
            int(item.get("ordinal") or 0),
            str(item.get("chunk_id") or ""),
        )
        matches.append((rank, item))
    matches.sort(key=lambda pair: pair[0])
    page = [item for _rank, item in matches[:limit]]
    return {
        "ok": True,
        "query": query,
        "book_id": book_id,
        "requested_match_mode": mode,
        "search_strategy": "deterministic_original_text_" + mode,
        "scope": "canonical_original_chunk_text",
        "query_terms": _bsp_terms(query),
        "total_matches": len(matches),
        "count": len(page),
        "results": page,
        "rank_mechanics": "exact phrase first, then narrowest deterministic term span, then book/ordinal/chunk",
    }


def _bsp_chunk_lookup(module, chunk_id: str) -> dict | None:
    books = getattr(module, "neatbooks", None)
    if books is None or not callable(getattr(books, "connect", None)):
        return None
    sql = """SELECT c.chunk_id,c.book_id,b.title,b.authors_json authors,c.chapter,c.ordinal,
                    c.page_start,c.page_end,c.char_start,c.char_end,c.text_sha256,
                    COALESCE(NULLIF(c.original_text,''),c.text,'') source_text
               FROM book_chunks c JOIN books b ON b.book_id=c.book_id WHERE c.chunk_id=?"""
    with books.connect() as db:
        row = db.execute(sql, (str(chunk_id),)).fetchone()
    return dict(row) if row else None


def _bsp_relaxed_search(module, query: str, limit: int, book_id: str | None) -> dict:
    books = getattr(module, "neatbooks", None)
    if books is None or not callable(getattr(books, "search_books", None)):
        return {"ok": False, "error": "NeatBooks relaxed search is unavailable.", "results": [], "count": 0}
    raw = books.search_books(query=query, limit=limit, book_id=book_id)
    payload = dict(raw) if isinstance(raw, dict) else {"results": list(raw or [])}
    output = []
    for legacy in list(payload.get("results") or [])[:limit]:
        if not isinstance(legacy, dict):
            continue
        source = _bsp_chunk_lookup(module, str(legacy.get("chunk_id") or ""))
        if source is None:
            item = dict(legacy)
            item.update({"exact_phrase_matched": None, "all_terms_matched": None, "match_verification": "source_chunk_unavailable"})
        else:
            match = _bsp_match(source.get("source_text"), query)
            item = _bsp_result_row(source, query, match, "relaxed")
            item["legacy_rank"] = legacy.get("rank")
            item["underlying_excerpt"] = str(legacy.get("excerpt") or "")[:800]
            item["match_verification"] = "checked_against_canonical_original_chunk_text"
        output.append(item)
    return {
        "ok": bool(payload.get("ok", True)),
        "query": query,
        "book_id": book_id,
        "requested_match_mode": "relaxed",
        "search_strategy": "relaxed_explicit",
        "underlying_search_strategy": payload.get("search_strategy") or "legacy_fts",
        "relaxed_query": payload.get("relaxed_query"),
        "count": len(output),
        "results": output,
        "scope": "legacy_ranked_search_with_per-result_original-text-match_flags",
    }


def _bsp_search(module, *, query: str, limit: int = 6, book_id: str | None = None,
                match_mode: str = "relaxed", allow_fallback: bool = False,
                match_mode_explicit: bool = True) -> dict:
    clean = _bsp_clean_query(query)
    if not clean:
        return {"ok": False, "error": "query is required.", "read_only": True, "model_calls": 0, "web_calls": 0}
    mode = str(match_mode or "relaxed").strip().casefold()
    if mode not in _BSP_MATCH_MODES:
        return {"ok": False, "error": "match_mode must be exact_phrase, all_terms, or relaxed.", "read_only": True, "model_calls": 0, "web_calls": 0}
    bounded_limit = max(1, min(12, int(limit or 6)))
    bid = str(book_id or "").strip() or None
    if mode == "relaxed":
        result = _bsp_relaxed_search(module, clean, bounded_limit, bid)
        result.update({
            "allow_fallback": bool(allow_fallback),
            "match_mode_explicit": bool(match_mode_explicit),
            "fallback_used": False,
            "silent_relaxation": False,
            "contract_note": (
                "Relaxed matching was explicitly requested; no result is represented as an exact phrase unless exact_phrase_matched is true."
                if match_mode_explicit else
                "Relaxed matching is the visible legacy compatibility default because match_mode was omitted; set exact_phrase or all_terms for a strict primary result."
            ),
            "read_only": True,
            "model_calls": 0,
            "web_calls": 0,
        })
        return result
    result = _bsp_primary_search(module, clean, mode, bounded_limit, bid)
    result.update({
        "allow_fallback": bool(allow_fallback),
        "match_mode_explicit": bool(match_mode_explicit),
        "fallback_used": False,
        "fallback_search": None,
        "silent_relaxation": False,
        "contract_note": "Primary results contain only the requested deterministic match mode. Any allowed relaxed fallback is returned separately and never merged into results.",
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    })
    if not result.get("results") and bool(allow_fallback):
        fallback = _bsp_relaxed_search(module, clean, bounded_limit, bid)
        result["fallback_used"] = bool(fallback.get("results"))
        result["fallback_search"] = fallback
    return result


def book_search_precision_self_test(module=None) -> dict:
    if module is None:
        module = _load_memory()
    checks = {}
    with tempfile.TemporaryDirectory(prefix="neat-bsp-") as folder:
        db_path = Path(folder) / "books.db"
        with sqlite3.connect(db_path) as db:
            db.executescript("""
                CREATE TABLE books(book_id TEXT PRIMARY KEY,title TEXT,authors_json TEXT);
                CREATE TABLE book_chunks(
                    chunk_id TEXT PRIMARY KEY,book_id TEXT,chapter TEXT,ordinal INTEGER,
                    page_start INTEGER,page_end INTEGER,char_start INTEGER,char_end INTEGER,
                    text_sha256 TEXT,original_text TEXT,text TEXT
                );
            """)
            texts = [
                ("C1", "Conditional probability is defined here. Prior probability is a separate phrase."),
                ("C2", "Probability appears here, but conditional appears much later in this chunk."),
                ("C3", "Bayes theorem is named in this exact source passage."),
            ]
            db.execute("INSERT INTO books VALUES(?,?,?)", ("BK-T", "Test Book", '["Tester"]'))
            cursor = 0
            for ordinal, (chunk_id, text_value) in enumerate(texts, 1):
                digest = hashlib.sha256(text_value.encode("utf-8")).hexdigest()
                db.execute("INSERT INTO book_chunks VALUES(?,?,?,?,?,?,?,?,?,?,?)", (
                    chunk_id, "BK-T", "chapter", ordinal, None, None, cursor, cursor + len(text_value),
                    digest, text_value, text_value,
                ))
                cursor += len(text_value)

        class FakeBooks:
            @staticmethod
            def connect():
                db = sqlite3.connect(db_path)
                db.row_factory = sqlite3.Row
                return db

            @staticmethod
            def search_books(query, limit=8, book_id=None):
                return {"query": query, "search_strategy": "relaxed_or", "relaxed_query": '"conditional" OR "probability"', "results": [
                    {"chunk_id": "C2", "book_id": "BK-T", "ordinal": 2, "excerpt": "relaxed candidate", "rank": -1.0}
                ]}

        fake = type("BSPFake", (), {"neatbooks": FakeBooks()})()
        exact = _bsp_search(fake, query="conditional probability", book_id="BK-T", limit=5, match_mode="exact_phrase", allow_fallback=False)
        all_terms = _bsp_search(fake, query="conditional probability", book_id="BK-T", limit=5, match_mode="all_terms", allow_fallback=False)
        zero = _bsp_search(fake, query="posterior probability", book_id="BK-T", limit=5, match_mode="exact_phrase", allow_fallback=False)
        separated = _bsp_search(fake, query="posterior probability", book_id="BK-T", limit=5, match_mode="exact_phrase", allow_fallback=True)
        relaxed = _bsp_search(fake, query="conditional probability", book_id="BK-T", limit=5, match_mode="relaxed", allow_fallback=False)
        legacy_default = _bsp_search(fake, query="conditional probability", book_id="BK-T", limit=5, match_mode="relaxed", allow_fallback=False, match_mode_explicit=False)
        checks.update({
            "exact_phrase_returns_only_contiguous_original_match": exact.get("total_matches") == 1 and [x.get("chunk_id") for x in exact.get("results", [])] == ["C1"] and exact["results"][0].get("exact_phrase_matched") is True,
            "all_terms_is_distinct_and_deterministic": all_terms.get("total_matches") == 2 and all_terms.get("results", [])[0].get("chunk_id") == "C1",
            "zero_exact_is_reported_without_fallback": zero.get("total_matches") == 0 and zero.get("results") == [] and zero.get("fallback_search") is None,
            "allowed_fallback_is_separate_not_merged": separated.get("results") == [] and separated.get("fallback_used") is True and (separated.get("fallback_search") or {}).get("results", [{}])[0].get("chunk_id") == "C2",
            "relaxed_mode_is_explicit_and_flagged": relaxed.get("search_strategy") == "relaxed_explicit" and relaxed.get("silent_relaxation") is False and relaxed.get("results", [{}])[0].get("exact_phrase_matched") is False,
            "omitted_mode_is_visible_legacy_default_not_silent": legacy_default.get("match_mode_explicit") is False and "legacy compatibility default" in str(legacy_default.get("contract_note") or "") and legacy_default.get("silent_relaxation") is False,
            "results_expose_exact_chunk_coordinates_and_hash": all(key in exact.get("results", [{}])[0] for key in ("book_id", "chunk_id", "ordinal", "char_start", "char_end", "text_sha256", "match_char_start_in_chunk")),
        })
    online_schema = next((item for item in globals().get("_ONLINE_BOOK_RESPONSE_TOOLS", []) if isinstance(item, dict) and item.get("name") == "search_books"), {})
    online_properties = ((online_schema.get("parameters") or {}).get("properties") or {})
    local_schema = next((item for item in getattr(module, "TOOL_SCHEMAS", []) if str((item.get("function") or {}).get("name") or "") == "search_books"), {})
    local_properties = ((((local_schema.get("function") or {}).get("parameters") or {}).get("properties")) or {})
    checks.update({
        "online_schema_exposes_explicit_mode_and_fallback": {"match_mode", "allow_fallback"}.issubset(online_properties),
        "local_schema_exposes_explicit_mode_and_fallback": {"match_mode", "allow_fallback"}.issubset(local_properties),
        "installer_did_not_modify_speech_surfaces": all(bool(value) for value in (getattr(module, "_BOOK_SEARCH_PRECISION_SPEECH_INVARIANCE", {}) or {}).values()),
        "learn_resilience_layer_remains_installed": bool(getattr(module, "_BOOK_LEARNING_RETRIEVAL_INSTALLED", False)),
    })
    return {"ok": all(bool(value) for value in checks.values()), "checks": checks, "version": _BOOK_SEARCH_PRECISION_VERSION, "model_calls": 0, "web_calls": 0, "live_database_modified": False}


def _install_book_search_precision(module) -> None:
    if getattr(module, "_BOOK_SEARCH_PRECISION_INSTALLED", False):
        return
    system_before = hashlib.sha256(str(getattr(module, "SYSTEM_PROMPT", "")).encode("utf-8")).hexdigest()
    chat_before = id(getattr(module, "run_online_chat_turn", None))
    context_before = id(getattr(module, "build_runtime_context", None))
    schema = {
        "type": "function",
        "name": "search_books",
        "description": "Search canonical original book chunks with an explicit match contract. Use exact_phrase for a literal contiguous phrase, all_terms when every term must occur in one chunk, or relaxed only when broader retrieval is deliberately wanted. No exact/all-terms request is silently relaxed; allow_fallback returns relaxed candidates separately and never merges them into primary results. Read-only.",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {"type": "string"},
                "limit": {"type": "integer", "minimum": 1, "maximum": 12},
                "book_id": {"type": ["string", "null"]},
                "match_mode": {"type": "string", "enum": ["exact_phrase", "all_terms", "relaxed"]},
                "allow_fallback": {"type": "boolean"},
            },
            "required": ["query"],
            "additionalProperties": False,
        },
        "strict": False,
    }

    def replace_response_schema(array):
        if not isinstance(array, list):
            return
        for index, item in enumerate(array):
            if isinstance(item, dict) and str(item.get("name") or "") == "search_books":
                array[index] = schema

    for array_name in ("_ONLINE_BOOK_RESPONSE_TOOLS", "_ONLINE_EVIDENCE_RESPONSE_TOOLS"):
        replace_response_schema(globals().get(array_name))

    if isinstance(getattr(module, "TOOL_SCHEMAS", None), list):
        local_schema = {"type": "function", "function": {key: value for key, value in schema.items() if key not in {"type", "strict"}}}
        for index, item in enumerate(module.TOOL_SCHEMAS):
            if str((item.get("function") or {}).get("name") or "") == "search_books":
                module.TOOL_SCHEMAS[index] = local_schema

    old_online = globals().get("_ora_execute_book_tool")
    if callable(old_online):
        def execute_precise_book_search(mod, name, arguments):
            if str(name or "") == "search_books":
                args = dict(arguments or {}) if isinstance(arguments, dict) else {}
                return _ora_clean_result(mod, _bsp_search(
                    mod,
                    query=str(args.get("query") or ""),
                    limit=int(args.get("limit") or 6),
                    book_id=str(args.get("book_id") or "").strip() or None,
                    match_mode=str(args.get("match_mode") or "relaxed"),
                    allow_fallback=bool(args.get("allow_fallback", False)),
                    match_mode_explicit="match_mode" in args,
                ))
            return old_online(mod, name, arguments)
        globals()["_ora_execute_book_tool"] = execute_precise_book_search

    old_local = getattr(module, "execute_tool", None)
    if callable(old_local):
        def execute_local_precise_search(name, arguments, *args, **kwargs):
            if str(name or "") == "search_books":
                tool_args = dict(arguments or {}) if isinstance(arguments, dict) else {}
                return _bsp_search(
                    module,
                    query=str(tool_args.get("query") or ""),
                    limit=int(tool_args.get("limit") or 6),
                    book_id=str(tool_args.get("book_id") or "").strip() or None,
                    match_mode=str(tool_args.get("match_mode") or "relaxed"),
                    allow_fallback=bool(tool_args.get("allow_fallback", False)),
                    match_mode_explicit="match_mode" in tool_args,
                )
            return old_local(name, arguments, *args, **kwargs)
        module.execute_tool = execute_local_precise_search

    module.search_books_precise = lambda query, **kwargs: _bsp_search(module, query=query, match_mode_explicit="match_mode" in kwargs, **kwargs)
    module.book_search_precision_self_test = lambda: book_search_precision_self_test(module)
    module.BOOK_SEARCH_PRECISION_VERSION = _BOOK_SEARCH_PRECISION_VERSION
    module._BOOK_SEARCH_PRECISION_SPEECH_INVARIANCE = {
        "system_prompt_sha256_unchanged": system_before == hashlib.sha256(str(getattr(module, "SYSTEM_PROMPT", "")).encode("utf-8")).hexdigest(),
        "run_online_chat_turn_callable_unchanged": chat_before == id(getattr(module, "run_online_chat_turn", None)),
        "runtime_context_builder_unchanged": context_before == id(getattr(module, "build_runtime_context", None)),
    }
    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs, dict):
        specs["book-search-precision"] = {"label": "Explicit exact/all-terms/relaxed original-book search with no silent fallback", "groups": ("quick", "critical", "all"), "runner": "memory.book_search_precision_self_test"}
    suites = globals().get("_SELF_TEST_NAMED_SUITES")
    if isinstance(suites, dict):
        checkpoint = list(suites.get("checkpoint") or ())
        if "book-search-precision" not in checkpoint:
            checkpoint.append("book-search-precision")
        suites["checkpoint"] = tuple(checkpoint)
    module._BOOK_SEARCH_PRECISION_INSTALLED = True


