def _ela_int(value: object, default: int = 0) -> int:
    try:
        return int(value or 0)
    except Exception:
        return int(default)


def _ela_float(value: object, default: float = 0.0) -> float:
    try:
        return float(value or 0.0)
    except Exception:
        return float(default)


def _ela_semantic_states() -> dict[str, dict]:
    """Read active completed book semantic-map state without model/network calls."""
    states: dict[str, dict] = {}
    try:
        with _sk_connect() as db:
            rows=db.execute("""SELECT s.source_key AS book_id,v.version_id,v.version_number,v.status,v.active,v.archive,v.completed_at,
                COUNT(u.unit_id) AS semantic_units
                FROM knowledge_sources s
                JOIN knowledge_versions v ON v.version_id=s.current_version_id
                LEFT JOIN knowledge_semantic_units u ON u.version_id=v.version_id
                WHERE s.source_kind='book' AND v.active=1 AND v.archive=0 AND v.status='completed'
                GROUP BY s.source_key,v.version_id,v.version_number,v.status,v.active,v.archive,v.completed_at""").fetchall()
        for row in rows:
            states[str(row["book_id"])]=dict(row)
    except Exception:
        return {}
    return states


def _ela_book_state(row: dict) -> dict:
    item=dict(row or {})
    total=max(0,_ela_int(item.get("chunks") if item.get("chunks") is not None else item.get("total_chunks")))
    done=max(0,_ela_int(item.get("digested_chunks")))
    if total and done>total: done=total
    percent=_ela_float(item.get("completion_percent"), (done/total*100.0 if total else 0.0))
    status=str(item.get("status") or "").strip().casefold()
    access=str(item.get("access_status") or "").strip().casefold()
    local_file=str(item.get("local_file") or "").strip()
    error=str(item.get("last_error") or item.get("error") or "").strip()
    if error and status=="error": display="ERROR"
    elif status in _ELA_COMPLETE_STATUS or access in _ELA_COMPLETE_ACCESS or (total>0 and done>=total and percent>=99.95): display="COMPLETE"
    elif status in {"digesting","partially_digested"} or (total>0 and 0<done<total): display="DIGESTING"
    elif access=="metadata_only" and total==0 and not local_file: display="METADATA ONLY"
    elif total>0: display="READY"
    elif local_file: display="IMPORTED"
    else: display="METADATA ONLY"
    readable=bool(total>0)
    return {
        **item,
        "display_status":display,
        "indexed":readable,
        "readable":readable,
        "local_copy":bool(local_file),
        "total_chunks":total,
        "digested_chunks":done,
        "remaining_chunks":max(0,total-done),
        "completion_percent":round(percent,1),
        "filename":Path(local_file).name if local_file else "",
        "error":error,
    }


def _ela_library_catalog_snapshot(module, *, mode: str="all", auto_import: bool=False, include_queue: bool=True) -> dict:
    """Unified SQL catalog view. `include_queue` is ignored for compatibility.

    All physical sources live permanently in books/. READY/DIGESTING/COMPLETE are
    logical states; there is no pending or archive filesystem/queue.
    """
    books=getattr(module,"neatbooks",None)
    if books is None:
        return {"ok":False,"error":"NeatBooks is unavailable","mode":mode,"catalog":[],"counts":{}}
    scan_errors=[]
    if auto_import:
        scanner=getattr(books,"list_ready_books",None) or getattr(books,"scan_pending_books",None)
        if callable(scanner):
            try:
                scanned=list(scanner(auto_import=True) or [])
                scan_errors=[x for x in scanned if isinstance(x,dict) and x.get("error") and not x.get("book_id")]
            except Exception:
                scan_errors=[]
    rows=[]
    try: rows=list(books.list_books(limit=500) or [])
    except Exception: rows=[]
    semantic_states=_ela_semantic_states()
    catalog=[]
    for raw in rows:
        if not isinstance(raw,dict): continue
        row=_ela_book_state(raw)
        bid=str(row.get("book_id") or "")
        semantic=semantic_states.get(bid)
        if semantic:
            row["semantic_map"]={
                "version_id":semantic.get("version_id"),"version_number":semantic.get("version_number"),
                "status":semantic.get("status"),"semantic_units":_ela_int(semantic.get("semantic_units")),
                "completed_at":semantic.get("completed_at"),
            }
            if _ela_int(semantic.get("semantic_units"))>0 and row.get("display_status") not in {"DIGESTING","ERROR"}:
                row["display_status"]="COMPLETE"
        catalog.append(row)
    for failed in scan_errors:
        row=_ela_book_state({
            "book_id":None,"title":failed.get("title") or Path(str(failed.get("filename") or "Untitled")).stem,
            "local_file":failed.get("path") or "","status":"error","last_error":failed.get("error") or "",
            "chunks":failed.get("chunks") or 0,"access_status":"local_user_copy",
        })
        catalog.append(row)
    order={"DIGESTING":0,"READY":1,"IMPORTED":2,"ERROR":3,"COMPLETE":4,"METADATA ONLY":5}
    catalog.sort(key=lambda r:(order.get(str(r.get("display_status")),9),str(r.get("title") or "").casefold(),str(r.get("book_id") or "")))
    selected=catalog
    m=str(mode or "all").casefold()
    if m in {"ready","pending","queue"}: selected=[r for r in catalog if r.get("display_status") in {"READY","DIGESTING","IMPORTED","ERROR"}]
    elif m in {"complete","completed","archive","archived"}: selected=[r for r in catalog if r.get("display_status")=="COMPLETE"]
    counts={key:sum(1 for r in catalog if r.get("display_status")==key) for key in order}
    counts.update({"all":len(catalog),"readable":sum(1 for r in catalog if r.get("readable")),"local_copies":sum(1 for r in catalog if r.get("local_copy"))})
    return {
        "ok":True,"version":_EPISTEMIC_LIBRARY_AWARENESS_VERSION,"mode":m,"catalog":selected,"all_catalog":catalog,"counts":counts,
        "books_directory":str(getattr(books,"BOOK_DIR","")),
        "storage_model":"all local book sources remain in books/; READY/DIGESTING/COMPLETE are SQL/catalog states only",
        "semantics":{"READY":"fixed evidence blocks are indexed/readable; no active completed semantic map is present","DIGESTING":"evidence blocks remain fixed while Assistant/LLM chooses a fluid number of semantic units and boundaries","COMPLETE":"an active completed book-level semantic map or completed legacy digest is known; the source still remains in books/","METADATA ONLY":"catalog record exists but no local indexed text is readable","ERROR":"import or digest error needs attention"},
    }

def _ela_library_line(item: dict) -> str:
    # /library is a catalog view: present the human book title, not the source filename.
    title=str(item.get("title") or "Untitled")
    bid=str(item.get("book_id") or "NO-BK-ID")
    status=str(item.get("display_status") or "UNKNOWN")
    semantic=item.get("semantic_map") if isinstance(item.get("semantic_map"),dict) else {}
    semantic_units=_ela_int(semantic.get("semantic_units"))
    total=_ela_int(item.get("total_chunks")); done=_ela_int(item.get("digested_chunks")); pct=_ela_float(item.get("completion_percent"))
    if semantic_units>0:
        digest=f"semantic-units={semantic_units} (fluid, LLM-chosen) | evidence-blocks={total} (fixed provenance)"
    else:
        digest=(f"evidence-blocks={total} (fixed provenance) | legacy-digest-progress={done}/{total} ({pct:.1f}%)" if total else "evidence-blocks=n/a")
    order_state=str(item.get("epub_reading_order") or "")
    wrapper_state=str(item.get("gutenberg_wrapper_cleanup") or "")
    order_note=(" | EPUB-order=legacy (re-import creates corrected BK-ID)" if order_state=="legacy" else " | EPUB-order=fallback" if order_state=="fallback" else "")
    wrapper_note=(" | Gutenberg-body=clean" if wrapper_state=="clean" else " | Gutenberg-body=legacy/untrimmed" if wrapper_state=="legacy" else "")
    readable="yes" if item.get("readable") else "no"
    suffix=f" | ERROR: {str(item.get('error'))[:180]}" if item.get("error") else ""
    return f"  {title} | {bid} | {status} | readable={readable} | {digest}{order_note}{wrapper_note}{suffix}"

def _ela_print_library(module, mode: str="all") -> dict:
    snap=_ela_library_catalog_snapshot(module,mode=mode,auto_import=True,include_queue=True)
    heading={"ready":"ready/digesting","pending":"ready/digesting","complete":"completed","archive":"completed"}.get(str(mode).casefold(),"all known books")
    print(f"\nUnified library catalog — {heading}")
    print(f"  DB books={snap.get('counts',{}).get('all',0)} | readable={snap.get('counts',{}).get('readable',0)} | digesting={snap.get('counts',{}).get('DIGESTING',0)} | complete={snap.get('counts',{}).get('COMPLETE',0)} | metadata-only={snap.get('counts',{}).get('METADATA ONLY',0)}")
    rows=snap.get("catalog") or []
    if not rows: print("  (none)")
    for item in rows: print(_ela_library_line(item))
    print("BK-ID/title are stable book references. Every local source remains in books/; READY/DIGESTING/COMPLETE are catalog states, not folders or queues. METADATA ONLY records need a local copy before reading.")
    return snap


def _ela_recent_reflection_questions(module, limit: int=4) -> list[str]:
    try:
        state=_reflection_journal_load(module,limit=4)
    except Exception:
        return []
    out=[]
    for entry in reversed(list(state.get("entries") or [])):
        for q in entry.get("open_questions") or []:
            clean=" ".join(str(q or "").split()).strip()
            if clean and clean.casefold() not in {x.casefold() for x in out}: out.append(clean)
            if len(out)>=limit: return out
    return out


def _ela_epistemic_map(module, query: str, *, domains: list[str], context_priority: list[str], personal_rows: list[dict], book_rows: list[dict], shared_book_trace: dict) -> tuple[str,dict]:
    shared=dict(shared_book_trace or {})
    item_ids=[str(x) for x in (shared.get("item_ids") or []) if str(x)]
    passage_ids=[str(x) for x in (shared.get("passage_ids") or []) if str(x)]
    windows=list(shared.get("source_excerpt_windows") or [])
    citation_handles=[str(x) for x in (shared.get("visible_citation_handles") or []) if str(x)]
    open_questions=[]; continuity_status="unavailable"
    try:
        continuity,continuity_status=_load_active_continuity(module)
        open_questions=[" ".join(str(x or "").split()).strip() for x in (continuity.get("open_questions") or []) if str(x or "").strip()][:6]
    except Exception as exc:
        continuity_status=f"unavailable:{type(exc).__name__}"
    reflection_questions=_ela_recent_reflection_questions(module,4)
    library=_ela_library_catalog_snapshot(module,mode="all",auto_import=False,include_queue=False)
    all_books=list(library.get("all_catalog") or [])
    qterms={x for x in re.findall(r"[a-z0-9']{3,}",str(query or "").casefold())}
    def title_score(row):
        title=str(row.get("title") or "").casefold(); overlap=sum(1 for t in qterms if t in title)
        active=2 if row.get("display_status")=="DIGESTING" else 1 if row.get("readable") else 0
        return (-overlap,-active,str(row.get("title") or "").casefold())
    useful_books=sorted(all_books,key=title_score)[:8]
    book_labels=[]
    for r in useful_books:
        semantic=r.get("semantic_map") if isinstance(r.get("semantic_map"),dict) else {}
        units=_ela_int(semantic.get("semantic_units"))
        progress=(f"semantic map complete: {units} units" if units>0 else f"source chunks digested {r.get('digested_chunks')}/{r.get('total_chunks')}")
        order_note=("; EPUB order legacy" if str(r.get("epub_reading_order") or "")=="legacy" else "; EPUB order fallback" if str(r.get("epub_reading_order") or "")=="fallback" else "")
        book_labels.append(f"{r.get('title')} [{r.get('display_status')}; {progress}{order_note}]")
    personal_questions=sum(1 for r in personal_rows if str(r.get("kind") or "").casefold()=="question")
    book_questions=sum(1 for r in book_rows if str(r.get("kind") or "").casefold()=="question")
    lines=[
        f"Assistant-selected context priority: {' > '.join(context_priority) if context_priority else '[none]'}",
        f"Open retrieval domains: {', '.join(domains) if domains else '[none]'}",
        f"Selected personal memories: {len(personal_rows)} ({personal_questions} question/unresolved-kind)",
        f"Selected book-linked memories: {len(book_rows)} ({book_questions} question/unresolved-kind)",
        f"Selected shared book/research knowledge: {len(item_ids)} KI items, {len(passage_ids)} exact passages, {len(windows)} retained source windows, {len(citation_handles)} visible citation handles",
        f"Local library: {library.get('counts',{}).get('all',0)} known, {library.get('counts',{}).get('readable',0)} readable/indexed, {library.get('counts',{}).get('DIGESTING',0)} digesting, {library.get('counts',{}).get('COMPLETE',0)} complete, {library.get('counts',{}).get('METADATA ONLY',0)} metadata-only",
    ]
    if book_labels: lines.append("Available/relevant local books: "+"; ".join(book_labels))
    lines.append(f"Active-continuity read status: {continuity_status}")
    if open_questions: lines.append("Active unresolved questions: "+" | ".join(open_questions))
    if reflection_questions: lines.append("Recent reflection questions (journal map only): "+" | ".join(reflection_questions))
    lines.extend([
        "Epistemic rule: question memories, hypotheses, reflection questions, and research uncertainties are unresolved navigation/state unless independently supported; they are not established facts by being stored or retrieved.",
        "Metadata rule: model provider identifies who reasons; evidence source identifies what material supports the answer. These are independent dimensions.",
        "Authority rule: this map describes what is available/selected. It does not choose beliefs, conclusions, retrieval depth, or whether more research is worthwhile for Assistant.",
    ])
    trace={"ok":True,"version":_EPISTEMIC_LIBRARY_AWARENESS_VERSION,"domains":list(domains),"context_priority":list(context_priority),"personal_memory_count":len(personal_rows),"book_memory_count":len(book_rows),"shared_item_ids":item_ids,"shared_passage_ids":passage_ids,"source_window_count":len(windows),"citation_handles":citation_handles,"open_questions":open_questions,"reflection_questions":reflection_questions,"library_counts":dict(library.get("counts") or {}),"book_labels":book_labels}
    return "\n".join(lines),trace


def _ela_research_chat_summary(module, report: dict, report_path: Path, provider: str) -> str:
    compact=module.compact_research_report(report,findings_limit=5)
    lines=[
        "[Research completed — verified by NeatMemory]",
        f"Run ID: {compact.get('run_id') or report_path.stem}",
        f"Topic: {compact.get('topic') or '[model-selected topic]'}",
        f"Model provider: {provider or compact.get('provider') or '[unknown]'}",
        f"Evidence source mode: {report.get('evidence_source_mode') or report.get('source_mode') or '[unknown]'}",
        f"Passes: {compact.get('completed_iterations')}/{compact.get('requested_iterations')} maximum",
    ]
    findings=compact.get("findings") or []
    if findings:
        lines.append("Main findings:"); lines.extend(f"- {finding}" for finding in findings)
    else: lines.append("Main findings: none recorded in the verified report.")
    lines.extend([
        f"Evidence read: {compact.get('web_sources')} web pages, {compact.get('book_passages')} book passages",
        f"Memory proposals: {compact.get('memory_proposals')}",
        f"Knowledge created: {int((report.get('memory_persistence') or {}).get('knowledge_created') or (report.get('memory_persistence') or {}).get('inserted') or 0)}",
        f"Canonical memories created: {len((report.get('memory_persistence') or {}).get('memory_ids') or [])}",
        f"Knowledge database modified: {'yes' if bool((report.get('memory_persistence') or {}).get('knowledge_database_modified')) else 'no'}",
        f"Canonical memory database modified: {'yes' if bool((report.get('memory_persistence') or {}).get('database_modified')) else 'no'}",
        f"Full report: {report_path}",
        "Provider and evidence source are separate metadata dimensions. The full report is available through the research-report tools when more detail is needed.",
    ])
    return "\n".join(lines)


def epistemic_library_awareness_self_test(module=None) -> dict:
    checks={}
    rows=[
        {"book_id":"BK-S","title":"William Shakespeare Collection","authors":[],"access_status":"local_user_copy","local_file":"shakespeare.epub","chunks":294,"status":"partially_digested","digested_chunks":55,"remaining_chunks":239,"completion_percent":18.7},
        {"book_id":"BK-C","title":"Completed Book","authors":[],"access_status":"digested_known","local_file":"done.epub","chunks":20,"status":"known_completed","digested_chunks":0,"remaining_chunks":20,"completion_percent":0.0,"epub_reading_order":"legacy"},
        {"book_id":"BK-M","title":"Metadata Book","authors":[],"access_status":"metadata_only","local_file":"","chunks":0,"status":"imported","digested_chunks":0,"remaining_chunks":0,"completion_percent":0.0},
    ]
    class FakeBooks:
        BOOK_DIR=Path("books"); PENDING_DIR=BOOK_DIR; ARCHIVE_DIR=BOOK_DIR
        @staticmethod
        def list_books(limit=500): return list(rows)
        @staticmethod
        def scan_pending_books(auto_import=False): return [{"number":1,"book_id":"BK-S","title":"William Shakespeare Collection","filename":"shakespeare.epub","path":"shakespeare.epub","chunks":294,"error":None}]
    class FakeModule: neatbooks=FakeBooks()
    original_semantic_states=globals().get("_ela_semantic_states")
    globals()["_ela_semantic_states"]=lambda:{"BK-C":{"version_id":"KDV-TEST","version_number":1,"status":"completed","semantic_units":22,"completed_at":"2026-08-13T00:00:00Z"}}
    try:
        snap=_ela_library_catalog_snapshot(FakeModule(),mode="all",auto_import=False,include_queue=True)
    finally:
        globals()["_ela_semantic_states"]=original_semantic_states
    states={r.get("book_id"):r.get("display_status") for r in snap.get("all_catalog") or []}
    checks["unified_catalog_contains_all_sql_books"]=snap.get("counts",{}).get("all")==3
    checks["digesting_status_visible"]=states.get("BK-S")=="DIGESTING"
    checks["completed_status_visible"]=states.get("BK-C")=="COMPLETE"
    checks["metadata_only_not_readable"]=states.get("BK-M")=="METADATA ONLY" and not next(r for r in snap["all_catalog"] if r.get("book_id")=="BK-M").get("readable")
    checks["no_pending_queue_semantics"]="book_pending" not in snap and "book_archive" not in snap and all("queue_number" not in r for r in snap["all_catalog"])
    shakespeare=next(r for r in snap["all_catalog"] if r.get("book_id")=="BK-S")
    rendered=_ela_library_line(shakespeare)
    checks["library_display_uses_title_not_filename"]="William Shakespeare Collection" in rendered and "shakespeare.epub" not in rendered
    completed=next(r for r in snap["all_catalog"] if r.get("book_id")=="BK-C")
    completed_line=_ela_library_line(completed)
    checks["semantic_map_completion_outranks_legacy_chunk_counter"]="semantic-units=22 (fluid, LLM-chosen)" in completed_line and "legacy-digest-progress=0/20" not in completed_line
    checks["fixed_evidence_vs_fluid_semantics_explicit"]="evidence-blocks=20 (fixed provenance)" in completed_line and "semantic-units=22 (fluid, LLM-chosen)" in completed_line
    checks["legacy_epub_order_is_visible_not_silently_rewritten"]="EPUB-order=legacy" in completed_line
    map_text,map_trace=_ela_epistemic_map(FakeModule(),"Shakespeare",domains=["books","personal"],context_priority=["recent","books","personal","system"],personal_rows=[{"id":"NB-X","kind":"question"}],book_rows=[],shared_book_trace={"item_ids":["KI-1"],"passage_ids":["KP-1"],"source_excerpt_windows":[{"handle":"K1"}],"visible_citation_handles":["K1"]})
    checks["epistemic_map_exposes_library_and_selected_evidence"]="Local library: 3 known" in map_text and "1 KI items" in map_text
    checks["epistemic_map_labels_uncertainty"]="unresolved navigation/state" in map_text
    checks["provider_source_distinction_explicit"]="model provider identifies who reasons" in map_text.casefold()
    checks["map_is_navigation_not_authority"]="does not choose beliefs" in map_text
    return {"ok":all(checks.values()),"checks":checks,"version":_EPISTEMIC_LIBRARY_AWARENESS_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False,"trace":map_trace}


def _install_epistemic_library_awareness(module) -> None:
    if getattr(module,"_EPISTEMIC_LIBRARY_AWARENESS_INSTALLED",False): return
    module.EPISTEMIC_LIBRARY_AWARENESS_VERSION=_EPISTEMIC_LIBRARY_AWARENESS_VERSION
    module.get_library_catalog=lambda mode="all":_ela_library_catalog_snapshot(module,mode=mode,auto_import=False,include_queue=True)
    module.get_last_epistemic_map=lambda:((module.get_last_retrieval_trace().get("trace") or {}).get("epistemic_map") if callable(getattr(module,"get_last_retrieval_trace",None)) else None)
    module.epistemic_library_awareness_self_test=lambda:epistemic_library_awareness_self_test(module)
    module.build_research_chat_summary=lambda report,report_path,provider:_ela_research_chat_summary(module,report,Path(report_path),provider)
    old_main=module.main
    def main_with_epistemic_library_awareness():
        previous=builtins.input
        def intercepted(prompt=""):
            while True:
                raw=previous(prompt); clean=" ".join(str(raw or "").strip().split()); low=clean.casefold()
                listing={"/library":"all","/library all":"all","/library list":"all","/book":"all","/book all":"all","/book list":"all","/library ready":"ready","/book ready":"ready","/library complete":"complete","/book complete":"complete","/library pending":"ready","/book pending":"ready","/library archive":"complete","/book archive":"complete","/digest library":"all","/digest library all":"all","/digest library ready":"ready","/digest library complete":"complete","/digest library pending":"ready","/digest library archive":"complete"}
                if low in listing:
                    try:_ela_print_library(module,listing[low])
                    except Exception as exc: print(f"Library error: {type(exc).__name__}: {exc}")
                    continue
                if low in {"/library status","/book status"}:
                    print(json.dumps(_ela_library_catalog_snapshot(module,mode="all",auto_import=False,include_queue=True),ensure_ascii=False,indent=2)); continue
                if low in {"/epistemic","/epistemic last","/epistemic status"}:
                    trace=module.get_last_epistemic_map()
                    print(json.dumps({"ok":bool(trace),"authority":"navigation/status only; not belief authority","last_epistemic_map":trace or {}},ensure_ascii=False,indent=2)); continue
                return raw
        builtins.input=intercepted
        try:return old_main()
        finally:builtins.input=previous
    module.main=main_with_epistemic_library_awareness
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["epistemic-library-awareness"]={"label":"Unified all-book catalog plus read-only epistemic map and provider/source clarity","groups":("quick","critical","all"),"runner":"memory.epistemic_library_awareness_self_test"}
    module._EPISTEMIC_LIBRARY_AWARENESS_INSTALLED=True


# >>> NEAT-SUBSYSTEM:research-synthesis rev=3
# NeatMemory 7.4.48.3 — Evidence-grounded research final synthesis + Python-expanded finding provenance
# ---------------------------------------------------------------------------
_RESEARCH_FINAL_SYNTHESIS_VERSION = "1.2-adaptive-web-semantic-provenance"
_RFS_MAX_FINDINGS = 96
_RFS_MAX_MAIN_FINDINGS = 12
_RFS_MAX_QUALIFIED_FINDINGS = 8
_RFS_MAX_UNRESOLVED = 10
_RFS_MAX_NEXT_QUESTIONS = 6

_RFS_SYSTEM = r"""You produce the FINAL synthesis for a completed bounded research run.
You may ONLY consolidate the supplied already-grounded findings. Do not add facts, sources, dates, numbers, comparisons, or conclusions that are not supported by those findings.

Return exactly one JSON object and no prose:
{
  "established_findings": [
    {"claim":"concise consolidated claim", "supporting_finding_indices":[0], "confidence":0.0}
  ],
  "qualified_findings": [
    {"claim":"claim that needs qualification", "qualification":"what remains limited/uncertain", "supporting_finding_indices":[1], "confidence":0.0}
  ],
  "unresolved_questions": ["important unresolved question"],
  "coverage_status": "strong|partial|thin",
  "coverage_reason": "brief reason based only on supplied evidence/uncertainties",
  "next_research_questions": ["specific evidence-seeking follow-up"],
  "overall_confidence": 0.0
}

Rules:
- supporting_finding_indices MUST refer only to supplied finding indices.
- Prefer fewer, stronger consolidated findings over many repetitive ones.
- Do not turn an uncertainty into a fact.
- If findings conflict or coverage is incomplete, use qualified_findings and unresolved_questions.
- Never cite a source directly; Python derives source_refs from the indexed supporting findings.
- overall_confidence and per-finding confidence may LOWER evidence confidence but may never justify raising it.
"""


def _rfs_norm_claim(value):
    return " ".join(str(value or "").split()).strip()


def _rfs_collect(report):
    findings=[]; seen=set(); uncertainties=[]
    # Historical/top-level findings first if present.
    sources=[]
    top=report.get("findings") or []
    if isinstance(top,list): sources.extend(top)
    for cycle in report.get("cycles") or []:
        if not isinstance(cycle,dict): continue
        analysis=cycle.get("analysis") or {}
        vals=analysis.get("findings") or [] if isinstance(analysis,dict) else []
        if isinstance(vals,list): sources.extend(vals)
        if isinstance(analysis,dict):
            for u in analysis.get("uncertainties") or []:
                clean=_rfs_norm_claim(u)
                if clean and clean not in uncertainties: uncertainties.append(clean)
    for item in sources:
        if isinstance(item,str):
            claim=_rfs_norm_claim(item); refs=[]; conf=0.5
        elif isinstance(item,dict):
            claim=_rfs_norm_claim(item.get("claim") or item.get("finding") or item.get("summary"))
            refs=item.get("source_refs") or item.get("evidence_refs") or []
            if isinstance(refs,str): refs=[refs]
            refs=[str(x).strip() for x in refs if str(x).strip()]
            try: conf=float(item.get("confidence",0.5))
            except Exception: conf=0.5
        else: continue
        if not claim: continue
        key=" ".join(re.findall(r"[\w'-]+",claim.casefold()))
        if key in seen: continue
        seen.add(key)
        findings.append({"index":len(findings),"claim":claim,"source_refs":list(dict.fromkeys(refs)),"confidence":max(0.0,min(1.0,conf))})
        if len(findings)>=_RFS_MAX_FINDINGS: break
    return findings,uncertainties


def _rfs_indices(value,count):
    if not isinstance(value,list): return []
    out=[]
    for x in value:
        try:i=int(x)
        except Exception:continue
        if 0<=i<count and i not in out: out.append(i)
    return out


def _rfs_ground_item(raw,findings,qualified=False):
    if not isinstance(raw,dict): return None
    claim=_rfs_norm_claim(raw.get("claim"))
    idx=_rfs_indices(raw.get("supporting_finding_indices"),len(findings))
    if not claim or not idx: return None
    support=[findings[i] for i in idx]
    refs=[]
    for f in support: refs.extend(f.get("source_refs") or [])
    refs=list(dict.fromkeys(str(x) for x in refs if str(x).strip()))
    evidence_cap=min([float(f.get("confidence",0.5)) for f in support] or [0.5])
    try:model_conf=float(raw.get("confidence",evidence_cap))
    except Exception:model_conf=evidence_cap
    effective=max(0.0,min(1.0,evidence_cap,model_conf))
    item={"claim":claim,"supporting_finding_indices":idx,"source_refs":refs,"confidence":round(effective,4),"confidence_cap_from_support":round(evidence_cap,4),"provenance_derived_by":"python-from-supporting-finding-indices"}
    if qualified:
        q=_rfs_norm_claim(raw.get("qualification"))
        if not q: return None
        item["qualification"]=q
    return item


def _rfs_dedupe_items(items):
    out=[]; seen=set()
    for item in items:
        key=" ".join(re.findall(r"[\w'-]+",str(item.get("claim") or "").casefold()))
        if not key or key in seen: continue
        seen.add(key); out.append(item)
    return out


def _rfs_fallback(report,findings,uncertainties,error=""):
    ranked=sorted(findings,key=lambda f:(float(f.get("confidence",0.0)),len(f.get("source_refs") or [])),reverse=True)[:min(8,_RFS_MAX_MAIN_FINDINGS)]
    established=[{"claim":f["claim"],"supporting_finding_indices":[f["index"]],"source_refs":list(f.get("source_refs") or []),"confidence":round(float(f.get("confidence",0.5)),4),"confidence_cap_from_support":round(float(f.get("confidence",0.5)),4),"provenance_derived_by":"python-deterministic-fallback"} for f in ranked]
    status="thin" if len(findings)<3 else "partial" if uncertainties else "strong"
    reason=("Few grounded findings were available." if status=="thin" else "Grounded findings remain accompanied by unresolved uncertainties." if status=="partial" else "The available grounded findings form a coherent bounded synthesis.")
    return {"version":_RESEARCH_FINAL_SYNTHESIS_VERSION,"method":"deterministic_fallback","quality_pass":bool(established),"established_findings":established,"qualified_findings":[],"unresolved_questions":uncertainties[:_RFS_MAX_UNRESOLVED],"coverage_status":status,"coverage_reason":reason,"next_research_questions":[],"overall_confidence":round(min([x["confidence"] for x in established] or [0.0]),4),"source_refs":list(dict.fromkeys(r for x in established for r in x.get("source_refs") or [])),"model_calls":0,"fallback_reason":str(error or "model synthesis unavailable")[:1000]}


def _rfs_validate(raw,report,findings,uncertainties):
    if not isinstance(raw,dict): return _rfs_fallback(report,findings,uncertainties,"non-object synthesis")
    est=[]
    for x in raw.get("established_findings") or []:
        g=_rfs_ground_item(x,findings,False)
        if g: est.append(g)
        if len(est)>=_RFS_MAX_MAIN_FINDINGS: break
    qual=[]
    for x in raw.get("qualified_findings") or []:
        g=_rfs_ground_item(x,findings,True)
        if g: qual.append(g)
        if len(qual)>=_RFS_MAX_QUALIFIED_FINDINGS: break
    est=_rfs_dedupe_items(est); qual=_rfs_dedupe_items(qual)
    if not est and not qual: return _rfs_fallback(report,findings,uncertainties,"model synthesis had no index-grounded findings")
    unresolved=[]
    for x in raw.get("unresolved_questions") or []:
        c=_rfs_norm_claim(x)
        if c and c not in unresolved: unresolved.append(c)
        if len(unresolved)>=_RFS_MAX_UNRESOLVED: break
    # Preserve cycle uncertainties even if the final model omits them.
    for c in uncertainties:
        if c not in unresolved: unresolved.append(c)
        if len(unresolved)>=_RFS_MAX_UNRESOLVED: break
    nxt=[]
    for x in raw.get("next_research_questions") or []:
        c=_rfs_norm_claim(x)
        if c and c not in nxt: nxt.append(c)
        if len(nxt)>=_RFS_MAX_NEXT_QUESTIONS: break
    status=str(raw.get("coverage_status") or "partial").strip().casefold()
    if status not in {"strong","partial","thin"}: status="partial"
    reason=_rfs_norm_claim(raw.get("coverage_reason")) or ("Unresolved questions remain." if unresolved else "Grounded findings were consolidated.")
    support_caps=[float(x.get("confidence",0.0)) for x in est+qual]
    cap=min(support_caps or [0.0])
    try: overall=float(raw.get("overall_confidence",cap))
    except Exception: overall=cap
    overall=max(0.0,min(1.0,overall,cap))
    refs=list(dict.fromkeys(r for x in est+qual for r in x.get("source_refs") or []))
    return {"version":_RESEARCH_FINAL_SYNTHESIS_VERSION,"method":"model-index-grounded","quality_pass":True,"established_findings":est,"qualified_findings":qual,"unresolved_questions":unresolved,"coverage_status":status,"coverage_reason":reason,"next_research_questions":nxt,"overall_confidence":round(overall,4),"source_refs":refs,"model_calls":1,"provenance_rule":"Python derives every synthesis source_ref only from explicitly indexed grounded cycle findings; synthesis cannot introduce new evidence."}


def _rfs_source_catalog(report):
    """Expand existing source_refs into human-readable persisted cycle provenance without model inference."""
    catalog = {}
    for cycle in report.get("cycles") or []:
        if not isinstance(cycle, dict):
            continue
        try: cycle_no = int(cycle.get("cycle") or 0)
        except Exception: cycle_no = 0
        for item in cycle.get("book_passages") or []:
            if not isinstance(item, dict):
                continue
            ref = str(item.get("source_ref") or "").strip()
            if not ref:
                bid = str(item.get("book_id") or "").strip(); cid = str(item.get("chunk_id") or "").strip()
                if bid or cid: ref = f"book:{bid}:{cid}"
            if not ref: continue
            catalog.setdefault(ref, {
                "source_ref": ref,
                "source_type": "book",
                "cycle": cycle_no,
                "book_id": item.get("book_id"),
                "chunk_id": item.get("chunk_id"),
                "title": item.get("title"),
                "authors": item.get("authors"),
                "chapter": item.get("chapter"),
                "ordinal": item.get("ordinal"),
                "page_start": item.get("page_start"),
                "page_end": item.get("page_end"),
                "query": item.get("query"),
            })
        for page in cycle.get("pages") or []:
            if not isinstance(page, dict):
                continue
            url = str(page.get("url") or page.get("canonical_url") or "").strip()
            if not url: continue
            ref = "web:" + url
            catalog.setdefault(ref, {
                "source_ref": ref,
                "source_type": "web",
                "cycle": cycle_no,
                "url": url,
                "title": page.get("title"),
                "author": page.get("author"),
                "published_at": page.get("published_at") or page.get("date"),
            })
        analysis = cycle.get("analysis") or {}
        if isinstance(analysis, dict):
            for unit in analysis.get("adaptive_web_evidence") or []:
                if not isinstance(unit, dict):
                    continue
                ref = str(unit.get("source_ref") or "").strip()
                if not ref:
                    continue
                catalog.setdefault(ref, {
                    "source_ref": ref,
                    "source_type": "web",
                    "cycle": cycle_no,
                    "url": unit.get("url"),
                    "title": unit.get("title"),
                    "author": unit.get("author"),
                    "published_at": unit.get("published_at"),
                    "snapshot_id": unit.get("snapshot_id"),
                    "source_document_id": unit.get("source_document_id"),
                    "adaptive_web_evidence_unit_id": unit.get("unit_id"),
                    "semantic_start": unit.get("start"),
                    "semantic_end": unit.get("end"),
                    "underlying_source_chunk_refs": unit.get("source_chunk_refs") or [],
                    "source_sha256": unit.get("source_sha256"),
                    "unit_kind": unit.get("unit_kind"),
                    "resume": unit.get("resume"),
                })
    return catalog


def _rfs_expand_provenance(report, refs):
    catalog = _rfs_source_catalog(report)
    out = []
    for ref in refs or []:
        key = str(ref or "").strip()
        if not key: continue
        item = dict(catalog.get(key) or {})
        if not item:
            kind = "book" if key.startswith("book:") else "web" if (key.startswith("web:") or key.startswith("web-unit:")) else "evidence"
            item = {"source_ref": key, "source_type": kind}
            if kind == "book":
                parts = key.split(":", 2)
                if len(parts) > 1: item["book_id"] = parts[1] or None
                if len(parts) > 2: item["chunk_id"] = parts[2] or None
            elif kind == "web" and key.startswith("web:"):
                item["url"] = key[4:]
        out.append(item)
    return out


def _rfs_attach_readable_provenance(report, synthesis):
    for group in ("established_findings", "qualified_findings"):
        for finding in synthesis.get(group) or []:
            if not isinstance(finding, dict): continue
            finding["provenance"] = _rfs_expand_provenance(report, finding.get("source_refs") or [])
            finding["source_types"] = list(dict.fromkeys(str(x.get("source_type") or "evidence") for x in finding["provenance"]))
    synthesis["source_catalog"] = _rfs_source_catalog(report)
    synthesis["provenance_expanded_by"] = "python-from-persisted-cycle-evidence"
    return synthesis


def _rfs_executive_text(synthesis):
    parts=[]
    est=synthesis.get("established_findings") or []
    qual=synthesis.get("qualified_findings") or []
    if est: parts.append("Established: "+" ".join(str(x.get("claim") or "").rstrip(".")+"." for x in est[:6]))
    if qual: parts.append("Qualified: "+" ".join((str(x.get("claim") or "").rstrip(".")+" — "+str(x.get("qualification") or "").rstrip(".")+".") for x in qual[:4]))
    parts.append("Coverage: "+str(synthesis.get("coverage_status") or "partial")+" — "+str(synthesis.get("coverage_reason") or ""))
    if synthesis.get("unresolved_questions"): parts.append("Unresolved: "+" ".join(str(x).rstrip("?")+"?" for x in (synthesis.get("unresolved_questions") or [])[:4]))
    return " ".join(parts)[:5000]


def _rfs_apply_to_result(web_module,backend,result):
    report=result.report; findings,uncertainties=_rfs_collect(report)
    if not findings:
        synthesis=_rfs_fallback(report,findings,uncertainties,"no grounded cycle findings")
    else:
        payload={"topic":report.get("topic"),"completed_iterations":report.get("completed_iterations"),"stopped_early":bool(report.get("stopped_early")),"stop_reason":report.get("stop_reason") or "","grounded_findings":findings,"cycle_uncertainties":uncertainties}
        try:
            raw=web_module._chat_json(backend,_RFS_SYSTEM,json.dumps(payload,ensure_ascii=False))
            synthesis=_rfs_validate(raw,report,findings,uncertainties)
        except Exception as exc:
            synthesis=_rfs_fallback(report,findings,uncertainties,f"{type(exc).__name__}: {exc}")
    synthesis=_rfs_attach_readable_provenance(report,synthesis)
    synthesis["executive_summary"]=_rfs_executive_text(synthesis)
    synthesis["generated_at"]=_sk_now() if '_sk_now' in globals() else datetime.now(timezone.utc).isoformat()
    synthesis["raw_grounded_finding_count"]=len(findings)
    report["research_synthesis"]=synthesis
    # These top-level fields repair the historical report/history surface and
    # make compact research retrieval see consolidated findings directly.
    report["main_findings"]=[dict(x) for x in (synthesis.get("established_findings") or [])]
    report["qualified_findings"]=[dict(x) for x in (synthesis.get("qualified_findings") or [])]
    report["findings"]=[dict(x) for x in (synthesis.get("established_findings") or [])]+[dict(x) for x in (synthesis.get("qualified_findings") or [])]
    report["unresolved_questions"]=list(synthesis.get("unresolved_questions") or [])
    report["research_coverage"]={"status":synthesis.get("coverage_status"),"reason":synthesis.get("coverage_reason"),"overall_confidence":synthesis.get("overall_confidence")}
    result.report_path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    return result


def _install_research_final_synthesis(module):
    if getattr(module,"_RESEARCH_FINAL_SYNTHESIS_INSTALLED",False): return
    web=sys.modules.get("neatweb_research_v1_4_stable")
    if web is None: return
    original_run=getattr(module,"run_research_loop",None)
    original_auto=getattr(module,"run_autonomous_research_loop",None)
    if callable(original_run):
        def run_with_final_synthesis(*args,**kwargs):
            result=original_run(*args,**kwargs)
            if not ((result.report or {}).get("research_synthesis") or {}).get("version"):
                backend=args[0] if args else kwargs.get("backend")
                result=_rfs_apply_to_result(web,backend,result)
            return result
        module.run_research_loop=run_with_final_synthesis; web.run_research_loop=run_with_final_synthesis
    if callable(original_auto):
        def autonomous_with_final_synthesis(*args,**kwargs):
            result=original_auto(*args,**kwargs)
            if not ((result.report or {}).get("research_synthesis") or {}).get("version"):
                backend=args[0] if args else kwargs.get("backend")
                result=_rfs_apply_to_result(web,backend,result)
            return result
        module.run_autonomous_research_loop=autonomous_with_final_synthesis; web.run_autonomous_research_loop=autonomous_with_final_synthesis
    module.get_research_synthesis=lambda run_id: _rfs_get_saved_synthesis(module,run_id)
    module.research_final_synthesis_self_test=lambda:research_final_synthesis_self_test(module)
    module.RESEARCH_FINAL_SYNTHESIS_VERSION=_RESEARCH_FINAL_SYNTHESIS_VERSION
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["research-final-synthesis"]={"label":"Final /learn synthesis is index-grounded in cycle findings, Python-derived provenance, confidence-capped, uncertainty-preserving, and visible at top level","groups":("quick","critical","all"),"runner":"memory.research_final_synthesis_self_test"}
    module._RESEARCH_FINAL_SYNTHESIS_INSTALLED=True


def _rfs_get_saved_synthesis(module,run_id):
    try:
        result=module.read_research_report(str(run_id),max_chars=120000)
    except Exception as exc:
        return {"ok":False,"error":f"{type(exc).__name__}: {exc}"}
    if not result.get("ok"): return result
    path=Path(result.get("path") or "")
    try: report=json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc: return {"ok":False,"error":f"{type(exc).__name__}: {exc}"}
    return {"ok":True,"run_id":str(run_id),"research_synthesis":report.get("research_synthesis"),"main_findings":report.get("main_findings") or [],"unresolved_questions":report.get("unresolved_questions") or []}


def research_final_synthesis_self_test(module=None):
    report={"topic":"persistent memory systems","completed_iterations":2,"cycles":[{"cycle":1,"book_passages":[{"source_ref":"book:BK-TEST:BK-TEST-C000007","book_id":"BK-TEST","chunk_id":"BK-TEST-C000007","title":"Test Book","ordinal":7,"chapter":"Memory","query":"exact source"}],"pages":[{"url":"https://example.test/retrieval","title":"Retrieval Source"}],"analysis":{"findings":[{"claim":"System A stores exact source text immutably.","source_refs":["book:BK-TEST:BK-TEST-C000007"],"confidence":0.9},{"claim":"System B uses retrieval plus consolidation.","source_refs":["web:https://example.test/retrieval"],"confidence":0.8}],"uncertainties":["Long-term benchmark coverage remains incomplete."]}},{"cycle":2,"analysis":{"findings":[{"claim":"System A stores exact source text immutably.","source_refs":["book:BK-TEST:BK-TEST-C000007"],"confidence":0.9},{"claim":"Only System B reports a bounded forgetting mechanism in this sample.","source_refs":["source-chunk:RSC-C"],"confidence":0.72}],"uncertainties":[]}}]}
    findings,unc=_rfs_collect(report)
    raw={"established_findings":[{"claim":"System A preserves exact source text immutably.","supporting_finding_indices":[0],"confidence":0.95},{"claim":"System B combines retrieval and consolidation.","supporting_finding_indices":[1],"confidence":0.75}],"qualified_findings":[{"claim":"The sample suggests a bounded forgetting mechanism for System B.","qualification":"The available evidence does not establish broad long-term comparative coverage.","supporting_finding_indices":[2],"confidence":0.7}],"unresolved_questions":[],"coverage_status":"partial","coverage_reason":"Long-term comparative evidence is incomplete.","next_research_questions":["Which systems report longitudinal memory benchmarks?"],"overall_confidence":0.9}
    syn=_rfs_attach_readable_provenance(report,_rfs_validate(raw,report,findings,unc))
    bad=_rfs_validate({"established_findings":[{"claim":"Invented claim","supporting_finding_indices":[99],"confidence":1.0}]},report,findings,unc)
    checks={
        "cycle_findings_are_collected":len(findings)==3,
        "duplicate_cycle_findings_are_collapsed":findings[0]["claim"].startswith("System A") and findings[1]["claim"].startswith("System B"),
        "provenance_is_python_derived":syn["established_findings"][0]["source_refs"]==["book:BK-TEST:BK-TEST-C000007"] and syn["established_findings"][0]["provenance_derived_by"].startswith("python"),
        "book_provenance_is_readable":syn["established_findings"][0]["provenance"][0].get("book_id")=="BK-TEST" and syn["established_findings"][0]["provenance"][0].get("chunk_id")=="BK-TEST-C000007" and syn["established_findings"][0]["provenance"][0].get("ordinal")==7,
        "web_provenance_is_readable":syn["established_findings"][1]["provenance"][0].get("url")=="https://example.test/retrieval" and syn["established_findings"][1]["source_types"]==["web"],
        "confidence_cannot_exceed_support":syn["established_findings"][0]["confidence"]==0.9 and syn["overall_confidence"]<=0.7,
        "uncertainty_is_preserved":any("benchmark coverage" in x for x in syn["unresolved_questions"]),
        "qualified_finding_retained":len(syn["qualified_findings"])==1,
        "invalid_indices_cannot_create_grounded_claim":bad.get("method")=="deterministic_fallback" and all(x.get("claim")!="Invented claim" for x in bad.get("established_findings") or []),
        "fallback_still_uses_grounded_findings":all(set(x.get("source_refs") or []).issubset({"book:BK-TEST:BK-TEST-C000007","web:https://example.test/retrieval","source-chunk:RSC-C"}) for x in bad.get("established_findings") or []),
    }
    return {"ok":all(checks.values()),"checks":checks,"version":_RESEARCH_FINAL_SYNTHESIS_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


# ---------------------------------------------------------------------------
# NeatMemory 7.4.28 — Deep Redigest Fidelity & Force
# ---------------------------------------------------------------------------
_DEEP_REDIGEST_FIDELITY_FORCE_VERSION = "1.0-explicit-target-fidelity-force-full-restart"


def deep_redigest_fidelity_force_self_test(module=None):
    checks={}
    # Reproduce the live Romeo & Juliet failure shape: Paris occurs in the
    # proposed claim metadata but not literally in the target source.
    source="Juliet speaks of the night and of her fears before the coming day."
    payload={"batch_complete":True,"memories":[{"kind":"fact","claim":"Paris is contextually relevant to Juliet's situation.","details":"","source_refs":["book:BK-TEST:C15"],"interpretation":"paraphrase","domain":"literature","importance":0.6,"confidence":0.7,"entities":[{"name":"Paris","origin":"explicit","confidence":0.9,"reason":""}],"implicit_keywords":[]}]}
    repaired,repairs=_sk_deep_safe_metadata_repair(json.loads(json.dumps(payload)),source)
    entity=((repaired.get("memories") or [{}])[0].get("entities") or [{}])[0]
    checks["nonliteral_explicit_entity_cannot_remain_explicit"]=entity.get("origin")=="inferred" and "not literal in the target chunk" in str(entity.get("reason") or "")
    audit=_sk_deep_validate_payload(repaired,{"book:BK-TEST:C15":{"excerpt":source}},source,max_memories=4)
    checks["repaired_contextual_entity_passes_entity_fidelity_gate"]=audit.get("ok") is True

    # Verify forced restart non-destructively supersedes only incomplete deep
    # checkpoints while a completed active version remains active.
    original=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV)
    original_connect=globals().get("_sk_connect")
    opened_connections=[]
    def _tracked_connect(*args,**kwargs):
        db=original_connect(*args,**kwargs); opened_connections.append(db); return db
    globals()["_sk_connect"]=_tracked_connect
    try:
        with tempfile.TemporaryDirectory(prefix="neat-deep-force-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=folder
            _sk_ensure_schema(module)
            source_row=_sk_upsert_source("book","BK-FORCE","Force Test","f"*64,{"kind":"test"})
            active=_sk_begin_version(source=source_row,scope="full book",digest_mode="deep",provider="gpt",model_alias="luna",model_id="test-luna",operation="redigest",total_chunks=2)
            _sk_finalize_version(source_row["source_id"],active["version_id"],active["run_id"],processed=2,model_calls=2,items=0)
            paused=_sk_begin_version(source=source_row,scope="full book",digest_mode="deep",provider="gpt",model_alias="luna",model_id="test-luna",operation="redigest",total_chunks=2)
            _sk_pause_version(paused["version_id"],paused["run_id"],"synthetic pause",processed=1,model_calls=1,items=0)
            changed=_sk_supersede_resumable_deep_versions(source_row["source_id"],source_sha256="f"*64,provider="gpt",model_alias="luna",model_id="test-luna",operation="redigest")
            with _sk_connect() as db:
                prow=db.execute("SELECT status,archive,active FROM knowledge_versions WHERE version_id=?",(paused["version_id"],)).fetchone()
                arow=db.execute("SELECT status,archive,active FROM knowledge_versions WHERE version_id=?",(active["version_id"],)).fetchone()
            checks["force_supersedes_incomplete_checkpoint_non_destructively"]=paused["version_id"] in changed and str(prow["status"])=="superseded" and int(prow["archive"])==1 and int(prow["active"])==0
            checks["force_does_not_touch_completed_active_digest"]=str(arow["status"])=="completed" and int(arow["active"])==1 and int(arow["archive"])==0
            # Windows-safe cleanup: sqlite3.Connection context managers commit/rollback
            # but do not close the underlying handle. Close every tracked connection
            # before TemporaryDirectory attempts to remove DB/WAL/SHM files.
            for db in reversed(opened_connections):
                try: db.close()
                except Exception: pass
            opened_connections.clear()
    finally:
        for db in reversed(opened_connections):
            try: db.close()
            except Exception: pass
        globals()["_sk_connect"]=original_connect
        if original is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=original

    # Public API/parser contract: force_full is a first-class digest parameter and
    # the CURRENT wrapped dispatcher must carry --force through behaviorally. Older
    # tests inspected one wrapper's bytecode constants and failed after harmless wrapping.
    checks["force_full_api_exposed"]="force_full" in _sk_digest_book.__code__.co_varnames
    old_load=globals().get("_load_digest_for_memory"); old_backend=globals().get("_sk_backend"); old_digest=globals().get("_sk_digest_book")
    observed={}
    try:
        globals()["_load_digest_for_memory"]=lambda mod: object()
        globals()["_sk_backend"]=lambda digest,mod,use_lmstudio=False,gpt_alias=None:(object(),"local",None)
        def _force_probe(digest_module,memory_module,backend,book_ref,scope_tokens=None,*,operation="digest",deep=False,model_alias=None,force_full=False):
            observed.update({"book_ref":book_ref,"operation":operation,"deep":bool(deep),"force_full":bool(force_full)})
            return {"ok":True,"self_test":True}
        globals()["_sk_digest_book"]=_force_probe
        import contextlib as _contextlib, io as _io
        with _contextlib.redirect_stdout(_io.StringIO()):
            handled=_sk_dispatch_command(module or object(),"/redigest BK-FORCE --deep --force")
        checks["force_flag_is_parsed"]=handled is True and observed=={"book_ref":"BK-FORCE","operation":"redigest","deep":True,"force_full":True}
    finally:
        if old_load is not None: globals()["_load_digest_for_memory"]=old_load
        if old_backend is not None: globals()["_sk_backend"]=old_backend
        if old_digest is not None: globals()["_sk_digest_book"]=old_digest
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_DEEP_REDIGEST_FIDELITY_FORCE_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


def _install_deep_redigest_fidelity_force(module):
    if getattr(module,"_DEEP_REDIGEST_FIDELITY_FORCE_INSTALLED",False): return
    module.deep_redigest_fidelity_force_self_test=lambda:deep_redigest_fidelity_force_self_test(module)
    module.DEEP_REDIGEST_FIDELITY_FORCE_VERSION=_DEEP_REDIGEST_FIDELITY_FORCE_VERSION
    module.RELEASE_NAME=RELEASE_NAME
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["deep-redigest-fidelity-force"]={"label":"Deep explicit entities are target-literal or safely inferred, and --force starts a fresh full redigest without stale checkpoints","groups":("quick","critical","all"),"runner":"memory.deep_redigest_fidelity_force_self_test"}
    module._DEEP_REDIGEST_FIDELITY_FORCE_INSTALLED=True



# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:research-pyramid rev=1
# NeatMemory 7.4.78.27 — Book-pattern Research Pyramid over retained multi-source evidence
# ---------------------------------------------------------------------------
# Research already has immutable retained pages, canonical source chunks, Assistant-chosen
# web evidence units, grounded cycle findings, and final synthesis. This layer derives
# a compact navigation pyramid from those persisted objects without re-researching or
# re-summarizing them. Derived nodes are navigation/interpretation, never source truth.
# Compression goes upward; verification goes downward.

_RESEARCH_PYRAMID_VERSION = "1.0-book-pattern-multisource-exact-evidence-exits"
_RESEARCH_PYRAMID_HINT_CHARS = 160
_RESEARCH_PYRAMID_LEXICON_MAX_TERMS = 2048
_RESEARCH_PYRAMID_TOOL_NAMES = {
    "research_pyramid_status", "search_research_pyramid", "get_research_pyramid_node",
    "read_research_evidence", "discover_research_candidates",
}


def _rp_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds")


def _rp_hash_text(value: object) -> str:
    return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()


def _rp_hash_json(value: object) -> str:
    raw=json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),default=str).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _rp_connect(module) -> sqlite3.Connection:
    db=sqlite3.connect(_research_archive_db_path(module),timeout=30)
    db.row_factory=sqlite3.Row
    db.execute("PRAGMA foreign_keys=ON")
    db.execute("PRAGMA busy_timeout=30000")
    return db


def _rp_ensure_schema(module) -> dict:
    import contextlib
    Path(_research_archive_db_path(module)).parent.mkdir(parents=True,exist_ok=True)
    with contextlib.closing(_rp_connect(module)) as db, db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS research_pyramid_meta(
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS research_pyramid_runs(
            run_id TEXT PRIMARY KEY,
            topic TEXT,
            report_path TEXT,
            report_sha256 TEXT NOT NULL,
            builder_version TEXT NOT NULL,
            node_count INTEGER NOT NULL DEFAULT 0,
            evidence_link_count INTEGER NOT NULL DEFAULT 0,
            built_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS research_pyramid_nodes(
            node_id TEXT PRIMARY KEY,
            run_id TEXT NOT NULL,
            sequence_no INTEGER NOT NULL,
            node_kind TEXT NOT NULL,
            status TEXT NOT NULL,
            title TEXT NOT NULL,
            hint_text TEXT NOT NULL,
            hint_sha256 TEXT NOT NULL,
            full_summary TEXT NOT NULL,
            full_summary_sha256 TEXT NOT NULL,
            full_summary_chars INTEGER NOT NULL,
            search_lexicon TEXT NOT NULL,
            search_lexicon_sha256 TEXT NOT NULL,
            confidence REAL,
            source_refs_json TEXT NOT NULL DEFAULT '[]',
            provenance_json TEXT NOT NULL DEFAULT '[]',
            created_at TEXT NOT NULL,
            FOREIGN KEY(run_id) REFERENCES research_pyramid_runs(run_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_research_pyramid_nodes_run ON research_pyramid_nodes(run_id,sequence_no,node_kind);
        CREATE INDEX IF NOT EXISTS idx_research_pyramid_nodes_kind ON research_pyramid_nodes(node_kind,status);
        CREATE TABLE IF NOT EXISTS research_pyramid_evidence(
            node_id TEXT NOT NULL,
            evidence_index INTEGER NOT NULL,
            source_ref TEXT NOT NULL,
            source_type TEXT NOT NULL,
            relation TEXT NOT NULL,
            provenance_json TEXT NOT NULL DEFAULT '{}',
            exact_exit_kind TEXT NOT NULL,
            source_sha256 TEXT,
            localized INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            PRIMARY KEY(node_id,evidence_index),
            FOREIGN KEY(node_id) REFERENCES research_pyramid_nodes(node_id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_research_pyramid_evidence_ref ON research_pyramid_evidence(source_ref);
        """)
        now=_rp_now()
        db.execute("INSERT INTO research_pyramid_meta(key,value,updated_at) VALUES('version',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(_RESEARCH_PYRAMID_VERSION,now))
    return {"ok":True,"version":_RESEARCH_PYRAMID_VERSION,"database":str(_research_archive_db_path(module))}


def _rp_tokens(value: object) -> list[str]:
    folded=unicodedata.normalize("NFKC",str(value or "")).casefold()
    out=[]; seen=set()
    for term in re.findall(r"[^\W_]+",folded,flags=re.UNICODE):
        if term and term not in seen:
            seen.add(term); out.append(term)
            if len(out)>=_RESEARCH_PYRAMID_LEXICON_MAX_TERMS: break
    return out


def _rp_lexicon(title: object, summary: object) -> str:
    terms=_rp_tokens(f"{str(title or '')} {str(summary or '')}")
    return "|"+"|".join(terms)+"|" if terms else "||"


def _rp_hint(value: object) -> str:
    fn=globals().get("_shn_compact_hint")
    if callable(fn):
        return str(fn(value,_RESEARCH_PYRAMID_HINT_CHARS))
    clean=" ".join(str(value or "").split())
    if len(clean)<=_RESEARCH_PYRAMID_HINT_CHARS: return clean
    cap=max(1,_RESEARCH_PYRAMID_HINT_CHARS-1); cut=clean[:cap]
    pos=max(cut.rfind(". "),cut.rfind("; "),cut.rfind(", "),cut.rfind(" "))
    if pos>=max(24,cap//2): cut=cut[:pos]
    return cut.rstrip(" .;,:") + "…"


def _rp_report_from_result(module, run_id: str) -> tuple[dict,str]:
    reader=getattr(module,"read_research_report",None)
    if callable(reader):
        try:
            raw=reader(str(run_id),max_chars=2_000_000)
            if isinstance(raw,dict) and raw.get("ok") is not False:
                report=raw.get("report") if isinstance(raw.get("report"),dict) else raw
                if isinstance(report,dict):
                    return dict(report),str(raw.get("path") or raw.get("report_path") or "")
        except Exception:
            pass
    _rp_ensure_schema(module)
    import contextlib
    try:
        with contextlib.closing(_rp_connect(module)) as db:
            row=db.execute("SELECT report_path FROM research_runs WHERE run_id=?",(str(run_id),)).fetchone()
    except sqlite3.OperationalError:
        row=None
    raw_path=str(row["report_path"] or "") if row else ""
    candidates=[]
    if raw_path:
        p=Path(raw_path); candidates.append(p)
        root=Path(getattr(module,"MEMORY_DIR",Path.cwd()))
        if not p.is_absolute(): candidates.extend([root/p,root/"research_reports"/p.name])
    for path in candidates:
        try:
            if path.is_file(): return json.loads(path.read_text(encoding="utf-8")),str(path)
        except Exception:
            continue
    return {},raw_path


def _rp_report_sha(report: dict, report_path: str="") -> str:
    try:
        path=Path(str(report_path or ""))
        if path.is_file(): return hashlib.sha256(path.read_bytes()).hexdigest()
    except Exception:
        pass
    return _rp_hash_json(report)


def _rp_source_catalog(module, report: dict) -> dict:
    catalog={}
    base=globals().get("_rfs_source_catalog")
    if callable(base):
        try: catalog.update({str(k):dict(v) for k,v in (base(report) or {}).items() if isinstance(v,dict)})
        except Exception: pass
    for cycle in report.get("cycles") or []:
        if not isinstance(cycle,dict): continue
        cycle_no=int(cycle.get("cycle") or 0)
        for page in cycle.get("pages") or []:
            if not isinstance(page,dict): continue
            url=str(page.get("url") or page.get("canonical_url") or "").strip()
            if not url: continue
            ref="web:"+url
            item=dict(catalog.get(ref) or {})
            item.update({
                "source_ref":ref,"source_type":"web","cycle":cycle_no,"url":url,
                "title":page.get("title"),"author":page.get("author"),"published_at":page.get("published_at") or page.get("date"),
                "snapshot_id":page.get("snapshot_id"),"page_id":page.get("page_id"),
                "source_document_id":page.get("source_document_id"),"readable_text_sha256":page.get("archive_text_sha256") or page.get("evidence_text_sha256"),
            })
            catalog[ref]=item
        analysis=cycle.get("analysis") or {}
        if isinstance(analysis,dict):
            for unit in analysis.get("adaptive_web_evidence") or []:
                if not isinstance(unit,dict): continue
                ref=str(unit.get("source_ref") or "").strip()
                if not ref: continue
                item=dict(catalog.get(ref) or {})
                item.update({
                    "source_ref":ref,"source_type":"web","cycle":cycle_no,"url":unit.get("url"),"title":unit.get("title"),
                    "author":unit.get("author"),"published_at":unit.get("published_at"),"snapshot_id":unit.get("snapshot_id"),
                    "source_document_id":unit.get("source_document_id"),"adaptive_web_evidence_unit_id":unit.get("unit_id"),
                    "semantic_start":unit.get("start"),"semantic_end":unit.get("end"),"underlying_source_chunk_refs":unit.get("source_chunk_refs") or [],
                    "source_sha256":unit.get("source_sha256"),"unit_kind":unit.get("unit_kind"),"resume":unit.get("resume"),
                })
                catalog[ref]=item
    return catalog


def _rp_exit_kind(source_ref: str, provenance: dict) -> tuple[str,bool]:
    ref=str(source_ref or "")
    if ref.startswith("web-unit:"): return "adaptive_web_evidence_unit",True
    if ref.startswith("source-chunk:"): return "canonical_source_chunk",True
    if ref.startswith("book:") and (provenance.get("chunk_id") or len(ref.split(":",2))>=3): return "canonical_book_chunk",True
    if ref.startswith("web:") and provenance.get("snapshot_id"): return "archived_snapshot_unlocalized",False
    if ref.startswith("web:"): return "web_source_metadata",False
    return "source_reference",False


def _rp_make_node(run_id: str, sequence_no: int, node_kind: str, status: str, title: str, summary: str,
                  confidence, source_refs: list[str], provenance: list[dict]) -> dict:
    title=" ".join(str(title or "").split()).strip() or node_kind.replace("_"," ").title()
    summary=" ".join(str(summary or "").split()).strip()
    hint=_rp_hint(summary or title)
    lexicon=_rp_lexicon(title,summary)
    node_id="RPN-"+_rp_hash_json({"run":run_id,"kind":node_kind,"seq":sequence_no,"title":title,"summary":summary})[:20].upper()
    try: conf=None if confidence is None else max(0.0,min(1.0,float(confidence)))
    except Exception: conf=None
    return {
        "node_id":node_id,"run_id":run_id,"sequence_no":int(sequence_no),"node_kind":node_kind,"status":status,
        "title":title,"hint_text":hint,"full_summary":summary,"search_lexicon":lexicon,"confidence":conf,
        "source_refs":list(dict.fromkeys(str(x) for x in source_refs if str(x or "").strip())),
        "provenance":[dict(x) for x in provenance if isinstance(x,dict)],
    }


def _rp_collect_nodes(module, report: dict, run_id: str) -> tuple[list[dict],dict]:
    synth=report.get("research_synthesis") or {}
    if not isinstance(synth,dict): synth={}
    catalog=_rp_source_catalog(module,report)
    nodes=[]; seq=1
    topic=str(report.get("topic") or synth.get("topic") or run_id)
    executive=str(synth.get("executive_summary") or "").strip()
    if not executive:
        pieces=[]
        for item in report.get("main_findings") or []:
            if isinstance(item,dict): pieces.append(str(item.get("claim") or ""))
            else: pieces.append(str(item or ""))
        executive=" ".join(x for x in pieces if x).strip()
    run_refs=[str(x) for x in (synth.get("source_refs") or []) if str(x or "").strip()]
    run_prov=[dict(catalog[x]) for x in run_refs if x in catalog]
    if executive or topic:
        nodes.append(_rp_make_node(run_id,seq,"run_summary",str((synth.get("coverage_status") or "summary")),topic,executive or topic,synth.get("overall_confidence"),run_refs,run_prov)); seq+=1
    established=synth.get("established_findings") or report.get("main_findings") or []
    qualified=synth.get("qualified_findings") or report.get("qualified_findings") or []
    for status,items in (("established",established),("qualified",qualified)):
        for item in items:
            if not isinstance(item,dict): item={"claim":str(item or "")}
            claim=" ".join(str(item.get("claim") or "").split()).strip()
            if not claim: continue
            qualification=" ".join(str(item.get("qualification") or "").split()).strip()
            summary=claim+(f" Qualification: {qualification}" if qualification else "")
            refs=[str(x) for x in (item.get("source_refs") or []) if str(x or "").strip()]
            prov=[dict(x) for x in (item.get("provenance") or []) if isinstance(x,dict)]
            if not prov: prov=[dict(catalog[x]) for x in refs if x in catalog]
            nodes.append(_rp_make_node(run_id,seq,"claim",status,claim,summary,item.get("confidence"),refs,prov)); seq+=1
    unresolved=synth.get("unresolved_questions") or report.get("unresolved_questions") or []
    for q in unresolved:
        text=" ".join(str(q or "").split()).strip()
        if text:
            nodes.append(_rp_make_node(run_id,seq,"unresolved_question","unresolved",text,text,None,[],[])); seq+=1
    seen_units=set()
    for cycle in report.get("cycles") or []:
        if not isinstance(cycle,dict): continue
        analysis=cycle.get("analysis") or {}
        if not isinstance(analysis,dict): continue
        for unit in analysis.get("adaptive_web_evidence") or []:
            if not isinstance(unit,dict): continue
            ref=str(unit.get("source_ref") or "").strip(); uid=str(unit.get("unit_id") or "")
            key=ref or uid
            if not key or key in seen_units: continue
            seen_units.add(key)
            title=str(unit.get("unit_title") or unit.get("title") or unit.get("url") or uid)
            summary=str(unit.get("resume") or "").strip() or title
            prov=dict(catalog.get(ref) or {}) if ref else {}
            refs=[ref] if ref else []
            status="analysis_evidence" if bool(unit.get("use_for_analysis")) else "navigation_only"
            nodes.append(_rp_make_node(run_id,seq,"evidence_unit",status,title,summary,None,refs,[prov] if prov else [])); seq+=1
    return nodes,catalog


def _rp_build_run(module, report: dict, report_path: str="", *, reason: str="manual_rebuild") -> dict:
    _rp_ensure_schema(module)
    run_id=str(report.get("run_id") or (Path(str(report_path)).stem if report_path else "")).strip()
    if not run_id: return {"ok":False,"error":"Research report has no run_id.","model_calls":0,"web_calls":0}
    nodes,catalog=_rp_collect_nodes(module,report,run_id)
    report_sha=_rp_report_sha(report,report_path); now=_rp_now(); topic=str(report.get("topic") or "")
    import contextlib
    with contextlib.closing(_rp_connect(module)) as db, db:
        old_ids=[str(r[0]) for r in db.execute("SELECT node_id FROM research_pyramid_nodes WHERE run_id=?",(run_id,)).fetchall()]
        if old_ids:
            db.execute("DELETE FROM research_pyramid_evidence WHERE node_id IN (SELECT node_id FROM research_pyramid_nodes WHERE run_id=?)",(run_id,))
            db.execute("DELETE FROM research_pyramid_nodes WHERE run_id=?",(run_id,))
        db.execute("INSERT INTO research_pyramid_runs(run_id,topic,report_path,report_sha256,builder_version,node_count,evidence_link_count,built_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(run_id) DO UPDATE SET topic=excluded.topic,report_path=excluded.report_path,report_sha256=excluded.report_sha256,builder_version=excluded.builder_version,node_count=excluded.node_count,evidence_link_count=excluded.evidence_link_count,built_at=excluded.built_at",(run_id,topic,str(report_path or ""),report_sha,_RESEARCH_PYRAMID_VERSION,0,0,now))
        evidence_total=0
        for node in nodes:
            refs=node["source_refs"]; provs=node["provenance"]
            db.execute("""INSERT INTO research_pyramid_nodes(node_id,run_id,sequence_no,node_kind,status,title,hint_text,hint_sha256,full_summary,full_summary_sha256,full_summary_chars,search_lexicon,search_lexicon_sha256,confidence,source_refs_json,provenance_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",(
                node["node_id"],run_id,node["sequence_no"],node["node_kind"],node["status"],node["title"],node["hint_text"],_rp_hash_text(node["hint_text"]),node["full_summary"],_rp_hash_text(node["full_summary"]),len(node["full_summary"]),node["search_lexicon"],_rp_hash_text(node["search_lexicon"]),node["confidence"],json.dumps(refs,ensure_ascii=False),json.dumps(provs,ensure_ascii=False,default=str),now))
            prov_by_ref={str(x.get("source_ref") or ""):dict(x) for x in provs if isinstance(x,dict) and str(x.get("source_ref") or "")}
            for idx,ref in enumerate(refs,1):
                prov=dict(prov_by_ref.get(ref) or catalog.get(ref) or {"source_ref":ref})
                source_type=str(prov.get("source_type") or ("book" if ref.startswith("book:") else "web" if ref.startswith("web") else "evidence"))
                kind,localized=_rp_exit_kind(ref,prov)
                source_sha=str(prov.get("source_sha256") or prov.get("readable_text_sha256") or prov.get("text_sha256") or "")
                db.execute("INSERT INTO research_pyramid_evidence(node_id,evidence_index,source_ref,source_type,relation,provenance_json,exact_exit_kind,source_sha256,localized,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(node["node_id"],idx,ref,source_type,"supports_or_qualifies" if node["node_kind"]=="claim" else "navigates_to",json.dumps(prov,ensure_ascii=False,default=str),kind,source_sha or None,1 if localized else 0,now))
                evidence_total+=1
        db.execute("UPDATE research_pyramid_runs SET node_count=?,evidence_link_count=?,built_at=? WHERE run_id=?",(len(nodes),evidence_total,now,run_id))
    return {"ok":True,"operation":"research_pyramid_build","reason":reason,"run_id":run_id,"topic":topic,"nodes":len(nodes),"evidence_links":evidence_total,"report_sha256":report_sha,"model_calls":0,"web_calls":0,"source_text_read":False,"semantic_redistillation":False,"authority":"Derived research navigation only; retained exact sources remain authoritative."}


def _rp_run_ids(module) -> list[str]:
    _rp_ensure_schema(module); import contextlib
    try:
        with contextlib.closing(_rp_connect(module)) as db:
            rows=db.execute("SELECT run_id FROM research_runs ORDER BY COALESCE(finished_at,created_at,archived_at),run_id").fetchall()
        return [str(r[0]) for r in rows]
    except sqlite3.OperationalError:
        return []


def _rp_rebuild(module, reference: str="all") -> dict:
    clean=str(reference or "all").strip(); ids=_rp_run_ids(module) if clean.casefold()=="all" else [clean]
    results=[]
    for rid in ids:
        report,path=_rp_report_from_result(module,rid)
        if not report:
            results.append({"ok":False,"run_id":rid,"error":"Research report could not be read.","model_calls":0,"web_calls":0}); continue
        results.append(_rp_build_run(module,report,path,reason="manual_rebuild"))
    return {"ok":bool(results) and all(bool(x.get("ok")) for x in results),"operation":"research_pyramid_rebuild","reference":clean,"runs":len(results),"nodes":sum(int(x.get("nodes") or 0) for x in results),"evidence_links":sum(int(x.get("evidence_links") or 0) for x in results),"results":results,"model_calls":0,"web_calls":0,"redigest_required":False,"research_calls":0}


def _rp_status(module) -> dict:
    _rp_ensure_schema(module); import contextlib
    with contextlib.closing(_rp_connect(module)) as db:
        built=[dict(r) for r in db.execute("SELECT * FROM research_pyramid_runs ORDER BY built_at DESC").fetchall()]
        counts={str(r[0]):int(r[1]) for r in db.execute("SELECT node_kind,COUNT(*) FROM research_pyramid_nodes GROUP BY node_kind").fetchall()}
        nodes=int(db.execute("SELECT COUNT(*) FROM research_pyramid_nodes").fetchone()[0]); evidence=int(db.execute("SELECT COUNT(*) FROM research_pyramid_evidence").fetchone()[0]); localized=int(db.execute("SELECT COUNT(*) FROM research_pyramid_evidence WHERE localized=1").fetchone()[0])
    archive_ids=_rp_run_ids(module); built_ids={str(x.get("run_id")) for x in built}; missing=[x for x in archive_ids if x not in built_ids]
    return {"ok":True,"version":_RESEARCH_PYRAMID_VERSION,"archived_research_runs":len(archive_ids),"distilled_runs":len(built),"nodes":nodes,"node_kinds":counts,"evidence_links":evidence,"localized_exact_exits":localized,"exact_exit_ready_percent":round(100.0*localized/evidence,2) if evidence else 100.0,"unbuilt_runs":missing,"coverage_complete":not missing,"rebuild_command":"/research pyramid rebuild all","model_calls":0,"web_calls":0,"authority":{"research_pyramid":"derived navigation and stored interpretation","research_reports":"persisted research reasoning/provenance","original_sources":"authoritative retained evidence"}}


def _rp_row_public(row: dict, evidence_count: int=0, localized_count: int=0) -> dict:
    return {"node_id":row.get("node_id"),"run_id":row.get("run_id"),"sequence_no":row.get("sequence_no"),"node_kind":row.get("node_kind"),"status":row.get("status"),"title":row.get("title"),"signpost":row.get("hint_text"),"confidence":row.get("confidence"),"evidence_count":int(evidence_count),"localized_exact_exit_count":int(localized_count),"full_summary_loaded":False,"source_text_loaded":False}


def _rp_search(module, query: str, limit: int=12, run_id: str="") -> dict:
    _rp_ensure_schema(module); clean=" ".join(str(query or "").split()).strip(); terms=_rp_tokens(clean)
    if not terms: return {"ok":False,"error":"query is required","model_calls":0,"web_calls":0}
    limit=max(1,min(50,int(limit or 12))); import contextlib
    with contextlib.closing(_rp_connect(module)) as db:
        sql="SELECT * FROM research_pyramid_nodes"; params=[]
        if str(run_id or "").strip(): sql+=" WHERE run_id=?"; params.append(str(run_id).strip())
        rows=[dict(r) for r in db.execute(sql,tuple(params)).fetchall()]
        ev={str(r[0]):(int(r[1]),int(r[2])) for r in db.execute("SELECT node_id,COUNT(*),SUM(localized) FROM research_pyramid_evidence GROUP BY node_id").fetchall()}
    matches=[]
    for row in rows:
        lex=str(row.get("search_lexicon") or "||"); hit=[t for t in terms if f"|{t}|" in lex]
        if len(hit)!=len(terms): continue
        ecount,lcount=ev.get(str(row.get("node_id")),(0,0)); item=_rp_row_public(row,ecount,lcount); item.update({"matched_query_tokens":len(hit),"query_token_count":len(terms),"relation":"RESEARCH_EXACT_ALL_TERMS"})
        matches.append(item)
    kind_rank={"claim":0,"run_summary":1,"evidence_unit":2,"unresolved_question":3}
    matches.sort(key=lambda x:(kind_rank.get(str(x.get("node_kind")),9),-int(x.get("localized_exact_exit_count") or 0),int(x.get("sequence_no") or 0),str(x.get("node_id"))))
    return {"ok":True,"operation":"search_research_pyramid","query":clean,"query_terms":terms,"count":min(limit,len(matches)),"results":matches[:limit],"persistent_index_used":True,"search_mode":"strict AND exact-token over hidden title+stored-summary lexicon","semantic_expansion_used":False,"lexicon_exposed":False,"full_summary_loaded":False,"source_text_loaded":False,"model_calls":0,"web_calls":0,"authority":"Navigation only; exact retained source establishes what may be claimed."}


def _rp_get_node(module, node_id: str, include_summary: bool=False) -> dict:
    _rp_ensure_schema(module); import contextlib
    with contextlib.closing(_rp_connect(module)) as db:
        row=db.execute("SELECT * FROM research_pyramid_nodes WHERE node_id=?",(str(node_id),)).fetchone()
        if not row: return {"ok":False,"error":"Research Pyramid node not found.","node_id":node_id,"model_calls":0,"web_calls":0}
        r=dict(row); evidence=[dict(x) for x in db.execute("SELECT * FROM research_pyramid_evidence WHERE node_id=? ORDER BY evidence_index",(str(node_id),)).fetchall()]
    out=_rp_row_public(r,len(evidence),sum(int(x.get("localized") or 0) for x in evidence))
    out["ok"]=True; out["source_refs"]=json.loads(str(r.get("source_refs_json") or "[]")); out["evidence"]=[{"evidence_index":x.get("evidence_index"),"source_ref":x.get("source_ref"),"source_type":x.get("source_type"),"relation":x.get("relation"),"exact_exit_kind":x.get("exact_exit_kind"),"localized":bool(x.get("localized")),"source_sha256":x.get("source_sha256")} for x in evidence]
    if include_summary: out["full_summary"]=r.get("full_summary"); out["full_summary_loaded"]=True
    out.update({"source_text_loaded":False,"read_only":True,"model_calls":0,"web_calls":0,"authority":"Derived research node; evidence links descend to retained sources."})
    return out


def _rp_book_chunk(module, source_ref: str, provenance: dict) -> dict:
    parts=str(source_ref).split(":",2); bid=str(provenance.get("book_id") or (parts[1] if len(parts)>1 else "")); cid=str(provenance.get("chunk_id") or (parts[2] if len(parts)>2 else ""))
