def _kir_execute_internal_action(module, action_id: str, *, actor: str="User") -> dict:
    if str(actor or "").casefold()!="user": return {"ok":False,"error":"Only the user can execute internal summary-repair actions."}
    record=_action_get(module,action_id)
    if not record.get("ok"): return record
    action=record["action"]
    if str(action.get("provider") or "")!=_KIR_INTERNAL_PROVIDER or str(action.get("action_name") or "")!=_KIR_REPAIR_ACTION:
        return {"ok":False,"error":"Not an internal summary-repair action."}
    status=_action_status_for(module,action_id)
    if status!="approved": return {"ok":False,"error":"Action requires explicit user approval.","status":status}
    _action_event(module,action_id,"execution_started",actor,metadata={"internal_controlled_action":True,"source_sha256":(action.get("payload") or {}).get("source_sha256")})
    started=time.perf_counter()
    try:
        test_call=getattr(module,"_KIR_SELF_TEST_MODEL_CALL",None)
        result=_kir_execute_repair(module,action_id,dict(action.get("payload") or {}),model_call=test_call if callable(test_call) else None)
        receipt={"provider":_KIR_INTERNAL_PROVIDER,"action_id":action_id,"action_name":_KIR_REPAIR_ACTION,"status":"success","duration_ms":round((time.perf_counter()-started)*1000,3),"result":result,"result_sha256":_foundation_digest(result),"executed_at":_foundation_now()}
        _action_event(module,action_id,"executed",actor,result=receipt,metadata={"internal_controlled_action":True})
        return {"ok":True,"receipt":receipt}
    except Exception as exc:
        receipt={"provider":_KIR_INTERNAL_PROVIDER,"action_id":action_id,"action_name":_KIR_REPAIR_ACTION,"status":"error","duration_ms":round((time.perf_counter()-started)*1000,3),"error_type":type(exc).__name__,"error":str(exc),"executed_at":_foundation_now()}
        _action_event(module,action_id,"failed",actor,result=receipt,metadata={"internal_controlled_action":True})
        return {"ok":False,"receipt":receipt}


