_HD74_VERSION = "1.0-nondestructive-deep-overlay-ranked-lexical-fallback"
_HD74_SOURCE_EXCERPT_CHARS = 6000
_HD74_SOURCE_HEAD_CHARS = 2400
_HD74_SOURCE_MIDDLE_CHARS = 1800
_HD74_SOURCE_TAIL_CHARS = 1800
_HD74_MAX_LOCALIZATION_TERMS = 6


def _hd74_lexicon_terms(value: object) -> set[str]:
    text=str(value or "")
    return {part for part in text.split("|") if part}


def _hd74_exact_source_excerpt(module, book_id: str, record: dict) -> dict:
    """Bounded deterministic source context for deep-signpost generation only.

    Selection is mechanical start/middle/end sampling when the exact stored span is
    larger than the cap. No excerpt is persisted in the deep-signpost table.
    """
    try:
        rows=_sp_source_rows_for_span(module,str(book_id or ""),record)
    except Exception as exc:
        return {"text":"","available":False,"truncated":False,"characters":0,"reason":str(exc)[:240]}
    if not rows:
        return {"text":"","available":False,"truncated":False,"characters":0,"reason":"exact source span unavailable"}
    start_ord=_shn_int_or_none(record.get("start_ordinal")); end_ord=_shn_int_or_none(record.get("end_ordinal"))
    start_char=_shn_int_or_none(record.get("start_char")); end_char=_shn_int_or_none(record.get("end_char"))
    parts=[]
    for row in rows:
        ordinal=int(row.get("ordinal") or 0); text=str(row.get("source_text") or "")
        left=max(0,min(len(text),int(start_char or 0))) if start_ord is not None and ordinal==start_ord else 0
        right=max(left,min(len(text),int(end_char if end_char is not None else len(text)))) if end_ord is not None and ordinal==end_ord else len(text)
        bounded=text[left:right]
        if bounded: parts.append(f"[chunk {ordinal}] {bounded}")
    full="\n".join(parts)
    if len(full)<=_HD74_SOURCE_EXCERPT_CHARS:
        return {"text":full,"available":bool(full),"truncated":False,"characters":len(full),"original_characters":len(full),"sampling":"full_exact_stored_span"}
    middle=max(0,(len(full)//2)-(_HD74_SOURCE_MIDDLE_CHARS//2))
    sampled=(full[:_HD74_SOURCE_HEAD_CHARS]+"\n[... mechanical middle sample ...]\n"+
             full[middle:middle+_HD74_SOURCE_MIDDLE_CHARS]+"\n[... mechanical tail sample ...]\n"+
             full[-_HD74_SOURCE_TAIL_CHARS:])
    return {"text":sampled[:_HD74_SOURCE_EXCERPT_CHARS],"available":True,"truncated":True,"characters":min(len(sampled),_HD74_SOURCE_EXCERPT_CHARS),"original_characters":len(full),"sampling":"deterministic_start_middle_end"}


