def _hd74_match_rows(module, book_id: str, version_id: str, include_norm: str, terms: list[str]) -> tuple[list[dict],dict[str,float]]:
    import math
    allowed={"semantic_unit"} if include_norm=="semantic_units" else {"structural_resume"} if include_norm=="structural_resumes" else {"semantic_unit","structural_resume"}
    rows=[dict(r) for r in _sp_rows_for_version(str(version_id or "")) if str(r.get("node_type") or "") in allowed]
