# identity while making completeness part of the schema contract and retrying only
# unresolved nodes. Python repairs structure only; it never writes semantic content.

_HD75_VERSION = "1.1-complete-batch-contract-targeted-repair"
_HD75_SCHEMA_NAME = "neatmemory_deep_signpost_complete_batch_v2"
_HD75_REPAIR_BATCH = 3
_HD75_FINAL_SINGLETON_RETRY = True



# Replace .74's model call with the same source-grounded packet plus an exact-count /
# allowed-ID schema. The model still authors every semantic field.



def _hd75_complete_generation(digest_module, backend, *, book: dict, batch: list[tuple[dict,dict]], call_batch=None) -> tuple[list[dict],list[dict],dict,int]:
    """Get one valid generated record for every target node without semantic repair.

    Initial accepted nodes are retained in memory. Only unresolved node IDs are sent again,
    first in tiny groups and finally as singletons. Nothing is written here; the caller's
    existing atomic commit remains the sole persistence point.
    """
    call_batch=call_batch or _hd_model_batch
    by_id={str(row.get("node_id") or ""):(row,inp) for row,inp in batch}
    order=list(by_id)
    accepted={}
    warnings=[]
    attempts=[]
    calls=0

    def run(ids: list[str], phase: str) -> None:
        nonlocal calls
        subset=[by_id[nid][1] for nid in ids]
        allowed={nid:by_id[nid][1] for nid in ids}
        raw,c=call_batch(digest_module,backend,book=book,inputs=subset)
        calls+=int(c or 0)
        good,bad=_hd_normalize_output(raw,allowed)
        before=set(accepted)
        for item in good:
            nid=str(item.get("node_id") or "")
            if nid in allowed: accepted[nid]=item
        warnings.extend(dict(x,phase=phase) for x in bad if isinstance(x,dict) and str(x.get("reason") or "")!="model_omitted_node")
        attempts.append({"phase":phase,"requested":len(ids),"accepted_new":len(set(accepted)-before),"remaining":sum(1 for nid in ids if nid not in accepted)})

    run(order,"initial")
    initial_accepted=set(accepted)
    remaining=[nid for nid in order if nid not in accepted]
    if remaining:
        groups=[remaining[i:i+_HD75_REPAIR_BATCH] for i in range(0,len(remaining),_HD75_REPAIR_BATCH)]
        for index,ids in enumerate(groups,1): run(ids,f"targeted_retry_{index}")
    remaining=[nid for nid in order if nid not in accepted]
    if remaining and _HD75_FINAL_SINGLETON_RETRY:
        for index,nid in enumerate(list(remaining),1): run([nid],f"singleton_retry_{index}")
    unresolved=[nid for nid in order if nid not in accepted]
    rejected=[{"node_id":nid,"reason":"model_invalid_or_omitted_after_targeted_retry"} for nid in unresolved]
    generated=[accepted[nid] for nid in order if nid in accepted]
    repair_used=len(attempts)>1
    diag={
        "repair_used":repair_used,
        "initial_requested":len(order),
        "initial_accepted":len(initial_accepted),
        "recovered_nodes":len(set(accepted)-initial_accepted),
        "unresolved_nodes":len(unresolved),
        "repair_model_calls":max(0,calls-1),
        "structural_warning_count":len(warnings),
        "attempts":attempts if repair_used else [],
    }
    return generated,rejected,diag,calls


# Replace the .73/.74 builder with bounded structural repair while preserving its
# provider resolution and all-or-nothing transaction boundary.
def _hd_build_deep(module, reference: str="all", *, force: bool=False, backend=None, digest_module=None, provider: str|None=None, gpt_alias: str|None=None) -> dict:
    _hd_ensure_schema(); versions=_sp_active_versions(reference)
    if not versions: return {"ok":False,"error":"No matching active digested book version exists.","reference":reference,"deep":True,"model_calls":0}
    if digest_module is None: digest_module=_load_digest_for_memory(module)
    provider_trace={}; alias=None
    try:
        if backend is None: backend,provider_choice,alias,provider_trace=_hd_resolve_backend(module,digest_module,provider=provider,gpt_alias=gpt_alias)
        else: provider_choice="local" if str(getattr(backend,"provider","") or "").casefold()=="local" else "online"
    except Exception as exc:
        return {"ok":False,"operation":"rebuild_deep_signposts" if force else "build_deep_signposts","reference":reference,"deep":True,"forced":bool(force),"error_type":type(exc).__name__,"error":str(exc),"existing_signposts_preserved":True,"model_calls":0,"python_semantic_judgment":False}
    results=[]; total_calls=0; staged=[]
    try:
        for version in versions:
            rows=_sp_rows_for_version(str(version.get("version_id") or "")); targets=[]; skipped=0
            for row in rows:
                if _sp_get(str(row.get("version_id") or ""),str(row.get("node_type") or ""),str(row.get("node_id") or "")) is None:
                    _sp_upsert(module,str(version.get("book_id") or ""),row)
                inp=_hd_input(module,row); existing=_hd_current(str(row.get("version_id") or ""),str(row.get("node_type") or ""),str(row.get("node_id") or ""))
                is_current=bool(existing and str(existing.get("build_version") or "")==_HD_VERSION and str(existing.get("input_sha256") or "")==inp["input_sha256"])
                if force or not is_current: targets.append((row,inp))
                else: skipped+=1
            rejected=[]; calls=0; repair_events=[]; book={"book_id":version.get("book_id"),"title":version.get("title")}
            for start in range(0,len(targets),_HD_MAX_BATCH):
                batch=targets[start:start+_HD_MAX_BATCH]
                generated,bad,diag,c=_hd75_complete_generation(digest_module,backend,book=book,batch=batch)
                calls+=c; total_calls+=c; rejected.extend(bad)
                if diag.get("repair_used"): repair_events.append({"batch_start":start,**diag})
                by_id={str(row.get("node_id") or ""):(row,inp) for row,inp in batch}
                for item in generated:
                    row,inp=by_id[item["node_id"]]; staged.append({"version":version,"row":row,"source_input":inp,"generated":item})
            results.append({
                "book_id":version.get("book_id"),"version_id":version.get("version_id"),"nodes":len(rows),"targeted":len(targets),
                "deep_skipped_current":skipped,"deep_rejected":rejected,"model_calls":calls,
                "structural_repair":{"used":bool(repair_events),"batches_repaired":len(repair_events),"recovered_nodes":sum(int(x.get("recovered_nodes") or 0) for x in repair_events),"repair_model_calls":sum(int(x.get("repair_model_calls") or 0) for x in repair_events),"events":repair_events},
            })
        if any(r.get("deep_rejected") for r in results):
            return {"ok":False,"operation":"rebuild_deep_signposts" if force else "build_deep_signposts","reference":reference,"deep":True,"forced":bool(force),"provider":provider_choice,"model":str(getattr(backend,"model_id","") or ""),"provider_resolution":provider_trace,"model_calls":total_calls,"results":results,"existing_signposts_preserved":True,"partial_deep_commit":False,"atomic_commit":True,"error":"Deep-signpost structural repair exhausted with unresolved target nodes; nothing was committed.","python_semantic_judgment":False}
        committed=_hd_commit_staged(module,staged,backend)
    except Exception as exc:
        return {"ok":False,"operation":"rebuild_deep_signposts" if force else "build_deep_signposts","reference":reference,"deep":True,"forced":bool(force),"provider":provider_choice,"model":str(getattr(backend,"model_id","") or ""),"model_alias":alias,"provider_resolution":provider_trace,"model_calls":total_calls,"error_type":type(exc).__name__,"error":str(exc),"retryable_transport_error":_hd_is_transport_error(exc),"existing_signposts_preserved":True,"partial_deep_commit":False,"atomic_commit":True,"python_semantic_judgment":False}
    final=[]
    for r,version in zip(results,versions):
        row=dict(r); row["deep_built"]=int(row.get("targeted") or 0); row["deep_coverage"]=_hd_deep_coverage(module,version); final.append(row)
    return {"ok":all(not r.get("deep_rejected") and (r.get("deep_coverage") or {}).get("complete") for r in final),"operation":"rebuild_deep_signposts" if force else "build_deep_signposts","reference":reference,"deep":True,"forced":bool(force),"provider":provider_choice,"model":str(getattr(backend,"model_id","") or ""),"model_alias":alias,"provider_resolution":provider_trace,"books":len(final),"deep_built":committed,"deep_skipped_current":sum(int(r.get("deep_skipped_current") or 0) for r in final),"model_calls":total_calls,"results":final,"atomic_commit":True,"existing_signposts_preserved_on_failure":True,"complete_batch_contract":True,"targeted_structural_retry":True,"authority":"Model-assisted derived navigation only; exact original chunks remain authoritative.","python_semantic_judgment":False,"source_text_stored_in_deep_signposts":False}


_HD75_BASE_FUSION_SELF_TEST=_deep_signpost_retrieval_fusion_self_test

def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    base=dict(_HD75_BASE_FUSION_SELF_TEST(module)); checks=dict(base.get("checks") or {}); details=dict(base.get("details") or {})
    sample=[{"node_id":"N1"},{"node_id":"N2"},{"node_id":"N3"}]
    schema=_hd75_schema(sample); arr=((schema.get("properties") or {}).get("signposts") or {})
    enum=((((arr.get("items") or {}).get("properties") or {}).get("node_id") or {}).get("enum") or [])
    checks["schema_requires_exact_batch_cardinality"]=arr.get("minItems")==3 and arr.get("maxItems")==3 and enum==["N1","N2","N3"]
    calls=[]
    def fake_call(digest_module,backend,*,book,inputs):
        ids=[str(x.get("node_id") or "") for x in inputs]; calls.append(ids)
        if len(calls)==1: ids=ids[:-1]
        return {"signposts":[{"node_id":nid,"hint":"hint "+nid,"navigation_summary":"navigation "+nid,"keywords":[nid],"likely_questions":["find "+nid]} for nid in ids]},1
    fake_batch=[({"node_id":"N1"},{"node_id":"N1","title":"one"}),({"node_id":"N2"},{"node_id":"N2","title":"two"}),({"node_id":"N3"},{"node_id":"N3","title":"three"})]
    generated,rejected,diag,model_calls=_hd75_complete_generation(None,None,book={"book_id":"BK-T"},batch=fake_batch,call_batch=fake_call)
    checks["omitted_node_is_retried_without_regenerating_accepted_nodes"]=not rejected and [x.get("node_id") for x in generated]==["N1","N2","N3"] and calls==[["N1","N2","N3"],["N3"]]
    checks["targeted_repair_is_structural_only"]=diag.get("repair_used") is True and diag.get("recovered_nodes")==1 and diag.get("repair_model_calls")==1 and model_calls==2
    details["complete_batch_repair"]={"calls":calls,"diag":diag,"rejected":rejected}
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["version"]=_HD75_VERSION
    return base


_HD75_BASE_INSTALL_FUSION=_install_deep_signpost_retrieval_fusion

def _install_deep_signpost_retrieval_fusion(module) -> None:
    _HD75_BASE_INSTALL_FUSION(module)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_HD75_VERSION


# .76 richness continuation inside deep-signpost-retrieval-fusion rev=3.
# Rich signposts are stored as append-only SQL revisions with a tiny current head.
# The full navigation card is not injected by normal search. Search consumes its
# bounded lexical index and shows only a compact clue + revision pointer; Assistant may
# explicitly open the rich card when more navigation detail is useful. Exact source
# and summary content are referenced by pointer/hash rather than duplicated here.
# Proper nouns/names are first-class retrieval keywords. Python preserves model-authored
# wording and validates mechanics only; it never rewrites semantic signpost content.

_HD76_VERSION = "1.2-rich-sql-revisions-progressive-reveal"
_HD76_SCHEMA_NAME = "neatmemory_rich_signpost_v1"
_HD76_REVISIONS_TABLE = "knowledge_rich_signpost_revisions"
_HD76_HEADS_TABLE = "knowledge_rich_signpost_heads"
_HD76_MAX_KEYWORDS = 20
_HD76_MAX_RELATIONS = 8
_HD76_MAX_LOCAL_ANCHORS = 8
_HD76_MAX_EXPANDED_NAV_CHARS = 2200
_HD76_MAX_RELATION_CHARS = 260
_HD76_MAX_ANCHOR_CHARS = 260
_HD76_HISTORY_LIMIT = 5

_HD76_BASE_HD_ENSURE_SCHEMA = _hd_ensure_schema

def _hd_ensure_schema() -> None:
    if _nm_bootstrap_schema_skip("rich-signpost-revisions-v76"):
        return
    _HD76_BASE_HD_ENSURE_SCHEMA()
    with _sk_connect() as db:
        db.executescript(f"""
        CREATE TABLE IF NOT EXISTS {_HD76_REVISIONS_TABLE}(
            rich_revision_id TEXT PRIMARY KEY,
            deep_signpost_id TEXT NOT NULL,
            previous_revision_id TEXT,
            previous_revision_sha256 TEXT,
            version_id TEXT NOT NULL,
            node_type TEXT NOT NULL,
            node_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            input_sha256 TEXT NOT NULL,
            tiny_hint TEXT NOT NULL,
            navigation_summary TEXT NOT NULL,
            expanded_navigation TEXT NOT NULL,
            keywords_json TEXT NOT NULL,
            relations_json TEXT NOT NULL,
            likely_questions_json TEXT NOT NULL,
            local_anchors_json TEXT NOT NULL,
            semantic_payload_sha256 TEXT NOT NULL,
            search_lexicon_sha256 TEXT NOT NULL,
            exact_source_pointer_json TEXT NOT NULL,
            exact_source_pointer_sha256 TEXT NOT NULL,
            summary_pointer_json TEXT NOT NULL,
            summary_pointer_sha256 TEXT NOT NULL,
            base_signpost_pointer_json TEXT NOT NULL,
            base_signpost_pointer_sha256 TEXT NOT NULL,
            previous_deep_pointer_json TEXT NOT NULL,
            previous_deep_pointer_sha256 TEXT NOT NULL,
            source_sha256 TEXT,
            provider TEXT NOT NULL,
            model TEXT NOT NULL,
            build_version TEXT NOT NULL,
            built_at TEXT NOT NULL,
            record_sha256 TEXT NOT NULL,
            python_semantic_judgment INTEGER NOT NULL DEFAULT 0,
            source_text_stored INTEGER NOT NULL DEFAULT 0,
            summary_text_stored INTEGER NOT NULL DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS idx_rich_signpost_node ON {_HD76_REVISIONS_TABLE}(version_id,node_type,node_id,built_at);
        CREATE INDEX IF NOT EXISTS idx_rich_signpost_book ON {_HD76_REVISIONS_TABLE}(book_id,built_at);
        CREATE TABLE IF NOT EXISTS {_HD76_HEADS_TABLE}(
            version_id TEXT NOT NULL,
            node_type TEXT NOT NULL,
            node_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            current_revision_id TEXT NOT NULL,
            previous_revision_id TEXT,
            current_record_sha256 TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY(version_id,node_type,node_id)
        );
        CREATE INDEX IF NOT EXISTS idx_rich_signpost_head_book ON {_HD76_HEADS_TABLE}(book_id,node_type,node_id);
        """)
    _nm_bootstrap_schema_mark("rich-signpost-revisions-v76")


def _hd76_clean_list(values, *, max_items: int, max_chars: int) -> list[str]:
    out=[]; seen=set()
    for value in list(values or [])[:max_items]:
        clean=_hd_clean(value,max_chars)
        key=clean.casefold()
        if clean and key not in seen:
            seen.add(key); out.append(clean)
    return out


def _hd76_schema(inputs: list[dict]) -> dict:
    node_ids=[str(x.get("node_id") or "") for x in inputs]
    if not node_ids or any(not x for x in node_ids) or len(set(node_ids))!=len(node_ids):
        raise ValueError("Rich signpost batch requires unique non-empty node IDs.")
    return {
        "type":"object","additionalProperties":False,
        "properties":{"signposts":{"type":"array","minItems":len(node_ids),"maxItems":len(node_ids),"items":{
            "type":"object","additionalProperties":False,
            "properties":{
                "node_id":{"type":"string","enum":node_ids},
                "hint":{"type":"string"},
                "navigation_summary":{"type":"string"},
                "expanded_navigation":{"type":"string"},
                "keywords":{"type":"array","maxItems":_HD76_MAX_KEYWORDS,"items":{"type":"string"}},
                "relations":{"type":"array","maxItems":_HD76_MAX_RELATIONS,"items":{"type":"string"}},
                "likely_questions":{"type":"array","maxItems":_HD_MAX_QUESTIONS,"items":{"type":"string"}},
                "local_anchors":{"type":"array","maxItems":_HD76_MAX_LOCAL_ANCHORS,"items":{"type":"string"}},
            },
            "required":["node_id","hint","navigation_summary","expanded_navigation","keywords","relations","likely_questions","local_anchors"]
        }}},"required":["signposts"]
    }

# Keep .75's structural completeness contract, but expand the authored navigation card.
def _hd75_schema(inputs: list[dict]) -> dict:
    return _hd76_schema(inputs)


def _hd_model_batch(digest_module, backend, *, book: dict, inputs: list[dict]) -> tuple[dict,int]:
    module=globals().get("_SP_RUNTIME_MODULE") or _load_memory()
    nodes=[]
    for item in inputs:
        node={k:v for k,v in item.items() if k not in {"input_sha256","source_sha256"}}
        source=_hd74_exact_source_excerpt(module,str(book.get("book_id") or ""),item)
        node["exact_source_excerpt"]=str(source.get("text") or "")
        node["exact_source_excerpt_available"]=bool(source.get("available"))
        node["exact_source_excerpt_truncated"]=bool(source.get("truncated"))
        node["exact_source_excerpt_sampling"]=str(source.get("sampling") or "none")
        nodes.append(node)
    node_ids=[str(x.get("node_id") or "") for x in inputs]
    packet={"book":{"book_id":str(book.get("book_id") or ""),"title":_hd_clean(book.get("title"),500),"authors":list(book.get("authors") or [])[:8]},"nodes":nodes}
    system=(
        "You are writing RICH NAVIGATION SIGNPOSTS for NeatMemory, not summaries and not source evidence. "
        f"Return exactly {len(node_ids)} entries: one and only one for every supplied node_id. Do not omit difficult nodes; describe them conservatively. "
        "Your job is to make each exact source unit easy for a future language model to FIND from many plausible questions. "
        "Use the title/higher-level summary plus the bounded exact-source excerpt. Preserve distinctive wording and retrieval anchors instead of beautifying them away. "
        "PROPER NOUNS AND NAMES ARE FIRST-CLASS KEYWORDS: preserve exact people, places, battles, organizations, named methods, doctrines, characters, technical terms, titles, and other names when they are useful retrieval anchors. "
        "For keywords, aim for roughly 12-20 distinctive words or short phrases when the supplied material supports that many; fewer is better than filler. Names may appear directly in keywords. "
        "hint is the tiny default road sign (<=160 characters). navigation_summary is a compact explanation of what is findable here (<=900 characters). "
        "expanded_navigation is the richer on-demand map: important ideas, distinctions, context, and how this node differs from nearby/related material (<=2200 characters). "
        "relations are short relationship/contrast statements useful for retrieval (for example A -> B, X versus Y); do not invent causal claims. "
        "likely_questions are varied ways a future model/user might look for this material. local_anchors identify distinctive subtopics/paragraph-level cues inside the supplied node without quoting source text. "
        "The exact-source excerpt may be mechanically sampled/truncated, so never claim it is complete. Do not invent source IDs, quotations, page/chapter numbers, people, events, or claims not supported by supplied material. JSON only."
    )
    result=_sk_call_json(digest_module,backend,system=system,user=json.dumps(packet,ensure_ascii=False),
                         max_tokens=max(3600,min(15000,2200+len(inputs)*1200)),
                         schema=_hd76_schema(inputs),schema_name=f"{_HD76_SCHEMA_NAME}_{len(inputs)}",deep=False)
    return result,1


_HD76_BASE_NORMALIZE_OUTPUT=_hd_normalize_output

def _hd_normalize_output(raw: dict, allowed: dict[str,dict]) -> tuple[list[dict],list[dict]]:
    good=[]; rejected=[]; seen=set()
    for item in list((raw or {}).get("signposts") or []):
        if not isinstance(item,dict):
            rejected.append({"reason":"not_object"}); continue
        node_id=str(item.get("node_id") or "")
        if node_id not in allowed or node_id in seen:
            rejected.append({"node_id":node_id,"reason":"unknown_or_duplicate_node_id"}); continue
        seen.add(node_id)
        hint=_shn_compact_hint(_hd_clean(item.get("hint"),600),_HD_MAX_HINT_CHARS)
        nav=_hd_clean(item.get("navigation_summary"),_HD_MAX_NAV_CHARS)
        expanded=_hd_clean(item.get("expanded_navigation"),_HD76_MAX_EXPANDED_NAV_CHARS)
        keywords=_hd76_clean_list(item.get("keywords"),max_items=_HD76_MAX_KEYWORDS,max_chars=_HD_MAX_TERM_CHARS)
        relations=_hd76_clean_list(item.get("relations"),max_items=_HD76_MAX_RELATIONS,max_chars=_HD76_MAX_RELATION_CHARS)
        questions=_hd76_clean_list(item.get("likely_questions"),max_items=_HD_MAX_QUESTIONS,max_chars=220)
        anchors=_hd76_clean_list(item.get("local_anchors"),max_items=_HD76_MAX_LOCAL_ANCHORS,max_chars=_HD76_MAX_ANCHOR_CHARS)
        if not hint:
            rejected.append({"node_id":node_id,"reason":"empty_hint"}); continue
        # Compatibility with older/self-test producers: absent rich fields become empty;
        # the live .76 model schema requires them, but Python never invents their semantics.
        source=allowed[node_id]
        lexicon=_sp_lexicon(source.get("title")," ".join([hint,nav,expanded,*keywords,*relations,*questions,*anchors]))
        good.append({"node_id":node_id,"hint":hint,"navigation_summary":nav,"expanded_navigation":expanded,
                     "keywords":keywords,"relations":relations,"likely_questions":questions,"local_anchors":anchors,"search_lexicon":lexicon})
    missing=[nid for nid in allowed if nid not in seen]
    rejected.extend({"node_id":nid,"reason":"model_omitted_node"} for nid in missing)
    return good,rejected


def _hd76_json(value, fallback):
    try:
        parsed=json.loads(str(value or ""))
        return parsed
    except Exception:
        return fallback


def _hd76_source_pointer(version: dict, row: dict, source_input: dict) -> dict:
    return {
        "book_id":str(version.get("book_id") or row.get("book_id") or ""),
        "version_id":str(row.get("version_id") or ""),
        "node_type":str(row.get("node_type") or ""),
        "node_id":str(row.get("node_id") or ""),
        "start":{"chunk_id":row.get("start_chunk_id"),"ordinal":row.get("start_ordinal"),"char":row.get("start_char")},
        "end":{"chunk_id":row.get("end_chunk_id"),"ordinal":row.get("end_ordinal"),"char":row.get("end_char")},
        "source_sha256":str(row.get("source_sha256") or source_input.get("source_sha256") or ""),
        "authority":"exact_original_source_range",
    }


def _hd76_summary_pointer(row: dict, source_input: dict, base: dict|None) -> dict:
    nt=str(row.get("node_type") or ""); nid=str(row.get("node_id") or "")
    return {
        "detail_ref":str((base or {}).get("detail_ref") or (("semantic:" if nt=="semantic_unit" else "structure:")+nid)),
        "node_type":nt,"node_id":nid,
        "summary_origin":str(source_input.get("summary_origin") or ""),
        "summary_revision_id":source_input.get("summary_revision_id"),
        "summary_sha256":str(source_input.get("summary_sha256") or ""),
        "read_tool":"read_book_semantic_unit" if nt=="semantic_unit" else "read_book_structural_resume",
        "read_arguments":{"unit_id":nid} if nt=="semantic_unit" else {"structural_resume_id":nid},
    }


def _hd76_base_pointer(base: dict|None) -> dict:
    base=base or {}
    return {k:base.get(k) for k in ("signpost_id","detail_ref","derivation_version","hint_sha256","summary_sha256","search_lexicon_sha256")}


def _hd76_deep_pointer(deep: dict|None) -> dict:
    deep=deep or {}
    return {k:deep.get(k) for k in ("deep_signpost_id","build_version","built_at","input_sha256","search_lexicon_sha256","provider","model")}


def _hd76_rich_head(version_id: str, node_type: str, node_id: str) -> dict|None:
    _hd_ensure_schema()
    with _sk_connect() as db:
        row=db.execute(f"SELECT * FROM {_HD76_HEADS_TABLE} WHERE version_id=? AND node_type=? AND node_id=?",(str(version_id),str(node_type),str(node_id))).fetchone()
    return dict(row) if row else None


def _hd76_rich_revision(revision_id: str) -> dict|None:
    _hd_ensure_schema()
    with _sk_connect() as db:
        row=db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(str(revision_id),)).fetchone()
    return dict(row) if row else None


def _hd76_make_revision(db, *, version: dict, row: dict, source_input: dict, generated: dict, backend, now: str, deep_signpost_id: str, old_deep: dict|None) -> tuple[str,str,str|None]:
    vid=str(row.get("version_id") or ""); nt=str(row.get("node_type") or ""); nid=str(row.get("node_id") or ""); bid=str(version.get("book_id") or "")
    base_row=db.execute("SELECT * FROM knowledge_semantic_signposts WHERE version_id=? AND node_type=? AND node_id=?",(vid,nt,nid)).fetchone()
    base=dict(base_row) if base_row else {}
    head_row=db.execute(f"SELECT * FROM {_HD76_HEADS_TABLE} WHERE version_id=? AND node_type=? AND node_id=?",(vid,nt,nid)).fetchone()
    head=dict(head_row) if head_row else {}
    prev_id=str(head.get("current_revision_id") or "") or None
    prev_sha=str(head.get("current_record_sha256") or "") or None
    source_pointer=_hd76_source_pointer(version,row,source_input)
    summary_pointer=_hd76_summary_pointer(row,source_input,base)
    base_pointer=_hd76_base_pointer(base)
    previous_deep_pointer=_hd76_deep_pointer(old_deep)
    semantic_payload={
        "hint":generated.get("hint") or "","navigation_summary":generated.get("navigation_summary") or "",
        "expanded_navigation":generated.get("expanded_navigation") or "","keywords":list(generated.get("keywords") or []),
        "relations":list(generated.get("relations") or []),"likely_questions":list(generated.get("likely_questions") or []),
        "local_anchors":list(generated.get("local_anchors") or []),
    }
    semantic_sha=_sk_hash(_sk_json(semantic_payload)); lex=str(generated.get("search_lexicon") or "||"); lex_sha=_sk_hash(lex)
    source_json=_sk_json(source_pointer); summary_json=_sk_json(summary_pointer); base_json=_sk_json(base_pointer); old_deep_json=_sk_json(previous_deep_pointer)
    source_ptr_sha=_sk_hash(source_json); summary_ptr_sha=_sk_hash(summary_json); base_ptr_sha=_sk_hash(base_json); old_deep_sha=_sk_hash(old_deep_json)
    provider="lmstudio" if str(getattr(backend,"provider","") or "").casefold()=="local" else "online"; model=str(getattr(backend,"model_id","") or "")
    seed={"version_id":vid,"node_type":nt,"node_id":nid,"previous":prev_id,"semantic":semantic_sha,"source":source_ptr_sha,"summary":summary_ptr_sha,"built_at":now}
    rid=_sk_id("RSR",seed,24)
    record_for_hash={"rich_revision_id":rid,"deep_signpost_id":deep_signpost_id,"previous_revision_id":prev_id,"previous_revision_sha256":prev_sha,
                     "version_id":vid,"node_type":nt,"node_id":nid,"book_id":bid,"input_sha256":source_input["input_sha256"],
                     "semantic_payload_sha256":semantic_sha,"search_lexicon_sha256":lex_sha,
                     "exact_source_pointer_sha256":source_ptr_sha,"summary_pointer_sha256":summary_ptr_sha,
                     "base_signpost_pointer_sha256":base_ptr_sha,"previous_deep_pointer_sha256":old_deep_sha,
                     "source_sha256":str(row.get("source_sha256") or source_input.get("source_sha256") or ""),
                     "provider":provider,"model":model,"build_version":_HD_VERSION,"built_at":now}
    record_sha=_sk_hash(_sk_json(record_for_hash))
    db.execute(f"""INSERT INTO {_HD76_REVISIONS_TABLE}(
        rich_revision_id,deep_signpost_id,previous_revision_id,previous_revision_sha256,version_id,node_type,node_id,book_id,input_sha256,
        tiny_hint,navigation_summary,expanded_navigation,keywords_json,relations_json,likely_questions_json,local_anchors_json,
        semantic_payload_sha256,search_lexicon_sha256,exact_source_pointer_json,exact_source_pointer_sha256,
        summary_pointer_json,summary_pointer_sha256,base_signpost_pointer_json,base_signpost_pointer_sha256,
        previous_deep_pointer_json,previous_deep_pointer_sha256,source_sha256,provider,model,build_version,built_at,record_sha256,
        python_semantic_judgment,source_text_stored,summary_text_stored)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,0,0)""",
        (rid,deep_signpost_id,prev_id,prev_sha,vid,nt,nid,bid,source_input["input_sha256"],
         semantic_payload["hint"],semantic_payload["navigation_summary"],semantic_payload["expanded_navigation"],
         _sk_json(semantic_payload["keywords"]),_sk_json(semantic_payload["relations"]),_sk_json(semantic_payload["likely_questions"]),_sk_json(semantic_payload["local_anchors"]),
         semantic_sha,lex_sha,source_json,source_ptr_sha,summary_json,summary_ptr_sha,base_json,base_ptr_sha,old_deep_json,old_deep_sha,
         str(row.get("source_sha256") or source_input.get("source_sha256") or ""),provider,model,_HD_VERSION,now,record_sha))
    db.execute(f"""INSERT INTO {_HD76_HEADS_TABLE}(version_id,node_type,node_id,book_id,current_revision_id,previous_revision_id,current_record_sha256,updated_at)
        VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(version_id,node_type,node_id) DO UPDATE SET
        book_id=excluded.book_id,previous_revision_id={_HD76_HEADS_TABLE}.current_revision_id,current_revision_id=excluded.current_revision_id,
        current_record_sha256=excluded.current_record_sha256,updated_at=excluded.updated_at""",
        (vid,nt,nid,bid,rid,prev_id,record_sha,now))
    return rid,record_sha,prev_id


# Compatibility current row + append-only rich revision/head update remain one transaction.
def _hd_commit_staged(module, staged: list[dict], backend) -> int:
    if not staged: return 0
    _hd_ensure_schema(); now=_sk_now(); provider="lmstudio" if str(getattr(backend,"provider","") or "").casefold()=="local" else "online"; model=str(getattr(backend,"model_id","") or "")
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            for item in staged:
                version=item["version"]; row=item["row"]; source_input=item["source_input"]; generated=item["generated"]
                vid=str(row.get("version_id") or ""); nt=str(row.get("node_type") or ""); nid=str(row.get("node_id") or "")
                old_row=db.execute(f"SELECT * FROM {_HD_TABLE} WHERE version_id=? AND node_type=? AND node_id=?",(vid,nt,nid)).fetchone(); old_deep=dict(old_row) if old_row else None
                did=_sk_id("DSG",{"version":vid,"node_type":nt,"node_id":nid,"input":source_input["input_sha256"]},20); lex=str(generated.get("search_lexicon") or "||")
                db.execute(f"""INSERT INTO {_HD_TABLE}(deep_signpost_id,version_id,node_type,node_id,book_id,input_sha256,hint_text,navigation_summary,keywords_json,likely_questions_json,search_lexicon,search_lexicon_sha256,provider,model,build_version,built_at,python_semantic_judgment,source_text_stored)
                            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,0)
                            ON CONFLICT(version_id,node_type,node_id) DO UPDATE SET deep_signpost_id=excluded.deep_signpost_id,book_id=excluded.book_id,input_sha256=excluded.input_sha256,hint_text=excluded.hint_text,navigation_summary=excluded.navigation_summary,keywords_json=excluded.keywords_json,likely_questions_json=excluded.likely_questions_json,search_lexicon=excluded.search_lexicon,search_lexicon_sha256=excluded.search_lexicon_sha256,provider=excluded.provider,model=excluded.model,build_version=excluded.build_version,built_at=excluded.built_at,python_semantic_judgment=0,source_text_stored=0""",
                           (did,vid,nt,nid,str(version.get("book_id") or ""),source_input["input_sha256"],generated["hint"],generated["navigation_summary"],_sk_json(generated["keywords"]),_sk_json(generated["likely_questions"]),lex,_sk_hash(lex),provider,model,_HD_VERSION,now))
                _hd76_make_revision(db,version=version,row=row,source_input=source_input,generated=generated,backend=backend,now=now,deep_signpost_id=did,old_deep=old_deep)
            db.commit()
        except Exception:
            db.rollback(); raise
    return len(staged)


def _hd76_decode_revision(row: dict, *, include_pointers: bool=True) -> dict:
    out={
        "rich_revision_id":row.get("rich_revision_id"),"deep_signpost_id":row.get("deep_signpost_id"),
        "previous_revision_id":row.get("previous_revision_id"),"previous_revision_sha256":row.get("previous_revision_sha256"),
        "book_id":row.get("book_id"),"version_id":row.get("version_id"),"node_type":row.get("node_type"),"node_id":row.get("node_id"),
        "tiny_hint":row.get("tiny_hint"),"navigation_summary":row.get("navigation_summary"),"expanded_navigation":row.get("expanded_navigation"),
        "keywords":_hd76_json(row.get("keywords_json"),[]),"relations":_hd76_json(row.get("relations_json"),[]),
        "likely_questions":_hd76_json(row.get("likely_questions_json"),[]),"local_anchors":_hd76_json(row.get("local_anchors_json"),[]),
        "hashes":{"semantic_payload_sha256":row.get("semantic_payload_sha256"),"search_lexicon_sha256":row.get("search_lexicon_sha256"),"record_sha256":row.get("record_sha256")},
        "provenance":{"provider":row.get("provider"),"model":row.get("model"),"build_version":row.get("build_version"),"built_at":row.get("built_at")},
        "authority":"Rich signpost is derived navigation only; open the exact original source pointer for evidence.",
        "python_semantic_judgment":False,"source_text_stored":False,"summary_text_stored":False,
    }
    if include_pointers:
        out["pointers"]={
            "exact_source":_hd76_json(row.get("exact_source_pointer_json"),{}),
            "summary":_hd76_json(row.get("summary_pointer_json"),{}),
            "base_signpost":_hd76_json(row.get("base_signpost_pointer_json"),{}),
            "previous_deep":_hd76_json(row.get("previous_deep_pointer_json"),{}),
        }
        out["pointer_hashes"]={"exact_source":row.get("exact_source_pointer_sha256"),"summary":row.get("summary_pointer_sha256"),"base_signpost":row.get("base_signpost_pointer_sha256"),"previous_deep":row.get("previous_deep_pointer_sha256")}
    return out


def _hd76_read_rich_signpost(module, node_id: str="", *, rich_revision_id: str="", book_id: str="", include_history: bool=False) -> dict:
    _hd_ensure_schema(); rid=str(rich_revision_id or "").strip(); nid=str(node_id or "").strip(); bid=str(book_id or "").strip()
    with _sk_connect() as db:
        if rid:
            row=db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(rid,)).fetchone()
        elif nid:
            sql=f"""SELECT r.* FROM {_HD76_HEADS_TABLE} h JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=h.current_revision_id WHERE h.node_id=?"""
            params=[nid]
            if bid: sql+=" AND h.book_id=?"; params.append(bid)
            sql+=" ORDER BY h.updated_at DESC LIMIT 1"
            row=db.execute(sql,tuple(params)).fetchone()
        else:
            return {"ok":False,"error":"node_id or rich_revision_id is required.","read_only":True,"model_calls":0,"web_calls":0}
        if not row:
            return {"ok":False,"error":"No matching rich signpost revision exists.","node_id":nid or None,"rich_revision_id":rid or None,"read_only":True,"model_calls":0,"web_calls":0}
        record=dict(row); history=[]
        if include_history:
            cursor=record.get("previous_revision_id"); count=0
            while cursor and count<_HD76_HISTORY_LIMIT:
                prev=db.execute(f"SELECT rich_revision_id,previous_revision_id,record_sha256,built_at,provider,model,build_version FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(cursor,)).fetchone()
                if not prev: break
                item=dict(prev); history.append(item); cursor=item.get("previous_revision_id"); count+=1
    out=_hd76_decode_revision(record,include_pointers=True); out.update({"ok":True,"read_only":True,"model_calls":0,"web_calls":0,"history":history,"history_truncated":bool(include_history and len(history)>=_HD76_HISTORY_LIMIT and history[-1].get("previous_revision_id"))})
    return out


# Normal retrieval reveals only that richer detail exists and the revision identity.
_HD76_BASE_SP_SEARCH_MAP=_sp_search_map

def _sp_search_map(module, book_id: str, *, version_id: str="", query: str="", include: str="all", offset: int=0, limit: int=_SMN_DEFAULT_LIMIT) -> dict|None:
    out=_HD76_BASE_SP_SEARCH_MAP(module,book_id,version_id=version_id,query=query,include=include,offset=offset,limit=limit)
    if not isinstance(out,dict) or not out.get("ok"): return out
    nodes=[]
    for node in list(out.get("nodes") or []):
        item=dict(node); card=dict(item.get("route_card") or {}); vid=str(out.get("version_id") or ""); nt=str(item.get("node_type") or ""); nid=str(item.get("node_id") or "")
        head=_hd76_rich_head(vid,nt,nid) if vid and nt and nid else None
        card["rich_signpost_available"]=bool(head); card["rich_revision_id"]=(head or {}).get("current_revision_id"); card["rich_record_sha256"]=(head or {}).get("current_record_sha256")
        card["rich_detail_tool"]="read_rich_signpost" if head else None
        item["route_card"]=card; nodes.append(item)
    out=dict(out); out["nodes"]=nodes; out["rich_signpost_progressive_reveal"]=True; out["rich_signpost_detail_included_by_default"]=False
    return out


_HD76_BASE_SDL_COMPACT_NODE=_sdl_compact_node

def _sdl_compact_node(node: dict, version: dict, *, provisional: bool=False, candidate: dict|None=None) -> dict:
    out=_HD76_BASE_SDL_COMPACT_NODE(node,version,provisional=provisional,candidate=candidate); card=dict(node.get("route_card") or {})
    out["rich_signpost_available"]=bool(card.get("rich_signpost_available")); out["rich_revision_id"]=card.get("rich_revision_id"); out["rich_detail_tool"]=card.get("rich_detail_tool")
    return out



def _hd76_register_tool(module) -> None:
    schema=_hd76_tool_schema()
    for array_name in ("_ONLINE_BOOK_RESPONSE_TOOLS","_ONLINE_EVIDENCE_RESPONSE_TOOLS"):
        arr=globals().get(array_name)
        if isinstance(arr,list) and not any(isinstance(x,dict) and str(x.get("name") or "")=="read_rich_signpost" for x in arr): arr.append(schema)
    if isinstance(globals().get("_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS"),dict): _ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS["read_rich_signpost"]=1700
    if isinstance(globals().get("_ADAPTIVE_TOOL_GROUPS"),dict):
        group=list(_ADAPTIVE_TOOL_GROUPS.get("books") or ())
        if "read_rich_signpost" not in group: group.append("read_rich_signpost")
        _ADAPTIVE_TOOL_GROUPS["books"]=tuple(group)
    if isinstance(getattr(module,"TOOL_SCHEMAS",None),list):
        local={"type":"function","function":{k:v for k,v in schema.items() if k not in {"type","strict"}}}
        if not any(str((x.get("function") or {}).get("name") or "")=="read_rich_signpost" for x in module.TOOL_SCHEMAS if isinstance(x,dict)): module.TOOL_SCHEMAS.append(local)
    if isinstance(getattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST",None),set): module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("read_rich_signpost")


def _hd76_wrap_dispatchers(module) -> None:
    old_evidence=globals().get("_ora_execute_evidence_tool")
    if callable(old_evidence) and not getattr(old_evidence,"_hd76_wrapped",False):
        def execute_rich(mod,name,arguments):
            args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)=="read_rich_signpost": return _ora_clean_result(mod,_hd76_read_rich_signpost(mod,str(args.get("node_id") or ""),rich_revision_id=str(args.get("rich_revision_id") or ""),book_id=str(args.get("book_id") or ""),include_history=bool(args.get("include_history",False))))
            return old_evidence(mod,name,arguments)
        execute_rich._hd76_wrapped=True; globals()["_ora_execute_evidence_tool"]=execute_rich
    old_execute=getattr(module,"execute_tool",None)
    if callable(old_execute) and not getattr(old_execute,"_hd76_wrapped",False):
        def execute_local(name,arguments,seen,*args,**kwargs):
            tool_args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)=="read_rich_signpost": return _hd76_read_rich_signpost(module,str(tool_args.get("node_id") or ""),rich_revision_id=str(tool_args.get("rich_revision_id") or ""),book_id=str(tool_args.get("book_id") or ""),include_history=bool(tool_args.get("include_history",False)))
            return old_execute(name,arguments,seen,*args,**kwargs)
        execute_local._hd76_wrapped=True; module.execute_tool=execute_local


_HD76_BASE_INSTALL_FUSION=_install_deep_signpost_retrieval_fusion

def _install_deep_signpost_retrieval_fusion(module) -> None:
    _HD76_BASE_INSTALL_FUSION(module)
    _hd_ensure_schema(); _hd76_register_tool(module); _hd76_wrap_dispatchers(module)
    module.read_rich_signpost=lambda node_id="",**kwargs:_hd76_read_rich_signpost(module,node_id,**kwargs)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_HD76_VERSION


_HD76_BASE_FUSION_SELF_TEST=_deep_signpost_retrieval_fusion_self_test

def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    module=module or _load_memory(); base=dict(_HD76_BASE_FUSION_SELF_TEST(module)); checks=dict(base.get("checks") or {}); details=dict(base.get("details") or {})
    schema=_hd76_schema([{"node_id":"N1"}]); props=((((schema.get("properties") or {}).get("signposts") or {}).get("items") or {}).get("properties") or {})
    checks["rich_schema_has_progressive_detail_fields"]={"expanded_navigation","keywords","relations","likely_questions","local_anchors"}.issubset(set(props)) and int(((props.get("keywords") or {}).get("maxItems") or 0))==20
    sample_raw={"signposts":[{"node_id":"N1","hint":"Find Holmes and Moriarty.","navigation_summary":"Named adversaries and deduction.","expanded_navigation":"A richer navigation map.","keywords":["Sherlock Holmes","Professor Moriarty","London","deduction"],"relations":["Holmes versus Moriarty"],"likely_questions":["Where is Moriarty discussed?"],"local_anchors":["paragraph contrasting detective and adversary"]}]}
    normalized,rejected=_hd_normalize_output(sample_raw,{"N1":{"title":"Test"}}); names=(normalized[0].get("keywords") if normalized else [])
    checks["proper_nouns_and_names_survive_keyword_normalization"]=not rejected and "Sherlock Holmes" in names and "Professor Moriarty" in names
    # Isolated SQL revision-chain proof: no live DB is touched.
    old_shared=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV); old_mem=os.getenv("NEAT_MEMORY_DIR")
    try:
        with tempfile.TemporaryDirectory(prefix="neat-rich-signpost-") as folder:
            os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=str(Path(folder)/"shared"); os.environ["NEAT_MEMORY_DIR"]=str(Path(folder)/"personal")
            _sd_ensure_schema(); _hd_ensure_schema()
            version={"book_id":"BK-RICH","title":"Rich Test"}; row={"version_id":"VER-RICH","node_type":"semantic_unit","node_id":"SDU-RICH","book_id":"BK-RICH","title":"Named idea","node_kind":"concept","start_chunk_id":"C1","start_ordinal":1,"start_char":0,"end_chunk_id":"C1","end_ordinal":1,"end_char":100,"source_sha256":"a"*64}
            source_input={"node_id":"SDU-RICH","input_sha256":"b"*64,"source_sha256":"a"*64,"summary_sha256":"c"*64,"summary_origin":"stored_semantic_digest","summary_revision_id":"SUM-1"}
            now1="2026-08-21T00:00:00+00:00"; now2="2026-08-21T00:00:01+00:00"
            backend=type("B",(),{"provider":"online","model_id":"gpt-test"})()
            with _sk_connect() as db:
                # Minimal base signpost pointer target.
                db.execute("""INSERT OR REPLACE INTO knowledge_semantic_signposts(signpost_id,source_id,book_id,version_id,node_type,node_id,sequence_no,node_kind,title,hint_text,hint_sha256,search_lexicon,search_lexicon_sha256,summary_sha256,summary_characters,summary_origin,summary_revision_id,linked_record_count,coverage_status,start_chunk_id,start_ordinal,start_char,end_chunk_id,end_ordinal,end_char,source_sha256,detail_ref,derivation_version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                           ("SGN-RICH","SRC","BK-RICH","VER-RICH","semantic_unit","SDU-RICH",1,"concept","Named idea","base",_sk_hash("base"),"|named|",_sk_hash("|named|"),"c"*64,10,"stored_semantic_digest","SUM-1",0,"canonical","C1",1,0,"C1",1,100,"a"*64,"semantic:SDU-RICH",_DURABLE_SIGNPOST_VERSION,now1,now1))
                db.commit()
            g1={"hint":"Tiny one","navigation_summary":"Nav one","expanded_navigation":"Expanded one","keywords":["Sun Tzu","enemy","self"],"relations":["knowledge -> victory"],"likely_questions":["Where is Sun Tzu's maxim?"],"local_anchors":["enemy/self contrast"],"search_lexicon":"|sun|tzu|enemy|self|victory|"}
            g2={**g1,"hint":"Tiny two","expanded_navigation":"Expanded two","keywords":["Sun Tzu","enemy","self","victory"]}
            with _sk_connect() as db:
                rid1,sha1,prev1=_hd76_make_revision(db,version=version,row=row,source_input=source_input,generated=g1,backend=backend,now=now1,deep_signpost_id="DSG-RICH",old_deep=None); db.commit()
            with _sk_connect() as db:
                rid2,sha2,prev2=_hd76_make_revision(db,version=version,row=row,source_input=source_input,generated=g2,backend=backend,now=now2,deep_signpost_id="DSG-RICH",old_deep={"deep_signpost_id":"DSG-RICH","build_version":"legacy"}); db.commit()
                cnt=int(db.execute(f"SELECT COUNT(*) FROM {_HD76_REVISIONS_TABLE} WHERE node_id='SDU-RICH'").fetchone()[0]); head=dict(db.execute(f"SELECT * FROM {_HD76_HEADS_TABLE} WHERE node_id='SDU-RICH'").fetchone())
                stored=dict(db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(rid2,)).fetchone())
            checks["rich_signposts_are_append_only_revisioned_sql"]=cnt==2 and prev1 is None and prev2==rid1 and head.get("current_revision_id")==rid2 and head.get("previous_revision_id")==rid1
            checks["rich_revision_has_source_summary_base_and_previous_pointers"]=all(stored.get(k) for k in ("exact_source_pointer_sha256","summary_pointer_sha256","base_signpost_pointer_sha256","previous_deep_pointer_sha256"))
            checks["rich_revision_stores_no_source_or_summary_text"]=int(stored.get("source_text_stored") or 0)==0 and int(stored.get("summary_text_stored") or 0)==0 and "source_text" not in stored and "summary_text" not in stored
            read=_hd76_read_rich_signpost(module,"SDU-RICH",book_id="BK-RICH",include_history=True)
            checks["rich_detail_is_explicit_read_with_lineage"]=bool(read.get("ok")) and read.get("rich_revision_id")==rid2 and read.get("previous_revision_id")==rid1 and len(read.get("history") or [])==1 and "Sun Tzu" in (read.get("keywords") or [])
            details["rich_sql_revision_test"]={"first":rid1,"second":rid2,"head":head,"read_keywords":read.get("keywords"),"history":read.get("history")}
    finally:
        if old_shared is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=old_shared
        if old_mem is None: os.environ.pop("NEAT_MEMORY_DIR",None)
        else: os.environ["NEAT_MEMORY_DIR"]=old_mem
    checks["rich_read_tool_schema_is_navigation_only"]="source text" in _hd76_tool_schema()["description"].casefold() and "navigation only" in _hd76_tool_schema()["description"].casefold()
    online_names={str(x.get("name") or "") for x in globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS",[]) if isinstance(x,dict)}
    local_names={str((x.get("function") or {}).get("name") or "") for x in getattr(module,"TOOL_SCHEMAS",[]) if isinstance(x,dict)}
    checks["rich_read_tool_is_exposed_online_and_local"]="read_rich_signpost" in online_names and "read_rich_signpost" in local_names and callable(getattr(module,"read_rich_signpost",None))
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["version"]=_HD76_VERSION
    return base


# .77 cost-effective retrieval continuation inside deep-signpost-retrieval-fusion rev=4.
# The expensive model is now confined to deep signpost AUTHORING. Once a rich signpost
# exists, its model-authored keywords (including proper names and multiword names) are
# projected into a tiny mutable SQL search index. Ordinary search is deterministic
# Python/SQLite token matching + IDF-like weighting; it does not call a model and does
# not reopen source text merely to rank candidates. The rich revision remains the
# append-only provenance object; this keyword table is only a rebuildable projection.
# Plain /signpost build|rebuild refreshes deterministic base signs + this projection
# with zero model calls and preserves valid deep/rich revisions. --deep remains the
# intentional model-assisted authoring/re-authoring operation.

_HD77_VERSION = "1.3-python-sql-keyword-primary-retrieval"
_HD77_KEYWORD_TABLE = "knowledge_rich_signpost_keyword_index"
_HD77_TOKEN_TABLE = "knowledge_rich_signpost_keyword_tokens"
_HD77_MAX_SQL_CANDIDATES = 128
_HD77_REFERENCE_LABEL_TOKENS = {"endnote","endnotes","reference","references","bibliography","index"}

_HD77_BASE_ENSURE_SCHEMA = _hd_ensure_schema

def _hd_ensure_schema() -> None:
    if _nm_bootstrap_schema_skip("rich-signpost-keyword-index-v77"):
        return
    _HD77_BASE_ENSURE_SCHEMA()
    with _sk_connect() as db:
        db.executescript(f"""
        CREATE TABLE IF NOT EXISTS {_HD77_KEYWORD_TABLE}(
            rich_revision_id TEXT NOT NULL,
            keyword_order INTEGER NOT NULL,
            version_id TEXT NOT NULL,
            node_type TEXT NOT NULL,
            node_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            keyword_text TEXT NOT NULL,
            keyword_norm TEXT NOT NULL,
            token_count INTEGER NOT NULL,
            PRIMARY KEY(rich_revision_id,keyword_order)
        );
        CREATE INDEX IF NOT EXISTS idx_rich_kw_version ON {_HD77_KEYWORD_TABLE}(version_id,node_type,node_id);
        CREATE INDEX IF NOT EXISTS idx_rich_kw_book ON {_HD77_KEYWORD_TABLE}(book_id,node_type,node_id);
        CREATE INDEX IF NOT EXISTS idx_rich_kw_norm ON {_HD77_KEYWORD_TABLE}(keyword_norm);
        CREATE TABLE IF NOT EXISTS {_HD77_TOKEN_TABLE}(
            rich_revision_id TEXT NOT NULL,
            keyword_order INTEGER NOT NULL,
            version_id TEXT NOT NULL,
            node_type TEXT NOT NULL,
            node_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            token TEXT NOT NULL,
            PRIMARY KEY(rich_revision_id,keyword_order,token)
        );
        CREATE INDEX IF NOT EXISTS idx_rich_kw_token ON {_HD77_TOKEN_TABLE}(token,version_id);
        CREATE INDEX IF NOT EXISTS idx_rich_kw_token_book ON {_HD77_TOKEN_TABLE}(book_id,token);
        """)
    _nm_bootstrap_schema_mark("rich-signpost-keyword-index-v77")


def _hd77_keyword_norm(value: object) -> str:
    return " ".join(_smn_terms(str(value or "")))


def _hd77_index_revision(db, rich_revision_id: str) -> dict:
    rid=str(rich_revision_id or "").strip()
    row=db.execute(f"SELECT version_id,node_type,node_id,book_id,keywords_json FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(rid,)).fetchone()
    if not row:
        return {"revision":rid,"keywords":0,"tokens":0}
    record=dict(row); keywords=_hd76_json(record.get("keywords_json"),[])
    db.execute(f"DELETE FROM {_HD77_TOKEN_TABLE} WHERE rich_revision_id=?",(rid,))
    db.execute(f"DELETE FROM {_HD77_KEYWORD_TABLE} WHERE rich_revision_id=?",(rid,))
    kw_count=0; tok_count=0
    for order,raw in enumerate(list(keywords or [])[:_HD76_MAX_KEYWORDS]):
        text=_hd_clean(raw,_HD_MAX_TERM_CHARS); norm=_hd77_keyword_norm(text); tokens=_smn_terms(text)
        if not text or not norm or not tokens: continue
        db.execute(f"INSERT INTO {_HD77_KEYWORD_TABLE}(rich_revision_id,keyword_order,version_id,node_type,node_id,book_id,keyword_text,keyword_norm,token_count) VALUES(?,?,?,?,?,?,?,?,?)",
                   (rid,order,str(record.get("version_id") or ""),str(record.get("node_type") or ""),str(record.get("node_id") or ""),str(record.get("book_id") or ""),text,norm,len(tokens)))
        kw_count+=1
        for token in tokens:
            db.execute(f"INSERT OR IGNORE INTO {_HD77_TOKEN_TABLE}(rich_revision_id,keyword_order,version_id,node_type,node_id,book_id,token) VALUES(?,?,?,?,?,?,?)",
                       (rid,order,str(record.get("version_id") or ""),str(record.get("node_type") or ""),str(record.get("node_id") or ""),str(record.get("book_id") or ""),token))
            tok_count+=1
    return {"revision":rid,"keywords":kw_count,"tokens":tok_count}


_HD77_BASE_MAKE_REVISION = _hd76_make_revision

def _hd76_make_revision(db, *, version: dict, row: dict, source_input: dict, generated: dict, backend, now: str, deep_signpost_id: str, old_deep: dict|None) -> tuple[str,str,str|None]:
    rid,record_sha,prev=_HD77_BASE_MAKE_REVISION(db,version=version,row=row,source_input=source_input,generated=generated,backend=backend,now=now,deep_signpost_id=deep_signpost_id,old_deep=old_deep)
    _hd77_index_revision(db,rid)
    return rid,record_sha,prev


def _hd77_reindex_scope(module, reference: str="all") -> dict:
    _hd_ensure_schema(); versions=_sp_active_versions(reference)
    if not versions:
        return {"ok":False,"reference":reference,"rich_heads":0,"keywords_indexed":0,"keyword_tokens_indexed":0,"model_calls":0,"error":"No matching active digested book version exists."}
    rich_heads=0; kw_total=0; tok_total=0
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            for version in versions:
                vid=str(version.get("version_id") or "")
                db.execute(f"DELETE FROM {_HD77_TOKEN_TABLE} WHERE version_id=?",(vid,))
                db.execute(f"DELETE FROM {_HD77_KEYWORD_TABLE} WHERE version_id=?",(vid,))
                heads=db.execute(f"SELECT current_revision_id FROM {_HD76_HEADS_TABLE} WHERE version_id=? ORDER BY node_type,node_id",(vid,)).fetchall()
                for head in heads:
                    diag=_hd77_index_revision(db,str(head[0] or "")); rich_heads+=1; kw_total+=int(diag.get("keywords") or 0); tok_total+=int(diag.get("tokens") or 0)
            db.commit()
        except Exception:
            db.rollback(); raise
    return {"ok":True,"reference":reference,"books":len(versions),"rich_heads":rich_heads,"keywords_indexed":kw_total,"keyword_tokens_indexed":tok_total,"model_calls":0,"python_semantic_judgment":False,"index_role":"rebuildable mechanical projection of model-authored rich-signpost keywords"}


def _hd77_mechanical_source_role(node_kind: object, title: object) -> tuple[str,list[str]]:
    label_terms=set(_smn_terms(" ".join([str(node_kind or ""),str(title or "")])))
    hits=sorted(label_terms & _HD77_REFERENCE_LABEL_TOKENS)
    return ("reference_material" if hits else "body_or_unknown"),hits


def _hd77_keyword_candidates(book_id: str, version_id: str, include_norm: str, query: str) -> dict:
    import math
    terms=_smn_terms(query); qnorm=" ".join(terms)
    if not terms:
        return {"terms":terms,"candidates":[],"indexed_query_terms":[],"unindexed_query_terms":terms,"heads":0}
    allowed={"semantic_unit"} if include_norm=="semantic_units" else {"structural_resume"} if include_norm=="structural_resumes" else {"semantic_unit","structural_resume"}
    placeholders=",".join("?" for _ in terms); type_ph=",".join("?" for _ in allowed)
    params=[str(version_id or ""),*sorted(allowed),*terms]
    with _sk_connect() as db:
        head_count=int(db.execute(f"SELECT COUNT(*) FROM {_HD76_HEADS_TABLE} WHERE version_id=? AND node_type IN ({type_ph})",(str(version_id or ""),*sorted(allowed))).fetchone()[0])
        rows=[dict(r) for r in db.execute(f"""
            SELECT t.rich_revision_id,t.node_type,t.node_id,t.token,t.keyword_order,k.keyword_text,k.keyword_norm,
                   r.tiny_hint,r.provider,r.model,r.record_sha256,b.node_kind,b.title,b.sequence_no,b.signpost_id,b.detail_ref
            FROM {_HD77_TOKEN_TABLE} t
            JOIN {_HD76_HEADS_TABLE} h ON h.current_revision_id=t.rich_revision_id
            JOIN {_HD77_KEYWORD_TABLE} k ON k.rich_revision_id=t.rich_revision_id AND k.keyword_order=t.keyword_order
            JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=t.rich_revision_id
            LEFT JOIN knowledge_semantic_signposts b ON b.version_id=t.version_id AND b.node_type=t.node_type AND b.node_id=t.node_id
            WHERE t.version_id=? AND t.node_type IN ({type_ph}) AND t.token IN ({placeholders})
            ORDER BY t.rich_revision_id,t.keyword_order,t.token
        """,tuple(params)).fetchall()]
    by={}; indexed=set()
    for row in rows:
        rid=str(row.get("rich_revision_id") or ""); token=str(row.get("token") or ""); indexed.add(token)
        item=by.setdefault(rid,{"rich_revision_id":rid,"node_type":row.get("node_type"),"node_id":row.get("node_id"),"tiny_hint":row.get("tiny_hint"),"provider":row.get("provider"),"model":row.get("model"),"record_sha256":row.get("record_sha256"),"node_kind":row.get("node_kind"),"title":row.get("title"),"sequence_no":int(row.get("sequence_no") or 0),"matched_tokens":set(),"matched_keywords":{}})
        item["matched_tokens"].add(token); item["matched_keywords"][int(row.get("keyword_order") or 0)]=(str(row.get("keyword_text") or ""),str(row.get("keyword_norm") or ""))
    dfs={t:sum(1 for item in by.values() if t in item["matched_tokens"]) for t in indexed}; n=max(1,head_count)
    weights={t:math.log((n+1.0)/(dfs.get(t,0)+1.0))+1.0 for t in indexed}; total_weight=sum(weights.values()) or 1.0
    candidates=[]
    for item in by.values():
        matched=sorted(item["matched_tokens"]); weighted=sum(weights.get(t,1.0) for t in matched); coverage=weighted/total_weight
        phrases=[]
        for text,norm in item["matched_keywords"].values():
            if norm and " " in norm and qnorm and norm in qnorm: phrases.append(text)
        role,role_basis=_hd77_mechanical_source_role(item.get("node_kind"),item.get("title"))
        item.update({"matched_tokens":matched,"matched_keyword_phrases":phrases,"keyword_weighted_coverage":coverage,"keyword_weighted_score":weighted,"source_role":role,"source_role_basis":role_basis})
        candidates.append(item)
    if len(terms)>=4 and any(len(x["matched_tokens"])>=2 for x in candidates):
        candidates=[x for x in candidates if len(x["matched_tokens"])>=2]
    candidates.sort(key=lambda x:(-float(x["keyword_weighted_coverage"]),-len(x["matched_tokens"]),-len(x["matched_keyword_phrases"]),int(x["source_role"]=="reference_material"),int(x.get("sequence_no") or 0),str(x.get("node_id") or "")))
    return {"terms":terms,"candidates":candidates[:_HD77_MAX_SQL_CANDIDATES],"indexed_query_terms":sorted(indexed),"unindexed_query_terms":[t for t in terms if t not in indexed],"heads":head_count}


_HD77_FALLBACK_SP_SEARCH_MAP = _sp_search_map

def _sp_search_map(module, book_id: str, *, version_id: str="", query: str="", include: str="all", offset: int=0, limit: int=_SMN_DEFAULT_LIMIT) -> dict|None:
    version,source=_smn_resolve_version(book_id,version_id)
    if not version: return None
    chosen=str(version.get("version_id") or "")
    include_norm={"both":"all","semantic":"semantic_units","structure":"structural_resumes"}.get(str(include or "all").casefold().strip(),str(include or "all").casefold().strip())
    if include_norm not in {"all","semantic_units","structural_resumes"}:
        return {"ok":False,"error":"include must be all, semantic_units, or structural_resumes.","read_only":True,"model_calls":0,"web_calls":0}
    terms=_smn_terms(query); page_offset=_smn_int(offset,0,0,10_000_000); page_limit=_smn_int(limit,_SMN_DEFAULT_LIMIT,1,_SMN_MAX_LIMIT)
    if not terms:
        return _HD77_FALLBACK_SP_SEARCH_MAP(module,book_id,version_id=version_id,query=query,include=include,offset=offset,limit=limit)
    diag=_hd77_keyword_candidates(str(book_id or ""),chosen,include_norm,str(query or "")); candidates=list(diag.get("candidates") or [])
    if not candidates:
        out=_HD77_FALLBACK_SP_SEARCH_MAP(module,book_id,version_id=version_id,query=query,include=include,offset=offset,limit=limit)
        if isinstance(out,dict):
            out=dict(out); out["keyword_sql_primary_attempted"]=True; out["keyword_sql_primary_hit"]=False; out["keyword_sql_fallback_used"]=True; out["model_calls"]=0
        return out
    selected=candidates[page_offset:page_offset+page_limit]; nodes=[]
    for item in selected:
        nt=str(item.get("node_type") or ""); nid=str(item.get("node_id") or ""); stored=_sp_get(chosen,nt,nid)
        if not stored: continue
        record=dict(stored); record["hint_text"]=str(item.get("tiny_hint") or record.get("hint_text") or "")
        record["matched_fields"]=["rich_signpost_keyword_index"]
        node=_sp_route_node(record,None); card=dict(node.get("route_card") or {})
        card.update({"rich_signpost_available":True,"rich_revision_id":item.get("rich_revision_id"),"rich_record_sha256":item.get("record_sha256"),"rich_detail_tool":"read_rich_signpost","deep_overlay_current":True,"deep_provider":item.get("provider"),"deep_model":item.get("model"),"keyword_sql_primary":True,"source_role":item.get("source_role"),"source_role_basis":list(item.get("source_role_basis") or []),"deep_signpost_is_navigation_only":True})
        node["route_card"]=card
        node.update({"match_mode":"python_sql_keyword_overlap","query_token_count":len(terms),"matched_token_count":len(item.get("matched_tokens") or []),"matched_query_tokens":list(item.get("matched_tokens") or []),"keyword_weighted_coverage":round(float(item.get("keyword_weighted_coverage") or 0.0),6),"matched_multiword_keyword_count":len(item.get("matched_keyword_phrases") or []),"keyword_values_exposed":False,"source_localization_terms":[],"semantic_expansion_used":False})
        nodes.append(node)
    total=len(candidates)
    return {"ok":True,"version":_HD77_VERSION,"book_id":book_id,"source_id":(source or {}).get("source_id"),"version_id":chosen,"version_number":version.get("version_number"),"version_status":version.get("status"),"active":bool(version.get("active")),"query":str(query or ""),"query_terms":terms,"query_operator":"deterministic SQL lookup over model-authored rich-signpost keyword tokens; IDF-like mechanical ranking; no semantic expansion","indexed_query_terms":list(diag.get("indexed_query_terms") or []),"unindexed_query_terms":list(diag.get("unindexed_query_terms") or []),"ranking":"keyword rarity-weighted coverage, matched-token count, exact multiword keyword phrase, then explicit reference-label penalty and source order","include":include_norm,"total_matches":total,"offset":page_offset,"limit":page_limit,"returned":len(nodes),"next_offset":page_offset+len(nodes) if page_offset+len(nodes)<total else None,"nodes":nodes,"view":"route","persistent_signpost_index_used":True,"rich_keyword_sql_index_used":True,"keyword_sql_primary_hit":True,"keyword_sql_fallback_used":False,"rich_signpost_detail_included_by_default":False,"source_text_exposed_in_route_result":False,"source_text_opened_for_ranking":False,"source_spans_checked":0,"model_calls":0,"web_calls":0,"python_semantic_judgment":False,"authority":"Model-authored keywords are derived navigation. Python only indexes and ranks exact normalized keyword tokens; exact original-source reopening remains required for evidence.","read_only":True}


_HD77_BASE_SP_BUILD = _HD_BASE_SP_BUILD

def _sp_build(module, reference: str="all", *, reason: str="manual_backfill") -> dict:
    result=dict(_HD77_BASE_SP_BUILD(module,reference,reason=reason))
    if result.get("ok"):
        try: idx=_hd77_reindex_scope(module,reference)
        except Exception as exc: idx={"ok":False,"error_type":type(exc).__name__,"error":str(exc),"model_calls":0}
        result["rich_keyword_index_refresh"]=idx
        result["deep_signposts_invalidated"]=0
        result["deep_rich_revisions_preserved"]=True
        result["model_calls"]=0
        result["python_only_rebuild"]=True
        result["semantic_keywords_authored_by_python"]=False
    return result



_HD77_BASE_SDL_COMPACT_NODE = _sdl_compact_node

def _sdl_compact_node(node: dict, version: dict, *, provisional: bool=False, candidate: dict|None=None) -> dict:
    out=_HD77_BASE_SDL_COMPACT_NODE(node,version,provisional=provisional,candidate=candidate)
    for key in ("keyword_weighted_coverage","matched_multiword_keyword_count","keyword_values_exposed"):
        if key in node: out[key]=node.get(key)
    card=dict(node.get("route_card") or {})
    out["keyword_sql_primary"]=bool(card.get("keyword_sql_primary")); out["source_role"]=card.get("source_role")
    return out


