# .78 exact-source exit continuation inside deep-signpost-retrieval-fusion rev=5.
# A live .77 keyword test proved that SQL keyword retrieval could return a strong
# candidate but Assistant's subsequent manual source read failed with "Book not found".
# The navigation result carried several identifiers (BK/source/version/node), leaving
# room for model-side reference transcription ambiguity. Rich revisions already own
# an immutable exact-source pointer, so expose that pointer as a one-hop read tool.
# Python resolves and verifies the stored pointer mechanically, then opens exactly one
# original source chunk inside the stored range. The model never needs to reconstruct
# a book ID from source/version IDs. This adds no semantic judgment and stores no text.

_HD78_VERSION = "1.4-python-keyword-plus-exact-source-exit"
_HD78_SOURCE_TOOL = "read_signpost_source"


def _hd78_source_record(*, rich_revision_id: str="", node_id: str="", book_id: str="") -> tuple[dict|None,dict|None,str|None]:
    _hd_ensure_schema(); rid=str(rich_revision_id or "").strip(); nid=str(node_id or "").strip(); bid=str(book_id or "").strip()
    with _sk_connect() as db:
        if rid:
            row=db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(rid,)).fetchone()
        elif nid:
            sql=f"""SELECT r.* FROM {_HD76_HEADS_TABLE} h JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=h.current_revision_id WHERE h.node_id=?"""
            params=[nid]
            if bid: sql+=" AND h.book_id=?"; params.append(bid)
            sql+=" ORDER BY h.updated_at DESC LIMIT 1"
            row=db.execute(sql,tuple(params)).fetchone()
        else:
            return None,None,"rich_revision_id or node_id is required."
    if not row: return None,None,"No matching rich signpost revision exists."
    record=dict(row); raw=str(record.get("exact_source_pointer_json") or ""); expected=str(record.get("exact_source_pointer_sha256") or "")
    if not raw or not expected: return record,None,"Rich signpost has no exact-source pointer."
    if _sk_hash(raw)!=expected: return record,None,"Exact-source pointer hash mismatch."
    pointer=_hd76_json(raw,{})
    if not isinstance(pointer,dict) or not pointer.get("book_id"): return record,None,"Exact-source pointer is malformed."
    return record,pointer,None


def _hd78_read_signpost_source(module, rich_revision_id: str="", *, node_id: str="", book_id: str="", ordinal=None) -> dict:
    record,pointer,error=_hd78_source_record(rich_revision_id=rich_revision_id,node_id=node_id,book_id=book_id)
    if error:
        return {"ok":False,"error":error,"rich_revision_id":str(rich_revision_id or "") or None,"node_id":str(node_id or "") or None,"read_only":True,"model_calls":0,"web_calls":0}
    start=dict(pointer.get("start") or {}); end=dict(pointer.get("end") or {})
    try: start_ord=int(start.get("ordinal")); end_ord=int(end.get("ordinal"))
    except Exception:
        return {"ok":False,"error":"Exact-source pointer has invalid ordinal bounds.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0}
    if start_ord<1 or end_ord<start_ord:
        return {"ok":False,"error":"Exact-source pointer has invalid ordinal bounds.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0}
    chosen=start_ord if ordinal is None else int(ordinal)
    if chosen<start_ord or chosen>end_ord:
        return {"ok":False,"error":"Requested ordinal is outside this signpost's immutable exact-source range.","rich_revision_id":record.get("rich_revision_id"),"requested_ordinal":chosen,"allowed_range":[start_ord,end_ord],"read_only":True,"model_calls":0,"web_calls":0}
    books=getattr(module,"neatbooks",None)
    if books is None or not callable(getattr(books,"read_book_chunks",None)):
        return {"ok":False,"error":"NeatBooks exact-source reader is unavailable.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0}
    pointer_bid=str(pointer.get("book_id") or "").strip()
    try:
        canonical=str(books.resolve_book_reference(pointer_bid) if callable(getattr(books,"resolve_book_reference",None)) else pointer_bid)
    except Exception as exc:
        return {"ok":False,"error":f"Stored signpost book pointer could not be resolved: {type(exc).__name__}: {exc}","rich_revision_id":record.get("rich_revision_id"),"stored_book_id":pointer_bid,"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0}
    try:
        result=books.read_book_chunks(book_id=canonical,start=chosen,count=1)
    except Exception as exc:
        return {"ok":False,"error":f"Exact signpost-source read failed: {type(exc).__name__}: {exc}","rich_revision_id":record.get("rich_revision_id"),"stored_book_id":pointer_bid,"canonical_book_id":canonical,"requested_ordinal":chosen,"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0}
    try: _bni_observe_read_result(module,result,trigger=_HD78_SOURCE_TOOL)
    except Exception: pass
    out=dict(result) if isinstance(result,dict) else {"result":result}
    out.update({
        "ok":bool(out.get("ok",True)),"read_only":True,"model_calls":0,"web_calls":0,
        "rich_revision_id":record.get("rich_revision_id"),"node_id":record.get("node_id"),"node_type":record.get("node_type"),
        "stored_book_id":pointer_bid,"canonical_book_id":canonical,"pointer_hash_valid":True,
        "exact_source_pointer_sha256":record.get("exact_source_pointer_sha256"),
        "signpost_source_range":{"start":start,"end":end,"source_sha256":pointer.get("source_sha256"),"authority":pointer.get("authority")},
        "requested_ordinal":chosen,"range_start_ordinal":start_ord,"range_end_ordinal":end_ord,
        "range_complete_in_this_read":start_ord==end_ord,
        "next_ordinal":chosen+1 if chosen<end_ord else None,
        "previous_ordinal":chosen-1 if chosen>start_ord else None,
        "source_authority":"Original NeatBooks chunk returned through an immutable rich-signpost pointer; signpost semantics remain navigation only.",
        "python_semantic_judgment":False,
    })
    return _ora_clean_result(module,out) if callable(globals().get("_ora_clean_result")) else out


def _hd78_source_exit_for_revision(rich_revision_id: str) -> dict|None:
    record,pointer,error=_hd78_source_record(rich_revision_id=rich_revision_id)
    if error or not record or not pointer: return None
    start=dict(pointer.get("start") or {}); end=dict(pointer.get("end") or {})
    return {
        "available":True,"tool":_HD78_SOURCE_TOOL,"arguments":{"rich_revision_id":record.get("rich_revision_id")},
        "stored_book_id":pointer.get("book_id"),"start_ordinal":start.get("ordinal"),"end_ordinal":end.get("ordinal"),
        "pointer_sha256":record.get("exact_source_pointer_sha256"),"pointer_hash_verified_on_read":True,
        "selection":"immutable_rich_signpost_exact_source_pointer","verification_required_before_claim":True,
    }


