# .79 rich-signpost search-surface continuation inside deep-signpost-retrieval-fusion rev=6.
# A live .78 validation turn asked Assistant to use the rich SQL keyword index first,
# but the carried capsule contained only an older generic signpost search result.
# The root cause is integration, not keyword quality: .77 made rich-keyword ranking
# an internal path of search_semantic_signposts, but never exposed a separately
# named rich-only tool; adaptive BOOKS seeding also normally surfaced only the
# first generic book tools, so explicit signpost intent could miss the rich route.
# .79 adds a zero-model search_rich_signposts tool that directly queries current
# rich SQL keyword heads, never falls back to the legacy lexical route, can scope
# by exact BK/source/title reference, returns the exact rich_revision_id plus only
# matched keywords/coverage/source-role facts, and opens no source text. Explicit
# signpost/keyword intent mechanically prioritizes search_rich_signposts followed
# by read_signpost_source in the adaptive BOOKS surface. Python still performs no
# semantic expansion or relevance judgment; the model authored the keywords and
# Assistant chooses which returned route to follow.

_HD79_VERSION = "1.6-explicit-rich-keyword-search-capsule-route"
_HD79_SEARCH_TOOL = "search_rich_signposts"
_HD79_INTENT_TERMS = (
    "signpost", "signposts", "rich signpost", "rich-signpost", "keyword index",
    "keyword-index", "keyword signpost", "navigation signpost", "read_signpost_source",
)


def _hd79_scope_versions(reference: str="", book_ids=None, book_scan_limit: int=100) -> dict:
    limit=max(1,min(100,int(book_scan_limit or 100)))
    clean=str(reference or "").strip()
    rows=[]; unresolved=[]
    if clean:
        rows=list(_sp_active_versions(clean))
        if not rows: unresolved.append(clean)
    elif isinstance(book_ids,(list,tuple)) and book_ids:
        seen=set()
        for ref in book_ids[:24]:
            r=str(ref or "").strip()
            if not r: continue
            found=list(_sp_active_versions(r))
            if not found: unresolved.append(r); continue
            for row in found:
                vid=str(row.get("version_id") or "")
                if vid and vid not in seen:
                    seen.add(vid); rows.append(row)
    else:
        rows=list(_sp_active_versions("all"))
    truncated=len(rows)>limit
    return {"versions":rows[:limit],"unresolved_book_references":unresolved,"scope_truncated":truncated}


def _hd79_candidate_node(item: dict, version: dict, query_terms: list[str]) -> dict|None:
    chosen=str(version.get("version_id") or "")
    nt=str(item.get("node_type") or ""); nid=str(item.get("node_id") or "")
    stored=_sp_get(chosen,nt,nid)
    if not stored: return None
    record=dict(stored); record["hint_text"]=str(item.get("tiny_hint") or record.get("hint_text") or "")
    record["matched_fields"]=["rich_signpost_keyword_index"]
    node=_sp_route_node(record,None); card=dict(node.get("route_card") or {})
    matched_kw=[]
    for pair in (item.get("matched_keywords") or {}).values():
        if isinstance(pair,(list,tuple)) and pair:
            txt=str(pair[0] or "").strip()
            if txt and txt not in matched_kw: matched_kw.append(txt)
    matched_tokens=list(item.get("matched_tokens") or [])
    unique_terms=[]
    for t in query_terms:
        if t not in unique_terms: unique_terms.append(t)
    coverage=(len(set(matched_tokens))/max(1,len(unique_terms)))
    card.update({
        "rich_signpost_available":True,
        "rich_revision_id":item.get("rich_revision_id"),
        "rich_record_sha256":item.get("record_sha256"),
        "rich_detail_tool":"read_rich_signpost",
        "preferred_exact_source_exit":"read_signpost_source",
        "deep_overlay_current":True,
        "deep_provider":item.get("provider"),
        "deep_model":item.get("model"),
        "keyword_sql_primary":True,
        "source_role":item.get("source_role"),
        "source_role_basis":list(item.get("source_role_basis") or []),
        "deep_signpost_is_navigation_only":True,
    })
    node["route_card"]=card
    node.update({
        "book_id":str(version.get("book_id") or node.get("book_id") or ""),
        "book_title":str(version.get("title") or ""),
        "rich_revision_id":item.get("rich_revision_id"),
        "match_mode":"python_sql_rich_keyword_only",
        "query_token_count":len(unique_terms),
        "matched_token_count":len(set(matched_tokens)),
        "matched_query_tokens":matched_tokens,
        "matched_keywords":matched_kw,
        "keyword_coverage":round(float(coverage),6),
        "keyword_weighted_coverage":round(float(item.get("keyword_weighted_coverage") or 0.0),6),
        "matched_multiword_keywords":list(item.get("matched_keyword_phrases") or []),
        "source_role":item.get("source_role"),
        "source_role_basis":list(item.get("source_role_basis") or []),
        "semantic_expansion_used":False,
        "source_text_opened_for_ranking":False,
    })
    return node


def _hd79_search_rich_signposts(module, query: str, *, reference: str="", book_ids=None, node_limit: int=6, book_scan_limit: int=100) -> dict:
    terms=_smn_terms(query); limit=max(1,min(16,int(node_limit or 6)))
    if not terms:
        return {"ok":False,"operation":_HD79_SEARCH_TOOL,"error":"query must contain at least one searchable token.","rich_only":True,"fallback_used":False,"model_calls":0,"source_spans_checked":0,"read_only":True}
    scope=_hd79_scope_versions(reference,book_ids,book_scan_limit)
    versions=list(scope.get("versions") or [])
    if (reference or book_ids) and not versions:
        return {"ok":False,"operation":_HD79_SEARCH_TOOL,"error":"No matching active digested book version exists for the requested scope.","reference":str(reference or ""),"unresolved_book_references":list(scope.get("unresolved_book_references") or []),"rich_only":True,"fallback_used":False,"model_calls":0,"source_spans_checked":0,"read_only":True}
    nodes=[]; books_checked=0; heads=0; indexed=set(); unindexed=set(terms)
    for version in versions:
        books_checked+=1
        diag=_hd77_keyword_candidates(str(version.get("book_id") or ""),str(version.get("version_id") or ""),"all",str(query or ""))
        heads+=int(diag.get("heads") or 0)
        indexed.update(diag.get("indexed_query_terms") or [])
        unindexed.difference_update(diag.get("indexed_query_terms") or [])
        for item in list(diag.get("candidates") or []):
            node=_hd79_candidate_node(item,version,terms)
            if node is not None: nodes.append(node)
    def rank(n):
        role_penalty=1 if str(n.get("source_role") or "")=="reference_material" else 0
        return (-float(n.get("keyword_coverage") or 0.0),-int(n.get("matched_token_count") or 0),-len(n.get("matched_multiword_keywords") or []),role_penalty,-float(n.get("keyword_weighted_coverage") or 0.0),str(n.get("book_title") or "").casefold(),int(n.get("sequence_no") or 0),str(n.get("node_id") or ""))
    nodes.sort(key=rank); nodes=nodes[:limit]
    return {
        "ok":True,"version":_HD79_VERSION,"operation":_HD79_SEARCH_TOOL,
        "query":str(query or ""),"query_terms":terms,"reference":str(reference or ""),
        "books_in_scope":len(versions),"books_checked":books_checked,"book_scope_truncated":bool(scope.get("scope_truncated")),
        "unresolved_book_references":list(scope.get("unresolved_book_references") or []),
        "rich_heads_seen":heads,"indexed_query_terms":sorted(indexed),"unindexed_query_terms":sorted(unindexed),
        "returned":len(nodes),"nodes":nodes,"rich_only":True,"rich_keyword_sql_index_used":True,
        "legacy_signpost_fallback_used":False,"semantic_candidate_fallback_used":False,
        "query_operator":"deterministic SQL exact-token overlap over model-authored rich-signpost keywords; no synonyms and no legacy fallback",
        "ranking":"query-token coverage, matched-token count, exact multiword-keyword match, explicit reference-material tie-break, then keyword rarity/source order",
        "matched_keyword_values_exposed":True,"full_keyword_card_exposed":False,
        "preferred_detail_tool":"read_rich_signpost","preferred_exact_source_exit":"read_signpost_source",
        "source_text_opened_for_ranking":False,"source_spans_checked":0,"model_calls":0,"web_calls":0,
        "python_semantic_judgment":False,
        "authority":"Rich keywords are model-authored derived navigation. Python performs exact mechanical indexing/ranking only; original source reopening is required for evidence.",
        "read_only":True,
    }



def _hd79_register_tool(module) -> None:
    schema=_hd79_search_schema()
    for array_name in ("_ONLINE_BOOK_RESPONSE_TOOLS","_ONLINE_EVIDENCE_RESPONSE_TOOLS"):
        arr=globals().get(array_name)
        if isinstance(arr,list):
            for i,item in enumerate(arr):
                if isinstance(item,dict) and str(item.get("name") or "")==_HD79_SEARCH_TOOL:
                    arr[i]=schema; break
            else: arr.append(schema)
    if isinstance(globals().get("_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS"),dict): _ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS[_HD79_SEARCH_TOOL]=1400
    if isinstance(globals().get("_ADAPTIVE_TOOL_GROUPS"),dict):
        group=list(_ADAPTIVE_TOOL_GROUPS.get("books") or ())
        if _HD79_SEARCH_TOOL not in group: group.append(_HD79_SEARCH_TOOL)
        _ADAPTIVE_TOOL_GROUPS["books"]=tuple(group)
    if isinstance(getattr(module,"TOOL_SCHEMAS",None),list):
        local={"type":"function","function":{k:v for k,v in schema.items() if k not in {"type","strict"}}}
        for i,item in enumerate(module.TOOL_SCHEMAS):
            if isinstance(item,dict) and str((item.get("function") or {}).get("name") or "")==_HD79_SEARCH_TOOL:
                module.TOOL_SCHEMAS[i]=local; break
        else: module.TOOL_SCHEMAS.append(local)
    if isinstance(getattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST",None),set): module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add(_HD79_SEARCH_TOOL)


def _hd79_wrap_dispatchers(module) -> None:
    old_evidence=globals().get("_ora_execute_evidence_tool")
    if callable(old_evidence) and not getattr(old_evidence,"_hd79_wrapped",False):
        def execute_rich_search(mod,name,arguments):
            args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)==_HD79_SEARCH_TOOL:
                return _ora_clean_result(mod,_hd79_search_rich_signposts(mod,str(args.get("query") or ""),reference=str(args.get("reference") or ""),book_ids=args.get("book_ids"),node_limit=int(args.get("node_limit") or 6),book_scan_limit=int(args.get("book_scan_limit") or 100)))
            return old_evidence(mod,name,arguments)
        execute_rich_search._hd79_wrapped=True; globals()["_ora_execute_evidence_tool"]=execute_rich_search
    old_execute=getattr(module,"execute_tool",None)
    if callable(old_execute) and not getattr(old_execute,"_hd79_wrapped",False):
        def execute_local(name,arguments,seen,*args,**kwargs):
            tool_args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)==_HD79_SEARCH_TOOL:
                return _hd79_search_rich_signposts(module,str(tool_args.get("query") or ""),reference=str(tool_args.get("reference") or ""),book_ids=tool_args.get("book_ids"),node_limit=int(tool_args.get("node_limit") or 6),book_scan_limit=int(tool_args.get("book_scan_limit") or 100))
            return old_execute(name,arguments,seen,*args,**kwargs)
        execute_local._hd79_wrapped=True; module.execute_tool=execute_local


def _hd79_install_adaptive_priority() -> None:
    base_groups=globals().get("_adaptive_tool_query_groups")
    if callable(base_groups) and not getattr(base_groups,"_hd79_wrapped",False):
        def query_groups(query,domains):
            groups=list(base_groups(query,domains)); folded=str(query or "").casefold()
            if any(term in folded for term in _HD79_INTENT_TERMS) and "books" not in groups: groups.append("books")
            return groups
        query_groups._hd79_wrapped=True; globals()["_adaptive_tool_query_groups"]=query_groups
    base_candidates=globals().get("_adaptive_tool_group_candidates")
    if callable(base_candidates) and not getattr(base_candidates,"_hd79_wrapped",False):
        def group_candidates(index,group,query,*,broad=False):
            names=list(base_candidates(index,group,query,broad=broad)); folded=str(query or "").casefold()
            if str(group)=="books" and any(term in folded for term in _HD79_INTENT_TERMS):
                preferred=[_HD79_SEARCH_TOOL,"read_signpost_source","read_rich_signpost","search_semantic_signposts","search_books","read_book_chunks"]
                ordered=[n for n in preferred if n in index]
                ordered.extend(n for n in names if n not in ordered)
                return ordered
            return names
        group_candidates._hd79_wrapped=True; globals()["_adaptive_tool_group_candidates"]=group_candidates


