            return {"terms":["enemy","yourself","victory","battle"],"heads":20,"indexed_query_terms":["battle"],"unindexed_query_terms":["enemy","yourself","victory"],"candidates":[{"rich_revision_id":"RSR-MAC","node_type":"semantic_unit","node_id":"MAC1","tiny_hint":"A battle in Macbeth.","provider":"online","model":"gpt-5.6-luna","record_sha256":"b"*64,"node_kind":"body","title":"Macbeth","sequence_no":1,"matched_tokens":["battle"],"matched_keywords":{0:("battle","battle")},"matched_keyword_phrases":[],"keyword_weighted_coverage":0.25,"source_role":"body_or_unknown","source_role_basis":[]}]}
