        globals()["_sp_get"]=lambda vid,nt,nid:{"version_id":vid,"node_type":nt,"node_id":nid,"sequence_no":20 if nid=="AOW20" else 1,"node_kind":"body","title":"Attack by Stratagem" if nid=="AOW20" else "Macbeth","book_id":"BK-AOW" if nid=="AOW20" else "BK-MAC","signpost_id":"SG-"+nid,"hint_text":"base","search_lexicon":"||","detail_ref":"semantic:"+nid,"summary_characters":20,"summary_origin":"test","linked_record_count":0,"coverage_status":"canonical"}
