    online_names={str(x.get("name") or "") for x in globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS",[]) if isinstance(x,dict)}
    local_names={str((x.get("function") or {}).get("name") or "") for x in getattr(module,"TOOL_SCHEMAS",[]) if isinstance(x,dict)}
