_HD79_BASE_INSTALL_FUSION=_install_deep_signpost_retrieval_fusion

def _install_deep_signpost_retrieval_fusion(module) -> None:
    _HD79_BASE_INSTALL_FUSION(module)
    _hd79_register_tool(module); _hd79_wrap_dispatchers(module); _hd79_install_adaptive_priority()
    module.search_rich_signposts=lambda query,**kwargs:_hd79_search_rich_signposts(module,query,**kwargs)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_HD79_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nEXPLICIT RICH SIGNPOST KEYWORD ROUTE — ZERO-MODEL FIRST HOP\n"
          "- search_rich_signposts is the dedicated rich SQL keyword-index tool. When the task explicitly asks for rich signposts/keyword signposts, call it fresh; do not substitute a carried generic search_semantic_signposts result.\n"
          "- For a named book, pass reference as its exact BK-ID/source ID/title when available so unrelated books cannot outrank the requested source. The tool never falls back to legacy signposts.\n"
          "- search_rich_signposts returns the exact rich_revision_id plus only matched keywords/coverage/source-role facts with zero model calls and zero source reads. Assistant chooses the candidate, then read_signpost_source follows that revision to original evidence.\n")
    if "EXPLICIT RICH SIGNPOST KEYWORD ROUTE — ZERO-MODEL FIRST HOP" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule


# .80 Python chunk-keyword distillation + Assistant keyword editing continuation.
# Live .79 validation proved the dedicated rich-search route was finally correct but
# returned rich_heads_seen=0 for The Art of War. The 94 already-existing deep
# signposts predated the .76 rich-revision/head layer, so .77's reindexer had no
# current rich heads to project. The user's intended design is simpler than the old
# model-authored-keyword assumption: Python mechanically distills each exact source
# span to a small 12-20 word navigation list using the same frequency/stopword style
# already proven by Chat Pyramid distillation; Assistant may later replace that list with
# her own 12-20 keywords. Keywords remain derived navigation only. Exact source text
# remains evidence and is never copied into the rich revision.

_HD80_VERSION = "1.8-exact-source-word-membership"
_HD80_MIN_KEYWORDS = 12
_HD80_MAX_KEYWORDS = 20
_HD80_DEFAULT_KEYWORDS = 18
_HD80_MAX_SOURCE_CHARS = 500000
_HD80_EDIT_TOOL = "revise_rich_signpost_keywords"


def _hd80_source_text(module, book_id: str, record: dict) -> dict:
    """Read the exact stored signpost span for deterministic Python keyword extraction."""
    try:
        rows=_sp_source_rows_for_span(module,str(book_id or ""),record)
    except Exception as exc:
        return {"ok":False,"text":"","rows":0,"characters":0,"truncated":False,"error":str(exc)[:300]}
    if not rows:
        return {"ok":False,"text":"","rows":0,"characters":0,"truncated":False,"error":"exact source span unavailable"}
    start_ord=_shn_int_or_none(record.get("start_ordinal")); end_ord=_shn_int_or_none(record.get("end_ordinal"))
    start_char=_shn_int_or_none(record.get("start_char")); end_char=_shn_int_or_none(record.get("end_char"))
    parts=[]
    for source_row in rows:
        ordinal=int(source_row.get("ordinal") or 0); text=str(source_row.get("source_text") or "")
        left=max(0,min(len(text),int(start_char or 0))) if start_ord is not None and ordinal==start_ord else 0
        right=max(left,min(len(text),int(end_char if end_char is not None else len(text)))) if end_ord is not None and ordinal==end_ord else len(text)
        bounded=text[left:right]
        if bounded: parts.append(bounded)
    full="\n".join(parts)
    if len(full)<=_HD80_MAX_SOURCE_CHARS:
        return {"ok":bool(full),"text":full,"rows":len(rows),"characters":len(full),"original_characters":len(full),"truncated":False,"sampling":"full_exact_stored_span"}
    # Mechanical cap only for pathological very-large structural spans. No model is involved.
    head=_HD80_MAX_SOURCE_CHARS//3; tail=_HD80_MAX_SOURCE_CHARS//3; mid=_HD80_MAX_SOURCE_CHARS-head-tail
    middle=max(0,(len(full)//2)-(mid//2))
    sampled=full[:head]+"\n"+full[middle:middle+mid]+"\n"+full[-tail:]
    return {"ok":True,"text":sampled[:_HD80_MAX_SOURCE_CHARS],"rows":len(rows),"characters":min(len(sampled),_HD80_MAX_SOURCE_CHARS),"original_characters":len(full),"truncated":True,"sampling":"deterministic_start_middle_end"}


def _hd80_all_word_tokens(text: object) -> list[str]:
    """Return exact normalized Unicode word tokens present in source text.

    The token boundary deliberately matches _smn_terms' Unicode lexical rule rather
    than the older ASCII Chat-Pyramid regex. This prevents source words such as
    `chüan` from being split into invented fragments such as `ch` / `an`.
    """
    folded=unicodedata.normalize("NFKC",str(text or "")).casefold()
    return [str(x) for x in re.findall(r"[^\W_]+",folded,flags=re.UNICODE) if str(x)]


def _hd84_source_word_counts_from_text(text: object) -> dict:
    tokens=_hd80_all_word_tokens(text); counts={}; first={}
    for index,token in enumerate(tokens):
        counts[token]=counts.get(token,0)+1
        first.setdefault(token,index)
    return {"tokens":tokens,"counts":counts,"first":first,"distinct":len(counts)}


def _hd84_rank_source_words(counts: dict, first: dict|None=None, *, target: int=_HD80_DEFAULT_KEYWORDS) -> list[str]:
    first=dict(first or {}); stops={unicodedata.normalize("NFKC",str(x)).casefold() for x in set(globals().get("_CHAT_PYRAMID_STOPWORDS") or ())}
    words=[str(x) for x in counts.keys() if str(x)]
    content=[w for w in words if w not in stops]
    ranked=sorted(content,key=lambda w:(-int(counts.get(w) or 0),-len(w),int(first.get(w,10**12)),w))
    if len(ranked)<_HD80_MIN_KEYWORDS:
        for w in sorted(words,key=lambda x:(int(first.get(x,10**12)),x)):
            if w not in ranked: ranked.append(w)
            if len(ranked)>=_HD80_MIN_KEYWORDS: break
    cap=min(_HD80_MAX_KEYWORDS,max(_HD80_MIN_KEYWORDS,int(target or _HD80_DEFAULT_KEYWORDS))) if len(ranked)>=_HD80_MIN_KEYWORDS else min(_HD80_MAX_KEYWORDS,len(ranked))
    return ranked[:cap]


def _hd80_distill_keywords(text: object) -> dict:
    """Mechanical source-word distillation; every output word occurs in the source."""
    data=_hd84_source_word_counts_from_text(text); ranked=_hd84_rank_source_words(data["counts"],data["first"],target=_HD80_DEFAULT_KEYWORDS)
    source_vocab=set(data["counts"]); keywords=[w for w in ranked if w in source_vocab][:_HD80_MAX_KEYWORDS]
    return {
        "keywords":keywords,"count":len(keywords),"contract_min":_HD80_MIN_KEYWORDS,"contract_max":_HD80_MAX_KEYWORDS,
        "underfilled":len(keywords)<_HD80_MIN_KEYWORDS,"model_calls":0,"semantic_expansion":False,
        "source_word_membership_enforced":True,"source_distinct_words":len(source_vocab),
        "normalization":"Unicode NFKC + casefold + Unicode word-token boundary",
        "method":"deterministic frequency/stopword ranking over exact Unicode source-word tokens only",
    }

def _hd80_clean_user_keywords(values) -> tuple[list[str],list[str]]:
    clean=[]; duplicates=[]; seen=set()
    for raw in list(values or []):
        text=_hd_clean(raw,_HD_MAX_TERM_CHARS)
        # User asked for words: each entry must normalize to exactly one searchable token.
        terms=_smn_terms(text)
        if len(terms)!=1: continue
        word=terms[0]
        if word in seen:
            duplicates.append(word); continue
        seen.add(word); clean.append(word)
    return clean,duplicates


_HD84_AUDIT_TABLE = "knowledge_rich_signpost_source_word_audits"


def _hd84_source_record_from_revision(current: dict) -> dict:
    pointer=_hd76_json(current.get("exact_source_pointer_json"),{})
    start=dict(pointer.get("start") or {}); end=dict(pointer.get("end") or {})
    return {
        "version_id":current.get("version_id"),"node_type":current.get("node_type"),"node_id":current.get("node_id"),
        "start_chunk_id":start.get("chunk_id"),"start_ordinal":start.get("ordinal"),"start_char":start.get("char"),
        "end_chunk_id":end.get("chunk_id"),"end_ordinal":end.get("ordinal"),"end_char":end.get("char"),
        "source_sha256":pointer.get("source_sha256") or current.get("source_sha256"),
    }


def _hd84_source_vocabulary(module, current: dict) -> dict:
    """Verify membership against the complete exact stored source range, never a sample."""
    record=_hd84_source_record_from_revision(current); bid=str(current.get("book_id") or "")
    try:
        rows=_sp_source_rows_for_span(module,bid,record)
    except Exception as exc:
        return {"ok":False,"error":str(exc)[:300],"counts":{},"first":{},"vocabulary":set(),"rows":0}
    try: so=int(record.get("start_ordinal")); eo=int(record.get("end_ordinal"))
    except Exception:
        return {"ok":False,"error":"invalid exact-source ordinal range","counts":{},"first":{},"vocabulary":set(),"rows":len(rows)}
    by_ord={int(r.get("ordinal") or 0):dict(r) for r in rows}
    expected=list(range(so,eo+1))
    if any(o not in by_ord for o in expected):
        return {"ok":False,"error":"exact source range is incomplete","counts":{},"first":{},"vocabulary":set(),"rows":len(rows),"expected_rows":len(expected)}
    if str(record.get("start_chunk_id") or "") and str(by_ord[so].get("chunk_id") or "")!=str(record.get("start_chunk_id") or ""):
        return {"ok":False,"error":"exact source start chunk does not match stored pointer","counts":{},"first":{},"vocabulary":set(),"rows":len(rows)}
    if str(record.get("end_chunk_id") or "") and str(by_ord[eo].get("chunk_id") or "")!=str(record.get("end_chunk_id") or ""):
        return {"ok":False,"error":"exact source end chunk does not match stored pointer","counts":{},"first":{},"vocabulary":set(),"rows":len(rows)}
    counts={}; first={}; token_no=0; chars=0
    start_char=_shn_int_or_none(record.get("start_char")); end_char=_shn_int_or_none(record.get("end_char"))
    for ordinal in expected:
        raw=str(by_ord[ordinal].get("source_text") or "")
        left=max(0,min(len(raw),int(start_char or 0))) if ordinal==so else 0
        right=max(left,min(len(raw),int(end_char if end_char is not None else len(raw)))) if ordinal==eo else len(raw)
        bounded=raw[left:right]; chars+=len(bounded)
        for token in _hd80_all_word_tokens(bounded):
            counts[token]=counts.get(token,0)+1; first.setdefault(token,token_no); token_no+=1
    return {"ok":bool(counts),"counts":counts,"first":first,"vocabulary":set(counts),"rows":len(rows),"characters":chars,"tokens":token_no,
            "normalization":"Unicode NFKC + casefold + Unicode word-token boundary","complete_exact_range":True}


def _hd84_ensure_audit_schema() -> None:
    _hd_ensure_schema()
    with _sk_connect() as db:
        db.execute(f"""CREATE TABLE IF NOT EXISTS {_HD84_AUDIT_TABLE}(
            rich_revision_id TEXT PRIMARY KEY,
            exact_source_pointer_sha256 TEXT NOT NULL,
            source_sha256 TEXT NOT NULL,
            verified INTEGER NOT NULL,
            invalid_keywords_json TEXT NOT NULL DEFAULT '[]',
            checked_at TEXT NOT NULL
        )""")
        db.commit()


def _hd84_audit_cached(db, current: dict) -> bool:
    row=db.execute(f"SELECT * FROM {_HD84_AUDIT_TABLE} WHERE rich_revision_id=?",(str(current.get("rich_revision_id") or ""),)).fetchone()
    if not row: return False
    d=dict(row)
    return bool(int(d.get("verified") or 0)) and str(d.get("exact_source_pointer_sha256") or "")==str(current.get("exact_source_pointer_sha256") or "") and str(d.get("source_sha256") or "")==str(current.get("source_sha256") or "")


def _hd84_record_audit(db, current: dict, *, verified: bool, invalid: list[str]) -> None:
    db.execute(f"""INSERT INTO {_HD84_AUDIT_TABLE}(rich_revision_id,exact_source_pointer_sha256,source_sha256,verified,invalid_keywords_json,checked_at)
        VALUES(?,?,?,?,?,?) ON CONFLICT(rich_revision_id) DO UPDATE SET exact_source_pointer_sha256=excluded.exact_source_pointer_sha256,source_sha256=excluded.source_sha256,verified=excluded.verified,invalid_keywords_json=excluded.invalid_keywords_json,checked_at=excluded.checked_at""",
        (str(current.get("rich_revision_id") or ""),str(current.get("exact_source_pointer_sha256") or ""),str(current.get("source_sha256") or ""),1 if verified else 0,_sk_json(list(invalid or [])),_sk_now()))


def _hd84_validate_keyword_membership(module, current: dict, keywords: list[str]) -> dict:
    source=_hd84_source_vocabulary(module,current)
    if not source.get("ok"):
        return {"ok":False,"error":source.get("error") or "exact source vocabulary unavailable","unsupported_keywords":list(keywords),"source":source}
    vocab=set(source.get("vocabulary") or set()); unsupported=[w for w in list(keywords or []) if w not in vocab]
    return {"ok":not unsupported,"unsupported_keywords":unsupported,"source":source,"source_word_membership_enforced":True}


def _hd80_semantic_payload(generated: dict) -> dict:
    return {
        "hint":str(generated.get("hint") or ""),"navigation_summary":str(generated.get("navigation_summary") or ""),
        "expanded_navigation":str(generated.get("expanded_navigation") or ""),"keywords":list(generated.get("keywords") or []),
        "relations":list(generated.get("relations") or []),"likely_questions":list(generated.get("likely_questions") or []),
        "local_anchors":list(generated.get("local_anchors") or []),
    }


def _hd80_insert_initial_revision(db, *, version: dict, row: dict, source_input: dict, generated: dict, deep: dict, now: str) -> tuple[str,str]:
    vid=str(row.get("version_id") or ""); nt=str(row.get("node_type") or ""); nid=str(row.get("node_id") or ""); bid=str(version.get("book_id") or row.get("book_id") or "")
    existing=db.execute(f"SELECT current_revision_id FROM {_HD76_HEADS_TABLE} WHERE version_id=? AND node_type=? AND node_id=?",(vid,nt,nid)).fetchone()
    if existing: return str(existing[0]),"existing"
    base_row=db.execute("SELECT * FROM knowledge_semantic_signposts WHERE version_id=? AND node_type=? AND node_id=?",(vid,nt,nid)).fetchone(); base=dict(base_row) if base_row else {}
    source_pointer=_hd76_source_pointer(version,row,source_input); summary_pointer=_hd76_summary_pointer(row,source_input,base); base_pointer=_hd76_base_pointer(base); deep_pointer=_hd76_deep_pointer(deep)
    semantic_payload=_hd80_semantic_payload(generated); semantic_sha=_sk_hash(_sk_json(semantic_payload)); lex=str(generated.get("search_lexicon") or "||"); lex_sha=_sk_hash(lex)
    source_json=_sk_json(source_pointer); summary_json=_sk_json(summary_pointer); base_json=_sk_json(base_pointer); deep_json=_sk_json(deep_pointer)
    source_ptr_sha=_sk_hash(source_json); summary_ptr_sha=_sk_hash(summary_json); base_ptr_sha=_sk_hash(base_json); deep_ptr_sha=_sk_hash(deep_json)
    seed={"version_id":vid,"node_type":nt,"node_id":nid,"previous":None,"semantic":semantic_sha,"source":source_ptr_sha,"summary":summary_ptr_sha,"built_at":now,"origin":"python_chunk_distillation"}
    rid=_sk_id("RSR",seed,24)
    record_for_hash={"rich_revision_id":rid,"deep_signpost_id":str(deep.get("deep_signpost_id") or ""),"previous_revision_id":None,"previous_revision_sha256":None,
        "version_id":vid,"node_type":nt,"node_id":nid,"book_id":bid,"input_sha256":source_input["input_sha256"],"semantic_payload_sha256":semantic_sha,"search_lexicon_sha256":lex_sha,
        "exact_source_pointer_sha256":source_ptr_sha,"summary_pointer_sha256":summary_ptr_sha,"base_signpost_pointer_sha256":base_ptr_sha,"previous_deep_pointer_sha256":deep_ptr_sha,
        "source_sha256":str(row.get("source_sha256") or source_input.get("source_sha256") or ""),"provider":"python","model":"deterministic-chunk-keyword-distiller","build_version":_HD80_VERSION,"built_at":now}
    record_sha=_sk_hash(_sk_json(record_for_hash))
    db.execute(f"""INSERT INTO {_HD76_REVISIONS_TABLE}(
        rich_revision_id,deep_signpost_id,previous_revision_id,previous_revision_sha256,version_id,node_type,node_id,book_id,input_sha256,
        tiny_hint,navigation_summary,expanded_navigation,keywords_json,relations_json,likely_questions_json,local_anchors_json,
        semantic_payload_sha256,search_lexicon_sha256,exact_source_pointer_json,exact_source_pointer_sha256,
        summary_pointer_json,summary_pointer_sha256,base_signpost_pointer_json,base_signpost_pointer_sha256,
        previous_deep_pointer_json,previous_deep_pointer_sha256,source_sha256,provider,model,build_version,built_at,record_sha256,
        python_semantic_judgment,source_text_stored,summary_text_stored)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,0,0)""",
        (rid,str(deep.get("deep_signpost_id") or ""),None,None,vid,nt,nid,bid,source_input["input_sha256"],semantic_payload["hint"],semantic_payload["navigation_summary"],semantic_payload["expanded_navigation"],
         _sk_json(semantic_payload["keywords"]),_sk_json(semantic_payload["relations"]),_sk_json(semantic_payload["likely_questions"]),_sk_json(semantic_payload["local_anchors"]),semantic_sha,lex_sha,
         source_json,source_ptr_sha,summary_json,summary_ptr_sha,base_json,base_ptr_sha,deep_json,deep_ptr_sha,str(row.get("source_sha256") or source_input.get("source_sha256") or ""),
         "python","deterministic-chunk-keyword-distiller",_HD80_VERSION,now,record_sha))
    db.execute(f"INSERT INTO {_HD76_HEADS_TABLE}(version_id,node_type,node_id,book_id,current_revision_id,previous_revision_id,current_record_sha256,updated_at) VALUES(?,?,?,?,?,?,?,?)",
               (vid,nt,nid,bid,rid,None,record_sha,now))
    _hd77_index_revision(db,rid)
    return rid,"created"


def _hd80_backfill_scope(module, reference: str="all") -> dict:
    _hd_ensure_schema(); versions=_sp_active_versions(reference)
    if not versions:
        return {"ok":False,"operation":"python_rich_keyword_backfill","reference":reference,"error":"No matching active digested book version exists.","model_calls":0}
    prepared=[]; skipped_heads=0; no_deep=0; underfilled=[]; source_reads=0; source_chars=0
    for version in versions:
        bid=str(version.get("book_id") or ""); vid=str(version.get("version_id") or "")
        for row in _sp_rows_for_version(vid):
            nt=str(row.get("node_type") or ""); nid=str(row.get("node_id") or "")
            if _hd76_rich_head(vid,nt,nid): skipped_heads+=1; continue
            deep=_hd_current(vid,nt,nid)
            if not deep: no_deep+=1; continue
            source=_hd80_source_text(module,bid,row); source_reads+=1
            if not source.get("ok"):
                underfilled.append({"node_id":nid,"reason":"source_unavailable","error":source.get("error")}); continue
            source_chars+=int(source.get("characters") or 0)
            distilled=_hd80_distill_keywords(source.get("text") or "")
            if distilled.get("underfilled"):
                underfilled.append({"node_id":nid,"reason":"fewer_than_12_distinct_source_words","keyword_count":distilled.get("count")}); continue
            inp=_hd_input(module,row)
            hint=_shn_compact_hint(_hd_clean(deep.get("hint_text") or ( _sp_get(vid,nt,nid) or {}).get("hint_text") or row.get("title") or nid,600),_HD_MAX_HINT_CHARS)
            nav=_hd_clean(deep.get("navigation_summary"),_HD_MAX_NAV_CHARS)
            questions=_hd76_clean_list(_hd76_json(deep.get("likely_questions_json"),[]),max_items=_HD_MAX_QUESTIONS,max_chars=220)
            generated={"hint":hint,"navigation_summary":nav,"expanded_navigation":"","keywords":list(distilled["keywords"]),"relations":[],"likely_questions":questions,"local_anchors":[]}
            generated["search_lexicon"]=_sp_lexicon(row.get("title")," ".join([hint,nav,*generated["keywords"],*questions]))
            prepared.append((version,row,inp,generated,deep,distilled,source))
    created=[]
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            now=_sk_now()
            for version,row,inp,generated,deep,distilled,source in prepared:
                rid,status=_hd80_insert_initial_revision(db,version=version,row=row,source_input=inp,generated=generated,deep=deep,now=now)
                if status=="created": created.append({"node_id":row.get("node_id"),"rich_revision_id":rid,"keyword_count":len(generated["keywords"]),"source_sampling":source.get("sampling")})
            db.commit()
        except Exception:
            db.rollback(); raise
    return {"ok":not underfilled,"operation":"python_rich_keyword_backfill","reference":reference,"books":len(versions),"created":len(created),"created_revisions":created[:100],"existing_heads_skipped":skipped_heads,"nodes_without_deep_signpost":no_deep,"underfilled":underfilled[:100],"source_spans_read":source_reads,"source_characters_processed":source_chars,"keyword_contract":"12-20 source words","default_target":_HD80_DEFAULT_KEYWORDS,"model_calls":0,"web_calls":0,"python_semantic_judgment":False,"authority":"Python keywords are mechanical derived navigation from exact source words; exact source remains evidence."}


_HD84_BASE_BACKFILL_SCOPE=_hd80_backfill_scope


def _hd84_repair_existing_current_heads(module, reference: str="all") -> dict:
    """One-time/cached mechanical repair for pre-.84 current heads.

    Existing Assistant/Python choices that are literal source words are preserved in
    order. Only non-source/malformed entries are removed; if fewer than 12 remain,
    Python fills from its deterministic exact-source-word ranking. No synonym or
    paraphrase can enter the replacement list.
    """
    _hd84_ensure_audit_schema(); versions=_sp_active_versions(reference)
    audited=0; cached=0; compliant=0; repaired=[]; failures=[]
    for version in versions:
        vid=str(version.get("version_id") or "")
        with _sk_connect() as db:
            rows=[dict(x) for x in db.execute(f"""SELECT r.* FROM {_HD76_HEADS_TABLE} h JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=h.current_revision_id WHERE h.version_id=? ORDER BY h.node_type,h.node_id""",(vid,)).fetchall()]
        for current in rows:
            with _sk_connect() as db:
                if _hd84_audit_cached(db,current): cached+=1; continue
            audited+=1; source=_hd84_source_vocabulary(module,current)
            if not source.get("ok"):
                failures.append({"rich_revision_id":current.get("rich_revision_id"),"error":source.get("error")}); continue
            vocab=set(source.get("vocabulary") or set()); raw_words=_hd76_json(current.get("keywords_json"),[])
            valid=[]; invalid=[]; seen=set()
            for raw in list(raw_words or []):
                terms=_smn_terms(str(raw or ""))
                if len(terms)!=1:
                    invalid.append(str(raw)); continue
                word=terms[0]
                if word in seen: invalid.append(word); continue
                seen.add(word)
                if word not in vocab: invalid.append(word); continue
                valid.append(word)
            if not invalid and _HD80_MIN_KEYWORDS<=len(valid)<=_HD80_MAX_KEYWORDS:
                with _sk_connect() as db:
                    _hd84_record_audit(db,current,verified=True,invalid=[]); db.commit()
                compliant+=1; continue
            target=max(_HD80_MIN_KEYWORDS,min(_HD80_MAX_KEYWORDS,len(raw_words) if raw_words else _HD80_DEFAULT_KEYWORDS))
            fixed=list(valid[:_HD80_MAX_KEYWORDS])
            for word in _hd84_rank_source_words(source.get("counts") or {},source.get("first") or {},target=_HD80_MAX_KEYWORDS):
                if word not in fixed: fixed.append(word)
                if len(fixed)>=target: break
            if len(fixed)<_HD80_MIN_KEYWORDS:
                failures.append({"rich_revision_id":current.get("rich_revision_id"),"error":"exact source range contains fewer than 12 eligible distinct words","invalid_keywords":invalid}); continue
            fixed=fixed[:_HD80_MAX_KEYWORDS]
            with _sk_connect() as db:
                db.execute("BEGIN IMMEDIATE")
                try:
                    _hd84_record_audit(db,current,verified=False,invalid=invalid)
                    new_rid,record_sha=_hd84_clone_keyword_revision(db,current,fixed,_sk_now(),provider="python",model="exact-source-word-integrity-repair",origin="python_source_word_integrity_repair")
                    new_row=dict(db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(new_rid,)).fetchone())
                    _hd84_record_audit(db,new_row,verified=True,invalid=[]); db.commit()
                except Exception:
                    db.rollback(); raise
            repaired.append({"previous_revision_id":current.get("rich_revision_id"),"rich_revision_id":new_rid,"invalid_keywords":invalid,"preserved_source_keywords":valid,"keywords":fixed,"record_sha256":record_sha})
    return {"ok":not failures,"operation":"source_word_keyword_integrity_audit","audited":audited,"cached_verified":cached,"compliant":compliant,"repaired":len(repaired),"repairs":repaired[:100],"failures":failures[:100],"model_calls":0,"web_calls":0,"python_semantic_judgment":False,"membership_rule":"every current keyword is one exact normalized word token present in the stored original source range"}



def _hd84_clone_keyword_revision(db, current: dict, keywords: list[str], now: str, *, provider: str="assistant", model: str="assistant-keyword-edit", origin: str="assistant_keyword_edit") -> tuple[str,str]:
    prev_id=str(current.get("rich_revision_id") or ""); prev_sha=str(current.get("record_sha256") or "")
    semantic_payload={"hint":str(current.get("tiny_hint") or ""),"navigation_summary":str(current.get("navigation_summary") or ""),"expanded_navigation":str(current.get("expanded_navigation") or ""),
        "keywords":list(keywords),"relations":_hd76_json(current.get("relations_json"),[]),"likely_questions":_hd76_json(current.get("likely_questions_json"),[]),"local_anchors":_hd76_json(current.get("local_anchors_json"),[])}
    semantic_sha=_sk_hash(_sk_json(semantic_payload))
    lex=_sp_lexicon(""," ".join([semantic_payload["hint"],semantic_payload["navigation_summary"],semantic_payload["expanded_navigation"],*keywords,*semantic_payload["relations"],*semantic_payload["likely_questions"],*semantic_payload["local_anchors"]])); lex_sha=_sk_hash(lex)
    seed={"version_id":current.get("version_id"),"node_type":current.get("node_type"),"node_id":current.get("node_id"),"previous":prev_id,"semantic":semantic_sha,"source":current.get("exact_source_pointer_sha256"),"summary":current.get("summary_pointer_sha256"),"built_at":now,"origin":origin}
    rid=_sk_id("RSR",seed,24)
    record_for_hash={"rich_revision_id":rid,"deep_signpost_id":current.get("deep_signpost_id"),"previous_revision_id":prev_id,"previous_revision_sha256":prev_sha,"version_id":current.get("version_id"),"node_type":current.get("node_type"),"node_id":current.get("node_id"),"book_id":current.get("book_id"),"input_sha256":current.get("input_sha256"),"semantic_payload_sha256":semantic_sha,"search_lexicon_sha256":lex_sha,"exact_source_pointer_sha256":current.get("exact_source_pointer_sha256"),"summary_pointer_sha256":current.get("summary_pointer_sha256"),"base_signpost_pointer_sha256":current.get("base_signpost_pointer_sha256"),"previous_deep_pointer_sha256":current.get("previous_deep_pointer_sha256"),"source_sha256":current.get("source_sha256"),"provider":provider,"model":model,"build_version":_HD80_VERSION,"built_at":now}
    record_sha=_sk_hash(_sk_json(record_for_hash))
    db.execute(f"""INSERT INTO {_HD76_REVISIONS_TABLE}(
        rich_revision_id,deep_signpost_id,previous_revision_id,previous_revision_sha256,version_id,node_type,node_id,book_id,input_sha256,
        tiny_hint,navigation_summary,expanded_navigation,keywords_json,relations_json,likely_questions_json,local_anchors_json,
        semantic_payload_sha256,search_lexicon_sha256,exact_source_pointer_json,exact_source_pointer_sha256,
        summary_pointer_json,summary_pointer_sha256,base_signpost_pointer_json,base_signpost_pointer_sha256,
        previous_deep_pointer_json,previous_deep_pointer_sha256,source_sha256,provider,model,build_version,built_at,record_sha256,
        python_semantic_judgment,source_text_stored,summary_text_stored)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,0,0)""",
        (rid,current.get("deep_signpost_id"),prev_id,prev_sha,current.get("version_id"),current.get("node_type"),current.get("node_id"),current.get("book_id"),current.get("input_sha256"),
         semantic_payload["hint"],semantic_payload["navigation_summary"],semantic_payload["expanded_navigation"],_sk_json(keywords),_sk_json(semantic_payload["relations"]),_sk_json(semantic_payload["likely_questions"]),_sk_json(semantic_payload["local_anchors"]),semantic_sha,lex_sha,
         current.get("exact_source_pointer_json"),current.get("exact_source_pointer_sha256"),current.get("summary_pointer_json"),current.get("summary_pointer_sha256"),current.get("base_signpost_pointer_json"),current.get("base_signpost_pointer_sha256"),current.get("previous_deep_pointer_json"),current.get("previous_deep_pointer_sha256"),current.get("source_sha256"),
         provider,model,_HD80_VERSION,now,record_sha))
    db.execute(f"UPDATE {_HD76_HEADS_TABLE} SET previous_revision_id=current_revision_id,current_revision_id=?,current_record_sha256=?,updated_at=? WHERE version_id=? AND node_type=? AND node_id=?",
               (rid,record_sha,now,current.get("version_id"),current.get("node_type"),current.get("node_id")))
    _hd77_index_revision(db,rid)
    return rid,record_sha


def _hd80_clone_keyword_revision(db, current: dict, keywords: list[str], now: str) -> tuple[str,str]:
    return _hd84_clone_keyword_revision(db,current,keywords,now)



# Future --deep builds still use the model for navigation hints/relations, but Python owns
# the initial keyword list by replacing the model-proposed list immediately before the
# atomic commit. This keeps one simple keyword rule for both legacy and future signposts.
_HD80_BASE_COMMIT_STAGED=_hd_commit_staged

def _hd_commit_staged(module, staged: list[dict], backend) -> int:
    # source_text_stored remains 0: exact source is read transiently only to derive keywords.
    prepared=[]
    for item in list(staged or []):
        copy_item=dict(item); generated=dict(copy_item.get("generated") or {}); version=copy_item.get("version") or {}; row=copy_item.get("row") or {}
        source=_hd80_source_text(module,str(version.get("book_id") or row.get("book_id") or ""),row); distilled=_hd80_distill_keywords(source.get("text") or "") if source.get("ok") else {"keywords":[],"underfilled":True}
        if distilled.get("underfilled"):
            raise ValueError(f"Python keyword distillation could not produce 12 source words for node {row.get('node_id')}; atomic deep commit preserved prior state.")
        generated["keywords"]=list(distilled.get("keywords") or [])
        generated["search_lexicon"]=_sp_lexicon(row.get("title")," ".join([str(generated.get("hint") or ""),str(generated.get("navigation_summary") or ""),str(generated.get("expanded_navigation") or ""),*generated["keywords"],*list(generated.get("relations") or []),*list(generated.get("likely_questions") or []),*list(generated.get("local_anchors") or [])]))
        copy_item["generated"]=generated; prepared.append(copy_item)
    return _HD80_BASE_COMMIT_STAGED(module,prepared,backend)


_HD80_BASE_SP_BUILD=_sp_build

def _sp_build(module, reference: str="all", *, reason: str="manual_backfill") -> dict:
    result=dict(_HD80_BASE_SP_BUILD(module,reference,reason=reason))
    if result.get("ok"):
        try: backfill=_hd80_backfill_scope(module,reference)
        except Exception as exc: backfill={"ok":False,"error_type":type(exc).__name__,"error":str(exc),"model_calls":0}
        try: idx=_hd77_reindex_scope(module,reference)
        except Exception as exc: idx={"ok":False,"error_type":type(exc).__name__,"error":str(exc),"model_calls":0}
        result["python_keyword_backfill"]=backfill; result["rich_keyword_index_refresh"]=idx
        result["python_keyword_distillation"]=True; result["keyword_contract"]="12-20 exact source words"; result["source_word_membership_enforced"]=True; result["assistant_keyword_editing_available"]=True
        result["model_calls"]=0; result["deep_signposts_invalidated"]=0; result["deep_rich_revisions_preserved"]=True; result["python_only_rebuild"]=True
    return result


def _sp_rebuild(module, reference: str="all") -> dict:
    result=dict(_sp_build(module,reference,reason="manual_rebuild")); result["existing_signposts_refreshed_in_place"]=True; result["summaries_modified"]=False; result["deep_regeneration_required"]=False
    return result


_HD80_BASE_SEARCH=_hd79_search_rich_signposts

def _hd79_search_rich_signposts(module, query: str, *, reference: str="", book_ids=None, node_limit: int=6, book_scan_limit: int=100) -> dict:
    out=dict(_HD80_BASE_SEARCH(module,query,reference=reference,book_ids=book_ids,node_limit=node_limit,book_scan_limit=book_scan_limit))
    out["version"]=_HD80_VERSION; out["keyword_contract"]="12-20 exact normalized words present in the stored original source range; Python baseline or Assistant selection"
    out["query_operator"]="deterministic SQL exact-token overlap over current rich-signpost keywords; no synonyms and no legacy fallback"
    out["authority"]="Keywords are derived navigation and every current .84 keyword is mechanically source-word grounded. Python and Assistant may select only words present in the stored exact original source range; reopening original source remains required for evidence."
    for node in list(out.get("nodes") or []):
        card=dict(node.get("route_card") or {}); origin=str(card.get("deep_provider") or "")
        node["keyword_origin"]="Assistant" if origin=="assistant" else "Python" if origin=="python" else origin or "legacy"
    return out


# Replace legacy tool descriptions so Assistant does not receive the superseded .76/.79
# "model-authored keywords" contract after .80 changes keyword ownership.



def _hd80_register_edit_tool(module) -> None:
    schema=_hd80_edit_schema()
    for array_name in ("_ONLINE_BOOK_RESPONSE_TOOLS","_ONLINE_EVIDENCE_RESPONSE_TOOLS"):
        arr=globals().get(array_name)
        if isinstance(arr,list):
            if not any(isinstance(x,dict) and str(x.get("name") or "")==_HD80_EDIT_TOOL for x in arr): arr.append(schema)
    if isinstance(globals().get("_ONLINE_MUTATING_TOOL_NAMES"),set): _ONLINE_MUTATING_TOOL_NAMES.add(_HD80_EDIT_TOOL)
    if isinstance(globals().get("_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS"),dict): _ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS[_HD80_EDIT_TOOL]=1200
    if isinstance(globals().get("_ADAPTIVE_TOOL_GROUPS"),dict):
        group=list(_ADAPTIVE_TOOL_GROUPS.get("books") or ())
        if _HD80_EDIT_TOOL not in group: group.append(_HD80_EDIT_TOOL)
        _ADAPTIVE_TOOL_GROUPS["books"]=tuple(group)
    if isinstance(getattr(module,"TOOL_SCHEMAS",None),list):
        local={"type":"function","function":{k:v for k,v in schema.items() if k not in {"type","strict"}}}
        if not any(isinstance(x,dict) and str((x.get("function") or {}).get("name") or "")==_HD80_EDIT_TOOL for x in module.TOOL_SCHEMAS): module.TOOL_SCHEMAS.append(local)


def _hd80_wrap_dispatchers(module) -> None:
    old_evidence=globals().get("_ora_execute_evidence_tool")
    if callable(old_evidence) and not getattr(old_evidence,"_hd80_wrapped",False):
        def execute_keyword_edit(mod,name,arguments):
            args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)==_HD80_EDIT_TOOL: return _ora_clean_result(mod,_hd80_revise_keywords(mod,str(args.get("rich_revision_id") or ""),args.get("keywords") or []))
            return old_evidence(mod,name,arguments)
        execute_keyword_edit._hd80_wrapped=True; globals()["_ora_execute_evidence_tool"]=execute_keyword_edit
    old_execute=getattr(module,"execute_tool",None)
    if callable(old_execute) and not getattr(old_execute,"_hd80_wrapped",False):
        def execute_local(name,arguments,seen,*args,**kwargs):
            tool_args=dict(arguments or {}) if isinstance(arguments,dict) else {}
            if str(name)==_HD80_EDIT_TOOL: return _hd80_revise_keywords(module,str(tool_args.get("rich_revision_id") or ""),tool_args.get("keywords") or [])
            return old_execute(name,arguments,seen,*args,**kwargs)
        execute_local._hd80_wrapped=True; module.execute_tool=execute_local


_HD80_BASE_FUSION_TEST=_deep_signpost_retrieval_fusion_self_test



_HD80_BASE_INSTALL_FUSION=_install_deep_signpost_retrieval_fusion

def _install_deep_signpost_retrieval_fusion(module) -> None:
    _HD80_BASE_INSTALL_FUSION(module)
    _hd80_register_edit_tool(module); _hd80_wrap_dispatchers(module)
    module.revise_rich_signpost_keywords=lambda rich_revision_id,keywords:_hd80_revise_keywords(module,rich_revision_id,keywords)
    module.distill_rich_signpost_keywords=lambda reference="all":_hd80_backfill_scope(module,reference)
    module.search_rich_signposts=lambda query,**kwargs:_hd79_search_rich_signposts(module,query,**kwargs)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_HD80_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nRICH KEYWORDS — EXACT SOURCE-WORD MEMBERSHIP\n"
          "- This supersedes earlier rich-keyword rules. Every current keyword must be one exact normalized Unicode word token present in that signpost's stored original source range. No synonym, paraphrase, conceptual substitute, or substring fragment may be inserted.\n"
          "- Python's initial 12-20-word distillation ranks only literal source tokens. Unicode source words stay whole under the shared lexical tokenizer.\n"
          "- Assistant may choose a different 12-20-word list, but revise_rich_signpost_keywords reopens the complete stored source range and mechanically rejects the entire revision if even one proposed word is absent. Python never invents replacements for an Assistant edit.\n"
          "- Pre-.84 current heads are mechanically audited on backfill/reflect; valid source-grounded choices are preserved, unsupported fragments/words are removed, and Python may fill only from literal source tokens to restore the 12-word minimum. All prior RSR revisions remain append-only history.\n"
          "- Keywords are navigation only. Exact original source remains evidence authority.\n")
    if "RICH KEYWORDS — EXACT SOURCE-WORD MEMBERSHIP" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule


# ---------------------------------------------------------------------------
# 7.4.78.86 MINIMAL ORIGINAL-WORD REFLECTION PROMPT RESET
# ---------------------------------------------------------------------------
# .84 over-corrected a simple wording requirement by adding a whole source-word
# integrity/audit layer to Assistant edits. .86 restores the proven .80-.83 edit
# contract: Python validates list mechanics and append-only lineage, while Assistant
# chooses the words. The reflection prompt now says plainly to COPY the 12-20
# keywords from the exact original source text she is shown. Python's automatic
# baseline still distills from original source text, using the newer Unicode-safe
# tokenizer. No source-word audit pass, automatic repair, or post-hoc semantic
# correction is performed on Assistant's list.

_HD86_VERSION = "1.0-minimal-original-word-prompt-reset"

# Use the pre-.84 backfill implementation. Because _hd80_distill_keywords is
# dynamically resolved, it retains the Unicode-safe source-token extraction added
# later; only the audit/repair wrapper is removed.
def _hd80_backfill_scope(module, reference: str="all") -> dict:
    out=dict(_HD84_BASE_BACKFILL_SCOPE(module,reference))
    out.pop("source_word_integrity",None)
    out.pop("source_word_membership_enforced",None)
    out["keyword_contract"]="12-20 words mechanically distilled by Python from exact original source text"
    out["authority"]="Python baseline keywords come from exact original source text; Assistant may later revise navigation wording. Original source remains evidence."
    return out


def _hd80_revise_keywords(module, rich_revision_id: str, keywords) -> dict:
    _hd_ensure_schema(); rid=str(rich_revision_id or "").strip(); clean,duplicates=_hd80_clean_user_keywords(keywords)
    if not rid:
        return {"ok":False,"operation":_HD80_EDIT_TOOL,"error":"rich_revision_id is required.","model_calls":0}
    if len(clean)<_HD80_MIN_KEYWORDS or len(clean)>_HD80_MAX_KEYWORDS:
        return {"ok":False,"operation":_HD80_EDIT_TOOL,"error":"Assistant must choose a final list containing 12 to 20 distinct single-word keywords.","keyword_count":len(clean),"contract_min":_HD80_MIN_KEYWORDS,"contract_max":_HD80_MAX_KEYWORDS,"duplicates_removed_for_validation":duplicates,"model_calls":0,"python_selected_replacements":False}
    with _sk_connect() as db:
        current_row=db.execute(f"SELECT * FROM {_HD76_REVISIONS_TABLE} WHERE rich_revision_id=?",(rid,)).fetchone()
        if not current_row:
            return {"ok":False,"operation":_HD80_EDIT_TOOL,"error":"No matching rich signpost revision exists.","rich_revision_id":rid,"model_calls":0}
        current=dict(current_row)
        head=db.execute(f"SELECT * FROM {_HD76_HEADS_TABLE} WHERE version_id=? AND node_type=? AND node_id=?",(current.get("version_id"),current.get("node_type"),current.get("node_id"))).fetchone()
        if not head or str(head["current_revision_id"] or "")!=rid:
            return {"ok":False,"operation":_HD80_EDIT_TOOL,"error":"The supplied revision is not the current head. Read the current rich signpost and decide again.","supplied_revision_id":rid,"current_revision_id":str(head["current_revision_id"] or "") if head else None,"model_calls":0,"stale_revision":True}
        before=_hd76_json(current.get("keywords_json"),[]); before_norm=[_hd77_keyword_norm(x) for x in before]
        db.execute("BEGIN IMMEDIATE")
        try:
            new_rid,record_sha=_hd80_clone_keyword_revision(db,current,clean,_sk_now()); db.commit()
        except Exception:
            db.rollback(); raise
    before_set=set(before_norm); after_set=set(clean)
    return {"ok":True,"operation":_HD80_EDIT_TOOL,"previous_revision_id":rid,"rich_revision_id":new_rid,"record_sha256":record_sha,"book_id":current.get("book_id"),"node_type":current.get("node_type"),"node_id":current.get("node_id"),"keywords":clean,"keyword_count":len(clean),"added":sorted(after_set-before_set),"removed":sorted(before_set-after_set),"contract_min":_HD80_MIN_KEYWORDS,"contract_max":_HD80_MAX_KEYWORDS,"revision_owner":"Assistant","previous_revision_preserved":True,"sql_index_updated":True,"source_text_modified":False,"model_calls":0,"python_selected_replacements":False,"authority":"Assistant-edited derived navigation only; exact original source remains evidence."}

# Clean the .84 status/tool surfaces so they describe the active .86 contract.
_HD86_BASE_SP_BUILD = _sp_build

def _sp_build(module, reference: str="all", *, reason: str="manual_backfill") -> dict:
    out=dict(_HD86_BASE_SP_BUILD(module,reference,reason=reason))
    out.pop("source_word_membership_enforced",None)
    if isinstance(out.get("python_keyword_backfill"),dict):
        out["python_keyword_backfill"].pop("source_word_integrity",None)
        out["python_keyword_backfill"].pop("source_word_membership_enforced",None)
        out["python_keyword_backfill"]["keyword_contract"]="12-20 words mechanically distilled by Python from exact original source text"
    out["keyword_contract"]="Python baseline: source-derived words; Assistant edit: 12-20 words she is instructed to copy exactly from original text"
    return out


