# retrieval/edit tests plus explicit .86 contract checks.
_HD86_BASE_FUSION_TEST = _HD80_BASE_FUSION_TEST

def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    module=module or _load_memory(); base=dict(_HD86_BASE_FUSION_TEST(module)); checks=dict(base.get("checks") or {}); details=dict(base.get("details") or {})
    import inspect as _hd86_inspect
    checks["python_baseline_keyword_distillation_reads_source"] = "_hd80_source_text" in _hd86_inspect.getsource(_hd_commit_staged) and "_hd80_distill_keywords" in _hd86_inspect.getsource(_hd_commit_staged)
    checks["assistant_keyword_revision_has_no_source_audit_layer"] = "_hd84_validate_keyword_membership" not in _hd86_inspect.getsource(_hd80_revise_keywords)
    checks["assistant_edit_still_append_only_and_mechanically_bounded"] = "12 to 20 distinct single-word keywords" in _hd86_inspect.getsource(getattr(_hd80_revise_keywords,"_bsc_base",_hd80_revise_keywords)) and "_hd80_clone_keyword_revision" in _hd86_inspect.getsource(getattr(_hd80_revise_keywords,"_bsc_base",_hd80_revise_keywords))
    checks["unicode_source_tokenizer_retained"] = "chüan" in set(_hd80_all_word_tokens("chüan")) and "ch" not in set(_hd80_all_word_tokens("chüan"))
    details["minimal_original_word_prompt_reset"]={"source_audit_removed":True,"python_baseline_source_derived":True,"assistant_semantic_choice_preserved":True}
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["version"]=_HD86_VERSION
    return base


# ---------------------------------------------------------------------------
# 7.4.78.122 RICH SIGNPOST EXACT-SOURCE LEXICAL STRENGTHS
# ---------------------------------------------------------------------------
# The existing rich-signpost keyword list remains the vocabulary. Python adds a
# deterministic 0..1 measurement of how strongly each exact source word is
# represented inside that signpost's original-source span. This is clerical
# navigation metadata only: it is NOT relevance, truth, confidence, importance,
# semantic weight, preference, or a ranking signal.

_KW122_VERSION = "1.0-rich-exact-source-lexical-presence"
_KW122_TABLE = "knowledge_rich_signpost_keyword_strengths"
_KW122_MEANING = "mechanical lexical presence in the exact original-source span; not relevance, truth, confidence, importance, semantic weight, or preference"


def _kw122_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _kw122_ensure_schema() -> None:
    if _nm_bootstrap_schema_skip("rich-keyword-strength-v122"):
        return
    _hd_ensure_schema()
    with _sk_connect() as db:
        db.execute(f"""CREATE TABLE IF NOT EXISTS {_KW122_TABLE}(
            rich_revision_id TEXT PRIMARY KEY,
            keywords_sha256 TEXT NOT NULL,
            exact_source_pointer_sha256 TEXT NOT NULL,
            source_sha256 TEXT NOT NULL,
            source_span_sha256 TEXT NOT NULL,
            strengths_json TEXT NOT NULL,
            strengths_sha256 TEXT NOT NULL,
            unsupported_keywords_json TEXT NOT NULL DEFAULT '[]',
            scoring_version TEXT NOT NULL,
            created_at TEXT NOT NULL
        )""")
        db.commit()
    _nm_bootstrap_schema_mark("rich-keyword-strength-v122")


def _kw122_book_profile(module, book_id: str) -> dict:
    """Canonical-book lexical profile. Exact tokens only; zero model/web calls."""
    bid=str(book_id or "").strip()
    if not bid:
        return {"ok":False,"book_id":bid,"chunks":{},"chunk_count":0,"document_frequency":{}}
    try:
        books=_kir_books_module(module)
        with books.connect() as db:
            cols={str(r[1]) for r in db.execute("PRAGMA table_info(book_chunks)").fetchall()}
            if not {"book_id","chunk_id","ordinal"}.issubset(cols):
                return {"ok":False,"book_id":bid,"chunks":{},"chunk_count":0,"document_frequency":{}}
            if "original_text" in cols and "text" in cols:
                source_expr="COALESCE(NULLIF(original_text,''),text,'')"
            elif "original_text" in cols:
                source_expr="COALESCE(original_text,'')"
            elif "text" in cols:
                source_expr="COALESCE(text,'')"
            else:
                return {"ok":False,"book_id":bid,"chunks":{},"chunk_count":0,"document_frequency":{}}
            rows=[dict(r) for r in db.execute(
                f"SELECT chunk_id,ordinal,{source_expr} source_text FROM book_chunks WHERE book_id=? ORDER BY ordinal,chunk_id",
                (bid,),
            ).fetchall()]
    except Exception as exc:
        return {"ok":False,"book_id":bid,"chunks":{},"chunk_count":0,"document_frequency":{},"error":str(exc)[:300]}
    chunks={}; df={}
    for row in rows:
        ordinal=int(row.get("ordinal") or 0); text=str(row.get("source_text") or "")
        tokens=_hd80_all_word_tokens(text)
        chunks[ordinal]={"chunk_id":str(row.get("chunk_id") or ""),"ordinal":ordinal,"text":text,"tokens":tokens}
        for token in set(tokens): df[token]=int(df.get(token,0))+1
    return {"ok":bool(rows),"book_id":bid,"chunks":chunks,"chunk_count":len(chunks),"document_frequency":df}


def _kw122_span_chunks(profile: dict, record: dict) -> list[dict]:
    try: start=int(record.get("start_ordinal")); end=int(record.get("end_ordinal"))
    except Exception: return []
    if start<1 or end<start: return []
    chunks=dict(profile.get("chunks") or {}); selected=[]
    start_char=_shn_int_or_none(record.get("start_char")); end_char=_shn_int_or_none(record.get("end_char"))
    for ordinal in range(start,end+1):
        base=chunks.get(ordinal)
        if not isinstance(base,dict): return []
        text=str(base.get("text") or "")
        left=max(0,min(len(text),int(start_char or 0))) if ordinal==start else 0
        right=max(left,min(len(text),int(end_char if end_char is not None else len(text)))) if ordinal==end else len(text)
        clipped=text[left:right]
        selected.append({"chunk_id":base.get("chunk_id"),"ordinal":ordinal,"text":clipped,"tokens":_hd80_all_word_tokens(clipped)})
    return selected


def _kw122_strength(*, count: int, total_tokens: int, local_chunk_hits: int, local_chunks: int, corpus_df: int, corpus_chunks: int) -> float:
    if count<=0 or total_tokens<=0: return 0.0
    frequency=1.0-math.exp(-float(count)/3.0)
    per_100=(float(count)*100.0)/max(1.0,float(total_tokens))
    density=1.0-math.exp(-per_100/2.0)
    distribution=max(0.0,min(1.0,float(local_chunk_hits)/max(1.0,float(local_chunks))))
    if corpus_chunks>1:
        numerator=math.log((float(corpus_chunks)+1.0)/(float(corpus_df)+1.0))
        denominator=max(1e-9,math.log(float(corpus_chunks)+1.0))
        distinctiveness=max(0.0,min(1.0,numerator/denominator))
    else:
        distinctiveness=0.5
    # Purely mechanical mixture; no semantic feature is present in this formula.
    score=0.25*frequency+0.20*density+0.10*distribution+0.45*distinctiveness
    return round(max(0.0,min(1.0,score)),4)



