def _kw122_self_test(module=None) -> dict:
    module=module or _load_memory(); checks={}; details={}; old_shared=os.getenv(_SHARED_KNOWLEDGE_DIR_ENV)
    try:
        with tempfile.TemporaryDirectory(prefix="neat-kw122-") as td:
            root=Path(td); os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=str(root/"shared")
            dbp=root/"book.db"; db=sqlite3.connect(dbp); db.row_factory=sqlite3.Row
            db.execute("CREATE TABLE book_chunks(book_id TEXT,chunk_id TEXT,ordinal INTEGER,original_text TEXT,text TEXT,original_text_hash TEXT,text_sha256 TEXT)")
            rows=[("BK-KW","C1",1,"fire fire wind discipline",None,"a"*64,"a"*64),("BK-KW","C2",2,"wind timing discipline discipline",None,"b"*64,"b"*64),("BK-KW","C3",3,"common common common",None,"c"*64,"c"*64)]
            db.executemany("INSERT INTO book_chunks VALUES(?,?,?,?,?,?,?)",rows); db.commit(); db.close()
            class Books:
                def connect(self):
                    conn=sqlite3.connect(dbp); conn.row_factory=sqlite3.Row; return conn
            fake=type("KWModule",(),{})(); fake.neatbooks=Books()
            pointer={"book_id":"BK-KW","start":{"chunk_id":"C1","ordinal":1,"char":0},"end":{"chunk_id":"C2","ordinal":2,"char":len("wind timing discipline discipline")},"source_sha256":"d"*64}
            current={"rich_revision_id":"RSR-KW122","book_id":"BK-KW","keywords_json":_sk_json(["fire","wind","discipline","timing"]),"exact_source_pointer_json":_sk_json(pointer),"exact_source_pointer_sha256":_sk_hash(_sk_json(pointer)),"source_sha256":"d"*64}
            first=_kw122_measure_rich_revision(fake,current); second=_kw122_measure_rich_revision(fake,current)
            strengths=dict(first.get("keyword_strengths") or {})
            checks["dictionary_keys_equal_existing_rich_keywords"]=list(strengths.keys())==["fire","wind","discipline","timing"]
            checks["scores_are_deterministic_and_bounded"]=strengths==dict(second.get("keyword_strengths") or {}) and all(0.0<=float(v)<=1.0 for v in strengths.values()) and second.get("cached") is True
            checks["all_test_keywords_are_exact_source_words"]=not first.get("unsupported_keywords")
            checks["source_span_hash_bound"]=bool(first.get("source_span_sha256")) and len(str(first.get("source_span_sha256")))==64
            checks["strength_is_navigation_only_and_not_ranking"]=first.get("affects_ranking") is False and first.get("meaning")==_KW122_MEANING
            checks["zero_model_and_web_calls"]=first.get("model_calls")==0 and first.get("web_calls")==0
            details["strengths"]=strengths
    finally:
        if old_shared is None: os.environ.pop(_SHARED_KNOWLEDGE_DIR_ENV,None)
        else: os.environ[_SHARED_KNOWLEDGE_DIR_ENV]=old_shared
    return {"ok":all(checks.values()),"checks":checks,"details":details,"version":_KW122_VERSION,"model_calls":0,"web_calls":0}


_KW122_BASE_FUSION_TEST=_deep_signpost_retrieval_fusion_self_test

def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    base=dict(_KW122_BASE_FUSION_TEST(module)); extra=_kw122_self_test(module); checks=dict(base.get("checks") or {}); checks.update({"kw122_"+k:v for k,v in (extra.get("checks") or {}).items()}); details=dict(base.get("details") or {}); details["keyword_strengths"]=extra.get("details")
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["keyword_strength_version"]=_KW122_VERSION
    return base


_KW122_BASE_INSTALL=_install_deep_signpost_retrieval_fusion

def _install_deep_signpost_retrieval_fusion(module) -> None:
    _KW122_BASE_INSTALL(module); _kw122_ensure_schema()
    module.read_rich_signpost=lambda node_id="",**kwargs:_hd76_read_rich_signpost(module,node_id,**kwargs)
    module.search_rich_signposts=lambda query,**kwargs:_hd79_search_rich_signposts(module,query,**kwargs)
    module.revise_rich_signpost_keywords=lambda rich_revision_id,keywords:_hd80_revise_keywords(module,rich_revision_id,keywords)
    module.rich_signpost_keyword_strengths=lambda rich_revision_id:_kw122_measure_rich_revision(module,_kw122_revision_row(rich_revision_id) or {})
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_KW122_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nRICH SIGNPOST KEYWORD STRENGTH — MECHANICAL PRESENCE ONLY\n"
          "- Rich signposts expose a dictionary mapping their existing exact-source keywords to deterministic 0..1 lexical-presence strengths. The score measures occurrence/density/distribution/book-distinctiveness only.\n"
          "- Keyword strength is navigation metadata, not relevance, truth, confidence, importance, semantic_weight, preference, or a recommendation. It does not alter ranking.\n"
          "- Exact original source remains authority. Use read_signpost_source before treating signpost navigation as evidence.\n")
    if "RICH SIGNPOST KEYWORD STRENGTH — MECHANICAL PRESENCE ONLY" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule



# ---------------------------------------------------------------------------
# 7.4.78.123 RICH SIGNPOST INSPECTABLE HEAD ENUMERATION
# ---------------------------------------------------------------------------
# Live .122 auditing exposed an inspectability gap rather than a scoring failure:
# search_rich_signposts could report that current rich heads existed (94 for the
# tested Art of War book) while returning zero candidates for a lexical miss, and
# the same tool rejected an empty query. Assistant therefore had no mechanical path to
# obtain a stable node_id / rich_revision_id before read_rich_signpost and
# read_signpost_source. .123 reuses the existing search_rich_signposts surface:
# when query is blank AND an explicit book scope is supplied, Python enumerates
# current rich heads in deterministic source order and returns directly actionable
# immutable IDs plus exact follow-up call arguments. This is bookkeeping only.
# It performs no lexical/semantic ranking, opens no source text, changes no .122
# strength score, and does not decide which head Assistant should inspect.

_ID123_VERSION = "1.0-rich-head-inspectable-enumeration"
_ID123_BASE_SEARCH_RICH = _hd79_search_rich_signposts
_ID123_BASE_FUSION_TEST = _deep_signpost_retrieval_fusion_self_test
_ID123_BASE_INSTALL = _install_deep_signpost_retrieval_fusion


def _id123_rows_for_version(version: dict) -> list[dict]:
    """Return current rich heads with only mechanical identity/navigation fields."""
    vid=str(version.get("version_id") or ""); bid=str(version.get("book_id") or "")
    if not vid or not bid: return []
    _hd_ensure_schema()
    with _sk_connect() as db:
        rows=[dict(x) for x in db.execute(f"""
            SELECT h.version_id,h.node_type,h.node_id,h.book_id,h.current_revision_id,
                   h.previous_revision_id,h.current_record_sha256,h.updated_at,
                   r.tiny_hint,r.record_sha256,r.provider,r.model,r.build_version
              FROM {_HD76_HEADS_TABLE} h
              JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=h.current_revision_id
             WHERE h.version_id=? AND h.book_id=?
        """,(vid,bid)).fetchall()]
    out=[]
    for row in rows:
        base=_sp_get(vid,str(row.get("node_type") or ""),str(row.get("node_id") or ""))
        item=dict(row)
        item["sequence_no"]=int((base or {}).get("sequence_no") or 0)
        item["node_kind"]=(base or {}).get("node_kind")
        item["title"]=(base or {}).get("title")
        out.append(item)
    out.sort(key=lambda x:(0 if int(x.get("sequence_no") or 0)>0 else 1,int(x.get("sequence_no") or 0) if int(x.get("sequence_no") or 0)>0 else 2**31,str(x.get("node_type") or ""),str(x.get("node_id") or "")))
    return out


def _id123_actionable_head(node: dict) -> dict:
    item=dict(node or {}); rid=str(item.get("rich_revision_id") or "").strip(); nid=str(item.get("node_id") or "").strip(); bid=str(item.get("book_id") or "").strip()
    if rid:
        item["rich_revision_id"]=rid
        item["inspect_rich_signpost"]={"tool":"read_rich_signpost","arguments":{"rich_revision_id":rid}}
        item["exact_source_exit"]={"tool":"read_signpost_source","arguments":{"rich_revision_id":rid}}
    elif nid:
        args={"node_id":nid}
        if bid: args["book_id"]=bid
        item["inspect_rich_signpost"]={"tool":"read_rich_signpost","arguments":args}
        item["exact_source_exit"]={"tool":"read_signpost_source","arguments":args}
    return item


def _id123_enumerate_rich_heads(module, *, reference: str="", book_ids=None, node_limit: int=6, book_scan_limit: int=100) -> dict:
    limit=max(1,min(16,int(node_limit or 6)))
    scope=_hd79_scope_versions(reference,book_ids,book_scan_limit)
    versions=list(scope.get("versions") or [])
    if not versions:
        return {"ok":False,"version":_ID123_VERSION,"operation":_HD79_SEARCH_TOOL,"mode":"MECHANICAL_HEAD_ENUMERATION","error":"Blank-query rich-head enumeration requires an explicit resolvable book reference or book_ids scope.","reference":str(reference or ""),"unresolved_book_references":list(scope.get("unresolved_book_references") or []),"rich_heads_seen":0,"returned":0,"nodes":[],"read_only":True,"model_calls":0,"web_calls":0,"source_spans_checked":0,"python_semantic_judgment":False}
    gathered=[]; total_heads=0
    for book_index,version in enumerate(versions):
        rows=_id123_rows_for_version(version); total_heads+=len(rows)
        for row in rows:
            nid=str(row.get("node_id") or ""); nt=str(row.get("node_type") or ""); rid=str(row.get("current_revision_id") or "")
            base=_sp_get(str(version.get("version_id") or ""),nt,nid)
            if base:
                node=_sp_route_node(dict(base),None)
            else:
                node={"node_id":nid,"node_type":nt,"sequence_no":int(row.get("sequence_no") or 0),"node_kind":row.get("node_kind"),"title":row.get("title")}
            card=dict(node.get("route_card") or {})
            card.update({"rich_signpost_available":True,"rich_revision_id":rid,"rich_record_sha256":row.get("current_record_sha256") or row.get("record_sha256"),"rich_detail_tool":"read_rich_signpost","preferred_exact_source_exit":"read_signpost_source","deep_signpost_is_navigation_only":True})
            node["route_card"]=card
            node.update({
                "book_id":str(version.get("book_id") or row.get("book_id") or ""),"book_title":str(version.get("title") or ""),"version_id":str(version.get("version_id") or row.get("version_id") or ""),
                "node_id":nid,"node_type":nt,"rich_revision_id":rid,"rich_record_sha256":row.get("current_record_sha256") or row.get("record_sha256"),
                "sequence_no":int(row.get("sequence_no") or node.get("sequence_no") or 0),"node_kind":row.get("node_kind") or node.get("node_kind"),"tiny_hint":str(row.get("tiny_hint") or ""),
                "match_mode":"python_sql_rich_head_enumeration","semantic_expansion_used":False,"source_text_opened_for_ranking":False,
            })
            node=_id123_actionable_head(node)
            gathered.append((book_index,0 if int(node.get("sequence_no") or 0)>0 else 1,int(node.get("sequence_no") or 0) if int(node.get("sequence_no") or 0)>0 else 2**31,str(nt),str(nid),node))
    gathered.sort(key=lambda x:x[:-1]); nodes=[x[-1] for x in gathered[:limit]]
    return {
        "ok":True,"version":_ID123_VERSION,"operation":_HD79_SEARCH_TOOL,"mode":"MECHANICAL_HEAD_ENUMERATION","query":"","query_terms":[],"reference":str(reference or ""),
        "books_in_scope":len(versions),"books_checked":len(versions),"book_scope_truncated":bool(scope.get("scope_truncated")),"unresolved_book_references":list(scope.get("unresolved_book_references") or []),
        "rich_heads_seen":total_heads,"returned":len(nodes),"nodes":nodes,"rich_only":True,"rich_keyword_sql_index_used":False,"legacy_signpost_fallback_used":False,"semantic_candidate_fallback_used":False,
        "enumeration_order":"book scope order, then canonical base-signpost sequence_no when available, then node_type/node_id; no lexical or semantic ranking",
        "stable_identity_exposed":True,"actionable_read_arguments_exposed":True,"keyword_strengths_included_in_enumeration":False,
        "preferred_detail_tool":"read_rich_signpost","preferred_exact_source_exit":"read_signpost_source","source_text_opened_for_ranking":False,"source_spans_checked":0,
        "model_calls":0,"web_calls":0,"python_semantic_judgment":False,"authority":"Current rich-head enumeration is mechanical navigation metadata only. Open read_rich_signpost for the weighted dictionary and read_signpost_source for exact evidence.","read_only":True,
    }


def _hd79_search_rich_signposts(module, query: str="", *, reference: str="", book_ids=None, node_limit: int=6, book_scan_limit: int=100) -> dict:
    terms=_smn_terms(query)
    if terms:
        out=dict(_ID123_BASE_SEARCH_RICH(module,query,reference=reference,book_ids=book_ids,node_limit=node_limit,book_scan_limit=book_scan_limit))
        out["mode"]="LEXICAL_SEARCH"
    else:
        if not str(reference or "").strip() and not (isinstance(book_ids,(list,tuple)) and any(str(x or "").strip() for x in book_ids)):
            return {"ok":False,"version":_ID123_VERSION,"operation":_HD79_SEARCH_TOOL,"mode":"MECHANICAL_HEAD_ENUMERATION","error":"Blank query is allowed only with an explicit book reference or book_ids scope; Python will not enumerate the whole library implicitly.","rich_heads_seen":0,"returned":0,"nodes":[],"read_only":True,"model_calls":0,"web_calls":0,"source_spans_checked":0,"python_semantic_judgment":False}
        out=_id123_enumerate_rich_heads(module,reference=reference,book_ids=book_ids,node_limit=node_limit,book_scan_limit=book_scan_limit)
    out["nodes"]=[_id123_actionable_head(x) for x in list(out.get("nodes") or [])]
    out["stable_identity_exposed"]=True
    out["actionable_read_arguments_exposed"]=True
    out["inspectability_version"]=_ID123_VERSION
    return out


def _hd79_search_schema() -> dict:
    return {"type":"function","name":_HD79_SEARCH_TOOL,"description":"Dedicated zero-model rich-signpost navigation over current heads. With a non-empty query it preserves the existing deterministic exact-token rich-keyword search. With query omitted/blank AND an explicit BK/source/title reference or book_ids scope, it mechanically enumerates current rich heads in source order so Assistant can obtain stable node_id/rich_revision_id values without guessing. Enumeration does not rank semantically, opens no source text, and returns directly usable read_rich_signpost and read_signpost_source arguments. Exact source remains evidence authority.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Optional. Non-empty performs lexical search; blank/omitted with explicit book scope enumerates current rich heads mechanically."},"reference":{"type":"string","description":"Optional exact book BK-ID, source ID, or exact title such as The Art of War. Required for blank-query enumeration unless book_ids is supplied."},"book_ids":{"type":"array","items":{"type":"string"},"maxItems":24},"node_limit":{"type":"integer","minimum":1,"maximum":16},"book_scan_limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False},"strict":False}


def _id123_self_test(module=None) -> dict:
    checks={}; details={}
    old_scope=globals().get("_hd79_scope_versions"); old_rows=globals().get("_id123_rows_for_version"); old_get=globals().get("_sp_get"); old_route=globals().get("_sp_route_node")
    try:
        globals()["_hd79_scope_versions"]=lambda reference="",book_ids=None,book_scan_limit=100:{"versions":[{"version_id":"VER-I123","book_id":"BK-I123","title":"Inspectability Test"}],"unresolved_book_references":[],"scope_truncated":False}
        globals()["_id123_rows_for_version"]=lambda version:[
            {"version_id":"VER-I123","book_id":"BK-I123","node_type":"semantic_unit","node_id":"N2","current_revision_id":"RSR-I123-B","current_record_sha256":"b"*64,"sequence_no":2,"node_kind":"concept","title":"Second","tiny_hint":"second"},
            {"version_id":"VER-I123","book_id":"BK-I123","node_type":"semantic_unit","node_id":"N1","current_revision_id":"RSR-I123-A","current_record_sha256":"a"*64,"sequence_no":1,"node_kind":"concept","title":"First","tiny_hint":"first"},
        ]
        globals()["_sp_get"]=lambda version_id,node_type,node_id:{"version_id":version_id,"node_type":node_type,"node_id":node_id,"sequence_no":1 if node_id=="N1" else 2,"node_kind":"concept","title":"First" if node_id=="N1" else "Second"}
        globals()["_sp_route_node"]=lambda record,candidate=None:{"node_id":record.get("node_id"),"node_type":record.get("node_type"),"sequence_no":record.get("sequence_no"),"node_kind":record.get("node_kind"),"title":record.get("title"),"route_card":{}}
        out=_id123_enumerate_rich_heads(object(),reference="BK-I123",node_limit=2)
        nodes=list(out.get("nodes") or [])
        checks["blank_scoped_enumeration_returns_stable_ids"]=bool(out.get("ok")) and [x.get("node_id") for x in nodes]==["N1","N2"] and [x.get("rich_revision_id") for x in nodes]==["RSR-I123-A","RSR-I123-B"]
        checks["enumeration_is_source_order_not_semantic_rank"]=out.get("mode")=="MECHANICAL_HEAD_ENUMERATION" and "no lexical or semantic ranking" in str(out.get("enumeration_order") or "")
        checks["direct_read_arguments_are_actionable"]=all(((x.get("inspect_rich_signpost") or {}).get("arguments") or {}).get("rich_revision_id")==x.get("rich_revision_id") and ((x.get("exact_source_exit") or {}).get("arguments") or {}).get("rich_revision_id")==x.get("rich_revision_id") for x in nodes)
        checks["enumeration_opens_no_source_or_model"]=out.get("source_spans_checked")==0 and out.get("model_calls")==0 and out.get("web_calls")==0
        no_scope=_hd79_search_rich_signposts(object(),"")
        checks["blank_unscoped_enumeration_fails_closed"]=no_scope.get("ok") is False and "whole library" in str(no_scope.get("error") or "")
        schema=_hd79_search_schema(); params=(schema.get("parameters") or {}); required=(params.get("required") or []); properties=(params.get("properties") or {})
        checks["existing_tool_accepts_blank_scoped_enumeration_without_new_command"]="query" not in required and "query" in properties and {"reference","book_ids"}.issubset(set(properties)) and str(schema.get("name") or "")==_HD79_SEARCH_TOOL
        details["enumeration"]={"returned":out.get("returned"),"ids":[{"node_id":x.get("node_id"),"rich_revision_id":x.get("rich_revision_id")} for x in nodes],"order":out.get("enumeration_order")}
    finally:
        if old_scope is not None: globals()["_hd79_scope_versions"]=old_scope
        if old_rows is not None: globals()["_id123_rows_for_version"]=old_rows
        if old_get is not None: globals()["_sp_get"]=old_get
        if old_route is not None: globals()["_sp_route_node"]=old_route
    return {"ok":all(checks.values()),"checks":checks,"details":details,"version":_ID123_VERSION}


def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    base=dict(_ID123_BASE_FUSION_TEST(module)); extra=_id123_self_test(module); checks=dict(base.get("checks") or {}); checks.update({"id123_"+k:v for k,v in (extra.get("checks") or {}).items()}); details=dict(base.get("details") or {}); details["inspectable_head_enumeration"]=extra.get("details")
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["inspectability_version"]=_ID123_VERSION
    return base


def _install_deep_signpost_retrieval_fusion(module) -> None:
    _ID123_BASE_INSTALL(module)
    _hd79_register_tool(module)
    module.search_rich_signposts=lambda query="",**kwargs:_hd79_search_rich_signposts(module,query,**kwargs)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_ID123_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nRICH SIGNPOST INSPECTABILITY — STABLE HEAD ENUMERATION\n"
          "- If a scoped rich-keyword search returns no candidate but current rich heads exist, you may call search_rich_signposts again with a blank query and the exact book scope to enumerate current heads mechanically.\n"
          "- Enumeration returns stable node_id/rich_revision_id values and exact follow-up arguments for read_rich_signpost and read_signpost_source. Python orders by stored source sequence only; it does not choose which head matters.\n"
          "- Open read_rich_signpost to inspect the weighted dictionary, then read_signpost_source for exact evidence. Enumeration and weights remain navigation only.\n")
    if "RICH SIGNPOST INSPECTABILITY — STABLE HEAD ENUMERATION" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule

# ---------------------------------------------------------------------------
# 7.4.78.125 COMPLETE SIGNPOST SOURCE SPAN + AUDITABLE LEXICAL COMPONENTS
# ---------------------------------------------------------------------------
# Live .124 Art of War auditing proved inspection visibility, then exposed the
# remaining mechanical mismatch: .122 computes lexical strengths over the complete
# immutable rich-signpost source range, while read_signpost_source defaulted to the
# first ordinal only. Assistant therefore could see a correct pointer path but not the
# complete evidence span used by the score. .125 makes the default exact-source exit
# return the whole stored signpost range (respecting first/last character bounds);
# an explicit ordinal still requests one chunk for backwards-compatible targeted
# inspection. The scoring formula itself is unchanged. read_rich_signpost now also
# exposes the raw/normalized frequency, density, distribution, book distinctiveness,
# and formula/version used for every visible strength. These are inspectable lexical
# mechanics only and do not affect ranking, relevance, sufficiency, truth, or meaning.

_LS125_VERSION = "1.0-complete-span-auditable-lexical-components"
_LS125_FORMULA_VERSION = "lexical_presence_formula_v1"
_LS125_FORMULA = {
    "version": _LS125_FORMULA_VERSION,
    "expression": "0.25*frequency + 0.20*density + 0.10*distribution + 0.45*distinctiveness",
    "coefficients": {"frequency":0.25,"density":0.20,"distribution":0.10,"distinctiveness":0.45},
    "frequency": "1-exp(-occurrences/3)",
    "density": "1-exp(-(occurrences_per_100_tokens)/2)",
    "distribution": "chunks_with_keyword/span_chunks",
    "distinctiveness": "log((book_chunks+1)/(book_document_frequency+1))/log(book_chunks+1); 0.5 when book_chunks<=1",
    "meaning": _KW122_MEANING,
    "affects_ranking": False,
}

_LS125_BASE_KW_SCHEMA = _kw122_ensure_schema

def _kw122_ensure_schema() -> None:
    if _nm_bootstrap_schema_skip("rich-keyword-components-v125"):
        return
    _LS125_BASE_KW_SCHEMA()
    with _sk_connect() as db:
        cols={str(r[1]) for r in db.execute(f"PRAGMA table_info({_KW122_TABLE})").fetchall()}
        if "components_json" not in cols:
            db.execute(f"ALTER TABLE {_KW122_TABLE} ADD COLUMN components_json TEXT NOT NULL DEFAULT '{{}}'")
        if "components_sha256" not in cols:
            db.execute(f"ALTER TABLE {_KW122_TABLE} ADD COLUMN components_sha256 TEXT NOT NULL DEFAULT ''")
        if "formula_version" not in cols:
            db.execute(f"ALTER TABLE {_KW122_TABLE} ADD COLUMN formula_version TEXT NOT NULL DEFAULT ''")
        db.commit()
    _nm_bootstrap_schema_mark("rich-keyword-components-v125")


def _ls125_word_components(*, count: int, total_tokens: int, local_chunk_hits: int, local_chunks: int, corpus_df: int, corpus_chunks: int) -> dict:
    occurrences=max(0,int(count or 0)); span_tokens=max(0,int(total_tokens or 0)); hit_chunks=max(0,int(local_chunk_hits or 0)); span_chunks=max(0,int(local_chunks or 0)); book_df=max(0,int(corpus_df or 0)); book_chunks=max(0,int(corpus_chunks or 0))
    if occurrences<=0 or span_tokens<=0:
        frequency=0.0; per_100=0.0; density=0.0; distribution=0.0
    else:
        frequency=1.0-math.exp(-float(occurrences)/3.0)
        per_100=(float(occurrences)*100.0)/max(1.0,float(span_tokens))
        density=1.0-math.exp(-per_100/2.0)
        distribution=max(0.0,min(1.0,float(hit_chunks)/max(1.0,float(span_chunks))))
    if book_chunks>1:
        numerator=math.log((float(book_chunks)+1.0)/(float(book_df)+1.0))
        denominator=max(1e-9,math.log(float(book_chunks)+1.0))
        distinctiveness=max(0.0,min(1.0,numerator/denominator))
    else:
        distinctiveness=0.5
    strength=_kw122_strength(count=occurrences,total_tokens=span_tokens,local_chunk_hits=hit_chunks,local_chunks=span_chunks,corpus_df=book_df,corpus_chunks=book_chunks)
    return {
        "strength":float(strength),
        "occurrences":occurrences,
        "span_tokens":span_tokens,
        "frequency":round(float(frequency),6),
        "occurrences_per_100_tokens":round(float(per_100),6),
        "density":round(float(density),6),
        "chunks_with_keyword":hit_chunks,
        "span_chunks":span_chunks,
        "distribution":round(float(distribution),6),
        "book_document_frequency":book_df,
        "book_chunks":book_chunks,
        "distinctiveness":round(float(distinctiveness),6),
        "formula_version":_LS125_FORMULA_VERSION,
    }


def _kw122_measure_word(profile: dict, span_chunks: list[dict], word: str) -> dict:
    terms=_hd80_all_word_tokens(word)
    if len(terms)!=1:
        components=_ls125_word_components(count=0,total_tokens=0,local_chunk_hits=0,local_chunks=len(span_chunks),corpus_df=0,corpus_chunks=int(profile.get("chunk_count") or 0))
        return {"present":False,"strength":0.0,"count":0,"local_chunk_hits":0,"corpus_df":0,"components":components}
    token=terms[0]; count=0; local_hits=0
    for chunk in span_chunks:
        hits=sum(1 for x in list(chunk.get("tokens") or []) if x==token)
        count+=hits; local_hits+=int(hits>0)
    total_tokens=sum(len(chunk.get("tokens") or []) for chunk in span_chunks)
    df=int((profile.get("document_frequency") or {}).get(token,0)); n=int(profile.get("chunk_count") or 0)
    components=_ls125_word_components(count=count,total_tokens=total_tokens,local_chunk_hits=local_hits,local_chunks=len(span_chunks),corpus_df=df,corpus_chunks=n)
    return {"present":count>0,"strength":float(components.get("strength") or 0.0),"count":count,"local_chunk_hits":local_hits,"corpus_df":df,"components":components}


def _kw122_measure_rich_revision(module, current: dict) -> dict:
    _kw122_ensure_schema()
    rid=str(current.get("rich_revision_id") or ""); keywords=list(_hd76_json(current.get("keywords_json"),[]) or []); keywords=[str(x) for x in keywords if str(x)]
    kw_sha=_sk_hash(_kw122_json(keywords)); ptr_sha=str(current.get("exact_source_pointer_sha256") or ""); source_sha=str(current.get("source_sha256") or "")
    with _sk_connect() as db:
        cached=db.execute(f"SELECT * FROM {_KW122_TABLE} WHERE rich_revision_id=?",(rid,)).fetchone()
    if cached:
        row=dict(cached)
        cache_matches=(str(row.get("keywords_sha256") or "")==kw_sha and str(row.get("exact_source_pointer_sha256") or "")==ptr_sha and str(row.get("source_sha256") or "")==source_sha and str(row.get("scoring_version") or "")==_KW122_VERSION)
        components=_hd76_json(row.get("components_json"),{}) if cache_matches else {}
        if cache_matches and isinstance(components,dict) and components and str(row.get("formula_version") or "")==_LS125_FORMULA_VERSION:
            return {"ok":True,"rich_revision_id":rid,"keyword_strengths":_hd76_json(row.get("strengths_json"),{}),"keyword_strength_components":components,"keyword_strength_formula":dict(_LS125_FORMULA),"unsupported_keywords":_hd76_json(row.get("unsupported_keywords_json"),[]),"source_span_sha256":row.get("source_span_sha256"),"strengths_sha256":row.get("strengths_sha256"),"components_sha256":row.get("components_sha256"),"version":_KW122_VERSION,"inspectability_version":_LS125_VERSION,"formula_version":_LS125_FORMULA_VERSION,"meaning":_KW122_MEANING,"cached":True,"model_calls":0,"web_calls":0,"affects_ranking":False}
    record=_hd84_source_record_from_revision(current); profile=_kw122_book_profile(module,str(current.get("book_id") or ""))
    if not profile.get("ok"):
        return {"ok":False,"rich_revision_id":rid,"error":profile.get("error") or "canonical book profile unavailable","keyword_strengths":{},"keyword_strength_components":{},"keyword_strength_formula":dict(_LS125_FORMULA),"unsupported_keywords":keywords,"version":_KW122_VERSION,"inspectability_version":_LS125_VERSION,"formula_version":_LS125_FORMULA_VERSION,"meaning":_KW122_MEANING,"model_calls":0,"web_calls":0,"affects_ranking":False}
    span=_kw122_span_chunks(profile,record)
