def _hd78_read_signpost_source(module, rich_revision_id: str="", *, node_id: str="", book_id: str="", ordinal=None) -> dict:
    # Explicit ordinal preserves the established one-chunk targeted-read contract.
    if ordinal is not None:
        out=dict(_LS125_BASE_READ_SOURCE(module,rich_revision_id,node_id=node_id,book_id=book_id,ordinal=ordinal))
        out["complete_span_default_version"]=_LS125_VERSION
        out["read_mode"]="EXPLICIT_SINGLE_ORDINAL"
        return out
    record,pointer,error=_hd78_source_record(rich_revision_id=rich_revision_id,node_id=node_id,book_id=book_id)
    if error:
        return {"ok":False,"error":error,"rich_revision_id":str(rich_revision_id or "") or None,"node_id":str(node_id or "") or None,"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    start=dict(pointer.get("start") or {}); end=dict(pointer.get("end") or {})
    try: start_ord=int(start.get("ordinal")); end_ord=int(end.get("ordinal"))
    except Exception:
        return {"ok":False,"error":"Exact-source pointer has invalid ordinal bounds.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    if start_ord<1 or end_ord<start_ord:
        return {"ok":False,"error":"Exact-source pointer has invalid ordinal bounds.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    books=getattr(module,"neatbooks",None)
    if books is None or not callable(getattr(books,"read_book_chunks",None)):
        return {"ok":False,"error":"NeatBooks exact-source reader is unavailable.","rich_revision_id":record.get("rich_revision_id"),"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    pointer_bid=str(pointer.get("book_id") or "").strip()
    try:
        canonical=str(books.resolve_book_reference(pointer_bid) if callable(getattr(books,"resolve_book_reference",None)) else pointer_bid)
    except Exception as exc:
        return {"ok":False,"error":f"Stored signpost book pointer could not be resolved: {type(exc).__name__}: {exc}","rich_revision_id":record.get("rich_revision_id"),"stored_book_id":pointer_bid,"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    try:
        rows=_kir_chunk_rows_for_range(module,canonical,start_ord,end_ord)
    except Exception as exc:
        return {"ok":False,"error":f"Exact signpost-source span read failed: {type(exc).__name__}: {exc}","rich_revision_id":record.get("rich_revision_id"),"stored_book_id":pointer_bid,"canonical_book_id":canonical,"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    by_ord={int(r.get("ordinal") or 0):dict(r) for r in rows}; expected=list(range(start_ord,end_ord+1))
    if any(o not in by_ord for o in expected):
        return {"ok":False,"error":"Exact source range is incomplete; Python will not label a partial span complete.","rich_revision_id":record.get("rich_revision_id"),"stored_book_id":pointer_bid,"canonical_book_id":canonical,"pointer_hash_valid":True,"expected_ordinals":expected,"returned_ordinals":sorted(by_ord),"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    start_chunk_id=str(start.get("chunk_id") or ""); end_chunk_id=str(end.get("chunk_id") or "")
    if start_chunk_id and str(by_ord[start_ord].get("chunk_id") or "")!=start_chunk_id:
        return {"ok":False,"error":"Exact source start chunk does not match the immutable signpost pointer.","rich_revision_id":record.get("rich_revision_id"),"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    if end_chunk_id and str(by_ord[end_ord].get("chunk_id") or "")!=end_chunk_id:
        return {"ok":False,"error":"Exact source end chunk does not match the immutable signpost pointer.","rich_revision_id":record.get("rich_revision_id"),"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0,"complete_span_default_version":_LS125_VERSION}
    start_char=_shn_int_or_none(start.get("char")); end_char=_shn_int_or_none(end.get("char")); exact_chunks=[]; span_parts=[]
    for o in expected:
        row=dict(by_ord[o]); raw=str(row.get("text") or row.get("original_text") or "")
        left=max(0,min(len(raw),int(start_char or 0))) if o==start_ord else 0
        right=max(left,min(len(raw),int(end_char if end_char is not None else len(raw)))) if o==end_ord else len(raw)
        bounded=raw[left:right]; item=dict(row)
        item["text"]=bounded; item["returned_start_char"]=left; item["returned_end_char"]=right; item["returned_text_sha256"]=hashlib.sha256(bounded.encode("utf-8")).hexdigest(); item["exact_signpost_span_fragment"]=True
        exact_chunks.append(item); span_parts.append(bounded)
    span_text="\n".join(span_parts); span_sha=hashlib.sha256(span_text.encode("utf-8")).hexdigest()
    raw_result={"ok":True,"book_id":canonical,"book":{"book_id":canonical},"chunks":exact_chunks}
    try: _bni_observe_read_result(module,raw_result,trigger=_HD78_SOURCE_TOOL)
    except Exception: pass
    out={
        "ok":True,"book_id":canonical,"book":{"book_id":canonical},"chunks":exact_chunks,
        "read_only":True,"model_calls":0,"web_calls":0,"rich_revision_id":record.get("rich_revision_id"),"node_id":record.get("node_id"),"node_type":record.get("node_type"),
        "stored_book_id":pointer_bid,"canonical_book_id":canonical,"pointer_hash_valid":True,"exact_source_pointer_sha256":record.get("exact_source_pointer_sha256"),
        "signpost_source_range":{"start":start,"end":end,"source_sha256":pointer.get("source_sha256"),"authority":pointer.get("authority")},
        "requested_ordinal":None,"range_start_ordinal":start_ord,"range_end_ordinal":end_ord,"returned_ordinals":expected,"range_chunk_count":len(expected),"range_complete_in_this_read":True,
        "lexical_measurement_span_sha256":span_sha,"lexical_measurement_span_join":"newline between exact clipped chunks","complete_span_default_version":_LS125_VERSION,"read_mode":"COMPLETE_SIGNPOST_SPAN",
        "next_ordinal":None,"previous_ordinal":None,
        "source_authority":"Complete exact original NeatBooks signpost span returned through an immutable rich-signpost pointer; first/last character bounds are enforced and signpost semantics remain navigation only.",
        "python_semantic_judgment":False,
    }
    return _ora_clean_result(module,out) if callable(globals().get("_ora_clean_result")) else out


def _hd78_tool_schema() -> dict:
    return {"type":"function","name":_HD78_SOURCE_TOOL,"description":"Open the complete exact original NeatBooks source span behind a rich signpost by following its immutable pointer. By default Python returns every ordinal in the stored range with exact first/last character bounds. Supply ordinal only for a targeted single-chunk read inside that range. Python verifies pointer/range identity and performs no semantic judgment; exact original source remains authority.","parameters":{"type":"object","properties":{"rich_revision_id":{"type":"string"},"node_id":{"type":"string"},"book_id":{"type":"string"},"ordinal":{"type":"integer","minimum":1,"description":"Optional targeted single ordinal. Omit to return the complete immutable signpost span."}},"additionalProperties":False},"strict":False}


_LS125_BASE_FUSION_TEST = _deep_signpost_retrieval_fusion_self_test
_LS125_BASE_INSTALL = _install_deep_signpost_retrieval_fusion


def _ls125_self_test(module=None) -> dict:
    checks={}; details={}
    profile={"chunk_count":10,"document_frequency":{"fire":2}}
    span=[{"tokens":["fire","fire","wind"]},{"tokens":["war","fire"]}]
    stat=_kw122_measure_word(profile,span,"fire"); comp=dict(stat.get("components") or {})
    checks["formula_components_exposed"] = all(k in comp for k in ("occurrences","frequency","density","distribution","distinctiveness","formula_version"))
    checks["formula_version_and_score_match"] = comp.get("formula_version")==_LS125_FORMULA_VERSION and float(comp.get("strength") or 0.0)==float(stat.get("strength") or 0.0)
    checks["formula_does_not_affect_ranking"] = _LS125_FORMULA.get("affects_ranking") is False and "not relevance" in str(_LS125_FORMULA.get("meaning") or "")
    old_source=globals().get("_hd78_source_record"); old_rows=globals().get("_kir_chunk_rows_for_range"); old_clean=globals().get("_ora_clean_result"); old_observe=globals().get("_bni_observe_read_result")
    try:
        pointer={"book_id":"BK-LS125","start":{"chunk_id":"C1","ordinal":1,"char":2},"end":{"chunk_id":"C2","ordinal":2,"char":3},"source_sha256":"s"*64,"authority":"original"}
        record={"rich_revision_id":"RSR-LS125","node_id":"N-LS125","node_type":"semantic_unit","exact_source_pointer_sha256":"p"*64}
        globals()["_hd78_source_record"]=lambda **kwargs:(record,pointer,None)
        globals()["_kir_chunk_rows_for_range"]=lambda module,book_id,start,end:[{"book_id":book_id,"chunk_id":"C1","ordinal":1,"text":"XXfire wind"},{"book_id":book_id,"chunk_id":"C2","ordinal":2,"text":"warYY"}]
        globals()["_ora_clean_result"]=lambda module,value:value
        globals()["_bni_observe_read_result"]=lambda *args,**kwargs:None
        class Books:
            @staticmethod
            def resolve_book_reference(book_id): return book_id
            @staticmethod
            def read_book_chunks(book_id,start=1,count=1): return {"ok":True,"book_id":book_id,"chunks":[{"book_id":book_id,"chunk_id":"C1" if int(start)==1 else "C2","ordinal":int(start),"text":"single"}]}
        fake=type("LS125Module",(),{})(); fake.neatbooks=Books()
        full=_hd78_read_signpost_source(fake,"RSR-LS125")
        chunks=list(full.get("chunks") or [])
        checks["default_read_returns_complete_multichunk_span"] = full.get("ok") is True and full.get("read_mode")=="COMPLETE_SIGNPOST_SPAN" and full.get("range_complete_in_this_read") is True and [x.get("text") for x in chunks]==["fire wind","war"] and full.get("returned_ordinals")==[1,2]
        expected_sha=hashlib.sha256("fire wind\nwar".encode("utf-8")).hexdigest()
        checks["visible_span_hash_matches_weight_span_convention"] = full.get("lexical_measurement_span_sha256")==expected_sha
        single=_hd78_read_signpost_source(fake,"RSR-LS125",ordinal=1)
        checks["explicit_ordinal_preserves_targeted_single_read"] = single.get("read_mode")=="EXPLICIT_SINGLE_ORDINAL" and single.get("requested_ordinal")==1
        details["complete_span"]={"texts":[x.get("text") for x in chunks],"sha256":full.get("lexical_measurement_span_sha256")}
        details["components"]=comp
    finally:
        if old_source is not None: globals()["_hd78_source_record"]=old_source
        if old_rows is not None: globals()["_kir_chunk_rows_for_range"]=old_rows
        if old_clean is not None: globals()["_ora_clean_result"]=old_clean
        if old_observe is not None: globals()["_bni_observe_read_result"]=old_observe
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"details":details,"version":_LS125_VERSION}


def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    base=dict(_LS125_BASE_FUSION_TEST(module)); extra=_ls125_self_test(module); checks=dict(base.get("checks") or {})
    # .125 intentionally supersedes the .78 progressive-default assertions: default
    # now returns the complete immutable span; explicit ordinal preserves targeted reads.
    checks.pop("rich_pointer_exact_source_exit_avoids_identifier_reconstruction",None)
    checks.pop("signpost_source_exit_is_range_bounded_and_progressive",None)
    checks.update({"ls125_"+k:v for k,v in (extra.get("checks") or {}).items()}); details=dict(base.get("details") or {}); details["complete_span_auditable_lexical_components"]=extra.get("details")
    details["superseded_checks"]=["rich_pointer_exact_source_exit_avoids_identifier_reconstruction","signpost_source_exit_is_range_bounded_and_progressive"]
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["lexical_inspectability_version"]=_LS125_VERSION
    return base


def _install_deep_signpost_retrieval_fusion(module) -> None:
    _LS125_BASE_INSTALL(module)
    _kw122_ensure_schema()
    _hd79_register_tool(module)
    module.read_rich_signpost=lambda node_id="",**kwargs:_hd76_read_rich_signpost(module,node_id,**kwargs)
    module.read_signpost_source=lambda rich_revision_id="",**kwargs:_hd78_read_signpost_source(module,rich_revision_id,**kwargs)
    module.search_rich_signposts=lambda query="",**kwargs:_hd79_search_rich_signposts(module,query,**kwargs)
    module.rich_signpost_keyword_strengths=lambda rich_revision_id:_kw122_measure_rich_revision(module,_kw122_revision_row(rich_revision_id) or {})
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_LS125_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nRICH SIGNPOST COMPLETE-SPAN AUDITABILITY\n"
          "- read_signpost_source returns the complete immutable signpost source span by default, including every stored ordinal and exact first/last character bounds. Supply ordinal only when you explicitly want one targeted chunk.\n"
          "- read_rich_signpost exposes each lexical strength together with frequency, density, distribution, book distinctiveness, and the unchanged formula/version. These values explain mechanical lexical presence only and do not alter ranking or semantic judgment.\n"
          "- Compare keyword_strength_source_span_sha256 with lexical_measurement_span_sha256 when auditing that the visible exact span is the same span measured for lexical strengths.\n")
    if "RICH SIGNPOST COMPLETE-SPAN AUDITABILITY" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule



# ---------------------------------------------------------------------------
# 7.4.78.126 VERIFIED SIGNPOST SOURCE CONTINUATION
# ---------------------------------------------------------------------------
# The live .125 Art of War audit proved that score explainability is now visible,
# but it also exposed a transport mismatch: .125 correctly assembled the complete
# exact signpost span, yet a ~74k-token result exceeded the ordinary ~24k tool-loop
# admission cap and was therefore withheld whole. Assistant then fell back to explicit
# single-ordinal reads and could not honestly claim complete-span coverage.
#
# .126 keeps the source pointer, lexical formula, capsule authority, and no-silent-
# truncation rule unchanged. Instead, the existing read_signpost_source tool now
# returns a deterministic bounded page when the exact span cannot fit comfortably in
# one tool result. Each page contains only exact source fragments, plus a hash-bound
# opaque cursor and ready-to-use next call. Following the returned cursor chain from
# page 1 to the final page mechanically proves complete byte/character coverage of
# the immutable pointed-to span. Python does not summarize, choose, rank, or omit
# semantically; pagination is purely transport bookkeeping. Explicit ordinal reads
# retain their targeted single-chunk behavior.

_LS126_VERSION = "1.0-verified-signpost-span-continuation"
_LS126_CURSOR_VERSION = "signpost-source-cursor-v1"
_LS126_PAGE_TEXT_TARGET_TOKENS = 8000
_LS126_BASE_READ_SOURCE = _hd78_read_signpost_source
_LS126_BASE_SOURCE_SCHEMA = _hd78_tool_schema
_LS126_BASE_FUSION_TEST = _deep_signpost_retrieval_fusion_self_test
_LS126_BASE_INSTALL = _install_deep_signpost_retrieval_fusion


def _ls126_cursor_encode(payload: dict) -> str:
    body=dict(payload or {})
    body["version"]=_LS126_CURSOR_VERSION
    raw=_sk_json(body).encode("utf-8")
    digest=hashlib.sha256(b"LS126|"+raw).hexdigest()
    token=base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")
    return token+"."+digest


def _ls126_cursor_decode(token: str) -> dict:
    text=str(token or "").strip()
    if not text or "." not in text:
        raise ValueError("Missing or invalid signpost-source continuation cursor.")
    enc,digest=text.rsplit(".",1)
    padded=enc+"="*((4-len(enc)%4)%4)
    try:
        raw=base64.urlsafe_b64decode(padded.encode("ascii"))
        data=json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise ValueError("Invalid signpost-source continuation cursor encoding.") from exc
    if not isinstance(data,dict) or str(data.get("version") or "")!=_LS126_CURSOR_VERSION:
        raise ValueError("Unsupported signpost-source continuation cursor version.")
    expected=hashlib.sha256(b"LS126|"+raw).hexdigest()
    if not hmac.compare_digest(str(digest or ""),expected):
        raise ValueError("Signpost-source continuation cursor integrity check failed.")
    return data


def _ls126_estimate_tokens(module, text: str) -> int:
    fn=globals().get("_ora_estimate_text_tokens")
    if callable(fn):
        try: return max(0,int(fn(module,str(text or ""))))
        except Exception: pass
    return max(1,(len(str(text or ""))+2)//3)


def _ls126_take_prefix(module, text: str, budget_tokens: int) -> int:
    value=str(text or "")
    budget=max(1,int(budget_tokens or 1))
    if not value: return 0
    if _ls126_estimate_tokens(module,value)<=budget: return len(value)
    lo,hi=1,len(value)
    best=1
    while lo<=hi:
        mid=(lo+hi)//2
        if _ls126_estimate_tokens(module,value[:mid])<=budget:
            best=mid; lo=mid+1
        else:
            hi=mid-1
    return max(1,best)


def _ls126_fragment_metadata(chunk: dict, text: str, rel_start: int, rel_end: int) -> dict:
    # Keep exact provenance/mechanical metadata while never duplicating hidden/full
    # source-text fields beside the returned page fragment.
    item={}
    for key,value in dict(chunk or {}).items():
        if key in {"text","original_text","source_text","clean_text","content"}: continue
        item[key]=value
    base_start=int(chunk.get("returned_start_char") or 0)
    item["text"]=str(text or "")
    item["page_fragment_start_char"]=base_start+int(rel_start)
    item["page_fragment_end_char"]=base_start+int(rel_end)
    item["page_fragment_sha256"]=hashlib.sha256(str(text or "").encode("utf-8")).hexdigest()
    item["exact_signpost_span_fragment"]=True
    item["fragment_complete_for_returned_chunk"]=(int(rel_start)==0 and int(rel_end)==len(str(chunk.get("text") or "")))
    return item


def _ls126_page_complete_result(module, full: dict, *, cursor: str="", target_tokens: int|None=None) -> dict:
    if not isinstance(full,dict) or not full.get("ok"):
        return dict(full or {})
    chunks=[dict(x) for x in list(full.get("chunks") or []) if isinstance(x,dict)]
    rid=str(full.get("rich_revision_id") or "")
    ptr_sha=str(full.get("exact_source_pointer_sha256") or "")
    span_sha=str(full.get("lexical_measurement_span_sha256") or "")
    if not chunks:
        out=dict(full); out.update({"continuation_version":_LS126_VERSION,"continuation_required":False,"range_complete_across_continuation":True,"continuation_page":1,"continuation_pages_seen":1}); return out
    if cursor:
        try: state=_ls126_cursor_decode(cursor)
        except Exception as exc:
            return {"ok":False,"error":str(exc),"rich_revision_id":rid or None,"read_only":True,"model_calls":0,"web_calls":0,"continuation_version":_LS126_VERSION}
        if str(state.get("rich_revision_id") or "")!=rid or str(state.get("exact_source_pointer_sha256") or "")!=ptr_sha or str(state.get("span_sha256") or "")!=span_sha:
            return {"ok":False,"error":"Continuation cursor no longer matches the immutable signpost/source span.","rich_revision_id":rid or None,"pointer_hash_valid":True,"read_only":True,"model_calls":0,"web_calls":0,"continuation_version":_LS126_VERSION}
        idx=max(0,int(state.get("chunk_index") or 0)); offset=max(0,int(state.get("chunk_offset") or 0)); page_no=max(1,int(state.get("page_no") or 2)); prior_chain=str(state.get("coverage_chain_sha256") or "0"*64); coverage_from_start=bool(state.get("coverage_from_start"))
    else:
        idx=0; offset=0; page_no=1; prior_chain="0"*64; coverage_from_start=True
    if idx>len(chunks):
        return {"ok":False,"error":"Continuation cursor points outside the signpost source span.","rich_revision_id":rid or None,"read_only":True,"model_calls":0,"web_calls":0,"continuation_version":_LS126_VERSION}
    text_target=max(1000,int(target_tokens or _LS126_PAGE_TEXT_TARGET_TOKENS)); used=0; fragments=[]; manifest=[]
    cur_idx=idx; cur_offset=offset
    while cur_idx < len(chunks) and used < text_target:
        chunk=chunks[cur_idx]; raw=str(chunk.get("text") or "")
        cur_offset=max(0,min(len(raw),cur_offset)); remaining=raw[cur_offset:]
        if not remaining:
            cur_idx+=1; cur_offset=0; continue
        available=max(1,text_target-used)
        take=_ls126_take_prefix(module,remaining,available)
        piece=remaining[:take]; rel_start=cur_offset; rel_end=cur_offset+take
        fragments.append(_ls126_fragment_metadata(chunk,piece,rel_start,rel_end))
        manifest.append({"ordinal":int(chunk.get("ordinal") or 0),"chunk_id":str(chunk.get("chunk_id") or ""),"start_char":int((chunk.get("returned_start_char") or 0)+rel_start),"end_char":int((chunk.get("returned_start_char") or 0)+rel_end),"text_sha256":hashlib.sha256(piece.encode("utf-8")).hexdigest()})
        used+=_ls126_estimate_tokens(module,piece)
        if rel_end>=len(raw):
            cur_idx+=1; cur_offset=0
        else:
            cur_offset=rel_end; break
    complete=(cur_idx>=len(chunks))
    page_manifest_sha=hashlib.sha256(_sk_json(manifest).encode("utf-8")).hexdigest()
    chain_sha=hashlib.sha256((prior_chain+"|"+page_manifest_sha).encode("utf-8")).hexdigest()
    out={k:v for k,v in dict(full).items() if k!="chunks"}
    out["chunks"]=fragments
    out["read_mode"]="COMPLETE_SIGNPOST_SPAN" if complete and page_no==1 else "VERIFIED_CONTINUATION_PAGE"
    out["continuation_version"]=_LS126_VERSION
    out["continuation_page"]=page_no
    out["continuation_required"]=not complete
    out["range_complete_in_this_read"]=bool(complete and page_no==1)
    out["range_complete_across_continuation"]=bool(complete and coverage_from_start)
    out["coverage_from_span_start"]=bool(coverage_from_start)
    out["page_returned_ordinals"]=[int(x.get("ordinal") or 0) for x in fragments]
    out["page_text_token_estimate"]=int(used)
    out["page_manifest_sha256"]=page_manifest_sha
    out["coverage_chain_sha256"]=chain_sha
    out["full_span_sha256"]=span_sha
    out["silent_truncation"]=False
    out["semantic_selection_performed_by_python"]=False
    out["pagination_reason"]="Exact transport paging only; source characters remain in immutable source order and no semantic summarization, ranking, or omission is performed."
    if complete:
        out["next_ordinal"]=None
        out["continuation"]=None
        out["continuation_status"]="COMPLETE"
    else:
        next_state={"rich_revision_id":rid,"exact_source_pointer_sha256":ptr_sha,"span_sha256":span_sha,"chunk_index":cur_idx,"chunk_offset":cur_offset,"page_no":page_no+1,"coverage_chain_sha256":chain_sha,"coverage_from_start":coverage_from_start}
        next_cursor=_ls126_cursor_encode(next_state)
        args={"rich_revision_id":rid,"cursor":next_cursor}
        out["continuation_status"]="MORE_EXACT_SOURCE_REQUIRED"
        out["continuation"]={"tool":"read_signpost_source","arguments":args,"instruction":"Use these arguments exactly to continue the same immutable source span. Continue until range_complete_across_continuation=true before claiming complete-span inspection."}
        out["next_page_arguments"]=args
    return out


def _hd78_read_signpost_source(module, rich_revision_id: str="", *, node_id: str="", book_id: str="", ordinal=None, cursor: str="") -> dict:
    if ordinal is not None and str(cursor or "").strip():
        return {"ok":False,"error":"Use either explicit ordinal or continuation cursor, not both.","rich_revision_id":str(rich_revision_id or "") or None,"read_only":True,"model_calls":0,"web_calls":0,"continuation_version":_LS126_VERSION}
    if ordinal is not None:
        out=dict(_LS126_BASE_READ_SOURCE(module,rich_revision_id,node_id=node_id,book_id=book_id,ordinal=ordinal))
        out["continuation_version"]=_LS126_VERSION
        out["range_complete_across_continuation"]=False
        return out
    full=dict(_LS126_BASE_READ_SOURCE(module,rich_revision_id,node_id=node_id,book_id=book_id))
    return _ls126_page_complete_result(module,full,cursor=str(cursor or ""))


def _hd78_tool_schema() -> dict:
    return {"type":"function","name":_HD78_SOURCE_TOOL,"description":"Open exact original NeatBooks text behind a rich signpost. Omit ordinal for verified complete-span traversal: Python returns a bounded exact-source page plus ready-to-use continuation arguments until range_complete_across_continuation=true. This is transport pagination only; no source text is semantically summarized, reranked, or silently truncated. Supply ordinal only for an explicit targeted single-chunk read.","parameters":{"type":"object","properties":{"rich_revision_id":{"type":"string"},"node_id":{"type":"string"},"book_id":{"type":"string"},"ordinal":{"type":"integer","minimum":1,"description":"Optional explicit targeted single ordinal; do not combine with cursor."},"cursor":{"type":"string","description":"Opaque hash-bound continuation cursor returned by the previous read_signpost_source page. Copy exactly; do not reconstruct."}},"additionalProperties":False},"strict":False}


def _ls126_self_test(module=None) -> dict:
    checks={}; details={}
    text1=("alpha beta gamma "*2200).strip(); text2=("war timing wind "*2200).strip()
    span_sha=hashlib.sha256((text1+"\n"+text2).encode("utf-8")).hexdigest()
    full={"ok":True,"rich_revision_id":"RSR-LS126","node_id":"N-LS126","exact_source_pointer_sha256":"p"*64,"lexical_measurement_span_sha256":span_sha,"range_start_ordinal":1,"range_end_ordinal":2,"chunks":[{"chunk_id":"C1","ordinal":1,"returned_start_char":0,"text":text1},{"chunk_id":"C2","ordinal":2,"returned_start_char":0,"text":text2}],"read_only":True,"model_calls":0,"web_calls":0}
    pages=[]; cursor=""
    for _ in range(40):
        page=_ls126_page_complete_result(module,full,cursor=cursor,target_tokens=900)
        pages.append(page)
        if page.get("range_complete_across_continuation"): break
        cursor=str(((page.get("continuation") or {}).get("arguments") or {}).get("cursor") or "")
        if not cursor: break
    reconstructed={"C1":"","C2":""}
    for page in pages:
        for frag in page.get("chunks") or []:
            cid=str(frag.get("chunk_id") or ""); reconstructed[cid]=reconstructed.get(cid,"")+str(frag.get("text") or "")
    checks["large_span_is_paged_instead_of_dumped"] = len(pages)>1 and pages[0].get("continuation_required") is True and pages[0].get("range_complete_in_this_read") is False
    checks["returned_cursor_is_directly_actionable"] = bool(((pages[0].get("continuation") or {}).get("arguments") or {}).get("cursor")) and ((pages[0].get("continuation") or {}).get("tool")=="read_signpost_source")
    checks["cursor_chain_reconstructs_exact_source"] = reconstructed.get("C1")==text1 and reconstructed.get("C2")==text2
    checks["final_page_proves_complete_continuation"] = bool(pages[-1].get("range_complete_across_continuation")) and pages[-1].get("continuation_status")=="COMPLETE" and pages[-1].get("full_span_sha256")==span_sha
    bad=str(((pages[0].get("continuation") or {}).get("arguments") or {}).get("cursor") or "")+"x"
    rejected=_ls126_page_complete_result(module,full,cursor=bad,target_tokens=900)
    checks["tampered_cursor_fails_closed"] = rejected.get("ok") is False and "cursor" in str(rejected.get("error") or "").casefold()
    schema=_hd78_tool_schema(); props=((schema.get("parameters") or {}).get("properties") or {})
    checks["same_tool_exposes_cursor_without_new_command"] = "cursor" in props and "continuation" in str(schema.get("description") or "").casefold()
    checks["pagination_is_mechanical_not_semantic"] = all(p.get("semantic_selection_performed_by_python") is False and p.get("silent_truncation") is False for p in pages)
    details["pages"]={"count":len(pages),"first_status":pages[0].get("continuation_status"),"final_status":pages[-1].get("continuation_status"),"final_chain":pages[-1].get("coverage_chain_sha256")}
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"details":details,"version":_LS126_VERSION}


def _deep_signpost_retrieval_fusion_self_test(module=None) -> dict:
    base=dict(_LS126_BASE_FUSION_TEST(module)); extra=_ls126_self_test(module); checks=dict(base.get("checks") or {}); checks.update({"ls126_"+k:v for k,v in (extra.get("checks") or {}).items()}); details=dict(base.get("details") or {}); details["verified_signpost_span_continuation"]=extra.get("details")
    base["checks"]=checks; base["details"]=details; base["ok"]=all(bool(v) for v in checks.values()); base["signpost_source_continuation_version"]=_LS126_VERSION
    return base


def _install_deep_signpost_retrieval_fusion(module) -> None:
    _LS126_BASE_INSTALL(module)
    _hd79_register_tool(module)
    module.read_signpost_source=lambda rich_revision_id="",**kwargs:_hd78_read_signpost_source(module,rich_revision_id,**kwargs)
    module.DEEP_SIGNPOST_RETRIEVAL_FUSION_VERSION=_LS126_VERSION
    prompt=str(getattr(module,"SYSTEM_PROMPT",""))
    rule=("\n\nRICH SIGNPOST VERIFIED SOURCE CONTINUATION\n"
          "- A complete rich-signpost source span may exceed one safe tool-result payload. read_signpost_source therefore returns exact source in deterministic bounded pages when necessary rather than asking you to invent a narrower semantic read.\n"
          "- If continuation_status is MORE_EXACT_SOURCE_REQUIRED, copy continuation.arguments exactly into the next read_signpost_source call. Continue until range_complete_across_continuation=true before claiming the complete span was inspected.\n"
          "- Pagination changes transport only: every returned fragment is exact source in immutable order; Python performs no summary, semantic selection, ranking, or omission. Explicit ordinal remains available only when you deliberately want one targeted chunk.\n"
          "- When inspecting enumerated rich heads, use the provided inspect_rich_signpost.arguments exactly; do not call read_rich_signpost without a returned node_id or rich_revision_id.\n")
    if "RICH SIGNPOST VERIFIED SOURCE CONTINUATION" not in prompt: module.SYSTEM_PROMPT=prompt.rstrip()+rule



# ---------------------------------------------------------------------------
# 7.4.78.127 AUTOMATIC VERIFIED SIGNPOST CONTINUATION
# ---------------------------------------------------------------------------
# The live .126 Art of War audit showed that bounded continuation itself was
# correct but still left a clerical burden with Assistant: after a requested complete
# rich-signpost span returned page 1, Assistant had to notice the cursor and issue each
# subsequent read_signpost_source call manually. Two multi-page spans therefore
# remained incomplete even though Python already held a hash-bound deterministic
# continuation route.
#
# .127 makes continuation ownership mechanical. Once Assistant requests
# read_signpost_source without an explicit ordinal and the admitted result says
# MORE_EXACT_SOURCE_REQUIRED, Python follows only the returned immutable cursor
# chain. Every page still passes the existing preflight/result-admission guards;
# Python cannot widen the range, invent a cursor, summarize source text, choose a
# semantic subset, or bypass capacity safety. The admitted pages are presented as
# one logical exact-evidence event for Capsule packing/verification, and synthetic
# transport call/output pairs remain auditable. If a hard page/token/admission
# guard stops the chain, completion stays false and no complete-span claim is
# manufactured. Explicit ordinal reads remain one targeted chunk.

_LS127_VERSION = "1.0-automatic-verified-signpost-continuation"
_LS127_MAX_AUTO_PAGES = 24
_LS127_MAX_AUTO_TEXT_TOKENS = 96000
_LS127_BASE_FUSION_TEST = _deep_signpost_retrieval_fusion_self_test
_LS127_BASE_INSTALL = _install_deep_signpost_retrieval_fusion


def _ls127_json_object(wire: str) -> dict:
    try:
        obj=json.loads(str(wire or "{}"))
        return dict(obj) if isinstance(obj,dict) else {}
    except Exception:
        return {}


def _ls127_chain_store(module) -> dict:
    rows=getattr(module,"_LS127_AUTO_CONTINUATION_CHAINS",None)
    if not isinstance(rows,dict):
        rows={}; setattr(module,"_LS127_AUTO_CONTINUATION_CHAINS",rows)
    return rows


def _ls127_trim_chain_store(module) -> None:
    rows=_ls127_chain_store(module)
    while len(rows)>64:
        try: rows.pop(next(iter(rows)))
        except Exception: break


def _ls127_synthetic_call_id(original_call_id: str, page_no: int) -> str:
    seed=f"{original_call_id}|{page_no}|{_LS127_VERSION}".encode("utf-8")
    return "AUTO-LS127-"+hashlib.sha256(seed).hexdigest()[:18].upper()


def _ls127_auto_follow_pages(module, *, first_payload: dict, first_wire: str, original_call_id: str,
                             instructions: str, working: list, tools: list, seen: set[str],
                             round_number: int=0, trace: dict|None=None) -> dict:
    """Mechanically follow only a returned read_signpost_source cursor chain.

    This helper performs no provider/model call. Each continuation page is executed
    through the existing preflight, exact-source dispatcher, citation binding, and
    result-admission guards before it is appended to the next provider input.
    """
    current=dict(first_payload or {})
    wires=[str(first_wire or "")]
    call_ids=[str(original_call_id or "")]
    events=[]
    pages=1
    text_tokens=max(0,int(current.get("page_text_token_estimate") or 0))
    hard_stop=None
    read_budget_blocked=False
    close_after=False
    final_chain=str(current.get("coverage_chain_sha256") or "")
    full_span_sha=str(current.get("full_span_sha256") or current.get("lexical_measurement_span_sha256") or "")

    while str(current.get("continuation_status") or "") == "MORE_EXACT_SOURCE_REQUIRED":
        if pages >= int(_LS127_MAX_AUTO_PAGES):
            hard_stop="AUTO_PAGE_LIMIT"
            break
        if text_tokens >= int(_LS127_MAX_AUTO_TEXT_TOKENS):
            hard_stop="AUTO_TEXT_TOKEN_LIMIT"
            break
        cont=dict(current.get("continuation") or {})
        next_args=dict(cont.get("arguments") or {})
        if str(cont.get("tool") or "") != _HD78_SOURCE_TOOL or not next_args.get("cursor") or not next_args.get("rich_revision_id"):
            hard_stop="INVALID_RETURNED_CONTINUATION"
            break
        fingerprint=hashlib.sha256(json.dumps({"name":_HD78_SOURCE_TOOL,"arguments":next_args},sort_keys=True,ensure_ascii=False).encode("utf-8")).hexdigest()
        if fingerprint in seen:
            hard_stop="CONTINUATION_ALREADY_EXECUTED"
            break
        execute_tool,blocked_output,preflight=_ora_tool_preflight_backpressure(
            module,name=_HD78_SOURCE_TOOL,arguments=next_args,instructions=instructions,
            working=working,tools=tools,prior_budget_block=False,
        )
        syn_id=_ls127_synthetic_call_id(original_call_id,pages+1)
        synthetic_call={"type":"function_call","call_id":syn_id,"name":_HD78_SOURCE_TOOL,"arguments":json.dumps(next_args,ensure_ascii=False,separators=(",",":"))}
        working.append(synthetic_call)
        if not execute_tool:
            working.append({"type":"function_call_output","call_id":syn_id,"output":blocked_output})
            read_budget_blocked=True; close_after=bool(preflight.get("close_tool_phase")); hard_stop=str(preflight.get("reason") or "PREFLIGHT_BLOCKED")
            break
        seen.add(fingerprint)
        logger=getattr(module,"append_diagnostic_log",None); started=time.perf_counter()
        if callable(logger):
            try: logger("tool.auto_continuation_call","Python followed a returned exact-source continuation cursor.",subsystem="tools",provider="online",details={"tool":_HD78_SOURCE_TOOL,"arguments":next_args,"call_id":syn_id,"round":round_number,"automatic":True,"semantic_selection":False})
            except Exception: pass
        try:
            result=_ora_execute_evidence_tool(module,_HD78_SOURCE_TOOL,next_args)
        except Exception as exc:
            hard_stop=f"EXECUTION_ERROR:{type(exc).__name__}"
            working.append({"type":"function_call_output","call_id":syn_id,"output":json.dumps({"ok":False,"error":f"Automatic exact-source continuation failed: {type(exc).__name__}: {exc}","automatic_continuation":True,"range_complete_across_continuation":False},ensure_ascii=False)})
            break
        result,candidates=_ora_attach_turn_tool_citation_candidates(module,_HD78_SOURCE_TOOL,result)
        admitted_output,admission=_ora_tool_result_admission(
            module,name=_HD78_SOURCE_TOOL,arguments=next_args,result=result,
            instructions=instructions,working=working,tools=tools,
        )
        working.append({"type":"function_call_output","call_id":syn_id,"output":admitted_output})
        if not bool(admission.get("admitted")) or not bool(admission.get("full_result_admitted")):
            read_budget_blocked=True; close_after=bool(admission.get("close_tool_phase_after_result")); hard_stop="RESULT_ADMISSION_BLOCKED"
            break
        _ora_commit_turn_tool_citations(module,candidates)
        event=_wnc_event_public(_HD78_SOURCE_TOOL,next_args,admitted_output)
        event["automatic_continuation_page"]=True; event["automatic_continuation_root_call_id"]=str(original_call_id or "")
        events.append(event)
        wires.append(admitted_output); call_ids.append(syn_id); pages+=1
        current=_ls127_json_object(admitted_output)
        text_tokens+=max(0,int(current.get("page_text_token_estimate") or 0))
        final_chain=str(current.get("coverage_chain_sha256") or final_chain)
        full_span_sha=str(current.get("full_span_sha256") or current.get("lexical_measurement_span_sha256") or full_span_sha)
        if callable(logger):
            try: logger("tool.auto_continuation_complete","Automatic exact-source continuation page admitted.",subsystem="tools",provider="online",details={"tool":_HD78_SOURCE_TOOL,"call_id":syn_id,"page":pages,"duration_ms":round((time.perf_counter()-started)*1000,3),"range_complete_across_continuation":bool(current.get("range_complete_across_continuation")),"automatic":True})
            except Exception: pass

    complete=bool(current.get("range_complete_across_continuation")) and str(current.get("continuation_status") or "") == "COMPLETE"
    status="COMPLETE" if complete else "HARD_STOP"
    chain={
        "version":_LS127_VERSION,"root_call_id":str(original_call_id or ""),"tool":_HD78_SOURCE_TOOL,
        "rich_revision_id":str(first_payload.get("rich_revision_id") or ""),"call_ids":call_ids,"wires":wires,
        "pages_admitted":len(wires),"auto_text_tokens":int(text_tokens),"complete":bool(complete),
        "status":status,"hard_stop_reason":hard_stop,"full_span_sha256":full_span_sha,
        "final_coverage_chain_sha256":final_chain,"semantic_selection":False,"silent_truncation":False,
    }
    store=_ls127_chain_store(module); store[str(original_call_id or "")]=chain; _ls127_trim_chain_store(module)
    if trace is not None:
        trace["automatic_signpost_continuation_chains"]=int(trace.get("automatic_signpost_continuation_chains") or 0)+1
        trace["automatic_signpost_continuation_pages"]=int(trace.get("automatic_signpost_continuation_pages") or 0)+max(0,len(wires)-1)
        if not complete: trace["automatic_signpost_continuation_hard_stops"]=int(trace.get("automatic_signpost_continuation_hard_stops") or 0)+1
    print(f"[signpost source continuation] {status} | pages {len(wires)} | exact text ~{int(text_tokens):,}t"+(f" | stop {hard_stop}" if hard_stop else ""),flush=True)
    return {"chain":chain,"events":events,"read_budget_blocked":read_budget_blocked,"close_after":close_after}


def _ls127_combined_chain_payload(chain: dict) -> dict:
    pages=[]
    for wire in list((chain or {}).get("wires") or []):
        obj=_ls127_json_object(wire)
        if obj: pages.append(obj)
    return {
        "ok":bool((chain or {}).get("complete")),
        "automatic_verified_continuation":True,
        "automatic_continuation_version":_LS127_VERSION,
        "rich_revision_id":str((chain or {}).get("rich_revision_id") or ""),
        "range_complete_across_continuation":bool((chain or {}).get("complete")),
        "continuation_status":"COMPLETE" if (chain or {}).get("complete") else "HARD_STOP",
        "continuation_hard_stop_reason":((chain or {}).get("hard_stop_reason") or None),
        "continuation_pages_admitted":len(pages),
        "full_span_sha256":str((chain or {}).get("full_span_sha256") or ""),
        "coverage_chain_sha256":str((chain or {}).get("final_coverage_chain_sha256") or ""),
        "pages":pages,
        "semantic_selection_performed_by_python":False,
        "silent_truncation":False,
        "authority":"Exact source pages from one immutable rich-signpost range. Automatic continuation changes transport only.",
    }


def _ls127_install_runtime_hooks(module) -> None:
    # `_install_capsule_manifest` is called earlier in _load_memory. Install these
    # hooks now, after the module has finished defining the capsule helpers.
    process=globals().get("_wnc_process_calls")
    if callable(process) and not getattr(process,"_ls127_wrapped",False):
        base_process=process
        def process_auto(mod,calls,*,instructions,working,tools,seen,round_number,trace):
            read_blocked,close_after,events=base_process(mod,calls,instructions=instructions,working=working,tools=tools,seen=seen,round_number=round_number,trace=trace)
            for call in list(calls or []):
                name=str(_ora_item_attr(call,"name","") or "")
                if name!=_HD78_SOURCE_TOOL: continue
                call_id=str(_ora_item_attr(call,"call_id","") or "")
                first_wire=_cm_find_call_output(working,call_id)
                first=_ls127_json_object(first_wire)
                # Explicit ordinal reads intentionally remain one targeted chunk.
                try: args=json.loads(str(_ora_item_attr(call,"arguments","{}") or "{}"))
                except Exception: args={}
                if not isinstance(args,dict) or args.get("ordinal") is not None: continue
                if str(first.get("continuation_status") or "")!="MORE_EXACT_SOURCE_REQUIRED": continue
                followed=_ls127_auto_follow_pages(mod,first_payload=first,first_wire=first_wire,original_call_id=call_id,instructions=instructions,working=working,tools=tools,seen=seen,round_number=round_number,trace=trace)
                events.extend(list(followed.get("events") or []))
                read_blocked=bool(read_blocked or followed.get("read_budget_blocked")); close_after=bool(close_after or followed.get("close_after"))
            return read_blocked,close_after,events
        process_auto._ls127_wrapped=True; process_auto._ls127_base=base_process
        globals()["_wnc_process_calls"]=process_auto

    register=globals().get("_cm_register_exact_event")
    if callable(register) and not getattr(register,"_ls127_wrapped",False):
        base_register=register
        def register_chain(mod,event,wire,call_id,tool):
            chain=dict(_ls127_chain_store(mod).get(str(call_id or "")) or {})
            if str(tool or "")!=_HD78_SOURCE_TOOL or not chain:
                return base_register(mod,event,wire,call_id,tool)
            combined=_ls127_combined_chain_payload(chain); combined_wire=json.dumps(combined,ensure_ascii=False,default=str,separators=(",",":"))
            combined_event=dict(event or {}); combined_event["result"]=combined; combined_event["automatic_verified_continuation"]=True
            reg=dict(base_register(mod,combined_event,combined_wire,call_id,tool) or {})
            reg.update({"automatic_continuation_complete":bool(chain.get("complete")),"automatic_continuation_pages":int(chain.get("pages_admitted") or 0),"combined_exact_characters":len(combined_wire),"full_span_sha256":chain.get("full_span_sha256")})
            chain["combined_evidence_handle"]=reg.get("evidence_handle"); _ls127_chain_store(mod)[str(call_id or "")]=chain
            return reg
        register_chain._ls127_wrapped=True; register_chain._ls127_base=base_register
        globals()["_cm_register_exact_event"]=register_chain

    offload=globals().get("_cm_offload_consumed_exact_outputs")
    if callable(offload) and not getattr(offload,"_ls127_wrapped",False):
        base_offload=offload
        def offload_chain(working,pending):
            out=dict(base_offload(working,pending) or {})
            module_obj=module
            chains=_ls127_chain_store(module_obj)
            synthetic={}
            for root in list((pending or {}).keys()):
                chain=dict(chains.get(str(root)) or {})
                for cid in list(chain.get("call_ids") or [])[1:]: synthetic[str(cid)]=chain
            if not synthetic: return out
            events=removed=handles=0
            for item in list(working or []):
                if not isinstance(item,dict) or str(item.get("type") or "")!="function_call_output": continue
                cid=str(item.get("call_id") or "")
                chain=synthetic.get(cid)
                if not chain: continue
                old=str(item.get("output") or "")
                receipt=_cm_offload_receipt(cid,_HD78_SOURCE_TOOL,old)
                receipt["automatic_continuation_root_call_id"]=str(chain.get("root_call_id") or "")
                receipt["automatic_continuation_complete"]=bool(chain.get("complete"))
                new=json.dumps(receipt,ensure_ascii=False,separators=(",",":")); item["output"]=new
                events+=1; removed+=max(0,len(old)-len(new)); handles+=len(new)
            out["events"]=int(out.get("events") or 0)+events; out["removed_characters"]=int(out.get("removed_characters") or 0)+removed; out["handle_characters"]=int(out.get("handle_characters") or 0)+handles
            return out
        offload_chain._ls127_wrapped=True; offload_chain._ls127_base=base_offload
        globals()["_cm_offload_consumed_exact_outputs"]=offload_chain

    active_loop=globals().get("_ora_run_responses_book_loop")
    if callable(active_loop) and not getattr(active_loop,"_ls127_turn_wrapped",False):
        base_loop=active_loop
        def run_with_auto_continuation(mod,backend,instructions,input_items,*,output_kwargs=None):
            mod._LS127_AUTO_CONTINUATION_CHAINS={}
            return base_loop(mod,backend,instructions,input_items,output_kwargs=output_kwargs)
        run_with_auto_continuation._ls127_turn_wrapped=True; run_with_auto_continuation._ls127_base=base_loop
        globals()["_ora_run_responses_book_loop"]=run_with_auto_continuation

    # Update already-registered schemas in place; same tool, no new command.
    new_description=("Open exact original NeatBooks text behind a rich signpost. Omit ordinal for the complete pointed-to span: if bounded paging is required, Python automatically follows only the returned hash-bound continuation cursor chain before ordinary navigation resumes, with every page still subject to normal preflight/admission safety. Supply ordinal only for an explicit targeted single-chunk read. Cursor remains an internal/recovery field and must never be reconstructed.")
    for arr in (globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS"),globals().get("_ONLINE_BOOK_RESPONSE_TOOLS")):
        if isinstance(arr,list):
            for row in arr:
                if isinstance(row,dict) and str(row.get("name") or "")==_HD78_SOURCE_TOOL: row["description"]=new_description
    for row in list(getattr(module,"TOOL_SCHEMAS",[]) or []):
        if not isinstance(row,dict): continue
        fn=row.get("function") or {}
        if str(fn.get("name") or "")==_HD78_SOURCE_TOOL: fn["description"]=new_description


