# ---------------------------------------------------------------------------
# 7.4.78.128 DETERMINISTIC LEXICAL STRENGTH ORDERING
# ---------------------------------------------------------------------------
# The live .127 Art of War audit established COMPLETE-SPAN PASS,
# SCORE-EXPLAINABILITY PASS, and SCORING QUALITY PASS for the .122/.125 lexical
# strengths as mechanical lexical-presence measurements. Assistant then explicitly
# confirmed that the strengths are useful as navigation metadata and supported
# using them as a deterministic lexical ordering aid, provided low-strength
# candidates remain discoverable and exact source remains authority.
#
# .128 therefore changes only the order of non-empty search_rich_signposts
# results. Python uses the exact normalized words in the current query and the
# already-audited per-signpost lexical strengths. It does not expand synonyms,
# infer relevance, inspect answer meaning, or filter by a minimum strength.
# Ordering is: more exact query words matched; higher average strength across
# those exact matched words; higher strongest exact-word strength; then the
# previous deterministic result order as a stable tie-break. A bounded node_limit
# still controls how many results are displayed, but zero candidates are removed
# merely for having a low lexical strength. Blank scoped enumeration remains in
# canonical source order and bypasses strength ordering entirely.

_LS128_VERSION = "1.0-deterministic-lexical-strength-ordering"
_LS128_CANDIDATE_POOL_LIMIT = 16
_LS128_BASE_SEARCH_RICH = _hd79_search_rich_signposts
_LS128_BASE_SEARCH_SCHEMA = _hd79_search_schema
_LS128_BASE_FUSION_TEST = _deep_signpost_retrieval_fusion_self_test
_LS128_BASE_INSTALL = _install_deep_signpost_retrieval_fusion


def _ls128_strength_map(node: dict) -> dict[str,float]:
    mapped={}
    for raw,value in dict((node or {}).get("keyword_strengths") or {}).items():
        terms=_smn_terms(str(raw or ""))
        if len(terms)!=1:
            continue
        try: score=max(0.0,min(1.0,float(value)))
        except Exception: score=0.0
        key=terms[0]
        if key not in mapped or score>mapped[key]: mapped[key]=score
    return mapped


def _ls128_annotate_candidate(node: dict, query_terms: list[str], base_index: int) -> dict:
    item=dict(node or {})
    unique=[]
    for t in query_terms:
        if t and t not in unique: unique.append(t)
    matched_raw=list(item.get("matched_query_tokens") or [])
    matched=[]
    for t in matched_raw:
        for norm in _smn_terms(str(t or "")):
            if norm in unique and norm not in matched: matched.append(norm)
    strengths=_ls128_strength_map(item)
    pairs={t:round(float(strengths.get(t,0.0)),6) for t in matched}
    vals=[float(pairs[t]) for t in matched]
    avg=round(sum(vals)/len(vals),6) if vals else 0.0
    strongest=round(max(vals),6) if vals else 0.0
    item.update({
        "lexical_ordering_version":_LS128_VERSION,
        "lexical_ordering_matched_query_terms":matched,
        "lexical_ordering_query_strengths":pairs,
        "lexical_ordering_match_count":len(matched),
        "lexical_ordering_average_strength":avg,
        "lexical_ordering_strongest_strength":strongest,
        "lexical_ordering_previous_order_index":int(base_index),
        "lexical_ordering_reason":"exact query-word coverage, then average audited lexical strength, then strongest audited lexical strength, then previous deterministic order",
        "lexical_ordering_navigation_only":True,
        "lexical_ordering_semantic_relevance":False,
        "lexical_ordering_strength_filter_threshold":None,
        "lexical_ordering_low_strength_filtered":False,
        "keyword_strengths_affect_ranking":True,
    })
    return item


def _ls128_order_nodes(nodes, query_terms: list[str]) -> list[dict]:
    annotated=[_ls128_annotate_candidate(dict(n or {}),query_terms,i) for i,n in enumerate(list(nodes or []))]
    annotated.sort(key=lambda n:(
        -int(n.get("lexical_ordering_match_count") or 0),
        -float(n.get("lexical_ordering_average_strength") or 0.0),
        -float(n.get("lexical_ordering_strongest_strength") or 0.0),
        int(n.get("lexical_ordering_previous_order_index") or 0),
    ))
    for rank,node in enumerate(annotated,1): node["lexical_ordering_rank"]=rank
    return annotated


def _hd79_search_rich_signposts(module, query: str="", *, reference: str="", book_ids=None, node_limit: int=6, book_scan_limit: int=100) -> dict:
    terms=_smn_terms(query)
    requested=max(1,min(16,int(node_limit or 6)))
    if not terms:
        out=dict(_LS128_BASE_SEARCH_RICH(module,query,reference=reference,book_ids=book_ids,node_limit=requested,book_scan_limit=book_scan_limit))
        out["lexical_strength_ordering_applied"]=False
        out["lexical_strength_ordering_reason"]="blank scoped enumeration preserves canonical source order"
        out["lexical_strength_ordering_version"]=_LS128_VERSION
        return out
    # Ask the preserved exact-token search for the widest already-supported bounded
    # pool before applying .128 ordering. This changes ordering, not query matching.
    pool_limit=max(requested,int(_LS128_CANDIDATE_POOL_LIMIT))
    out=dict(_LS128_BASE_SEARCH_RICH(module,query,reference=reference,book_ids=book_ids,node_limit=pool_limit,book_scan_limit=book_scan_limit))
    if not out.get("ok"):
        out["lexical_strength_ordering_applied"]=False
        out["lexical_strength_ordering_version"]=_LS128_VERSION
        return out
    base_nodes=list(out.get("nodes") or [])
    ordered=_ls128_order_nodes(base_nodes,terms)
    visible=ordered[:requested]
    out["nodes"]=visible
    out["returned"]=len(visible)
    out["lexical_strength_ordering_applied"]=True
    out["lexical_strength_ordering_version"]=_LS128_VERSION
    out["lexical_strength_candidates_considered"]=len(ordered)
    out["lexical_strength_display_limit"]=requested
    out["lexical_strength_candidate_pool_limit"]=_LS128_CANDIDATE_POOL_LIMIT
    out["lexical_strength_candidates_removed_for_low_strength"]=0
    out["lexical_strength_filter_threshold"]=None
    out["keyword_strengths_affect_ranking"]=True
    out["keyword_strengths_are_navigation_only"]=True
    out["ranking"]="exact query-word match count, average audited lexical strength of those exact matched words, strongest exact matched-word strength, then previous deterministic order"
    out["ranking_explanation_visible_per_candidate"]=True
    out["semantic_ranking_used"]=False
    out["semantic_expansion_used"]=False
    out["source_text_opened_for_128_ordering"]=False
    out["python_semantic_judgment"]=False
    out["authority"]="Lexical strength changes candidate presentation order only. It is mechanical navigation metadata, never relevance, truth, confidence, importance, or answer authority; reopen exact source before interpretation."
    return out


def _hd79_search_schema() -> dict:
    schema=dict(_LS128_BASE_SEARCH_SCHEMA())
    # Reuse the current .123-capable schema rather than introducing a new tool.
    if not schema or str(schema.get("name") or "")!=_HD79_SEARCH_TOOL:
        schema={"type":"function","name":_HD79_SEARCH_TOOL,"parameters":{"type":"object","properties":{"query":{"type":"string"},"reference":{"type":"string"},"book_ids":{"type":"array","items":{"type":"string"},"maxItems":24},"node_limit":{"type":"integer","minimum":1,"maximum":16},"book_scan_limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False},"strict":False}
    schema=dict(schema)
    schema["description"]="Dedicated zero-model rich-signpost navigation. Non-empty queries use exact normalized query words and audited lexical strengths only to order matching candidates mechanically; each candidate exposes the exact matched-word strengths and ordering reason, no low-strength threshold is applied, and exact source remains authority. Blank query with explicit book scope preserves mechanical source-order head enumeration."
    return schema


