def _ann_search(module, *, query: str, book_id: str="", include_history: bool=True, limit: int=50) -> dict:
    _ann_ensure_schema(module); q=" ".join(str(query or "").split()).strip(); bid=str(book_id or "").strip(); lim=max(1,min(500,int(limit or 50)))
    if not q: return {"ok":False,"error":"query is required","read_only":True,"model_calls":0}
    where=["(LOWER(m.summary) LIKE ? OR LOWER(a.target_ref) LIKE ? OR LOWER(a.annotation_id) LIKE ?)"]; needle="%"+q.casefold()+"%"; vals=[needle,needle,needle]
    if bid: where.append("a.book_id=?"); vals.append(bid)
    if not include_history: where.append("a.status='active'")
    sql="SELECT a.*,m.summary,m.state AS memory_state,m.temporal_status,m.content_sha256 AS memory_sha256 FROM assistant_book_annotations a JOIN memories m ON m.id=a.memory_id WHERE "+" AND ".join(where)+" ORDER BY a.modified_at DESC,a.created_at DESC LIMIT ?"; vals.append(lim)
    with module.db_connect() as db: rows=[dict(x) for x in db.execute(sql,tuple(vals)).fetchall()]
    items=[]
    for r in rows:
        summary=str(r.get("summary") or ""); pos=summary.casefold().find(q.casefold()); start=max(0,pos-180) if pos>=0 else 0; snippet=summary[start:start+520]
        items.append({"annotation_id":r["annotation_id"],"ref":"annotation:"+r["annotation_id"],"memory_id":r["memory_id"],"latest_receipt_id":_ann_latest_receipt_id(module,r["annotation_id"]),"book_id":r["book_id"],"target_ref":r["target_ref"],"owner":r["owner"],"comment":summary,"snippet":snippet,"confidence":float(r["confidence"]),"revision":int(r["revision"]),"parent_annotation_id":r.get("parent_annotation_id"),"status":r["status"],"memory_state":r.get("memory_state"),"temporal_status":r.get("temporal_status"),"created_at":r["created_at"],"modified_at":r.get("modified_at"),"comment_sha256":r.get("comment_sha256"),"memory_sha256":r.get("memory_sha256")})
    return {"ok":True,"query":q,"book_id":bid or None,"include_history":bool(include_history),"count":len(items),"items":items,"read_only":True,"model_calls":0,"ownership":"Assistant personal memory; never canonical NeatBook fact"}


def _ann_revision_chains(rows: list[dict], limit: int=100) -> list[dict]:
    byid={str(r.get("annotation_id") or ""):r for r in rows if r.get("annotation_id")}; groups={}
    for row in rows:
        cur=row; seen=set(); root=str(row.get("annotation_id") or "")
        while cur and str(cur.get("parent_annotation_id") or "") and str(cur.get("annotation_id") or "") not in seen:
            seen.add(str(cur.get("annotation_id") or "")); pid=str(cur.get("parent_annotation_id") or ""); parent=byid.get(pid)
            if not parent: break
            root=pid; cur=parent
        groups.setdefault(root,[]).append(row)
    out=[]
    for root,items in sorted(groups.items(),key=lambda kv:max(str(x.get("modified_at") or x.get("created_at") or "") for x in kv[1]),reverse=True)[:max(1,int(limit or 100))]:
        seq=sorted(items,key=lambda x:(int(x.get("revision") or 0),str(x.get("created_at") or "")))
        out.append({"root_annotation_id":root,"length":len(seq),"revisions":[{"annotation_id":x.get("annotation_id"),"revision":int(x.get("revision") or 0),"parent_annotation_id":x.get("parent_annotation_id"),"status":x.get("status"),"created_at":x.get("created_at")} for x in seq]})
    return out


def _ann_status(module, *, book_id: str="", check_targets: bool=True, target_limit: int=250) -> dict:
    _ann_ensure_schema(module); bid=str(book_id or "").strip(); lim=max(1,min(2000,int(target_limit or 250)))
    where="WHERE a.book_id=?" if bid else ""; vals=(bid,) if bid else ()
    with module.db_connect() as db:
        rows=[dict(x) for x in db.execute(f"SELECT a.*,m.id AS joined_memory_id,m.state AS memory_state,m.temporal_status,m.content_sha256 AS memory_sha256 FROM assistant_book_annotations a LEFT JOIN memories m ON m.id=a.memory_id {where} ORDER BY a.created_at ASC",vals).fetchall()]
        if bid:
            receipt_rows=[dict(x) for x in db.execute("SELECT * FROM assistant_book_annotation_receipts WHERE book_id=? ORDER BY committed_at DESC",(bid,)).fetchall()]
        else:
            receipt_rows=[dict(x) for x in db.execute("SELECT * FROM assistant_book_annotation_receipts ORDER BY committed_at DESC").fetchall()]
    status_counts={}
    for r in rows: status_counts[str(r.get("status") or "unknown")]=status_counts.get(str(r.get("status") or "unknown"),0)+1
    orphan_memory=sum(1 for r in rows if not r.get("joined_memory_id"))
    active=[r for r in rows if str(r.get("status") or "").casefold()=="active"]
    fresh=stale=broken=checked=0; target_items=[]
    if check_targets:
        for r in active[:lim]:
            checked+=1; pinned=str(r.get("target_sha256") or "")
            try:
                snap=_ann_target_snapshot(module,str(r.get("book_id") or ""),str(r.get("target_ref") or "")); current=str(snap.get("target_sha256") or ""); state="fresh" if current and current==pinned else "stale"
                if state=="fresh": fresh+=1
                else: stale+=1
                target_items.append({"annotation_id":r.get("annotation_id"),"target_ref":r.get("target_ref"),"state":state,"pinned_sha256":pinned,"current_sha256":current or None})
            except Exception as exc:
                broken+=1; target_items.append({"annotation_id":r.get("annotation_id"),"target_ref":r.get("target_ref"),"state":"broken","pinned_sha256":pinned,"error":str(exc)[:300]})
    books=sorted({str(r.get("book_id") or "") for r in rows if r.get("book_id")})
    sidecars=[]
    for b in books[:100]:
        path=_ann_default_sidecar_path(module,b); exists=path.exists(); sidecars.append({"book_id":b,"path":str(path),"exists":exists,"file_sha256":(_kir_hash_bytes(path.read_bytes()) if exists else None)})
    covered={str(r.get("annotation_id") or "") for r in receipt_rows}
    receipt_actions={}
    for r in receipt_rows: receipt_actions[str(r.get("action") or "unknown")]=receipt_actions.get(str(r.get("action") or "unknown"),0)+1
    return {"ok":True,"version":_ANN_VERSION,"owner":_ANN_OWNER,"storage":{"database":str(getattr(module,"DATABASE_FILE","")),"annotation_table":_ANN_TABLE,"receipt_table":_ANN_RECEIPT_TABLE,"portable_sidecar_name":"assistant_annotations.enc","sidecars":sidecars},"book_id":bid or None,"counts":{"annotations":len(rows),"active":len(active),"history":len(rows)-len(active),"by_status":status_counts,"orphan_annotation_rows_missing_memory":orphan_memory,"receipts":len(receipt_rows),"annotations_with_receipts":sum(1 for r in rows if str(r.get("annotation_id") or "") in covered),"legacy_annotations_without_receipts":sum(1 for r in rows if str(r.get("annotation_id") or "") not in covered),"receipt_actions":receipt_actions},"revision_chains":_ann_revision_chains(rows),"target_health":{"checked":checked,"check_limit":lim,"active_total":len(active),"complete":checked>=len(active),"fresh":fresh,"stale":stale,"broken":broken,"items":target_items},"recent_receipts":[{"receipt_id":r.get("receipt_id"),"action":r.get("action"),"annotation_id":r.get("annotation_id"),"status":r.get("annotation_status"),"committed_at":r.get("committed_at"),"receipt_sha256":r.get("receipt_sha256")} for r in receipt_rows[:20]],"read_only":True,"model_calls":0,"canonical_book_fact":False}


def _ann_lifecycle(module, *, annotation_id: str, action: str, reason: str="") -> dict:
    _ann_ensure_schema(module); aid=str(annotation_id or "").strip(); act=str(action or "").casefold().strip()
    if act not in _ANN_LIFECYCLE_ACTIONS: raise ValueError("action must be archive or retract")
    row=_ann_get_row(module,aid)
    if not row: raise ValueError(f"Annotation not found: {aid}")
    if str(row.get("owner") or "")!=_ANN_OWNER: raise ValueError("Annotation ownership mismatch.")
    if str(row.get("status") or "").casefold()!="active": raise ValueError("Only an active annotation can be archived or retracted.")
    clean_reason=" ".join(str(reason or "").split()).strip()
    if act=="retract" and not clean_reason: raise ValueError("A retraction reason is required so the historical record remains interpretable.")
    if not clean_reason: clean_reason="Assistant chose to archive this personal annotation without deleting its history."
    new_status=_ANN_LIFECYCLE_ACTIONS[act]; changed=_ann_now(); mid=str(row.get("memory_id") or ""); memory_sha=str(row.get("memory_sha256") or "")
    receipt=_ann_make_receipt(action=act,annotation_id=aid,memory_id=mid,book_id=str(row.get("book_id") or ""),target_ref=str(row.get("target_ref") or ""),revision=int(row.get("revision") or 1),parent_annotation_id=str(row.get("parent_annotation_id") or ""),annotation_status=new_status,target_sha256=str(row.get("target_sha256") or ""),comment_sha256=str(row.get("comment_sha256") or ""),memory_sha256=memory_sha,committed_at=changed,reason=clean_reason,metadata={"previous_status":"active"})
    with module.db_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            old=db.execute("SELECT payload_json,state,temporal_status FROM memories WHERE id=?",(mid,)).fetchone()
            db.execute("UPDATE assistant_book_annotations SET status=?,modified_at=? WHERE annotation_id=?",(new_status,changed,aid))
            if old:
                memory_state="disputed" if act=="retract" else "archived"
                db.execute("UPDATE memories SET state=?,temporal_status='historical',modified_at=? WHERE id=?",(memory_state,changed,mid))
                db.execute("INSERT INTO memory_history(memory_id,changed_at,action,previous_payload_json,new_payload_json,reason) VALUES(?,?,?,?,?,?)",(mid,changed,f"annotation_{act}",old["payload_json"],old["payload_json"],clean_reason))
            _ann_insert_receipt_tx(db,receipt); db.commit()
        except Exception:
            db.rollback(); raise
    return {"ok":True,"annotation_id":aid,"memory_id":mid,"receipt_id":receipt["receipt_id"],"receipt_sha256":receipt["receipt_sha256"],"action":act,"status":new_status,"revision":int(row.get("revision") or 1),"book_id":row.get("book_id"),"target_ref":row.get("target_ref"),"committed_at":changed,"reason":clean_reason,"committed":True,"content_preserved":True,"history_preserved":True,"personal_memory":True,"canonical_book_fact":False,"source_modified":False,"receipt":receipt,"model_calls":0}


def _ann_sidecar_payload(module, book_id: str) -> dict:
    bid=str(book_id or "").strip(); ident=_ann_book_identity(module,bid); listing=_ann_list(module,book_id=bid,include_history=True,limit=2000)
    records=[]
    with module.db_connect() as db:
        for item in listing["items"]:
            row=db.execute("SELECT * FROM memories WHERE id=?",(item["memory_id"],)).fetchone()
            ann=db.execute("SELECT * FROM assistant_book_annotations WHERE annotation_id=?",(item["annotation_id"],)).fetchone()
            if not row or not ann: continue
            records.append({"annotation":dict(ann),"memory":{"id":row["id"],"tier":row["tier"],"state":row["state"],"type":row["type"],"kind":row["kind"],"domain":row["domain"],"interpretation":row["interpretation"],"summary":row["summary"],"data":row["data"],"version":int(row["version"]),"base_importance":float(row["base_importance"]),"current_importance":float(row["current_importance"]),"confidence":float(row["confidence"]),"activation":float(row["activation"]),"created_at":row["created_at"],"modified_at":row["modified_at"],"observed_at":row["observed_at"],"valid_from":row["valid_from"],"temporal_status":row["temporal_status"],"project_status":row["project_status"],"last_confirmed_at":row["last_confirmed_at"],"content_sha256":row["content_sha256"],"payload_json":row["payload_json"]}})
    core={"schema":_ANN_SIDECAR_SCHEMA,"owner":_ANN_OWNER,"author":_ANN_OWNER,"ownership":"canonical-personal-memory","book":{"book_id":bid,"title":ident.get("title"),"canonical_text_sha256":ident.get("canonical_text_sha256"),"source_file_sha256":ident.get("source_file_sha256")},"records":records,"exported_at":_ann_now()}
    core["manifest_sha256"]=_kir_hash_json({"schema":core["schema"],"owner":core["owner"],"book":core["book"],"records":[{"annotation_id":x["annotation"]["annotation_id"],"memory_id":x["memory"]["id"],"content_sha256":x["memory"]["content_sha256"],"target_sha256":x["annotation"]["target_sha256"],"comment_sha256":x["annotation"]["comment_sha256"]} for x in records]})
    return core


def _ann_default_sidecar_path(module, book_id: str) -> Path:
    return Path(module.safe_memory_path("annotation_exports"))/str(book_id)/"assistant_annotations.enc"


def _ann_export_sidecar(module, book_id: str, path: str="", passphrase: str="") -> dict:
    _portable_passphrase_bytes(passphrase); payload=_ann_sidecar_payload(module,book_id); target=Path(path).expanduser() if str(path or "").strip() else _ann_default_sidecar_path(module,book_id)
    env=_bf_encrypt_json(payload,passphrase,kind=_ANN_SIDECAR_KIND,aad=_ANN_SIDECAR_AAD); rec=_bf_write_envelope(target,env)
    check=_bf_decrypt_json(_bf_read_envelope(target),passphrase,kind=_ANN_SIDECAR_KIND,aad=_ANN_SIDECAR_AAD)
    if not isinstance(check,dict) or check.get("manifest_sha256")!=payload.get("manifest_sha256"): raise ValueError("Annotation sidecar verification failed after write.")
    return {"ok":True,"book_id":book_id,"path":str(target),"annotations":len(payload.get("records") or []),"owner":_ANN_OWNER,"encrypted":True,"cipher":"AES-256-GCM","passphrase_stored":False,"file_sha256":rec.get("sha256"),"manifest_sha256":payload.get("manifest_sha256")}


def _ann_import_sidecar(module, path: str, passphrase: str) -> dict:
    _portable_passphrase_bytes(passphrase); source=Path(str(path or "")).expanduser(); env=_bf_read_envelope(source); payload=_bf_decrypt_json(env,passphrase,kind=_ANN_SIDECAR_KIND,aad=_ANN_SIDECAR_AAD)
    if not isinstance(payload,dict) or payload.get("schema")!=_ANN_SIDECAR_SCHEMA: raise ValueError("Unsupported annotation sidecar schema.")
    if str(payload.get("owner") or "")!=_ANN_OWNER: raise ValueError("Annotation sidecar owner is not Assistant; refusing cross-owner memory import.")
    book=dict(payload.get("book") or {}); bid=str(book.get("book_id") or "").strip(); current=_ann_book_identity(module,bid)
    expected=str(book.get("canonical_text_sha256") or ""); actual=str(current.get("canonical_text_sha256") or "")
    if expected and actual and expected!=actual: raise ValueError("Book canonical SHA-256 differs from the annotation sidecar; refusing silent attachment to different source text.")
    records=list(payload.get("records") or [])
    # Full collision preflight before any write.
    with module.db_connect() as db:
        for rec in records:
            ann=dict((rec or {}).get("annotation") or {}); mem=dict((rec or {}).get("memory") or {}); aid=str(ann.get("annotation_id") or ""); mid=str(mem.get("id") or "")
            if not aid or not mid: raise ValueError("Annotation sidecar contains an incomplete record.")
            arow=db.execute("SELECT comment_sha256,target_sha256,memory_id FROM assistant_book_annotations WHERE annotation_id=?",(aid,)).fetchone()
            if arow and (str(arow["comment_sha256"])!=str(ann.get("comment_sha256")) or str(arow["target_sha256"])!=str(ann.get("target_sha256")) or str(arow["memory_id"])!=mid): raise ValueError(f"Divergent annotation ID collision: {aid}")
            mrow=db.execute("SELECT content_sha256 FROM memories WHERE id=?",(mid,)).fetchone()
            if mrow and str(mrow["content_sha256"])!=str(mem.get("content_sha256")): raise ValueError(f"Divergent personal-memory ID collision: {mid}")
    inserted=0; reused=0
    with module.db_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            for rec in records:
                ann=dict(rec["annotation"]); mem=dict(rec["memory"]); aid=str(ann["annotation_id"]); mid=str(mem["id"])
                exists=db.execute("SELECT 1 FROM assistant_book_annotations WHERE annotation_id=?",(aid,)).fetchone()
                if exists: reused+=1; continue
                if not db.execute("SELECT 1 FROM memories WHERE id=?",(mid,)).fetchone():
                    payload_json=str(mem.get("payload_json") or "{}"); pobj=json.loads(payload_json); digest=module.memory_content_sha256(pobj)
                    if digest!=str(mem.get("content_sha256") or ""): raise ValueError(f"Personal-memory SHA mismatch in sidecar: {mid}")
                    _ann_insert_memory_tx(db,module,memory_id=mid,digest=digest,payload=pobj,confidence=float(mem.get("confidence") or 0.75),created_at=str(mem.get("created_at") or _ann_now()))
                    db.execute("UPDATE memories SET state=?,temporal_status=?,modified_at=? WHERE id=?",(str(mem.get("state") or "validated"),str(mem.get("temporal_status") or "active"),str(mem.get("modified_at") or mem.get("created_at") or _ann_now()),mid))
                db.execute("INSERT INTO assistant_book_annotations(annotation_id,memory_id,owner,author,book_id,target_ref,target_sha256,comment_sha256,confidence,personal_keywords_json,personal_keyword_strengths_json,personal_keyword_apexes_json,personal_keyword_apexes_sha256,personal_keywords_sha256,personal_keyword_source_sha256,keyword_strength_version,keyword_apex_version,revision,parent_annotation_id,status,created_at,modified_at,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                           (aid,mid,str(ann.get("owner") or _ANN_OWNER),str(ann.get("author") or _ANN_OWNER),str(ann.get("book_id") or bid),str(ann.get("target_ref") or ""),str(ann.get("target_sha256") or ""),str(ann.get("comment_sha256") or ""),float(ann.get("confidence") or 0.75),str(ann.get("personal_keywords_json") or "[]"),str(ann.get("personal_keyword_strengths_json") or "{}"),str(ann.get("personal_keyword_apexes_json") or "{}"),str(ann.get("personal_keyword_apexes_sha256") or ""),str(ann.get("personal_keywords_sha256") or ""),str(ann.get("personal_keyword_source_sha256") or ""),str(ann.get("keyword_strength_version") or ""),str(ann.get("keyword_apex_version") or ""),int(ann.get("revision") or 1),ann.get("parent_annotation_id"),str(ann.get("status") or "active"),str(ann.get("created_at") or _ann_now()),str(ann.get("modified_at") or ann.get("created_at") or _ann_now()),str(ann.get("metadata_json") or "{}")))
                inserted+=1
            db.commit()
        except Exception:
            db.rollback(); raise
    try: module.rebuild_memory_index_if_needed(force=False)
    except Exception: pass
    return {"ok":True,"book_id":bid,"owner":_ANN_OWNER,"inserted":inserted,"reused":reused,"records":len(records),"encrypted":True,"source_path":str(source),"canonical_book_sha256":actual or expected or None,"canonical_book_fact":False,"personal_memory":True}


def _ann_benchmark(module, *, book_id: str="", iterations: int=10, echo: bool=True, save_receipt: bool=True) -> dict:
    loops=max(1,min(100,int(iterations or 10))); samples=[]
    bid=str(book_id or "").strip()
    for _ in range(loops):
        t=time.perf_counter(); _ann_list(module,book_id=bid,include_history=True,limit=500); samples.append((time.perf_counter()-t)*1000)
    vals=sorted(samples); median=vals[len(vals)//2]
    result={"ok":True,"kind":"zero_model_personal_annotation_lookup","book_id":bid or None,"iterations":loops,"median_ms":round(median,4),"min_ms":round(min(vals),4),"max_ms":round(max(vals),4),"model_calls":0,"web_calls":0,"read_only":True,"ownership":"Assistant personal memory"}
    if save_receipt and callable(globals().get("_dev_write_benchmark_receipt")):
        try: result["receipt_path"]=str(_dev_write_benchmark_receipt(module,"annotations",result))
        except Exception: pass
    if echo: print(json.dumps(result,ensure_ascii=False,indent=2))
    return result


def _ann_self_test(module=None) -> dict:
    if module is None: module=_load_memory()
    old_dir=module.MEMORY_DIR; old_db=module.DATABASE_FILE; old_books=getattr(module,"_ANN_SELF_TEST_BOOKS",None); old_targets=getattr(module,"_ANN_SELF_TEST_TARGETS",None)
    checks={}
    with tempfile.TemporaryDirectory(prefix="neat-ann-") as td:
        root=Path(td); module.MEMORY_DIR=root; module.DATABASE_FILE=root/"neatmemory_v2.db"; module.initialize_database()
        bid="BK-ANNTEST"; ref=f"evidence:{bid}:{bid}-C000001"; book_sha=_kir_hash_text("canonical annotation test book"); evidence_sha=_kir_hash_text("immutable annotation evidence")
        module._ANN_SELF_TEST_BOOKS={bid:{"book_id":bid,"title":"Annotation Test","canonical_text_sha256":book_sha}}
