            stale=_ann_read(module,second["annotation_id"])
            third=_ann_write(module,book_id=bid,target_ref=ref,comment="A separate observation that I may no longer need active.",confidence=0.61); archived=_ann_lifecycle(module,annotation_id=third["annotation_id"],action="archive",reason="Self-test archive without deleting history.")
            fourth=_ann_write(module,book_id=bid,target_ref=ref,comment="A deliberately retractable interpretation.",confidence=0.55); retracted=_ann_lifecycle(module,annotation_id=fourth["annotation_id"],action="retract",reason="Self-test retraction: Assistant no longer endorses this interpretation.")
            lifecycle_status=_ann_status(module,book_id=bid,check_targets=False); archive_receipt=_ann_read_receipt(module,archived["receipt_id"]); retract_receipt=_ann_read_receipt(module,retracted["receipt_id"])
