    module.formal_structure_persistence_self_test=lambda:formal_structure_persistence_self_test(module)
    module.formal_structure_benchmark_self_test=lambda:formal_structure_benchmark_self_test(module)
    module.run_formal_structure_benchmark=lambda book_id="",iterations=5:_fso_benchmark(module,book_id=book_id,iterations=iterations)

    # Future successful digest/redigest automatically refreshes only this exact
    # deterministic overlay. Installed before authoritative-library write-through,
    # so the outer authority wrapper persists both digest and overlay atomically.
    global _sk_digest_book
    old_digest=_sk_digest_book
    def digest_with_formal_overlay(digest_module, memory_module, backend, book_ref: str, scope_tokens: list[str] | None=None, *, operation: str="digest", deep: bool=False, model_alias: str | None=None, force_full: bool=False) -> dict:
        # Preserve the exact public digest/redigest signature through the formal
        # overlay decorator. In particular --force depends on force_full remaining
        # a first-class API parameter after every installed wrapper.
        result=old_digest(digest_module,memory_module,backend,book_ref,scope_tokens,operation=operation,deep=deep,model_alias=model_alias,force_full=force_full)
        if isinstance(result,dict) and result.get("ok"):
            try:
                bid=str(result.get("book_id") or book_ref); result["formal_structure_overlay"]=_fso_build(memory_module,bid,flush=False)
            except Exception as exc:
                result["formal_structure_overlay"]={"ok":False,"error":f"{type(exc).__name__}: {exc}","model_calls":0,"redigest_required":False}
        return result
    _sk_digest_book=digest_with_formal_overlay

    # Augment semantic-map views rather than rewriting historical semantic unit_kind.
    global _sd_book_map
    globals()["_FSO_BASE_SD_BOOK_MAP"]=_sd_book_map
    old_map=_sd_book_map
    def map_with_formal_overlay(book_id,*args,**kwargs):
        out=old_map(book_id,*args,**kwargs)
        if not isinstance(out,dict) or not out.get("ok"): return out
        memberships=_fso_membership(module,str(book_id));
        for unit in out.get("semantic_units") or []:
            uid=str(unit.get("unit_id") or ""); linked=memberships.get(uid,[])
            if linked:
                unit["formal_overlay_membership"]=linked
                if str(unit.get("unit_kind") or "") in {"front_matter","back_matter"} and any(x.get("boundary_status")=="canonical" for x in linked):
                    unit["formal_effective_role"]="main_text"
                    unit["formal_role_note"]="Historical semantic unit_kind retained; exact formal overlay identifies this source span as canonical literary structure."
        try:
            formal=_fso_view(module,str(book_id),include_nodes=True,node_limit=5000)
            if formal.get("ok"): out["formal_structure_overlay"]=formal
        except Exception: pass
        return out
    _sd_book_map=map_with_formal_overlay

    # Pyramid status/read gains the exact formal layer without changing top synthesis
    # or forcing structural summaries to replace semantic interpretation.
    global _kp_overview, _kp_read_node
    old_overview=_kp_overview; old_read=_kp_read_node
    def overview_with_formal(mod,book_id,*args,**kwargs):
        out=old_overview(mod,book_id,*args,**kwargs)
