            if name=="request_formal_structural_reconciliation": return _fsr_request(module,book_id=str(a.get("book_id") or ""),formal_ref=str(a.get("formal_ref") or ""),reason=str(a.get("reason") or ""),provider=str(a.get("provider") or "online"),model_alias=str(a.get("model_alias") or ""),requested_by="Assistant")
