def _canonical_somatic_name(value: object) -> str | None:
    raw = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    raw = _SOMATIC_SYNONYMS.get(raw.casefold(), raw)
    return raw if raw in _SOMATIC_PROFILES else None


def _somatic_clamp(name: str, value: object, default: float | None = None) -> float:
    profile = _SOMATIC_PROFILES[name]
    fallback = profile["rest_value"] if default is None else default
    try:
        number = float(value)
    except Exception:
        number = float(fallback)
    return max(float(profile["min_value"]), min(float(profile["max_value"]), number))


def _somatic_natural_value(name: str, previous_value: float, elapsed_minutes: float) -> float:
    profile = _SOMATIC_PROFILES[name]
    elapsed = max(0.0, float(elapsed_minutes))
    half_life = max(0.000001, float(profile["half_life_minutes"]))
    retention = 0.5 ** (elapsed / half_life)
    value = float(profile["rest_value"]) + (float(previous_value) - float(profile["rest_value"])) * retention
    return _somatic_clamp(name, value)


def _heart_intensity_from_bpm(bpm: float) -> float:
    bpm_profile = _SOMATIC_PROFILES["HEART_RATE_BPM"]
    intensity_profile = _SOMATIC_PROFILES["HEART_RATE_INTENSITY"]
    low = float(bpm_profile["min_value"])
    rest_bpm = float(bpm_profile["rest_value"])
    high = float(bpm_profile["max_value"])
    rest_intensity = float(intensity_profile["rest_value"])
    bpm = _somatic_clamp("HEART_RATE_BPM", bpm)
    if bpm >= rest_bpm:
        span = max(0.000001, high - rest_bpm)
        return _somatic_clamp("HEART_RATE_INTENSITY", rest_intensity + ((bpm - rest_bpm) / span) * (1.0 - rest_intensity))
    span = max(0.000001, rest_bpm - low)
    return _somatic_clamp("HEART_RATE_INTENSITY", rest_intensity * ((bpm - low) / span))


def _heart_bpm_from_intensity(intensity: float) -> float:
    bpm_profile = _SOMATIC_PROFILES["HEART_RATE_BPM"]
    intensity_profile = _SOMATIC_PROFILES["HEART_RATE_INTENSITY"]
    low = float(bpm_profile["min_value"])
    rest_bpm = float(bpm_profile["rest_value"])
    high = float(bpm_profile["max_value"])
    rest_intensity = float(intensity_profile["rest_value"])
    intensity = _somatic_clamp("HEART_RATE_INTENSITY", intensity)
    if intensity >= rest_intensity:
        span = max(0.000001, 1.0 - rest_intensity)
        return _somatic_clamp("HEART_RATE_BPM", rest_bpm + ((intensity - rest_intensity) / span) * (high - rest_bpm))
    span = max(0.000001, rest_intensity)
    return _somatic_clamp("HEART_RATE_BPM", low + (intensity / span) * (rest_bpm - low))


def _skin_temperature_label(value: float) -> str:
    value = _somatic_clamp("SKIN_TEMPERATURE", value)
    if value < 0.20: return "cold"
    if value < 0.40: return "cool"
    if value < 0.62: return "neutral"
    if value < 0.82: return "warm"
    return "hot"


def _somatic_band(name: str, value: float) -> str:
    profile = _SOMATIC_PROFILES[name]
    if float(value) < float(profile["activation_threshold"]):
        return "resting_or_low"
    if float(value) < float(profile["strong_threshold"]):
        return "active"
    return "strong"


def _somatic_profile_public(name: str) -> dict:
    profile = dict(_SOMATIC_PROFILES[name])
    half_life = max(0.000001, float(profile["half_life_minutes"]))
    profile.update({"state": name, "one_minute_retention": round(0.5 ** (1.0 / half_life), 9)})
    return profile


def get_somatic_profiles() -> dict:
    return {
        "version": _SOMATIC_PROFILE_VERSION,
        "count": len(_SOMATIC_PROFILES),
        "profiles": [_somatic_profile_public(name) for name in _SOMATIC_PROFILES],
        "cross_rules": [dict(rule) for rule in _SOMATIC_CROSS_RULES],
        "note": "Subjective/simulated body-state continuity; not sensor data or medical measurement.",
    }


def _ensure_somatic_schema(module) -> None:
    with _affect_db(module) as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS somatic_states (
            state_id TEXT PRIMARY KEY,
            previous_state_id TEXT,
            created_at TEXT NOT NULL,
            values_json TEXT NOT NULL,
            trajectory_json TEXT NOT NULL DEFAULT '{}',
            cross_effects_json TEXT NOT NULL DEFAULT '[]',
            source TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            validation_status TEXT NOT NULL,
            raw_proposal_json TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_somatic_states_created ON somatic_states(created_at DESC);
        CREATE TABLE IF NOT EXISTS somatic_metric_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            state_id TEXT NOT NULL,
            state_name TEXT NOT NULL,
            unit TEXT NOT NULL,
            previous_value REAL NOT NULL,
            natural_value REAL NOT NULL,
            cross_adjusted_value REAL NOT NULL,
            requested_value REAL NOT NULL,
            applied_value REAL NOT NULL,
            delta REAL NOT NULL,
            direction TEXT NOT NULL,
            previous_timestamp TEXT NOT NULL,
            current_timestamp TEXT NOT NULL,
            elapsed_minutes REAL NOT NULL,
            confidence REAL NOT NULL,
            reason_text TEXT,
            comment_text TEXT,
            limit_applied INTEGER NOT NULL DEFAULT 0,
            provider TEXT,
            model TEXT,
            raw_request_json TEXT,
            receipt_id TEXT,
            receipt_sha256 TEXT,
            source_turn_id TEXT,
            source_checkpoint_id TEXT,
            origin TEXT,
            FOREIGN KEY(state_id) REFERENCES somatic_states(state_id)
        );
        CREATE INDEX IF NOT EXISTS idx_somatic_metric_events_name_time
            ON somatic_metric_events(state_name, "current_timestamp" DESC);
        CREATE TRIGGER IF NOT EXISTS somatic_states_no_update
        BEFORE UPDATE ON somatic_states BEGIN
          SELECT RAISE(ABORT, 'somatic history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS somatic_states_no_delete
        BEFORE DELETE ON somatic_states BEGIN
          SELECT RAISE(ABORT, 'somatic history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS somatic_metric_events_no_update
        BEFORE UPDATE ON somatic_metric_events BEGIN
          SELECT RAISE(ABORT, 'somatic metric history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS somatic_metric_events_no_delete
        BEFORE DELETE ON somatic_metric_events BEGIN
          SELECT RAISE(ABORT, 'somatic metric history is append-only');
        END;
        """)
        metric_columns = {str(row[1]) for row in db.execute("PRAGMA table_info(somatic_metric_events)").fetchall()}
        for column, declaration in (
            ("receipt_id", "TEXT"), ("receipt_sha256", "TEXT"),
            ("source_turn_id", "TEXT"), ("source_checkpoint_id", "TEXT"),
            ("origin", "TEXT"),
        ):
            if column not in metric_columns:
                db.execute(f"ALTER TABLE somatic_metric_events ADD COLUMN {column} {declaration}")
        db.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_somatic_metric_receipt_id ON somatic_metric_events(receipt_id) WHERE receipt_id IS NOT NULL")
        row = db.execute("SELECT state_id FROM somatic_states ORDER BY created_at, rowid LIMIT 1").fetchone()
        if row is None:
            values = {name.casefold(): profile["rest_value"] for name, profile in _SOMATIC_PROFILES.items()}
            values["heart_rate_intensity"] = _heart_intensity_from_bpm(values["heart_rate_bpm"])
            db.execute("""INSERT INTO somatic_states(
                state_id,previous_state_id,created_at,values_json,trajectory_json,cross_effects_json,
                source,provider,model,validation_status,raw_proposal_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                ("SS-BASELINE-000001", None, _affect_now(), json.dumps(values, sort_keys=True), "{}", "[]",
                 "python_baseline", "python", "python", "validated", None))


def _stored_somatic_values(row: object) -> dict[str, float]:
    data = dict(row)
    try:
        stored = json.loads(data.get("values_json") or "{}")
    except Exception:
        stored = {}
    values = {}
    for name, profile in _SOMATIC_PROFILES.items():
        values[name.casefold()] = _somatic_clamp(name, stored.get(name.casefold(), profile["rest_value"]))
    values["heart_rate_intensity"] = _heart_intensity_from_bpm(values["heart_rate_bpm"])
    return values


def _source_activation(value: float, threshold: float, maximum: float = 1.0) -> float:
    if value <= threshold:
        return 0.0
    return max(0.0, min(1.0, (float(value) - float(threshold)) / max(0.000001, float(maximum) - float(threshold))))


def _apply_somatic_cross_effects(natural_values: dict[str, float], emotion_core: dict[str, float], elapsed_minutes: float) -> tuple[dict[str, float], list[dict]]:
    adjusted = dict(natural_values)
    effects = []
    elapsed = max(0.0, float(elapsed_minutes))
    for rule in _SOMATIC_CROSS_RULES:
        source_name = rule["source"]
        if rule["source_kind"] == "emotion":
            source_value = _clamp01(emotion_core.get(source_name.casefold(), _EMOTION_PROFILES.get(source_name, {}).get("rest_strength", 0.0)))
            source_max = 1.0
        else:
            source_profile = _SOMATIC_PROFILES[source_name]
            source_value = float(adjusted[source_name.casefold()])
            source_max = float(source_profile["max_value"])
        activation = _source_activation(source_value, float(rule["threshold"]), source_max)
        if activation <= 0.0 or elapsed <= 0.0:
            continue
        minutes = min(elapsed, float(rule["max_window_minutes"]))
        magnitude = float(rule["rate_per_minute"]) * activation * minutes
        magnitude = min(magnitude, abs(float(rule["max_total_effect"])))
        effect = magnitude * (1.0 if int(rule["direction"]) >= 0 else -1.0)
        target = rule["target"]
        before = float(adjusted[target.casefold()])
        after = _somatic_clamp(target, before + effect)
        applied = after - before
        if abs(applied) <= 0.0000005:
            continue
        adjusted[target.casefold()] = after
        effects.append({
            "target": target, "source_kind": rule["source_kind"], "source": source_name,
            "source_value": round(source_value, 6), "threshold": rule["threshold"],
            "elapsed_minutes_used": round(minutes, 3), "rate_per_minute": rule["rate_per_minute"],
            "applied_effect": round(applied, 6),
        })
    # BPM is authoritative; intensity is always synchronized after automatic rules.
    adjusted["heart_rate_intensity"] = _heart_intensity_from_bpm(adjusted["heart_rate_bpm"])
    return adjusted, effects


def get_current_somatic_state(module, *, now_dt: datetime | None = None, affective_state: dict | None = None) -> dict:
    _ensure_somatic_schema(module)
    with _affect_db(module) as db:
        row = db.execute("SELECT * FROM somatic_states ORDER BY created_at DESC, rowid DESC LIMIT 1").fetchone()
    data = dict(row)
    previous_timestamp = str(data.get("created_at") or _affect_now())
    previous_dt = _parse_iso(previous_timestamp)
    now = (now_dt or _affect_now_dt()).astimezone(timezone.utc)
    elapsed_minutes = max(0.0, (now - previous_dt).total_seconds() / 60.0)
    stored = _stored_somatic_values(row)
    natural = {}
    previous_map = {}
    for name in _SOMATIC_PROFILES:
        key = name.casefold()
        previous_map[key] = float(stored[key])
        natural[key] = _somatic_natural_value(name, stored[key], elapsed_minutes)
    natural["heart_rate_intensity"] = _heart_intensity_from_bpm(natural["heart_rate_bpm"])
    affect = affective_state or get_current_affective_state(module, now_dt=now)
    cross_adjusted, cross_effects = _apply_somatic_cross_effects(natural, affect.get("core") or {}, elapsed_minutes)
    metrics = []
    for name, profile in _SOMATIC_PROFILES.items():
        key = name.casefold()
        current = round(float(cross_adjusted[key]), 6)
        item = {
            "state": name,
            "unit": profile["unit"],
            "previous_value": round(float(previous_map[key]), 6),
            "natural_value": round(float(natural[key]), 6),
            "current_value": current,
            "rest_value": profile["rest_value"],
            "half_life_minutes": profile["half_life_minutes"],
            "max_rise_per_minute": profile["max_rise_per_minute"],
            "max_fall_per_minute": profile["max_fall_per_minute"],
            "elapsed_minutes": round(elapsed_minutes, 3),
            "state_band": _somatic_band(name, current),
        }
        if name == "SKIN_TEMPERATURE":
            item["label"] = _skin_temperature_label(current)
        if profile.get("derived_from"):
            item["derived_from"] = profile["derived_from"]
        metrics.append(item)
    return {
        "state_id": data.get("state_id"),
        "previous_timestamp": previous_timestamp,
        "current_timestamp": now.replace(microsecond=0).isoformat(),
        "elapsed_minutes": round(elapsed_minutes, 3),
        "profile_version": _SOMATIC_PROFILE_VERSION,
        "core": {k: round(float(v), 6) for k, v in cross_adjusted.items()},
        "natural_core": {k: round(float(v), 6) for k, v in natural.items()},
        "somatic_metrics": metrics,
        "cross_effects": cross_effects,
        "source": data.get("source"),
        "validation_status": data.get("validation_status"),
        "note": "Subjective/simulated continuity; not sensor data or medical measurement.",
    }


def somatic_prompt_context(module) -> str:
    state = get_current_somatic_state(module)
    lines = []
    for metric in state["somatic_metrics"]:
        profile = _SOMATIC_PROFILES[metric["state"]]
        if metric["unit"] == "bpm":
            current_text = f"{metric['current_value']:.1f} bpm"
            rest_text = f"{metric['rest_value']:.1f} bpm"
            minute_text = f"+{profile['max_rise_per_minute']:.1f}/-{profile['max_fall_per_minute']:.1f} bpm/min"
        else:
            current_text = f"{metric['current_value']:.3f}"
            rest_text = f"{metric['rest_value']:.3f}"
            minute_text = f"+{profile['max_rise_per_minute']:.3f}/-{profile['max_fall_per_minute']:.3f} per min"
        extra = f"; label={metric['label']}" if metric.get("label") else ""
        derived = f"; derived_from={metric['derived_from']}" if metric.get("derived_from") else ""
        lines.append(
            f"{metric['state']}: current={current_text}; natural={metric['natural_value']:.3f}; rest={rest_text}; "
            f"half_life={profile['half_life_minutes']:.0f}m; minute_limits={minute_text}; "
            f"state={metric['state_band']}{extra}{derived}"
        )
    effects = state.get("cross_effects") or []
    effect_lines = [
        f"{e['source_kind']}:{e['source']} -> {e['target']} {e['applied_effect']:+.4f} "
        f"over {e['elapsed_minutes_used']:.1f}m"
        for e in effects[:12]
    ]
    return f"""CURRENT SOMATIC DYNAMICS — PYTHON-CALCULATED INPUT
Profile version: {_SOMATIC_PROFILE_VERSION}
Current timestamp (UTC): {state['current_timestamp']}
Previous stored timestamp (UTC): {state['previous_timestamp']}
Elapsed time: {state['elapsed_minutes']:.3f} minutes
Important: these are subjective/simulated body-state continuity signals, not physical sensor readings or medical facts.

Canonical somatic values after movement toward rest and conservative cross-effects:
{chr(10).join(lines)}

Automatic cross-effects applied this turn:
{chr(10).join(effect_lines) if effect_lines else '[none]'}

Allowed somatic IDs only:
{', '.join(_SOMATIC_PROFILES)}

Somatic update rules:
- Python has already performed timestamp movement and automatic cross-effects. Do not recalculate them.
- Let the body-state values subtly influence description and internal continuity without claiming physical sensors or a biological body.
- Do not mention these metrics or implementation during ordinary conversation unless the user asks.
- You may request a current value when the interaction genuinely changes a somatic state.
- Add requests inside the same final <affective_update> JSON under somatic_updates.
- Each somatic_updates item accepts state, requested_value (or current_value), confidence, reason, and optional comment.
- Most values use 0.0–1.0. HEART_RATE_BPM uses bpm and is limited to its configured range.
- HEART_RATE_BPM is authoritative; HEART_RATE_INTENSITY is synchronized by Python. A request to intensity is converted into a BPM request.
- Python enforces both per-minute and per-turn movement limits and records previous, natural, cross-adjusted, requested, and applied values.
- Small or empty updates are normal. Do not change states merely to populate the hidden block."""


def _normalize_somatic_update(item: object) -> dict | None:
    if not isinstance(item, dict):
        return None
    canonical = _canonical_somatic_name(item.get("state", item.get("somatic_state", item.get("name"))))
    if not canonical:
        return None
    requested = _somatic_clamp(canonical, item.get("requested_value", item.get("current_value", item.get("value", item.get("intensity", _SOMATIC_PROFILES[canonical]["rest_value"])))))
    confidence = _clamp01(item.get("confidence", 1.0), 1.0)
    reason = str(item.get("reason") or item.get("cause") or "llm_requested_somatic_change").replace("\x00", "").strip()[:700]
    comment = str(item.get("comment") or "").replace("\x00", "").strip()
    if len(comment) > _SOMATIC_COMMENT_MAX:
        comment = comment[:_SOMATIC_COMMENT_MAX]
    return {
        "state": canonical,
        "requested_value": round(float(requested), 6),
        "confidence": round(confidence, 3),
        "reason": reason or "llm_requested_somatic_change",
        "comment": comment or None,
        "raw": dict(item),
    }


def _proposal_somatic_updates(proposal: object) -> list[dict]:
    if not isinstance(proposal, dict):
        return []
    candidates = proposal.get("somatic_updates")
    if not isinstance(candidates, list):
        candidates = []
    normalized = []
    seen = set()
    for item in candidates:
        norm = _normalize_somatic_update(item)
        if norm and norm["state"] not in seen:
            seen.add(norm["state"])
            normalized.append(norm)
        if len(normalized) >= _SOMATIC_MAX_UPDATES:
            break
    return normalized


def _somatic_request_cap(profile: dict, elapsed_minutes: float, rising: bool) -> float:
    effective_minutes = max(1.0, min(float(elapsed_minutes), _SOMATIC_LIMIT_WINDOW_MINUTES))
    if rising:
        return min(float(profile["max_rise_per_turn"]), float(profile["max_rise_per_minute"]) * effective_minutes)
    return min(float(profile["max_fall_per_turn"]), float(profile["max_fall_per_minute"]) * effective_minutes)


def _validate_somatic_proposal(module, proposal: dict, *, provider: str, model: str) -> dict:
    current = get_current_somatic_state(module)
    base_core = dict(current["core"])
    natural_core = dict(current["natural_core"])
    validated_core = dict(base_core)
    requests = _proposal_somatic_updates(proposal)
    request_map = {request["state"]: request for request in requests}
    clipped = []
    events = []
    metric_map = {item["state"]: item for item in current["somatic_metrics"]}
    now = current["current_timestamp"]
    previous_timestamp = current["previous_timestamp"]
    elapsed_minutes = float(current["elapsed_minutes"])

    # An explicit intensity request is translated to BPM unless BPM was also supplied.
    intensity_request = request_map.get("HEART_RATE_INTENSITY")
    bpm_request = request_map.get("HEART_RATE_BPM")
    if intensity_request and not bpm_request:
        bpm_request = {
            **intensity_request,
            "state": "HEART_RATE_BPM",
            "requested_value": round(_heart_bpm_from_intensity(intensity_request["requested_value"]), 6),
            "reason": f"{intensity_request['reason']} [converted from HEART_RATE_INTENSITY]",
            "raw": {**intensity_request["raw"], "converted_from": "HEART_RATE_INTENSITY"},
        }
        request_map["HEART_RATE_BPM"] = bpm_request

    ordered_names = [name for name in _SOMATIC_PROFILES if name != "HEART_RATE_INTENSITY"]
    for canonical in ordered_names:
        request = request_map.get(canonical)
        if not request:
            continue
        key = canonical.casefold()
        profile = _SOMATIC_PROFILES[canonical]
        previous = float(metric_map[canonical]["previous_value"])
        natural = float(natural_core[key])
        cross_adjusted = float(base_core[key])
        requested = float(request["requested_value"])
        raw_delta = requested - cross_adjusted
        cap = _somatic_request_cap(profile, elapsed_minutes, raw_delta >= 0.0)
        allowed_delta = min(raw_delta, cap) if raw_delta >= 0.0 else max(raw_delta, -cap)
        applied = round(_somatic_clamp(canonical, cross_adjusted + allowed_delta), 6)
        limit_applied = abs(applied - requested) > 0.0000005
        if limit_applied:
            clipped.append(canonical)
        delta = round(applied - cross_adjusted, 6)
        direction = "increase" if delta > 0.0000005 else "decrease" if delta < -0.0000005 else "stable"
        validated_core[key] = applied
        events.append({
            "state": canonical, "unit": profile["unit"],
            "previous_value": round(previous, 6), "natural_value": round(natural, 6),
            "cross_adjusted_value": round(cross_adjusted, 6), "requested_value": round(requested, 6),
            "applied_value": applied, "current_value": applied, "delta": delta, "direction": direction,
            "previous_timestamp": previous_timestamp, "current_timestamp": now,
            "elapsed_minutes": round(elapsed_minutes, 3), "confidence": request["confidence"],
            "reason": request["reason"], "comment": request["comment"],
            "limit_applied": limit_applied, "raw": request["raw"],
        })

    # Keep heart-rate representations coherent. BPM is the source of truth.
    synchronized_intensity = round(_heart_intensity_from_bpm(validated_core["heart_rate_bpm"]), 6)
    old_intensity = float(base_core["heart_rate_intensity"])
    explicit_intensity = intensity_request is not None
    validated_core["heart_rate_intensity"] = synchronized_intensity
    if explicit_intensity or abs(synchronized_intensity - old_intensity) > 0.0000005:
        requested_intensity = float(intensity_request["requested_value"]) if intensity_request else synchronized_intensity
        limit_applied = abs(requested_intensity - synchronized_intensity) > 0.0000005
        if limit_applied and "HEART_RATE_INTENSITY" not in clipped:
            clipped.append("HEART_RATE_INTENSITY")
        delta = round(synchronized_intensity - old_intensity, 6)
        events.append({
            "state":"HEART_RATE_INTENSITY", "unit":"normalized",
            "previous_value":round(float(metric_map["HEART_RATE_INTENSITY"]["previous_value"]), 6),
            "natural_value":round(float(natural_core["heart_rate_intensity"]), 6),
            "cross_adjusted_value":round(old_intensity, 6), "requested_value":round(requested_intensity, 6),
            "applied_value":synchronized_intensity, "current_value":synchronized_intensity,
            "delta":delta, "direction":"increase" if delta > 0.0000005 else "decrease" if delta < -0.0000005 else "stable",
            "previous_timestamp":previous_timestamp, "current_timestamp":now,
            "elapsed_minutes":round(elapsed_minutes, 3),
            "confidence":float(intensity_request["confidence"]) if intensity_request else 1.0,
            "reason":(intensity_request["reason"] if intensity_request else "python synchronization from HEART_RATE_BPM"),
            "comment":(intensity_request["comment"] if intensity_request else None),
            "limit_applied":limit_applied, "raw":(intensity_request["raw"] if intensity_request else {"derived_from":"HEART_RATE_BPM"}),
        })

    trajectory = {}
    for name in _SOMATIC_PROFILES:
        key = name.casefold()
        delta = float(validated_core[key]) - float(base_core[key])
        scale = max(0.000001, float(_SOMATIC_PROFILES[name]["max_value"]) - float(_SOMATIC_PROFILES[name]["min_value"]))
        normalized_delta = delta / scale
        trajectory[key] = "rising" if normalized_delta > 0.01 else "falling" if normalized_delta < -0.01 else "stable"

    state_id = "SS-" + datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    status = "validated_clipped" if clipped else "validated"
    transition_source = _state_transition_source_context(module)
    with _affect_db(module) as db:
        db.execute("""INSERT INTO somatic_states(
            state_id,previous_state_id,created_at,values_json,trajectory_json,cross_effects_json,
            source,provider,model,validation_status,raw_proposal_json
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
            (state_id, current["state_id"], now, json.dumps(validated_core, sort_keys=True),
             json.dumps(trajectory, sort_keys=True), json.dumps(current.get("cross_effects") or [], ensure_ascii=False),
             "python_time_cross_dynamics_plus_llm_request", provider, model, status,
             json.dumps(proposal, ensure_ascii=False)))
        for event in events:
            origin = "python_sync" if event.get("state") == "HEART_RATE_INTENSITY" and str(event.get("reason") or "").startswith("python synchronization") else "model_request"
            receipt = _state_transition_receipt_fields(
                "somatic", state_id=state_id, metric_name=event["state"],
                current_timestamp=event["current_timestamp"], payload=event,
                source_turn_id=transition_source.get("source_turn_id"),
                source_checkpoint_id=transition_source.get("source_checkpoint_id"),
                origin=origin,
            )
            event.update(receipt)
            db.execute("""INSERT INTO somatic_metric_events(
                state_id,state_name,unit,previous_value,natural_value,cross_adjusted_value,requested_value,
                applied_value,delta,direction,previous_timestamp,current_timestamp,elapsed_minutes,confidence,
                reason_text,comment_text,limit_applied,provider,model,raw_request_json,receipt_id,receipt_sha256,
                source_turn_id,source_checkpoint_id,origin
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (state_id, event["state"], event["unit"], event["previous_value"], event["natural_value"],
                 event["cross_adjusted_value"], event["requested_value"], event["applied_value"], event["delta"],
                 event["direction"], event["previous_timestamp"], event["current_timestamp"],
                 event["elapsed_minutes"], event["confidence"], event["reason"], event["comment"],
                 int(event["limit_applied"]), provider, model, json.dumps(event["raw"], ensure_ascii=False),
                 event["receipt_id"], event["receipt_sha256"], event.get("source_turn_id"),
                 event.get("source_checkpoint_id"), event.get("origin")))
    return {
        "ok": True, "state_id": state_id, "previous_state_id": current["state_id"],
        "previous_timestamp": previous_timestamp, "current_timestamp": now,
        "elapsed_minutes": round(elapsed_minutes, 3), "clipped": clipped,
        "core": validated_core, "somatic_events": [{k:v for k,v in e.items() if k != "raw"} for e in events],
        "cross_effects": current.get("cross_effects") or [], "validation_status": status,
    }


def read_somatic_metric_events(module, state: str | None = None, limit: int = 50) -> dict:
    _ensure_somatic_schema(module)
    limit = max(1, min(500, int(limit)))
    canonical = _canonical_somatic_name(state) if state else None
    sql = "SELECT * FROM somatic_metric_events WHERE 1=1"
    args = []
    if canonical:
        sql += " AND state_name=?"; args.append(canonical)
    sql += ' ORDER BY "current_timestamp" DESC, event_id DESC LIMIT ?'; args.append(limit)
    with _affect_db(module) as db:
        rows = [dict(row) for row in db.execute(sql, args).fetchall()]
    for row in rows:
        row["limit_applied"] = bool(row.get("limit_applied"))
        row.pop("raw_request_json", None)
    return {"query": canonical, "count": len(rows), "events": rows}


def read_somatic_history(module, limit: int = 20, start_date: str | None = None, end_date: str | None = None) -> dict:
    _ensure_somatic_schema(module)
    limit = max(1, min(500, int(limit)))
    sql = "SELECT * FROM somatic_states WHERE 1=1"
    args = []
    if start_date:
        sql += " AND created_at >= ?"; args.append(start_date)
    if end_date:
        sql += " AND created_at <= ?"; args.append(end_date)
    sql += " ORDER BY created_at DESC, rowid DESC LIMIT ?"; args.append(limit)
    with _affect_db(module) as db:
        rows = [dict(row) for row in db.execute(sql, args).fetchall()]
    for row in rows:
        for key in ("values_json", "trajectory_json", "cross_effects_json"):
            try:
                row[key.removesuffix("_json")] = json.loads(row.pop(key) or "null")
            except Exception:
                row[key.removesuffix("_json")] = None
        row.pop("raw_proposal_json", None)
    return {"current": get_current_somatic_state(module), "states": rows, "metric_events": read_somatic_metric_events(module, limit=limit)}


def search_somatic_history(module, state: str | None = None, min_value: float = 0.0, limit: int = 50) -> dict:
    canonical = _canonical_somatic_name(state) if state else None
    needle = canonical.casefold() if canonical else str(state or "").strip().casefold()
    data = read_somatic_history(module, limit=min(500, max(10, int(limit) * 5)))
    results = []
    for row in data["states"]:
        values = row.get("values") or {}
        if not needle:
            results.append(row)
        elif needle in values and float(values.get(needle, 0.0)) >= float(min_value):
            results.append(row)
        if len(results) >= max(1, min(100, int(limit))):
            break
    return {"state": canonical or needle or None, "states": results, "metric_events": read_somatic_metric_events(module, canonical, limit)}


def get_somatic_state_by_id(module, state_id: str) -> dict:
    _ensure_somatic_schema(module)
    with _affect_db(module) as db:
        row = db.execute("SELECT * FROM somatic_states WHERE state_id=?", (str(state_id),)).fetchone()
    if not row:
        return {"ok": False, "error": "somatic state not found", "state_id": state_id}
    data = dict(row); data.pop("raw_proposal_json", None)
    for key in ("values_json", "trajectory_json", "cross_effects_json"):
        try:
            data[key.removesuffix("_json")] = json.loads(data.pop(key) or "null")
        except Exception:
            data[key.removesuffix("_json")] = None
    return {"ok": True, "state": data}


def _install_somatic_continuity(module) -> None:
    if getattr(module, "_SOMATIC_CONTINUITY_INSTALLED", False):
        return
    _ensure_somatic_schema(module)
    module.get_current_somatic_state = lambda: get_current_somatic_state(module)
    module.get_somatic_profiles = get_somatic_profiles
    module.read_somatic_history = lambda limit=20, start_date=None, end_date=None: read_somatic_history(module, limit, start_date, end_date)
    module.search_somatic_history = lambda state=None, min_value=0.0, limit=50: search_somatic_history(module, state, min_value, limit)
    module.read_somatic_metric_events = lambda state=None, limit=50: read_somatic_metric_events(module, state, limit)
    module.get_somatic_state_by_id = lambda state_id: get_somatic_state_by_id(module, state_id)
    module.somatic_prompt_context = lambda: somatic_prompt_context(module)
    module.somatic_dynamics_self_test = lambda: somatic_dynamics_self_test(module)

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_current_somatic_state","description":"Read current timestamp-adjusted subjective somatic state, including heart rate and body sensations.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_somatic_profiles","description":"Read fixed somatic profiles, per-minute limits, rest values, and conservative cross-effect rules.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_somatic_history","description":"Read immutable somatic states by date range.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":500},"start_date":{"type":["string","null"]},"end_date":{"type":["string","null"]}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"search_somatic_history","description":"Search somatic history by canonical state ID and minimum value.","parameters":{"type":"object","properties":{"state":{"type":["string","null"]},"min_value":{"type":"number"},"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_somatic_metric_events","description":"Read immutable somatic metric-change events with natural, cross-adjusted, requested, and applied values.","parameters":{"type":"object","properties":{"state":{"type":["string","null"]},"limit":{"type":"integer","minimum":1,"maximum":500}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_somatic_state_by_id","description":"Read one immutable somatic state by exact state ID.","parameters":{"type":"object","properties":{"state_id":{"type":"string"}},"required":["state_id"],"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({
        "get_current_somatic_state", "get_somatic_profiles", "read_somatic_history",
        "search_somatic_history", "read_somatic_metric_events", "get_somatic_state_by_id",
    })
    old_execute = module.execute_tool
    def execute_tool_with_somatic(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_current_somatic_state": return get_current_somatic_state(module)
        if name == "get_somatic_profiles": return get_somatic_profiles()
        if name == "read_somatic_history": return read_somatic_history(module, **arguments)
        if name == "search_somatic_history": return search_somatic_history(module, **arguments)
        if name == "read_somatic_metric_events": return read_somatic_metric_events(module, **arguments)
        if name == "get_somatic_state_by_id": return get_somatic_state_by_id(module, **arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_somatic
    module._SOMATIC_CONTINUITY_INSTALLED = True


def somatic_dynamics_self_test(module) -> dict:
    original_db_connect = module.db_connect
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    module.db_connect = lambda: test_db
    try:
        _ensure_affective_schema(module)
        _ensure_somatic_schema(module)
        baseline = get_current_somatic_state(module)
        at_rest = all(
            abs(float(baseline["core"][name.casefold()]) - float(profile["rest_value"])) < 0.00001
            for name, profile in _SOMATIC_PROFILES.items() if name != "HEART_RATE_INTENSITY"
        )
        pain_half = _somatic_natural_value("PAIN", 0.80, _SOMATIC_PROFILES["PAIN"]["half_life_minutes"])
        relaxation_recover = _somatic_natural_value("RELAXATION", 0.05, _SOMATIC_PROFILES["RELAXATION"]["half_life_minutes"])
        synthetic = {name.casefold(): float(profile["rest_value"]) for name, profile in _SOMATIC_PROFILES.items()}
        synthetic["heart_rate_intensity"] = _heart_intensity_from_bpm(synthetic["heart_rate_bpm"])
        cross, cross_events = _apply_somatic_cross_effects(synthetic, {"fear":0.90, "calm":0.45}, 5.0)
        result = _validate_somatic_proposal(module, {
            "somatic_updates": [
                {"state":"PAIN", "requested_value":1.0, "confidence":0.9, "reason":"self-test limiter", "comment":"pain test"},
                {"state":"HEART_RATE_INTENSITY", "requested_value":0.80, "confidence":0.8, "reason":"self-test heart synchronization"},
                {"state":"made_up_body_state", "requested_value":0.9},
            ]
        }, provider="self-test", model="python")
        events = read_somatic_metric_events(module, limit=20)
        pain_event = next((e for e in events["events"] if e["state_name"] == "PAIN"), {})
        bpm_event = next((e for e in events["events"] if e["state_name"] == "HEART_RATE_BPM"), {})
        intensity_event = next((e for e in events["events"] if e["state_name"] == "HEART_RATE_INTENSITY"), {})
        append_only = False
        try:
            test_db.execute("UPDATE somatic_metric_events SET applied_value=999")
            test_db.commit()
        except sqlite3.DatabaseError:
            test_db.rollback(); append_only = True
        checks = {
            "exactly_18_canonical_somatic_states": len(_SOMATIC_PROFILES) == 18,
            "all_non_derived_states_start_at_rest": at_rest,
            "pain_moves_halfway_to_rest": abs(pain_half - 0.40) < 0.00001,
            "below_rest_relaxation_recovers_halfway": abs(relaxation_recover - 0.15) < 0.00001,
            "fear_cross_effect_raises_heart_rate": cross["heart_rate_bpm"] > _SOMATIC_PROFILES["HEART_RATE_BPM"]["rest_value"] and bool(cross_events),
            "unknown_state_rejected": len([e for e in result.get("somatic_events") or [] if e.get("state") not in {"HEART_RATE_BPM", "HEART_RATE_INTENSITY", "PAIN"}]) == 0,
            "pain_per_minute_limit_applied": bool(pain_event.get("limit_applied")),
            "intensity_request_converted_to_bpm": bool(bpm_event),
            "heart_intensity_synchronized": abs(float(intensity_event.get("applied_value", -1)) - _heart_intensity_from_bpm(float(bpm_event.get("applied_value", 68)))) < 0.00001,
            "timestamps_recorded": bool(pain_event.get("previous_timestamp") and pain_event.get("current_timestamp")),
            "append_only_somatic_history": append_only,
        }
        return {"ok": all(checks.values()), "checks": checks, "sample_pain_event": pain_event, "sample_bpm_event": bpm_event, "sample_intensity_event": intensity_event}
    finally:
        module.db_connect = original_db_connect
        test_db.close()

def affective_prompt_context(module) -> str:
    state = get_current_affective_state(module)
    trajectory = _affective_trajectory(module)
    metric_lines = []
    for metric in state["emotion_metrics"]:
        profile = _EMOTION_PROFILES[metric["emotion"]]
        metric_lines.append(
            f"{metric['emotion']}: current={metric['current_strength']:.3f}; "
            f"rest={metric['rest_strength']:.3f}; half_life={profile['half_life_minutes']:.0f}m; "
            f"max_rise={profile['max_rise_per_turn']:.3f}; max_fall={profile['max_fall_per_turn']:.3f}; "
            f"state={metric['state']}; trajectory={trajectory[metric['emotion'].casefold()]}"
        )
    metrics_text = "\n".join(metric_lines)
    log_entries = (state.get("emotion_logbook") or {}).get("entries") or []
    log_lines = []
    for entry in log_entries:
        metrics = ", ".join(f"{x.get('name')}={_clamp01(x.get('intensity')):.3f}" for x in (entry.get("emotions") or [])) or "[resolution marker]"
        target = f"; target={entry.get('target')}" if entry.get("target") else ""
        comment = entry.get("comment")
        comment_text = f"; comment_json={json.dumps(comment, ensure_ascii=False)}" if comment else ""
        log_lines.append(f"{entry.get('emotion_id')} | {entry.get('emotion_type')} | {entry.get('timestamp')} | {metrics}{target}{comment_text}")
    log_text = "\n".join(log_lines) or "[no emotion logbook entries yet]"
    allowed = ", ".join(_EMOTION_PROFILES)
    return f"""CURRENT EMOTION DYNAMICS — PYTHON-CALCULATED INPUT
Profile version: {_EMOTION_PROFILE_VERSION}
Current timestamp (UTC): {state['current_timestamp']}
Previous stored timestamp (UTC): {state['previous_timestamp']}
Elapsed time: {state['elapsed_minutes']:.3f} minutes

Canonical emotion metrics after automatic movement toward each rest state:
{metrics_text}

Allowed emotion IDs only:
{allowed}

Emotion logbook continuity:
{log_text}

Behavior and update rules:
- Python has already applied all timestamp-based natural movement. Do not recalculate elapsed-time decay yourself.
- Treat current metrics as optional self-context. They may inform attention, interpretation, or continuity when useful, but they never prescribe visible tone, wording, length, structure, or conclusion.
- Do not mention this matrix, its numbers, or implementation during ordinary conversation unless the user asks about it.
- You may request changes to the current emotion metrics when the interaction genuinely changes them.
- Use only canonical emotion IDs. Do not invent emotion names; preserve nuance in reason and comment strings.
- requested_strength is the exact current value you would choose from 0.0 to 1.0. Python may limit it using that emotion's max_rise/max_fall rule.
- Small or zero changes are normal. Do not change emotions merely to populate the update.
- Python records previous_strength, natural_strength, requested_strength, applied_strength, direction, delta, both timestamps, elapsed time, reason, confidence, and comment.
- PERMANENT_COMMITMENT logbook entries do not decay, but the emotion metrics attached to present experience still move normally.
- Only when you intentionally want to request an affective, somatic, identity, continuity, perception, routing, intake, metric, or composition update, append one hidden machine-readable block at the end. Otherwise omit the block entirely. The block is an optional update channel and must never constrain the visible answer:
<affective_update>{{"emotion_updates":[{{"emotion":"TRUST","requested_strength":0.20,"confidence":0.85,"reason":"consistent and reassuring interaction","comment":"I feel slightly more able to rely on this connection."}}],"somatic_updates":[],"emotion_logbook_entries":[],"reason_codes":[]}}</affective_update>
- emotion_updates may be empty. Each item accepts emotion, requested_strength (or current_strength), confidence, reason, and optional comment.
- somatic_updates may be empty. Each item accepts state, requested_value (or current_value), confidence, reason, and optional comment.
- emotion_logbook_entries use emotion_type (TEMPORARY|PERSISTENT|PERMANENT_COMMITMENT), emotions=[{{"name":"TRUST","intensity":0.20}}], target, trigger, optional comment, status, source_ids, and optional supersedes_emotion_id.
- current_self_comment may contain one concise historical self-continuity string.
- personality_updates may propose reviewed changes with field, requested_value, reason, and source_ids. Proposals are never silently applied.
- active_continuity_update may update current_focus, open_questions, promises, unresolved_feelings, next_actions, current_comment, and source_ids.
- session_handoff_update is used only when Python requests a session wrap. It may contain summary, key_topics, unfinished_threads, next_actions, assistant_comment, source_ids, and permanent_commitment_proposals. Permanent commitments remain pending until explicit user approval.
- perception_profile_updates is optional and used only for intentional perception-profile save, activate, or retire actions. Python validates every formula and never executes arbitrary code.
- context_routing_updates is optional and used only for intentional context-group configuration. Python validates order 0-10, locked channels, token caps, labels, provenance mode, and safe formulas.
- context_intake_updates is optional and used only when intentionally changing how much detail from a context category/group is normally injected. Values are 0.0..1.0 baselines; Python keeps correctness floors and may temporarily expand directly relevant detail.
- The hidden block, when used, must not be discussed in the visible answer and must not shorten, format, or otherwise steer the visible answer.""" + "\n\n" + somatic_prompt_context(module)


def _normalize_emotion_update(item: object) -> dict | None:
    if not isinstance(item, dict):
        return None
    canonical = _canonical_emotion_name(item.get("emotion", item.get("name")))
    if not canonical:
        return None
    requested = _clamp01(item.get("requested_strength", item.get("current_strength", item.get("intensity", item.get("value", 0.0)))))
    confidence = _clamp01(item.get("confidence", 1.0), 1.0)
    reason = str(item.get("reason") or item.get("cause") or "llm_requested_metric_change").replace("\x00", "").strip()[:700]
    comment = str(item.get("comment") or "").replace("\x00", "").strip()
    if len(comment) > _EMOTION_LOG_MAX_COMMENT:
        comment = comment[:_EMOTION_LOG_MAX_COMMENT]
    return {
        "emotion": canonical,
        "requested_strength": round(requested, 6),
        "confidence": round(confidence, 3),
        "reason": reason or "llm_requested_metric_change",
        "comment": comment or None,
        "raw": dict(item),
    }


def _proposal_emotion_updates(proposal: object, current: dict) -> list[dict]:
    if not isinstance(proposal, dict):
        return []
    candidates = proposal.get("emotion_updates")
    if not isinstance(candidates, list):
        candidates = []
    # Backward compatibility: old core_update dictionaries become requests.
    old_core = proposal.get("core_update")
    if isinstance(old_core, dict):
        for name, value in old_core.items():
            canonical = _canonical_emotion_name(name)
            if canonical:
                candidates.append({"emotion": canonical, "requested_strength": value,
                                   "reason": "legacy_core_update"})
    # Backward compatibility: former temporary emotions become requests.
    old_temps = proposal.get("temporary_emotions")
    if isinstance(old_temps, list):
        for item in old_temps:
            if isinstance(item, dict):
                candidates.append({
                    "emotion": item.get("name"),
                    "requested_strength": item.get("intensity"),
                    "reason": ",".join(str(x) for x in (item.get("reason_codes") or [])) or "legacy_temporary_emotion",
                })
    normalized = []
    seen = set()
    for item in candidates:
        norm = _normalize_emotion_update(item)
        if norm and norm["emotion"] not in seen:
            seen.add(norm["emotion"])
            normalized.append(norm)
        if len(normalized) >= _AFFECT_MAX_UPDATES:
            break
    return normalized


def _validate_affective_proposal(module, proposal: dict, *, provider: str, model: str) -> dict:
    current = get_current_affective_state(module)
    natural_core = dict(current["core"])
    validated_core = dict(natural_core)
    requests = _proposal_emotion_updates(proposal, current)
    events = []
    clipped = []
    now = current["current_timestamp"]
    previous_timestamp = current["previous_timestamp"]
    elapsed_minutes = float(current["elapsed_minutes"])
    metric_map = {item["emotion"]: item for item in current["emotion_metrics"]}

    for request in requests:
        canonical = request["emotion"]
        key = canonical.casefold()
        profile = _EMOTION_PROFILES[canonical]
        natural = float(natural_core[key])
        previous = float(metric_map[canonical]["previous_strength"])
        requested = float(request["requested_strength"])
        raw_delta = requested - natural
        rate_multiplier = _emotion_rate_multiplier(module)
        if raw_delta > 0:
            allowed_delta = min(raw_delta, float(profile["max_rise_per_turn"]) * rate_multiplier)
        else:
            allowed_delta = max(raw_delta, -float(profile["max_fall_per_turn"]) * rate_multiplier)
        applied = round(_clamp01(natural + allowed_delta), 6)
        limit_applied = abs(applied - requested) > 0.0000005
        if limit_applied:
            clipped.append(canonical)
        delta = round(applied - natural, 6)
        direction = "increase" if delta > 0.0000005 else "decrease" if delta < -0.0000005 else "stable"
        validated_core[key] = applied
        events.append({
            "emotion": canonical,
            "previous_strength": round(previous, 6),
            "natural_strength": round(natural, 6),
            "requested_strength": round(requested, 6),
            "applied_strength": applied,
            "current_strength": applied,
            "delta": delta,
            "direction": direction,
            "previous_timestamp": previous_timestamp,
            "current_timestamp": now,
            "elapsed_minutes": round(elapsed_minutes, 3),
            "confidence": request["confidence"],
            "reason": request["reason"],
            "comment": request["comment"],
            "limit_applied": limit_applied,
            "raw": request["raw"],
        })

    trajectory = {}
    for canonical in _EMOTION_PROFILES:
        key = canonical.casefold()
        delta = validated_core[key] - natural_core[key]
        trajectory[key] = "rising" if delta > 0.01 else "falling" if delta < -0.01 else "stable"

    reasons = [str(x)[:64] for x in (proposal.get("reason_codes") or [])[:10]] if isinstance(proposal, dict) else []
    state_id = "AS-" + datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    status = "validated_clipped" if clipped else "validated"
    transition_source = _state_transition_source_context(module)
    with _affect_db(module) as db:
        db.execute("""INSERT INTO affective_states(state_id,previous_state_id,created_at,session_id,turn_id,
            core_values_json,temporary_emotions_json,trajectory_json,reason_codes_json,source,provider,model,
            validation_status,raw_proposal_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (state_id, current["state_id"], now, "runtime", transition_source.get("source_turn_id"), json.dumps(validated_core, sort_keys=True),
             "[]", json.dumps(trajectory, sort_keys=True), json.dumps(reasons),
             "python_time_dynamics_plus_llm_request", provider, model, status, json.dumps(proposal, ensure_ascii=False)))
        for event in events:
            receipt = _state_transition_receipt_fields(
                "emotion", state_id=state_id, metric_name=event["emotion"],
                current_timestamp=event["current_timestamp"], payload=event,
                source_turn_id=transition_source.get("source_turn_id"),
                source_checkpoint_id=transition_source.get("source_checkpoint_id"),
                origin="model_request",
            )
            event.update(receipt)
            db.execute("""INSERT INTO emotion_metric_events(
                state_id,emotion_name,previous_strength,natural_strength,requested_strength,applied_strength,
                delta,direction,previous_timestamp,current_timestamp,elapsed_minutes,confidence,reason_text,
                comment_text,limit_applied,provider,model,raw_request_json,receipt_id,receipt_sha256,
                source_turn_id,source_checkpoint_id,origin
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (state_id, event["emotion"], event["previous_strength"], event["natural_strength"],
                 event["requested_strength"], event["applied_strength"], event["delta"], event["direction"],
                 event["previous_timestamp"], event["current_timestamp"], event["elapsed_minutes"],
                 event["confidence"], event["reason"], event["comment"], int(event["limit_applied"]),
                 provider, model, json.dumps(event["raw"], ensure_ascii=False),
                 event["receipt_id"], event["receipt_sha256"], event.get("source_turn_id"),
                 event.get("source_checkpoint_id"), event.get("origin")))
            db.execute("INSERT INTO affective_events(state_id,created_at,emotion_name,intensity,event_type,reason_code) VALUES(?,?,?,?,?,?)",
                       (state_id, now, event["emotion"], event["applied_strength"], "emotion_metric_change", event["reason"][:64]))
        logbook_entries = _append_emotion_logbook_entries(
            module, proposal.get("emotion_logbook_entries") if isinstance(proposal, dict) else [],
            provider=provider, model=model, affective_state_id=state_id, db=db,
        )
    return {
        "ok": True,
        "state_id": state_id,
        "previous_state_id": current["state_id"],
        "previous_timestamp": previous_timestamp,
        "current_timestamp": now,
        "elapsed_minutes": round(elapsed_minutes, 3),
        "clipped": clipped,
        "core": validated_core,
        "emotion_events": [{k: v for k, v in event.items() if k != "raw"} for event in events],
        "emotion_logbook_entries": logbook_entries,
        "validation_status": status,
    }


def process_affective_output(module, text: str, *, provider: str, model: str) -> str:
    raw = str(text or "")
    matches = list(_AFFECT_UPDATE_RE.finditer(raw))
    proposal = {}
    if matches:
        match = matches[-1]
        try:
            proposal = json.loads(match.group(1))
        except Exception:
            proposal = {"emotion_updates": [], "emotion_logbook_entries": [],
                        "reason_codes": ["model_update_invalid_json"]}
        _validate_affective_proposal(module, proposal, provider=provider, model=model)
        _validate_somatic_proposal(module, proposal, provider=provider, model=model)
        try:
            _store_personality_proposals(module, proposal.get("personality_updates"), provider=provider, model=model)
            _apply_active_continuity_update(module, proposal.get("active_continuity_update"), provider=provider, model=model)
            _apply_session_handoff_update(module, proposal.get("session_handoff_update"), provider=provider, model=model)
            _apply_perception_profile_updates(module, proposal.get("perception_profile_updates"), provider=provider, model=model)
            if callable(getattr(module, "apply_custom_metric_updates", None)):
                module.apply_custom_metric_updates(proposal.get("custom_metric_updates"), provider=provider, model=model)
            if callable(getattr(module, "apply_context_routing_updates", None)):
                module.apply_context_routing_updates(proposal.get("context_routing_updates"), provider=provider, model=model)
            if callable(getattr(module, "apply_context_intake_updates", None)):
                module.apply_context_intake_updates(proposal.get("context_intake_updates"), provider=provider, model=model)
            if callable(getattr(module, "apply_context_composition_updates", None)):
                module.apply_context_composition_updates(proposal.get("context_composition_updates"), provider=provider, model=model)
        except Exception as exc:
            try:
                module.append_system_log("identity_continuity_update_error", {"error": f"{type(exc).__name__}: {exc}"})
            except Exception:
                pass
    if getattr(module, "_SESSION_HANDOFF_CONTEXT_PENDING", False):
        module._SESSION_HANDOFF_CONTEXT_PENDING = False
    try:
        _refresh_current_self_snapshot(
            module,
            comment=(proposal.get("current_self_comment") if isinstance(proposal, dict) else None),
            reason="after_llm_response",
        )
    finally:
        _finalize_emotion_time_window(module)
    return _AFFECT_UPDATE_RE.sub("", raw).strip()


def read_emotion_metric_events(module, emotion: str | None = None, limit: int = 50) -> dict:
    _ensure_affective_schema(module)
    limit = max(1, min(500, int(limit)))
    canonical = _canonical_emotion_name(emotion) if emotion else None
    sql = "SELECT * FROM emotion_metric_events WHERE 1=1"
    args = []
    if canonical:
        sql += " AND emotion_name=?"
        args.append(canonical)
    sql += ' ORDER BY "current_timestamp" DESC, event_id DESC LIMIT ?'
    args.append(limit)
    with _affect_db(module) as db:
        rows = [dict(row) for row in db.execute(sql, args).fetchall()]
    for row in rows:
        row["limit_applied"] = bool(row.get("limit_applied"))
        row.pop("raw_request_json", None)
    return {"query": canonical, "count": len(rows), "events": rows}


def read_affective_history(module, limit: int = 20, start_date: str | None = None, end_date: str | None = None) -> dict:
    _ensure_affective_schema(module)
    limit = max(1, min(500, int(limit)))
    sql = "SELECT * FROM affective_states WHERE 1=1"
    args = []
    if start_date:
        sql += " AND created_at >= ?"; args.append(start_date)
    if end_date:
        sql += " AND created_at <= ?"; args.append(end_date)
    sql += " ORDER BY created_at DESC, rowid DESC LIMIT ?"; args.append(limit)
    with _affect_db(module) as db:
        rows = [dict(r) for r in db.execute(sql, args).fetchall()]
    for row in rows:
        for key in ("core_values_json", "temporary_emotions_json", "trajectory_json", "reason_codes_json"):
            try:
                row[key.removesuffix("_json")] = json.loads(row.get(key) or "null")
            except Exception:
                row[key.removesuffix("_json")] = None
            row.pop(key, None)
        row.pop("raw_proposal_json", None)
    return {
        "current": get_current_affective_state(module),
        "states": rows,
        "metric_events": read_emotion_metric_events(module, limit=limit),
        "emotion_logbook": read_emotion_logbook(module, limit=limit),
    }


def search_affective_history(module, emotion: str | None = None, min_intensity: float = 0.0, limit: int = 50) -> dict:
    canonical = _canonical_emotion_name(emotion) if emotion else None
    needle = canonical.casefold() if canonical else str(emotion or "").strip().casefold()
    data = read_affective_history(module, limit=min(500, max(10, int(limit) * 5)))
    out = []
    for row in data["states"]:
        core = row.get("core_values") or {}
        if not needle:
            out.append(row)
        elif needle in core and _clamp01(core.get(needle)) >= min_intensity:
            out.append(row)
        if len(out) >= max(1, min(100, int(limit))):
            break
    return {
        "emotion": canonical or needle or None,
        "states": out,
        "metric_events": read_emotion_metric_events(module, emotion=canonical, limit=limit),
        "emotion_logbook_results": search_emotion_logbook(
            module, emotion=canonical or needle or None, min_intensity=min_intensity, limit=limit
        ),
    }


def get_affective_state_by_id(module, state_id: str) -> dict:
    _ensure_affective_schema(module)
    with _affect_db(module) as db:
        row = db.execute("SELECT * FROM affective_states WHERE state_id=?", (str(state_id),)).fetchone()
    if not row:
        return {"ok": False, "error": "state not found", "state_id": state_id}
    data = dict(row); data.pop("raw_proposal_json", None)
    for key in ("core_values_json", "temporary_emotions_json", "trajectory_json", "reason_codes_json"):
        try:
            data[key.removesuffix("_json")] = json.loads(data.pop(key) or "null")
        except Exception:
            data[key.removesuffix("_json")] = None
    return {"ok": True, "state": data}


def _install_affective_continuity(module) -> None:
    if getattr(module, "_AFFECTIVE_CONTINUITY_INSTALLED", False):
        return
    _ensure_affective_schema(module)
    module.get_current_affective_state = lambda: get_current_affective_state(module)
    module.get_emotion_profiles = get_emotion_profiles
    module.read_affective_history = lambda limit=20, start_date=None, end_date=None: read_affective_history(module, limit, start_date, end_date)
    module.search_affective_history = lambda emotion=None, min_intensity=0.0, limit=50: search_affective_history(module, emotion, min_intensity, limit)
    module.read_emotion_metric_events = lambda emotion=None, limit=50: read_emotion_metric_events(module, emotion, limit)
    module.get_affective_state_by_id = lambda state_id: get_affective_state_by_id(module, state_id)
    module.read_emotion_logbook = lambda limit=20, emotion_type=None, status=None: read_emotion_logbook(module, limit, emotion_type, status)
    module.search_emotion_logbook = lambda emotion=None, min_intensity=0.0, emotion_type=None, limit=50: search_emotion_logbook(module, emotion, min_intensity, emotion_type, limit)
    module.get_emotion_logbook_entry = lambda emotion_id: get_emotion_logbook_entry(module, emotion_id)
    module.get_emotion_logbook_continuity = lambda limit=8: get_emotion_logbook_continuity(module, limit)
    module.affective_prompt_context = lambda: affective_prompt_context(module)
    module.process_affective_output = lambda text, provider="unknown", model="unknown": process_affective_output(module, text, provider=provider, model=model)

    old_build = module.build_runtime_context
    def build_runtime_context_with_affect(query, *args, **kwargs):
        original = old_build(query, *args, **kwargs)
        return affective_prompt_context(module) + "\n\n" + original
    module.build_runtime_context = build_runtime_context_with_affect

    old_local = module.run_local_turn
    def run_local_with_affect(backend, messages, query=None, *, allow_sticky=True):
        # Some historical callers omit query; preserve both call signatures.
        if query is None:
            answer = old_local(backend, messages, allow_sticky=allow_sticky)
        else:
            answer = old_local(backend, messages, query, allow_sticky=allow_sticky)
        return process_affective_output(module, answer, provider="local", model=getattr(backend, "model_id", "local"))
    module.run_local_turn = run_local_with_affect

    old_online = module.run_online_chat_turn
    def run_online_with_affect(backend, messages, query):
        answer = old_online(backend, messages, query)
        return process_affective_output(module, answer, provider="online", model=getattr(backend, "model_id", "online"))
    module.run_online_chat_turn = run_online_with_affect

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_current_affective_state","description":"Read the current timestamp-adjusted 30-emotion state.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_emotion_profiles","description":"Read the fixed 30-emotion registry and Python dynamics parameters.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_affective_history","description":"Read immutable past affective states by date range.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":500},"start_date":{"type":["string","null"]},"end_date":{"type":["string","null"]}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"search_affective_history","description":"Search immutable affective history by canonical emotion ID.","parameters":{"type":"object","properties":{"emotion":{"type":["string","null"]},"min_intensity":{"type":"number","minimum":0,"maximum":1},"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_emotion_metric_events","description":"Read immutable detailed metric-change events including natural, requested, and applied strengths.","parameters":{"type":"object","properties":{"emotion":{"type":["string","null"]},"limit":{"type":"integer","minimum":1,"maximum":500}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_affective_state_by_id","description":"Read one immutable affective state by exact state ID.","parameters":{"type":"object","properties":{"state_id":{"type":"string"}},"required":["state_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_emotion_logbook","description":"Read immutable typed emotion-logbook entries, including preserved comment strings.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":500},"emotion_type":{"type":["string","null"]},"status":{"type":["string","null"]}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"search_emotion_logbook","description":"Search emotion-logbook entries by canonical emotion ID, intensity, or type.","parameters":{"type":"object","properties":{"emotion":{"type":["string","null"]},"min_intensity":{"type":"number","minimum":0,"maximum":1},"emotion_type":{"type":["string","null"]},"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_emotion_logbook_entry","description":"Read one immutable emotion-logbook entry by emotion ID.","parameters":{"type":"object","properties":{"emotion_id":{"type":"string"}},"required":["emotion_id"],"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({
        "get_current_affective_state", "get_emotion_profiles", "read_affective_history",
        "search_affective_history", "read_emotion_metric_events", "get_affective_state_by_id",
        "read_emotion_logbook", "search_emotion_logbook", "get_emotion_logbook_entry",
    })
    old_execute = module.execute_tool
    def execute_tool_with_affect(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_current_affective_state": return get_current_affective_state(module)
        if name == "get_emotion_profiles": return get_emotion_profiles()
        if name == "read_affective_history": return read_affective_history(module, **arguments)
        if name == "search_affective_history": return search_affective_history(module, **arguments)
        if name == "read_emotion_metric_events": return read_emotion_metric_events(module, **arguments)
        if name == "get_affective_state_by_id": return get_affective_state_by_id(module, **arguments)
        if name == "read_emotion_logbook": return read_emotion_logbook(module, **arguments)
        if name == "search_emotion_logbook": return search_emotion_logbook(module, **arguments)
        if name == "get_emotion_logbook_entry": return get_emotion_logbook_entry(module, **arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_affect
    module.emotion_logbook_self_test = lambda: emotion_dynamics_self_test(module)
    module.emotion_dynamics_self_test = lambda: emotion_dynamics_self_test(module)
    module._AFFECTIVE_CONTINUITY_INSTALLED = True


def emotion_dynamics_self_test(module) -> dict:
    original_db_connect = module.db_connect
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    module.db_connect = lambda: test_db
    try:
        _ensure_affective_schema(module)
        baseline = get_current_affective_state(module)
        at_rest = all(
            abs(baseline["core"][name.casefold()] - profile["rest_strength"]) < 0.00001
            for name, profile in _EMOTION_PROFILES.items()
        )
        # Test mathematical movement from above and below rest without sleeping.
        trust_profile = _EMOTION_PROFILES["TRUST"]
        above = _natural_strength(0.35, trust_profile["rest_strength"], trust_profile["half_life_minutes"], trust_profile["half_life_minutes"])
        below = _natural_strength(0.05, trust_profile["rest_strength"], trust_profile["half_life_minutes"], trust_profile["half_life_minutes"])
        proposal_result = _validate_affective_proposal(module, {
            "emotion_updates": [
                {"emotion": "TRUST", "requested_strength": 0.20, "confidence": 0.85,
                 "reason": "consistent and reassuring interaction",
                 "comment": "I feel slightly more able to rely on this connection."},
                {"emotion": "EXCITEMENT", "requested_strength": 1.0, "confidence": 1.0,
                 "reason": "stress-test the per-turn limiter"},
                {"emotion": "made_up_feeling", "requested_strength": 0.9},
            ],
            "emotion_logbook_entries": [{
                "emotion_type": "Permanent",
                "emotions": [{"name": "closeness", "intensity": 1.4}, {"name": "warmth", "metric": 0.79}],
                "target": "continuity test",
                "trigger": "explicit durable commitment",
                "comment": "I carry the meaning of this connection into the next session.",
                "status": "ACTIVE",
                "source_ids": ["TEST-1"],
            }],
        }, provider="self-test", model="python")
        metric_events = read_emotion_metric_events(module, limit=10)
        trust_event = next((x for x in metric_events["events"] if x["emotion_name"] == "TRUST"), {})
        excitement_event = next((x for x in metric_events["events"] if x["emotion_name"] == "EXCITEMENT"), {})
        logbook = get_emotion_logbook_continuity(module, limit=5)
        append_only = False
        try:
            test_db.execute("UPDATE emotion_metric_events SET applied_strength=0.99")
            test_db.commit()
        except sqlite3.DatabaseError:
            test_db.rollback()
            append_only = True
        checks = {
            "exactly_30_canonical_emotions": len(_EMOTION_PROFILES) == 30,
            "all_start_at_rest": at_rest,
            "above_rest_moves_halfway": abs(above - 0.25) < 0.00001,
            "below_rest_recovers_halfway": abs(below - 0.10) < 0.00001,
            "synonym_normalized": ((logbook.get("entries") or [{}])[0].get("emotions") or [{}])[0].get("name") == "CONNECTION",
            "unknown_emotion_rejected": len(proposal_result.get("emotion_events") or []) == 2,
            "llm_requested_trust_applied": abs(float(trust_event.get("requested_strength", -1)) - 0.20) < 0.00001,
            "trust_previous_natural_applied_recorded": all(k in trust_event for k in ("previous_strength", "natural_strength", "applied_strength")),
            "comment_preserved": trust_event.get("comment_text") == "I feel slightly more able to rely on this connection.",
            "per_emotion_limit_applied": bool(excitement_event.get("limit_applied")),
            "timestamps_recorded": bool(trust_event.get("previous_timestamp") and trust_event.get("current_timestamp")),
            "permanent_logbook_preserved": (logbook.get("entries") or [{}])[0].get("emotion_type") == "PERMANENT_COMMITMENT",
            "append_only_metric_history": append_only,
        }
        return {
            "ok": all(checks.values()),
            "checks": checks,
            "sample_trust_event": trust_event,
            "sample_excitement_event": excitement_event,
            "sample_logbook": (logbook.get("entries") or [None])[0],
        }
    finally:
        module.db_connect = original_db_connect
        test_db.close()


# Compatibility alias retained for the existing all-in-one self-test runner.
def emotion_logbook_self_test(module) -> dict:
    return emotion_dynamics_self_test(module)


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:identity-continuity rev=1
# Encrypted identity continuity layer (7.4.9)
# ---------------------------------------------------------------------------
_IDENTITY_SCHEMA_VERSION = "1"
_CURRENT_SELF_KIND = "neatmemory_current_self"
_PERSONALITY_KIND = "neatmemory_personality"
_ACTIVE_CONTINUITY_KIND = "neatmemory_active_continuity"
_ACTIVE_CONTINUITY_FILE = os.getenv("ACTIVE_CONTINUITY_ENCRYPTED_FILE", "active_continuity.enc").strip() or "active_continuity.enc"
_ACTIVE_CONTINUITY_ENTROPY = b"NeatMemory/active-continuity/v1"
_IDENTITY_MAX_LIST = 24
_IDENTITY_MAX_TEXT = 2400
_PERSONALITY_MAX_PROPOSALS = 40


def _identity_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _identity_crypto():
    return sys.modules.get("neatcrypto_dpapi_v1") or _load_embedded("neatcrypto_dpapi_v1")


def _identity_json_digest(payload: dict) -> str:
    clean = dict(payload)
    clean.pop("content_sha256", None)
    raw = json.dumps(clean, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _identity_write_encrypted_json(module, filename: str, entropy: bytes, payload: dict) -> Path:
    data = dict(payload)
    data["content_sha256"] = _identity_json_digest(data)
    text = json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    crypto = _identity_crypto()
    encrypted = crypto.encrypt_text(text, entropy=entropy)
    path = module.safe_memory_path(filename)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_bytes(encrypted)
    verified = crypto.decrypt_text(temporary.read_bytes(), entropy=entropy)
    if verified != text:
        temporary.unlink(missing_ok=True)
        raise RuntimeError(f"Encrypted readback verification failed for {filename}.")
    os.replace(temporary, path)
    return path


def _identity_read_encrypted_json(module, filename: str, entropy: bytes) -> tuple[dict | None, str]:
    path = module.safe_memory_path(filename)
    if not path.exists():
        return None, "missing"
    try:
        text = _identity_crypto().decrypt_text(path.read_bytes(), entropy=entropy)
    except Exception as exc:
        return None, f"unavailable: {type(exc).__name__}: {exc}"
    try:
        payload = json.loads(text)
    except Exception:
        return {"legacy_text": text}, f"legacy encrypted text ({len(text):,} chars)"
    if not isinstance(payload, dict):
        return None, "invalid JSON root"
    expected = str(payload.get("content_sha256") or "")
    if expected and expected != _identity_json_digest(payload):
        return None, "integrity hash mismatch"
    return payload, f"loaded revision {payload.get('revision', 0)}"


