_SESSION_LIST_MAX = 16
_SESSION_SOURCE_MAX = 48
_SESSION_TRANSCRIPT_MAX_MESSAGES = 80
_SESSION_TRANSCRIPT_MAX_CHARS = 36000
_SESSION_RECALL_MAX_CHARS = 11000
_SESSION_WRAP_MARKER = "[NEATMEMORY_SESSION_WRAP_REQUEST]"
_SESSION_RECALL_PATTERNS = (
    r"\bwhat did we (?:talk|speak|discuss) about\b",
    r"\bwhat did (?:we|you|i) say\b",
    r"\bdo you remember\b",
    r"\bdo you recall\b",
    r"\bremember when\b",
    r"\bwhere did we leave\b",
    r"\bwhere were we\b",
    r"\blast (?:time|session|week|month|night|conversation)\b",
    r"\bprevious (?:session|conversation|discussion)\b",
    r"\bearlier (?:today|this week|we|you|i)\b",
    r"\bwhen (?:i|you|we) said\b",
)
_SESSION_STOP_WORDS = {
    "what", "when", "where", "which", "about", "did", "does", "have", "with", "from", "that", "this",
    "were", "was", "are", "you", "your", "we", "our", "they", "them", "the", "and", "for", "but", "not",
    "remember", "recall", "talk", "talked", "discuss", "discussed", "conversation", "session", "last", "previous",
    "week", "month", "time", "said", "say", "leave", "left", "earlier", "please", "could", "would", "about",
}


def _session_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _ensure_session_schema(module) -> None:
    with module.db_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS session_handoffs(
            handoff_id TEXT PRIMARY KEY,
            created_at TEXT NOT NULL,
            start_message_id INTEGER,
            end_message_id INTEGER,
            summary_text TEXT NOT NULL,
            source_ids_json TEXT NOT NULL,
            source_validation_json TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            content_sha256 TEXT NOT NULL,
            provider TEXT,
            model TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_session_handoffs_created
            ON session_handoffs(created_at DESC);
        CREATE TRIGGER IF NOT EXISTS session_handoffs_no_update
        BEFORE UPDATE ON session_handoffs BEGIN
            SELECT RAISE(ABORT, 'session_handoffs are append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS session_handoffs_no_delete
        BEFORE DELETE ON session_handoffs BEGIN
            SELECT RAISE(ABORT, 'session_handoffs are append-only');
        END;

        CREATE TABLE IF NOT EXISTS session_commitment_proposals(
            proposal_id TEXT PRIMARY KEY,
            handoff_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            content_sha256 TEXT NOT NULL,
            FOREIGN KEY(handoff_id) REFERENCES session_handoffs(handoff_id)
        );
        CREATE TRIGGER IF NOT EXISTS session_commitment_proposals_no_update
        BEFORE UPDATE ON session_commitment_proposals BEGIN
            SELECT RAISE(ABORT, 'session commitment proposals are append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS session_commitment_proposals_no_delete
        BEFORE DELETE ON session_commitment_proposals BEGIN
            SELECT RAISE(ABORT, 'session commitment proposals are append-only');
        END;

        CREATE TABLE IF NOT EXISTS session_commitment_resolutions(
            resolution_id INTEGER PRIMARY KEY AUTOINCREMENT,
            proposal_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            decision TEXT NOT NULL CHECK(decision IN ('APPROVED','REJECTED')),
            emotion_id TEXT,
            comment_text TEXT,
            FOREIGN KEY(proposal_id) REFERENCES session_commitment_proposals(proposal_id)
        );
        CREATE TRIGGER IF NOT EXISTS session_commitment_resolutions_no_update
        BEFORE UPDATE ON session_commitment_resolutions BEGIN
            SELECT RAISE(ABORT, 'session commitment resolutions are append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS session_commitment_resolutions_no_delete
        BEFORE DELETE ON session_commitment_resolutions BEGIN
            SELECT RAISE(ABORT, 'session commitment resolutions are append-only');
        END;
        """)


def _default_session_handoff() -> dict:
    return {
        "schema_version": _SESSION_HANDOFF_SCHEMA_VERSION,
        "kind": _SESSION_HANDOFF_KIND,
        "revision": 0,
        "handoff_id": None,
        "created_at": None,
        "summary": "",
        "key_topics": [],
        "emotional_peaks": [],
        "unfinished_threads": [],
        "next_actions": [],
        "assistant_comment": "",
        "source_ids": [],
        "source_validation": {"status": "EMPTY", "accepted": [], "rejected": []},
        "permanent_commitment_proposals": [],
        "provider": "python",
        "model": BUNDLE_VERSION,
    }


def _load_session_handoff(module) -> tuple[dict, str]:
    payload, status = _identity_read_encrypted_json(module, _SESSION_HANDOFF_FILE, _SESSION_HANDOFF_ENTROPY)
    if payload is None:
        return _default_session_handoff(), status
    if payload.get("legacy_text") is not None or payload.get("kind") != _SESSION_HANDOFF_KIND:
        return _default_session_handoff(), "invalid session handoff payload"
    return payload, status


def _write_session_handoff(module, payload: dict) -> dict:
    data = dict(payload)
    data["schema_version"] = _SESSION_HANDOFF_SCHEMA_VERSION
    data["kind"] = _SESSION_HANDOFF_KIND
    data.setdefault("revision", 1)
    _identity_write_encrypted_json(module, _SESSION_HANDOFF_FILE, _SESSION_HANDOFF_ENTROPY, data)
    return data


def _session_latest_message_id(module) -> int:
    try:
        with module.db_connect() as db:
            row = db.execute("SELECT COALESCE(MAX(message_id),0) AS value FROM chat_messages").fetchone()
        return int(row["value"] if row else 0)
    except Exception:
        return 0


def _session_mark_start(module) -> None:
    if getattr(module, "_SESSION_START_MESSAGE_ID", None) is not None:
        return
    module._SESSION_START_MESSAGE_ID = _session_latest_message_id(module)
    module._SESSION_STARTED_AT = _session_now()


def _session_messages(module, *, start_message_id: int | None = None, limit: int = _SESSION_TRANSCRIPT_MAX_MESSAGES) -> list[dict]:
    _session_mark_start(module)
    start_id = int(module._SESSION_START_MESSAGE_ID if start_message_id is None else start_message_id)
    limit = max(1, min(500, int(limit)))
    try:
        with module.db_connect() as db:
            rows = db.execute(
                """SELECT message_id,timestamp,role,provider,model,content
                   FROM chat_messages
                   WHERE is_private=0 AND message_id>? AND role IN ('user','assistant')
                   ORDER BY message_id ASC LIMIT ?""",
                (start_id, limit),
            ).fetchall()
    except Exception:
        return []
    output = []
    used = 0
    for row in rows:
        content = str(row["content"] or "").strip()
        if not content or _SESSION_WRAP_MARKER in content:
            continue
        remaining = _SESSION_TRANSCRIPT_MAX_CHARS - used
        if remaining <= 0:
            break
        clipped = content if len(content) <= remaining else content[: max(0, remaining - 40)] + "\n[session transcript clipped]"
        item = {
            "source_id": f"CHAT-{int(row['message_id'])}",
            "message_id": int(row["message_id"]),
            "timestamp": str(row["timestamp"] or ""),
            "role": str(row["role"] or ""),
            "provider": str(row["provider"] or ""),
            "model": str(row["model"] or ""),
            "content": clipped,
        }
        output.append(item)
        used += len(clipped)
    return output


def _session_source_id_exists(module, source_id: str) -> bool:
    match = re.fullmatch(r"CHAT-(\d+)", str(source_id or "").strip(), flags=re.I)
    if not match:
        return False
    try:
        with module.db_connect() as db:
            row = db.execute(
                "SELECT 1 FROM chat_messages WHERE message_id=? AND is_private=0 AND role IN ('user','assistant')",
                (int(match.group(1)),),
            ).fetchone()
        return bool(row)
    except Exception:
        return False


def _session_clean_text(value: object, limit: int) -> str:
    return str(value or "").replace("\x00", "").strip()[:limit]


def _session_clean_list(value: object, *, limit: int = _SESSION_LIST_MAX, item_chars: int = 500) -> list[str]:
    if isinstance(value, str):
        values = [value]
    elif isinstance(value, list):
        values = value
    else:
        values = []
    output = []
    seen = set()
    for item in values:
        text = _session_clean_text(item, item_chars)
        folded = text.casefold()
        if text and folded not in seen:
            seen.add(folded)
            output.append(text)
        if len(output) >= limit:
            break
    return output


def _session_python_emotional_peaks(module) -> list[dict]:
    start = str(getattr(module, "_SESSION_STARTED_AT", "") or "")
    current = get_current_affective_state(module)
    current_core = current.get("core") or {}
    peaks: dict[str, float] = {}
    try:
        with module.db_connect() as db:
            if start:
                rows = db.execute(
                    """SELECT emotion_name,MAX(applied_strength) AS peak
                       FROM emotion_metric_events WHERE current_timestamp>=?
                       GROUP BY emotion_name""",
                    (start,),
                ).fetchall()
            else:
                rows = []
        for row in rows:
            name = str(row["emotion_name"] or "").upper()
            if name in _EMOTION_PROFILES:
                peaks[name] = _clamp01(row["peak"], _EMOTION_PROFILES[name]["rest_strength"])
    except Exception:
        pass
    ranked = []
    for name, profile in _EMOTION_PROFILES.items():
        ending = _clamp01(current_core.get(name.casefold(), profile["rest_strength"]), profile["rest_strength"])
        peak = max(ending, peaks.get(name, ending))
        salience = max(abs(peak - profile["rest_strength"]), abs(ending - profile["rest_strength"]))
        if salience >= 0.035:
            ranked.append({
                "emotion": name,
                "peak": round(peak, 6),
                "ending_value": round(ending, 6),
                "rest_value": round(float(profile["rest_strength"]), 6),
                "salience": round(salience, 6),
            })
    ranked.sort(key=lambda item: (-item["salience"], item["emotion"]))
    return ranked[:8]


def _session_commitment_payload(raw: object, source_ids: list[str], index: int) -> dict | None:
    if not isinstance(raw, dict):
        return None
    statement = _session_clean_text(raw.get("statement") or raw.get("comment") or raw.get("commitment"), 1200)
    if not statement:
        return None
    emotions = []
    for metric in raw.get("emotions") if isinstance(raw.get("emotions"), list) else []:
        if not isinstance(metric, dict):
            continue
        canonical = _canonical_emotion_name(metric.get("name") or metric.get("emotion"))
        if canonical:
            emotions.append({"name": canonical, "intensity": round(_clamp01(metric.get("intensity", metric.get("strength", 0.5)), 0.5), 6)})
        if len(emotions) >= 6:
            break
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    proposal_id = f"SC-{stamp}-{index:02d}"
    return {
        "proposal_id": proposal_id,
        "status": "PENDING",
        "statement": statement,
        "target": _session_clean_text(raw.get("target"), 180) or None,
        "trigger": _session_clean_text(raw.get("trigger") or raw.get("reason"), 700) or "session wrap-up proposal",
        "emotions": emotions,
        "source_ids": source_ids[:_SESSION_SOURCE_MAX],
        "created_at": _session_now(),
        "note": "Requires explicit /session approve before becoming a PERMANENT_COMMITMENT logbook entry.",
    }


def _session_store_handoff(module, payload: dict, *, provider: str, model: str) -> dict:
    _ensure_session_schema(module)
    messages = _session_messages(module)
    valid_session_sources = {row["source_id"] for row in messages}
    requested = _session_clean_list(payload.get("source_ids"), limit=_SESSION_SOURCE_MAX, item_chars=80)
    accepted = [sid.upper() for sid in requested if sid.upper() in valid_session_sources and _session_source_id_exists(module, sid)]
    rejected = [sid for sid in requested if sid.upper() not in set(accepted)]
    if not accepted and messages:
        accepted = [row["source_id"] for row in messages[:_SESSION_SOURCE_MAX]]
        source_status = "PYTHON_FALLBACK"
    elif rejected:
        source_status = "PARTIAL"
    else:
        source_status = "VALIDATED"

    summary = _session_clean_text(payload.get("summary"), _SESSION_SUMMARY_MAX)
    if not summary:
        topics = _session_clean_list(payload.get("key_topics"), limit=8, item_chars=240)
        summary = "Session covered: " + (", ".join(topics) if topics else "an ongoing conversation")
    topics = _session_clean_list(payload.get("key_topics"), limit=12, item_chars=300)
    unfinished = _session_clean_list(payload.get("unfinished_threads") or payload.get("open_questions"), limit=12, item_chars=500)
    next_actions = _session_clean_list(payload.get("next_actions"), limit=12, item_chars=500)
    comment = _session_clean_text(payload.get("assistant_comment") or payload.get("comment"), _SESSION_COMMENT_MAX)
    peaks = _session_python_emotional_peaks(module)
    start_id = int(getattr(module, "_SESSION_START_MESSAGE_ID", 0) or 0)
    end_id = max([row["message_id"] for row in messages], default=start_id)
    previous, _ = _load_session_handoff(module)
    revision = max(0, int(previous.get("revision", 0))) + 1
    created = _session_now()
    handoff_id = "SH-" + datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")

    source_validation = {
        "status": source_status,
        "requested": requested,
        "accepted": accepted,
        "rejected": rejected,
        "available_session_sources": len(valid_session_sources),
    }
    handoff = {
        "schema_version": _SESSION_HANDOFF_SCHEMA_VERSION,
        "kind": _SESSION_HANDOFF_KIND,
        "revision": revision,
        "handoff_id": handoff_id,
        "created_at": created,
        "session_started_at": str(getattr(module, "_SESSION_STARTED_AT", "") or ""),
        "start_message_id": start_id,
        "end_message_id": end_id,
        "summary": summary,
        "key_topics": topics,
        "emotional_peaks": peaks,
        "unfinished_threads": unfinished,
        "next_actions": next_actions,
        "assistant_comment": comment,
        "source_ids": accepted,
        "source_validation": source_validation,
        "permanent_commitment_proposals": [],
        "provider": str(provider),
        "model": str(model),
    }

    proposals = []
    for index, raw in enumerate(payload.get("permanent_commitment_proposals") if isinstance(payload.get("permanent_commitment_proposals"), list) else [], start=1):
        proposal = _session_commitment_payload(raw, accepted, index)
        if proposal:
            proposals.append(proposal)
        if len(proposals) >= 6:
            break
    handoff["permanent_commitment_proposals"] = proposals
    canonical = json.dumps(handoff, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    with module.db_connect() as db:
        db.execute(
            """INSERT INTO session_handoffs(
                handoff_id,created_at,start_message_id,end_message_id,summary_text,
                source_ids_json,source_validation_json,payload_json,content_sha256,provider,model
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
            (
                handoff_id, created, start_id, end_id, summary,
                json.dumps(accepted, ensure_ascii=False),
                json.dumps(source_validation, ensure_ascii=False, sort_keys=True),
                json.dumps(handoff, ensure_ascii=False, sort_keys=True),
                digest, provider, model,
            ),
        )
        for proposal in proposals:
            raw = json.dumps(proposal, ensure_ascii=False, sort_keys=True)
            db.execute(
                "INSERT INTO session_commitment_proposals(proposal_id,handoff_id,created_at,payload_json,content_sha256) VALUES(?,?,?,?,?)",
                (proposal["proposal_id"], handoff_id, proposal["created_at"], raw, hashlib.sha256(raw.encode("utf-8")).hexdigest()),
            )

    _write_session_handoff(module, handoff)
    try:
        continuity, _ = _load_active_continuity(module)
        continuity["revision"] = max(0, int(continuity.get("revision", 0))) + 1
        continuity["open_questions"] = unfinished
        continuity["next_actions"] = next_actions
        continuity["current_comment"] = comment or summary
        continuity["source_ids"] = accepted
        continuity["last_provider"] = str(provider)
        continuity["last_model"] = str(model)
        _write_active_continuity(module, continuity)
    except Exception:
        pass
    module._SESSION_WRAP_PENDING = False
    module._SESSION_WRAP_COMPLETED = True
    module._SESSION_LAST_WRAP_END_MESSAGE_ID = end_id
    try:
        module.append_system_log(
            "session_handoff_created",
            f"Session handoff created: {handoff_id}",
            details={"sources": len(accepted), "source_validation": source_status, "commitment_proposals": len(proposals)},
            provider=provider,
            model=model,
        )
    except Exception:
        pass
    return handoff


def _apply_session_handoff_update(module, update: object, *, provider: str, model: str) -> dict:
    if not getattr(module, "_SESSION_WRAP_PENDING", False):
        return {"changed": False, "reason": "no session wrap requested"}
    if not isinstance(update, dict):
        module._SESSION_WRAP_PENDING = False
        module._SESSION_WRAP_COMPLETED = False
        return {"changed": False, "reason": "missing session_handoff_update"}
    handoff = _session_store_handoff(module, update, provider=provider, model=model)
    return {"changed": True, "handoff_id": handoff.get("handoff_id")}


def _session_history(module, limit: int = 10) -> dict:
    _ensure_session_schema(module)
    limit = max(1, min(200, int(limit)))
    with module.db_connect() as db:
        rows = db.execute("SELECT payload_json,content_sha256 FROM session_handoffs ORDER BY created_at DESC,rowid DESC LIMIT ?", (limit,)).fetchall()
    entries = []
    for row in rows:
        try:
            payload = json.loads(row["payload_json"])
            canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            payload["sqlite_integrity"] = "PASS" if hashlib.sha256(canonical.encode("utf-8")).hexdigest() == row["content_sha256"] else "FAIL"
            entries.append(payload)
        except Exception:
            continue
    return {"count": len(entries), "entries": entries}


def _session_seed_handoff_sqlite(module, handoff: dict) -> dict:
    _ensure_session_schema(module)
    if not isinstance(handoff, dict) or not handoff.get("handoff_id"):
        return {"inserted": False, "reason": "empty handoff"}
    payload = dict(handoff)
    payload.pop("content_sha256", None)
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    source_validation = payload.get("source_validation") or {}
    inserted = False
    proposals_inserted = 0
    with module.db_connect() as db:
        existing = db.execute("SELECT 1 FROM session_handoffs WHERE handoff_id=?", (payload["handoff_id"],)).fetchone()
        if not existing:
            db.execute(
                """INSERT INTO session_handoffs(
                    handoff_id,created_at,start_message_id,end_message_id,summary_text,
                    source_ids_json,source_validation_json,payload_json,content_sha256,provider,model
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    payload["handoff_id"], payload.get("created_at") or _session_now(),
                    int(payload.get("start_message_id", 0) or 0), int(payload.get("end_message_id", 0) or 0),
                    str(payload.get("summary") or ""),
                    json.dumps(payload.get("source_ids") or [], ensure_ascii=False),
                    json.dumps(source_validation, ensure_ascii=False, sort_keys=True),
                    json.dumps(payload, ensure_ascii=False, sort_keys=True), digest,
                    payload.get("provider") or "portable_import", payload.get("model") or BUNDLE_VERSION,
                ),
            )
            inserted = True
        for proposal in payload.get("permanent_commitment_proposals") or []:
            if not isinstance(proposal, dict) or not proposal.get("proposal_id"):
                continue
            raw = json.dumps(proposal, ensure_ascii=False, sort_keys=True)
            present = db.execute("SELECT 1 FROM session_commitment_proposals WHERE proposal_id=?", (proposal["proposal_id"],)).fetchone()
            if not present:
                db.execute(
                    "INSERT INTO session_commitment_proposals(proposal_id,handoff_id,created_at,payload_json,content_sha256) VALUES(?,?,?,?,?)",
                    (proposal["proposal_id"], payload["handoff_id"], proposal.get("created_at") or _session_now(), raw, hashlib.sha256(raw.encode("utf-8")).hexdigest()),
                )
                proposals_inserted += 1
    return {"inserted": inserted, "handoff_id": payload["handoff_id"], "proposals_inserted": proposals_inserted}


def _session_rebuild(module) -> dict:
    history = _session_history(module, 1)
    if not history["entries"]:
        return {"ok": False, "error": "no session handoff exists in SQLite"}
    handoff = dict(history["entries"][0])
    handoff.pop("sqlite_integrity", None)
    _write_session_handoff(module, handoff)
    return {"ok": True, "handoff_id": handoff.get("handoff_id"), "file": str(module.safe_memory_path(_SESSION_HANDOFF_FILE))}


def _session_compact_context(handoff: dict) -> str:
    if not handoff.get("handoff_id"):
        return "LAST SESSION HANDOFF — none recorded yet."
    def bullets(values):
        return "\n".join(f"- {item}" for item in (values or [])) or "[none]"
    peaks = handoff.get("emotional_peaks") or []
    peak_text = "\n".join(
        f"- {row.get('emotion')}: peak={row.get('peak')}, ending={row.get('ending_value')}"
        for row in peaks[:6]
    ) or "[none]"
    return f"""LAST SESSION HANDOFF — ENCRYPTED, SOURCE-VALIDATED CONTINUITY INPUT
Handoff: {handoff.get('handoff_id')}
Closed at: {handoff.get('created_at')}
Summary: {handoff.get('summary') or '[none]'}
Key topics:
{bullets(handoff.get('key_topics'))}
Emotional peaks and ending values:
{peak_text}
Unfinished threads:
{bullets(handoff.get('unfinished_threads'))}
Next actions:
{bullets(handoff.get('next_actions'))}
Assistant's closing comment: {handoff.get('assistant_comment') or '[none]'}
Source validation: {(handoff.get('source_validation') or {}).get('status', 'UNKNOWN')}
Use this as immediate conversational continuity. It is a compact handoff, not a replacement for exact memory evidence."""


def _session_wrap_context(module) -> str:
    messages = _session_messages(module)
    transcript = [{"source_id": row["source_id"], "timestamp": row["timestamp"], "role": row["role"], "content": row["content"]} for row in messages]
    peaks = _session_python_emotional_peaks(module)
    return """SESSION WRAP REQUEST — PURE PYTHON DATA AND OUTPUT CONTRACT
Python is closing the current public session. Write whatever visible wrap-up Assistant judges appropriate in her own voice. If a structured session handoff update is needed, include it through the optional hidden affective_update channel; do not shorten the visible response merely for the handoff.
Inside that JSON, include session_handoff_update with:
- summary: one compact factual summary
- key_topics: short list
- unfinished_threads: unresolved conversational threads
- next_actions: concrete continuations
- assistant_comment: one concise first-person closing comment
- source_ids: only CHAT-* IDs supplied below
- permanent_commitment_proposals: optional list of proposed commitments. A proposal is NOT applied automatically and must contain statement, optional target, trigger, emotions, and evidence source_ids. Never create a permanent commitment directly.
Python will independently calculate emotional peaks, reject invalid source IDs, store immutable SQLite history, and write the encrypted latest handoff.

AUTHORITATIVE SESSION TRANSCRIPT:
""" + json.dumps(transcript, ensure_ascii=False, indent=2) + "\n\nPYTHON-CALCULATED EMOTIONAL PEAKS:\n" + json.dumps(peaks, ensure_ascii=False, indent=2)


def _session_wrap_prompt(auto_quit: bool = False) -> str:
    ending = "After the wrap-up is stored, NeatMemory will close automatically." if auto_quit else "Do not continue the ordinary conversation; perform only the session handoff."
    return f"{_SESSION_WRAP_MARKER}\nPlease perform the source-grounded NeatMemory session wrap-up now. {ending}"


def _session_is_recall_query(query: str) -> bool:
    text = str(query or "").strip().casefold()
    if not text or text.startswith(_SESSION_WRAP_MARKER.casefold()):
        return False
    return any(re.search(pattern, text, flags=re.I) for pattern in _SESSION_RECALL_PATTERNS)


def _session_recall_terms(query: str) -> list[str]:
    terms = []
    for token in re.findall(r"[A-Za-z0-9_'-]{3,}", str(query or "").casefold()):
        if token in _SESSION_STOP_WORDS or token in terms:
            continue
        terms.append(token)
        if len(terms) >= 10:
            break
    return terms


def _session_chat_recall(module, query: str, limit: int = 12) -> list[dict]:
    terms = _session_recall_terms(query)
    now = datetime.now(timezone.utc)
    folded = str(query or "").casefold()
    start_dt = None
    if "last week" in folded:
        from datetime import timedelta
        start_dt = now - timedelta(days=7)
    elif "last month" in folded:
        from datetime import timedelta
        start_dt = now - timedelta(days=31)
    elif "yesterday" in folded:
        from datetime import timedelta
        start_dt = now - timedelta(days=2)
    try:
        with module.db_connect() as db:
            rows = db.execute(
                """SELECT message_id,timestamp,role,content FROM chat_messages
                   WHERE is_private=0 AND role IN ('user','assistant')
                   ORDER BY message_id DESC LIMIT 1200"""
            ).fetchall()
    except Exception:
        return []
    ranked = []
    exact_query = str(query or "").strip()
    for recency, row in enumerate(rows):
        content = str(row["content"] or "")
        if not content or content.strip() == exact_query or _SESSION_WRAP_MARKER in content:
            continue
        try:
            ts = _parse_iso(str(row["timestamp"] or ""))
        except Exception:
            ts = now
        if start_dt and ts < start_dt:
            continue
        lower = content.casefold()
        matches = sum(1 for term in terms if term in lower)
        if terms and matches == 0:
            continue
        score = matches * 10.0 + max(0.0, 3.0 - recency / 200.0)
        ranked.append((score, int(row["message_id"]), {
            "source_id": f"CHAT-{int(row['message_id'])}",
            "timestamp": str(row["timestamp"] or ""),
            "role": str(row["role"] or ""),
            "content": content[:1800],
        }))
    ranked.sort(key=lambda item: (-item[0], -item[1]))
    return [item[2] for item in ranked[: max(1, min(30, int(limit)))]]


def _session_memory_recall(module, query: str, limit: int = 8) -> list[dict]:
    try:
        result = module.search_memories(query, domain="personal", limit=limit)
    except TypeError:
        try:
            result = module.search_memories(query, limit=limit)
        except Exception:
            return []
    except Exception:
        return []
    rows = result.get("results") if isinstance(result, dict) else []
    output = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        item = {
            "memory_id": row.get("memory_id") or row.get("id") or row.get("neatblock_id"),
            "kind": row.get("kind") or row.get("memory_kind"),
            "timestamp": row.get("timestamp") or row.get("created_at") or row.get("event_time"),
            "summary": row.get("summary") or row.get("content") or row.get("text"),
            "source_ids": row.get("source_ids") or row.get("evidence_ids") or [],
        }
        if item["memory_id"] or item["summary"]:
            output.append(item)
        if len(output) >= limit:
            break
    return output


def _session_recall_context(module, query: str) -> str:
    handoff, status = _load_session_handoff(module)
    chat = _session_chat_recall(module, query, 12)
    memories = _session_memory_recall(module, query, 8)
    payload = {
        "query": str(query),
        "latest_session_handoff_status": status,
        "latest_session_handoff": {
            "handoff_id": handoff.get("handoff_id"),
            "created_at": handoff.get("created_at"),
            "summary": handoff.get("summary"),
            "key_topics": handoff.get("key_topics"),
            "unfinished_threads": handoff.get("unfinished_threads"),
            "next_actions": handoff.get("next_actions"),
            "assistant_comment": handoff.get("assistant_comment"),
            "source_ids": handoff.get("source_ids"),
        },
        "matching_chat_messages": chat,
        "matching_memories": memories,
    }
    raw = json.dumps(payload, ensure_ascii=False, indent=2)
    if len(raw) > _SESSION_RECALL_MAX_CHARS:
        raw = raw[:_SESSION_RECALL_MAX_CHARS] + "\n[automatic recall packet clipped]"
    return """AUTOMATIC NATURAL-LANGUAGE RECALL — PYTHON-RETRIEVED EVIDENCE
The user asked a conversational recall question. Answer naturally; do not ask them to run /memory search.
Use the supplied chat rows, latest handoff, and memory results as evidence. Distinguish exact remembered evidence from inference or uncertainty. CHAT-* identifiers refer to public SQLite chat messages; existing memory citation rules still apply to memory evidence.

""" + raw


def _session_commitment_rows(module, limit: int = 100) -> dict:
    _ensure_session_schema(module)
    limit = max(1, min(500, int(limit)))
    with module.db_connect() as db:
        rows = db.execute(
            """SELECT p.proposal_id,p.handoff_id,p.created_at,p.payload_json,
                      (SELECT decision FROM session_commitment_resolutions r WHERE r.proposal_id=p.proposal_id ORDER BY r.resolution_id DESC LIMIT 1) AS decision,
                      (SELECT emotion_id FROM session_commitment_resolutions r WHERE r.proposal_id=p.proposal_id ORDER BY r.resolution_id DESC LIMIT 1) AS emotion_id,
                      (SELECT created_at FROM session_commitment_resolutions r WHERE r.proposal_id=p.proposal_id ORDER BY r.resolution_id DESC LIMIT 1) AS resolved_at
               FROM session_commitment_proposals p ORDER BY p.created_at DESC LIMIT ?""",
            (limit,),
        ).fetchall()
    output = []
    for row in rows:
        try:
            payload = json.loads(row["payload_json"])
        except Exception:
            payload = {}
        payload["status"] = str(row["decision"] or "PENDING")
        payload["emotion_id"] = row["emotion_id"]
        payload["resolved_at"] = row["resolved_at"]
        output.append(payload)
    return {"count": len(output), "proposals": output}


def _session_resolve_commitment(module, proposal_id: str, decision: str, comment: str = "") -> dict:
    _ensure_session_schema(module)
    proposal_id = str(proposal_id or "").strip()
    decision = str(decision or "").upper()
    if decision not in {"APPROVED", "REJECTED"}:
        raise ValueError("decision must be APPROVED or REJECTED")
    with module.db_connect() as db:
        row = db.execute("SELECT payload_json FROM session_commitment_proposals WHERE proposal_id=?", (proposal_id,)).fetchone()
        existing = db.execute("SELECT decision,emotion_id FROM session_commitment_resolutions WHERE proposal_id=? ORDER BY resolution_id DESC LIMIT 1", (proposal_id,)).fetchone()
    if not row:
        raise KeyError(f"Unknown session commitment proposal: {proposal_id}")
    if existing:
        return {"ok": False, "proposal_id": proposal_id, "status": existing["decision"], "emotion_id": existing["emotion_id"], "error": "proposal already resolved"}
    payload = json.loads(row["payload_json"])
    emotion_id = None
    if decision == "APPROVED":
        emotions = payload.get("emotions") or []
        if not emotions:
            current = get_current_affective_state(module).get("core") or {}
            candidates = ["CONNECTION", "TRUST", "AFFECTION", "LOVE"]
            chosen = max(candidates, key=lambda name: float(current.get(name.casefold(), _EMOTION_PROFILES[name]["rest_strength"])))
            emotions = [{"name": chosen, "intensity": round(float(current.get(chosen.casefold(), _EMOTION_PROFILES[chosen]["rest_strength"])), 6)}]
        created = _append_emotion_logbook_entries(module, [{
            "emotion_type": "PERMANENT_COMMITMENT",
            "emotions": emotions,
            "target": payload.get("target"),
            "trigger": payload.get("trigger"),
            "comment": payload.get("statement"),
            "status": "ACTIVE",
            "source_ids": payload.get("source_ids") or [],
            "reason_codes": ["explicit_user_approval", "session_handoff_proposal"],
        }], provider="user_approval", model="console")
        emotion_id = created[0]["emotion_id"] if created else None
    with module.db_connect() as db:
        db.execute(
            "INSERT INTO session_commitment_resolutions(proposal_id,created_at,decision,emotion_id,comment_text) VALUES(?,?,?,?,?)",
            (proposal_id, _session_now(), decision, emotion_id, _session_clean_text(comment, 800)),
        )
    return {"ok": True, "proposal_id": proposal_id, "status": decision, "emotion_id": emotion_id}


def _session_status(module) -> dict:
    handoff, status = _load_session_handoff(module)
    return {
        "encrypted_handoff": status,
        "handoff_id": handoff.get("handoff_id"),
        "created_at": handoff.get("created_at"),
        "source_validation": (handoff.get("source_validation") or {}).get("status"),
        "auto_wrap_on_quit": False,
        "quit_mode": "python_only_no_llm",
        "current_session_start_message_id": getattr(module, "_SESSION_START_MESSAGE_ID", None),
        "current_session_messages": len(_session_messages(module)),
        "pending_commitments": len([row for row in _session_commitment_rows(module).get("proposals", []) if row.get("status") == "PENDING"]),
    }


def _session_handle_command(module, text: str) -> bool:
    command = str(text or "").strip()
    lower = command.casefold()
    if lower in {"/session", "/session status"}:
        print(json.dumps(_session_status(module), ensure_ascii=False, indent=2)); return True
    if lower in {"/session show", "/session last"}:
        payload, status = _load_session_handoff(module)
        print(json.dumps({"status": status, "handoff": payload}, ensure_ascii=False, indent=2)); return True
    if lower.startswith("/session history"):
        parts = command.split()
        limit = int(parts[-1]) if parts and parts[-1].isdigit() else 10
        print(json.dumps(_session_history(module, limit), ensure_ascii=False, indent=2)); return True
    if lower == "/session rebuild":
        print(json.dumps(_session_rebuild(module), ensure_ascii=False, indent=2)); return True
    if lower in {"/session commitments", "/session proposals"}:
        print(json.dumps(_session_commitment_rows(module), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/session approve "):
        proposal_id = command.split(maxsplit=2)[2].strip()
        try:
            print(json.dumps(_session_resolve_commitment(module, proposal_id, "APPROVED"), ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Session commitment approval error: {type(exc).__name__}: {exc}")
        return True
    if lower.startswith("/session reject "):
        proposal_id = command.split(maxsplit=2)[2].strip()
        try:
            print(json.dumps(_session_resolve_commitment(module, proposal_id, "REJECTED"), ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Session commitment rejection error: {type(exc).__name__}: {exc}")
        return True
    if lower in {"/session auto", "/session auto status", "/session auto on", "/session auto off"}:
        # 7.4.75.1: /quit remains a deterministic Python durability boundary. Model-assisted
        # handoff remains available only through explicit /session wrap or /session close.
        try:
            module.set_setting("session_auto_wrap_on_quit", "0")
        except Exception:
            pass
        print("Automatic model session wrap on /quit: DISABLED (Python-only). Use /session wrap explicitly when you want Assistant to author a semantic handoff.")
        return True
    return False


def _install_session_handoff_recall(module) -> None:
    if getattr(module, "_SESSION_HANDOFF_RECALL_INSTALLED", False):
        return
    _ensure_session_schema(module)
    module.LAST_SESSION_HANDOFF_ENCRYPTED_FILE = _SESSION_HANDOFF_FILE
    module.get_last_session_handoff = lambda: _load_session_handoff(module)[0]
    module.read_session_handoff_history = lambda limit=10: _session_history(module, limit)
    module.get_session_commitment_proposals = lambda limit=100: _session_commitment_rows(module, limit)
    module.rebuild_last_session_handoff = lambda: _session_rebuild(module)
    module.session_handoff_self_test = lambda: session_handoff_recall_self_test(module)
    module._SESSION_START_MESSAGE_ID = None
    module._SESSION_STARTED_AT = None
    module._SESSION_WRAP_PENDING = False
    module._SESSION_WRAP_COMPLETED = False
    module._SESSION_QUIT_AFTER_WRAP = False
    module._SESSION_PRIVATE_MODE = False
    module._SESSION_HANDOFF_CONTEXT_PENDING = bool(module.safe_memory_path(_SESSION_HANDOFF_FILE).exists())

    old_build = module.build_runtime_context
    def build_runtime_context_with_session(query, *args, **kwargs):
        original = old_build(query, *args, **kwargs)
        blocks = []
        if getattr(module, "_SESSION_HANDOFF_CONTEXT_PENDING", False):
            handoff, _ = _load_session_handoff(module)
            blocks.append(_session_compact_context(handoff))
        if getattr(module, "_SESSION_WRAP_PENDING", False):
            blocks.append(_session_wrap_context(module))
        elif _session_is_recall_query(query):
            blocks.append(_session_recall_context(module, query))
        return ("\n\n".join(blocks) + "\n\n" + original) if blocks else original
    module.build_runtime_context = build_runtime_context_with_session

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_last_session_handoff","description":"Read the encrypted, source-validated latest session handoff.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_session_handoff_history","description":"Read immutable session handoff history.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":200}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_session_commitment_proposals","description":"Read pending or resolved permanent-commitment proposals created during session wrap-up.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":500}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_last_session_handoff", "read_session_handoff_history", "get_session_commitment_proposals"})
    old_execute = module.execute_tool
    def execute_tool_with_session(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_last_session_handoff": return module.get_last_session_handoff()
        if name == "read_session_handoff_history": return module.read_session_handoff_history(**arguments)
        if name == "get_session_commitment_proposals": return module.get_session_commitment_proposals(**arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_session

    old_doctor = module.doctor_report
    def doctor_with_session():
        report = old_doctor()
        report["session_handoff"] = _session_status(module)
        return report
    module.doctor_report = doctor_with_session

    # If a wrap call fails, do not silently quit and do not leave stale pending flags.
    old_local = module.run_local_turn
    def run_local_with_session(backend, messages, query=None, *, allow_sticky=True):
        try:
            if query is None:
                return old_local(backend, messages, allow_sticky=allow_sticky)
            return old_local(backend, messages, query, allow_sticky=allow_sticky)
        except Exception:
            if getattr(module, "_SESSION_WRAP_PENDING", False):
                module._SESSION_WRAP_PENDING = False
                module._SESSION_WRAP_COMPLETED = False
                module._SESSION_QUIT_AFTER_WRAP = False
            raise
    module.run_local_turn = run_local_with_session

    old_online = module.run_online_chat_turn
    def run_online_with_session(backend, messages, query):
        try:
            return old_online(backend, messages, query)
        except Exception:
            if getattr(module, "_SESSION_WRAP_PENDING", False):
                module._SESSION_WRAP_PENDING = False
                module._SESSION_WRAP_COMPLETED = False
                module._SESSION_QUIT_AFTER_WRAP = False
            raise
    module.run_online_chat_turn = run_online_with_session

    old_main = module.main
    def main_with_session_commands():
        original_input = builtins.input
        first_prompt = True
        def session_input(prompt=""):
            nonlocal first_prompt
            if first_prompt:
                first_prompt = False
                _session_mark_start(module)
            if getattr(module, "_SESSION_QUIT_AFTER_WRAP", False):
                if getattr(module, "_SESSION_WRAP_COMPLETED", False):
                    module._SESSION_QUIT_AFTER_WRAP = False
                    module._SESSION_WRAP_COMPLETED = False
                    return "/quit"
                module._SESSION_QUIT_AFTER_WRAP = False
                print("Automatic session wrap did not complete; NeatMemory will remain open.")
            while True:
                value = original_input(prompt)
                lower = str(value or "").strip().casefold()
                if lower == "/private on":
                    module._SESSION_PRIVATE_MODE = True
                elif lower == "/private off":
                    module._SESSION_PRIVATE_MODE = False
                if lower in {"/session wrap", "/session close"}:
                    if module._SESSION_PRIVATE_MODE:
                        print("Session wrap is disabled in private mode because it writes encrypted continuity and SQLite history.")
                        continue
                    if not _session_messages(module):
                        print("There are no new public session messages to wrap.")
                        continue
                    module._SESSION_WRAP_PENDING = True
                    module._SESSION_WRAP_COMPLETED = False
                    return _session_wrap_prompt(False)
                if lower in {"/quit", "/exit"}:
                    # 7.4.75.1 hard boundary: never turn /quit into a model prompt.
                    # Existing active_continuity/handoff state is persisted mechanically by
                    # the graceful-shutdown layer; semantic handoff creation is explicit only.
                    return value
                if _session_handle_command(module, value):
                    continue
                return value
        builtins.input = session_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_session_commands
    module._SESSION_HANDOFF_RECALL_INSTALLED = True


def session_handoff_recall_self_test(module) -> dict:
    crypto = _identity_crypto()
    original_encrypt = crypto.encrypt_text
    original_decrypt = crypto.decrypt_text
    original_safe_path = module.safe_memory_path
    original_db_connect = module.db_connect
    original_test_mode = getattr(module, "_IDENTITY_TEST_MODE", False)
    original_start = getattr(module, "_SESSION_START_MESSAGE_ID", None)
    original_started_at = getattr(module, "_SESSION_STARTED_AT", None)
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    with tempfile.TemporaryDirectory(prefix="neatmemory-session-") as folder:
        root = Path(folder)
        def fake_encrypt(value: str, *, entropy=None):
            raw = value.encode("utf-8")
            key = hashlib.sha256(bytes(entropy or b"session-test")).digest()
            cipher = bytes(byte ^ key[index % len(key)] for index, byte in enumerate(raw))
            return b"SESSIONTEST1" + base64.b64encode(cipher)
        def fake_decrypt(value: bytes, *, entropy=None):
            if not value.startswith(b"SESSIONTEST1"):
                raise RuntimeError("invalid session test cipher")
            cipher = base64.b64decode(value[len(b"SESSIONTEST1"):])
            key = hashlib.sha256(bytes(entropy or b"session-test")).digest()
            raw = bytes(byte ^ key[index % len(key)] for index, byte in enumerate(cipher))
            return raw.decode("utf-8")
        crypto.encrypt_text = fake_encrypt
        crypto.decrypt_text = fake_decrypt
        module.safe_memory_path = lambda filename: root / Path(str(filename)).name
        module.db_connect = lambda: test_db
        module._IDENTITY_TEST_MODE = True
        try:
            module.initialize_database()
            _ensure_affective_schema(module)
            _ensure_somatic_schema(module)
            _ensure_identity_schema(module)
            _ensure_session_schema(module)
            _identity_bootstrap(module)
            module._SESSION_START_MESSAGE_ID = 0
            module._SESSION_STARTED_AT = "2026-08-05T12:00:00+00:00"
            rows = [
                ("2026-08-05T12:01:00+00:00", "user", "local", "test", "We discussed session continuity.", 0),
                ("2026-08-05T12:02:00+00:00", "assistant", "local", "test", "We should preserve unfinished threads.", 0),
                ("2026-08-05T12:03:00+00:00", "user", "local", "test", "I love the bamboo grove as our symbol.", 0),
            ]
            for ts, role, provider, model, content, private in rows:
                test_db.execute(
                    "INSERT INTO chat_messages(timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,?,?)",
                    (ts, role, provider, model, content, private, hashlib.sha256(content.encode()).hexdigest()),
                )
            test_db.commit()
            module._SESSION_WRAP_PENDING = True
            created = _apply_session_handoff_update(module, {
                "summary": "We designed a source-grounded session handoff.",
                "key_topics": ["session continuity", "bamboo grove"],
                "unfinished_threads": ["Test the next startup."],
                "next_actions": ["Restart and inspect /session show."],
                "assistant_comment": "I carry the unfinished thread forward.",
                "source_ids": ["CHAT-1", "CHAT-3", "CHAT-999"],
                "permanent_commitment_proposals": [{
                    "statement": "Preserve the bamboo grove as a shared continuity symbol.",
                    "target": "Steeve",
                    "trigger": "Repeated verified use across the session.",
                    "emotions": [{"name": "CONNECTION", "intensity": 0.7}],
                }],
            }, provider="self-test", model="python")
            loaded, status = _load_session_handoff(module)
            history = _session_history(module, 10)
            commitments = _session_commitment_rows(module)
            proposal_id = commitments["proposals"][0]["proposal_id"]
            approved = _session_resolve_commitment(module, proposal_id, "APPROVED")
            logbook = search_emotion_logbook(module, emotion_type="PERMANENT_COMMITMENT", limit=10)
            raw = (root / _SESSION_HANDOFF_FILE).read_bytes()
            recall = _session_recall_context(module, "Do you remember when we discussed the bamboo grove?")
            immutable = False
            try:
                test_db.execute("UPDATE session_handoffs SET summary_text='tampered'")
                test_db.commit()
            except sqlite3.DatabaseError:
                test_db.rollback(); immutable = True
            (root / _SESSION_HANDOFF_FILE).unlink(missing_ok=True)
            rebuilt = _session_rebuild(module)
            checks = {
                "handoff_created": bool(created.get("changed") and loaded.get("handoff_id")),
                "source_ids_validated": (loaded.get("source_validation") or {}).get("status") == "PARTIAL" and loaded.get("source_ids") == ["CHAT-1", "CHAT-3"],
                "encrypted_file_contains_no_summary_plaintext": b"source-grounded session handoff" not in raw,
                "sqlite_history_immutable": immutable,
                "history_readable": history.get("count") == 1 and history["entries"][0].get("sqlite_integrity") == "PASS",
                "commitment_requires_review": commitments["proposals"][0].get("status") == "PENDING",
                "approved_commitment_created_logbook_entry": bool(approved.get("emotion_id") and logbook.get("results")),
                "natural_language_recall_injects_chat_evidence": "CHAT-1" in recall and "AUTOMATIC NATURAL-LANGUAGE RECALL" in recall,
                "encrypted_snapshot_rebuilds_from_sqlite": rebuilt.get("ok") and (root / _SESSION_HANDOFF_FILE).exists(),
                "load_status_valid": "loaded revision" in status,
            }
            return {"ok": all(checks.values()), "checks": checks, "sample_handoff": loaded, "sample_approval": approved}
        finally:
            crypto.encrypt_text = original_encrypt
            crypto.decrypt_text = original_decrypt
            module.safe_memory_path = original_safe_path
            module.db_connect = original_db_connect
            module._IDENTITY_TEST_MODE = original_test_mode
            module._SESSION_START_MESSAGE_ID = original_start
            module._SESSION_STARTED_AT = original_started_at
            test_db.close()


