_PERCEPTION_ALLOWED_BINOPS = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow)
_PERCEPTION_ALLOWED_UNARYOPS = (ast.UAdd, ast.USub, ast.Not)
_PERCEPTION_ALLOWED_CMPOPS = (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)


def _perception_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _perception_canonical(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _perception_digest(value: object) -> str:
    return hashlib.sha256(_perception_canonical(value).encode("utf-8")).hexdigest()


def _perception_clean_text(value: object, limit: int) -> str:
    return str(value or "").replace("\x00", "").strip()[:limit]


def _perception_safe_identifier(value: object) -> str:
    text = re.sub(r"[^a-zA-Z0-9_]+", "_", str(value or "").strip()).strip("_").casefold()
    if not text or not re.fullmatch(r"[a-z_][a-z0-9_]{0,63}", text):
        raise ValueError(f"Invalid derived-variable name: {value!r}")
    if text in _PERCEPTION_SAFE_FUNCTIONS or text in {"emotion", "somatic", "session", "memory", "context", "time", "derived", "true", "false"}:
        raise ValueError(f"Reserved derived-variable name: {text}")
    return text


def _ensure_perception_schema(module) -> None:
    with module.db_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS perception_profiles (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            profile_id TEXT NOT NULL,
            version INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            name TEXT NOT NULL,
            comment_text TEXT,
            previous_version INTEGER,
            profile_json TEXT NOT NULL,
            profile_sha256 TEXT NOT NULL,
            validation_json TEXT NOT NULL,
            UNIQUE(profile_id, version)
        );
        CREATE INDEX IF NOT EXISTS idx_perception_profiles_latest
            ON perception_profiles(profile_id, version DESC);
        CREATE TABLE IF NOT EXISTS perception_profile_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            profile_id TEXT NOT NULL,
            profile_version INTEGER,
            created_at TEXT NOT NULL,
            event_type TEXT NOT NULL,
            actor TEXT NOT NULL,
            reason_text TEXT,
            payload_json TEXT NOT NULL,
            payload_sha256 TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_perception_events_profile
            ON perception_profile_events(profile_id, created_at DESC, event_id DESC);
        CREATE TABLE IF NOT EXISTS perception_cache (
            cache_key TEXT PRIMARY KEY,
            profile_id TEXT NOT NULL,
            profile_version INTEGER NOT NULL,
            source_revision TEXT NOT NULL,
            query_sha256 TEXT NOT NULL,
            computed_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            packet_json TEXT NOT NULL,
            packet_sha256 TEXT NOT NULL,
            cache_hits INTEGER NOT NULL DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS idx_perception_cache_profile
            ON perception_cache(profile_id, profile_version, computed_at DESC);
        CREATE TRIGGER IF NOT EXISTS perception_profiles_no_update
        BEFORE UPDATE ON perception_profiles BEGIN
            SELECT RAISE(ABORT, 'perception profile history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS perception_profiles_no_delete
        BEFORE DELETE ON perception_profiles BEGIN
            SELECT RAISE(ABORT, 'perception profile history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS perception_events_no_update
        BEFORE UPDATE ON perception_profile_events BEGIN
            SELECT RAISE(ABORT, 'perception profile events are append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS perception_events_no_delete
        BEFORE DELETE ON perception_profile_events BEGIN
            SELECT RAISE(ABORT, 'perception profile events are append-only');
        END;
        """)


def _perception_default_profile() -> dict:
    return {
        "schema_version": _PERCEPTION_SCHEMA_VERSION,
        "profile_id": _PERCEPTION_DEFAULT_ID,
        "name": "Balanced Presence",
        "comment": "General conversation with balanced identity, emotional, somatic, continuity, memory, and context awareness.",
        "source_metrics": [
            "emotion.CONNECTION.current", "emotion.CONNECTION.trend",
            "emotion.TRUST.current", "emotion.TRUST.trend",
            "emotion.CURIOSITY.current", "emotion.STRESS.current",
            "emotion.CALM.current", "emotion.SAFETY.current",
            "somatic.FATIGUE.current", "somatic.ENERGY.current",
            "somatic.HEART_RATE_BPM.current", "somatic.RELAXATION.current",
            "session.unfinished_thread_count", "session.next_action_count",
            "session.hours_since_last_handoff", "memory.recall_confidence",
            "context.remaining_tokens", "context.remaining_ratio",
        ],
        "derived_variables": {
            "felt_safety": "clamp(0.35 * emotion.TRUST.current + 0.30 * emotion.CONNECTION.current + 0.20 * emotion.SAFETY.current + 0.15 * (1 - emotion.STRESS.current), 0, 1)",
            "learning_readiness": "clamp(0.40 * emotion.CURIOSITY.current + 0.25 * somatic.ENERGY.current + 0.20 * memory.recall_confidence + 0.15 * (1 - somatic.FATIGUE.current), 0, 1)",
            "continuity_pressure": "clamp(0.12 * session.unfinished_thread_count + 0.08 * session.next_action_count + 0.02 * min(session.hours_since_last_handoff, 24), 0, 1)",
        },
        "processing": list(_PERCEPTION_ALLOWED_STAGES),
        "output": {
            "always_include": [
                "derived.felt_safety", "derived.learning_readiness", "derived.continuity_pressure",
                "emotion.CONNECTION.current", "emotion.CURIOSITY.current",
                "somatic.FATIGUE.current", "session.unfinished_thread_count",
                "context.remaining_ratio",
            ],
            "include_when_above": {
                "emotion.STRESS.current": 0.42,
                "somatic.HEART_RATE_INTENSITY.current": 0.45,
            },
            "include_when_below": {
                "somatic.ENERGY.current": 0.35,
                "memory.recall_confidence": 0.45,
            },
            "hide_neutral": True,
            "neutral_distance": 0.035,
            "rank_by_salience": True,
            "maximum_variables": 12,
            "maximum_characters": 4800,
            "precision": 3,
            "include_sources": True,
        },
    }


def _perception_event(module, profile_id: str, version: int | None, event_type: str, actor: str, reason: str, payload: object) -> None:
    raw = _perception_canonical(payload)
    with module.db_connect() as db:
        db.execute(
            """INSERT INTO perception_profile_events(
                profile_id,profile_version,created_at,event_type,actor,reason_text,payload_json,payload_sha256
            ) VALUES(?,?,?,?,?,?,?,?)""",
            (profile_id, version, _perception_now(), event_type, actor, _perception_clean_text(reason, 1000), raw,
             hashlib.sha256(raw.encode("utf-8")).hexdigest()),
        )


def _perception_latest_event(module, profile_id: str, event_types: tuple[str, ...] | None = None) -> dict | None:
    _ensure_perception_schema(module)
    sql = "SELECT * FROM perception_profile_events WHERE profile_id=?"
    args: list[object] = [profile_id]
    if event_types:
        placeholders = ",".join("?" for _ in event_types)
        sql += f" AND event_type IN ({placeholders})"
        args.extend(event_types)
    sql += " ORDER BY event_id DESC LIMIT 1"
    with module.db_connect() as db:
        row = db.execute(sql, args).fetchone()
    return dict(row) if row else None


def _perception_is_retired(module, profile_id: str) -> bool:
    row = _perception_latest_event(module, profile_id, ("retired", "restored"))
    return bool(row and row.get("event_type") == "retired")


def _perception_metric_catalog(module, *, include_values: bool = False, query: str = "") -> dict:
    metrics, sources = _perception_collect_metrics(module, query=query)
    entries = []
    for ref, item in sorted(metrics.items()):
        entry = {
            "id": ref,
            "category": item.get("category"),
            "type": "number" if isinstance(item.get("value"), (int, float)) and not isinstance(item.get("value"), bool) else "boolean" if isinstance(item.get("value"), bool) else "text",
            "unit": item.get("unit"),
            "description": item.get("description"),
            "source_id": item.get("source_id"),
        }
        if include_values:
            entry.update({
                "value": item.get("value"), "trend": item.get("trend"),
                "salience": item.get("salience"), "distance_from_rest": item.get("distance_from_rest"),
            })
        entries.append(entry)
    return {
        "schema_version": _PERCEPTION_SCHEMA_VERSION,
        "count": len(entries),
        "metrics": entries,
        "source_revision_inputs": sources,
        "safe_functions": sorted(_PERCEPTION_SAFE_FUNCTIONS),
        "allowed_processing_stages": list(_PERCEPTION_ALLOWED_STAGES),
    }


def _perception_float(value: object, default: float = 0.0) -> float:
    try:
        number = float(value)
        return number if math.isfinite(number) else default
    except Exception:
        return default


def _perception_trend(delta: float, scale: float = 1.0) -> str:
    threshold = max(0.000001, abs(scale) * 0.01)
    if delta > threshold:
        return "increasing"
    if delta < -threshold:
        return "decreasing"
    return "stable"


def _perception_add_metric(output: dict, ref: str, value: object, *, category: str, unit: str | None = None,
                           description: str = "", source_id: str | None = None, trend: str | None = None,
                           distance_from_rest: float | None = None, recent_delta: float | None = None,
                           salience: float = 0.0) -> None:
    if isinstance(value, float):
        value = round(value, 9)
    output[ref] = {
        "value": value,
        "category": category,
        "unit": unit,
        "description": description,
        "source_id": source_id,
        "trend": trend,
        "distance_from_rest": None if distance_from_rest is None else round(float(distance_from_rest), 9),
        "recent_delta": None if recent_delta is None else round(float(recent_delta), 9),
        "salience": round(max(0.0, min(1.0, _perception_float(salience))), 6),
    }


def _perception_collect_metrics(module, *, query: str = "") -> tuple[dict, dict]:
    metrics: dict[str, dict] = {}
    affect = get_current_affective_state(module)
    somatic = get_current_somatic_state(module, affective_state=affect)
    affect_id = str(affect.get("state_id") or "")
    somatic_id = str(somatic.get("state_id") or "")

    for item in affect.get("emotion_metrics") or []:
        name = str(item.get("emotion") or "").upper()
        if not name:
            continue
        current = _perception_float(item.get("current_strength"))
        previous = _perception_float(item.get("previous_strength"), current)
        rest = _perception_float(item.get("rest_strength"))
        delta = current - previous
        distance = current - rest
        salience = min(1.0, abs(distance) * 1.35 + abs(delta) * 3.0)
        root = f"emotion.{name}"
        common = dict(category="emotion", source_id=affect_id, trend=_perception_trend(delta), distance_from_rest=distance, recent_delta=delta, salience=salience)
        _perception_add_metric(metrics, root + ".current", current, description=f"Current timestamp-adjusted {name} strength.", **common)
        _perception_add_metric(metrics, root + ".previous", previous, description=f"Previous stored {name} strength.", **common)
        _perception_add_metric(metrics, root + ".rest", rest, description=f"Configured {name} rest strength.", **common)
        _perception_add_metric(metrics, root + ".distance_from_rest", distance, description=f"Signed {name} distance from rest.", **common)
        _perception_add_metric(metrics, root + ".recent_delta", delta, description=f"Current minus previous {name} strength.", **common)
        _perception_add_metric(metrics, root + ".salience", salience, description=f"Python-computed {name} salience.", **common)
        _perception_add_metric(metrics, root + ".trend", {"increasing": 1.0, "stable": 0.0, "decreasing": -1.0}[common["trend"]], description=f"Numeric {name} trend: -1, 0, or 1.", **common)

    somatic_profile_map = _SOMATIC_PROFILES
    for item in somatic.get("somatic_metrics") or []:
        name = str(item.get("state") or "").upper()
        if not name:
            continue
        current = _perception_float(item.get("current_value"))
        previous = _perception_float(item.get("previous_value"), current)
        rest = _perception_float(item.get("rest_value"))
        delta = current - previous
        distance = current - rest
        profile = somatic_profile_map.get(name) or {}
        scale = max(1e-9, abs(_perception_float(profile.get("max_value"), 1.0) - _perception_float(profile.get("min_value"), 0.0)))
        salience = min(1.0, abs(distance) / scale * 2.2 + abs(delta) / scale * 4.0)
        root = f"somatic.{name}"
        common = dict(category="somatic", unit=item.get("unit"), source_id=somatic_id, trend=_perception_trend(delta, scale), distance_from_rest=distance, recent_delta=delta, salience=salience)
        _perception_add_metric(metrics, root + ".current", current, description=f"Current timestamp-adjusted {name} value.", **common)
        _perception_add_metric(metrics, root + ".previous", previous, description=f"Previous stored {name} value.", **common)
        _perception_add_metric(metrics, root + ".rest", rest, description=f"Configured {name} rest value.", **common)
        _perception_add_metric(metrics, root + ".distance_from_rest", distance, description=f"Signed {name} distance from rest.", **common)
        _perception_add_metric(metrics, root + ".recent_delta", delta, description=f"Current minus previous {name} value.", **common)
        _perception_add_metric(metrics, root + ".salience", salience, description=f"Python-computed {name} salience.", **common)
        _perception_add_metric(metrics, root + ".trend", {"increasing": 1.0, "stable": 0.0, "decreasing": -1.0}[common["trend"]], description=f"Numeric {name} trend: -1, 0, or 1.", **common)

    handoff, handoff_status = _load_session_handoff(module)
    created_at = str(handoff.get("created_at") or "")
    hours_since_handoff = 0.0
    if created_at:
        try:
            hours_since_handoff = max(0.0, (datetime.now(timezone.utc) - _parse_iso(created_at)).total_seconds() / 3600.0)
        except Exception:
            hours_since_handoff = 0.0
    unfinished = len(handoff.get("unfinished_threads") or [])
    next_actions = len(handoff.get("next_actions") or [])
    pending = len([x for x in (_session_commitment_rows(module, 500).get("proposals") or []) if x.get("status") == "PENDING"])
    handoff_source = str(handoff.get("handoff_id") or "")
    _perception_add_metric(metrics, "session.handoff_present", bool(handoff.get("handoff_id")), category="session", description="Whether a validated last-session handoff exists.", source_id=handoff_source, salience=0.1)
    _perception_add_metric(metrics, "session.unfinished_thread_count", unfinished, category="session", description="Unfinished threads in the latest handoff.", source_id=handoff_source, salience=min(1, unfinished / 5))
    _perception_add_metric(metrics, "session.next_action_count", next_actions, category="session", description="Next actions in the latest handoff.", source_id=handoff_source, salience=min(1, next_actions / 5))
    _perception_add_metric(metrics, "session.pending_commitment_count", pending, category="session", description="Pending permanent-commitment proposals.", source_id=handoff_source, salience=min(1, pending / 3))
    _perception_add_metric(metrics, "session.hours_since_last_handoff", hours_since_handoff, category="session", unit="hours", description="Elapsed hours since the latest session handoff.", source_id=handoff_source, salience=min(1, hours_since_handoff / 72))
    session_messages = len(_session_messages(module)) if hasattr(module, "_SESSION_START_MESSAGE_ID") else 0
    _perception_add_metric(metrics, "session.current_message_count", session_messages, category="session", description="Public messages in the current session window.", source_id="chat_messages", salience=min(1, session_messages / 40))

    if callable(getattr(module, "get_self_continuity_status", None)):
        try:
            self_status = module.get_self_continuity_status()
            self_counts = self_status.get("counts") or {}
            active_high = int(self_counts.get("active:high", 0))
            active_mid = int(self_counts.get("active:mid", 0))
            active_low = int(self_counts.get("active:low", 0))
            review_count = sum(int(value) for key, value in self_counts.items() if str(key).startswith("review:"))
            self_source = str(self_status.get("session_id") or "self_continuity")
            _perception_add_metric(metrics, "continuity.global_query_cycle", int(self_status.get("global_query_cycle", 0)), category="continuity", description="Persistent count of successfully completed conversational turns.", source_id=self_source, salience=0.0)
            _perception_add_metric(metrics, "continuity.session_query_cycle", int(self_status.get("session_query_cycle", 0)), category="continuity", description="Successfully completed conversational turns in the current runtime session.", source_id=self_source, salience=0.0)
            _perception_add_metric(metrics, "continuity.active_high_note_count", active_high, category="continuity", description="Active high-priority self-continuity notes.", source_id=self_source, salience=min(1.0, active_high / 4.0))
            _perception_add_metric(metrics, "continuity.active_mid_note_count", active_mid, category="continuity", description="Active medium-priority self-continuity notes.", source_id=self_source, salience=min(1.0, active_mid / 8.0))
            _perception_add_metric(metrics, "continuity.active_low_note_count", active_low, category="continuity", description="Active low-priority self-continuity notes.", source_id=self_source, salience=min(1.0, active_low / 12.0))
            _perception_add_metric(metrics, "continuity.review_note_count", review_count, category="continuity", description="Self-continuity notes waiting for Assistant review.", source_id=self_source, salience=min(1.0, review_count / 3.0))
        except Exception:
            pass

    trace = module.get_last_retrieval_trace() if callable(getattr(module, "get_last_retrieval_trace", None)) else {}
    trace_payload = (trace.get("trace") or {}) if isinstance(trace, dict) and trace.get("ok") else {}
    selected_memories = trace_payload.get("selected_memories") or []
    scores = [_perception_float(x.get("score")) for x in selected_memories if isinstance(x, dict)]
    top_score = max(scores) if scores else 0.0
    # Scores vary by engine; map positive values into 0..1 without assuming their scale.
    recall_confidence = 0.0 if top_score <= 0 else top_score / (1.0 + top_score)
    _perception_add_metric(metrics, "memory.retrieved_count", len(selected_memories), category="memory", description="Count of memories in the latest retrieval trace.", source_id=str(trace_payload.get("created_at") or ""), salience=min(1, len(selected_memories) / 10))
    _perception_add_metric(metrics, "memory.top_retrieval_score", top_score, category="memory", description="Top raw score in the latest retrieval trace.", source_id=str(trace_payload.get("created_at") or ""), salience=recall_confidence)
    _perception_add_metric(metrics, "memory.recall_confidence", recall_confidence, category="memory", description="Bounded confidence proxy derived from the latest top retrieval score.", source_id=str(trace_payload.get("created_at") or ""), salience=1 - recall_confidence if query else recall_confidence)
    _perception_add_metric(metrics, "memory.primary_evidence_count", len(trace_payload.get("primary_provenance") or []), category="memory", description="Direct primary-provenance links in the latest retrieval trace.", source_id=str(trace_payload.get("created_at") or ""), salience=min(1, len(trace_payload.get("primary_provenance") or []) / 5))

    adaptive = dict(getattr(module, "_ADAPTIVE_LAST_DECISION", {}) or {})
    context_limit = _perception_float(adaptive.get("model_context_limit_tokens") or module.get_setting("endpoint_context_tokens", "") or getattr(module, "ONLINE_MODEL_CONTEXT_TOKENS", 0))
    selected_level = str(adaptive.get("selected") or "")
    level_info = ((adaptive.get("levels") or {}).get(selected_level) or {}) if isinstance(adaptive.get("levels"), dict) else {}
    estimated_input = _perception_float(level_info.get("estimated_complete_prompt_tokens") or adaptive.get("estimated_complete_prompt_tokens"))
    reserved_output = _perception_float(adaptive.get("reserved_output_tokens") or getattr(module, "ADAPTIVE_OUTPUT_RESERVE_TOKENS", 4096), 4096)
    remaining = max(0.0, context_limit - estimated_input - reserved_output) if context_limit else 0.0
    remaining_ratio = remaining / context_limit if context_limit else 0.0
    _perception_add_metric(metrics, "context.model_limit_tokens", context_limit, category="context", unit="tokens", description="Detected or configured model context limit.", source_id=selected_level, salience=0.1)
    _perception_add_metric(metrics, "context.estimated_input_tokens", estimated_input, category="context", unit="tokens", description="Latest complete-prompt input estimate.", source_id=selected_level, salience=min(1, estimated_input / context_limit) if context_limit else 0)
    _perception_add_metric(metrics, "context.reserved_output_tokens", reserved_output, category="context", unit="tokens", description="Output/tool token reserve.", source_id=selected_level, salience=0.1)
    _perception_add_metric(metrics, "context.remaining_tokens", remaining, category="context", unit="tokens", description="Estimated remaining tokens after input and reserve.", source_id=selected_level, salience=1 - remaining_ratio if context_limit else 0)
    _perception_add_metric(metrics, "context.remaining_ratio", remaining_ratio, category="context", description="Estimated context fraction remaining.", source_id=selected_level, salience=1 - remaining_ratio if context_limit else 0)

    now = datetime.now(timezone.utc)
    _perception_add_metric(metrics, "time.utc_hour", now.hour + now.minute / 60.0, category="time", unit="hour", description="Current UTC hour as a decimal.", source_id=now.date().isoformat(), salience=0)
    _perception_add_metric(metrics, "time.minute_of_day", now.hour * 60 + now.minute, category="time", unit="minutes", description="Current UTC minute of day.", source_id=now.date().isoformat(), salience=0)

    source_inputs = {
        "affective_state_id": affect_id,
        "affective_timestamp": affect.get("previous_timestamp"),
        "somatic_state_id": somatic_id,
        "somatic_timestamp": somatic.get("previous_timestamp"),
        "session_handoff_id": handoff_source,
        "session_handoff_status": handoff_status,
        "retrieval_trace_created_at": trace_payload.get("created_at"),
        "retrieval_query_hash": hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
        "adaptive_selected": selected_level,
        "context_limit": context_limit,
        "minute_bucket": now.replace(second=0, microsecond=0).isoformat(),
    }
    return metrics, source_inputs


def _perception_attribute_path(node: ast.AST) -> str | None:
    parts: list[str] = []
    current = node
    while isinstance(current, ast.Attribute):
        parts.append(current.attr)
        current = current.value
    if isinstance(current, ast.Name):
        parts.append(current.id)
        return ".".join(reversed(parts))
    return None


def _perception_ast_depth(node: ast.AST) -> int:
    children = list(ast.iter_child_nodes(node))
    return 1 if not children else 1 + max(_perception_ast_depth(child) for child in children)


def _perception_parse_formula(expression: str, metric_refs: set[str], derived_names: set[str]) -> tuple[ast.Expression, set[str], set[str]]:
    expression = _perception_clean_text(expression, _PERCEPTION_MAX_FORMULA_CHARS)
    if not expression:
        raise ValueError("Formula cannot be empty.")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"Invalid formula syntax: {exc.msg}") from exc
    nodes = list(ast.walk(tree))
    if len(nodes) > _PERCEPTION_MAX_AST_NODES:
        raise ValueError("Formula is too complex.")
    if _perception_ast_depth(tree) > _PERCEPTION_MAX_AST_DEPTH:
        raise ValueError("Formula nesting is too deep.")
    used_metrics: set[str] = set()
    used_derived: set[str] = set()
    for node in nodes:
        if isinstance(node, ast.Expression | ast.Load | ast.operator | ast.unaryop | ast.boolop | ast.cmpop):
            continue
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool):
                continue
            if not isinstance(node.value, (int, float)) or not math.isfinite(float(node.value)):
                raise ValueError("Only finite numeric and boolean constants are allowed.")
            continue
        if isinstance(node, ast.BinOp):
            if not isinstance(node.op, _PERCEPTION_ALLOWED_BINOPS):
                raise ValueError("Unsupported binary operator.")
            continue
        if isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, _PERCEPTION_ALLOWED_UNARYOPS):
                raise ValueError("Unsupported unary operator.")
            continue
        if isinstance(node, ast.BoolOp):
            if not isinstance(node.op, (ast.And, ast.Or)):
                raise ValueError("Unsupported boolean operator.")
            continue
        if isinstance(node, ast.Compare):
            if not all(isinstance(op, _PERCEPTION_ALLOWED_CMPOPS) for op in node.ops):
                raise ValueError("Unsupported comparison operator.")
            continue
        if isinstance(node, ast.IfExp):
            continue
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in _PERCEPTION_SAFE_FUNCTIONS:
                raise ValueError("Only approved mathematical functions are allowed.")
            if node.keywords:
                raise ValueError("Keyword arguments are not allowed in formulas.")
            continue
        if isinstance(node, ast.Attribute):
            path = _perception_attribute_path(node)
            if path and path in metric_refs:
                used_metrics.add(path)
                continue
            # Parent attributes are visited separately; only reject complete-looking paths.
            if path and path.count(".") >= 2:
                raise ValueError(f"Unknown metric reference: {path}")
            continue
        if isinstance(node, ast.Name):
            if node.id in _PERCEPTION_SAFE_FUNCTIONS or node.id in {"True", "False"}:
                continue
            if node.id in derived_names:
                used_derived.add(node.id)
                continue
            if node.id in {"emotion", "somatic", "session", "memory", "context", "time"}:
                continue
            raise ValueError(f"Unknown name in formula: {node.id}")
        raise ValueError(f"Unsupported formula element: {type(node).__name__}")
    return tree, used_metrics, used_derived


def _perception_bound_number(value: object) -> float | bool:
    if isinstance(value, bool):
        return value
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("Formula produced a non-finite value.")
    if abs(number) > 1_000_000_000:
        raise ValueError("Formula result exceeds the safety range.")
    return number


def _perception_eval_ast(node: ast.AST, metric_values: dict[str, object], derived_values: dict[str, object]) -> object:
    if isinstance(node, ast.Expression):
        return _perception_eval_ast(node.body, metric_values, derived_values)
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Attribute):
        path = _perception_attribute_path(node)
        if path not in metric_values:
            raise KeyError(f"Metric is unavailable: {path}")
        return metric_values[path]
    if isinstance(node, ast.Name):
        if node.id == "True": return True
        if node.id == "False": return False
        if node.id in derived_values: return derived_values[node.id]
        raise KeyError(f"Derived variable is unavailable: {node.id}")
    if isinstance(node, ast.UnaryOp):
        value = _perception_eval_ast(node.operand, metric_values, derived_values)
        if isinstance(node.op, ast.Not): return not bool(value)
        if isinstance(node.op, ast.UAdd): return _perception_bound_number(+float(value))
        if isinstance(node.op, ast.USub): return _perception_bound_number(-float(value))
    if isinstance(node, ast.BinOp):
        left = float(_perception_eval_ast(node.left, metric_values, derived_values))
        right = float(_perception_eval_ast(node.right, metric_values, derived_values))
        if isinstance(node.op, ast.Add): value = left + right
        elif isinstance(node.op, ast.Sub): value = left - right
        elif isinstance(node.op, ast.Mult): value = left * right
        elif isinstance(node.op, ast.Div):
            if abs(right) < 1e-12: raise ZeroDivisionError("division by zero")
            value = left / right
        elif isinstance(node.op, ast.Mod):
            if abs(right) < 1e-12: raise ZeroDivisionError("modulo by zero")
            value = left % right
        elif isinstance(node.op, ast.Pow):
            if abs(right) > 8 or abs(left) > 1_000_000:
                raise ValueError("Power operation exceeds safety limits.")
            value = left ** right
        else: raise ValueError("Unsupported binary operator.")
        return _perception_bound_number(value)
    if isinstance(node, ast.BoolOp):
        values = [_perception_eval_ast(x, metric_values, derived_values) for x in node.values]
        return all(bool(x) for x in values) if isinstance(node.op, ast.And) else any(bool(x) for x in values)
    if isinstance(node, ast.Compare):
        left = _perception_eval_ast(node.left, metric_values, derived_values)
        for op, comparator in zip(node.ops, node.comparators):
            right = _perception_eval_ast(comparator, metric_values, derived_values)
            if isinstance(op, ast.Eq): ok = left == right
            elif isinstance(op, ast.NotEq): ok = left != right
            elif isinstance(op, ast.Lt): ok = float(left) < float(right)
            elif isinstance(op, ast.LtE): ok = float(left) <= float(right)
            elif isinstance(op, ast.Gt): ok = float(left) > float(right)
            elif isinstance(op, ast.GtE): ok = float(left) >= float(right)
            else: raise ValueError("Unsupported comparison.")
            if not ok: return False
            left = right
        return True
    if isinstance(node, ast.IfExp):
        branch = node.body if bool(_perception_eval_ast(node.test, metric_values, derived_values)) else node.orelse
        return _perception_eval_ast(branch, metric_values, derived_values)
    if isinstance(node, ast.Call):
        name = node.func.id
        args = [_perception_eval_ast(x, metric_values, derived_values) for x in node.args]
        nums = [float(x) for x in args]
        if name == "min": value = min(nums)
        elif name == "max": value = max(nums)
        elif name == "abs":
            if len(nums) != 1: raise ValueError("abs expects one argument")
            value = abs(nums[0])
        elif name == "clamp":
            if len(nums) != 3: raise ValueError("clamp expects value, minimum, maximum")
            if nums[1] > nums[2]: raise ValueError("clamp minimum exceeds maximum")
            value = max(nums[1], min(nums[2], nums[0]))
        elif name == "mean":
            if not nums: raise ValueError("mean expects at least one argument")
            value = sum(nums) / len(nums)
        elif name == "sum": value = sum(nums)
        elif name == "sqrt":
            if len(nums) != 1 or nums[0] < 0: raise ValueError("sqrt expects one non-negative argument")
            value = math.sqrt(nums[0])
        elif name == "log1p":
            if len(nums) != 1 or nums[0] <= -1: raise ValueError("log1p expects a value greater than -1")
            value = math.log1p(nums[0])
        elif name == "exp":
            if len(nums) != 1 or abs(nums[0]) > 30: raise ValueError("exp input exceeds safety limits")
            value = math.exp(nums[0])
        elif name == "round":
            if len(nums) not in {1, 2}: raise ValueError("round expects one or two arguments")
            digits = int(nums[1]) if len(nums) == 2 else 0
            if abs(digits) > 9: raise ValueError("round precision exceeds safety limits")
            value = round(nums[0], digits)
        elif name == "choose":
            if len(args) != 3: raise ValueError("choose expects condition, true value, false value")
            value = args[1] if bool(args[0]) else args[2]
        elif name == "safe_div":
            if len(nums) not in {2, 3}: raise ValueError("safe_div expects numerator, denominator, optional fallback")
            value = (nums[2] if len(nums) == 3 else 0.0) if abs(nums[1]) < 1e-12 else nums[0] / nums[1]
        elif name == "scale":
            if len(nums) != 5: raise ValueError("scale expects value, in_min, in_max, out_min, out_max")
            if abs(nums[2] - nums[1]) < 1e-12: raise ValueError("scale input range cannot be zero")
            value = nums[3] + ((nums[0] - nums[1]) / (nums[2] - nums[1])) * (nums[4] - nums[3])
        elif name == "sigmoid":
            if len(nums) != 1: raise ValueError("sigmoid expects one argument")
            x = max(-30.0, min(30.0, nums[0]))
            value = 1.0 / (1.0 + math.exp(-x))
        else: raise ValueError(f"Unknown safe function: {name}")
        return _perception_bound_number(value)
    raise ValueError(f"Unsupported expression node: {type(node).__name__}")


def _perception_topological_order(dependencies: dict[str, set[str]]) -> list[str]:
    remaining = {name: set(values) for name, values in dependencies.items()}
    ordered: list[str] = []
    while remaining:
        ready = sorted(name for name, deps in remaining.items() if not deps)
        if not ready:
            cycle = ", ".join(sorted(remaining))
            raise ValueError(f"Derived-variable dependency cycle: {cycle}")
        for name in ready:
            ordered.append(name)
            remaining.pop(name)
        for deps in remaining.values():
            deps.difference_update(ready)
    return ordered


def _perception_normalize_output(output: object) -> dict:
    data = dict(output) if isinstance(output, dict) else {}
    def refs(value: object) -> list[str]:
        values = value if isinstance(value, list) else []
        clean = []
        for item in values:
            ref = _perception_clean_text(item, 160)
            if ref and ref not in clean:
                clean.append(ref)
        return clean[:_PERCEPTION_MAX_OUTPUT_VARIABLES]
    def thresholds(value: object) -> dict[str, float]:
        result = {}
        if isinstance(value, dict):
            for key, raw in value.items():
                ref = _perception_clean_text(key, 160)
                try: number = float(raw)
                except Exception: continue
                if ref and math.isfinite(number): result[ref] = number
        return result
    return {
        "always_include": refs(data.get("always_include")),
        "include_when_above": thresholds(data.get("include_when_above")),
        "include_when_below": thresholds(data.get("include_when_below")),
        "hide_neutral": bool(data.get("hide_neutral", True)),
        "neutral_distance": max(0.0, min(1.0, _perception_float(data.get("neutral_distance"), 0.04))),
        "rank_by_salience": bool(data.get("rank_by_salience", True)),
        "maximum_variables": max(1, min(_PERCEPTION_MAX_OUTPUT_VARIABLES, int(_perception_float(data.get("maximum_variables"), 12)))),
        "maximum_characters": max(800, min(12000, int(_perception_float(data.get("maximum_characters"), 4800)))),
        "precision": max(0, min(8, int(_perception_float(data.get("precision"), 3)))),
        "include_sources": bool(data.get("include_sources", True)),
    }


def _perception_validate_profile(module, raw_profile: object, *, profile_id: str | None = None) -> tuple[dict, dict]:
    if not isinstance(raw_profile, dict):
        raise ValueError("Perception profile must be a JSON object.")
    metrics, _ = _perception_collect_metrics(module)
    metric_refs = set(metrics)
    name = _perception_clean_text(raw_profile.get("name"), 120)
    if not name:
        raise ValueError("Perception profile name is required.")
    comment = _perception_clean_text(raw_profile.get("comment"), 1200)
    if not comment:
        raise ValueError("Perception profile comment is required and should explain its intended use.")
    requested_id = _perception_clean_text(profile_id or raw_profile.get("profile_id"), 100).upper()
    if requested_id:
        requested_id = re.sub(r"[^A-Z0-9_-]+", "-", requested_id).strip("-")[:100]
    if not requested_id:
        slug = re.sub(r"[^A-Z0-9]+", "-", name.upper()).strip("-")[:48] or "PROFILE"
        requested_id = f"PP-{slug}-{hashlib.sha256((name + comment).encode('utf-8')).hexdigest()[:8].upper()}"

    raw_derived = raw_profile.get("derived_variables") or {}
    if not isinstance(raw_derived, dict):
        raise ValueError("derived_variables must be an object mapping names to formulas.")
    if len(raw_derived) > _PERCEPTION_MAX_FORMULAS:
        raise ValueError(f"A profile may define at most {_PERCEPTION_MAX_FORMULAS} derived variables.")
    derived: dict[str, str] = {}
    for key, expression in raw_derived.items():
        identifier = _perception_safe_identifier(key)
        if identifier in derived:
            raise ValueError(f"Duplicate derived-variable name: {identifier}")
        derived[identifier] = _perception_clean_text(expression, _PERCEPTION_MAX_FORMULA_CHARS)
    derived_names = set(derived)
    parsed: dict[str, ast.Expression] = {}
    dependencies: dict[str, set[str]] = {}
    formula_metric_refs: set[str] = set()
    formula_details = {}
    for name_key, expression in derived.items():
        tree, used_metrics, used_derived = _perception_parse_formula(expression, metric_refs, derived_names)
        parsed[name_key] = tree
        dependencies[name_key] = set(used_derived)
        formula_metric_refs.update(used_metrics)
        formula_details[name_key] = {"metrics": sorted(used_metrics), "derived_dependencies": sorted(used_derived), "ast_nodes": len(list(ast.walk(tree)))}
    order = _perception_topological_order(dependencies)

    output = _perception_normalize_output(raw_profile.get("output"))
    output_refs = set(output["always_include"]) | set(output["include_when_above"]) | set(output["include_when_below"])
    valid_output_refs = metric_refs | {f"derived.{name_key}" for name_key in derived}
    unknown_output = sorted(output_refs - valid_output_refs)
    if unknown_output:
        raise ValueError(f"Unknown output metric(s): {', '.join(unknown_output[:8])}")

    requested_sources = raw_profile.get("source_metrics") or []
    if not isinstance(requested_sources, list):
        raise ValueError("source_metrics must be a list.")
    source_metrics = []
    for raw_ref in requested_sources:
        ref = _perception_clean_text(raw_ref, 160)
        if not ref: continue
        if ref not in metric_refs:
            raise ValueError(f"Unknown source metric: {ref}")
        if ref not in source_metrics: source_metrics.append(ref)
    for ref in sorted(formula_metric_refs | {x for x in output_refs if x in metric_refs}):
        if ref not in source_metrics: source_metrics.append(ref)
    if len(source_metrics) > _PERCEPTION_MAX_SOURCE_METRICS:
        raise ValueError(f"A profile may use at most {_PERCEPTION_MAX_SOURCE_METRICS} source metrics.")

    requested_stages = raw_profile.get("processing") or list(_PERCEPTION_ALLOWED_STAGES)
    if not isinstance(requested_stages, list):
        raise ValueError("processing must be a list.")
    unknown_stages = [str(x) for x in requested_stages if str(x) not in _PERCEPTION_ALLOWED_STAGES]
    if unknown_stages:
        raise ValueError(f"Unknown processing stage(s): {', '.join(unknown_stages[:8])}")
    # Python canonicalizes stage order so a profile cannot calculate after filtering or render before budgeting.
    requested_set = set(str(x) for x in requested_stages)
    mandatory = {"refresh_authoritative_state", "calculate_base_metrics", "calculate_derived_variables", "render_compact_packet"}
    requested_set.update(mandatory)
    processing = [stage for stage in _PERCEPTION_ALLOWED_STAGES if stage in requested_set]

    metric_values = {ref: item.get("value") for ref, item in metrics.items()}
    derived_values: dict[str, object] = {}
    preview = {}
    for name_key in order:
        value = _perception_eval_ast(parsed[name_key], metric_values, derived_values)
        derived_values[name_key] = value
        preview[name_key] = value

    normalized = {
        "schema_version": _PERCEPTION_SCHEMA_VERSION,
        "profile_id": requested_id,
        "name": name,
        "comment": comment,
        "source_metrics": source_metrics,
        "derived_variables": derived,
        "processing": processing,
        "output": output,
    }
    encoded = _perception_canonical(normalized).encode("utf-8")
    if len(encoded) > _PERCEPTION_MAX_PROFILE_BYTES:
        raise ValueError("Perception profile exceeds the configured size limit.")
    validation = {
        "ok": True,
        "validated_at": _perception_now(),
        "profile_sha256": hashlib.sha256(encoded).hexdigest(),
        "formula_order": order,
        "formula_details": formula_details,
        "preview_derived_values": preview,
        "source_metric_count": len(source_metrics),
        "derived_variable_count": len(derived),
        "canonical_processing": processing,
        "arbitrary_code_execution": False,
    }
    return normalized, validation


def _perception_latest_profile(module, reference: str | None = None, *, version: int | None = None, include_retired: bool = True) -> dict | None:
    _ensure_perception_schema(module)
    ref = _perception_clean_text(reference, 160)
    with module.db_connect() as db:
        if not ref:
            active_id = str(module.get_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID) or _PERCEPTION_DEFAULT_ID)
            active_version = int(_perception_float(module.get_setting("active_perception_profile_version", "0"), 0)) or None
            ref, version = active_id, active_version
        if version is not None:
            row = db.execute("SELECT * FROM perception_profiles WHERE profile_id=? AND version=?", (ref, int(version))).fetchone()
        else:
            row = db.execute(
                """SELECT * FROM perception_profiles
                   WHERE profile_id=? OR lower(name)=lower(?)
                   ORDER BY CASE WHEN profile_id=? THEN 0 ELSE 1 END, version DESC LIMIT 1""",
                (ref, ref, ref),
            ).fetchone()
    if not row:
        return None
    data = dict(row)
    try:
        profile = json.loads(data.pop("profile_json"))
        validation = json.loads(data.pop("validation_json"))
    except Exception:
        return None
    profile.update({
        "version": int(data.get("version") or 0),
        "created_at": data.get("created_at"),
        "created_by": data.get("created_by"),
        "provider": data.get("provider"),
        "model": data.get("model"),
        "previous_version": data.get("previous_version"),
        "profile_sha256": data.get("profile_sha256"),
        "validation": validation,
        "retired": _perception_is_retired(module, profile.get("profile_id")),
    })
    if profile["retired"] and not include_retired:
        return None
    active_id = str(module.get_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID) or _PERCEPTION_DEFAULT_ID)
    active_version = int(_perception_float(module.get_setting("active_perception_profile_version", "0"), 0))
    profile["active"] = profile.get("profile_id") == active_id and (active_version in {0, int(profile.get("version") or 0)})
    return profile


def _perception_list_profiles(module, *, include_retired: bool = False, include_history: bool = False) -> dict:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        rows = [dict(row) for row in db.execute("SELECT profile_id,version FROM perception_profiles ORDER BY profile_id,version DESC").fetchall()]
    active_id = str(module.get_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID) or _PERCEPTION_DEFAULT_ID)
    active_version = int(_perception_float(module.get_setting("active_perception_profile_version", "0"), 0))
    grouped: dict[str, list[int]] = {}
    for row in rows:
        grouped.setdefault(str(row["profile_id"]), []).append(int(row["version"]))
    chosen: list[tuple[str, int, int]] = []
    for profile_id, versions in grouped.items():
        latest_version = max(versions)
        if include_history:
            chosen.extend((profile_id, version, latest_version) for version in sorted(versions, reverse=True))
        else:
            selected_version = active_version if profile_id == active_id and active_version in versions else latest_version
            chosen.append((profile_id, selected_version, latest_version))
    output = []
    for profile_id, version, latest_version in chosen:
        profile = _perception_latest_profile(module, profile_id, version=version, include_retired=True)
        if not profile or (profile.get("retired") and not include_retired):
            continue
        output.append({
            "profile_id": profile.get("profile_id"), "version": profile.get("version"),
            "latest_version": latest_version,
            "newer_version_available": int(profile.get("version") or 0) < latest_version,
            "name": profile.get("name"), "comment": profile.get("comment"),
            "created_at": profile.get("created_at"), "created_by": profile.get("created_by"),
            "active": profile.get("active"), "retired": profile.get("retired"),
            "derived_variable_count": len(profile.get("derived_variables") or {}),
            "source_metric_count": len(profile.get("source_metrics") or []),
        })
    output.sort(key=lambda x: (not bool(x.get("active")), str(x.get("name") or "").casefold(), -int(x.get("version") or 0)))
    return {"count": len(output), "profiles": output, "active_profile_id": active_id, "active_profile_version": active_version}


def _perception_save_profile(module, raw_profile: object, *, provider: str, model: str, actor: str = "Assistant", activate: bool = False, reason: str = "profile_saved") -> dict:
    _ensure_perception_schema(module)
    normalized, validation = _perception_validate_profile(module, raw_profile)
    profile_id = normalized["profile_id"]
    with module.db_connect() as db:
        latest = db.execute("SELECT version,profile_sha256 FROM perception_profiles WHERE profile_id=? ORDER BY version DESC LIMIT 1", (profile_id,)).fetchone()
        version = int(latest["version"] or 0) + 1 if latest else 1
        previous_version = int(latest["version"]) if latest else None
        profile_raw = _perception_canonical(normalized)
        digest = hashlib.sha256(profile_raw.encode("utf-8")).hexdigest()
        if latest and latest["profile_sha256"] == digest:
            existing = _perception_latest_profile(module, profile_id, version=previous_version)
            if activate:
                _perception_activate_profile(module, profile_id, version=previous_version, actor=actor, reason="identical_profile_activated")
            return {"ok": True, "changed": False, "reason": "identical profile already exists", "profile": existing}
        db.execute(
            """INSERT INTO perception_profiles(
                profile_id,version,created_at,created_by,provider,model,name,comment_text,previous_version,
                profile_json,profile_sha256,validation_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
            (profile_id, version, _perception_now(), actor, provider, model, normalized["name"], normalized["comment"], previous_version,
             profile_raw, digest, _perception_canonical(validation)),
        )
    _perception_event(module, profile_id, version, "saved", actor, reason, {"profile_sha256": digest, "comment": normalized["comment"]})
    _perception_clear_cache(module, profile_id=profile_id)
    if activate:
        _perception_activate_profile(module, profile_id, version=version, actor=actor, reason="save_and_activate")
    _perception_write_snapshot(module)
    return {"ok": True, "changed": True, "profile": _perception_latest_profile(module, profile_id, version=version)}


def _perception_activate_profile(module, reference: str, *, version: int | None = None, actor: str = "Assistant", reason: str = "profile_loaded") -> dict:
    profile = _perception_latest_profile(module, reference, version=version, include_retired=False)
    if not profile:
        raise KeyError(f"Unknown or retired perception profile: {reference}")
    module.set_setting("active_perception_profile_id", profile["profile_id"])
    module.set_setting("active_perception_profile_version", str(profile["version"]))
    _perception_event(module, profile["profile_id"], profile["version"], "activated", actor, reason, {"name": profile["name"]})
    _perception_write_snapshot(module)
    return {"ok": True, "active_profile_id": profile["profile_id"], "version": profile["version"], "name": profile["name"], "comment": profile["comment"]}


def _perception_retire_profile(module, reference: str, *, actor: str = "Assistant", reason: str = "profile_retired") -> dict:
    profile = _perception_latest_profile(module, reference, include_retired=True)
    if not profile:
        raise KeyError(f"Unknown perception profile: {reference}")
    if profile["profile_id"] == _PERCEPTION_DEFAULT_ID:
        raise ValueError("The built-in fallback profile cannot be retired.")
    _perception_event(module, profile["profile_id"], profile["version"], "retired", actor, reason, {"name": profile["name"]})
    active = _perception_latest_profile(module)
    fallback = None
    if active and active.get("profile_id") == profile["profile_id"]:
        fallback = _perception_activate_profile(module, _PERCEPTION_DEFAULT_ID, actor="Python", reason="active_profile_retired_fallback")
    _perception_clear_cache(module, profile_id=profile["profile_id"])
    _perception_write_snapshot(module)
    return {"ok": True, "retired_profile_id": profile["profile_id"], "version": profile["version"], "fallback": fallback}


def _perception_clone_profile(module, reference: str, *, name: str | None = None, comment: str | None = None, actor: str = "user") -> dict:
    profile = _perception_latest_profile(module, reference, include_retired=True)
    if not profile:
        raise KeyError(f"Unknown perception profile: {reference}")
    clone = {key: profile.get(key) for key in ("source_metrics", "derived_variables", "processing", "output")}
    clone_name = _perception_clean_text(name, 120) or f"{profile['name']} Copy"
    clone_comment = _perception_clean_text(comment, 1200) or f"Clone of {profile['profile_id']} v{profile['version']}."
    clone.update({"name": clone_name, "comment": clone_comment})
    return _perception_save_profile(module, clone, provider="console", model="python", actor=actor, reason="profile_cloned")


def _perception_profile_rows(module) -> list[dict]:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        rows = db.execute("SELECT * FROM perception_profiles ORDER BY row_id").fetchall()
    return [dict(row) for row in rows]


def _perception_event_rows(module) -> list[dict]:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        rows = db.execute("SELECT * FROM perception_profile_events ORDER BY event_id").fetchall()
    return [dict(row) for row in rows]


def _perception_export_component(module) -> dict:
    _perception_bootstrap(module)
    rows = _perception_profile_rows(module)
    events = _perception_event_rows(module)
    return {
        "schema_version": _PERCEPTION_SCHEMA_VERSION,
        "kind": _PERCEPTION_KIND,
        "created_at": _perception_now(),
        "active_profile_id": str(module.get_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID) or _PERCEPTION_DEFAULT_ID),
        "active_profile_version": int(_perception_float(module.get_setting("active_perception_profile_version", "0"), 0)),
        "profiles": rows,
        "events": events,
        "profile_count": len(rows),
        "event_count": len(events),
    }


def _perception_write_snapshot(module) -> dict:
    payload = _perception_export_component(module)
    _identity_write_encrypted_json(module, _PERCEPTION_FILE, _PERCEPTION_ENTROPY, payload)
    return payload


def _perception_import_component(module, component: object, *, source: str = "portable_import", write_snapshot: bool = True) -> dict:
    if not isinstance(component, dict) or component.get("kind") != _PERCEPTION_KIND:
        return {"ok": False, "reason": "missing or invalid perception component", "profiles_inserted": 0}
    if str(component.get("schema_version")) != _PERCEPTION_SCHEMA_VERSION:
        raise ValueError(f"Unsupported perception component schema: {component.get('schema_version')!r}")
    _ensure_perception_schema(module)
    remap: dict[str, str] = {}
    inserted = 0
    skipped = 0
    conflicts = 0
    rows = component.get("profiles") or []
    if not isinstance(rows, list):
        raise ValueError("Perception component profiles must be a list.")
    with module.db_connect() as db:
        for raw_row in rows:
            if not isinstance(raw_row, dict):
                continue
            original_id = _perception_clean_text(raw_row.get("profile_id"), 100)
            version = int(_perception_float(raw_row.get("version"), 0))
            if not original_id or version < 1:
                continue
            profile_json = str(raw_row.get("profile_json") or "")
            try:
                profile_obj = json.loads(profile_json)
                normalized, validation = _perception_validate_profile(module, profile_obj, profile_id=original_id)
            except Exception:
                continue
            profile_json = _perception_canonical(normalized)
            digest = hashlib.sha256(profile_json.encode("utf-8")).hexdigest()
            existing = db.execute("SELECT profile_sha256 FROM perception_profiles WHERE profile_id=? AND version=?", (original_id, version)).fetchone()
            target_id = original_id
            if existing:
                if existing["profile_sha256"] == digest:
                    skipped += 1
                    remap[original_id] = original_id
                    continue
                conflicts += 1
                target_id = f"{original_id}-IMPORTED-{digest[:8].upper()}"[:100]
                normalized["profile_id"] = target_id
                profile_json = _perception_canonical(normalized)
                digest = hashlib.sha256(profile_json.encode("utf-8")).hexdigest()
                while db.execute("SELECT 1 FROM perception_profiles WHERE profile_id=? AND version=?", (target_id, version)).fetchone():
                    version += 1
            remap[original_id] = target_id
            db.execute(
                """INSERT INTO perception_profiles(
                    profile_id,version,created_at,created_by,provider,model,name,comment_text,previous_version,
                    profile_json,profile_sha256,validation_json
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (target_id, version, raw_row.get("created_at") or _perception_now(), raw_row.get("created_by") or source,
                 raw_row.get("provider") or source, raw_row.get("model") or BUNDLE_VERSION,
                 normalized["name"], normalized["comment"], raw_row.get("previous_version"), profile_json, digest,
                 _perception_canonical(validation)),
            )
            inserted += 1
    events_inserted = 0
    for raw_event in component.get("events") or []:
        if not isinstance(raw_event, dict): continue
        original_id = _perception_clean_text(raw_event.get("profile_id"), 100)
        target_id = remap.get(original_id, original_id)
        payload_text = str(raw_event.get("payload_json") or "{}")
        try: payload = json.loads(payload_text)
        except Exception: payload = {"legacy_payload": payload_text[:4000]}
        _perception_event(module, target_id, int(_perception_float(raw_event.get("profile_version"), 0)) or None,
                          str(raw_event.get("event_type") or "imported_event"), str(raw_event.get("actor") or source),
                          str(raw_event.get("reason_text") or source), payload)
        events_inserted += 1
    active_id = remap.get(str(component.get("active_profile_id") or ""), str(component.get("active_profile_id") or ""))
    active_version = int(_perception_float(component.get("active_profile_version"), 0)) or None
    if active_id and _perception_latest_profile(module, active_id, version=active_version, include_retired=False):
        module.set_setting("active_perception_profile_id", active_id)
        module.set_setting("active_perception_profile_version", str(active_version or 0))
    elif not _perception_latest_profile(module, None, include_retired=False):
        module.set_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID)
        module.set_setting("active_perception_profile_version", "1")
    if write_snapshot:
        _perception_write_snapshot(module)
    return {"ok": True, "profiles_inserted": inserted, "profiles_skipped": skipped, "conflicts_remapped": conflicts, "events_inserted": events_inserted, "active_profile_id": module.get_setting("active_perception_profile_id", _PERCEPTION_DEFAULT_ID)}


def _perception_bootstrap(module) -> None:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        count = int(db.execute("SELECT COUNT(*) FROM perception_profiles").fetchone()[0])
    if count == 0:
        payload, _ = _identity_read_encrypted_json(module, _PERCEPTION_FILE, _PERCEPTION_ENTROPY)
        if isinstance(payload, dict) and payload.get("kind") == _PERCEPTION_KIND:
            try:
                _perception_import_component(module, payload, source="encrypted_snapshot_recovery", write_snapshot=False)
            except Exception:
                pass
        with module.db_connect() as db:
            count = int(db.execute("SELECT COUNT(*) FROM perception_profiles").fetchone()[0])
        if count == 0:
            _perception_save_profile(module, _perception_default_profile(), provider="python", model=BUNDLE_VERSION, actor="Python", activate=True, reason="default_profile_seed")
    active = _perception_latest_profile(module, None, include_retired=False)
    if not active:
        fallback = _perception_latest_profile(module, _PERCEPTION_DEFAULT_ID, include_retired=False)
        if not fallback:
            _perception_save_profile(module, _perception_default_profile(), provider="python", model=BUNDLE_VERSION, actor="Python", activate=True, reason="fallback_profile_reseed")
        else:
            _perception_activate_profile(module, _PERCEPTION_DEFAULT_ID, version=fallback["version"], actor="Python", reason="invalid_active_profile_fallback")


def _perception_clear_cache(module, *, profile_id: str | None = None) -> dict:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        if profile_id:
            cur = db.execute("DELETE FROM perception_cache WHERE profile_id=?", (profile_id,))
        else:
            cur = db.execute("DELETE FROM perception_cache")
    return {"ok": True, "rows_removed": max(0, int(cur.rowcount or 0)), "profile_id": profile_id}


def _perception_cache_status(module) -> dict:
    _ensure_perception_schema(module)
    with module.db_connect() as db:
        count = int(db.execute("SELECT COUNT(*) FROM perception_cache").fetchone()[0])
        latest = db.execute("SELECT * FROM perception_cache ORDER BY computed_at DESC LIMIT 1").fetchone()
    return {"entries": count, "latest": dict(latest) if latest else None, "ttl_seconds": _PERCEPTION_CACHE_TTL_SECONDS, "authoritative": False, "rebuildable": True}


def _perception_compute_derived(profile: dict, metrics: dict[str, dict]) -> tuple[dict[str, object], dict]:
    metric_values = {ref: item.get("value") for ref, item in metrics.items()}
    derived = profile.get("derived_variables") or {}
    derived_names = set(derived)
    parsed = {}
    deps = {}
    details = {}
    for name, expression in derived.items():
        tree, used_metrics, used_derived = _perception_parse_formula(str(expression), set(metrics), derived_names)
        parsed[name] = tree
        deps[name] = used_derived
        details[name] = {"metrics": sorted(used_metrics), "derived_dependencies": sorted(used_derived)}
    order = _perception_topological_order(deps)
    values = {}
    for name in order:
        values[name] = _perception_eval_ast(parsed[name], metric_values, values)
    return values, {"order": order, "dependencies": details}


def _perception_select_packet(profile: dict, metrics: dict[str, dict], derived_values: dict[str, object], *, sources: dict, query: str) -> dict:
    output = profile.get("output") or {}
    maximum = int(output.get("maximum_variables", 12))
    precision = int(output.get("precision", 3))
    candidates: dict[str, dict] = {}
    allowed_sources = set(profile.get("source_metrics") or [])
    for ref in allowed_sources:
        if ref in metrics:
            candidates[ref] = dict(metrics[ref])
    for name, value in derived_values.items():
        refs = profile.get("validation", {}).get("formula_details", {}).get(name, {}).get("metrics", [])
        source_ids = sorted({str(metrics[x].get("source_id")) for x in refs if x in metrics and metrics[x].get("source_id")})
        salience = max([_perception_float(metrics[x].get("salience")) for x in refs if x in metrics] or [0.35])
        candidates[f"derived.{name}"] = {
            "value": value, "category": "derived", "unit": None,
            "description": f"Assistant-defined derived variable {name}.",
            "source_id": ",".join(source_ids[:6]), "trend": None,
            "distance_from_rest": None, "recent_delta": None, "salience": salience,
        }
    selected: list[str] = []
    always = [ref for ref in output.get("always_include", []) if ref in candidates]
    selected.extend(always)
    for ref, threshold in (output.get("include_when_above") or {}).items():
        if ref in candidates and _perception_float(candidates[ref].get("value")) > float(threshold) and ref not in selected:
            selected.append(ref)
    for ref, threshold in (output.get("include_when_below") or {}).items():
        if ref in candidates and _perception_float(candidates[ref].get("value")) < float(threshold) and ref not in selected:
            selected.append(ref)
    remaining = []
    neutral_distance = float(output.get("neutral_distance", 0.04))
    for ref, item in candidates.items():
        if ref in selected: continue
        if output.get("hide_neutral", True) and item.get("distance_from_rest") is not None and abs(_perception_float(item.get("distance_from_rest"))) < neutral_distance and abs(_perception_float(item.get("recent_delta"))) < neutral_distance:
            continue
        remaining.append((float(item.get("salience") or 0), ref))
    if output.get("rank_by_salience", True):
        remaining.sort(key=lambda x: (-x[0], x[1]))
    else:
        remaining.sort(key=lambda x: x[1])
    for _, ref in remaining:
        if len(selected) >= maximum: break
        selected.append(ref)
    selected = selected[:maximum]
    variables = []
    for ref in selected:
        item = candidates[ref]
        value = item.get("value")
        if isinstance(value, float): value = round(value, precision)
        row = {"id": ref, "value": value}
        for key in ("unit", "trend", "distance_from_rest", "recent_delta", "salience"):
            if item.get(key) is not None:
                raw = item.get(key)
                row[key] = round(raw, precision) if isinstance(raw, float) else raw
        if output.get("include_sources", True) and item.get("source_id"):
            row["source_id"] = item.get("source_id")
        variables.append(row)
    packet = {
        "schema_version": _PERCEPTION_SCHEMA_VERSION,
        "computed_at": _perception_now(),
        "profile": {
            "profile_id": profile.get("profile_id"), "version": profile.get("version"),
            "name": profile.get("name"), "comment": profile.get("comment"),
            "processing": profile.get("processing"),
        },
        "variables": variables,
        "variable_count": len(variables),
        "source_revision": _perception_digest(sources),
        "query_sha256": hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
        "authority": "Derived read-only view. SQLite and encrypted identity sources remain authoritative.",
    }
    maximum_chars = int(output.get("maximum_characters", 4800))
    raw = json.dumps(packet, ensure_ascii=False, separators=(",", ":"))
    while len(raw) > maximum_chars and len(packet["variables"]) > 1:
        packet["variables"].pop()
        packet["variable_count"] = len(packet["variables"])
        raw = json.dumps(packet, ensure_ascii=False, separators=(",", ":"))
    packet["packet_sha256"] = _perception_digest({k: v for k, v in packet.items() if k != "packet_sha256"})
    return packet


def _perception_get_packet(module, *, query: str = "", force: bool = False, profile_reference: str | None = None) -> dict:
    _perception_bootstrap(module)
    profile = _perception_latest_profile(module, profile_reference, include_retired=False)
    fallback_reason = None
    if not profile:
        profile = _perception_latest_profile(module, _PERCEPTION_DEFAULT_ID, include_retired=False)
        fallback_reason = "requested profile unavailable; default fallback used"
    if not profile:
        raise RuntimeError("No valid perception profile is available.")
    metrics, source_inputs = _perception_collect_metrics(module, query=query)
    source_revision = _perception_digest(source_inputs)
    query_sha = hashlib.sha256(str(query or "").encode("utf-8")).hexdigest()
    cache_key = hashlib.sha256(f"{profile['profile_id']}|{profile['version']}|{source_revision}|{query_sha}".encode("utf-8")).hexdigest()
    now = datetime.now(timezone.utc)
    if not force:
        with module.db_connect() as db:
            row = db.execute("SELECT * FROM perception_cache WHERE cache_key=?", (cache_key,)).fetchone()
        if row:
            try:
                expires = _parse_iso(str(row["expires_at"]))
                packet = json.loads(row["packet_json"])
                if expires >= now and _perception_digest({k: v for k, v in packet.items() if k != "packet_sha256"}) == packet.get("packet_sha256"):
                    with module.db_connect() as db:
                        db.execute("UPDATE perception_cache SET cache_hits=cache_hits+1 WHERE cache_key=?", (cache_key,))
                    packet["cache"] = "hit"
                    if fallback_reason: packet["fallback_reason"] = fallback_reason
                    packet["packet_sha256"] = _perception_digest({k: v for k, v in packet.items() if k != "packet_sha256"})
                    return packet
            except Exception:
                pass
    try:
        derived_values, derived_diagnostics = _perception_compute_derived(profile, metrics)
        packet = _perception_select_packet(profile, metrics, derived_values, sources=source_inputs, query=query)
        packet["derived_diagnostics"] = derived_diagnostics
    except Exception as exc:
        if profile.get("profile_id") != _PERCEPTION_DEFAULT_ID:
            fallback = _perception_latest_profile(module, _PERCEPTION_DEFAULT_ID, include_retired=False)
            if fallback:
                derived_values, derived_diagnostics = _perception_compute_derived(fallback, metrics)
                packet = _perception_select_packet(fallback, metrics, derived_values, sources=source_inputs, query=query)
                packet["derived_diagnostics"] = derived_diagnostics
                packet["fallback_reason"] = f"Active profile failed validation/runtime calculation: {type(exc).__name__}: {exc}"
                profile = fallback
            else:
                raise
        else:
            raise
    packet["cache"] = "miss"
    packet["packet_sha256"] = _perception_digest({k: v for k, v in packet.items() if k != "packet_sha256"})
    expires = now + timedelta(seconds=_PERCEPTION_CACHE_TTL_SECONDS)
    raw = _perception_canonical(packet)
    with module.db_connect() as db:
        db.execute(
            """INSERT OR REPLACE INTO perception_cache(
                cache_key,profile_id,profile_version,source_revision,query_sha256,computed_at,expires_at,
                packet_json,packet_sha256,cache_hits
            ) VALUES(?,?,?,?,?,?,?,?,?,0)""",
            (cache_key, profile["profile_id"], int(profile["version"]), source_revision, query_sha,
             now.replace(microsecond=0).isoformat(), expires.replace(microsecond=0).isoformat(), raw,
             hashlib.sha256(raw.encode("utf-8")).hexdigest()),
        )
    return packet


def _perception_prompt_context(module, query: str) -> str:
    packet = _perception_get_packet(module, query=query)
    prompt_packet = dict(packet)
    prompt_packet.pop("derived_diagnostics", None)
    compact = json.dumps(prompt_packet, ensure_ascii=False, separators=(",", ":"))
    base = """SELF-DESIGNED PERCEPTION PROFILE — PYTHON-COMPUTED, READ-ONLY
Python already refreshed authoritative sources, calculated the active profile, applied its filters and context budget, and cached this packet. Use it as prepared self-context; do not recompute its arithmetic. The profile changes presentation and derived interpretation only—it cannot overwrite source truth.

""" + compact
    if _PERCEPTION_DESIGN_MARKER in str(query or ""):
        catalog = _perception_metric_catalog(module, include_values=False, query=query)
        active = _perception_latest_profile(module)
        design = {
            "active_profile": active,
            "metric_catalog": catalog,
            "profile_schema": {
                "name": "required string",
                "comment": "required purpose, e.g. for fast learning with low emotional input",
                "source_metrics": ["catalog metric IDs"],
                "derived_variables": {"snake_case_name": "safe formula"},
                "processing": list(_PERCEPTION_ALLOWED_STAGES),
                "output": {
                    "always_include": ["metric or derived.name"],
                    "include_when_above": {"metric": 0.5},
                    "include_when_below": {"metric": 0.5},
                    "hide_neutral": True, "neutral_distance": 0.04,
                    "rank_by_salience": True, "maximum_variables": 12,
                    "maximum_characters": 4800, "precision": 3, "include_sources": True,
                },
            },
            "save_protocol": (
                "At the end of the normal hidden <affective_update> JSON, add perception_profile_updates as a list. "
                "Each item may use action save, activate, or retire. For save, include profile and activate true/false. "
                "Python validates formulas, previews them, versions the profile, and rejects arbitrary code."
            ),
            "example_hidden_field": {
                "perception_profile_updates": [{
                    "action": "save", "activate": False,
                    "profile": {"name": "Focused Learning", "comment": "For fast learning with low emotional input.",
                                "source_metrics": ["emotion.CURIOSITY.current", "somatic.FATIGUE.current"],
                                "derived_variables": {"learning_readiness": "clamp(0.7 * emotion.CURIOSITY.current + 0.3 * (1 - somatic.FATIGUE.current), 0, 1)"},
                                "processing": list(_PERCEPTION_ALLOWED_STAGES),
                                "output": {"always_include": ["derived.learning_readiness"], "maximum_variables": 6}}
                }]
            },
        }
        base += "\n\nPERCEPTION PROFILE DESIGN WORKSPACE\n" + json.dumps(design, ensure_ascii=False, indent=2)
    else:
        base += "\n\nOptional profile control: when intentionally saving/loading a perception profile, add perception_profile_updates to the existing hidden affective_update JSON. Otherwise omit it."
    return base


def _perception_preview(module, reference: str | None = None, *, query: str = "") -> dict:
    profile = _perception_latest_profile(module, reference, include_retired=True)
    if not profile:
        raise KeyError(f"Unknown perception profile: {reference}")
    packet = _perception_get_packet(module, query=query, force=True, profile_reference=profile["profile_id"])
    return {"ok": True, "profile": {k: profile.get(k) for k in ("profile_id", "version", "name", "comment", "active", "retired")}, "packet": packet}


def _apply_perception_profile_updates(module, updates: object, *, provider: str, model: str) -> dict:
    if not isinstance(updates, list):
        return {"changed": False, "results": []}
    results = []
    for item in updates[:8]:
        if not isinstance(item, dict):
            continue
        action = str(item.get("action") or "save").strip().casefold()
        try:
            if action in {"save", "create", "update"}:
                profile = item.get("profile") if isinstance(item.get("profile"), dict) else item
                result = _perception_save_profile(
                    module, profile, provider=provider, model=model, actor="Assistant",
                    activate=bool(item.get("activate", False)), reason=str(item.get("reason") or "assistant_profile_design"),
                )
            elif action in {"activate", "load"}:
                ref = str(item.get("profile_id") or item.get("name") or item.get("reference") or "")
                result = _perception_activate_profile(module, ref, version=int(item["version"]) if item.get("version") else None, actor="Assistant", reason=str(item.get("reason") or "assistant_profile_activation"))
            elif action == "retire":
                ref = str(item.get("profile_id") or item.get("name") or item.get("reference") or "")
                result = _perception_retire_profile(module, ref, actor="Assistant", reason=str(item.get("reason") or "assistant_profile_retirement"))
            else:
                raise ValueError(f"Unknown perception profile action: {action}")
            results.append({"action": action, "ok": True, "result": result})
        except Exception as exc:
            results.append({"action": action, "ok": False, "error": f"{type(exc).__name__}: {exc}"})
            try:
                module.append_system_log("perception_profile_update_rejected", {"action": action, "error": results[-1]["error"]}, provider=provider, model=model)
            except Exception:
                pass
    outcome = {"changed": any(x.get("ok") for x in results), "results": results, "processed_at": _perception_now()}
    module._PERCEPTION_LAST_UPDATE_RESULT = outcome
    return outcome


def _perception_status(module) -> dict:
    _perception_bootstrap(module)
    active = _perception_latest_profile(module)
    return {
        "active_profile": active,
        "available_profiles": _perception_list_profiles(module).get("profiles"),
        "cache": _perception_cache_status(module),
        "encrypted_snapshot": str(module.safe_memory_path(_PERCEPTION_FILE)),
        "authoritative_sources": "SQLite affective/somatic/session/memory state plus encrypted identity files",
        "profile_role": "read-only derived perception and prompt selection",
        "arbitrary_code_execution": False,
        "last_model_profile_update": getattr(module, "_PERCEPTION_LAST_UPDATE_RESULT", None),
    }


def _perception_design_prompt(purpose: str, *, reference: str | None = None) -> str:
    purpose = _perception_clean_text(purpose, 1200) or "Design a useful perception profile for your current needs."
    edit = f"Revise the existing profile {reference!r}." if reference else "Create a new versioned profile."
    return (
        f"{_PERCEPTION_DESIGN_MARKER}\n{edit} Purpose requested by Steeve: {purpose}\n"
        "Inspect the supplied metric catalog and active profile. Choose source metrics, safe mathematical equations, processing stages, filters, ordering, and context limits. "
        "Give the profile a clear name and a Comment explaining when to use it. Save it through perception_profile_updates in your hidden affective_update block. "
        "Do not activate it unless that is clearly appropriate or explicitly requested. In the visible answer, explain the profile you designed and whether it was activated."
    )


def _perception_handle_command(module, text: str) -> bool:
    command = str(text or "").strip()
    lower = command.casefold()
    try:
        if lower in {"/perception", "/perception status", "/perception active"}:
            print(json.dumps(_perception_status(module), ensure_ascii=False, indent=2)); return True
        if lower in {"/perception profiles", "/perception list"}:
            print(json.dumps(_perception_list_profiles(module), ensure_ascii=False, indent=2)); return True
        if lower in {"/perception history", "/perception profiles all"}:
            print(json.dumps(_perception_list_profiles(module, include_retired=True, include_history=True), ensure_ascii=False, indent=2)); return True
        if lower.startswith("/perception metrics"):
            query = command[len("/perception metrics"):].strip().casefold()
            catalog = _perception_metric_catalog(module, include_values=False)
            if query:
                catalog["metrics"] = [x for x in catalog["metrics"] if query in str(x.get("id", "")).casefold() or query in str(x.get("description", "")).casefold()]
                catalog["count"] = len(catalog["metrics"])
            print(json.dumps(catalog, ensure_ascii=False, indent=2)); return True
        if lower.startswith("/perception values"):
            query = command[len("/perception values"):].strip().casefold()
            catalog = _perception_metric_catalog(module, include_values=True)
            if query:
                catalog["metrics"] = [x for x in catalog["metrics"] if query in str(x.get("id", "")).casefold() or query in str(x.get("description", "")).casefold()]
                catalog["count"] = len(catalog["metrics"])
            print(json.dumps(catalog, ensure_ascii=False, indent=2)); return True
        for prefix in ("/perception show ", "/perception preview ", "/perception load ", "/perception retire "):
            if lower.startswith(prefix):
                ref = command[len(prefix):].strip()
                if not ref: raise ValueError(f"Use {prefix}<profile ID or exact name>")
                if prefix == "/perception show ": result = _perception_latest_profile(module, ref, include_retired=True)
                elif prefix == "/perception preview ": result = _perception_preview(module, ref)
                elif prefix == "/perception load ": result = _perception_activate_profile(module, ref, actor="user", reason="console_load")
                else: result = _perception_retire_profile(module, ref, actor="user", reason="console_retire")
                print(json.dumps(result, ensure_ascii=False, indent=2)); return True
        if lower.startswith("/perception clone "):
            body = command[len("/perception clone "):].strip()
            parts = [part.strip() for part in body.split("|")]
            ref = parts[0] if parts else ""
            name = parts[1] if len(parts) > 1 else None
            comment = parts[2] if len(parts) > 2 else None
            print(json.dumps(_perception_clone_profile(module, ref, name=name, comment=comment), ensure_ascii=False, indent=2)); return True
        if lower in {"/perception cache", "/perception cache status", "/perception debug"}:
            print(json.dumps({"status": _perception_status(module), "active_packet": _perception_get_packet(module, force=True)}, ensure_ascii=False, indent=2)); return True
        if lower in {"/perception cache clear", "/perception rebuild"}:
            cleared = _perception_clear_cache(module)
            snapshot = _perception_write_snapshot(module)
            print(json.dumps({"ok": True, "cache": cleared, "snapshot_profiles": snapshot.get("profile_count"), "active_packet": _perception_get_packet(module, force=True)}, ensure_ascii=False, indent=2)); return True
    except Exception as exc:
        print(f"Perception profile error: {type(exc).__name__}: {exc}")
        return True
    return False


def _install_perception_profiles(module) -> None:
    if getattr(module, "_PERCEPTION_PROFILES_INSTALLED", False):
        return
    module.PERCEPTION_PROFILES_ENCRYPTED_FILE = _PERCEPTION_FILE
    # Database bootstrap is deferred until the core runtime has initialized app_settings and chat tables.
    module.get_perception_metric_catalog = lambda include_values=False, query="": _perception_metric_catalog(module, include_values=include_values, query=query)
    module.list_perception_profiles = lambda include_retired=False, include_history=False: _perception_list_profiles(module, include_retired=include_retired, include_history=include_history)
    module.get_perception_profile = lambda reference=None, version=None: _perception_latest_profile(module, reference, version=version, include_retired=True)
    module.preview_perception_profile = lambda reference=None, query="": _perception_preview(module, reference, query=query)
    module.get_active_perception_packet = lambda query="", force=False: _perception_get_packet(module, query=query, force=force)
    module.activate_perception_profile = lambda reference, version=None: _perception_activate_profile(module, reference, version=version, actor="tool", reason="tool_activation")
    module.save_perception_profile = lambda profile, activate=False: _perception_save_profile(module, profile, provider="tool", model="runtime", actor="Assistant", activate=activate, reason="tool_save")
    module.get_perception_status = lambda: _perception_status(module)
    module.perception_profiles_self_test = lambda: perception_profiles_self_test(module)

    old_build = module.build_runtime_context
    def build_runtime_context_with_perception(query, *args, **kwargs):
        original = old_build(query, *args, **kwargs)
        try:
            context = _perception_prompt_context(module, str(query or ""))
        except Exception as exc:
            context = (
                "SELF-DESIGNED PERCEPTION PROFILE — SAFE FALLBACK\n"
                f"The derived perception packet could not be computed: {type(exc).__name__}: {exc}. "
                "Use authoritative runtime context directly; do not invent missing values."
            )
        return context + "\n\n" + original
    module.build_runtime_context = build_runtime_context_with_perception

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_perception_metric_catalog","description":"Read the Python-authorized metric catalog available for safe perception-profile formulas.","parameters":{"type":"object","properties":{"include_values":{"type":"boolean"},"query":{"type":"string"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"list_perception_profiles","description":"List saved versioned perception profiles and their comments.","parameters":{"type":"object","properties":{"include_retired":{"type":"boolean"},"include_history":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_perception_profile","description":"Read one perception profile by ID or exact name.","parameters":{"type":"object","properties":{"reference":{"type":["string","null"]},"version":{"type":["integer","null"]}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"preview_perception_profile","description":"Calculate a read-only preview packet for one saved perception profile.","parameters":{"type":"object","properties":{"reference":{"type":["string","null"]},"query":{"type":"string"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_active_perception_packet","description":"Read the current Python-computed and cached active perception packet.","parameters":{"type":"object","properties":{"query":{"type":"string"},"force":{"type":"boolean"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_perception_metric_catalog", "list_perception_profiles", "get_perception_profile", "preview_perception_profile", "get_active_perception_packet"})
    old_execute = module.execute_tool
    def execute_tool_with_perception(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_perception_metric_catalog": return module.get_perception_metric_catalog(**arguments)
        if name == "list_perception_profiles": return module.list_perception_profiles(**arguments)
        if name == "get_perception_profile": return module.get_perception_profile(**arguments)
        if name == "preview_perception_profile": return module.preview_perception_profile(**arguments)
        if name == "get_active_perception_packet": return module.get_active_perception_packet(**arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_perception

    old_doctor = module.doctor_report
    def doctor_with_perception():
        report = old_doctor()
        report["perception_profiles"] = _perception_status(module)
        return report
    module.doctor_report = doctor_with_perception

    old_main = module.main
    def main_with_perception_commands():
        original_input = builtins.input
        def perception_input(prompt=""):
            while True:
                value = original_input(prompt)
                lower = str(value or "").strip().casefold()
                if lower == "/perception create" or lower.startswith("/perception design "):
                    purpose = str(value).strip()[len("/perception create"):].strip() if lower == "/perception create" else str(value).strip()[len("/perception design "):].strip()
                    return _perception_design_prompt(purpose)
                if lower.startswith("/perception edit "):
                    body = str(value).strip()[len("/perception edit "):].strip()
                    parts = body.split(None, 1)
                    reference = parts[0] if parts else ""
                    purpose = parts[1] if len(parts) > 1 else "Improve this profile while preserving its purpose."
                    return _perception_design_prompt(purpose, reference=reference)
                if _perception_handle_command(module, value):
                    continue
                return value
        builtins.input = perception_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_perception_commands
    module._PERCEPTION_PROFILES_INSTALLED = True


def perception_profiles_self_test(module) -> dict:
    crypto = _identity_crypto()
    original_encrypt = crypto.encrypt_text
    original_decrypt = crypto.decrypt_text
