_SELF_CONTINUITY_ENTROPY = b"NeatMemory/self-continuity/v1"
_SELF_CONTINUITY_PRIORITIES = ("low", "mid", "high")
_SELF_CONTINUITY_ACTIONS = {"increase", "decrease", "archive", "hold", "review"}
_SELF_CONTINUITY_STATUSES = {"active", "review", "resolved", "archived"}
