def _normalize_openai_compatible_url(raw: str) -> str:
    """Normalize an OpenAI-compatible base URL and ensure it ends in /v1."""
    value = str(raw or "").strip()
    if not value:
        raise ValueError("LLM endpoint cannot be empty.")
    if "://" not in value:
        value = "http://" + value
    parsed = urlsplit(value)
    if parsed.scheme not in {"http", "https"}:
        raise ValueError("LLM endpoint must use http:// or https://.")
    if not parsed.hostname:
        raise ValueError("LLM endpoint must include an IP address or hostname.")
    if parsed.username or parsed.password:
        raise ValueError("Do not put credentials in the URL; use NEATMEMORY_LLM_API_KEY.")
    if parsed.query or parsed.fragment:
        raise ValueError("LLM endpoint must not include a query string or fragment.")
    path = parsed.path.rstrip("/")
    if not path:
        path = "/v1"
    elif not path.casefold().endswith("/v1"):
        path += "/v1"
    return urlunsplit((parsed.scheme, parsed.netloc, path, "", ""))


def _configure_remote_llm(args: list[str]) -> tuple[list[str], dict]:
    """Apply a named LM Studio/Vast profile or a custom endpoint before modules load."""
    remaining: list[str] = []
    values: dict[str, str | bool | None] = {
        "endpoint": None, "url": None, "ip": None, "port": None, "model": None,
        "api_key": None, "show": False,
    }
    expects_value = {
        "--endpoint": "endpoint",
        "--llm-endpoint": "endpoint",
        "--llm-profile": "endpoint",
        "--llm-url": "url",
        "--llm-ip": "ip",
        "--llm-port": "port",
        "--llm-model": "model",
        "--llm-api-key": "api_key",
    }
    index = 0
    while index < len(args):
        token = args[index]
        if token == "--show-llm-config":
            values["show"] = True
            index += 1
            continue
        field = expects_value.get(token)
        if field:
            if index + 1 >= len(args):
                raise ValueError(f"{token} requires a value.")
            values[field] = args[index + 1]
            index += 2
            continue
        remaining.append(token)
        index += 1

    if values["url"] and values["ip"]:
        raise ValueError("Use either --llm-url or --llm-ip, not both.")

    requested_profile = str(values["endpoint"] or "").strip().casefold().replace(" ", "")
    if requested_profile and requested_profile not in {"lmstudio", "vast", "custom"}:
        raise ValueError("--endpoint must be lmstudio, vast, or custom.")
    if requested_profile in {"lmstudio", "vast"} and (values["url"] or values["ip"]):
        raise ValueError("Use a named --endpoint profile or a custom --llm-url/--llm-ip, not both.")

    source = "default"
    profile = requested_profile
    candidate: str | None = None

    if profile == "lmstudio":
        candidate = os.getenv("NEATMEMORY_LMSTUDIO_URL", "http://127.0.0.1:1234/v1")
        source = "--endpoint lmstudio"
    elif profile == "vast":
        candidate = os.getenv("NEATMEMORY_VAST_URL", "http://127.0.0.1:20000/v1")
        source = "--endpoint vast"
    elif values["url"]:
        profile = "custom"
        candidate = str(values["url"])
        source = "--llm-url"
    elif values["ip"]:
        profile = "custom"
        port = str(values["port"] or os.getenv("NEATMEMORY_LLM_PORT", "20000")).strip()
        if not port.isdigit() or not 1 <= int(port) <= 65535:
            raise ValueError("LLM port must be an integer from 1 to 65535.")
        candidate = f"http://{str(values['ip']).strip()}:{port}/v1"
        source = "--llm-ip"
    else:
        env_profile = os.getenv("NEATMEMORY_LLM_ENDPOINT", "").strip().casefold().replace(" ", "")
        if env_profile in {"lmstudio", "vast"}:
            profile = env_profile
            variable = "NEATMEMORY_LMSTUDIO_URL" if profile == "lmstudio" else "NEATMEMORY_VAST_URL"
            default_url = "http://127.0.0.1:1234/v1" if profile == "lmstudio" else "http://127.0.0.1:20000/v1"
            candidate = os.getenv(variable, default_url)
            source = "NEATMEMORY_LLM_ENDPOINT"
        elif os.getenv("NEATMEMORY_LLM_URL", "").strip():
            profile = "custom"
            candidate = os.environ["NEATMEMORY_LLM_URL"]
            source = "NEATMEMORY_LLM_URL"
        elif os.getenv("NEATMEMORY_LLM_IP", "").strip():
            profile = "custom"
            port = os.getenv("NEATMEMORY_LLM_PORT", "20000").strip()
            if not port.isdigit() or not 1 <= int(port) <= 65535:
                raise ValueError("NEATMEMORY_LLM_PORT must be an integer from 1 to 65535.")
            candidate = f"http://{os.environ['NEATMEMORY_LLM_IP'].strip()}:{port}/v1"
            source = "NEATMEMORY_LLM_IP"
        elif os.getenv("LM_STUDIO_BASE_URL", "").strip():
            profile = "custom"
            candidate = os.environ["LM_STUDIO_BASE_URL"]
            source = "LM_STUDIO_BASE_URL"
        else:
            profile = "lmstudio"
            candidate = os.getenv("NEATMEMORY_LMSTUDIO_URL", "http://127.0.0.1:1234/v1")
            source = "default lmstudio"

    resolved = _normalize_openai_compatible_url(candidate)
    os.environ["NEATMEMORY_LLM_ENDPOINT"] = profile or "custom"
    os.environ["NEATMEMORY_LLM_URL"] = resolved
    os.environ["LM_STUDIO_BASE_URL"] = resolved

    if values["model"]:
        model = str(values["model"]).strip()
    elif profile == "lmstudio":
        model = os.getenv("NEATMEMORY_LMSTUDIO_MODEL", "").strip()
    elif profile == "vast":
        model = os.getenv("NEATMEMORY_VAST_MODEL", "").strip()
    else:
        model = str(os.getenv("NEATMEMORY_LLM_MODEL", "") or os.getenv("LM_STUDIO_MODEL", "")).strip()
    if model:
        os.environ["NEATMEMORY_LLM_MODEL"] = model
        os.environ["LM_STUDIO_MODEL"] = model
    else:
        os.environ.pop("NEATMEMORY_LLM_MODEL", None)
        os.environ.pop("LM_STUDIO_MODEL", None)

    if values["api_key"]:
        api_key = str(values["api_key"]).strip()
    elif profile == "lmstudio":
        api_key = os.getenv("NEATMEMORY_LMSTUDIO_API_KEY", "lm-studio").strip() or "lm-studio"
    elif profile == "vast":
        api_key = os.getenv("NEATMEMORY_VAST_API_KEY", "none").strip() or "none"
    else:
        api_key = str(os.getenv("NEATMEMORY_LLM_API_KEY", "") or os.getenv("LM_STUDIO_API_KEY", "none")).strip() or "none"
    os.environ["NEATMEMORY_LLM_API_KEY"] = api_key
    os.environ["LM_STUDIO_API_KEY"] = api_key

    return remaining, {
        "profile": profile or "custom",
        "url": resolved,
        "source": source,
        "model": model or "automatic /v1/models discovery",
        "api_key_configured": bool(api_key),
        "show": bool(values["show"]),
    }

def _print_llm_config(config: dict) -> None:
    print("NeatMemory local endpoint configuration")
    print(f"  Profile:  {config['profile']}")
    print(f"  Endpoint: {config['url']}")
    print(f"  Source:   {config['source']}")
    print(f"  Model:    {config['model']}")
    print(f"  API key:  {'configured' if config['api_key_configured'] else 'placeholder/default'}")



