            _db.execute("INSERT INTO book_chunks VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",("BK-LIVE","C2",2,19,37,"Exact original two","clean two","clean two",hashlib.sha256(b"Exact original two").hexdigest(),"cleanhash2",3,4))
