    old_dir=module.MEMORY_DIR; old_db=module.DATABASE_FILE; old_targets=getattr(module,"_CONST_SELF_TEST_TARGETS",None)
    checks={}
    with tempfile.TemporaryDirectory(prefix="neat-const-") as td:
        root=Path(td); module.MEMORY_DIR=root; module.DATABASE_FILE=root/"neatmemory_v2.db"; module.initialize_database()
        a="semantic:CONST-A"; b="formal:CONST-B"; support="evidence:BK-C:BK-C-C000001"
        module._CONST_SELF_TEST_TARGETS={a:{"book_id":"BK-A","kind":"semantic","sha256":_kir_hash_text("A")},b:{"book_id":"BK-B","kind":"formal","sha256":_kir_hash_text("B")},support:{"book_id":"BK-C","kind":"evidence","sha256":_kir_hash_text("support")}}
        try:
            created=_const_write(module,from_ref=a,to_ref=b,relation_type="thematic_resemblance",epistemic_status="source_supported",rationale="Both nodes stage recognition through concealment.",confidence=0.72,supporting_refs=[support])
            exp=_const_list(module,mode="exploratory"); audited=_const_list(module,mode="audited"); read=_const_read(module,created["edge_id"])
            checks={"created":created.get("ok") is True,"personal_not_fact":created.get("personal_memory") is True and created.get("canonical_fact") is False,"cross_book":read.get("from_book_id")=="BK-A" and read.get("to_book_id")=="BK-B","audited_visible":len(audited.get("items") or [])==1 and audited["items"][0].get("audited") is True,"exploratory_visible":len(exp.get("items") or [])==1,"pins_exact":read.get("from_sha256")==_kir_hash_text("A") and read.get("to_sha256")==_kir_hash_text("B"),"zero_model":created.get("model_calls")==0,"source_not_modified":created.get("source_modified") is False,"neatbook_not_modified":created.get("neatbook_modified") is False}
        finally:
            module.MEMORY_DIR=old_dir; module.DATABASE_FILE=old_db; module._CONST_SELF_TEST_TARGETS=old_targets
    return {"ok":all(checks.values()),"checks":checks,"version":_CONST_VERSION,"model_calls":0,"web_calls":0}


