_ONLINE_TPM_LIMIT_RE = re.compile(r"\bLimit\s*:?\s*(?P<value>\d+(?:\.\d+)?)", re.I)
_ONLINE_TPM_USED_RE = re.compile(r"\b(?:Used|Current)\s*:?\s*(?P<value>\d+(?:\.\d+)?)", re.I)
_ONLINE_TPM_REQUESTED_RE = re.compile(r"\bRequested\s*:?\s*(?P<value>\d+(?:\.\d+)?)", re.I)
_ONLINE_TPM_RETRY_RE = re.compile(r"(?:try again in|retry after)\s*(?P<seconds>\d+(?:\.\d+)?)s?", re.I)
_ONLINE_PROVIDER_PREFLIGHT_DEFAULT_OUTPUT_TOKENS = max(4096, min(65536, int(os.getenv("ONLINE_PROVIDER_PREFLIGHT_OUTPUT_TOKENS", "16384") or "16384")))
_ONLINE_PROVIDER_TPM_LIMIT_TOKENS = max(0, int(os.getenv("ONLINE_PROVIDER_TPM_LIMIT_TOKENS", "0") or "0"))
