_ONLINE_TOOL_RESULT_MAX_TOKENS = max(4096, min(32768, int(os.getenv("ONLINE_TOOL_RESULT_MAX_TOKENS", "24000") or "24000")))
_ONLINE_TOOL_LOOP_HEADROOM_TOKENS = max(4096, min(32768, int(os.getenv("ONLINE_TOOL_LOOP_HEADROOM_TOKENS", "12000") or "12000")))
# A tiny slice of the already-reserved tool-loop headroom is dedicated to receipts
# from state-changing tools. Evidence reads may never consume this reserve. The
# purpose is only to guarantee that Assistant can learn whether a mutation completed
# and obtain its stable ID/ref, preventing accidental duplicate writes when the
# ordinary result budget has fallen to zero late in a tool loop.
_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS = max(256, min(2048, int(os.getenv("ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS", "768") or "768")))
# 7.4.78.59: verification-integrity lane for ONE compact request-envelope receipt.
# Ordinary evidence cannot consume this reserve. A one-receipt verification result may
# enter the in-process working list even when the current WITH_TOOLS estimate has no
# ordinary result room; the tool phase then closes immediately and the next provider
# request must pass the per-request envelope reconciliation + canonical preflight again.
_ONLINE_REQUEST_RECEIPT_VERIFICATION_RESERVE_TOKENS = max(512, min(4096, int(os.getenv("ONLINE_REQUEST_RECEIPT_VERIFICATION_RESERVE_TOKENS", "2048") or "2048")))
_REQUEST_RECEIPT_VERIFICATION_TOOL = "get_request_envelope_receipts"

def _ora_request_receipt_verification_lane(name: str, arguments: dict | None = None) -> bool:
    """Mechanical eligibility for the tiny request-receipt verification lane.

    Only a single compact receipt is eligible. `limit` omitted is mechanically treated
    as 1 by the receipt reader, so Assistant can ask for the newest receipt immediately after
    a provider round even though that round's provider_call_id was generated outside the
    model request. Explicit provider_call_id/envelope_id filters remain supported.
    """
    if str(name or "") != _REQUEST_RECEIPT_VERIFICATION_TOOL:
        return False
    args=dict(arguments or {}) if isinstance(arguments,dict) else {}
    try:
        limit=int(args.get("limit") if args.get("limit") is not None else 1)
    except Exception:
        return False
    return limit == 1

_ONLINE_LIFECYCLE_VERIFICATION_RESERVE_TOKENS = max(512, min(4096, int(os.getenv("ONLINE_LIFECYCLE_VERIFICATION_RESERVE_TOKENS", "2048") or "2048")))
# 7.4.78.152: one compact durable forensic-turn receipt may borrow a bounded slice
# of the already protected execution headroom. This never raises the 120k compiled
# input ceiling and broad diagnostic searches remain ordinary-budget only.
_ONLINE_FORENSIC_RECEIPT_VERIFICATION_RESERVE_TOKENS = max(1024, min(8192, int(os.getenv("ONLINE_FORENSIC_RECEIPT_VERIFICATION_RESERVE_TOKENS", "4096") or "4096")))

def _ora_forensic_receipt_verification_lane(name: str, arguments: dict | None = None) -> bool:
    if str(name or "") != "search_diagnostic_logs": return False
    args=dict(arguments or {}) if isinstance(arguments,dict) else {}
    try: limit=int(args.get("limit") if args.get("limit") is not None else 50)
    except Exception: return False
    return limit == 1 and str(args.get("event_type") or "").casefold() == "forensics.turn_receipt"



def _ora_issue_lifecycle_verification_lane(name: str, arguments: dict | None = None) -> bool:
    """Eligibility for one compact lifecycle verification read under pressure.

    Python judges only bounded shape, never issue relevance or lifecycle meaning.
    """
    tool=str(name or ""); args=dict(arguments or {}) if isinstance(arguments,dict) else {}
    if tool == "get_issue_lifecycle_status": return True
    if tool == "read_issue_lifecycle":
        return bool(str(args.get("issue_id") or "").strip()) and args.get("include_history") is False
    if tool == "list_legacy_issue_candidates":
        try: limit=int(args.get("limit") if args.get("limit") is not None else 100)
        except Exception: return False
        return bool(str(args.get("query") or "").strip()) and limit == 1
    return False

_ANSWER_AUTHORITY_MANIFEST_VERIFICATION_TOOL = "get_answer_authority_manifest"

def _ora_answer_authority_manifest_verification_lane(name: str, arguments: dict | None = None) -> bool:
    """Mechanical eligibility for one compact post-answer authority receipt."""
    if str(name or "") != _ANSWER_AUTHORITY_MANIFEST_VERIFICATION_TOOL:
        return False
    args=dict(arguments or {}) if isinstance(arguments,dict) else {}
    try:
        limit=int(args.get("limit") if args.get("limit") is not None else 1)
    except Exception:
        return False
    return limit == 1

def _ora_reserved_verification_lane_kind(name: str, arguments: dict | None = None) -> str | None:
    if _ora_request_receipt_verification_lane(name,arguments): return "request_envelope_receipt"
    if _ora_answer_authority_manifest_verification_lane(name,arguments): return "answer_authority_manifest"
    if _ora_issue_lifecycle_verification_lane(name,arguments): return "issue_lifecycle"
    if _ora_forensic_receipt_verification_lane(name,arguments): return "forensic_turn_receipt"
    return None


def _ora_reserved_verification_lane_tokens(kind: str | None) -> int:
    if kind == "issue_lifecycle": return int(_ONLINE_LIFECYCLE_VERIFICATION_RESERVE_TOKENS)
    if kind == "forensic_turn_receipt": return int(_ONLINE_FORENSIC_RECEIPT_VERIFICATION_RESERVE_TOKENS)
    return int(_ONLINE_REQUEST_RECEIPT_VERIFICATION_RESERVE_TOKENS)

