def _ora_int(value, default, minimum, maximum):
    try:
        parsed = int(value)
    except Exception:
        parsed = int(default)
    return max(int(minimum), min(int(maximum), parsed))


def _ora_book_read_shape(module, arguments: dict | None = None, result=None) -> dict:
    """Mechanically estimate an exact book range without choosing its meaning.

    Prefer already-produced chunk metadata, then SQLite LENGTH/token metadata, and
    finally a conservative count-only fallback. No source text is returned here and
    Python never selects which story or claim matters.
    """
    args = dict(arguments or {}) if isinstance(arguments, dict) else {}
    book_id = str(args.get("book_id") or "").strip()
    start = _ora_int(args.get("start"), 1, 1, 10_000_000)
    count = _ora_int(args.get("count"), 6, 1, 20)
    rows = []
    if isinstance(result, dict):
        for raw in list(result.get("chunks") or [])[:count]:
            if not isinstance(raw, dict):
                continue
            text = str(raw.get("text") or raw.get("original_text") or "")
            rows.append({
                "chunk_id": str(raw.get("chunk_id") or ""),
                "ordinal": _ora_int(raw.get("ordinal"), start + len(rows), 1, 10_000_000),
                "characters": len(text),
                "token_hint": _ora_int(raw.get("token_estimate"), 0, 0, 10_000_000),
            })
    if not rows and module is not None and book_id:
        books = getattr(module, "neatbooks", None)
        connect = getattr(books, "connect", None)
        if callable(connect):
            try:
                with connect() as db:
                    found = db.execute(
                        "SELECT chunk_id,ordinal,character_count,token_estimate,LENGTH(text) AS text_chars "
                        "FROM book_chunks WHERE book_id=? AND ordinal>=? ORDER BY ordinal LIMIT ?",
                        (book_id, start, count),
                    ).fetchall()
                for raw in found:
                    def value(key, index, default=0):
                        try:
                            return raw[key]
                        except Exception:
                            try:
                                return raw[index]
                            except Exception:
                                return default
                    rows.append({
                        "chunk_id": str(value("chunk_id", 0, "") or ""),
                        "ordinal": _ora_int(value("ordinal", 1, start + len(rows)), start + len(rows), 1, 10_000_000),
                        "characters": _ora_int(value("text_chars", 4, value("character_count", 2, 0)), 0, 0, 100_000_000),
                        "token_hint": _ora_int(value("token_estimate", 3, 0), 0, 0, 10_000_000),
                    })
            except Exception:
                rows = []
    estimates = []
    for row in rows:
        chars = int(row.get("characters") or 0)
        hint = int(row.get("token_hint") or 0)
        # JSON/provenance framing makes raw token_hint alone optimistic. Three
        # chars/token plus a bounded per-chunk envelope matched the real failure.
        tokens = max(800, hint, (chars + 2) // 3) + 160
        estimates.append({
            "chunk_id": str(row.get("chunk_id") or ""),
            "ordinal": int(row.get("ordinal") or 0),
            "estimated_result_tokens": int(tokens),
        })
    if estimates:
        total = 700 + sum(int(item["estimated_result_tokens"]) for item in estimates)
        total += max(0, count - len(estimates)) * 2800
        method = "exact_chunk_metadata"
    else:
        total = 700 + count * 2800
        method = "conservative_count_fallback"
    return {
        "book_id": book_id,
        "start_ordinal": start,
        "requested_count": count,
        "estimated_result_tokens": int(total),
        "chunk_estimates": estimates,
        "estimate_method": method,
        "semantic_selection_performed": False,
    }


def _ora_book_narrowing_plan(module, name: str, arguments: dict, allowed_tokens: int, result=None) -> dict | None:
    if str(name or "") != "read_book_chunks":
        return None
    shape = _ora_book_read_shape(module, arguments, result=result)
    allowed = max(0, int(allowed_tokens or 0))
    budget = max(0, allowed - 700)
    chunk_costs = [int(item.get("estimated_result_tokens") or 0) for item in shape.get("chunk_estimates") or []]
    if not chunk_costs:
        chunk_costs = [2800] * int(shape.get("requested_count") or 1)
    safe_count = 0
    used = 0
    for cost in chunk_costs:
        if used + cost > budget:
            break
        used += cost
        safe_count += 1
    if allowed < int(_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS.get("read_book_chunks", 5000)):
        safe_count = 0
    return {
        "reason": "The requested exact range is mechanically too large for the remaining tool-result room.",
        "requested_range": {
            "book_id": shape.get("book_id"),
            "start_ordinal": shape.get("start_ordinal"),
            "count": shape.get("requested_count"),
        },
        "estimated_result_tokens": shape.get("estimated_result_tokens"),
        "allowed_result_tokens": allowed,
        "suggested_max_count_from_same_start": int(safe_count),
        "chunk_estimates": list(shape.get("chunk_estimates") or [])[:20],
        "targeted_sequence": [
            "Search one requested story title or distinctive character with search_books limit=2 or 3.",
            "Read the best returned ordinal with read_book_chunks count=1.",
            "Continue by one adjacent chunk only if the admitted source ends before the required event.",
        ],
        "retry_batch_limit": 1,
        "semantic_selection_performed_by_python": False,
        "silent_truncation": False,
    }


def _ora_tool_execution_floor_tokens(name: str, arguments: dict | None = None, module=None) -> int:
    """Return a conservative pre-execution result-room floor for one local read.

    7.4.64.3 introduced the common backpressure frame. 7.4.64.4 reused that
    frame for retained research; 7.4.64.5 extends it to row-atomic raw conversation.
    Raw-chat exact/around reads may use SQLite COUNT/LENGTH metadata before execution,
    while research scales only from explicit mechanical request bounds.
    This is not semantic prediction: Python does not choose evidence or estimate
    its importance, and a blocked read claims no evidence.
    """
    tool_name = str(name or "")
    args = dict(arguments or {}) if isinstance(arguments, dict) else {}
    base = int(_ONLINE_TOOL_PREFLIGHT_FLOOR_TOKENS.get(tool_name, _ONLINE_TOOL_BACKPRESSURE_DEFAULT_FLOOR_TOKENS))

    if tool_name == "read_book_chunks":
        shape = _ora_book_read_shape(module, args)
        return max(base, int(shape.get("estimated_result_tokens") or base))

    # Raw conversation is already normalized as one public user/assistant message per
    # stable CHAT row. Preserve that atomic unit: use SQLite LENGTH(content) metadata
    # to price an exact requested row window before building or admitting its text.
    if tool_name in {"search_issue_lifecycle", "list_legacy_issue_candidates"}:
        limit = _ora_int(args.get("limit"), 50 if tool_name == "search_issue_lifecycle" else 100, 1, 500)
        # Candidate/issue rows are bounded metadata/excerpts, not full historical payloads.
        return max(base, 650 + 260 * min(limit, 100))

    if tool_name == "read_issue_lifecycle":
        return max(base, 3200 if bool(args.get("include_history", True)) else 1800)

    if tool_name in {"search_raw_chat", "read_raw_chat", "read_raw_chat_around"}:
        shape_fn = globals().get("_rcr_preflight_shape")
        if callable(shape_fn) and module is not None:
            try:
                shape = dict(shape_fn(module, tool_name, args) or {})
                estimated = int(shape.get("estimated_tokens") or 0)
                if estimated > 0:
                    return max(base, estimated)
            except Exception:
                pass
        if tool_name == "search_raw_chat":
            limit = _ora_int(args.get("limit"), 12, 1, 30)
            chars = limit * int(globals().get("_RAW_CHAT_SEARCH_EXCERPT_CHARS", 1400) or 1400)
            return max(base, 500 + (chars + 2) // 3 + 160 * limit)
        if tool_name == "read_raw_chat":
            count = _ora_int(args.get("count"), 30, 1, 100)
            return max(base, 500 + 320 * count)
        before = _ora_int(args.get("before"), 15, 0, 50)
        after = _ora_int(args.get("after"), 15, 0, 50)
        return max(base, 500 + 320 * (before + after + 1))

    # Fresh public-web tools are network operations, so reject obviously doomed
    # calls *before* contacting the internet. Search results are compact metadata;
    # page reads scale from the explicit maximum readable-text request.
    if tool_name == "live_web_search":
        max_results = _ora_int(args.get("max_results"), 5, 1, 10)
        return max(base, 650 + 420 * max_results)

    if tool_name == "live_web_read":
        max_chars = _ora_int(args.get("max_chars"), 12000, 1000, 20000)
        return max(base, 650 + (max_chars + 2) // 3)

    if tool_name == "live_web_map":
        max_signposts = _ora_int(args.get("max_signposts"), 10, 3, 20)
        return max(base, 800 + 260 * max_signposts)

    if tool_name == "live_web_passage":
        before = _ora_int(args.get("before"), 250, 0, 5000)
        after = _ora_int(args.get("after"), 1500, 200, 7000)
        return max(base, 700 + (before + after + 600 + 2) // 3)

    # Archived research-page search returns up to limit * excerpt_chars of source
    # text plus snapshot/provenance metadata. Three chars/token is intentionally
    # conservative for a preflight floor; the post-execution admission guard
    # remains authoritative if an unusual result is still larger.
    if tool_name == "search_web_archive":
        limit = _ora_int(args.get("limit"), 8, 1, 30)
        excerpt_chars = _ora_int(args.get("excerpt_chars"), 1400, 400, 3000)
        return max(base, 512 + (limit * excerpt_chars + 2) // 3)

    if tool_name == "read_web_archive_page":
        characters = _ora_int(args.get("characters"), 12000, 500, 26000)
        return max(base, 600 + (characters + 2) // 3)

    if tool_name == "read_web_archive_around":
        before = _ora_int(args.get("before"), 1800, 0, 10000)
        after = _ora_int(args.get("after"), 7000, 500, 20000)
        return max(base, 600 + (before + after + 300 + 2) // 3)

    # Metadata/result-list surfaces are bounded by item count rather than a direct
    # character range. Scale conservatively so a small search can still run after
    # a broad read is refused, while large result lists are stopped earlier.
    if tool_name == "list_web_archive_pages":
        limit = _ora_int(args.get("limit"), 20, 1, 100)
        return max(base, 500 + 110 * limit)

    if tool_name == "search_web_evidence_units":
        limit = _ora_int(args.get("limit"), 12, 1, 50)
        return max(base, 600 + 180 * limit)

    # A reconstructed WEU has no caller-supplied size bound. Require meaningful
    # room and let Assistant fall back to bounded unit search/archive reads when tight.
    if tool_name == "read_web_evidence_unit":
        return max(base, 5500)

    # Direct research-report tools are not added by this hotfix, but if already
    # present through another installed surface, honor their explicit max_chars.
    if tool_name == "read_research_report":
        max_chars = _ora_int(args.get("max_chars"), 30000, 1000, 120000)
        return max(base, 800 + (max_chars + 2) // 3)

    if tool_name in {"list_research_reports", "search_research_reports"}:
        limit = _ora_int(args.get("limit"), 20 if tool_name == "list_research_reports" else 8, 1, 50)
        return max(base, 500 + 140 * limit)

    return base


def _ora_clean_result(module, value):
    cleaner = getattr(getattr(module, "context_cleaner", None), "clean_payload", None)
    if callable(cleaner):
        try:
            return cleaner(value, string_limit=_ONLINE_BOOK_RESULT_STRING_LIMIT)
        except Exception:
            pass
    return value


def _ora_working_request_estimate(module, instructions: str, working: list, tools: list) -> dict:
    """Estimate current Responses input before admitting another local tool result.

    This deliberately mirrors provider preflight without changing retrieval, logging a
    provider attempt, or reserving a new completion. It is used only to decide whether
    a *new* local tool result can safely enter the next tool-loop round.
    """
    try:
        input_wire = json.dumps(working or [], ensure_ascii=False, separators=(",", ":"), default=str)
    except Exception:
        input_wire = str(working or [])
    try:
        tools_wire = json.dumps(tools or [], ensure_ascii=False, separators=(",", ":"), default=str)
    except Exception:
        tools_wire = str(tools or [])
    instructions_tokens = _ora_estimate_text_tokens(module, instructions or "")
    input_items_tokens = _ora_estimate_text_tokens(module, input_wire)
    tools_tokens = _ora_estimate_text_tokens(module, tools_wire) if tools else 0
    protocol_overhead_tokens = 256 + 16 * len(working or []) + 24 * len(tools or [])
    return {
        "instructions_tokens": instructions_tokens,
        "input_items_tokens": input_items_tokens,
        "tools_tokens": tools_tokens,
        "protocol_overhead_tokens": protocol_overhead_tokens,
        "final_input_estimate_tokens": instructions_tokens + input_items_tokens + tools_tokens + protocol_overhead_tokens,
    }


def _ora_tool_budget_snapshot(module, *, instructions: str, working: list, tools: list, mutation_tool: bool = False) -> dict:
    """Return deterministic tool-result room before a local tool is executed.

    This is token mechanics only. It never changes retrieval, evidence ordering, or
    Assistant's interpretation. Evidence/read tools may use only ordinary result room;
    mutation tools may additionally rely on the tiny receipt reserve from 7.4.64.2.
    """
    current = _ora_working_request_estimate(module, instructions, working, tools)
    decision = dict(getattr(module, "_ADAPTIVE_LAST_DECISION", {}) or {})
    last_preflight = dict(getattr(module, "_ONLINE_PROVIDER_PREFLIGHT_LAST", {}) or {})
    output_cap = int(last_preflight.get("max_output_tokens") or decision.get("reserved_output_tokens") or getattr(module, "CHAT_OUTPUT_RESERVE_TOKENS", 0) or _ONLINE_PROVIDER_PREFLIGHT_DEFAULT_OUTPUT_TOKENS)
    model_limit = int(decision.get("model_context_limit_tokens") or 0)
    safety_margin = int(decision.get("safety_margin_tokens") or 0)
    physical_model_safe_input = max(1, model_limit - output_cap - safety_margin) if model_limit > 0 else 0
    adaptive_safe_input = int(decision.get("safe_input_limit_tokens") or 0)
    model_safe_input = min(x for x in (physical_model_safe_input, adaptive_safe_input) if x > 0) if (physical_model_safe_input > 0 or adaptive_safe_input > 0) else 0
    fixed_cap = int(_ONLINE_TOOL_RESULT_MAX_TOKENS)
    current_tokens = int(current.get("final_input_estimate_tokens") or 0)
    if model_safe_input > 0:
        hard_remaining = max(0, model_safe_input - current_tokens)
        remaining = max(0, hard_remaining - int(_ONLINE_TOOL_LOOP_HEADROOM_TOKENS))
        allowed_tokens = max(0, min(fixed_cap, remaining))
        mutation_allowed_tokens = max(0, min(int(_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS), hard_remaining)) if mutation_tool else 0
    else:
        hard_remaining = None
        remaining = None
        allowed_tokens = fixed_cap
        mutation_allowed_tokens = int(_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS) if mutation_tool else 0
    return {
        "current_input_estimate_tokens": current_tokens,
        "model_safe_input_tokens": int(model_safe_input) if model_safe_input else None,
        "physical_model_safe_input_tokens": int(physical_model_safe_input) if physical_model_safe_input else None,
        "adaptive_safe_input_limit_tokens": int(adaptive_safe_input) if adaptive_safe_input else None,
        "hard_remaining_before_result_tokens": int(hard_remaining) if hard_remaining is not None else None,
        "remaining_before_result_tokens": int(remaining) if remaining is not None else None,
        "allowed_result_tokens": int(allowed_tokens),
        "mutation_allowed_tokens": int(mutation_allowed_tokens),
        "fixed_per_result_cap_tokens": fixed_cap,
        "headroom_tokens": int(_ONLINE_TOOL_LOOP_HEADROOM_TOKENS),
        "output_cap_tokens": int(output_cap),
    }


def _ora_tool_preflight_backpressure(module, *, name: str, arguments: dict, instructions: str, working: list, tools: list, prior_budget_block: bool = False) -> tuple[bool, str, dict]:
    """Decide whether a local tool should execute before producing its result.

    State-changing tools are never blocked here because their commit acknowledgement is
    protected separately. For reads, once a parallel batch has already hit the payload
    guard, later reads in that same batch are deferred so the model can see the first
    budget signal before choosing another range. Otherwise a conservative per-tool floor
    prevents obviously doomed reads when ordinary admission room is already too small.
    """
    tool_name = str(name or "")
    mutation_tool = tool_name in _ONLINE_MUTATING_TOOL_NAMES
    verification_lane_kind = _ora_reserved_verification_lane_kind(tool_name, arguments)
    request_receipt_lane = verification_lane_kind == "request_envelope_receipt"
    answer_manifest_lane = verification_lane_kind == "answer_authority_manifest"
    lifecycle_lane = verification_lane_kind == "issue_lifecycle"
    forensic_lane = verification_lane_kind == "forensic_turn_receipt"
    verification_reserve_tokens = _ora_reserved_verification_lane_tokens(verification_lane_kind) if verification_lane_kind else 0
    snapshot = _ora_tool_budget_snapshot(module, instructions=instructions, working=working, tools=tools, mutation_tool=mutation_tool)
    allowed = int(snapshot.get("allowed_result_tokens") or 0)
    floor = int(_ora_tool_execution_floor_tokens(tool_name, arguments, module=module))
    details = dict(snapshot)
    details.update({
        "tool": tool_name,
        "arguments": dict(arguments or {}),
        "mutation_tool": bool(mutation_tool),
        "reserved_verification_lane_kind": verification_lane_kind,
        "request_receipt_verification_lane": bool(request_receipt_lane),
        "answer_authority_manifest_verification_lane": bool(answer_manifest_lane),
        "issue_lifecycle_verification_lane": bool(lifecycle_lane),
        "forensic_turn_receipt_verification_lane": bool(forensic_lane),
        "verification_reserve_tokens": int(verification_reserve_tokens),
        "request_receipt_reserve_tokens": int(_ONLINE_REQUEST_RECEIPT_VERIFICATION_RESERVE_TOKENS) if verification_lane_kind in {"request_envelope_receipt","answer_authority_manifest"} else 0,
        "lifecycle_verification_reserve_tokens": int(_ONLINE_LIFECYCLE_VERIFICATION_RESERVE_TOKENS) if lifecycle_lane else 0,
        "forensic_verification_reserve_tokens": int(_ONLINE_FORENSIC_RECEIPT_VERIFICATION_RESERVE_TOKENS) if forensic_lane else 0,
        "conservative_execution_floor_tokens": floor,
        "prior_budget_block_in_batch": bool(prior_budget_block),
        "context_or_retrieval_changed": False,
        "evidence_claimed": False,
    })
    if verification_lane_kind:
        # One compact mechanical verification receipt may execute even if ordinary room
        # is zero or an earlier read in this batch was blocked. Its result still has the
        # same strict reserve cap and closes the tool phase before the next send.
        reason=("single_request_receipt_verification_lane" if request_receipt_lane else "single_answer_authority_manifest_verification_lane" if answer_manifest_lane else "bounded_issue_lifecycle_verification_lane" if lifecycle_lane else "single_forensic_turn_receipt_verification_lane")
        details.update({"execute": True, "close_tool_phase": True, "close_after_result": True, "reason": reason})
        return True, "", details
    if mutation_tool or snapshot.get("model_safe_input_tokens") is None:
        details.update({"execute": True, "close_tool_phase": False, "reason": "mutation_receipt_protected" if mutation_tool else "context_limit_unknown"})
        return True, "", details
    if prior_budget_block:
        details.update({"execute": False, "close_tool_phase": allowed <= int(_ONLINE_TOOL_BACKPRESSURE_CLOSE_TOKENS), "reason": "previous_read_in_parallel_batch_hit_budget_guard"})
    elif allowed <= 0:
        details.update({"execute": False, "close_tool_phase": True, "reason": "ordinary_read_result_room_exhausted"})
    elif allowed < floor:
        details.update({"execute": False, "close_tool_phase": allowed <= int(_ONLINE_TOOL_BACKPRESSURE_CLOSE_TOKENS), "reason": "remaining_room_below_conservative_execution_floor"})
    else:
        details.update({"execute": True, "close_tool_phase": False, "reason": "sufficient_preflight_room"})
        return True, "", details
    envelope = {
        "ok": True,
        "tool_executed": False,
        "tool_loop_backpressure": True,
        "tool": tool_name,
        "arguments": dict(arguments or {}),
        "allowed_result_tokens": allowed,
        "conservative_execution_floor_tokens": floor,
        "close_tool_phase": bool(details.get("close_tool_phase")),
        "reason": details.get("reason"),
        "read_only": True,
        "evidence_returned": False,
        "silent_truncation": False,
        "next_action": (
            "Answer from evidence already admitted; no more read tools are available in this response."
            if details.get("close_tool_phase")
            else "Re-plan after this budget signal and issue a materially narrower read/search if more evidence is still necessary."
        ),
    }
    narrowing = _ora_book_narrowing_plan(module, tool_name, arguments, allowed)
    if narrowing is not None:
        envelope["mechanical_narrowing_plan"] = narrowing
    logger = getattr(module, "append_diagnostic_log", None)
    if callable(logger):
        try:
            logger("tool.preflight_budget_blocked", f"Online local read tool blocked before execution: {tool_name}", severity="warning", subsystem="tools", provider="online", details=details)
        except Exception:
            pass
    if details.get("reason") == "previous_read_in_parallel_batch_hit_budget_guard":
        console_reason = f"{tool_name} deferred after an earlier read in the same batch hit the budget guard"
    elif allowed <= 0:
        console_reason = f"{tool_name} not executed; ordinary read-result room exhausted"
    else:
        console_reason = f"{tool_name} not executed; ordinary allowed ~{allowed:,}t below conservative floor ~{floor:,}t"
    print(
        "[tool-loop backpressure] " + console_reason
        + (" | close tool phase" if details.get("close_tool_phase") else " | re-plan one narrower read"),
        flush=True,
    )
    return False, json.dumps(envelope, ensure_ascii=False, default=str), details


def _ora_tool_result_admission(module, *, name: str, arguments: dict, result, instructions: str, working: list, tools: list) -> tuple[str, dict]:
    """Admit one local tool result only if the next Responses round can hold it.

    Evidence/read results retain the strict 7.4.62.3 rule: Python never semantically
    summarizes or silently truncates them. State-changing tools are different because
    execution may already have committed before admission is evaluated. A tiny fixed
    receipt allowance is therefore carved from the existing tool-loop headroom so a
    successful mutation can always return its stable mechanical acknowledgement instead
    of looking like an unread oversized evidence result.
    """
    tool_name = str(name or "")
    mutation_tool = tool_name in _ONLINE_MUTATING_TOOL_NAMES
    verification_lane_kind = _ora_reserved_verification_lane_kind(tool_name, arguments)
    request_receipt_lane = verification_lane_kind == "request_envelope_receipt"
    answer_manifest_lane = verification_lane_kind == "answer_authority_manifest"
    lifecycle_lane = verification_lane_kind == "issue_lifecycle"
    forensic_lane = verification_lane_kind == "forensic_turn_receipt"
    verification_reserve_tokens = _ora_reserved_verification_lane_tokens(verification_lane_kind) if verification_lane_kind else 0
    cleaned = _ora_clean_result(module, result)
    try:
        wire = json.dumps(cleaned, ensure_ascii=False, default=str)
    except Exception:
        wire = json.dumps({"ok": False, "error": "Tool result could not be serialized safely."}, ensure_ascii=False)
    result_tokens = _ora_estimate_text_tokens(module, wire)
    current = _ora_working_request_estimate(module, instructions, working, tools)
    decision = dict(getattr(module, "_ADAPTIVE_LAST_DECISION", {}) or {})
    last_preflight = dict(getattr(module, "_ONLINE_PROVIDER_PREFLIGHT_LAST", {}) or {})
    output_cap = int(last_preflight.get("max_output_tokens") or decision.get("reserved_output_tokens") or getattr(module, "CHAT_OUTPUT_RESERVE_TOKENS", 0) or _ONLINE_PROVIDER_PREFLIGHT_DEFAULT_OUTPUT_TOKENS)
    model_limit = int(decision.get("model_context_limit_tokens") or 0)
    safety_margin = int(decision.get("safety_margin_tokens") or 0)
    physical_model_safe_input = max(1, model_limit - output_cap - safety_margin) if model_limit > 0 else 0
    adaptive_safe_input = int(decision.get("safe_input_limit_tokens") or 0)
    model_safe_input = min(x for x in (physical_model_safe_input, adaptive_safe_input) if x > 0) if (physical_model_safe_input > 0 or adaptive_safe_input > 0) else 0
    fixed_cap = int(_ONLINE_TOOL_RESULT_MAX_TOKENS)
    current_tokens = int(current.get("final_input_estimate_tokens") or 0)
    if model_safe_input > 0:
        hard_remaining = max(0, model_safe_input - current_tokens)
        remaining = max(0, hard_remaining - int(_ONLINE_TOOL_LOOP_HEADROOM_TOKENS))
        allowed_tokens = max(0, min(fixed_cap, remaining))
        mutation_allowed_tokens = max(0, min(int(_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS), hard_remaining)) if mutation_tool else 0
    else:
        hard_remaining = None
        remaining = None
        allowed_tokens = fixed_cap
        mutation_allowed_tokens = int(_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS) if mutation_tool else 0

    ordinary_admitted = result_tokens <= allowed_tokens and allowed_tokens >= 1
    mutation_full_admitted = mutation_tool and result_tokens <= mutation_allowed_tokens and mutation_allowed_tokens >= 1
    reserved_verification_admitted = bool(verification_lane_kind) and result_tokens <= int(verification_reserve_tokens)
    request_receipt_reserved_admitted = request_receipt_lane and reserved_verification_admitted
    answer_manifest_reserved_admitted = answer_manifest_lane and reserved_verification_admitted
    lifecycle_reserved_admitted = lifecycle_lane and reserved_verification_admitted
    forensic_reserved_admitted = forensic_lane and reserved_verification_admitted
    admitted = ordinary_admitted or mutation_full_admitted or reserved_verification_admitted
    details = {
        "tool": tool_name,
        "estimated_result_tokens": int(result_tokens),
        "allowed_result_tokens": int(allowed_tokens),
        "mutation_tool": bool(mutation_tool),
        "reserved_verification_lane_kind": verification_lane_kind,
        "request_receipt_verification_lane": bool(request_receipt_lane),
        "answer_authority_manifest_verification_lane": bool(answer_manifest_lane),
        "issue_lifecycle_verification_lane": bool(lifecycle_lane),
        "forensic_turn_receipt_verification_lane": bool(forensic_lane),
        "verification_reserve_tokens": int(verification_reserve_tokens),
        "request_receipt_reserve_tokens": int(_ONLINE_REQUEST_RECEIPT_VERIFICATION_RESERVE_TOKENS) if verification_lane_kind in {"request_envelope_receipt","answer_authority_manifest"} else 0,
        "lifecycle_verification_reserve_tokens": int(_ONLINE_LIFECYCLE_VERIFICATION_RESERVE_TOKENS) if lifecycle_lane else 0,
        "forensic_verification_reserve_tokens": int(_ONLINE_FORENSIC_RECEIPT_VERIFICATION_RESERVE_TOKENS) if forensic_lane else 0,
        "request_receipt_reserved_admitted": bool(request_receipt_reserved_admitted),
        "answer_authority_manifest_reserved_admitted": bool(answer_manifest_reserved_admitted),
        "issue_lifecycle_reserved_admitted": bool(lifecycle_reserved_admitted),
        "forensic_turn_receipt_reserved_admitted": bool(forensic_reserved_admitted),
        "mutation_receipt_reserve_tokens": int(_ONLINE_MUTATION_RECEIPT_RESERVE_TOKENS) if mutation_tool else 0,
        "mutation_allowed_tokens": int(mutation_allowed_tokens),
        "current_input_estimate_tokens": current_tokens,
        "model_safe_input_tokens": int(model_safe_input) if model_safe_input else None,
        "physical_model_safe_input_tokens": int(physical_model_safe_input) if physical_model_safe_input else None,
        "adaptive_safe_input_limit_tokens": int(adaptive_safe_input) if adaptive_safe_input else None,
        "hard_remaining_before_result_tokens": int(hard_remaining) if hard_remaining is not None else None,
        "remaining_before_result_tokens": int(remaining) if remaining is not None else None,
        "fixed_per_result_cap_tokens": fixed_cap,
        "headroom_tokens": int(_ONLINE_TOOL_LOOP_HEADROOM_TOKENS),
        "admitted": bool(admitted),
        "full_result_admitted": bool(admitted),
        "context_or_retrieval_changed": False,
        "silent_truncation": False,
    }
    logger = getattr(module, "append_diagnostic_log", None)
    if admitted:
        if mutation_full_admitted and not ordinary_admitted:
            details["mutation_receipt_headroom_used"] = True
        if reserved_verification_admitted and not ordinary_admitted:
            details["reserved_verification_lane_used"] = True
            details["request_receipt_verification_reserve_used"] = bool(request_receipt_lane)
            details["answer_authority_manifest_verification_reserve_used"] = bool(answer_manifest_lane)
            details["issue_lifecycle_verification_reserve_used"] = bool(lifecycle_lane)
            details["forensic_turn_receipt_verification_reserve_used"] = bool(forensic_lane)
            details["close_tool_phase_after_result"] = True
            details["temporary_working_overflow_allowed_before_reconciliation"] = True
            print(
                "[tool-loop verification lane] "
                f"{tool_name} bounded verification result ~{result_tokens:,}t admitted from reserved ~{int(verification_reserve_tokens):,}t lane | close tool phase | next provider request must revalidate",
                flush=True,
            )
        if callable(logger):
            try:
                if reserved_verification_admitted and not ordinary_admitted:
                    event = ("tool.request_receipt_verification_reserved_admitted" if request_receipt_lane else "tool.answer_authority_manifest_verification_reserved_admitted" if answer_manifest_lane else "tool.issue_lifecycle_verification_reserved_admitted" if lifecycle_lane else "tool.forensic_turn_receipt_verification_reserved_admitted")
                else:
                    event = "tool.mutation_result_admitted" if mutation_full_admitted and not ordinary_admitted else "tool.result_admitted"
                logger(event, f"Online local tool result admitted: {name}", subsystem="tools", provider="online", details=details)
            except Exception:
                pass
        return wire, details

    # A state-changing tool may already have committed. Never answer that situation
    # with the ordinary "make a narrower read" envelope, because retrying could
    # duplicate a write. Return only deterministic mechanical receipt fields.
    if mutation_tool:
        source = cleaned if isinstance(cleaned, dict) else {}
        ok_value = source.get("ok", True)
        committed = bool(ok_value is not False)
        receipt = {
            "ok": bool(committed),
            "tool": tool_name,
            "mutation_receipt": True,
            "committed": bool(committed),
            "full_result_admitted": False,
            "full_result_withheld_for_budget": True,
            "do_not_repeat_automatically": True,
        }
        for key in _ONLINE_MUTATION_RECEIPT_KEYS:
            value = source.get(key)
            if value is None:
                continue
            if isinstance(value, (str, int, float, bool)) and (not isinstance(value, str) or len(value) <= 300):
                receipt[key] = value
            elif key == "active_paths" and isinstance(value, list):
                receipt[key] = [str(x)[:200] for x in value[:24]]
        if not committed and source.get("error"):
            receipt["error"] = str(source.get("error"))[:500]
        receipt_wire = json.dumps(receipt, ensure_ascii=False, default=str)
        receipt_tokens = _ora_estimate_text_tokens(module, receipt_wire)
        details["mutation_receipt_tokens"] = int(receipt_tokens)
        details["full_result_admitted"] = False
        details["mutation_receipt_admitted"] = bool(mutation_allowed_tokens >= 1 and receipt_tokens <= mutation_allowed_tokens)
        # The compact receipt is deliberately bounded independently from evidence.
        # If even the conservative safe-input estimate says no reserved room remains,
        # keep the receipt minimal and mark the condition visibly rather than telling
        # Assistant to repeat a mutation whose result Python already knows.
        if not details["mutation_receipt_admitted"]:
            receipt = {
                "ok": bool(committed),
                "tool": tool_name,
                "mutation_receipt": True,
                "committed": bool(committed),
                "receipt_budget_exhausted": True,
                "do_not_repeat_automatically": True,
            }
            for key in ("edge_id", "ref", "entry_id", "path", "preview_id", "annotation_id", "receipt_id", "memory_id", "status", "revision"):
                value = source.get(key)
                if isinstance(value, (str, int, float, bool)) and (not isinstance(value, str) or len(value) <= 200):
                    receipt[key] = value
            receipt_wire = json.dumps(receipt, ensure_ascii=False, default=str)
            details["mutation_receipt_tokens"] = int(_ora_estimate_text_tokens(module, receipt_wire))
        details["admitted"] = True
        details["withheld_before_next_provider_round"] = False
        if callable(logger):
            try:
                logger("tool.mutation_receipt_admitted", f"State-changing tool returned compact mutation receipt: {name}", severity="warning", subsystem="tools", provider="online", details=details)
            except Exception:
                pass
        print(
            "[tool-loop budget] "
            f"{name} result ~{result_tokens:,}t exceeds ordinary allowed ~{allowed_tokens:,}t; compact mutation receipt ~{int(details.get('mutation_receipt_tokens') or 0):,}t returned | no duplicate-write ambiguity",
            flush=True,
        )
        return receipt_wire, details

    scalar_meta = {}
    if isinstance(cleaned, dict):
        for key, value in cleaned.items():
            if len(scalar_meta) >= 16:
                break
            if value is None or isinstance(value, (str, int, float, bool)):
                text = str(value) if isinstance(value, str) else value
                if not isinstance(text, str) or len(text) <= 300:
                    scalar_meta[str(key)] = text
    envelope = {
        "ok": True,
        "result_admitted": False,
        "result_too_large_for_tool_loop": True,
        "tool": tool_name,
        "arguments": dict(arguments or {}),
        "estimated_result_tokens": int(result_tokens),
        "allowed_result_tokens": int(allowed_tokens),
        "silent_truncation": False,
        "evidence_dropped": False,
        "mechanical_metadata": scalar_meta,
        "next_action": "Issue a narrower tool call (smaller range/limit or specific node/orders). Python withheld the oversized result rather than truncating or semantically summarizing it.",
        "read_only": True,
    }
    narrowing = _ora_book_narrowing_plan(module, tool_name, arguments, allowed_tokens, result=cleaned)
    if narrowing is not None:
        envelope["mechanical_narrowing_plan"] = narrowing
    details["withheld_before_next_provider_round"] = True
    if callable(logger):
        try:
            logger("tool.result_budget_blocked", f"Online local tool result withheld from provider context: {name}", severity="warning", subsystem="tools", provider="online", details=details)
        except Exception:
            pass
    print(
        "[tool-loop budget] "
        f"{name} result ~{result_tokens:,}t exceeds allowed ~{allowed_tokens:,}t; full result withheld, narrower read required | no silent truncation",
        flush=True,
    )
    return json.dumps(envelope, ensure_ascii=False, default=str), details


def _ora_book_overview(module, book_id: str, *, chunk_count: int = 8, entry_limit: int = 120) -> dict:
    """Read-only structural scan of opening book chunks; returns exact lines and provenance, not semantic conclusions."""
    books = getattr(module, "neatbooks", None)
    bid = str(book_id or "").strip()
    if books is None:
        return {"ok": False, "error": "NeatBooks is unavailable.", "read_only": True, "model_calls": 0}
    if not bid:
        return {"ok": False, "error": "book_id is required.", "read_only": True, "model_calls": 0}
    chunk_count = _ora_int(chunk_count, 8, 1, 20)
    entry_limit = _ora_int(entry_limit, 120, 1, 200)
    raw = books.read_book_chunks(book_id=bid, start=1, count=chunk_count)
    if not isinstance(raw, dict) or raw.get("ok") is False:
        result = dict(raw) if isinstance(raw, dict) else {"ok": False, "error": "Book read failed."}
        result.update({"read_only": True, "model_calls": 0, "operation": "book_overview"})
        return _ora_clean_result(module, result)
    _bni_observe_read_result(module, raw, trigger="book_overview")
    chunks = list(raw.get("chunks") or [])
    marker_re = re.compile(r"^(?:table\s+of\s+contents|contents?|index|works?|plays?)\s*[:.-]*$", re.IGNORECASE)
    detected = []
    candidates = []
    marker_seen = False
    for chunk in chunks:
        if not isinstance(chunk, dict):
            continue
        cid = str(chunk.get("chunk_id") or "")
        try: ordinal = int(chunk.get("ordinal") or 0)
        except Exception: ordinal = 0
        text = str(chunk.get("text") or "")
        for line_no, raw_line in enumerate(text.splitlines(), 1):
            line = " ".join(str(raw_line).strip().split())
            if not line:
                continue
            if marker_re.match(line):
                marker_seen = True
                detected.append({"text": line, "book_id": bid, "chunk_id": cid, "ordinal": ordinal, "line_in_chunk": line_no})
                continue
            # Once a structural marker is found, retain exact subsequent non-empty lines.
            # If none is found, retain only short opening heading-like lines as navigation hints.
            keep = marker_seen or (len(line) <= 140 and (line.isupper() or line.istitle()))
            if keep and len(candidates) < entry_limit:
                candidates.append({"text": line, "book_id": bid, "chunk_id": cid, "ordinal": ordinal, "line_in_chunk": line_no})
    book = dict(raw.get("book") or {})
    return _ora_clean_result(module, {
        "ok": True,
        "operation": "book_overview",
        "book": book,
        "book_id": bid,
        "scanned_range": {"start_ordinal": 1, "chunk_count": chunk_count},
        "detected_markers": detected,
        "candidate_structure_lines": candidates,
        "marker_found": bool(detected),
        "interpretation_note": "These are exact structural/navigation candidates from opening chunks. Python did not classify them as definitive works/chapters; Assistant decides what they mean from the evidence.",
        "read_only": True,
        "model_calls": 0,
    })



# ---------------------------------------------------------------------------
# 7.4.78.132 BOOK MECHANICAL PROFILE CONSOLIDATION
# ---------------------------------------------------------------------------
# One subsystem now owns the reusable source-bound book profile lifecycle, compact
# projection, provenance/compatibility receipts, deterministic two-profile
# comparison, model/tool exposure, and the capsule-safe projection hook. This is a
# no-new-semantics consolidation of the live-proven .129/.130/.131 contracts.
# Persisted table names and the .129 profile schema identifier remain unchanged so
# existing profiles require no migration or rescan; the .131 comparison algorithm
# identifier also remains a compatibility fact. Exact source remains authority.
# Python performs only mechanical storage, counting, hashing, compatibility checks,
# bounded projection, and exact intersection/delta calculations; Assistant owns meaning.
_BMP132_VERSION = "1.0-book-mechanical-profile-consolidated"
_BM129_VERSION = "1.0-reusable-book-mechanical-metadata"  # persisted profile schema compatibility ID
_BM129_NORMALIZATION_VERSION = "hd80-exact-word-normalization-v1"
_BM129_REGION_CHUNKS = 8
_BM129_MAX_LOCATIONS_PER_TERM = 16
_BM129_CARD_TERMS = 12
_BM129_CARD_STRUCTURES = 8
_BM129_CARD_REGIONS = 4
_BM129_CARD_SIGNPOSTS = 6
_BM129_PROFILE_TABLE = "knowledge_book_mechanical_profiles"
_BM129_HEAD_TABLE = "knowledge_book_mechanical_profile_heads"
_BM129_TERM_TABLE = "knowledge_book_mechanical_terms"
_BM129_REGION_TABLE = "knowledge_book_mechanical_regions"
_BM129_SIGNPOST_TABLE = "knowledge_book_mechanical_signposts"
_BM129_BASE_BOOK_OVERVIEW = _ora_book_overview


def _bm129_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _bm129_ensure_schema() -> None:
    _kw122_ensure_schema()
    with _sk_connect() as db:
        db.executescript(f"""
        CREATE TABLE IF NOT EXISTS {_BM129_PROFILE_TABLE}(
            profile_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL,
            source_fingerprint_sha256 TEXT NOT NULL,
            source_sha256 TEXT NOT NULL,
            schema_version TEXT NOT NULL,
            normalization_version TEXT NOT NULL,
            identity_json TEXT NOT NULL,
            structure_json TEXT NOT NULL,
            coverage_json TEXT NOT NULL,
            summary_json TEXT NOT NULL,
            metadata_sha256 TEXT NOT NULL,
            generated_at TEXT NOT NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_bm129_profile_book_source
            ON {_BM129_PROFILE_TABLE}(book_id,source_fingerprint_sha256,schema_version);
        CREATE TABLE IF NOT EXISTS {_BM129_HEAD_TABLE}(
            book_id TEXT PRIMARY KEY,
            profile_id TEXT NOT NULL,
            source_fingerprint_sha256 TEXT NOT NULL,
            metadata_sha256 TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS {_BM129_TERM_TABLE}(
            profile_id TEXT NOT NULL,
            term TEXT NOT NULL,
            occurrence_count INTEGER NOT NULL,
            chunk_hits INTEGER NOT NULL,
            total_tokens INTEGER NOT NULL,
            density REAL NOT NULL,
            distribution REAL NOT NULL,
            chunk_distinctiveness REAL NOT NULL,
            lexical_strength REAL NOT NULL,
            first_ordinal INTEGER,
            last_ordinal INTEGER,
            locations_json TEXT NOT NULL,
            PRIMARY KEY(profile_id,term)
        );
        CREATE INDEX IF NOT EXISTS idx_bm129_term_lookup ON {_BM129_TERM_TABLE}(term,lexical_strength,profile_id);
        CREATE TABLE IF NOT EXISTS {_BM129_REGION_TABLE}(
            profile_id TEXT NOT NULL,
            region_id TEXT NOT NULL,
            region_kind TEXT NOT NULL,
            label TEXT NOT NULL,
            start_ordinal INTEGER NOT NULL,
            end_ordinal INTEGER NOT NULL,
            chunk_count INTEGER NOT NULL,
            token_count INTEGER NOT NULL,
            source_range_sha256 TEXT NOT NULL,
            top_frequency_json TEXT NOT NULL,
            concentrated_terms_json TEXT NOT NULL,
            provenance_json TEXT NOT NULL,
            PRIMARY KEY(profile_id,region_id)
        );
        CREATE INDEX IF NOT EXISTS idx_bm129_region_book_order ON {_BM129_REGION_TABLE}(profile_id,start_ordinal,end_ordinal);
        CREATE TABLE IF NOT EXISTS {_BM129_SIGNPOST_TABLE}(
            profile_id TEXT NOT NULL,
            rich_revision_id TEXT NOT NULL,
            node_id TEXT NOT NULL,
            node_type TEXT NOT NULL,
            sequence_no INTEGER NOT NULL DEFAULT 0,
            start_ordinal INTEGER,
            end_ordinal INTEGER,
            exact_source_pointer_sha256 TEXT,
            source_span_sha256 TEXT,
            keywords_json TEXT NOT NULL,
            keyword_strengths_json TEXT NOT NULL,
            keyword_apexes_json TEXT NOT NULL DEFAULT '{{}}',
            record_sha256 TEXT,
            PRIMARY KEY(profile_id,rich_revision_id)
        );
        CREATE INDEX IF NOT EXISTS idx_bm129_signpost_order ON {_BM129_SIGNPOST_TABLE}(profile_id,sequence_no,node_type,node_id);
        """)
        cols={str(r[1]) for r in db.execute(f"PRAGMA table_info({_BM129_SIGNPOST_TABLE})").fetchall()}
        if "keyword_apexes_json" not in cols:
            db.execute(f"ALTER TABLE {_BM129_SIGNPOST_TABLE} ADD COLUMN keyword_apexes_json TEXT NOT NULL DEFAULT '{{}}'")
        db.commit()


def _bm129_rowdict(row) -> dict:
    if row is None: return {}
    try: return dict(row)
    except Exception: return {}


def _bm129_book_rows(module, book_id: str, *, include_text: bool) -> dict:
    books=getattr(module,"neatbooks",None); bid=str(book_id or "").strip()
    if books is None or not callable(getattr(books,"connect",None)) or not bid:
        return {"ok":False,"book_id":bid,"error":"NeatBooks source is unavailable."}
    try:
        with books.connect() as db:
            bcols={str(r[1]) for r in db.execute("PRAGMA table_info(books)").fetchall()}
            ccols={str(r[1]) for r in db.execute("PRAGMA table_info(book_chunks)").fetchall()}
            brow=_bm129_rowdict(db.execute("SELECT * FROM books WHERE book_id=?",(bid,)).fetchone()) if "book_id" in bcols else {}
            if not {"book_id","chunk_id","ordinal"}.issubset(ccols):
                return {"ok":False,"book_id":bid,"error":"Canonical book_chunks schema is incomplete."}
            text_expr=("COALESCE(NULLIF(original_text,''),text,'')" if {"original_text","text"}.issubset(ccols) else
                       "COALESCE(original_text,'')" if "original_text" in ccols else "COALESCE(text,'')" if "text" in ccols else "''")
            hash_expr=("COALESCE(NULLIF(original_text_hash,''),NULLIF(text_sha256,''),'')" if {"original_text_hash","text_sha256"}.issubset(ccols) else
                       "COALESCE(original_text_hash,'')" if "original_text_hash" in ccols else "COALESCE(text_sha256,'')" if "text_sha256" in ccols else "''")
            chapter_expr="COALESCE(chapter,'')" if "chapter" in ccols else "''"
            content_sha=str(brow.get("content_sha256") or brow.get("source_sha256") or "")
            has_hash_columns=bool({"original_text_hash","text_sha256"}.intersection(ccols))
            fingerprint_needs_text=bool(include_text or (not has_hash_columns and not content_sha))
            select=f"SELECT chunk_id,ordinal,{chapter_expr} AS chapter,{hash_expr} AS source_hash"
            if fingerprint_needs_text: select+=f",{text_expr} AS source_text"
            rows=[_bm129_rowdict(r) for r in db.execute(select+" FROM book_chunks WHERE book_id=? ORDER BY ordinal,chunk_id",(bid,)).fetchall()]
    except Exception as exc:
        return {"ok":False,"book_id":bid,"error":str(exc)[:400]}
    pieces=[]
    for r in rows:
        h=str(r.get("source_hash") or "")
        if not h and "source_text" in r: h=hashlib.sha256(str(r.get("source_text") or "").encode("utf-8")).hexdigest()
        pieces.append([int(r.get("ordinal") or 0),str(r.get("chunk_id") or ""),h])
    content_sha=str(brow.get("content_sha256") or brow.get("source_sha256") or "")
    fingerprint=hashlib.sha256(_bm129_json({"book_id":bid,"content_sha256":content_sha,"chunks":pieces}).encode("utf-8")).hexdigest()
    return {"ok":bool(rows),"book_id":bid,"book":brow,"chunks":rows,"source_fingerprint_sha256":fingerprint,"source_sha256":content_sha or fingerprint}


def _bm129_identity(book: dict, book_id: str) -> dict:
    meta={}
    raw=book.get("metadata_json")
    if raw:
        try:
            parsed=json.loads(raw) if isinstance(raw,str) else raw
            if isinstance(parsed,dict): meta=parsed
        except Exception: meta={}
    keys=("title","authors_json","author","translator","editor","publisher","publication_date","language","edition","source_type","status","access_status","epub_reading_order","gutenberg_wrapper_cleanup")
    out={"book_id":book_id}
    for key in keys:
        value=book.get(key)
        if value not in (None,"",[],{}): out[key]=value
    # Reuse explicit captured bibliographic metadata without promoting arbitrary
    # source text into identity fields.
    for key in ("title","author","authors","translator","editor","publisher","publication_date","language","edition"):
        if key not in out and meta.get(key) not in (None,"",[],{}): out[key]=meta.get(key)
    return out


def _bm129_structure(module, book_id: str, chunks: list[dict]) -> list[dict]:
    out=[]
    # Stored chapter labels are exact ingestion metadata. Consecutive identical
    # labels are merged mechanically; Python does not decide literary structure.
    current=None
    for row in chunks:
        label=" ".join(str(row.get("chapter") or "").split())
        ordinal=int(row.get("ordinal") or 0)
        if not label: continue
        if current and current["label"]==label and ordinal==int(current["end_ordinal"])+1:
            current["end_ordinal"]=ordinal
        else:
            current={"entry_type":"stored_chapter_label","label":label,"start_ordinal":ordinal,"end_ordinal":ordinal,"origin":"book_chunks.chapter","status":"SOURCE_METADATA"}; out.append(current)
    try:
        with _bni_connect(module) as db:
            rows=db.execute("SELECT entry_id,entry_type,label,start_ordinal,end_ordinal,origin,status,source_text_sha256 FROM book_navigation_entries WHERE book_id=? AND active=1 AND origin='python_auto' ORDER BY start_ordinal,line_start,created_at LIMIT 1000",(book_id,)).fetchall()
        for row in rows:
            item=_bm129_rowdict(row); item["end_ordinal"]=int(item.get("end_ordinal") or item.get("start_ordinal") or 0); out.append(item)
    except Exception: pass
    seen=set(); clean=[]
    for item in sorted(out,key=lambda x:(int(x.get("start_ordinal") or 0),str(x.get("entry_type") or ""),str(x.get("label") or "").casefold())):
        key=(str(item.get("entry_type") or ""),str(item.get("label") or "").casefold(),int(item.get("start_ordinal") or 0),int(item.get("end_ordinal") or 0))
        if key in seen: continue
        seen.add(key); clean.append(item)
    return clean


def _bm129_compile_terms(chunks: list[dict]) -> tuple[dict, int]:
    stats={}; total_tokens=0; n=max(1,len(chunks))
    for row in chunks:
        ordinal=int(row.get("ordinal") or 0); tokens=_hd80_all_word_tokens(str(row.get("source_text") or "")); total_tokens+=len(tokens)
        local={}
        for token in tokens: local[token]=int(local.get(token,0))+1
        for token,count in local.items():
            s=stats.setdefault(token,{"occurrence_count":0,"chunk_hits":0,"first_ordinal":ordinal,"last_ordinal":ordinal,"locations":[]})
            s["occurrence_count"]+=int(count); s["chunk_hits"]+=1; s["last_ordinal"]=ordinal
            if len(s["locations"])<_BM129_MAX_LOCATIONS_PER_TERM: s["locations"].append(ordinal)
    for token,s in stats.items():
        count=int(s["occurrence_count"]); hits=int(s["chunk_hits"])
        s["total_tokens"]=total_tokens
        s["density"]=round(float(count)/max(1,total_tokens),8)
        s["distribution"]=round(float(hits)/max(1,len(chunks)),6)
        if len(chunks)>1:
            num=math.log((len(chunks)+1.0)/(hits+1.0)); den=max(1e-9,math.log(len(chunks)+1.0)); distinct=max(0.0,min(1.0,num/den))
        else: distinct=0.5
        s["chunk_distinctiveness"]=round(distinct,6)
        s["lexical_strength"]=_kw122_strength(count=count,total_tokens=total_tokens,local_chunk_hits=hits,local_chunks=len(chunks),corpus_df=hits,corpus_chunks=len(chunks))
    return stats,total_tokens


def _bm129_regions(chunks: list[dict], global_terms: dict) -> list[dict]:
    regions=[]
    for offset in range(0,len(chunks),_BM129_REGION_CHUNKS):
        group=chunks[offset:offset+_BM129_REGION_CHUNKS]
        if not group: continue
        local={}; token_count=0; source_manifest=[]
        for row in group:
            toks=_hd80_all_word_tokens(str(row.get("source_text") or "")); token_count+=len(toks)
            for t in toks: local[t]=int(local.get(t,0))+1
            source_manifest.append([int(row.get("ordinal") or 0),str(row.get("chunk_id") or ""),str(row.get("source_hash") or "")])
        freq=sorted(((t,c) for t,c in local.items() if len(t)>=2),key=lambda x:(-x[1],x[0]))[:20]
        conc=[]
        for t,c in local.items():
            if len(t)<3: continue
            gc=max(1,int((global_terms.get(t) or {}).get("occurrence_count") or c))
            concentration=float(c)/gc
            local_density=float(c)/max(1,token_count)
            score=concentration*0.7+min(1.0,local_density*100.0)*0.3
            conc.append((score,t,c,round(concentration,6)))
        conc.sort(key=lambda x:(-x[0],-x[2],x[1])); concentrated=[{"term":t,"count":c,"share_of_book_occurrences":share} for _,t,c,share in conc[:20]]
        start=int(group[0].get("ordinal") or 0); end=int(group[-1].get("ordinal") or 0)
        regions.append({"region_id":f"SRCWIN-{start:06d}-{end:06d}","region_kind":"fixed_source_window","label":f"source chunks {start}-{end}","start_ordinal":start,"end_ordinal":end,"chunk_count":len(group),"token_count":token_count,"source_range_sha256":hashlib.sha256(_bm129_json(source_manifest).encode("utf-8")).hexdigest(),"top_frequency":[{"term":t,"count":c} for t,c in freq],"concentrated_terms":concentrated,"provenance":{"window_chunks":_BM129_REGION_CHUNKS,"mechanical_window":True,"semantic_boundary":False}})
    return regions


def _bm129_signposts(module, book_id: str) -> list[dict]:
    _bm129_ensure_schema(); out=[]
    try:
        with _sk_connect() as db:
            rows=db.execute(f"""SELECT h.node_id,h.node_type,h.current_revision_id,h.current_record_sha256,
                r.keywords_json,r.exact_source_pointer_json,r.exact_source_pointer_sha256,
                k.strengths_json,k.source_span_sha256,k.apexes_json
                FROM {_HD76_HEADS_TABLE} h JOIN {_HD76_REVISIONS_TABLE} r ON r.rich_revision_id=h.current_revision_id
                LEFT JOIN {_KW122_TABLE} k ON k.rich_revision_id=h.current_revision_id
                WHERE h.book_id=?""",(book_id,)).fetchall()
    except Exception: rows=[]
    for row in rows:
        d=_bm129_rowdict(row); pointer=_hd76_json(d.get("exact_source_pointer_json"),{}) or {}
        base=None
        try: base=_sp_get(str(pointer.get("version_id") or ""),str(d.get("node_type") or ""),str(d.get("node_id") or ""))
        except Exception: base=None
        keywords=list(_hd76_json(d.get("keywords_json"),[]) or []); strengths=dict(_hd76_json(d.get("strengths_json"),{}) or {}); apexes=dict(_hd76_json(d.get("apexes_json"),{}) or {})
        if keywords and (not apexes or any(k not in apexes for k in keywords if k in strengths)):
            current=_kw122_revision_row(str(d.get("current_revision_id") or "")); measured=_kw122_measure_rich_revision(module,current) if current else {}
            strengths=dict(measured.get("keyword_strengths") or strengths); apexes=dict(measured.get("keyword_apexes") or apexes)
        out.append({"rich_revision_id":str(d.get("current_revision_id") or ""),"node_id":str(d.get("node_id") or ""),"node_type":str(d.get("node_type") or ""),"sequence_no":int((base or {}).get("sequence_no") or 0),"start_ordinal":_shn_int_or_none(pointer.get("start_ordinal")),"end_ordinal":_shn_int_or_none(pointer.get("end_ordinal")),"exact_source_pointer_sha256":str(d.get("exact_source_pointer_sha256") or ""),"source_span_sha256":str(d.get("source_span_sha256") or ""),"keywords":keywords,"keyword_strengths":strengths,"keyword_apexes":apexes,"record_sha256":str(d.get("current_record_sha256") or "")})
    out.sort(key=lambda x:(0 if x["sequence_no"]>0 else 1,x["sequence_no"] if x["sequence_no"]>0 else 2**31,x["node_type"],x["node_id"]))
    return out


def _bm129_compile_profile(module, snap: dict) -> dict:
    bid=str(snap.get("book_id") or ""); chunks=list(snap.get("chunks") or [])
    terms,total_tokens=_bm129_compile_terms(chunks); structure=_bm129_structure(module,bid,chunks); regions=_bm129_regions(chunks,terms); signposts=_bm129_signposts(module,bid)
    ords=[int(x.get("ordinal") or 0) for x in chunks]; expected=list(range(min(ords),max(ords)+1)) if ords else []
    coverage={"chunk_count":len(chunks),"first_ordinal":min(ords) if ords else None,"last_ordinal":max(ords) if ords else None,"missing_ordinals":[x for x in expected if x not in set(ords)],"total_exact_tokens":total_tokens,"total_exact_characters":sum(len(str(x.get("source_text") or "")) for x in chunks),"complete_ordinal_coverage":bool(ords) and not any(x for x in expected if x not in set(ords)),"source_text_stored_in_metadata":False}
    identity=_bm129_identity(dict(snap.get("book") or {}),bid)
    summary={"stored_exact_terms":len(terms),"structural_entries":len(structure),"fixed_source_regions":len(regions),"current_rich_signposts":len(signposts),"cross_book_exact_term_comparison_ready":True,"semantic_similarity_score_present":False,"model_calls":0,"web_calls":0,"python_semantic_judgment":False}
    core={"book_id":bid,"source_fingerprint_sha256":snap.get("source_fingerprint_sha256"),"source_sha256":snap.get("source_sha256"),"schema_version":_BM129_VERSION,"normalization_version":_BM129_NORMALIZATION_VERSION,"identity":identity,"structure":structure,"coverage":coverage,"summary":summary}
    core["metadata_sha256"]=hashlib.sha256(_bm129_json(core).encode("utf-8")).hexdigest()
    core["profile_id"]="BMP-"+hashlib.sha256((bid+"|"+str(snap.get("source_fingerprint_sha256") or "")+"|"+_BM129_VERSION).encode("utf-8")).hexdigest()[:24]
    core["terms"]=terms; core["regions"]=regions; core["signposts"]=signposts
    return core


def _bm129_store_profile(profile: dict) -> dict:
    _bm129_ensure_schema(); pid=str(profile.get("profile_id") or ""); bid=str(profile.get("book_id") or ""); now=_sk_now()
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            db.execute(f"DELETE FROM {_BM129_TERM_TABLE} WHERE profile_id=?",(pid,)); db.execute(f"DELETE FROM {_BM129_REGION_TABLE} WHERE profile_id=?",(pid,)); db.execute(f"DELETE FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=?",(pid,))
            db.execute(f"""INSERT OR REPLACE INTO {_BM129_PROFILE_TABLE}(profile_id,book_id,source_fingerprint_sha256,source_sha256,schema_version,normalization_version,identity_json,structure_json,coverage_json,summary_json,metadata_sha256,generated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",(pid,bid,str(profile.get("source_fingerprint_sha256") or ""),str(profile.get("source_sha256") or ""),_BM129_VERSION,_BM129_NORMALIZATION_VERSION,_bm129_json(profile.get("identity") or {}),_bm129_json(profile.get("structure") or []),_bm129_json(profile.get("coverage") or {}),_bm129_json(profile.get("summary") or {}),str(profile.get("metadata_sha256") or ""),now))
            for term,s in dict(profile.get("terms") or {}).items():
                db.execute(f"INSERT INTO {_BM129_TERM_TABLE} VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(pid,str(term),int(s.get("occurrence_count") or 0),int(s.get("chunk_hits") or 0),int(s.get("total_tokens") or 0),float(s.get("density") or 0.0),float(s.get("distribution") or 0.0),float(s.get("chunk_distinctiveness") or 0.0),float(s.get("lexical_strength") or 0.0),s.get("first_ordinal"),s.get("last_ordinal"),_bm129_json(s.get("locations") or [])))
            for r in list(profile.get("regions") or []):
                db.execute(f"INSERT INTO {_BM129_REGION_TABLE} VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(pid,str(r.get("region_id") or ""),str(r.get("region_kind") or ""),str(r.get("label") or ""),int(r.get("start_ordinal") or 0),int(r.get("end_ordinal") or 0),int(r.get("chunk_count") or 0),int(r.get("token_count") or 0),str(r.get("source_range_sha256") or ""),_bm129_json(r.get("top_frequency") or []),_bm129_json(r.get("concentrated_terms") or []),_bm129_json(r.get("provenance") or {})))
            for s in list(profile.get("signposts") or []):
                db.execute(f"INSERT INTO {_BM129_SIGNPOST_TABLE}(profile_id,rich_revision_id,node_id,node_type,sequence_no,start_ordinal,end_ordinal,exact_source_pointer_sha256,source_span_sha256,keywords_json,keyword_strengths_json,keyword_apexes_json,record_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",(pid,str(s.get("rich_revision_id") or ""),str(s.get("node_id") or ""),str(s.get("node_type") or ""),int(s.get("sequence_no") or 0),s.get("start_ordinal"),s.get("end_ordinal"),str(s.get("exact_source_pointer_sha256") or ""),str(s.get("source_span_sha256") or ""),_bm129_json(s.get("keywords") or []),_bm129_json(s.get("keyword_strengths") or {}),_bm129_json(s.get("keyword_apexes") or {}),str(s.get("record_sha256") or "")))
            db.execute(f"INSERT OR REPLACE INTO {_BM129_HEAD_TABLE}(book_id,profile_id,source_fingerprint_sha256,metadata_sha256,updated_at) VALUES(?,?,?,?,?)",(bid,pid,str(profile.get("source_fingerprint_sha256") or ""),str(profile.get("metadata_sha256") or ""),now)); db.commit()
        except Exception:
            db.rollback(); raise
    return {"ok":True,"profile_id":pid,"book_id":bid,"metadata_sha256":profile.get("metadata_sha256"),"stored":True}


def _bm129_load_profile(profile_id: str, *, include_terms: bool=False, include_regions: bool=False, include_signposts: bool=False) -> dict:
    _bm129_ensure_schema(); pid=str(profile_id or "")
    with _sk_connect() as db:
        row=db.execute(f"SELECT * FROM {_BM129_PROFILE_TABLE} WHERE profile_id=?",(pid,)).fetchone()
        if not row: return {"ok":False,"error":"Book mechanical metadata profile not found.","profile_id":pid}
        d=_bm129_rowdict(row)
        out={"ok":True,"profile_id":pid,"book_id":d.get("book_id"),"source_fingerprint_sha256":d.get("source_fingerprint_sha256"),"source_sha256":d.get("source_sha256"),"schema_version":d.get("schema_version"),"normalization_version":d.get("normalization_version"),"identity":_hd76_json(d.get("identity_json"),{}),"structure":_hd76_json(d.get("structure_json"),[]),"coverage":_hd76_json(d.get("coverage_json"),{}),"summary":_hd76_json(d.get("summary_json"),{}),"metadata_sha256":d.get("metadata_sha256"),"generated_at":d.get("generated_at"),"authority":"mechanical reusable navigation metadata; exact source remains authority","python_semantic_judgment":False}
        if include_terms:
            rows=db.execute(f"SELECT * FROM {_BM129_TERM_TABLE} WHERE profile_id=? ORDER BY lexical_strength DESC,occurrence_count DESC,term",(pid,)).fetchall(); out["terms"]=[{**_bm129_rowdict(r),"locations":_hd76_json(_bm129_rowdict(r).get("locations_json"),[])} for r in rows]
        if include_regions:
            rows=db.execute(f"SELECT * FROM {_BM129_REGION_TABLE} WHERE profile_id=? ORDER BY start_ordinal,end_ordinal",(pid,)).fetchall(); out["regions"]=[{**_bm129_rowdict(r),"top_frequency":_hd76_json(_bm129_rowdict(r).get("top_frequency_json"),[]),"concentrated_terms":_hd76_json(_bm129_rowdict(r).get("concentrated_terms_json"),[]),"provenance":_hd76_json(_bm129_rowdict(r).get("provenance_json"),{})} for r in rows]
        if include_signposts:
            rows=db.execute(f"SELECT * FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=? ORDER BY CASE WHEN sequence_no>0 THEN 0 ELSE 1 END,sequence_no,node_type,node_id",(pid,)).fetchall(); out["signposts"]=[{**_bm129_rowdict(r),"keywords":_hd76_json(_bm129_rowdict(r).get("keywords_json"),[]),"keyword_strengths":_hd76_json(_bm129_rowdict(r).get("keyword_strengths_json"),{}),"keyword_apexes":_hd76_json(_bm129_rowdict(r).get("keyword_apexes_json"),{})} for r in rows]
    return out



def _bm129_refresh_signpost_overlay(module, profile_id: str, book_id: str) -> dict:
    """Refresh mutable derived-signpost inventory without rescanning canonical book text."""
    pid=str(profile_id or ""); bid=str(book_id or ""); signs=_bm129_signposts(module,bid); manifest=[]
    _bm129_ensure_schema()
    with _sk_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            db.execute(f"DELETE FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=?",(pid,))
            for s in signs:
                db.execute(f"INSERT INTO {_BM129_SIGNPOST_TABLE}(profile_id,rich_revision_id,node_id,node_type,sequence_no,start_ordinal,end_ordinal,exact_source_pointer_sha256,source_span_sha256,keywords_json,keyword_strengths_json,keyword_apexes_json,record_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",(pid,str(s.get("rich_revision_id") or ""),str(s.get("node_id") or ""),str(s.get("node_type") or ""),int(s.get("sequence_no") or 0),s.get("start_ordinal"),s.get("end_ordinal"),str(s.get("exact_source_pointer_sha256") or ""),str(s.get("source_span_sha256") or ""),_bm129_json(s.get("keywords") or []),_bm129_json(s.get("keyword_strengths") or {}),_bm129_json(s.get("keyword_apexes") or {}),str(s.get("record_sha256") or "")))
                manifest.append([s.get("rich_revision_id"),s.get("record_sha256"),s.get("source_span_sha256")])
            row=db.execute(f"SELECT summary_json FROM {_BM129_PROFILE_TABLE} WHERE profile_id=?",(pid,)).fetchone()
            summary=_hd76_json(row[0],{}) if row else {}
            summary=dict(summary or {}); summary["current_rich_signposts"]=len(signs); summary["signpost_inventory_sha256"]=hashlib.sha256(_bm129_json(manifest).encode("utf-8")).hexdigest(); summary["signpost_inventory_refreshed_without_source_rescan"]=True
            db.execute(f"UPDATE {_BM129_PROFILE_TABLE} SET summary_json=? WHERE profile_id=?",(_bm129_json(summary),pid)); db.commit()
        except Exception:
            db.rollback(); raise
    return {"count":len(signs),"signpost_inventory_sha256":summary.get("signpost_inventory_sha256")}

def _bm129_get_or_build(module, book_id: str, *, force: bool=False) -> dict:
    bid=str(book_id or "").strip(); probe=_bm129_book_rows(module,bid,include_text=False)
    if not probe.get("ok"): return probe
    _bm129_ensure_schema(); fingerprint=str(probe.get("source_fingerprint_sha256") or "")
    with _sk_connect() as db:
        head=db.execute(f"SELECT * FROM {_BM129_HEAD_TABLE} WHERE book_id=?",(bid,)).fetchone()
    if head and not force and str(head["source_fingerprint_sha256"] or "")==fingerprint:
        pid=str(head["profile_id"] or ""); overlay=_bm129_refresh_signpost_overlay(module,pid,bid); loaded=_bm129_load_profile(pid); loaded["cache_reused"]=True; loaded["source_rescan_performed"]=False; loaded["derived_signpost_overlay_refreshed"]=True; loaded["signpost_inventory_sha256"]=overlay.get("signpost_inventory_sha256"); return loaded
    snap=_bm129_book_rows(module,bid,include_text=True)
    if not snap.get("ok"): return snap
    profile=_bm129_compile_profile(module,snap); _bm129_store_profile(profile)
    loaded=_bm129_load_profile(str(profile.get("profile_id") or "")); loaded["cache_reused"]=False; loaded["source_rescan_performed"]=True; return loaded


def _bm129_card(profile: dict) -> dict:
    if not isinstance(profile,dict) or not profile.get("ok"): return {"available":False,"error":str((profile or {}).get("error") or "metadata unavailable")[:300]}
    pid=str(profile.get("profile_id") or ""); _bm129_ensure_schema()
    with _sk_connect() as db:
        # Prefer vocabulary already selected by the rich-signpost navigation layer;
        # this projection does not ask Python to invent a semantic keyword set.
        sp=db.execute(f"SELECT keywords_json FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=?",(pid,)).fetchall()
        nav_words=[]; seen=set()
        for row in sp:
            for raw in list(_hd76_json(row[0],[]) or []):
                terms=_hd80_all_word_tokens(str(raw or ""))
                if len(terms)==1 and terms[0] not in seen: seen.add(terms[0]); nav_words.append(terms[0])
        terms=[]
        if nav_words:
            q=",".join("?" for _ in nav_words[:500]); rows=db.execute(f"SELECT term,occurrence_count,chunk_hits,density,distribution,chunk_distinctiveness,lexical_strength,first_ordinal,last_ordinal FROM {_BM129_TERM_TABLE} WHERE profile_id=? AND term IN ({q}) ORDER BY lexical_strength DESC,occurrence_count DESC,term LIMIT ?",tuple([pid]+nav_words[:500]+[_BM129_CARD_TERMS])).fetchall()
        else:
            rows=db.execute(f"SELECT term,occurrence_count,chunk_hits,density,distribution,chunk_distinctiveness,lexical_strength,first_ordinal,last_ordinal FROM {_BM129_TERM_TABLE} WHERE profile_id=? AND LENGTH(term)>=4 ORDER BY lexical_strength DESC,occurrence_count DESC,term LIMIT ?",(pid,_BM129_CARD_TERMS)).fetchall()
        terms=[_bm129_rowdict(r) for r in rows]
        regions=[{**_bm129_rowdict(r),"concentrated_terms":_hd76_json(_bm129_rowdict(r).get("concentrated_terms_json"),[])[:6]} for r in db.execute(f"SELECT region_id,label,start_ordinal,end_ordinal,token_count,concentrated_terms_json FROM {_BM129_REGION_TABLE} WHERE profile_id=? ORDER BY start_ordinal LIMIT ?",(pid,_BM129_CARD_REGIONS)).fetchall()]
        signpost_count=int(db.execute(f"SELECT COUNT(*) FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=?",(pid,)).fetchone()[0])
        signs=[]
        for r in db.execute(f"SELECT rich_revision_id,node_id,node_type,sequence_no,start_ordinal,end_ordinal,keywords_json,keyword_strengths_json FROM {_BM129_SIGNPOST_TABLE} WHERE profile_id=? ORDER BY CASE WHEN sequence_no>0 THEN 0 ELSE 1 END,sequence_no,node_type,node_id LIMIT ?",(pid,_BM129_CARD_SIGNPOSTS)).fetchall():
            d=_bm129_rowdict(r); d["keywords"]=list(_hd76_json(d.pop("keywords_json",None),[]) or [])[:8]; strengths=dict(_hd76_json(d.pop("keyword_strengths_json",None),{}) or {}); d["keyword_strengths"]={k:strengths[k] for k in d["keywords"] if k in strengths}; signs.append(d)
    structure=list(profile.get("structure") or [])
    return {"available":True,"projection_version":_BM129_VERSION,"profile_id":pid,"metadata_sha256":profile.get("metadata_sha256"),"source_sha256":profile.get("source_sha256"),"identity":profile.get("identity") or {},"structure":{"stored_entries":len(structure),"shown":structure[:_BM129_CARD_STRUCTURES]},"lexical_profile":{"stored_exact_terms":int((profile.get("summary") or {}).get("stored_exact_terms") or 0),"shown_terms":terms,"term_selection_basis":"current rich-signpost exact vocabulary when available; otherwise mechanical exact-token fallback"},"regional_fingerprints":{"stored":int((profile.get("summary") or {}).get("fixed_source_regions") or 0),"shown":regions},"signpost_map":{"stored":signpost_count,"shown":signs},"evidence_status":profile.get("coverage") or {},"hidden_reusable_metadata":{"full_term_table":True,"full_region_table":True,"full_signpost_inventory":True,"structure_table_in_profile":True,"cross_book_exact_term_comparison_ready":True,"injected_by_default":False},"navigation_only":True,"semantic_similarity_score_present":False,"python_semantic_judgment":False,"exact_source_remains_authority":True}


def _bm129_metadata_view(module, book_id: str, *, detail: str="full", force: bool=False) -> dict:
    profile=_bm129_get_or_build(module,book_id,force=force)
    mode=str(detail or "full").strip().casefold()
    if mode in {"card","compact","projection"}: return _bm129_card(profile)
    if not profile.get("ok"): return profile
    return _bm129_load_profile(str(profile.get("profile_id") or ""),include_terms=mode in {"full","terms","all"},include_regions=mode in {"full","regions","all"},include_signposts=mode in {"full","signposts","all"})


def _ora_book_overview(module, book_id: str, *, chunk_count: int = 8, entry_limit: int = 120) -> dict:
    out=dict(_BM129_BASE_BOOK_OVERVIEW(module,book_id,chunk_count=chunk_count,entry_limit=entry_limit))
    if not out.get("ok"): return out
    profile=_bm129_get_or_build(module,str(book_id or ""))
    out["mechanical_navigation_card"]=_bm129_card(profile)
    out["reusable_book_metadata"]=_bmp132_projection_receipt(profile)
    return _ora_clean_result(module,out)


def _bm129_self_test() -> dict:
    chunks=[
        {"chunk_id":"C1","ordinal":1,"chapter":"ONE","source_hash":"h1","source_text":"war war chariots command"},
        {"chunk_id":"C2","ordinal":2,"chapter":"ONE","source_hash":"h2","source_text":"war operations chariots"},
        {"chunk_id":"C3","ordinal":3,"chapter":"TWO","source_hash":"h3","source_text":"terrain command operations"},
    ]
    terms,total=_bm129_compile_terms(chunks); regions=_bm129_regions(chunks,terms)
    checks={
        "exact_terms_are_normalized_and_counted":terms.get("war",{}).get("occurrence_count")==3 and terms.get("chariots",{}).get("chunk_hits")==2,
        "strength_components_are_mechanical":0.0<=float(terms.get("war",{}).get("lexical_strength") or -1)<=1.0 and terms.get("war",{}).get("distribution")>0,
        "regional_fingerprint_is_source_window_not_semantic_boundary":len(regions)==1 and regions[0].get("provenance",{}).get("semantic_boundary") is False,
        "regional_profile_contains_no_source_text":all("source_text" not in _bm129_json(r) for r in regions),
        "normalized_term_rows_support_future_cross_book_overlap":set(["war","chariots","operations"]).issubset(terms),
        "personal_semantic_weights_are_not_part_of_mechanical_term_stats":all("semantic_weight" not in s for s in terms.values()),
    }
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_BM129_VERSION,"model_calls":0,"web_calls":0,"python_semantic_judgment":False}


# ---------------------------------------------------------------------------
# Consolidated comparison mechanics — historical .131 algorithm contract
# ---------------------------------------------------------------------------
# The comparison remains deterministic and bounded: exact normalized term
# intersection/difference, explicit numeric deltas, exact structure-label counts,
# fixed source-window positional pairing, and signpost inventory/token counts. The
# consolidation changes ownership/duplication only, not any comparison ordering or
# semantic boundary.
_BM131_VERSION = "1.0-reusable-book-profile-mechanical-comparison"
_BM131_TOOL = "compare_book_profiles"
_BM131_DEFAULT_TERM_LIMIT = 12
_BM131_DEFAULT_REGION_LIMIT = 6
_BM131_DEFAULT_STRUCTURE_LIMIT = 10
_BM131_DEFAULT_KEYWORD_LIMIT = 12


def _bmp132_profile_receipt(profile: dict) -> dict:
    """Canonical provenance/cache receipt shared by projection and comparison surfaces."""
    p=dict(profile or {}) if isinstance(profile,dict) else {}
    return {
        "book_id":p.get("book_id"),
        "title":str((p.get("identity") or {}).get("title") or ""),
        "profile_id":p.get("profile_id"),
        "metadata_sha256":p.get("metadata_sha256"),
        "source_sha256":p.get("source_sha256"),
        "source_fingerprint_sha256":p.get("source_fingerprint_sha256"),
        "schema_version":p.get("schema_version"),
        "normalization_version":p.get("normalization_version"),
        "generated_at":p.get("generated_at"),
        "cache_reused":p.get("cache_reused"),
        "source_rescan_performed":p.get("source_rescan_performed"),
        "derived_signpost_overlay_refreshed":p.get("derived_signpost_overlay_refreshed"),
        "signpost_inventory_sha256":p.get("signpost_inventory_sha256") or (p.get("summary") or {}).get("signpost_inventory_sha256"),
        "coverage":p.get("coverage") or {},
        "summary":p.get("summary") or {},
    }


def _bmp132_projection_receipt(profile: dict) -> dict:
    """Small book_overview receipt; exact .130-visible shape retained under one owner."""
    p=dict(profile or {}) if isinstance(profile,dict) else {}
    return {
        "version":_BM129_VERSION,
        "profile_id":p.get("profile_id"),
        "metadata_sha256":p.get("metadata_sha256"),
        "cache_reused":p.get("cache_reused"),
        "source_rescan_performed":p.get("source_rescan_performed"),
        "stored_rich_injected_compact":True,
        "full_metadata_injected_by_default":False,
        "source_text_stored_in_metadata":False,
        "semantic_similarity_score_present":False,
        "authority":"mechanical reusable navigation metadata only; exact source remains authority",
    }


def _bmp132_comparability(a_profile: dict, b_profile: dict) -> dict:
    """One authoritative mechanical compatibility receipt for profile comparison."""
    pa=dict(a_profile or {}); pb=dict(b_profile or {})
    same_schema=str(pa.get("schema_version") or "")==str(pb.get("schema_version") or "")
    same_norm=str(pa.get("normalization_version") or "")==str(pb.get("normalization_version") or "")
    complete_a=bool((pa.get("coverage") or {}).get("complete_ordinal_coverage")); complete_b=bool((pb.get("coverage") or {}).get("complete_ordinal_coverage"))
    return {
        "same_profile_schema":same_schema,
        "same_normalization_version":same_norm,
        "a_complete_ordinal_coverage":complete_a,
        "b_complete_ordinal_coverage":complete_b,
        "exact_term_identity_comparable":bool(same_norm),
        "density_distribution_and_distinctiveness_comparable":bool(same_schema and same_norm),
        "lexical_strength_comparable":bool(same_schema and same_norm),
        "lexical_strength_runtime_contract":str(globals().get("_KW122_VERSION") or ""),
        "lexical_formula_version_explicitly_stored_per_bm129_profile":False,
        "lexical_formula_compatibility_basis":"Both profiles share the same BM129 schema + normalization contract; BM129 v1 computes lexical_strength with its fixed KW122-derived implementation. A separate per-profile formula field was not persisted by .129.",
        "coverage_status":"COMPLETE_BOTH" if complete_a and complete_b else "PARTIAL_COVERAGE_PRESENT",
        "semantic_similarity_score_computed":False,
    }


def _bmp132_capsule_book_overview_projection(event: dict) -> dict | None:
    """Profile-owned .130 transport projection: protect only card + tiny receipt."""
    if not isinstance(event,dict) or str(event.get("tool") or "")!="book_overview": return None
    result=event.get("result")
    if not isinstance(result,dict): return None
    card=result.get("mechanical_navigation_card"); receipt=result.get("reusable_book_metadata")
    if not isinstance(card,dict) or card.get("available") is not True: return None
    identity=dict(card.get("identity") or {}) if isinstance(card.get("identity"),dict) else {}
    compact_result={
        "ok":bool(result.get("ok",True)),
        "operation":str(result.get("operation") or "book_overview"),
        "book_id":str(result.get("book_id") or identity.get("book_id") or ""),
        "mechanical_navigation_card":dict(card),
        "reusable_book_metadata":dict(receipt or {}) if isinstance(receipt,dict) else {},
        "capsule_return_projection":{
            "version":"1.0-book-overview-mechanical-card-only",
            "protected_as":"inspection_metadata",
            "ordinary_book_overview_navigation_retained":False,
            "source_text_retained":False,
            "semantic_authority_changed":False,
        },
    }
    projected=dict(event); projected["result"]=compact_result; projected["capsule_inspection_projection"]="book_overview_mechanical_navigation_card"
    return projected


def _bm131_norm_label(value: object) -> str:
    return " ".join(str(value or "").split()).casefold()


def _bm131_resolve_book_ref(module, reference: str) -> dict:
    ref=" ".join(str(reference or "").split())
    if not ref:
        return {"ok":False,"error":"book reference is required","reference":ref}
    books=getattr(module,"neatbooks",None)
    if books is None or not callable(getattr(books,"connect",None)):
        return {"ok":False,"error":"NeatBooks source is unavailable.","reference":ref}
    try:
        with books.connect() as db:
            cols={str(r[1]) for r in db.execute("PRAGMA table_info(books)").fetchall()}
            if "book_id" not in cols:
                return {"ok":False,"error":"NeatBooks books table lacks book_id.","reference":ref}
            title_expr="COALESCE(title,'')" if "title" in cols else "''"
            exact=db.execute(f"SELECT book_id,{title_expr} AS title FROM books WHERE book_id=?",(ref,)).fetchall()
            if exact:
                row=_bm129_rowdict(exact[0]); return {"ok":True,"book_id":str(row.get("book_id") or ref),"title":str(row.get("title") or ""),"resolved_by":"exact_book_id"}
            rows=[_bm129_rowdict(r) for r in db.execute(f"SELECT book_id,{title_expr} AS title FROM books ORDER BY book_id").fetchall()]
    except Exception as exc:
        return {"ok":False,"error":f"{type(exc).__name__}: {exc}","reference":ref}
    folded=ref.casefold(); matches=[r for r in rows if " ".join(str(r.get("title") or "").split()).casefold()==folded]
    if len(matches)==1:
        row=matches[0]; return {"ok":True,"book_id":str(row.get("book_id") or ""),"title":str(row.get("title") or ""),"resolved_by":"exact_title"}
    if len(matches)>1:
        return {"ok":False,"error":"Exact title is ambiguous; use a BK-ID.","reference":ref,"candidates":[{"book_id":r.get("book_id"),"title":r.get("title")} for r in matches[:12]]}
    return {"ok":False,"error":"No exact BK-ID or exact title matched.","reference":ref}


def _bm131_term_map(profile_id: str) -> dict[str,dict]:
    _bm129_ensure_schema(); pid=str(profile_id or "")
    with _sk_connect() as db:
        rows=db.execute(f"SELECT term,occurrence_count,chunk_hits,total_tokens,density,distribution,chunk_distinctiveness,lexical_strength,first_ordinal,last_ordinal FROM {_BM129_TERM_TABLE} WHERE profile_id=?",(pid,)).fetchall()
    return {str(d.get("term") or ""):d for d in (_bm129_rowdict(r) for r in rows) if str(d.get("term") or "")}


def _bm131_term_side(term: str, row: dict) -> dict:
    return {"term":term,"occurrence_count":int(row.get("occurrence_count") or 0),"chunk_hits":int(row.get("chunk_hits") or 0),"density":round(float(row.get("density") or 0.0),8),"distribution":round(float(row.get("distribution") or 0.0),6),"chunk_distinctiveness":round(float(row.get("chunk_distinctiveness") or 0.0),6),"lexical_strength":round(float(row.get("lexical_strength") or 0.0),6),"first_ordinal":row.get("first_ordinal"),"last_ordinal":row.get("last_ordinal")}


def _bm131_term_pair(term: str, a: dict, b: dict) -> dict:
    sa=float(a.get("lexical_strength") or 0.0); sb=float(b.get("lexical_strength") or 0.0)
    da=float(a.get("density") or 0.0); db=float(b.get("density") or 0.0)
    xa=float(a.get("chunk_distinctiveness") or 0.0); xb=float(b.get("chunk_distinctiveness") or 0.0)
    return {"term":term,"a":_bm131_term_side(term,a),"b":_bm131_term_side(term,b),"joint_min_lexical_strength":round(min(sa,sb),6),"absolute_density_delta":round(abs(da-db),8),"absolute_lexical_strength_delta":round(abs(sa-sb),6),"absolute_distinctiveness_delta":round(abs(xa-xb),6)}


def _bm131_compare_terms(a_terms: dict, b_terms: dict, limit: int) -> dict:
    lim=max(1,min(40,int(limit or _BM131_DEFAULT_TERM_LIMIT)))
    ak=set(a_terms); bk=set(b_terms); shared=ak&bk; a_only=ak-bk; b_only=bk-ak
    joint=sorted(shared,key=lambda t:(-min(float(a_terms[t].get("lexical_strength") or 0.0),float(b_terms[t].get("lexical_strength") or 0.0)),-(float(a_terms[t].get("lexical_strength") or 0.0)+float(b_terms[t].get("lexical_strength") or 0.0)),t))
    density=sorted(shared,key=lambda t:(-abs(float(a_terms[t].get("density") or 0.0)-float(b_terms[t].get("density") or 0.0)),t))
    strength=sorted(shared,key=lambda t:(-abs(float(a_terms[t].get("lexical_strength") or 0.0)-float(b_terms[t].get("lexical_strength") or 0.0)),t))
    distinct=sorted(shared,key=lambda t:(-abs(float(a_terms[t].get("chunk_distinctiveness") or 0.0)-float(b_terms[t].get("chunk_distinctiveness") or 0.0)),t))
    ao=sorted(a_only,key=lambda t:(-float(a_terms[t].get("lexical_strength") or 0.0),-int(a_terms[t].get("occurrence_count") or 0),t))
    bo=sorted(b_only,key=lambda t:(-float(b_terms[t].get("lexical_strength") or 0.0),-int(b_terms[t].get("occurrence_count") or 0),t))
    return {
        "exact_intersection_count":len(shared),"a_only_count":len(a_only),"b_only_count":len(b_only),
        "shared_high_joint_lexical_strength":{"ordering":"descending min(A strength,B strength), then combined strength, then exact term","shown":[_bm131_term_pair(t,a_terms[t],b_terms[t]) for t in joint[:lim]]},
        "largest_shared_density_deltas":{"ordering":"descending absolute normalized density delta, then exact term","shown":[_bm131_term_pair(t,a_terms[t],b_terms[t]) for t in density[:lim]]},
        "largest_shared_lexical_strength_deltas":{"ordering":"descending absolute lexical-strength delta, then exact term","shown":[_bm131_term_pair(t,a_terms[t],b_terms[t]) for t in strength[:lim]]},
        "largest_shared_distinctiveness_deltas":{"ordering":"descending absolute chunk-distinctiveness delta, then exact term","shown":[_bm131_term_pair(t,a_terms[t],b_terms[t]) for t in distinct[:lim]]},
        "a_only_high_lexical_strength":{"ordering":"A lexical strength, then A occurrence count, then exact term","shown":[_bm131_term_side(t,a_terms[t]) for t in ao[:lim]]},
        "b_only_high_lexical_strength":{"ordering":"B lexical strength, then B occurrence count, then exact term","shown":[_bm131_term_side(t,b_terms[t]) for t in bo[:lim]]},
        "bounded_projection":True,"shown_limit_per_ordering":lim,
    }


def _bm131_structure_compare(a: list, b: list, limit: int) -> dict:
    lim=max(1,min(30,int(limit or _BM131_DEFAULT_STRUCTURE_LIMIT)))
    def prep(rows):
        types={}; labels={}
        for raw in list(rows or []):
            item=dict(raw or {}); typ=str(item.get("entry_type") or "unknown"); types[typ]=types.get(typ,0)+1
            key=_bm131_norm_label(item.get("label"));
            if key and key not in labels: labels[key]=str(item.get("label") or "")
        return types,labels
    at,al=prep(a); bt,bl=prep(b); shared=set(al)&set(bl); ao=set(al)-set(bl); bo=set(bl)-set(al)
    return {"a_entry_count":len(a or []),"b_entry_count":len(b or []),"a_entry_types":dict(sorted(at.items())),"b_entry_types":dict(sorted(bt.items())),"exact_normalized_label_intersection_count":len(shared),"shared_labels_shown":[{"normalized_label":k,"a_label":al[k],"b_label":bl[k]} for k in sorted(shared)[:lim]],"a_only_label_count":len(ao),"b_only_label_count":len(bo),"a_only_labels_shown":[al[k] for k in sorted(ao)[:lim]],"b_only_labels_shown":[bl[k] for k in sorted(bo)[:lim]],"label_normalization":"Unicode casefold + whitespace collapse only; no stemming, synonyms, or semantic alignment","bounded_projection":True}


