def provider_payload_preflight_self_test(module=None) -> dict:
    events=[]
    class FakeModule:
        CHAT_OUTPUT_RESERVE_TOKENS=16384
        _ADAPTIVE_LAST_DECISION={
            "selected":"low",
            "reserved_output_tokens":16384,
            "model_context_limit_tokens":128000,
            "safety_margin_tokens":12800,
            "levels":{"low":{"estimated_complete_prompt_tokens":32000}},
        }
        _ONLINE_TPM_LEARNED_LIMIT_TOKENS=200000
        @staticmethod
        def _adaptive_estimate_tokens(text): return max(1,(len(str(text))+3)//4) if text else 0
        @staticmethod
        def append_diagnostic_log(event_type,summary,**kwargs): events.append({"event_type":event_type,**kwargs}); return {"ok":True}
    class FakeResponses:
        def __init__(self): self.requests=[]
        def create(self,**kwargs): self.requests.append(dict(kwargs)); return type("R",(),{"output":[],"output_text":"ok","usage":None})()
    backend=type("B",(),{})(); backend.model_id="fake-online"; backend.client=type("C",(),{})(); backend.client.responses=FakeResponses()
    fake=FakeModule()
    request={"model":"fake-online","instructions":"x"*12000,"input":[{"role":"user","content":"y"*16000}],"tools":[{"type":"function","name":"probe","description":"z"*4000,"parameters":{"type":"object","properties":{},"additionalProperties":False}}],"store":False}
    preview_req,preview=_ora_request_preflight(fake,backend,request,preview_only=True)
    response=_ora_responses_create_with_tpm_recovery(fake,backend,**request)
    sent=backend.client.responses.requests[0]
    pre=dict(getattr(fake,"_ONLINE_PROVIDER_PREFLIGHT_LAST",{}) or {})

    blocked_backend=type("B",(),{})(); blocked_backend.model_id="fake-online"; blocked_backend.client=type("C",(),{})(); blocked_backend.client.responses=FakeResponses()
    blocked=False
    try:
        _ora_responses_create_with_tpm_recovery(fake,blocked_backend,model="fake-online",instructions="q"*900000,input=[{"role":"user","content":"r"*1000}],store=False)
    except RuntimeError as exc:
        blocked="blocked request before api call" in str(exc).casefold()

    parsed=_ora_tpm_rate_limit_info(RuntimeError("Request too large for gpt-5.6-luna in organization org-test on tokens per min (TPM): Limit 200000, Requested 273084. The input or output tokens must be reduced in order to run successfully.")) or {}
    checks={
        "first_request_has_explicit_technical_output_reservation": sent.get("max_output_tokens")==16384,
        "final_input_estimate_includes_tool_schema": int(pre.get("tools_tokens") or 0)>0 and int(pre.get("final_input_estimate_tokens") or 0)>int(pre.get("instructions_tokens") or 0),
        "projected_request_includes_output_reservation": int(pre.get("projected_prompt_plus_output_tokens") or 0)==int(pre.get("final_input_estimate_tokens") or 0)+int(pre.get("max_output_tokens") or 0),
        "preflight_does_not_drop_context": pre.get("context_or_retrieval_changed") is False,
        "context_budget_ledger_visible_to_model": "CONTEXT BUDGET LEDGER — MECHANICAL" in str(sent.get("instructions") or "") and pre.get("context_budget_ledger_injected") is True,
        "context_budget_ledger_remeasured": int(pre.get("final_input_estimate_tokens") or 0) >= int(pre.get("pre_ledger_input_estimate_tokens") or 0),
        "context_budget_final_size_visible_to_model": "final_provider_input_estimate_tokens:" in str(sent.get("instructions") or ""),
        "context_budget_remaining_room_visible_to_model": "remaining_safe_input_after_ledger_tokens:" in str(sent.get("instructions") or ""),
        "context_budget_model_visible_final_matches_preflight": f"final_provider_input_estimate_tokens: {int(pre.get('final_input_estimate_tokens') or 0)}" in str(sent.get("instructions") or ""),
        "context_budget_model_visible_room_matches_preflight": f"remaining_safe_input_after_ledger_tokens: {pre.get('remaining_safe_input_tokens') if pre.get('remaining_safe_input_tokens') is not None else 'unknown'}" in str(sent.get("instructions") or ""),
        "complete_ledger_exposes_chat_intake": "chat_legacy_config_hard_limit_applied:" in str(sent.get("instructions") or ""),
        "complete_ledger_exposes_recent_tier": "recent_authorized_tier:" in str(sent.get("instructions") or ""),
        "complete_ledger_exposes_capacity_conflict": "capacity_conflict_active:" in str(sent.get("instructions") or ""),
        "complete_ledger_exposes_section_borrowing": "section_budget_role:" in str(sent.get("instructions") or ""),
        "canonical_preview_matches_actual_final_estimate": int(preview.get("final_input_estimate_tokens") or 0)==int(pre.get("final_input_estimate_tokens") or 0),
        "canonical_preview_matches_actual_tool_schema_estimate": int(preview.get("tools_tokens") or 0)==int(pre.get("tools_tokens") or 0),
        "canonical_preview_has_no_commit_side_effect_contract": preview.get("preview_only") is True,
        "known_oversized_request_blocks_before_provider": blocked and len(blocked_backend.client.responses.requests)==0,
        "new_openai_request_too_large_wording_parses_limit_and_requested": parsed.get("limit_tokens_per_minute")==200000 and parsed.get("requested_tokens")==273084 and parsed.get("used_tokens_per_minute") is None,
        "preflight_diagnostic_logged": any(e.get("event_type")=="provider.preflight" for e in events),
        "normal_request_completed": getattr(response,"output_text","")=="ok",
    }
    return {"ok":all(checks.values()),"checks":checks,"version":_ONLINE_BOOK_ACCESS_VERSION,"model_calls":len(backend.client.responses.requests),"blocked_model_calls":len(blocked_backend.client.responses.requests)}


