_CONTEXT_CAPACITY_PROFILE_VERSION = "2.1-total-input-reserve-accounting"
_CONTEXT_EXECUTION_RESERVE_PERCENT = 20
_CONTEXT_GATE_STEP_PERCENT = 10

# 7.4.78.115: preserve the model-side micro-gate implementations but keep them dormant
# by default. Live 2B/4B/9B tests showed that tiny route/selection calls can consume
# disproportionate reasoning budget. Mechanical safety checks, hard provider limits,
# provenance verification, and explicit human approval gates remain active. This is a
# reversible runtime policy, not code retirement.
_MODEL_INFERENCE_MICRO_GATES_DEFAULT_ENABLED = False
_MODEL_INFERENCE_MICRO_GATES_ENV = "NEAT_MODEL_INFERENCE_GATES"

def _model_inference_micro_gates_enabled(module=None) -> bool:
    override=getattr(module,"_MODEL_INFERENCE_MICRO_GATES_RUNTIME_OVERRIDE",None) if module is not None else None
    if override is not None:
        return bool(override)
    raw=str(os.getenv(_MODEL_INFERENCE_MICRO_GATES_ENV,"") or "").strip().casefold()
    if raw in {"1","true","yes","on","enabled"}: return True
    if raw in {"0","false","no","off","disabled"}: return False
    return bool(_MODEL_INFERENCE_MICRO_GATES_DEFAULT_ENABLED)

def _model_inference_micro_gate_status(module=None) -> dict:
    enabled=_model_inference_micro_gates_enabled(module)
    return {
        "version":"1.1-consolidated-dormant-inference-policy",
        "enabled":bool(enabled),
        "policy_state":"ENABLED" if enabled else "DORMANT",
        "default_enabled":bool(_MODEL_INFERENCE_MICRO_GATES_DEFAULT_ENABLED),
        "environment_override":_MODEL_INFERENCE_MICRO_GATES_ENV,
        "model_inference_calls_permitted":bool(enabled),
        "semantic_output_channel":"PUBLIC_CONTENT_ONLY",
        "reasoning_content_role":"TELEMETRY_ONLY_NON_OPERATIONAL",
        "no_selection_structural_depth":"LOW",
        "mechanical_safety_checks_active":True,
        "hard_provider_limits_active":True,
        "human_approval_gates_active":True,
        "gate_code_retained":True,
        "persistent_state":False,
    }


def _context_execution_capacity_profile(effective_safe_envelope_tokens: int) -> dict:
    """Mechanical 80/20 envelope split with 10%-of-envelope context gates.

    No token tier is hard-coded: every concrete token threshold is derived from the
    effective safe envelope for the request. Python owns only capacity arithmetic.
    """
    envelope=max(1,int(effective_safe_envelope_tokens or 1))
    reserve_percent=max(1,min(99,int(_CONTEXT_EXECUTION_RESERVE_PERCENT)))
    gate_percent=max(1,min(100-reserve_percent,int(_CONTEXT_GATE_STEP_PERCENT)))
    reserve=max(1,(envelope*reserve_percent)//100)
    context_ceiling=max(1,envelope-reserve)
    gate_step=max(1,(envelope*gate_percent)//100)
    thresholds=[]
    current=gate_step
    while current < context_ceiling:
        thresholds.append(int(current)); current += gate_step
    if not thresholds or thresholds[-1] != context_ceiling:
        thresholds.append(int(context_ceiling))
    return {
        "version":_CONTEXT_CAPACITY_PROFILE_VERSION,
        "effective_safe_envelope_tokens":int(envelope),
        "context_ceiling_tokens":int(context_ceiling),
        "protected_execution_reserve_tokens":int(reserve),
        "execution_reserve_percent":int(reserve_percent),
        "context_ceiling_percent":int(100-reserve_percent),
        "context_gate_step_percent":int(gate_percent),
        "context_gate_step_tokens":int(gate_step),
        "context_gate_thresholds_tokens":thresholds,
        "context_gate_count":len(thresholds),
        "python_semantic_selection":False,
    }


def _context_execution_capacity_profile_from_module(module) -> dict:
    last=dict(getattr(module,"_CONTEXT_EXECUTION_CAPACITY_PROFILE_LAST",{}) or {}) if module is not None else {}
    if int(last.get("effective_safe_envelope_tokens") or 0)>0:
        return last
    decision=dict(getattr(module,"_ADAPTIVE_LAST_DECISION",{}) or {}) if module is not None else {}
    envelope=int(decision.get("safe_input_limit_tokens") or 0)
    if envelope<=0 and module is not None:
        envelope=int(getattr(module,"CONTEXT_SAFE_INPUT_CAP_TOKENS",0) or getattr(module,"ADAPTIVE_SAFE_INPUT_CAP_TOKENS",0) or 0)
    return _context_execution_capacity_profile(envelope or 1)


_CONTEXT_POSITION_TELEMETRY_VERSION = "1.2-compact-live-projection-diagnostic-events"
_CONTEXT_POSITION_TELEMETRY_MARKER = "CONTEXT STATUS — MECHANICAL LIVE GAUGE"
_CONTEXT_POSITION_TELEMETRY_DIAGNOSTIC_EVENT = "context.position_event"


def _context_position_telemetry_snapshot(module, *, current_input_tokens: int, compiled_input_ceiling_tokens: int,
                                         effective_safe_envelope_tokens: int, retrieval_level: object = None,
                                         delivery_complete = None, clipping_active: bool = False,
                                         clipping_reasons = None, phase: object = None) -> dict:
    """Build the single current model-visible context-position projection.

    The projection is rebuilt for the current provider request, so it replaces itself
    rather than accumulating as conversation history. Gate/state event history is kept
    outside the prompt in diagnostic receipts. Python reports arithmetic/state only.
    """
    current=max(0,int(current_input_tokens or 0)); ceiling=max(0,int(compiled_input_ceiling_tokens or 0)); envelope=max(0,int(effective_safe_envelope_tokens or 0))
    pending=dict(getattr(module,"_CONTEXT_REQUEST_ENVELOPE_PENDING",{}) or {}) if module is not None else {}
    request_seq=int(pending.get("request_seq") or 0)
    if request_seq<=0 or current<=0 or ceiling<=0 or envelope<=0:
        return {"ok":False,"version":_CONTEXT_POSITION_TELEMETRY_VERSION,"reason":"no_active_request_envelope_or_capacity"}
    profile=_context_execution_capacity_profile(envelope)
    thresholds=[int(x) for x in (profile.get("context_gate_thresholds_tokens") or []) if int(x or 0)>0 and int(x or 0)<=ceiling]
    step=int(profile.get("context_gate_step_tokens") or 0); reserve=int(profile.get("protected_execution_reserve_tokens") or max(0,envelope-ceiling))
    epoch_material=f"{_CONTEXT_POSITION_TELEMETRY_VERSION}|{envelope}|{ceiling}|{step}"
    epoch=hashlib.sha256(epoch_material.encode("utf-8")).hexdigest()[:16]
    latest=max([x for x in thresholds if x<=current],default=0)
    next_gate=next((x for x in thresholds if x>current),None)
    delivery_state="COMPLETE" if delivery_complete is True else ("INCOMPLETE" if delivery_complete is False else "UNKNOWN")
    retrieval=str(retrieval_level or "unknown").upper()
    reasons=[]
    for value in list(clipping_reasons or []):
        clean=str(value or "").strip()
        if clean and clean not in reasons: reasons.append(clean)
    clipping_state="ACTIVE" if bool(clipping_active or reasons) else "NONE"
    return {
        "ok":True,"version":_CONTEXT_POSITION_TELEMETRY_VERSION,"projection_role":"LATEST_CURRENT_STATUS_ONLY",
        "epoch":epoch,"request_seq":request_seq,"phase":str(phase or pending.get("phase") or "UNKNOWN"),
        "current_input_estimate_tokens":current,"delivery_state":delivery_state,"retrieval_level":retrieval,
        "clipping_state":clipping_state,"clipping_reasons":reasons,
        "compiled_input_min_tokens":0,"compiled_input_max_tokens":ceiling,
        "estimated_headroom_tokens":max(0,ceiling-current),"effective_safe_envelope_tokens":envelope,
        "protected_execution_reserve_tokens":reserve,"latest_crossed_gate_tokens":latest,
        "gate_percent_of_safe_envelope":round((100.0*latest/envelope),1) if envelope and latest else 0.0,
        "position_percent_of_compiled_range":round((100.0*current/ceiling),1) if ceiling else None,
        "next_gate_tokens":next_gate,"gate_thresholds_tokens":thresholds,
        "historical_telemetry_in_prompt":False,"diagnostic_history_available":True,
        "python_semantic_selection":False,"advice_generated":False,"persistent_state":False,
    }


def _context_position_telemetry_state_signature(snapshot: dict) -> str:
    snap=dict(snapshot or {})
    material="|".join([
        str(snap.get("delivery_state") or "UNKNOWN"),str(snap.get("retrieval_level") or "UNKNOWN"),
        str(snap.get("clipping_state") or "NONE"),",".join(str(x) for x in (snap.get("clipping_reasons") or [])),
    ])
    return hashlib.sha256(material.encode("utf-8")).hexdigest()[:16]


def _context_position_telemetry_event_preview(module, snapshot: dict) -> dict:
    """Return a diagnostic-only event for a new gate or material mechanical state change."""
    snap=dict(snapshot or {})
    if not snap.get("ok"):
        return {"emit":False,"version":_CONTEXT_POSITION_TELEMETRY_VERSION,"reason":"no_valid_snapshot"}
    epoch=str(snap.get("epoch") or ""); current=int(snap.get("current_input_estimate_tokens") or 0)
    thresholds=[int(x) for x in (snap.get("gate_thresholds_tokens") or []) if int(x or 0)>0]
    state=dict(getattr(module,"_CONTEXT_POSITION_TELEMETRY_STATE",{}) or {}) if module is not None else {}
    same_epoch=str(state.get("epoch") or "")==epoch
    high_water=int(state.get("high_water_gate_tokens") or 0) if same_epoch else 0
    crossed=[x for x in thresholds if high_water < x <= current]
    state_signature=_context_position_telemetry_state_signature(snap)
    previous_signature=str(state.get("last_state_signature") or "") if same_epoch else ""
    baseline=not bool(previous_signature)
    state_changed=bool(previous_signature and previous_signature!=state_signature)
    if not crossed and not baseline and not state_changed:
        return {"emit":False,"version":_CONTEXT_POSITION_TELEMETRY_VERSION,"reason":"no_new_gate_or_material_state_change","epoch":epoch,"high_water_gate_tokens":high_water,"state_signature":state_signature}
    trigger=("CONTEXT_GATE_AND_STATE_CHANGED" if crossed and state_changed else
             "CONTEXT_GATE_CROSSED" if crossed else
             "CONTEXT_STATE_BASELINED" if baseline else "CONTEXT_STATE_CHANGED")
    event=dict(snap)
    event.update({
        "trigger":trigger,"diagnostic_only":True,"model_visible_event_history":False,
        "crossed_gate_count":len(crossed),"crossed_gates_tokens":crossed,
        "high_water_before_tokens":high_water,"state_signature":state_signature,
        "previous_state_signature":previous_signature or None,"material_state_changed":bool(state_changed),
        "baseline_event":bool(baseline),
    })
    return {"emit":True,"version":_CONTEXT_POSITION_TELEMETRY_VERSION,"event":event}


def _context_position_telemetry_render(snapshot: dict) -> str:
    """Render Assistant's minimal current gauge; detailed mechanics remain diagnostic-only."""
    e=dict(snapshot or {})
    if not e.get("ok"): return ""
    next_text=(f"{int(e.get('next_gate_tokens'))}t" if e.get("next_gate_tokens") is not None else "none")
    current=int(e.get("current_input_estimate_tokens") or 0)
    ceiling=int(e.get("compiled_input_max_tokens") or 0)
    headroom=int(e.get("estimated_headroom_tokens") or 0)
    envelope=int(e.get("effective_safe_envelope_tokens") or 0)
    delivery=str(e.get("delivery_state") or "UNKNOWN")
    clipping=str(e.get("clipping_state") or "NONE")
    return "\n".join([
        _CONTEXT_POSITION_TELEMETRY_MARKER,
        f"input: {current}/{ceiling}t | headroom: {headroom}t | safe envelope: {envelope}t | next gate: {next_text}",
        f"state: {delivery} | clipping: {clipping}",
    ])


def _context_position_telemetry_commit(module, snapshot: dict, event_preview: dict, *, request_seq: int) -> dict:
    """Commit runtime high-water/current-status only after preview/actual request parity."""
    snap=dict(snapshot or {}); epoch=str(snap.get("epoch") or "")
    if module is None or not snap.get("ok") or not epoch:
        return {"ok":False,"reason":"invalid_snapshot"}
    prior=dict(getattr(module,"_CONTEXT_POSITION_TELEMETRY_STATE",{}) or {})
    same_epoch=str(prior.get("epoch") or "")==epoch
    old=int(prior.get("high_water_gate_tokens") or 0) if same_epoch else 0
    event=dict((event_preview or {}).get("event") or {}) if (event_preview or {}).get("emit") else {}
    latest_event_gate=max([int(x) for x in (event.get("crossed_gates_tokens") or [])],default=0)
    high=max(old,latest_event_gate)
    state_signature=_context_position_telemetry_state_signature(snap)
    state={
        "version":_CONTEXT_POSITION_TELEMETRY_VERSION,"epoch":epoch,"high_water_gate_tokens":high,
        "last_state_signature":state_signature,"last_request_seq":int(request_seq or snap.get("request_seq") or 0),
        "last_snapshot":dict(snap),"last_event":dict(event) if event else dict(prior.get("last_event") or {}),
        "persistent_state":False,
    }
    module._CONTEXT_POSITION_TELEMETRY_STATE=state
    module._CONTEXT_POSITION_TELEMETRY_LAST_SNAPSHOT=dict(snap)
    if event: module._CONTEXT_POSITION_TELEMETRY_LAST_EVENT=dict(event)
    return {"ok":True,"high_water_gate_tokens":high,"advanced":high>old,"epoch":epoch,"event_committed":bool(event),"state_signature":state_signature}

def _context_execution_output_cap(module) -> int:
    """Return call headroom from the protected reserve, bounded by provider policy.

    This removes tiny gate-specific ceilings without silently increasing the provider's
    configured ordinary output reservation.
    """
    profile=_context_execution_capacity_profile_from_module(module)
    cap=max(1,int(profile.get("protected_execution_reserve_tokens") or 1))
    configured=int(getattr(module,"CHAT_OUTPUT_RESERVE_TOKENS",0) or 0) if module is not None else 0
    if configured>0:
        cap=min(cap,configured)
    return max(1,int(cap))


_DOMAIN_ALLOWED = ("system", "personal", "books")
_DOMAIN_DEFAULT = ("personal",)
_CONTEXT_PRIORITY_ALLOWED = ("recent", "system", "personal", "books")
_DOMAIN_ROUTER_OUTPUT_TOKENS = 220
_DOMAIN_CALIBRATION_FILE = "adaptive_token_calibration.json"


def _domain_json_safe(value):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _domain_json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_domain_json_safe(v) for v in value]
    return str(value)


def _domain_atomic_write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    text = json.dumps(_domain_json_safe(payload), ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    try:
        with temporary.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _recent_reflection_journal_status(module, run_id: object) -> dict:
    """Read-only verification that a reflection run was appended to the journal.

    Reflection reports are finalized before the journal append result is returned,
    so journal visibility must be derived from the append-only journal itself rather
    than inferred from immutable report JSON.
    """
    status = {
        "recorded": False,
        "run_id": str(run_id or ""),
        "journal_ref": None,
        "chain_valid": None,
        "authority": "reflection-map-only",
    }
    try:
        journal_path = Path(getattr(module, "MEMORY_DIR", Path.cwd())) / "reflection_journal.jsonl"
        status["path"] = str(journal_path)
        if not journal_path.exists():
            return status
        previous_hash = ""
        chain_valid = True
        matched_entry = None
        for raw_line in journal_path.read_text(encoding="utf-8").splitlines():
            if not raw_line.strip():
                continue
            entry = json.loads(raw_line)
            if not isinstance(entry, dict):
                chain_valid = False
                continue
            if str(entry.get("previous_entry_sha256") or "") != previous_hash:
                chain_valid = False
            payload_for_hash = {k: v for k, v in entry.items() if k != "entry_sha256"}
            canonical = json.dumps(
                payload_for_hash, ensure_ascii=False, sort_keys=True, separators=(",", ":")
            ).encode("utf-8")
            actual_hash = hashlib.sha256(canonical).hexdigest()
            stored_hash = str(entry.get("entry_sha256") or "")
            if stored_hash != actual_hash:
                chain_valid = False
            previous_hash = stored_hash or actual_hash
            if str(entry.get("run_id") or "") == str(run_id or ""):
                matched_entry = entry
        status["chain_valid"] = chain_valid
        if matched_entry is not None:
            status.update({
                "recorded": True,
                "journal_ref": matched_entry.get("journal_ref"),
                "created_at": matched_entry.get("created_at"),
                "status": matched_entry.get("status"),
                "confidence": matched_entry.get("confidence"),
                "entry_sha256": matched_entry.get("entry_sha256"),
                "authority": matched_entry.get("authority") or "reflection-map-only",
            })
    except Exception as exc:
        status["error"] = f"{type(exc).__name__}: {exc}"
    return status


def _install_domain_aware_retrieval(module) -> None:
    if getattr(module, "_DOMAIN_AWARE_RETRIEVAL_INSTALLED", False):
        return

    original_build_runtime_context = module.build_runtime_context
    original_is_self_system_query = module._is_self_system_query
    original_adaptive_prepare_context = module._adaptive_prepare_context
    original_adaptive_record_actual_usage = module._adaptive_record_actual_usage
    original_adaptive_estimate_tokens = module._adaptive_estimate_tokens
    original_adaptive_build_candidate = module._adaptive_build_candidate
    original_adaptive_depth_selector = getattr(module, "_adaptive_call_selector", None)

    module.RETRIEVAL_ENGINE_VERSION = "2.6.11-routing-dormancy-explicit-output"
    module._DOMAIN_ACTIVE_DOMAINS = None
    module._DOMAIN_LAST_ROUTING = None
    module._DOMAIN_ACTIVE_CALIBRATION_FACTOR = 1.0
    module._DOMAIN_ACTIVE_CALIBRATION_KEY = None
    module._DOMAIN_ACTIVE_LEVEL = None
    module._DOMAIN_ACTIVE_PRIORITY = ("recent", "personal", "system", "books")
    module.DOMAIN_HARD_EXCLUSION_ENABLED = False

    if "CROSS-DOMAIN CURRENT-STATE AUTHORITY RULE" not in str(module.SYSTEM_PROMPT):
        module.SYSTEM_PROMPT = str(module.SYSTEM_PROMPT).rstrip() + (
            "\n\nCROSS-DOMAIN CURRENT-STATE AUTHORITY RULE\n"
            "- Questions about how NeatMemory, retrieval, memory reliability, or the current project is working may require SYSTEM and PERSONAL evidence together.\n"
            "- Verified current runtime/receipts/traces outrank older personal memories for present program-state facts.\n"
            "- Newer explicit user corrections outrank older conflicting personal summaries for the current answer; preserve older records as history rather than silently deleting them.\n"
            "- Do not claim a stale handoff is current when newer verified operational evidence is available.\n"
        )

    def normalize_domains(value) -> tuple[str, ...]:
        if isinstance(value, str):
            raw = [value]
        else:
            raw = list(value or [])
        clean: list[str] = []
        for item in raw:
            name = str(item or "").strip().casefold()
            if name == "mixed":
                continue
            if name in _DOMAIN_ALLOWED and name not in clean:
                clean.append(name)
        ordered = tuple(name for name in _DOMAIN_ALLOWED if name in clean)
        return ordered or _DOMAIN_DEFAULT

    def enhanced_is_self_system_query(query: str) -> bool:
        q = " ".join(str(query or "").casefold().split())
        strong = (
            "neatmemory", "neat memory", "retrieval system", "retrieval depth",
            "data recovery", "memory recovery", "low mid high", "low/mid/high",
            "adaptive retrieval", "context budget", "token budget", "context window",
            "safe input", "retrieval trace", "/trace", "/benchmark", "benchmark receipt",
            "runtime", "provider", "model context", "checkpoint", "console",
            "packet build", "retrieval engine", "system logbook", "source code version",
        )
        meta_memory_state = (
            bool(re.search(r"\bmemory\b", q))
            and any(term in q for term in (
                "how is", "working", "work now", "now", "reliable", "correct", "right information",
                "correct information", "retrieval", "system", "status", "state", "accuracy",
            ))
        )
        return original_is_self_system_query(query) or meta_memory_state or any(term in q for term in strong)

    module._is_self_system_query = enhanced_is_self_system_query

    def python_domain_minimum(query: str) -> dict:
        """Advisory lexical hints only. Assistant/model routing is authoritative for priority."""
        q = " ".join(str(query or "").casefold().split())
        hints: list[str] = []
        signals: dict[str, list[str]] = {name: [] for name in _DOMAIN_ALLOWED}
        system_terms = (
            "neatmemory", "neat memory", "retrieval system", "data recovery", "memory recovery",
            "adaptive retrieval", "context budget", "token budget", "context window", "benchmark",
            "receipt", "trace", "runtime", "provider", "checkpoint", "database integrity",
            "retrieval engine", "system logbook",
        )
        personal_terms = (
            "remember", "do you remember", "we talked", "what did i say", "my preference",
            "my project", "our project", "our plan", "our conversation", "between us",
            "assistant", "continuity", "personal memory", "my history", "about me",
        )
        book_terms = (
            "book", "chapter", "novel", "play", "poem", "author", "quotation", "quote",
            "source chunk", "book chunk", "neatblock", "canonical chunk", "original source",
            "romeo", "juliet", "shakespeare", "friar lawrence", "tybalt", "capulet",
            "montague", "balthasar", "mantua", "verona",
        )
        if any(term in q for term in system_terms):
            hints.append("system"); signals["system"].append("lexical system/runtime hint")
        if any(term in q for term in personal_terms):
            hints.append("personal"); signals["personal"].append("lexical personal/continuity hint")
        if any(term in q for term in book_terms):
            hints.append("books"); signals["books"].append("lexical book/source hint")
        if re.search(r"\b(?:NB|MEM)-\d{8}-[A-Za-z0-9]+\b", str(query or "")):
            if "personal" not in hints: hints.append("personal")
            signals["personal"].append("structured-memory identifier hint")
        if re.search(r"\bBK-[A-Za-z0-9-]+\b", str(query or "")):
            if "books" not in hints: hints.append("books")
            signals["books"].append("book identifier hint")
        if module._is_simple_social_query(q) and "personal" not in hints:
            hints.append("personal"); signals["personal"].append("social continuity hint")
        if not hints:
            hints=["personal"]
        return {
            "mandatory_domains": [],
            "suggested_domains": list(dict.fromkeys(hints)),
            "signals": signals,
            "reason": "Python hints are advisory only; Assistant decides context priority from the query and recent conversation.",
        }

    def normalize_context_priority(value) -> tuple[str, ...]:
        raw = [value] if isinstance(value, str) else list(value or [])
        clean: list[str] = []
        for item in raw:
            name = str(item or "").strip().casefold()
            if name in _CONTEXT_PRIORITY_ALLOWED and name not in clean:
                clean.append(name)
        return tuple(clean) or ("recent", "personal", "system", "books")

