    _PRIOR_OUTPUT_PROVENANCE_BOUNDARY_VERSION = "1.0-exact-chat-message-span-origin-boundary"
    _RECENT_SOFT_BUDGET_VERSION = "1.5-dormant-structural-floor"
    _CONTEXT_BUDGET_LEDGER_VERSION = "1.2-total-input-reserve-accounting"
    module._CONTEXT_BUDGET_LEDGER_LAST = None
    module._CONTEXT_BUDGET_CANDIDATES = {}
    module._CONTEXT_BUDGET_ACTIVE = None
    module._CONTEXT_MATERIAL_BUDGET_OVERRIDE_TOKENS = None
    module._RECENT_CHAT_INTAKE_LAST = None
    module._RECENT_COMPONENTS_LAST = None
    module._RECENT_RENDERED_TEXT_LAST = None
    module._RECENT_RENDERED_BLOCK_LAST = None
    module._RECENT_PACKET_BINDINGS = {}
    module._CONTEXT_FINAL_REQUEST_BOUNDARY_LAST = None
    module._CONTEXT_REQUEST_ENVELOPE_SEQ = 0
    module._CONTEXT_REQUEST_ENVELOPES = []
    module._CONTEXT_REQUEST_ENVELOPE_PENDING = None
    module._CONTEXT_REQUEST_EVIDENCE_REFS = []
    module._CONTEXT_PROVIDER_CALL_ID_PENDING = None
    module._CONTEXT_CAPACITY_ROUTE_CONTRACT = None
    module._CONTEXT_CAPACITY_CONFLICT_LAST = None
