                header=("ASSISTANT-SELECTED RECENT CONTEXT — CONTINUITY INPUT\n"
                        "current_task_source: CURRENT_USER_TURN\n"
                        "prior_assistant_output_authority: UNVERIFIED_IN_RECENT / NONE_BY_RECENT_ALONE\n"
                        "prior_assistant_origin_binding: EXACT_OBJECT_REQUIRED / CONTEXTUAL_MENTION_IS_NOT_A_PROVENANCE_EDGE\n"
                        "prior_user_input_authority: USER_STATEMENT\n")
                begin=str(packet_location.get("begin_marker") or ""); end_marker=str(packet_location.get("end_marker") or "")
                start=int(packet_location.get("start") or 0); stop=int(packet_location.get("end") or 0)
