    def _ccr_registered_final_packet_in_request(instructions: str, level: str) -> dict:
        """Locate exactly one registered FINAL packet for the selected retrieval level."""
        text=str(instructions or "")
        chosen=str(level or "").strip().casefold()
        matches=[]
        for binding_id,row_raw in dict(getattr(module,"_RECENT_PACKET_BINDINGS",{}) or {}).items():
            row=dict(row_raw or {}) if isinstance(row_raw,dict) else {}
            if str(row.get("level") or "").casefold()!=chosen or str(row.get("phase") or "").casefold()!="final":
                continue
            begin,end=_recent_packet_markers(str(binding_id))
            begin_count=text.count(begin); end_count=text.count(end)
            start=text.find(begin); stop_marker=text.find(end,start+len(begin)) if start>=0 else -1
            if begin_count==1 and end_count==1 and start>=0 and stop_marker>=start+len(begin):
                matches.append({"binding_id":str(binding_id),"start":start,"end":stop_marker+len(end),"begin_marker":begin,"end_marker":end,"record":row})
        if len(matches)!=1:
            return {"ok":False,"version":_RECENT_PACKET_BINDING_VERSION,"level":chosen,"phase":"final","matching_registered_packets":len(matches),"binding_ids":[x.get("binding_id") for x in matches]}
        out=dict(matches[0]); out.update({"ok":True,"version":_RECENT_PACKET_BINDING_VERSION,"level":chosen,"phase":"final","matching_registered_packets":1})
        return out

    _CONTEXT_REQUEST_ENVELOPE_VERSION = "1.1-final-boundary-redecision-fresh-envelope"
    module.CONTEXT_REQUEST_ENVELOPE_VERSION = _CONTEXT_REQUEST_ENVELOPE_VERSION

    def _cre_request_sha256(request: dict) -> str:
        try:
            wire=json.dumps(dict(request or {}),sort_keys=True,ensure_ascii=False,separators=(",",":"),default=str)
        except Exception:
            wire=str(dict(request or {}))
        return hashlib.sha256(wire.encode("utf-8","replace")).hexdigest()

    def _cre_request_phase(request: dict) -> str:
        req=dict(request or {}); tools=list(req.get("tools") or []); items=list(req.get("input") or [])
        has_tool_results=False
        for item in items:
            if not isinstance(item,dict): continue
            kind=str(item.get("type") or item.get("role") or "").casefold()
            if kind in {"function_call_output","tool_result","tool"}: has_tool_results=True; break
        if tools and has_tool_results: return "TOOL_FOLLOWUP_WITH_TOOLS"
        if tools: return "WITH_TOOLS"
        if has_tool_results: return "SYNTHESIS_AFTER_TOOL_RESULTS"
        return "NO_TOOLS"

    def _cre_compact_history(exclude_seq: int|None=None) -> list[dict]:
        out=[]
        for raw in list(getattr(module,"_CONTEXT_REQUEST_ENVELOPES",[]) or [])[-8:]:
            if not isinstance(raw,dict): continue
            if exclude_seq is not None and int(raw.get("request_seq") or 0)==int(exclude_seq): continue
            out.append({
                "seq":int(raw.get("request_seq") or 0),"phase":raw.get("phase"),"status":raw.get("status"),
                "input":int(raw.get("actual_preflight_final_input_tokens") or raw.get("preview_final_input_estimate_tokens") or 0),
                "tools":int(raw.get("actual_preflight_tools_tokens") or raw.get("preview_tools_tokens") or 0),
                "recent_after":int(raw.get("recent_target_after_tokens") or 0),"provider_call_id":raw.get("provider_call_id"),
                "envelope_id":raw.get("envelope_id"),"evidence_record_ref":raw.get("evidence_record_ref"),
            })
        return out[-6:]

    def _cre_store_envelope(envelope: dict) -> dict:
        env=dict(envelope or {}); seq=int(env.get("request_seq") or 0)
        history=[]; replaced=False
        for raw in list(getattr(module,"_CONTEXT_REQUEST_ENVELOPES",[]) or []):
            row=dict(raw or {}) if isinstance(raw,dict) else {}
            if int(row.get("request_seq") or 0)==seq and seq>0:
                history.append(env); replaced=True
            else: history.append(row)
        if not replaced: history.append(env)
        module._CONTEXT_REQUEST_ENVELOPES=history[-16:]
        module._CONTEXT_REQUEST_ENVELOPE_PENDING=dict(env)
        module._CONTEXT_FINAL_REQUEST_BOUNDARY_LAST=dict(env)  # compatibility alias; request-scoped in .56
        return env

    def _cre_update_envelope(request_seq: int, **fields) -> dict:
        seq=int(request_seq or 0); found={}
        for raw in list(getattr(module,"_CONTEXT_REQUEST_ENVELOPES",[]) or []):
            if isinstance(raw,dict) and int(raw.get("request_seq") or 0)==seq:
                found=dict(raw); break
        if not found:
            found={"version":_CONTEXT_REQUEST_ENVELOPE_VERSION,"request_seq":seq}
        found.update(fields)
        return _cre_store_envelope(found)

    _CONTEXT_REQUEST_EVIDENCE_VERSION = "1.0-encrypted-blackbox-parity-receipt"
    module.CONTEXT_REQUEST_EVIDENCE_VERSION = _CONTEXT_REQUEST_EVIDENCE_VERSION

    def _cree_envelope_id(provider_call_id: str, request_seq: int, base_request_sha: str) -> str:
        material=f"{provider_call_id}|{int(request_seq)}|{base_request_sha}"
        return "CRE-"+hashlib.sha256(material.encode("utf-8","replace")).hexdigest()[:20].upper()

    def _cree_compact_receipt(envelope: dict) -> dict:
        env=dict(envelope or {})
        return {
            "version":_CONTEXT_REQUEST_EVIDENCE_VERSION,
            "envelope_id":env.get("envelope_id"),"request_seq":int(env.get("request_seq") or 0),
            "provider_call_id":env.get("provider_call_id"),"phase":env.get("phase"),
            "route_action":env.get("route_action"),"retrieval_level":env.get("retrieval_level"),
            "binding_id":env.get("binding_id"),
            "recent_target_before_tokens":int(env.get("recent_target_before_tokens") or 0),
            "recent_target_after_tokens":int(env.get("recent_target_after_tokens") or 0),
            "preview_request_sha256":env.get("preview_request_sha256"),
            "actual_request_sha256":env.get("actual_request_sha256"),
            "preview_final_input_tokens":int(env.get("preview_final_input_estimate_tokens") or 0),
            "actual_preflight_final_input_tokens":int(env.get("actual_preflight_final_input_tokens") or 0),
            "preview_tools_tokens":int(env.get("preview_tools_tokens") or 0),
            "actual_preflight_tools_tokens":int(env.get("actual_preflight_tools_tokens") or 0),
            "preview_ledger_overhead_tokens":int(env.get("preview_ledger_overhead_tokens") or 0),
            "actual_preflight_ledger_overhead_tokens":int(env.get("actual_preflight_ledger_overhead_tokens") or 0),
            "preview_safe_input_tokens":int(env.get("preview_safe_input_tokens") or 0),
            "actual_preflight_safe_input_tokens":int(env.get("actual_preflight_safe_input_tokens") or 0),
            "preview_output_reserve_tokens":int(env.get("preview_output_reserve_tokens") or 0),
            "actual_preflight_output_reserve_tokens":int(env.get("actual_preflight_output_reserve_tokens") or 0),
            "request_hash_matches":bool(env.get("request_hash_matches")),
            "preview_matches_actual_preflight":bool(env.get("preview_matches_actual_preflight")),
            "ledger_overhead_matches":bool(env.get("ledger_overhead_matches")),
            "parity_verified":bool(env.get("preview_matches_actual_preflight") and env.get("request_hash_matches") and env.get("ledger_overhead_matches")),
            "no_raw_prompt_or_tool_payloads_stored":True,"python_semantic_selection":False,
        }

    def _cree_persist_parity_receipt(envelope: dict, *, model: str="") -> dict:
        env=dict(envelope or {}); provider_call_id=str(env.get("provider_call_id") or "")
        if not provider_call_id:
            return {"ok":False,"error":"provider_call_id missing","durable":False}
        begin=getattr(module,"_blackbox_begin_event",None); add_frame=getattr(module,"_blackbox_add_frame",None); add_outcome=getattr(module,"_blackbox_add_outcome",None)
        if not (callable(begin) and callable(add_frame) and callable(add_outcome)):
            return {"ok":False,"error":"encrypted Black Box writer unavailable","durable":False}
        receipt=_cree_compact_receipt(env)
        event=begin("request_envelope_evidence",{
            "kind":"request_envelope_evidence","envelope_id":receipt.get("envelope_id"),
            "provider_call_id":provider_call_id,"request_seq":receipt.get("request_seq"),"phase":receipt.get("phase"),
        },provider="online",model=str(model or "online"),parameters={"evidence_version":_CONTEXT_REQUEST_EVIDENCE_VERSION,"payload_policy":"HASHES_AND_ACCOUNTING_ONLY"})
        add_frame(event,"request_envelope_parity_receipt",receipt,metadata={"authority":"mechanical_provider_request_evidence","raw_request_stored":False,"raw_tool_results_stored":False})
        add_outcome(event["event_id"],"parity_verified",success=bool(receipt.get("parity_verified")),note={"provider_call_id":provider_call_id,"envelope_id":receipt.get("envelope_id")},source="python")
        record_ref=f"record:blackbox-event:{event['event_id']}"
        cached={"event_id":event["event_id"],"record_ref":record_ref,"provider_call_id":provider_call_id,"envelope_id":receipt.get("envelope_id"),"request_seq":receipt.get("request_seq"),"phase":receipt.get("phase")}
        refs=list(getattr(module,"_CONTEXT_REQUEST_EVIDENCE_REFS",[]) or []); refs.append(cached); module._CONTEXT_REQUEST_EVIDENCE_REFS=refs[-32:]
        _cre_update_envelope(int(receipt.get("request_seq") or 0),evidence_blackbox_event_id=event["event_id"],evidence_record_ref=record_ref,evidence_receipt_version=_CONTEXT_REQUEST_EVIDENCE_VERSION,evidence_persisted=True)
        return {"ok":True,"durable":True,**cached,"receipt":receipt}

    def _cree_persist_provider_outcome(provider_call_id: str, outcome_type: str, *, success: bool|None=None, response_id=None, provider_attempt=None, error_type=None) -> dict:
        pid=str(provider_call_id or "")
        ref=next((dict(x) for x in reversed(list(getattr(module,"_CONTEXT_REQUEST_EVIDENCE_REFS",[]) or [])) if str((x or {}).get("provider_call_id") or "")==pid),None)
        if not ref:
            return {"ok":False,"error":"request-envelope evidence event not found in current process","provider_call_id":pid}
        add_outcome=getattr(module,"_blackbox_add_outcome",None)
        if not callable(add_outcome): return {"ok":False,"error":"Black Box outcome writer unavailable","provider_call_id":pid}
        note={"provider_call_id":pid,"envelope_id":ref.get("envelope_id"),"response_id":response_id,"provider_attempt":provider_attempt,"error_type":error_type}
        outcome_id=add_outcome(ref["event_id"],str(outcome_type),success=success,note=note,source="python")
        return {"ok":True,"event_id":ref["event_id"],"record_ref":ref.get("record_ref"),"outcome_id":outcome_id,"provider_call_id":pid,"envelope_id":ref.get("envelope_id")}

    def _cree_event_to_compact(event_id: str) -> dict|None:
        getter=getattr(module,"get_blackbox_event",None)
        if not callable(getter): return None
        record=getter(str(event_id),include_payloads=True)
        if not isinstance(record,dict) or not record.get("ok"): return None
        event_meta=dict(record.get("event") or {})
        if str(event_meta.get("event_type") or "")!="request_envelope_evidence": return None
        receipt=None
        for frame in record.get("frames") or []:
            if str((frame or {}).get("frame_type") or "")=="request_envelope_parity_receipt" and isinstance((frame or {}).get("payload"),dict):
                receipt=dict(frame.get("payload") or {}); break
        if receipt is None: return None
        outcomes=[]
        for row in record.get("outcomes") or []:
            outcomes.append({"outcome_type":row.get("outcome_type"),"success":row.get("success"),"created_at":row.get("created_at"),"note":row.get("note") if isinstance(row.get("note"),dict) else None})
        return {"event_id":event_id,"record_ref":f"record:blackbox-event:{event_id}","started_at":event_meta.get("started_at"),"receipt":receipt,"outcomes":outcomes,"encrypted_at_rest":True,"append_only_blackbox":True}

    def get_request_envelope_receipts(provider_call_id: str|None=None, envelope_id: str|None=None, limit: int=1) -> dict:
        limit=max(1,min(5,int(limit or 1))); pid=str(provider_call_id or "").strip(); eid=str(envelope_id or "").strip()
        event_ids=[]
        for row in reversed(list(getattr(module,"_CONTEXT_REQUEST_EVIDENCE_REFS",[]) or [])):
            if not isinstance(row,dict): continue
            if pid and str(row.get("provider_call_id") or "")!=pid: continue
            if eid and str(row.get("envelope_id") or "")!=eid: continue
            if row.get("event_id") and row.get("event_id") not in event_ids: event_ids.append(row.get("event_id"))
            if len(event_ids)>=limit: break
        if len(event_ids)<limit:
            if pid or eid:
                searcher=getattr(module,"search_blackbox_events",None)
                query=pid or eid
                found=searcher(query,max(5,limit*3)) if callable(searcher) and query else {"events":[]}
                candidates=found.get("events") or []
            else:
                lister=getattr(module,"list_blackbox_events",None)
                found=lister(200) if callable(lister) else {"events":[]}
                candidates=[x for x in (found.get("events") or []) if str((x or {}).get("event_type") or "")=="request_envelope_evidence"]
            for row in candidates:
                event_id=(row or {}).get("event_id")
                if event_id and event_id not in event_ids: event_ids.append(event_id)
                if len(event_ids)>=limit: break
        receipts=[]
        for event_id in event_ids[:limit]:
            compact=_cree_event_to_compact(event_id)
            if not compact: continue
            r=dict(compact.get("receipt") or {})
            if pid and str(r.get("provider_call_id") or "")!=pid: continue
            if eid and str(r.get("envelope_id") or "")!=eid: continue
            receipts.append(compact)
        return {"ok":True,"version":_CONTEXT_REQUEST_EVIDENCE_VERSION,"count":len(receipts),"receipts":receipts,"filters":{"provider_call_id":pid or None,"envelope_id":eid or None},"read_only":True,"bounded":True,"model_calls":0,"web_calls":0,"authority":"mechanical provider-request verification evidence; not semantic truth authority"}

    def _cre_route_contract(rail: dict, decision: dict) -> dict:
        existing=dict(getattr(module,"_CONTEXT_CAPACITY_ROUTE_CONTRACT",{}) or {})
        action=str(rail.get("selected_action_effective") or rail.get("selected_action") or "")
        level=str(rail.get("final_retrieval_level") or decision.get("selected") or "").casefold()
        active=bool(rail.get("active"))
        candidate={
            "version":"1.0-turn-scoped-assistant-capacity-route","active":active,"action":action or None,
            "retrieval_level":level or None,"elastic_dimension":"RECENT" if action.startswith("REDUCE_RECENT_USE_") else None,
            "selection_mode":rail.get("selection_mode"),"assistant_selected":str(rail.get("selection_mode") or "").startswith("ASSISTANT"),
            "provider_safe_limit_non_overridable":True,"python_semantic_selection":False,"persistent_state":False,
        }
        if not existing or existing.get("action")!=candidate.get("action") or existing.get("retrieval_level")!=candidate.get("retrieval_level") or bool(existing.get("active"))!=active:
            module._CONTEXT_CAPACITY_ROUTE_CONTRACT=dict(candidate)
            return candidate
        return existing

    def _ccr_final_request_boundary_reconcile(backend, request: dict) -> dict:
        """Prepare one immutable provider-request envelope immediately before preflight.

        Every provider-send wrapper invocation receives a new request_seq and a fresh fit
        receipt. The Assistant-selected capacity route is turn-scoped; the FIT receipt is not.
        A later tool/synthesis request may reuse REDUCE_RECENT authorization, but it must
        be measured and hash-bound again. No prior request's FIT flag can bypass this path.
        """
        req=dict(request or {})
