            print(f"[context telemetry event] {telemetry_event.get('trigger')} | gate {int(telemetry_snapshot.get('latest_crossed_gate_tokens') or 0):,}t | current ~{int(telemetry_snapshot.get('current_input_estimate_tokens') or 0):,}/{int(telemetry_snapshot.get('compiled_input_max_tokens') or 0):,}t | head ~{int(telemetry_snapshot.get('estimated_headroom_tokens') or 0):,}t | state {telemetry_snapshot.get('delivery_state')} | retrieval {telemetry_snapshot.get('retrieval_level')} | clipping {telemetry_snapshot.get('clipping_state')} | next {nxt_text}",flush=True)
