    _ccr_final_request_boundary_reconcile_once = _ccr_final_request_boundary_reconcile

    def _ccr_final_boundary_redecision(backend, request: dict, blocked: dict, prior_error: Exception) -> dict:
        """Ask Assistant what to do when the exact final request overflows unexpectedly.

        This is intentionally narrower than the earlier adaptive rail. At this point the
        retrieval candidate is already materialized, so Python may not pretend that a
        HIGH->MID/LOW substitution is an in-place operation. The only elastic operation
        mechanically available without rebuilding semantic retrieval is RECENT shrinkage
        at the current delivered depth. HOLD_NO_SEND remains the fail-closed DEFAULT.
        """
        env=dict(blocked or {})
        measured=int(env.get("preview_final_input_estimate_tokens") or 0)
        safe=int(env.get("preview_safe_input_tokens") or 0)
        overflow=max(0,measured-safe) if safe else int(env.get("overflow_tokens") or 0)
        level=str(env.get("retrieval_level") or (getattr(module,"_ADAPTIVE_LAST_DECISION",{}) or {}).get("selected") or "").casefold()
        current_recent=int(env.get("recent_target_after_tokens") or env.get("recent_target_before_tokens") or 0)
        failed_seq=int(env.get("request_seq") or 0)
        failed_envelope_id=str(env.get("envelope_id") or "")
        levels=tuple(getattr(module,"ADAPTIVE_RETRIEVAL_LEVELS",("low","mid","high")))
        reduce_action=f"REDUCE_RECENT_USE_{level.upper()}" if level in levels and current_recent>0 else ""
        options=[{
            "action":"HOLD_NO_SEND","effect":"keep the current context authorization unchanged and do not send an oversized provider request",
            "fits_without_rebuild":True,"semantic_tradeoff":False,
        }]
        if reduce_action:
            options.append({
                "action":reduce_action,"retrieval_level":level,
                "effect":f"preserve {level.upper()} retrieval and authorize Python to shrink only RECENT until a fresh exact request envelope fits",
                "current_recent_target_tokens":current_recent,"minimum_exact_overflow_tokens":overflow,
                "suggested_initial_recent_target_tokens":max(0,current_recent-overflow-256),
                "fits_without_rebuild":False,"requires_fresh_request_envelope":True,
            })
        card={
            "version":_CONTEXT_CAPACITY_CONFLICT_VERSION,
            "trigger":"FINAL_REQUEST_EXACT_OVERFLOW_WITHOUT_AUTHORIZED_ELASTIC_ROUTE",
            "failed_request_seq":failed_seq,"failed_envelope_id":failed_envelope_id,
            "exact_final_input_tokens":measured,"provider_safe_input_tokens":safe,"exact_overflow_tokens":overflow,
            "current_recent_target_tokens":current_recent,"current_retrieval_level":level or None,
            "prior_route_action":env.get("route_action"),"default_action":"HOLD_NO_SEND",
            "recommended_action":reduce_action or "HOLD_NO_SEND",
            "options":options,"other_valid_actions":["OWN_PLAN"] if reduce_action else [],
            "own_plan_constraints":{
                "retrieval_level_must_equal_current":level or None,
                "recent_target_tokens_min":0,"recent_target_tokens_max":max(0,current_recent-1),
                "reason":"Changing retrieval depth here is not an in-place mechanical operation; a different depth requires a new adaptive build.",
            } if reduce_action else None,
            "failed_envelope_never_authorizes_retry":True,
            "retry_requires_new_request_seq_and_envelope":True,
            "python_semantic_selection":False,"hard_limit_is_non_overridable":True,
            "rule":"Assistant chooses whether RECENT may shrink at the current retrieval depth. Python may only validate/reduce that authorized elastic dimension and must rebuild/hash-bind a fresh request envelope before sending.",
        }
        print(f"[final-boundary capacity conflict] request #{failed_seq} exact {measured:,}/{safe:,}t | overflow {overflow:,}t | RECENT {current_recent:,}t | retrieval {(level or 'none').upper()} | default HOLD_NO_SEND",flush=True)
        if not _model_inference_micro_gates_enabled(module):
            decision_record={"card":card,"selected_action":"HOLD_NO_SEND","selected_action_effective":"HOLD_NO_SEND",
                             "selection_mode":"MODEL_INFERENCE_GATES_DORMANT_HOLD_NO_SEND","reason":"model-side capacity gate dormant; fail-closed hard provider boundary",
                             "selector_metadata":{"attempted":False,"disabled":True,"provider_calls":0},"recent_target_requested_tokens":current_recent}
            _cre_update_envelope(failed_seq,status="BLOCKED_FINAL_BOUNDARY_HOLD",model_visible_status="EXACT_OVERFLOW_MODEL_GATES_DORMANT_HELD_NO_SEND",final_boundary_redecision=decision_record)
            print("[final-boundary capacity conflict] model gates DORMANT | HOLD_NO_SEND | oversized request remains blocked | provider gate calls 0",flush=True)
            return {"retry":False,"card":card,"decision":decision_record,"error":str(prior_error)}
        selector=getattr(module,"_context_capacity_selector",None)
        if not callable(selector):
            selector=_ccr_call_selector
        choice=None; valid={str(x.get("action") or "") for x in options}|({"OWN_PLAN"} if reduce_action else set())
        for attempt in range(2):
            choice=selector(backend,str(getattr(module,"_DOMAIN_ACTIVE_PROVIDER","") or "online"),str(((getattr(module,"_RECENT_SOFT_BUDGET_ACTIVE",None) or {}).get("query") or "FINAL_REQUEST_BOUNDARY")),card)
            action=str((choice or {}).get("action") or "").upper()
            if action=="OWN_PLAN":
                own_level=str((choice or {}).get("retrieval_level") or "").casefold()
                own_target=(choice or {}).get("recent_target_tokens")
                try: own_target=int(own_target)
                except Exception: own_target=None
                if own_level==level and own_target is not None and 0<=own_target<current_recent:
                    break
            elif action in valid:
                break
            print(f"[final-boundary capacity conflict] invalid choice attempt {attempt+1}/2; DEFAULT remains HOLD_NO_SEND",flush=True)
        action=str((choice or {}).get("action") or "").upper()
        selection_mode="ASSISTANT_EXPLICIT_FINAL_BOUNDARY_CHOICE"
        requested_target=current_recent
        effective_action=action
        if action=="OWN_PLAN" and reduce_action:
            own_level=str((choice or {}).get("retrieval_level") or "").casefold()
            try: own_target=int((choice or {}).get("recent_target_tokens"))
            except Exception: own_target=None
            if own_level==level and own_target is not None and 0<=own_target<current_recent:
                requested_target=own_target; effective_action=reduce_action
            else:
                action="HOLD_NO_SEND"; effective_action=action; selection_mode="FINAL_BOUNDARY_SELECTOR_FAILURE_DEFAULT_HOLD"
        elif action==reduce_action and reduce_action:
            requested_target=current_recent
        elif action!="HOLD_NO_SEND":
            action="HOLD_NO_SEND"; effective_action=action; selection_mode="FINAL_BOUNDARY_SELECTOR_FAILURE_DEFAULT_HOLD"

        decision_record={
            "card":card,"selected_action":action,"selected_action_effective":effective_action,
            "selection_mode":selection_mode,"reason":str((choice or {}).get("reason") or ""),
            "selector_metadata":dict((choice or {}).get("metadata") or {}),"recent_target_requested_tokens":requested_target,
        }
        _cre_update_envelope(failed_seq,
            status="BLOCKED_FINAL_BOUNDARY_REDECISION" if action!="HOLD_NO_SEND" else "BLOCKED_FINAL_BOUNDARY_HOLD",
            model_visible_status="EXACT_OVERFLOW_ASSISTANT_REDECISION_SELECTED" if action!="HOLD_NO_SEND" else "EXACT_OVERFLOW_HELD_NO_SEND",
            final_boundary_redecision=decision_record,
        )
        if action=="HOLD_NO_SEND" or not reduce_action:
            print(f"[final-boundary capacity conflict] Assistant {action or 'DEFAULT/HOLD_NO_SEND'} | oversized request remains blocked | no provider call",flush=True)
            return {"retry":False,"card":card,"decision":decision_record,"error":str(prior_error)}

        rail={
            "version":_CONTEXT_CAPACITY_CONFLICT_VERSION,"active":True,
            "selected_action":action,"selected_action_effective":effective_action,
            "selection_mode":selection_mode,"reason":str((choice or {}).get("reason") or ""),
            "recent_target_before_tokens":current_recent,"recent_target_after_tokens":int(requested_target),
            "requested_retrieval_level":str((getattr(module,"_ADAPTIVE_LAST_DECISION",{}) or {}).get("model_requested") or level),
            "pre_rail_safe_fallback":level,"chosen_retrieval_level":level,"final_retrieval_level":level,
            "selector_metadata":dict((choice or {}).get("metadata") or {}),
            "final_boundary_redecision":True,"failed_request_seq":failed_seq,"failed_envelope_id":failed_envelope_id,
            "failed_exact_final_input_tokens":measured,"failed_exact_safe_input_tokens":safe,"failed_exact_overflow_tokens":overflow,
            "failed_envelope_never_authorizes_retry":True,"retry_requires_new_request_seq_and_envelope":True,
            "exact_provider_fit_verified":False,"final_request_boundary_fit_verified":False,
            "python_semantic_selection":False,
        }
        decision=dict(getattr(module,"_ADAPTIVE_LAST_DECISION",{}) or {})
        decision["capacity_conflict_rail"]=dict(rail)
        if level: decision["selected"]=level
        decision["model_reason"]=(str(decision.get("model_reason") or "")+f"; exact final-boundary overflow required Assistant redecision; Assistant selected {action}").strip("; ")
        ledger=dict(getattr(module,"_CONTEXT_BUDGET_LEDGER_LAST",{}) or {})
        ledger["capacity_conflict_rail"]=dict(rail)
        module._ADAPTIVE_LAST_DECISION=decision
        module._CONTEXT_BUDGET_LEDGER_LAST=ledger
        module._CONTEXT_CAPACITY_CONFLICT_LAST=dict(rail)
        module._CONTEXT_CAPACITY_ROUTE_CONTRACT=None  # force fresh contract derivation from this explicit Assistant choice
        print(f"[final-boundary capacity conflict] Assistant {action} | failed envelope #{failed_seq} stays blocked | retry requires fresh request envelope",flush=True)
        return {"retry":True,"card":card,"decision":decision_record,"rail":rail}

    def _ccr_final_request_boundary_reconcile(backend, request: dict) -> dict:
        try:
            return _ccr_final_request_boundary_reconcile_once(backend,request)
        except RuntimeError as exc:
            blocked=dict(getattr(module,"_CONTEXT_REQUEST_ENVELOPE_PENDING",{}) or {})
            is_exact_overflow=bool(
                int(blocked.get("overflow_tokens") or 0)>0
                and str(blocked.get("model_visible_status") or "")=="BLOCKED_BEFORE_PROVIDER"
                and "exceeds the provider-safe input" in str(exc)
                and "No provider call was made" in str(exc)
            )
            if not is_exact_overflow:
                raise
            resolution=_ccr_final_boundary_redecision(backend,request,blocked,exc)
            if not resolution.get("retry"):
                raise RuntimeError(
                    f"Final-boundary capacity conflict held before provider: exact request {int(blocked.get('preview_final_input_estimate_tokens') or 0)}>{int(blocked.get('preview_safe_input_tokens') or 0)}; Assistant did not authorize an elastic RECENT route. No provider call was made."
                ) from exc
            # Important: call the one-shot coordinator again rather than mutating the
            # failed envelope. This increments request_seq and creates a fresh hash-bound
            # envelope whose exact preview/preflight must independently pass.
            return _ccr_final_request_boundary_reconcile_once(backend,request)

    module._context_capacity_final_request_boundary_reconcile=_ccr_final_request_boundary_reconcile
    module._context_request_envelope_verify_actual_preflight=_cre_verify_actual_preflight
    module._context_request_envelope_update=_cre_update_envelope
    module._context_request_envelope_persist_parity_receipt=_cree_persist_parity_receipt
    module._context_request_envelope_persist_provider_outcome=_cree_persist_provider_outcome
    module.get_request_envelope_receipts=get_request_envelope_receipts
    if isinstance(getattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST",None),set): module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("get_request_envelope_receipts")
    module.get_context_final_request_boundary_status=lambda: {"ok":True,"version":_CONTEXT_REQUEST_ENVELOPE_VERSION,"evidence_version":_CONTEXT_REQUEST_EVIDENCE_VERSION,"last":dict(getattr(module,"_CONTEXT_REQUEST_ENVELOPE_PENDING",{}) or {}),"history":list(getattr(module,"_CONTEXT_REQUEST_ENVELOPES",[]) or []),"evidence_refs":list(getattr(module,"_CONTEXT_REQUEST_EVIDENCE_REFS",[]) or [])[-8:],"route_contract":dict(getattr(module,"_CONTEXT_CAPACITY_ROUTE_CONTRACT",{}) or {})}

