    def domain_aware_prepare_context(backend, messages, query, *, provider, output_reserve_tokens, extra_instruction_text=""):
        python_plan = python_domain_minimum(query)
        availability = domain_availability()
        router_logger = getattr(module, "append_diagnostic_log", None)
        router_started = module.time.perf_counter_ns()
        if callable(router_logger):
            router_logger(
                "retrieval.router_start", "Context-priority retrieval director started.", subsystem="retrieval", provider=provider,
                model=str(getattr(backend, "model_id", "")), details={"python_advisory_hints": python_plan.get("suggested_domains") or []},
            )
        requested_priority, router_reason, router_metadata = call_domain_router(backend, provider, query, python_plan, availability)
        routing_dormant = bool(router_metadata.get("disabled"))
        if callable(router_logger):
            router_failed = bool(router_metadata.get("error"))
            router_logger(
                "retrieval.router_error" if router_failed else "retrieval.router_complete",
                "Context-priority retrieval director failed; fallback used." if router_failed else "Context-priority retrieval director completed.",
                severity="warning" if router_failed else "info", subsystem="retrieval", provider=provider, model=str(getattr(backend, "model_id", "")),
                details={
                    "duration_ms": round((module.time.perf_counter_ns()-router_started)/1_000_000.0,4),
                    "priority": list(normalize_context_priority(requested_priority)), "reason": router_reason,
                    "provider_input_tokens": router_metadata.get("provider_input_tokens"),
                    "provider_output_tokens": router_metadata.get("provider_output_tokens"),
                    "request_id": router_metadata.get("request_id"), "error": router_metadata.get("error"),
                    "model_call_count": 1 if router_metadata.get("attempted") else 0,
                },
            )
        context_priority = normalize_context_priority(requested_priority)
        priority_domains = tuple(x for x in context_priority if x in _DOMAIN_ALLOWED)
        selected_domains = tuple(_DOMAIN_ALLOWED)
        excluded = []
        key = calibration_key(provider, str(getattr(backend, "model_id", "unknown")), selected_domains)
        factor, calibration_data = load_calibration(key)
        module._DOMAIN_ACTIVE_DOMAINS = selected_domains
        module._DOMAIN_ACTIVE_PRIORITY = context_priority
        module._DOMAIN_ACTIVE_CALIBRATION_FACTOR = factor
        module._DOMAIN_ACTIVE_CALIBRATION_KEY = key
        routing = {
            "allowed_context_sources": list(_CONTEXT_PRIORITY_ALLOWED),
            "allowed_domains": list(_DOMAIN_ALLOWED),
            "python_mandatory_domains": [],
            "python_advisory_hints": python_plan["suggested_domains"],
            "python_reason": python_plan["reason"],
            "model_context_priority": None if routing_dormant else list(context_priority),
            "context_priority": list(context_priority),
            "selection_mode": router_metadata.get("selection_mode") or ("ASSISTANT_EXPLICIT_ROUTING" if not routing_dormant else "MODEL_ROUTING_DORMANT_MECHANICAL_ORDER"),
            "model_reason": None if routing_dormant else (router_reason or "no reason supplied"),
            "priority_domains": list(priority_domains),
            "selected_domains": list(selected_domains),
            "excluded_domains": excluded,
            "hard_exclusion_enabled": False,
            "assistant_priority_authoritative": not routing_dormant,
            "assistant_selected": not routing_dormant,
            "python_semantic_selection": False,
            "domain_availability": availability,
            "router": router_metadata,
            "token_calibration": {
                "profile_key": key, "factor_used": factor,
                "existing_profile": (calibration_data.get("profiles") or {}).get(key),
            },
            "selected_at": module.utc_now(),
        }
        if routing_dormant:
            context_instruction = (
                "\n\nCONTEXT AVAILABILITY — MODEL ROUTING DORMANT / OPEN-DOMAIN MODE\n"
                f"Mechanical delivery order: {' > '.join(context_priority)}. Open evidence domains: {', '.join(selected_domains)}. Excluded domains: none.\n"
                "No semantic context priority was chosen by Assistant or Python in this pre-context step. The order is a stable structural fallback only. "
                "All domains remain available; verified provenance/current operational evidence and explicit user corrections still govern factual authority. "
                "Assistant may decide what evidence matters in the actual answer; hidden reasoning is never parsed as a routing choice."
            )
            print(
                f"[context retrieval] model routing DORMANT | mechanical order {'>'.join(x.upper() for x in context_priority)} | open SYSTEM+PERSONAL+BOOKS | excluded none | provider routing calls 0 | calibration {factor:.3f}",
                flush=True,
            )
        else:
            context_instruction = (
                "\n\nASSISTANT-DIRECTED CONTEXT PRIORITY — OPEN-DOMAIN MODE\n"
                f"Assistant chose context priority: {' > '.join(context_priority)}. Open evidence domains: {', '.join(selected_domains)}. Excluded domains: none.\n"
                f"Reason: {router_reason or python_plan['reason']}.\n"
                "This priority was chosen from the user's query plus compact recent conversation. Treat it as the relevance/composition order for this turn, not as an authority hierarchy. "
                "All domains remain available if lower-priority evidence becomes necessary. Python lexical hints are advisory only and cannot force a domain or topic. "
                "For factual conflicts, verified provenance/current operational evidence and explicit user corrections still determine truth; priority only determines what to inspect first."
            )
            print(
                f"[context retrieval] Assistant priority {'>'.join(x.upper() for x in context_priority)} | open SYSTEM+PERSONAL+BOOKS | excluded none | calibration {factor:.3f}",
                flush=True,
            )
        module._CONTEXT_BUDGET_CANDIDATES = {}
        module._RECENT_PACKET_BINDINGS = {}
        module._CONTEXT_FINAL_REQUEST_BOUNDARY_LAST = None
        module._CONTEXT_REQUEST_ENVELOPE_SEQ = 0
        module._CONTEXT_REQUEST_ENVELOPES = []
        module._CONTEXT_REQUEST_ENVELOPE_PENDING = None
        module._CONTEXT_REQUEST_EVIDENCE_REFS = []
        module._CONTEXT_PROVIDER_CALL_ID_PENDING = None
        module._CONTEXT_CAPACITY_ROUTE_CONTRACT = None
        # Context-position telemetry high-water is intentionally process/continuity scoped,
        # not turn scoped. A new capacity epoch resets mechanically when envelope/ceiling changes.
        module._CONTEXT_BUDGET_LEDGER_LAST = {
            "version":_CONTEXT_BUDGET_LEDGER_VERSION,"query_sha256":hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
            "raw_query_stored":False,"provider":str(provider),"stages":{},"python_semantic_selection":False,
        }
        module._RECENT_SOFT_BUDGET_ACTIVE = {
            "query": str(query or ""), "backend": backend, "provider": str(provider),
            "decision": None, "components": None,
        } if "recent" in context_priority else None
        saved_retrieval_default = getattr(module, "ADAPTIVE_RETRIEVAL_DEFAULT", "mid")
        try:
            if routing_dormant:
                module.ADAPTIVE_RETRIEVAL_DEFAULT = "low"
            result = original_adaptive_prepare_context(
                backend, messages, query, provider=provider,
                output_reserve_tokens=output_reserve_tokens,
                extra_instruction_text=extra_instruction_text + context_instruction,
            )
            result = _ccr_maybe_resolve(
                result, backend, provider, query, messages,
                extra_instruction_text + context_instruction,
            )
            if routing_dormant:
                dormant_decision = dict(result.get("decision") or {})
                dormant_decision.update({
                    "selector_failure_fallback": "low",
                    "model_requested": None,
                    "selector_fallback_used": False,
                    "selector_dormant": True,
                    "selection_mode": "MODEL_ROUTING_DORMANT_STRUCTURAL_FLOOR",
                    "model_reason": "retrieval-depth selector dormant; LOW is the structural floor, not an Assistant semantic choice",
                    "assistant_selected_depth": False,
                    "python_semantic_selection": False,
                })
                result["decision"] = dormant_decision
            # Clarify the legacy base metric so it cannot be mistaken for expanded RECENT CHAT intake.
            result["context"] = str(result.get("context") or "").replace(
                "Raw conversation estimate:", "Legacy raw-chat file metric (not RECENT CHAT intake):"
            )
        finally:
            module.ADAPTIVE_RETRIEVAL_DEFAULT = saved_retrieval_default
            active_soft = getattr(module, "_RECENT_SOFT_BUDGET_ACTIVE", None)
            if isinstance(active_soft, dict):
                active_soft["backend"] = None
            module._RECENT_SOFT_BUDGET_ACTIVE = None
            module._DOMAIN_ACTIVE_DOMAINS = None
            module._DOMAIN_ACTIVE_PRIORITY = ("recent", "personal", "system", "books")
            module._DOMAIN_ACTIVE_CALIBRATION_FACTOR = 1.0
        decision = result.get("decision") or {}
        effective_envelope=int(decision.get("safe_input_limit_tokens") or getattr(module,"CONTEXT_SAFE_INPUT_CAP_TOKENS",0) or 1)
        capacity_profile=_context_execution_capacity_profile(effective_envelope)
        module._CONTEXT_EXECUTION_CAPACITY_PROFILE_LAST=dict(capacity_profile)
        decision["execution_capacity_profile"]=dict(capacity_profile)
        print(f"[context reserve] safe envelope {effective_envelope:,}t | compiled input ceiling {int(capacity_profile['context_ceiling_tokens']):,}t ({int(capacity_profile['context_ceiling_percent'])}%) | execution reserve {int(capacity_profile['protected_execution_reserve_tokens']):,}t ({int(capacity_profile['execution_reserve_percent'])}%) | gates every {int(capacity_profile['context_gate_step_tokens']):,}t ({int(capacity_profile['context_gate_step_percent'])}%)",flush=True)
        routing["recent_materialization"] = dict(getattr(module, "_RECENT_ANSWER_CONTEXT_LAST", {}) or {})
        ledger=dict(getattr(module,"_CONTEXT_BUDGET_LEDGER_LAST",{}) or {})
        selected_level=str(decision.get("selected") or "")
        recent_delivery=dict(getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {})
        ledger.update({
            "adaptive_selected_level":selected_level or None,
            "safe_input_limit_tokens":int(decision.get("safe_input_limit_tokens") or 0),
            "model_context_limit_tokens":int(decision.get("model_context_limit_tokens") or 0),
            "reserved_output_tokens":int(decision.get("reserved_output_tokens") or 0),
            "execution_capacity_profile":dict(capacity_profile),
            "context_ceiling_tokens":int(capacity_profile["context_ceiling_tokens"]),
            "compiled_input_ceiling_tokens":int(capacity_profile["context_ceiling_tokens"]),
            "protected_execution_reserve_tokens":int(capacity_profile["protected_execution_reserve_tokens"]),
            "mandatory_input_overhead_estimate_tokens":int(decision.get("mandatory_input_overhead_estimate_tokens") or 0),
            "context_material_budget_tokens":int(decision.get("context_material_budget_tokens") or 0),
            "recent":recent_delivery,
            "recent_chat_intake":dict(getattr(module,"_RECENT_CHAT_INTAKE_LAST",{}) or {}),
            "candidate_sections":dict(getattr(module,"_CONTEXT_BUDGET_CANDIDATES",{}) or {}),
            "selected_sections":dict((getattr(module,"_CONTEXT_BUDGET_CANDIDATES",{}) or {}).get(selected_level) or {}),
            "capacity_conflict_rail":dict(getattr(module,"_CONTEXT_CAPACITY_CONFLICT_LAST",{}) or {}),
        })
        module._CONTEXT_BUDGET_LEDGER_LAST=ledger
        intake=dict(ledger.get("recent_chat_intake") or {})
        if intake:
            print(
                f"[context budget] CHAT raw {int(intake.get('raw_public_messages_available') or 0):,} rows / {int(intake.get('raw_public_characters_available') or 0):,} chars | "
                f"loaded {int(intake.get('rows_loaded') or 0):,} rows ~{int(intake.get('estimated_loaded_tokens') or 0):,}t | "
                f"configured hints {int(intake.get('configured_message_hint') or 0):,} rows / {int(intake.get('configured_character_hint') or 0):,} chars | legacy hard applied {str(bool(intake.get('legacy_config_limit_applied'))).lower()}",
                flush=True,
            )
        decision["context_budget_ledger"]={k:v for k,v in ledger.items() if k not in {"candidate_sections"}}
        result["decision"]=decision
        decision["domain_routing"] = routing
        decision["context_priority"] = list(context_priority)
        result["decision"] = decision
        result["context"] += context_instruction
        module._DOMAIN_LAST_ROUTING = routing
        module._ADAPTIVE_LAST_DECISION = decision
        last = module.get_last_retrieval_trace()
        if last.get("ok"):
            trace = dict(last.get("trace") or {})
            trace["domain_routing"] = routing
            trace["context_priority"] = list(context_priority)
            trace["adaptive_retrieval"] = decision
            module._store_retrieval_trace(trace)
        return result

    def domain_aware_build_candidate(query, level, safe_input_tokens):
        previous_level = getattr(module, "_DOMAIN_ACTIVE_LEVEL", None)
        previous_budget = getattr(module,"_CONTEXT_BUDGET_ACTIVE",None)
        module._DOMAIN_ACTIVE_LEVEL = str(level)
        profile=_context_execution_capacity_profile(safe_input_tokens)
        context_ceiling=int(profile["context_ceiling_tokens"])
        override=getattr(module,"_CONTEXT_MATERIAL_BUDGET_OVERRIDE_TOKENS",None)
        material_budget=context_ceiling if override is None else max(0,min(context_ceiling,int(override)))
        module._CONTEXT_EXECUTION_CAPACITY_PROFILE_LAST=dict(profile)
        module._CONTEXT_BUDGET_ACTIVE={"level":str(level),"safe_input_tokens":material_budget,"effective_safe_envelope_tokens":int(profile["effective_safe_envelope_tokens"]),"compiled_input_ceiling_tokens":context_ceiling,"context_material_budget_tokens":material_budget,"protected_execution_reserve_tokens":int(profile["protected_execution_reserve_tokens"]),"context_gate_step_tokens":int(profile["context_gate_step_tokens"])}
        try:
            _ensure_recent_soft_budget_decision(query, safe_input_tokens)
            built=original_adaptive_build_candidate(query, level, material_budget)
            built["compiled_input_ceiling_tokens"]=context_ceiling
            built["context_material_budget_tokens"]=material_budget
            built["execution_capacity_profile"]=dict(profile)
            stage=dict(getattr(module,"_CONTEXT_BUDGET_SECTION_LAST",{}) or {})
            candidates=dict(getattr(module,"_CONTEXT_BUDGET_CANDIDATES",{}) or {})
            candidates[str(level)]=stage
            module._CONTEXT_BUDGET_CANDIDATES=candidates
            built["context_budget_sections"]=stage
            return built
        finally:
            module._CONTEXT_BUDGET_ACTIVE=previous_budget
            module._DOMAIN_ACTIVE_LEVEL = previous_level

    module._adaptive_build_candidate = domain_aware_build_candidate

    module._adaptive_prepare_context = domain_aware_prepare_context

    def domain_aware_record_actual_usage(response, provider: str) -> None:
        original_adaptive_record_actual_usage(response, provider)
        routing = getattr(module, "_DOMAIN_LAST_ROUTING", None) or {}
        decision = getattr(module, "_ADAPTIVE_LAST_DECISION", None) or {}
        key = ((routing.get("token_calibration") or {}).get("profile_key")) or getattr(module, "_DOMAIN_ACTIVE_CALIBRATION_KEY", None)
        factor_used = ((routing.get("token_calibration") or {}).get("factor_used")) or 1.0
        usage = getattr(response, "usage", None)
        if provider == "online":
            actual = getattr(usage, "input_tokens", None) if usage is not None else None
        else:
            actual = getattr(usage, "prompt_tokens", None) if usage is not None else None
        selected_level = str(decision.get("selected") or "mid")
        estimated = ((decision.get("levels") or {}).get(selected_level) or {}).get("estimated_complete_prompt_tokens")
        if key:
            profile = save_calibration(str(key), float(factor_used), estimated, actual)
            routing.setdefault("token_calibration", {})["updated_profile"] = profile
            decision["domain_routing"] = routing
            module._DOMAIN_LAST_ROUTING = routing
            module._ADAPTIVE_LAST_DECISION = decision
            last = module.get_last_retrieval_trace()
            if last.get("ok"):
                trace = dict(last.get("trace") or {})
                trace["domain_routing"] = routing
                trace["adaptive_retrieval"] = decision
                module._store_retrieval_trace(trace)

    module._adaptive_record_actual_usage = domain_aware_record_actual_usage

