    visible, validation = _citation_process_answer("League [[CITE:T1]] Band [[CITE:T2]]", catalog)

    # A result that does not fit must never enter the citable turn catalog.
    class TightModule(FakeModule):
        _ADAPTIVE_LAST_DECISION = {"selected":"low","reserved_output_tokens":4096,"model_context_limit_tokens":20000,"safety_margin_tokens":4096}
