def _presence_handle_command(module, text: str) -> bool:
    command = str(text or "").strip()
    lower = command.casefold()
    if lower in {"/startup", "/startup show", "/startup status", "/startup refresh"}:
        print(_render_startup_presence_panel(module), end="")
        view, status = _load_startup_view(module)
        print(json.dumps({"status": status, "view": view}, ensure_ascii=False, indent=2))
        if lower == "/startup refresh":
            module._STARTUP_PRESENCE_CONTEXT_PENDING = True
        return True
    if lower == "/startup available":
        print(json.dumps({
            "maximum_items": _STARTUP_VIEW_MAX_ITEMS,
            "emotions": list(_EMOTION_PROFILES),
            "somatic": [{"id": name, "unit": profile.get("unit"), "rest": profile.get("rest_value")} for name, profile in _SOMATIC_PROFILES.items()],
        }, ensure_ascii=False, indent=2)); return True
    if lower in {"/startup auto", "/startup reset"}:
        print(json.dumps(_apply_startup_display_update(module, {"startup_display_update": {"mode": "automatic"}}, provider="user", model="console"), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/startup set "):
        raw = command.split(maxsplit=2)[2]
        ids = [item for item in re.split(r"[\s,]+", raw) if item]
        print(json.dumps(_apply_startup_display_update(module, {"startup_display": ids}, provider="user", model="console"), ensure_ascii=False, indent=2)); return True

    if lower == "/identity verify":
        print(json.dumps(_identity_verify_report(module), ensure_ascii=False, indent=2)); return True
    if lower == "/identity rebuild":
        print(json.dumps(_identity_rebuild(module), ensure_ascii=False, indent=2)); return True
    if lower == "/self show":
        payload, status = _load_current_self_snapshot(module)
        print(json.dumps({"status": status, "snapshot": payload}, ensure_ascii=False, indent=2)); return True
    if lower == "/self snapshot":
        payload = _refresh_current_self_snapshot(module, reason="manual_snapshot")
        print(json.dumps(payload, ensure_ascii=False, indent=2)); return True

    if lower in {"/emotion profiles", "/emotion profile"}:
        print(json.dumps(get_emotion_profiles(), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/emotion debug"):
        parts = command.split()
        limit = int(parts[-1]) if parts[-1].isdigit() else 12
        print(json.dumps(_emotion_debug_report(module, limit), ensure_ascii=False, indent=2)); return True

    if lower in {"/somatic", "/somatic status"}:
        print(json.dumps(get_current_somatic_state(module), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/somatic history"):
        parts = command.split()
        limit = int(parts[-1]) if parts[-1].isdigit() else 20
        print(json.dumps(read_somatic_history(module, limit=limit), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/somatic search "):
        parts = command.split()
        state = parts[2]
        limit = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else 50
        print(json.dumps(search_somatic_history(module, state=state, limit=limit), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/somatic events"):
        parts = command.split()
        state = None
        limit = 50
        if len(parts) > 2 and not parts[2].isdigit():
            state = parts[2]
        if parts and parts[-1].isdigit():
            limit = int(parts[-1])
        print(json.dumps(read_somatic_metric_events(module, state=state, limit=limit), ensure_ascii=False, indent=2)); return True
    if lower in {"/somatic profiles", "/somatic profile"}:
        print(json.dumps(get_somatic_profiles(), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/somatic debug"):
        parts = command.split()
        limit = int(parts[-1]) if parts[-1].isdigit() else 12
        print(json.dumps(_somatic_debug_report(module, limit), ensure_ascii=False, indent=2)); return True

    if lower in {"/context", "/context status"}:
        print(json.dumps(_context_status_report(module), ensure_ascii=False, indent=2)); return True
    if lower == "/context breakdown":
        print(json.dumps(_context_breakdown_report(module), ensure_ascii=False, indent=2)); return True
    if lower == "/context detect":
        module._ENDPOINT_CONTEXT_CACHE = None
        print(json.dumps(_context_status_report(module, force_detection=True), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/context set "):
        value = command.split(maxsplit=2)[2].strip().casefold()
        if value in {"auto", "automatic", "clear", "off"}:
            module.set_setting("endpoint_context_tokens", "")
            module._ENDPOINT_CONTEXT_CACHE = None
            print("Endpoint context override cleared; automatic detection is active.")
        else:
            try:
                tokens = int(value.replace(",", ""))
                if not 4096 <= tokens <= 4_000_000:
                    raise ValueError
            except ValueError:
                print("Use /context set with 4096 to 4000000 tokens, or auto.")
            else:
                module.set_setting("endpoint_context_tokens", str(tokens))
                module._ENDPOINT_CONTEXT_CACHE = None
                print(f"Endpoint context override set to {tokens:,} tokens. This changes NeatMemory's prompt budget, not the server process itself.")
        return True
    return False


def _install_presence_menu_diagnostics(module) -> None:
    if getattr(module, "_PRESENCE_MENU_DIAGNOSTICS_INSTALLED", False):
        return
    _startup_view_bootstrap(module)
    # 7.4.70.1: the populated-state recovery proof imports this module in a
    # disposable second process before its deterministic test cipher is installed.
    # On Windows, normal startup materializes current_self immediately because
    # os.name == "nt"; that can overwrite the intentionally stale test snapshot
    # with production-DPAPI output before the proof can inspect/rebuild it.
    # Suppress only this startup materialization in the explicitly marked isolated
    # PSR child. Production startup and every non-PSR path remain unchanged.
    if os.getenv("NEAT_PSR_SUPPRESS_STARTUP_CURRENT_SELF", "").strip() != "1":
        try:
            _refresh_current_self_snapshot(module, reason="startup_presence_bootstrap")
        except Exception:
            pass
    module._STARTUP_PRESENCE_CONTEXT_PENDING = True
    module.STARTUP_VIEW_ENCRYPTED_FILE = _STARTUP_VIEW_FILE
    module.get_startup_presence = lambda include_all=True: _startup_presence_snapshot(module, include_all=include_all)
    module.get_startup_view = lambda: _load_startup_view(module)[0]
    module.get_context_diagnostics = lambda breakdown=False: _context_breakdown_report(module) if breakdown else _context_status_report(module)
    module.presence_menu_self_test = lambda: presence_menu_diagnostics_self_test(module)
    module.print_help = _print_help_7491

    # Make the real endpoint context authoritative for local adaptive retrieval
    # when llama.cpp/LM Studio exposes it, while retaining the old fallback.
    old_context_limit = module._adaptive_model_context_limit
    def adaptive_model_context_limit_with_endpoint(backend, provider):
        if str(provider).casefold() == "local":
            detected = _detect_endpoint_context(module)
            if detected.get("context_tokens"):
                return int(detected["context_tokens"]), str(detected.get("source") or "detected endpoint context")
        return old_context_limit(backend, provider)
    module._adaptive_model_context_limit = adaptive_model_context_limit_with_endpoint

    old_build = module.build_runtime_context
    def build_runtime_context_with_startup_presence(query, *args, **kwargs):
        original = old_build(query, *args, **kwargs)
        if getattr(module, "_STARTUP_PRESENCE_CONTEXT_PENDING", False):
            # Adaptive retrieval builds LOW/MID/HIGH candidates before selecting
            # one. Keep the startup block pending so every candidate receives
            # the same pure data; the flag is cleared after the first LLM reply.
            return _startup_presence_context(module) + "\n\n" + original
        return original
    module.build_runtime_context = build_runtime_context_with_startup_presence

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_startup_presence","description":"Read the authoritative Python startup presence data and selected display variables.","parameters":{"type":"object","properties":{"include_all":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_context_diagnostics","description":"Read endpoint-context and prompt-section diagnostics.","parameters":{"type":"object","properties":{"breakdown":{"type":"boolean"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_startup_presence", "get_context_diagnostics"})
    old_execute = module.execute_tool
    def execute_tool_with_presence(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_startup_presence": return module.get_startup_presence(**arguments)
        if name == "get_context_diagnostics": return module.get_context_diagnostics(**arguments)
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_presence

    old_doctor = module.doctor_report
    def doctor_with_presence():
        report = old_doctor()
        report["startup_presence"] = {
            "view": _load_startup_view(module)[1],
            "selected": [row.get("id") for row in _startup_presence_snapshot(module, include_all=False).get("selected_variables", [])],
        }
        report["endpoint_context"] = _detect_endpoint_context(module)
        return report
    module.doctor_report = doctor_with_presence

    old_main = module.main
    def main_with_presence_commands():
        original_input = builtins.input
        first_prompt = True
        def presence_input(prompt=""):
            nonlocal first_prompt
            if first_prompt:
                first_prompt = False
                try:
                    print(_render_startup_presence_panel(module), end="")
                except Exception as exc:
                    print(f"Startup presence unavailable: {type(exc).__name__}: {exc}")
            while True:
                value = original_input(prompt)
                if _presence_handle_command(module, value):
                    continue
                return value
        builtins.input = presence_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_presence_commands
    module._PRESENCE_MENU_DIAGNOSTICS_INSTALLED = True


def presence_menu_diagnostics_self_test(module) -> dict:
    crypto = _identity_crypto()
    original_encrypt = crypto.encrypt_text
    original_decrypt = crypto.decrypt_text
    original_safe_path = module.safe_memory_path
    original_db_connect = module.db_connect
    original_test_mode = getattr(module, "_IDENTITY_TEST_MODE", False)
    original_window = getattr(module, "_EMOTION_ACTIVE_TIME_WINDOW", None)
    original_volatile = getattr(module, "_STARTUP_VIEW_VOLATILE", None)
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    with tempfile.TemporaryDirectory(prefix="neatmemory-presence-") as folder:
        root = Path(folder)
        def fake_encrypt(text: str, *, entropy=None):
            raw = text.encode("utf-8")
            key = hashlib.sha256(bytes(entropy or b"test")).digest()
            cipher = bytes(b ^ key[i % len(key)] for i, b in enumerate(raw))
            return b"TESTENC1" + base64.b64encode(cipher)
        def fake_decrypt(payload: bytes, *, entropy=None):
            if not payload.startswith(b"TESTENC1"):
                raise RuntimeError("bad test cipher")
            cipher = base64.b64decode(payload[8:])
            key = hashlib.sha256(bytes(entropy or b"test")).digest()
            raw = bytes(b ^ key[i % len(key)] for i, b in enumerate(cipher))
            return raw.decode("utf-8")
        crypto.encrypt_text = fake_encrypt
        crypto.decrypt_text = fake_decrypt
        module.safe_memory_path = lambda filename: root / Path(str(filename)).name
        module.db_connect = lambda: test_db
        module._IDENTITY_TEST_MODE = True
        module._STARTUP_VIEW_VOLATILE = None
        try:
            module.initialize_database()
            _ensure_affective_schema(module)
            _ensure_somatic_schema(module)
            _ensure_identity_schema(module)
            _identity_bootstrap(module)
            _refresh_current_self_snapshot(module, reason="presence_self_test")
            boot = _startup_view_bootstrap(module)
            auto = _startup_presence_snapshot(module, include_all=True)
            update = _apply_startup_display_update(module, {
                "startup_display": ["CONNECTION", "TRUST", "HEART_RATE_BPM", "made_up_state", "TRUST"],
                "startup_display_comment": "These are the states I want visible when I wake.",
            }, provider="local", model="self-test")
            chosen = _startup_presence_snapshot(module, include_all=False)
            raw_file = (root / _STARTUP_VIEW_FILE).read_bytes()
            context = _startup_presence_context(module)
            verify = _identity_verify_report(module)
            checks = {
                "encrypted_startup_view_created": boot.get("created") and (root / _STARTUP_VIEW_FILE).exists(),
                "automatic_fallback_contains_heart_rate": any(row.get("id") == "HEART_RATE_BPM" for row in auto.get("selected_variables", [])),
                "all_30_emotions_available": len(auto.get("available_emotion_ids") or []) == 30,
                "all_18_somatic_states_available": len(auto.get("available_somatic_ids") or []) == 18,
                "llm_selection_applied": update.get("changed") and chosen.get("view_mode") == "chosen",
                "invalid_and_duplicate_ids_removed": [row.get("id") for row in chosen.get("selected_variables", [])] == ["CONNECTION", "TRUST", "HEART_RATE_BPM"],
                "comment_preserved": chosen.get("view_comment") == "These are the states I want visible when I wake.",
                "encrypted_payload_not_plaintext": b"states I want visible" not in raw_file,
                "pure_data_context_contains_update_contract": "startup_display" in context and "emotion_values" in context and "somatic_values" in context,
                "identity_verify_includes_startup": verify.get("ok") and "startup_view" in (verify.get("checks") or {}),
            }
            return {"ok": all(checks.values()), "checks": checks, "sample_presence": chosen}
        finally:
            crypto.encrypt_text = original_encrypt
            crypto.decrypt_text = original_decrypt
            module.safe_memory_path = original_safe_path
            module.db_connect = original_db_connect
            module._IDENTITY_TEST_MODE = original_test_mode
            module._EMOTION_ACTIVE_TIME_WINDOW = original_window
            module._STARTUP_VIEW_VOLATILE = original_volatile
            test_db.close()



