def _context_routing_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _context_routing_clean(value: object, limit: int = 1000) -> str:
    return str(value or "").replace("\x00", "").strip()[:limit]


def _context_routing_default_group(group_id: str) -> dict:
    definition = _CONTEXT_GROUP_DEFINITIONS[group_id]
    decorator_function = None
    decorator_phase = "off"
    decorator_display = "trace"
    decorator_values: list[str] = []
    # Error-only observers are protected defaults. They are silent during
    # successful operation and make failures visible to Assistant on the next
    # available context build without granting automatic repair authority.
    if group_id == "routing_control":
        decorator_function = "build_runtime_context"
        decorator_phase = "error"
        decorator_display = "context"
        decorator_values = [
            "diagnostic.error_type", "diagnostic.error_message", "diagnostic.duration_ms",
            "diagnostic.tokens_before", "diagnostic.last_successful_function",
            "derived.continuity_pressure",
        ]
    elif group_id == "runtime_truth":
        decorator_function = "run_chat_turn"
        decorator_phase = "error"
        decorator_display = "context"
        decorator_values = [
            "diagnostic.error_type", "diagnostic.error_message", "diagnostic.duration_ms",
            "diagnostic.tokens_before", "diagnostic.last_successful_function",
        ]
    elif group_id == "authority_rules":
        decorator_function = "execute_tool"
        decorator_phase = "error"
        decorator_display = "context"
        decorator_values = [
            "diagnostic.error_type", "diagnostic.error_message", "diagnostic.duration_ms",
            "diagnostic.last_successful_function",
        ]
    return {
        "group_id": group_id,
        "order": 1,
        "formula": "context.group_default_score",
        "token_cap": None,
        "minimum_score": None,
        "role": definition["role"],
        "provenance": "required",
        "decorator_function": decorator_function,
        "decorator_phase": decorator_phase,
        "decorator_display": decorator_display,
        "decorator_values": decorator_values,
    }


def _context_routing_default_groups() -> dict[str, dict]:
    return {group_id: _context_routing_default_group(group_id) for group_id in _CONTEXT_GROUP_DEFINITIONS}


def _context_routing_profile_version(profile_id: str, name: str, comment: str, groups: dict, *, version: int, actor: str) -> dict:
    return {
        "profile_id": profile_id,
        "version": int(version),
        "name": _context_routing_clean(name, 120) or "Context Routing Profile",
        "comment": _context_routing_clean(comment, 1200) or "Context group routing configuration.",
        "created_at": _context_routing_now(),
        "created_by": _context_routing_clean(actor, 120) or "Python",
        "groups": groups,
    }


