_REAR_MIRROR_VERSION = "2.2-manual-only-action-snake-tail"
_REAR_MIRROR_CONTEXT_MAX_CHARS = 1700
_REAR_MIRROR_ARGUMENT_MAX_CHARS = 700
_REAR_MIRROR_RESULT_MAX_CHARS = 900
_REAR_MIRROR_DETAILS_MAX_CHARS = 1000
_REAR_MIRROR_OBSERVATION_NAMES = {
    "read_action_snake", "search_action_snake", "get_action_snake", "action_snake_status",
    "get_rear_mirror", "rear_mirror_status", "mirror", "rear_mirror",
}
_REAR_MIRROR_NOISE_EXACT = {
    "chat.turn_start", "provider.request_start", "provider.request_heartbeat",
    "provider.heartbeat", "tool.call", "diagnostics.logbook_started",
}
_REAR_MIRROR_NOISE_FRAGMENTS = (
    "heartbeat", "preflight", "token_estimate", "token.estimate", "context_estimate",
    "retrieval.router_", "retrieval.selector_", "context.delivery_", "context_delivery_",
)


def _rm4_bound(value, max_chars: int):
    if value in (None, "", {}, []): return None
    try: raw=json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),default=str)
    except Exception: raw=str(value)
    if len(raw)<=max_chars: return value
    return {"bounded":True,"characters":len(raw),"sha256":hashlib.sha256(raw.encode("utf-8",errors="replace")).hexdigest(),"preview":raw[:max_chars]}


def _rm4_duration_ms(record: dict):
    for container_name in ("details","numeric_metrics"):
        container=record.get(container_name)
        if not isinstance(container,dict): continue
        for key in ("duration_ms","elapsed_ms"):
            value=container.get(key)
            try:
                if value not in (None,"") and not isinstance(value,bool): return round(float(value),3)
            except Exception: pass
    return None


def _rm4_parse_time(value):
    text=str(value or "").strip()
    if not text: return None
    try:
        dt=datetime.fromisoformat(text.replace("Z","+00:00"))
        if dt.tzinfo is None: dt=dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception: return None


def _rm4_freshness(record: dict) -> dict:
    dt=_rm4_parse_time(record.get("timestamp_utc") or record.get("timestamp"))
    if dt is None: return {"age_seconds":None,"age_human":"unknown"}
    age=max(0.0,(datetime.now(timezone.utc)-dt).total_seconds())
    if age<60: human=f"{int(age)}s ago"
    elif age<3600: human=f"{int(age//60)}m ago"
    elif age<86400: human=f"{int(age//3600)}h ago"
    else: human=f"{int(age//86400)}d ago"
    return {"age_seconds":round(age,3),"age_human":human}


def _rm4_is_observation(record: dict) -> bool:
    name=str(record.get("name") or "").casefold().strip()
    if name in _REAR_MIRROR_OBSERVATION_NAMES: return True
    if name.startswith("action_snake.") or name.startswith("rear_mirror."): return True
    return False


def _rm4_is_noise(record: dict) -> bool:
    if _rm4_is_observation(record): return True
    name=str(record.get("name") or "").casefold().strip()
    if name in _REAR_MIRROR_NOISE_EXACT: return True
    if any(fragment in name for fragment in _REAR_MIRROR_NOISE_FRAGMENTS): return True
    # Start/call markers describe an operation beginning, not the last completed action.
    if name.endswith(".start") or name.endswith("_start") or name.endswith(".call"): return True
    return False


def _rm4_is_substantive_action(record: dict) -> bool:
    if not isinstance(record,dict) or _rm4_is_noise(record): return False
    name=str(record.get("name") or "").casefold().strip()
    status=str(record.get("status") or "").casefold().strip()
    kind=str(record.get("kind") or "").casefold().strip()
    # Terminal outcomes are substantive regardless of whether they originated from
    # a tool wrapper, chat-turn hook, research/digest operation, or another runtime action.
    if any(token in name for token in ("complete","completed","failed","failure","error","timeout","blocked","cancelled","canceled")):
        return True
    if status in {"complete","completed","success","failed","failed_result","error","timeout","blocked","cancelled","canceled","partial"}:
        # Suppress generic diagnostics/system bookkeeping that merely announce state.
        if kind in {"diagnostic_event","system_log_event"} and any(token in name for token in ("started","initialized","status","snapshot","metric","telemetry")):
            return False
        return True
    return False


def _rm4_latest_substantive_action(module) -> dict:
    try: status=module.action_snake_status()
    except Exception as exc:
        return {"ok":False,"record":None,"empty_reason":"action_snake_unavailable","error":f"{type(exc).__name__}: {exc}","snake_status":{},"latest_retained_record":None}
    if not isinstance(status,dict) or not status.get("ok"):
        return {"ok":False,"record":None,"empty_reason":"action_snake_unavailable","error":str((status or {}).get("error") or "Action Snake status unavailable"),"snake_status":status if isinstance(status,dict) else {},"latest_retained_record":None}
    retained=int(status.get("retained_actions") or 0)
    try:
        receipt=module.read_action_snake(max(1,min(200,retained or 1)),include_payloads=True)
        actions=list(receipt.get("actions") or []) if isinstance(receipt,dict) and receipt.get("ok") else []
    except Exception as exc:
        return {"ok":False,"record":None,"empty_reason":"action_snake_read_failed","error":f"{type(exc).__name__}: {exc}","snake_status":status,"latest_retained_record":None}
    latest_action=actions[0] if actions else None
    if retained<=0 or not actions:
        return {"ok":True,"record":None,"empty_reason":"action_snake_empty","snake_status":status,"latest_retained_record":latest_action}
    skipped=0
    for candidate in actions:
        if not isinstance(candidate,dict): continue
        if not _rm4_is_substantive_action(candidate):
            skipped+=1; continue
        record=dict(candidate)
        try:
            opened=module.get_action_snake(record.get("action_ref") or record.get("action_id"))
            if isinstance(opened,dict) and opened.get("ok") and isinstance(opened.get("action"),dict): record=dict(opened.get("action"))
        except Exception: pass
        record["integrity_verified"]=True
        return {"ok":True,"record":record,"empty_reason":None,"snake_status":status,"latest_retained_record":latest_action,"skipped_newer_noise_events":skipped}
    return {"ok":True,"record":None,"empty_reason":"no_substantive_actions_retained","snake_status":status,"latest_retained_record":latest_action,"skipped_newer_noise_events":skipped}


def _rm4_project_record(record: dict) -> dict:
    result=record.get("result_snapshot")
    explicit_ok=result.get("ok") if isinstance(result,dict) and "ok" in result else None
    return {
        "action_ref":record.get("action_ref"),"action_id":record.get("action_id"),
        "kind":record.get("kind"),"event":record.get("name"),"status":record.get("status"),
        "action":str(record.get("summary") or "")[:900],
        "recorded_at":record.get("timestamp"),"recorded_at_utc":record.get("timestamp_utc"),
        "freshness":_rm4_freshness(record),"duration_ms":_rm4_duration_ms(record),
        "provider":record.get("provider"),"model":record.get("model"),"source":record.get("source"),
        "arguments":_rm4_bound(record.get("arguments"),_REAR_MIRROR_ARGUMENT_MAX_CHARS),
        "details":_rm4_bound(record.get("details"),_REAR_MIRROR_DETAILS_MAX_CHARS),
        "result_snapshot":_rm4_bound(result,_REAR_MIRROR_RESULT_MAX_CHARS),"explicit_ok":explicit_ok,
        "source_refs":list(record.get("source_refs") or [])[:20],"correlation_ids":_rm4_bound(record.get("correlation_ids"),700),
        "diagnostic_log_id":record.get("diagnostic_log_id"),"blackbox_event_id":record.get("blackbox_event_id"),
        "read_only_declared":record.get("read_only_declared"),"canonical_state_change_declared":record.get("canonical_state_change_declared"),
        "integrity_verified":bool(record.get("integrity_verified") is True),
    }


def _rm4_latest_any_projection(record):
    if not isinstance(record,dict): return None
    return {k:record.get(k) for k in ("action_ref","timestamp","kind","name","status","summary") if k in record}


def _rear_mirror_simple(module, *, full: bool=False) -> dict:
    tail=_rm4_latest_substantive_action(module)
    record=tail.get("record") if isinstance(tail,dict) else None
    snake_status=dict(tail.get("snake_status") or {}) if isinstance(tail,dict) else {}
    out={
        "version":_REAR_MIRROR_VERSION,
        "last_action":_rm4_project_record(record) if isinstance(record,dict) else None,
        "empty_reason":tail.get("empty_reason") if isinstance(tail,dict) else "unknown",
        "skipped_newer_noise_events":int(tail.get("skipped_newer_noise_events") or 0) if isinstance(tail,dict) else 0,
        "action_snake":{"retained_actions":snake_status.get("retained_actions"),"oldest_action_id":snake_status.get("oldest_action_id"),"newest_action_id":snake_status.get("newest_action_id"),"capacity":snake_status.get("capacity")},
        "authority":"Derived read-only view of the latest retained substantive Action Snake event. It reports the recorded action/outcome directly; telemetry/start/observation noise is skipped mechanically; Action Snake remains operational authority.",
        "persistent_writes":False,"model_calls":0,"web_calls":0,
    }
    if not record:
        out["latest_retained_record"]=_rm4_latest_any_projection(tail.get("latest_retained_record") if isinstance(tail,dict) else None)
        if isinstance(tail,dict) and tail.get("error"): out["error"]=tail.get("error")
    if full:
        out["full_action_snake_record"]=dict(record) if isinstance(record,dict) else None
        out["full_action_snake_status"]=snake_status
    return out


def _rear_mirror_simple_context(mirror: dict) -> str:
    action=mirror.get("last_action") or {}
    if not action:
        latest=mirror.get("latest_retained_record") or {}
        lines=["REAR MIRROR — ACTION SNAKE TAIL",f"Last substantive action: NONE ({mirror.get('empty_reason') or 'unknown'})"]
        if latest: lines.append(f"Newest retained record: {latest.get('action_ref') or '?'} | {latest.get('kind') or '?'} | {latest.get('name') or '?'} | {latest.get('status') or '?'}")
        lines.append("Authority: read-only operational view; do not infer an action that is not recorded.")
        return "\n".join(lines)[:_REAR_MIRROR_CONTEXT_MAX_CHARS]
    freshness=action.get("freshness") or {}
    lines=[
        "REAR MIRROR — LAST SUBSTANTIVE ACTION",
        f"{action.get('action_ref') or '?'} | {action.get('kind') or '?'} | {action.get('event') or '?'} | status={action.get('status') or '?'} | {freshness.get('age_human') or 'age unknown'}",
        f"Action: {action.get('action') or '(no summary recorded)'}",
        f"Recorded: {action.get('recorded_at') or action.get('recorded_at_utc') or '?'} | duration_ms={action.get('duration_ms')}",
    ]
    if action.get("arguments") not in (None,{},[]): lines.append("Arguments: "+json.dumps(_rm4_bound(action.get("arguments"),380),ensure_ascii=False,default=str,separators=(",",":")))
    if action.get("details") not in (None,{},[]): lines.append("Details: "+json.dumps(_rm4_bound(action.get("details"),450),ensure_ascii=False,default=str,separators=(",",":")))
    if action.get("result_snapshot") not in (None,{},[]): lines.append("Result: "+json.dumps(_rm4_bound(action.get("result_snapshot"),450),ensure_ascii=False,default=str,separators=(",",":")))
    lines.append("Authority: bounded projection of the encrypted Action Snake receipt; no semantic reconstruction.")
    return "\n".join(lines)[:_REAR_MIRROR_CONTEXT_MAX_CHARS]


def _install_simple_rear_mirror(module) -> None:
    if getattr(module,"_SIMPLE_REAR_MIRROR_INSTALLED",False): return
    module.get_rear_mirror=lambda full=False: _rear_mirror_simple(module,full=bool(full))
