_CAPSULE_MANIFEST_BASE_ROUNDS = 12
_CAPSULE_MANIFEST_MAX_ROUNDS = 24
_CAPSULE_MANIFEST_MAX_TOOLS = 33  # current largest advertised group; self-test prevents group/ceiling drift
_CAPSULE_MANIFEST_MAX_CARRY_ITEMS = 12
_CAPSULE_MANIFEST_MAX_CARRY_ITEM_CHARS = 8_000
_CAPSULE_MANIFEST_MAX_CARRY_TOTAL_CHARS = 24_000
_CAPSULE_MANIFEST_MAX_REFS = 32
_CAPSULE_EVIDENCE_CARD_MAX_CARDS = 24
