        projection_text=_cm_run_responses_loop(projection_mod,projection_backend,"F"*40000,[{"role":"user","content":"Inspect LOW coverage, then enrich BOOKS if useful."}],output_kwargs={})
        preq=projection_backend.client.responses.requests; ptrace=dict(getattr(projection_mod,"_CAPSULE_MANIFEST_LAST_TRACE",{}) or {})
