def _cm_benchmark_dir(module) -> Path:
    base=Path(getattr(module,"BENCHMARK_DIR",Path(getattr(module,"ROOT",Path.cwd()))/"benchmarks"/"receipts")); base.mkdir(parents=True,exist_ok=True); return base


def _cm_run_benchmark(module) -> dict:
    started=time.perf_counter(); result=_cm_synthetic_benchmark(module); run_id=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")+"-"+secrets.token_hex(4)
    receipt={"ok":bool(result.get("ok")),"benchmark":{"name":"capsule-manifest","version":_CAPSULE_MANIFEST_VERSION,"run_id":run_id,"finished_at":datetime.now(timezone.utc).isoformat(timespec="milliseconds"),"runtime_version":str(getattr(module,"NEATMEMORY_VERSION",BUNDLE_VERSION)),"kind":"zero-model-zero-network-explicit-decision-gate-assistant-packing-and-cumulative-provider-input-shape"},"summary":{"planned_cases":2,"completed_cases":2,"failed_cases":0 if result.get("ok") else 1,"model_calls":0,"web_calls":0,"duration_ms":round((time.perf_counter()-started)*1000,3),"cumulative_provider_input_reduction_percent":result.get("cumulative_provider_input_reduction_percent")},"result":result,"receipt_validation":{"status":"PASS" if result.get("ok") else "FAIL","errors":[] if result.get("ok") else ["capsule manifest benchmark failed"]}}
    path=_cm_benchmark_dir(module)/f"capsule-manifest-{run_id}.json"; path.write_text(json.dumps(receipt,ensure_ascii=False,indent=2),encoding="utf-8")
    return {"ok":receipt["ok"],"path":str(path),**{k:v for k,v in receipt.items() if k!="ok"}}


def _cm_compact_trace(trace: dict) -> dict:
    row=dict(trace or {})
    rounds=[]
    for x in list(row.get("rounds") or []):
        rounds.append({k:x.get(k) for k in ("phase","input_estimate_tokens","tools_tokens","tool_count") if k in x})
    decision=dict(row.get("decision") or {})
    return {
        "version":row.get("version") or _CAPSULE_MANIFEST_VERSION,
        "activated":bool(row.get("activated")),
        "domain":row.get("domain"),
        "rounds":rounds,
        "cumulative_provider_input_estimate_tokens":row.get("cumulative_provider_input_estimate_tokens"),
        "decision":{k:decision.get(k) for k in ("choice","reason","cumulative_provider_input_at_decision_tokens") if decision.get(k) is not None},
        "selected_tools":list(row.get("selected_tools") or []),
        "selected_tool_count":int(row.get("selected_tool_count") or len(list(row.get("selected_tools") or []))),
        "tool_count_ceiling":int(row.get("tool_count_ceiling") or _CAPSULE_MANIFEST_MAX_TOOLS),
        "budget":dict(row.get("budget") or {}),
        "exact_source_items_admitted":row.get("exact_source_items_admitted",0),
        "evidence_offload":{"events":row.get("evidence_offload_events",0),"offloaded_characters":row.get("evidence_offloaded_characters",0),"handle_characters":row.get("evidence_handle_characters",0)},
        "evidence_packing":{"gate_rounds":row.get("evidence_packing_gate_rounds",0),"reprompts":row.get("evidence_packing_reprompts",0),"packet_count":row.get("evidence_packet_count",0),"card_count":row.get("evidence_card_count",0),"decision_count":row.get("evidence_return_decision_count",0),"modes":dict(row.get("evidence_return_modes") or {}),"events_sealed":row.get("atomic_events_sealed",0)},
        "atomic":{"max_exact_calls_per_response":1,"round_budget":row.get("capsule_round_budget",0),"blocked_extra_exact_calls":row.get("atomic_exact_read_blocks",0),"unpacked_fallback_events":row.get("atomic_unpacked_fallback_events",0)},
        "return":{"characters":row.get("return_bundle_characters",0),"full_exact_baseline_characters":row.get("return_bundle_full_exact_baseline_characters",0),"saved_characters":row.get("return_bundle_saved_characters",0),"reduction_percent":row.get("return_bundle_reduction_percent",0.0)},
        "full_context_provider_rounds":row.get("full_context_provider_rounds",0),
        "capsule_rounds":row.get("capsule_rounds",0),
        "source_verification_progress_lease":{k:(row.get("source_verification_progress_lease") or {}).get(k) for k in ("version","stage","stage_label","stall_rounds","max_stall_rounds","observed_source_rounds","progress_renewals","fallback_due","fallback_reason","exact_source_opened") if k in (row.get("source_verification_progress_lease") or {})},
        "envelope_replan":{"count":row.get("capsule_envelope_replans",0),"last":dict(row.get("capsule_last_envelope_replan") or {})},
    }


def _cm_clip(text: object, limit: int=500) -> str:
    s=str(text or "")
    return s if len(s)<=limit else s[:max(0,limit-1)]+"…"


def _cm_compact_manifest(manifest: dict) -> dict:
    row=dict(manifest or {}); note=dict(row.get("travel_note") or {})
    cards=[]
    for c in list(row.get("evidence_cards") or []):
        cards.append({"card_id":c.get("card_id"),"label":_cm_clip(c.get("label"),160),"source_ref":c.get("source_ref"),"exact_excerpt":_cm_clip(c.get("exact_excerpt"),320),"evidence_handle":c.get("evidence_handle")})
    packets=[]
    for p in list(row.get("evidence_packets") or []):
        excerpts=[{"label":_cm_clip((x or {}).get("label"),100),"source_ref":(x or {}).get("source_ref"),"exact_excerpt":_cm_clip((x or {}).get("exact_excerpt"),220)} for x in list(p.get("excerpts") or [])[:4]]
        packets.append({"packet_id":p.get("packet_id"),"label":_cm_clip(p.get("label"),160),"evidence_handle":p.get("evidence_handle"),"excerpt_count":len(list(p.get("excerpts") or [])),"excerpts":excerpts})
    list_counts={k:len(list(note.get(k) or [])) for k in ("priorities","order","todo","do_not_forget","questions","return_with")}
    return {
        "version":_CAPSULE_MANIFEST_VERSION,
        "domain":row.get("domain"),
        "objective":_cm_clip(row.get("objective"),600),
        "selected_tools":list(row.get("selected_tools") or []),
        "selected_tool_count":len(list(row.get("selected_tools") or [])),
        "tool_count_ceiling":int(row.get("tool_count_ceiling") or _CAPSULE_MANIFEST_MAX_TOOLS),
        "carry_item_count":len(list(row.get("carry_items") or [])),
        "carry_ref_count":len(list(row.get("carry_refs") or [])),
        "travel_note":{"purpose":_cm_clip(note.get("purpose"),500),"commentary":_cm_clip(note.get("commentary"),500),"list_counts":list_counts,"do_not_forget":[_cm_clip(x,240) for x in list(note.get("do_not_forget") or [])[:3]]},
        "evidence_packet_count":len(packets),
        "evidence_packets":packets,
        "evidence_card_count":len(cards),
        "evidence_cards":cards,
        "evidence_return_decisions":[{"evidence_handle":x.get("evidence_handle"),"mode":x.get("mode"),"reason":_cm_clip(x.get("reason"),260)} for x in list(row.get("evidence_return_decisions") or [])],
        "budget":dict(row.get("budget") or {}),
        "ephemeral":row.get("ephemeral",True),
        "persistent_writes":row.get("persistent_writes",False),
    }


def _cm_handle_console(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()).casefold()
    if clean=="/benchmark capsule-manifest":
        print(json.dumps(_cm_run_benchmark(module),ensure_ascii=False,indent=2)); return True
    if clean in {"/capsule status","/capsule manifest status"}:
        raw_trace=dict(getattr(module,"_CAPSULE_MANIFEST_LAST_TRACE",{}) or {"version":_CAPSULE_MANIFEST_VERSION,"status":"not-yet-used"})
        print(json.dumps(_cm_compact_trace(raw_trace) if raw_trace.get("rounds") else raw_trace,ensure_ascii=False,indent=2)); return True
    if clean in {"/capsule status full","/capsule manifest status full"}:
        print(json.dumps(dict(getattr(module,"_CAPSULE_MANIFEST_LAST_TRACE",{}) or {"version":_CAPSULE_MANIFEST_VERSION,"status":"not-yet-used"}),ensure_ascii=False,indent=2)); return True
    if clean in {"/capsule last","/capsule manifest last"}:
        raw_manifest=dict(getattr(module,"_CAPSULE_MANIFEST_LAST",{}) or {"version":_CAPSULE_MANIFEST_VERSION,"status":"none"})
        print(json.dumps(_cm_compact_manifest(raw_manifest) if raw_manifest.get("domain") else raw_manifest,ensure_ascii=False,indent=2)); return True
    if clean in {"/capsule last full","/capsule manifest last full"}:
        print(json.dumps(dict(getattr(module,"_CAPSULE_MANIFEST_LAST",{}) or {"version":_CAPSULE_MANIFEST_VERSION,"status":"none"}),ensure_ascii=False,indent=2)); return True
    return False


def _install_capsule_manifest(module) -> None:
    if getattr(module,"_CAPSULE_MANIFEST_INSTALLED",False): return
    module.CAPSULE_MANIFEST_VERSION=_CAPSULE_MANIFEST_VERSION
    module._CAPSULE_MANIFEST_ACTIVE={}; module._CAPSULE_MANIFEST_LAST={}; module._CAPSULE_MANIFEST_LAST_TRACE={"version":_CAPSULE_MANIFEST_VERSION,"status":"not-yet-used"}
    module.capsule_manifest_self_test=lambda:capsule_manifest_self_test(module)
    module.run_capsule_manifest_benchmark=lambda:_cm_run_benchmark(module)

    arr=globals().get("_ONLINE_EVIDENCE_RESPONSE_TOOLS")
    if isinstance(arr,list):
        existing={_cm_tool_name(x) for x in arr if isinstance(x,dict)}
        schema=_cm_enter_schema()
        if schema["name"] not in existing: arr.append(schema)

    previous_online=globals().get("_ora_execute_evidence_tool")
    if callable(previous_online):
        def execute_with_capsule_note(mod,name,arguments):
            if str(name or "")=="capsule_note_update": return _cm_note_update(mod,dict(arguments or {}) if isinstance(arguments,dict) else {})
            if str(name or "")=="capsule_evidence_card_create": return _cm_evidence_card_create(mod,dict(arguments or {}) if isinstance(arguments,dict) else {})
            if str(name or "")=="capsule_evidence_packet_create": return _cm_evidence_packet_create(mod,dict(arguments or {}) if isinstance(arguments,dict) else {})
            if str(name or "")=="capsule_evidence_carry_full": return _cm_evidence_carry_full(mod,dict(arguments or {}) if isinstance(arguments,dict) else {})
            if str(name or "")=="capsule_evidence_leave_external": return _cm_evidence_leave_external(mod,dict(arguments or {}) if isinstance(arguments,dict) else {})
            return previous_online(mod,name,arguments)
        globals()["_ora_execute_evidence_tool"]=execute_with_capsule_note

    globals()["_ora_run_responses_book_loop"]=_cm_run_responses_loop

    original_main=module.main
    def main_with_capsule_manifest():
        original_input=builtins.input
        def wrapped_input(prompt=""):
            while True:
                raw=original_input(prompt)
                try:
                    if _cm_handle_console(module,raw): continue
                except Exception as exc:
                    print(f"Capsule Manifest command error: {type(exc).__name__}: {exc}"); continue
                return raw
        builtins.input=wrapped_input
        try: return original_main()
        finally: builtins.input=original_input
    module.main=main_with_capsule_manifest

    old_help=module.print_help
    def help_with_capsule_manifest(*args,**kwargs):
        result=old_help(*args,**kwargs)
        print("  /benchmark capsule-manifest             zero-model explicit decision-gate/packing/cumulative-input benchmark")
        print("  /capsule status                         compact last capsule token/evidence/return summary")
        print("  /capsule status full                    full packing-card/decision-gate diagnostic dump")
        print("  /capsule last                           compact last manifest/travel-note/evidence-packet/card snapshot")
        print("  /capsule last full                      full last manifest/travel-note/evidence-packet/card snapshot")
        return result
    module.print_help=help_with_capsule_manifest

    old_catalog=globals().get("_uv_benchmark_catalog")
    if callable(old_catalog) and not globals().get("_CM_BENCHMARK_CATALOG_WRAPPED"):
        def cm_catalog(mod):
            out=dict(old_catalog(mod)); out["capsule-manifest"]={"command":"/benchmark capsule-manifest","kind":"zero_model_zero_network","model_calls":0,"provider":"none","purpose":"Measure explicit Assistant capsule/full-context gating, multi-excerpt evidence packets, atomic per-event packing, adaptive round allowance, packing weights, and cumulative provider-input shape for repeated source navigation","runner_available":True}; return out
        globals()["_uv_benchmark_catalog"]=cm_catalog; globals()["_CM_BENCHMARK_CATALOG_WRAPPED"]=True

    guidance=("\n\nASSISTANT-DIRECTED CAPSULE MANIFEST — PACK YOUR OWN CONTEXT\n"
        "- One ordinary source-navigation/tool round may proceed in full context. Before ANY second source-navigation round, NeatMemory presents an explicit Capsule Decision Gate with updated current/cumulative weight.\n"
        "- At that gate, if you already have enough evidence, answer with no tool call. If you need more navigation, YOU must choose exactly one: enter_capsule_manifest(...) or stay_full_context(reason=...). Python will not choose for you.\n"
        "- stay_full_context requires your own reason why the full context is worth carrying. The reason is operational working state, not source evidence, and is recorded for diagnostics.\n"
        "- The current full-context request includes a CAPSULE PACKING VIEW with mechanical weights. YOU choose what crosses: domain, tool groups/individual tools, compact carry_items/refs, and your own travel note (purpose, commentary, priorities, order, todo, do-not-forget, questions, return-with).\n"
        "- Call enter_capsule_manifest ALONE to cross. Python measures the exact selected capsule. If it exceeds your target/hard budget, Python returns the weight and YOU repack; nothing is silently dropped.\n"
        "- Your travel note is your ephemeral working state. It is not source evidence. You may update it inside the capsule with capsule_note_update. Exact-source reads are ATOMIC: request at most ONE exact-source tool call per response. Read one -> inspect/pack -> then request the next. Never batch several exact reads. After inspection, use a multi-excerpt Evidence Packet when several distinct details/caveats from the same exact event matter; use a single Evidence Card for a simple excerpt; carry-full remains valid when surrounding context itself is necessary; external-only remains valid when the exact body need not return. Compact mode seals only after verified excerpts cover every exact source item. Python verifies binding/coverage/sequencing only and never chooses semantic importance.\n"
        "- Capsule round allowance is mechanical, not semantic: Python sizes it from the length of YOUR travel-note todo list, with a 12-round base and a 24-round hard ceiling. It does not invent tasks or decide which evidence deserves more rounds.\n"
        "- The capsule is read-only navigation by design. If you need a semantic/personal/state mutation, return to full context and use the established governed write surface.\n"
        "- Books are the first intended live route: normally carry only the book navigation/exact-read tools you judge necessary, exact source refs rather than broad raw text, and a short note reminding yourself what to verify. Web/Research/Chat can use the same manifest contract.\n")
    if "ASSISTANT-DIRECTED CAPSULE MANIFEST — PACK YOUR OWN CONTEXT" not in str(module.SYSTEM_PROMPT): module.SYSTEM_PROMPT=str(module.SYSTEM_PROMPT).rstrip()+guidance
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME; module._CAPSULE_MANIFEST_INSTALLED=True

