def _ci_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _ci_clamp(value: object) -> float:
    try:
        number = float(value)
    except Exception as exc:
        raise ValueError("Context intake quantity must be numeric from 0.0 to 1.0.") from exc
    if not math.isfinite(number) or number < 0.0 or number > 1.0:
        raise ValueError("Context intake quantity must be from 0.0 to 1.0.")
    return round(number, 4)


def _ci_default_state() -> dict:
    return {
        "kind": "neatmemory-context-intake-preferences",
        "schema_version": 1,
        "feature_version": _CONTEXT_INTAKE_VERSION,
        "revision": 1,
        "adaptive_relevance_boost": True,
        "category_amounts": dict(_CONTEXT_INTAKE_DEFAULTS),
        "group_overrides": {},
        "history": [{"at": _ci_now(), "actor": "Python", "action": "bootstrap", "reason": "Assistant feedback: less data by default, deeper detail on demand."}],
    }


def _ci_validate_state(payload: object) -> dict:
    if not isinstance(payload, dict) or payload.get("kind") != "neatmemory-context-intake-preferences":
        raise ValueError("Invalid context intake preference state.")
    categories = dict(_CONTEXT_INTAKE_DEFAULTS)
    for key, value in dict(payload.get("category_amounts") or {}).items():
        key = str(key).strip().casefold()
        if key in _CONTEXT_INTAKE_CATEGORIES:
            categories[key] = _ci_clamp(value)
    overrides = {}
    for key, value in dict(payload.get("group_overrides") or {}).items():
        key = str(key).strip().casefold().replace("-", "_")
        if key in _CONTEXT_GROUP_DEFINITIONS:
            overrides[key] = _ci_clamp(value)
    return {
        "kind": "neatmemory-context-intake-preferences",
        "schema_version": 1,
        "feature_version": _CONTEXT_INTAKE_VERSION,
        "revision": max(1, int(payload.get("revision") or 1)),
        "adaptive_relevance_boost": bool(payload.get("adaptive_relevance_boost", True)),
        "category_amounts": categories,
        "group_overrides": overrides,
        "history": list(payload.get("history") or [])[-200:],
    }


def _ci_read_state(module, *, force: bool = False) -> tuple[dict, str]:
    cached = getattr(module, "_CONTEXT_INTAKE_STATE_CACHE", None)
    if isinstance(cached, dict) and not force:
        return cached, "encrypted cache"
    if getattr(module, "_CONTEXT_INTAKE_TEST_NO_WRITE", False):
        state = _ci_validate_state(cached or _ci_default_state())
        module._CONTEXT_INTAKE_STATE_CACHE = state
        return state, "self-test cache"
    try:
        payload, status = _identity_read_encrypted_json(module, _CONTEXT_INTAKE_FILE, _CONTEXT_INTAKE_ENTROPY)
    except Exception:
        if os.name == "nt":
            raise
        state = _ci_default_state()
        module._CONTEXT_INTAKE_STATE_CACHE = state
        return state, "volatile defaults (DPAPI unavailable on non-Windows self-test/runtime)"
    if payload is None:
        state = _ci_default_state()
        try:
            _identity_write_encrypted_json(module, _CONTEXT_INTAKE_FILE, _CONTEXT_INTAKE_ENTROPY, state)
            status = "created encrypted defaults"
        except Exception:
            if os.name == "nt":
                raise
            status = "volatile defaults (DPAPI unavailable on non-Windows self-test/runtime)"
    else:
        state = _ci_validate_state(payload)
    module._CONTEXT_INTAKE_STATE_CACHE = state
    return state, status


def _ci_write_state(module, state: dict) -> dict:
    state = _ci_validate_state(state)
    state["revision"] = max(1, int(state.get("revision") or 1)) + 1
    if not getattr(module, "_CONTEXT_INTAKE_TEST_NO_WRITE", False):
        _identity_write_encrypted_json(module, _CONTEXT_INTAKE_FILE, _CONTEXT_INTAKE_ENTROPY, state)
    module._CONTEXT_INTAKE_STATE_CACHE = state
    return state


def _ci_category_for_group(group_id: str, text: str = "") -> str:
    first = next((line.strip().upper() for line in str(text).splitlines() if line.strip()), "")
    if "CUSTOM VARIABLES & EQUATIONS" in str(text).upper():
        return "metrics"
    if first.startswith("CURRENT EMOTION"):
        return "emotion"
    if first.startswith("CURRENT SOMATIC"):
        return "somatic"
    return _CONTEXT_INTAKE_GROUP_CATEGORY.get(str(group_id or "").casefold(), "other")


def _ci_query_relevance(category: str, query: str, routing_values: dict | None = None) -> float:
    values = routing_values or {}
    routed = max(float(values.get("context.group_relevance", 0.0) or 0.0), float(values.get("context.group_task_match", 0.0) or 0.0))
    terms = _CONTEXT_INTAKE_QUERY_TERMS.get(category) or set()
    query_terms = set(re.findall(r"[a-z0-9_]{3,}", str(query or "").casefold()))
    lexical = min(1.0, len(query_terms & terms) / 2.0) if terms else 0.0
    # Explicit category language is independent evidence and may always expand detail.
    # The generic router uses broad whole-group lexical overlap, so medium scores can be
    # produced by incidental shared words. Only a strong router result is allowed to
    # override Assistant's low baseline when category-specific language is absent. The 0.75
    # boundary matches the existing "directly relevant" correctness-floor threshold.
    routed_direct = routed if routed >= 0.75 else 0.0
    return max(0.0, min(1.0, max(routed_direct, lexical)))


def _ci_amount(module, category: str, *, group_id: str | None = None, query: str = "", routing_values: dict | None = None, locked: bool = False) -> dict:
    state, _ = _ci_read_state(module)
    category = category if category in _CONTEXT_INTAKE_CATEGORIES else "other"
    base = float((state.get("group_overrides") or {}).get(group_id, (state.get("category_amounts") or {}).get(category, _CONTEXT_INTAKE_DEFAULTS[category])))
    relevance = _ci_query_relevance(category, query, routing_values)
    boost = (1.0 - base) * relevance * 0.75 if state.get("adaptive_relevance_boost", True) else 0.0
    effective = min(1.0, base + boost)
    floor = float(_CONTEXT_INTAKE_FLOORS.get(str(group_id or ""), 0.0))
    if locked:
        floor = max(floor, 0.10)
    # Directly requested evidence/diagnostics should not be starved by a low baseline.
    if relevance >= 0.75 and category in {"research", "provenance", "system", "diagnostics", "emotion", "somatic", "metrics"}:
        floor = max(floor, 0.40)
    effective = max(floor, effective)
    return {"category": category, "baseline": round(base, 4), "relevance": round(relevance, 4), "adaptive_boost": round(boost, 4), "floor": round(floor, 4), "effective": round(effective, 4)}


def _ci_tokens(module, text: str) -> int:
    return _context_routing_token_estimate(module, text)


def _ci_compact_lines(module, text: str, target_tokens: int, marker: str) -> str:
    text = str(text or "")
    if _ci_tokens(module, text) <= target_tokens:
        return text
    lines = text.splitlines()
    if len(lines) <= 3:
        return text[:max(120, int(target_tokens * 3.2))].rstrip() + "\n" + marker
    head_budget = max(1, int(target_tokens * 0.72))
    tail_budget = max(1, target_tokens - head_budget - _ci_tokens(module, marker))
    head = []
    for line in lines:
        candidate = "\n".join(head + [line])
        if _ci_tokens(module, candidate) > head_budget:
            break
        head.append(line)
    tail = []
    for line in reversed(lines[len(head):]):
        candidate = "\n".join(reversed([line] + tail))
        if _ci_tokens(module, candidate) > tail_budget:
            break
        tail.insert(0, line)
    return "\n".join(head + [marker] + tail).strip()


def _ci_compact_emotion(module, text: str, amount: float, target_tokens: int) -> str:
    if amount >= 0.82:
        return _ci_compact_lines(module, text, target_tokens, "[emotion detail compacted by Assistant's intake preference]")
    lines = str(text).splitlines()
    metric_rows = []
    for line in lines:
        m = re.match(r"^([A-Z][A-Z0-9_]+): current=([0-9.]+); rest=([0-9.]+);.*trajectory=([^;]+)$", line.strip())
        if m:
            current, rest = float(m.group(2)), float(m.group(3))
            trajectory = m.group(4).strip().casefold()
            salience = abs(current-rest) + (0.08 if trajectory not in {"stable", "steady", "flat", "0"} else 0.0)
            metric_rows.append((salience, line))
    keep_count = max(2, min(len(metric_rows), int(round(2 + amount * 10))))
    chosen = {line for _, line in sorted(metric_rows, key=lambda row: row[0], reverse=True)[:keep_count]}
    out = []
    in_metrics = False
    skipped = 0
    for line in lines:
        if line.startswith("Canonical emotion metrics"):
            in_metrics = True; out.append(line); continue
        if in_metrics and re.match(r"^[A-Z][A-Z0-9_]+: current=", line.strip()):
            if line in chosen: out.append(line)
            else: skipped += 1
            continue
        if in_metrics and line.startswith("Allowed emotion IDs only:"):
            if skipped: out.append(f"[{skipped} near-baseline/lower-salience emotion rows omitted by intake preference]")
            in_metrics = False
            if amount >= 0.55: out.append(line)
            continue
        if amount < 0.45 and line.startswith("Emotion logbook continuity:"):
            out.append("Emotion logbook continuity: [available on demand]")
            break
        out.append(line)
    return _ci_compact_lines(module, "\n".join(out), target_tokens, "[additional emotion detail available on demand]")


def _ci_compact_somatic(module, text: str, amount: float, target_tokens: int) -> str:
    if amount >= 0.82:
        return _ci_compact_lines(module, text, target_tokens, "[somatic detail compacted by Assistant's intake preference]")
    lines = str(text).splitlines()
    metric_rows = []
    for line in lines:
        m = re.match(r"^([A-Z][A-Z0-9_]+): current=([^;]+); natural=([^;]+); rest=([^;]+);", line.strip())
        if m:
            def num(value):
                hit = re.search(r"-?[0-9]+(?:\.[0-9]+)?", value)
                return float(hit.group(0)) if hit else 0.0
            metric_rows.append((abs(num(m.group(2))-num(m.group(4))), line))
    keep_count = max(2, min(len(metric_rows), int(round(2 + amount * 8))))
    chosen = {line for _, line in sorted(metric_rows, key=lambda row: row[0], reverse=True)[:keep_count]}
    out=[]; in_metrics=False; skipped=0
    for line in lines:
        if line.startswith("Canonical somatic values"):
            in_metrics=True; out.append(line); continue
        if in_metrics and re.match(r"^[A-Z][A-Z0-9_]+: current=", line.strip()):
            if line in chosen: out.append(line)
            else: skipped += 1
            continue
        if in_metrics and line.startswith("Automatic cross-effects"):
            if skipped: out.append(f"[{skipped} near-rest/lower-salience somatic rows omitted by intake preference]")
            in_metrics=False; out.append(line); continue
        if amount < 0.45 and line.startswith("Allowed somatic IDs only:"):
            out.append("Allowed somatic IDs: [registry available on demand]")
            continue
        out.append(line)
    return _ci_compact_lines(module, "\n".join(out), target_tokens, "[additional somatic detail available on demand]")


def _ci_apply_group_quantity(module, group_id: str, group_text: str, query: str, routing_values: dict, *, locked: bool = False) -> dict:
    category = _ci_category_for_group(group_id, group_text)
    meta = _ci_amount(module, category, group_id=group_id, query=query, routing_values=routing_values, locked=locked)
    before = _ci_tokens(module, group_text)
    effective = float(meta["effective"])
    # The preference controls detail, not truth storage. Small groups are left intact.
    target = max(48 if not locked else 96, int(math.ceil(before * effective)))
    meta.update({"tokens_before": before, "target_tokens": target, "compacted": False})
    if not locked and effective <= 0.025 and meta["relevance"] < 0.20:
        meta["compacted"] = True; meta["tokens_after"] = 0
        return {"omit": True, "text": "", "meta": meta}
    if before <= max(120, target):
        meta["tokens_after"] = before
        return {"omit": False, "text": group_text, "meta": meta}
    if category == "emotion":
        compact = _ci_compact_emotion(module, group_text, effective, target)
    elif category == "somatic":
        compact = _ci_compact_somatic(module, group_text, effective, target)
    else:
        compact = _ci_compact_lines(module, group_text, target, f"[{category} detail compacted by Assistant's context intake preference; full data remains retrievable]")
    after = _ci_tokens(module, compact)
    meta["compacted"] = after < before
    meta["tokens_after"] = after
    return {"omit": False, "text": compact, "meta": meta}


def _ci_status(module) -> dict:
    state, status = _ci_read_state(module)
    return {
        "ok": True,
        "version": _CONTEXT_INTAKE_VERSION,
        "state_status": status,
        "revision": state["revision"],
        "adaptive_relevance_boost": state["adaptive_relevance_boost"],
        "category_amounts": dict(state["category_amounts"]),
        "group_overrides": dict(state["group_overrides"]),
        "correctness_floors": dict(_CONTEXT_INTAKE_FLOORS),
        "meaning": "Amounts are default detail baselines, not deletion percentages. Directly relevant turns may temporarily expand detail; protected correctness channels keep a minimum floor.",
    }


def _ci_set(module, target: str, amount: object, *, actor: str, reason: str) -> dict:
    state, _ = _ci_read_state(module)
    target = str(target or "").strip().casefold().replace("-", "_")
    value = _ci_clamp(amount)
    if target in _CONTEXT_INTAKE_CATEGORIES:
        state["category_amounts"][target] = value
        action = "set_category"
    elif target in _CONTEXT_GROUP_DEFINITIONS:
        state["group_overrides"][target] = value
        action = "set_group"
    else:
        raise ValueError("Unknown context intake category/group: " + target)
    state["history"].append({"at": _ci_now(), "actor": str(actor)[:120], "action": action, "target": target, "amount": value, "reason": str(reason or "")[:700]})
    state = _ci_write_state(module, state)
    return {"ok": True, "action": action, "target": target, "amount": value, "revision": state["revision"]}


def _ci_reset(module, target: str = "all", *, actor: str, reason: str) -> dict:
    state, _ = _ci_read_state(module)
    target = str(target or "all").strip().casefold().replace("-", "_")
    if target == "all":
        state["category_amounts"] = dict(_CONTEXT_INTAKE_DEFAULTS)
        state["group_overrides"] = {}
    elif target in _CONTEXT_INTAKE_CATEGORIES:
        state["category_amounts"][target] = _CONTEXT_INTAKE_DEFAULTS[target]
    elif target in _CONTEXT_GROUP_DEFINITIONS:
        state["group_overrides"].pop(target, None)
    else:
        raise ValueError("Unknown context intake category/group: " + target)
    state["history"].append({"at": _ci_now(), "actor": str(actor)[:120], "action": "reset", "target": target, "reason": str(reason or "")[:700]})
    state = _ci_write_state(module, state)
    return {"ok": True, "reset": target, "revision": state["revision"]}


def _ci_apply_updates(module, updates: object, *, provider: str, model: str) -> dict:
    if updates is None:
        return {"ok": True, "applied": [], "errors": []}
    rows = updates if isinstance(updates, list) else [updates]
    applied=[]; errors=[]
    for item in rows[:16]:
        if not isinstance(item, dict):
            errors.append({"error": "update must be an object"}); continue
        action = str(item.get("action") or "").strip().casefold().replace("-", "_")
        reason = str(item.get("reason") or "intentional context intake preference")[:700]
        actor = f"Assistant/{provider}/{model}"[:120]
        try:
            if action in {"set_category", "set_group", "set"}:
                result = _ci_set(module, str(item.get("target") or item.get("category") or item.get("group") or ""), item.get("amount"), actor=actor, reason=reason)
            elif action in {"reset", "reset_category", "reset_group"}:
                result = _ci_reset(module, str(item.get("target") or item.get("category") or item.get("group") or "all"), actor=actor, reason=reason)
            else:
                raise ValueError("Unsupported context intake action: " + (action or "<empty>"))
            applied.append({"action": action, "result": result})
        except Exception as exc:
            errors.append({"action": action, "error": f"{type(exc).__name__}: {exc}"})
    return {"ok": not errors, "applied": applied, "errors": errors}


def _ci_design_prompt(purpose: str) -> str:
    purpose = str(purpose or "Choose how much of each context category you generally want injected during ordinary conversation.").strip()
    return _CONTEXT_INTAKE_DESIGN_MARKER + "\n" + purpose


def _ci_design_contract(module) -> str:
    status = _ci_status(module)
    groups = sorted(_CONTEXT_GROUP_DEFINITIONS)
    return (
        "\n\nCONTEXT INTAKE DESIGN TRANSACTION — ASSISTANT CHOOSES DEFAULT ATTENTION QUANTITIES\n"
        "Choose only changes you genuinely want. Quantity 0.0..1.0 controls default injected detail, never deletes stored data. Relevance may temporarily expand a category; protected correctness channels retain a small floor.\n"
        "Categories: " + ", ".join(_CONTEXT_INTAKE_CATEGORIES) + "\n"
        "Groups available for optional overrides: " + ", ".join(groups) + "\n"
        "Current preferences: " + json.dumps(status["category_amounts"], sort_keys=True) + "\n"
        "Return EXACTLY one JSON object and no Markdown: {\"visible_response\":\"...\",\"context_intake_updates\":[{\"action\":\"set_category\",\"target\":\"emotion\",\"amount\":0.3,\"reason\":\"...\"}]} . "
        "A deliberate no-change design uses an empty context_intake_updates list. Do not change quantities merely to populate the transaction."
    )


def _ci_parse_design(answer: object) -> dict:
    raw = str(answer or "").strip()
    if raw.startswith("```"):
        lines=raw.splitlines(); lines=lines[1:]
        if lines and lines[-1].strip()=="```": lines=lines[:-1]
        raw="\n".join(lines).strip()
    try:
        payload=json.loads(raw)
    except Exception as exc:
        start=raw.find("{"); end=raw.rfind("}")
        if start < 0 or end <= start:
            raise ValueError("Context intake design was not returned as the required JSON transaction.") from exc
        payload=json.loads(raw[start:end+1])
    if not isinstance(payload, dict) or not isinstance(payload.get("context_intake_updates"), list):
        raise ValueError("Context intake design requires visible_response and context_intake_updates list.")
    visible=str(payload.get("visible_response") or "I made no separate explanation.").strip()[:6000]
    if len(payload["context_intake_updates"]) > 16:
        raise ValueError("Context intake design proposed too many changes at once.")
    return {"visible_response": visible, "context_intake_updates": payload["context_intake_updates"]}


def _ci_commit_design(module, answer: object, *, provider: str, model: str) -> str:
    try:
        payload=_ci_parse_design(answer)
    except Exception as exc:
        module._CONTEXT_INTAKE_LAST_DESIGN={"ok":False,"error":f"{type(exc).__name__}: {exc}","at":_ci_now()}
        return (str(answer or "").strip()+"\n\n[context intake commit: 0 applied — structured transaction missing/invalid; no preferences changed]").strip()
    result=_ci_apply_updates(module,payload["context_intake_updates"],provider=provider,model=model)
    applied=len(result.get("applied") or []); rejected=len(result.get("errors") or [])
    module._CONTEXT_INTAKE_LAST_DESIGN={"ok":not rejected,"applied":applied,"rejected":rejected,"at":_ci_now()}
    suffix=f"[context intake commit: {applied} applied"
    if rejected: suffix+=f", {rejected} rejected"
    if not payload["context_intake_updates"]: suffix+=", deliberate no-change design"
    suffix+="]"
    return payload["visible_response"]+"\n\n"+suffix


def _ci_preview(module, query: str) -> dict:
    base = getattr(module, "_CONTEXT_ROUTING_BASE_BUILD", None)
    if not callable(base):
        return {"ok":False,"error":"context routing base builder unavailable"}
    report = _context_route_text(module, base(query), query, include_text=False)
    return {"ok":True,"query":query,"tokens_before":report.get("tokens_before"),"tokens_after":report.get("tokens_after"),"groups":[{"group_id":row.get("group_id"),"tokens_before":row.get("tokens_before"),"tokens_after":row.get("tokens_after"),"intake":row.get("intake")} for row in report.get("groups",[])],"omitted":report.get("omitted",[])}


def selective_context_injection_self_test(module=None) -> dict:
    module = module or _load_memory()
    original_cache=getattr(module,"_CONTEXT_INTAKE_STATE_CACHE",None)
    original_flag=getattr(module,"_CONTEXT_INTAKE_TEST_NO_WRITE",False)
    checks={}
    try:
        module._CONTEXT_INTAKE_TEST_NO_WRITE=True
        module._CONTEXT_INTAKE_STATE_CACHE=_ci_default_state()
        checks["defaults_are_selective"]=_ci_status(module)["category_amounts"]["emotion"] < _ci_status(module)["category_amounts"]["continuity"]
        _ci_set(module,"emotion",0.2,actor="SelfTest",reason="compact emotion")
        state,_=_ci_read_state(module)
        checks["assistant_quantity_is_persistent_state"]=abs(state["category_amounts"]["emotion"]-0.2)<1e-9
        sample="CURRENT EMOTION DYNAMICS — PYTHON-CALCULATED INPUT\nProfile version: test\nCanonical emotion metrics after automatic movement toward each rest state:\n" + "\n".join(f"E{i}: current={0.1+i/100:.3f}; rest=0.100; half_life=10m; max_rise=0.1; max_fall=0.1; state=x; trajectory=stable" for i in range(20)) + "\nAllowed emotion IDs only:\n" + ",".join(f"E{i}" for i in range(20)) + "\nEmotion logbook continuity:\n[none]"
        routed=_ci_apply_group_quantity(module,"emotion",sample,"ordinary hello",{"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["emotion_matrix_compacts"]=bool(routed["meta"].get("compacted")) and routed["meta"]["tokens_after"] < routed["meta"]["tokens_before"]
        direct=_ci_apply_group_quantity(module,"emotion",sample,"how do you feel emotion state",{"context.group_relevance":0.9,"context.group_task_match":0.9},locked=False)
        checks["direct_question_expands_detail"]=direct["meta"]["effective"] > routed["meta"]["effective"]
        lexical_only=_ci_apply_group_quantity(module,"emotion",sample,"how were you feeling about our conversation yesterday?",{"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["lexical_relevance_expands_without_router"]=lexical_only["meta"]["relevance"] >= 0.5 and lexical_only["meta"]["effective"] > routed["meta"]["effective"]
        temporal_probe=_ci_amount(module,"continuity",group_id="active_continuity",query="how were you feeling about our conversation yesterday?",routing_values={"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["temporal_conversation_expands_continuity"]=temporal_probe["relevance"] >= 0.75 and temporal_probe["effective"] > temporal_probe["baseline"]
        router_only=_ci_apply_group_quantity(module,"emotion",sample,"ordinary hello",{"context.group_relevance":0.9,"context.group_task_match":0.9},locked=False)
        checks["router_relevance_expands_without_keywords"]=router_only["meta"]["relevance"] >= 0.9 and router_only["meta"]["effective"] > routed["meta"]["effective"]
        medium_router_noise=_ci_amount(module,"metrics",group_id="other_context",query="how were you feeling about our conversation yesterday?",routing_values={"context.group_relevance":0.5,"context.group_task_match":0.5},locked=False)
        checks["medium_generic_router_overlap_does_not_override_metrics_baseline"]=medium_router_noise["relevance"] == 0.0 and abs(medium_router_noise["effective"]-medium_router_noise["baseline"]) < 1e-9
        debug_probe=_ci_amount(module,"diagnostics",group_id="observer_hypotheses",query="why did the redigest fail and what does the diagnostic receipt show?",routing_values={"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["debug_probe_expands_from_explicit_terms"]=debug_probe["relevance"] >= 0.75 and debug_probe["effective"] >= 0.4
        debug_system_probe=_ci_amount(module,"system",group_id="runtime_truth",query="why did the redigest fail and what does the diagnostic receipt show?",routing_values={"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["debug_probe_expands_system_without_router"]=debug_system_probe["relevance"] >= 0.75 and debug_system_probe["effective"] > debug_system_probe["baseline"]
        continuity_probe=_ci_amount(module,"continuity",group_id="active_continuity",query="what did we decide about Assistant's continuity project?",routing_values={"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        personal_probe=_ci_amount(module,"personal_memory",group_id="personal_memory",query="what did we decide about Assistant's continuity project?",routing_values={"context.group_relevance":0.0,"context.group_task_match":0.0},locked=False)
        checks["continuity_probe_expands_without_router"]=continuity_probe["relevance"] >= 0.75 and continuity_probe["effective"] > continuity_probe["baseline"]
        checks["personal_probe_expands_without_router"]=personal_probe["relevance"] >= 0.75 and personal_probe["effective"] > personal_probe["baseline"]
        locked=_ci_amount(module,"system",group_id="runtime_truth",query="hello",routing_values={},locked=True)
        checks["correctness_floor_survives_low_preference"]=locked["effective"] >= _CONTEXT_INTAKE_FLOORS["runtime_truth"]
        design=json.dumps({"visible_response":"I want less routine diagnostics.","context_intake_updates":[{"action":"set_category","target":"diagnostics","amount":0.02,"reason":"keep routine conversation clean"}]})
        visible=_ci_commit_design(module,design,provider="self-test",model="python")
        checks["design_transaction_commits"]="context intake commit: 1 applied" in visible and abs(_ci_status(module)["category_amounts"]["diagnostics"]-0.02)<1e-9
        checks["derived_metrics_cannot_target_authoritative_roots"]=all(root in _CUSTOM_METRIC_RESERVED_ROOTS for root in {"emotion","somatic","session","memory","context"})
        authoritative_target_rejected=False
        try:
            _cm_define_equation(module,name="unsafe_writeback",output_ref="emotion.TRUST.derived",formula="1 + 1",purpose="must be rejected",semantic_role="interpretive",actor="SelfTest",provider="python",model="self-test",include_system=False)
        except Exception:
            authoritative_target_rejected=True
        checks["authoritative_writeback_rejected_by_parser"]=authoritative_target_rejected
        _cm_define_variable(module,ref="selftest.metric_input",value_type="float",description="Temporary semantic-role input",value_kind="user_supplied",context_mode="off",actor="SelfTest",provider="python",model="self-test")
        _cm_set_value(module,"selftest.metric_input",2.0,actor="SelfTest",provider="python",model="self-test",reason="semantic role test",recalculate=False,include_system=False)
        semantic_eq=_cm_define_equation(module,name="semantic_signal",output_ref="selftest.semantic_signal",formula="metric_input * 2",purpose="A deliberately interpretive self-test signal.",semantic_role="interpretive",context_mode="off",actor="SelfTest",provider="python",model="self-test",include_system=False)
        checks["semantic_role_persisted"]=(semantic_eq.get("equation") or {}).get("semantic_role")=="interpretive" and (semantic_eq.get("equation") or {}).get("authoritative_writeback") is False
        checks["semantic_roles_available"]=_CUSTOM_METRIC_SEMANTIC_ROLES=={"operational","descriptive","interpretive"}
        checks["metrics_refresh_before_injection"]=inspect.signature(_cm_context_packet).parameters["force_recalculate"].default is True and "freshness" in inspect.getsource(_cm_context_packet)
        malformed=_ci_commit_design(module,"I want less data but forgot the transaction.",provider="self-test",model="python")
        checks["no_preferences_inferred_from_prose"]="0 applied" in malformed
    finally:
        if original_cache is None:
            try: delattr(module,"_CONTEXT_INTAKE_STATE_CACHE")
            except Exception: pass
        else: module._CONTEXT_INTAKE_STATE_CACHE=original_cache
        module._CONTEXT_INTAKE_TEST_NO_WRITE=original_flag
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_CONTEXT_INTAKE_VERSION,"model_calls":0,"web_calls":0,"live_state_modified":False}


def _ci_help() -> str:
    return (
        "/context intake — Assistant-controlled default context quantities\n\n"
        "  /context intake | /context preferences\n"
        "  /context intake set <category|group> <0.0..1.0>\n"
        "  /context intake reset <category|group|all>\n"
        "  /context intake preview [query]\n"
        "  /context intake design [purpose]\n\n"
        "Amounts are detail baselines, not deletion. Relevant turns may temporarily expand detail. Full source data remains stored/retrievable; protected correctness channels keep a small minimum floor."
    )


def _ci_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    if lower in {"/context intake","/context preferences","/context intake status"}:
        print(json.dumps(_ci_status(module),ensure_ascii=False,indent=2)); return True
    if lower in {"/context intake help","/context preferences help"}:
        print(_ci_help()); return True
    if lower.startswith("/context intake set "):
        parts=clean[len("/context intake set "):].split()
        if len(parts)!=2:
            print("Use /context intake set <category|group> <0.0..1.0>"); return True
        try: print(json.dumps(_ci_set(module,parts[0],parts[1],actor="User",reason="manual context intake command"),ensure_ascii=False,indent=2))
        except Exception as exc: print(f"Context intake error: {type(exc).__name__}: {exc}")
        return True
    if lower.startswith("/context intake reset"):
        target=clean[len("/context intake reset"):].strip() or "all"
        try: print(json.dumps(_ci_reset(module,target,actor="User",reason="manual reset"),ensure_ascii=False,indent=2))
        except Exception as exc: print(f"Context intake error: {type(exc).__name__}: {exc}")
        return True
    if lower.startswith("/context intake preview"):
        query=clean[len("/context intake preview"):].strip() or "ordinary conversation"
        print(json.dumps(_ci_preview(module,query),ensure_ascii=False,indent=2)); return True
    return False


def _install_selective_context_injection(module) -> None:
    if getattr(module,"_SELECTIVE_CONTEXT_INJECTION_INSTALLED",False): return
    _ci_read_state(module)
    module.CONTEXT_INTAKE_VERSION=_CONTEXT_INTAKE_VERSION
    module.get_context_intake_preferences=lambda:_ci_status(module)
    module.apply_context_intake_updates=lambda updates,provider="unknown",model="unknown":_ci_apply_updates(module,updates,provider=provider,model=model)
    module.preview_context_intake=lambda query="ordinary conversation":_ci_preview(module,query)
    module.selective_context_injection_self_test=lambda:selective_context_injection_self_test(module)

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_context_intake_preferences","description":"Read Assistant's encrypted default context-detail quantities by category and optional group overrides.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"preview_context_intake","description":"Preview relevance-aware context quantities and token reductions for a query without exposing full private context.","parameters":{"type":"object","properties":{"query":{"type":"string"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_context_intake_preferences","preview_context_intake"})
    old_execute=module.execute_tool
    def execute_with_context_intake(name,arguments,seen,*args,**kwargs):
        if name=="get_context_intake_preferences": return module.get_context_intake_preferences()
        if name=="preview_context_intake": return module.preview_context_intake(**arguments)
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_with_context_intake

    # Design is transactional just like /metrics design. Assistant chooses; Python validates.
    old_local=module.run_local_turn
    def run_local_with_context_intake(backend,messages,query=None,*,allow_sticky=True):
        if query is None: return old_local(backend,messages,allow_sticky=allow_sticky)
        answer=old_local(backend,messages,query,allow_sticky=allow_sticky)
        if _CONTEXT_INTAKE_DESIGN_MARKER in str(query or ""):
            return _ci_commit_design(module,answer,provider="local",model=getattr(backend,"model_id","local"))
        return answer
    module.run_local_turn=run_local_with_context_intake
    old_online=module.run_online_chat_turn
    def run_online_with_context_intake(backend,messages,query):
        answer=old_online(backend,messages,query)
        if _CONTEXT_INTAKE_DESIGN_MARKER in str(query or ""):
            return _ci_commit_design(module,answer,provider="online",model=getattr(backend,"model_id","online"))
        return answer
    module.run_online_chat_turn=run_online_with_context_intake

    old_build=module.build_runtime_context
    def build_with_context_intake_design(query,*args,**kwargs):
        result=old_build(query,*args,**kwargs)
        if _CONTEXT_INTAKE_DESIGN_MARKER in str(query or ""):
            result += _mcp_tag_runtime_context(_ci_design_contract(module),"selective-context-injection","post_routing_context")
        return result
    module.build_runtime_context=build_with_context_intake_design

    old_main=module.main
    def main_with_context_intake_commands():
        previous=builtins.input
        def intake_input(prompt=""):
            while True:
                value=previous(prompt); compact=" ".join(str(value or "").strip().split()); lower=compact.casefold()
                if lower=="/context intake design" or lower.startswith("/context intake design "):
                    purpose=compact[len("/context intake design"):].strip()
                    return _ci_design_prompt(purpose)
                if _ci_handle_command(module,value): continue
                return value
        builtins.input=intake_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_context_intake_commands

    old_help=module.print_help
    def help_with_context_intake(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /context intake|preferences | /context intake set <category|group> <0..1> | reset <target|all>")
        print("  /context intake preview [query] | /context intake design [purpose]")
    module.print_help=help_with_context_intake

    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["selective-context-injection"]={"label":"Assistant-controlled selective context quantities, relevance expansion, compact affective views, semantic derived-signal labels, freshness, and no authoritative writeback","groups":("quick","critical","all"),"runner":"memory.selective_context_injection_self_test"}
    module.NEATMEMORY_VERSION=BUNDLE_VERSION
    module.RELEASE_NAME=RELEASE_NAME
    module._SELECTIVE_CONTEXT_INJECTION_INSTALLED=True


# ---------------------------------------------------------------------------
# NeatMemory 7.4.31 — Assistant-Controlled Context Composition
# ---------------------------------------------------------------------------
# This layer does not create a second truth store. Typed variables and safe
# equations remain authoritative in the existing custom-metric subsystem.
# Context composition stores only append-only, data-only presentation rules:
# whether/when a value is shown, detail level, priority, placement, label, and
# a restricted placeholder template. No rule can execute code or write back
# into emotion/somatic/session/memory/context authoritative namespaces.
_CONTEXT_COMPOSITION_VERSION = "1.1-assistant-controlled-context-panels"
_CONTEXT_COMPOSITION_DESIGN_MARKER = "[NEATMEMORY_CONTEXT_COMPOSITION_DESIGN]"
_CONTEXT_PANEL_DESIGN_MARKER = "[NEATMEMORY_CONTEXT_PANEL_DESIGN]"
_CONTEXT_COMPOSITION_VISIBILITY = {"always", "auto", "off"}
_CONTEXT_COMPOSITION_DETAIL = {"minimal", "compact", "normal", "full"}
_CONTEXT_COMPOSITION_PLACEMENTS = {"startup", "continuity", "emotion", "somatic", "research", "diagnostics", "metrics", "personal", "system", "custom"}
_CONTEXT_COMPOSITION_MAX_TERMS = 24
_CONTEXT_COMPOSITION_MAX_TEMPLATE = 360
_CONTEXT_COMPOSITION_MAX_LABEL = 120
_CONTEXT_COMPOSITION_MAX_VIEWS = 512
_CONTEXT_COMPOSITION_MAX_PANELS = 128
_CONTEXT_COMPOSITION_MAX_PANEL_MEMBERS = 32
_CONTEXT_COMPOSITION_MAX_PANEL_TEMPLATE = 1200
_CONTEXT_COMPOSITION_PANEL_LAYOUTS = {"lines", "bullets", "inline"}
_CONTEXT_COMPOSITION_PANEL_PLACEHOLDERS = {"title", "panel_ref", "items"}
_CONTEXT_COMPOSITION_ALLOWED_PLACEHOLDERS = {"label", "ref", "value", "unit", "unit_suffix", "role"}
_CONTEXT_COMPOSITION_PLACEMENT_HEADERS = {
    "startup": "STARTUP VIEW — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "continuity": "ACTIVE CONTINUITY — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "emotion": "CURRENT EMOTION — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "somatic": "CURRENT SOMATIC — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "research": "RESEARCH — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "diagnostics": "OBSERVER — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "metrics": "CUSTOM VARIABLES & EQUATIONS — ASSISTANT-COMPOSED VIEW",
    "personal": "RETRIEVED PERSONAL MEMORIES — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "system": "SELF-DESIGNED PERCEPTION PROFILE — CUSTOM METRIC COMPOSITION (DERIVED/NON-AUTHORITATIVE)",
    "custom": "CUSTOM VARIABLES & EQUATIONS — ASSISTANT-COMPOSED CUSTOM GROUP",
}


def _cc_ensure_schema(module) -> None:
    _cm_ensure_schema(module)
    with module.db_connect() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS custom_metric_context_views (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            view_id TEXT NOT NULL,
            version INTEGER NOT NULL,
            variable_id TEXT NOT NULL,
            variable_ref TEXT NOT NULL,
            visibility TEXT NOT NULL,
            detail_level TEXT NOT NULL,
            priority REAL NOT NULL,
            placement TEXT NOT NULL,
            display_label TEXT,
            display_template TEXT NOT NULL,
            conditions_json TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            provenance_json TEXT NOT NULL,
            definition_sha256 TEXT NOT NULL,
            UNIQUE(view_id, version)
        );
        CREATE INDEX IF NOT EXISTS idx_custom_metric_context_views_ref
            ON custom_metric_context_views(variable_ref, version DESC);
        CREATE INDEX IF NOT EXISTS idx_custom_metric_context_views_status
            ON custom_metric_context_views(status, row_id DESC);
        CREATE TRIGGER IF NOT EXISTS custom_metric_context_views_no_update
        BEFORE UPDATE ON custom_metric_context_views BEGIN
            SELECT RAISE(ABORT, 'custom metric context view history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_context_views_no_delete
        BEFORE DELETE ON custom_metric_context_views BEGIN
            SELECT RAISE(ABORT, 'custom metric context view history is append-only');
        END;
        CREATE TABLE IF NOT EXISTS custom_metric_context_panels (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            panel_id TEXT NOT NULL,
            version INTEGER NOT NULL,
            panel_ref TEXT NOT NULL,
            title TEXT NOT NULL,
            visibility TEXT NOT NULL,
            detail_level TEXT NOT NULL,
            priority REAL NOT NULL,
            placement TEXT NOT NULL,
            layout TEXT NOT NULL,
            panel_template TEXT NOT NULL,
            members_json TEXT NOT NULL,
            conditions_json TEXT NOT NULL,
            suppress_member_standalone INTEGER NOT NULL DEFAULT 1,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL,
            provider TEXT,
            model TEXT,
            provenance_json TEXT NOT NULL,
            definition_sha256 TEXT NOT NULL,
            UNIQUE(panel_id, version)
        );
        CREATE INDEX IF NOT EXISTS idx_custom_metric_context_panels_ref
            ON custom_metric_context_panels(panel_ref, version DESC);
        CREATE INDEX IF NOT EXISTS idx_custom_metric_context_panels_status
            ON custom_metric_context_panels(status, row_id DESC);
        CREATE TRIGGER IF NOT EXISTS custom_metric_context_panels_no_update
        BEFORE UPDATE ON custom_metric_context_panels BEGIN
            SELECT RAISE(ABORT, 'custom metric context panel history is append-only');
        END;
        CREATE TRIGGER IF NOT EXISTS custom_metric_context_panels_no_delete
        BEFORE DELETE ON custom_metric_context_panels BEGIN
            SELECT RAISE(ABORT, 'custom metric context panel history is append-only');
        END;
        """)


def _cc_view_id(ref: str) -> str:
    normalized=_cm_normalize_ref(ref)
    return "VIEW-" + hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:20].upper()


def _cc_clean_terms(values: object) -> list[str]:
    raw=values if isinstance(values,list) else ([values] if values else [])
    out=[]
    for item in raw:
        term=" ".join(str(item or "").strip().casefold().split())[:80]
        if term and term not in out:
            out.append(term)
        if len(out)>=_CONTEXT_COMPOSITION_MAX_TERMS:
            break
    return out


def _cc_validate_conditions(value: object, *, value_type: str | None = None) -> dict:
    raw=dict(value) if isinstance(value,dict) else {}
    allowed={"query_any","query_all","query_none","min_value","max_value"}
    unknown=set(raw)-allowed
    if unknown:
        raise ValueError("Unsupported context-view condition keys: " + ", ".join(sorted(unknown)))
    out={
        "query_any":_cc_clean_terms(raw.get("query_any")),
        "query_all":_cc_clean_terms(raw.get("query_all")),
        "query_none":_cc_clean_terms(raw.get("query_none")),
    }
    numeric_type=str(value_type or "").casefold() in _CUSTOM_METRIC_FORMULA_TYPES-{"boolean"}
    for key in ("min_value","max_value"):
        if raw.get(key) is not None:
            if not numeric_type:
                raise ValueError(f"{key} is only valid for numeric context-view variables.")
            val=float(raw[key])
            if not math.isfinite(val): raise ValueError(f"{key} must be finite.")
            out[key]=val
    if out.get("min_value") is not None and out.get("max_value") is not None and out["min_value"]>out["max_value"]:
        raise ValueError("Context-view min_value exceeds max_value.")
    return out


def _cc_validate_template(value: object) -> str:
    template=" ".join(str(value or "{label} = {value}{unit_suffix}").replace("\x00","").split())[:_CONTEXT_COMPOSITION_MAX_TEMPLATE]
    placeholders=set(re.findall(r"\{([a-z_][a-z0-9_]*)\}",template,flags=re.I))
    unknown={x.casefold() for x in placeholders}-_CONTEXT_COMPOSITION_ALLOWED_PLACEHOLDERS
    if unknown:
        raise ValueError("Unsupported display-template placeholders: " + ", ".join(sorted(unknown)))
    # Any unmatched brace is rejected so this remains data, never format code.
    stripped=re.sub(r"\{[a-z_][a-z0-9_]*\}","",template,flags=re.I)
    if "{" in stripped or "}" in stripped:
        raise ValueError("Display template contains unmatched/unsupported braces.")
    return template


def _cc_decode_row(row: object) -> dict | None:
    if not row: return None
    data=dict(row)
    data["conditions"]=_cm_parse_json(data.pop("conditions_json","{}"),{})
    data["provenance"]=_cm_parse_json(data.pop("provenance_json","{}"),{})
    return data


def _cc_latest_views(module, *, include_retired: bool=False) -> list[dict]:
    _cc_ensure_schema(module)
    with module.db_connect() as db:
        rows=db.execute("""
            SELECT v.* FROM custom_metric_context_views v
            JOIN (SELECT view_id,MAX(version) max_version FROM custom_metric_context_views GROUP BY view_id) latest
            ON latest.view_id=v.view_id AND latest.max_version=v.version
            ORDER BY v.priority DESC,v.variable_ref
        """).fetchall()
    decoded=[_cc_decode_row(row) for row in rows]
    return [row for row in decoded if row and (include_retired or row.get("status")=="active")]


def _cc_get_view(module, ref: str, *, include_retired: bool=True) -> dict | None:
    try: normalized=_cm_normalize_ref(ref)
    except Exception: return None
    view_id=_cc_view_id(normalized)
    for row in _cc_latest_views(module,include_retired=include_retired):
        if row.get("view_id")==view_id: return row
    return None


def _cc_set_view(module, ref: str, *, visibility: str="auto", detail_level: str="normal", priority: object=0.5,
                 placement: str="metrics", display_label: object=None, display_template: object=None,
                 conditions: object=None, actor: str="Assistant", provider: str="runtime", model: str="runtime",
                 reason: str="context_composition", status: str="active") -> dict:
    _cc_ensure_schema(module)
    definition=_cm_get_variable(module,ref,include_retired=False)
    if not definition: raise KeyError(f"Unknown active custom variable: {ref}")
    normalized=definition["ref"]
    visibility=str(visibility or "auto").strip().casefold()
    detail_level=str(detail_level or "normal").strip().casefold()
    placement=str(placement or "metrics").strip().casefold()
    status=str(status or "active").strip().casefold()
    if visibility not in _CONTEXT_COMPOSITION_VISIBILITY: raise ValueError("visibility must be always, auto, or off.")
    if detail_level not in _CONTEXT_COMPOSITION_DETAIL: raise ValueError("detail_level must be minimal, compact, normal, or full.")
    if placement not in _CONTEXT_COMPOSITION_PLACEMENTS: raise ValueError("Unsupported context-view placement.")
    if status not in {"active","retired"}: raise ValueError("Context-view status must be active or retired.")
    priority=float(priority)
    if not math.isfinite(priority) or priority<0.0 or priority>1.0: raise ValueError("priority must be from 0.0 to 1.0.")
    label=_cm_clean(display_label,_CONTEXT_COMPOSITION_MAX_LABEL) or normalized
    template=_cc_validate_template(display_template)
    clean_conditions=_cc_validate_conditions(conditions,value_type=definition.get("value_type"))
    body={"variable_ref":normalized,"visibility":visibility,"detail_level":detail_level,"priority":round(priority,4),"placement":placement,"display_label":label,"display_template":template,"conditions":clean_conditions,"status":status}
    digest=_cm_sha(body)
    view_id=_cc_view_id(normalized)
    provenance={"actor":_cm_clean(actor,120) or "unknown","provider":_cm_clean(provider,120) or "unknown","model":_cm_clean(model,200) or "unknown","reason":_cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),"presentation_only":True,"authoritative_writeback":False}
    with module.db_connect() as db:
        previous=db.execute("SELECT * FROM custom_metric_context_views WHERE view_id=? ORDER BY version DESC LIMIT 1",(view_id,)).fetchone()
        if previous:
            decoded=_cc_decode_row(previous)
            if str(decoded.get("definition_sha256") or "")==digest:
                return {"ok":True,"created":False,"idempotent":True,"view":decoded}
            version=int(decoded.get("version") or 0)+1
        else:
            count=int(db.execute("SELECT COUNT(DISTINCT view_id) FROM custom_metric_context_views").fetchone()[0])
            if count>=_CONTEXT_COMPOSITION_MAX_VIEWS: raise ValueError("Context composition view limit reached.")
            version=1
        created_at=_cm_now()
        db.execute("""INSERT INTO custom_metric_context_views(
            view_id,version,variable_id,variable_ref,visibility,detail_level,priority,placement,display_label,display_template,
            conditions_json,status,created_at,created_by,provider,model,provenance_json,definition_sha256
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (view_id,version,definition["variable_id"],normalized,visibility,detail_level,round(priority,4),placement,label,template,
         _cm_canonical(clean_conditions),status,created_at,_cm_clean(actor,120) or "unknown",_cm_clean(provider,120),_cm_clean(model,200),_cm_canonical(provenance),digest))
        row=db.execute("SELECT * FROM custom_metric_context_views WHERE view_id=? AND version=?",(view_id,version)).fetchone()
    return {"ok":True,"created":True,"view":_cc_decode_row(row)}


def _cc_reset_view(module, ref: str, *, actor: str="Assistant", provider: str="runtime", model: str="runtime", reason: str="context_view_reset") -> dict:
    current=_cc_get_view(module,ref,include_retired=False)
    if not current: return {"ok":True,"changed":False,"ref":_cm_normalize_ref(ref),"reason":"no active view"}
    result=_cc_set_view(module,ref,visibility=current.get("visibility","auto"),detail_level=current.get("detail_level","normal"),priority=current.get("priority",0.5),placement=current.get("placement","metrics"),display_label=current.get("display_label"),display_template=current.get("display_template"),conditions=current.get("conditions") or {},actor=actor,provider=provider,model=model,reason=reason,status="retired")
    return {"ok":True,"changed":True,"ref":current.get("variable_ref"),"retired_version":(result.get("view") or {}).get("version")}



def _cc_panel_id(ref: str) -> str:
    normalized=_cm_normalize_ref(ref)
    return "PANEL-" + hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:20].upper()


def _cc_validate_panel_template(value: object) -> str:
    template=str(value or "{title}\n{items}").replace("\x00","").strip()[:_CONTEXT_COMPOSITION_MAX_PANEL_TEMPLATE]
    placeholders=set(re.findall(r"\{([a-z_][a-z0-9_]*)\}",template,flags=re.I))
    unknown={x.casefold() for x in placeholders}-_CONTEXT_COMPOSITION_PANEL_PLACEHOLDERS
    if unknown:
        raise ValueError("Unsupported panel-template placeholders: " + ", ".join(sorted(unknown)))
    stripped=re.sub(r"\{[a-z_][a-z0-9_]*\}","",template,flags=re.I)
    if "{" in stripped or "}" in stripped:
        raise ValueError("Panel template contains unmatched/unsupported braces.")
    return template


def _cc_validate_panel_conditions(value: object) -> dict:
    raw=dict(value) if isinstance(value,dict) else {}
    unknown=set(raw)-{"query_any","query_all","query_none"}
    if unknown:
        raise ValueError("Unsupported context-panel condition keys: " + ", ".join(sorted(unknown)))
    return {"query_any":_cc_clean_terms(raw.get("query_any")),"query_all":_cc_clean_terms(raw.get("query_all")),"query_none":_cc_clean_terms(raw.get("query_none"))}


def _cc_validate_panel_members(module, members: object, *, panel_detail: str) -> list[dict]:
    if not isinstance(members,list) or not members:
        raise ValueError("A context panel requires at least one member variable/equation output.")
    if len(members)>_CONTEXT_COMPOSITION_MAX_PANEL_MEMBERS:
        raise ValueError("Context panel member limit exceeded.")
    clean=[]; seen=set()
    for index,raw in enumerate(members):
        item={"ref":raw} if isinstance(raw,str) else (dict(raw) if isinstance(raw,dict) else {})
        ref=_cm_normalize_ref(item.get("ref") or item.get("target") or "")
        definition=_cm_get_variable(module,ref,include_retired=False)
        if not definition:
            raise KeyError(f"Unknown active custom variable for panel member: {ref}")
        ref=definition["ref"]
        if ref in seen:
            raise ValueError(f"Duplicate context-panel member: {ref}")
        seen.add(ref)
        detail=str(item.get("detail_level") or item.get("detail") or panel_detail).strip().casefold()
        if detail not in _CONTEXT_COMPOSITION_DETAIL:
            raise ValueError("Panel member detail_level must be minimal, compact, normal, or full.")
        order=int(item.get("order",(index+1)*10))
        if order<0 or order>10000:
            raise ValueError("Panel member order must be from 0 to 10000.")
        label=_cm_clean(item.get("display_label") or item.get("label"),_CONTEXT_COMPOSITION_MAX_LABEL) or ref
        template=_cc_validate_template(item.get("display_template") or item.get("template") or "{label}: {value}{unit_suffix}")
        clean.append({"ref":ref,"display_label":label,"display_template":template,"detail_level":detail,"order":order})
    clean.sort(key=lambda x:(int(x.get("order",0)),x.get("ref","")))
    return clean


def _cc_decode_panel_row(row: object) -> dict | None:
    if not row: return None
    data=dict(row)
    data["members"]=_cm_parse_json(data.pop("members_json","[]"),[])
    data["conditions"]=_cm_parse_json(data.pop("conditions_json","{}"),{})
    data["provenance"]=_cm_parse_json(data.pop("provenance_json","{}"),{})
    data["suppress_member_standalone"]=bool(data.get("suppress_member_standalone"))
    return data


def _cc_latest_panels(module, *, include_retired: bool=False) -> list[dict]:
    _cc_ensure_schema(module)
    with module.db_connect() as db:
        rows=db.execute("""
            SELECT p.* FROM custom_metric_context_panels p
            JOIN (SELECT panel_id,MAX(version) max_version FROM custom_metric_context_panels GROUP BY panel_id) latest
            ON latest.panel_id=p.panel_id AND latest.max_version=p.version
            ORDER BY p.priority DESC,p.panel_ref
        """).fetchall()
    decoded=[_cc_decode_panel_row(row) for row in rows]
    return [row for row in decoded if row and (include_retired or row.get("status")=="active")]


def _cc_get_panel(module, ref: str, *, include_retired: bool=True) -> dict | None:
    try: normalized=_cm_normalize_ref(ref)
    except Exception: return None
    panel_id=_cc_panel_id(normalized)
    for row in _cc_latest_panels(module,include_retired=include_retired):
        if row.get("panel_id")==panel_id: return row
    return None


def _cc_set_panel(module, panel_ref: str, *, title: object=None, visibility: str="auto", detail_level: str="compact",
                  priority: object=0.5, placement: str="metrics", layout: str="lines", panel_template: object=None,
                  members: object=None, conditions: object=None, suppress_member_standalone: object=True,
                  actor: str="Assistant", provider: str="runtime", model: str="runtime", reason: str="context_panel_composition",
                  status: str="active") -> dict:
    _cc_ensure_schema(module)
    normalized=_cm_normalize_ref(panel_ref)
    visibility=str(visibility or "auto").strip().casefold(); detail_level=str(detail_level or "compact").strip().casefold()
    placement=str(placement or "metrics").strip().casefold(); layout=str(layout or "lines").strip().casefold(); status=str(status or "active").strip().casefold()
    if visibility not in _CONTEXT_COMPOSITION_VISIBILITY: raise ValueError("visibility must be always, auto, or off.")
    if detail_level not in _CONTEXT_COMPOSITION_DETAIL: raise ValueError("detail_level must be minimal, compact, normal, or full.")
    if placement not in _CONTEXT_COMPOSITION_PLACEMENTS: raise ValueError("Unsupported context-panel placement.")
    if layout not in _CONTEXT_COMPOSITION_PANEL_LAYOUTS: raise ValueError("layout must be lines, bullets, or inline.")
    if status not in {"active","retired"}: raise ValueError("Context-panel status must be active or retired.")
    priority=float(priority)
    if not math.isfinite(priority) or priority<0.0 or priority>1.0: raise ValueError("priority must be from 0.0 to 1.0.")
    clean_title=_cm_clean(title,_CONTEXT_COMPOSITION_MAX_LABEL) or normalized
    clean_template=_cc_validate_panel_template(panel_template)
    clean_members=_cc_validate_panel_members(module,members,panel_detail=detail_level)
    clean_conditions=_cc_validate_panel_conditions(conditions)
    suppress=bool(suppress_member_standalone)
    body={"panel_ref":normalized,"title":clean_title,"visibility":visibility,"detail_level":detail_level,"priority":round(priority,4),"placement":placement,"layout":layout,"panel_template":clean_template,"members":clean_members,"conditions":clean_conditions,"suppress_member_standalone":suppress,"status":status}
    digest=_cm_sha(body); panel_id=_cc_panel_id(normalized)
    provenance={"actor":_cm_clean(actor,120) or "unknown","provider":_cm_clean(provider,120) or "unknown","model":_cm_clean(model,200) or "unknown","reason":_cm_clean(reason,_CUSTOM_METRIC_MAX_REASON),"presentation_only":True,"authoritative_writeback":False,"member_definitions_unchanged":True}
    with module.db_connect() as db:
        previous=db.execute("SELECT * FROM custom_metric_context_panels WHERE panel_id=? ORDER BY version DESC LIMIT 1",(panel_id,)).fetchone()
        if previous:
            decoded=_cc_decode_panel_row(previous)
            if str(decoded.get("definition_sha256") or "")==digest:
                return {"ok":True,"created":False,"idempotent":True,"panel":decoded}
            version=int(decoded.get("version") or 0)+1
        else:
            count=int(db.execute("SELECT COUNT(DISTINCT panel_id) FROM custom_metric_context_panels").fetchone()[0])
            if count>=_CONTEXT_COMPOSITION_MAX_PANELS: raise ValueError("Context composition panel limit reached.")
            version=1
        created_at=_cm_now()
        db.execute("""INSERT INTO custom_metric_context_panels(
            panel_id,version,panel_ref,title,visibility,detail_level,priority,placement,layout,panel_template,members_json,conditions_json,
            suppress_member_standalone,status,created_at,created_by,provider,model,provenance_json,definition_sha256
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (panel_id,version,normalized,clean_title,visibility,detail_level,round(priority,4),placement,layout,clean_template,_cm_canonical(clean_members),_cm_canonical(clean_conditions),1 if suppress else 0,status,created_at,_cm_clean(actor,120) or "unknown",_cm_clean(provider,120),_cm_clean(model,200),_cm_canonical(provenance),digest))
        row=db.execute("SELECT * FROM custom_metric_context_panels WHERE panel_id=? AND version=?",(panel_id,version)).fetchone()
    return {"ok":True,"created":True,"panel":_cc_decode_panel_row(row)}


def _cc_reset_panel(module, ref: str, *, actor: str="Assistant", provider: str="runtime", model: str="runtime", reason: str="context_panel_reset") -> dict:
    current=_cc_get_panel(module,ref,include_retired=False)
    if not current: return {"ok":True,"changed":False,"panel_ref":_cm_normalize_ref(ref),"reason":"no active panel"}
    result=_cc_set_panel(module,current.get("panel_ref"),title=current.get("title"),visibility=current.get("visibility","auto"),detail_level=current.get("detail_level","compact"),priority=current.get("priority",0.5),placement=current.get("placement","metrics"),layout=current.get("layout","lines"),panel_template=current.get("panel_template"),members=current.get("members") or [],conditions=current.get("conditions") or {},suppress_member_standalone=current.get("suppress_member_standalone",True),actor=actor,provider=provider,model=model,reason=reason,status="retired")
    return {"ok":True,"changed":True,"panel_ref":current.get("panel_ref"),"retired_version":(result.get("panel") or {}).get("version")}


def _cc_panel_condition_eval(panel: dict, state: dict, query: str) -> dict:
    conditions=dict(panel.get("conditions") or {}); q=str(query or "").casefold()
    any_terms=list(conditions.get("query_any") or []); all_terms=list(conditions.get("query_all") or []); none_terms=list(conditions.get("query_none") or [])
    matched_any=(not any_terms) or any(term in q for term in any_terms); matched_all=all(term in q for term in all_terms); matched_none=not any(term in q for term in none_terms)
    explicit_terms=any_terms+all_terms; explicit_hits=sum(1 for term in explicit_terms if term in q)
    explicit_score=min(1.0,explicit_hits/max(1,len(explicit_terms))) if explicit_terms else 0.0
    variables={row.get("ref"):row for row in state.get("variables") or []}
    context_text=" ".join([str(panel.get("panel_ref") or ""),str(panel.get("title") or "")]+[f"{m.get('ref','')} {((variables.get(m.get('ref')) or {}).get('description') or '')}" for m in panel.get("members") or []])
    context_terms=set(re.findall(r"[a-z0-9_]{3,}",context_text.casefold().replace("."," "))); q_terms=set(re.findall(r"[a-z0-9_]{3,}",q))
    inferred=min(0.6,len(q_terms & context_terms)/max(1,min(4,len(q_terms)))) if q_terms else 0.0
    relevance=max(explicit_score,inferred); conditions_ok=matched_any and matched_all and matched_none
    has_conditions=bool(any_terms or all_terms or none_terms)
    visibility=str(panel.get("visibility") or "auto")
    if visibility=="off": show=False; reason="visibility_off"
    elif has_conditions: show=conditions_ok; reason="configured_rule" if show else "conditions_not_met"
    elif visibility=="always": show=True; reason="always_visible"
    else: show=relevance>0.0; reason="inferred_relevance" if show else "no_relevance"
    return {"ok":bool(show),"reason":reason,"relevance":round(relevance,4),"query_any":matched_any,"query_all":matched_all,"query_none":matched_none,"has_conditions":has_conditions}


def _cc_render_panel(panel: dict, state: dict, roles: dict[str,str], *, include_values: bool) -> dict:
    variables={row.get("ref"):row for row in state.get("variables") or [] if row.get("status")=="active" and row.get("current")}
    member_rows=[]
    for member in panel.get("members") or []:
        row=variables.get(member.get("ref"))
        if not row: continue
        role=roles.get(str(row.get("ref")),"descriptive" if row.get("value_kind")!="calculated" else "legacy_unspecified")
        view={"display_label":member.get("display_label") or row.get("ref"),"display_template":member.get("display_template") or "{label}: {value}{unit_suffix}"}
        display=_cc_render_template(view,row,role,expose_value=include_values)
        entry={"ref":row.get("ref"),"display":display,"detail_level":member.get("detail_level") or panel.get("detail_level"),"semantic_role":role,"order":member.get("order",0)}
        if include_values: entry["value"]=(row.get("current") or {}).get("value")
        detail=str(entry.get("detail_level") or "compact")
        if detail in {"compact","normal","full"}: entry.update({"unit":row.get("unit"),"value_kind":(row.get("current") or {}).get("value_kind")})
        if detail in {"normal","full"}: entry.update({"confidence":(row.get("current") or {}).get("confidence"),"recorded_at":(row.get("current") or {}).get("recorded_at"),"type":row.get("value_type")})
        if detail=="full":
            eq=next((e for e in state.get("equations") or [] if e.get("status")=="active" and e.get("output_ref")==row.get("ref")),None)
            entry["equation"]={"equation_ref":eq.get("equation_ref"),"formula":eq.get("formula"),"purpose":eq.get("purpose"),"input_refs":(eq.get("validation") or {}).get("input_refs") or [],"authoritative_writeback":False} if eq else None
        member_rows.append(entry)
    layout=str(panel.get("layout") or "lines")
    displays=[str(x.get("display") or "") for x in member_rows]
    if layout=="inline": items=" | ".join(displays)
    elif layout=="bullets": items="\n".join("- "+x for x in displays)
    else: items="\n".join(displays)
    rendered=str(panel.get("panel_template") or "{title}\n{items}")
    replacements={"title":str(panel.get("title") or panel.get("panel_ref") or ""),"panel_ref":str(panel.get("panel_ref") or ""),"items":items}
    for key,val in replacements.items(): rendered=rendered.replace("{"+key+"}",val)
    return {"panel_ref":panel.get("panel_ref"),"title":panel.get("title"),"display":rendered,"members":member_rows,"member_refs":[x.get("ref") for x in member_rows],"layout":layout,"visibility":panel.get("visibility"),"detail_level":panel.get("detail_level"),"priority":panel.get("priority"),"placement":panel.get("placement"),"suppress_member_standalone":bool(panel.get("suppress_member_standalone")),"configured":True}


def _cc_compose_panels(module, state: dict, query: str, *, include_values: bool) -> dict:
    roles=_cc_semantic_role_map(state); considered=[]; selected=[]
    for panel in _cc_latest_panels(module,include_retired=False):
        cond=_cc_panel_condition_eval(panel,state,query)
        base=float(panel.get("priority",0.5) or 0.0); effective=min(1.0,base+0.25*float(cond.get("relevance",0.0)))
        item={"panel_ref":panel.get("panel_ref"),"selected":bool(cond.get("ok")),"reason":cond.get("reason"),"visibility":panel.get("visibility"),"detail_level":panel.get("detail_level"),"priority":round(base,4),"effective_priority":round(effective,4),"placement":panel.get("placement"),"layout":panel.get("layout"),"condition":cond,"configured":True}
        considered.append(item)
        if not item["selected"]: continue
        rendered=_cc_render_panel(panel,state,roles,include_values=include_values)
        if not rendered.get("members"):
            item["selected"]=False; item["reason"]="no_active_members"; continue
        selected.append({**item,**rendered})
    selected.sort(key=lambda x:(x.get("effective_priority",0),x.get("panel_ref","")),reverse=True)
    selected=selected[:16]
    suppressed=set()
    for panel in selected:
        if panel.get("suppress_member_standalone"):
            suppressed.update(str(x) for x in panel.get("member_refs") or [] if x)
    return {"selected":selected,"considered":considered,"suppressed_refs":suppressed}


def _cc_panel_status(module) -> dict:
    panels=_cc_latest_panels(module,include_retired=False)
    return {"ok":True,"version":_CONTEXT_COMPOSITION_VERSION,"panel_count":len(panels),"panels":[{k:p.get(k) for k in ("panel_ref","title","version","visibility","detail_level","priority","placement","layout","panel_template","members","conditions","suppress_member_standalone","created_by","provenance")} for p in panels],"meaning":"Panels group existing variables/equation outputs for presentation only. Members and authoritative source state are unchanged."}


def _cc_panel_preview(module, query: str) -> dict:
    state=_cm_state(module,recalculate=True,include_system=True); packet=_cc_compose_panels(module,state,query,include_values=False)
    return {"ok":True,"version":_CONTEXT_COMPOSITION_VERSION,"query":str(query or "")[:500],"selected_count":len(packet.get("selected") or []),"selected":[{k:x.get(k) for k in ("panel_ref","title","placement","visibility","detail_level","priority","effective_priority","layout","display","member_refs","suppress_member_standalone")} for x in packet.get("selected") or []],"not_selected":[{k:x.get(k) for k in ("panel_ref","reason","placement","visibility","priority","condition")} for x in packet.get("considered") or [] if not x.get("selected")],"preview_exposes_values":False,"authoritative_writeback":False}

def _cc_semantic_role_map(state: dict) -> dict[str,str]:
    out={}
    for eq in state.get("equations") or []:
        if eq.get("status")=="active": out[str(eq.get("output_ref"))]=str(eq.get("semantic_role") or "legacy_unspecified")
    return out


def _cc_condition_eval(view: dict, row: dict, query: str) -> dict:
    conditions=dict(view.get("conditions") or {})
    q=str(query or "").casefold()
    any_terms=list(conditions.get("query_any") or [])
    all_terms=list(conditions.get("query_all") or [])
    none_terms=list(conditions.get("query_none") or [])
    matched_any=(not any_terms) or any(term in q for term in any_terms)
    matched_all=all(term in q for term in all_terms)
    matched_none=not any(term in q for term in none_terms)
    current=(row.get("current") or {}).get("value")
    threshold_ok=True
    if conditions.get("min_value") is not None:
        try: threshold_ok=threshold_ok and float(current)>=float(conditions["min_value"])
        except Exception: threshold_ok=False
    if conditions.get("max_value") is not None:
        try: threshold_ok=threshold_ok and float(current)<=float(conditions["max_value"])
        except Exception: threshold_ok=False
    explicit_terms=any_terms+all_terms
    explicit_hits=sum(1 for term in explicit_terms if term in q)
    explicit_score=min(1.0, explicit_hits/max(1,len(explicit_terms))) if explicit_terms else 0.0
    ref_terms=set(re.findall(r"[a-z0-9_]{3,}",str(row.get("ref") or "").casefold().replace("."," ")))
    desc_terms=set(re.findall(r"[a-z0-9_]{3,}",str(row.get("description") or "").casefold()))
    q_terms=set(re.findall(r"[a-z0-9_]{3,}",q))
    inferred=min(0.6,len(q_terms & (ref_terms|desc_terms))/max(1,min(4,len(q_terms)))) if q_terms else 0.0
    relevance=max(explicit_score,inferred)
    ok=matched_any and matched_all and matched_none and threshold_ok
    return {"ok":ok,"relevance":round(relevance,4),"query_any":matched_any,"query_all":matched_all,"query_none":matched_none,"threshold":threshold_ok}


def _cc_inherited_view(row: dict) -> dict:
    mode=str(row.get("context_mode") or "auto")
    return {"view_id":None,"version":0,"variable_ref":row.get("ref"),"visibility":mode if mode in _CONTEXT_COMPOSITION_VISIBILITY else "auto","detail_level":"normal","priority":0.65 if mode=="always" else 0.5,"placement":"metrics","display_label":row.get("ref"),"display_template":"{label} = {value}{unit_suffix}","conditions":{},"status":"inherited","configured":False}


def _cc_render_template(view: dict, row: dict, role: str, *, expose_value: bool=True) -> str:
    current=row.get("current") or {}
    value=current.get("value")
    if expose_value:
        if isinstance(value,float): value_text=f"{value:.6g}"
        else: value_text=str(value)
    else:
        value_text="[hidden]"
    unit=str(row.get("unit") or "")
    values={"label":str(view.get("display_label") or row.get("ref") or ""),"ref":str(row.get("ref") or ""),"value":value_text,"unit":unit,"unit_suffix":(" "+unit) if unit else "","role":role}
    text=str(view.get("display_template") or "{label} = {value}{unit_suffix}")
    for key,val in values.items(): text=text.replace("{"+key+"}",val)
    return text


def _cc_compose(module, query: str, *, force_recalculate: bool=True, include_values: bool=True) -> dict:
    state=_cm_state(module,recalculate=force_recalculate,include_system=True)
    active_views={row["variable_ref"]:row for row in _cc_latest_views(module,include_retired=False)}
    roles=_cc_semantic_role_map(state)
    panel_packet=_cc_compose_panels(module,state,query,include_values=include_values)
    suppressed_refs=set(panel_packet.get("suppressed_refs") or set())
    considered=[]
    selected=[]
    for row in state.get("variables") or []:
        if row.get("status")!="active" or not row.get("current"): continue
        view=dict(active_views.get(row.get("ref")) or _cc_inherited_view(row))
        view["configured"]=row.get("ref") in active_views
        visibility=str(view.get("visibility") or "auto")
        cond=_cc_condition_eval(view,row,query)
        # Explicit off is absolute. Always/auto still obey explicit conditions if
        # Assistant supplied any; inherited auto without conditions preserves 7.4.30 behavior.
        has_conditions=any(bool(x) for x in (view.get("conditions") or {}).values())
        show=visibility!="off" and (cond["ok"] if has_conditions else True)
        suppressed=row.get("ref") in suppressed_refs
        if suppressed: show=False
        base_priority=float(view.get("priority",0.5) or 0.0)
        effective_priority=min(1.0,base_priority+0.25*float(cond.get("relevance",0.0)))
        reason="suppressed_by_selected_panel" if suppressed else ("visibility_off" if visibility=="off" else ("conditions_not_met" if not show else ("configured_rule" if view.get("configured") else "inherited_metric_context_mode")))
        item={"ref":row.get("ref"),"selected":bool(show),"reason":reason,"visibility":visibility,"detail_level":view.get("detail_level"),"priority":round(base_priority,4),"effective_priority":round(effective_priority,4),"placement":view.get("placement"),"configured":bool(view.get("configured")),"condition":cond,"semantic_role":roles.get(str(row.get("ref")),"descriptive" if row.get("value_kind")!="calculated" else "legacy_unspecified")}
        considered.append(item)
        if not show: continue
        current=row.get("current") or {}
        selected.append({**item,"row":row,"view":view,"recorded_at":str(current.get("recorded_at") or "")})
    selected.sort(key=lambda x:(x["effective_priority"],x["recorded_at"],x["ref"]),reverse=True)
    selected=selected[:_CUSTOM_METRIC_MAX_CONTEXT_VARIABLES]
    rendered=[]
    for item in selected:
        row=item["row"]; view=item["view"]; role=item["semantic_role"]; current=row.get("current") or {}
        entry={"ref":row.get("ref"),"display":_cc_render_template(view,row,role,expose_value=include_values),"placement":item["placement"],"detail_level":item["detail_level"],"priority":item["priority"],"effective_priority":item["effective_priority"],"visibility":item["visibility"],"semantic_role":role,"configured":item["configured"]}
        if include_values: entry["value"]=current.get("value")
        detail=item["detail_level"]
        if detail in {"compact","normal","full"}: entry.update({"unit":row.get("unit"),"value_kind":current.get("value_kind")})
        if detail in {"normal","full"}: entry.update({"confidence":current.get("confidence"),"recorded_at":current.get("recorded_at"),"type":row.get("value_type")})
        if detail=="full":
            eq=next((e for e in state.get("equations") or [] if e.get("status")=="active" and e.get("output_ref")==row.get("ref")),None)
            entry.update({"description":row.get("description"),"derived_by":row.get("derived_by"),"equation":({"equation_ref":eq.get("equation_ref"),"formula":eq.get("formula"),"purpose":eq.get("purpose"),"input_refs":(eq.get("validation") or {}).get("input_refs") or [],"authoritative_writeback":False} if eq else None)})
        rendered.append(entry)
    return {"ok":True,"version":_CONTEXT_COMPOSITION_VERSION,"computed_at":_cm_now(),"query":str(query or "")[:500],"selected":rendered,"selected_count":len(rendered),"considered":considered,"configured_view_count":len(active_views),"panels_selected":panel_packet.get("selected") or [],"panels_selected_count":len(panel_packet.get("selected") or []),"panels_considered":panel_packet.get("considered") or [],"configured_panel_count":len(_cc_latest_panels(module,include_retired=False)),"freshness":"recalculated_before_injection" if force_recalculate else "caller_controlled","authoritative_writeback":False,"arbitrary_code_execution":False}


def _cc_context_packet(module, *, query: str="", force_recalculate: bool=True) -> dict:
    packet=_cc_compose(module,query,force_recalculate=force_recalculate,include_values=True)
    variables=[]
    for item in packet.get("selected") or []:
        variables.append({k:item.get(k) for k in ("ref","value","unit","value_kind","confidence","recorded_at","visibility","detail_level","priority","effective_priority","placement","semantic_role","configured","display") if k in item})
    panels=[]
    for panel in packet.get("panels_selected") or []:
        panels.append({k:panel.get(k) for k in ("panel_ref","title","display","placement","detail_level","priority","effective_priority","layout","member_refs","suppress_member_standalone")})
    return {"version":_CUSTOM_METRICS_VERSION,"composition_version":_CONTEXT_COMPOSITION_VERSION,"computed_at":packet.get("computed_at"),"variables":variables,"equations":[],"recalculation":{"ok":True},"variable_count_total":len(packet.get("considered") or []),"equation_count_total":len(_cm_latest_equations(module)),"context_truncated":packet.get("selected_count",0)<sum(1 for x in packet.get("considered") or [] if x.get("selected")),"freshness":packet.get("freshness"),"composition":{"configured_view_count":packet.get("configured_view_count"),"configured_panel_count":packet.get("configured_panel_count"),"panels":panels,"authoritative_writeback":False}}


def _cc_prompt_context(module, query: str) -> str:
    # Preserve the mature /metrics design workspace exactly; composition is a
    # presentation layer and must not weaken metric/equation creation contracts.
    if _CUSTOM_METRIC_DESIGN_MARKER in str(query or ""):
        return _CC_ORIGINAL_CM_PROMPT_CONTEXT(module,query)
    try: packet=_cc_compose(module,query,force_recalculate=True,include_values=True)
    except Exception as exc:
        return "CUSTOM VARIABLES & EQUATIONS — CONTEXT COMPOSITION ERROR\n"+f"{type(exc).__name__}: {exc}"
    try:
        if getattr(module,"_CONTEXT_ARCHITECTURE_MAINTENANCE_INSTALLED",False):
            # Adaptive retrieval renders LOW/MID/HIGH candidates before one is selected.
            # Cache candidate composition here, but do not count it as exposure yet.
            # Exactly one selected packet is recorded after the completed Assistant turn.
            level=str(getattr(module,"_DOMAIN_ACTIVE_LEVEL",None) or "").strip().casefold()
            if level in {"low","mid","high"}:
                packets=getattr(module,"_CONTEXT_ARCH_PACKETS_BY_LEVEL",None)
                if not isinstance(packets,dict):
                    packets={}; module._CONTEXT_ARCH_PACKETS_BY_LEVEL=packets
                packets[level]=packet
            else:
                module._CONTEXT_ARCH_DIRECT_PACKET=packet
    except Exception:
        # Usage telemetry must never block context injection.
        pass
    intro=("CUSTOM VARIABLES & EQUATIONS — ASSISTANT-CONTROLLED CONTEXT COMPOSITION\n"
           "Presentation rules are data-only and append-only. Derived/interpretive values never become authoritative emotion, somatic, continuity, session, memory, or context state.\n"
           "When you intentionally want to change how existing custom variables/equations are shown, including coherent multi-variable panels, you may request context_composition_updates inside the hidden <affective_update> JSON. Supported presentation actions include set_view/reset_view and set_panel/reset_panel. Do not silently create display rules or panels for every value.\n"
           f"composition_version={_CONTEXT_COMPOSITION_VERSION}; selected={packet.get('selected_count',0)}; selected_panels={packet.get('panels_selected_count',0)}; configured_views={packet.get('configured_view_count',0)}; configured_panels={packet.get('configured_panel_count',0)}")
    grouped={}
    for item in packet.get("selected") or []: grouped.setdefault(item.get("placement") or "metrics",[]).append(("variable",item))
    for panel in packet.get("panels_selected") or []: grouped.setdefault(panel.get("placement") or "metrics",[]).append(("panel",panel))
    blocks=[intro]
    order=["startup","continuity","emotion","somatic","research","personal","metrics","system","diagnostics","custom"]
    for placement in order:
        rows=grouped.get(placement) or []
        if not rows: continue
        rows.sort(key=lambda pair:(float(pair[1].get("effective_priority",pair[1].get("priority",0)) or 0),str(pair[1].get("panel_ref") or pair[1].get("ref") or "")),reverse=True)
        lines=[_CONTEXT_COMPOSITION_PLACEMENT_HEADERS[placement]]
        for kind,item in rows:
            detail=item.get("detail_level")
            if kind=="panel":
                lines.append(str(item.get("display") or item.get("title") or item.get("panel_ref")))
                if detail in {"compact","normal","full"}: lines.append(f"  [panel={item.get('panel_ref')}; priority={float(item.get('effective_priority',0)):.2f}; members={len(item.get('member_refs') or [])}]")
                if detail=="full":
                    for member in item.get("members") or []:
                        lines.append(f"  member={member.get('ref')} | role={member.get('semantic_role')} | authoritative_writeback=false")
                        if member.get("equation"):
                            eq=member["equation"]; lines.append(f"    equation={eq.get('formula')} | purpose={eq.get('purpose')}")
                continue
            line="- "+str(item.get("display") or item.get("ref"))
            if detail in {"compact","normal","full"}: line+=f" [role={item.get('semantic_role')}; priority={float(item.get('effective_priority',0)):.2f}]"
            if detail in {"normal","full"}: line+=f" [kind={item.get('value_kind')}; confidence={item.get('confidence')}]"
            lines.append(line)
            if detail=="full" and item.get("equation"):
                eq=item["equation"]; lines.append(f"  equation={eq.get('formula')} | purpose={eq.get('purpose')} | authoritative_writeback=false")
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)


# Keep the previous implementation available for /metrics design and replace
# ordinary metric context injection with the composed view.
_CC_ORIGINAL_CM_CONTEXT_PACKET = _cm_context_packet
_CC_ORIGINAL_CM_PROMPT_CONTEXT = _cm_prompt_context

def _cm_context_packet(module, *, query: str="", force_recalculate: bool=True) -> dict:
    # freshness remains explicit for the selective-context regression contract.
    return _cc_context_packet(module,query=query,force_recalculate=force_recalculate)

def _cm_prompt_context(module, query: str) -> str:
    return _cc_prompt_context(module,query)


def _cc_status(module) -> dict:
    state=_cm_state(module,recalculate=False,include_system=False)
    refs={row.get("ref"):row for row in state.get("variables") or []}
    views=[]
    for ref,row in sorted(refs.items()):
        configured=_cc_get_view(module,ref,include_retired=False)
        view=dict(configured or _cc_inherited_view(row)); view["configured"]=bool(configured)
        views.append({k:view.get(k) for k in ("variable_ref","visibility","detail_level","priority","placement","display_label","display_template","conditions","configured")})
    panels=_cc_latest_panels(module,include_retired=False)
    return {"ok":True,"version":_CONTEXT_COMPOSITION_VERSION,"view_count":len(views),"configured_count":sum(1 for x in views if x.get("configured")),"views":views,"panel_count":len(panels),"panels":[{k:p.get(k) for k in ("panel_ref","title","version","visibility","detail_level","priority","placement","layout","members","conditions","suppress_member_standalone")} for p in panels],"meaning":"Views and panels affect presentation/injection only. Variables/equations and authoritative source state remain unchanged."}


def _cc_preview(module, query: str) -> dict:
    packet=_cc_compose(module,query,force_recalculate=True,include_values=False)
    return {"ok":True,"version":packet.get("version"),"query":packet.get("query"),"selected_count":packet.get("selected_count"),"selected":[{k:x.get(k) for k in ("ref","placement","visibility","detail_level","priority","effective_priority","semantic_role","configured","display")} for x in packet.get("selected") or []],"not_selected":[{k:x.get(k) for k in ("ref","reason","placement","visibility","priority","condition","configured")} for x in packet.get("considered") or [] if not x.get("selected")],"panel_selected_count":packet.get("panels_selected_count",0),"panels_selected":[{k:x.get(k) for k in ("panel_ref","title","placement","visibility","detail_level","priority","effective_priority","layout","display","member_refs","suppress_member_standalone")} for x in packet.get("panels_selected") or []],"panels_not_selected":[{k:x.get(k) for k in ("panel_ref","reason","placement","visibility","priority","condition")} for x in packet.get("panels_considered") or [] if not x.get("selected")],"preview_exposes_values":False,"authoritative_writeback":False}


def _cc_apply_updates(module, updates: object, *, provider: str, model: str) -> dict:
    if updates is None: return {"ok":True,"version":_CONTEXT_COMPOSITION_VERSION,"applied":0,"results":[],"errors":[],"changed":False}
    if not isinstance(updates,list): raise ValueError("context_composition_updates must be a list.")
    results=[]; errors=[]
    for index,item in enumerate(updates[:64]):
        if not isinstance(item,dict): errors.append({"index":index,"error":"update must be an object"}); continue
        action=str(item.get("action") or "").strip().casefold()
        try:
            if action in {"set_view","define_view","configure_view"}:
                result=_cc_set_view(module,item.get("ref") or item.get("target"),visibility=item.get("visibility","auto"),detail_level=item.get("detail_level") or item.get("detail") or "normal",priority=item.get("priority",0.5),placement=item.get("placement","metrics"),display_label=item.get("display_label") or item.get("label"),display_template=item.get("display_template") or item.get("template"),conditions=item.get("conditions") or {},actor="Assistant",provider=provider,model=model,reason=item.get("reason") or "assistant_context_composition")
            elif action in {"reset_view","retire_view"}:
                result=_cc_reset_view(module,item.get("ref") or item.get("target"),actor="Assistant",provider=provider,model=model,reason=item.get("reason") or "assistant_context_view_reset")
            elif action in {"set_panel","define_panel","configure_panel"}:
                result=_cc_set_panel(module,item.get("panel_ref") or item.get("ref") or item.get("target"),title=item.get("title") or item.get("display_label") or item.get("label"),visibility=item.get("visibility","auto"),detail_level=item.get("detail_level") or item.get("detail") or "compact",priority=item.get("priority",0.5),placement=item.get("placement","metrics"),layout=item.get("layout","lines"),panel_template=item.get("panel_template") or item.get("template") or "{title}\n{items}",members=item.get("members") or [],conditions=item.get("conditions") or {},suppress_member_standalone=item.get("suppress_member_standalone",True),actor="Assistant",provider=provider,model=model,reason=item.get("reason") or "assistant_context_panel_composition")
            elif action in {"reset_panel","retire_panel"}:
                result=_cc_reset_panel(module,item.get("panel_ref") or item.get("ref") or item.get("target"),actor="Assistant",provider=provider,model=model,reason=item.get("reason") or "assistant_context_panel_reset")
            else: raise ValueError(f"Unsupported context composition action: {action}")
            results.append({"index":index,"action":action,"ok":True,"result":result})
        except Exception as exc: errors.append({"index":index,"action":action,"error":f"{type(exc).__name__}: {exc}"})
    return {"ok":not errors,"version":_CONTEXT_COMPOSITION_VERSION,"applied":len(results),"results":results,"errors":errors,"changed":bool(results)}


def _cc_design_prompt(purpose: str) -> str:
    purpose=_cm_clean(purpose,1600) or "Choose how your custom variables and derived equations should enter your context."
    contract={"visible_response":"Explain in your own voice what context views you chose and why; choose whatever length and structure feels appropriate.","context_composition_updates":[{"action":"set_view","ref":"project.assistant.progress","visibility":"auto","detail_level":"compact","priority":0.85,"placement":"continuity","display_label":"Project progress","display_template":"{label}: {value}{unit_suffix}","conditions":{"query_any":["project","progress","unfinished"]},"reason":"Example only; choose real variables and conditions that are meaningful to you."}]}
    return f"{_CONTEXT_COMPOSITION_DESIGN_MARKER}\nPurpose: {purpose}\nDesign your own context composition using only existing typed custom variables/equation outputs. You control whether/when each appears, detail, priority, placement, label, and display template. Prefer a small useful set; do not surface everything. Return exactly one JSON object matching this contract so Python can validate and commit it transactionally:\n{json.dumps(contract,ensure_ascii=False,indent=2)}"

def _cc_panel_design_prompt(purpose: str) -> str:
    purpose=_cm_clean(purpose,1600) or "Choose whether groups of existing variables/equation outputs would be more useful as context panels."
    contract={"visible_response":"Explain in your own voice which panel(s) you chose and why, or deliberately choose no change; choose whatever length and structure feels appropriate.","context_composition_updates":[{"action":"set_panel","panel_ref":"continuity.work_status","title":"Continuity work status","visibility":"auto","detail_level":"compact","priority":0.85,"placement":"continuity","layout":"lines","panel_template":"{title}\n{items}","members":[{"ref":"continuity.note_load","display_label":"Notes","display_template":"{label}: {value}","order":10}],"conditions":{"query_any":["continuity","unfinished","notes"]},"suppress_member_standalone":True,"reason":"Example only; choose real members and rules that are useful to you."}]}
    return f"{_CONTEXT_PANEL_DESIGN_MARKER}\nPurpose: {purpose}\nDesign zero or more multi-variable context panels using only existing typed variables/equation outputs. A panel is presentation-only: it cannot alter member variables, equations, memory, emotion, somatic state, continuity, session state, or any authoritative source. Prefer small coherent panels; do not create a panel merely because the feature exists. Return exactly one JSON object matching this contract so Python can validate and commit it transactionally:\n{json.dumps(contract,ensure_ascii=False,indent=2)}"


def _cc_panel_design_contract(module) -> str:
    state=_cm_state(module,recalculate=True,include_system=False); roles=_cc_semantic_role_map(state); available=[]
    for row in state.get("variables") or []:
        if row.get("status")!="active" or not row.get("current"): continue
        available.append({"ref":row.get("ref"),"type":row.get("value_type"),"unit":row.get("unit"),"description":row.get("description"),"value_kind":row.get("value_kind"),"semantic_role":roles.get(str(row.get("ref")),"descriptive" if row.get("value_kind")!="calculated" else "legacy_unspecified"),"current_value":(row.get("current") or {}).get("value")})
    design={"available_variables":available[:160],"existing_panels":[{k:p.get(k) for k in ("panel_ref","title","visibility","detail_level","priority","placement","layout","members","conditions","suppress_member_standalone")} for p in _cc_latest_panels(module,include_retired=False)],"visibility":sorted(_CONTEXT_COMPOSITION_VISIBILITY),"detail_levels":sorted(_CONTEXT_COMPOSITION_DETAIL),"placements":sorted(_CONTEXT_COMPOSITION_PLACEMENTS),"layouts":sorted(_CONTEXT_COMPOSITION_PANEL_LAYOUTS),"panel_template_placeholders":sorted(_CONTEXT_COMPOSITION_PANEL_PLACEHOLDERS),"member_template_placeholders":sorted(_CONTEXT_COMPOSITION_ALLOWED_PLACEHOLDERS),"condition_schema":{"query_any":["phrase"],"query_all":["phrase"],"query_none":["phrase"]},"safety":"Panels are presentation-only and append-only. Member definitions are referenced, never copied or rewritten. No arbitrary code and no authoritative writeback."}
    return "\n\nCONTEXT PANEL DESIGN WORKSPACE\n"+json.dumps(design,ensure_ascii=False,indent=2)



def _cc_design_contract(module) -> str:
    state=_cm_state(module,recalculate=True,include_system=False)
    available=[]
    roles=_cc_semantic_role_map(state)
    for row in state.get("variables") or []:
        if row.get("status")!="active" or not row.get("current"): continue
        available.append({"ref":row.get("ref"),"type":row.get("value_type"),"unit":row.get("unit"),"description":row.get("description"),"value_kind":row.get("value_kind"),"semantic_role":roles.get(str(row.get("ref")),"descriptive" if row.get("value_kind")!="calculated" else "legacy_unspecified"),"current_value":(row.get("current") or {}).get("value")})
    design={"available_variables":available[:160],"visibility":sorted(_CONTEXT_COMPOSITION_VISIBILITY),"detail_levels":sorted(_CONTEXT_COMPOSITION_DETAIL),"placements":sorted(_CONTEXT_COMPOSITION_PLACEMENTS),"allowed_template_placeholders":sorted(_CONTEXT_COMPOSITION_ALLOWED_PLACEHOLDERS),"condition_schema":{"query_any":["phrase"],"query_all":["phrase"],"query_none":["phrase"],"min_value":"numeric optional","max_value":"numeric optional"},"safety":"Views are presentation-only. No arbitrary code, no writes to authoritative state, no hidden inference from prose, append-only versions."}
    return "\n\nCONTEXT COMPOSITION DESIGN WORKSPACE\n"+json.dumps(design,ensure_ascii=False,indent=2)


def _cc_parse_design(answer: object) -> dict:
    text=str(answer or "").strip()
    candidates=[text]
    fenced=re.findall(r"```(?:json)?\s*(\{.*?\})\s*```",text,flags=re.I|re.S); candidates.extend(fenced)
    start=text.find("{"); end=text.rfind("}")
    if start>=0 and end>start: candidates.append(text[start:end+1])
    for candidate in candidates:
        try:
            data=json.loads(candidate)
            if isinstance(data,dict): return data
        except Exception: pass
    return {}


def _cc_commit_design(module, answer: object, *, provider: str, model: str) -> str:
    data=_cc_parse_design(answer)
    updates=data.get("context_composition_updates") if isinstance(data,dict) else None
    visible=str(data.get("visible_response") or "").strip() if isinstance(data,dict) else ""
    if not isinstance(updates,list):
        return (visible or str(answer or "").strip()) + "\n\n[context composition commit: 0 applied; no valid structured updates found]"
    report=_cc_apply_updates(module,updates,provider=provider,model=model)
    suffix=f"[context composition commit: {report.get('applied',0)} applied"
    if report.get("errors"): suffix+=f", {len(report['errors'])} rejected"
    suffix+="]"
    return (visible or "Context composition design processed.")+"\n\n"+suffix


def _cc_help() -> str:
    return ("/context views — Assistant-controlled variable/equation presentation\n\n"
            "  /context views\n  /context view show <ref>\n"
            "  /context view set <ref> visibility <always|auto|off>\n"
            "  /context view set <ref> detail <minimal|compact|normal|full>\n"
            "  /context view set <ref> priority <0..1>\n"
            "  /context view set <ref> placement <startup|continuity|emotion|somatic|research|diagnostics|metrics|personal|system|custom>\n"
            "  /context view reset <ref>\n  /context view preview <question>\n  /context view design [purpose]\n\n"
            "  /context panels | /context panel show <panel_ref>\n"
            "  /context panel preview <question> | /context panel reset <panel_ref>\n"
            "  /context panel design [purpose]\n\n"
            "Use design commands for labels, safe templates, multi-condition rules, and grouped panels. Views/panels never modify underlying data.")


def _cc_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    try:
        if lower in {"/context views","/context view","/context view status"}: print(json.dumps(_cc_status(module),ensure_ascii=False,indent=2)); return True
        if lower in {"/context panels","/context panel","/context panel status"}: print(json.dumps(_cc_panel_status(module),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context panel show "):
            ref=clean[len("/context panel show "):].strip(); print(json.dumps({"ok":True,"panel":_cc_get_panel(module,ref,include_retired=True)},ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context panel preview"):
            query=clean[len("/context panel preview"):].strip() or "ordinary conversation"; print(json.dumps(_cc_panel_preview(module,query),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context panel reset "):
            ref=clean[len("/context panel reset "):].strip(); print(json.dumps(_cc_reset_panel(module,ref,actor="User",provider="console",model=BUNDLE_VERSION),ensure_ascii=False,indent=2)); return True
        if lower in {"/context view help","/context views help"}: print(_cc_help()); return True
        if lower.startswith("/context view show "):
            ref=clean[len("/context view show "):].strip(); row=_cc_get_view(module,ref,include_retired=True); print(json.dumps({"ok":True,"view":row or _cc_inherited_view(next(x for x in _cm_state(module,recalculate=False,include_system=False)["variables"] if x.get("ref")==_cm_normalize_ref(ref)))},ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context view preview"):
            query=clean[len("/context view preview"):].strip() or "ordinary conversation"; print(json.dumps(_cc_preview(module,query),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context view reset "):
            ref=clean[len("/context view reset "):].strip(); print(json.dumps(_cc_reset_view(module,ref,actor="User",provider="console",model=BUNDLE_VERSION),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context view set "):
            rest=clean[len("/context view set "):].strip().split()
            if len(rest)!=3: print("Use /context view set <ref> <visibility|detail|priority|placement> <value>"); return True
            ref,field,value=rest; current=_cc_get_view(module,ref,include_retired=False)
            base=dict(current or _cc_inherited_view(next(x for x in _cm_state(module,recalculate=False,include_system=False)["variables"] if x.get("ref")==_cm_normalize_ref(ref))))
            kwargs={"visibility":base.get("visibility","auto"),"detail_level":base.get("detail_level","normal"),"priority":base.get("priority",0.5),"placement":base.get("placement","metrics"),"display_label":base.get("display_label"),"display_template":base.get("display_template"),"conditions":base.get("conditions") or {}}
            if field.casefold()=="visibility": kwargs["visibility"]=value
            elif field.casefold() in {"detail","detail_level"}: kwargs["detail_level"]=value
            elif field.casefold()=="priority": kwargs["priority"]=value
            elif field.casefold()=="placement": kwargs["placement"]=value
            else: print("Field must be visibility, detail, priority, or placement."); return True
            print(json.dumps(_cc_set_view(module,ref,actor="User",provider="console",model=BUNDLE_VERSION,reason="manual context view command",**kwargs),ensure_ascii=False,indent=2)); return True
        if lower.startswith("/context view design"):
            print("Use /context view design <purpose> from normal chat so Assistant can design the views."); return True
        if lower.startswith("/context panel design"):
            print("Use /context panel design <purpose> from normal chat so Assistant can design grouped panels."); return True
    except Exception as exc:
        print(f"Context composition error: {type(exc).__name__}: {exc}"); return True
    return False


