def _install_context_composition(module) -> None:
    if getattr(module,"_CONTEXT_COMPOSITION_INSTALLED",False): return
    _cc_ensure_schema(module)
    module.CONTEXT_COMPOSITION_VERSION=_CONTEXT_COMPOSITION_VERSION
    module.get_context_composition_views=lambda:_cc_status(module)
    module.preview_context_composition=lambda query="ordinary conversation":_cc_preview(module,query)
    module.get_context_composition_panels=lambda:_cc_panel_status(module)
    module.preview_context_panels=lambda query="ordinary conversation":_cc_panel_preview(module,query)
    module.apply_context_composition_updates=lambda updates,provider="unknown",model="unknown":_cc_apply_updates(module,updates,provider=provider,model=model)
    module.context_composition_self_test=lambda:context_composition_self_test(module)
    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_context_composition_views","description":"Read Assistant's variable/equation context presentation rules: visibility, detail, priority, placement, labels, templates, and conditions.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"preview_context_composition","description":"Preview which custom variables/derived equations and panels would be injected for a query and where, without exposing their values.","parameters":{"type":"object","properties":{"query":{"type":"string"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_context_composition_panels","description":"Read Assistant's append-only multi-variable context panels, member references, conditions, layout, priority, and placement.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"preview_context_panels","description":"Preview which Assistant-authored context panels would appear for a query without exposing member values.","parameters":{"type":"object","properties":{"query":{"type":"string"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_context_composition_views","preview_context_composition","get_context_composition_panels","preview_context_panels"})
    old_execute=module.execute_tool
    def execute_with_composition(name,arguments,seen,*args,**kwargs):
        if name=="get_context_composition_views": return module.get_context_composition_views()
        if name=="preview_context_composition": return module.preview_context_composition(**arguments)
        if name=="get_context_composition_panels": return module.get_context_composition_panels()
        if name=="preview_context_panels": return module.preview_context_panels(**arguments)
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_with_composition

    old_local=module.run_local_turn
    def run_local_with_composition(backend,messages,query=None,*,allow_sticky=True):
        if query is None: return old_local(backend,messages,allow_sticky=allow_sticky)
        answer=old_local(backend,messages,query,allow_sticky=allow_sticky)
        if _CONTEXT_COMPOSITION_DESIGN_MARKER in str(query or "") or _CONTEXT_PANEL_DESIGN_MARKER in str(query or ""):
            return _cc_commit_design(module,answer,provider="local",model=getattr(backend,"model_id","local"))
        return answer
    module.run_local_turn=run_local_with_composition
    old_online=module.run_online_chat_turn
    def run_online_with_composition(backend,messages,query):
        answer=old_online(backend,messages,query)
        if _CONTEXT_COMPOSITION_DESIGN_MARKER in str(query or "") or _CONTEXT_PANEL_DESIGN_MARKER in str(query or ""):
            return _cc_commit_design(module,answer,provider="online",model=getattr(backend,"model_id","online"))
        return answer
    module.run_online_chat_turn=run_online_with_composition

    old_build=module.build_runtime_context
    def build_with_composition_design(query,*args,**kwargs):
        result=old_build(query,*args,**kwargs)
        if _CONTEXT_COMPOSITION_DESIGN_MARKER in str(query or ""):
            result += _mcp_tag_runtime_context(_cc_design_contract(module),"context-composition","post_routing_context")
        if _CONTEXT_PANEL_DESIGN_MARKER in str(query or ""):
            result += _mcp_tag_runtime_context(_cc_panel_design_contract(module),"context-composition","post_routing_context")
        return result
    module.build_runtime_context=build_with_composition_design

    old_main=module.main
    def main_with_composition_commands():
        previous=builtins.input
        def composition_input(prompt=""):
            while True:
                value=previous(prompt); compact=" ".join(str(value or "").strip().split()); lower=compact.casefold()
                if lower=="/context view design" or lower.startswith("/context view design "):
                    purpose=compact[len("/context view design"):].strip(); return _cc_design_prompt(purpose)
                if lower=="/context panel design" or lower.startswith("/context panel design "):
                    purpose=compact[len("/context panel design"):].strip(); return _cc_panel_design_prompt(purpose)
                if _cc_handle_command(module,value): continue
                return value
        builtins.input=composition_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_composition_commands

    old_help=module.print_help
    def help_with_composition(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /context views | /context view show <ref> | set <ref> <visibility|detail|priority|placement> <value>")
        print("  /context view preview <query> | /context view reset <ref> | /context view design [purpose]")
        print("  /context panels | /context panel show <ref> | /context panel preview <query> | reset <ref> | design [purpose]")
    module.print_help=help_with_composition

    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict): specs["context-composition"]={"label":"Assistant-authored variable/equation context views and grouped panels with safe visibility, conditions, detail, priority, placement, layouts, and display templates","groups":("quick","critical","all"),"runner":"memory.context_composition_self_test"}
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME; module._CONTEXT_COMPOSITION_INSTALLED=True

