# >>> NEAT-SUBSYSTEM:context-compiler rev=2
# Python-side context compiler (7.4.35)
# ---------------------------------------------------------------------------
_CONTEXT_COMPILER_VERSION = "1.1-adaptive-budget-integrated-evidence-packet-compiler"
_CONTEXT_COMPILER_HISTORY_TERMS = {
    "history", "historical", "previous", "previously", "earlier", "older", "old",
    "superseded", "supersession", "archive", "archived", "retired", "before", "version history",
}
_CONTEXT_COMPILER_ROLE_ORDER = {
    "primary": 0,
    "contradictory": 1,
    "temporal_early": 2,
    "temporal_late": 3,
    "supporting": 4,
    "historical": 5,
}
_CONTEXT_COMPILER_GROUP_PROTECTED = {"routing_control", "runtime_truth", "authority_rules"}
_CONTEXT_COMPILER_PROTECTED_MARKERS = (
    "CUSTOM VARIABLES & EQUATIONS — ASSISTANT-CONTROLLED CONTEXT COMPOSITION",
    "CONTEXT ARCHITECTURE MAINTENANCE — REVIEW DUE",
    "CONTEXT ROUTING CONTROL — PYTHON-VALIDATED",
    "VERIFIED FACT / EVIDENCE / INTERPRETATION BOUNDARY",
)
_CONTEXT_COMPILER_REFERENCE_RE = re.compile(
    r"\[\[CITE:[A-Za-z0-9_.:-]+\]\]|\b(?:NB|MEM|BK|KI|KP|KSB|KDV|SCS|RW|BBE|OBS|ECHO|TASK|PROC|MRB)-[A-Za-z0-9_.:-]+\b"
)
_CONTEXT_COMPILER_GROUP_RE = re.compile(
    r"^\[CONTEXT GROUP (?P<group>[a-z0-9_]+) \|(?P<meta>[^\]]*)\]\n?",
    re.I,
)
_CONTEXT_COMPILER_QUERY_STOPWORDS = {
    "the", "and", "for", "with", "this", "that", "from", "what", "when", "where", "which",
    "who", "why", "how", "are", "was", "were", "have", "has", "had", "our", "your", "you",
    "about", "into", "than", "then", "still", "does", "did", "can", "could", "would", "should",
}


def _ccp_tokens(module, text: str) -> int:
    estimator = getattr(module, "_adaptive_estimate_tokens", None) or getattr(module, "approximate_tokens", None)
    if callable(estimator):
        try:
            return max(1, int(estimator(str(text or ""))))
        except Exception:
            pass
    return max(1, int(math.ceil(len(str(text or "")) / 4.0)))


def _ccp_normalize(text: str) -> str:
    return " ".join(str(text or "").casefold().split())


def _ccp_refs(text: str) -> tuple[str, ...]:
    return tuple(sorted(set(_CONTEXT_COMPILER_REFERENCE_RE.findall(str(text or "")))))


def _ccp_terms(text: str) -> set[str]:
    return {
        token for token in re.findall(r"[a-z0-9_]{3,}", str(text or "").casefold())
        if token not in _CONTEXT_COMPILER_QUERY_STOPWORDS
    }


def _ccp_similarity(a: str, b: str) -> float:
    left = _ccp_terms(a); right = _ccp_terms(b)
    if not left or not right:
        return 0.0
    lexical = len(left & right) / max(1, len(left | right))
    # Repeated evidence prose can differ by only a few words while a set-based
    # Jaccard score looks artificially low. Sequence similarity remains safe here
    # because near-dedup additionally requires an identical provenance signature.
    import difflib
    sequence = difflib.SequenceMatcher(None, _ccp_normalize(a), _ccp_normalize(b), autojunk=False).ratio()
    return max(lexical, sequence)


def _ccp_history_requested(query: str) -> bool:
    q = " ".join(str(query or "").casefold().split())
    return any(term in q for term in _CONTEXT_COMPILER_HISTORY_TERMS)


def _ccp_explicit_superseded_by(text: str) -> tuple[str, ...]:
    raw = str(text or "")
    found = []
    patterns = (
        r"superseded_by_ids?\s*[:=]\s*\[?([^\]\n;]+)",
        r"superseded\s+by\s*[:=]?\s*((?:NB|MEM|BK|KI|KP|KSB|KDV|SCS)-[A-Za-z0-9_.:-]+)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, raw, re.I):
            found.extend(re.findall(r"\b(?:NB|MEM|BK|KI|KP|KSB|KDV|SCS)-[A-Za-z0-9_.:-]+\b", match.group(1)))
    return tuple(dict.fromkeys(found))


def _ccp_temporal_role(text: str) -> str | None:
    lower = str(text or "").casefold()
    if any(marker in lower for marker in (
        "temporal_status=historical", '"temporal_status": "historical"', "temporal=historical",
        "state=archived", '"state": "archived"', "status=retired", '"status": "retired"',
        "operational_status=historical", '"operational_status": "historical"', "superseded_by",
        "superseded by",
    )):
        return "historical"
    return None


def _ccp_role_for_unit(module, unit: str, query: str) -> tuple[str, str]:
    refs = set(_ccp_refs(unit))
    plan = getattr(module, "_EVIDENCE_LAST_PLAN", None) or {}
    for row in plan.get("selected_evidence") or []:
        memory_id = str(row.get("memory_id") or "")
        if memory_id and any(memory_id in ref for ref in refs):
            role = str(row.get("role") or "supporting")
            return role, "python retrieval evidence plan"
    temporal = _ccp_temporal_role(unit)
    if temporal:
        return temporal, "explicit historical/supersession marker"
    lower = str(unit or "").casefold()
    if any(term in lower for term in ("contradict", "counterevidence", "opposing evidence", "disputed", "conflict with")):
        return "contradictory", "explicit contradiction marker"
    if any(term in lower for term in ("primary evidence", "authoritative", "exact source", "exact passage", "verified source")):
        return "primary", "explicit authority/evidence marker"
    return "supporting", "default retained context support"


def _ccp_parse_groups(text: str) -> list[dict]:
    source = str(text or "").strip()
    if not source:
        return []
    starts = list(re.finditer(r"(?m)^\[CONTEXT GROUP [a-z0-9_]+ \|[^\]]*\]", source, re.I))
    if not starts:
        return [{"group_id": "unrouted", "header": "", "meta": "", "body": source, "index": 0}]
    groups = []
    if starts[0].start() > 0 and source[:starts[0].start()].strip():
        groups.append({"group_id":"unrouted","header":"","meta":"","body":source[:starts[0].start()].strip(),"index":-1})
    for idx, match in enumerate(starts):
        end = starts[idx + 1].start() if idx + 1 < len(starts) else len(source)
        block = source[match.start():end].strip()
        first, _, body = block.partition("\n")
        parsed = _CONTEXT_COMPILER_GROUP_RE.match(first + "\n")
        group_id = parsed.group("group").casefold() if parsed else "unrouted"
        meta = parsed.group("meta").strip() if parsed else ""
        groups.append({"group_id":group_id,"header":first,"meta":meta,"body":body.strip(),"index":idx})
    return groups


def _ccp_split_units(body: str) -> list[str]:
    raw = str(body or "").strip()
    if not raw:
        return []
    return _rbi_split_preserving_exact_evidence(raw)


def _ccp_group_score(meta: str) -> float:
    match = re.search(r"\bscore=(-?\d+(?:\.\d+)?)", str(meta or ""), re.I)
    try:
        return float(match.group(1)) if match else 0.5
    except Exception:
        return 0.5


def _ccp_unit_priority(unit: dict, query_terms: set[str]) -> float:
    role = str(unit.get("role") or "supporting")
    role_weight = {
        "primary": 100.0, "contradictory": 98.0, "temporal_early": 96.0, "temporal_late": 96.0,
        "supporting": 65.0, "historical": 30.0,
    }.get(role, 60.0)
    overlap = len(query_terms & _ccp_terms(unit.get("text") or ""))
    reference_bonus = 8.0 if unit.get("refs") else 0.0
    return role_weight + min(18.0, overlap * 3.0) + reference_bonus + 8.0 * float(unit.get("group_score") or 0.0)


def _ccp_adaptive_budget_snapshot(module) -> dict:
    """Read the active candidate budget, or the last completed adaptive decision.

    Normal LOW/MID/HIGH candidate builds set an active safe-input budget temporarily.
    Direct diagnostics such as /context compile preview run outside that temporary scope,
    so they inherit only already-known adaptive metadata rather than inventing a cap.
    """
    active_safe = getattr(module, "_CONTEXT_COMPILER_SAFE_INPUT_TOKENS", None)
    active_level = str(getattr(module, "_DOMAIN_ACTIVE_LEVEL", None) or "").casefold()
    decision = dict(getattr(module, "_ADAPTIVE_LAST_DECISION", {}) or {})
    selected = str(decision.get("selected") or "").casefold()
    if active_level in {"low", "mid", "high"}:
        level = active_level
        level_source = "active_adaptive_candidate"
    elif selected in {"low", "mid", "high"}:
        level = selected
        level_source = "last_adaptive_decision"
    else:
        level = "mid"
        level_source = "default_mid_no_adaptive_level"
    safe = active_safe
    if safe is not None:
        safe_source = "active_adaptive_candidate"
    else:
        safe = decision.get("safe_input_limit_tokens")
        safe_source = "last_adaptive_decision" if safe is not None else "unavailable"
    levels = decision.get("levels") or {}
    selected_info = levels.get(level) or {} if isinstance(levels, dict) else {}
    return {
        "level": level,
        "level_source": level_source,
        "safe_input_tokens": safe,
        "safe_input_source": safe_source,
        "selected_level_estimated_prompt_tokens": selected_info.get("estimated_complete_prompt_tokens") if isinstance(selected_info, dict) else None,
        "reserved_output_tokens": decision.get("reserved_output_tokens"),
        "model_context_limit_tokens": decision.get("model_context_limit_tokens"),
        "model_context_limit_source": decision.get("model_context_limit_source"),
    }


def _ccp_budget_target(module, tokens_before: int) -> dict:
    snapshot = _ccp_adaptive_budget_snapshot(module)
    safe = snapshot.get("safe_input_tokens")
    level = str(snapshot.get("level") or "mid").casefold()
    if level not in {"low", "mid", "high"}:
        level = "mid"
    ratio = {"low": 0.62, "mid": 0.70, "high": 0.78}[level]
    base = {
        "level": level,
        "level_source": snapshot.get("level_source"),
        "safe_input_tokens": None,
        "safe_input_source": snapshot.get("safe_input_source"),
        "selected_level_estimated_prompt_tokens": snapshot.get("selected_level_estimated_prompt_tokens"),
        "reserved_output_tokens": snapshot.get("reserved_output_tokens"),
        "model_context_limit_tokens": snapshot.get("model_context_limit_tokens"),
        "model_context_limit_source": snapshot.get("model_context_limit_source"),
    }
    if safe is None:
        # Direct/non-adaptive builds: compiler dedup/supersession still runs, but no
        # invented hard cap is imposed without a real provider input budget.
        return {**base,"target_tokens":tokens_before,"budget_source":"no_adaptive_budget_available"}
    try:
        safe_int = max(512, int(safe))
    except Exception:
        safe_int = max(512, tokens_before)
    target = max(512, min(tokens_before, int(safe_int * ratio)))
    source = str(snapshot.get("safe_input_source") or "adaptive")
    return {**base,"safe_input_tokens":safe_int,"target_tokens":target,"budget_source":f"{source}_safe_input_fraction","fraction":ratio}


def _ccp_compile(module, context: str, query: str, *, include_text: bool = True) -> dict:
    before = str(context or "")
    tokens_before = _ccp_tokens(module, before)
    groups = _ccp_parse_groups(before)
    all_refs = set(_ccp_refs(before))
    history_requested = _ccp_history_requested(query)
    query_terms = _ccp_terms(query)
    seen_exact: dict[tuple[str,str], dict] = {}
    accepted_by_group: dict[int, list[dict]] = {}
    exact_removed = []
    near_removed = []
    superseded_removed = []
    role_counts = {}
    protected_units = 0
    unit_sequence = 0

    # First pass: exact/near dedup and conservative explicit supersession handling.
    for group in groups:
        gid = group["group_id"]
        group_protected = gid in _CONTEXT_COMPILER_GROUP_PROTECTED or any(marker in group.get("body", "") for marker in _CONTEXT_COMPILER_PROTECTED_MARKERS)
        kept = []
        for raw_unit in _ccp_split_units(group.get("body") or ""):
            unit_sequence += 1
            norm = _ccp_normalize(raw_unit)
            refs = _ccp_refs(raw_unit)
            role, role_reason = _ccp_role_for_unit(module, raw_unit, query)
            explicit_targets = _ccp_explicit_superseded_by(raw_unit)
            protected = bool(group_protected or role in {"primary", "contradictory", "temporal_early", "temporal_late"})
            if protected:
                protected_units += 1
            # Only omit an explicitly superseded unit when the replacement is actually
            # visible in this packet and the user did not request history.
            if explicit_targets and not history_requested and any(target in before for target in explicit_targets) and not protected:
                superseded_removed.append({"group_id":gid,"refs":list(refs),"superseded_by":list(explicit_targets),"reason":"explicit supersession target present"})
                continue
            exact_key = (gid, norm)
            if norm and exact_key in seen_exact:
                prior = seen_exact[exact_key]
                # Exact text has exactly the same reference signature; provenance is retained by the first copy.
                exact_removed.append({"group_id":gid,"refs":list(refs),"kept_sequence":prior["sequence"],"reason":"exact duplicate in same routed group"})
                continue
            candidate = {
                "sequence": unit_sequence, "group_id": gid, "text": raw_unit, "norm": norm,
                "refs": refs, "role": role, "role_reason": role_reason, "protected": protected,
                "group_score": _ccp_group_score(group.get("meta") or ""), "group_index": group.get("index", 0),
                "header": group.get("header") or "", "meta": group.get("meta") or "",
            }
            # Near-dedup is intentionally conservative: same group, long prose, and the
            # same provenance signature (or no provenance on either unit) are required.
            duplicate_of = None
            if len(raw_unit) >= 160:
                for prior in kept[-12:]:
                    if tuple(prior.get("refs") or ()) != refs:
                        continue
                    if _ccp_similarity(raw_unit, prior.get("text") or "") >= 0.94:
                        duplicate_of = prior
                        break
            if duplicate_of is not None:
                near_removed.append({"group_id":gid,"refs":list(refs),"kept_sequence":duplicate_of["sequence"],"reason":"near duplicate with identical provenance signature"})
                continue
            kept.append(candidate)
            if norm:
                seen_exact[exact_key] = candidate
        # A routed category can appear more than once in a composed context.
        # Preserve each physical occurrence instead of overwriting its siblings.
        accepted_by_group[group["index"]] = kept

    units = [unit for group in groups for unit in accepted_by_group.get(group["index"], [])]
    for unit in units:
        role_counts[unit["role"]] = role_counts.get(unit["role"], 0) + 1
        unit["priority_score"] = _ccp_unit_priority(unit, query_terms)

    def render(current_units: list[dict]) -> str:
        by_gid = {}
        for unit in current_units:
            by_gid.setdefault(unit["group_index"], []).append(unit)
        rendered = []
        for group in groups:
            gid = group["group_id"]
            rows = by_gid.get(group["index"]) or []
            if not rows:
                continue
            # Preserve original paragraph order. Evidence roles are exposed in the receipt;
            # source text itself is not rewritten or relabeled.
            rows.sort(key=lambda x: x["sequence"])
            body = "\n\n".join(row["text"] for row in rows).strip()
            if group.get("header"):
                rendered.append(group["header"] + ("\n" + body if body else ""))
            else:
                rendered.append(body)
        return "\n\n".join(x for x in rendered if x).strip()

    deduped_text = render(units)
    tokens_after_filtering = _ccp_tokens(module, deduped_text)
    budget = _ccp_budget_target(module, tokens_after_filtering)
    target = int(budget["target_tokens"])
    budget_omitted = []
    active = list(units)
    if _ccp_tokens(module, render(active)) > target:
        # Remove lowest-value optional units first. Never remove locked channels,
        # Assistant-selected custom composition, primary/contradictory/temporal evidence,
        # or the sole remaining unit of a routed group.
        optional = sorted(
            [u for u in active if not u["protected"]],
            key=lambda u: (float(u["priority_score"]), -int(u["sequence"])),
        )
        for candidate in optional:
            if _ccp_tokens(module, render(active)) <= target:
                break
            same_group = [u for u in active if u["group_id"] == candidate["group_id"]]
            if len(same_group) <= 1:
                continue
            active.remove(candidate)
            budget_omitted.append({
                "group_id":candidate["group_id"], "role":candidate["role"], "refs":list(candidate["refs"]),
                "priority_score":round(float(candidate["priority_score"]),4), "reason":"lowest-value optional unit above compiler budget",
            })

    compiled = render(active)
    tokens_after = _ccp_tokens(module, compiled)
    output_refs = set(_ccp_refs(compiled))
    removed_refs = all_refs - output_refs
    protected_present = all(
        any(u["sequence"] == p["sequence"] for u in active)
        for p in units if p["protected"]
    )
    final_role_counts = {}
    for unit in active:
        final_role_counts[unit["role"]] = final_role_counts.get(unit["role"], 0) + 1
    report = {
        "ok": True,
        "version": _CONTEXT_COMPILER_VERSION,
        "query_sha256": hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
        "raw_query_stored": False,
        "tokens_before": tokens_before,
        "tokens_after_filtering": tokens_after_filtering,
        "tokens_after": tokens_after,
        "tokens_saved": max(0, tokens_before - tokens_after),
        "savings_ratio": round(max(0.0, (tokens_before - tokens_after) / max(1, tokens_before)), 4),
        "groups_before": len(groups),
        "groups_after": len({u["group_id"] for u in active}),
        "units_before": sum(len(_ccp_split_units(group.get("body") or "")) for group in groups),
        "units_after": len(active),
        "exact_duplicates_removed": len(exact_removed),
        "near_duplicates_removed": len(near_removed),
        "explicitly_superseded_removed": len(superseded_removed),
        "budget_units_omitted": len(budget_omitted),
        "history_requested": history_requested,
        "evidence_roles": dict(sorted(final_role_counts.items())),
        "evidence_roles_before_budget": dict(sorted(role_counts.items())),
        "budget": {**budget, "met": tokens_after <= target, "overflow_tokens": max(0, tokens_after - target)},
        "protected_units": protected_units,
        "protected_units_preserved": protected_present,
        "reference_ids_before": len(all_refs),
        "reference_ids_after": len(output_refs),
        "reference_ids_intentionally_omitted": len(removed_refs),
        "citation_binding_policy": "kept source text and identifiers are byte-preserved; near-duplicates require identical provenance signatures",
        "authoritative_writeback": False,
        "arbitrary_code_execution": False,
        "decisions": {
            "exact_duplicates": exact_removed,
            "near_duplicates": near_removed,
            "superseded": superseded_removed,
            "budget_omissions": budget_omitted,
        },
    }
    receipt_payload = {k:v for k,v in report.items() if k not in {"receipt_sha256"}}
    report["receipt_sha256"] = hashlib.sha256(json.dumps(receipt_payload,ensure_ascii=False,sort_keys=True,separators=(",",":")).encode("utf-8")).hexdigest()
    if include_text:
        report["context"] = compiled
    return report


def _ccp_status(module) -> dict:
    last = dict(getattr(module, "_CONTEXT_COMPILER_LAST_REPORT", {}) or {})
    last.pop("context", None)
    return {
        "ok": True,
        "version": _CONTEXT_COMPILER_VERSION,
        "installed": bool(getattr(module, "_CONTEXT_COMPILER_INSTALLED", False)),
        "policy": {
            "exact_dedup": "same routed group only",
            "near_dedup": "same routed group + >=0.94 token-set similarity + identical provenance signature",
            "supersession": "omit only when an explicit superseded-by target is present in the same packet and history was not requested",
            "protected": sorted(_CONTEXT_COMPILER_GROUP_PROTECTED),
            "assistant_context_composition_protected": True,
            "primary_contradictory_temporal_evidence_protected": True,
            "budget_overflow_policy": "preserve protected evidence even if the target cannot be met",
            "raw_query_stored": False,
            "authoritative_writeback": False,
        },
        "last_receipt": last or None,
    }


def _ccp_preview(module, query: str) -> dict:
    base = getattr(module, "_CONTEXT_COMPILER_BASE_BUILD", None)
    if not callable(base):
        return {"ok":False,"error":"context compiler base builder unavailable"}
    previous = bool(getattr(module, "_CONTEXT_COMPILER_PREVIEW_ACTIVE", False))
    module._CONTEXT_COMPILER_PREVIEW_ACTIVE = True
    try:
        raw = base(str(query or ""))
        report = _ccp_compile(module, raw, str(query or ""), include_text=False)
        report["preview_exposes_context"] = False
        return report
    finally:
        module._CONTEXT_COMPILER_PREVIEW_ACTIVE = previous


def _ccp_handle_command(module, raw: str) -> bool:
    compact = " ".join(str(raw or "").strip().split())
    lower = compact.casefold()
    if lower in {"/context compile", "/context compiler", "/context compile status"}:
        print(json.dumps(_ccp_status(module),ensure_ascii=False,indent=2)); return True
    if lower in {"/context compile receipt", "/context compiler receipt"}:
        report = dict(getattr(module,"_CONTEXT_COMPILER_LAST_REPORT",{}) or {})
        report.pop("context",None)
        print(json.dumps({"ok":bool(report),"receipt":report or None},ensure_ascii=False,indent=2)); return True
    prefix = "/context compile preview"
    if lower == prefix or lower.startswith(prefix + " "):
        query = compact[len(prefix):].strip() or "ordinary conversation"
        print(json.dumps(_ccp_preview(module,query),ensure_ascii=False,indent=2)); return True
    return False


def context_compiler_self_test(module) -> dict:
    checks = {}
    old_plan = getattr(module,"_EVIDENCE_LAST_PLAN",None)
    old_safe = getattr(module,"_CONTEXT_COMPILER_SAFE_INPUT_TOKENS",None)
    old_level = getattr(module,"_DOMAIN_ACTIVE_LEVEL",None)
    old_decision = getattr(module,"_ADAPTIVE_LAST_DECISION",None)
    try:
        module._DOMAIN_ACTIVE_LEVEL="mid"
        module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=20000
        cite="[[CITE:P1]]"
        duplicate=("PRIMARY SOURCE EVIDENCE "+cite+" NB-TEST-A " + "alpha beta gamma delta "*18).strip()
        near1=("Supporting record "+cite+" NB-TEST-A " + "continuity unfinished notes evidence "*20 + "first wording").strip()
        near2=("Supporting record "+cite+" NB-TEST-A " + "continuity unfinished notes evidence "*20 + "second wording").strip()
        distinct=("Supporting record [[CITE:P2]] NB-TEST-B " + "continuity unfinished notes evidence "*20 + "second source").strip()
        superseded="NB-OLD state=archived superseded_by_ids=[NB-NEW] old retained summary"
        replacement="NB-NEW active replacement summary with current evidence"
        contradiction="CONTRADICTORY EVIDENCE NB-CONTRA conflicts with the primary interpretation and must remain visible."
        custom="CUSTOM VARIABLES & EQUATIONS — ASSISTANT-CONTROLLED CONTEXT COMPOSITION\nContinuity notes: 2"
        raw=(
            "[CONTEXT GROUP routing_control | role=CONTROL | order=1 adaptive | source=python | authority=authoritative | confidence=1.00 | provenance=required | score=1.000]\nLOCKED CONTROL\n\n"
            "[CONTEXT GROUP retrieval_evidence | role=EVIDENCE | order=1 adaptive | source=memory | authority=source-backed | confidence=0.95 | provenance=required | score=0.900]\n"
            + duplicate+"\n\n"+duplicate+"\n\n"+near1+"\n\n"+near2+"\n\n"+distinct+"\n\n"+superseded+"\n\n"+replacement+"\n\n"+contradiction+"\n\n"
            "[CONTEXT GROUP other_context | role=METRICS | order=1 adaptive | source=runtime | authority=derived | confidence=0.80 | provenance=required | score=0.500]\n"+custom
        )
        module._EVIDENCE_LAST_PLAN={"query":"unfinished continuity","selected_evidence":[
            {"memory_id":"NB-TEST-A","role":"primary","contribution":"direct evidence"},
            {"memory_id":"NB-CONTRA","role":"contradictory","contribution":"preserve conflict"},
        ]}
        first=_ccp_compile(module,raw,"unfinished continuity",include_text=True)
        checks["exact_duplicate_removed"]=first["exact_duplicates_removed"]==1
        checks["near_duplicate_same_provenance_removed"]=first["near_duplicates_removed"]>=1
        checks["near_duplicate_distinct_provenance_preserved"]="[[CITE:P2]]" in first["context"] and "NB-TEST-B" in first["context"]
        checks["explicit_superseded_removed_when_replacement_present"]=first["explicitly_superseded_removed"]==1 and "NB-OLD" not in first["context"] and "NB-NEW" in first["context"]
        historical=_ccp_compile(module,raw,"show previous historical continuity versions",include_text=True)
        checks["history_query_preserves_superseded"]="NB-OLD" in historical["context"]
        checks["retrieval_plan_role_preserved"]=(first.get("evidence_roles") or {}).get("primary",0)>=1 and (first.get("evidence_roles") or {}).get("contradictory",0)>=1
        checks["protected_context_composition_preserved"]="Continuity notes: 2" in first["context"] and first["protected_units_preserved"] is True
        checks["locked_control_preserved"]="LOCKED CONTROL" in first["context"]
        repeated_groups="[CONTEXT GROUP runtime_truth | first]\nExact source ALPHA.\n\n[CONTEXT GROUP runtime_truth | second]\nExact source OMEGA."
        repeated_report=_ccp_compile(module,repeated_groups,"read exact source",include_text=True)
        checks["repeated_group_preserves_unique_protected_text_and_order"]=repeated_report["context"]==repeated_groups
        checks["repeated_group_units_not_duplicated"]=repeated_report["units_after"]==2
        checks["raw_query_not_stored"]="query" not in first and first.get("raw_query_stored") is False and bool(first.get("query_sha256"))
        checks["receipt_hash_present"]=len(str(first.get("receipt_sha256") or ""))==64
        checks["no_authoritative_writeback"]=first.get("authoritative_writeback") is False and first.get("arbitrary_code_execution") is False
        checks["preview_contract_hides_context"]= "context" not in _ccp_compile(module,raw,"unfinished continuity",include_text=False)
        # Tight budget: optional supporting material may be removed, but protected
        # primary/contradictory/custom/locked content must survive even if that means overflow.
        module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=700
        tight=_ccp_compile(module,raw,"unfinished continuity",include_text=True)
        checks["budget_forecast_exercised"]=tight["budget"]["budget_source"]=="active_adaptive_candidate_safe_input_fraction" and tight["budget_units_omitted"]>=1
        checks["budget_never_drops_contradiction"]="NB-CONTRA" in tight["context"]
        checks["budget_never_drops_custom_composition"]="Continuity notes: 2" in tight["context"]
        checks["budget_reports_overflow_if_protected_requires_it"]=isinstance(tight["budget"].get("overflow_tokens"),int)
        # Direct preview/builds occur after the temporary adaptive-candidate scope.
        # They must inherit the last real provider budget/selected level rather than
        # reporting an invented or null budget.
        module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=None
        module._DOMAIN_ACTIVE_LEVEL=None
        module._ADAPTIVE_LAST_DECISION={
            "selected":"low",
            "safe_input_limit_tokens":4096,
            "reserved_output_tokens":768,
            "model_context_limit_tokens":8192,
            "model_context_limit_source":"self_test",
            "levels":{"low":{"estimated_complete_prompt_tokens":2500}},
        }
        inherited=_ccp_compile(module,raw,"unfinished continuity",include_text=False)
        inherited_budget=inherited.get("budget") or {}
        checks["direct_preview_inherits_last_adaptive_safe_budget"]=inherited_budget.get("safe_input_tokens")==4096 and inherited_budget.get("safe_input_source")=="last_adaptive_decision"
        checks["direct_preview_inherits_selected_level"]=inherited_budget.get("level")=="low" and inherited_budget.get("level_source")=="last_adaptive_decision"
        checks["adaptive_metadata_exposed_in_receipt"]=inherited_budget.get("selected_level_estimated_prompt_tokens")==2500 and inherited_budget.get("reserved_output_tokens")==768 and inherited_budget.get("model_context_limit_tokens")==8192
    finally:
        module._EVIDENCE_LAST_PLAN=old_plan
        module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=old_safe
        module._DOMAIN_ACTIVE_LEVEL=old_level
        module._ADAPTIVE_LAST_DECISION=old_decision
    return {"ok":all(bool(v) for v in checks.values()),"checks":checks,"version":_CONTEXT_COMPILER_VERSION,"model_calls":0,"web_calls":0,"authoritative_writeback":False}


def _install_context_compiler(module) -> None:
    if getattr(module,"_CONTEXT_COMPILER_INSTALLED",False):
        return
    module.CONTEXT_COMPILER_VERSION=_CONTEXT_COMPILER_VERSION
    module._CONTEXT_COMPILER_LAST_REPORT=None
    module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=None
    module._CONTEXT_COMPILER_PREVIEW_ACTIVE=False
    module.get_context_compiler_status=lambda:_ccp_status(module)
    module.preview_context_compiler=lambda query="ordinary conversation":_ccp_preview(module,query)
    module.context_compiler_self_test=lambda:context_compiler_self_test(module)

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_context_compiler_status","description":"Read the deterministic Python-side context compiler policy and last privacy-preserving packet receipt: deduplication, explicit supersession, evidence roles, token budget, omissions, and protected-channel status.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"preview_context_compiler","description":"Preview context compiler counts and token forecast for a query without exposing the compiled private context.","parameters":{"type":"object","properties":{"query":{"type":"string"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_context_compiler_status","preview_context_compiler"})
    old_execute=module.execute_tool
    def execute_with_compiler(name,arguments,seen,*args,**kwargs):
        if name=="get_context_compiler_status": return module.get_context_compiler_status()
        if name=="preview_context_compiler": return module.preview_context_compiler(**arguments)
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_with_compiler

    # Carry the adaptive provider input budget into the build wrapper so the
    # compiler forecasts against the same bounded envelope used by LOW/MID/HIGH.
    old_candidate=module._adaptive_build_candidate
    def build_candidate_with_compiler_budget(query,level,safe_input_tokens):
        previous_safe=getattr(module,"_CONTEXT_COMPILER_SAFE_INPUT_TOKENS",None)
        try:
            module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=int(safe_input_tokens)
            return old_candidate(query,level,safe_input_tokens)
        finally:
            module._CONTEXT_COMPILER_SAFE_INPUT_TOKENS=previous_safe
    module._adaptive_build_candidate=build_candidate_with_compiler_budget

    old_build=module.build_runtime_context
    module._CONTEXT_COMPILER_BASE_BUILD=old_build
    def build_with_context_compiler(query,*args,**kwargs):
        raw=old_build(query,*args,**kwargs)
        if getattr(module,"_CONTEXT_COMPILER_PREVIEW_ACTIVE",False):
            return raw
        report=_ccp_compile(module,raw,str(query or ""),include_text=True)
        context=report.pop("context")
        module._CONTEXT_COMPILER_LAST_REPORT=dict(report)
        # Attach the receipt to the existing retrieval trace rather than creating
        # another authoritative store. It contains hashes/counts/reasons, not context text.
        try:
            last=module.get_last_retrieval_trace()
            if last.get("ok"):
                trace=dict(last.get("trace") or {})
                trace["context_compiler"]=dict(report)
                trace["total_context_chars"]=len(context)
                module._store_retrieval_trace(trace)
        except Exception:
            pass
        return context
    module.build_runtime_context=build_with_context_compiler

    old_main=module.main
    def main_with_context_compiler_commands():
        previous=builtins.input
        def compiler_input(prompt=""):
            while True:
                value=previous(prompt)
                if _ccp_handle_command(module,value):
                    continue
                return value
        builtins.input=compiler_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_context_compiler_commands

    old_help=module.print_help
    def help_with_context_compiler(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /context compile | /context compile receipt | /context compile preview <query>")
    module.print_help=help_with_context_compiler

    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["context-compiler"]={"label":"Deterministic Python-side context compilation with safe deduplication, explicit supersession filtering, evidence-role preservation, token-budget forecasting, and packet receipts","groups":("quick","critical","all"),"runner":"memory.context_compiler_self_test"}
    module.NEATMEMORY_VERSION=BUNDLE_VERSION
    module.RELEASE_NAME=RELEASE_NAME
    module._CONTEXT_COMPILER_INSTALLED=True


