_CONTEXT_DELIVERY_VERSION = "1.2-budget-ledger-soft-section-receipt"
_CONTEXT_DELIVERY_NOTICE_MARKER = "CONTEXT DELIVERY NOTICE — MECHANICAL"


def _cdo_int(value, default=0) -> int:
    try:
        return max(0, int(value))
    except Exception:
        return max(0, int(default))


def _cdo_join(items: list[str]) -> str:
    clean = [str(item).strip() for item in items if str(item).strip()]
    if not clean:
        return ""
    if len(clean) == 1:
        return clean[0]
    if len(clean) == 2:
        return clean[0] + " and " + clean[1]
    return ", ".join(clean[:-1]) + ", and " + clean[-1]


def _cdo_character_omissions(text: str) -> tuple[int, int]:
    values = []
    for raw in re.findall(r"\[\.\.\.,\s*([0-9][0-9,]*)\s+characters omitted by context budget\s*\.\.\.\]", str(text or ""), flags=re.IGNORECASE):
        try:
            values.append(int(raw.replace(",", "")))
        except Exception:
            pass
    return len(values), sum(values)


def _cdo_candidate_report(module, query: str, context: str, active: dict | None = None) -> dict:
    active = dict(active or {})
    section = dict(active.get("section_budget") or {})
    compiler = dict(getattr(module, "_CONTEXT_COMPILER_LAST_REPORT", {}) or {})
    context_text = str(context or "")
    return {
        "level": str(getattr(module, "_DOMAIN_ACTIVE_LEVEL", None) or "direct"),
        "query_sha256": hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
        "raw_query_stored": False,
        "context_characters_delivered": len(context_text),
        "context_utf8_bytes_delivered": len(context_text.encode("utf-8")),
        "sections_seen": _cdo_int(section.get("sections_seen")),
        "sections_skipped": list(section.get("sections_skipped") or []),
        "section_clip_markers": _cdo_int(section.get("section_clip_markers")),
        "global_budget_markers": _cdo_int(section.get("global_budget_markers")),
        "character_omission_markers": _cdo_int(section.get("character_omission_markers")),
        "characters_omitted_by_section_budget": _cdo_int(section.get("characters_omitted_by_section_budget")),
        "recent_context_clipped": ("[RECENT context clipped at configured bound]" in context_text or "[RECENT context clipped at explicit diagnostic bound]" in context_text),
        "recent_soft_budget_active": bool((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_budget_active")),
        "recent_soft_regression_applied": bool((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_regression_applied")),
        "recent_soft_tokens_omitted": _cdo_int((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_tokens_omitted")),
        "recent_soft_available_tokens": _cdo_int(((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_budget") or {}).get("available_recent_context_tokens")),
        "recent_soft_delivered_tokens": _cdo_int((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("estimated_tokens_delivered")),
        "recent_soft_selection": ((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_budget") or {}).get("selection"),
        "recent_soft_authorized_tier_multiplier": _cdo_int(((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_budget") or {}).get("authorized_tier_multiplier"),1),
        "recent_soft_next_alert_tokens": _cdo_int(((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("soft_budget") or {}).get("next_soft_alert_tokens")),
        "recent_hard_limit_applied": bool((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("hard_limit_applied")),
        "recent_hard_tokens_beyond_limit": _cdo_int((getattr(module,"_RECENT_ANSWER_CONTEXT_LAST",{}) or {}).get("hard_tokens_beyond_limit")),
        "compiler_budget_units_omitted": _cdo_int(compiler.get("budget_units_omitted")),
        "compiler_receipt_sha256": compiler.get("receipt_sha256"),
        "compiler_protected_units_preserved": compiler.get("protected_units_preserved"),
        "authoritative_writeback": False,
    }


def _cdo_finalize_receipt(module, query: str, candidate: dict, history: dict, decision: dict) -> dict:
    receipt = dict(candidate or {})
    history = dict(history or {})
    decision = dict(decision or {})
    available = _cdo_int(history.get("messages_available"))
    delivered_history = _cdo_int(history.get("messages_delivered"))
    omitted_history = _cdo_int(history.get("messages_omitted_by_limit"), max(0, available - delivered_history))
    requested = str(decision.get("model_requested") or decision.get("prebuild_model_requested") or "").casefold()
    delivered_level = str(decision.get("selected") or "").casefold()
    levels = ("low", "mid", "high")
    hard_fit_downgrade = bool(requested in levels and delivered_level in levels and levels.index(delivered_level) < levels.index(requested))
    receipt.update({
        "version": _CONTEXT_DELIVERY_VERSION,
        "created_at": module.utc_now(),
        "query_sha256": hashlib.sha256(str(query or "").encode("utf-8")).hexdigest(),
        "raw_query_stored": False,
        "history_messages_available": available,
        "history_messages_delivered": delivered_history,
        "history_messages_omitted_by_limit": omitted_history,
        "provider_depth_requested": requested or None,
        "provider_depth_delivered": delivered_level or None,
        "provider_hard_fit_downgrade": hard_fit_downgrade,
        "meaning_assessed_by_python": False,
        "assistant_response_mode_selected_by_python": False,
        "authoritative_writeback": False,
    })
    losses = []
    if omitted_history:
        losses.append(f"{omitted_history} history message{'s' if omitted_history != 1 else ''}")
    compiler_omitted = _cdo_int(receipt.get("compiler_budget_units_omitted"))
    if compiler_omitted:
        losses.append(f"{compiler_omitted} admitted context unit{'s' if compiler_omitted != 1 else ''}")
    skipped = list(receipt.get("sections_skipped") or [])
    if skipped:
        losses.append(f"{len(skipped)} context section{'s' if len(skipped) != 1 else ''}")
    chars_omitted = _cdo_int(receipt.get("characters_omitted_by_section_budget"))
    if chars_omitted:
        losses.append(f"{chars_omitted} context character{'s' if chars_omitted != 1 else ''}")
    elif _cdo_int(receipt.get("section_clip_markers")) or _cdo_int(receipt.get("global_budget_markers")):
        losses.append("context text of uncounted length")
    if bool(receipt.get("recent_context_clipped")):
        losses.append("bounded RECENT material")
    if bool(receipt.get("recent_hard_limit_applied")):
        losses.append(f"{_cdo_int(receipt.get('recent_hard_tokens_beyond_limit'))} RECENT token{'s' if _cdo_int(receipt.get('recent_hard_tokens_beyond_limit')) != 1 else ''} beyond the hard safe-input boundary")
    reasons = []
    if omitted_history:
        reasons.append("history_token_limit")
    if compiler_omitted:
        reasons.append("context_compiler_budget")
    if skipped or chars_omitted or _cdo_int(receipt.get("section_clip_markers")) or _cdo_int(receipt.get("global_budget_markers")):
        reasons.append("context_section_budget")
    if bool(receipt.get("recent_context_clipped")):
        reasons.append("recent_context_bound")
    if bool(receipt.get("recent_hard_limit_applied")):
        reasons.append("recent_hard_safe_limit")
    if hard_fit_downgrade:
        reasons.append("provider_hard_fit_downgrade")
    incomplete = bool(reasons)
    notice = None
    if incomplete:
        clauses = []
        if losses:
            clauses.append("delivery limits omitted " + _cdo_join(losses))
        if hard_fit_downgrade:
            clauses.append(f"a hard provider-fit limit reduced retrieval depth from {requested.upper()} to {delivered_level.upper()}")
        notice = "Context incomplete: " + "; ".join(clauses) + ". Source material remains available through its normal retrieval path; Assistant decides whether this limitation matters before concluding."
    receipt["delivery_complete"] = not incomplete
    receipt["incomplete_reasons"] = reasons
    receipt["notice"] = notice
    hash_payload = {key:value for key,value in receipt.items() if key not in {"receipt_sha256"}}
    receipt["receipt_sha256"] = hashlib.sha256(json.dumps(hash_payload,ensure_ascii=False,sort_keys=True,separators=(",",":"),default=str).encode("utf-8")).hexdigest()
    return receipt


def _cdo_public_status(module) -> dict:
    receipt = dict(getattr(module, "_CONTEXT_DELIVERY_LAST_RECEIPT", {}) or {})
    return {
        "ok": True,
        "version": _CONTEXT_DELIVERY_VERSION,
        "installed": bool(getattr(module, "_CONTEXT_DELIVERY_OBSERVABILITY_INSTALLED", False)),
        "policy": {
            "mechanical_detection_only": True,
            "python_judges_meaning": False,
            "python_selects_response_mode": False,
            "notice_position": "after final context compilation and adaptive selection",
            "no_notice_for_zero_matches": True,
            "no_notice_for_exact_deduplication": True,
            "no_notice_for_explicit_supersession_current_view": True,
            "no_notice_for_assistant_selected_bounded_intake": True,
            "assistant_selected_recent_soft_regression_is_recorded_not_called_incomplete": True,
            "per_section_budgets_are_soft_shares_during_adaptive_builds": True,
            "provider_budget_ledger_is_model_visible": True,
        },
        "last_receipt": receipt or None,
    }


def context_delivery_observability_self_test(module=None) -> dict:
    module = module or _load_memory()
    checks = {}
    saved_pending = getattr(module, "_CONTEXT_DELIVERY_HISTORY_PENDING", None)
    saved_active = getattr(module, "_CONTEXT_DELIVERY_ACTIVE_CANDIDATE", None)
    saved_last = getattr(module, "_CONTEXT_DELIVERY_LAST_RECEIPT", None)
    saved_cap = module.MODEL_CONTEXT_MAX_CHARS
    saved_budgets = module.CONTEXT_SECTION_BUDGETS
    try:
        messages = [
            {"role":"user","content":"OLD-ANCHOR " + "old " * 160},
            {"role":"assistant","content":"NEW-ANSWER " + "new " * 8},
        ]
        trimmed = module.trim_messages(messages, 35)
        loss_history = dict(getattr(module,"_CONTEXT_DELIVERY_HISTORY_PENDING",{}) or {})
        checks["history_loss_counted"] = len(trimmed) == 1 and loss_history.get("messages_omitted_by_limit") == 1
        full = module.trim_messages(messages, 10000)
        full_history = dict(getattr(module,"_CONTEXT_DELIVERY_HISTORY_PENDING",{}) or {})
        checks["no_loss_control_complete"] = len(full) == 2 and full_history.get("messages_omitted_by_limit") == 0

        module.MODEL_CONTEXT_MAX_CHARS = 500
        module.CONTEXT_SECTION_BUDGETS = {"first":500,"second":500,"third":500}
        active = {}
        module._CONTEXT_DELIVERY_ACTIVE_CANDIDATE = active
        packet, sizes = module._fit_context_sections([
            ("first","FIRST SECTION","A"*3000),
            ("second","SECOND SECTION","SECOND-SENTINEL "+"B"*100),
            ("third","THIRD SECTION","THIRD-SENTINEL"),
        ])
        section = dict(active.get("section_budget") or {})
        checks["section_loss_counted"] = sizes.get("third") == 0 and "third" in (section.get("sections_skipped") or []) and section.get("global_budget_markers",0) >= 1
        checks["section_loss_not_silently_claimed_complete"] = "THIRD-SENTINEL" not in packet

        candidate = {
            "level":"mid","sections_seen":3,"sections_skipped":["third"],
            "section_clip_markers":1,"global_budget_markers":1,
            "character_omission_markers":1,"characters_omitted_by_section_budget":744,
            "recent_context_clipped":False,"compiler_budget_units_omitted":2,
            "compiler_protected_units_preserved":True,"authoritative_writeback":False,
        }
        incomplete = _cdo_finalize_receipt(module,"audit query",candidate,loss_history,{"model_requested":"high","selected":"mid"})
        checks["neutral_notice_created"] = str(incomplete.get("notice") or "").startswith("Context incomplete:") and "Assistant decides" in str(incomplete.get("notice") or "")
        checks["all_mechanical_reasons_present"] = set(incomplete.get("incomplete_reasons") or []) == {"history_token_limit","context_compiler_budget","context_section_budget","provider_hard_fit_downgrade"}
        checks["provider_downgrade_visible"] = incomplete.get("provider_hard_fit_downgrade") is True and "HIGH to MID" in str(incomplete.get("notice") or "")
        checks["python_does_not_choose_meaning_or_response_mode"] = incomplete.get("meaning_assessed_by_python") is False and incomplete.get("assistant_response_mode_selected_by_python") is False
        complete = _cdo_finalize_receipt(module,"control",{"level":"mid","sections_skipped":[],"compiler_budget_units_omitted":0},{"messages_available":2,"messages_delivered":2,"messages_omitted_by_limit":0},{"model_requested":"mid","selected":"mid"})
        checks["complete_control_has_no_notice"] = complete.get("delivery_complete") is True and complete.get("notice") is None
        soft = _cdo_finalize_receipt(module,"soft",{"level":"mid","sections_skipped":[],"compiler_budget_units_omitted":0,"recent_soft_regression_applied":True,"recent_soft_tokens_omitted":7000,"recent_hard_limit_applied":False},{"messages_available":2,"messages_delivered":2,"messages_omitted_by_limit":0},{"model_requested":"mid","selected":"mid"})
        checks["assistant_selected_soft_regression_is_not_false_incomplete"] = soft.get("delivery_complete") is True and soft.get("notice") is None
        hard_recent = _cdo_finalize_receipt(module,"hard",{"level":"mid","sections_skipped":[],"compiler_budget_units_omitted":0,"recent_hard_limit_applied":True,"recent_hard_tokens_beyond_limit":5000},{"messages_available":2,"messages_delivered":2,"messages_omitted_by_limit":0},{"model_requested":"mid","selected":"mid"})
        checks["hard_recent_limit_is_visible_incomplete"] = hard_recent.get("delivery_complete") is False and "recent_hard_safe_limit" in (hard_recent.get("incomplete_reasons") or [])
        checks["receipt_hash_present"] = len(str(incomplete.get("receipt_sha256") or "")) == 64
        checks["raw_query_not_stored"] = incomplete.get("raw_query_stored") is False and "query" not in incomplete
        checks["read_only_status_available"] = _cdo_public_status(module).get("policy",{}).get("mechanical_detection_only") is True
    finally:
        module._CONTEXT_DELIVERY_HISTORY_PENDING = saved_pending
        module._CONTEXT_DELIVERY_ACTIVE_CANDIDATE = saved_active
        module._CONTEXT_DELIVERY_LAST_RECEIPT = saved_last
        module.MODEL_CONTEXT_MAX_CHARS = saved_cap
        module.CONTEXT_SECTION_BUDGETS = saved_budgets
    return {"ok":all(bool(value) for value in checks.values()),"checks":checks,"version":_CONTEXT_DELIVERY_VERSION,"model_calls":0,"web_calls":0,"live_database_modified":False}


def _install_context_delivery_observability(module) -> None:
    if getattr(module, "_CONTEXT_DELIVERY_OBSERVABILITY_INSTALLED", False):
        return
    module.CONTEXT_DELIVERY_VERSION = _CONTEXT_DELIVERY_VERSION
    module._CONTEXT_DELIVERY_HISTORY_PENDING = None
    module._CONTEXT_DELIVERY_ACTIVE_HISTORY = None
    module._CONTEXT_DELIVERY_ACTIVE_CANDIDATE = None
    module._CONTEXT_DELIVERY_CANDIDATE_REPORTS = {}
    module._CONTEXT_DELIVERY_LAST_RECEIPT = None

    old_trim = module.trim_messages
    def trim_messages_with_delivery_receipt(messages, max_tokens):
        available = len(messages or [])
        delivered = old_trim(messages, max_tokens)
        module._CONTEXT_DELIVERY_HISTORY_PENDING = {
            "messages_available": available,
            "messages_delivered": len(delivered),
            "messages_omitted_by_limit": max(0, available-len(delivered)),
            "max_tokens": int(max_tokens),
        }
        return delivered
    module.trim_messages = trim_messages_with_delivery_receipt

    old_fit = module._fit_context_sections
    def fit_context_sections_with_delivery_receipt(sections):
        rows = list(sections)
        packet, sizes = old_fit(rows)
        active = getattr(module, "_CONTEXT_DELIVERY_ACTIVE_CANDIDATE", None)
        if isinstance(active, dict):
            skipped = []
            for key, _title, raw in rows:
                meaningful = str(raw or "").strip() not in {"", "[none]"}
                if meaningful and _cdo_int(sizes.get(key)) == 0:
                    skipped.append(str(key))
            omission_markers, omitted_chars = _cdo_character_omissions(packet)
            active["section_budget"] = {
                "sections_seen": len(rows),
                "sections_skipped": skipped,
                "section_clip_markers": str(packet).count("[section clipped by Python context budget]"),
                "global_budget_markers": str(packet).count("[global context budget reached]"),
                "character_omission_markers": omission_markers,
                "characters_omitted_by_section_budget": omitted_chars,
            }
        return packet, sizes
    module._fit_context_sections = fit_context_sections_with_delivery_receipt

    old_build = module.build_runtime_context
    def build_context_with_delivery_capture(query, *args, **kwargs):
        previous = getattr(module, "_CONTEXT_DELIVERY_ACTIVE_CANDIDATE", None)
        active = {}
        module._CONTEXT_DELIVERY_ACTIVE_CANDIDATE = active
        try:
            context = old_build(query, *args, **kwargs)
        finally:
            module._CONTEXT_DELIVERY_ACTIVE_CANDIDATE = previous
        report = _cdo_candidate_report(module, str(query or ""), str(context or ""), active)
        level = str(report.get("level") or "direct")
        reports = dict(getattr(module,"_CONTEXT_DELIVERY_CANDIDATE_REPORTS",{}) or {})
        reports[level] = report
        module._CONTEXT_DELIVERY_CANDIDATE_REPORTS = reports
        return context
    module.build_runtime_context = build_context_with_delivery_capture

    old_prepare = module._adaptive_prepare_context
    def prepare_context_with_delivery_receipt(backend, messages, query, *, provider, output_reserve_tokens, extra_instruction_text=""):
        history = dict(getattr(module,"_CONTEXT_DELIVERY_HISTORY_PENDING",{}) or {})
        module._CONTEXT_DELIVERY_HISTORY_PENDING = None
        module._CONTEXT_DELIVERY_ACTIVE_HISTORY = history
        module._CONTEXT_DELIVERY_CANDIDATE_REPORTS = {}
        try:
            result = old_prepare(
                backend,messages,query,provider=provider,
                output_reserve_tokens=output_reserve_tokens,
                extra_instruction_text=extra_instruction_text,
            )
        finally:
            module._CONTEXT_DELIVERY_ACTIVE_HISTORY = None
        decision = dict(result.get("decision") or {})
        selected = str(decision.get("selected") or "direct")
        reports = dict(getattr(module,"_CONTEXT_DELIVERY_CANDIDATE_REPORTS",{}) or {})
        candidate = dict(reports.get(selected) or reports.get("direct") or (list(reports.values())[-1] if reports else {}))
        receipt = _cdo_finalize_receipt(module,str(query or ""),candidate,history,decision)
        module._CONTEXT_DELIVERY_LAST_RECEIPT = dict(receipt)
        decision["context_delivery"] = dict(receipt)
        # .219 dark operational state: update the derived index only. This write
        # never adds text to the provider packet and carries no semantic authority.
        refresh_index = getattr(module, "_operational_refresh_hidden_index", None)
        if callable(refresh_index):
            try:
                refresh_index(reason="context_delivery_receipt", persist=True)
            except Exception:
                pass
        result["decision"] = decision
        if receipt.get("notice"):
            result["context"] = str(result.get("context") or "") + "\n\n" + _mcp_tag_runtime_context(_CONTEXT_DELIVERY_NOTICE_MARKER + "\n" + str(receipt["notice"]),"context-delivery-observability","post_compiler_context")
            print(
                "[context delivery] INCOMPLETE | "
                f"history -{receipt.get('history_messages_omitted_by_limit',0)} | "
                f"compiler units -{receipt.get('compiler_budget_units_omitted',0)} | "
                f"sections skipped -{len(receipt.get('sections_skipped') or [])} | "
                f"section clips {receipt.get('section_clip_markers',0)} | section chars -{receipt.get('characters_omitted_by_section_budget',0)} | "
                f"recent beyond ceiling {receipt.get('recent_hard_tokens_beyond_limit',0)}t | recent hard applied {str(bool(receipt.get('recent_hard_limit_applied'))).lower()} | "
                f"provider depth {receipt.get('provider_depth_requested') or '-'}->{receipt.get('provider_depth_delivered') or '-'}",
                flush=True,
            )
        try:
            last = module.get_last_retrieval_trace()
            if last.get("ok"):
                trace = dict(last.get("trace") or {})
                trace["context_delivery"] = dict(receipt)
                module._store_retrieval_trace(trace)
        except Exception:
            pass
        logger = getattr(module,"append_diagnostic_log",None)
        if callable(logger):
            try:
                logger(
                    "retrieval.context_delivery",
                    "Context delivery complete." if receipt.get("delivery_complete") else "Context delivery mechanically incomplete.",
                    severity="info" if receipt.get("delivery_complete") else "warning",
                    subsystem="retrieval",provider=str(provider),details={key:value for key,value in receipt.items() if key not in {"notice"}},
                )
            except Exception:
                pass
        module._ADAPTIVE_LAST_DECISION = decision
        return result
    module._adaptive_prepare_context = prepare_context_with_delivery_receipt

    module.get_context_delivery_status = lambda: _cdo_public_status(module)
    module.context_delivery_observability_self_test = lambda: context_delivery_observability_self_test(module)
    module.TOOL_SCHEMAS.append({"type":"function","function":{
        "name":"get_context_delivery_status",
        "description":"Read the latest turn-scoped mechanical context-delivery receipt: history/section/compiler omissions, provider-fit depth adjustment, completeness, and neutral notice. It never judges whether missing material matters.",
        "parameters":{"type":"object","properties":{},"additionalProperties":False},
    }})
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("get_context_delivery_status")
    old_execute = module.execute_tool
    def execute_with_context_delivery(name, arguments, seen, *args, **kwargs):
        if name == "get_context_delivery_status":
            return module.get_context_delivery_status()
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool = execute_with_context_delivery

    old_main = module.main
    def main_with_context_delivery_command():
        previous = builtins.input
        def delivery_input(prompt=""):
            while True:
                value = previous(prompt)
                if " ".join(str(value or "").strip().split()).casefold() in {"/context delivery","/context delivery status"}:
                    print(json.dumps(module.get_context_delivery_status(),ensure_ascii=False,indent=2)); continue
                return value
        builtins.input = delivery_input
        try:
            return old_main()
        finally:
            builtins.input = previous
    module.main = main_with_context_delivery_command
    old_help = module.print_help
    def help_with_context_delivery(*args, **kwargs):
        old_help(*args,**kwargs)
        print("  /context delivery      Show the latest mechanical delivery receipt; Python does not judge whether omissions matter.")
    module.print_help = help_with_context_delivery

    specs = globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["context-delivery-observability"] = {
            "label":"Turn-scoped neutral incomplete-context notices for mechanical history/section/compiler/provider-fit loss with Assistant-owned response mode",
            "groups":("quick","critical","all"),
            "runner":"memory.context_delivery_observability_self_test",
        }
        globals()["_SELF_TEST_EXPECTED"] = tuple(specs)
    suites = globals().get("_SELF_TEST_NAMED_SUITES")
    if isinstance(suites,dict):
        checkpoint = tuple(suites.get("checkpoint") or ())
        if "context-delivery-observability" not in checkpoint:
            suites["checkpoint"] = checkpoint + ("context-delivery-observability",)
    module.NEATMEMORY_VERSION = BUNDLE_VERSION
    module.RELEASE_NAME = RELEASE_NAME
    module._CONTEXT_DELIVERY_OBSERVABILITY_INSTALLED = True


# The parent self-test dispatcher resolves a requested subsystem before it loads the
# embedded runtime. Register this test statically as well as during installation so
# ``--self-test context-delivery-observability`` and the checkpoint suite can select
# it without creating a live runtime first.
if isinstance(globals().get("_SELF_TEST_SPECS"),dict):
    _SELF_TEST_SPECS["context-delivery-observability"] = {
        "label":"Turn-scoped neutral incomplete-context notices for mechanical history/section/compiler/provider-fit loss with Assistant-owned response mode",
        "groups":("quick","critical","all"),
        "runner":"memory.context_delivery_observability_self_test",
    }
    _SELF_TEST_EXPECTED = tuple(_SELF_TEST_SPECS)
if isinstance(globals().get("_SELF_TEST_NAMED_SUITES"),dict):
    _checkpoint_context_delivery = tuple(_SELF_TEST_NAMED_SUITES.get("checkpoint") or ())
    if "context-delivery-observability" not in _checkpoint_context_delivery:
        _SELF_TEST_NAMED_SUITES["checkpoint"] = _checkpoint_context_delivery + ("context-delivery-observability",)


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:expression-freedom-diagnostics rev=2
# Expression Freedom Safeguard (7.4.37.2)
# Ordinary visible answers are not bounded by NeatMemory brevity/style quotas.
# Machine/admin JSON operations remain bounded for deterministic correctness.
# ---------------------------------------------------------------------------
_EXPRESSION_FREEDOM_VERSION = "1.0-ordinary-visible-expression-unbounded-by-neatmemory"

def _expression_freedom_status(module) -> dict:
    return {
        "ok": True,
        "version": _EXPRESSION_FREEDOM_VERSION,
        "ordinary_chat": {
            "neatmemory_output_token_cap": (None if int(getattr(module, "CHAT_MAX_OUTPUT_TOKENS", 0) or 0) <= 0 else int(module.CHAT_MAX_OUTPUT_TOKENS)),
            "output_cap_source": "none_provider_managed" if int(getattr(module, "CHAT_MAX_OUTPUT_TOKENS", 0) or 0) <= 0 else "explicit_operator_CHAT_MAX_OUTPUT_TOKENS",
            "context_output_reserve_tokens": int(getattr(module, "CHAT_OUTPUT_RESERVE_TOKENS", 0) or 0),
            "reserve_is_generation_cap": False,
            "forced_concise_instruction": False,
            "forced_word_limit": None,
            "forced_sentence_limit": None,
            "forced_character_limit": None,
            "personality_verbosity_injected_as_quota": False,
            "affective_update_required_every_turn": False,
        },
        "boundaries": {
            "provider_model_context_limits_remain": True,
            "safety_and_integrity_rules_remain": True,
            "machine_admin_structured_operations_may_be_bounded": True,
            "input_context_budgets_do_not_limit_visible_answer_style": True,
        },
        "principle": "NeatMemory may organize Assistant's information, but ordinary visible expression length, structure, wording, and detail remain Assistant/model-controlled within unavoidable provider limits.",
    }

def expression_freedom_self_test(module=None) -> dict:
    if module is None:
        module = _load_memory()
    status = _expression_freedom_status(module)
    system_prompt = str(getattr(module, "SYSTEM_PROMPT", ""))
    checks = {
        "ordinary_cap_disabled_by_default": int(getattr(module, "CHAT_MAX_OUTPUT_TOKENS", 0) or 0) == 0,
        "provider_managed_status": status["ordinary_chat"]["output_cap_source"] == "none_provider_managed",
        "reserve_not_cap": status["ordinary_chat"]["reserve_is_generation_cap"] is False,
        "system_prompt_expression_freedom": "NeatMemory imposes no word-count, sentence-count, character-count" in system_prompt,
        "no_concise_ordinary_prompt": "Return a concise final answer" not in system_prompt,
        "no_word_limit_ordinary_prompt": "under 500 words" not in system_prompt,
        "affective_channel_optional": status["ordinary_chat"]["affective_update_required_every_turn"] is False,
        "no_authority_change": status["boundaries"]["safety_and_integrity_rules_remain"] is True,
    }
    return {"ok": all(checks.values()), "checks": checks, "status": status}

def _install_expression_freedom(module) -> None:
    if getattr(module, "_EXPRESSION_FREEDOM_INSTALLED", False):
        return
    module.EXPRESSION_FREEDOM_VERSION = _EXPRESSION_FREEDOM_VERSION
    module.get_expression_freedom_status = lambda: _expression_freedom_status(module)
    module.expression_freedom_self_test = lambda: expression_freedom_self_test(module)
    original_main = module.main
    def main_with_expression_freedom_command():
        original_input = builtins.input
        def expression_input(prompt=""):
            while True:
                value = original_input(prompt)
                clean = str(value or "").strip().casefold()
                if clean in {"/expression freedom", "/expression-freedom", "/expression status"}:
                    print(json.dumps(_expression_freedom_status(module), ensure_ascii=False, indent=2))
                    continue
                return value
        builtins.input = expression_input
        try:
            return original_main()
        finally:
            builtins.input = original_input
    module.main = main_with_expression_freedom_command
    module.NEATMEMORY_VERSION = BUNDLE_VERSION
    module.RELEASE_NAME = RELEASE_NAME
    module._EXPRESSION_FREEDOM_INSTALLED = True


