_OPERATIONAL_STATE_FILENAME = "current_operational_state.json"
_OPERATIONAL_RECEIPT_SCAN_LIMIT = 500
_OPERATIONAL_TRACE_SCAN_LIMIT = 250


def _operational_parse_datetime(value: object) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except Exception:
        return None


def _operational_datetime_rank(value: object) -> float:
    parsed = _operational_parse_datetime(value)
    return parsed.timestamp() if parsed else 0.0


def _operational_runtime_compatibility(current_version: str, receipt_version: str) -> str:
    current = str(current_version or "").strip()
    receipt = str(receipt_version or "").strip()
    if current and receipt == current:
        return "current_runtime"
    current_match = re.match(r"^(\d+)\.(\d+)", current)
    receipt_match = re.match(r"^(\d+)\.(\d+)", receipt)
    if current_match and receipt_match and current_match.groups() == receipt_match.groups():
        return "compatible_prior_checkpoint"
    return "historical_runtime"


def _operational_receipt_type(path: Path, data: dict) -> str:
    benchmark = data.get("benchmark") or {}
    name = str(benchmark.get("name") or "").strip().casefold()
    filename = path.name.casefold()
    if name == "retrieval_levels" or filename.startswith("retrieval-levels-"):
        return "retrieval_levels"
    if name == "pilot738" or filename.startswith("pilot738-"):
        return "pilot738"
    return name or "benchmark"


def _operational_receipt_type_priority(receipt_type: str) -> int:
    return {"retrieval_levels": 3, "pilot738": 2, "benchmark": 1}.get(str(receipt_type), 0)


def _operational_scan_benchmark_receipts(module) -> list[dict]:
    root = Path(module.MEMORY_DIR) / "benchmarks" / "receipts"
    records: list[dict] = []
    try:
        paths = sorted(root.glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)[:_OPERATIONAL_RECEIPT_SCAN_LIMIT]
    except Exception:
        paths = []
    for path in paths:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict) or not isinstance(data.get("benchmark"), dict):
                continue
            benchmark = data.get("benchmark") or {}
            summary = data.get("summary") or {}
            validation = data.get("receipt_validation") or {}
            environment = data.get("environment") or {}
            finished_at = benchmark.get("finished_at") or data.get("finished_at")
            status = str(validation.get("status") or "UNKNOWN").strip().upper()
            receipt_type = _operational_receipt_type(path, data)
            runtime_version = str(environment.get("neatmemory_version") or environment.get("runtime_version") or benchmark.get("runtime_version") or "").strip()
            compatibility = _operational_runtime_compatibility(module.NEATMEMORY_VERSION, runtime_version)
            try:
                modified_at = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).replace(microsecond=0).isoformat()
                modified_rank = path.stat().st_mtime
            except Exception:
                modified_at = None
                modified_rank = 0.0
            records.append({
                "receipt_name": path.name,
                "absolute_path": str(path.resolve()),
                "receipt_type": receipt_type,
                "benchmark_name": benchmark.get("name"),
                "benchmark_version": benchmark.get("version"),
                "run_id": benchmark.get("run_id"),
                "started_at": benchmark.get("started_at"),
                "finished_at": finished_at,
                "validation_status": status,
                "validation_errors": list(validation.get("errors") or []),
                "validator": validation.get("validator"),
                "planned_cases": summary.get("planned_cases"),
                "completed_cases": summary.get("completed_cases"),
                "failed_cases": summary.get("failed_cases"),
                "primary_evidence_gate_failures": summary.get("primary_evidence_gate_failures"),
                "questions_with_identical_levels": summary.get("questions_with_identical_levels"),
                "questions_with_nondecreasing_tokens": summary.get("questions_with_nondecreasing_tokens"),
                "provider": environment.get("provider"),
                "model": environment.get("model"),
                "runtime_version": runtime_version,
                "retrieval_engine": environment.get("retrieval_engine"),
                "runtime_compatibility": compatibility,
                "file_modified_at": modified_at,
                "_finished_rank": _operational_datetime_rank(finished_at),
                "_modified_rank": modified_rank,
                "_type_priority": _operational_receipt_type_priority(receipt_type),
                "_compatibility_priority": {"current_runtime": 2, "compatible_prior_checkpoint": 1, "historical_runtime": 0}.get(compatibility, 0),
            })
        except Exception:
            continue
    return records


def _operational_select_latest_validated_benchmark(module, records: list[dict] | None = None) -> tuple[dict | None, list[dict]]:
    records = list(records if records is not None else _operational_scan_benchmark_receipts(module))
    passing = [row for row in records if row.get("validation_status") == "PASS"]
    pool = passing or records
    ordered = sorted(
        pool,
        key=lambda row: (
            1 if row.get("validation_status") == "PASS" else 0,
            float(row.get("_finished_rank") or 0.0),
            int(row.get("_compatibility_priority") or 0),
            int(row.get("_type_priority") or 0),
            float(row.get("_modified_rank") or 0.0),
        ),
        reverse=True,
    )
    selected = dict(ordered[0]) if ordered else None
    historical = []
    selected_name = str((selected or {}).get("receipt_name") or "")
    for row in sorted(records, key=lambda item: (float(item.get("_finished_rank") or 0.0), float(item.get("_modified_rank") or 0.0)), reverse=True):
        if str(row.get("receipt_name") or "") == selected_name:
            continue
        clean = {k: v for k, v in row.items() if not str(k).startswith("_")}
        clean["operational_status"] = "historical"
        historical.append(clean)
        if len(historical) >= 5:
            break
    if selected:
        selected = {k: v for k, v in selected.items() if not str(k).startswith("_")}
        selected["operational_status"] = "newest_validated_benchmark" if selected.get("validation_status") == "PASS" else "newest_available_unvalidated_benchmark"
        selected["current_runtime_has_matching_receipt"] = selected.get("runtime_compatibility") == "current_runtime"
    return selected, historical


def _operational_safe_live_citation_validation_record(trace: dict, row) -> dict | None:
    """Project a live citation-validation trace into hash-only operational state.

    The authoritative retrieval trace may retain its original query under its own
    governance. The hidden operational index must not duplicate that prose.
    """
    trace = dict(trace or {})
    citation = trace.get("citation_commands") or {}
    validation = citation.get("validation") or {}
    if validation.get("status") not in {"PASS", "PASS_CORRECTED"}:
        return None
    if not validation.get("automatic_commands_used"):
        return None
    raw_query = str(trace.get("query") or "")
    try:
        trace_id = row["trace_id"]
        recorded_at = row["created_at"]
    except Exception:
        trace_id = getattr(row, "trace_id", None) if row is not None else None
        recorded_at = getattr(row, "created_at", None) if row is not None else None
    return {
        "trace_id": trace_id,
        "recorded_at": recorded_at,
        "query_sha256": hashlib.sha256(raw_query.encode("utf-8")).hexdigest() if raw_query else None,
        "raw_query_stored": False,
        "catalog_level": validation.get("catalog_level"),
        "validation_status": validation.get("status"),
        "validator": validation.get("validator"),
        "commands_found": list(validation.get("commands_found") or []),
        "resolved_command_count": len(validation.get("resolved_commands") or []),
        "unresolved_commands": list(validation.get("unresolved_commands") or []),
        "automatic_commands_used": bool(validation.get("automatic_commands_used")),
        "manually_typed_ids": list(validation.get("manually_typed_ids") or []),
        "invalid_manual_ids": list(validation.get("invalid_manual_ids") or []),
        "corrected_ids": list(validation.get("corrected_ids") or []),
        "final_cited_ids": list(validation.get("final_cited_ids") or []),
    }


def _operational_latest_live_citation_validation(module) -> dict | None:
    try:
        module._ensure_retrieval_trace_schema()
        with module.db_connect() as db:
            rows = db.execute(
                "SELECT trace_id,created_at,trace_json FROM retrieval_trace_log ORDER BY trace_id DESC LIMIT ?",
                (_OPERATIONAL_TRACE_SCAN_LIMIT,),
            ).fetchall()
    except Exception:
        rows = []
    for row in rows:
        try:
            trace = json.loads(row["trace_json"] or "{}")
            projected = _operational_safe_live_citation_validation_record(trace, row)
            if projected is not None:
                return projected
        except Exception:
            continue
    return None


def _operational_token_calibration(module) -> dict:
    path = Path(module.MEMORY_DIR) / _DOMAIN_CALIBRATION_FILE
    try:
        data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
    except Exception as exc:
        return {"path": str(path.resolve()), "exists": path.exists(), "error": f"{type(exc).__name__}: {exc}"}
    provider = str(module.get_setting("active_provider", "local") or "local")
    model = str(module.get_setting("online_model", "") or module.get_setting("model", "") or "")
    profiles = data.get("profiles") if isinstance(data, dict) else None
    if not isinstance(profiles, dict):
        profiles = data if isinstance(data, dict) else {}
    matching = []
    for key, value in profiles.items():
        if not isinstance(value, dict):
            continue
        key_text = str(key)
        if key_text.startswith(provider + "|"):
            domain_priority = 2 if key_text.endswith("|system") else (1 if "|system|" in key_text else 0)
            matching.append((domain_priority, str(value.get("updated_at") or ""), key_text, value))
    matching.sort(reverse=True)
    selected_key = matching[0][2] if matching else None
    selected = matching[0][3] if matching else None
    return {
        "path": str(path.resolve()),
        "exists": path.exists(),
        "active_provider": provider,
        "configured_model": model or None,
        "selected_profile_key": selected_key,
        "selected_profile": selected,
        "available_profile_keys": sorted(str(key) for key in profiles),
    }


def _operational_build_state(module, query: str, level: str) -> dict:
    selected_benchmark, historical = _operational_select_latest_validated_benchmark(module)
    citation_validation = _operational_latest_live_citation_validation(module)
    calibration = _operational_token_calibration(module)
    backup_reader=globals().get("_nc_operational_backup_evidence")
    try: backup_verification=backup_reader(module) if callable(backup_reader) else None
    except Exception as exc: backup_verification={"available":False,"artifact_verified":False,"status":"UNAVAILABLE","error":f"{type(exc).__name__}: {exc}"}
    generated_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    current_runtime = {
        "neatmemory_version": module.NEATMEMORY_VERSION,
        "schema_version": getattr(module, "SCHEMA_VERSION", None),
        "retrieval_engine": getattr(module, "RETRIEVAL_ENGINE_VERSION", None),
        "citation_engine": getattr(module, "CITATION_ENGINE_VERSION", None),
        "active_provider": module.get_setting("active_provider", "local"),
        "selected_domain": list(getattr(module, "_DOMAIN_ACTIVE_DOMAINS", None) or []),
        "candidate_level": level,
        "generated_at": generated_at,
    }
    return {
        "schema": "neatmemory_current_operational_state_v1",
        "generated_at": generated_at,
        "query": str(query),
        "candidate_level": level,
        "selection_policy": [
            "validated receipts before unvalidated receipts",
            "newest finished_at before older receipts",
            "runtime compatibility as a tie-breaker",
            "retrieval-level receipts before older pilot formats as a tie-breaker",
            "file modification time only as a final fallback",
        ],
        "current_runtime": current_runtime,
        "latest_validated_benchmark": selected_benchmark,
        "latest_live_citation_validation": citation_validation,
        "latest_backup_verification": backup_verification,
        "token_calibration": calibration,
        "historical_benchmarks": historical,
    }


_OPERATIONAL_INDEX_VERSION = "2.1-hidden-on-demand-query-hash-only"


def _operational_context_delivery_snapshot(module) -> dict:
    """Return bounded mechanical current-delivery/projection state without raw prose."""
    delivery = dict(getattr(module, "_CONTEXT_DELIVERY_LAST_RECEIPT", {}) or {})
    mcp_last = dict(getattr(module, "_MODEL_CONTEXT_CONTROL_LAST", {}) or {})
    mcp_summary = {}
    if mcp_last:
        try:
            mcp_summary = dict(_mcp_projection_summary(mcp_last) or {})
        except Exception:
            mcp_summary = {}
    categories = dict(mcp_summary.get("category_totals") or {})
    recent = dict(categories.get("recent_raw") or {})
    unknown = dict(mcp_summary.get("unregistered") or {})
    dq = str(delivery.get("query_sha256") or "")
    pq = str(mcp_last.get("query_sha256") or "")
    relation = "same_turn" if dq and pq and dq == pq else ("projection_unavailable" if not pq else "different_turn")
    return {
        "delivery_available": bool(delivery),
        "delivery": {
            "receipt_sha256": delivery.get("receipt_sha256"),
            "created_at": delivery.get("created_at"),
            "level": delivery.get("level"),
            "delivery_complete": delivery.get("delivery_complete"),
            "incomplete_reasons": list(delivery.get("incomplete_reasons") or []),
            "provider_depth_delivered": delivery.get("provider_depth_delivered"),
            "recent_soft_delivered_tokens": delivery.get("recent_soft_delivered_tokens"),
            "recent_hard_limit_applied": delivery.get("recent_hard_limit_applied"),
            "recent_hard_tokens_beyond_limit": delivery.get("recent_hard_tokens_beyond_limit"),
            "query_sha256": dq or None,
            "raw_query_stored": False,
        } if delivery else None,
        "projection_available": bool(mcp_last),
        "projection_relation_to_delivery": relation,
        "model_context_projection": {
            "version": mcp_last.get("version"),
            "provider": mcp_last.get("provider"),
            "mode": mcp_last.get("mode"),
            "query_sha256": pq or None,
            "raw_query_stored": False,
            "tokens_before": mcp_last.get("tokens_before"),
            "tokens_after": mcp_last.get("tokens_after"),
            "tokens_saved": mcp_last.get("tokens_saved"),
            "recent_raw": {
                "blocks": recent.get("blocks", 0),
                "tokens_before": recent.get("tokens_before", 0),
                "tokens_after": recent.get("tokens_after", 0),
            },
            "unregistered": {
                "blocks": unknown.get("blocks", 0),
                "tokens_before": unknown.get("tokens_before", 0),
                "producer_totals": list(unknown.get("producer_totals") or [])[:16],
                "normal_policy": unknown.get("normal_policy"),
            },
        } if mcp_last else None,
    }


def _operational_index_hash(payload: dict) -> str:
    core = {k: v for k, v in dict(payload or {}).items() if k != "index_sha256"}
    return hashlib.sha256(json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")).hexdigest()


def _operational_read_cached_index(module) -> dict:
    path = Path(getattr(module, "_OPERATIONAL_STATE_PATH", Path(module.MEMORY_DIR) / _OPERATIONAL_STATE_FILENAME))
    if not path.exists():
        return {"ok": False, "available": False, "path": str(path.resolve()), "reason": "index_not_materialized"}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            raise ValueError("index root is not an object")
        expected = str(data.get("index_sha256") or "")
        actual = _operational_index_hash(data)
        return {"ok": bool(expected) and expected == actual, "available": True, "path": str(path.resolve()), "integrity_ok": bool(expected) and expected == actual, "index": data}
    except Exception as exc:
        return {"ok": False, "available": True, "path": str(path.resolve()), "integrity_ok": False, "error": f"{type(exc).__name__}: {exc}"}


def _operational_refresh_hidden_index(module, *, reason: str = "on_demand", persist: bool = True) -> dict:
    """Rebuild the dark operational pointer from retained mechanical evidence.

    The index is derived/cache state only. It is never injected into model context,
    never becomes semantic authority, and stores no raw query/context prose.
    """
    level = str(getattr(module, "_DOMAIN_ACTIVE_LEVEL", None) or "low").strip().casefold()
    if level not in {"low", "mid", "high"}:
        level = "low"
    state = dict(_operational_build_state(module, "", level) or {})
    state.pop("query", None)
    state["schema"] = "neatmemory_hidden_operational_state_index_v2"
    state["version"] = _OPERATIONAL_INDEX_VERSION
    state["index_role"] = "derived read-only freshness pointer over authoritative operational receipts; not semantic authority"
    state["provider_injection"] = False
    state["automatic_context_injection"] = False
    state["automatic_citation_injection"] = False
    state["refresh_reason"] = str(reason or "on_demand")
    state["latest_context_delivery"] = _operational_context_delivery_snapshot(module)
    state["model_calls"] = 0
    state["web_calls"] = 0
    path = Path(getattr(module, "_OPERATIONAL_STATE_PATH", Path(module.MEMORY_DIR) / _OPERATIONAL_STATE_FILENAME))
    previous = _operational_read_cached_index(module)
    prev_index = dict(previous.get("index") or {}) if isinstance(previous, dict) else {}
    if prev_index:
        state["previous_index"] = {
            "index_sha256": prev_index.get("index_sha256"),
            "generated_at": prev_index.get("generated_at"),
            "bundle_version": ((prev_index.get("current_runtime") or {}).get("neatmemory_version")),
        }
    else:
        state["previous_index"] = None
    state["index_sha256"] = _operational_index_hash(state)
    if persist:
        _domain_atomic_write_json(path, state)
    module._OPERATIONAL_LAST_STATE = dict(state)
    return {
        "ok": True,
        "version": _OPERATIONAL_INDEX_VERSION,
        "path": str(path.resolve()),
        "persisted": bool(persist),
        "integrity_ok": _operational_index_hash(state) == state.get("index_sha256"),
        "index": state,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    }


def _operational_get_hidden_index(module, *, refresh: bool = True) -> dict:
    if refresh:
        return _operational_refresh_hidden_index(module, reason="explicit_read", persist=True)
    cached = _operational_read_cached_index(module)
    cached.update({"version": _OPERATIONAL_INDEX_VERSION, "read_only": True, "model_calls": 0, "web_calls": 0})
    return cached


def _operational_catalog_from_state(state: dict) -> dict:
    runtime = state.get("current_runtime") or {}
    benchmark = state.get("latest_validated_benchmark") or {}
    citation = state.get("latest_live_citation_validation") or {}
    calibration = state.get("token_calibration") or {}
    backup = state.get("latest_backup_verification") or {}
    entries = []

    runtime_facts = [
        f"Current NeatMemory runtime is {runtime.get('neatmemory_version')}",
        f"Retrieval engine is {runtime.get('retrieval_engine')}",
        f"Citation engine is {runtime.get('citation_engine')}",
        f"Active provider is {runtime.get('active_provider')}",
    ]
    entries.append({
        "handle": "S1", "role": "SYSTEM_RUNTIME", "contribution": "current runtime and active engines",
        "memory_ids": [], "neatblock_ids": [], "book_ids": [], "chunk_ids": [],
        "fact_lines": _citation_unique(runtime_facts),
        "receipt_names": [], "paths": [],
        "versions": _citation_unique([runtime.get("neatmemory_version"), runtime.get("retrieval_engine"), runtime.get("citation_engine")]),
        "timestamps": _citation_unique([runtime.get("generated_at")]), "all_ids": [],
    })

    if benchmark:
        benchmark_facts = [
            f"Newest validated benchmark type is {benchmark.get('receipt_type')}",
            f"Completed {benchmark.get('completed_cases')} of {benchmark.get('planned_cases')} cases with {benchmark.get('failed_cases')} failures",
            f"Receipt validation is {benchmark.get('validation_status')}",
            f"Benchmark runtime relation is {benchmark.get('runtime_compatibility')}",
        ]
        entries.append({
            "handle": "S2", "role": "SYSTEM_BENCHMARK", "contribution": "newest validated benchmark selected by operational freshness policy",
            "memory_ids": [], "neatblock_ids": [], "book_ids": [], "chunk_ids": [],
            "fact_lines": _citation_unique(benchmark_facts),
            "receipt_names": _citation_unique([benchmark.get("receipt_name")]),
            "paths": _citation_unique([benchmark.get("absolute_path")]),
            "versions": _citation_unique([benchmark.get("runtime_version"), benchmark.get("retrieval_engine"), benchmark.get("benchmark_version")]),
            "timestamps": _citation_unique([benchmark.get("started_at"), benchmark.get("finished_at")]), "all_ids": [],
        })

    if citation:
        citation_facts = [
            f"Latest live canonical citation validation is {citation.get('validation_status')}",
            f"Automatic citation commands used: {citation.get('automatic_commands_used')}",
            f"Resolved commands: {citation.get('resolved_command_count')}",
            f"Manually typed IDs: {len(citation.get('manually_typed_ids') or [])}",
            f"Invalid manual IDs: {len(citation.get('invalid_manual_ids') or [])}",
        ]
        entries.append({
            "handle": "S3", "role": "SYSTEM_CITATION", "contribution": "newest successful live citation-command validation from trace history",
            "memory_ids": [], "neatblock_ids": [], "book_ids": [], "chunk_ids": [],
            "fact_lines": _citation_unique(citation_facts),
            "receipt_names": _citation_unique([f"retrieval_trace_log:{citation.get('trace_id')}"]),
            "paths": [], "versions": _citation_unique([citation.get("validator")]),
            "timestamps": _citation_unique([citation.get("recorded_at")]), "all_ids": [],
        })

    selected_profile = calibration.get("selected_profile") or {}
    calibration_facts = [
        f"Calibration profile is {calibration.get('selected_profile_key') or '[none]'}",
        f"Calibration factor is {selected_profile.get('factor') if selected_profile else '[unavailable]'}",
        f"Calibration samples are {selected_profile.get('samples') if selected_profile else '[unavailable]'}",
    ]
    entries.append({
        "handle": "S4", "role": "SYSTEM_CALIBRATION", "contribution": "current provider/model token-calibration state",
        "memory_ids": [], "neatblock_ids": [], "book_ids": [], "chunk_ids": [],
        "fact_lines": _citation_unique(calibration_facts),
        "receipt_names": _citation_unique([calibration.get("selected_profile_key")]),
        "paths": _citation_unique([calibration.get("path")]),
        "versions": [], "timestamps": _citation_unique([selected_profile.get("updated_at") if selected_profile else None]), "all_ids": [],
    })

    if backup:
        backup_facts = [
            f"Latest backup receipt status is {backup.get('status')}",
            f"Backup artifact cryptographically verified: {backup.get('artifact_verified')}",
            f"Receipt hash chain valid: {backup.get('hash_chain_valid')}",
            f"Backup operation was {backup.get('operation')}",
            f"Backup file is {backup.get('backup_file')}",
            f"Backup contains {backup.get('chat_rows')} chat rows and {backup.get('workshop_files')} Workshop files",
            f"Live-chat relation at verification was {backup.get('live_relation')}",
            f"Restore performed: {backup.get('restore_performed')}; live state modified: {backup.get('live_state_modified')}",
        ]
        entries.append({
            "handle": "S5", "role": "SYSTEM_BACKUP_VERIFICATION", "contribution": "newest durable NeatCrypt backup creation/verification receipt",
            "memory_ids": [], "neatblock_ids": [], "book_ids": [], "chunk_ids": [],
            "fact_lines": _citation_unique(backup_facts),
            "receipt_names": _citation_unique([backup.get("receipt_id"),backup.get("receipt_file")]),
            "paths": [],
            "versions": _citation_unique([backup.get("source_bundle_version"),backup.get("format_version")]),
            "timestamps": _citation_unique([backup.get("verified_at")]), "all_ids": [],
        })

    roles: dict[str, list[str]] = {}
    for entry in entries:
        roles.setdefault(str(entry.get("role") or "").upper(), []).append(str(entry.get("handle")))
    return {
        "query": str(state.get("query") or ""),
        "level": str(state.get("candidate_level") or ""),
        "query_kind": "system_operational",
        "entries": entries,
        "roles": roles,
        "canonical_ids": [],
    }


def _operational_merge_catalogs(base: dict, addition: dict) -> dict:
    base = dict(base or {})
    addition = dict(addition or {})
    entries = list(base.get("entries") or []) + list(addition.get("entries") or [])
    roles: dict[str, list[str]] = {}
    for source in (base.get("roles") or {}, addition.get("roles") or {}):
        for role, handles in source.items():
            roles.setdefault(str(role), [])
            for handle in handles or []:
                if handle not in roles[str(role)]:
                    roles[str(role)].append(handle)
    return {
        "query": str(base.get("query") or addition.get("query") or ""),
        "level": str(base.get("level") or addition.get("level") or ""),
        "query_kind": str(base.get("query_kind") or addition.get("query_kind") or ""),
        "entries": entries,
        "roles": roles,
        "canonical_ids": _citation_unique(list(base.get("canonical_ids") or []) + list(addition.get("canonical_ids") or [])),
    }


def _operational_context_text(state: dict) -> str:
    runtime = state.get("current_runtime") or {}
    benchmark = state.get("latest_validated_benchmark") or {}
    citation = state.get("latest_live_citation_validation") or {}
    calibration = state.get("token_calibration") or {}
    selected_profile = calibration.get("selected_profile") or {}
    backup = state.get("latest_backup_verification") or {}
    lines = [
        "AUTHORITATIVE CURRENT OPERATIONAL INDEX — PYTHON-CALCULATED",
        "This index overrides any older 'latest benchmark' label that may appear in broad historical diagnostics above.",
        f"Generated: {state.get('generated_at')} | candidate depth: {state.get('candidate_level')}",
        "S1 CURRENT RUNTIME",
        f"- NeatMemory: {runtime.get('neatmemory_version')}",
        f"- Retrieval engine: {runtime.get('retrieval_engine')}",
        f"- Citation engine: {runtime.get('citation_engine')}",
        f"- Provider: {runtime.get('active_provider')}",
    ]
    if benchmark:
        current_note = "current runtime" if benchmark.get("current_runtime_has_matching_receipt") else f"{benchmark.get('runtime_compatibility')}; current runtime has not yet produced a matching benchmark receipt"
        lines.extend([
            "S2 NEWEST VALIDATED BENCHMARK",
            f"- Receipt: {benchmark.get('receipt_name')}",
            f"- Type: {benchmark.get('receipt_type')} | finished: {benchmark.get('finished_at')}",
            f"- Result: {benchmark.get('completed_cases')}/{benchmark.get('planned_cases')} completed; {benchmark.get('failed_cases')} failed; validation {benchmark.get('validation_status')}",
            f"- Runtime: {benchmark.get('runtime_version')} ({current_note})",
            f"- Path: {benchmark.get('absolute_path')}",
        ])
    else:
        lines.extend(["S2 NEWEST VALIDATED BENCHMARK", "- No benchmark receipt was found."])
    if citation:
        lines.extend([
            "S3 NEWEST LIVE CITATION VALIDATION",
            f"- Trace: {citation.get('trace_id')} | recorded: {citation.get('recorded_at')}",
            f"- Status: {citation.get('validation_status')} | automatic commands: {citation.get('automatic_commands_used')}",
            f"- Resolved: {citation.get('resolved_command_count')} | manual IDs: {len(citation.get('manually_typed_ids') or [])} | invalid IDs: {len(citation.get('invalid_manual_ids') or [])}",
        ])
    else:
        lines.extend(["S3 NEWEST LIVE CITATION VALIDATION", "- No successful automatic citation-command trace was found."])
    lines.extend([
        "S4 TOKEN CALIBRATION",
        f"- Profile: {calibration.get('selected_profile_key') or '[none]'}",
        f"- Factor: {selected_profile.get('factor') if selected_profile else '[unavailable]'} | samples: {selected_profile.get('samples') if selected_profile else '[unavailable]'}",
        f"- Path: {calibration.get('path')}",
    ])
    if backup:
        lines.extend([
            "S5 NEWEST DURABLE BACKUP VERIFICATION",
            f"- Receipt: {backup.get('receipt_id')} | operation: {backup.get('operation')} | verified: {backup.get('verified_at')}",
            f"- Artifact: {backup.get('backup_file')} | SHA-256: {backup.get('backup_sha256')}",
            f"- Result: status {backup.get('status')} | artifact verified {backup.get('artifact_verified')} | receipt chain valid {backup.get('hash_chain_valid')}",
            f"- Contents: {backup.get('chat_rows')} chat rows | {backup.get('workshop_files')} Workshop files | {backup.get('issue_lifecycle_rows')} issue rows",
            f"- Live relation: {backup.get('live_relation')} | restore performed {backup.get('restore_performed')} | live state modified {backup.get('live_state_modified')}",
            f"- Receipt file: {backup.get('receipt_file')}",
        ])
    lines.append("Historical receipts are context only and must not be described as the newest result.")
    return "\n".join(lines)


def _install_current_operational_evidence(module) -> None:
    if getattr(module, "_CURRENT_OPERATIONAL_EVIDENCE_INSTALLED", False):
        return

    # .219: this subsystem is deliberately dark. It does not decorate
    # build_runtime_context, does not alter SYSTEM_PROMPT, and does not add an
    # operational citation catalog to ordinary model context.
    module.OPERATIONAL_EVIDENCE_VERSION = _OPERATIONAL_INDEX_VERSION
    module.OPERATIONAL_EVIDENCE_AUTO_INJECTION = False
    module._OPERATIONAL_STATES_BY_LEVEL = {}
    module._OPERATIONAL_LAST_STATE = {}
    module._OPERATIONAL_STATE_PATH = Path(module.MEMORY_DIR) / _OPERATIONAL_STATE_FILENAME

    module._operational_scan_benchmark_receipts = lambda: _operational_scan_benchmark_receipts(module)
    module._operational_select_latest_validated_benchmark = lambda records=None: _operational_select_latest_validated_benchmark(module, records)
    module._operational_latest_live_citation_validation = lambda: _operational_latest_live_citation_validation(module)
    module._operational_build_state = lambda query="", level="low": _operational_build_state(module, query, level)
    module._operational_catalog_from_state = _operational_catalog_from_state
    module._operational_refresh_hidden_index = lambda reason="on_demand", persist=True: _operational_refresh_hidden_index(module, reason=reason, persist=persist)
    module.get_current_operational_state_index = lambda refresh=True: _operational_get_hidden_index(module, refresh=refresh)

    def current_operational_evidence_self_test() -> dict:
        synthetic = [
            {
                "receipt_name": "older-pass.json", "validation_status": "PASS", "finished_at": "2026-08-04T08:00:00+00:00",
                "runtime_compatibility": "compatible_prior_checkpoint", "receipt_type": "retrieval_levels",
                "_finished_rank": _operational_datetime_rank("2026-08-04T08:00:00+00:00"), "_compatibility_priority": 1,
                "_type_priority": 3, "_modified_rank": 1.0,
            },
            {
                "receipt_name": "newer-fail.json", "validation_status": "FAIL", "finished_at": "2026-08-04T09:00:00+00:00",
                "runtime_compatibility": "current_runtime", "receipt_type": "retrieval_levels",
                "_finished_rank": _operational_datetime_rank("2026-08-04T09:00:00+00:00"), "_compatibility_priority": 2,
                "_type_priority": 3, "_modified_rank": 2.0,
            },
            {
                "receipt_name": "newest-pass.json", "validation_status": "PASS", "finished_at": "2026-08-04T08:30:00+00:00",
                "runtime_compatibility": "compatible_prior_checkpoint", "receipt_type": "retrieval_levels",
                "_finished_rank": _operational_datetime_rank("2026-08-04T08:30:00+00:00"), "_compatibility_priority": 1,
                "_type_priority": 3, "_modified_rank": 3.0,
            },
        ]
        selected, historical = _operational_select_latest_validated_benchmark(module, synthetic)
        privacy_probe_query = "private operational citation validation query"
        privacy_probe = _operational_safe_live_citation_validation_record({
            "query": privacy_probe_query,
            "citation_commands": {"validation": {
                "status": "PASS", "automatic_commands_used": True, "catalog_level": "low",
                "validator": "synthetic", "commands_found": ["[[CITE:S1]]"],
                "resolved_commands": ["[[CITE:S1]]"], "unresolved_commands": [],
            }},
        }, {"trace_id": 7, "created_at": "2026-08-27T00:00:00+00:00"})
        saved_delivery = getattr(module, "_CONTEXT_DELIVERY_LAST_RECEIPT", None)
        saved_projection = getattr(module, "_MODEL_CONTEXT_CONTROL_LAST", None)
        try:
            qhash = hashlib.sha256(b"self-test").hexdigest()
            module._CONTEXT_DELIVERY_LAST_RECEIPT = {
                "receipt_sha256": "a" * 64, "created_at": "2026-08-27T16:41:13+00:00", "level": "low",
                "delivery_complete": True, "incomplete_reasons": [], "provider_depth_delivered": "low",
                "recent_soft_delivered_tokens": 14964, "recent_hard_limit_applied": False,
                "recent_hard_tokens_beyond_limit": 0, "query_sha256": qhash,
            }
            module._MODEL_CONTEXT_CONTROL_LAST = {
                "ok": True, "version": "1.3-registered-producer-span-scope", "provider": "online", "mode": "NORMAL",
                "query_sha256": qhash, "raw_query_stored": False, "tokens_before": 40223, "tokens_after": 20547,
                "tokens_saved": 19676, "variables": [
                    {"category": "recent_raw", "action": "included", "tokens_before": 16619, "tokens_after": 16619, "registered": True},
                    {"category": "other_context", "action": "available_not_projected", "tokens_before": 1988, "tokens_after": 0, "registered": False, "producer_family": "unattributed", "producer_stage": "provider_bound_unattributed", "unregistered_signature_sha256": "b" * 64},
                ],
                "semantic_ranking": False, "semantic_sufficiency_decision": False,
                "user_or_assistant_history_rewritten": False, "exact_evidence_byte_preservation": True,
            }
            hidden = _operational_refresh_hidden_index(module, reason="self_test", persist=False)
            idx = dict(hidden.get("index") or {})
            snap = dict(idx.get("latest_context_delivery") or {})
            proj = dict(snap.get("model_context_projection") or {})
            checks = {
                "newer_failed_receipt_does_not_displace_pass": selected.get("receipt_name") == "newest-pass.json",
                "historical_receipts_labeled": all(row.get("operational_status") == "historical" for row in historical),
                "hidden_index_is_integrity_bound": hidden.get("integrity_ok") is True and len(str(idx.get("index_sha256") or "")) == 64,
                "hidden_index_stores_no_raw_query": "query" not in idx and snap.get("delivery", {}).get("raw_query_stored") is False,
                "citation_validation_sanitizer_is_hash_only": bool(privacy_probe) and "query" not in privacy_probe and privacy_probe.get("raw_query_stored") is False and privacy_probe.get("query_sha256") == hashlib.sha256(privacy_probe_query.encode("utf-8")).hexdigest(),
                "live_citation_snapshot_is_hash_only": (not (idx.get("latest_live_citation_validation") or {})) or ("query" not in (idx.get("latest_live_citation_validation") or {}) and (idx.get("latest_live_citation_validation") or {}).get("raw_query_stored") is False),
                "current_delivery_is_indexed": snap.get("delivery", {}).get("receipt_sha256") == "a" * 64 and snap.get("delivery", {}).get("delivery_complete") is True,
                "current_projection_is_indexed": snap.get("projection_relation_to_delivery") == "same_turn" and proj.get("recent_raw", {}).get("tokens_before") == 16619 and proj.get("unregistered", {}).get("tokens_before") == 1988,
                "index_declares_no_provider_injection": idx.get("provider_injection") is False and idx.get("automatic_context_injection") is False and idx.get("automatic_citation_injection") is False,
                "system_prompt_not_modified_by_operational_index": "CURRENT OPERATIONAL EVIDENCE RULE" not in str(module.SYSTEM_PROMPT),
                "runtime_compatibility_classified": _operational_runtime_compatibility("7.4.5-current", "7.4.3-prior") == "compatible_prior_checkpoint",
                "zero_model_zero_web": int(hidden.get("model_calls") or 0) == 0 and int(hidden.get("web_calls") or 0) == 0,
            }
            return {"ok": all(checks.values()), "checks": checks, "version": _OPERATIONAL_INDEX_VERSION, "model_calls": 0, "web_calls": 0, "persistent_writes": False}
        finally:
            module._CONTEXT_DELIVERY_LAST_RECEIPT = saved_delivery
            module._MODEL_CONTEXT_CONTROL_LAST = saved_projection

    module.current_operational_evidence_self_test = current_operational_evidence_self_test
    module._CURRENT_OPERATIONAL_EVIDENCE_INSTALLED = True

# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:benchmark-citation-binding rev=1
# Per-case retrieval-benchmark citation resolution and validation (7.4.5.1)
# ---------------------------------------------------------------------------
_BENCHMARK_CITATION_ENGINE_VERSION = "1.1-per-case-catalog-binding"


def _benchmark_citation_catalog_summary(catalog: dict) -> dict:
    catalog = dict(catalog or {})
    return {
        "query": str(catalog.get("query") or ""),
        "level": str(catalog.get("level") or ""),
        "query_kind": str(catalog.get("query_kind") or ""),
        "entries": list(catalog.get("entries") or []),
        "roles": dict(catalog.get("roles") or {}),
        "canonical_ids": list(catalog.get("canonical_ids") or []),
    }


def _benchmark_finalize_case_citations(module, case: dict, question_text: str, forced_level: str, catalog: dict) -> dict:
    case = dict(case or {})
    question_text = str(question_text or "")
    forced_level = str(forced_level or "").strip().casefold()
    catalog = dict(catalog or {})
    raw_answer = str(case.get("answer") or "")
    case["raw_model_answer"] = raw_answer
    case["citation_catalog"] = _benchmark_citation_catalog_summary(catalog)

    visible, validation = module._citation_process_answer(raw_answer, catalog)
    validation = dict(validation or {})
    errors = list(validation.get("errors") or [])
    catalog_query = str(catalog.get("query") or "")
    catalog_level = str(catalog.get("level") or "").strip().casefold()
    query_matches = catalog_query == question_text
    level_matches = catalog_level == forced_level
    remaining_commands = [match.group(0) for match in _CITATION_COMMAND_RE.finditer(visible)]
    available_handles = [str(entry.get("handle") or "") for entry in (catalog.get("entries") or [])]

    if not query_matches:
        errors.append("citation catalog query does not match this benchmark case")
    if not level_matches:
        errors.append("citation catalog level does not match the forced benchmark level")
    if available_handles and not validation.get("commands_found"):
        errors.append("the model did not use any supplied citation command")
    if validation.get("manually_typed_ids"):
        errors.append("benchmark answers must use citation commands instead of manually typed NB/BK identifiers")
    if remaining_commands:
        errors.append("one or more raw citation commands remained after benchmark resolution")

    errors = _citation_unique(errors)
    prior_status = str(validation.get("status") or "PASS")
    if errors:
        status = "FAIL"
    elif prior_status == "PASS_CORRECTED":
        status = "PASS_CORRECTED"
    else:
        status = "PASS"

    validation.update({
        "status": status,
        "errors": errors,
        "catalog_query": catalog_query,
        "catalog_level": catalog_level,
        "benchmark_question": question_text,
        "forced_level": forced_level,
        "catalog_query_matches_case": query_matches,
        "catalog_level_matches_forced_level": level_matches,
        "available_handles": available_handles,
        "remaining_commands_after_resolution": remaining_commands,
        "raw_answer_preserved": True,
        "resolved_answer_saved": True,
        "validator": "neatmemory_benchmark_per_case_citation_v1",
    })

    case["answer"] = visible
    case["citation_validation"] = validation
    case["answer_contains_raw_citation_commands"] = bool(remaining_commands)

    trace_wrapper = dict(case.get("trace") or {})
    trace_payload = dict(trace_wrapper.get("trace") or {})
    trace_payload["citation_commands"] = {
        "catalog": _benchmark_citation_catalog_summary(catalog),
        "validation": validation,
        "benchmark_case_bound": True,
    }
    trace_wrapper["trace"] = trace_payload
    case["trace"] = trace_wrapper

    if status == "FAIL" and case.get("status") == "completed":
        case["status"] = "failed"
        case["error"] = {
            "type": "BenchmarkCitationValidationError",
            "message": "; ".join(errors or ["per-case benchmark citation validation failed"]),
            "stage": "benchmark_citation_validation",
            "retryable": False,
        }
    return case



# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:portable-recovery rev=1
# Portable passphrase-encrypted identity backup layer (7.4.9.2)
# ---------------------------------------------------------------------------
_PORTABLE_BACKUP_KIND = "neatmemory_portable_identity_backup"
_PORTABLE_BACKUP_SCHEMA_VERSION = "1"
_PORTABLE_BACKUP_ENVELOPE_VERSION = "1"
_PORTABLE_BACKUP_EXTENSION = ".nmib"
_PORTABLE_BACKUP_AAD = b"NeatMemory Portable Identity Backup v1"
_PORTABLE_BACKUP_MAX_BYTES = 256 * 1024 * 1024
_PORTABLE_BACKUP_MIN_PASSPHRASE = 12
_PORTABLE_SCRYPT_N = 2 ** 15
_PORTABLE_SCRYPT_R = 8
_PORTABLE_SCRYPT_P = 1
_PORTABLE_SCRYPT_DKLEN = 32


def _portable_crypto_capability() -> dict:
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM  # noqa: F401
        return {
            "available": True,
            "cipher": "AES-256-GCM",
            "kdf": "scrypt",
            "runtime_encryption": "Windows DPAPI",
            "portable_extension": _PORTABLE_BACKUP_EXTENSION,
        }
    except Exception as exc:
        return {
            "available": False,
            "error": f"{type(exc).__name__}: {exc}",
            "install": "python -m pip install cryptography",
            "runtime_encryption": "Windows DPAPI remains available on Windows",
        }


def _portable_aesgcm():
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        return AESGCM
    except Exception as exc:
        raise RuntimeError(
            "Portable identity backups require the audited 'cryptography' package. "
            "Install it with: python -m pip install cryptography"
        ) from exc


def _portable_passphrase_bytes(passphrase: str) -> bytes:
    value = str(passphrase or "")
    if len(value) < _PORTABLE_BACKUP_MIN_PASSPHRASE:
        raise ValueError(
            f"Portable backup passphrase must contain at least {_PORTABLE_BACKUP_MIN_PASSPHRASE} characters."
        )
    return value.encode("utf-8")


def _portable_derive_key(passphrase: str, salt: bytes, *, n: int, r: int, p: int) -> bytes:
    secret = _portable_passphrase_bytes(passphrase)
    if len(salt) < 16:
        raise ValueError("Portable backup salt is too short.")
    if not (2 ** 14 <= int(n) <= 2 ** 20 and 1 <= int(r) <= 32 and 1 <= int(p) <= 16):
        raise ValueError("Portable backup KDF parameters are outside accepted safety limits.")
    return hashlib.scrypt(
        secret,
        salt=salt,
        n=int(n),
        r=int(r),
        p=int(p),
        dklen=_PORTABLE_SCRYPT_DKLEN,
        maxmem=256 * 1024 * 1024,
    )


def _portable_canonical_bytes(value: object) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _portable_component_digest(value: object) -> str:
    return hashlib.sha256(_portable_canonical_bytes(value)).hexdigest()


def _portable_default_backup_path() -> Path:
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    return (Path.cwd() / "identity_backups" / f"neatmemory_identity_{stamp}{_PORTABLE_BACKUP_EXTENSION}").resolve()


def _portable_resolve_path(raw: str | None, *, for_write: bool) -> Path:
    text = os.path.expandvars(str(raw or "").strip().strip('"'))
    if not text:
        path = _portable_default_backup_path()
    else:
        path = Path(text).expanduser()
        if not path.is_absolute():
            path = Path.cwd() / path
        if path.exists() and path.is_dir():
            stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
            path = path / f"neatmemory_identity_{stamp}{_PORTABLE_BACKUP_EXTENSION}"
        elif for_write and path.suffix.casefold() != _PORTABLE_BACKUP_EXTENSION:
            path = path.with_suffix(_PORTABLE_BACKUP_EXTENSION)
        path = path.resolve()
    if for_write:
        path.parent.mkdir(parents=True, exist_ok=True)
    return path


def _portable_read_required_component(module, filename: str, entropy: bytes, expected_kind: str) -> dict:
    payload, status = _identity_read_encrypted_json(module, filename, entropy)
    if not isinstance(payload, dict):
        raise RuntimeError(f"Cannot export {filename}: {status}.")
    if payload.get("kind") != expected_kind:
        raise RuntimeError(f"Cannot export {filename}: unexpected payload kind {payload.get('kind')!r}.")
    return payload


def _portable_collect_emotion_logbook(module) -> list[dict]:
    _ensure_affective_schema(module)
    with _affect_db(module) as db:
        rows = db.execute("SELECT * FROM emotion_logbook ORDER BY timestamp, rowid").fetchall()
    return [dict(row) for row in rows]


def _portable_collect_payload(module) -> dict:
    if os.name != "nt" and not getattr(module, "_IDENTITY_TEST_MODE", False):
        raise RuntimeError("Creating a portable backup requires access to the current Windows DPAPI identity files.")
    _identity_bootstrap(module)
    _startup_view_bootstrap(module)
    _refresh_current_self_snapshot(module, reason="portable_identity_export")

    personality = _portable_read_required_component(
        module, module.PERSONALITY_ENCRYPTED_FILE, module.PERSONALITY_DPAPI_ENTROPY, _PERSONALITY_KIND
    )
    current_self = _portable_read_required_component(
        module, module.CURRENT_SELF_ENCRYPTED_FILE, module.CURRENT_SELF_DPAPI_ENTROPY, _CURRENT_SELF_KIND
    )
    active_continuity = _portable_read_required_component(
        module, _ACTIVE_CONTINUITY_FILE, _ACTIVE_CONTINUITY_ENTROPY, _ACTIVE_CONTINUITY_KIND
    )
    startup_view = _portable_read_required_component(
        module, _STARTUP_VIEW_FILE, _STARTUP_VIEW_ENTROPY, _STARTUP_VIEW_KIND
    )
    session_handoff, _session_status_text = _load_session_handoff(module)
    emotion_logbook = _portable_collect_emotion_logbook(module)
    perception_profiles = _perception_export_component(module)
    self_continuity = _self_export_component(module)

    components = {
        "personality": personality,
        "current_self": current_self,
        "active_continuity": active_continuity,
        "startup_view": startup_view,
        "last_session_handoff": session_handoff,
        "emotion_logbook": emotion_logbook,
        "perception_profiles": perception_profiles,
        "self_continuity": self_continuity,
    }
    payload = {
        "kind": _PORTABLE_BACKUP_KIND,
        "schema_version": _PORTABLE_BACKUP_SCHEMA_VERSION,
        "created_at": _identity_now(),
        "source_bundle_version": BUNDLE_VERSION,
        "components": components,
        "settings": {
            "emotion_rate_multiplier": str(module.get_setting("emotion_rate_multiplier", "1.0") or "1.0"),
            "endpoint_context_tokens": str(module.get_setting("endpoint_context_tokens", "") or ""),
            "current_self_enabled": str(module.get_setting("current_self_enabled", "1") or "1"),
        },
        "manifest": {
            "component_sha256": {name: _portable_component_digest(value) for name, value in components.items()},
            "component_count": len(components),
            "emotion_logbook_entries": len(emotion_logbook),
            "perception_profile_versions": len(perception_profiles.get("profiles") or []),
            "self_continuity_note_versions": len(self_continuity.get("notes") or []),
            "self_continuity_cycle_events": len(self_continuity.get("cycle_events") or []),
        },
        "recovery_note": (
            "Machine-independent passphrase backup. Runtime files remain protected by Windows DPAPI; "
            "import re-encrypts them for the new Windows user profile."
        ),
    }
    return payload


def _portable_validate_payload(payload: object) -> dict:
    if not isinstance(payload, dict):
        raise ValueError("Portable backup payload must be a JSON object.")
    if payload.get("kind") != _PORTABLE_BACKUP_KIND:
        raise ValueError("This file is not a NeatMemory portable identity backup.")
    if str(payload.get("schema_version")) != _PORTABLE_BACKUP_SCHEMA_VERSION:
        raise ValueError(f"Unsupported portable backup schema: {payload.get('schema_version')!r}.")
    components = payload.get("components")
    if not isinstance(components, dict):
        raise ValueError("Portable backup components are missing.")
    required = {
        "personality": _PERSONALITY_KIND,
        "current_self": _CURRENT_SELF_KIND,
        "active_continuity": _ACTIVE_CONTINUITY_KIND,
        "startup_view": _STARTUP_VIEW_KIND,
        "last_session_handoff": _SESSION_HANDOFF_KIND,
    }
    for name, kind in required.items():
        value = components.get(name)
        if not isinstance(value, dict) or value.get("kind") != kind:
            raise ValueError(f"Portable backup component {name!r} is missing or invalid.")
    if not isinstance(components.get("emotion_logbook", []), list):
        raise ValueError("Portable backup emotion_logbook component is invalid.")
    perception_component = components.get("perception_profiles")
    if perception_component is not None:
        if not isinstance(perception_component, dict) or perception_component.get("kind") != _PERCEPTION_KIND:
            raise ValueError("Portable backup perception_profiles component is invalid.")
        if str(perception_component.get("schema_version")) != _PERCEPTION_SCHEMA_VERSION:
            raise ValueError("Portable backup perception_profiles schema is unsupported.")
    self_component = components.get("self_continuity")
    if self_component is not None:
        if not isinstance(self_component, dict) or self_component.get("kind") != _SELF_CONTINUITY_KIND:
            raise ValueError("Portable backup self_continuity component is invalid.")
        if str(self_component.get("schema_version")) != _SELF_CONTINUITY_SCHEMA_VERSION:
            raise ValueError("Portable backup self_continuity schema is unsupported.")
    expected = ((payload.get("manifest") or {}).get("component_sha256") or {})
    for name, value in components.items():
        digest = _portable_component_digest(value)
        if expected and str(expected.get(name) or "") != digest:
            raise ValueError(f"Portable backup manifest mismatch for component {name!r}.")
    return payload


def _portable_encrypt_payload(payload: dict, passphrase: str) -> dict:
    AESGCM = _portable_aesgcm()
    plaintext = _portable_canonical_bytes(_portable_validate_payload(payload))
    salt = os.urandom(16)
    nonce = os.urandom(12)
    key = _portable_derive_key(
        passphrase, salt, n=_PORTABLE_SCRYPT_N, r=_PORTABLE_SCRYPT_R, p=_PORTABLE_SCRYPT_P
    )
    ciphertext = AESGCM(key).encrypt(nonce, plaintext, _PORTABLE_BACKUP_AAD)
    return {
        "kind": _PORTABLE_BACKUP_KIND,
        "envelope_version": _PORTABLE_BACKUP_ENVELOPE_VERSION,
        "created_at": payload.get("created_at"),
        "cipher": "AES-256-GCM",
        "kdf": {
            "name": "scrypt",
            "n": _PORTABLE_SCRYPT_N,
            "r": _PORTABLE_SCRYPT_R,
            "p": _PORTABLE_SCRYPT_P,
            "salt_b64": base64.b64encode(salt).decode("ascii"),
        },
        "nonce_b64": base64.b64encode(nonce).decode("ascii"),
        "payload_sha256": hashlib.sha256(plaintext).hexdigest(),
        "ciphertext_b64": base64.b64encode(ciphertext).decode("ascii"),
    }


def _portable_decrypt_envelope(envelope: object, passphrase: str) -> dict:
    AESGCM = _portable_aesgcm()
    if not isinstance(envelope, dict) or envelope.get("kind") != _PORTABLE_BACKUP_KIND:
        raise ValueError("This file is not a NeatMemory portable identity backup envelope.")
    if str(envelope.get("envelope_version")) != _PORTABLE_BACKUP_ENVELOPE_VERSION:
        raise ValueError(f"Unsupported portable backup envelope: {envelope.get('envelope_version')!r}.")
    kdf = envelope.get("kdf") or {}
    if kdf.get("name") != "scrypt" or envelope.get("cipher") != "AES-256-GCM":
        raise ValueError("Unsupported portable backup cryptographic parameters.")
    try:
        salt = base64.b64decode(str(kdf.get("salt_b64") or ""), validate=True)
        nonce = base64.b64decode(str(envelope.get("nonce_b64") or ""), validate=True)
        ciphertext = base64.b64decode(str(envelope.get("ciphertext_b64") or ""), validate=True)
    except Exception as exc:
        raise ValueError("Portable backup contains invalid base64 data.") from exc
    if len(nonce) != 12:
        raise ValueError("Portable backup AES-GCM nonce has an invalid length.")
    key = _portable_derive_key(
        passphrase,
        salt,
        n=int(kdf.get("n", 0)),
        r=int(kdf.get("r", 0)),
        p=int(kdf.get("p", 0)),
    )
    try:
        plaintext = AESGCM(key).decrypt(nonce, ciphertext, _PORTABLE_BACKUP_AAD)
    except Exception as exc:
        raise ValueError("Wrong passphrase or damaged portable backup.") from exc
    expected = str(envelope.get("payload_sha256") or "")
    if not expected or hashlib.sha256(plaintext).hexdigest() != expected:
        raise ValueError("Portable backup plaintext integrity check failed.")
    try:
        payload = json.loads(plaintext.decode("utf-8"))
    except Exception as exc:
        raise ValueError("Portable backup plaintext is not valid UTF-8 JSON.") from exc
    return _portable_validate_payload(payload)


def _portable_write_backup(module, path: Path, passphrase: str) -> dict:
    payload = _portable_collect_payload(module)
    envelope = _portable_encrypt_payload(payload, passphrase)
    raw = json.dumps(envelope, ensure_ascii=False, indent=2, sort_keys=True).encode("utf-8") + b"\n"
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        with temporary.open("wb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        if temporary.stat().st_size > _PORTABLE_BACKUP_MAX_BYTES:
            raise ValueError("Portable backup exceeds the configured safety limit.")
        check_envelope = json.loads(temporary.read_text(encoding="utf-8"))
        verified = _portable_decrypt_envelope(check_envelope, passphrase)
        if verified.get("created_at") != payload.get("created_at"):
            raise RuntimeError("Portable backup readback verification returned the wrong payload.")
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)
    return {
        "ok": True,
        "path": str(path),
        "bytes": path.stat().st_size,
        "created_at": payload.get("created_at"),
        "source_bundle_version": payload.get("source_bundle_version"),
        "components": sorted((payload.get("components") or {}).keys()),
        "emotion_logbook_entries": len((payload.get("components") or {}).get("emotion_logbook") or []),
        "perception_profile_versions": len((((payload.get("components") or {}).get("perception_profiles") or {}).get("profiles") or [])),
        "active_perception_profile_id": ((payload.get("components") or {}).get("perception_profiles") or {}).get("active_profile_id"),
        "encryption": "AES-256-GCM with scrypt-derived key",
        "portable": True,
        "reminder": "Keep the passphrase separately and copy the .nmib file to another machine or trusted backup location.",
    }


def _portable_read_backup(path: Path, passphrase: str) -> dict:
    if not path.exists() or not path.is_file():
        raise FileNotFoundError(f"Portable identity backup not found: {path}")
    size = path.stat().st_size
    if size <= 0 or size > _PORTABLE_BACKUP_MAX_BYTES:
        raise ValueError("Portable identity backup size is outside accepted limits.")
    try:
        envelope = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError("Portable identity backup envelope is not valid JSON.") from exc
    return _portable_decrypt_envelope(envelope, passphrase)


def _portable_payload_summary(path: Path, payload: dict) -> dict:
    components = payload.get("components") or {}
    return {
        "ok": True,
        "path": str(path),
        "created_at": payload.get("created_at"),
        "source_bundle_version": payload.get("source_bundle_version"),
        "personality_revision": (components.get("personality") or {}).get("revision"),
        "active_continuity_revision": (components.get("active_continuity") or {}).get("revision"),
        "startup_view_revision": (components.get("startup_view") or {}).get("revision"),
        "last_session_handoff_id": (components.get("last_session_handoff") or {}).get("handoff_id"),
        "current_self_updated_at": (components.get("current_self") or {}).get("updated_at"),
        "emotion_logbook_entries": len(components.get("emotion_logbook") or []),
        "perception_profile_versions": len((components.get("perception_profiles") or {}).get("profiles") or []),
        "active_perception_profile_id": (components.get("perception_profiles") or {}).get("active_profile_id"),
        "self_continuity_note_versions": len((components.get("self_continuity") or {}).get("notes") or []),
        "self_continuity_global_cycle": ((components.get("self_continuity") or {}).get("runtime_state") or {}).get("global_cycle"),
        "integrity": "AES-GCM authentication, payload SHA-256, and per-component SHA-256 all verified",
    }


def _portable_archive_runtime_files(module) -> list[str]:
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    files = [
        module.PERSONALITY_ENCRYPTED_FILE,
        module.CURRENT_SELF_ENCRYPTED_FILE,
        _ACTIVE_CONTINUITY_FILE,
        _STARTUP_VIEW_FILE,
        _SESSION_HANDOFF_FILE,
        _PERCEPTION_FILE,
        _SELF_CONTINUITY_FILE,
    ]
    archived: list[str] = []
    for filename in files:
        source = module.safe_memory_path(filename)
        if not source.exists():
            continue
        folder = source.parent / "identity_import_recovery"
        folder.mkdir(parents=True, exist_ok=True)
        destination = folder / f"{source.name}.preimport-{stamp}.enc"
        destination.write_bytes(source.read_bytes())
        archived.append(str(destination))
    return archived


def _portable_parse_snapshot_time(snapshot: dict) -> datetime:
    raw = str(snapshot.get("updated_at") or snapshot.get("current_timestamp") or "")
    try:
        return _parse_iso(raw)
    except Exception:
        return _affect_now_dt()


def _portable_age_snapshot(snapshot: dict, now_dt: datetime) -> tuple[dict[str, float], dict[str, float], float]:
    source_dt = _portable_parse_snapshot_time(snapshot)
    elapsed = max(0.0, (now_dt - source_dt).total_seconds() / 60.0)
    try:
        rate = max(0.0, min(100.0, float(snapshot.get("emotion_rate_multiplier", 1.0))))
    except Exception:
        rate = 1.0
    raw_emotions = {str(k).upper(): v for k, v in (snapshot.get("emotions") or {}).items()}
    emotions: dict[str, float] = {}
    for name, profile in _EMOTION_PROFILES.items():
        previous = _clamp01(raw_emotions.get(name, profile["rest_strength"]), profile["rest_strength"])
        emotions[name.casefold()] = _natural_strength(
            previous,
            profile["rest_strength"],
            elapsed * rate,
            profile["half_life_minutes"],
        )
    raw_somatic = {str(k).upper(): v for k, v in (snapshot.get("somatic") or {}).items()}
    somatic: dict[str, float] = {}
    for name, profile in _SOMATIC_PROFILES.items():
        if name == "HEART_RATE_INTENSITY":
            continue
        previous = _somatic_clamp(name, raw_somatic.get(name, profile["rest_value"]))
        somatic[name.casefold()] = _somatic_natural_value(name, previous, elapsed)
    somatic["heart_rate_intensity"] = _heart_intensity_from_bpm(somatic["heart_rate_bpm"])
    return emotions, somatic, elapsed


def _portable_insert_logbook_rows(db: sqlite3.Connection, rows: list[dict]) -> int:
    if not rows:
        return 0
    columns = [str(row[1]) for row in db.execute("PRAGMA table_info(emotion_logbook)").fetchall()]
    inserted = 0
    for item in rows:
        if not isinstance(item, dict) or not item.get("emotion_id"):
            continue
        selected = [name for name in columns if name in item]
        if not selected:
            continue
        placeholders = ",".join("?" for _ in selected)
        quoted = ",".join(f'"{name}"' for name in selected)
        before = db.total_changes
        db.execute(
            f"INSERT OR IGNORE INTO emotion_logbook({quoted}) VALUES({placeholders})",
            tuple(item.get(name) for name in selected),
        )
        inserted += max(0, db.total_changes - before)
    return inserted


def _portable_seed_sqlite_identity(module, snapshot: dict, logbook_rows: list[dict], *, source_path: str) -> dict:
    _ensure_affective_schema(module)
    _ensure_somatic_schema(module)
    now_dt = _affect_now_dt()
    now_text = now_dt.replace(microsecond=0).isoformat()
    imported_emotions, imported_somatic, source_elapsed = _portable_age_snapshot(snapshot, now_dt)
    current_affect = get_current_affective_state(module, now_dt=now_dt)
    current_somatic = get_current_somatic_state(module, now_dt=now_dt, affective_state=current_affect)
    suffix = datetime.now().strftime("%Y%m%d%H%M%S") + "-" + os.urandom(4).hex()
    affective_id = f"AS-PORTABLE-{suffix}"
    somatic_id = f"SS-PORTABLE-{suffix}"
    raw_import = json.dumps({
        "source": "portable_identity_backup",
        "source_path": source_path,
        "source_snapshot_updated_at": snapshot.get("updated_at"),
        "source_elapsed_minutes_applied": round(source_elapsed, 6),
    }, ensure_ascii=False, sort_keys=True)

    with _affect_db(module) as db:
        previous_affective = db.execute(
            "SELECT state_id, created_at FROM affective_states ORDER BY created_at DESC, rowid DESC LIMIT 1"
        ).fetchone()
        db.execute(
            """INSERT INTO affective_states(
                state_id,previous_state_id,created_at,session_id,turn_id,core_values_json,
                temporary_emotions_json,trajectory_json,reason_codes_json,source,provider,model,
                validation_status,raw_proposal_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                affective_id,
                previous_affective["state_id"] if previous_affective else None,
                now_text,
                "portable_import",
                "portable_import",
                json.dumps(imported_emotions, ensure_ascii=False, sort_keys=True),
                "[]",
                json.dumps({"portable_import": True, "source_elapsed_minutes": source_elapsed}, sort_keys=True),
                '["portable_identity_import"]',
                "portable_identity_import",
                "python",
                BUNDLE_VERSION,
                "validated",
                raw_import,
            ),
        )
        prior_emotions = current_affect.get("core") or {}
        previous_affective_timestamp = str(current_affect.get("current_timestamp") or now_text)
        raw_snapshot_emotions = {str(k).upper(): v for k, v in (snapshot.get("emotions") or {}).items()}
        for name, profile in _EMOTION_PROFILES.items():
            key = name.casefold()
            previous = float(prior_emotions.get(key, profile["rest_strength"]))
            requested = _clamp01(raw_snapshot_emotions.get(name, imported_emotions[key]), imported_emotions[key])
            applied = float(imported_emotions[key])
            delta = applied - previous
            direction = "increase" if delta > 1e-9 else "decrease" if delta < -1e-9 else "stable"
            db.execute(
                """INSERT INTO emotion_metric_events(
                    state_id,emotion_name,previous_strength,natural_strength,requested_strength,
                    applied_strength,delta,direction,previous_timestamp,current_timestamp,
                    elapsed_minutes,confidence,reason_text,comment_text,limit_applied,provider,model,raw_request_json
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    affective_id, name, previous, previous, requested, applied, delta, direction,
                    previous_affective_timestamp, now_text, 0.0, 1.0,
                    "Portable identity backup restored on a new/current Windows profile.",
                    str(snapshot.get("current_self_comment") or "")[:_IDENTITY_MAX_TEXT],
                    0, "python", BUNDLE_VERSION, raw_import,
                ),
            )

        previous_somatic = db.execute(
            "SELECT state_id, created_at FROM somatic_states ORDER BY created_at DESC, rowid DESC LIMIT 1"
        ).fetchone()
        db.execute(
            """INSERT INTO somatic_states(
                state_id,previous_state_id,created_at,values_json,trajectory_json,cross_effects_json,
                source,provider,model,validation_status,raw_proposal_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
            (
                somatic_id,
                previous_somatic["state_id"] if previous_somatic else None,
                now_text,
                json.dumps(imported_somatic, ensure_ascii=False, sort_keys=True),
                json.dumps({"portable_import": True, "source_elapsed_minutes": source_elapsed}, sort_keys=True),
                "[]",
                "portable_identity_import",
                "python",
                BUNDLE_VERSION,
                "validated",
                raw_import,
            ),
        )
        prior_somatic = current_somatic.get("core") or {}
        previous_somatic_timestamp = str(current_somatic.get("current_timestamp") or now_text)
        raw_snapshot_somatic = {str(k).upper(): v for k, v in (snapshot.get("somatic") or {}).items()}
        for name, profile in _SOMATIC_PROFILES.items():
            key = name.casefold()
            previous = float(prior_somatic.get(key, profile["rest_value"]))
            requested = _somatic_clamp(name, raw_snapshot_somatic.get(name, imported_somatic[key]))
            applied = float(imported_somatic[key])
            delta = applied - previous
            direction = "increase" if delta > 1e-9 else "decrease" if delta < -1e-9 else "stable"
            db.execute(
                """INSERT INTO somatic_metric_events(
                    state_id,state_name,unit,previous_value,natural_value,cross_adjusted_value,
                    requested_value,applied_value,delta,direction,previous_timestamp,current_timestamp,
                    elapsed_minutes,confidence,reason_text,comment_text,limit_applied,provider,model,raw_request_json
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    somatic_id, name, profile["unit"], previous, previous, previous, requested, applied,
                    delta, direction, previous_somatic_timestamp, now_text, 0.0, 1.0,
                    "Portable identity backup restored on a new/current Windows profile.",
                    str(snapshot.get("current_self_comment") or "")[:_IDENTITY_MAX_TEXT],
                    0, "python", BUNDLE_VERSION, raw_import,
                ),
            )
        logbook_inserted = _portable_insert_logbook_rows(db, logbook_rows)

    return {
        "affective_state_id": affective_id,
        "somatic_state_id": somatic_id,
        "source_elapsed_minutes_applied": round(source_elapsed, 6),
        "emotion_logbook_rows_inserted": logbook_inserted,
    }


def _portable_restore_payload(module, payload: dict, *, source_path: Path) -> dict:
    if os.name != "nt" and not getattr(module, "_IDENTITY_TEST_MODE", False):
        raise RuntimeError(
            "Portable backup verification works on any platform, but restoring DPAPI runtime files requires Windows."
        )
    payload = _portable_validate_payload(payload)
    components = payload["components"]
    archived = _portable_archive_runtime_files(module)
    sqlite_result = _portable_seed_sqlite_identity(
        module,
        components["current_self"],
        components.get("emotion_logbook") or [],
        source_path=str(source_path),
    )

    personality = dict(components["personality"])
    personality.pop("content_sha256", None)
    _identity_write_encrypted_json(
        module, module.PERSONALITY_ENCRYPTED_FILE, module.PERSONALITY_DPAPI_ENTROPY, personality
    )

    continuity = dict(components["active_continuity"])
    continuity.pop("content_sha256", None)
    _identity_write_encrypted_json(module, _ACTIVE_CONTINUITY_FILE, _ACTIVE_CONTINUITY_ENTROPY, continuity)

    startup = dict(components["startup_view"])
    startup.pop("content_sha256", None)
    _write_startup_view(module, startup)

    session_handoff = dict(components.get("last_session_handoff") or _default_session_handoff())
    session_handoff.pop("content_sha256", None)
    session_handoff_sqlite = {"inserted": False, "reason": "empty handoff"}
    if session_handoff.get("handoff_id"):
        _write_session_handoff(module, session_handoff)
        session_handoff_sqlite = _session_seed_handoff_sqlite(module, session_handoff)

    settings = payload.get("settings") or {}
    if "emotion_rate_multiplier" in settings:
        try:
            _set_emotion_rate(module, float(settings["emotion_rate_multiplier"]))
        except Exception:
            pass
    if "endpoint_context_tokens" in settings:
        module.set_setting("endpoint_context_tokens", str(settings.get("endpoint_context_tokens") or ""))
    if "current_self_enabled" in settings:
        module.set_setting("current_self_enabled", "1" if str(settings.get("current_self_enabled")) == "1" else "0")

    perception_restore = _perception_import_component(
        module, components.get("perception_profiles"), source="portable_identity_import", write_snapshot=True
    ) if components.get("perception_profiles") else {"ok": True, "reason": "older backup without perception profiles", "profiles_inserted": 0}
    self_continuity_restore = _self_import_component(
        module, components.get("self_continuity"), source="portable_identity_import", write_snapshot=True
    ) if components.get("self_continuity") else {"ok": True, "reason": "older backup without self-continuity", "note_versions_inserted": 0}

    refreshed = _refresh_current_self_snapshot(
        module,
        comment=str((components.get("current_self") or {}).get("current_self_comment") or ""),
        reason="portable_identity_import",
    )
    verify = _identity_verify_report(module)
    if not verify.get("ok"):
        raise RuntimeError(f"Portable restore completed but identity verification failed: {verify}")
    return {
        "ok": True,
        "source_path": str(source_path),
        "source_bundle_version": payload.get("source_bundle_version"),
        "source_created_at": payload.get("created_at"),
        "recovery_archives": archived,
        "sqlite_identity_seed": sqlite_result,
        "personality_revision": personality.get("revision"),
        "active_continuity_revision": continuity.get("revision"),
        "startup_view_revision": startup.get("revision"),
        "last_session_handoff_id": session_handoff.get("handoff_id"),
        "last_session_handoff_sqlite": session_handoff_sqlite,
        "perception_profiles": perception_restore,
        "self_continuity": self_continuity_restore,
        "current_self": {
            "updated_at": refreshed.get("updated_at"),
            "source_affective_state_id": refreshed.get("source_affective_state_id"),
            "source_somatic_state_id": refreshed.get("source_somatic_state_id"),
        },
        "verification": verify,
        "note": "Imported identity was re-encrypted with DPAPI for the current Windows user profile.",
    }


def _portable_prompt_new_passphrase() -> str:
    first = getpass.getpass("New portable backup passphrase: ")
    second = getpass.getpass("Repeat passphrase: ")
    if first != second:
        raise ValueError("Passphrases did not match.")
    _portable_passphrase_bytes(first)
    return first


def _portable_prompt_passphrase() -> str:
    value = getpass.getpass("Portable backup passphrase: ")
    _portable_passphrase_bytes(value)
    return value


def _portable_backup_status() -> dict:
    capability = _portable_crypto_capability()
    default_folder = str((Path.cwd() / "identity_backups").resolve())
    backups = []
    folder = Path(default_folder)
    if folder.exists():
        backups = [str(path.resolve()) for path in sorted(folder.glob(f"*{_PORTABLE_BACKUP_EXTENSION}"), key=lambda p: p.stat().st_mtime, reverse=True)[:20]]
    return {
        **capability,
        "default_folder": default_folder,
        "recent_backups": backups,
        "commands": [
            "/identity export [file]",
            "/identity backup verify <file>",
            "/identity import <file>",
        ],
        "passphrase_storage": "The passphrase is never stored by NeatMemory.",
    }


def _portable_command_argument(command: str, prefix: str) -> str:
    return command[len(prefix):].strip()


def _portable_identity_handle_command(module, text: str) -> bool:
    command = str(text or "").strip()
    lower = command.casefold()
    if lower in {"/identity portable", "/identity backup", "/identity backup status", "/identity backup list"}:
        print(json.dumps(_portable_backup_status(), ensure_ascii=False, indent=2)); return True

    export_prefix = None
    for candidate in ("/identity export", "/identity backup create"):
        if lower == candidate or lower.startswith(candidate + " "):
            export_prefix = candidate
            break
    if export_prefix:
        try:
            target = _portable_resolve_path(_portable_command_argument(command, export_prefix), for_write=True)
            passphrase = _portable_prompt_new_passphrase()
            result = _portable_write_backup(module, target, passphrase)
            print(json.dumps(result, ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Portable identity export error: {type(exc).__name__}: {exc}")
        return True

    verify_prefix = "/identity backup verify"
    if lower == verify_prefix or lower.startswith(verify_prefix + " "):
        raw_path = _portable_command_argument(command, verify_prefix)
        if not raw_path:
            print("Use /identity backup verify <file.nmib>"); return True
        try:
            path = _portable_resolve_path(raw_path, for_write=False)
            payload = _portable_read_backup(path, _portable_prompt_passphrase())
            print(json.dumps(_portable_payload_summary(path, payload), ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Portable identity verification error: {type(exc).__name__}: {exc}")
        return True

    import_prefix = None
    for candidate in ("/identity import", "/identity restore"):
        if lower == candidate or lower.startswith(candidate + " "):
            import_prefix = candidate
            break
    if import_prefix:
        raw_path = _portable_command_argument(command, import_prefix)
        if not raw_path:
            print("Use /identity import <file.nmib>"); return True
        try:
            path = _portable_resolve_path(raw_path, for_write=False)
            payload = _portable_read_backup(path, _portable_prompt_passphrase())
            summary = _portable_payload_summary(path, payload)
            print(json.dumps({"verified_backup": summary, "action": "restoring now"}, ensure_ascii=False, indent=2))
            result = _portable_restore_payload(module, payload, source_path=path)
            print(json.dumps(result, ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Portable identity import error: {type(exc).__name__}: {exc}")
        return True
    return False


def _install_portable_identity_backup(module) -> None:
    if getattr(module, "_PORTABLE_IDENTITY_BACKUP_INSTALLED", False):
        return
    module.get_portable_identity_backup_status = _portable_backup_status
    module.create_portable_identity_backup = lambda path, passphrase: _portable_write_backup(
        module, _portable_resolve_path(path, for_write=True), passphrase
    )
    module.verify_portable_identity_backup = lambda path, passphrase: _portable_payload_summary(
        _portable_resolve_path(path, for_write=False),
        _portable_read_backup(_portable_resolve_path(path, for_write=False), passphrase),
    )
    module.restore_portable_identity_backup = lambda path, passphrase: _portable_restore_payload(
        module,
        _portable_read_backup(_portable_resolve_path(path, for_write=False), passphrase),
        source_path=_portable_resolve_path(path, for_write=False),
    )
    module.portable_identity_backup_self_test = lambda: portable_identity_backup_self_test(module)

    old_doctor = module.doctor_report
    def doctor_with_portable_backup():
        report = old_doctor()
        report["portable_identity_backup"] = _portable_backup_status()
        return report
    module.doctor_report = doctor_with_portable_backup

    old_main = module.main
    def main_with_portable_identity_commands():
        original_input = builtins.input
        def portable_input(prompt=""):
            while True:
                value = original_input(prompt)
                if _portable_identity_handle_command(module, value):
                    continue
                return value
        builtins.input = portable_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_portable_identity_commands
    module._PORTABLE_IDENTITY_BACKUP_INSTALLED = True


def portable_identity_backup_self_test(module) -> dict:
    capability = _portable_crypto_capability()
    if not capability.get("available"):
        return {"ok": False, "checks": {"cryptography_available": False}, "capability": capability}
    crypto = _identity_crypto()
    original_encrypt = crypto.encrypt_text
    original_decrypt = crypto.decrypt_text
    original_safe_path = module.safe_memory_path
    original_db_connect = module.db_connect
    original_test_mode = getattr(module, "_IDENTITY_TEST_MODE", False)
    original_volatile = getattr(module, "_STARTUP_VIEW_VOLATILE", None)
    original_cwd = Path.cwd()
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    with tempfile.TemporaryDirectory(prefix="neatmemory-portable-") as folder:
        root = Path(folder)
        def fake_encrypt(text: str, *, entropy=None):
            raw = text.encode("utf-8")
            key = hashlib.sha256(bytes(entropy or b"test")).digest()
            cipher = bytes(b ^ key[i % len(key)] for i, b in enumerate(raw))
            return b"TESTENC1" + base64.b64encode(cipher)
        def fake_decrypt(payload: bytes, *, entropy=None):
            if not payload.startswith(b"TESTENC1"):
                raise RuntimeError("bad test cipher")
            cipher = base64.b64decode(payload[8:])
            key = hashlib.sha256(bytes(entropy or b"test")).digest()
            raw = bytes(b ^ key[i % len(key)] for i, b in enumerate(cipher))
            return raw.decode("utf-8")
        crypto.encrypt_text = fake_encrypt
        crypto.decrypt_text = fake_decrypt
        module.safe_memory_path = lambda filename: root / Path(str(filename)).name
        module.db_connect = lambda: test_db
        module._IDENTITY_TEST_MODE = True
        module._STARTUP_VIEW_VOLATILE = None
        try:
            os.chdir(root)
            module.initialize_database()
            _ensure_affective_schema(module)
            _ensure_somatic_schema(module)
            _ensure_identity_schema(module)
            _identity_bootstrap(module)
            _startup_view_bootstrap(module)

            secret = "PORTABLE-SECRET-CONTINUITY-STRING"
            personality, _ = _load_personality_profile(module)
            personality["personality_comment"] = secret
            personality["revision"] = 7
            _write_personality_profile(module, personality)
            continuity, _ = _load_active_continuity(module)
            continuity["current_focus"] = "Preserve identity across Windows reinstall"
            continuity["revision"] = 4
            _write_active_continuity(module, continuity)
            _refresh_current_self_snapshot(module, comment="Portable current self continuity", reason="portable_self_test")
            _apply_startup_display_update(
                module,
                {"startup_display": ["TRUST", "CONNECTION", "HEART_RATE_BPM"]},
                provider="python",
                model="self-test",
            )
            _ensure_self_continuity_schema(module)
            module._SELF_CONTINUITY_SESSION_INITIALIZED = False
            _self_begin_runtime_session(module, force=True)
            portable_self_note = _self_create_note(module, {
                "content": "Portable self-continuity survives Windows reinstall.",
                "comment": "Portable backup integration test.",
                "priority": "high",
                "cycle_length": 7,
                "after_cycle": "review",
                "triggers": ["portable", "continuity"],
            }, actor="Assistant", provider="self-test", model="python", current_cycle=4)
            with module.db_connect() as db:
                db.execute("UPDATE self_continuity_runtime_state SET global_cycle=4,session_cycle=2 WHERE singleton=1")
            _self_write_snapshot(module)

            backup_path = root / f"identity-test{_PORTABLE_BACKUP_EXTENSION}"
            passphrase = "correct horse battery staple"
            created = _portable_write_backup(module, backup_path, passphrase)
            verified_payload = _portable_read_backup(backup_path, passphrase)
            verified = _portable_payload_summary(backup_path, verified_payload)
            wrong_passphrase_rejected = False
            try:
                _portable_read_backup(backup_path, "wrong passphrase value")
            except Exception:
                wrong_passphrase_rejected = True

            replacement = _default_personality_profile()
            replacement["personality_comment"] = "replacement"
            _write_personality_profile(module, replacement)
            _write_active_continuity(module, _default_active_continuity())
            _write_startup_view(module, _default_startup_view())

            restored = _portable_restore_payload(module, verified_payload, source_path=backup_path)
            restored_personality, _ = _load_personality_profile(module)
            restored_continuity, _ = _load_active_continuity(module)
            restored_startup, _ = _load_startup_view(module)
            restored_self_note = _self_get_note(module, portable_self_note["note_id"])
            restored_self_state = _self_runtime_state(module)
            latest_affect = test_db.execute(
                "SELECT source FROM affective_states ORDER BY created_at DESC, rowid DESC LIMIT 1"
            ).fetchone()
            raw_backup = backup_path.read_bytes()
            checks = {
                "cryptography_available": capability.get("available") is True,
                "portable_backup_created": created.get("ok") and backup_path.exists(),
                "backup_contains_no_plaintext_secret": secret.encode("utf-8") not in raw_backup,
                "correct_passphrase_verifies": verified.get("ok") is True,
                "wrong_passphrase_rejected": wrong_passphrase_rejected,
                "personality_restored": restored_personality.get("personality_comment") == secret and restored_personality.get("revision") == 7,
                "active_continuity_restored": restored_continuity.get("current_focus") == "Preserve identity across Windows reinstall",
                "startup_view_restored": [row.get("id") for row in restored_startup.get("selected_variables", [])] == ["TRUST", "CONNECTION", "HEART_RATE_BPM"],
                "self_continuity_restored": bool(restored_self_note and restored_self_note.get("content") == "Portable self-continuity survives Windows reinstall."),
                "self_continuity_cycle_restored": int(restored_self_state.get("global_cycle", 0)) >= 4,
                "sqlite_identity_seeded": bool(latest_affect and latest_affect["source"] == "portable_identity_import"),
                "recovery_archive_created": bool(restored.get("recovery_archives")),
                "post_restore_identity_verifies": bool((restored.get("verification") or {}).get("ok")),
            }
            return {"ok": all(checks.values()), "checks": checks, "sample": verified}
        finally:
            os.chdir(original_cwd)
            crypto.encrypt_text = original_encrypt
            crypto.decrypt_text = original_decrypt
            module.safe_memory_path = original_safe_path
            module.db_connect = original_db_connect
            module._IDENTITY_TEST_MODE = original_test_mode
            module._STARTUP_VIEW_VOLATILE = original_volatile
            test_db.close()


def _install_benchmark_citation_hotfix(module) -> None:
    if getattr(module, "_BENCHMARK_CITATION_HOTFIX_INSTALLED", False):
        return

    module.BENCHMARK_CITATION_ENGINE_VERSION = _BENCHMARK_CITATION_ENGINE_VERSION
    previous_case_runner = module._retrieval_levels_run_case
    previous_benchmark_runner = module.run_benchmark_retrieval_levels

    def per_case_citation_runner(backend, provider: str, question: dict, level: str):
        old_catalogs = dict(getattr(module, "_CITATION_CATALOGS_BY_LEVEL", {}) or {})
        old_last_catalog = dict(getattr(module, "_CITATION_LAST_CATALOG", {}) or {})
        old_last_validation = dict(getattr(module, "_CITATION_LAST_VALIDATION", {}) or {})
        module._CITATION_CATALOGS_BY_LEVEL = {}
        module._CITATION_LAST_CATALOG = {}
        module._CITATION_LAST_VALIDATION = {}
        try:
            case = previous_case_runner(backend, provider, question, level)
            normalized_level = str(level or "").strip().casefold()
            catalog = dict((module._CITATION_CATALOGS_BY_LEVEL or {}).get(normalized_level) or {})
            return _benchmark_finalize_case_citations(
                module,
                case,
                str(question.get("prompt") or question.get("question") or ""),
                normalized_level,
                catalog,
            )
        finally:
            module._CITATION_CATALOGS_BY_LEVEL = old_catalogs
            module._CITATION_LAST_CATALOG = old_last_catalog
            module._CITATION_LAST_VALIDATION = old_last_validation

    module._retrieval_levels_run_case = per_case_citation_runner

    def benchmark_with_per_case_citation_validation(local_backend, active_provider: str):
        result = previous_benchmark_runner(local_backend, active_provider)
        receipt = result.get("receipt") or {}
        cases = list(receipt.get("cases") or [])
        citation_failures = []
        raw_command_failures = []
        catalog_binding_failures = []
        incomplete_cases = []

        for case in cases:
            label = f"{case.get('question_id')}:{case.get('forced_level')}"
            validation = case.get("citation_validation") or {}
            if str(validation.get("status") or "") not in {"PASS", "PASS_CORRECTED"}:
                citation_failures.append(label)
            if case.get("answer_contains_raw_citation_commands") or _CITATION_COMMAND_RE.search(str(case.get("answer") or "")):
                raw_command_failures.append(label)
            if not validation.get("catalog_query_matches_case") or not validation.get("catalog_level_matches_forced_level"):
                catalog_binding_failures.append(label)
            if case.get("status") != "completed":
                incomplete_cases.append(label)

        validation = receipt.setdefault("receipt_validation", {})
        errors = list(validation.get("errors") or [])
        if citation_failures:
            errors.append("per-case citation validation failures: " + ", ".join(citation_failures))
        if raw_command_failures:
            errors.append("resolved answers still contain raw citation commands: " + ", ".join(raw_command_failures))
        if catalog_binding_failures:
            errors.append("citation catalog binding failures: " + ", ".join(catalog_binding_failures))
        if incomplete_cases:
            errors.append("benchmark cases not completed: " + ", ".join(incomplete_cases))
        errors = _citation_unique(errors)
        validation.update({
            "status": "PASS" if not errors else "FAIL",
            "errors": errors,
            "validator": "neatmemory_retrieval_levels_per_case_citation_v1",
            "citation_cases_validated": len(cases) - len(citation_failures),
            "citation_case_failures": len(citation_failures),
            "raw_command_failures": len(raw_command_failures),
            "catalog_binding_failures": len(catalog_binding_failures),
        })

        receipt.setdefault("benchmark", {})["version"] = "1.2-per-case-citation-validation"
        receipt.setdefault("environment", {})["benchmark_citation_engine"] = _BENCHMARK_CITATION_ENGINE_VERSION
        summary = receipt.setdefault("summary", {})
        summary["citation_cases_validated"] = len(cases) - len(citation_failures)
        summary["citation_case_failures"] = len(citation_failures)
        summary["resolved_answers_with_raw_commands"] = len(raw_command_failures)
        summary["catalog_binding_failures"] = len(catalog_binding_failures)

        result["ok"] = not errors
        path = Path(str(result.get("path") or ""))
        if path:
            module._benchmark_atomic_write_json(path, receipt)
        return result

    module.run_benchmark_retrieval_levels = benchmark_with_per_case_citation_validation
    module._benchmark_finalize_case_citations = lambda case, question_text, forced_level, catalog: _benchmark_finalize_case_citations(
        module, case, question_text, forced_level, catalog
    )

    def benchmark_citation_hotfix_self_test() -> dict:
        catalog = {
            "query": "What happened?",
            "level": "low",
            "query_kind": "exact",
            "entries": [{
                "handle": "E1",
                "role": "PRIMARY",
                "contribution": "direct fact",
                "memory_ids": ["NB-20260803-da0d7d58d8"],
                "neatblock_ids": ["NB-fe788700c9412a24f0ac"],
                "book_ids": ["BK-b94004bc3824ec7b"],
                "chunk_ids": ["BK-b94004bc3824ec7b-C000025"],
                "all_ids": [
                    "NB-20260803-da0d7d58d8", "NB-fe788700c9412a24f0ac",
                    "BK-b94004bc3824ec7b", "BK-b94004bc3824ec7b-C000025",
                ],
            }],
            "roles": {"PRIMARY": ["E1"]},
            "canonical_ids": [
                "NB-20260803-da0d7d58d8", "NB-fe788700c9412a24f0ac",
                "BK-b94004bc3824ec7b", "BK-b94004bc3824ec7b-C000025",
            ],
        }
        good = _benchmark_finalize_case_citations(
            module,
            {"status": "completed", "answer": "Supported fact. [[CITE:E1]]", "trace": {"trace": {}}},
            "What happened?", "low", catalog,
        )
        unknown = _benchmark_finalize_case_citations(
            module,
            {"status": "completed", "answer": "Unsupported. [[CITE:E9]]", "trace": {"trace": {}}},
            "What happened?", "low", catalog,
        )
        stale = _benchmark_finalize_case_citations(
            module,
            {"status": "completed", "answer": "Supported fact. [[CITE:E1]]", "trace": {"trace": {}}},
            "A different question", "high", catalog,
        )
        manual = _benchmark_finalize_case_citations(
            module,
            {"status": "completed", "answer": "Manual NB-20260803-da0d7d58d8", "trace": {"trace": {}}},
            "What happened?", "low", catalog,
        )
        checks = {
            "good_case_passes": (good.get("citation_validation") or {}).get("status") == "PASS",
            "good_answer_is_resolved": "[[CITE:" not in str(good.get("answer") or ""),
            "raw_answer_is_preserved": str(good.get("raw_model_answer") or "").endswith("[[CITE:E1]]"),
            "catalog_query_bound": bool((good.get("citation_validation") or {}).get("catalog_query_matches_case")),
            "catalog_level_bound": bool((good.get("citation_validation") or {}).get("catalog_level_matches_forced_level")),
            "unknown_handle_fails": (unknown.get("citation_validation") or {}).get("status") == "FAIL",
            "unknown_handle_fails_case": unknown.get("status") == "failed",
            "stale_query_and_level_fail": (stale.get("citation_validation") or {}).get("status") == "FAIL",
            "manual_identifier_fails_benchmark": (manual.get("citation_validation") or {}).get("status") == "FAIL",
            "trace_has_case_bound_catalog": bool((((good.get("trace") or {}).get("trace") or {}).get("citation_commands") or {}).get("benchmark_case_bound")),
            "engine_version": module.BENCHMARK_CITATION_ENGINE_VERSION == _BENCHMARK_CITATION_ENGINE_VERSION,
        }
        return {"ok": all(checks.values()), "checks": checks}

    module.benchmark_citation_hotfix_self_test = benchmark_citation_hotfix_self_test
    module._BENCHMARK_CITATION_HOTFIX_INSTALLED = True



