_BACKUP_FAMILY_KIND = "neatmemory_recovery_family"
_BACKUP_FAMILY_SCHEMA = "1"
_BACKUP_FAMILY_ROOT = os.getenv("NEATMEMORY_BACKUP_DIR", "assistant_backups").strip() or "assistant_backups"
_BACKUP_FAMILY_MANIFEST = "recovery_manifest.json"
