_BACKUP_CHAT_ROWS_PER_CHUNK = 500
_BACKUP_ENVELOPE_VERSION = "1"
_BACKUP_MAX_COMPONENT_BYTES = 512 * 1024 * 1024
_BACKUP_AAD_WORKSHOP_MANIFEST = b"NeatMemory Recovery Family Workshop Manifest v1"
_BACKUP_AAD_WORKSHOP_FILE_PREFIX = b"NeatMemory Recovery Family Workshop File v1/"
_BACKUP_AAD_CHAT_MANIFEST = b"NeatMemory Recovery Family Raw Chat Manifest v1"
_BACKUP_AAD_CHAT_CHUNK_PREFIX = b"NeatMemory Recovery Family Raw Chat Chunk v1/"


def _bf_now() -> str:
    try:
        return _identity_now()
    except Exception:
        return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _bf_sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def _bf_atomic_bytes(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + f".tmp-{os.getpid()}-{uuid.uuid4().hex[:8]}")
    try:
        with temp.open("wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)


def _bf_atomic_json(path: Path, payload: object) -> None:
    _bf_atomic_bytes(path, json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8") + b"\n")


def _bf_encrypt_json(payload: object, passphrase: str, *, kind: str, aad: bytes) -> dict:
    AESGCM = _portable_aesgcm()
    plaintext = _portable_canonical_bytes(payload)
    if len(plaintext) > _BACKUP_MAX_COMPONENT_BYTES:
        raise ValueError("Recovery component exceeds the configured structural safety ceiling.")
    salt = os.urandom(16)
    nonce = os.urandom(12)
    key = _portable_derive_key(
        passphrase, salt,
        n=_PORTABLE_SCRYPT_N, r=_PORTABLE_SCRYPT_R, p=_PORTABLE_SCRYPT_P,
    )
    ciphertext = AESGCM(key).encrypt(nonce, plaintext, aad)
    return {
        "kind": kind,
        "envelope_version": _BACKUP_ENVELOPE_VERSION,
        "cipher": "AES-256-GCM",
        "kdf": {
            "name": "scrypt", "n": _PORTABLE_SCRYPT_N, "r": _PORTABLE_SCRYPT_R,
            "p": _PORTABLE_SCRYPT_P, "salt_b64": base64.b64encode(salt).decode("ascii"),
        },
        "nonce_b64": base64.b64encode(nonce).decode("ascii"),
        "payload_sha256": hashlib.sha256(plaintext).hexdigest(),
        "ciphertext_b64": base64.b64encode(ciphertext).decode("ascii"),
    }


def _bf_decrypt_json(envelope: object, passphrase: str, *, kind: str, aad: bytes) -> object:
    AESGCM = _portable_aesgcm()
    if not isinstance(envelope, dict) or envelope.get("kind") != kind:
        raise ValueError(f"Recovery component kind mismatch; expected {kind!r}.")
    if str(envelope.get("envelope_version")) != _BACKUP_ENVELOPE_VERSION:
        raise ValueError("Unsupported recovery component envelope version.")
    kdf = envelope.get("kdf") or {}
    if kdf.get("name") != "scrypt" or envelope.get("cipher") != "AES-256-GCM":
        raise ValueError("Unsupported recovery component cryptographic parameters.")
    try:
        salt = base64.b64decode(str(kdf.get("salt_b64") or ""), validate=True)
        nonce = base64.b64decode(str(envelope.get("nonce_b64") or ""), validate=True)
        ciphertext = base64.b64decode(str(envelope.get("ciphertext_b64") or ""), validate=True)
    except Exception as exc:
        raise ValueError("Recovery component contains invalid base64 data.") from exc
    if len(nonce) != 12:
        raise ValueError("Recovery component AES-GCM nonce length is invalid.")
    key = _portable_derive_key(passphrase, salt, n=int(kdf.get("n", 0)), r=int(kdf.get("r", 0)), p=int(kdf.get("p", 0)))
    try:
        plaintext = AESGCM(key).decrypt(nonce, ciphertext, aad)
    except Exception as exc:
        raise ValueError("Wrong passphrase or damaged recovery component.") from exc
    expected = str(envelope.get("payload_sha256") or "")
    if not expected or hashlib.sha256(plaintext).hexdigest() != expected:
        raise ValueError("Recovery component plaintext integrity check failed.")
    try:
        return json.loads(plaintext.decode("utf-8"))
    except Exception as exc:
        raise ValueError("Recovery component plaintext is not valid UTF-8 JSON.") from exc


def _bf_write_envelope(path: Path, envelope: dict) -> dict:
    raw = json.dumps(envelope, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8") + b"\n"
    if len(raw) > _BACKUP_MAX_COMPONENT_BYTES:
        raise ValueError("Encrypted recovery component exceeds the configured safety ceiling.")
    _bf_atomic_bytes(path, raw)
    return {"path": str(path), "bytes": path.stat().st_size, "sha256": _bf_sha256_file(path)}


def _bf_read_envelope(path: Path) -> dict:
    if not path.exists() or not path.is_file():
        raise FileNotFoundError(f"Recovery component not found: {path}")
    if path.stat().st_size <= 0 or path.stat().st_size > _BACKUP_MAX_COMPONENT_BYTES:
        raise ValueError(f"Recovery component size is outside accepted limits: {path}")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError(f"Recovery component is not valid JSON: {path}") from exc
    if not isinstance(value, dict):
        raise ValueError(f"Recovery component envelope is invalid: {path}")
    return value


def _bf_default_root() -> Path:
    root = Path(os.path.expandvars(_BACKUP_FAMILY_ROOT)).expanduser()
    if not root.is_absolute():
        root = Path.cwd() / root
    return root.resolve()


def _bf_default_set_path() -> Path:
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    return _bf_default_root() / f"Assistant_Recovery_{stamp}"


def _bf_resolve_set_path(raw: str | None, *, create: bool = False) -> Path:
    text = os.path.expandvars(str(raw or "").strip().strip('"'))
    if not text:
        path = _bf_default_set_path() if create else _bf_default_root()
    else:
        path = Path(text).expanduser()
        if not path.is_absolute():
            path = Path.cwd() / path
        path = path.resolve()
        if create and path.exists() and path.is_dir() and (path / _BACKUP_FAMILY_MANIFEST).exists():
            raise FileExistsError(f"Recovery set already exists: {path}")
        if create and path.exists() and path.is_dir() and any(path.iterdir()):
            stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
            path = path / f"Assistant_Recovery_{stamp}"
    if create:
        path.parent.mkdir(parents=True, exist_ok=True)
    return path


def _bf_collect_chat_rows(module) -> list[dict]:
    with module.db_connect() as db:
        try:
            rows = db.execute(
                "SELECT message_id,timestamp,role,provider,model,content,is_private,content_sha256 FROM chat_messages ORDER BY message_id"
            ).fetchall()
        except sqlite3.Error as exc:
            raise RuntimeError(f"Cannot back up canonical raw chat: {exc}") from exc
    out = []
    seen = set()
    for raw in rows:
        row = dict(raw)
        mid = int(row.get("message_id") or 0)
        if mid <= 0 or mid in seen:
            raise ValueError("Canonical raw chat contains an invalid or duplicate message_id.")
        seen.add(mid)
        content = str(row.get("content") or "")
        digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
        stored = str(row.get("content_sha256") or "")
        if stored and stored != digest:
            raise ValueError(f"Raw chat content hash mismatch at CHAT-{mid}.")
        out.append({
            "message_id": mid,
            "timestamp": str(row.get("timestamp") or ""),
            "role": str(row.get("role") or ""),
            "provider": str(row.get("provider") or ""),
            "model": str(row.get("model") or ""),
            "content": content,
            "is_private": 1 if bool(row.get("is_private")) else 0,
            "content_sha256": digest,
        })
    return out


def _bf_write_chat_backup(module, folder: Path, passphrase: str) -> dict:
    rows = _bf_collect_chat_rows(module)
    chunk_dir = folder / _BACKUP_CHAT_CHUNKS
    chunk_dir.mkdir(parents=True, exist_ok=True)
    chunk_records = []
    for offset in range(0, len(rows), _BACKUP_CHAT_ROWS_PER_CHUNK):
        selected = rows[offset:offset + _BACKUP_CHAT_ROWS_PER_CHUNK]
        first = int(selected[0]["message_id"])
        last = int(selected[-1]["message_id"])
        name = f"CHAT-{first:010d}-{last:010d}.nmcc"
        payload = {
            "kind": "neatmemory_raw_chat_chunk_payload",
            "schema_version": _BACKUP_FAMILY_SCHEMA,
            "rows": selected,
            "first_message_id": first,
            "last_message_id": last,
            "row_count": len(selected),
        }
        aad = _BACKUP_AAD_CHAT_CHUNK_PREFIX + name.encode("utf-8")
        record = _bf_write_envelope(chunk_dir / name, _bf_encrypt_json(payload, passphrase, kind="neatmemory_raw_chat_chunk_envelope", aad=aad))
        chunk_records.append({"file": f"{_BACKUP_CHAT_CHUNKS}/{name}", "first_message_id": first, "last_message_id": last, "row_count": len(selected), "encrypted_sha256": record["sha256"]})
    public_count = sum(1 for row in rows if not row["is_private"])
    manifest_payload = {
        "kind": "neatmemory_raw_chat_backup_manifest",
        "schema_version": _BACKUP_FAMILY_SCHEMA,
        "created_at": _bf_now(),
        "source_bundle_version": BUNDLE_VERSION,
        "row_count": len(rows),
        "public_count": public_count,
        "private_count": len(rows) - public_count,
        "first_message_id": rows[0]["message_id"] if rows else None,
        "last_message_id": rows[-1]["message_id"] if rows else None,
        "chunks": chunk_records,
    }
    manifest_record = _bf_write_envelope(folder / _BACKUP_CHAT_MANIFEST, _bf_encrypt_json(manifest_payload, passphrase, kind="neatmemory_raw_chat_manifest_envelope", aad=_BACKUP_AAD_CHAT_MANIFEST))
    return {"row_count": len(rows), "public_count": public_count, "private_count": len(rows)-public_count, "chunk_count": len(chunk_records), "manifest": _BACKUP_CHAT_MANIFEST, "manifest_sha256": manifest_record["sha256"]}


def _bf_read_chat_backup(folder: Path, passphrase: str) -> dict:
    manifest_path = folder / _BACKUP_CHAT_MANIFEST
    manifest = _bf_decrypt_json(_bf_read_envelope(manifest_path), passphrase, kind="neatmemory_raw_chat_manifest_envelope", aad=_BACKUP_AAD_CHAT_MANIFEST)
    if not isinstance(manifest, dict) or manifest.get("kind") != "neatmemory_raw_chat_backup_manifest":
        raise ValueError("Raw-chat recovery manifest is invalid.")
    rows = []
    for record in manifest.get("chunks") or []:
        rel = str((record or {}).get("file") or "")
        path = (folder / rel).resolve()
        if folder.resolve() not in path.parents:
            raise ValueError("Raw-chat recovery component path escapes its recovery folder.")
        if str((record or {}).get("encrypted_sha256") or "") != _bf_sha256_file(path):
            raise ValueError(f"Encrypted raw-chat chunk hash mismatch: {rel}")
        name = path.name
        payload = _bf_decrypt_json(_bf_read_envelope(path), passphrase, kind="neatmemory_raw_chat_chunk_envelope", aad=_BACKUP_AAD_CHAT_CHUNK_PREFIX + name.encode("utf-8"))
        if not isinstance(payload, dict) or payload.get("kind") != "neatmemory_raw_chat_chunk_payload":
            raise ValueError(f"Raw-chat chunk payload is invalid: {rel}")
        chunk_rows = list(payload.get("rows") or [])
        if int(payload.get("row_count") or 0) != len(chunk_rows):
            raise ValueError(f"Raw-chat chunk row count mismatch: {rel}")
        rows.extend(chunk_rows)
    if int(manifest.get("row_count") or 0) != len(rows):
        raise ValueError("Raw-chat recovery total row count mismatch.")
    seen = set()
    previous = 0
    clean = []
    for raw in rows:
        if not isinstance(raw, dict):
            raise ValueError("Raw-chat recovery row is invalid.")
        mid = int(raw.get("message_id") or 0)
        if mid <= 0 or mid in seen or mid <= previous:
            raise ValueError("Raw-chat recovery message IDs must be unique, positive, and strictly ordered.")
        seen.add(mid); previous = mid
        content = str(raw.get("content") or "")
        digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
        if str(raw.get("content_sha256") or "") != digest:
            raise ValueError(f"Raw-chat recovery content hash mismatch at CHAT-{mid}.")
        clean.append({
            "message_id": mid, "timestamp": str(raw.get("timestamp") or ""), "role": str(raw.get("role") or ""),
            "provider": str(raw.get("provider") or ""), "model": str(raw.get("model") or ""), "content": content,
            "is_private": 1 if bool(raw.get("is_private")) else 0, "content_sha256": digest,
        })
    return {"manifest": manifest, "rows": clean, "manifest_path": str(manifest_path)}


def _bf_workshop_export_payload(module) -> dict:
    manifest = _ws_load_manifest(module)
    files = []
    for logical, meta in sorted((manifest.get("files") or {}).items()):
        payload = _ws_read_payload(module, meta)
        files.append({"path": logical, "meta": dict(meta), "payload": payload})
    return {"manifest": manifest, "files": files}


def _bf_write_workshop_backup(module, folder: Path, passphrase: str) -> dict:
    exported = _bf_workshop_export_payload(module)
    files_dir = folder / _BACKUP_WORKSHOP_FILES
    files_dir.mkdir(parents=True, exist_ok=True)
    file_records = []
    for item in exported["files"]:
        meta = dict(item["meta"])
        file_id = str(meta.get("file_id") or "")
        name = f"{re.sub(r'[^A-Za-z0-9_-]+','',file_id)}.nmwf"
        if not name or name == ".nmwf":
            raise ValueError("Workshop recovery encountered an invalid file ID.")
        portable_payload = {
            "kind": "neatmemory_workshop_portable_file",
            "schema_version": _BACKUP_FAMILY_SCHEMA,
            "meta": meta,
            "content": str((item.get("payload") or {}).get("content") or ""),
        }
        record = _bf_write_envelope(files_dir / name, _bf_encrypt_json(portable_payload, passphrase, kind="neatmemory_workshop_file_envelope", aad=_BACKUP_AAD_WORKSHOP_FILE_PREFIX + name.encode("utf-8")))
        file_records.append({"file": f"{_BACKUP_WORKSHOP_FILES}/{name}", "file_id": file_id, "path": meta.get("path"), "content_sha256": meta.get("content_sha256"), "encrypted_sha256": record["sha256"]})
    manifest_payload = {
        "kind": "neatmemory_workshop_backup_manifest",
        "schema_version": _BACKUP_FAMILY_SCHEMA,
        "created_at": _bf_now(),
        "source_bundle_version": BUNDLE_VERSION,
        "workshop_version": _WORKSHOP_VERSION,
        "live_manifest": exported["manifest"],
        "file_records": file_records,
    }
    manifest_record = _bf_write_envelope(folder / _BACKUP_WORKSHOP_MANIFEST, _bf_encrypt_json(manifest_payload, passphrase, kind="neatmemory_workshop_manifest_envelope", aad=_BACKUP_AAD_WORKSHOP_MANIFEST))
    return {"file_count": len(file_records), "active_paths": list(exported["manifest"].get("active_paths") or []), "manifest": _BACKUP_WORKSHOP_MANIFEST, "manifest_sha256": manifest_record["sha256"]}


def _bf_read_workshop_backup(folder: Path, passphrase: str) -> dict:
    manifest_path = folder / _BACKUP_WORKSHOP_MANIFEST
    portable = _bf_decrypt_json(_bf_read_envelope(manifest_path), passphrase, kind="neatmemory_workshop_manifest_envelope", aad=_BACKUP_AAD_WORKSHOP_MANIFEST)
    if not isinstance(portable, dict) or portable.get("kind") != "neatmemory_workshop_backup_manifest":
        raise ValueError("Workshop recovery manifest is invalid.")
    live_manifest = _ws_validate_manifest(portable.get("live_manifest"))
    records = list(portable.get("file_records") or [])
    files = {}
    for record in records:
        rel = str((record or {}).get("file") or "")
        path = (folder / rel).resolve()
        if folder.resolve() not in path.parents:
            raise ValueError("Workshop recovery component path escapes its recovery folder.")
        if str((record or {}).get("encrypted_sha256") or "") != _bf_sha256_file(path):
            raise ValueError(f"Encrypted Workshop file hash mismatch: {rel}")
        name = path.name
        payload = _bf_decrypt_json(_bf_read_envelope(path), passphrase, kind="neatmemory_workshop_file_envelope", aad=_BACKUP_AAD_WORKSHOP_FILE_PREFIX + name.encode("utf-8"))
        if not isinstance(payload, dict) or payload.get("kind") != "neatmemory_workshop_portable_file":
            raise ValueError(f"Workshop portable file payload is invalid: {rel}")
        meta = dict(payload.get("meta") or {})
        logical = _ws_normalize_path(meta.get("path"))
        file_id = str(meta.get("file_id") or "")
        content = str(payload.get("content") or "")
        if logical != str((record or {}).get("path") or "") or file_id != str((record or {}).get("file_id") or ""):
            raise ValueError(f"Workshop recovery file identity mismatch: {rel}")
        digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
        if digest != str(meta.get("content_sha256") or "") or digest != str((record or {}).get("content_sha256") or ""):
            raise ValueError(f"Workshop recovery content hash mismatch: {logical}")
        if logical in files:
            raise ValueError(f"Duplicate Workshop recovery path: {logical}")
        files[logical] = {"meta": meta, "content": content}
    if set(files) != set((live_manifest.get("files") or {}).keys()):
        raise ValueError("Workshop recovery manifest/file set mismatch.")
    for logical, live_meta in (live_manifest.get("files") or {}).items():
        if str(live_meta.get("file_id") or "") != str(files[logical]["meta"].get("file_id") or ""):
            raise ValueError(f"Workshop recovery stable file ID mismatch: {logical}")
    return {"portable_manifest": portable, "live_manifest": live_manifest, "files": files, "manifest_path": str(manifest_path)}


def _bf_component_file_record(root: Path, relative: str, *, kind: str) -> dict:
    path = (root / relative).resolve()
    if root.resolve() not in path.parents and path != root.resolve():
        raise ValueError("Recovery component path escapes the recovery set.")
    return {"kind": kind, "path": relative.replace("\\", "/"), "bytes": path.stat().st_size, "sha256": _bf_sha256_file(path)}


def _bf_create_family(module, target: Path, passphrase: str, *, identity_writer=None, identity_reader=None) -> dict:
    _portable_passphrase_bytes(passphrase)
    target = Path(target).resolve()
    if target.exists() and any(target.iterdir()):
        raise FileExistsError(f"Recovery set destination is not empty: {target}")
    target.mkdir(parents=True, exist_ok=True)
    identity_path = target / _BACKUP_IDENTITY_NAME
    writer = identity_writer or (lambda p, pw: _portable_write_backup(module, p, pw))
    try:
        identity_result = writer(identity_path, passphrase)
        workshop_result = _bf_write_workshop_backup(module, target / _BACKUP_WORKSHOP_DIR, passphrase)
        chat_result = _bf_write_chat_backup(module, target / _BACKUP_CHAT_DIR, passphrase)
        component_files = []
        for path in sorted(p for p in target.rglob("*") if p.is_file() and p.name != _BACKUP_FAMILY_MANIFEST):
            rel = path.relative_to(target).as_posix()
            kind = "identity" if rel == _BACKUP_IDENTITY_NAME else "workshop" if rel.startswith(_BACKUP_WORKSHOP_DIR + "/") else "raw_chat"
            component_files.append(_bf_component_file_record(target, rel, kind=kind))
        manifest = {
            "kind": _BACKUP_FAMILY_KIND,
            "schema_version": _BACKUP_FAMILY_SCHEMA,
            "family_version": _BACKUP_FAMILY_VERSION,
            "created_at": _bf_now(),
            "source_bundle_version": BUNDLE_VERSION,
            "components": {
                "identity": {"path": _BACKUP_IDENTITY_NAME, "encrypted": True, "format": "nmib"},
                "workshop": {"path": _BACKUP_WORKSHOP_DIR, "encrypted": True, **workshop_result},
                "raw_chat": {"path": _BACKUP_CHAT_DIR, "encrypted": True, **chat_result},
            },
            "files": component_files,
            "security": {
                "portable_cipher": "AES-256-GCM",
                "kdf": "scrypt with independent salt per encrypted artifact",
                "cryptographic_domains": "identity/workshop/raw-chat are adjacent but use distinct AAD/domain separation",
                "passphrase_stored": False,
            },
            "restore_policy": "Verify/decrypt/preflight all siblings before any live-state mutation; refuse divergent raw-chat or Workshop histories.",
        }
        _bf_atomic_json(target / _BACKUP_FAMILY_MANIFEST, manifest)
        # Final readback verifies all encrypted siblings with the same passphrase before reporting success.
        verified = _bf_verify_family(module, target, passphrase, identity_reader=identity_reader)
        if not verified.get("ok"):
            raise RuntimeError("Recovery set final readback verification failed.")
        return {"ok": True, "path": str(target), "created_at": manifest["created_at"], "source_bundle_version": BUNDLE_VERSION, "identity": identity_result, "workshop": workshop_result, "raw_chat": chat_result, "manifest": _BACKUP_FAMILY_MANIFEST, "verified": True, "passphrase_stored": False}
    except Exception:
        # Do not leave a folder that looks like a completed recovery set.
        try:
            if (target / _BACKUP_FAMILY_MANIFEST).exists():
                (target / _BACKUP_FAMILY_MANIFEST).unlink(missing_ok=True)
        except Exception:
            pass
        raise


def _bf_load_family_manifest(root: Path) -> dict:
    path = root / _BACKUP_FAMILY_MANIFEST
    if not path.exists():
        raise FileNotFoundError(f"Recovery family manifest not found: {path}")
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError("Recovery family manifest is not valid JSON.") from exc
    if not isinstance(payload, dict) or payload.get("kind") != _BACKUP_FAMILY_KIND or str(payload.get("schema_version")) != _BACKUP_FAMILY_SCHEMA:
        raise ValueError("Recovery family manifest kind/schema is invalid.")
    return payload


def _bf_verify_outer_hashes(root: Path, manifest: dict) -> None:
    for record in manifest.get("files") or []:
        rel = str((record or {}).get("path") or "")
        path = (root / rel).resolve()
        if root.resolve() not in path.parents:
            raise ValueError("Recovery family file path escapes the set.")
        if not path.exists() or not path.is_file():
            raise FileNotFoundError(f"Recovery family component missing: {rel}")
        digest = _bf_sha256_file(path)
        if digest != str((record or {}).get("sha256") or ""):
            raise ValueError(f"Recovery family encrypted-file hash mismatch: {rel}")


def _bf_verify_family(module, root: Path, passphrase: str, *, identity_reader=None) -> dict:
    root = Path(root).resolve()
    manifest = _bf_load_family_manifest(root)
    _bf_verify_outer_hashes(root, manifest)
    reader = identity_reader or (lambda p, pw: _portable_read_backup(p, pw))
    identity_payload = reader(root / _BACKUP_IDENTITY_NAME, passphrase)
    workshop = _bf_read_workshop_backup(root / _BACKUP_WORKSHOP_DIR, passphrase)
    chat = _bf_read_chat_backup(root / _BACKUP_CHAT_DIR, passphrase)
    return {
        "ok": True, "path": str(root), "created_at": manifest.get("created_at"), "source_bundle_version": manifest.get("source_bundle_version"),
        "identity": {"verified": True, "created_at": (identity_payload or {}).get("created_at") if isinstance(identity_payload, dict) else None},
        "workshop": {"verified": True, "file_count": len(workshop["files"]), "active_paths": list(workshop["live_manifest"].get("active_paths") or [])},
        "raw_chat": {"verified": True, "row_count": len(chat["rows"]), "public_count": sum(1 for x in chat["rows"] if not x["is_private"]), "private_count": sum(1 for x in chat["rows"] if x["is_private"])},
        "integrity": "outer encrypted-file SHA-256 + AES-GCM authentication + per-source content hashes verified",
        "mutation_performed": False,
    }


def _bf_live_chat_rows(module) -> list[dict]:
    return _bf_collect_chat_rows(module)


def _bf_chat_preflight(module, backup_rows: list[dict]) -> dict:
    live = _bf_live_chat_rows(module)
    live_by_id = {int(x["message_id"]): x for x in live}
    backup_by_id = {int(x["message_id"]): x for x in backup_rows}
    conflicts = []
    for mid, current in live_by_id.items():
        candidate = backup_by_id.get(mid)
        if candidate is None:
            conflicts.append({"message_id": mid, "reason": "live history contains a CHAT ID absent from the recovery set"})
            continue
        fields = ("timestamp","role","provider","model","content","is_private","content_sha256")
        if any(current.get(k) != candidate.get(k) for k in fields):
            conflicts.append({"message_id": mid, "reason": "same CHAT ID has different canonical content/metadata"})
    if conflicts:
        return {"ok": False, "conflicts": conflicts[:20], "live_rows": len(live), "backup_rows": len(backup_rows), "policy": "fail-closed; raw-chat histories are never renumbered or silently merged"}
    missing = [mid for mid in backup_by_id if mid not in live_by_id]
    return {"ok": True, "live_rows": len(live), "backup_rows": len(backup_rows), "missing_rows_to_restore": len(missing), "already_matching_rows": len(live), "mode": "noop" if not missing else "complete_exact_subset" if live else "restore_empty"}


def _bf_workshop_signature(manifest: dict) -> dict:
    return {str(path): {"file_id": str(meta.get("file_id") or ""), "content_sha256": str(meta.get("content_sha256") or ""), "revision": int(meta.get("revision") or 0)} for path, meta in sorted((manifest.get("files") or {}).items())}


def _bf_workshop_preflight(module, backup: dict) -> dict:
    live = _ws_load_manifest(module)
    live_sig = _bf_workshop_signature(live)
    backup_sig = _bf_workshop_signature(backup["live_manifest"])
    if not live_sig:
        return {"ok": True, "mode": "restore_empty", "live_files": 0, "backup_files": len(backup_sig)}
    if live_sig == backup_sig and list(live.get("active_paths") or []) == list(backup["live_manifest"].get("active_paths") or []):
        return {"ok": True, "mode": "noop_exact_match", "live_files": len(live_sig), "backup_files": len(backup_sig)}
    return {"ok": False, "mode": "conflict", "live_files": len(live_sig), "backup_files": len(backup_sig), "error": "Live Workshop is non-empty and differs from this recovery snapshot; automatic merge/overwrite is refused."}


def _bf_preflight_restore(module, root: Path, passphrase: str, *, identity_reader=None) -> dict:
    root = Path(root).resolve()
    verified = _bf_verify_family(module, root, passphrase, identity_reader=identity_reader)
    workshop = _bf_read_workshop_backup(root / _BACKUP_WORKSHOP_DIR, passphrase)
    chat = _bf_read_chat_backup(root / _BACKUP_CHAT_DIR, passphrase)
    ws_check = _bf_workshop_preflight(module, workshop)
    chat_check = _bf_chat_preflight(module, chat["rows"])
    ok = bool(ws_check.get("ok") and chat_check.get("ok"))
    return {"ok": ok, "verified": verified, "workshop": ws_check, "raw_chat": chat_check, "mutation_performed": False, "message": "All recovery siblings verified and live conflicts checked before mutation." if ok else "Restore refused during preflight; live state is unchanged."}


def _bf_stage_workshop(module, backup: dict) -> Path:
    root = _ws_root(module)
    root.parent.mkdir(parents=True, exist_ok=True)
    stage = root.parent / f".{root.name}.restore-stage-{uuid.uuid4().hex[:10]}"
    files_root = stage / _WORKSHOP_FILES_DIRNAME
    files_root.mkdir(parents=True, exist_ok=True)
    live_manifest = dict(backup["live_manifest"])
    for logical, item in backup["files"].items():
        meta = dict(item["meta"])
        content = str(item["content"])
        file_id = str(meta.get("file_id") or "")
        payload = _ws_payload_for_content(meta, content)
        encrypted = _ws_encrypt_json(module, payload, entropy=_ws_file_entropy(file_id))
        _bf_atomic_bytes(files_root / f"{re.sub(r'[^A-Za-z0-9_-]+','',file_id)}.enc", encrypted)
    _bf_atomic_bytes(stage / _WORKSHOP_MANIFEST_NAME, _ws_encrypt_json(module, live_manifest, entropy=_WORKSHOP_MANIFEST_ENTROPY))
    # Readback using direct staged bytes before swap.
    check_manifest = _ws_decrypt_json(module, (stage / _WORKSHOP_MANIFEST_NAME).read_bytes(), entropy=_WORKSHOP_MANIFEST_ENTROPY)
    _ws_validate_manifest(check_manifest)
    return stage


def _bf_commit_workshop_restore(module, backup: dict, preflight: dict) -> dict:
    mode = str(preflight.get("mode") or "")
    if mode == "noop_exact_match":
        return {"ok": True, "mode": mode, "restored": False, "archive": None}
    if mode != "restore_empty":
        raise RuntimeError("Workshop restore attempted without a safe preflight mode.")
    stage = _bf_stage_workshop(module, backup)
    root = _ws_root(module)
    archive = None
    try:
        if root.exists():
            archive = root.parent / f"{root.name}.pre-restore-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:6]}"
            os.replace(root, archive)
        os.replace(stage, root)
    except Exception:
        # Best-effort rollback of the original empty Workshop directory.
        try:
            if not root.exists() and archive is not None and archive.exists():
                os.replace(archive, root)
        except Exception:
            pass
        raise
    finally:
        if stage.exists():
            shutil.rmtree(stage, ignore_errors=True)
    # Validate using normal live reader after swap.
    restored_manifest = _ws_load_manifest(module)
    if _bf_workshop_signature(restored_manifest) != _bf_workshop_signature(backup["live_manifest"]):
        raise RuntimeError("Workshop restore readback signature mismatch.")
    return {"ok": True, "mode": mode, "restored": True, "archive": str(archive) if archive else None, "file_count": len(backup["files"])}


def _bf_raw_mirror_path(module) -> Path:
    name = str(getattr(module, "RAW_CONVERSATION_FILE", "raw_conversation.txt") or "raw_conversation.txt")
    try:
        return Path(module.safe_memory_path(name))
    except Exception:
        return (Path.cwd() / name).resolve()


def _bf_rebuild_raw_mirror(module, rows: list[dict]) -> str:
    path = _bf_raw_mirror_path(module)
    lines = []
    for row in rows:
        if bool(row.get("is_private")):
            continue
        lines.append(json.dumps({
            "message_id": int(row["message_id"]), "timestamp": row["timestamp"], "role": row["role"],
            "provider": row["provider"], "model": row["model"], "content": row["content"],
        }, ensure_ascii=False, separators=(",", ":")))
    data = (("\n".join(lines) + "\n") if lines else "").encode("utf-8")
    _bf_atomic_bytes(path, data)
    return str(path)


def _bf_commit_chat_restore(module, backup_rows: list[dict], preflight: dict) -> dict:
    if not preflight.get("ok"):
        raise RuntimeError("Raw-chat restore attempted without safe preflight.")
    live_ids = {int(x["message_id"]) for x in _bf_live_chat_rows(module)}
    missing = [row for row in backup_rows if int(row["message_id"]) not in live_ids]
    inserted = 0
    with module.db_connect() as db:
        columns = {str(row[1]) for row in db.execute("PRAGMA table_info(chat_messages)").fetchall()}
        required = {"message_id","timestamp","role","provider","model","content","is_private","content_sha256"}
        if not required.issubset(columns):
            raise RuntimeError("Canonical chat_messages schema is missing required recovery columns.")
        for row in missing:
            db.execute(
                "INSERT INTO chat_messages(message_id,timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,?,?,?)",
                (int(row["message_id"]), row["timestamp"], row["role"], row["provider"], row["model"], row["content"], int(row["is_private"]), row["content_sha256"]),
            )
            inserted += 1
        # Derived raw-chat FTS is deliberately disposable; force clean rebuild on next search.
        try: db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_TABLE}")
        except Exception: pass
        try: db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_META_TABLE}")
        except Exception: pass
    final_rows = _bf_live_chat_rows(module)
    if len(final_rows) != len(backup_rows) or any(a != b for a, b in zip(final_rows, backup_rows)):
        raise RuntimeError("Raw-chat restore readback did not exactly match the recovery snapshot.")
    mirror = _bf_rebuild_raw_mirror(module, final_rows)
    # Other evidence meshes are derived/disposable and may rebuild independently; do not rewrite them here.
    return {"ok": True, "inserted_rows": inserted, "total_rows": len(final_rows), "public_rows": sum(1 for x in final_rows if not x["is_private"]), "private_rows": sum(1 for x in final_rows if x["is_private"]), "raw_public_mirror": mirror, "stable_chat_ids_preserved": True, "derived_raw_chat_fts_invalidated": True}


def _bf_restore_family(module, root: Path, passphrase: str, *, identity_reader=None, identity_restorer=None) -> dict:
    root = Path(root).resolve()
    preflight = _bf_preflight_restore(module, root, passphrase, identity_reader=identity_reader)
    if not preflight.get("ok"):
        return {"ok": False, "preflight": preflight, "mutation_performed": False, "error": "Recovery family restore refused; resolve the reported conflict first."}
    reader = identity_reader or (lambda p, pw: _portable_read_backup(p, pw))
    identity_payload = reader(root / _BACKUP_IDENTITY_NAME, passphrase)
    workshop_backup = _bf_read_workshop_backup(root / _BACKUP_WORKSHOP_DIR, passphrase)
    chat_backup = _bf_read_chat_backup(root / _BACKUP_CHAT_DIR, passphrase)
    # Preflight already proved semantic compatibility. Each sibling uses its own atomic/transactional mechanics.
    workshop_result = _bf_commit_workshop_restore(module, workshop_backup, preflight["workshop"])
    chat_result = _bf_commit_chat_restore(module, chat_backup["rows"], preflight["raw_chat"])
    restorer = identity_restorer or (lambda payload, source: _portable_restore_payload(module, payload, source_path=source))
    identity_result = restorer(identity_payload, root / _BACKUP_IDENTITY_NAME)
    return {
        "ok": True, "path": str(root), "preflight": preflight,
        "identity": identity_result, "workshop": workshop_result, "raw_chat": chat_result,
        "mutation_performed": True,
        "note": "Identity/self, Workshop, and raw chat are restored as adjacent siblings. They remain independently stored and do not become one fused identity file.",
    }


def _bf_list_sets() -> list[dict]:
    root = _bf_default_root()
    if not root.exists():
        return []
    out = []
    for folder in sorted((p for p in root.iterdir() if p.is_dir()), key=lambda p: p.stat().st_mtime, reverse=True):
        manifest = folder / _BACKUP_FAMILY_MANIFEST
        if not manifest.exists():
            continue
        try:
            raw = json.loads(manifest.read_text(encoding="utf-8"))
            out.append({"path": str(folder), "created_at": raw.get("created_at"), "source_bundle_version": raw.get("source_bundle_version"), "components": sorted((raw.get("components") or {}).keys())})
        except Exception:
            out.append({"path": str(folder), "error": "manifest unreadable"})
    return out[:30]


def _bf_status(module) -> dict:
    ws = _ws_status(module) if "_ws_status" in globals() else {"available": False}
    try:
        chat_rows = len(_bf_collect_chat_rows(module))
    except Exception as exc:
        chat_rows = None
        chat_error = f"{type(exc).__name__}: {exc}"
    else:
        chat_error = None
    return {
        "ok": True, "version": _BACKUP_FAMILY_VERSION,
        "canonical_command_family": "/backup",
        "default_root": str(_bf_default_root()),
        "recent_recovery_sets": _bf_list_sets(),
        "components": {
            "identity_self_continuity": {"portable_format": ".nmib", "live_protection": "existing Windows DPAPI", "legacy_identity_commands_preserved": True},
            "workshop": {"live_encrypted": True, "stored_files": ws.get("file_count"), "active_paths": ws.get("active_paths")},
            "raw_chat": {"portable_encrypted": True, "canonical_rows": chat_rows, "error": chat_error, "live_sqlite_encryption": False, "reason": "live chat remains schema-compatible in this checkpoint because many continuity/retrieval/citation systems read chat_messages directly"},
        },
        "commands": ["/backup create [folder]", "/backup verify <folder>", "/backup restore <folder>", "/backup status", "/backup list", "/backup help"],
        "passphrase_storage": "The recovery passphrase is never stored by NeatMemory.",
        "restore_policy": "Full-family verification and conflict preflight before mutation; divergent CHAT histories or non-matching non-empty Workshops fail closed.",
    }


def _bf_help_text() -> str:
    return (
        "\n/backup — consolidated Assistant recovery family\n"
        "  /backup status                 show encryption/recovery readiness and recent sets\n"
        "  /backup list                   list recovery-family folders\n"
        "  /backup create [folder]        create identity + Workshop + raw-chat encrypted siblings with one passphrase\n"
        "  /backup verify <folder>        authenticate/decrypt/hash-check the complete family; no mutation\n"
        "  /backup restore <folder>       verify + preflight all siblings, then restore compatible state\n"
        "  /backup help                   show this page\n\n"
        "Security/ownership:\n"
        "  • Identity/self, Workshop, and raw chat are adjacent recovery siblings, not one fused identity artifact.\n"
        "  • Workshop is encrypted live and portable. Raw chat is encrypted in the portable recovery family; its live SQLite column remains unchanged in this checkpoint so existing recall, continuity, citation, and evidence readers are not broken.\n"
        "  • CHAT message IDs are immutable recovery identities: restore never renumbers or silently merges divergent histories.\n"
        "  • Existing /identity export|import|backup commands remain supported as identity-only compatibility commands.\n"
    )


def _bf_handle_command(module, text: str) -> bool:
    command = str(text or "").strip()
    low = command.casefold()
    if low in {"/backup", "/backup status"}:
        print(json.dumps(_bf_status(module), ensure_ascii=False, indent=2)); return True
    if low in {"/backup help", "/help backup", "/help /backup"}:
        print(_bf_help_text()); return True
    if low == "/backup list":
        print(json.dumps({"ok": True, "recovery_sets": _bf_list_sets()}, ensure_ascii=False, indent=2)); return True
    if low == "/backup create" or low.startswith("/backup create "):
        raw = command[len("/backup create"):].strip()
        try:
            target = _bf_resolve_set_path(raw, create=True)
            result = _bf_create_family(module, target, _portable_prompt_new_passphrase())
            print(json.dumps(result, ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Backup family create error: {type(exc).__name__}: {exc}")
        return True
    if low == "/backup verify" or low.startswith("/backup verify "):
        raw = command[len("/backup verify"):].strip()
        if not raw:
            print("Use /backup verify <recovery-folder>"); return True
        try:
            root = _bf_resolve_set_path(raw, create=False)
            print(json.dumps(_bf_verify_family(module, root, _portable_prompt_passphrase()), ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Backup family verification error: {type(exc).__name__}: {exc}")
        return True
    if low == "/backup restore" or low.startswith("/backup restore "):
        raw = command[len("/backup restore"):].strip()
        if not raw:
            print("Use /backup restore <recovery-folder>"); return True
        try:
            root = _bf_resolve_set_path(raw, create=False)
            result = _bf_restore_family(module, root, _portable_prompt_passphrase())
            print(json.dumps(result, ensure_ascii=False, indent=2))
        except Exception as exc:
            print(f"Backup family restore error: {type(exc).__name__}: {exc}")
        return True
    return False


def _install_backup_family(module) -> None:
    if getattr(module, "_BACKUP_FAMILY_INSTALLED", False):
        return
    module.get_backup_status = lambda: _bf_status(module)
    module.list_backup_sets = _bf_list_sets
    module.create_backup_family = lambda path, passphrase: _bf_create_family(module, _bf_resolve_set_path(path, create=True), passphrase)
    module.verify_backup_family = lambda path, passphrase: _bf_verify_family(module, _bf_resolve_set_path(path, create=False), passphrase)
    module.restore_backup_family = lambda path, passphrase: _bf_restore_family(module, _bf_resolve_set_path(path, create=False), passphrase)
    module.backup_family_self_test = lambda: backup_family_self_test(module)
    # The canonical self-test registry already exposes this subsystem as
    # ``backup``. Do not mutate the registry after _SELF_TEST_EXPECTED is frozen;
    # doing so breaks registry-integrity checks. ``backup-family`` remains an alias.

    old_doctor = module.doctor_report
    def doctor_with_backup_family():
        report = old_doctor()
        report["backup_family"] = _bf_status(module)
        return report
    module.doctor_report = doctor_with_backup_family

    old_main = module.main
    def main_with_backup_commands():
        original_input = builtins.input
        def backup_input(prompt=""):
            while True:
                value = original_input(prompt)
                if _bf_handle_command(module, value):
                    continue
                return value
        builtins.input = backup_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_backup_commands
    module._BACKUP_FAMILY_INSTALLED = True


def backup_family_self_test(module) -> dict:
    checks = {}
    original_db_connect = module.db_connect
    original_safe = module.safe_memory_path
    original_ws_path = os.getenv("NEATMEMORY_WORKSHOP_PATH")
    crypto = _identity_crypto()
    original_encrypt = crypto.encrypt_text
    original_decrypt = crypto.decrypt_text
    test_db = sqlite3.connect(":memory:")
    test_db.row_factory = sqlite3.Row
    identity_restore_calls = []
    try:
        test_db.execute("CREATE TABLE chat_messages(message_id INTEGER PRIMARY KEY AUTOINCREMENT,timestamp TEXT NOT NULL,role TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,content TEXT NOT NULL,is_private INTEGER NOT NULL DEFAULT 0,content_sha256 TEXT NOT NULL)")
        def add_chat(mid, content, private=0):
            test_db.execute("INSERT INTO chat_messages(message_id,timestamp,role,provider,model,content,is_private,content_sha256) VALUES(?,?,?,?,?,?,?,?)", (mid, f"2026-08-12T12:00:{mid:02d}+00:00", "user" if mid == 1 else "assistant", "test", "test", content, private, hashlib.sha256(content.encode()).hexdigest()))
            test_db.commit()
        add_chat(1, "public-one", 0); add_chat(3, "private-three", 1)
        module.db_connect = lambda: test_db
        with tempfile.TemporaryDirectory(prefix="neat-backup-family-") as folder:
            root = Path(folder)
            live = root / "live"
            live.mkdir()
            module.safe_memory_path = lambda name: live / Path(str(name)).name
            os.environ["NEATMEMORY_WORKSHOP_PATH"] = str(root / "Workshop")
            def fake_encrypt(text: str, *, entropy=None):
                raw = text.encode("utf-8"); key = hashlib.sha256(bytes(entropy or b"test")).digest(); cipher = bytes(b ^ key[i % len(key)] for i,b in enumerate(raw)); return b"TESTENC1" + base64.b64encode(cipher)
            def fake_decrypt(payload: bytes, *, entropy=None):
                if not payload.startswith(b"TESTENC1"): raise RuntimeError("bad test cipher")
                cipher = base64.b64decode(payload[8:]); key = hashlib.sha256(bytes(entropy or b"test")).digest(); raw = bytes(b ^ key[i % len(key)] for i,b in enumerate(cipher)); return raw.decode("utf-8")
            crypto.encrypt_text = fake_encrypt; crypto.decrypt_text = fake_decrypt
            _ws_write_file(module, "Study/Macbeth.md", "witches and kings", purpose="Study Macbeth", resume="Whole-play working notes", contains="notes", origin="assistant", provenance=[], replace=True)
            before_ws = _ws_load_manifest(module)
            before_file_id = before_ws["files"]["Study/Macbeth.md"]["file_id"]
            before_revision = before_ws["files"]["Study/Macbeth.md"]["revision"]
            backup_root = root / "recovery"
            def fake_identity_writer(path, passphrase):
                payload = {"kind":"test_identity","created_at":_bf_now(),"source_bundle_version":BUNDLE_VERSION,"secret":"identity"}
                _bf_write_envelope(path, _bf_encrypt_json(payload, passphrase, kind="test_identity_envelope", aad=b"test identity"))
                return {"ok":True,"path":str(path)}
            def fake_identity_reader(path, passphrase):
                return _bf_decrypt_json(_bf_read_envelope(path), passphrase, kind="test_identity_envelope", aad=b"test identity")
            created = _bf_create_family(module, backup_root, "correct horse battery staple", identity_writer=fake_identity_writer, identity_reader=fake_identity_reader)
            verified = _bf_verify_family(module, backup_root, "correct horse battery staple", identity_reader=fake_identity_reader)
            checks["create_verify_family"] = bool(created.get("ok") and verified.get("ok") and verified["raw_chat"]["row_count"] == 2 and verified["workshop"]["file_count"] == 1)
            # Simulate empty destination and restore exact non-contiguous IDs.
            shutil.rmtree(Path(os.environ["NEATMEMORY_WORKSHOP_PATH"]), ignore_errors=True)
            _ws_load_manifest(module, create=True)
            test_db.execute("DELETE FROM chat_messages"); test_db.commit()
            def fake_identity_restore(payload, source):
                identity_restore_calls.append((payload, str(source))); return {"ok":True,"test":True}
            restored = _bf_restore_family(module, backup_root, "correct horse battery staple", identity_reader=fake_identity_reader, identity_restorer=fake_identity_restore)
            rows = _bf_collect_chat_rows(module)
            restored_ws = _ws_load_manifest(module)
            checks["stable_noncontiguous_chat_ids"] = [x["message_id"] for x in rows] == [1,3]
            mirror_text = _bf_raw_mirror_path(module).read_text(encoding="utf-8")
            checks["private_not_in_public_mirror"] = "public-one" in mirror_text and "private-three" not in mirror_text
            checks["workshop_ids_revisions_preserved"] = restored_ws["files"]["Study/Macbeth.md"]["file_id"] == before_file_id and restored_ws["files"]["Study/Macbeth.md"]["revision"] == before_revision
            checks["family_restore_calls_identity_after_preflight"] = bool(restored.get("ok") and len(identity_restore_calls) == 1)
            # Divergent chat blocks the family before identity mutation.
            identity_restore_calls.clear()
            test_db.execute("UPDATE chat_messages SET content='diverged',content_sha256=? WHERE message_id=1", (hashlib.sha256(b"diverged").hexdigest(),)); test_db.commit()
            refused = _bf_restore_family(module, backup_root, "correct horse battery staple", identity_reader=fake_identity_reader, identity_restorer=fake_identity_restore)
            checks["divergent_chat_fails_before_identity"] = refused.get("ok") is False and refused.get("mutation_performed") is False and len(identity_restore_calls) == 0
            # Restore original DB so outer hash corruption test is independent.
            test_db.execute("UPDATE chat_messages SET content='public-one',content_sha256=? WHERE message_id=1", (hashlib.sha256(b"public-one").hexdigest(),)); test_db.commit()
            # Tamper one encrypted file; outer SHA should catch it before decryption.
            chat_chunk = next((backup_root / _BACKUP_CHAT_DIR / _BACKUP_CHAT_CHUNKS).glob("*.nmcc"))
            original_chunk = chat_chunk.read_bytes(); chat_chunk.write_bytes(original_chunk + b"x")
            try:
                _bf_verify_family(module, backup_root, "correct horse battery staple", identity_reader=fake_identity_reader)
                tamper_failed = False
            except Exception:
                tamper_failed = True
            checks["encrypted_file_tamper_detected"] = tamper_failed
            chat_chunk.write_bytes(original_chunk)
            checks["separate_encrypted_siblings"] = (backup_root / _BACKUP_IDENTITY_NAME).is_file() and (backup_root / _BACKUP_WORKSHOP_DIR / _BACKUP_WORKSHOP_MANIFEST).is_file() and (backup_root / _BACKUP_CHAT_DIR / _BACKUP_CHAT_MANIFEST).is_file()
            checks["model_calls_zero"] = True
    finally:
        module.db_connect = original_db_connect
        module.safe_memory_path = original_safe
        crypto.encrypt_text = original_encrypt; crypto.decrypt_text = original_decrypt
        if original_ws_path is None: os.environ.pop("NEATMEMORY_WORKSHOP_PATH", None)
        else: os.environ["NEATMEMORY_WORKSHOP_PATH"] = original_ws_path
        try: test_db.close()
        except Exception: pass
    return {"ok": all(bool(v) for v in checks.values()), "checks": checks, "model_calls": 0}
# <<< NEAT-SUBSYSTEM:backup-family

# >>> NEAT-SUBSYSTEM:observability rev=1
# Function lifecycle signals and context observability (7.4.20)
# ---------------------------------------------------------------------------

_FUNCTION_OBSERVABILITY_VERSION = "1.0-function-lifecycle-signals-context-observability"
_DIAGNOSTIC_SCHEMA_VERSION = "1"
_DIAGNOSTIC_DB_FILE = "diagnostics.sqlite"
_DIAGNOSTIC_CONTEXT_QUEUE_LIMIT = 20
_DIAGNOSTIC_LIST_LIMIT = 500
_DIAGNOSTIC_MAX_MESSAGE = 700
_DIAGNOSTIC_GUARD = threading.local()
_DIAGNOSTIC_CONTEXT_QUEUE: list[dict] = []
_DIAGNOSTIC_LAST_SUCCESSFUL_FUNCTION = ""
_DIAGNOSTIC_WRAPPED_FUNCTIONS: dict[str, object] = {}


def _diagnostic_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _diagnostic_json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _diagnostic_hash(*parts: object) -> str:
    digest = hashlib.sha256()
    for part in parts:
        payload = part if isinstance(part, bytes) else str(part).encode("utf-8", errors="replace")
        digest.update(len(payload).to_bytes(8, "big"))
        digest.update(payload)
    return digest.hexdigest()


def _diagnostic_scrub_text(value: object, limit: int = _DIAGNOSTIC_MAX_MESSAGE) -> str:
    text = str(value or "").replace("\x00", " ")
    text = re.sub(r"(?i)\b(authorization|api[_ -]?key|password|passphrase|secret|access[_ -]?token|bearer)\b\s*[:=]\s*[^\s,;]+", r"\1=[REDACTED]", text)
    text = re.sub(r"\bsk-[A-Za-z0-9_-]{12,}\b", "[REDACTED_API_KEY]", text)
    text = re.sub(r"(?i)\bBearer\s+[A-Za-z0-9._~+/-]{12,}\b", "Bearer [REDACTED]", text)
    text = re.sub(r"[A-Za-z0-9+/]{120,}={0,2}", "[REDACTED_LONG_BLOB]", text)
    return " ".join(text.split())[:max(1, int(limit))]


def _diagnostic_scrub_traceback(value: object, limit: int = 20000) -> str:
    lines = []
    remaining = max(1, int(limit))
    for raw_line in str(value or "").splitlines():
        clean = _diagnostic_scrub_text(raw_line, min(2000, remaining))
        lines.append(clean)
        remaining -= len(clean) + 1
        if remaining <= 0:
            break
    return "\n".join(lines)


def _diagnostic_private_mode(module) -> bool:
    return bool(globals().get("_BLACKBOX_PRIVATE_MODE", False) or getattr(module, "_SESSION_PRIVATE_MODE", False))


def _diagnostic_db_path(module) -> Path:
    return module.safe_memory_path(_DIAGNOSTIC_DB_FILE)


def _diagnostic_connect(module) -> sqlite3.Connection:
    path = _diagnostic_db_path(module)
    path.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(path, timeout=30.0)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA foreign_keys=ON")
    try:
        db.execute("PRAGMA journal_mode=WAL")
    except sqlite3.DatabaseError:
        pass
    return db


def _diagnostic_ensure_schema(module) -> None:
    with _diagnostic_connect(module) as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS diagnostic_meta (
            singleton INTEGER PRIMARY KEY CHECK(singleton=1),
            schema_version TEXT NOT NULL,
            feature_version TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS function_diagnostic_events (
            diagnostic_id TEXT PRIMARY KEY,
            sequence INTEGER NOT NULL UNIQUE,
            call_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            function_name TEXT NOT NULL,
            group_id TEXT NOT NULL,
            phase TEXT NOT NULL,
            display_mode TEXT NOT NULL,
            success INTEGER,
            duration_ms REAL,
            tokens_before INTEGER,
            tokens_after INTEGER,
            error_type TEXT,
            error_message TEXT,
            error_signature TEXT,
            values_json TEXT NOT NULL,
            unavailable_json TEXT NOT NULL,
            value_sources_json TEXT NOT NULL,
            suggestions_json TEXT NOT NULL,
            echo_links_json TEXT NOT NULL,
            full_detail_object_id TEXT,
            previous_event_hash TEXT,
            event_hash TEXT NOT NULL UNIQUE
        );
        CREATE INDEX IF NOT EXISTS idx_function_diagnostics_created
            ON function_diagnostic_events(created_at DESC, sequence DESC);
        CREATE INDEX IF NOT EXISTS idx_function_diagnostics_error
            ON function_diagnostic_events(phase, error_signature, sequence DESC);
        CREATE INDEX IF NOT EXISTS idx_function_diagnostics_call
            ON function_diagnostic_events(call_id, sequence);
        CREATE TRIGGER IF NOT EXISTS function_diagnostic_events_deny_update
        BEFORE UPDATE ON function_diagnostic_events
        BEGIN SELECT RAISE(ABORT, 'diagnostic events are append-only'); END;
        CREATE TRIGGER IF NOT EXISTS function_diagnostic_events_deny_delete
        BEFORE DELETE ON function_diagnostic_events
        BEGIN SELECT RAISE(ABORT, 'diagnostic events are append-only'); END;
        """)
        now = _diagnostic_now()
        db.execute(
            "INSERT INTO diagnostic_meta(singleton,schema_version,feature_version,created_at,updated_at) "
            "VALUES(1,?,?,?,?) ON CONFLICT(singleton) DO UPDATE SET "
            "schema_version=excluded.schema_version, feature_version=excluded.feature_version, updated_at=excluded.updated_at",
            (_DIAGNOSTIC_SCHEMA_VERSION, _FUNCTION_OBSERVABILITY_VERSION, now, now),
        )


def _diagnostic_query_for_call(function_name: str, args: tuple, kwargs: dict) -> str:
    for key in ("query", "text", "request"):
        value = kwargs.get(key)
        if isinstance(value, str) and value.strip():
            return value
    try:
        if function_name in {"build_runtime_context", "retrieve_relevant_memories", "personal_context_for_query", "book_context_for_query", "research_context_for_query", "search_controlled_mesh"}:
            return str(args[0] if args else "")
        if function_name in {"run_local_turn", "run_online_chat_turn"}:
            return str(args[2] if len(args) > 2 else "")
        if function_name == "execute_tool":
            return "tool " + str(args[0] if args else kwargs.get("name") or "")
        if function_name in {"run_research_loop", "run_autonomous_research_loop"}:
            return str(args[0] if args else kwargs.get("topic") or kwargs.get("query") or "research")
    except Exception:
        pass
    return function_name.replace("_", " ")


def _diagnostic_value_size(value: object, *, depth: int = 0) -> int:
    if depth > 4 or value is None:
        return 0
    if isinstance(value, str):
        return len(value)
    if isinstance(value, bytes):
        return len(value)
    if isinstance(value, (int, float, bool)):
        return len(str(value))
    if isinstance(value, dict):
        return sum(_diagnostic_value_size(key, depth=depth + 1) + _diagnostic_value_size(item, depth=depth + 1) for key, item in list(value.items())[:200])
    if isinstance(value, (list, tuple, set)):
        return sum(_diagnostic_value_size(item, depth=depth + 1) for item in list(value)[:200])
    return min(2000, len(str(value)))


def _diagnostic_token_count(value: object) -> int:
    return max(0, int(math.ceil(_diagnostic_value_size(value) / 4.0)))


def _diagnostic_active_observers(module, function_name: str) -> list[dict]:
    try:
        state, _ = _context_routing_read_state(module)
        _profile_id, container = _context_routing_resolve_profile(state)
        profile = _context_routing_profile_current(container)
    except Exception:
        profile = _context_routing_profile_version(
            _CONTEXT_ROUTING_DEFAULT_PROFILE_ID, "Adaptive Default", "Safe diagnostic fallback.",
            _context_routing_default_groups(), version=1, actor="Python"
        )
    observers = []
    for group_id, definition in _CONTEXT_GROUP_DEFINITIONS.items():
        config = dict(profile.get("groups", {}).get(group_id) or _context_routing_default_group(group_id))
        if not definition["locked"] and int(config.get("order", 1)) == 0:
            continue
        target = config.get("decorator_function")
        phase = str(config.get("decorator_phase") or "off").casefold()
        if not target or phase == "off":
            continue
        matches = target == function_name or (target == "run_chat_turn" and function_name in {"run_local_turn", "run_online_chat_turn"})
        if not matches:
            continue
        observers.append({
            "group_id": group_id,
            "locked": bool(definition["locked"]),
            "function_name": target,
            "phase": phase,
            "display": str(config.get("decorator_display") or "trace").casefold(),
            "values": list(config.get("decorator_values") or []),
        })
    return observers


def _diagnostic_report_values(module, group_id: str, query: str) -> tuple[dict, float | None]:
    report = getattr(module, "_LAST_CONTEXT_ROUTING_REPORT", None)
    if not isinstance(report, dict):
        return {}, None
    query_hash = hashlib.sha256(str(query or "").encode("utf-8")).hexdigest()
    if report.get("query_sha256") != query_hash:
        return {}, None
    routing_values = dict((report.get("routing_values_by_group") or {}).get(group_id) or {})
    formula_score = None
    for row in report.get("groups") or []:
        if row.get("group_id") == group_id:
            try:
                formula_score = float(row.get("formula_score"))
            except Exception:
                formula_score = None
            break
    return routing_values, formula_score


def _diagnostic_collect_values(module, observer: dict, *, function_name: str, phase: str, call_id: str,
                               query: str, duration_ms: float | None, tokens_before: int,
                               tokens_after: int | None, error: BaseException | None,
                               call_depth: int) -> tuple[dict, list[str], dict]:
    requested = list(observer.get("values") or [])
    values: dict[str, object] = {}
    unavailable: list[str] = []
    sources: dict[str, str] = {}
    routing_values, formula_score = _diagnostic_report_values(module, observer["group_id"], query)
    metrics: dict[str, dict] = {}
    derived: dict[str, object] = {}
    perception_needed = any(not ref.startswith("diagnostic.") and ref not in _CONTEXT_ROUTING_FORMULA_REFS for ref in requested)
    if perception_needed:
        try:
            metrics, _ = _perception_collect_metrics(module, query=query)
            profile = _perception_latest_profile(module, None, include_retired=False)
            if profile:
                derived, _ = _perception_compute_derived(profile, metrics)
        except Exception:
            metrics, derived = {}, {}
    automatic = {
        "diagnostic.call_id": call_id,
        "diagnostic.function_name": function_name,
        "diagnostic.phase": phase,
        "diagnostic.duration_ms": None if duration_ms is None else round(float(duration_ms), 3),
        "diagnostic.tokens_before": int(tokens_before),
        "diagnostic.tokens_after": None if tokens_after is None else int(tokens_after),
        "diagnostic.error_type": type(error).__name__ if error is not None else None,
        "diagnostic.error_message": _diagnostic_scrub_text(error) if error is not None else None,
        "diagnostic.formula_score": formula_score,
        "diagnostic.last_successful_function": _DIAGNOSTIC_LAST_SUCCESSFUL_FUNCTION or None,
        "diagnostic.call_depth": int(call_depth),
    }
    for ref in requested:
        if ref in automatic:
            if automatic[ref] is None:
                unavailable.append(ref)
            else:
                values[ref] = automatic[ref]
                sources[ref] = "python_lifecycle"
        elif ref in routing_values:
            values[ref] = routing_values[ref]
            sources[ref] = "current_context_routing_report"
        elif ref.startswith("derived."):
            key = ref.split(".", 1)[1]
            if key in derived:
                values[ref] = derived[key]
                sources[ref] = "active_perception_profile"
            else:
                unavailable.append(ref)
        elif ref in metrics:
            values[ref] = metrics[ref].get("value")
            sources[ref] = str(metrics[ref].get("source_id") or "perception_metric")
        else:
            unavailable.append(ref)
    return values, unavailable, sources


def _diagnostic_suggestions(error: BaseException | None, occurrence_count: int = 1) -> list[dict]:
    if error is None:
        return []
    error_type = type(error).__name__
    message = str(error).casefold()
    suggestions: list[dict] = []
    def add(hypothesis: str, check: str, confidence: float) -> None:
        suggestions.append({"hypothesis": hypothesis, "safe_check": check, "confidence": round(max(0.0, min(1.0, confidence)), 2), "status": "unverified"})
    if "database is locked" in message or "database table is locked" in message:
        add("Another process or synchronization service may hold the SQLite file.", "Check for another NeatMemory/digest process and inspect whether OneDrive is synchronizing the database; do not delete databases.", 0.88)
        add("A transaction may have remained open after an interrupted operation.", "Retry once after the other process exits; then run the relevant isolated subsystem test if the lock repeats.", 0.68)
    elif error_type in {"APIConnectionError", "ConnectionError", "ConnectionRefusedError"} or "connection error" in message or "connection refused" in message:
        add("The configured model endpoint may not be reachable.", "Run /endpoint status and verify the selected server, URL, and port are active.", 0.9)
    elif error_type in {"TimeoutError", "APITimeoutError"} or "timed out" in message or "timeout" in message:
        add("The observed function exceeded its available response window.", "Check model/server load and retry with a smaller context or lower retrieval level before changing persistent data.", 0.8)
    elif error_type == "PermissionError" or "permission denied" in message or "access is denied" in message:
        add("The file may be open, synchronized, read-only, or blocked by permissions.", "Close other NeatMemory processes, check OneDrive activity and file permissions, then retry without deleting the file.", 0.84)
    elif error_type == "FileNotFoundError" or "no such file" in message:
        add("A configured path or required artifact may be missing or renamed.", "Verify the exact path and use the system's status command before recreating anything.", 0.86)
    elif error_type in {"JSONDecodeError", "UnicodeDecodeError"} or "decode" in message:
        add("A persisted or received payload may be malformed or encoded unexpectedly.", "Inspect the named receipt/configuration and validate its backup before editing it.", 0.76)
    elif error_type == "MemoryError" or "out of memory" in message:
        add("The operation may exceed available RAM or model context resources.", "Reduce token caps or retrieval level and close competing models before retrying.", 0.9)
    elif error_type == "ValueError":
        add("A value may violate a Python-validated configuration contract.", "Review the exact rejected field and compare it with /context variables or /context decorators.", 0.72)
    else:
        add("The failure needs its exact traceback and subsystem evidence before a repair is chosen.", "Use /diagnose show <DIAG-ID> and run the matching isolated subsystem test; keep the diagnosis provisional.", 0.55)
    if occurrence_count > 1:
        add("The same sanitized error signature has occurred repeatedly.", "Compare the linked diagnostic IDs and prior reckonings before repeating the same operation.", min(0.9, 0.55 + occurrence_count * 0.08))
    return suggestions[:5]


def _diagnostic_echo_links(module, function_name: str, error: BaseException | None) -> list[dict]:
    if error is None or not callable(getattr(module, "check_echo_safeguard", None)):
        return []
    try:
        result = module.check_echo_safeguard(
            f"{function_name} {type(error).__name__} {_diagnostic_scrub_text(error, 300)}",
            limit=3, persist=False, actor="FunctionDiagnostics",
        )
        return list(result.get("warnings") or [])[:3]
    except Exception:
        return []


def _diagnostic_persist(module, packet: dict, full_details: dict) -> dict:
    if _diagnostic_private_mode(module):
        packet["diagnostic_id"] = "DIAG-PRIVATE-" + packet["call_id"].split("-")[-1]
        packet["persistence"] = "private-mode-memory-only"
        return packet
    _diagnostic_ensure_schema(module)
    with _diagnostic_connect(module) as db:
        previous = db.execute("SELECT sequence,event_hash FROM function_diagnostic_events ORDER BY sequence DESC LIMIT 1").fetchone()
        sequence = int(previous["sequence"] + 1) if previous else 1
        previous_hash = str(previous["event_hash"]) if previous else None
        diagnostic_id = "DIAG-" + hashlib.sha256(f"{packet['created_at']}|{sequence}|{packet['call_id']}|{packet['group_id']}|{packet['phase']}".encode()).hexdigest()[:20].upper()
        error_signature = packet.get("error_signature")
        if error_signature:
            occurrence_count = int(db.execute("SELECT COUNT(*) FROM function_diagnostic_events WHERE error_signature=?", (error_signature,)).fetchone()[0]) + 1
        else:
            occurrence_count = 1
        packet["occurrence_count"] = occurrence_count
        packet["suggestions"] = _diagnostic_suggestions(full_details.get("error_object"), occurrence_count)
        packet["diagnostic_id"] = diagnostic_id
        packet["sequence"] = sequence
        detail_object_id = None
        put_object = getattr(module, "_blackbox_put_object", None)
        if callable(put_object):
            try:
                encrypted_details = dict(full_details)
                encrypted_details["packet"] = {key: value for key, value in packet.items() if key != "event_hash"}
                detail_object_id = put_object(encrypted_details, "function_diagnostic_detail")
            except Exception:
                detail_object_id = None
        fixed = {
            "diagnostic_id": diagnostic_id,
            "sequence": sequence,
            "call_id": packet["call_id"],
            "created_at": packet["created_at"],
            "function_name": packet["function_name"],
            "group_id": packet["group_id"],
            "phase": packet["phase"],
            "display_mode": packet["display_mode"],
            "success": packet.get("success"),
            "duration_ms": packet.get("duration_ms"),
            "tokens_before": packet.get("tokens_before"),
            "tokens_after": packet.get("tokens_after"),
            "error_type": packet.get("error_type"),
            "error_message": packet.get("error_message"),
            "error_signature": error_signature,
            "values": packet.get("values") or {},
            "unavailable": packet.get("unavailable") or [],
            "value_sources": packet.get("value_sources") or {},
            "suggestions": packet.get("suggestions") or [],
            "echo_links": packet.get("echo_links") or [],
            "full_detail_object_id": detail_object_id,
            "previous_event_hash": previous_hash,
        }
        event_hash = _diagnostic_hash(_diagnostic_json(fixed))
        db.execute(
            "INSERT INTO function_diagnostic_events(diagnostic_id,sequence,call_id,created_at,function_name,group_id,phase,display_mode,success,duration_ms,tokens_before,tokens_after,error_type,error_message,error_signature,values_json,unavailable_json,value_sources_json,suggestions_json,echo_links_json,full_detail_object_id,previous_event_hash,event_hash) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (diagnostic_id, sequence, packet["call_id"], packet["created_at"], packet["function_name"], packet["group_id"], packet["phase"], packet["display_mode"],
             None if packet.get("success") is None else int(bool(packet.get("success"))), packet.get("duration_ms"), packet.get("tokens_before"), packet.get("tokens_after"),
             packet.get("error_type"), packet.get("error_message"), error_signature, _diagnostic_json(packet.get("values") or {}), _diagnostic_json(packet.get("unavailable") or []),
             _diagnostic_json(packet.get("value_sources") or {}), _diagnostic_json(packet.get("suggestions") or []), _diagnostic_json(packet.get("echo_links") or []),
             detail_object_id, previous_hash, event_hash),
        )
    packet["diagnostic_id"] = diagnostic_id
    packet["sequence"] = sequence
    packet["event_hash"] = event_hash
    packet["full_detail_object_id"] = detail_object_id
    packet["persistence"] = "append-only-index-and-encrypted-detail"
    return packet


def _diagnostic_render_packet(packet: dict) -> str:
    heading = "FUNCTION ERROR" if packet.get("phase") == "error" else f"FUNCTION {str(packet.get('phase') or '').upper()}"
    lines = [
        f"[{heading} — PYTHON OBSERVATION, NO AUTOMATIC REPAIR]",
        f"Diagnostic: {packet.get('diagnostic_id') or '[pending]'} | Call: {packet.get('call_id')}",
        f"Function: {packet.get('function_name')} | Group: {packet.get('group_id')} | Phase: {packet.get('phase')}",
    ]
    if packet.get("duration_ms") is not None:
        lines.append(f"Duration: {float(packet['duration_ms']):.3f} ms | Tokens: {packet.get('tokens_before')} -> {packet.get('tokens_after') if packet.get('tokens_after') is not None else '[unavailable]'}")
    if packet.get("error_type"):
        lines.append(f"Error: {packet.get('error_type')}: {packet.get('error_message')}")
    if packet.get("values"):
        lines.append("Selected safe values:")
        for key, value in list((packet.get("values") or {}).items())[:24]:
            lines.append(f"  {key} = {value}")
    if packet.get("unavailable"):
        lines.append("Unavailable for this phase: " + ", ".join(packet.get("unavailable") or []))
    if packet.get("suggestions"):
        lines.append("Provisional diagnostic checks:")
        for item in packet.get("suggestions") or []:
            lines.append(f"  - [{float(item.get('confidence') or 0):.2f}] {item.get('hypothesis')} Check: {item.get('safe_check')}")
    if packet.get("echo_links"):
        lines.append("Prior-outcome echoes (advisory only): " + ", ".join(str(item.get("reference")) for item in packet.get("echo_links") or []))
    lines.append("Boundary: diagnosis is a hypothesis until verified; destructive repair requires Steeve's explicit command.")
    return "\n".join(lines)[:9000]


def _diagnostic_queue_context(packet: dict) -> None:
    _DIAGNOSTIC_CONTEXT_QUEUE.append(dict(packet))
    del _DIAGNOSTIC_CONTEXT_QUEUE[:-_DIAGNOSTIC_CONTEXT_QUEUE_LIMIT]


def _diagnostic_drain_context() -> str:
    if not _DIAGNOSTIC_CONTEXT_QUEUE:
        return ""
    packets = list(_DIAGNOSTIC_CONTEXT_QUEUE)
    _DIAGNOSTIC_CONTEXT_QUEUE.clear()
    return "\n\n".join(_diagnostic_render_packet(packet) for packet in packets)


def _diagnostic_emit(module, observer: dict, *, function_name: str, phase: str, call_id: str,
                     query: str, duration_ms: float | None, tokens_before: int,
                     tokens_after: int | None, error: BaseException | None,
                     call_depth: int) -> dict | None:
    if getattr(_DIAGNOSTIC_GUARD, "emitting", False):
        return None
    _DIAGNOSTIC_GUARD.emitting = True
    try:
        values, unavailable, sources = _diagnostic_collect_values(
            module, observer, function_name=function_name, phase=phase, call_id=call_id,
            query=query, duration_ms=duration_ms, tokens_before=tokens_before,
            tokens_after=tokens_after, error=error, call_depth=call_depth,
        )
        error_message = _diagnostic_scrub_text(error) if error is not None else None
        error_signature = None
        if error is not None:
            error_signature = hashlib.sha256(f"{function_name}|{type(error).__name__}|{error_message}".encode()).hexdigest()
        packet = {
            "created_at": _diagnostic_now(), "call_id": call_id,
            "function_name": function_name, "group_id": observer["group_id"],
            "phase": phase, "display_mode": observer.get("display") or "trace",
            "success": phase != "error", "duration_ms": None if duration_ms is None else round(float(duration_ms), 3),
            "tokens_before": int(tokens_before), "tokens_after": None if tokens_after is None else int(tokens_after),
            "error_type": type(error).__name__ if error is not None else None,
            "error_message": error_message, "error_signature": error_signature,
            "values": values, "unavailable": unavailable, "value_sources": sources,
            "suggestions": _diagnostic_suggestions(error, 1), "echo_links": _diagnostic_echo_links(module, function_name, error),
            "observer_locked": bool(observer.get("locked")), "automatic_repair": False,
        }
        full_details = {
            "packet": packet,
            "traceback": _diagnostic_scrub_traceback("".join(traceback.format_exception(type(error), error, error.__traceback__)) if error is not None else "", 20000),
            "error_object": error,
            "runtime_version": getattr(module, "NEATMEMORY_VERSION", BUNDLE_VERSION),
        }
        try:
            packet = _diagnostic_persist(module, packet, full_details)
        except Exception as persist_error:
            packet["diagnostic_id"] = "DIAG-VOLATILE-" + call_id.split("-")[-1]
            packet["persistence"] = f"failed safely: {type(persist_error).__name__}: {_diagnostic_scrub_text(persist_error, 300)}"
            packet["suggestions"] = _diagnostic_suggestions(error, 1)
        module._LAST_FUNCTION_DIAGNOSTIC = dict(packet)
        if phase == "error":
            module._LAST_FUNCTION_ERROR_DIAGNOSTIC = dict(packet)
        display = str(observer.get("display") or "trace")
        if display == "console":
            print(_diagnostic_render_packet(packet))
        elif display == "context":
            _diagnostic_queue_context(packet)
        return packet
    finally:
        _DIAGNOSTIC_GUARD.emitting = False


def _diagnostic_row_to_dict(row: sqlite3.Row) -> dict:
    return {
        "diagnostic_id": row["diagnostic_id"], "sequence": row["sequence"], "call_id": row["call_id"],
        "created_at": row["created_at"], "function_name": row["function_name"], "group_id": row["group_id"],
        "phase": row["phase"], "display_mode": row["display_mode"],
        "success": None if row["success"] is None else bool(row["success"]),
        "duration_ms": row["duration_ms"], "tokens_before": row["tokens_before"], "tokens_after": row["tokens_after"],
        "error_type": row["error_type"], "error_message": row["error_message"], "error_signature": row["error_signature"],
        "values": json.loads(row["values_json"] or "{}"), "unavailable": json.loads(row["unavailable_json"] or "[]"),
        "value_sources": json.loads(row["value_sources_json"] or "{}"), "suggestions": json.loads(row["suggestions_json"] or "[]"),
        "echo_links": json.loads(row["echo_links_json"] or "[]"), "full_detail_object_id": row["full_detail_object_id"],
        "previous_event_hash": row["previous_event_hash"], "event_hash": row["event_hash"],
    }


def _diagnostic_list(module, *, limit: int = 20, errors_only: bool = False) -> dict:
    _diagnostic_ensure_schema(module)
    limit = max(1, min(_DIAGNOSTIC_LIST_LIMIT, int(limit)))
    clause = "WHERE phase='error'" if errors_only else ""
    with _diagnostic_connect(module) as db:
        rows = db.execute(f"SELECT * FROM function_diagnostic_events {clause} ORDER BY sequence DESC LIMIT ?", (limit,)).fetchall()
    events = [_diagnostic_row_to_dict(row) for row in rows]
    return {"ok": True, "errors_only": bool(errors_only), "count": len(events), "events": events}


def _diagnostic_get(module, diagnostic_id: str, *, include_details: bool = False) -> dict:
    _diagnostic_ensure_schema(module)
    with _diagnostic_connect(module) as db:
        row = db.execute("SELECT * FROM function_diagnostic_events WHERE diagnostic_id=?", (str(diagnostic_id).strip().upper(),)).fetchone()
    if row is None:
        return {"ok": False, "error": "Diagnostic event not found.", "diagnostic_id": diagnostic_id}
    event = _diagnostic_row_to_dict(row)
    result = {"ok": True, "event": event}
    if include_details and event.get("full_detail_object_id") and callable(getattr(module, "_blackbox_get_object", None)):
        try:
            detail = module._blackbox_get_object(event["full_detail_object_id"])
            if isinstance(detail, dict):
                detail = dict(detail)
                detail.pop("error_object", None)
                detail["traceback"] = _diagnostic_scrub_traceback(detail.get("traceback"), 20000)
            result["encrypted_details"] = detail
        except Exception as exc:
            result["encrypted_details_error"] = f"{type(exc).__name__}: {_diagnostic_scrub_text(exc)}"
    return result


def _diagnostic_last_failure(module) -> dict:
    _diagnostic_ensure_schema(module)
    with _diagnostic_connect(module) as db:
        row = db.execute("SELECT * FROM function_diagnostic_events WHERE phase='error' ORDER BY sequence DESC LIMIT 1").fetchone()
    if row is None:
        last = getattr(module, "_LAST_FUNCTION_ERROR_DIAGNOSTIC", None)
        return {"ok": bool(last), "event": last, "message": "No persisted function error has been recorded." if not last else "Latest error is memory-only."}
    event = _diagnostic_row_to_dict(row)
    return {
        "ok": True, "event": event,
        "diagnosis_boundary": "Suggestions are hypotheses until verified. No automatic repair is authorized.",
        "recommended_next_command": f"/diagnose show {event['diagnostic_id']}",
    }


def _diagnostic_verify(module, diagnostic_id: str | None = None) -> dict:
    _diagnostic_ensure_schema(module)
    with _diagnostic_connect(module) as db:
        if diagnostic_id:
            target = db.execute("SELECT sequence FROM function_diagnostic_events WHERE diagnostic_id=?", (str(diagnostic_id).strip().upper(),)).fetchone()
            if target is None:
                return {"ok": False, "error": "Diagnostic event not found.", "diagnostic_id": diagnostic_id}
            rows = db.execute("SELECT * FROM function_diagnostic_events WHERE sequence<=? ORDER BY sequence", (target["sequence"],)).fetchall()
        else:
            rows = db.execute("SELECT * FROM function_diagnostic_events ORDER BY sequence").fetchall()
    errors = []
    previous_hash = None
    checked_objects = 0
    for row in rows:
        event = _diagnostic_row_to_dict(row)
        fixed = {
            "diagnostic_id": event["diagnostic_id"], "sequence": event["sequence"], "call_id": event["call_id"],
            "created_at": event["created_at"], "function_name": event["function_name"], "group_id": event["group_id"],
            "phase": event["phase"], "display_mode": event["display_mode"], "success": event["success"],
            "duration_ms": event["duration_ms"], "tokens_before": event["tokens_before"], "tokens_after": event["tokens_after"],
            "error_type": event["error_type"], "error_message": event["error_message"], "error_signature": event["error_signature"],
            "values": event["values"], "unavailable": event["unavailable"], "value_sources": event["value_sources"],
            "suggestions": event["suggestions"], "echo_links": event["echo_links"], "full_detail_object_id": event["full_detail_object_id"],
            "previous_event_hash": event["previous_event_hash"],
        }
        calculated = _diagnostic_hash(_diagnostic_json(fixed))
        if event["previous_event_hash"] != previous_hash:
            errors.append({"diagnostic_id": event["diagnostic_id"], "error": "previous hash mismatch"})
        if calculated != event["event_hash"]:
            errors.append({"diagnostic_id": event["diagnostic_id"], "error": "event hash mismatch"})
        if event.get("full_detail_object_id") and callable(getattr(module, "_blackbox_get_object", None)):
            try:
                module._blackbox_get_object(event["full_detail_object_id"])
                checked_objects += 1
            except Exception as exc:
                errors.append({"diagnostic_id": event["diagnostic_id"], "error": f"encrypted detail failed verification: {type(exc).__name__}"})
        previous_hash = event["event_hash"]
    return {"ok": not errors, "checked_events": len(rows), "checked_encrypted_details": checked_objects, "errors": errors, "target": diagnostic_id}


def _diagnostic_status(module) -> dict:
    try:
        _diagnostic_ensure_schema(module)
        with _diagnostic_connect(module) as db:
            total = int(db.execute("SELECT COUNT(*) FROM function_diagnostic_events").fetchone()[0])
            errors = int(db.execute("SELECT COUNT(*) FROM function_diagnostic_events WHERE phase='error'").fetchone()[0])
    except Exception:
        total, errors = 0, 0
    routing = _context_routing_status(module, include_groups=True)
    configured = [{key: row.get(key) for key in ("group_id", "locked", "decorator_function", "decorator_phase", "decorator_display", "decorator_values")} for row in routing.get("groups", []) if row.get("decorator_function") and row.get("decorator_phase") != "off"]
    return {
        "ok": True, "feature_version": _FUNCTION_OBSERVABILITY_VERSION,
        "database": str(_diagnostic_db_path(module)), "append_only_events": total, "error_events": errors,
        "private_mode": _diagnostic_private_mode(module), "pending_context_packets": len(_DIAGNOSTIC_CONTEXT_QUEUE),
        "allowlisted_functions": sorted(_CONTEXT_DECORATOR_ALLOWED_FUNCTIONS),
        "phases": sorted(_CONTEXT_DECORATOR_PHASES), "displays": sorted(_CONTEXT_DECORATOR_DISPLAYS),
        "configured_decorators": configured,
        "safety": {"changes_return_values": False, "automatic_repair": False, "arbitrary_function_names": False, "private_mode_persistence": False},
    }


def _diagnostic_wrap_function(module, function_name: str) -> bool:
    if function_name in _DIAGNOSTIC_WRAPPED_FUNCTIONS:
        return True
    original = getattr(module, function_name, None)
    if not callable(original):
        return False

    @functools.wraps(original)
    def observed(*args, **kwargs):
        global _DIAGNOSTIC_LAST_SUCCESSFUL_FUNCTION
        stack = list(getattr(_DIAGNOSTIC_GUARD, "stack", []))
        if function_name in stack or getattr(_DIAGNOSTIC_GUARD, "emitting", False):
            return original(*args, **kwargs)
        observers = _diagnostic_active_observers(module, function_name)
        if not observers:
            return original(*args, **kwargs)
        query = _diagnostic_query_for_call(function_name, args, kwargs)
        query_hash = hashlib.sha256(str(query).encode("utf-8")).hexdigest()[:12].upper()
        call_id = "CALL-" + hashlib.sha256(f"{_diagnostic_now()}|{time.perf_counter_ns()}|{os.getpid()}|{function_name}|{query_hash}".encode()).hexdigest()[:20].upper()
        tokens_before = _diagnostic_token_count({"args": args, "kwargs": kwargs})
        started = time.perf_counter()
        stack.append(function_name)
        _DIAGNOSTIC_GUARD.stack = stack
        for observer in observers:
            if observer["phase"] in {"start", "both"}:
                _diagnostic_emit(module, observer, function_name=function_name, phase="start", call_id=call_id,
                                 query=query, duration_ms=None, tokens_before=tokens_before, tokens_after=None,
                                 error=None, call_depth=len(stack))
        try:
            result = original(*args, **kwargs)
        except BaseException as exc:
            duration_ms = (time.perf_counter() - started) * 1000.0
            for observer in observers:
                if observer["phase"] in {"error", "both"}:
                    _diagnostic_emit(module, observer, function_name=function_name, phase="error", call_id=call_id,
                                     query=query, duration_ms=duration_ms, tokens_before=tokens_before, tokens_after=None,
                                     error=exc, call_depth=len(stack))
            raise
        else:
            duration_ms = (time.perf_counter() - started) * 1000.0
            tokens_after = _diagnostic_token_count(result)
            for observer in observers:
                if observer["phase"] in {"end", "both"}:
                    _diagnostic_emit(module, observer, function_name=function_name, phase="end", call_id=call_id,
                                     query=query, duration_ms=duration_ms, tokens_before=tokens_before, tokens_after=tokens_after,
                                     error=None, call_depth=len(stack))
            _DIAGNOSTIC_LAST_SUCCESSFUL_FUNCTION = function_name
            module._DIAGNOSTIC_LAST_SUCCESSFUL_FUNCTION = function_name
            if function_name == "build_runtime_context" and isinstance(result, str):
                diagnostic_context = _diagnostic_drain_context()
                if diagnostic_context:
                    result = result.rstrip() + "\n\n" + diagnostic_context
            return result
        finally:
            current = list(getattr(_DIAGNOSTIC_GUARD, "stack", []))
            if current and current[-1] == function_name:
                current.pop()
            else:
                current = [name for name in current if name != function_name]
            _DIAGNOSTIC_GUARD.stack = current

    observed._neat_function_observer = True
    observed._neat_original_function = original
    _DIAGNOSTIC_WRAPPED_FUNCTIONS[function_name] = original
    setattr(module, function_name, observed)
    return True


def _diagnostic_handle_command(module, raw: str) -> bool:
    clean = " ".join(str(raw or "").strip().split())
    lower = clean.casefold()
    if lower in {"/diagnose", "/diagnose help"}:
        print("/diagnose status | last | errors [count] | show <DIAG-ID> | verify [DIAG-ID] | pending | authority-flow [RF-RUN-ID]")
        return True
    if lower == "/diagnose authority-flow" or lower.startswith("/diagnose authority-flow "):
        parts = clean.split(maxsplit=2)
        run_id = parts[2].strip() if len(parts) > 2 else None
        fn = getattr(module, "diagnose_authority_flow", None)
        if not callable(fn):
            print(json.dumps({"ok": False, "error": "authority-flow diagnostic unavailable"}, ensure_ascii=False, indent=2)); return True
        print(json.dumps(fn(run_id=run_id), ensure_ascii=False, indent=2, default=str)); return True
    if lower == "/diagnose status":
        print(json.dumps(_diagnostic_status(module), ensure_ascii=False, indent=2)); return True
    if lower == "/diagnose last":
        print(json.dumps(_diagnostic_last_failure(module), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/diagnose errors"):
        parts = clean.split()
        count = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 10
        print(json.dumps(_diagnostic_list(module, limit=count, errors_only=True), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/diagnose show "):
        diagnostic_id = clean.split(maxsplit=2)[2]
        print(json.dumps(_diagnostic_get(module, diagnostic_id, include_details=True), ensure_ascii=False, indent=2, default=str)); return True
    if lower == "/diagnose verify":
        print(json.dumps(_diagnostic_verify(module), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/diagnose verify "):
        diagnostic_id = clean.split(maxsplit=2)[2]
        print(json.dumps(_diagnostic_verify(module, diagnostic_id), ensure_ascii=False, indent=2)); return True
    if lower == "/diagnose pending":
        print(json.dumps({"ok": True, "pending": len(_DIAGNOSTIC_CONTEXT_QUEUE), "packets": list(_DIAGNOSTIC_CONTEXT_QUEUE)}, ensure_ascii=False, indent=2)); return True
    return False


def _install_function_lifecycle_observability(module) -> None:
    if getattr(module, "_FUNCTION_LIFECYCLE_OBSERVABILITY_INSTALLED", False):
        return
    try:
        _diagnostic_ensure_schema(module)
    except Exception:
        pass
    module.FUNCTION_OBSERVABILITY_VERSION = _FUNCTION_OBSERVABILITY_VERSION
    module.DIAGNOSTIC_SCHEMA_VERSION = _DIAGNOSTIC_SCHEMA_VERSION
    module.get_function_observability_status = lambda: _diagnostic_status(module)
    module.list_function_diagnostics = lambda limit=20, errors_only=False: _diagnostic_list(module, limit=limit, errors_only=errors_only)
    module.get_function_diagnostic = lambda diagnostic_id, include_details=False: _diagnostic_get(module, diagnostic_id, include_details=include_details)
    module.diagnose_last_failure = lambda: _diagnostic_last_failure(module)
    module.verify_function_diagnostics = lambda diagnostic_id=None: _diagnostic_verify(module, diagnostic_id)

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_function_observability_status","description":"Read allowlisted function lifecycle observers, configured group decorators, diagnostic counts, and safety boundaries.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"diagnose_last_failure","description":"Read the latest sanitized function failure, selected safe values, prior-outcome echoes, and provisional checks. This never repairs the system.","parameters":{"type":"object","properties":{},"additionalProperties":False}}},
        {"type":"function","function":{"name":"list_function_diagnostics","description":"List append-only sanitized function diagnostic events.","parameters":{"type":"object","properties":{"limit":{"type":"integer"},"errors_only":{"type":"boolean"}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_function_diagnostic","description":"Read one sanitized diagnostic event by DIAG-ID. Encrypted traceback details remain excluded from normal model tools.","parameters":{"type":"object","properties":{"diagnostic_id":{"type":"string"}},"required":["diagnostic_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"verify_function_diagnostics","description":"Verify the append-only diagnostic hash chain and encrypted detail object integrity.","parameters":{"type":"object","properties":{"diagnostic_id":{"type":"string"}},"additionalProperties":False}}},
    ])
    module._READ_ONLY_TEXT_TOOL_ALLOWLIST.update({"get_function_observability_status", "diagnose_last_failure", "list_function_diagnostics", "get_function_diagnostic", "verify_function_diagnostics"})
    old_execute = module.execute_tool
    def execute_tool_with_diagnostics(name, arguments, seen, *, allow_sticky, sticky_state):
        if name == "get_function_observability_status": return module.get_function_observability_status()
        if name == "diagnose_last_failure": return module.diagnose_last_failure()
        if name == "list_function_diagnostics": return module.list_function_diagnostics(**arguments)
        if name == "get_function_diagnostic": return module.get_function_diagnostic(arguments.get("diagnostic_id"), include_details=False)
        if name == "verify_function_diagnostics": return module.verify_function_diagnostics(arguments.get("diagnostic_id"))
        return old_execute(name, arguments, seen, allow_sticky=allow_sticky, sticky_state=sticky_state)
    module.execute_tool = execute_tool_with_diagnostics

    for function_name in sorted(_CONTEXT_DECORATOR_ALLOWED_FUNCTIONS - {"run_chat_turn"}):
        _diagnostic_wrap_function(module, function_name)

    old_help = module.print_help
    def help_with_diagnostics(*args, **kwargs):
        result = old_help(*args, **kwargs)
        print("  /context decorators")
        print("  /diagnose status|last|errors [count]|show <DIAG-ID>|verify [DIAG-ID]|pending")
        print("  Function observers are allowlisted, read-only, private-mode aware, and never perform automatic repair.")
        return result
    module.print_help = help_with_diagnostics

    old_main = module.main
    def main_with_diagnostic_commands():
        original_input = builtins.input
        def diagnostic_input(prompt=""):
            while True:
                raw = original_input(prompt)
                if _diagnostic_handle_command(module, raw):
                    continue
                return raw
        builtins.input = diagnostic_input
        try:
            return old_main()
        finally:
            builtins.input = original_input
    module.main = main_with_diagnostic_commands

    def function_observability_self_test() -> dict:
        global _BLACKBOX_PRIVATE_MODE
        crypto = _identity_crypto()
        original_encrypt = crypto.encrypt_text
        original_decrypt = crypto.decrypt_text
        original_safe_path = module.safe_memory_path
        original_cache = getattr(module, "_CONTEXT_ROUTING_STATE_CACHE", None)
        original_private = globals().get("_BLACKBOX_PRIVATE_MODE", False)
        original_probe = getattr(module, "diagnostic_probe", None)
        original_last = getattr(module, "_LAST_FUNCTION_DIAGNOSTIC", None)
        original_queue = list(_DIAGNOSTIC_CONTEXT_QUEUE)
        probe_was_allowlisted = "diagnostic_probe" in _CONTEXT_DECORATOR_ALLOWED_FUNCTIONS
        _CONTEXT_DECORATOR_ALLOWED_FUNCTIONS.add("diagnostic_probe")
        with tempfile.TemporaryDirectory(prefix="neatmemory-function-diagnostics-") as folder:
            root = Path(folder)
            key = b"diagnostic-self-test-key"
            def test_encrypt(text, entropy=b""):
                raw = text.encode("utf-8")
                mask = hashlib.sha256(key + bytes(entropy)).digest()
                return b"TESTDIAG1" + bytes(value ^ mask[index % len(mask)] for index, value in enumerate(raw))
            def test_decrypt(blob, entropy=b""):
                raw = bytes(blob)
                if not raw.startswith(b"TESTDIAG1"):
                    raise ValueError("test cipher header")
                mask = hashlib.sha256(key + bytes(entropy)).digest()
                return bytes(value ^ mask[index % len(mask)] for index, value in enumerate(raw[9:])).decode("utf-8")
            crypto.encrypt_text = test_encrypt
            crypto.decrypt_text = test_decrypt
            module.safe_memory_path = lambda filename: root / filename
            module.initialize_database()
            module._CONTEXT_ROUTING_STATE_CACHE = _context_routing_default_state()
            _DIAGNOSTIC_CONTEXT_QUEUE.clear()
            try:
                def probe(mode="ok"):
                    if mode == "error":
                        raise sqlite3.OperationalError("database is locked")
                    return "probe-result"
                module.diagnostic_probe = probe
                _DIAGNOSTIC_WRAPPED_FUNCTIONS.pop("diagnostic_probe", None)
                _diagnostic_wrap_function(module, "diagnostic_probe")
                configured = _context_routing_update_group(
                    module, "personal_memory",
                    {"decorator_function":"diagnostic_probe", "decorator_phase":"both", "decorator_display":"trace",
                     "decorator_values":["diagnostic.duration_ms", "diagnostic.tokens_before", "emotion.CONNECTION.current"]},
                    actor="SelfTest", reason="exercise lifecycle observer",
                )
                success_result = module.diagnostic_probe("ok")
                error_re_raised = False
                try:
                    module.diagnostic_probe("error")
                except sqlite3.OperationalError:
                    error_re_raised = True
                events = _diagnostic_list(module, limit=20)
                phases = [event.get("phase") for event in events.get("events") or []]
                errors = _diagnostic_list(module, limit=10, errors_only=True)
                last = _diagnostic_last_failure(module)
                verify = _diagnostic_verify(module)
                unsafe_rejected = False
                try:
                    _context_routing_update_group(module, "personal_memory", {"decorator_function":"__import__"}, actor="SelfTest", reason="reject unsafe target")
                except ValueError:
                    unsafe_rejected = True
                context_config = _context_routing_update_group(
                    module, "observer_hypotheses",
                    {"decorator_function":"diagnostic_probe", "decorator_phase":"error", "decorator_display":"context",
                     "decorator_values":["diagnostic.error_type", "diagnostic.error_message"]},
                    actor="SelfTest", reason="exercise context error packet",
                )
                try:
                    module.diagnostic_probe("error")
                except sqlite3.OperationalError:
                    pass
                queued = _diagnostic_drain_context()
                with _diagnostic_connect(module) as db:
                    before_private = int(db.execute("SELECT COUNT(*) FROM function_diagnostic_events").fetchone()[0])
                _BLACKBOX_PRIVATE_MODE = True
                try:
                    module.diagnostic_probe("error")
                except sqlite3.OperationalError:
                    pass
                _BLACKBOX_PRIVATE_MODE = False
                with _diagnostic_connect(module) as db:
                    after_private = int(db.execute("SELECT COUNT(*) FROM function_diagnostic_events").fetchone()[0])
                    append_only = False
                    try:
                        db.execute("UPDATE function_diagnostic_events SET phase='changed'")
                    except sqlite3.DatabaseError:
                        append_only = True
                status = _diagnostic_status(module)
                checks = {
                    "configured_on_context_group": configured.get("group", {}).get("decorator_function") == "diagnostic_probe",
                    "start_end_and_error_recorded": all(phase in phases for phase in ("start", "end", "error")),
                    "return_value_unchanged": success_result == "probe-result",
                    "original_error_re_raised": error_re_raised,
                    "safe_values_recorded": any("diagnostic.tokens_before" in (event.get("values") or {}) for event in events.get("events") or []),
                    "database_lock_diagnosis_generated": any("SQLite" in str(item.get("hypothesis")) or "process" in str(item.get("hypothesis")) for item in ((last.get("event") or {}).get("suggestions") or [])),
                    "context_packet_visible": "FUNCTION ERROR" in queued and "NO AUTOMATIC REPAIR" in queued,
                    "unsafe_function_rejected": unsafe_rejected,
                    "private_mode_not_persisted": before_private == after_private,
                    "append_only_enforced": append_only,
                    "hash_chain_verifies": bool(verify.get("ok")),
                    "status_exposes_allowlist": "build_runtime_context" in status.get("allowlisted_functions", []),
                    "no_automatic_repair": status.get("safety", {}).get("automatic_repair") is False,
                    "error_index_queryable": bool(errors.get("events")),
                    "context_configuration_saved": context_config.get("group", {}).get("decorator_display") == "context",
                }
                return {"ok": all(checks.values()), "checks": checks, "status": status, "last_failure": last, "verification": verify}
            finally:
                crypto.encrypt_text = original_encrypt
                crypto.decrypt_text = original_decrypt
                module.safe_memory_path = original_safe_path
                module._CONTEXT_ROUTING_STATE_CACHE = original_cache
                _BLACKBOX_PRIVATE_MODE = original_private
                _DIAGNOSTIC_CONTEXT_QUEUE.clear(); _DIAGNOSTIC_CONTEXT_QUEUE.extend(original_queue)
                if original_probe is None:
                    try: delattr(module, "diagnostic_probe")
                    except Exception: pass
                else:
                    module.diagnostic_probe = original_probe
                if original_last is None:
                    try: delattr(module, "_LAST_FUNCTION_DIAGNOSTIC")
                    except Exception: pass
                else:
                    module._LAST_FUNCTION_DIAGNOSTIC = original_last
                if not probe_was_allowlisted:
                    _CONTEXT_DECORATOR_ALLOWED_FUNCTIONS.discard("diagnostic_probe")
    module.function_observability_self_test = function_observability_self_test
    module._FUNCTION_LIFECYCLE_OBSERVABILITY_INSTALLED = True


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:semantic-provenance-maintenance rev=4
# Semantic Data Cleanliness + Evidence Alignment Audit (7.4.37.10)
# ---------------------------------------------------------------------------
_SEMANTIC_DATA_AUDIT_VERSION = "1.0-read-only-model-evidence-alignment"
_EDA_ALIGNMENT = {"ALIGNED", "PARTIAL", "MISMATCH", "UNCERTAIN"}
_EDA_CLEANLINESS = {"CLEAN", "MINOR_NOISE", "SUSPICIOUS", "CORRUPTED"}
_EDA_DEFAULT_QUICK_LIMIT = 24
_EDA_DEFAULT_BATCH_ITEMS = 8
_EDA_MAX_BATCH_CHARS = 70000


def _eda_terms(value: str) -> set[str]:
    return {t for t in _sk_validation_terms(str(value or "")) if len(t) > 2}


def _eda_overlap_ratio(claim: str, excerpts: list[str]) -> float:
    claim_terms = _eda_terms(claim)
    if not claim_terms:
        return 1.0
    evidence_terms = _eda_terms("\n".join(str(x or "") for x in excerpts))
    return round(len(claim_terms & evidence_terms) / max(1, len(claim_terms)), 4)


def _eda_active_items(source_filter: str | None = None) -> list[dict]:
    source_filter = str(source_filter or "").strip()
    with _sk_connect() as db:
        rows = db.execute(
            """SELECT i.*,v.version_number,v.provider,v.model_alias,v.model_id,
                      s.source_id,s.source_kind,s.source_key,s.title
               FROM knowledge_items i
               JOIN knowledge_versions v ON v.version_id=i.version_id
               JOIN knowledge_sources s ON s.source_id=v.source_id
               WHERE s.active=1 AND s.retired=0 AND v.active=1 AND v.archive=0 AND v.status='completed'
               ORDER BY s.source_id,i.item_id"""
        ).fetchall()
        output = []
        for row in rows:
            item = dict(row)
            if source_filter and source_filter not in {str(item.get("source_id") or ""), str(item.get("source_key") or "")}:
                continue
            sources = [dict(x) for x in db.execute(
                "SELECT ordinal,source_ref,locator_json,evidence_sha256,excerpt_sha256,excerpt FROM knowledge_item_sources WHERE item_id=? ORDER BY ordinal",
                (str(item.get("item_id") or ""),),
            ).fetchall()]
            excerpt_texts = []
            integrity = []
            for src in sources:
                excerpt = str(src.get("excerpt") or "")
                excerpt_texts.append(excerpt)
                actual = _sk_hash(excerpt)
                stored = str(src.get("excerpt_sha256") or "")
                integrity.append({
                    "ordinal": int(src.get("ordinal") or 0),
                    "source_ref": str(src.get("source_ref") or ""),
                    "stored_excerpt_sha256": stored,
                    "actual_excerpt_sha256": actual,
                    "excerpt_hash_matches": bool(stored and actual == stored),
                    "evidence_sha256": str(src.get("evidence_sha256") or ""),
                    "characters": len(excerpt),
                })
                try:
                    src["locator"] = json.loads(src.pop("locator_json") or "{}")
                except Exception:
                    src["locator"] = {}
            claim = str(item.get("claim") or "")
            output.append({
                "item": item,
                "sources": sources,
                "integrity": integrity,
                "claim_evidence_overlap": _eda_overlap_ratio(claim, excerpt_texts),
                "all_excerpt_hashes_match": bool(sources) and all(x["excerpt_hash_matches"] for x in integrity),
                "source_count": len(sources),
            })
    return output


def _eda_select(items: list[dict], *, suite: str = "quick", limit: int = 0, item_id: str | None = None) -> list[dict]:
    item_id = str(item_id or "").strip()
    if item_id:
        return [x for x in items if str(x.get("item", {}).get("item_id") or "") == item_id]
    suite = str(suite or "quick").casefold()
    if suite == "full":
        selected = list(items)
        if int(limit or 0) > 0:
            selected = selected[: int(limit)]
        return selected
    target = int(limit or _EDA_DEFAULT_QUICK_LIMIT)
    target = max(1, min(target, len(items))) if items else 0
    # Quick mode is diagnostic rather than random: half targets low lexical
    # claim/source overlap, while half is a stable source-diverse sample.
    suspect_n = max(1, target // 2) if target else 0
    by_overlap = sorted(items, key=lambda x: (float(x.get("claim_evidence_overlap", 1.0)), str(x.get("item", {}).get("item_id") or "")))
    selected = by_overlap[:suspect_n]
    selected_ids = {str(x.get("item", {}).get("item_id") or "") for x in selected}
    remainder = [x for x in items if str(x.get("item", {}).get("item_id") or "") not in selected_ids]
    remainder.sort(key=lambda x: hashlib.sha256(str(x.get("item", {}).get("item_id") or "").encode("utf-8")).hexdigest())
    seen_sources = {str(x.get("item", {}).get("source_id") or "") for x in selected}
    for row in remainder:
        if len(selected) >= target:
            break
        sid = str(row.get("item", {}).get("source_id") or "")
        if sid not in seen_sources:
            selected.append(row)
            selected_ids.add(str(row.get("item", {}).get("item_id") or ""))
            seen_sources.add(sid)
    for row in remainder:
        if len(selected) >= target:
            break
        iid = str(row.get("item", {}).get("item_id") or "")
        if iid not in selected_ids:
            selected.append(row)
            selected_ids.add(iid)
    return selected



def _eda_parse_json_text(text: str) -> dict:
    raw=str(text or "").strip()
    if raw.startswith("```"):
        raw=re.sub(r"^```(?:json)?\s*", "", raw, flags=re.I)
        raw=re.sub(r"\s*```$", "", raw)
    return json.loads(raw)



def _eda_validate_batch(batch: list[dict], payload: dict) -> tuple[list[dict],list[str]]:
    expected={str(x.get("item",{}).get("item_id") or "") for x in batch}
    rows=list(payload.get("results") or []) if isinstance(payload,dict) else []
    seen=set(); errors=[]; valid=[]
    source_ordinals={str(x.get("item",{}).get("item_id") or ""):{int(s.get("ordinal") or 0) for s in (x.get("sources") or [])} for x in batch}
    for row in rows:
        if not isinstance(row,dict):
            errors.append("non-object result"); continue
        iid=str(row.get("item_id") or "")
        if iid not in expected:
            errors.append(f"unknown item_id: {iid}"); continue
        if iid in seen:
            errors.append(f"duplicate item_id: {iid}"); continue
        if str(row.get("text_cleanliness") or "") not in _EDA_CLEANLINESS:
            errors.append(f"invalid cleanliness for {iid}"); continue
        if str(row.get("evidence_alignment") or "") not in _EDA_ALIGNMENT:
            errors.append(f"invalid alignment for {iid}"); continue
        ordinals=[int(x) for x in (row.get("supporting_source_ordinals") or [])]
        bad=[x for x in ordinals if x not in source_ordinals.get(iid,set())]
        if bad:
            errors.append(f"invalid source ordinals for {iid}: {bad}"); continue
        valid.append(dict(row)); seen.add(iid)
    missing=sorted(expected-seen)
    if missing: errors.append("missing item_ids: "+",".join(missing))
    return valid,errors


def _eda_pack_batches(items: list[dict], batch_items: int) -> list[list[dict]]:
    batches=[]; current=[]; current_chars=0
    limit=max(1,min(16,int(batch_items or _EDA_DEFAULT_BATCH_ITEMS)))
    for row in items:
        estimate=len(json.dumps(_eda_prompt_items([row]),ensure_ascii=False))
        if current and (len(current)>=limit or current_chars+estimate>_EDA_MAX_BATCH_CHARS):
            batches.append(current); current=[]; current_chars=0
        current.append(row); current_chars+=estimate
    if current: batches.append(current)
    return batches


def _eda_receipt_path(module, run_id: str) -> Path:
    root=Path(module.MEMORY_DIR)/"audits"/"receipts"
    root.mkdir(parents=True,exist_ok=True)
    return root/f"semantic-data-cleanliness-{run_id}.json"


def _eda_atomic_write(path: Path,payload: dict) -> None:
    temp=path.with_suffix(path.suffix+".tmp")
    temp.write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    os.replace(temp,path)


def _eda_parse_command(module, raw: str) -> dict:
    tokens=" ".join(str(raw or "").strip().split()).split()
    opts={"suite":"quick","limit":0,"batch_items":_EDA_DEFAULT_BATCH_ITEMS,"provider":str(module.get_setting("active_provider","online") or "online").casefold(),"gpt_alias":None,"source_filter":None,"item_id":None,"print_progress":True}
    i=2
    while i<len(tokens):
        t=tokens[i].casefold()
        if t in {"--quick","quick"}: opts["suite"]="quick"
        elif t in {"--full","full"}: opts["suite"]="full"
        elif t=="--online": opts["provider"]="online"
        elif t in {"--local","--lmstudio"}: opts["provider"]="local"
        elif t=="--limit" and i+1<len(tokens): i+=1; opts["limit"]=max(1,int(tokens[i]))
        elif t=="--batch" and i+1<len(tokens): i+=1; opts["batch_items"]=max(1,min(16,int(tokens[i])))
        elif t=="--source" and i+1<len(tokens): i+=1; opts["source_filter"]=tokens[i]
        elif t=="--item" and i+1<len(tokens): i+=1; opts["item_id"]=tokens[i]
        elif t=="--gpt" and i+1<len(tokens): i+=1; opts["provider"]="online"; opts["gpt_alias"]=tokens[i].casefold()
        i+=1
    return opts


def _eda_run(module, *, suite: str="quick", limit: int=0, batch_items: int=_EDA_DEFAULT_BATCH_ITEMS, provider: str="online", gpt_alias: str|None=None, source_filter: str|None=None, item_id: str|None=None, print_progress: bool=True) -> dict:
    candidates=_eda_active_items(source_filter)
    selected=_eda_select(candidates,suite=suite,limit=limit,item_id=item_id)
    if item_id and not selected:
        raise ValueError(f"Active shared Knowledge Item not found: {item_id}")
    if not selected:
        raise ValueError("No active shared Knowledge Items available for audit.")
    backend,resolved_provider,resolved_alias=_ska_make_backend(module,provider=provider,gpt_alias=gpt_alias)
    batches=_eda_pack_batches(selected,batch_items)
    run_id=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S")+"Z-"+uuid.uuid4().hex[:10]
    started_at=_sk_now(); results=[]; batch_meta=[]; errors=[]; total_calls=0
    if print_progress:
        print(f"Semantic data cleanliness audit: {len(selected)} KIs | {len(batches)} model calls | {str(suite).upper()} | {resolved_provider}/{resolved_alias or getattr(backend,'model_id','')}",flush=True)
    for idx,batch in enumerate(batches,1):
        if print_progress: print(f"[{idx}/{len(batches)}] auditing {len(batch)} Knowledge Items...",flush=True)
        try:
            payload,meta=_eda_call_batch(module,backend,resolved_provider,batch); total_calls+=1; batch_meta.append(meta)
            judged,batch_errors=_eda_validate_batch(batch,payload); errors.extend([f"batch {idx}: {e}" for e in batch_errors])
            judged_by_id={str(x.get("item_id") or ""):x for x in judged}
            for source_row in batch:
                iid=str(source_row.get("item",{}).get("item_id") or "")
                judgment=judged_by_id.get(iid)
                if judgment is None:
                    results.append({
                        "item_id":iid,"status":"ERROR","text_cleanliness":"SUSPICIOUS","evidence_alignment":"UNCERTAIN","confidence":0.0,
                        "cleanliness_reason":"Model audit result missing or invalid.","alignment_reason":"No valid model judgment was returned for this item.",
                        "supporting_source_ordinals":[],"manual_review":True,
                        "source_id":str(source_row.get("item",{}).get("source_id") or ""),"source_key":str(source_row.get("item",{}).get("source_key") or ""),
                        "version_id":str(source_row.get("item",{}).get("version_id") or ""),
                        "deterministic_integrity":{"all_excerpt_hashes_match":source_row.get("all_excerpt_hashes_match"),"sources":source_row.get("integrity")},
                        "claim_evidence_overlap":source_row.get("claim_evidence_overlap"),
                    }); continue
                integrity_ok=bool(source_row.get("all_excerpt_hashes_match"))
                manual=bool(judgment.get("manual_review")) or not integrity_ok or str(judgment.get("evidence_alignment")) in {"MISMATCH","UNCERTAIN"} or str(judgment.get("text_cleanliness")) in {"SUSPICIOUS","CORRUPTED"}
                results.append({
                    **judgment,
                    "status":"REVIEW" if manual else "PASS",
                    "manual_review":manual,
                    "source_id":str(source_row.get("item",{}).get("source_id") or ""),
                    "source_key":str(source_row.get("item",{}).get("source_key") or ""),
                    "version_id":str(source_row.get("item",{}).get("version_id") or ""),
                    "claim_evidence_overlap":source_row.get("claim_evidence_overlap"),
                    "deterministic_integrity":{"all_excerpt_hashes_match":integrity_ok,"sources":source_row.get("integrity")},
                })
        except Exception as exc:
            errors.append(f"batch {idx}: {type(exc).__name__}: {exc}")
            for source_row in batch:
                iid=str(source_row.get("item",{}).get("item_id") or "")
                results.append({
                    "item_id":iid,"status":"ERROR","text_cleanliness":"SUSPICIOUS","evidence_alignment":"UNCERTAIN","confidence":0.0,
                    "cleanliness_reason":"Audit batch failed before a valid model judgment was recorded.",
                    "alignment_reason":f"{type(exc).__name__}: {exc}","supporting_source_ordinals":[],"manual_review":True,
                    "source_id":str(source_row.get("item",{}).get("source_id") or ""),"source_key":str(source_row.get("item",{}).get("source_key") or ""),
                    "version_id":str(source_row.get("item",{}).get("version_id") or ""),"claim_evidence_overlap":source_row.get("claim_evidence_overlap"),
                    "deterministic_integrity":{"all_excerpt_hashes_match":source_row.get("all_excerpt_hashes_match"),"sources":source_row.get("integrity")},
                })
    align_counts={k:sum(1 for r in results if r.get("evidence_alignment")==k) for k in sorted(_EDA_ALIGNMENT)}
    clean_counts={k:sum(1 for r in results if r.get("text_cleanliness")==k) for k in sorted(_EDA_CLEANLINESS)}
    integrity_failures=sum(1 for r in results if not bool((r.get("deterministic_integrity") or {}).get("all_excerpt_hashes_match")))
    manual_count=sum(1 for r in results if r.get("manual_review"))
    receipt={
        "audit":{
            "name":"semantic_data_cleanliness_and_evidence_alignment",
            "version":_SEMANTIC_DATA_AUDIT_VERSION,
            "bundle_version":BUNDLE_VERSION,
            "run_id":run_id,"started_at":started_at,"finished_at":_sk_now(),
            "suite":str(suite),"selection_policy":"quick=suspect-low-overlap + source-diverse deterministic sample; full=all active KIs",
            "provider":resolved_provider,"model_alias":resolved_alias,"model":str(getattr(backend,"model_id","") or ""),
            "model_calls":total_calls,"source_filter":source_filter,"item_filter":item_id,
        },
        "policy":{
            "read_only":True,"automatic_repair":False,"authoritative_writeback":False,"model_judgment_non_authoritative":True,
            "external_knowledge_allowed":False,"clean_at_boundary_preserve_trusted_runtime_data":True,
            "raw_source_text_duplicated_in_receipt":False,
        },
        "summary":{
            "selected_items":len(selected),"completed_results":len(results),"manual_review":manual_count,
            "alignment":align_counts,"text_cleanliness":clean_counts,"deterministic_excerpt_hash_failures":integrity_failures,
            "batch_errors":len(errors),
        },
        "results":results,"batch_metadata":batch_meta,"errors":errors,
    }
    receipt["receipt_validation"]={
        "status":"PASS" if len(results)==len(selected) and not errors else "WARN",
        "all_selected_items_accounted_for":len(results)==len(selected),
        "read_only":True,"automatic_repair":False,"authoritative_writeback":False,
    }
    path=_eda_receipt_path(module,run_id); _eda_atomic_write(path,receipt)
    if print_progress:
        print("Semantic data cleanliness audit completed",flush=True)
        print(f"Items: {len(results)} | manual review: {manual_count} | hash failures: {integrity_failures} | receipt: {receipt['receipt_validation']['status']}",flush=True)
        print("Evidence alignment: "+" | ".join(f"{k}={align_counts[k]}" for k in sorted(align_counts)),flush=True)
        print("Text cleanliness: "+" | ".join(f"{k}={clean_counts[k]}" for k in sorted(clean_counts)),flush=True)
        if manual_count:
            print("Review candidates:",flush=True)
            for r in [x for x in results if x.get("manual_review")][:20]:
                print(f"  {r.get('item_id')} | {r.get('evidence_alignment')} | {r.get('text_cleanliness')} | {str(r.get('alignment_reason') or '')[:180]}",flush=True)
        print(f"Saved receipt: {path}",flush=True)
    return {"ok":not errors,"path":str(path),"receipt":receipt}



def _eda_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    prefixes=("/audit evidence-alignment","/audit data-cleanliness","/audit semantic-cleanliness","/knowledge evidence-alignment")
    if not any(lower.startswith(p) for p in prefixes): return False
    try:
        opts=_eda_parse_command(module,clean)
        result=_eda_run(module,**opts); receipt=result.get("receipt") or {}
        compact={"ok":result.get("ok"),"path":result.get("path"),"audit":receipt.get("audit"),"summary":receipt.get("summary"),"policy":receipt.get("policy"),"receipt_validation":receipt.get("receipt_validation")}
        print(json.dumps(compact,ensure_ascii=False,indent=2))
    except Exception as exc:
        print(json.dumps({"ok":False,"error":f"{type(exc).__name__}: {exc}"},ensure_ascii=False,indent=2))
    return True


def _install_semantic_data_cleanliness_audit(module) -> None:
    if getattr(module,"_SEMANTIC_DATA_CLEANLINESS_AUDIT_INSTALLED",False): return
    module.SEMANTIC_DATA_CLEANLINESS_AUDIT_VERSION=_SEMANTIC_DATA_AUDIT_VERSION
    module.run_semantic_data_cleanliness_audit=lambda **kwargs:_eda_run(module,**kwargs)
    module.semantic_data_cleanliness_audit_self_test=lambda:semantic_data_cleanliness_audit_self_test(module)
    old_main=module.main
    def main_with_semantic_data_audit():
        previous=builtins.input
        def audit_input(prompt=""):
            while True:
                value=previous(prompt)
                if _eda_handle_command(module,value): continue
                return value
        builtins.input=audit_input
        try:return old_main()
        finally:builtins.input=previous
    module.main=main_with_semantic_data_audit
    old_help=module.print_help
    def help_with_semantic_data_audit(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /audit evidence-alignment [--quick|--full] [--limit N] [--item KI-ID] [--source SOURCE-ID] [--online|--lmstudio|--gpt luna]")
        print("      Read-only model audit: independent text cleanliness + KI-to-source evidence alignment; no automatic repair.")
    module.print_help=help_with_semantic_data_audit
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["semantic-data-cleanliness"]={"label":"Read-only model semantic data cleanliness and KI-to-source evidence-alignment audit contracts","groups":("quick","critical","all"),"runner":"memory.semantic_data_cleanliness_audit_self_test"}
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME; module._SEMANTIC_DATA_CLEANLINESS_AUDIT_INSTALLED=True



# ---------------------------------------------------------------------------
# Provenance Chain Fidelity Audit (7.4.37.11)
# Extends 7.4.37.10 without changing canonical memory or retrieval behavior.
# Verifies: claim -> stored excerpt -> canonical locator text -> citation locator.
# ---------------------------------------------------------------------------
_PROVENANCE_CHAIN_AUDIT_VERSION = "1.1-claim-excerpt-locator-chain"
_EDA_STORED_ALIGNMENT = {"ALIGNED", "PARTIAL", "MISMATCH", "UNCERTAIN"}
_EDA_LOCATOR_RELATION = {"EXACT", "STORED_WITHIN_CANONICAL", "CANONICAL_WITHIN_STORED", "MISMATCH", "UNVERIFIABLE"}
_EDA_REF_BINDING = {"MATCH", "MISMATCH", "UNVERIFIABLE"}


def _eda_text_relation(stored: str, canonical: str) -> str:
    stored = str(stored or "")
    canonical = str(canonical or "")
    if not stored or not canonical:
        return "UNVERIFIABLE"
    if stored == canonical:
        return "EXACT"
    if stored in canonical:
        return "STORED_WITHIN_CANONICAL"
    if canonical in stored:
        return "CANONICAL_WITHIN_STORED"
    return "MISMATCH"


def _eda_source_ref_parts(source_ref: str) -> tuple[str | None, str | None]:
    ref = str(source_ref or "").strip()
    # Canonical book refs produced by the shared-knowledge layer are normally
    # book:<BK-ID>:<chunk-id>. Be conservative: unknown formats are unverifiable.
    m = re.match(r"^book:([^:]+):(.+)$", ref, flags=re.I)
    if m:
        return m.group(1), m.group(2)
    return None, None


def _eda_canonical_locator_snapshot(src: dict) -> dict:
    locator = dict(src.get("locator") or {})
    stored = str(src.get("excerpt") or "")
    source_ref = str(src.get("source_ref") or "")
    kind = str(locator.get("kind") or "").casefold()
    book_id = str(locator.get("book_id") or "")
    chunk_id = str(locator.get("chunk_id") or "")
    canonical = ""
    error = None
    try:
        if book_id and chunk_id:
            rec = _dei_book_chunk_record(book_id, chunk_id)
            full = str(rec.get("text") or "")
            if kind == "book_span" or ("char_start" in locator and "char_end" in locator):
                start = max(0, int(locator.get("char_start") or 0))
                end = min(len(full), int(locator.get("char_end") or len(full)))
                canonical = full[start:end]
            else:
                canonical = full
        else:
            error = "canonical locator is not a verifiable book locator"
    except Exception as exc:
        error = f"{type(exc).__name__}: {exc}"

    relation = _eda_text_relation(stored, canonical)
    ref_book, ref_chunk = _eda_source_ref_parts(source_ref)
    if ref_book is None or not book_id or not chunk_id:
        ref_binding = "UNVERIFIABLE"
    else:
        ref_binding = "MATCH" if (ref_book == book_id and ref_chunk == chunk_id) else "MISMATCH"

    stored_sha = _sk_hash(stored) if stored else None
    canonical_sha = _sk_hash(canonical) if canonical else None
    evidence_sha = str(src.get("evidence_sha256") or "") or None
    excerpt_sha = str(src.get("excerpt_sha256") or "") or None
    return {
        "relation": relation,
        "source_ref_binding": ref_binding,
        "book_id": book_id or None,
        "chunk_id": chunk_id or None,
        "kind": kind or None,
        "stored_characters": len(stored),
        "canonical_characters": len(canonical),
        "stored_excerpt_sha256": stored_sha,
        "canonical_locator_sha256": canonical_sha,
        "stored_excerpt_hash_matches_record": bool(excerpt_sha and stored_sha == excerpt_sha),
        "evidence_sha256_matches_canonical": bool(evidence_sha and canonical_sha and evidence_sha == canonical_sha),
        "error": error,
        # Used only in the model prompt; stripped from receipt enrichment below.
        "_canonical_text": canonical,
    }


_eda_active_items_v10 = _eda_active_items

def _eda_active_items(source_filter: str | None = None) -> list[dict]:
    rows = _eda_active_items_v10(source_filter)
    for row in rows:
        fidelity = []
        for src in row.get("sources") or []:
            snap = _eda_canonical_locator_snapshot(src)
            fidelity.append(snap)
        row["locator_fidelity"] = fidelity
        relations = [str(x.get("relation") or "UNVERIFIABLE") for x in fidelity]
        bindings = [str(x.get("source_ref_binding") or "UNVERIFIABLE") for x in fidelity]
        if any(x == "MISMATCH" for x in relations) or any(x == "MISMATCH" for x in bindings):
            overall = "MISMATCH"
        elif relations and all(x in {"EXACT", "STORED_WITHIN_CANONICAL", "CANONICAL_WITHIN_STORED"} for x in relations) and all(x in {"MATCH", "UNVERIFIABLE"} for x in bindings):
            overall = "VERIFIED"
        else:
            overall = "UNVERIFIABLE"
        row["provenance_chain_status"] = overall
    return rows


def _eda_model_schema() -> dict:
    result_props = {
        "item_id": {"type":"string"},
        "text_cleanliness": {"type":"string","enum":sorted(_EDA_CLEANLINESS)},
        "stored_excerpt_alignment": {"type":"string","enum":sorted(_EDA_STORED_ALIGNMENT)},
        "evidence_alignment": {"type":"string","enum":sorted(_EDA_ALIGNMENT)},
        "confidence": {"type":"number","minimum":0.0,"maximum":1.0},
        "cleanliness_reason": {"type":"string"},
        "stored_alignment_reason": {"type":"string"},
        "alignment_reason": {"type":"string"},
        "supporting_source_ordinals": {"type":"array","items":{"type":"integer"}},
        "manual_review": {"type":"boolean"},
    }
    return {
        "type":"object",
        "properties":{"results":{"type":"array","items":{"type":"object","properties":result_props,"required":list(result_props.keys()),"additionalProperties":False}}},
        "required":["results"],"additionalProperties":False,
    }


def _eda_prompt_items(batch: list[dict]) -> list[dict]:
    payload=[]
    for row in batch:
        item=row["item"]
        sources=[]
        fidelities=list(row.get("locator_fidelity") or [])
        for idx,src in enumerate(row.get("sources") or []):
            fidelity=fidelities[idx] if idx < len(fidelities) else _eda_canonical_locator_snapshot(src)
            sources.append({
                "ordinal":int(src.get("ordinal") or 0),
                "source_ref":str(src.get("source_ref") or ""),
                "locator":dict(src.get("locator") or {}),
                "stored_excerpt":str(src.get("excerpt") or ""),
                "canonical_locator_text":str(fidelity.get("_canonical_text") or ""),
                "deterministic_locator_relation":str(fidelity.get("relation") or "UNVERIFIABLE"),
                "source_ref_binding":str(fidelity.get("source_ref_binding") or "UNVERIFIABLE"),
            })
        payload.append({
            "item_id":str(item.get("item_id") or ""),
            "kind":str(item.get("kind") or ""),
            "interpretation":str(item.get("interpretation") or ""),
            "claim":str(item.get("claim") or ""),
            "details":str(item.get("details") or ""),
            "provenance_chain_status":str(row.get("provenance_chain_status") or "UNVERIFIABLE"),
            "sources":sources,
        })
    return payload


def _eda_call_batch(module, backend, provider: str, batch: list[dict]) -> tuple[dict,dict]:
    system = (
        "You are NeatMemory's read-only provenance-chain auditor. COGNITIVE AUTONOMY: choose your own internal reasoning depth; no API effort level is prescribed. Use ONLY the supplied fields; do not use outside knowledge and do not repair memory. "
        "For each Knowledge Item, judge three distinct things. "
        "TEXT CLEANLINESS: judge whether the supplied source text is coherent/usable versus noisy, suspicious, or corrupted. "
        "STORED EXCERPT ALIGNMENT: compare the KI claim/details ONLY to stored_excerpt. This answers whether the stored KI evidence text supports the claim. "
        "CANONICAL EVIDENCE ALIGNMENT (return this as evidence_alignment): when canonical_locator_text is non-empty, compare the KI claim/details to canonical_locator_text, not merely to stored_excerpt. If canonical_locator_text is empty, use UNCERTAIN unless another canonical source for the same item is available. "
        "A clean stored excerpt can be ALIGNED while canonical evidence is MISMATCH if the excerpt was attached to the wrong locator/chunk. "
        "Treat deterministic_locator_relation=MISMATCH or source_ref_binding=MISMATCH as mandatory manual review; do not explain it away. "
        "Labels: ALIGNED=material support; PARTIAL=material part unsupported; MISMATCH=different event/topic/person or conflict; UNCERTAIN=insufficient canonical evidence. "
        "Cleanliness labels: CLEAN, MINOR_NOISE, SUSPICIOUS, CORRUPTED. Archaic spelling/punctuation is not noise by itself. "
        "supporting_source_ordinals may contain only supplied ordinals. manual_review must be true for any MISMATCH/UNCERTAIN/SUSPICIOUS/CORRUPTED or deterministic provenance mismatch. Return every item_id exactly once."
    )
    user=json.dumps({"knowledge_items":_eda_prompt_items(batch)},ensure_ascii=False)
    schema=_eda_model_schema(); started=time.perf_counter()
    meta={"provider":provider,"model":str(getattr(backend,"model_id","") or ""),"input_characters":len(user),"provenance_chain_audit_version":_PROVENANCE_CHAIN_AUDIT_VERSION}
    if str(provider).casefold()=="online":
        safe_schema=_sk_validate_openai_strict_schema(schema,schema_name="neatmemory_provenance_chain_audit_v11")
        response=backend.client.responses.create(
            model=backend.model_id,
            input=[{"role":"system","content":system},{"role":"user","content":user}],
            max_output_tokens=12000,store=False,
            text={"format":{"type":"json_schema","name":"neatmemory_provenance_chain_audit_v11","strict":True,"schema":safe_schema}},
        )
        text=str(getattr(response,"output_text","") or ""); usage=getattr(response,"usage",None)
        meta.update({"request_id":getattr(response,"id",None),"provider_input_tokens":getattr(usage,"input_tokens",None) if usage is not None else None,"provider_output_tokens":getattr(usage,"output_tokens",None) if usage is not None else None})
        payload=_eda_parse_json_text(text)
    else:
        response=backend.client.chat.completions.create(model=backend.model_id,messages=[{"role":"system","content":system+" Return JSON only."},{"role":"user","content":user}],temperature=0.0,max_tokens=12000)
        message=response.choices[0].message; text=str(message.content or "")
        payload=_eda_parse_json_text(text); usage=getattr(response,"usage",None)
        meta.update({"request_id":getattr(response,"id",None),"provider_input_tokens":getattr(usage,"prompt_tokens",None) if usage is not None else None,"provider_output_tokens":getattr(usage,"completion_tokens",None) if usage is not None else None})
    meta["elapsed_seconds"]=round(time.perf_counter()-started,3)
    return payload,meta


_eda_validate_batch_v10 = _eda_validate_batch

def _eda_validate_batch(batch: list[dict], payload: dict) -> tuple[list[dict],list[str]]:
    valid,errors=_eda_validate_batch_v10(batch,payload)
    by_id={str(x.get("item",{}).get("item_id") or ""):x for x in batch}
    for judgment in valid:
        iid=str(judgment.get("item_id") or ""); source_row=by_id.get(iid) or {}
        fidelity=[]
        for snap in source_row.get("locator_fidelity") or []:
            fidelity.append({k:v for k,v in snap.items() if k != "_canonical_text"})
        chain_status=str(source_row.get("provenance_chain_status") or "UNVERIFIABLE")
        judgment["deterministic_provenance_chain"]={"status":chain_status,"sources":fidelity}
        if chain_status == "MISMATCH":
            judgment["manual_review"] = True
    return valid,errors


_eda_run_v10 = _eda_run

def _eda_run(module, **kwargs) -> dict:
    result=_eda_run_v10(module,**kwargs)
    receipt=result.get("receipt") or {}
    rows=list(receipt.get("results") or [])
    chain_counts={"VERIFIED":0,"MISMATCH":0,"UNVERIFIABLE":0}
    stored_counts={k:0 for k in sorted(_EDA_STORED_ALIGNMENT)}
    for row in rows:
        status=str((row.get("deterministic_provenance_chain") or {}).get("status") or "UNVERIFIABLE")
        chain_counts[status]=chain_counts.get(status,0)+1
        sa=str(row.get("stored_excerpt_alignment") or "")
        if sa in stored_counts: stored_counts[sa]+=1
    receipt.setdefault("audit",{})["version"]=_PROVENANCE_CHAIN_AUDIT_VERSION
    receipt.setdefault("summary",{})["deterministic_provenance_chain"]=chain_counts
    receipt["summary"]["stored_excerpt_alignment"]=stored_counts
    receipt.setdefault("policy",{})["provenance_chain_checked"]="claim -> stored excerpt -> canonical locator text -> source_ref binding"
    path=Path(str(result.get("path") or "")) if result.get("path") else None
    if path:
        _eda_atomic_write(path,receipt)
    if kwargs.get("print_progress",True):
        print("Provenance chain: "+" | ".join(f"{k}={chain_counts.get(k,0)}" for k in ("VERIFIED","MISMATCH","UNVERIFIABLE")),flush=True)
        print("Stored excerpt alignment: "+" | ".join(f"{k}={stored_counts.get(k,0)}" for k in sorted(stored_counts)),flush=True)
        for row in rows:
            chain=(row.get("deterministic_provenance_chain") or {})
            if chain.get("status") == "MISMATCH":
                print(f"  PROVENANCE MISMATCH {row.get('item_id')} | stored={row.get('stored_excerpt_alignment')} | canonical={row.get('evidence_alignment')}",flush=True)
    result["receipt"]=receipt
    return result



# ---------------------------------------------------------------------------
# Source-Chunk Audit Coverage + Strict Stored-Evidence Review (7.4.37.12)
# Extends 7.4.37.11.  No canonical memory or retrieval behavior changes.
# Adds deterministic reconstruction for unified source-chunk and archived
# research locators, and treats any non-ALIGNED stored excerpt as reviewable.
# ---------------------------------------------------------------------------
_PROVENANCE_CHAIN_AUDIT_VERSION = "1.2-source-chunk-research-coverage-strict-stored-review"

_eda_canonical_locator_snapshot_v11 = _eda_canonical_locator_snapshot
_eda_validate_batch_v11 = _eda_validate_batch
_eda_run_v11 = _eda_run


def _eda_memory_module():
    return sys.modules.get("neatmemory_v7_0_stable")


def _eda_normalize_ref(value: str) -> str:
    raw = str(value or "").strip()
    return raw[4:] if raw.casefold().startswith("web:") else raw


def _eda_canonical_locator_snapshot(src: dict) -> dict:
    locator = dict(src.get("locator") or {})
    stored = str(src.get("excerpt") or "")
    source_ref = str(src.get("source_ref") or "")
    kind = str(locator.get("kind") or "").casefold()
    memory_module = _eda_memory_module()
    canonical = ""
    error = None
    binding = "UNVERIFIABLE"
    resolver = "unknown"

    # 1) Modern unified raw-source authority.  Current research digestion stores
    # source_ref=source-chunk:<id> and locator fields containing the same chunk id.
    chunk_id = str(locator.get("source_chunk_id") or locator.get("raw_source_chunk_id") or "").strip()
    if not chunk_id and source_ref.casefold().startswith("source-chunk:"):
        chunk_id = source_ref.split(":", 1)[1].strip()
    if chunk_id and memory_module is not None:
        try:
            row = _rsc_chunk(memory_module, chunk_id, include_text=True)
            if row:
                canonical = str(row.get("text") or "")
                resolver = "unified_source_chunk"
                expected = f"source-chunk:{chunk_id}"
                binding = "MATCH" if source_ref == expected else ("UNVERIFIABLE" if not source_ref else "MISMATCH")
            else:
                error = f"canonical source chunk not found: {chunk_id}"
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"

    # 2) Book locators: preserve the proven 7.4.37.11 behavior.
    if not canonical and (locator.get("book_id") and locator.get("chunk_id")):
        snap = _eda_canonical_locator_snapshot_v11(src)
        snap["resolver"] = "book_chunk"
        return snap

    # 3) Archived research/full-page locators. Older stored research sources may
    # have snapshot_id/page_id but no explicit kind tag. Treat those as canonical
    # archive locators too.
    if not canonical and (kind == "research_span" or locator.get("snapshot_id") or locator.get("page_id")) and memory_module is not None:
        reference = str(locator.get("snapshot_id") or locator.get("page_id") or locator.get("source_ref") or source_ref or "").strip()
        if reference.casefold().startswith("web:"):
            reference = reference[4:]
        try:
            if reference:
                got = _research_read_full_text(memory_module, reference)
                if got.get("ok"):
                    full = str(got.get("text") or "")
                    start_raw = locator.get("char_start") if locator.get("char_start") is not None else locator.get("chunk_start")
                    end_raw = locator.get("char_end") if locator.get("char_end") is not None else locator.get("chunk_end")
                    start = max(0, int(start_raw or 0))
                    end = min(len(full), int(end_raw if end_raw is not None else len(full)))
                    canonical = full[start:end]
                    resolver = "research_archive_span" if (start or end < len(full)) else "research_archive_full_page"
                    loc_ref = str(locator.get("source_ref") or "").strip()
                    if loc_ref and source_ref:
                        binding = "MATCH" if _eda_normalize_ref(loc_ref) == _eda_normalize_ref(source_ref) else "MISMATCH"
                else:
                    error = str(got.get("error") or "research archive source unavailable")
            else:
                error = "research_span has no snapshot/page/source reference"
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"

    # 4) Archived search-result snippets. Older research KIs can legitimately
    # cite a search snippet when the full page was unavailable.
    if not canonical and locator.get("search_result_id") and memory_module is not None:
        search_id = str(locator.get("search_result_id") or "").strip()
        try:
            with _research_archive_connect(memory_module) as db:
                row = db.execute("SELECT search_result_id,url,canonical_url,snippet FROM research_search_results WHERE search_result_id=?", (search_id,)).fetchone()
            if row:
                row = dict(row)
                canonical = str(row.get("snippet") or "")
                resolver = "research_search_snippet"
                ref_url = _eda_normalize_ref(source_ref).split("#archive-chunk-",1)[0]
                canonical_url = str(row.get("canonical_url") or row.get("url") or "")
                binding = "MATCH" if (not ref_url or not canonical_url or ref_url == canonical_url) else "MISMATCH"
            else:
                error = f"research search result not found: {search_id}"
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"

    # 5) Older direct locators used by chat/text-file digestion.
    if not canonical and kind in {"sqlite_chat", "text_file", "book_chunk", "book_span"} and memory_module is not None:
        try:
            got = _dei_locator_text(memory_module, locator)
            canonical = str(got.get("text") or "")
            resolver = f"digest_locator:{kind}"
            error = got.get("error")
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"

    relation = _eda_text_relation(stored, canonical)
    stored_sha = _sk_hash(stored) if stored else None
    canonical_sha = _sk_hash(canonical) if canonical else None
    evidence_sha = str(src.get("evidence_sha256") or "") or None
    excerpt_sha = str(src.get("excerpt_sha256") or "") or None
    return {
        "relation": relation,
        "source_ref_binding": binding,
        "book_id": str(locator.get("book_id") or "") or None,
        "chunk_id": str(locator.get("chunk_id") or chunk_id or "") or None,
        "kind": kind or ("source_chunk" if chunk_id else None),
        "resolver": resolver,
        "stored_characters": len(stored),
        "canonical_characters": len(canonical),
        "stored_excerpt_sha256": stored_sha,
        "canonical_locator_sha256": canonical_sha,
        "stored_excerpt_hash_matches_record": bool(excerpt_sha and stored_sha == excerpt_sha),
        "evidence_sha256_matches_canonical": bool(evidence_sha and canonical_sha and evidence_sha == canonical_sha),
        "error": error,
        "_canonical_text": canonical,
    }


def _eda_validate_batch(batch: list[dict], payload: dict) -> tuple[list[dict], list[str]]:
    valid, errors = _eda_validate_batch_v11(batch, payload)
    # For a cleanliness audit, a KI whose own attached excerpt is anything less
    # than ALIGNED must be surfaced.  Wider canonical evidence cannot hide a bad
    # per-item excerpt binding.
    for judgment in valid:
        stored = str(judgment.get("stored_excerpt_alignment") or "UNCERTAIN")
        if stored in {"MISMATCH", "PARTIAL", "UNCERTAIN"}:
            judgment["manual_review"] = True
    return valid, errors


def _eda_run(module, **kwargs) -> dict:
    result = _eda_run_v11(module, **kwargs)
    receipt = result.get("receipt") or {}
    rows = list(receipt.get("results") or [])

    stored_review = [r for r in rows if str(r.get("stored_excerpt_alignment") or "") in {"MISMATCH", "PARTIAL", "UNCERTAIN"}]
    minor_noise = [r for r in rows if str(r.get("text_cleanliness") or "") == "MINOR_NOISE"]
    kind_counts = {}
    resolver_counts = {}
    unresolved_reasons = {}
    for row in rows:
        for snap in ((row.get("deterministic_provenance_chain") or {}).get("sources") or []):
            kind = str(snap.get("kind") or "unknown")
            resolver = str(snap.get("resolver") or "unknown")
            kind_counts[kind] = kind_counts.get(kind, 0) + 1
            resolver_counts[resolver] = resolver_counts.get(resolver, 0) + 1
            if str(snap.get("relation") or "") == "UNVERIFIABLE":
                reason = str(snap.get("error") or f"unresolved:{kind}")[:300]
                unresolved_reasons[reason] = unresolved_reasons.get(reason, 0) + 1

    summary = receipt.setdefault("summary", {})
    summary["stored_excerpt_review_candidates"] = len(stored_review)
    summary["minor_noise_items"] = len(minor_noise)
    summary["locator_kind_counts"] = kind_counts
    summary["canonical_resolver_counts"] = resolver_counts
    summary["unverifiable_locator_reasons"] = unresolved_reasons
    receipt.setdefault("audit", {})["version"] = _PROVENANCE_CHAIN_AUDIT_VERSION
    receipt.setdefault("policy", {})["stored_excerpt_non_aligned_requires_review"] = True
    receipt["policy"]["canonical_locator_coverage"] = "book + unified source-chunk + archived full-page/span + archived search snippet + legacy chat/text-file"

    # Recompute manual review after strict stored-excerpt policy so the receipt's
    # summary cannot retain the older permissive count.
    for row in rows:
        if str(row.get("stored_excerpt_alignment") or "") in {"MISMATCH", "PARTIAL", "UNCERTAIN"}:
            row["manual_review"] = True
            row["status"] = "REVIEW"
    summary["manual_review"] = sum(1 for r in rows if r.get("manual_review"))

    path = Path(str(result.get("path") or "")) if result.get("path") else None
    if path:
        _eda_atomic_write(path, receipt)

    if kwargs.get("print_progress", True):
        if stored_review:
            print("Stored-evidence review candidates:", flush=True)
            for row in stored_review[:30]:
                print(
                    f"  {row.get('item_id')} | stored={row.get('stored_excerpt_alignment')} | canonical={row.get('evidence_alignment')} | "
                    f"{str(row.get('stored_alignment_reason') or '')[:180]}",
                    flush=True,
                )
        if minor_noise:
            print("Minor-noise items (diagnostic, not corruption):", flush=True)
            for row in minor_noise[:20]:
                print(f"  {row.get('item_id')} | {str(row.get('cleanliness_reason') or '')[:180]}", flush=True)
        if unresolved_reasons:
            print("Unverifiable locator reasons:", flush=True)
            for reason, count in sorted(unresolved_reasons.items(), key=lambda kv: (-kv[1], kv[0])):
                print(f"  {count}x | {reason}", flush=True)

    result["receipt"] = receipt
    return result


def semantic_data_cleanliness_audit_self_test(module) -> dict:
    base = {}
    # Direct resolver primitives, no live model calls.
    base["source_chunk_ref_normalization"] = _eda_normalize_ref("web:https://example.test/a") == "https://example.test/a"
    synthetic = {
        "item": {"item_id": "KI-X"},
        "sources": [{"ordinal": 1}],
        "locator_fidelity": [{"relation": "EXACT", "source_ref_binding": "MATCH", "resolver": "unified_source_chunk", "_canonical_text": "same"}],
        "provenance_chain_status": "VERIFIED",
    }
    payload = {"results": [{
        "item_id": "KI-X", "text_cleanliness": "CLEAN", "stored_excerpt_alignment": "MISMATCH",
        "evidence_alignment": "ALIGNED", "confidence": 0.9, "cleanliness_reason": "clean",
        "stored_alignment_reason": "attached excerpt does not support claim", "alignment_reason": "wider canonical chunk supports claim",
        "supporting_source_ordinals": [1], "manual_review": False,
    }]}
    valid, errs = _eda_validate_batch([synthetic], payload)
    base["stored_mismatch_forces_review_even_when_canonical_aligned"] = len(valid) == 1 and not errs and valid[0].get("manual_review") is True
    base["read_only_no_repair"] = True
    base["self_test_model_calls_zero"] = True
    return {
        "ok": all(bool(v) for v in base.values()),
        "checks": base,
        "version": _PROVENANCE_CHAIN_AUDIT_VERSION,
        "model_calls": 0,
        "authoritative_writeback": False,
        "automatic_repair": False,
    }


# ---------------------------------------------------------------------------
# NeatMemory 7.4.37.13 — Batch Integrity Maintenance
# Read-only batch workflow: audit -> independent repair proposals -> batch
# validation.  No canonical memory mutation occurs in this release.
# ---------------------------------------------------------------------------
_BATCH_INTEGRITY_MAINTENANCE_VERSION = "1.1-read-only-propose-validate-archive-and-resolver-coverage"
_BIM_ACTIONS = {"KEEP", "CORRECT", "ARCHIVE", "UNCERTAIN"}


def _bim_schema() -> dict:
    props = {
        "item_id": {"type":"string"},
        "action": {"type":"string", "enum":sorted(_BIM_ACTIONS)},
        "proposed_claim": {"type":"string"},
        "proposed_details": {"type":"string"},
        "confidence": {"type":"number", "minimum":0.0, "maximum":1.0},
        "reason": {"type":"string"},
        "supporting_source_ordinals": {"type":"array", "items":{"type":"integer"}},
    }
    return {"type":"object","properties":{"repairs":{"type":"array","items":{"type":"object","properties":props,"required":list(props),"additionalProperties":False}}},"required":["repairs"],"additionalProperties":False}


def _bim_validation_schema() -> dict:
    props = {
        "item_id": {"type":"string"},
        "alignment": {"type":"string", "enum":sorted(_EDA_ALIGNMENT)},
        "confidence": {"type":"number", "minimum":0.0, "maximum":1.0},
        "reason": {"type":"string"},
    }
    return {"type":"object","properties":{"results":{"type":"array","items":{"type":"object","properties":props,"required":list(props),"additionalProperties":False}}},"required":["results"],"additionalProperties":False}


def _bim_candidate_payload(row: dict, audit_result: dict) -> dict:
    sources=[]
    for idx,src in enumerate(row.get("sources") or []):
        snaps=list(row.get("locator_fidelity") or [])
        snap=snaps[idx] if idx < len(snaps) else _eda_canonical_locator_snapshot(src)
        sources.append({
            "ordinal":int(src.get("ordinal") or 0),
            "source_ref":str(src.get("source_ref") or ""),
            "canonical_locator_text":str(snap.get("_canonical_text") or ""),
            "resolver":str(snap.get("resolver") or "unknown"),
            "locator_relation":str(snap.get("relation") or "UNVERIFIABLE"),
            "source_ref_binding":str(snap.get("source_ref_binding") or "UNVERIFIABLE"),
        })
    item=row.get("item") or {}
    return {
        "item_id":str(item.get("item_id") or ""),
        "kind":str(item.get("kind") or "fact"),
        "claim":str(item.get("claim") or ""),
        "details":str(item.get("details") or ""),
        "interpretation":str(item.get("interpretation") or ""),
        "domain":str(item.get("domain") or ""),
        "audit":{
            "text_cleanliness":str(audit_result.get("text_cleanliness") or ""),
            "stored_excerpt_alignment":str(audit_result.get("stored_excerpt_alignment") or ""),
            "canonical_alignment":str(audit_result.get("evidence_alignment") or ""),
            "stored_reason":str(audit_result.get("stored_alignment_reason") or ""),
            "canonical_reason":str(audit_result.get("alignment_reason") or ""),
            "provenance_chain_status":str(row.get("provenance_chain_status") or "UNVERIFIABLE"),
        },
        "sources":sources,
    }


def _bim_parse_json(text: str) -> dict:
    return _eda_parse_json_text(text)


def _bim_model_call(module, backend, provider: str, system: str, payload: dict, schema: dict, schema_name: str, max_tokens: int=12000) -> tuple[dict,dict]:
    user=json.dumps(payload,ensure_ascii=False)
    system=str(system).rstrip()+"\n\nCOGNITIVE AUTONOMY: Choose your own internal reasoning depth; NeatMemory does not prescribe an API effort level."
    started=time.perf_counter()
    meta={"provider":provider,"model":str(getattr(backend,"model_id","") or ""),"input_characters":len(user)}
    if str(provider).casefold()=="online":
        safe_schema=_sk_validate_openai_strict_schema(schema,schema_name=schema_name)
        response=backend.client.responses.create(
            model=backend.model_id,
            input=[{"role":"system","content":system},{"role":"user","content":user}],
            max_output_tokens=max_tokens,store=False,
            text={"format":{"type":"json_schema","name":schema_name,"strict":True,"schema":safe_schema}},
        )
        body=str(getattr(response,"output_text","") or "")
        usage=getattr(response,"usage",None)
        meta.update({"request_id":getattr(response,"id",None),"provider_input_tokens":getattr(usage,"input_tokens",None) if usage is not None else None,"provider_output_tokens":getattr(usage,"output_tokens",None) if usage is not None else None})
    else:
        response=backend.client.chat.completions.create(model=backend.model_id,messages=[{"role":"system","content":system+" Return JSON only."},{"role":"user","content":user}],temperature=0.0,max_tokens=max_tokens)
        message=response.choices[0].message
        body=str(message.content or "")
        usage=getattr(response,"usage",None)
        meta.update({"request_id":getattr(response,"id",None),"provider_input_tokens":getattr(usage,"prompt_tokens",None) if usage is not None else None,"provider_output_tokens":getattr(usage,"completion_tokens",None) if usage is not None else None})
    meta["elapsed_seconds"]=round(time.perf_counter()-started,3)
    return _bim_parse_json(body),meta


def _bim_validate_proposals(candidates: list[dict], payload: dict) -> tuple[list[dict],list[str]]:
    expected={str(x.get("item_id") or ""):x for x in candidates}
    rows=list(payload.get("repairs") or []) if isinstance(payload,dict) else []
    out=[]; errors=[]; seen=set()
    for row in rows:
        if not isinstance(row,dict): errors.append("non-object repair row"); continue
        iid=str(row.get("item_id") or "")
        if iid not in expected: errors.append(f"unexpected item_id: {iid}"); continue
        if iid in seen: errors.append(f"duplicate item_id: {iid}"); continue
        seen.add(iid)
        action=str(row.get("action") or "")
        if action not in _BIM_ACTIONS: errors.append(f"{iid}: invalid action {action}"); continue
        claim=" ".join(str(row.get("proposed_claim") or "").split()).strip()
        details=str(row.get("proposed_details") or "").strip()
        if action=="CORRECT" and len(claim)<8:
            errors.append(f"{iid}: CORRECT requires a substantive proposed_claim"); continue
        allowed={int(s.get("ordinal") or 0) for s in expected[iid].get("sources") or []}
        supplied=[]
        for value in row.get("supporting_source_ordinals") or []:
            try: supplied.append(int(value))
            except Exception: errors.append(f"{iid}: invalid source ordinal"); supplied=[]; break
        if any(x not in allowed for x in supplied): errors.append(f"{iid}: unbound source ordinal"); continue
        try: confidence=float(row.get("confidence") or 0.0)
        except Exception: confidence=0.0
        out.append({**row,"item_id":iid,"action":action,"proposed_claim":claim,"proposed_details":details,"confidence":max(0.0,min(1.0,confidence)),"supporting_source_ordinals":supplied})
    missing=sorted(set(expected)-seen)
    if missing: errors.append("missing item_ids: "+", ".join(missing))
    return out,errors


def _bim_validate_checks(proposals: list[dict], payload: dict) -> tuple[dict,list[str]]:
    expected={str(x.get("item_id") or "") for x in proposals if str(x.get("action") or "") in {"CORRECT","ARCHIVE"}}
    rows=list(payload.get("results") or []) if isinstance(payload,dict) else []
    out={}; errors=[]
    for row in rows:
        if not isinstance(row,dict): errors.append("non-object validation row"); continue
        iid=str(row.get("item_id") or "")
        if iid not in expected: errors.append(f"unexpected validation item_id: {iid}"); continue
        if iid in out: errors.append(f"duplicate validation item_id: {iid}"); continue
        label=str(row.get("alignment") or "")
        if label not in _EDA_ALIGNMENT: errors.append(f"{iid}: invalid alignment {label}"); continue
        try: confidence=float(row.get("confidence") or 0.0)
        except Exception: confidence=0.0
        out[iid]={**row,"item_id":iid,"alignment":label,"confidence":max(0.0,min(1.0,confidence))}
    missing=sorted(expected-set(out))
    if missing: errors.append("missing validation item_ids: "+", ".join(missing))
    return out,errors


def _bim_receipt_path(module, run_id: str) -> Path:
    base=Path(getattr(module, "MEMORY_DIR", Path.cwd() / "neat_memory")) / "audits" / "receipts"
    base.mkdir(parents=True,exist_ok=True)
    return base / f"batch-integrity-maintenance-{run_id}.json"



def _bim_parse_command(module, raw: str) -> dict:
    tokens=" ".join(str(raw or "").strip().split()).split()
    opts={"provider":str(module.get_setting("active_provider","online") or "online").casefold(),"gpt_alias":None,"limit":24,"print_progress":True}
    i=2
    while i<len(tokens):
        t=tokens[i].casefold()
        if t=="--online": opts["provider"]="online"
        elif t in {"--local","--lmstudio"}: opts["provider"]="local"
        elif t=="--gpt" and i+1<len(tokens): i+=1; opts["provider"]="online"; opts["gpt_alias"]=tokens[i].casefold()
        elif t=="--limit" and i+1<len(tokens): i+=1; opts["limit"]=max(1,min(200,int(tokens[i])))
        i+=1
    return opts


def _bim_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    if not (lower.startswith("/maintenance batch") or lower.startswith("/repair batch")):
        return False
    try:
        result=_bim_run(module,**_bim_parse_command(module,clean))
        print(json.dumps(result,ensure_ascii=False,indent=2))
    except Exception as exc:
        print(json.dumps({"ok":False,"error":f"{type(exc).__name__}: {exc}"},ensure_ascii=False,indent=2))
    return True


def _install_batch_integrity_maintenance(module) -> None:
    if getattr(module,"_BATCH_INTEGRITY_MAINTENANCE_INSTALLED",False): return
    module.BATCH_INTEGRITY_MAINTENANCE_VERSION=_BATCH_INTEGRITY_MAINTENANCE_VERSION
    module.run_batch_integrity_maintenance=lambda **kwargs:_bim_run(module,**kwargs)
    module.batch_integrity_maintenance_self_test=lambda:batch_integrity_maintenance_self_test(module)
    old_main=module.main
    def main_with_batch_maintenance():
        previous=builtins.input
        def batch_input(prompt=""):
            while True:
                value=previous(prompt)
                if _bim_handle_command(module,value): continue
                return value
        builtins.input=batch_input
        try:return old_main()
        finally:builtins.input=previous
    module.main=main_with_batch_maintenance
    old_help=module.print_help
    def help_with_batch_maintenance(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /maintenance batch [--online|--lmstudio] [--limit N]")
        print("      Batch audit + evidence-grounded repair proposals + independent batch validation; read-only.")
    module.print_help=help_with_batch_maintenance
    specs=globals().get("_SELF_TEST_SPECS")
    if isinstance(specs,dict):
        specs["batch-integrity-maintenance"]={"label":"Read-only batch audit, repair proposal, and independent repair validation contracts","groups":("quick","critical","all"),"runner":"memory.batch_integrity_maintenance_self_test"}
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME; module._BATCH_INTEGRITY_MAINTENANCE_INSTALLED=True

# ---------------------------------------------------------------------------
# NeatMemory 7.4.37.16 — Safe Batch Apply + Post-Apply Verification
# Applies ONLY actions previously marked safe_to_apply by the read-only batch
# maintenance receipt. Existing shared KIs remain immutable: unsupported KIs
# are quarantined via temporal sidecar status, while corrections create a new
# evidence-bound KI and an append-only supersession relation.
# ---------------------------------------------------------------------------
_BATCH_SAFE_APPLY_VERSION = "1.2-live-excerpt-hash-preflight-compatible"
_BSA_LEDGER_SCHEMA = "1.0"


def _bsa_memory_dir(module) -> Path:
    getter = getattr(module, "get_memory_dir", None)
    if callable(getter):
        try:
            return Path(getter())
        except Exception:
            pass
    value = getattr(module, "MEMORY_DIR", None)
    if value:
        return Path(value)
    return Path.cwd() / "neat_memory"


def _bsa_receipts_dir(module) -> Path:
    path = _bsa_memory_dir(module) / "audits" / "receipts"
    path.mkdir(parents=True, exist_ok=True)
    return path



def _bsa_load_json(path: Path) -> dict:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError(f"Receipt is not a JSON object: {path}")
    return payload


def _bsa_receipt_sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _bsa_ensure_ledger(db) -> None:
    db.executescript("""
    CREATE TABLE IF NOT EXISTS knowledge_maintenance_actions(
        action_id TEXT PRIMARY KEY,
        source_receipt_sha256 TEXT NOT NULL,
        item_id TEXT NOT NULL,
        action TEXT NOT NULL,
        new_item_id TEXT,
        applied_at TEXT NOT NULL,
        actor TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        payload_sha256 TEXT NOT NULL,
        UNIQUE(source_receipt_sha256,item_id,action)
    );
    CREATE INDEX IF NOT EXISTS idx_knowledge_maintenance_actions_item
        ON knowledge_maintenance_actions(item_id,applied_at);
    """)


def _bsa_live_item(item_id: str) -> dict | None:
    for row in _eda_active_items():
        if str((row.get("item") or {}).get("item_id") or "") == str(item_id):
            return row
    return None


def _bsa_safe_rows(receipt: dict) -> list[dict]:
    rows=[]
    for raw in receipt.get("decisions") or []:
        if not isinstance(raw,dict) or not raw.get("safe_to_apply"):
            continue
        action=str(raw.get("action") or "").upper()
        if action not in {"ARCHIVE","CORRECT"}:
            continue
        rows.append(dict(raw))
    return rows


def _bsa_receipt_successful(receipt: dict) -> bool:
    # Console return objects include ok=true, but the canonical saved
    # batch-integrity-maintenance receipt intentionally stores the inner
    # result and therefore has no top-level ok field. Accept either schema,
    # while still rejecting explicit ok=false or any saved receipt with errors.
    if not isinstance(receipt, dict):
        return False
    if "ok" in receipt:
        return bool(receipt.get("ok"))
    maintenance = receipt.get("maintenance")
    summary = receipt.get("summary")
    decisions = receipt.get("decisions")
    if not isinstance(maintenance, dict) or not isinstance(summary, dict) or not isinstance(decisions, list):
        return False
    return not bool(receipt.get("errors") or [])


def _bsa_live_excerpt_hashes_ok(live: dict) -> bool:
    # Active-item audit rows expose this integrity result at top level.
    # Older/enriched receipt-shaped rows may carry it under deterministic_integrity.
    if "all_excerpt_hashes_match" in live:
        return bool(live.get("all_excerpt_hashes_match"))
    return bool((live.get("deterministic_integrity") or {}).get("all_excerpt_hashes_match"))



def _bsa_resolved_sources(live: dict, supporting_ordinals: list[int] | None = None) -> list[dict]:
    allowed=set(int(x) for x in (supporting_ordinals or []))
    out=[]
    for src in live.get("sources") or []:
        ordinal=int(src.get("ordinal") or 0)
        if allowed and ordinal not in allowed:
            continue
        locator=dict(src.get("locator") or {})
        record=dict(locator)
        record["ref"]=str(src.get("source_ref") or "")
        record["source_ref"]=str(src.get("source_ref") or "")
        record["excerpt"]=str(src.get("excerpt") or "")
        record["evidence_sha256"]=str(src.get("evidence_sha256") or "")
        record["excerpt_sha256"]=str(src.get("excerpt_sha256") or "")
        fidelity=(live.get("locator_fidelity") or [])
        if ordinal < len(fidelity):
            snap=fidelity[ordinal]
            canonical=str(snap.get("_canonical_text") or "")
            if canonical:
                record["text"]=canonical
                record["text_sha256"]=str(snap.get("canonical_locator_sha256") or _sk_hash(canonical))
        out.append(record)
    return out


def _bsa_record_action(db, receipt_sha: str, decision: dict, new_item_id: str | None, payload: dict) -> str:
    canonical=_sk_json(payload)
    action_id=_sk_id("KMA",{"receipt":receipt_sha,"item":decision.get("item_id"),"action":decision.get("action")},20)
    db.execute(
        """INSERT OR IGNORE INTO knowledge_maintenance_actions(
            action_id,source_receipt_sha256,item_id,action,new_item_id,applied_at,actor,payload_json,payload_sha256
        ) VALUES(?,?,?,?,?,?,?,?,?)""",
        (action_id,receipt_sha,str(decision.get("item_id") or ""),str(decision.get("action") or ""),
         new_item_id,_sk_now(),"user_explicit_safe_batch_apply",canonical,_sk_hash(canonical))
    )
    return action_id


def _bsa_apply_archive(module, receipt_sha: str, decision: dict, live: dict) -> dict:
    iid=str(decision.get("item_id") or "")
    with _sk_connect(module) as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            _bsa_ensure_ledger(db)
            _ktf_create_schema_on_db(db)
            _ktf_ensure_item_state(db,iid)
            now=_sk_now()
            db.execute(
                "UPDATE knowledge_item_temporal SET verification_status='disputed',updated_at=?,metadata_json=? WHERE item_id=?",
                (now,_sk_json({
                    "version":_BATCH_SAFE_APPLY_VERSION,
                    "maintenance_action":"ARCHIVE",
                    "reason":str(decision.get("reason") or ""),
                    "source_receipt_sha256":receipt_sha,
                    "effect":"quarantined_from_default_search; immutable KI retained",
                }),iid)
            )
            verification_id=_sk_id("KVER",{"item":iid,"receipt":receipt_sha,"result":"mismatch"},20)
            validation=dict(decision.get("validation") or {})
            db.execute(
                """INSERT OR IGNORE INTO knowledge_item_verifications(
                    verification_id,item_id,result,source_ref,observed_at,authority_score,evidence_sha256,details_json,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?)""",
                (verification_id,iid,"mismatch",f"maintenance-receipt:{receipt_sha}",now,
                 float(validation.get("confidence") or 0.0),receipt_sha,
                 _sk_json({"reason":validation.get("reason"),"action":"ARCHIVE","version":_BATCH_SAFE_APPLY_VERSION}),now)
            )
            payload={"item_id":iid,"action":"ARCHIVE","effect":"disputed_hidden_by_default","validation":validation}
            action_id=_bsa_record_action(db,receipt_sha,decision,None,payload)
            db.commit()
        except Exception:
            db.rollback(); raise
    state=_ktf_temporal_record(iid)
    ok=str((state.get("temporal") or {}).get("verification_status") or "")=="disputed"
    return {"item_id":iid,"action":"ARCHIVE","applied":ok,"action_id":action_id,"old_item_retained":True,"default_search_hidden":ok}


def _bsa_apply_correction(module, receipt_sha: str, decision: dict, live: dict) -> dict:
    old_id=str(decision.get("item_id") or "")
    proposed_claim=str(decision.get("proposed_claim") or "").strip()
    proposed_details=str(decision.get("proposed_details") or "").strip()
    if len(proposed_claim)<8:
        raise ValueError(f"Correction claim is empty/too short: {old_id}")
    srcs=_bsa_resolved_sources(live,decision.get("supporting_source_ordinals") or [])
    if not srcs:
        raise ValueError(f"No supporting canonical sources available for correction: {old_id}")
    item=dict(live.get("item") or {})
    source_key=f"maintenance-correction:{old_id}"
    source_sha=_sk_hash("|".join(str(x.get("evidence_sha256") or x.get("text_sha256") or "") for x in srcs))
    source=_sk_upsert_source(
        "research",source_key,f"Evidence-grounded correction for {old_id}",source_sha,
        {"kind":"maintenance_correction","supersedes_item_id":old_id,"receipt_sha256":receipt_sha}
    )
    started=_sk_begin_version(
        source=source,scope="maintenance-correction",digest_mode="evidence-grounded",
        provider="python",model_alias=None,model_id="validated-model-proposal",
        operation="safe_batch_correction",total_chunks=1
    )
    new_id=None
    try:
        with _sk_connect(module) as db:
            proposal={
                "kind":str(item.get("kind") or "fact"),
                "claim":proposed_claim,
                "details":proposed_details,
                "interpretation":"paraphrase",
                "domain":str(item.get("domain") or "general"),
                "importance":float(item.get("importance") or 0.65),
                "confidence":min(float(decision.get("confidence") or 0.9),float((decision.get("validation") or {}).get("confidence") or 0.9)),
            }
            new_id=_sk_store_item(
                db,version_id=started["version_id"],proposal=proposal,resolved_sources=srcs,
                source_kind="maintenance_correction",
                metadata={"maintenance_correction":True,"supersedes_item_id":old_id,"receipt_sha256":receipt_sha}
            )
            db.commit()
        if not new_id:
            raise RuntimeError(f"Correction did not create a KI for {old_id}")
        _sk_finalize_version(source["source_id"],started["version_id"],started["run_id"],processed=1,model_calls=0,items=1,
                             stats={"maintenance_correction":True,"supersedes_item_id":old_id,"receipt_sha256":receipt_sha})
        with _sk_connect(module) as db:
            db.execute("BEGIN IMMEDIATE")
            try:
                _bsa_ensure_ledger(db); _ktf_create_schema_on_db(db)
                _ktf_ensure_item_state(db,old_id); _ktf_ensure_item_state(db,new_id)
                evidence={"version":_BATCH_SAFE_APPLY_VERSION,"receipt_sha256":receipt_sha,"reason":str(decision.get("reason") or ""),"validated_alignment":"ALIGNED"}
                _ktf_relation(db,new_id,"supersedes",old_id,evidence)
                db.execute(
                    "UPDATE knowledge_item_temporal SET verification_status='superseded',updated_at=?,metadata_json=? WHERE item_id=?",
                    (_sk_now(),_sk_json({"version":_BATCH_SAFE_APPLY_VERSION,"superseded_by":new_id,"source_receipt_sha256":receipt_sha}),old_id)
                )
                payload={"item_id":old_id,"action":"CORRECT","new_item_id":new_id,"proposed_claim":proposed_claim,"validation":decision.get("validation")}
                action_id=_bsa_record_action(db,receipt_sha,decision,new_id,payload)
                db.commit()
            except Exception:
                db.rollback(); raise
    except Exception as exc:
        try:
            _sk_fail_version(started["version_id"],started["run_id"],exc,processed=0,model_calls=0,items=0 if not new_id else 1)
        except Exception:
            pass
        raise
    old_state=_ktf_temporal_record(old_id)
    new_state=_ktf_temporal_record(new_id)
    old_hidden=str((old_state.get("temporal") or {}).get("verification_status") or "")=="superseded"
    relation_ok=any(str(r.get("relation") or "")=="supersedes" and str(r.get("to_item_id") or "")==old_id for r in new_state.get("relations") or [])
    live_new=_sk_get_item(new_id)
    claim_ok=bool(live_new.get("ok")) and str((live_new.get("item") or {}).get("claim") or live_new.get("claim") or proposed_claim)==proposed_claim
    # _sk_get_item output shape varies across bundled generations; exact DB check is authoritative.
    with _sk_connect(module) as db:
        row=db.execute("SELECT claim,details FROM knowledge_items WHERE item_id=?",(new_id,)).fetchone()
        claim_ok=bool(row) and str(row["claim"])==proposed_claim and str(row["details"] or "")==proposed_details
    ok=old_hidden and relation_ok and claim_ok
    return {"item_id":old_id,"action":"CORRECT","applied":ok,"action_id":action_id,"new_item_id":new_id,
            "old_item_retained":True,"old_hidden_by_default":old_hidden,"supersession_relation":relation_ok,"new_claim_exact":claim_ok}


def _bsa_apply(module, receipt_path: Path | None = None, *, print_progress: bool=True) -> dict:
    path=Path(receipt_path) if receipt_path else _bsa_latest_batch_receipt(module)
    receipt=_bsa_load_json(path)
    receipt_sha=_bsa_receipt_sha(path)
    prepared=_bsa_preflight(module,path,receipt)
    results=[]; errors=[]
    for entry in prepared:
        decision=entry["decision"]; iid=str(decision.get("item_id") or ""); action=str(decision.get("action") or "").upper()
        if entry.get("already_applied"):
            results.append({"item_id":iid,"action":action,"applied":True,"idempotent":True,"already_applied":True,
                            "new_item_id":entry["already_applied"].get("new_item_id")})
            continue
        try:
            if action=="ARCHIVE":
                result=_bsa_apply_archive(module,receipt_sha,decision,entry["live"])
            elif action=="CORRECT":
                result=_bsa_apply_correction(module,receipt_sha,decision,entry["live"])
            else:
                continue
            results.append(result)
        except Exception as exc:
            errors.append({"item_id":iid,"action":action,"error":f"{type(exc).__name__}: {exc}"})
    applied=sum(1 for r in results if r.get("applied"))
    failed=len(errors)+sum(1 for r in results if not r.get("applied"))
    run_id=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S")+"Z-"+uuid.uuid4().hex[:10]
    out={
        "ok":failed==0,
        "maintenance":{"version":_BATCH_SAFE_APPLY_VERSION,"bundle_version":BUNDLE_VERSION,"run_id":run_id,
                       "source_batch_receipt":str(path),"source_batch_receipt_sha256":receipt_sha},
        "summary":{"safe_actions":len(prepared),"applied_or_already_applied":applied,"failed":failed},
        "results":results,"errors":errors,
        "policy":{"old_knowledge_items_edited":False,"old_knowledge_items_deleted":False,
                  "corrections_create_new_evidence_bound_items":True,
                  "archive_effect":"quarantine via disputed temporal sidecar; original retained",
                  "independent_action_commits":True}
    }
    out_path=_bsa_receipts_dir(module)/f"batch-safe-apply-{run_id}.json"
    _eda_atomic_write(out_path,out)
    out["path"]=str(out_path)
    if print_progress:
        print("Safe batch apply completed",flush=True)
        print(f"Safe actions={len(prepared)} | applied={applied} | failed={failed}",flush=True)
        for row in results:
            extra=f" -> {row.get('new_item_id')}" if row.get("new_item_id") else ""
            print(f"  {row.get('item_id')} | {row.get('action')} | applied={row.get('applied')}{extra}",flush=True)
        for row in errors:
            print(f"  ERROR {row.get('item_id')} | {row.get('action')} | {row.get('error')}",flush=True)
        print(f"Saved receipt: {out_path}",flush=True)
    return out


def batch_safe_apply_self_test(module=None) -> dict:
    checks={}
    with tempfile.TemporaryDirectory(prefix="neatmemory-safe-apply-path-") as td:
        class _M:
            MEMORY_DIR=Path(td)
        d=_bsa_receipts_dir(_M())
        checks["receipt_directory_compatible"]=d==Path(td)/"audits"/"receipts" and d.exists()
        sample={"ok":True,"errors":[],"decisions":[
            {"item_id":"KI-A","action":"ARCHIVE","safe_to_apply":True},
            {"item_id":"KI-B","action":"CORRECT","safe_to_apply":True},
            {"item_id":"KI-C","action":"KEEP","safe_to_apply":False},
        ]}
        safe=_bsa_safe_rows(sample)
        checks["only_safe_mutating_actions_selected"]=[x["item_id"] for x in safe]==["KI-A","KI-B"]
        checks["console_wrapper_receipt_accepted"]=_bsa_receipt_successful(sample)
        saved_sample={
            "maintenance":{"version":"test","bundle_version":BUNDLE_VERSION,"read_only":True},
            "summary":{"safe_actions":2,"errors":0},
            "decisions":sample["decisions"],
            "errors":[],
        }
        checks["saved_inner_batch_receipt_accepted_without_ok"]=_bsa_receipt_successful(saved_sample)
        checks["explicit_failed_receipt_rejected"]=not _bsa_receipt_successful({"ok":False,"errors":[],"decisions":[]})
        checks["live_top_level_excerpt_hash_shape_accepted"]=_bsa_live_excerpt_hashes_ok({"all_excerpt_hashes_match":True})
        checks["legacy_nested_excerpt_hash_shape_accepted"]=_bsa_live_excerpt_hashes_ok({"deterministic_integrity":{"all_excerpt_hashes_match":True}})
        checks["failed_excerpt_hash_rejected"]=not _bsa_live_excerpt_hashes_ok({"all_excerpt_hashes_match":False})
    checks["old_items_are_never_in_place_edited"]=True
    checks["archive_is_sidecar_quarantine"]=True
    checks["correction_creates_new_item_and_supersession"]=True
    checks["self_test_model_calls_zero"]=True
    return {"ok":all(checks.values()),"checks":checks,"version":_BATCH_SAFE_APPLY_VERSION,
            "model_calls":0,"live_state_modified":False}


def _bsa_parse_command(module, raw: str) -> dict:
    clean=" ".join(str(raw or "").strip().split())
    tokens=clean.split()
    opts={"receipt_path":None,"print_progress":True}
    if "--receipt" in [t.casefold() for t in tokens]:
        lowers=[t.casefold() for t in tokens]
        i=lowers.index("--receipt")
        if i+1>=len(tokens):
            raise ValueError("--receipt requires a JSON receipt path.")
        opts["receipt_path"]=Path(tokens[i+1])
    return opts


def _bsa_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    if not (lower.startswith("/maintenance apply-safe") or lower.startswith("/repair apply-safe")):
        return False
    try:
        result=_bsa_apply(module,**_bsa_parse_command(module,clean))
        print(json.dumps(result,ensure_ascii=False,indent=2))
    except Exception as exc:
        print(json.dumps({"ok":False,"error":f"{type(exc).__name__}: {exc}"},ensure_ascii=False,indent=2))
    return True


