_DEV_VALIDATION_VERSION = "1.0-zero-model-engineering-and-semantic-map-audits"


def _dev_median(values: list[float]) -> float:
    vals=sorted(float(x) for x in values)
    if not vals: return 0.0
    n=len(vals); mid=n//2
    return vals[mid] if n%2 else (vals[mid-1]+vals[mid])/2.0


def _dev_semantic_map_metrics(data: dict) -> dict:
    units=[x for x in (data.get("semantic_units") or []) if isinstance(x,dict)]
    structures=[x for x in (data.get("structural_resumes") or []) if isinstance(x,dict)]
    starts=[]; positive=0; hashed=0; refs=0
    for u in units:
        start=(int(u.get("start_ordinal") or 0),int(u.get("start_char") or 0))
        end=(int(u.get("end_ordinal") or 0),int(u.get("end_char") or 0))
        starts.append(start)
        if end>start: positive+=1
        if str(u.get("source_sha256") or "").strip(): hashed+=1
        if list(u.get("source_refs") or []): refs+=1
    monotonic=all(starts[i] <= starts[i+1] for i in range(max(0,len(starts)-1)))
    canonical=sum(1 for x in structures if str(x.get("coverage_status") or "").casefold()=="canonical")
    partial=sum(1 for x in structures if str(x.get("coverage_status") or "").casefold()=="partial")
    n=max(1,len(units))
    integrity_parts=[
        25.0 if monotonic else 0.0,
        25.0*(positive/n),
        25.0*(hashed/n),
        15.0*(refs/n),
        10.0 if bool(data.get("active")) and str(data.get("version_status") or "").casefold()=="completed" else 0.0,
    ]
    return {
        "semantic_units":len(units),"structural_resumes":len(structures),
        "canonical_structures":canonical,"partial_structures":partial,
        "canonical_structure_ratio":round(canonical/max(1,canonical+partial),4) if (canonical+partial) else None,
        "monotonic_source_order":monotonic,"positive_span_units":positive,
        "hashed_units":hashed,"source_ref_units":refs,
        "integrity_score":round(sum(integrity_parts),2),
        "note":"Canonical/partial structure ratio is diagnostic only; fluid semantic units are not penalized for crossing formal boundaries.",
    }


def _dev_transport_recovery_self_test(module=None) -> dict:
    digest=_load_digest()
    original={name:getattr(digest,name,None) for name in (
        "CONNECTION_RETRY_ATTEMPTS","CONNECTION_RETRY_INITIAL_SECONDS","CONNECTION_RETRY_MAX_SECONDS"
    )}
    original_sleep=getattr(digest.time,"sleep",None)
    sleeps=[]
    class APIConnectionError(Exception): pass
    class APITimeoutError(Exception): pass
    class AuthenticationError(Exception): pass
    try:
        digest.CONNECTION_RETRY_ATTEMPTS=4; digest.CONNECTION_RETRY_INITIAL_SECONDS=0.0; digest.CONNECTION_RETRY_MAX_SECONDS=0.0
        digest.time.sleep=lambda seconds:sleeps.append(float(seconds))
        calls={"connection":0,"timeout":0,"auth":0,"permanent":0}
        def connection_then_ok():
            calls["connection"]+=1
            if calls["connection"]<3: raise APIConnectionError("Connection error")
            return "ok"
        def timeout_then_ok():
            calls["timeout"]+=1
            if calls["timeout"]<2: raise APITimeoutError("Request timed out")
            return "timeout-ok"
        def auth_fail():
            calls["auth"]+=1; raise AuthenticationError("bad key")
        def permanent_connection():
            calls["permanent"]+=1; raise APIConnectionError("Connection error")
        connection_result=digest.call_with_retry(connection_then_ok)
        timeout_result=digest.call_with_retry(timeout_then_ok)
        auth_raised=False
        try: digest.call_with_retry(auth_fail)
        except AuthenticationError: auth_raised=True
        permanent_raised=False
        try: digest.call_with_retry(permanent_connection)
        except APIConnectionError: permanent_raised=True
        checks={
            "connection_recovers_after_two_failures":connection_result=="ok" and calls["connection"]==3,
            "timeout_is_retryable":timeout_result=="timeout-ok" and calls["timeout"]==2,
            "authentication_fails_fast":auth_raised and calls["auth"]==1,
            "connection_retry_is_bounded":permanent_raised and calls["permanent"]==4,
            "retry_path_used_sleep_hook":len(sleeps)>=4,
        }
    finally:
        if original_sleep is not None: digest.time.sleep=original_sleep
        for name,value in original.items():
            if value is not None: setattr(digest,name,value)
    return {"ok":all(checks.values()),"checks":checks,"model_calls":0,"web_calls":0,"version":_DEV_VALIDATION_VERSION}


