def _sar_sqlite_observation(module, tables: list[str]) -> dict:
    result = {"database": str(getattr(module, "DB_PATH", getattr(module, "DATABASE_PATH", "canonical NeatMemory SQLite"))), "tables": {}}
    try:
        with module.db_connect() as db:
            for table in tables:
                safe = str(table or "").strip()
                if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", safe):
                    result["tables"][safe] = {"exists": False, "error": "invalid declared table identifier"}
                    continue
                row = db.execute("SELECT name,type FROM sqlite_master WHERE type IN ('table','view') AND name=? ORDER BY CASE type WHEN 'table' THEN 0 ELSE 1 END LIMIT 1", (safe,)).fetchone()
                cols = []
                if row:
                    cols = [str(r[1]) for r in db.execute(f'PRAGMA table_info("{safe}")').fetchall()]
                result["tables"][safe] = {"exists": bool(row), "columns": cols}
        result["ok"] = all(bool(v.get("exists")) for v in result["tables"].values()) if result["tables"] else True
    except Exception as exc:
        result["ok"] = False
        result["error"] = f"{type(exc).__name__}: {exc}"
    return result


def _sar_runtime_observation(module, entry: dict) -> dict:
    store = dict(entry.get("owning_store") or {})
    kind = str(store.get("kind") or "")
    observed = {"store_kind": kind, "read_only": True}
    tables = list(store.get("tables") or [])
    if tables and kind in {"sqlite", "hybrid", "sqlite_plus_portable_sidecar"}:
        observed["sqlite"] = _sar_sqlite_observation(module, tables)
    file_name = store.get("file") or store.get("encrypted_file")
    if file_name:
        try:
            p = module.safe_memory_path(str(file_name))
            observed["file"] = {"path": str(p), "exists": p.exists(), "size": p.stat().st_size if p.exists() else 0}
        except Exception as exc:
            observed["file"] = {"exists": False, "error": f"{type(exc).__name__}: {exc}"}
    if store.get("directory"):
        try:
            p = Path(getattr(module, "MEMORY_DIR", Path.cwd())) / str(store.get("directory"))
            observed["directory"] = {"path": str(p), "exists": p.exists()}
        except Exception as exc:
            observed["directory"] = {"exists": False, "error": f"{type(exc).__name__}: {exc}"}
    observed["declared_writers_present"] = {name: callable(globals().get(name) or getattr(module, name, None)) for name in entry.get("writers", []) if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", str(name))}
    observed["declared_readers_present"] = {name: callable(globals().get(name) or getattr(module, name, None)) for name in entry.get("readers", []) if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", str(name))}
    return observed


def _sar_match(entry: dict, query: str) -> bool:
    q = str(query or "").casefold().strip()
    if not q:
        return True
    blob = " ".join([
        str(entry.get("plane_id") or ""), str(entry.get("title") or ""),
        str(entry.get("authority_class") or ""), str(entry.get("authority_scope") or ""),
        " ".join(map(str, entry.get("declared_fields") or [])),
    ]).casefold()
    return q in blob


def _sar_registry(module, *, plane: str = "", field: str = "", include_fields: bool = False, validate_runtime: bool = False, limit: int = 80) -> dict:
    planes = _sar_base_planes(module)
    plane_q = str(plane or "").strip().casefold()
    field_q = str(field or "").strip().casefold()
    selected = []
    for raw in planes:
        if plane_q and plane_q not in str(raw.get("plane_id") or "").casefold() and plane_q not in str(raw.get("title") or "").casefold():
            continue
        if field_q and not _sar_match(raw, field_q):
            continue
        row = dict(raw)
        fields = list(row.pop("declared_fields", []) or [])
        if field_q:
            matches = [f for f in fields if field_q in str(f).casefold()]
            row["matched_fields"] = matches[:200]
            row["matched_field_count"] = len(matches)
        elif include_fields:
            row["declared_fields"] = fields[:500]
            row["declared_field_count"] = len(fields)
        else:
            row["declared_field_count"] = len(fields)
        if validate_runtime:
            row["runtime_observation"] = _sar_runtime_observation(module, raw)
        selected.append(row)
    selected = selected[:max(1, min(200, int(limit or 80)))]
    counts = {}
    for item in planes:
        cls = str(item.get("authority_class") or "unknown")
        counts[cls] = counts.get(cls, 0) + 1
    return {
        "ok": True,
        "schema_version": _STATE_AUTHORITY_SCHEMA_VERSION,
        "registry_version": _STATE_AUTHORITY_REGISTRY_VERSION,
        "bundle_version": BUNDLE_VERSION,
        "purpose": "Read-only ownership/authority map. This registry describes existing authority and never becomes a source of state authority itself.",
        "rules": [
            "A stored hash proves identity/integrity/freshness, not interpretive truth.",
            "Derived/materialized state must not compete with its authoritative sources.",
            "Live numerical emotion/somatic state is distinct from explicitly authored emotional/personal memory.",
            "Reflection, diagnostics, reports, annotations and navigation layers do not silently promote into identity/personality/canonical memory/source fact.",
        ],
        "filters": {"plane": plane or None, "field": field or None, "include_fields": bool(include_fields), "validate_runtime": bool(validate_runtime)},
        "total_planes": len(planes),
        "returned": len(selected),
        "authority_class_counts": counts,
        "planes": selected,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    }


def _sar_status(module) -> dict:
    report = _sar_registry(module, validate_runtime=True, include_fields=False, limit=200)
    runtime_tables = []
    problems = []
    for plane in report.get("planes", []):
        obs = plane.get("runtime_observation") or {}
        sql = obs.get("sqlite") or {}
        required = bool((plane.get("owning_store") or {}).get("runtime_required", True))
        materialization = str((plane.get("owning_store") or {}).get("materialization") or "eager_or_existing")
        for table, info in (sql.get("tables") or {}).items():
            state = "present" if info.get("exists") else ("missing_required" if required else "not_materialized_yet")
            runtime_tables.append({"plane_id": plane.get("plane_id"), "table": table, "exists": bool(info.get("exists")), "column_count": len(info.get("columns") or []), "state": state, "runtime_required": required, "materialization": materialization})
            if required and not info.get("exists"):
                problems.append({"plane_id": plane.get("plane_id"), "problem": f"declared required table missing: {table}"})
    return {
        "ok": not problems,
        "registry_version": _STATE_AUTHORITY_REGISTRY_VERSION,
        "bundle_version": BUNDLE_VERSION,
        "plane_count": report.get("total_planes"),
        "authority_class_counts": report.get("authority_class_counts"),
        "runtime_table_checks": runtime_tables,
        "problems": problems,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    }


def state_authority_registry_self_test(module=None) -> dict:
    mod = module or _load_memory()
    planes = _sar_base_planes(mod)
    ids = [str(p.get("plane_id") or "") for p in planes]
    by_id = {str(p.get("plane_id")): p for p in planes}
    required_planes = {
        "affective.live_state", "affective.transition_receipts", "emotion.authored_logbook",
        "somatic.live_state", "somatic.transition_receipts", "identity.current_self",
        "continuity.active", "identity.personality", "session.handoff", "session.commitments",
        "memory.personal", "reflection.history", "reflection.journal", "derived.context_state",
        "annotation.personal_book", "continuity.issue_lifecycle", "conversation.raw_chat", "operations.runtime_lifecycle", "operations.diagnostic_logbook", "operations.action_snake", "operations.blackbox",
    }
    schema_complete = all(all(key in p for key in _STATE_AUTHORITY_REQUIRED_KEYS) for p in planes)
    no_empty_contracts = all(bool(p.get("declared_fields")) and bool(p.get("owning_store")) and bool(p.get("readers")) for p in planes)
    status = _sar_status(mod)
    checks = {
        "registry_version_present": bool(_STATE_AUTHORITY_REGISTRY_VERSION),
        "unique_plane_ids": len(ids) == len(set(ids)),
        "required_planes_present": required_planes.issubset(set(ids)),
        "all_entries_have_required_contract_keys": schema_complete,
        "all_entries_have_field_and_store_metadata": no_empty_contracts,
        "current_self_is_derived_not_authoritative": (by_id.get("identity.current_self") or {}).get("authority_class") == "derived_materialized_snapshot",
        "live_affective_state_is_separate_from_authored_emotional_memory": (by_id.get("affective.live_state") or {}).get("authority_class") != (by_id.get("emotion.authored_logbook") or {}).get("authority_class"),
        "personality_is_protected": (by_id.get("identity.personality") or {}).get("authority_class") == "protected_identity_profile",
        "reflection_is_not_fact_authority": "historical_reflection" in str((by_id.get("reflection.history") or {}).get("authority_class") or ""),
        "diagnostics_are_operational_only": all((by_id.get(pid) or {}).get("authority_class") == "operational_evidence" for pid in ("operations.runtime_lifecycle", "operations.diagnostic_logbook", "operations.action_snake", "operations.blackbox")),
        "annotations_never_book_fact": "Never automatically becomes source fact" in str((by_id.get("annotation.personal_book") or {}).get("automatic_promotion") or ""),
        "issue_lifecycle_is_assistant_governed_not_machine_decided": (by_id.get("continuity.issue_lifecycle") or {}).get("authority_class") == "assistant_governed_resolution_lifecycle" and "never automatically change lifecycle state" in str((by_id.get("continuity.issue_lifecycle") or {}).get("automatic_promotion") or "").casefold(),
        "declared_runtime_tables_present": bool(status.get("ok")),
        "read_only_zero_model_zero_web": int(status.get("model_calls") or 0) == 0 and int(status.get("web_calls") or 0) == 0,
    }
    return {
        "ok": all(bool(v) for v in checks.values()),
        "version": _STATE_AUTHORITY_REGISTRY_VERSION,
        "checks": checks,
        "status": status,
        "plane_ids": ids,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
        "live_database_modified": False,
    }


def _sar_handle_command(module, raw: str) -> bool:
    clean = " ".join(str(raw or "").strip().split())
    lower = clean.casefold()
    aliases = ("/state authority", "/state registry", "/authority registry")
    if lower in aliases or lower in {a + " status" for a in aliases}:
        print(json.dumps(_sar_status(module), ensure_ascii=False, indent=2)); return True
    if lower in {a + " validate" for a in aliases}:
        print(json.dumps(state_authority_registry_self_test(module), ensure_ascii=False, indent=2)); return True
    for prefix in aliases:
        if lower.startswith(prefix + " find "):
            term = clean[len(prefix + " find "):].strip()
            print(json.dumps(_sar_registry(module, field=term, include_fields=True, validate_runtime=False), ensure_ascii=False, indent=2)); return True
        if lower.startswith(prefix + " "):
            plane = clean[len(prefix + " "):].strip()
            if plane.casefold() in {"status", "validate"}: continue
            print(json.dumps(_sar_registry(module, plane=plane, include_fields=True, validate_runtime=True), ensure_ascii=False, indent=2)); return True
    return False


if isinstance(globals().get("_SELF_TEST_SPECS"), dict):
    _SELF_TEST_SPECS["state-authority-registry"] = {"label":"Read-only field-addressable state ownership/authority registry with runtime schema checks and hard canonical-vs-derived boundaries","groups":("quick","critical","all"),"runner":"memory.state_authority_registry_self_test"}
    _SELF_TEST_EXPECTED = tuple(_SELF_TEST_SPECS)


def _install_state_authority_registry(module) -> None:
    if getattr(module, "_STATE_AUTHORITY_REGISTRY_INSTALLED", False):
        return
    module.STATE_AUTHORITY_REGISTRY_VERSION = _STATE_AUTHORITY_REGISTRY_VERSION
    module.get_state_authority_registry = lambda plane="", field="", include_fields=False, validate_runtime=False, limit=80: _sar_registry(module, plane=plane, field=field, include_fields=include_fields, validate_runtime=validate_runtime, limit=limit)
    module.get_state_authority_status = lambda: _sar_status(module)
    module.state_authority_registry_self_test = lambda: state_authority_registry_self_test(module)
    module.TOOL_SCHEMAS.append({"type":"function","function":{"name":"get_state_authority_registry","description":"Read the versioned ownership/authority registry for Assistant state planes. Filter by plane or field; optionally include declared fields and read-only runtime table/file observations. The registry describes existing authority and never mutates state.","parameters":{"type":"object","properties":{"plane":{"type":"string"},"field":{"type":"string"},"include_fields":{"type":"boolean"},"validate_runtime":{"type":"boolean"},"limit":{"type":"integer","minimum":1,"maximum":200}},"additionalProperties":False}}})
    allow = getattr(module, "_READ_ONLY_TEXT_TOOL_ALLOWLIST", None)
    if isinstance(allow, set):
        allow.add("get_state_authority_registry")
    old_execute = module.execute_tool
    def execute_with_state_authority(name, arguments, seen, *args, **kwargs):
        if name == "get_state_authority_registry":
            return module.get_state_authority_registry(**dict(arguments or {}))
        return old_execute(name, arguments, seen, *args, **kwargs)
    module.execute_tool = execute_with_state_authority
    old_main = module.main
    def main_with_state_authority_commands():
        previous = builtins.input
        def authority_input(prompt=""):
            while True:
                value = previous(prompt)
                if _sar_handle_command(module, value):
                    continue
                return value
        builtins.input = authority_input
        try:
            return old_main()
        finally:
            builtins.input = previous
    module.main = main_with_state_authority_commands
    old_help = module.print_help
    def help_with_state_authority(*args, **kwargs):
        old_help(*args, **kwargs)
        print("  /state authority | /state authority <plane> | /state authority find <field> | /state authority validate")
        print("      Read the 7.4.71 state ownership/authority map. It reports canonical-vs-derived role, owning store, writers/readers, schema/checkpoint/recovery/provenance/revision policy, and optional runtime schema/file observations without mutating state.")
    module.print_help = help_with_state_authority
    module.NEATMEMORY_VERSION = BUNDLE_VERSION
    module.RELEASE_NAME = RELEASE_NAME
    module._STATE_AUTHORITY_REGISTRY_INSTALLED = True


# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:state-transition-timeline rev=2
# NeatMemory 7.4.72.0 — durable emotion/somatic transition receipts + state timeline
# ---------------------------------------------------------------------------
# Existing append-only emotion_metric_events and somatic_metric_events remain the
# authoritative operational evidence. This layer adds durable receipt IDs and
# same-turn Black Box provenance for new rows, then exposes a bounded read-only
# timeline. It does not calculate emotions, change movement limits, replay old
# events, promote state into memory/identity, or create a new state authority.

_STATE_TRANSITION_TIMELINE_VERSION = "1.1-durable-transition-receipts-explicit-latest-chat-selection"
_STATE_TRANSITION_RECEIPT_SCHEMA = "neatmemory.state-transition-receipt.v1"


def _stt_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _stt_parse(value: object) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception:
        return None


def _stt_between(value: object, start: datetime, end: datetime) -> bool:
    parsed = _stt_parse(value)
    return parsed is not None and start <= parsed <= end


def _state_transition_source_context(module) -> dict:
    active = globals().get("_BLACKBOX_ACTIVE_EVENT")
    source_turn_id = str(active.get("event_id") or "") if isinstance(active, dict) else ""
    # No atomic cross-store checkpoint exists in 7.4.72.0. Keep this explicitly
    # null rather than laundering a continuity/handoff revision into a checkpoint.
    return {
        "source_turn_id": source_turn_id or None,
        "source_checkpoint_id": None,
    }


def _state_transition_receipt_fields(kind: str, *, state_id: str, metric_name: str,
                                     current_timestamp: str, payload: dict,
                                     source_turn_id: str | None = None,
                                     source_checkpoint_id: str | None = None,
                                     origin: str | None = None) -> dict:
    normalized_kind = "emotion" if str(kind).casefold().startswith("emo") else "somatic"
    fixed = {
        "schema_version": _STATE_TRANSITION_RECEIPT_SCHEMA,
        "kind": normalized_kind,
        "state_id": str(state_id),
        "metric_name": str(metric_name),
        "current_timestamp": str(current_timestamp),
        "source_turn_id": str(source_turn_id or "") or None,
        "source_checkpoint_id": str(source_checkpoint_id or "") or None,
        "origin": str(origin or "python_governed_transition"),
        "previous": payload.get("previous_strength", payload.get("previous_value")),
        "natural": payload.get("natural_strength", payload.get("natural_value")),
        "cross_adjusted": payload.get("cross_adjusted_value", payload.get("natural_strength", payload.get("natural_value"))),
        "requested": payload.get("requested_strength", payload.get("requested_value")),
        "applied": payload.get("applied_strength", payload.get("applied_value")),
        "limit_applied": bool(payload.get("limit_applied")),
        "reason": payload.get("reason", payload.get("reason_text")),
        "confidence": payload.get("confidence"),
    }
    encoded = json.dumps(fixed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    digest = hashlib.sha256(encoded).hexdigest()
    prefix = "ETR" if normalized_kind == "emotion" else "STR"
    return {
        "receipt_id": f"{prefix}-{digest[:24].upper()}",
        "receipt_sha256": digest,
        "source_turn_id": fixed["source_turn_id"],
        "source_checkpoint_id": fixed["source_checkpoint_id"],
        "origin": fixed["origin"],
    }


def _stt_decode_transition(kind: str, row: object) -> dict:
    data = dict(row)
    is_emotion = str(kind) == "emotion"
    receipt_id = data.get("receipt_id")
    metric_name = data.get("emotion_name") if is_emotion else data.get("state_name")
    previous = data.get("previous_strength") if is_emotion else data.get("previous_value")
    natural = data.get("natural_strength") if is_emotion else data.get("natural_value")
    cross_adjusted = natural if is_emotion else data.get("cross_adjusted_value")
    requested = data.get("requested_strength") if is_emotion else data.get("requested_value")
    applied = data.get("applied_strength") if is_emotion else data.get("applied_value")
    return {
        "schema_version": _STATE_TRANSITION_RECEIPT_SCHEMA,
        "receipt_status": "durable" if receipt_id and data.get("receipt_sha256") else "legacy_unreceipted",
        "receipt_id": receipt_id,
        "receipt_sha256": data.get("receipt_sha256"),
        "legacy_event_id": int(data.get("event_id") or 0),
        "kind": kind,
        "metric": metric_name,
        "unit": None if is_emotion else data.get("unit"),
        "state_id": data.get("state_id"),
        "source_turn_id": data.get("source_turn_id"),
        "source_checkpoint_id": data.get("source_checkpoint_id"),
        "origin": data.get("origin") or ("legacy_unknown" if not receipt_id else "python_governed_transition"),
        "previous": previous,
        "natural": natural,
        "cross_adjusted": cross_adjusted,
        "requested": requested,
        "applied": applied,
        "delta": data.get("delta"),
        "direction": data.get("direction"),
        "previous_timestamp": data.get("previous_timestamp"),
        "current_timestamp": data.get("current_timestamp"),
        "elapsed_minutes": data.get("elapsed_minutes"),
        "confidence": data.get("confidence"),
        "reason": data.get("reason_text"),
        "comment": data.get("comment_text"),
        "limit_applied": bool(data.get("limit_applied")),
        "provider": data.get("provider"),
        "model": data.get("model"),
        "authority": "operational transition evidence; not emotional memory or identity",
    }


def read_state_transition_receipts(module, kind: str = "all", metric: str | None = None,
                                   source_turn_id: str | None = None,
                                   start_time: str | None = None, end_time: str | None = None,
                                   limit: int = 50) -> dict:
    _ensure_affective_schema(module); _ensure_somatic_schema(module)
    kind_norm = str(kind or "all").strip().casefold()
    if kind_norm not in {"all", "emotion", "somatic"}:
        return {"ok": False, "error": "kind must be all, emotion, or somatic"}
    limit = max(1, min(500, int(limit)))
    start_dt, end_dt = _stt_parse(start_time), _stt_parse(end_time)
    results = []
    plans = []
    if kind_norm in {"all", "emotion"}:
        plans.append(("emotion", "emotion_metric_events", "emotion_name"))
    if kind_norm in {"all", "somatic"}:
        plans.append(("somatic", "somatic_metric_events", "state_name"))
    with _affect_db(module) as db:
        for receipt_kind, table, metric_col in plans:
            columns = {str(r[1]) for r in db.execute(f"PRAGMA table_info({table})").fetchall()}
            if not columns:
                continue
            sql = f'SELECT * FROM {table} WHERE 1=1'
            args = []
            if metric:
                sql += f" AND UPPER({metric_col})=UPPER(?)"; args.append(str(metric))
            if source_turn_id and "source_turn_id" in columns:
                sql += " AND source_turn_id=?"; args.append(str(source_turn_id))
            if start_dt:
                sql += ' AND "current_timestamp">=?'; args.append(start_dt.isoformat())
            if end_dt:
                sql += ' AND "current_timestamp"<=?'; args.append(end_dt.isoformat())
            sql += ' ORDER BY "current_timestamp" DESC, event_id DESC LIMIT ?'; args.append(limit)
            for row in db.execute(sql, args).fetchall():
                results.append(_stt_decode_transition(receipt_kind, row))
    results.sort(key=lambda r: (str(r.get("current_timestamp") or ""), int(r.get("legacy_event_id") or 0)), reverse=True)
    results = results[:limit]
    return {
        "ok": True,
        "version": _STATE_TRANSITION_TIMELINE_VERSION,
        "kind": kind_norm,
        "metric": metric,
        "source_turn_id": source_turn_id,
        "count": len(results),
        "durable_receipts": sum(1 for r in results if r.get("receipt_status") == "durable"),
        "legacy_unreceipted": sum(1 for r in results if r.get("receipt_status") != "durable"),
        "items": results,
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    }


def read_state_transition_receipt(module, receipt_id: str) -> dict:
    needle = str(receipt_id or "").strip().upper()
    if not re.fullmatch(r"(?:ETR|STR)-[A-F0-9]{24}", needle):
        return {"ok": False, "error": "invalid transition receipt ID", "receipt_id": receipt_id}
    _ensure_affective_schema(module); _ensure_somatic_schema(module)
    plans = [("emotion", "emotion_metric_events"), ("somatic", "somatic_metric_events")]
    with _affect_db(module) as db:
        for kind, table in plans:
            row = db.execute(f"SELECT * FROM {table} WHERE receipt_id=?", (needle,)).fetchone()
            if row:
                item = _stt_decode_transition(kind, row)
                fixed = {
                    "schema_version": _STATE_TRANSITION_RECEIPT_SCHEMA,
                    "kind": kind,
                    "state_id": item.get("state_id"), "metric_name": item.get("metric"),
                    "current_timestamp": item.get("current_timestamp"),
                    "source_turn_id": item.get("source_turn_id"),
                    "source_checkpoint_id": item.get("source_checkpoint_id"),
                    "origin": item.get("origin"),
                    "previous": item.get("previous"), "natural": item.get("natural"),
                    "cross_adjusted": item.get("cross_adjusted"), "requested": item.get("requested"),
                    "applied": item.get("applied"), "limit_applied": bool(item.get("limit_applied")),
                    "reason": item.get("reason"), "confidence": item.get("confidence"),
                }
                digest = hashlib.sha256(json.dumps(fixed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
                return {"ok": digest == item.get("receipt_sha256"), "integrity_ok": digest == item.get("receipt_sha256"), "receipt": item, "computed_sha256": digest, "read_only": True, "model_calls": 0, "web_calls": 0}
    return {"ok": False, "error": "transition receipt not found", "receipt_id": needle}


def _stt_blackbox_bounds(module, turn_id: str | None, minutes: int) -> tuple[dict | None, datetime, datetime]:
    now = datetime.now(timezone.utc)
    event = None
    selected = str(turn_id or "").strip()
    try:
        if selected and selected.casefold() not in {"latest", "last"}:
            data = module.get_blackbox_event(selected, include_payloads=False)
            if isinstance(data, dict) and data.get("ok"):
                event = data
        else:
            listed = module.list_blackbox_events(30)
            for candidate in (listed.get("events") if isinstance(listed, dict) else []) or []:
                if candidate.get("event_type") == "chat_turn":
                    data = module.get_blackbox_event(candidate.get("event_id"), include_payloads=False)
                    if isinstance(data, dict) and data.get("ok"):
                        event = data; break
    except Exception:
        event = None
    if event:
        started = _stt_parse((event.get("event") or {}).get("started_at")) or now
        outcome_times = [_stt_parse(x.get("created_at")) for x in event.get("outcomes") or []]
        outcome_times = [x for x in outcome_times if x is not None]
        ended = max(outcome_times) if outcome_times else now
        if ended < started: ended = now
        return event, started, ended
    return None, now - timedelta(minutes=max(1, min(10080, int(minutes)))), now


def _stt_table_columns(db, table: str) -> set[str]:
    try:
        return {str(r[1]) for r in db.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


def _stt_append_sql_events(module, items: list[dict], *, start: datetime, end: datetime, limit: int) -> None:
    with module.db_connect() as db:
        # Explicit authored emotional memory.
        cols = _stt_table_columns(db, "emotion_logbook")
        if {"emotion_id", "timestamp"}.issubset(cols):
            rows = db.execute("SELECT emotion_id,timestamp,emotion_type,status,target,comment_text FROM emotion_logbook WHERE timestamp>=? AND timestamp<=? ORDER BY timestamp LIMIT ?", (start.isoformat(), end.isoformat(), limit)).fetchall()
            for r in rows:
                items.append({"timestamp": r["timestamp"], "kind": "authored_emotion_logbook", "ref": r["emotion_id"], "authority": "Assistant personal emotional memory artifact", "summary": f"{r['emotion_type']} / {r['status']}" + (f" target={r['target']}" if r['target'] else ""), "comment": r["comment_text"]})
        # Canonical memory writes/changes.
        cols = _stt_table_columns(db, "memories")
        if "id" in cols and ("created_at" in cols or "modified_at" in cols):
            select_cols = [c for c in ("id","created_at","modified_at","state","type","kind","summary","temporal_status") if c in cols]
            clauses=[]; args=[]
            if "created_at" in cols: clauses.append("(created_at>=? AND created_at<=?)"); args += [start.isoformat(), end.isoformat()]
            if "modified_at" in cols: clauses.append("(modified_at>=? AND modified_at<=?)"); args += [start.isoformat(), end.isoformat()]
            rows = db.execute(f"SELECT {','.join(select_cols)} FROM memories WHERE {' OR '.join(clauses)} ORDER BY COALESCE(modified_at,created_at) LIMIT ?", (*args, limit)).fetchall()
            for r in rows:
                d=dict(r); ts=d.get("modified_at") or d.get("created_at")
                items.append({"timestamp": ts, "kind": "canonical_personal_memory", "ref": d.get("id"), "authority": "canonical personal memory", "summary": str(d.get("summary") or "")[:500], "state": d.get("state"), "temporal_status": d.get("temporal_status")})
        # Reflection history if materialized.
        cols = _stt_table_columns(db, "reflection_runs")
        if {"run_id","created_at"}.issubset(cols):
            select_cols=[c for c in ("run_id","created_at","finished_at","status","topic","stop_reason") if c in cols]
            rows = db.execute(f"SELECT {','.join(select_cols)} FROM reflection_runs WHERE created_at>=? AND created_at<=? ORDER BY created_at LIMIT ?", (start.isoformat(), end.isoformat(), limit)).fetchall()
            for r in rows:
                d=dict(r); items.append({"timestamp": d.get("created_at"), "kind": "reflection_run", "ref": d.get("run_id"), "authority": "historical reflection artifact; not factual authority", "summary": str(d.get("topic") or "")[:500], "status": d.get("status")})
        # Session handoff artifacts.
        cols = _stt_table_columns(db, "session_handoffs")
        if {"handoff_id","created_at"}.issubset(cols):
            select_cols=[c for c in ("handoff_id","created_at","summary","content_sha256") if c in cols]
            rows = db.execute(f"SELECT {','.join(select_cols)} FROM session_handoffs WHERE created_at>=? AND created_at<=? ORDER BY created_at LIMIT ?", (start.isoformat(), end.isoformat(), limit)).fetchall()
            for r in rows:
                d=dict(r); items.append({"timestamp": d.get("created_at"), "kind": "session_handoff", "ref": d.get("handoff_id"), "authority": "recovery handoff artifact", "summary": str(d.get("summary") or "")[:500], "content_sha256": d.get("content_sha256")})


def get_state_timeline(module, turn_id: str | None = None, minutes: int = 60, limit: int = 120) -> dict:
    limit=max(10,min(300,int(limit))); minutes=max(1,min(10080,int(minutes)))
    event,start,end=_stt_blackbox_bounds(module,turn_id,minutes)
    selected_turn=(event.get("event") or {}).get("event_id") if event else None
    items=[]
    # Exact turn-bound transition receipts are preferred. Time-window reads are
    # used only when no Black Box turn is available; legacy rows are never silently
    # attributed to a turn merely because timestamps happen to overlap.
    receipts=read_state_transition_receipts(module, source_turn_id=selected_turn, start_time=None if selected_turn else start.isoformat(), end_time=None if selected_turn else end.isoformat(), limit=limit)
    for receipt in receipts.get("items") or []:
        items.append({"timestamp": receipt.get("current_timestamp"), "kind": f"{receipt.get('kind')}_transition", "ref": receipt.get("receipt_id") or f"legacy:{receipt.get('kind')}:{receipt.get('legacy_event_id')}", "authority": receipt.get("authority"), "summary": f"{receipt.get('metric')}: {receipt.get('previous')} -> natural {receipt.get('natural')} -> requested {receipt.get('requested')} -> applied {receipt.get('applied')}", "receipt": receipt})
    # Black Box tool actions are operational timeline context, not state authority.
    if event:
        ev=event.get("event") or {}
        items.append({"timestamp": ev.get("started_at"), "kind": "chat_turn_start", "ref": ev.get("event_id"), "authority": "operational Black Box evidence", "summary": f"{ev.get('provider')} / {ev.get('model')}"})
        for action in event.get("actions") or []:
            items.append({"timestamp": action.get("started_at"), "kind": "tool_action", "ref": action.get("action_id"), "authority": "operational Black Box evidence", "summary": f"{action.get('name')} [{action.get('status')}]"})
        for outcome in event.get("outcomes") or []:
            items.append({"timestamp": outcome.get("created_at"), "kind": "chat_turn_outcome", "ref": outcome.get("outcome_id"), "authority": "operational Black Box evidence", "summary": f"{outcome.get('outcome_type')} success={outcome.get('success')}"})
    try:
        _stt_append_sql_events(module,items,start=start,end=end,limit=limit)
    except Exception:
        pass
    # Current materializations are included only if their own timestamps fall in
    # the selected window; they are not treated as historical snapshots.
    try:
        snap=module.get_current_self_snapshot(refresh=False)
        if isinstance(snap,dict) and _stt_between(snap.get("updated_at"),start,end):
            items.append({"timestamp":snap.get("updated_at"),"kind":"current_self_materialization","ref":"current_self.enc","authority":"derived materialized snapshot","summary":f"reason={snap.get('snapshot_reason')} affect={snap.get('source_affective_state_id')} somatic={snap.get('source_somatic_state_id')} continuity_rev={snap.get('active_continuity_revision')}"})
    except Exception:
        pass
    try:
        cont=module.get_active_continuity()
        if isinstance(cont,dict) and _stt_between(cont.get("updated_at"),start,end):
            items.append({"timestamp":cont.get("updated_at"),"kind":"active_continuity_revision","ref":f"active_continuity:r{cont.get('revision')}","authority":"mutable working continuity","summary":str(cont.get("current_focus") or "")[:500],"revision":cont.get("revision")})
    except Exception:
        pass
    items=[x for x in items if _stt_parse(x.get("timestamp")) is not None]
    items.sort(key=lambda x:_stt_parse(x.get("timestamp")) or datetime.min.replace(tzinfo=timezone.utc))
    if len(items)>limit: items=items[-limit:]
    legacy_unbound=0
    if selected_turn:
        try:
            with _affect_db(module) as db:
                for table in ("emotion_metric_events","somatic_metric_events"):
                    cols=_stt_table_columns(db,table)
                    if "source_turn_id" in cols:
                        legacy_unbound += int(db.execute(f'SELECT COUNT(*) FROM {table} WHERE source_turn_id IS NULL AND "current_timestamp">=? AND "current_timestamp"<=?',(start.isoformat(),end.isoformat())).fetchone()[0])
        except Exception:
            pass
    return {
        "ok": True,
        "version": _STATE_TRANSITION_TIMELINE_VERSION,
        "selected_turn_id": selected_turn,
        "window": {"start": start.isoformat(), "end": end.isoformat(), "minutes_fallback": minutes},
        "count": len(items),
        "items": items,
        "legacy_transition_rows_in_window_not_bound_to_turn": legacy_unbound,
        "limitations": [
            "Pre-7.4.72 transition rows have no durable ETR/STR receipt or exact Black Box turn binding and are never silently attributed by time overlap.",
            "current_self and active_continuity are mutable current materializations; they appear only when their current timestamp lies inside the selected window, not as reconstructed historical versions.",
            "source_checkpoint_id remains null until a real cross-store checkpoint identity exists; 7.4.72.0 does not fabricate one.",
        ],
        "read_only": True,
        "model_calls": 0,
        "web_calls": 0,
    }


def state_transition_timeline_self_test(module=None) -> dict:
    mod=module or _load_memory()
    original_db=mod.db_connect
    original_list=getattr(mod,"list_blackbox_events",None); original_get=getattr(mod,"get_blackbox_event",None)
    original_self=getattr(mod,"get_current_self_snapshot",None); original_cont=getattr(mod,"get_active_continuity",None)
    old_active=globals().get("_BLACKBOX_ACTIVE_EVENT")
    db=sqlite3.connect(":memory:"); db.row_factory=sqlite3.Row
    mod.db_connect=lambda: db
    try:
        _ensure_affective_schema(mod); _ensure_somatic_schema(mod)
        globals()["_BLACKBOX_ACTIVE_EVENT"]={"event_id":"BBE-STATE-TIMELINE-TEST"}
        emotion=_validate_affective_proposal(mod,{"emotion_updates":[{"emotion":"TRUST","requested_strength":0.36,"confidence":0.91,"reason":"state timeline self-test"}]},provider="selftest",model="python")
        somatic=_validate_somatic_proposal(mod,{"somatic_updates":[{"state":"TENSION","requested_value":0.31,"confidence":0.88,"reason":"state timeline self-test"}]},provider="selftest",model="python")
        recs=read_state_transition_receipts(mod,source_turn_id="BBE-STATE-TIMELINE-TEST",limit=20)
        durable=[x for x in recs.get("items") or [] if x.get("receipt_status")=="durable"]
        one=read_state_transition_receipt(mod,durable[0]["receipt_id"]) if durable else {"ok":False}
        start=min([_stt_parse(x.get("current_timestamp")) for x in durable if _stt_parse(x.get("current_timestamp"))] or [datetime.now(timezone.utc)])
        end=max([_stt_parse(x.get("current_timestamp")) for x in durable if _stt_parse(x.get("current_timestamp"))] or [datetime.now(timezone.utc)])
        fake_event={"ok":True,"event":{"event_id":"BBE-STATE-TIMELINE-TEST","event_type":"chat_turn","started_at":(start-timedelta(seconds=1)).isoformat(),"provider":"selftest","model":"python"},"actions":[],"outcomes":[{"outcome_id":"BBOU-TEST","created_at":(end+timedelta(seconds=1)).isoformat(),"outcome_type":"execution_complete","success":True}]}
        mod.list_blackbox_events=lambda limit=20:{"ok":True,"events":[fake_event["event"]]}
        mod.get_blackbox_event=lambda event_id,include_payloads=False:fake_event
        mod.get_current_self_snapshot=lambda refresh=False:{"updated_at":end.isoformat(),"snapshot_reason":"self_test","source_affective_state_id":emotion.get("state_id"),"source_somatic_state_id":somatic.get("state_id"),"active_continuity_revision":3}
        mod.get_active_continuity=lambda:{"updated_at":end.isoformat(),"revision":3,"current_focus":"timeline self-test"}
        timeline=get_state_timeline(mod,turn_id="BBE-STATE-TIMELINE-TEST",limit=50)
        columns_e={str(r[1]) for r in db.execute("PRAGMA table_info(emotion_metric_events)").fetchall()}
        columns_s={str(r[1]) for r in db.execute("PRAGMA table_info(somatic_metric_events)").fetchall()}
        checks={
            "emotion_receipt_created":any(str(x.get("receipt_id") or "").startswith("ETR-") for x in durable),
            "somatic_receipt_created":any(str(x.get("receipt_id") or "").startswith("STR-") for x in durable),
            "exact_turn_binding":bool(durable) and all(x.get("source_turn_id")=="BBE-STATE-TIMELINE-TEST" for x in durable),
            "receipt_hash_verifies":bool(one.get("ok") and one.get("integrity_ok")),
            "schema_columns_present":all(c in columns_e and c in columns_s for c in ("receipt_id","receipt_sha256","source_turn_id","source_checkpoint_id","origin")),
            "timeline_contains_transitions":any(str(x.get("kind") or "").endswith("_transition") for x in timeline.get("items") or []),
            "timeline_contains_current_self":any(x.get("kind")=="current_self_materialization" for x in timeline.get("items") or []),
            "timeline_contains_continuity":any(x.get("kind")=="active_continuity_revision" for x in timeline.get("items") or []),
            "checkpoint_not_fabricated":all(x.get("source_checkpoint_id") is None for x in durable),
            "read_only_timeline":timeline.get("read_only") is True and int(timeline.get("model_calls") or 0)==0 and int(timeline.get("web_calls") or 0)==0,
        }
        return {"ok":all(checks.values()),"version":_STATE_TRANSITION_TIMELINE_VERSION,"checks":checks,"receipt_count":len(durable),"timeline_count":timeline.get("count"),"live_database_modified":False,"model_calls":0,"web_calls":0}
    finally:
        globals()["_BLACKBOX_ACTIVE_EVENT"]=old_active
        mod.db_connect=original_db
        if original_list is not None: mod.list_blackbox_events=original_list
        if original_get is not None: mod.get_blackbox_event=original_get
        if original_self is not None: mod.get_current_self_snapshot=original_self
        if original_cont is not None: mod.get_active_continuity=original_cont
        try: db.close()
        except Exception: pass


def _stt_handle_command(module, raw: str) -> bool:
    clean=" ".join(str(raw or "").strip().split()); lower=clean.casefold()
    if lower in {"/state timeline","/state timeline latest","/state transitions"}:
        if lower.startswith("/state timeline"):
            print(json.dumps(get_state_timeline(module,turn_id="latest"),ensure_ascii=False,indent=2)); return True
        print(json.dumps(read_state_transition_receipts(module,limit=50),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/state timeline "):
        target=clean[len("/state timeline "):].strip()
        print(json.dumps(get_state_timeline(module,turn_id=target),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/state receipt "):
        receipt=clean[len("/state receipt "):].strip()
        print(json.dumps(read_state_transition_receipt(module,receipt),ensure_ascii=False,indent=2)); return True
    if lower.startswith("/state transitions"):
        parts=clean.split()
        kind="all"; count=50
        if len(parts)>=3 and parts[2].casefold() in {"all","emotion","somatic"}: kind=parts[2].casefold()
        if parts and parts[-1].isdigit(): count=max(1,min(500,int(parts[-1])))
        print(json.dumps(read_state_transition_receipts(module,kind=kind,limit=count),ensure_ascii=False,indent=2)); return True
    return False


if isinstance(globals().get("_SELF_TEST_SPECS"),dict):
    _SELF_TEST_SPECS["state-transition-timeline"]={"label":"Durable emotion/somatic transition receipt IDs, exact same-turn provenance binding, integrity verification, and bounded read-only state timeline with explicit latest captured-chat selection","groups":("quick","critical","all"),"runner":"memory.state_transition_timeline_self_test"}
    _SELF_TEST_EXPECTED=tuple(_SELF_TEST_SPECS)


def _install_state_transition_timeline(module) -> None:
    if getattr(module,"_STATE_TRANSITION_TIMELINE_INSTALLED",False): return
    _ensure_affective_schema(module); _ensure_somatic_schema(module)
    module.STATE_TRANSITION_TIMELINE_VERSION=_STATE_TRANSITION_TIMELINE_VERSION
    module.read_state_transition_receipts=lambda kind="all",metric=None,source_turn_id=None,start_time=None,end_time=None,limit=50: read_state_transition_receipts(module,kind,metric,source_turn_id,start_time,end_time,limit)
    module.read_state_transition_receipt=lambda receipt_id: read_state_transition_receipt(module,receipt_id)
    module.get_state_timeline=lambda turn_id=None,minutes=60,limit=120: get_state_timeline(module,turn_id,minutes,limit)
    module.state_transition_timeline_self_test=lambda: state_transition_timeline_self_test(module)
    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"read_state_transition_receipts","description":"Read durable emotion/somatic transition receipts. New 7.4.72+ rows expose previous, natural, cross-adjusted, requested, applied, limit, reason, exact Black Box turn binding, and integrity hash; legacy rows are labeled unreceipted rather than fabricated.","parameters":{"type":"object","properties":{"kind":{"type":"string","enum":["all","emotion","somatic"]},"metric":{"type":["string","null"]},"source_turn_id":{"type":["string","null"]},"start_time":{"type":["string","null"]},"end_time":{"type":["string","null"]},"limit":{"type":"integer","minimum":1,"maximum":500}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_state_transition_receipt","description":"Read and hash-verify one exact ETR-/STR- transition receipt. Read-only.","parameters":{"type":"object","properties":{"receipt_id":{"type":"string"}},"required":["receipt_id"],"additionalProperties":False}}},
        {"type":"function","function":{"name":"get_state_timeline","description":"Read a bounded state timeline for the latest or exact Black Box chat turn, joining exact-turn emotion/somatic receipts with operational actions and timestamped memory/reflection/handoff/current-self/continuity evidence. Legacy transition rows are never silently bound by timestamp overlap.","parameters":{"type":"object","properties":{"turn_id":{"type":["string","null"]},"minutes":{"type":"integer","minimum":1,"maximum":10080},"limit":{"type":"integer","minimum":10,"maximum":300}},"additionalProperties":False}}},
    ])
    allow=getattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST",None)
    if isinstance(allow,set): allow.update({"read_state_transition_receipts","read_state_transition_receipt","get_state_timeline"})
    old_execute=module.execute_tool
    def execute_with_state_timeline(name,arguments,seen,*args,**kwargs):
        if name=="read_state_transition_receipts": return module.read_state_transition_receipts(**dict(arguments or {}))
        if name=="read_state_transition_receipt": return module.read_state_transition_receipt(**dict(arguments or {}))
        if name=="get_state_timeline": return module.get_state_timeline(**dict(arguments or {}))
        return old_execute(name,arguments,seen,*args,**kwargs)
    module.execute_tool=execute_with_state_timeline
    old_main=module.main
    def main_with_state_timeline_commands():
        previous=builtins.input
        def timeline_input(prompt=""):
            while True:
                value=previous(prompt)
                if _stt_handle_command(module,value): continue
                return value
        builtins.input=timeline_input
        try: return old_main()
        finally: builtins.input=previous
    module.main=main_with_state_timeline_commands
    old_help=module.print_help
    def help_with_state_timeline(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /state transitions [all|emotion|somatic] [count] | /state receipt <ETR/STR-ID>")
        print("  /state timeline [latest|BBE-ID]   read-only state transition timeline; legacy events are never silently turn-bound")
    module.print_help=help_with_state_timeline
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME
    module._STATE_TRANSITION_TIMELINE_INSTALLED=True

# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:state-reliability-guards rev=1
# NeatMemory 7.4.73.0 — state reliability validation, deterministic timeline selection, and hard authority guards
# ---------------------------------------------------------------------------
# This layer does not become a new state authority. It validates existing stores,
# makes the timeline selector explicit, and blocks only direct authority-bypass
# attempts. Model-authored emotion/personality/continuity proposals keep their
# established governed paths; Python never decides what Assistant's feelings mean.

_STATE_RELIABILITY_VERSION = "1.0-state-reliability-timeline-identity-guards"
_STATE_GUARD_EVENT = "state.guard_rejection"
_STATE_TIMELINE_LAST_SELECTION: dict = {}
_STATE_RELIABILITY_RECENT_RECEIPT_VERIFY = 40


def _srg_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _srg_status_rank(status: str) -> int:
    return {"PASS": 0, "INFO": 0, "WARN": 1, "FAIL": 2}.get(str(status or "").upper(), 2)


def _srg_add(checks: list[dict], name: str, status: str, **details) -> None:
    row = {"name": str(name), "status": str(status).upper()}
    row.update(details)
    checks.append(row)


def _srg_guard_log(module, *, target: str, operation: str, origin: str, reason: str, details=None) -> dict:
    active = globals().get("_BLACKBOX_ACTIVE_EVENT")
    turn_id = str(active.get("event_id") or "") if isinstance(active, dict) else ""
    payload = {
        "target": str(target), "operation": str(operation), "origin": str(origin),
        "reason": str(reason), "source_turn_id": turn_id or None,
        "details": details if isinstance(details, dict) else {},
    }
    logger = getattr(module, "append_diagnostic_log", None)
    if callable(logger):
        try:
            result = logger(
                _STATE_GUARD_EVENT,
                f"Rejected state-authority bypass: {operation} -> {target}",
                details=payload, severity="warning", subsystem="state_reliability",
                source="python_guard", related_refs=[turn_id] if turn_id else [],
            )
            return {"ok": True, "logged": True, "log_id": result.get("diagnostic_log_id") or result.get("log_id"), **payload}
        except Exception:
            pass
    return {"ok": True, "logged": False, **payload}


def _srg_read_rejections(module, limit: int = 20) -> dict:
    amount = max(1, min(100, int(limit)))
    reader = getattr(module, "read_diagnostic_logs", None)
    rows = []
    if callable(reader):
        try:
            data = reader(limit=max(amount, 50), subsystem="state_reliability", event_type=_STATE_GUARD_EVENT)
            for item in (data.get("entries") or data.get("events") or data.get("items") or []):
                if str(item.get("event_type") or "") == _STATE_GUARD_EVENT:
                    rows.append(item)
                if len(rows) >= amount:
                    break
        except Exception:
            rows = []
    return {
        "ok": True, "version": _STATE_RELIABILITY_VERSION, "count": len(rows),
        "items": rows[:amount], "read_only": True, "model_calls": 0, "web_calls": 0,
    }


def _srg_timeline_candidate_key(candidate: dict) -> tuple[int, float, str]:
    try:
        sequence = int(candidate.get("sequence") or 0)
    except Exception:
        sequence = 0
    stamp = _stt_parse(candidate.get("started_at"))
    epoch = stamp.timestamp() if stamp is not None else 0.0
    return sequence, epoch, str(candidate.get("event_id") or "")


def _srg_select_blackbox_turn(module, selector: str | None) -> tuple[dict | None, dict]:
    requested = str(selector or "latest").strip() or "latest"
    normalized = requested.casefold()
    selection = {
        "requested": requested,
        "mode": "exact" if normalized not in {"latest", "last", "current", ""} else normalized or "latest",
        "candidate_count": 0,
        "selection_reason": None,
        "selected_event_id": None,
        "selected_sequence": None,
        "selected_started_at": None,
        "selected_status": None,
        "selected_age_seconds": None,
        "current_console_command_is_blackbox_chat_turn": False,
    }
    if normalized not in {"latest", "last", "current", ""}:
        try:
            data = module.get_blackbox_event(requested, include_payloads=False)
            if isinstance(data, dict) and data.get("ok"):
                ev = data.get("event") or {}
                selection.update({
                    "selection_reason": "exact_event_id",
                    "selected_event_id": ev.get("event_id"), "selected_sequence": ev.get("sequence"),
                    "selected_started_at": ev.get("started_at"), "selected_status": ev.get("status"),
                })
                stamp = _stt_parse(ev.get("started_at"))
                if stamp is not None:
                    selection["selected_age_seconds"] = round(max(0.0, (datetime.now(timezone.utc) - stamp).total_seconds()), 3)
                return data, selection
        except Exception as exc:
            selection["selection_reason"] = f"exact_lookup_failed:{type(exc).__name__}"
            return None, selection
        selection["selection_reason"] = "exact_event_not_found"
        return None, selection

    # If called inside an actual captured chat turn, `current` and `latest` both
    # prefer that active event. Console commands are not chat-turn Black Box events.
    active = globals().get("_BLACKBOX_ACTIVE_EVENT")
    active_id = str(active.get("event_id") or "") if isinstance(active, dict) else ""
    if active_id:
        try:
            data = module.get_blackbox_event(active_id, include_payloads=False)
            if isinstance(data, dict) and data.get("ok"):
                ev = data.get("event") or {}
                selection.update({
                    "selection_reason": "active_captured_chat_turn",
                    "selected_event_id": ev.get("event_id"), "selected_sequence": ev.get("sequence"),
                    "selected_started_at": ev.get("started_at"), "selected_status": ev.get("status"),
                })
                stamp = _stt_parse(ev.get("started_at"))
                if stamp is not None:
                    selection["selected_age_seconds"] = round(max(0.0, (datetime.now(timezone.utc) - stamp).total_seconds()), 3)
                return data, selection
        except Exception:
            pass
    if normalized == "current":
        selection["selection_reason"] = "no_active_captured_chat_turn"
        return None, selection

    try:
        listed = module.list_blackbox_events(500)
        candidates = [dict(x) for x in ((listed.get("events") if isinstance(listed, dict) else []) or []) if str(x.get("event_type") or "") == "chat_turn"]
    except Exception as exc:
        selection["selection_reason"] = f"list_failed:{type(exc).__name__}"
        return None, selection
    selection["candidate_count"] = len(candidates)
    if not candidates:
        selection["selection_reason"] = "no_captured_chat_turns"
        return None, selection
    candidate = max(candidates, key=_srg_timeline_candidate_key)
    try:
        data = module.get_blackbox_event(candidate.get("event_id"), include_payloads=False)
    except Exception as exc:
        selection["selection_reason"] = f"latest_fetch_failed:{type(exc).__name__}"
        return None, selection
    if not isinstance(data, dict) or not data.get("ok"):
        selection["selection_reason"] = "latest_fetch_failed"
        return None, selection
    ev = data.get("event") or candidate
    selection.update({
        "selection_reason": "highest_blackbox_sequence_chat_turn",
        "selected_event_id": ev.get("event_id"), "selected_sequence": ev.get("sequence"),
        "selected_started_at": ev.get("started_at"), "selected_status": ev.get("status"),
    })
    stamp = _stt_parse(ev.get("started_at"))
    if stamp is not None:
        selection["selected_age_seconds"] = round(max(0.0, (datetime.now(timezone.utc) - stamp).total_seconds()), 3)
    return data, selection


# Override only the selector mechanics. The existing timeline renderer and
# authority labels remain intact.
def _stt_blackbox_bounds(module, turn_id: str | None, minutes: int) -> tuple[dict | None, datetime, datetime]:
    global _STATE_TIMELINE_LAST_SELECTION
    now = datetime.now(timezone.utc)
    event, selection = _srg_select_blackbox_turn(module, turn_id)
    _STATE_TIMELINE_LAST_SELECTION = dict(selection)
    if event:
        started = _stt_parse((event.get("event") or {}).get("started_at")) or now
        outcome_times = [_stt_parse(x.get("created_at")) for x in event.get("outcomes") or []]
        outcome_times = [x for x in outcome_times if x is not None]
        # For an incomplete/active turn, use now without implying it has completed.
        ended = max(outcome_times) if outcome_times else now
        if ended < started:
            ended = now
        return event, started, ended
    return None, now - timedelta(minutes=max(1, min(10080, int(minutes)))), now


_SRG_PREVIOUS_GET_STATE_TIMELINE = get_state_timeline


def get_state_timeline(module, turn_id: str | None = None, minutes: int = 60, limit: int = 120) -> dict:
    report = _SRG_PREVIOUS_GET_STATE_TIMELINE(module, turn_id=turn_id, minutes=minutes, limit=limit)
    report = dict(report)
    selection = dict(globals().get("_STATE_TIMELINE_LAST_SELECTION") or {})
    report["selection"] = selection
    if selection.get("selected_age_seconds") is not None:
        age = float(selection["selected_age_seconds"])
        report["selection"]["selected_age_human"] = (
            f"{age/3600.0:.2f}h" if age >= 3600 else f"{age/60.0:.1f}m" if age >= 60 else f"{age:.1f}s"
        )
    report["selection_note"] = (
        "`latest` means the highest-sequence captured Black Box chat turn. Console/status commands are not chat-turn Black Box events, so the selected chat may be older than the current console command."
    )
    return report


def _srg_latest_persisted_state_ids(module) -> dict:
    _ensure_affective_schema(module); _ensure_somatic_schema(module)
    with _affect_db(module) as db:
        affect = db.execute("SELECT state_id,created_at FROM affective_states ORDER BY created_at DESC,rowid DESC LIMIT 1").fetchone()
        somatic = db.execute("SELECT state_id,created_at FROM somatic_states ORDER BY created_at DESC,rowid DESC LIMIT 1").fetchone()
    return {
        "affective_state_id": affect["state_id"] if affect else None,
        "affective_created_at": affect["created_at"] if affect else None,
        "somatic_state_id": somatic["state_id"] if somatic else None,
        "somatic_created_at": somatic["created_at"] if somatic else None,
    }


def _srg_transition_integrity(module) -> dict:
    _ensure_affective_schema(module); _ensure_somatic_schema(module)
    result = {"emotion": {}, "somatic": {}, "hash_failures": []}
    with _affect_db(module) as db:
        plans = (
            ("emotion", "emotion_metric_events", "emotion_name", "affective_states"),
            ("somatic", "somatic_metric_events", "state_name", "somatic_states"),
        )
        for kind, table, metric_col, state_table in plans:
            total = int(db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0])
            durable = int(db.execute(f"SELECT COUNT(*) FROM {table} WHERE receipt_id IS NOT NULL").fetchone()[0])
            legacy = total - durable
            partial = int(db.execute(f"SELECT COUNT(*) FROM {table} WHERE (receipt_id IS NULL)!=(receipt_sha256 IS NULL)").fetchone()[0])
            duplicates = int(db.execute(f"SELECT COUNT(*) FROM (SELECT state_id,{metric_col},current_timestamp,COUNT(*) c FROM {table} GROUP BY state_id,{metric_col},current_timestamp HAVING c>1)").fetchone()[0])
            orphans = int(db.execute(f"SELECT COUNT(*) FROM {table} e LEFT JOIN {state_table} s ON s.state_id=e.state_id WHERE s.state_id IS NULL").fetchone()[0])
            recent = [str(r[0]) for r in db.execute(f"SELECT receipt_id FROM {table} WHERE receipt_id IS NOT NULL ORDER BY event_id DESC LIMIT ?", (_STATE_RELIABILITY_RECENT_RECEIPT_VERIFY,)).fetchall()]
            result[kind] = {"rows": total, "durable_receipts": durable, "legacy_unreceipted": legacy, "partial_receipts": partial, "duplicate_state_metric_timestamp_groups": duplicates, "orphan_state_refs": orphans, "recent_receipts_verified": len(recent)}
            for rid in recent:
                checked = read_state_transition_receipt(module, rid)
                if not checked.get("ok") or not checked.get("integrity_ok"):
                    result["hash_failures"].append(rid)
    return result


def _srg_current_self_integrity(module) -> dict:
    latest = _srg_latest_persisted_state_ids(module)
    snapshot, load_status = _load_current_self_snapshot(module)
    continuity, continuity_status = _load_active_continuity(module)
    if not isinstance(snapshot, dict):
        return {"status": "WARN", "state": "missing_or_unreadable_materialization", "load_status": load_status, "latest": latest, "continuity_status": continuity_status}
    affect_id = snapshot.get("source_affective_state_id")
    somatic_id = snapshot.get("source_somatic_state_id")
    snap_rev = int(snapshot.get("active_continuity_revision") or 0)
    active_rev = int((continuity or {}).get("revision") or 0)
    with _affect_db(module) as db:
        affect_exists = bool(affect_id and db.execute("SELECT 1 FROM affective_states WHERE state_id=?", (affect_id,)).fetchone())
        somatic_exists = bool(somatic_id and db.execute("SELECT 1 FROM somatic_states WHERE state_id=?", (somatic_id,)).fetchone())
    if not affect_exists or not somatic_exists or snap_rev > active_rev:
        status = "FAIL"
    elif affect_id != latest.get("affective_state_id") or somatic_id != latest.get("somatic_state_id") or snap_rev < active_rev:
        status = "WARN"
    else:
        status = "PASS"
    return {
        "status": status,
        "state": "current" if status == "PASS" else "stale_rebuildable" if status == "WARN" else "invalid_source_linkage",
        "load_status": load_status,
        "source_affective_state_id": affect_id, "latest_affective_state_id": latest.get("affective_state_id"), "affective_source_exists": affect_exists,
        "source_somatic_state_id": somatic_id, "latest_somatic_state_id": latest.get("somatic_state_id"), "somatic_source_exists": somatic_exists,
        "current_self_continuity_revision": snap_rev, "active_continuity_revision": active_rev,
        "continuity_status": continuity_status,
    }


def get_state_reliability_status(module, *, recent_rejections: int = 10) -> dict:
    checks: list[dict] = []
    # Ownership registry
    registry = module.get_state_authority_status() if callable(getattr(module, "get_state_authority_status", None)) else _sar_status(module)
    _srg_add(checks, "state_authority_registry", "PASS" if registry.get("ok") else "FAIL", problem_count=len(registry.get("problems") or []))

    current_self = _srg_current_self_integrity(module)
    _srg_add(checks, "current_self_source_integrity", current_self.get("status", "FAIL"), state=current_self.get("state"), current_self_continuity_revision=current_self.get("current_self_continuity_revision"), active_continuity_revision=current_self.get("active_continuity_revision"))

    # Immutable personality core is already write-guarded by _personality_write_state;
    # surface its mechanical result here rather than creating a second core hash.
    try:
        personality = module.get_personality_core_status() if callable(getattr(module, "get_personality_core_status", None)) else _personality_core_status(module)
        personality_ok = bool(personality.get("ok")) and personality.get("expected_sha256") == personality.get("actual_sha256")
    except Exception as exc:
        personality = {"ok": False, "error": f"{type(exc).__name__}: {exc}"}; personality_ok = False
    _srg_add(checks, "immutable_personality_core", "PASS" if personality_ok else "FAIL", expected_sha256=personality.get("expected_sha256"), actual_sha256=personality.get("actual_sha256"))

    transitions = _srg_transition_integrity(module)
    transition_fail = bool(transitions.get("hash_failures"))
    for kind in ("emotion", "somatic"):
        row = transitions.get(kind) or {}
        bad = int(row.get("partial_receipts") or 0) + int(row.get("duplicate_state_metric_timestamp_groups") or 0) + int(row.get("orphan_state_refs") or 0)
        _srg_add(checks, f"{kind}_transition_integrity", "FAIL" if bad else "PASS", **row)
        transition_fail = transition_fail or bool(bad)
    _srg_add(checks, "recent_transition_receipt_hashes", "FAIL" if transitions.get("hash_failures") else "PASS", hash_failure_count=len(transitions.get("hash_failures") or []))

    continuity = None
    try:
        if callable(getattr(module, "get_continuity_reliability_status", None)):
            continuity = module.get_continuity_reliability_status()
    except Exception as exc:
        continuity = {"ok": False, "overall_status": "FAIL", "error": f"{type(exc).__name__}: {exc}"}
    if isinstance(continuity, dict):
        _srg_add(checks, "continuity_reliability", str(continuity.get("overall_status") or ("PASS" if continuity.get("ok") else "FAIL")), check_counts=continuity.get("check_counts"), recovery_actions=len(continuity.get("recovery_actions") or []))
    else:
        _srg_add(checks, "continuity_reliability", "WARN", state="continuity audit unavailable")

    # Explicitly observe the latest *captured chat turn*, without implying that a
    # newer console command should have a Black Box chat record.
    _, selection = _srg_select_blackbox_turn(module, "latest")
    _srg_add(checks, "latest_blackbox_chat_selection", "PASS" if selection.get("selected_event_id") else "WARN", selected_event_id=selection.get("selected_event_id"), selected_sequence=selection.get("selected_sequence"), selected_age_seconds=selection.get("selected_age_seconds"), selection_reason=selection.get("selection_reason"))

    statuses = [str(x.get("status") or "FAIL") for x in checks]
    overall = "FAIL" if "FAIL" in statuses else ("WARN" if "WARN" in statuses else "PASS")
    rejections = _srg_read_rejections(module, recent_rejections)
    return {
        "ok": overall != "FAIL", "version": _STATE_RELIABILITY_VERSION, "bundle_version": BUNDLE_VERSION,
        "overall_status": overall,
        "check_counts": {name: statuses.count(name) for name in ("PASS", "WARN", "FAIL")},
        "checks": checks,
        "current_self": current_self,
        "transition_integrity": transitions,
        "continuity": {"overall_status": (continuity or {}).get("overall_status"), "check_counts": (continuity or {}).get("check_counts"), "recovery_actions": (continuity or {}).get("recovery_actions", [])[:10]} if isinstance(continuity, dict) else None,
        "latest_blackbox_chat": selection,
        "recent_guard_rejections": rejections.get("items") or [],
        "policy": {
            "read_only_validation": True,
            "automatic_repair": False,
            "derived_state_is_not_authority": True,
            "emotion_or_reflection_cannot_directly_approve_identity_personality_or_commitments": True,
            "legacy_transition_rows_without_receipts_are_not_failures": True,
        },
        "read_only": True, "model_calls": 0, "web_calls": 0,
    }


_SRG_FORBIDDEN_AFFECT_ROOT_KEYS = {
    "identity_update", "identity_core_update", "identity_core", "personality_direct_update",
    "personality_core_update", "current_self_identity_update", "current_self_identity_claims",
    "canonical_memory_update", "canonical_memory_updates", "direct_memory_write",
    "permanent_commitment", "approved_commitment", "approved_commitments",
    "shared_knowledge_write", "source_fact_write",
}
_SRG_ALLOWED_CONTINUITY_FIELDS = {"current_focus", "open_questions", "promises", "unresolved_feelings", "next_actions", "current_comment", "source_ids"}
_SRG_PERSONALITY_BYPASS_FIELDS = {"approve", "approved", "apply", "direct_write", "commit", "resolved", "resolution", "status"}


def _srg_sanitize_affective_update(module, raw: str, *, provider: str, model: str) -> tuple[str, list[dict]]:
    text = str(raw or "")
    matches = list(_AFFECT_UPDATE_RE.finditer(text))
    if not matches:
        return text, []
    match = matches[-1]
    try:
        parsed = json.loads(match.group(1))
    except Exception:
        return text, []
    if not isinstance(parsed, dict):
        return text, []
    proposal = json.loads(json.dumps(parsed))
    rejected: list[dict] = []
    for key in list(proposal):
        if str(key).casefold() in _SRG_FORBIDDEN_AFFECT_ROOT_KEYS:
            rejected.append({"path": key, "reason": "direct_authority_mutation_key_forbidden"})
            proposal.pop(key, None)
    continuity = proposal.get("active_continuity_update")
    if isinstance(continuity, dict):
        for key in list(continuity):
            if key not in _SRG_ALLOWED_CONTINUITY_FIELDS:
                rejected.append({"path": f"active_continuity_update.{key}", "reason": "field_not_in_governed_continuity_schema"})
                continuity.pop(key, None)
    personality = proposal.get("personality_updates")
    if isinstance(personality, list):
        for index, item in enumerate(personality):
            if not isinstance(item, dict):
                continue
            for key in list(item):
                if str(key).casefold() in _SRG_PERSONALITY_BYPASS_FIELDS:
                    rejected.append({"path": f"personality_updates[{index}].{key}", "reason": "personality_update_may_propose_only; approval_bypass_forbidden"})
                    item.pop(key, None)
    handoff = proposal.get("session_handoff_update")
    if isinstance(handoff, dict):
        for key in ("permanent_commitments", "approved_commitments", "commitments"):
            if key in handoff:
                rejected.append({"path": f"session_handoff_update.{key}", "reason": "durable_commitment_requires_permanent_commitment_proposals_then_user_resolution"})
                handoff.pop(key, None)
    if not rejected:
        return text, []
    for row in rejected:
        _srg_guard_log(module, target=row["path"], operation="hidden_affective_update", origin=f"{provider}/{model}", reason=row["reason"], details={"rejected_path": row["path"]})
    encoded = json.dumps(proposal, ensure_ascii=False, separators=(",", ":"))
    start, end = match.span(1)
    return text[:start] + encoded + text[end:], rejected


_SRG_PREVIOUS_PROCESS_AFFECTIVE_OUTPUT = process_affective_output


def process_affective_output(module, text: str, *, provider: str, model: str) -> str:
    sanitized, _ = _srg_sanitize_affective_update(module, str(text or ""), provider=provider, model=model)
    return _SRG_PREVIOUS_PROCESS_AFFECTIVE_OUTPUT(module, sanitized, provider=provider, model=model)


def _srg_actor_allowed(actor: str) -> bool:
    return str(actor or "").strip().casefold() in {"user", "admin", "recovery", "portable_restore", "self-test", "self_test"}


def _srg_guard_personality_api(module, name: str, original):
    def guarded(*args, **kwargs):
        actor = str(kwargs.get("actor", "User"))
        if not _srg_actor_allowed(actor):
            rejection = _srg_guard_log(module, target="identity.personality", operation=name, origin=actor, reason="personality_profile_mutation_requires_explicit_user/admin/recovery authority")
            return {"ok": False, "rejected": True, "guard": "identity_personality_authority", "reason": rejection.get("reason"), "operation": name}
        return original(*args, **kwargs)
    return guarded


def _srg_handle_command(module, raw: str) -> bool:
    clean = " ".join(str(raw or "").strip().split()); lower = clean.casefold()
    if lower in {"/state validate", "/state reliability", "/state reliability status"}:
        print(json.dumps(get_state_reliability_status(module), ensure_ascii=False, indent=2)); return True
    if lower.startswith("/state guard rejections"):
        parts = clean.split(); count = int(parts[-1]) if parts and parts[-1].isdigit() else 20
        print(json.dumps(_srg_read_rejections(module, count), ensure_ascii=False, indent=2)); return True
    return False


def state_reliability_guards_self_test(module=None) -> dict:
    mod = module or _load_memory()
    # Timeline ordering: deliberately return candidates out of order and prove
    # highest sequence wins rather than first-row ordering assumptions.
    original_list = getattr(mod, "list_blackbox_events", None); original_get = getattr(mod, "get_blackbox_event", None)
    fake = {
        "BBE-SRG-1": {"event_id": "BBE-SRG-1", "sequence": 10, "event_type": "chat_turn", "started_at": "2026-01-01T00:00:00+00:00", "status": "execution_complete", "provider": "selftest", "model": "python"},
        "BBE-SRG-2": {"event_id": "BBE-SRG-2", "sequence": 12, "event_type": "chat_turn", "started_at": "2026-01-01T00:02:00+00:00", "status": "execution_complete", "provider": "selftest", "model": "python"},
        "BBE-SRG-3": {"event_id": "BBE-SRG-3", "sequence": 11, "event_type": "chat_turn", "started_at": "2026-01-01T00:03:00+00:00", "status": "execution_complete", "provider": "selftest", "model": "python"},
    }
    try:
        mod.list_blackbox_events = lambda limit=20: {"ok": True, "events": [fake["BBE-SRG-1"], fake["BBE-SRG-3"], fake["BBE-SRG-2"]]}
        mod.get_blackbox_event = lambda event_id, include_payloads=False: {"ok": True, "event": fake[str(event_id)], "actions": [], "outcomes": [{"outcome_id": "OUT", "created_at": fake[str(event_id)]["started_at"], "outcome_type": "execution_complete", "success": True}]}
        selected, selection = _srg_select_blackbox_turn(mod, "latest")
        selection_ok = selection.get("selected_event_id") == "BBE-SRG-2" and int(selection.get("selected_sequence") or 0) == 12
    finally:
        if original_list is not None: mod.list_blackbox_events = original_list
        if original_get is not None: mod.get_blackbox_event = original_get

    malicious = '<affective_update>{"identity_core_update":{"name":"replace"},"personality_updates":[{"field":"voice.warmth","requested_value":0.4,"reason":"proposal is okay","approve":true}],"active_continuity_update":{"current_focus":"keep","identity":"bad"},"session_handoff_update":{"permanent_commitments":["bad"]}}</affective_update>'
    sanitized, rejected = _srg_sanitize_affective_update(mod, malicious, provider="selftest", model="python")
    parsed = json.loads(_AFFECT_UPDATE_RE.search(sanitized).group(1))
    sanitize_ok = (
        "identity_core_update" not in parsed
        and "identity" not in (parsed.get("active_continuity_update") or {})
        and "approve" not in ((parsed.get("personality_updates") or [{}])[0])
        and "permanent_commitments" not in (parsed.get("session_handoff_update") or {})
        and len(rejected) >= 4
    )
    # Actor guard must reject a model-origin direct profile mutation without
    # needing to execute the underlying write.
    actor_guard_ok = True
    candidate = getattr(mod, "activate_personality_profile", None)
    if callable(candidate):
        guarded = _srg_guard_personality_api(mod, "activate_personality_profile", candidate)
        result = guarded("balanced", actor="model")
        actor_guard_ok = bool(isinstance(result, dict) and result.get("rejected"))
    rejections = _srg_read_rejections(mod, 20)
    reliability = get_state_reliability_status(mod, recent_rejections=5)
    checks = {
        "latest_selector_uses_highest_blackbox_sequence": selection_ok,
        "affective_direct_authority_keys_are_removed": sanitize_ok,
        "guard_rejections_are_encrypted_and_queryable": int(rejections.get("count") or 0) >= 1,
        "direct_model_personality_profile_mutation_is_rejected": actor_guard_ok,
        "state_validator_is_read_only": reliability.get("read_only") is True and int(reliability.get("model_calls") or 0) == 0 and int(reliability.get("web_calls") or 0) == 0,
        "validator_reports_registry": any(x.get("name") == "state_authority_registry" for x in reliability.get("checks") or []),
        "validator_reports_current_self": any(x.get("name") == "current_self_source_integrity" for x in reliability.get("checks") or []),
        "validator_reports_personality_core": any(x.get("name") == "immutable_personality_core" for x in reliability.get("checks") or []),
        "validator_reports_transition_integrity": any(x.get("name") == "recent_transition_receipt_hashes" for x in reliability.get("checks") or []),
    }
    return {"ok": all(bool(v) for v in checks.values()), "version": _STATE_RELIABILITY_VERSION, "checks": checks, "rejected_paths": [x.get("path") for x in rejected], "read_only_validator": True, "model_calls": 0, "web_calls": 0, "live_database_modified": False}


def _install_state_reliability_guards(module) -> None:
    if getattr(module, "_STATE_RELIABILITY_GUARDS_INSTALLED", False):
        return
    module.STATE_RELIABILITY_VERSION = _STATE_RELIABILITY_VERSION
    module.get_state_reliability_status = lambda recent_rejections=10: get_state_reliability_status(module, recent_rejections=recent_rejections)
    module.read_state_guard_rejections = lambda limit=20: _srg_read_rejections(module, limit)
    module.state_reliability_guards_self_test = lambda: state_reliability_guards_self_test(module)
    # Timeline installer captured the old function into its module lambda. Rebind
    # it here to the hardened selector/reporting version.
    module.get_state_timeline = lambda turn_id=None, minutes=60, limit=120: get_state_timeline(module, turn_id, minutes, limit)

    # Guard direct personality profile lifecycle methods. Proposal creation stays
    # model-accessible only as a proposal; user/admin/recovery remains required to
    # activate/retire/create/approve profile state.
    for attr in ("create_personality_profile", "activate_personality_profile", "retire_personality_profile", "resolve_personality_proposal"):
        original = getattr(module, attr, None)
        if callable(original):
            setattr(module, attr, _srg_guard_personality_api(module, attr, original))

    module.TOOL_SCHEMAS.extend([
        {"type":"function","function":{"name":"get_state_reliability_status","description":"Run a compact read-only reliability/invariant audit over the State Authority Registry, current_self source linkage, immutable personality core, emotion/somatic transition receipts, continuity reliability, and latest captured Black Box chat selection. No automatic repair.","parameters":{"type":"object","properties":{"recent_rejections":{"type":"integer","minimum":0,"maximum":100}},"additionalProperties":False}}},
        {"type":"function","function":{"name":"read_state_guard_rejections","description":"Read recent encrypted state-authority guard rejection events. Read-only; these are operational integrity events, not Assistant memories or identity.","parameters":{"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":False}}},
    ])
    allow = getattr(module, "_READ_ONLY_TEXT_TOOL_ALLOWLIST", None)
    if isinstance(allow, set): allow.update({"get_state_reliability_status", "read_state_guard_rejections"})
    old_execute = module.execute_tool
    def execute_with_state_reliability(name, arguments, seen, *args, **kwargs):
        if name == "get_state_reliability_status": return module.get_state_reliability_status(**dict(arguments or {}))
        if name == "read_state_guard_rejections": return module.read_state_guard_rejections(**dict(arguments or {}))
        return old_execute(name, arguments, seen, *args, **kwargs)
    module.execute_tool = execute_with_state_reliability

    old_main = module.main
    def main_with_state_reliability_commands():
        previous = builtins.input
        def reliability_input(prompt=""):
            while True:
                value = previous(prompt)
                if _srg_handle_command(module, value): continue
                return value
        builtins.input = reliability_input
        try: return old_main()
        finally: builtins.input = previous
    module.main = main_with_state_reliability_commands
    old_help = module.print_help
    def help_with_state_reliability(*args, **kwargs):
        old_help(*args, **kwargs)
        print("  /state validate | /state reliability | /state guard rejections [N]")
        print("      Compact read-only invariants + recent rejected authority-bypass attempts. No automatic repair or identity/personality writeback.")
        print("  /state timeline latest")
        print("      `latest` means latest captured Black Box chat turn by sequence; console/status commands are not chat-turn events. Selection metadata explains age/reason.")
    module.print_help = help_with_state_reliability
    module.NEATMEMORY_VERSION = BUNDLE_VERSION; module.RELEASE_NAME = RELEASE_NAME
    module._STATE_RELIABILITY_GUARDS_INSTALLED = True

# ---------------------------------------------------------------------------
# >>> NEAT-SUBSYSTEM:state-privacy-governance rev=4
# NeatMemory 7.4.74.0 — privacy, retention, export/backup coverage, and redaction governance
# ---------------------------------------------------------------------------
# This layer is intentionally governance/observability first. It does not silently
# delete Assistant/user history, change emotion/somatic math, or invent a new privacy
# authority. It makes the existing retention/export/encryption/authorship contract
# explicit, verifies it, and embeds a non-secret coverage manifest in portable
# backup payloads so a backup says what it does and does not contain.

_STATE_PRIVACY_VERSION = "1.3-neatcrypt-conversation-aware-privacy-governance"
_STATE_PRIVACY_SCHEMA = "neatmemory.state-privacy-governance.v1"
_STATE_PRIVACY_MANIFEST_KIND = "neatmemory_state_privacy_manifest"
_STATE_PRIVACY_MANIFEST_SCHEMA = "1"
_STATE_PRIVACY_DELETE_POLICY = "explicit-governed-lifecycle-only-no-automatic-sensitive-history-deletion"


