_NEATCRYPT_RESTORE_GUARD_MANIFEST = "guard.json"


def _nc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds")


def _nc_canonical(value) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _nc_sha(value) -> str:
    if isinstance(value, bytes): raw = value
    else: raw = _nc_canonical(value)
    return hashlib.sha256(raw).hexdigest()


def _nc_aesgcm():
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        return AESGCM
    except Exception as exc:
        raise RuntimeError("NeatCrypt requires the Python 'cryptography' package with AESGCM support.") from exc


def _nc_argon2id():
    try:
        from cryptography.hazmat.primitives.kdf.argon2 import Argon2id
        return Argon2id
    except Exception as exc:
        raise RuntimeError("NeatCrypt requires cryptography Argon2id support.") from exc


def _nc_validate_passphrase(passphrase: str, *, for_new: bool = False) -> bytes:
    value = str(passphrase or "")
    legacy_minimum = int(globals().get("_PORTABLE_BACKUP_MIN_PASSPHRASE") or 10)
    minimum = max(legacy_minimum, _NEATCRYPT_NEW_PASSPHRASE_MIN) if for_new else legacy_minimum
    if len(value) < minimum:
        raise ValueError(f"Backup passphrase must contain at least {minimum} characters.")
    return value.encode("utf-8")


def _nc_derive_wrap_key(passphrase: str, salt: bytes, *, iterations: int = _NEATCRYPT_ARGON2_ITERATIONS,
                        lanes: int = _NEATCRYPT_ARGON2_LANES, memory_kib: int = _NEATCRYPT_ARGON2_MEMORY_KIB) -> bytes:
    secret = _nc_validate_passphrase(passphrase)
    if len(salt) != _NEATCRYPT_ARGON2_SALT_BYTES:
        raise ValueError("NeatCrypt Argon2id salt length is invalid.")
    if not (
        1 <= int(iterations) <= _NEATCRYPT_ARGON2_MAX_ITERATIONS
        and 1 <= int(lanes) <= _NEATCRYPT_ARGON2_MAX_LANES
        and 8 * 1024 <= int(memory_kib) <= _NEATCRYPT_ARGON2_MAX_MEMORY_KIB
    ):
        raise ValueError("NeatCrypt Argon2id parameters are outside accepted safety bounds.")
    KDF = _nc_argon2id()
    return KDF(salt=salt, length=_NEATCRYPT_ARGON2_LENGTH, iterations=int(iterations), lanes=int(lanes), memory_cost=int(memory_kib)).derive(secret)


def _nc_chat_metadata_v1(timestamp, role, provider, model, is_private, content_sha256) -> dict:
    return {
        "timestamp": str(timestamp or ""),
        "role": str(role or ""),
        "provider": str(provider or ""),
        "model": str(model or ""),
        "is_private": 1 if bool(is_private) else 0,
        "content_sha256": str(content_sha256 or ""),
    }


def _nc_chat_storage_tag(master_key: bytes, content: str, message_id: int) -> str:
    if not isinstance(master_key, (bytes, bytearray)) or len(master_key) != _NEATCRYPT_MASTER_KEY_BYTES:
        raise ValueError("NeatCrypt master key is invalid.")
    mid = int(message_id or 0)
    if mid <= 0:
        raise ValueError("NeatCrypt NC2 requires a positive stable CHAT message_id.")
    subkey = hmac.new(bytes(master_key), _NEATCRYPT_CHAT_TAG_DOMAIN, hashlib.sha256).digest()
    material = mid.to_bytes(8, "big", signed=False) + str(content or "").encode("utf-8")
    return _NEATCRYPT_CHAT_TAG_PREFIX + hmac.new(subkey, material, hashlib.sha256).hexdigest()


def _nc_chat_metadata(message_id, timestamp, role, provider, model, is_private, content_auth_tag) -> dict:
    return {
        "message_id": int(message_id),
        "timestamp": str(timestamp or ""),
        "role": str(role or ""),
        "provider": str(provider or ""),
        "model": str(model or ""),
        "is_private": 1 if bool(is_private) else 0,
        "content_auth_tag": str(content_auth_tag or ""),
    }


def _nc_chat_encrypt(master_key: bytes, content: str, *, message_id, timestamp, role, provider, model, is_private,
                     content_sha256="", content_auth_tag: str | None = None) -> bytes:
    if not isinstance(master_key, (bytes, bytearray)) or len(master_key) != _NEATCRYPT_MASTER_KEY_BYTES:
        raise ValueError("NeatCrypt master key is invalid.")
    plain = str(content or "").encode("utf-8")
    digest = hashlib.sha256(plain).hexdigest()
    if str(content_sha256 or "") and str(content_sha256) != digest:
        raise ValueError("Chat plaintext hash does not match content_sha256 before encryption.")
    tag = _nc_chat_storage_tag(master_key, str(content or ""), int(message_id))
    if content_auth_tag is not None and not hmac.compare_digest(str(content_auth_tag), tag):
        raise ValueError("NeatCrypt NC2 physical content tag does not match plaintext/CHAT identity.")
    meta = _nc_chat_metadata(message_id, timestamp, role, provider, model, is_private, tag)
    nonce = os.urandom(_NEATCRYPT_NONCE_BYTES)
    cipher = _nc_aesgcm()(bytes(master_key)).encrypt(nonce, plain, _NEATCRYPT_CHAT_AAD_PREFIX + _nc_canonical(meta))
    return _NEATCRYPT_MAGIC + nonce + cipher


def _nc_chat_decrypt(master_key: bytes, blob: bytes, *, message_id=None, timestamp, role, provider, model, is_private, content_sha256) -> str:
    raw = bytes(blob or b"")
    magic = raw[:3]
    if magic not in {_NEATCRYPT_LEGACY_MAGIC, _NEATCRYPT_MAGIC} or len(raw) <= 3 + _NEATCRYPT_NONCE_BYTES + 16:
        raise ValueError("NeatCrypt chat ciphertext envelope is invalid.")
    nonce = raw[3:3+_NEATCRYPT_NONCE_BYTES]
    cipher = raw[3+_NEATCRYPT_NONCE_BYTES:]
    if magic == _NEATCRYPT_LEGACY_MAGIC:
        meta = _nc_chat_metadata_v1(timestamp, role, provider, model, is_private, content_sha256)
        aad = _NEATCRYPT_CHAT_AAD_PREFIX_V1 + _nc_canonical(meta)
    else:
        if int(message_id or 0) <= 0:
            raise ValueError("NeatCrypt NC2 CHAT identity is missing.")
        if not str(content_sha256 or "").startswith(_NEATCRYPT_CHAT_TAG_PREFIX):
            raise ValueError("NeatCrypt NC2 physical content tag is invalid.")
        meta = _nc_chat_metadata(message_id, timestamp, role, provider, model, is_private, content_sha256)
        aad = _NEATCRYPT_CHAT_AAD_PREFIX + _nc_canonical(meta)
    try:
        plain = _nc_aesgcm()(bytes(master_key)).decrypt(nonce, cipher, aad)
    except Exception as exc:
        raise ValueError("NeatCrypt chat decryption/authentication failed.") from exc
    digest = hashlib.sha256(plain).hexdigest()
    text = plain.decode("utf-8")
    if magic == _NEATCRYPT_LEGACY_MAGIC:
        if digest != str(content_sha256 or ""):
            raise ValueError("NeatCrypt legacy chat plaintext hash verification failed.")
    else:
        expected_tag = _nc_chat_storage_tag(master_key, text, int(message_id))
        if not hmac.compare_digest(expected_tag, str(content_sha256 or "")):
            raise ValueError("NeatCrypt NC2 keyed content-tag verification failed.")
    return text


def _nc_chat_plain_sha(master_key: bytes, blob: bytes, **metadata) -> str:
    text = _nc_chat_decrypt(master_key, blob, **metadata)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _nc_chat_fault_detail(row: dict, exc: BaseException) -> dict:
    """Return bounded non-secret diagnostics for one unreadable encrypted CHAT row."""
    message = str(exc or "")[:500]
    folded = message.casefold()
    if "authentication failed" in folded or "decryption/authentication failed" in folded:
        classification = "AUTHENTICATION_FAILED"
    elif "keyed content-tag" in folded:
        classification = "CONTENT_TAG_MISMATCH"
    elif "ciphertext envelope" in folded:
        classification = "CIPHERTEXT_ENVELOPE_INVALID"
    elif "identity is missing" in folded:
        classification = "CHAT_IDENTITY_INVALID"
    elif "content tag is invalid" in folded:
        classification = "PHYSICAL_CONTENT_TAG_INVALID"
    else:
        classification = "DECRYPT_OR_INTEGRITY_ERROR"
    cause = getattr(exc, "__cause__", None) or getattr(exc, "__context__", None)
    detail = {
        "message_id": int(row.get("message_id") or 0),
        "timestamp": str(row.get("timestamp") or ""),
        "role": str(row.get("role") or ""),
        "provider": str(row.get("provider") or ""),
        "model": str(row.get("model") or ""),
        "encryption_version": str(row.get("encryption_version") or ""),
        "classification": classification,
        "error_type": type(exc).__name__,
        "error": message,
    }
    if cause is not None:
        detail["cause_type"] = type(cause).__name__
        cause_text = str(cause or "").strip()
        if cause_text:
            detail["cause"] = cause_text[:300]
    return detail


def _nc_decrypt_physical_chat_row(master_key: bytes, row: dict) -> dict:
    """Authenticate/decrypt one physical CHAT row without the SQLite UDF/view."""
    content = _nc_chat_decrypt(
        master_key,
        bytes(row.get("content_cipher") or b""),
        message_id=row.get("message_id"),
        timestamp=row.get("timestamp"),
        role=row.get("role"),
        provider=row.get("provider"),
        model=row.get("model"),
        is_private=row.get("is_private"),
        content_sha256=row.get("content_sha256"),
    )
    return {
        "message_id": int(row.get("message_id") or 0),
        "timestamp": str(row.get("timestamp") or ""),
        "role": str(row.get("role") or ""),
        "provider": str(row.get("provider") or ""),
        "model": str(row.get("model") or ""),
        "content": content,
        "is_private": int(row.get("is_private") or 0),
        # Logical callers historically receive the plaintext SHA through the
        # compatibility view; never expose the keyed physical H1 tag as that SHA.
        "content_sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
        "encryption_version": str(row.get("encryption_version") or ""),
    }


def _nc_fault_isolated_recent_messages(
    module,
    limit: int | None = None,
    char_cap: int | None = None,
    *,
    adaptive_expand: bool = False,
    hard_token_cap: int | None = None,
) -> tuple[list[dict], dict]:
    """Read RECENT directly from encrypted rows while isolating row-level faults.

    This path is intentionally narrower than backup/integrity verification:
    unreadable rows remain physically untouched and are skipped only for ordinary
    RECENT delivery. Strict backup/restore/forensic reads continue to fail closed.
    """
    configured_count = getattr(module, "configured_chat_load", lambda: 8)()
    configured_cap = getattr(module, "configured_chat_char_cap", lambda: 7000)()
    explicit_bound = limit is not None or char_cap is not None
    use_adaptive = bool(adaptive_expand and not explicit_bound and int(hard_token_cap or 0) > 0)
    count = None if use_adaptive else (configured_count if limit is None else max(0, int(limit)))
    cap = None if use_adaptive else (configured_cap if char_cap is None else max(1000, int(char_cap)))
    hard_tokens = max(1, int(hard_token_cap or 1)) if use_adaptive else None
    intake = {
        "version": "1.0-neatcrypt-row-fault-isolated-recent",
        "configured_message_hint": int(configured_count),
        "configured_character_hint": int(configured_cap),
        "adaptive_expand": bool(adaptive_expand),
        "legacy_config_limit_applied": bool(not use_adaptive and not explicit_bound),
        "hard_token_scan_ceiling": int(hard_token_cap or 0) if use_adaptive else None,
        "raw_public_messages_available": None,
        "raw_public_characters_available": None,
        "raw_public_characters_known": False,
        "rows_loaded": 0,
        "characters_loaded": 0,
        "estimated_loaded_tokens": 0,
        "stopped_by_hard_token_scan_ceiling": False,
        "limit_type": "PROVIDER_DERIVED_HARD_SCAN" if use_adaptive else "EXPLICIT_OR_CONFIGURED_BOUND",
        "fault_isolation_active": True,
        "encrypted_rows_scanned": 0,
        "unreadable_rows_skipped": 0,
        "unreadable_chat_ids": [],
    }
    if not use_adaptive and int(count or 0) <= 0:
        return [], intake
    key = _nc_read_local_key(module, required=True)
    base = getattr(module, "_NEATCRYPT_BASE_DB_CONNECT", module.db_connect)
    selected_newest_first = []
    failures = []
    used_chars = 0
    used_tokens = 0
    estimator = getattr(module, "_adaptive_estimate_tokens", lambda value: max(1, (len(str(value or "")) + 3) // 4))
    with base() as db:
        try:
            db.row_factory = sqlite3.Row
        except Exception:
            pass
        total = db.execute(
            f"SELECT COUNT(*) AS n FROM {_NEATCRYPT_SECURE_CHAT_TABLE} "
            "WHERE is_private=0 AND role IN ('user','assistant')"
        ).fetchone()
        if total is not None:
            try:
                intake["raw_public_messages_available"] = int(total["n"])
            except Exception:
                intake["raw_public_messages_available"] = int(total[0] or 0)
        cursor = db.execute(
            f"SELECT message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version "
            f"FROM {_NEATCRYPT_SECURE_CHAT_TABLE} "
            "WHERE is_private=0 AND role IN ('user','assistant') ORDER BY message_id DESC"
        )
        for raw in cursor:
            row = dict(raw)
            intake["encrypted_rows_scanned"] += 1
            try:
                logical = _nc_decrypt_physical_chat_row(key, row)
            except Exception as exc:
                failures.append(_nc_chat_fault_detail(row, exc))
                continue
            original = str(logical.get("content") or "")
            delivered = original
            delivery_offset = 0
            if use_adaptive:
                row_tokens = int(estimator(original)) + 96
                if selected_newest_first and used_tokens + row_tokens > hard_tokens:
                    intake["stopped_by_hard_token_scan_ceiling"] = True
                    break
                if not selected_newest_first and row_tokens > hard_tokens:
                    lo, hi = 0, len(original)
                    while lo < hi:
                        mid = (lo + hi + 1) // 2
                        piece = original[-mid:]
                        if int(estimator(piece)) + 96 <= hard_tokens:
                            lo = mid
                        else:
                            hi = mid - 1
                    delivered = original[-lo:] if lo > 0 else ""
                    delivery_offset = max(0, len(original) - len(delivered))
                    row_tokens = int(estimator(delivered)) + 96 if delivered else 0
                    intake["stopped_by_hard_token_scan_ceiling"] = True
            else:
                if selected_newest_first and used_chars + len(original) > int(cap):
                    break
                if len(original) > int(cap) and not selected_newest_first:
                    delivery_offset = max(0, len(original) - int(cap))
                    delivered = original[-int(cap):]
                row_tokens = int(estimator(delivered)) + 96 if delivered else 0
            selected_newest_first.append({
                "message_id": logical.get("message_id"),
                "timestamp": logical.get("timestamp"),
                "role": logical.get("role"),
                "provider": logical.get("provider"),
                "model": logical.get("model"),
                "content": delivered,
                "content_sha256": logical.get("content_sha256"),
                "delivered_content_sha256": hashlib.sha256(delivered.encode("utf-8", "replace")).hexdigest(),
                "delivery_char_offset": delivery_offset,
                "delivery_truncated": delivered != original,
            })
            used_chars += len(delivered)
            used_tokens += row_tokens
            if not use_adaptive and len(selected_newest_first) >= int(count):
                break
            if use_adaptive and used_tokens >= int(hard_tokens):
                intake["stopped_by_hard_token_scan_ceiling"] = True
                break
    selected_newest_first.reverse()
    intake["rows_loaded"] = len(selected_newest_first)
    intake["characters_loaded"] = int(used_chars)
    intake["estimated_loaded_tokens"] = int(used_tokens)
    intake["unreadable_rows_skipped"] = len(failures)
    intake["unreadable_chat_ids"] = [int(x.get("message_id") or 0) for x in failures[:50]]
    module._NEATCRYPT_CHAT_FAULTS_LAST = [dict(x) for x in failures[:50]]
    module._NEATCRYPT_CHAT_FAULT_ISOLATION_LAST = dict(intake)
    return selected_newest_first, intake


def _nc_recent_public_messages_safe(module, limit: int | None = None, char_cap: int | None = None) -> list[dict]:
    rows, intake = _nc_fault_isolated_recent_messages(module, limit=limit, char_cap=char_cap)
    module._RECENT_CHAT_INTAKE_LAST = dict(intake)
    return [{"role": str(row.get("role") or ""), "content": str(row.get("content") or "")} for row in rows]


def _nc_chat_doctor(module) -> dict:
    """Read-only authenticated scan of every physical encrypted CHAT row."""
    key = _nc_read_local_key(module, required=False)
    result = {
        "ok": False,
        "version": "1.0-read-only-chat-row-integrity-doctor",
        "read_only": True,
        "database_modified": False,
        "model_calls": 0,
        "web_calls": 0,
        "master_key_available": key is not None,
        "secure_chat_present": _nc_secure_chat_exists(module),
        "secure_rows": 0,
        "scanned_rows": 0,
        "decryptable_rows": 0,
        "failed_rows": 0,
        "failures": [],
        "normal_recent_policy": "Unreadable rows are preserved and skipped only for ordinary RECENT delivery; portable backup snapshots preserve opaque encrypted rows verbatim and report degradation; master-key rotation and destructive integrity transforms remain fail-closed.",
    }
    if key is None:
        result["status"] = "LOCKED_MASTER_KEY_UNAVAILABLE"
        return result
    base = getattr(module, "_NEATCRYPT_BASE_DB_CONNECT", module.db_connect)
    failures = []
    versions = {}
    with base() as db:
        try:
            db.row_factory = sqlite3.Row
            db.execute("PRAGMA query_only=ON")
        except Exception:
            pass
        if _nc_object_type(db, _NEATCRYPT_SECURE_CHAT_TABLE) != "table":
            result["status"] = "SECURE_CHAT_TABLE_MISSING"
            return result
        rows = db.execute(
            f"SELECT message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version "
            f"FROM {_NEATCRYPT_SECURE_CHAT_TABLE} ORDER BY message_id"
        )
        for raw in rows:
            row = dict(raw)
            result["scanned_rows"] += 1
            version = str(row.get("encryption_version") or "UNKNOWN")
            versions[version] = int(versions.get(version, 0)) + 1
            try:
                _nc_decrypt_physical_chat_row(key, row)
                result["decryptable_rows"] += 1
            except Exception as exc:
                failures.append(_nc_chat_fault_detail(row, exc))
    result["secure_rows"] = int(result["scanned_rows"])
    result["failed_rows"] = len(failures)
    result["failures"] = failures[:200]
    result["failures_truncated"] = len(failures) > 200
    result["encryption_versions"] = versions
    result["ok"] = len(failures) == 0
    result["status"] = "HEALTHY" if result["ok"] else "DEGRADED_UNREADABLE_ROWS"
    return result


def _nc_handle_doctor_command(module, raw: str) -> bool:
    clean = " ".join(str(raw or "").strip().split())
    lower = clean.casefold()
    if lower not in {"/doctor chat", "/doctor chat scan", "/doctor chat status"}:
        return False
    try:
        print(json.dumps(_nc_chat_doctor(module), ensure_ascii=False, indent=2))
    except Exception as exc:
        print(json.dumps({
            "ok": False,
            "status": "DOCTOR_ERROR",
            "read_only": True,
            "database_modified": False,
            "model_calls": 0,
            "web_calls": 0,
            "error": f"{type(exc).__name__}: {exc}",
        }, ensure_ascii=False, indent=2))
    return True


def _nc_keyring_path(module) -> Path:
    return Path(module.safe_memory_path(_NEATCRYPT_KEYRING_FILE))


def _nc_prepare_local_key_blob(master_key: bytes) -> bytes:
    if len(master_key) != _NEATCRYPT_MASTER_KEY_BYTES:
        raise ValueError("NeatCrypt master key length is invalid.")
    crypto = _identity_crypto()
    payload = json.dumps({"kind":"neatcrypt-local-keyring","version":"1","master_key_b64":base64.b64encode(master_key).decode("ascii")}, separators=(",", ":"))
    encrypted = crypto.encrypt_text(payload, entropy=_NEATCRYPT_KEYRING_ENTROPY)
    verified = crypto.decrypt_text(encrypted, entropy=_NEATCRYPT_KEYRING_ENTROPY)
    if verified != payload:
        raise RuntimeError("NeatCrypt local key-wrapper readback verification failed.")
    return encrypted


def _nc_write_local_key(module, master_key: bytes, *, prepared_blob: bytes | None = None) -> Path:
    encrypted = bytes(prepared_blob) if prepared_blob is not None else _nc_prepare_local_key_blob(master_key)
    path = _nc_keyring_path(module)
    _bf_atomic_bytes(path, encrypted)
    # Do not switch the in-memory key until the on-disk local wrapper has itself
    # been decrypted and compared.  This closes the rotation/keyring split-brain
    # case where a nominal write succeeds but leaves an unusable local wrapper.
    verified_text = _identity_crypto().decrypt_text(path.read_bytes(), entropy=_NEATCRYPT_KEYRING_ENTROPY)
    verified_payload = json.loads(verified_text)
    verified_key = base64.b64decode(str(verified_payload.get("master_key_b64") or ""), validate=True)
    if verified_payload.get("kind") != "neatcrypt-local-keyring" or not hmac.compare_digest(verified_key, bytes(master_key)):
        raise RuntimeError("NeatCrypt local key-wrapper post-write verification failed.")
    module._NEATCRYPT_MASTER_KEY_CACHE = bytes(master_key)
    return path


def _nc_read_local_key(module, *, required: bool = False) -> bytes | None:
    cached = getattr(module, "_NEATCRYPT_MASTER_KEY_CACHE", None)
    if isinstance(cached, (bytes, bytearray)) and len(cached) == _NEATCRYPT_MASTER_KEY_BYTES:
        return bytes(cached)
    path = _nc_keyring_path(module)
    if not path.exists():
        if required: raise RuntimeError("NeatCrypt local master-key wrapper is missing. Use /backup load <file.nacb> to recover with the portable passphrase.")
        return None
    try:
        text = _identity_crypto().decrypt_text(path.read_bytes(), entropy=_NEATCRYPT_KEYRING_ENTROPY)
        data = json.loads(text)
        key = base64.b64decode(str(data.get("master_key_b64") or ""), validate=True)
        if data.get("kind") != "neatcrypt-local-keyring" or len(key) != _NEATCRYPT_MASTER_KEY_BYTES:
            raise ValueError("invalid local keyring payload")
        module._NEATCRYPT_MASTER_KEY_CACHE = key
        return key
    except Exception as exc:
        if required:
            raise RuntimeError("NeatCrypt local key cannot be unlocked on this Windows profile. Restore from an Assistant Continuity Backup with /backup load <file.nacb>.") from exc
        return None


def _nc_object_type(db, name: str) -> str:
    row = db.execute("SELECT type FROM sqlite_master WHERE name=? ORDER BY CASE type WHEN 'table' THEN 0 WHEN 'view' THEN 1 ELSE 2 END LIMIT 1", (name,)).fetchone()
    return str(row[0]) if row else "missing"


def _nc_secure_chat_exists(module) -> bool:
    base = getattr(module, "_NEATCRYPT_BASE_DB_CONNECT", module.db_connect)
    try:
        with base() as db:
            return _nc_object_type(db, _NEATCRYPT_SECURE_CHAT_TABLE) == "table" and _nc_object_type(db, _NEATCRYPT_CHAT_VIEW) == "view"
    except Exception:
        return False


def _nc_register_udfs(module, db) -> None:
    key = _nc_read_local_key(module, required=False)
    def content_tag(content, message_id, digest):
        if key is None: raise RuntimeError("NeatCrypt chat store is locked; portable recovery is required.")
        text = str(content or "")
        actual = hashlib.sha256(text.encode("utf-8")).hexdigest()
        if str(digest or "") and not hmac.compare_digest(str(digest), actual):
            raise ValueError("Logical chat content_sha256 does not match plaintext.")
        return _nc_chat_storage_tag(key, text, int(message_id))
    def enc(content, message_id, timestamp, role, provider, model, is_private, stored_tag):
        if key is None: raise RuntimeError("NeatCrypt chat store is locked; use /backup load <file.nacb>.")
        return sqlite3.Binary(_nc_chat_encrypt(
            key, str(content or ""), message_id=message_id, timestamp=timestamp, role=role,
            provider=provider, model=model, is_private=is_private, content_auth_tag=stored_tag,
        ))
    def dec(blob, message_id, timestamp, role, provider, model, is_private, stored_tag):
        if key is None: raise RuntimeError("NeatCrypt chat store is locked; use /backup load <file.nacb>.")
        return _nc_chat_decrypt(
            key, bytes(blob or b""), message_id=message_id, timestamp=timestamp, role=role,
            provider=provider, model=model, is_private=is_private, content_sha256=stored_tag,
        )
    def plain_sha(blob, message_id, timestamp, role, provider, model, is_private, stored_tag):
        if key is None: raise RuntimeError("NeatCrypt chat store is locked; use /backup load <file.nacb>.")
        return _nc_chat_plain_sha(
            key, bytes(blob or b""), message_id=message_id, timestamp=timestamp, role=role,
            provider=provider, model=model, is_private=is_private, content_sha256=stored_tag,
        )
    # NC2 functions. The legacy seven-argument decrypt remains registered so an
    # already-open NC1 compatibility view can be read while startup replaces it.
    db.create_function("neatcrypt_chat_content_tag", 3, content_tag)
    db.create_function("neatcrypt_encrypt_chat", 8, enc)
    db.create_function("neatcrypt_decrypt_chat", 8, dec)
    db.create_function("neatcrypt_plain_chat_sha256", 8, plain_sha)
    db.create_function("neatcrypt_encrypt_chat", 7, lambda *args: (_ for _ in ()).throw(RuntimeError("Legacy NeatCrypt write trigger must be upgraded before writing.")))
    db.create_function("neatcrypt_decrypt_chat", 7, lambda blob,timestamp,role,provider,model,is_private,digest: _nc_chat_decrypt(
        key, bytes(blob or b""), timestamp=timestamp, role=role, provider=provider,
        model=model, is_private=is_private, content_sha256=digest,
    ) if key is not None else (_ for _ in ()).throw(RuntimeError("NeatCrypt chat store is locked.")))


def _nc_install_db_wrapper(module) -> None:
    if getattr(module, "_NEATCRYPT_DB_WRAPPED", False): return
    base = module.db_connect
    module._NEATCRYPT_BASE_DB_CONNECT = base
    def wrapped():
        db = base()
        _nc_register_udfs(module, db)
        return db
    module.db_connect = wrapped
    module._NEATCRYPT_DB_WRAPPED = True


# The embedded legacy initializer still owns the original plaintext schema. On a
# subsequent encrypted launch, CREATE TABLE IF NOT EXISTS accepts the existing
# logical chat_messages view, but SQLite correctly rejects its following CREATE
# INDEX because views cannot be indexed. Keep the mature logical schema intact and
# suppress only that one obsolete physical-index statement while the initializer
# runs. The equivalent encrypted physical index is created below.
_NEATCRYPT_LEGACY_CHAT_INDEX_RE = re.compile(
    r"\bCREATE\s+INDEX\s+IF\s+NOT\s+EXISTS\s+idx_chat_messages_timestamp\s+"
    r"ON\s+(?:main\s*\.\s*)?chat_messages\s*\(\s*timestamp\s*\)\s*;?",
    re.IGNORECASE,
)


def _nc_filter_legacy_initializer_script(script: str) -> tuple[str, int]:
    return _NEATCRYPT_LEGACY_CHAT_INDEX_RE.subn(
        "-- NeatCrypt: chat_messages is a view; its physical timestamp index is on chat_messages_secure;",
        str(script or ""),
    )


class _NCInitializerConnectionProxy:
    """Delegate SQLite work while removing only the obsolete view-index DDL."""

    def __init__(self, connection):
        object.__setattr__(self, "_connection", connection)

    def __getattr__(self, name):
        return getattr(self._connection, name)

    def __setattr__(self, name, value):
        setattr(self._connection, name, value)

    def __enter__(self):
        self._connection.__enter__()
        return self

    def __exit__(self, exc_type, exc, traceback):
        return self._connection.__exit__(exc_type, exc, traceback)

    def executescript(self, script):
        filtered, _ = _nc_filter_legacy_initializer_script(script)
        return self._connection.executescript(filtered)


def _nc_run_initializer_with_secure_chat_view(module, initializer):
    """Run legacy initialization without dropping or replacing encrypted chat."""
    original_connect = module.db_connect

    def initializer_connect():
        return _NCInitializerConnectionProxy(original_connect())

    module.db_connect = initializer_connect
    try:
        return initializer()
    finally:
        module.db_connect = original_connect


def _nc_create_secure_schema(db) -> None:
    db.execute(f"""CREATE TABLE IF NOT EXISTS {_NEATCRYPT_SECURE_CHAT_TABLE}(
        message_id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        role TEXT NOT NULL,
        provider TEXT NOT NULL,
        model TEXT NOT NULL,
        content_cipher BLOB NOT NULL,
        is_private INTEGER NOT NULL DEFAULT 0,
        content_sha256 TEXT NOT NULL,
        encryption_version TEXT NOT NULL DEFAULT 'NC1'
    )""")
    db.execute(f"CREATE INDEX IF NOT EXISTS idx_{_NEATCRYPT_SECURE_CHAT_TABLE}_timestamp ON {_NEATCRYPT_SECURE_CHAT_TABLE}(timestamp)")


def _nc_create_compatibility_view(db) -> None:
    db.execute(f"DROP VIEW IF EXISTS {_NEATCRYPT_CHAT_VIEW}")
    db.execute(f"""CREATE VIEW {_NEATCRYPT_CHAT_VIEW} AS
        SELECT message_id,timestamp,role,provider,model,
               neatcrypt_decrypt_chat(content_cipher,message_id,timestamp,role,provider,model,is_private,content_sha256) AS content,
               is_private,
               neatcrypt_plain_chat_sha256(content_cipher,message_id,timestamp,role,provider,model,is_private,content_sha256) AS content_sha256
        FROM {_NEATCRYPT_SECURE_CHAT_TABLE}""")
    for name in ("neatcrypt_chat_insert", "neatcrypt_chat_update", "neatcrypt_chat_delete"):
        db.execute(f"DROP TRIGGER IF EXISTS {name}")
    db.execute(f"""CREATE TRIGGER neatcrypt_chat_insert INSTEAD OF INSERT ON {_NEATCRYPT_CHAT_VIEW}
        BEGIN
          INSERT INTO {_NEATCRYPT_SECURE_CHAT_TABLE}(message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version)
          VALUES(NEW.message_id,NEW.timestamp,NEW.role,NEW.provider,NEW.model,
                 X'',COALESCE(NEW.is_private,0),'pending','NC2');
          UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE}
             SET content_sha256=neatcrypt_chat_content_tag(NEW.content,message_id,NEW.content_sha256)
           WHERE rowid=last_insert_rowid();
          UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE}
             SET content_cipher=neatcrypt_encrypt_chat(NEW.content,message_id,timestamp,role,provider,model,is_private,content_sha256)
           WHERE rowid=last_insert_rowid();
        END""")
    db.execute(f"""CREATE TRIGGER neatcrypt_chat_update INSTEAD OF UPDATE ON {_NEATCRYPT_CHAT_VIEW}
        BEGIN
          UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE}
             SET timestamp=NEW.timestamp,role=NEW.role,provider=NEW.provider,model=NEW.model,
                 message_id=NEW.message_id,content_cipher=X'',
                 is_private=COALESCE(NEW.is_private,0),content_sha256='pending',encryption_version='NC2'
           WHERE message_id=OLD.message_id;
          UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE}
             SET content_sha256=neatcrypt_chat_content_tag(NEW.content,message_id,NEW.content_sha256)
           WHERE message_id=NEW.message_id;
          UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE}
             SET content_cipher=neatcrypt_encrypt_chat(NEW.content,message_id,timestamp,role,provider,model,is_private,content_sha256)
           WHERE message_id=NEW.message_id;
        END""")
    db.execute(f"""CREATE TRIGGER neatcrypt_chat_delete INSTEAD OF DELETE ON {_NEATCRYPT_CHAT_VIEW}
        BEGIN DELETE FROM {_NEATCRYPT_SECURE_CHAT_TABLE} WHERE message_id=OLD.message_id; END""")


def _nc_upsert_setting_db(db, key: str, value: str) -> None:
    columns = {str(row[1]): row for row in db.execute("PRAGMA table_info(app_settings)").fetchall()}
    if "updated_at" in columns:
        db.execute(
            "INSERT INTO app_settings(key,value,updated_at) VALUES(?,?,?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",
            (str(key), str(value), _nc_now()),
        )
    else:
        db.execute(
            "INSERT INTO app_settings(key,value) VALUES(?,?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
            (str(key), str(value)),
        )


def _nc_disable_plaintext_fts(module) -> None:
    try:
        with module.db_connect() as db:
            db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_TABLE}")
            db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_META_TABLE}")
    except Exception:
        pass


def _nc_verify_secure_rows(module, master_key: bytes, expected_rows: list[dict] | None = None) -> dict:
    with module.db_connect() as db:
        rows = db.execute(f"SELECT message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256 FROM {_NEATCRYPT_SECURE_CHAT_TABLE} ORDER BY message_id").fetchall()
    decoded = []
    for row in rows:
        content = _nc_chat_decrypt(
            master_key, bytes(row["content_cipher"]), message_id=row["message_id"],
            timestamp=row["timestamp"], role=row["role"], provider=row["provider"],
            model=row["model"], is_private=row["is_private"], content_sha256=row["content_sha256"],
        )
        decoded.append({
            "message_id":int(row["message_id"]),"timestamp":str(row["timestamp"]),
            "role":str(row["role"]),"provider":str(row["provider"]),"model":str(row["model"]),
            "content":content,"is_private":int(row["is_private"] or 0),
            "content_sha256":hashlib.sha256(content.encode("utf-8")).hexdigest(),
        })
    exact = True
    if expected_rows is not None:
        exact = decoded == expected_rows
    return {"ok": exact, "row_count": len(decoded), "rows": decoded if expected_rows is not None else None}


def _nc_encrypt_known_row(master_key: bytes, row: dict) -> tuple[bytes, str]:
    mid = int(row.get("message_id") or 0)
    content = str(row.get("content") or "")
    digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
    stored = str(row.get("content_sha256") or "")
    if stored and not hmac.compare_digest(stored, digest):
        raise ValueError(f"Canonical chat hash mismatch at CHAT-{mid} before NC2 encryption.")
    tag = _nc_chat_storage_tag(master_key, content, mid)
    cipher = _nc_chat_encrypt(
        master_key, content, message_id=mid, timestamp=row.get("timestamp"), role=row.get("role"),
        provider=row.get("provider"), model=row.get("model"), is_private=row.get("is_private"),
        content_sha256=digest, content_auth_tag=tag,
    )
    # Exact authenticated readback occurs before any plaintext table is retired.
    check = _nc_chat_decrypt(
        master_key, cipher, message_id=mid, timestamp=row.get("timestamp"), role=row.get("role"),
        provider=row.get("provider"), model=row.get("model"), is_private=row.get("is_private"),
        content_sha256=tag,
    )
    if check != content:
        raise RuntimeError(f"NeatCrypt NC2 pre-commit readback failed at CHAT-{mid}.")
    return cipher, tag


def _nc_replace_secure_rows(db, master_key: bytes, rows: list[dict]) -> None:
    _nc_create_secure_schema(db)
    db.execute(f"DELETE FROM {_NEATCRYPT_SECURE_CHAT_TABLE}")
    for row in rows:
        cipher, tag = _nc_encrypt_known_row(master_key, row)
        db.execute(
            f"INSERT INTO {_NEATCRYPT_SECURE_CHAT_TABLE}(message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version) VALUES(?,?,?,?,?,?,?,?,?)",
            (int(row["message_id"]),str(row.get("timestamp") or ""),str(row.get("role") or ""),
             str(row.get("provider") or ""),str(row.get("model") or ""),sqlite3.Binary(cipher),
             int(row.get("is_private") or 0),tag,"NC2"),
        )


def _nc_retire_plaintext_mirror(module) -> dict:
    try: path = Path(module.safe_memory_path(str(getattr(module, "RAW_CONVERSATION_FILE", "raw_conversation.txt"))))
    except Exception: path = Path.cwd() / "raw_conversation.txt"
    existed = path.exists()
    size = path.stat().st_size if existed else 0
    if existed: path.unlink()
    try: module.set_setting(_NEATCRYPT_PLAINTEXT_RETIRE_SETTING, "1")
    except Exception: pass
    return {"path":str(path),"existed":existed,"bytes_removed_from_active_filesystem":size,"deleted":existed and not path.exists(),"secure_erase_claimed":False,"note":"Filesystem deletion is not claimed to physically erase prior SSD/storage remnants."}


def _nc_migrate_chat(module, master_key: bytes, *, expected_rows: list[dict] | None = None) -> dict:
    base = getattr(module, "_NEATCRYPT_BASE_DB_CONNECT", module.db_connect)
    with base() as probe:
        typ = _nc_object_type(probe, _NEATCRYPT_CHAT_VIEW)
        secure_type = _nc_object_type(probe, _NEATCRYPT_SECURE_CHAT_TABLE)
    if typ not in {"table", "missing"}:
        if not (typ == "view" and secure_type == "table"):
            raise RuntimeError(f"Unsupported chat_messages object type during NeatCrypt migration: {typ}")
    plaintext_rows = list(expected_rows) if expected_rows is not None else (_bf_collect_chat_rows(module) if typ in {"table","view"} else [])
    mode = "upgraded_to_nc2" if typ == "view" and secure_type == "table" else "migrated"
    with module.db_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            _nc_replace_secure_rows(db, master_key, plaintext_rows)
            physical = db.execute(f"SELECT COUNT(*) AS n FROM {_NEATCRYPT_SECURE_CHAT_TABLE}").fetchone()
            if int(physical["n"] if physical is not None else 0) != len(plaintext_rows):
                raise RuntimeError("NeatCrypt migration row-count verification failed before plaintext retirement.")
            if typ == "table": db.execute(f"DROP TABLE {_NEATCRYPT_CHAT_VIEW}")
            _nc_create_compatibility_view(db)
            db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_TABLE}")
            db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_META_TABLE}")
            _nc_upsert_setting_db(db, _NEATCRYPT_SETTING, _NEATCRYPT_CHAT_VERSION)
            db.commit()
        except Exception:
            db.rollback(); raise
    verified = _nc_verify_secure_rows(module, master_key, plaintext_rows)
    if not verified.get("ok"):
        raise RuntimeError("NeatCrypt post-migration decrypt/hash readback did not match canonical plaintext chat snapshot.")
    mirror = _nc_retire_plaintext_mirror(module)
    _nc_activate_chat_runtime(module)
    return {"ok":True,"mode":mode,"row_count":len(plaintext_rows),"plaintext_table_removed":True,"physical_ciphertext_verified":True,"raw_mirror":mirror,"nc2_rows":len(plaintext_rows)}


def _nc_append_public_message(module, role: str, content: str, *, provider: str, model: str) -> int:
    key = _nc_read_local_key(module, required=True)
    timestamp = module.utc_now() if hasattr(module, "utc_now") else _nc_now()
    digest = hashlib.sha256(str(content).encode("utf-8")).hexdigest()
    with module.db_connect() as db:
        db.execute("BEGIN IMMEDIATE")
        cur = db.execute(
            f"INSERT INTO {_NEATCRYPT_SECURE_CHAT_TABLE}(timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version) VALUES(?,?,?,?,X'',0,'pending','NC2')",
            (timestamp,role,provider,model),
        )
        mid = int(cur.lastrowid)
        tag = _nc_chat_storage_tag(key, str(content), mid)
        cipher = _nc_chat_encrypt(
            key, str(content), message_id=mid, timestamp=timestamp, role=role, provider=provider,
            model=model, is_private=0, content_sha256=digest, content_auth_tag=tag,
        )
        db.execute(
            f"UPDATE {_NEATCRYPT_SECURE_CHAT_TABLE} SET content_cipher=?,content_sha256=? WHERE message_id=?",
            (sqlite3.Binary(cipher),tag,mid),
        )
        db.commit()
    return mid


def _nc_activate_chat_runtime(module) -> None:
    module.append_public_message=lambda role,content,*,provider,model:_nc_append_public_message(module,role,content,provider=provider,model=model)
    module.recent_public_messages=lambda limit=None,char_cap=None:_nc_recent_public_messages_safe(module,limit=limit,char_cap=char_cap)
    module.recent_raw_exchanges=lambda limit=2:_nc_recent_raw_exchanges(module,limit)
    module.get_chat_integrity_doctor=lambda:_nc_chat_doctor(module)
    module._NEATCRYPT_FAULT_ISOLATED_RECENT_READER=lambda limit=None,char_cap=None,adaptive_expand=False,hard_token_cap=None:_nc_fault_isolated_recent_messages(
        module,limit=limit,char_cap=char_cap,adaptive_expand=adaptive_expand,hard_token_cap=hard_token_cap
    )


def _nc_recent_raw_exchanges(module, limit: int = 2) -> list[list[dict]]:
    n = max(1, min(20, int(limit or 2)))
    try:
        rows, _ = _nc_fault_isolated_recent_messages(
            module, limit=n * 4 + 8, char_cap=100_000_000, adaptive_expand=False
        )
    except Exception:
        return []
    exchanges=[]; current=[]
    for row in rows:
        role=str(row.get("role") or "")
        if role == "user":
            if current: exchanges.append(current)
            current=[]
        current.append({
            "message_id":int(row.get("message_id") or 0),
            "timestamp":str(row.get("timestamp") or ""),
            "role":role,
            "provider":str(row.get("provider") or ""),
            "model":str(row.get("model") or ""),
            "content":str(row.get("content") or ""),
        })
    if current: exchanges.append(current)
    return exchanges[-n:]


def _nc_backup_root() -> Path:
    p=Path(os.path.expandvars(_NEATCRYPT_BACKUP_DIR)).expanduser()
    if not p.is_absolute(): p=Path.cwd()/p
    p.mkdir(parents=True, exist_ok=True)
    return p.resolve()


def _nc_backup_path(raw: str = "", *, for_write: bool = False) -> Path:
    text=os.path.expandvars(str(raw or "").strip().strip('"'))
    if not text:
        p=_nc_backup_root()/f"Assistant_Continuity_{datetime.now().strftime('%Y%m%d-%H%M%S')}{_NEATCRYPT_BACKUP_EXTENSION}"
    else:
        supplied=Path(text).expanduser(); supplied_was_absolute=supplied.is_absolute()
        p=supplied if supplied_was_absolute else Path.cwd()/supplied
        if p.suffix.casefold()!=_NEATCRYPT_BACKUP_EXTENSION: p=p.with_suffix(_NEATCRYPT_BACKUP_EXTENSION)
        p=p.resolve()
        # `/backup new` without a path writes into assistant_backups. For read-only
        # verify/restore, a bare basename should therefore find that same default
        # location before reporting FileNotFoundError. Explicit relative folders
        # and absolute paths retain their exact meaning.
        if not for_write and not p.exists() and not supplied_was_absolute and supplied.parent==Path("."):
            fallback=(_nc_backup_root()/p.name).resolve()
            if fallback.exists(): p=fallback
    if for_write:
        p.parent.mkdir(parents=True,exist_ok=True)
        if p.exists(): raise FileExistsError(f"Backup already exists: {p}")
    return p


def _nc_workshop_component(module) -> dict:
    exp=_bf_workshop_export_payload(module)
    files=[]
    for item in exp.get("files") or []:
        meta=dict(item.get("meta") or {}); payload=dict(item.get("payload") or {})
        files.append({"path":str(item.get("path") or meta.get("path") or ""),"meta":meta,"content":str(payload.get("content") or "")})
    return {"manifest":exp.get("manifest") or {},"files":files}


def _nc_workshop_for_restore(component: dict) -> dict:
    live_manifest=dict(component.get("manifest") or {})
    files={}
    for item in component.get("files") or []:
        logical=str(item.get("path") or "")
        files[logical]={"meta":dict(item.get("meta") or {}),"content":str(item.get("content") or "")}
    return {"live_manifest":live_manifest,"files":files}


def _nc_issue_component(module) -> dict:
    try:
        _ensure_issue_lifecycle_schema(module)
        with module.db_connect() as db:
            rows=[dict(x) for x in db.execute("SELECT * FROM assistant_issue_lifecycle ORDER BY created_at,issue_id,version").fetchall()]
    except Exception as exc:
        raise RuntimeError(
            "Assistant issue lifecycle could not be read; continuity backup creation is refused rather than silently substituting an empty component."
        ) from exc
    return {"rows":rows,"row_count":len(rows),"sha256":_nc_sha(rows)}


def _nc_physical_chat_snapshot(module) -> list[dict]:
    """Return the exact encrypted CHAT table in portable JSON form, without decrypting it."""
    base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
    with base() as db:
        try: db.row_factory=sqlite3.Row
        except Exception: pass
        if _nc_object_type(db,_NEATCRYPT_SECURE_CHAT_TABLE)!="table":
            return []
        rows=db.execute(
            f"SELECT message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version "
            f"FROM {_NEATCRYPT_SECURE_CHAT_TABLE} ORDER BY message_id"
        ).fetchall()
    out=[]
    for raw in rows:
        row=dict(raw); cipher=bytes(row.get("content_cipher") or b"")
        out.append({
            "message_id":int(row.get("message_id") or 0),
            "timestamp":str(row.get("timestamp") or ""),
            "role":str(row.get("role") or ""),
            "provider":str(row.get("provider") or ""),
            "model":str(row.get("model") or ""),
            "content_cipher_b64":base64.b64encode(cipher).decode("ascii"),
            "content_cipher_sha256":hashlib.sha256(cipher).hexdigest(),
            "is_private":int(row.get("is_private") or 0),
            "content_sha256":str(row.get("content_sha256") or ""),
            "encryption_version":str(row.get("encryption_version") or ""),
        })
    return out


def _nc_validate_physical_chat_snapshot(rows) -> list[dict]:
    clean=[]; last=0
    for raw in rows or []:
        if not isinstance(raw,dict): raise ValueError("Backup physical CHAT row is not an object.")
        row=dict(raw); mid=int(row.get("message_id") or 0)
        if mid<=last: raise ValueError("Backup physical CHAT IDs are not strictly increasing.")
        last=mid
        for field in ("timestamp","role","provider","model","content_cipher_b64","content_cipher_sha256","content_sha256","encryption_version"):
            if field not in row: raise ValueError(f"Backup physical CHAT row CHAT-{mid} is missing {field}.")
        try: cipher=base64.b64decode(str(row.get("content_cipher_b64") or ""),validate=True)
        except Exception as exc: raise ValueError(f"Backup physical CHAT ciphertext is not valid base64 at CHAT-{mid}.") from exc
        if hashlib.sha256(cipher).hexdigest()!=str(row.get("content_cipher_sha256") or ""):
            raise ValueError(f"Backup physical CHAT ciphertext hash mismatch at CHAT-{mid}.")
        row["is_private"]=1 if bool(row.get("is_private")) else 0
        clean.append(row)
    return clean


def _nc_backup_chat_components(module) -> tuple[list[dict],list[dict],list[dict]]:
    """Collect logical decryptable CHAT plus an exact physical encrypted snapshot.

    On encrypted stores, one unreadable row must not make the continuity snapshot
    impossible. The unreadable row is preserved only as authenticated opaque
    ciphertext; it is never represented as readable logical chat.
    """
    physical=_nc_physical_chat_snapshot(module)
    if not physical:
        logical=_bf_collect_chat_rows(module)
        return logical,[],[]
    key=_nc_read_local_key(module,required=True)
    logical=[]; failures=[]
    for stored in physical:
        row={
            "message_id":stored["message_id"],"timestamp":stored["timestamp"],"role":stored["role"],
            "provider":stored["provider"],"model":stored["model"],
            "content_cipher":base64.b64decode(stored["content_cipher_b64"]),
            "is_private":stored["is_private"],"content_sha256":stored["content_sha256"],
            "encryption_version":stored["encryption_version"],
        }
        try: logical.append(_nc_decrypt_physical_chat_row(key,row))
        except Exception as exc: failures.append(_nc_chat_fault_detail(row,exc))
    # Keep the historical logical backup schema exactly bounded to its fields.
    logical=[{k:r[k] for k in ("message_id","timestamp","role","provider","model","content","is_private","content_sha256")} for r in logical]
    return logical,physical,failures


def _nc_physical_snapshot_relation(live: list[dict], backup: list[dict]) -> str:
    if live==backup: return "exact_match"
    if len(live)>=len(backup) and live[:len(backup)]==backup: return "backup_is_exact_physical_prefix_of_newer_live_chat"
    if len(backup)>=len(live) and backup[:len(live)]==live: return "live_chat_is_exact_physical_prefix_of_newer_backup"
    return "histories_differ"


def _nc_physical_chat_restore_preflight(module, backup_physical: list[dict]) -> dict:
    backup=_nc_validate_physical_chat_snapshot(backup_physical)
    live=_nc_physical_chat_snapshot(module)
    if live:
        relation=_nc_physical_snapshot_relation(live,backup)
        if relation=="exact_match":
            return {"ok":True,"mode":"noop_physical_exact","live_rows":len(live),"backup_rows":len(backup),"physical_relation":relation}
        if relation=="backup_is_exact_physical_prefix_of_newer_live_chat":
            return {"ok":True,"mode":"live_encrypted_superset_physical_key_recovery","live_rows":len(live),"backup_rows":len(backup),"newer_live_rows_preserved":len(live)-len(backup),"physical_relation":relation}
        if relation=="live_chat_is_exact_physical_prefix_of_newer_backup":
            return {"ok":True,"mode":"complete_exact_physical_subset","live_rows":len(live),"backup_rows":len(backup),"physical_relation":relation}
        return {"ok":False,"mode":"refuse_divergent_physical_history","live_rows":len(live),"backup_rows":len(backup),"physical_relation":relation,"policy":"fail closed; never merge divergent encrypted CHAT histories"}
    # A fresh runtime may still expose the legacy plaintext table. It must be empty.
    base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
    with base() as db:
        typ=_nc_object_type(db,_NEATCRYPT_CHAT_VIEW)
        if typ=="table":
            n=int(db.execute(f"SELECT COUNT(*) FROM {_NEATCRYPT_CHAT_VIEW}").fetchone()[0])
            if n:
                return {"ok":False,"mode":"refuse_nonempty_plaintext_live_history","live_rows":n,"backup_rows":len(backup),"policy":"fail closed; physical encrypted backup cannot be merged into a non-empty plaintext history"}
    return {"ok":True,"mode":"restore_empty_physical","live_rows":0,"backup_rows":len(backup),"physical_relation":"empty_live"}


def _nc_restore_physical_chat(module, backup_physical: list[dict], master_key: bytes, preflight: dict) -> dict:
    if not preflight.get("ok"): raise RuntimeError("Physical CHAT restore attempted without safe preflight.")
    rows=_nc_validate_physical_chat_snapshot(backup_physical); mode=str(preflight.get("mode") or "")
    _nc_write_local_key(module,master_key)
    if mode in {"noop_physical_exact","live_encrypted_superset_physical_key_recovery"}:
        _nc_disable_plaintext_fts(module); mirror=_nc_retire_plaintext_mirror(module); _nc_activate_chat_runtime(module)
        return {"ok":True,"mode":mode,"backup_rows":len(rows),"live_rows_preserved":len(_nc_physical_chat_snapshot(module)),"physical_ciphertext_preserved":True,"raw_mirror":mirror}
    if mode not in {"restore_empty_physical","complete_exact_physical_subset"}:
        raise RuntimeError(f"Unsupported safe physical CHAT restore mode: {mode}")
    base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
    with base() as db:
        db.execute("BEGIN IMMEDIATE")
        try:
            typ=_nc_object_type(db,_NEATCRYPT_CHAT_VIEW)
            if typ=="table":
                if int(db.execute(f"SELECT COUNT(*) FROM {_NEATCRYPT_CHAT_VIEW}").fetchone()[0]):
                    raise RuntimeError("Physical CHAT restore encountered a non-empty plaintext table after preflight.")
                db.execute(f"DROP TABLE {_NEATCRYPT_CHAT_VIEW}")
            elif typ=="view":
                db.execute(f"DROP VIEW {_NEATCRYPT_CHAT_VIEW}")
            _nc_create_secure_schema(db)
            existing={int(x[0]) for x in db.execute(f"SELECT message_id FROM {_NEATCRYPT_SECURE_CHAT_TABLE}").fetchall()}
            if mode=="restore_empty_physical":
                db.execute(f"DELETE FROM {_NEATCRYPT_SECURE_CHAT_TABLE}"); existing=set()
            for row in rows:
                mid=int(row["message_id"])
                if mid in existing: continue
                cipher=base64.b64decode(row["content_cipher_b64"],validate=True)
                db.execute(
                    f"INSERT INTO {_NEATCRYPT_SECURE_CHAT_TABLE}(message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version) VALUES(?,?,?,?,?,?,?,?,?)",
                    (mid,row["timestamp"],row["role"],row["provider"],row["model"],sqlite3.Binary(cipher),int(row["is_private"]),row["content_sha256"],row["encryption_version"]),
                )
            _nc_create_compatibility_view(db)
            db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_TABLE}"); db.execute(f"DROP TABLE IF EXISTS {_RAW_CHAT_FTS_META_TABLE}")
            _nc_upsert_setting_db(db,_NEATCRYPT_SETTING,_NEATCRYPT_CHAT_VERSION)
            db.commit()
        except Exception:
            db.rollback(); raise
    exact=_nc_physical_chat_snapshot(module)==rows
    if not exact: raise RuntimeError("Restored physical CHAT snapshot did not match the authenticated backup bytes exactly.")
    _nc_disable_plaintext_fts(module); mirror=_nc_retire_plaintext_mirror(module); _nc_activate_chat_runtime(module)
    doctor=_nc_chat_doctor(module)
    return {"ok":True,"mode":mode,"rows":len(rows),"physical_ciphertext_preserved":True,"physical_snapshot_readback_exact":True,"unreadable_rows":int(doctor.get("failed_rows") or 0),"unreadable_source_ids":[int(x.get("message_id") or 0) for x in doctor.get("failures") or []],"raw_mirror":mirror}


def _nc_collect_backup_payload(module) -> dict:
    identity=_portable_collect_payload(module)
    chat,physical,failures=_nc_backup_chat_components(module)
    workshop=_nc_workshop_component(module)
    issues=_nc_issue_component(module)
    components={"identity":identity,"chat":chat,"workshop":workshop,"issue_lifecycle":issues}
    if physical:
        components["chat_physical"]=physical
    total_rows=len(physical) if physical else len(chat)
    unreadable_ids=[int(x.get("message_id") or 0) for x in failures]
    return {
        "kind":"assistant_continuity_backup_payload","schema_version":"1","created_at":_nc_now(),"source_bundle_version":BUNDLE_VERSION,
        "components":components,
        "manifest":{
            "component_sha256":{k:_nc_sha(v) for k,v in components.items()},
            "chat_rows":total_rows,"chat_readable_rows":len(chat),"chat_physical_rows":len(physical),
            "chat_unreadable_rows":len(failures),"chat_unreadable_ids":unreadable_ids,
            "chat_snapshot_mode":"physical_encrypted_plus_logical_readable" if physical else "logical_plaintext",
            "workshop_files":len(workshop.get("files") or []),"issue_lifecycle_rows":int(issues.get("row_count") or 0),
            "authority_note":"Chat history travels with identity for continuity recovery but remains conversational evidence, not immutable personality/core authority. Unreadable encrypted CHAT rows are preserved verbatim as opaque physical evidence and are never falsely represented as readable plaintext."
        }
    }


def _nc_validate_backup_payload(payload) -> dict:
    if not isinstance(payload,dict) or payload.get("kind")!="assistant_continuity_backup_payload" or str(payload.get("schema_version"))!="1":
        raise ValueError("Invalid Assistant Continuity Backup payload.")
    comps=payload.get("components") or {}
    if not isinstance(comps,dict): raise ValueError("Backup components are missing.")
    _portable_validate_payload(comps.get("identity"))
    clean_chat=[]; last=0
    for raw in comps.get("chat") or []:
        if not isinstance(raw,dict): raise ValueError("Backup chat row is not an object.")
        row=dict(raw); mid=int(row.get("message_id") or 0)
        if mid<=last: raise ValueError("Backup chat IDs are not strictly increasing.")
        last=mid; content=str(row.get("content") or ""); digest=hashlib.sha256(content.encode("utf-8")).hexdigest()
        if digest != str(row.get("content_sha256") or ""): raise ValueError(f"Backup chat hash mismatch at CHAT-{mid}.")
        for field in ("timestamp","role","provider","model"):
            if field not in row: raise ValueError(f"Backup chat row CHAT-{mid} is missing {field}.")
        clean_chat.append(row)
    physical=[]
    if "chat_physical" in comps:
        physical=_nc_validate_physical_chat_snapshot(comps.get("chat_physical") or [])
        physical_ids={int(x["message_id"]) for x in physical}
        logical_ids={int(x["message_id"]) for x in clean_chat}
        if not logical_ids.issubset(physical_ids):
            raise ValueError("Backup logical CHAT rows are not a subset of the authenticated physical CHAT snapshot.")
        manifest=dict(payload.get("manifest") or {})
        missing=sorted(physical_ids-logical_ids)
        if int(manifest.get("chat_rows") or 0)!=len(physical): raise ValueError("Backup total CHAT row count does not match physical snapshot.")
        if int(manifest.get("chat_readable_rows") or 0)!=len(clean_chat): raise ValueError("Backup readable CHAT row count is inconsistent.")
        if int(manifest.get("chat_unreadable_rows") or 0)!=len(missing): raise ValueError("Backup unreadable CHAT row count is inconsistent.")
        if [int(x) for x in (manifest.get("chat_unreadable_ids") or [])]!=missing: raise ValueError("Backup unreadable CHAT IDs are inconsistent with physical/logical components.")
    workshop=comps.get("workshop")
    if not isinstance(workshop,dict) or not isinstance(workshop.get("manifest") or {},dict) or not isinstance(workshop.get("files") or [],list):
        raise ValueError("Backup Workshop component is structurally invalid.")
    workshop_paths=[]
    for raw in workshop.get("files") or []:
        if not isinstance(raw,dict): raise ValueError("Backup Workshop file entry is invalid.")
        logical=str(raw.get("path") or "")
        if not logical or logical in workshop_paths: raise ValueError("Backup Workshop paths are missing or duplicated.")
        workshop_paths.append(logical)
    issues=comps.get("issue_lifecycle")
    if not isinstance(issues,dict) or not isinstance(issues.get("rows") or [],list):
        raise ValueError("Backup issue-lifecycle component is structurally invalid.")
    issue_rows=list(issues.get("rows") or [])
    if int(issues.get("row_count") or 0)!=len(issue_rows) or str(issues.get("sha256") or "")!=_nc_sha(issue_rows):
        raise ValueError("Backup issue-lifecycle count/hash validation failed.")
    expected=(payload.get("manifest") or {}).get("component_sha256") or {}
    if set(expected) != set(comps): raise ValueError("Backup component manifest does not exactly cover payload components.")
    for name,value in comps.items():
        if str(expected.get(name) or "") != _nc_sha(value): raise ValueError(f"Backup component hash mismatch: {name}")
    return payload


def _nc_create_backup_envelope(payload: dict, passphrase: str, master_key: bytes) -> dict:
    _nc_validate_backup_payload(payload); _nc_validate_passphrase(passphrase,for_new=True)
    salt=os.urandom(_NEATCRYPT_ARGON2_SALT_BYTES); wrap_nonce=os.urandom(_NEATCRYPT_NONCE_BYTES); payload_nonce=os.urandom(_NEATCRYPT_NONCE_BYTES)
    wrap_key=_nc_derive_wrap_key(passphrase,salt)
    wrapped=_nc_aesgcm()(wrap_key).encrypt(wrap_nonce,master_key,_NEATCRYPT_WRAP_AAD)
    header={"kind":_NEATCRYPT_BACKUP_KIND,"format_version":"1","created_at":payload.get("created_at"),"source_bundle_version":payload.get("source_bundle_version"),"cipher":"AES-256-GCM","kdf":{"name":"Argon2id","iterations":_NEATCRYPT_ARGON2_ITERATIONS,"lanes":_NEATCRYPT_ARGON2_LANES,"memory_kib":_NEATCRYPT_ARGON2_MEMORY_KIB,"length":32,"salt_b64":base64.b64encode(salt).decode("ascii")}}
    pdata=_nc_canonical(payload)
    cipher=_nc_aesgcm()(master_key).encrypt(payload_nonce,pdata,_NEATCRYPT_BACKUP_AAD+_nc_canonical(header))
    return {**header,"wrapped_master_key":{"nonce_b64":base64.b64encode(wrap_nonce).decode("ascii"),"ciphertext_b64":base64.b64encode(wrapped).decode("ascii")},"payload":{"nonce_b64":base64.b64encode(payload_nonce).decode("ascii"),"ciphertext_b64":base64.b64encode(cipher).decode("ascii"),"plaintext_sha256":hashlib.sha256(pdata).hexdigest()},"recovery":"backup file + passphrase is sufficient; old Windows DPAPI profile is not required"}


def _nc_open_backup_envelope(envelope, passphrase: str) -> tuple[bytes,dict]:
    if not isinstance(envelope,dict) or envelope.get("kind")!=_NEATCRYPT_BACKUP_KIND or str(envelope.get("format_version"))!="1": raise ValueError("Not a supported Assistant Continuity Backup.")
    if envelope.get("cipher")!="AES-256-GCM": raise ValueError("Unsupported NeatCrypt cipher.")
    kdf=dict(envelope.get("kdf") or {})
    if kdf.get("name")!="Argon2id": raise ValueError("Unsupported NeatCrypt KDF.")
    if int(kdf.get("length") or 0)!=_NEATCRYPT_ARGON2_LENGTH: raise ValueError("Unsupported NeatCrypt KDF output length.")
    salt=base64.b64decode(str(kdf.get("salt_b64") or ""),validate=True)
    wrap_key=_nc_derive_wrap_key(passphrase,salt,iterations=int(kdf.get("iterations") or 0),lanes=int(kdf.get("lanes") or 0),memory_kib=int(kdf.get("memory_kib") or 0))
    w=dict(envelope.get("wrapped_master_key") or {}); p=dict(envelope.get("payload") or {})
    try:
        wrap_nonce=base64.b64decode(str(w.get("nonce_b64") or ""),validate=True)
        payload_nonce=base64.b64decode(str(p.get("nonce_b64") or ""),validate=True)
        if len(wrap_nonce)!=_NEATCRYPT_NONCE_BYTES or len(payload_nonce)!=_NEATCRYPT_NONCE_BYTES:
            raise ValueError("NeatCrypt backup nonce length is invalid.")
        master=_nc_aesgcm()(wrap_key).decrypt(wrap_nonce,base64.b64decode(str(w.get("ciphertext_b64") or ""),validate=True),_NEATCRYPT_WRAP_AAD)
    except Exception as exc: raise ValueError("Wrong backup passphrase or damaged master-key wrapper.") from exc
    if len(master)!=32: raise ValueError("Recovered NeatCrypt master key length is invalid.")
    header={k:envelope.get(k) for k in ("kind","format_version","created_at","source_bundle_version","cipher","kdf")}
    try:
        pdata=_nc_aesgcm()(master).decrypt(payload_nonce,base64.b64decode(str(p.get("ciphertext_b64") or ""),validate=True),_NEATCRYPT_BACKUP_AAD+_nc_canonical(header))
    except Exception as exc: raise ValueError("Backup payload authentication/decryption failed.") from exc
    if hashlib.sha256(pdata).hexdigest()!=str(p.get("plaintext_sha256") or ""): raise ValueError("Backup payload plaintext hash mismatch.")
    payload=json.loads(pdata.decode("utf-8")); _nc_validate_backup_payload(payload)
    return master,payload


def _nc_write_backup_file(path: Path, envelope: dict) -> dict:
    raw=json.dumps(envelope,ensure_ascii=False,sort_keys=True,indent=2).encode("utf-8")+b"\n"
    if len(raw)>_NEATCRYPT_MAX_BACKUP_BYTES: raise ValueError("Assistant Continuity Backup exceeds configured size ceiling.")
    _bf_atomic_bytes(path,raw)
    return {"path":str(path),"bytes":path.stat().st_size,"sha256":_bf_sha256_file(path)}


def _nc_read_backup_file(path: Path) -> dict:
    if not path.exists() or not path.is_file(): raise FileNotFoundError(path)
    if path.stat().st_size<=0 or path.stat().st_size>_NEATCRYPT_MAX_BACKUP_BYTES: raise ValueError("Backup file size is outside accepted limits.")
    data=json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data,dict): raise ValueError("Backup envelope is not a JSON object.")
    return data


def _nc_receipt_root(module) -> Path:
    root=Path(module.safe_memory_path(_NEATCRYPT_RECEIPT_DIR))
    root.mkdir(parents=True,exist_ok=True)
    return root.resolve()


def _nc_receipt_digest(receipt: dict) -> str:
    return _nc_sha({key:value for key,value in dict(receipt or {}).items() if key!="receipt_sha256"})


def _nc_recent_backup_receipts(module, limit: int = 20) -> dict:
    root=_nc_receipt_root(module); records=[]; previous=None; chain_ok=True
    for path in sorted(root.glob("*.json")):
        try:
            receipt=json.loads(path.read_text(encoding="utf-8"))
            digest=_nc_receipt_digest(receipt)
            hash_ok=hmac.compare_digest(str(receipt.get("receipt_sha256") or ""),digest)
            link_ok=str(receipt.get("previous_receipt_sha256") or "") == str(previous or "")
            chain_ok=chain_ok and hash_ok and link_ok
            records.append({
                "receipt_id":receipt.get("receipt_id"),"operation":receipt.get("operation"),
                "status":receipt.get("status"),"verified_at":receipt.get("verified_at"),
                "backup_file":(receipt.get("backup") or {}).get("file_name"),
                "backup_sha256":(receipt.get("backup") or {}).get("sha256"),
                "receipt_sha256":receipt.get("receipt_sha256"),"receipt_hash_valid":hash_ok,
                "previous_link_valid":link_ok,"receipt_file":path.name,
            })
            previous=str(receipt.get("receipt_sha256") or "") if hash_ok else None
        except Exception as exc:
            chain_ok=False
            records.append({"receipt_file":path.name,"status":"UNREADABLE","error":f"{type(exc).__name__}: {exc}"})
            previous=None
    return {
        "ok":chain_ok,"receipt_version":_NEATCRYPT_RECEIPT_VERSION,
        "receipt_count":len(records),"hash_chain_valid":chain_ok,
        "recent":list(reversed(records[-max(1,int(limit)):]))
    }


def _nc_operational_backup_evidence(module) -> dict | None:
    """Return the newest durable receipt as bounded non-secret operational evidence."""
    history=_nc_recent_backup_receipts(module,limit=1)
    recent=list(history.get("recent") or [])
    if not recent:
        return None
    latest=dict(recent[0]); receipt_file=str(latest.get("receipt_file") or "")
    path=_nc_receipt_root(module)/receipt_file
    try:
        receipt=json.loads(path.read_text(encoding="utf-8"))
        receipt_hash_valid=hmac.compare_digest(str(receipt.get("receipt_sha256") or ""),_nc_receipt_digest(receipt))
    except Exception as exc:
        return {
            "available":True,"artifact_verified":False,"status":"UNREADABLE",
            "receipt_file":receipt_file,"hash_chain_valid":False,
            "error":f"{type(exc).__name__}: {exc}",
        }
    cryptographic=dict(receipt.get("cryptographic_checks") or {})
    artifact_verified=(
        str(receipt.get("status") or "").upper()=="VERIFIED"
        and bool(cryptographic)
        and all(bool(value) for value in cryptographic.values())
        and receipt_hash_valid
        and bool(history.get("hash_chain_valid"))
    )
    components=dict(receipt.get("components") or {}); backup=dict(receipt.get("backup") or {})
    envelope=dict(receipt.get("envelope") or {}); live=dict(receipt.get("live_comparison") or {})
    return {
        "available":True,"artifact_verified":artifact_verified,
        "status":receipt.get("status"),"operation":receipt.get("operation"),
        "verified_at":receipt.get("verified_at"),"receipt_id":receipt.get("receipt_id"),
        "receipt_file":receipt_file,"receipt_sha256":receipt.get("receipt_sha256"),
        "receipt_hash_valid":receipt_hash_valid,"hash_chain_valid":bool(history.get("hash_chain_valid")),
        "receipt_count":int(history.get("receipt_count") or 0),
        "backup_file":backup.get("file_name"),"backup_bytes":backup.get("bytes"),"backup_sha256":backup.get("sha256"),
        "source_bundle_version":envelope.get("source_bundle_version"),"format_version":envelope.get("format_version"),
        "cipher":envelope.get("cipher"),"kdf":envelope.get("kdf"),
        "chat_rows":components.get("chat_rows"),"workshop_files":components.get("workshop_files"),
        "issue_lifecycle_rows":components.get("issue_lifecycle_rows"),
        "live_relation":live.get("relation"),"live_rows_at_verification":live.get("live_rows"),
        "restore_performed":bool(receipt.get("restore_performed")),
        "live_state_modified":bool(receipt.get("live_state_modified")),
        "passphrase_stored":bool(receipt.get("passphrase_stored")),
        "master_key_stored":bool(receipt.get("master_key_stored")),
        "evidence_authority":"mechanical backup verification receipt; operational evidence only",
    }


def _nc_live_chat_relation(module, backup_rows: list[dict], backup_physical: list[dict] | None = None) -> dict:
    try:
        if backup_physical is not None:
            live=_nc_physical_chat_snapshot(module); backup=_nc_validate_physical_chat_snapshot(backup_physical)
            relation=_nc_physical_snapshot_relation(live,backup)
            return {"available":True,"relation":relation,"comparison":"exact_encrypted_physical_rows","live_rows":len(live),"backup_rows":len(backup)}
        live=_bf_live_chat_rows(module)
        if live==backup_rows:
            relation="exact_match"
        elif len(live)>=len(backup_rows) and live[:len(backup_rows)]==backup_rows:
            relation="backup_is_verified_prefix_of_newer_live_chat"
        elif len(backup_rows)>=len(live) and backup_rows[:len(live)]==live:
            relation="live_chat_is_verified_prefix_of_newer_backup"
        else:
            relation="histories_differ"
        return {"available":True,"relation":relation,"live_rows":len(live),"backup_rows":len(backup_rows)}
    except Exception as exc:
        return {"available":False,"relation":"unavailable","backup_rows":len(backup_physical) if backup_physical is not None else len(backup_rows),"error":f"{type(exc).__name__}: {exc}"}


def _nc_backup_verification_summary(module, source: Path, envelope: dict, master: bytes, payload: dict) -> dict:
    components=dict(payload.get("components") or {}); chat=list(components.get("chat") or [])
    physical=list(components.get("chat_physical") or []) if "chat_physical" in components else None
    identity=dict(components.get("identity") or {}); workshop=dict(components.get("workshop") or {})
    issues=dict(components.get("issue_lifecycle") or {}); local_key=_nc_read_local_key(module,required=False)
    total=len(physical) if physical is not None else len(chat)
    readable_ids={int(x.get("message_id") or 0) for x in chat}
    physical_ids={int(x.get("message_id") or 0) for x in (physical or [])}
    unreadable_ids=sorted(physical_ids-readable_ids) if physical is not None else []
    return {
        "ok":True,"artifact_verified":True,"version":_NEATCRYPT_BACKUP_VERSION,
        "verified_at":_nc_now(),
        "backup":{"file_name":source.name,"bytes":source.stat().st_size,"sha256":_bf_sha256_file(source)},
        "envelope":{
            "kind":envelope.get("kind"),"format_version":envelope.get("format_version"),
            "created_at":envelope.get("created_at"),"source_bundle_version":envelope.get("source_bundle_version"),
            "cipher":envelope.get("cipher"),"kdf":(envelope.get("kdf") or {}).get("name"),
        },
        "components":{
            "identity_component_names":sorted(str(key) for key in (identity.get("components") or {})),
            "chat_rows":total,"chat_readable_rows":len(chat),"chat_physical_rows":len(physical or []),
            "chat_unreadable_rows":len(unreadable_ids),"chat_unreadable_ids":unreadable_ids,
            "workshop_files":len(workshop.get("files") or []),
            "issue_lifecycle_rows":int(issues.get("row_count") or 0),
            "manifest_sha256":_nc_sha(payload.get("manifest") or {}),
            "payload_sha256":_nc_sha(payload),
        },
        "cryptographic_checks":{
            "argon2id_master_key_wrapper_authenticated":True,
            "aes_256_gcm_payload_authenticated":True,
            "payload_plaintext_sha256_matched":True,
            "component_manifest_hashes_matched":True,
            "logical_chat_row_ids_ordered_and_readable_content_hashes_matched":True,
            "physical_chat_ciphertext_hashes_matched_or_not_applicable":True,
        },
        "chat_integrity":{
            "status":"HEALTHY" if not unreadable_ids else "DEGRADED_OPAQUE_ROWS_PRESERVED",
            "all_rows_physically_preserved": physical is not None or not unreadable_ids,
            "all_rows_decryptable": not unreadable_ids,
            "unreadable_rows":len(unreadable_ids),"unreadable_source_ids":unreadable_ids,
            "policy":"Artifact verification authenticates and preserves opaque ciphertext but does not relabel unreadable live CHAT as healthy plaintext.",
        },
        "live_comparison":_nc_live_chat_relation(module,chat,physical),
        "local_master_key_available":local_key is not None,
        "backup_master_key_matches_local_wrapper":hmac.compare_digest(local_key,master) if local_key is not None else None,
        "backup_plus_passphrase_sufficient":True,"old_windows_dpapi_required":False,
        "passphrase_stored":False,"master_key_exposed":False,"restore_performed":False,
        "live_state_modified":False,"model_calls":0,"web_calls":0,"provider_requests":0,
    }


def _nc_persist_backup_receipt(module, operation: str, verification: dict, *, extra: dict | None = None) -> dict:
    root=_nc_receipt_root(module); history=_nc_recent_backup_receipts(module,limit=1)
    if int(history.get("receipt_count") or 0)>0 and not history.get("hash_chain_valid"):
        raise RuntimeError("Existing NeatCrypt backup receipt chain is invalid; refusing to append misleading evidence.")
    recent=list(history.get("recent") or [])
    previous=str((recent[0] if recent else {}).get("receipt_sha256") or "") or None
    verified_at=str(verification.get("verified_at") or _nc_now())
    identity_seed={
        "operation":str(operation),"verified_at":verified_at,
        "backup_sha256":(verification.get("backup") or {}).get("sha256"),"nonce":uuid.uuid4().hex,
    }
    receipt_id="NCBR-"+_nc_sha(identity_seed)[:20]
    receipt={
        "kind":_NEATCRYPT_RECEIPT_KIND,"receipt_version":_NEATCRYPT_RECEIPT_VERSION,
        "receipt_id":receipt_id,"operation":str(operation),"status":"VERIFIED",
        "verified_at":verified_at,"bundle_version":BUNDLE_VERSION,
        "backup":dict(verification.get("backup") or {}),
        "envelope":dict(verification.get("envelope") or {}),
        "components":dict(verification.get("components") or {}),
        "cryptographic_checks":dict(verification.get("cryptographic_checks") or {}),
        "live_comparison":dict(verification.get("live_comparison") or {}),
        "backup_master_key_matches_local_wrapper":verification.get("backup_master_key_matches_local_wrapper"),
        "verification_read_only":True,"restore_performed":False,"live_state_modified":False,
        "passphrase_stored":False,"master_key_stored":False,
        "previous_receipt_sha256":previous,
        "extra":dict(extra or {}),
    }
    receipt["receipt_sha256"]=_nc_receipt_digest(receipt)
    stamp=datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    path=root/f"{stamp}-{receipt_id}.json"
    _bf_atomic_json(path,receipt)
    reread=json.loads(path.read_text(encoding="utf-8"))
    if not hmac.compare_digest(str(reread.get("receipt_sha256") or ""),_nc_receipt_digest(reread)):
        raise RuntimeError("Durable NeatCrypt backup receipt failed authenticated hash readback.")
    # The durable JSON receipt is authoritative.  Mirror a bounded, non-secret
    # event into the encrypted Diagnostic Logbook so future investigations can
    # discover that the operation happened without needing console history.
    diagnostic_log_recorded=False
    logger=getattr(module,"append_diagnostic_log",None)
    if callable(logger):
        try:
            cryptographic=dict(receipt.get("cryptographic_checks") or {})
            components=dict(receipt.get("components") or {})
            backup=dict(receipt.get("backup") or {})
            logger(
                "backup.verification_receipt",
                "Assistant Continuity Backup receipt verified and persisted.",
                severity="info",subsystem="recovery",source="python",
                details={
                    "receipt_id":receipt_id,"operation":str(operation),"status":"VERIFIED",
                    "verified_at":verified_at,"backup_file":backup.get("file_name"),
                    "backup_sha256":backup.get("sha256"),"chat_rows":components.get("chat_rows"),
                    "receipt_sha256":receipt.get("receipt_sha256"),
                    "previous_receipt_sha256":previous,
                    "artifact_verified":bool(cryptographic) and all(bool(value) for value in cryptographic.values()),
                    "restore_performed":False,"live_state_modified":False,
                    "passphrase_stored":False,"master_key_stored":False,
                },
                related_refs=[receipt_id],
            )
            diagnostic_log_recorded=True
        except Exception:
            # Diagnostic mirroring is observability, not receipt authority.  A
            # logging outage must not invalidate the already-authenticated file.
            diagnostic_log_recorded=False
    return {"ok":True,"receipt_id":receipt_id,"receipt_file":str(path),"receipt_sha256":receipt["receipt_sha256"],"previous_receipt_sha256":previous,"hash_chain_valid":True,"diagnostic_log_recorded":diagnostic_log_recorded}


def _nc_try_persist_backup_receipt(module, operation: str, verification: dict, *, extra: dict | None = None) -> dict:
    try:
        return _nc_persist_backup_receipt(module,operation,verification,extra=extra)
    except Exception as exc:
        return {"ok":False,"error":f"{type(exc).__name__}: {exc}","artifact_verification_remains_valid":True}


def _nc_verify_backup(module, source: Path, passphrase: str) -> dict:
    # This decrypts/authenticates only in process memory. It never invokes any
    # restore backend and never writes identity, chat, Workshop, issues, or keys.
    envelope=_nc_read_backup_file(source)
    master,payload=_nc_open_backup_envelope(envelope,passphrase)
    verification=_nc_backup_verification_summary(module,source,envelope,master,payload)
    receipt=_nc_try_persist_backup_receipt(module,"verify",verification)
    return {**verification,"durable_receipt":receipt,"receipt_evidence_written":bool(receipt.get("ok"))}


def _nc_create_backup(module, target: Path, passphrase: str) -> dict:
    # Create + authenticate the portable artifact before any first-time plaintext
    # migration. Once NeatCrypt is already active, /backup new is a true snapshot:
    # it never rewrites live CHAT merely to make a backup.
    existing_key=_nc_read_local_key(module,required=False)
    secure_active=_nc_secure_chat_exists(module)
    if secure_active and existing_key is None:
        raise RuntimeError("Encrypted chat exists but the local key wrapper cannot be unlocked. Use /backup load with an existing portable backup before creating another backup.")
    master=existing_key or os.urandom(32)
    payload=_nc_collect_backup_payload(module)
    envelope=_nc_create_backup_envelope(payload,passphrase,master)
    file_record=_nc_write_backup_file(target,envelope)
    reopened_master,reopened_payload=_nc_open_backup_envelope(_nc_read_backup_file(target),passphrase)
    if reopened_master!=master or _nc_sha(reopened_payload)!=_nc_sha(payload): raise RuntimeError("Backup readback verification failed; live chat was not migrated.")
    physical=list((payload.get("components") or {}).get("chat_physical") or [])
    if secure_active and physical:
        # Verify the live physical snapshot is still byte-identical. No migration,
        # key rewrite, or CHAT mutation is performed in the ordinary snapshot path.
        current=_nc_physical_chat_snapshot(module)
        if current!=physical:
            raise RuntimeError("Live encrypted CHAT changed during backup snapshot; artifact remains on disk but no VERIFIED creation receipt was issued. Retry from a quiescent console.")
        keyring=_nc_keyring_path(module)
        if not keyring.is_file(): raise RuntimeError("Encrypted CHAT is active but its local key wrapper file is missing.")
        readable=len((payload.get("components") or {}).get("chat") or [])
        migration={"ok":True,"mode":"snapshot_only_existing_encrypted_chat","row_count":len(physical),"readable_rows":readable,"unreadable_rows":len(physical)-readable,"physical_ciphertext_preserved":True,"live_state_modified":False}
    else:
        keyring=_nc_write_local_key(module,master)
        migration=_nc_migrate_chat(module,master,expected_rows=list(payload["components"]["chat"]))
    verification=_nc_backup_verification_summary(module,target,envelope,reopened_master,reopened_payload)
    receipt=_nc_try_persist_backup_receipt(module,"create",verification,extra={"chat_snapshot":migration})
    return {"ok":True,"version":_NEATCRYPT_BACKUP_VERSION,"backup":file_record,"portable_recovery_verified":True,"old_windows_dpapi_required_for_restore":False,"local_key_wrapper":str(keyring),"chat_migration":migration,"chat_integrity":verification.get("chat_integrity"),"manifest":payload.get("manifest"),"durable_receipt":receipt,"receipt_evidence_written":bool(receipt.get("ok")),"model_calls":0,"web_calls":0,"provider_requests":0}


def _nc_rotate_master_key(module, target: Path, passphrase: str) -> dict:
    """Create a verified NC2 backup and replace the live master key.

    `/backup new` intentionally remains a snapshot/rewrap operation for recovery
    continuity.  Rotation is explicit because older backups remain readable as
    historical snapshots but cannot unlock chat written under the new live key.
    """
    if not _nc_secure_chat_exists(module):
        raise RuntimeError("NeatCrypt chat is not active yet. Create the first verified backup with /backup new before rotating the live key.")
    old_master=_nc_read_local_key(module,required=True)
    payload=_nc_collect_backup_payload(module)
    _physical=list((payload.get("components") or {}).get("chat_physical") or [])
    _logical=list((payload.get("components") or {}).get("chat") or [])
    if _physical and len(_physical)!=len(_logical):
        _missing=sorted({int(x.get("message_id") or 0) for x in _physical}-{int(x.get("message_id") or 0) for x in _logical})
        raise RuntimeError(f"Master-key rotation refused: {len(_missing)} encrypted CHAT row(s) are unreadable and cannot be safely re-encrypted under a new key: {_missing[:20]}")
    new_master=os.urandom(_NEATCRYPT_MASTER_KEY_BYTES)
    while hmac.compare_digest(new_master,old_master):
        new_master=os.urandom(_NEATCRYPT_MASTER_KEY_BYTES)
    envelope=_nc_create_backup_envelope(payload,passphrase,new_master)
    file_record=_nc_write_backup_file(target,envelope)
    reopened_master,reopened_payload=_nc_open_backup_envelope(_nc_read_backup_file(target),passphrase)
    if not hmac.compare_digest(reopened_master,new_master) or _nc_sha(reopened_payload)!=_nc_sha(payload):
        raise RuntimeError("Rotated backup readback verification failed; the live master key was not changed.")
    prepared_wrapper=_nc_prepare_local_key_blob(new_master)
    # The authenticated recovery artifact and verified local wrapper are staged
    # before the live rows change.  A process interruption after this boundary is
    # recoverable from the newly verified backup even if local wrapper publication
    # has not yet completed.
    migration=_nc_migrate_chat(module,new_master,expected_rows=list(payload["components"]["chat"]))
    keyring=_nc_write_local_key(module,new_master,prepared_blob=prepared_wrapper)
    verified=_nc_verify_secure_rows(module,new_master,list(payload["components"]["chat"]))
    if not verified.get("ok"):
        raise RuntimeError("Rotated live chat failed exact NC2 readback after local key publication.")
    old_key_rejected=True
    if payload["components"]["chat"]:
        base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
        with base() as db:
            row=db.execute(f"SELECT message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256 FROM {_NEATCRYPT_SECURE_CHAT_TABLE} ORDER BY message_id LIMIT 1").fetchone()
        try:
            _nc_chat_decrypt(old_master,bytes(row["content_cipher"]),message_id=row["message_id"],timestamp=row["timestamp"],role=row["role"],provider=row["provider"],model=row["model"],is_private=row["is_private"],content_sha256=row["content_sha256"])
            old_key_rejected=False
        except Exception:
            old_key_rejected=True
    if not old_key_rejected:
        raise RuntimeError("NeatCrypt rotation proof failed: the retired live key decrypted an NC2 row.")
    verification=_nc_backup_verification_summary(module,target,envelope,new_master,reopened_payload)
    receipt=_nc_try_persist_backup_receipt(module,"rotate",verification,extra={"old_live_master_key_rejected":old_key_rejected,"chat_migration":migration})
    return {
        "ok":True,"version":_NEATCRYPT_BACKUP_VERSION,"operation":"master_key_rotation",
        "backup":file_record,"portable_recovery_verified":True,"chat_migration":migration,
        "local_key_wrapper":str(keyring),"old_live_master_key_rejected":old_key_rejected,
        "durable_receipt":receipt,"receipt_evidence_written":bool(receipt.get("ok")),
        "older_backups":"remain valid historical snapshots but do not unlock the newly rotated live chat store",
        "old_windows_dpapi_required_for_restore":False,"manifest":payload.get("manifest"),
        "model_calls":0,"web_calls":0,"provider_requests":0,
    }


def _nc_chat_restore_preflight(module, backup_rows: list[dict], *, recovered_master_key: bytes | None = None) -> dict:
    prior_cache=getattr(module,"_NEATCRYPT_MASTER_KEY_CACHE",None)
    temporary_key=False
    if recovered_master_key is not None and _nc_secure_chat_exists(module) and _nc_read_local_key(module,required=False) is None:
        # A valid portable backup can temporarily unlock a copied encrypted live store in memory
        # so preflight can compare histories before any new Windows DPAPI wrapper is written.
        module._NEATCRYPT_MASTER_KEY_CACHE=bytes(recovered_master_key); temporary_key=True
    try:
        live=_bf_live_chat_rows(module)
        # If the live encrypted store is a strict superset of the older backup, preserve it.
        # This is the important new-Windows case: the backup may be old as a snapshot but still
        # carries the same wrapped master key needed to unlock newer copied chat ciphertext.
        if len(live)>=len(backup_rows) and all(live[i]==backup_rows[i] for i in range(len(backup_rows))):
            if len(live)>len(backup_rows):
                return {"ok":True,"mode":"live_encrypted_superset_key_recovery","live_rows":len(live),"backup_rows":len(backup_rows),"newer_live_rows_preserved":len(live)-len(backup_rows),"policy":"portable backup supplies key recovery; newer matching live chat is preserved and never rolled back to the older snapshot"}
            return {"ok":True,"mode":"noop","live_rows":len(live),"backup_rows":len(backup_rows),"already_matching_rows":len(live)}
        return _bf_chat_preflight(module,backup_rows)
    except Exception as exc:
        return {"ok":False,"error":f"Cannot compare live chat safely with the recovered master key: {type(exc).__name__}: {exc}","policy":"fail closed; do not overwrite or renumber chat histories"}
    finally:
        if temporary_key:
            module._NEATCRYPT_MASTER_KEY_CACHE=prior_cache


def _nc_restore_chat(module, rows: list[dict], master_key: bytes, preflight: dict) -> dict:
    if not preflight.get("ok"): raise RuntimeError("Chat restore attempted without safe preflight.")
    mode=str(preflight.get("mode") or "")
    if mode=="noop":
        _nc_write_local_key(module,master_key)
        return {"ok":True,"mode":"noop","rows":len(rows),"local_key_wrapper_refreshed":True}
    if mode=="live_encrypted_superset_key_recovery":
        _nc_write_local_key(module,master_key)
        _nc_disable_plaintext_fts(module); mirror=_nc_retire_plaintext_mirror(module)
        current=_bf_live_chat_rows(module)
        return {"ok":True,"mode":mode,"backup_rows":len(rows),"live_rows_preserved":len(current),"newer_live_rows_preserved":max(0,len(current)-len(rows)),"local_key_wrapper_refreshed":True,"raw_mirror":mirror}
    if mode not in {"restore_empty","complete_exact_subset"}:
        raise RuntimeError(f"Unsupported safe chat restore mode: {mode}")
    # For a fresh/empty runtime, replace the plaintext compatibility table with secure storage.
    live=_bf_live_chat_rows(module)
    if live and mode!="complete_exact_subset": raise RuntimeError("Live chat is non-empty; overwrite refused.")
    _nc_write_local_key(module,master_key)
    if not _nc_secure_chat_exists(module):
        mig=_nc_migrate_chat(module,master_key)
    else: mig={"ok":True,"mode":"already_encrypted"}
    live_ids={int(x["message_id"]) for x in _bf_live_chat_rows(module)}
    with module.db_connect() as db:
        for row in rows:
            mid=int(row["message_id"])
            if mid in live_ids: continue
            cipher,tag=_nc_encrypt_known_row(master_key,row)
            db.execute(f"INSERT INTO {_NEATCRYPT_SECURE_CHAT_TABLE}(message_id,timestamp,role,provider,model,content_cipher,is_private,content_sha256,encryption_version) VALUES(?,?,?,?,?,?,?,?,?)",(mid,row["timestamp"],row["role"],row["provider"],row["model"],sqlite3.Binary(cipher),int(row["is_private"]),tag,"NC2"))
    final=_bf_live_chat_rows(module)
    if final!=rows: raise RuntimeError("Restored encrypted chat readback does not exactly match backup history.")
    _nc_disable_plaintext_fts(module); mirror=_nc_retire_plaintext_mirror(module)
    return {"ok":True,"mode":mode,"rows":len(rows),"stable_chat_ids_preserved":True,"physical_encryption_verified":_nc_verify_secure_rows(module,master_key).get("ok"),"raw_mirror":mirror,"migration":mig}


def _nc_restore_issues(module, component: dict) -> dict:
    rows=[dict(x) for x in component.get("rows") or []]
    if not rows: return {"ok":True,"mode":"empty_component","rows":0}
    _ensure_issue_lifecycle_schema(module)
    with module.db_connect() as db:
        live=[dict(x) for x in db.execute("SELECT * FROM assistant_issue_lifecycle ORDER BY created_at,issue_id,version").fetchall()]
        if live:
            if _nc_sha(live)==_nc_sha(rows): return {"ok":True,"mode":"noop_exact_match","rows":len(rows)}
            raise RuntimeError("Live issue lifecycle differs from backup; automatic overwrite/merge refused.")
        cols=[str(x[1]) for x in db.execute("PRAGMA table_info(assistant_issue_lifecycle)").fetchall()]
        for row in rows:
            keys=[c for c in cols if c in row]
            db.execute(f"INSERT INTO assistant_issue_lifecycle({','.join(keys)}) VALUES({','.join('?' for _ in keys)})",tuple(row[k] for k in keys))
    return {"ok":True,"mode":"restored_empty","rows":len(rows)}


def _nc_restore_guard_root(module) -> Path:
    root=Path(module.safe_memory_path(_NEATCRYPT_RESTORE_GUARD_DIR))
    root.mkdir(parents=True,exist_ok=True)
    return root.resolve()


def _nc_restore_guard_targets(module) -> list[Path]:
    names=[
        getattr(module,"PERSONALITY_ENCRYPTED_FILE",None),
        getattr(module,"CURRENT_SELF_ENCRYPTED_FILE",None),
        globals().get("_ACTIVE_CONTINUITY_FILE"),globals().get("_STARTUP_VIEW_FILE"),
        globals().get("_SESSION_HANDOFF_FILE"),globals().get("_PERCEPTION_FILE"),
        globals().get("_SELF_CONTINUITY_FILE"),_NEATCRYPT_KEYRING_FILE,
        str(getattr(module,"RAW_CONVERSATION_FILE","raw_conversation.txt") or "raw_conversation.txt"),
    ]
    targets=[]
    for name in names:
        if name:
            targets.append(Path(module.safe_memory_path(str(name))).resolve())
    if targets:
        targets.append((targets[0].parent/"identity_import_recovery").resolve())
    targets.append(_ws_root(module).resolve())
    unique=[]; seen=set()
    for path in targets:
        key=str(path)
        if key not in seen:
            seen.add(key); unique.append(path)
    return unique


def _nc_capture_restore_guard(module, source: Path) -> dict:
    """Capture exact pre-restore SQLite/files so an exception can roll back siblings."""
    root=_nc_restore_guard_root(module)
    guard=Path(tempfile.mkdtemp(prefix="restore-",dir=str(root))).resolve()
    records=[]
    try:
        db_snapshot=guard/"state.sqlite"
        base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
        live=base(); snapshot=sqlite3.connect(str(db_snapshot))
        try:
            live.backup(snapshot)
        finally:
            snapshot.close(); live.close()
        store=guard/"paths"; store.mkdir(parents=True,exist_ok=True)
        for index,target in enumerate(_nc_restore_guard_targets(module)):
            item=store/f"item-{index:03d}"
            exists=target.exists()
            if target.is_symlink():
                raise RuntimeError(f"Restore guard refuses symbolic-link state target: {target}")
            kind="missing"
            if exists and target.is_file():
                kind="file"; shutil.copy2(target,item)
            elif exists and target.is_dir():
                kind="directory"; shutil.copytree(target,item)
            elif exists:
                raise RuntimeError(f"Restore guard cannot snapshot unsupported state object: {target}")
            records.append({"target":str(target),"kind":kind,"snapshot":str(item.relative_to(guard)) if exists else None})
        manifest={
            "kind":"neatcrypt_restore_guard","version":"1","status":"prepared",
            "created_at":_nc_now(),"source":str(Path(source).resolve()),"database_snapshot":"state.sqlite",
            "paths":records,"model_calls":0,"web_calls":0,"provider_requests":0,
        }
        _bf_atomic_json(guard/_NEATCRYPT_RESTORE_GUARD_MANIFEST,manifest)
        return {"path":guard,"manifest":manifest}
    except Exception:
        shutil.rmtree(guard,ignore_errors=True)
        raise


def _nc_apply_restore_guard(module, guard: dict) -> dict:
    path=Path(guard["path"]).resolve(); manifest=dict(guard.get("manifest") or {})
    if manifest.get("kind")!="neatcrypt_restore_guard" or not (path/"state.sqlite").is_file():
        raise RuntimeError("NeatCrypt restore rollback guard is incomplete.")
    errors=[]; module._NEATCRYPT_MASTER_KEY_CACHE=None
    try:
        source=sqlite3.connect(str(path/"state.sqlite"))
        base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect); live=base()
        try:
            source.backup(live)
        finally:
            live.close(); source.close()
    except Exception as exc:
        errors.append(f"database: {type(exc).__name__}: {exc}")
    allowed_targets={str(x) for x in _nc_restore_guard_targets(module)}
    for record in manifest.get("paths") or []:
        target=Path(str(record.get("target") or "")); kind=str(record.get("kind") or "missing")
        try:
            if not target.is_absolute() or str(target) not in allowed_targets:
                raise RuntimeError("rollback target is outside the exact guarded state set")
            if target.exists():
                if target.is_dir() and not target.is_symlink(): shutil.rmtree(target)
                else: target.unlink()
            if kind in {"file","directory"}:
                snapshot=(path/str(record.get("snapshot") or "")).resolve()
                if path not in snapshot.parents: raise RuntimeError("guard snapshot path escaped rollback directory")
                target.parent.mkdir(parents=True,exist_ok=True)
                if kind=="file": shutil.copy2(snapshot,target)
                else: shutil.copytree(snapshot,target)
        except Exception as exc:
            errors.append(f"{target}: {type(exc).__name__}: {exc}")
    result={"ok":not errors,"rolled_back_at":_nc_now(),"errors":errors}
    manifest["status"]="rolled_back" if not errors else "rollback_incomplete"
    manifest["rollback"]=result
    try: _bf_atomic_json(path/_NEATCRYPT_RESTORE_GUARD_MANIFEST,manifest)
    except Exception: pass
    return result


def _nc_discard_restore_guard(guard: dict) -> None:
    path=Path(guard.get("path") or "")
    if path.exists() and path.name.startswith("restore-"):
        shutil.rmtree(path)


def _nc_load_backup(module, source: Path, passphrase: str) -> dict:
    envelope=_nc_read_backup_file(source); master,payload=_nc_open_backup_envelope(envelope,passphrase)
    comps=payload["components"]
    # All semantic/cipher checks happen before mutation.
    identity=_portable_validate_payload(comps["identity"])
    chat=[dict(x) for x in comps.get("chat") or []]
    physical=[dict(x) for x in comps.get("chat_physical") or []] if "chat_physical" in comps else None
    chat_pre=_nc_physical_chat_restore_preflight(module,physical) if physical is not None else _nc_chat_restore_preflight(module,chat,recovered_master_key=master)
    ws_backup=_nc_workshop_for_restore(dict(comps.get("workshop") or {})); ws_pre=_bf_workshop_preflight(module,ws_backup)
    issue_live=[]; issue_error=None
    try:
        with module.db_connect() as db:
            if _nc_object_type(db,"assistant_issue_lifecycle")=="table":
                issue_live=[dict(x) for x in db.execute("SELECT * FROM assistant_issue_lifecycle ORDER BY created_at,issue_id,version").fetchall()]
    except Exception as exc:
        issue_error=f"{type(exc).__name__}: {exc}"
    issue_rows=list((comps.get("issue_lifecycle") or {}).get("rows") or [])
    issue_ok=issue_error is None and (not issue_live or _nc_sha(issue_live)==_nc_sha(issue_rows))
    preflight={"ok":bool(chat_pre.get("ok") and ws_pre.get("ok") and issue_ok),"chat":chat_pre,"workshop":ws_pre,"issue_lifecycle":{"ok":issue_ok,"live_rows":len(issue_live),"backup_rows":len(issue_rows),"read_error":issue_error},"backup_verified":True,"mutation_performed":False}
    if not preflight["ok"]:
        return {"ok":False,"error":"Assistant Continuity Backup restore refused during preflight; live state is unchanged.","preflight":preflight,"mutation_performed":False}
    guard=_nc_capture_restore_guard(module,source)
    try:
        _nc_write_local_key(module,master)
        identity_result=_portable_restore_payload(module,identity,source_path=source)
        workshop_result=_bf_commit_workshop_restore(module,ws_backup,ws_pre)
        chat_result=_nc_restore_physical_chat(module,physical,master,chat_pre) if physical is not None else _nc_restore_chat(module,chat,master,chat_pre)
        issues_result=_nc_restore_issues(module,dict(comps.get("issue_lifecycle") or {}))
    except Exception as exc:
        rollback=_nc_apply_restore_guard(module,guard)
        if rollback.get("ok"):
            _nc_discard_restore_guard(guard)
            raise RuntimeError(f"Assistant Continuity Backup restore failed and all guarded live state was rolled back: {type(exc).__name__}: {exc}") from exc
        raise RuntimeError(f"Assistant Continuity Backup restore failed and rollback was incomplete; preserve guard {guard['path']}: {rollback}") from exc
    _nc_discard_restore_guard(guard)
    return {"ok":True,"version":_NEATCRYPT_BACKUP_VERSION,"source":str(source),"source_bundle_version":payload.get("source_bundle_version"),"preflight":preflight,"restore_atomicity":"all guarded SQLite/files roll back automatically on caught restore failure","identity":identity_result,"workshop":workshop_result,"chat":chat_result,"issue_lifecycle":issues_result,"old_windows_dpapi_required":False,"new_local_key_wrapper_created":True,"model_calls":0,"web_calls":0,"provider_requests":0}


def _nc_backup_status(module) -> dict:
    root=_nc_backup_root(); recent=[]
    for p in sorted(root.glob(f"*{_NEATCRYPT_BACKUP_EXTENSION}"), key=lambda x:x.stat().st_mtime, reverse=True)[:20]:
        recent.append({"path":str(p.resolve()),"bytes":p.stat().st_size,"modified_at":datetime.fromtimestamp(p.stat().st_mtime,timezone.utc).isoformat()})
    base=getattr(module,"_NEATCRYPT_BASE_DB_CONNECT",module.db_connect)
    object_type="unknown"; secure_rows=0; fts_present=False; versions={}; keyed_tags=0; plaintext_hash_rows=0
    try:
        with base() as db:
            object_type=_nc_object_type(db,_NEATCRYPT_CHAT_VIEW)
            if _nc_object_type(db,_NEATCRYPT_SECURE_CHAT_TABLE)=="table":
                secure_rows=int(db.execute(f"SELECT COUNT(*) FROM {_NEATCRYPT_SECURE_CHAT_TABLE}").fetchone()[0])
                versions={str(x[0]):int(x[1]) for x in db.execute(f"SELECT encryption_version,COUNT(*) FROM {_NEATCRYPT_SECURE_CHAT_TABLE} GROUP BY encryption_version").fetchall()}
                keyed_tags=int(db.execute(f"SELECT COUNT(*) FROM {_NEATCRYPT_SECURE_CHAT_TABLE} WHERE content_sha256 LIKE ?",(_NEATCRYPT_CHAT_TAG_PREFIX+"%",)).fetchone()[0])
                plaintext_hash_rows=int(db.execute(f"SELECT COUNT(*) FROM {_NEATCRYPT_SECURE_CHAT_TABLE} WHERE length(content_sha256)=64 AND content_sha256 NOT LIKE ?",(_NEATCRYPT_CHAT_TAG_PREFIX+"%",)).fetchone()[0])
            fts_present=_nc_object_type(db,_RAW_CHAT_FTS_TABLE)=="table"
    except Exception: pass
    key=_nc_read_local_key(module,required=False)
    try: mirror=Path(module.safe_memory_path(str(getattr(module,"RAW_CONVERSATION_FILE","raw_conversation.txt"))))
    except Exception: mirror=Path.cwd()/"raw_conversation.txt"
    guard_root=Path(module.safe_memory_path(_NEATCRYPT_RESTORE_GUARD_DIR)); pending_guards=[]
    if guard_root.exists():
        for p in sorted(guard_root.glob("restore-*"),key=lambda x:x.stat().st_mtime,reverse=True)[:20]:
            try: meta=json.loads((p/_NEATCRYPT_RESTORE_GUARD_MANIFEST).read_text(encoding="utf-8"))
            except Exception: meta={"status":"unreadable"}
            if str(meta.get("status") or "") not in {"rolled_back","completed"}: pending_guards.append({"path":str(p),"status":meta.get("status"),"created_at":meta.get("created_at"),"source":meta.get("source")})
    receipts=_nc_recent_backup_receipts(module,limit=20)
