def _nc_prompt_new_passphrase() -> str:
    first=getpass.getpass("New Assistant backup passphrase: "); second=getpass.getpass("Repeat passphrase: ")
    if first!=second: raise ValueError("Passphrases did not match.")
    _nc_validate_passphrase(first,for_new=True); return first


def _nc_prompt_passphrase() -> str:
    value=getpass.getpass("Assistant backup passphrase: "); _nc_validate_passphrase(value); return value


def _nc_is_neatcrypt_verify_command(command: str) -> bool:
    clean=str(command or "").strip(); lower=clean.casefold()
    if lower=="/backup verify": return True
    if not lower.startswith("/backup verify "): return False
    raw=clean[len("/backup verify"):].strip().strip('"')
    supplied=Path(os.path.expandvars(raw)).expanduser()
    if supplied.suffix.casefold()==_NEATCRYPT_BACKUP_EXTENSION or supplied.name.casefold().startswith("assistant_continuity_"):
        return True
    try:
        return _nc_backup_path(raw,for_write=False).is_file()
    except Exception:
        return False


def _nc_handle_backup_command(module, raw: str) -> bool:
    command=str(raw or "").strip(); lower=command.casefold()
    if lower in {"/backup","/backup status"}:
        print(json.dumps(_nc_backup_status(module),ensure_ascii=False,indent=2)); return True
    if lower=="/backup new" or lower.startswith("/backup new "):
        arg=command[len("/backup new"):].strip()
        try:
            target=_nc_backup_path(arg,for_write=True); pw=_nc_prompt_new_passphrase(); result=_nc_create_backup(module,target,pw); print(json.dumps(result,ensure_ascii=False,indent=2))
        except Exception as exc: print(f"Assistant continuity backup error: {type(exc).__name__}: {exc}")
        return True
    if _nc_is_neatcrypt_verify_command(command):
        arg=command[len("/backup verify"):].strip()
        if not arg: print("Use /backup verify <file.nacb> (read-only; no restore)"); return True
        try:
            source=_nc_backup_path(arg,for_write=False); pw=_nc_prompt_passphrase(); result=_nc_verify_backup(module,source,pw); print(json.dumps(result,ensure_ascii=False,indent=2))
        except Exception as exc: print(f"Assistant continuity backup verification error: {type(exc).__name__}: {exc}")
        return True
    if lower=="/backup rotate" or lower.startswith("/backup rotate "):
        arg=command[len("/backup rotate"):].strip()
        try:
            target=_nc_backup_path(arg,for_write=True); pw=_nc_prompt_new_passphrase(); result=_nc_rotate_master_key(module,target,pw); print(json.dumps(result,ensure_ascii=False,indent=2))
        except Exception as exc: print(f"NeatCrypt master-key rotation error: {type(exc).__name__}: {exc}")
        return True
    if lower=="/backup load" or lower.startswith("/backup load "):
        arg=command[len("/backup load"):].strip()
        if not arg: print("Use /backup load <file.nacb>"); return True
        try:
            source=_nc_backup_path(arg,for_write=False); pw=_nc_prompt_passphrase(); result=_nc_load_backup(module,source,pw); print(json.dumps(result,ensure_ascii=False,indent=2))
        except Exception as exc: print(f"Assistant continuity restore error: {type(exc).__name__}: {exc}")
        return True
    return False


# The older backup-family console wrapper remains installed underneath NeatCrypt.
# Route the new simple continuity-backup namespace first, then delegate legacy
# /backup create|restore|verify|list|help commands unchanged.  The old wrapper
# resolves _bf_handle_command dynamically, so this keeps command ownership
# deterministic even if wrapper nesting/order changes later.
_NC_LEGACY_BF_HANDLE = globals().get("_bf_handle_command")
def _nc_backup_family_command_router(module, raw: str) -> bool:
    command=str(raw or "").strip(); lower=command.casefold()
    if lower in {"/backup","/backup status"} or lower=="/backup new" or lower.startswith("/backup new ") or _nc_is_neatcrypt_verify_command(command) or lower=="/backup rotate" or lower.startswith("/backup rotate ") or lower=="/backup load" or lower.startswith("/backup load "):
        return _nc_handle_backup_command(module,command)
    legacy=_NC_LEGACY_BF_HANDLE
    if callable(legacy):
        return bool(legacy(module,command))
    return False


