def _install_neatcrypt_continuity_backup(module) -> None:
    if getattr(module,"_NEATCRYPT_CONTINUITY_BACKUP_INSTALLED",False): return
    # Make the new /backup, /backup status, /backup new, and /backup load
    # namespace authoritative while preserving the older compatibility verbs.
    globals()["_bf_handle_command"]=_nc_backup_family_command_router
    _nc_install_db_wrapper(module)
    # If the chat store was already migrated in a prior run, make all legacy readers transparently decrypt through the view.
    if _nc_secure_chat_exists(module):
        with module.db_connect() as db: _nc_create_compatibility_view(db)
        _nc_disable_plaintext_fts(module)
        _nc_activate_chat_runtime(module)
    old_init=module.initialize_database
    def init_with_neatcrypt():
        # Once chat is encrypted, keep the compatibility view in place and run
        # mature initialization through the narrow legacy-index DDL filter.
        result=_nc_run_initializer_with_secure_chat_view(module,old_init) if _nc_secure_chat_exists(module) else old_init()
        if _nc_secure_chat_exists(module):
            with module.db_connect() as db: _nc_create_compatibility_view(db)
            _nc_disable_plaintext_fts(module)
            _nc_activate_chat_runtime(module)
        return result
    module.initialize_database=init_with_neatcrypt
    # Never persist a plaintext FTS index once chat encryption is active.
    original_ensure=globals().get("_rcr_ensure_index")
    if callable(original_ensure):
        def neatcrypt_aware_ensure(mod):
            if _nc_secure_chat_exists(mod):
                _nc_disable_plaintext_fts(mod)
                return {"ok":True,"fts5":False,"indexed_through_row":0,"new_rows":0,"method":"neatcrypt_sql_decrypt_scan"}
            return original_ensure(mod)
        globals()["_rcr_ensure_index"]=neatcrypt_aware_ensure
    module.get_neatcrypt_backup_status=lambda:_nc_backup_status(module)
    module.neatcrypt_continuity_backup_self_test=lambda:neatcrypt_continuity_backup_self_test(module)
    if hasattr(module,"TOOL_SCHEMAS"):
        existing_tools={str((schema.get("function") or {}).get("name") or "") for schema in module.TOOL_SCHEMAS if isinstance(schema,dict)}
        if "get_neatcrypt_backup_status" not in existing_tools:
            module.TOOL_SCHEMAS.append({"type":"function","function":{
                "name":"get_neatcrypt_backup_status",
                "description":"Read NeatCrypt encrypted-chat status, discovered .nacb artifacts, and durable hash-chained creation/verification receipts. This never receives a passphrase and never restores a backup.",
                "parameters":{"type":"object","properties":{},"additionalProperties":False},
            }})
    if hasattr(module,"_READ_ONLY_TEXT_TOOL_ALLOWLIST"):
        module._READ_ONLY_TEXT_TOOL_ALLOWLIST.add("get_neatcrypt_backup_status")
    if hasattr(module,"execute_tool"):
        old_execute=module.execute_tool
        def execute_with_neatcrypt_status(name,arguments,seen,*args,**kwargs):
            if name=="get_neatcrypt_backup_status": return module.get_neatcrypt_backup_status()
            return old_execute(name,arguments,seen,*args,**kwargs)
        module.execute_tool=execute_with_neatcrypt_status
    old_main=module.main
    def main_with_neatcrypt_backup():
        previous=builtins.input
        def intercepted(prompt=""):
            while True:
                value=previous(prompt)
                if _nc_handle_doctor_command(module,value): continue
                if _nc_handle_backup_command(module,value): continue
                return value
        builtins.input=intercepted
        try:return old_main()
        finally:builtins.input=previous
    module.main=main_with_neatcrypt_backup
    old_help=module.print_help
    def help_with_neatcrypt(*args,**kwargs):
        old_help(*args,**kwargs)
        print("  /doctor chat")
        print("      Read-only authenticated scan of encrypted CHAT rows. Reports unreadable CHAT IDs/reasons; never repairs, deletes, decrypts to console, or mutates the database.")
        print("  /backup | /backup status")
        print("  /backup new [filename] | /backup verify <filename.nacb> | /backup rotate [filename] | /backup load <filename>")
        print("      Assistant Continuity Backup (.nacb): identity/personality + continuity + encrypted chat + Workshop, protected by NeatCrypt AES-256-GCM with Argon2id passphrase wrapping. /backup verify authenticates the complete artifact and writes only a hash-chained evidence receipt—no restore or live-state mutation. /backup new snapshots/rewraps the current key; /backup rotate creates a new live key. Backup+passphrase is portable; old Windows DPAPI is not required.")
    module.print_help=help_with_neatcrypt
    module.NEATCRYPT_VERSION=_NEATCRYPT_VERSION; module.NEATCRYPT_BACKUP_VERSION=_NEATCRYPT_BACKUP_VERSION
    module.NEATMEMORY_VERSION=BUNDLE_VERSION; module.RELEASE_NAME=RELEASE_NAME
    module._NEATCRYPT_CONTINUITY_BACKUP_INSTALLED=True

# Register chat as an explicit authority/privacy plane. Encryption changes storage protection,
# not semantic authority: chat is conversational evidence/history, never immutable personality/core.
_SAR_BASE_BEFORE_NEATCRYPT = _sar_base_planes
def _sar_base_planes(module):
    planes=_SAR_BASE_BEFORE_NEATCRYPT(module)
    if not any(str(x.get("plane_id"))=="conversation.raw_chat" for x in planes):
        planes.append({
            "plane_id":"conversation.raw_chat","title":"Canonical conversation/chat evidence history","authority_class":"conversational_evidence_history","authority_scope":"Exact user/Assistant conversational evidence used for continuity and retrieval; bundled with identity for recovery but not immutable personality/core authority.","owner":"User and Assistant/model authored messages; Python persists/protects exact rows.",
            "owning_store":_sar_store("sqlite",database="canonical NeatMemory SQLite",tables=["chat_messages"],physical_encrypted_table=_NEATCRYPT_SECURE_CHAT_TABLE),
            "writers":["append_public_message / governed chat persistence"],"readers":["recent chat context","raw-chat recall","session handoff evidence","backup/recovery"],"schema_version":_NEATCRYPT_CHAT_VERSION,
            "checkpoint_behavior":"Canonical rows are encrypted before persistence once NeatCrypt is activated; message IDs/hashes remain stable.","recovery_behavior":"Assistant Continuity Backup carries exact chat rows and a passphrase-wrapped NeatCrypt master key; restore establishes a new local Windows wrapper without the old DPAPI profile.",
            "provenance_fields":["message_id","timestamp","role","provider","model","is_private","content_sha256"],"revision_policy":"Append chronological rows; stable message IDs; recovery refuses divergent same-ID histories.","supersession_policy":"Chat evidence is historical and not silently rewritten/superseded by personality state.","automatic_promotion":"Never becomes immutable personality/core or canonical fact merely because it is included in the continuity backup.","source_marker":"neatcrypt-continuity-backup","declared_fields":["message_id","timestamp","role","provider","model","content_cipher","is_private","content_sha256","encryption_version"]})
    return planes

_SPG_POLICY_BEFORE_NEATCRYPT = _spg_plane_policy
def _spg_plane_policy(plane_id: str) -> dict:
    if str(plane_id)=="conversation.raw_chat":
        return dict(privacy_class="restricted_conversation",authorship="mixed_user_and_assistant_model_messages_with_exact_role_provider_model_provenance",retention="canonical_conversation_history_no_automatic_expiry",delete_behavior="no automatic delete; migration removes active plaintext representation only after verified portable backup and encrypted readback",portable_identity="included_in_assistant_continuity_backup",recovery_family="included_in_single_file_nacb",encryption="NeatCrypt AES-256-GCM at rest; portable master key wrapped by Argon2id passphrase; DPAPI optional local convenience only",redaction="message content is confidential; no persistent plaintext FTS index after encryption")
    return _SPG_POLICY_BEFORE_NEATCRYPT(plane_id)

_SPG_PORTABILITY_BEFORE_NEATCRYPT = _spg_portability_coverage
def _spg_portability_coverage(module) -> dict:
    base=dict(_SPG_PORTABILITY_BEFORE_NEATCRYPT(module))
    legacy=base.get("full_backup_family")
    if legacy: base["legacy_backup_family"]={**dict(legacy),"status":"compatibility-only; primary /backup UX is Assistant Continuity Backup (.nacb)"}
    continuity={
        "format":_NEATCRYPT_BACKUP_EXTENSION,
        "commands":["/backup status","/backup new [filename]","/backup rotate [filename]","/backup load <filename>"],
        "encryption":"NeatCrypt AES-256-GCM payload encryption; random 256-bit master key; Argon2id passphrase wrapping; fresh salt/nonces; DPAPI is local convenience only",
        "included":["portable identity/personality components","canonical chat history (user + Assistant/model rows)","Workshop","Assistant issue lifecycle history"],
        "excluded":["canonical personal-memory SQLite beyond identity component","book/research databases","runtime lifecycle ledger","Diagnostic Logbook","Black Box","annotation sidecar unless separately exported"],
        "windows_portability":"backup file + passphrase is sufficient to recover the NeatCrypt master key on a new Windows profile; old DPAPI profile is not required",
        "authority_note":"Chat is bundled with identity for continuity recovery but remains conversational evidence/history, not immutable personality/core authority.",
    }
    base["full_backup_family"]=continuity
    base["assistant_continuity_backup"]=dict(continuity)
    if isinstance(base.get("portable_identity_backup"),dict):
        base["portable_identity_backup"]={**base["portable_identity_backup"],"status":"legacy identity-only compatibility surface; primary /backup is .nacb and includes chat continuity"}
    keyrot=dict(base.get("key_rotation") or {})
    keyrot.update({"neatcrypt_portable":"/backup new snapshots and rewraps the current master key with fresh Argon2id salt/AES-GCM nonces. /backup rotate generates a new random live master key, re-encrypts exact chat rows as NC2, verifies old-key rejection, and writes a new portable recovery artifact; passphrases are never stored.","windows_change":"Recover the matching master key from a valid .nacb, then create a new local DPAPI wrapper for the destination Windows profile. Backups made before explicit rotation remain historical snapshots but cannot unlock the rotated live chat store."})
    base["key_rotation"]=keyrot
    return base

