def _checkpoint_file_sha256() -> str | None:
    try:
        return hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    except Exception:
        return None


def _checkpoint_status(module) -> dict:
    return {
        "ok": True,
        "checkpoint": {
            "id": CHECKPOINT_ID,
            "policy_version": CHECKPOINT_POLICY_VERSION,
            "bundle_version": BUNDLE_VERSION,
            "release_name": RELEASE_NAME,
            "file_sha256": _checkpoint_file_sha256(),
            "mode": "ANCHOR_BASELINE",
            "feature_freeze": False,
            "baseline_frozen": True,
            "anchor_checkpoint": True,
            "post_anchor_bundle_version": BUNDLE_VERSION,
        },
        "policy": {
            "normal_use_is_primary_validation": True,
            "fix_every_edge_case_immediately": False,
            "new_features_frozen_by_default": False,
            "orthogonal_layers_may_climb_above_anchor": True,
            "reopen_only_on": list(_CHECKPOINT_REOPEN_TRIGGERS),
            "three_failed_patch_attempts_then_reevaluate": True,
            "canonical_memory_modified_by_status_command": False,
        },
        "five_group_architecture": _five_group_architecture_contract_report(),
        "architecture_layers": list(_CHECKPOINT_ARCHITECTURE_LAYERS),
        "post_anchor_layers": ([{"name":"constellation","version":str(globals().get("_CONST_VERSION") or ""),"ownership":"Assistant personal interpretive memory","mutates_anchor":False}] if globals().get("_CONST_VERSION") else []) + ([{"name":"opportunistic-reports","version":str(globals().get("_AOR_VERSION") or ""),"ownership":"Assistant optional report archive","mutates_anchor":False,"automatic_promotion":False}] if globals().get("_AOR_VERSION") else []),
        "validation_evidence": dict(_CHECKPOINT_VALIDATION_EVIDENCE),
        "accepted_contracts": list(_CHECKPOINT_ACCEPTED_CONTRACTS),
        "known_limitations": list(_CHECKPOINT_KNOWN_LIMITATIONS),
        "journey_note": _CHECKPOINT_JOURNEY_NOTE + "\n\n" + _NEATCRYPT_JOURNEY_NOTE,
        "health_command": f"python {Path(__file__).name} --self-test checkpoint",
    }


def _checkpoint_handle_command(module, raw: str) -> bool:
    clean = " ".join(str(raw or "").strip().split())
    lower = clean.casefold()
    if lower in {"/checkpoint journey", "/consolidation journey"}:
        print(_CHECKPOINT_JOURNEY_NOTE)
        return True
    if lower not in {"/checkpoint", "/checkpoint status", "/consolidation checkpoint", "/consolidation status"}:
        return False
    print(json.dumps(_checkpoint_status(module), ensure_ascii=False, indent=2))
    return True


def _install_consolidation_checkpoint(module) -> None:
    if getattr(module, "_CONSOLIDATION_CHECKPOINT_INSTALLED", False):
        return
    module.CONSOLIDATION_CHECKPOINT_ID = CHECKPOINT_ID
    module.CONSOLIDATION_CHECKPOINT_POLICY_VERSION = CHECKPOINT_POLICY_VERSION
    module.get_consolidation_checkpoint_status = lambda: _checkpoint_status(module)
    module.knowledge_architecture_checkpoint_self_test = lambda: knowledge_architecture_checkpoint_self_test(module)
    old_main = module.main

    def main_with_consolidation_checkpoint():
        previous = builtins.input

        def checkpoint_input(prompt=""):
            while True:
                value = previous(prompt)
                if _checkpoint_handle_command(module, value):
                    continue
                return value

        builtins.input = checkpoint_input
        try:
            return old_main()
        finally:
            builtins.input = previous

    module.main = main_with_consolidation_checkpoint
    old_help = module.print_help

    def help_with_consolidation_checkpoint(*args, **kwargs):
        old_help(*args, **kwargs)
        print("  /checkpoint status | /checkpoint journey")
        print("      Show the 7.4.63.0 Knowledge Architecture Consolidation anchor carried by this newer bundle: authoritative per-book container, immutable evidence, fluid semantics, exact formal structure, reconciled structural summaries, Knowledge Pyramid, versioned history/annotations, integrity, and provider/tool-loop budget guards; or show the maintained Journey for the next maintainer.")
        print("  python <bundle>.py --self-test checkpoint")
        print("      Run the frozen baseline checkpoint plus the zero-model knowledge-architecture contract.")
        print("  python <bundle>.py --self-test checkpoint-knowledge")
        print("      Run the bounded zero-model architecture regression surface (authority, pyramid, revisions, annotations, formal structure, reconciliation, provider/tool-loop guards).")

    module.print_help = help_with_consolidation_checkpoint
    module.NEATMEMORY_VERSION = BUNDLE_VERSION
    module.RELEASE_NAME = RELEASE_NAME
    module._CONSOLIDATION_CHECKPOINT_INSTALLED = True


def main() -> None:
    raw_args = list(sys.argv[1:])
    if raw_args == ["--source-verify"]:
        # Maintenance must work without opening live memory or requiring DPAPI.
        report=_five_group_architecture_contract_report()
        print(json.dumps(report,ensure_ascii=False,indent=2))
        raise SystemExit(0 if report.get("ok") else 1)
    if "--self-test-worker" in raw_args:
        index = raw_args.index("--self-test-worker")
        if index + 1 >= len(raw_args):
            raise SystemExit("--self-test-worker requires a subsystem name.")
        subsystem = raw_args[index + 1]
        output_path = None
        if "--self-test-worker-output" in raw_args:
            output_index = raw_args.index("--self-test-worker-output")
            if output_index + 1 >= len(raw_args):
                raise SystemExit("--self-test-worker-output requires a path.")
            output_path = Path(raw_args[output_index + 1]).resolve()
        raise SystemExit(_self_test_worker(subsystem, output_path))
    if "--self-test" in raw_args:
        index = raw_args.index("--self-test")
        selection = "all"
        if index + 1 < len(raw_args) and not raw_args[index + 1].startswith("--"):
            selection = raw_args[index + 1]
        if selection.casefold() == "list":
            print(_self_test_list_text())
            return
        raise SystemExit(_self_test(selection))
    try:
        args, llm_config = _configure_remote_llm(raw_args)
    except ValueError as exc:
        raise SystemExit(f"LLM endpoint configuration error: {exc}") from exc

    if llm_config["show"]:
        _print_llm_config(llm_config)
        if not args:
            return

    if "--digest" in args:
        # Optional startup provider: --digest local or --digest online.
        clean_args = [a for a in args if a != "--digest"]
        if clean_args and clean_args[0].casefold() in {"local", "online"}:
            os.environ["NEATDIGEST_PROVIDER"] = clean_args.pop(0).casefold()
        sys.argv = [sys.argv[0]] + clean_args
        print(f"LLM endpoint profile: {llm_config['profile']} ({llm_config['url']})")
        _load_digest().main()
        return
    sys.argv = [sys.argv[0]] + args
    print(f"LLM endpoint profile: {llm_config['profile']} ({llm_config['url']})")
    _load_memory().main()


if __name__ == "__main__":
    main()

